INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1, 1, 'Which of the following is a natural number: -3, 0, 4, or 1/2?', 'text', 1, 'Natural numbers start at 1.', '{"why":"Natural numbers are positive counting numbers beginning with 1.","sol":"Step 1: Natural numbers are 1, 2, 3, 4, ...\nStep 2: -3 is negative.\nStep 3: 0 is not included in this classification.\nStep 4: 1/2 is a fraction.\nStep 5: 4 belongs to the natural numbers.","steps":["Step 1: Natural numbers are 1, 2, 3, 4, ...","Step 2: -3 is negative.","Step 3: 0 is not included in this classification.","Step 4: 1/2 is a fraction.","Step 5: 4 belongs to the natural numbers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Number Systems"}', 0),
  (2, 1, 'Is 0 a natural number, whole number, or integer?', 'text', 1, 'Remember which sets include zero.', '{"why":"Whole numbers include 0, and integers include negative numbers, zero, and positive numbers.","sol":"Step 1: 0 is not a natural number in this classification.\nStep 2: Whole numbers include 0.\nStep 3: Integers also include 0.","steps":["Step 1: 0 is not a natural number in this classification.","Step 2: Whole numbers include 0.","Step 3: Integers also include 0."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Number Systems"}', 1),
  (3, 1, 'Which type of number is -8?', 'text', 1, 'Look at its sign.', '{"why":"-8 belongs to the set of integers because integers include negative whole-number values.","sol":"Step 1: -8 is less than zero.\nStep 2: Negative numbers are not natural or whole numbers.\nStep 3: Negative whole-number values belong to the integers.","steps":["Step 1: -8 is less than zero.","Step 2: Negative numbers are not natural or whole numbers.","Step 3: Negative whole-number values belong to the integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Number Systems"}', 2),
  (4, 1, 'Which is greater: -3 or -7?', 'text', 1, 'Think about their positions on the number line.', '{"why":"-3 is closer to zero and is therefore greater than -7.","sol":"Step 1: Locate -3 and -7 on the number line.\nStep 2: -3 is to the right of -7.\nStep 3: A number farther right is greater.","steps":["Step 1: Locate -3 and -7 on the number line.","Step 2: -3 is to the right of -7.","Step 3: A number farther right is greater."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Number Systems"}', 3),
  (5, 1, 'Arrange these integers from smallest to largest: 3, -2, 0, -5, 1.', 'text', 1, 'Start with the most negative number.', '{"why":"Numbers increase as we move from left to right on the number line.","sol":"Step 1: The smallest number is -5.\nStep 2: Next is -2.\nStep 3: Then comes 0.\nStep 4: Then 1.\nStep 5: Finally, 3.","steps":["Step 1: The smallest number is -5.","Step 2: Next is -2.","Step 3: Then comes 0.","Step 4: Then 1.","Step 5: Finally, 3."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"Number Systems"}', 4),
  (6, 1, 'Calculate: -6 + 4', 'text', 1, 'Start at -6 and move 4 units to the right.', '{"why":"Adding 4 to -6 moves four units toward zero, giving -2.","sol":"Step 1: Start with -6.\nStep 2: Add 4.\nStep 3: -6 + 4 = -2.","steps":["Step 1: Start with -6.","Step 2: Add 4.","Step 3: -6 + 4 = -2."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"Number Systems"}', 5),
  (7, 1, 'Calculate: 5 - 9', 'text', 1, 'Subtracting a larger number from a smaller number gives a negative result.', '{"why":"5 is 4 less than 9, so 5 - 9 = -4.","sol":"Step 1: Start with 5.\nStep 2: Subtract 9.\nStep 3: 5 - 9 = -4.","steps":["Step 1: Start with 5.","Step 2: Subtract 9.","Step 3: 5 - 9 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"Number Systems"}', 6),
  (8, 1, 'Calculate: -4 × -3', 'text', 1, 'Look at the signs.', '{"why":"Two negative signs produce a positive result, and 4 × 3 = 12.","sol":"Step 1: The numbers have the same sign.\nStep 2: Negative × Negative gives Positive.\nStep 3: 4 × 3 = 12.","steps":["Step 1: The numbers have the same sign.","Step 2: Negative × Negative gives Positive.","Step 3: 4 × 3 = 12."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"Number Systems"}', 7),
  (9, 1, 'Calculate: -20 ÷ 5', 'text', 1, 'Look at the signs before dividing.', '{"why":"Different signs give a negative result, and 20 ÷ 5 = 4.","sol":"Step 1: Negative ÷ Positive gives Negative.\nStep 2: 20 ÷ 5 = 4.\nStep 3: Therefore, -20 ÷ 5 = -4.","steps":["Step 1: Negative ÷ Positive gives Negative.","Step 2: 20 ÷ 5 = 4.","Step 3: Therefore, -20 ÷ 5 = -4."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"Number Systems"}', 8),
  (10, 1, 'Which statement is correct?', 'text', 1, 'Think about how the number sets are contained.', '{"why":"The natural-number set is contained inside the whole-number set, which is contained inside the integers.","sol":"Step 1: Natural numbers are contained in whole numbers.\nStep 2: Whole numbers are contained in integers.\nStep 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers.","steps":["Step 1: Natural numbers are contained in whole numbers.","Step 2: Whole numbers are contained in integers.","Step 3: Therefore, Natural Numbers ⊂ Whole Numbers ⊂ Integers."],"options":[],"conceptId":"math_numbers_number_systems","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"Number Systems"}', 9),
  (11, 2, 'Solve: 6 + 2 × 3', 'text', 1, 'Multiplication comes before addition.', '{"why":"Multiplication has priority over addition, so 2 × 3 is calculated first.","sol":"Step 1: Identify multiplication and addition.\nStep 2: Calculate 2 × 3 = 6.\nStep 3: Calculate 6 + 6 = 12.","steps":["Step 1: Identify multiplication and addition.","Step 2: Calculate 2 × 3 = 6.","Step 3: Calculate 6 + 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 0),
  (12, 2, 'Solve: 20 - 12 ÷ 3', 'text', 1, 'Division comes before subtraction.', '{"why":"Division is performed before subtraction.","sol":"Step 1: Calculate 12 ÷ 3 = 4.\nStep 2: Calculate 20 - 4 = 16.","steps":["Step 1: Calculate 12 ÷ 3 = 4.","Step 2: Calculate 20 - 4 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 1),
  (13, 2, 'Solve: (7 + 5) × 2', 'text', 1, 'Start with the brackets.', '{"why":"Brackets are calculated before multiplication.","sol":"Step 1: Calculate 7 + 5 = 12.\nStep 2: Calculate 12 × 2 = 24.","steps":["Step 1: Calculate 7 + 5 = 12.","Step 2: Calculate 12 × 2 = 24."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 2),
  (14, 2, 'Solve: 3 + 2²', 'text', 1, 'Calculate the order before addition.', '{"why":"Orders such as powers are calculated before addition.","sol":"Step 1: Calculate 2² = 4.\nStep 2: Calculate 3 + 4 = 7.","steps":["Step 1: Calculate 2² = 4.","Step 2: Calculate 3 + 4 = 7."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 3),
  (15, 2, 'Solve: 24 ÷ 3 × 2', 'text', 1, 'Division and multiplication have equal priority. Work left to right.', '{"why":"Division and multiplication have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 24 ÷ 3 = 8.\nStep 2: Continue left to right: 8 × 2 = 16.","steps":["Step 1: Start from the left: 24 ÷ 3 = 8.","Step 2: Continue left to right: 8 × 2 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 4),
  (16, 2, 'Solve: 15 - 6 + 2', 'text', 1, 'Addition and subtraction have equal priority.', '{"why":"Addition and subtraction have equal priority, so they are evaluated from left to right.","sol":"Step 1: Start from the left: 15 - 6 = 9.\nStep 2: Continue left to right: 9 + 2 = 11.","steps":["Step 1: Start from the left: 15 - 6 = 9.","Step 2: Continue left to right: 9 + 2 = 11."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q6","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 5),
  (17, 2, 'Solve: 8 + 2 × (5 - 3)²', 'text', 1, 'Follow the order: brackets, orders, multiplication, addition.', '{"why":"The expression follows BODMAS: brackets, orders, multiplication, then addition.","sol":"Step 1: (5 - 3) = 2.\nStep 2: 2² = 4.\nStep 3: 2 × 4 = 8.\nStep 4: 8 + 8 = 16.","steps":["Step 1: (5 - 3) = 2.","Step 2: 2² = 4.","Step 3: 2 × 4 = 8.","Step 4: 8 + 8 = 16."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q7","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 6),
  (18, 2, 'Solve: 2 × [3 + (4 - 1)]', 'text', 1, 'Solve the innermost brackets first.', '{"why":"Nested brackets are solved from the innermost bracket outward.","sol":"Step 1: 4 - 1 = 3.\nStep 2: 3 + 3 = 6.\nStep 3: 2 × 6 = 12.","steps":["Step 1: 4 - 1 = 3.","Step 2: 3 + 3 = 6.","Step 3: 2 × 6 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q8","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 7),
  (19, 2, 'A student solves 10 + 4 × 2 as (10 + 4) × 2. What did the student do wrong?', 'text', 1, 'Check which operation should be performed first.', '{"why":"The multiplication must be performed before the addition, so the correct answer is 18.","sol":"Step 1: Multiplication has priority over addition.\nStep 2: Calculate 4 × 2 = 8.\nStep 3: Calculate 10 + 8 = 18.","steps":["Step 1: Multiplication has priority over addition.","Step 2: Calculate 4 × 2 = 8.","Step 3: Calculate 10 + 8 = 18."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q9","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 8),
  (20, 2, 'Solve: 18 ÷ 3 × 2', 'text', 1, 'Do not automatically multiply first.', '{"why":"Division and multiplication have equal priority and are evaluated from left to right.","sol":"Step 1: Division and multiplication have equal priority.\nStep 2: Work from left to right: 18 ÷ 3 = 6.\nStep 3: 6 × 2 = 12.","steps":["Step 1: Division and multiplication have equal priority.","Step 2: Work from left to right: 18 ÷ 3 = 6.","Step 3: 6 × 2 = 12."],"options":[],"conceptId":"math_numbers_bodmas_order_of_operations","skillId":"math_numbers","subskillId":"math_numbers_q10","subject":"math","chapter":"numbers","topic":"BODMAS / Order of Operations"}', 9),
  (21, 3, 'Is 4,572 divisible by 3?', 'text', 1, 'Sum the digits', '{"why":"A number is divisible by 3 if the sum of its digits is divisible by 3 (4 + 5 + 7 + 2 = 18 = 3 × 6).","sol":"Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18\nStep 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)\nStep 3: Conclude: 4,572 is divisible by 3","steps":["Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18","Step 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)","Step 3: Conclude: 4,572 is divisible by 3"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 0),
  (22, 3, 'Determine if 3,524 is divisible by 4.', 'text', 1, 'Check last two digits', '{"why":"A number is divisible by 4 if the number formed by its last two digits is divisible by 4 (24 ÷ 4 = 6).","sol":"Step 1: Identify the last two digits: 24\nStep 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6\nStep 3: Conclude: 3,524 is divisible by 4","steps":["Step 1: Identify the last two digits: 24","Step 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6","Step 3: Conclude: 3,524 is divisible by 4"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 1),
  (23, 3, 'Is 1,236 divisible by 6?', 'text', 1, 'Check divisibility by both 2 and 3', '{"why":"Divisibility by 6 requires the number to be even and the sum of its digits to be a multiple of 3.","sol":"Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2\nStep 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3\nStep 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6","steps":["Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2","Step 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3","Step 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 2),
  (24, 3, 'Find the smallest single digit x such that 5,3x2 is divisible by 9.', 'text', 1, 'Sum of digits must be a multiple of 9', '{"why":"Sum of digits is 5 + 3 + x + 2 = 10 + x. The smallest single digit making this divisible by 9 is x = 8 (sum = 18).","sol":"Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10\nStep 2: Set equation: 10 + x = 18 (next multiple of 9)\nStep 3: Solve for x: x = 18 - 10 = 8","steps":["Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10","Step 2: Set equation: 10 + x = 18 (next multiple of 9)","Step 3: Solve for x: x = 18 - 10 = 8"],"options":[],"conceptId":"math_numbers_divisibility_rules","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Divisibility Rules"}', 3),
  (25, 4, 'Calculate 17 mod 5.', 'text', 1, 'Find remainder when 17 is divided by 5', '{"why":"17 divided by 5 yields quotient 3 with remainder 2.","sol":"Step 1: Divide 17 by 5: 17 = 5 × 3 + 2\nStep 2: Identify quotient (3) and remainder (2)\nStep 3: Conclude: 17 mod 5 = 2","steps":["Step 1: Divide 17 by 5: 17 = 5 × 3 + 2","Step 2: Identify quotient (3) and remainder (2)","Step 3: Conclude: 17 mod 5 = 2"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 0),
  (26, 4, 'Evaluate (14 + 23) mod 6.', 'text', 1, 'Add then take modulo, or take modulo first', '{"why":"14 + 23 = 37. 37 = 6 × 6 + 1, so 37 mod 6 = 1.","sol":"Step 1: 14 mod 6 = 2, and 23 mod 6 = 5\nStep 2: Add remainders: 2 + 5 = 7\nStep 3: Reduce modulo 6: 7 mod 6 = 1","steps":["Step 1: 14 mod 6 = 2, and 23 mod 6 = 5","Step 2: Add remainders: 2 + 5 = 7","Step 3: Reduce modulo 6: 7 mod 6 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 1),
  (27, 4, 'Find (7 × 8) mod 5.', 'text', 1, 'Multiply then divide by 5', '{"why":"56 divided by 5 gives remainder 1.","sol":"Step 1: Compute product: 7 × 8 = 56\nStep 2: Divide 56 by 5: 56 = 5 × 11 + 1\nStep 3: Conclude: 56 mod 5 = 1","steps":["Step 1: Compute product: 7 × 8 = 56","Step 2: Divide 56 by 5: 56 = 5 × 11 + 1","Step 3: Conclude: 56 mod 5 = 1"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 2),
  (28, 4, 'Find 3^4 mod 7.', 'text', 1, 'Compute powers step by step', '{"why":"3^4 = 81. 81 = 7 × 11 + 4, so 81 mod 7 = 4.","sol":"Step 1: 3^2 = 9 ≡ 2 (mod 7)\nStep 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)\nStep 3: 2^2 = 4 (mod 7)","steps":["Step 1: 3^2 = 9 ≡ 2 (mod 7)","Step 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)","Step 3: 2^2 = 4 (mod 7)"],"options":[],"conceptId":"math_numbers_modular_arithmetic","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Modular Arithmetic"}', 3),
  (29, 5, 'What is the only even prime number?', 'text', 1, 'Smallest prime', '{"why":"2 is the smallest prime and the only even prime number, because any larger even number is divisible by 2.","sol":"Step 1: Check even numbers: 2, 4, 6, 8...\nStep 2: 2 has only divisors 1 and 2 → prime\nStep 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime","steps":["Step 1: Check even numbers: 2, 4, 6, 8...","Step 2: 2 has only divisors 1 and 2 → prime","Step 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 0),
  (30, 5, 'Find the prime factorization of 60.', 'text', 1, 'Break into prime factors', '{"why":"60 = 4 × 15 = (2 × 2) × (3 × 5) = 2² × 3 × 5.","sol":"Step 1: 60 = 2 × 30\nStep 2: 30 = 2 × 15\nStep 3: 15 = 3 × 5\nStep 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5","steps":["Step 1: 60 = 2 × 30","Step 2: 30 = 2 × 15","Step 3: 15 = 3 × 5","Step 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 1),
  (31, 5, 'Is 29 a prime or composite number?', 'text', 1, 'Check divisibility by primes ≤ √29 ≈ 5.38 (2, 3, 5)', '{"why":"29 has no divisors other than 1 and itself, making it prime.","sol":"Step 1: Check primes up to √29: 2, 3, 5\nStep 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)\nStep 3: Conclude: 29 has no divisors other than 1 and 29 → Prime","steps":["Step 1: Check primes up to √29: 2, 3, 5","Step 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)","Step 3: Conclude: 29 has no divisors other than 1 and 29 → Prime"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 2),
  (32, 5, 'Find the greatest common divisor (GCD) of 24 and 36 using prime factorization.', 'text', 1, 'Take lowest power of common prime factors', '{"why":"GCD(24, 36) = 2² × 3 = 12.","sol":"Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²\nStep 2: Identify common prime factors: 2 and 3\nStep 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12","steps":["Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²","Step 2: Identify common prime factors: 2 and 3","Step 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12"],"options":[],"conceptId":"math_numbers_prime_numbers","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Prime Numbers"}', 3),
  (33, 6, 'Solve the linear congruence: 2x ≡ 6 (mod 8) for 0 ≤ x < 8.', 'text', 1, 'Check integers 0 through 7 or divide by gcd', '{"why":"2(3) = 6 ≡ 6 (mod 8) and 2(7) = 14 ≡ 6 (mod 8).","sol":"Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions\nStep 2: Divide congruence by 2: x ≡ 3 (mod 4)\nStep 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7","steps":["Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions","Step 2: Divide congruence by 2: x ≡ 3 (mod 4)","Step 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 0),
  (34, 6, 'Is 38 ≡ 14 (mod 8)?', 'text', 1, 'Check if (38 - 14) is divisible by 8', '{"why":"38 - 14 = 24, which is a multiple of 8 (8 × 3 = 24).","sol":"Step 1: Calculate difference: 38 - 14 = 24\nStep 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)\nStep 3: Conclude: 38 ≡ 14 (mod 8) is True","steps":["Step 1: Calculate difference: 38 - 14 = 24","Step 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)","Step 3: Conclude: 38 ≡ 14 (mod 8) is True"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 1),
  (35, 6, 'Find the modular inverse of 3 modulo 7.', 'text', 1, 'Find integer x such that 3x ≡ 1 (mod 7)', '{"why":"3 × 5 = 15 ≡ 1 (mod 7), so 5 is the modular multiplicative inverse of 3 modulo 7.","sol":"Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12\nStep 2: 12 mod 7 = 5; next test 3(5) = 15\nStep 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5","steps":["Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12","Step 2: 12 mod 7 = 5; next test 3(5) = 15","Step 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5"],"options":[],"conceptId":"math_numbers_congruence_relations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Congruence Relations"}', 2),
  (36, 7, 'A boy walks 600 m from home to school. What is the distance travelled?', 'text', 1, 'Distance tells how far the boy travelled.', '{"why":"Distance is the total length of the path travelled.","sol":"Step 1: The boy travels from home to school.\nStep 2: The given length is 600 m.\nStep 3: Therefore, the distance travelled is 600 m.","steps":["Step 1: The boy travels from home to school.","Step 2: The given length is 600 m.","Step 3: Therefore, the distance travelled is 600 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance"}', 0),
  (37, 7, 'A runner travels 400 m and then another 300 m. Find the total distance.', 'text', 1, 'Add both sections of the path.', '{"why":"Both sections form part of the total path travelled.","sol":"Step 1: First section = 400 m.\nStep 2: Second section = 300 m.\nStep 3: Total distance = 400 + 300.\nStep 4: Total distance = 700 m.","steps":["Step 1: First section = 400 m.","Step 2: Second section = 300 m.","Step 3: Total distance = 400 + 300.","Step 4: Total distance = 700 m."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance"}', 1),
  (38, 7, 'A cyclist travels 5 km, then 2 km, then 3 km. Find the total distance.', 'text', 1, 'Add every section travelled.', '{"why":"Total distance is the sum of all parts of the path.","sol":"Step 1: First section = 5 km.\nStep 2: Second section = 2 km.\nStep 3: Third section = 3 km.\nStep 4: Total distance = 5 + 2 + 3 = 10 km.","steps":["Step 1: First section = 5 km.","Step 2: Second section = 2 km.","Step 3: Third section = 3 km.","Step 4: Total distance = 5 + 2 + 3 = 10 km."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance"}', 2),
  (39, 7, 'What does distance measure in a motion problem?', 'text', 1, 'Think about how far the object travels.', '{"why":"Distance measures how far an object travels, without considering direction.","sol":"Step 1: An object follows a path when it moves.\nStep 2: Distance measures the length of that path.\nStep 3: Therefore, distance tells how far the object travelled.","steps":["Step 1: An object follows a path when it moves.","Step 2: Distance measures the length of that path.","Step 3: Therefore, distance tells how far the object travelled."],"options":[],"conceptId":"math_linear_motion_distance","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance"}', 3),
  (40, 8, 'A car moves 60 km east from A to B. What is its displacement?', 'text', 1, 'State both the size and direction of the change in position.', '{"why":"Displacement describes the change in position together with direction.","sol":"Step 1: The car starts at A.\nStep 2: It finishes 60 km east of A.\nStep 3: Therefore, its displacement is 60 km east.","steps":["Step 1: The car starts at A.","Step 2: It finishes 60 km east of A.","Step 3: Therefore, its displacement is 60 km east."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 0),
  (41, 8, 'A cyclist moves 5 km west from P to Q. What is the displacement?', 'text', 1, 'The direction of movement is west.', '{"why":"Displacement must include the direction of the change in position.","sol":"Step 1: The cyclist starts at P.\nStep 2: The cyclist finishes 5 km west of P.\nStep 3: Therefore, displacement = 5 km west.","steps":["Step 1: The cyclist starts at P.","Step 2: The cyclist finishes 5 km west of P.","Step 3: Therefore, displacement = 5 km west."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 1),
  (42, 8, 'A runner completes a 400 m lap and finishes exactly where they started. Find the displacement.', 'text', 1, 'Compare the starting position with the final position.', '{"why":"There is no change in position when the object finishes where it started.","sol":"Step 1: The runner starts at one point.\nStep 2: After one complete lap, the runner returns to that same point.\nStep 3: The starting and final positions are identical.\nStep 4: Therefore, displacement = 0 m.","steps":["Step 1: The runner starts at one point.","Step 2: After one complete lap, the runner returns to that same point.","Step 3: The starting and final positions are identical.","Step 4: Therefore, displacement = 0 m."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 2),
  (43, 8, 'A person moves 2 km north. State the displacement.', 'text', 1, 'Include both magnitude and direction.', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: The person changes position by 2 km.\nStep 2: The direction is north.\nStep 3: Therefore, displacement = 2 km north.","steps":["Step 1: The person changes position by 2 km.","Step 2: The direction is north.","Step 3: Therefore, displacement = 2 km north."],"options":[],"conceptId":"math_linear_motion_displacement","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Displacement"}', 3),
  (44, 9, 'A car travels 70 km east in a straight line. State its distance and displacement.', 'text', 1, 'The car moves in one direction only.', '{"why":"For straight movement in one direction, distance equals the magnitude of displacement.","sol":"Step 1: The total path travelled is 70 km.\nStep 2: The final position is 70 km east of the start.\nStep 3: Distance = 70 km.\nStep 4: Displacement = 70 km east.","steps":["Step 1: The total path travelled is 70 km.","Step 2: The final position is 70 km east of the start.","Step 3: Distance = 70 km.","Step 4: Displacement = 70 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 0),
  (45, 9, 'A student walks 3 km north and then 3 km south. Find the distance and displacement.', 'text', 1, 'Calculate the whole path first, then compare start and finish.', '{"why":"The student travels 6 km but finishes at the starting position.","sol":"Step 1: Distance = 3 + 3 = 6 km.\nStep 2: The student returns to the starting position.\nStep 3: Therefore, displacement = 0 km.","steps":["Step 1: Distance = 3 + 3 = 6 km.","Step 2: The student returns to the starting position.","Step 3: Therefore, displacement = 0 km."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 1),
  (46, 9, 'A cyclist travels 4 km east and then 1 km east. Find the distance and displacement.', 'text', 1, 'Both parts are in the same direction.', '{"why":"Both movements increase the cyclist''s position in the same direction.","sol":"Step 1: Distance = 4 + 1 = 5 km.\nStep 2: The cyclist finishes 5 km east of the start.\nStep 3: Displacement = 5 km east.","steps":["Step 1: Distance = 4 + 1 = 5 km.","Step 2: The cyclist finishes 5 km east of the start.","Step 3: Displacement = 5 km east."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 2),
  (47, 9, 'Can displacement be zero while distance is greater than zero?', 'text', 1, 'Think about an object returning to its starting point.', '{"why":"Returning to the starting position makes displacement zero even though a distance was travelled.","sol":"Step 1: An object can move away from its starting point.\nStep 2: It can then return to the same starting point.\nStep 3: The distance travelled is greater than zero.\nStep 4: The starting and final positions are the same, so displacement is zero.","steps":["Step 1: An object can move away from its starting point.","Step 2: It can then return to the same starting point.","Step 3: The distance travelled is greater than zero.","Step 4: The starting and final positions are the same, so displacement is zero."],"options":[],"conceptId":"math_linear_motion_distance_and_displacement_compared","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance and Displacement Compared"}', 3),
  (48, 10, 'A car travels 180 km in 3 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Speed tells us the distance covered per unit of time.","sol":"Step 1: Distance = 180 km.\nStep 2: Time = 3 h.\nStep 3: Speed = 180 ÷ 3.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 180 km.","Step 2: Time = 3 h.","Step 3: Speed = 180 ÷ 3.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Speed"}', 0),
  (49, 10, 'A cyclist travels 100 km in 5 hours. Find the speed.', 'text', 1, 'Divide the distance by the time.', '{"why":"Dividing distance by time gives the rate at which distance is covered.","sol":"Step 1: Distance = 100 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 100 ÷ 5.\nStep 4: Speed = 20 km/h.","steps":["Step 1: Distance = 100 km.","Step 2: Time = 5 h.","Step 3: Speed = 100 ÷ 5.","Step 4: Speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Speed"}', 1),
  (50, 10, 'A bus travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Substitute distance and time into s = d/t.', '{"why":"Speed is the distance travelled for each hour of the journey.","sol":"Step 1: Distance = 360 km.\nStep 2: Time = 6 h.\nStep 3: Speed = 360 ÷ 6.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 360 km.","Step 2: Time = 6 h.","Step 3: Speed = 360 ÷ 6.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Speed"}', 2),
  (51, 10, 'A runner covers 20 km in 2 hours. Find the runner''s speed.', 'text', 1, 'Divide 20 km by 2 hours.', '{"why":"Speed is calculated by dividing distance by time.","sol":"Step 1: Distance = 20 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 20 ÷ 2.\nStep 4: Speed = 10 km/h.","steps":["Step 1: Distance = 20 km.","Step 2: Time = 2 h.","Step 3: Speed = 20 ÷ 2.","Step 4: Speed = 10 km/h."],"options":[],"conceptId":"math_linear_motion_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Speed"}', 3),
  (52, 11, 'A car travels 50 km in 1 hour and 70 km in 2 hours. Find its average speed.', 'text', 1, 'Find total distance and total time first.', '{"why":"Average speed uses the total distance and total time for the whole journey.","sol":"Step 1: Total distance = 50 + 70 = 120 km.\nStep 2: Total time = 1 + 2 = 3 h.\nStep 3: Average speed = 120 ÷ 3.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 50 + 70 = 120 km.","Step 2: Total time = 1 + 2 = 3 h.","Step 3: Average speed = 120 ÷ 3.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 0),
  (53, 11, 'A cyclist travels 40 km in 2 hours and 20 km in 1 hour. Find the average speed.', 'text', 1, 'Add the distances and add the times.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 40 + 20 = 60 km.\nStep 2: Total time = 2 + 1 = 3 h.\nStep 3: Average speed = 60 ÷ 3.\nStep 4: Average speed = 20 km/h.","steps":["Step 1: Total distance = 40 + 20 = 60 km.","Step 2: Total time = 2 + 1 = 3 h.","Step 3: Average speed = 60 ÷ 3.","Step 4: Average speed = 20 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 1),
  (54, 11, 'A bus travels 100 km to a town in 2 hours and returns 100 km in 3 hours. Find its average speed.', 'text', 1, 'The total distance is 200 km and the total time is 5 hours.', '{"why":"The whole journey must be considered when calculating average speed.","sol":"Step 1: Total distance = 100 + 100 = 200 km.\nStep 2: Total time = 2 + 3 = 5 h.\nStep 3: Average speed = 200 ÷ 5.\nStep 4: Average speed = 40 km/h.","steps":["Step 1: Total distance = 100 + 100 = 200 km.","Step 2: Total time = 2 + 3 = 5 h.","Step 3: Average speed = 200 ÷ 5.","Step 4: Average speed = 40 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 2),
  (55, 11, 'A journey covers 90 km in 3 hours. What is the average speed?', 'text', 1, 'For one constant journey, divide distance by time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: Total distance = 90 km.\nStep 2: Total time = 3 h.\nStep 3: Average speed = 90 ÷ 3.\nStep 4: Average speed = 30 km/h.","steps":["Step 1: Total distance = 90 km.","Step 2: Total time = 3 h.","Step 3: Average speed = 90 ÷ 3.","Step 4: Average speed = 30 km/h."],"options":[],"conceptId":"math_linear_motion_average_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Speed"}', 3),
  (56, 12, 'A car travels at 70 km/h east. State its velocity.', 'text', 1, 'Velocity includes speed and direction.', '{"why":"Velocity requires both magnitude and direction.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Direction = east.\nStep 3: Therefore, velocity = 70 km/h east.","steps":["Step 1: Speed = 70 km/h.","Step 2: Direction = east.","Step 3: Therefore, velocity = 70 km/h east."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 0),
  (57, 12, 'A train moves at 90 km/h south. State its velocity.', 'text', 1, 'Include the direction south.', '{"why":"The direction distinguishes velocity from speed.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Direction = south.\nStep 3: Therefore, velocity = 90 km/h south.","steps":["Step 1: Speed = 90 km/h.","Step 2: Direction = south.","Step 3: Therefore, velocity = 90 km/h south."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 1),
  (58, 12, 'Is 40 km/h a complete statement of velocity?', 'text', 1, 'Ask whether a direction has been given.', '{"why":"A velocity must specify direction.","sol":"Step 1: 40 km/h gives the magnitude of motion.\nStep 2: No direction is specified.\nStep 3: Therefore, it describes speed, not a complete velocity.","steps":["Step 1: 40 km/h gives the magnitude of motion.","Step 2: No direction is specified.","Step 3: Therefore, it describes speed, not a complete velocity."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 2),
  (59, 12, 'A cyclist moves at 30 km/h west. What is the speed and what is the velocity?', 'text', 1, 'Speed has no direction; velocity includes direction.', '{"why":"Velocity is speed together with direction.","sol":"Step 1: The speed is 30 km/h.\nStep 2: The direction is west.\nStep 3: Therefore, velocity is 30 km/h west.","steps":["Step 1: The speed is 30 km/h.","Step 2: The direction is west.","Step 3: Therefore, velocity is 30 km/h west."],"options":[],"conceptId":"math_linear_motion_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Velocity"}', 3),
  (60, 13, 'A car moves 100 km east in 2 hours. Find its average velocity.', 'text', 1, 'Use displacement ÷ time.', '{"why":"Average velocity uses displacement divided by total time.","sol":"Step 1: Displacement = 100 km east.\nStep 2: Time = 2 h.\nStep 3: Average velocity = 100 ÷ 2.\nStep 4: Average velocity = 50 km/h east.","steps":["Step 1: Displacement = 100 km east.","Step 2: Time = 2 h.","Step 3: Average velocity = 100 ÷ 2.","Step 4: Average velocity = 50 km/h east."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 0),
  (61, 13, 'A runner returns to the starting point after 3 hours. What is the average velocity?', 'text', 1, 'The displacement is zero.', '{"why":"Returning to the starting point gives zero displacement.","sol":"Step 1: The runner finishes at the starting position.\nStep 2: Displacement = 0 km.\nStep 3: Average velocity = 0 ÷ 3.\nStep 4: Average velocity = 0 km/h.","steps":["Step 1: The runner finishes at the starting position.","Step 2: Displacement = 0 km.","Step 3: Average velocity = 0 ÷ 3.","Step 4: Average velocity = 0 km/h."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 1),
  (62, 13, 'A cyclist travels 60 km west in 3 hours. Find the average velocity.', 'text', 1, 'Include the direction west.', '{"why":"Average velocity includes the direction of displacement.","sol":"Step 1: Displacement = 60 km west.\nStep 2: Time = 3 h.\nStep 3: Average velocity = 60 ÷ 3.\nStep 4: Average velocity = 20 km/h west.","steps":["Step 1: Displacement = 60 km west.","Step 2: Time = 3 h.","Step 3: Average velocity = 60 ÷ 3.","Step 4: Average velocity = 20 km/h west."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 2),
  (63, 13, 'What quantity is used to calculate average velocity: distance or displacement?', 'text', 1, 'Velocity describes a change in position.', '{"why":"Average velocity is total displacement divided by total time.","sol":"Step 1: Velocity includes direction.\nStep 2: Displacement includes direction.\nStep 3: Therefore, average velocity uses displacement.","steps":["Step 1: Velocity includes direction.","Step 2: Displacement includes direction.","Step 3: Therefore, average velocity uses displacement."],"options":[],"conceptId":"math_linear_motion_average_velocity","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Average Velocity"}', 3),
  (64, 14, 'A car changes velocity from 10 m/s to 30 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use a = (v - u)/t.', '{"why":"Acceleration measures the change in velocity per unit time.","sol":"Step 1: u = 10 m/s.\nStep 2: v = 30 m/s.\nStep 3: Change in velocity = 30 - 10 = 20 m/s.\nStep 4: Acceleration = 20 ÷ 5 = 4 m/s².","steps":["Step 1: u = 10 m/s.","Step 2: v = 30 m/s.","Step 3: Change in velocity = 30 - 10 = 20 m/s.","Step 4: Acceleration = 20 ÷ 5 = 4 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 0),
  (65, 14, 'A bicycle changes velocity from 4 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract the initial velocity from the final velocity first.', '{"why":"Acceleration is the change in velocity divided by time.","sol":"Step 1: u = 4 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change in velocity = 16 - 4 = 12 m/s.\nStep 4: Acceleration = 12 ÷ 6 = 2 m/s².","steps":["Step 1: u = 4 m/s.","Step 2: v = 16 m/s.","Step 3: Change in velocity = 16 - 4 = 12 m/s.","Step 4: Acceleration = 12 ÷ 6 = 2 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 1),
  (66, 14, 'A car changes velocity from 20 m/s to 8 m/s in 4 s. Find its acceleration.', 'text', 1, 'Final velocity minus initial velocity gives a negative change.', '{"why":"The negative acceleration shows that velocity is decreasing in the chosen direction.","sol":"Step 1: u = 20 m/s.\nStep 2: v = 8 m/s.\nStep 3: Change in velocity = 8 - 20 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 4 = -3 m/s².","steps":["Step 1: u = 20 m/s.","Step 2: v = 8 m/s.","Step 3: Change in velocity = 8 - 20 = -12 m/s.","Step 4: Acceleration = -12 ÷ 4 = -3 m/s²."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 2),
  (67, 14, 'What does acceleration measure?', 'text', 1, 'Think about what happens to velocity as time passes.', '{"why":"Acceleration tells us how quickly velocity changes with time.","sol":"Step 1: Velocity can change during motion.\nStep 2: Acceleration measures how quickly that velocity changes.\nStep 3: Therefore, acceleration is change in velocity per unit time.","steps":["Step 1: Velocity can change during motion.","Step 2: Acceleration measures how quickly that velocity changes.","Step 3: Therefore, acceleration is change in velocity per unit time."],"options":[],"conceptId":"math_linear_motion_acceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Acceleration"}', 3),
  (68, 15, 'A car slows from 30 m/s to 20 m/s in 5 s. Find its acceleration.', 'text', 1, 'Use final velocity minus initial velocity.', '{"why":"The negative acceleration represents a decrease in velocity.","sol":"Step 1: u = 30 m/s.\nStep 2: v = 20 m/s.\nStep 3: Change = 20 - 30 = -10 m/s.\nStep 4: Acceleration = -10 ÷ 5 = -2 m/s².","steps":["Step 1: u = 30 m/s.","Step 2: v = 20 m/s.","Step 3: Change = 20 - 30 = -10 m/s.","Step 4: Acceleration = -10 ÷ 5 = -2 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 0),
  (69, 15, 'A bus slows from 40 m/s to 16 m/s in 6 s. Find its acceleration.', 'text', 1, 'Subtract 40 from 16, then divide by 6.', '{"why":"Velocity decreases by 24 m/s during the 6 seconds.","sol":"Step 1: u = 40 m/s.\nStep 2: v = 16 m/s.\nStep 3: Change = 16 - 40 = -24 m/s.\nStep 4: Acceleration = -24 ÷ 6 = -4 m/s².","steps":["Step 1: u = 40 m/s.","Step 2: v = 16 m/s.","Step 3: Change = 16 - 40 = -24 m/s.","Step 4: Acceleration = -24 ÷ 6 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 1),
  (70, 15, 'A motorcycle slows from 18 m/s to 6 m/s in 3 s. Find its acceleration.', 'text', 1, 'A decrease in velocity produces a negative change.', '{"why":"The negative sign indicates that the velocity is decreasing.","sol":"Step 1: u = 18 m/s.\nStep 2: v = 6 m/s.\nStep 3: Change = 6 - 18 = -12 m/s.\nStep 4: Acceleration = -12 ÷ 3 = -4 m/s².","steps":["Step 1: u = 18 m/s.","Step 2: v = 6 m/s.","Step 3: Change = 6 - 18 = -12 m/s.","Step 4: Acceleration = -12 ÷ 3 = -4 m/s²."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 2),
  (71, 15, 'What does a negative acceleration mean in these examples?', 'text', 1, 'Look at what happened to the velocity.', '{"why":"A negative change in velocity produces negative acceleration in the chosen direction.","sol":"Step 1: The final velocity is smaller than the initial velocity.\nStep 2: Therefore, v - u is negative.\nStep 3: The negative acceleration represents a decrease in velocity in the chosen direction.","steps":["Step 1: The final velocity is smaller than the initial velocity.","Step 2: Therefore, v - u is negative.","Step 3: The negative acceleration represents a decrease in velocity in the chosen direction."],"options":[],"conceptId":"math_linear_motion_deceleration","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Deceleration"}', 3),
  (72, 16, 'A point on a distance-time graph is (3 h, 150 km). What distance has been travelled?', 'text', 1, 'Distance is read from the vertical coordinate.', '{"why":"Distance is represented on the vertical axis.","sol":"Step 1: The point is (3 h, 150 km).\nStep 2: The second coordinate represents distance.\nStep 3: Therefore, distance = 150 km.","steps":["Step 1: The point is (3 h, 150 km).","Step 2: The second coordinate represents distance.","Step 3: Therefore, distance = 150 km."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 0),
  (73, 16, 'A point on a distance-time graph is (4 h, 200 km). What time does it represent?', 'text', 1, 'Time is represented on the horizontal axis.', '{"why":"Time is represented on the horizontal axis.","sol":"Step 1: The point is (4 h, 200 km).\nStep 2: The first coordinate represents time.\nStep 3: Therefore, time = 4 h.","steps":["Step 1: The point is (4 h, 200 km).","Step 2: The first coordinate represents time.","Step 3: Therefore, time = 4 h."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 1),
  (74, 16, 'At 6 hours, a graph shows a distance of 360 km. State the point on the graph.', 'text', 1, 'Write the point as (time, distance).', '{"why":"The horizontal coordinate is time and the vertical coordinate is distance.","sol":"Step 1: Time = 6 h.\nStep 2: Distance = 360 km.\nStep 3: A point is written as (time, distance).\nStep 4: Therefore, the point is (6 h, 360 km).","steps":["Step 1: Time = 6 h.","Step 2: Distance = 360 km.","Step 3: A point is written as (time, distance).","Step 4: Therefore, the point is (6 h, 360 km)."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 2),
  (75, 16, 'Which quantity belongs on the horizontal axis of a distance-time graph?', 'text', 1, 'Think about which quantity is allowed to pass as the motion happens.', '{"why":"A distance-time graph shows how distance changes with time.","sol":"Step 1: Time passes during motion.\nStep 2: Distance changes as time passes.\nStep 3: Therefore, time is placed on the horizontal axis.","steps":["Step 1: Time passes during motion.","Step 2: Distance changes as time passes.","Step 3: Therefore, time is placed on the horizontal axis."],"options":[],"conceptId":"math_linear_motion_reading_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Reading a Distance-Time Graph"}', 3),
  (76, 17, 'A distance-time graph goes from (0 h, 0 km) to (4 h, 200 km). Find its gradient.', 'text', 1, 'Gradient = change in distance ÷ change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 200 - 0 = 200 km.\nStep 2: Change in time = 4 - 0 = 4 h.\nStep 3: Gradient = 200 ÷ 4.\nStep 4: Gradient = 50 km/h.","steps":["Step 1: Change in distance = 200 - 0 = 200 km.","Step 2: Change in time = 4 - 0 = 4 h.","Step 3: Gradient = 200 ÷ 4.","Step 4: Gradient = 50 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 0),
  (77, 17, 'A graph passes through (2 h, 40 km) and (5 h, 160 km). Find the gradient.', 'text', 1, 'Subtract corresponding coordinates first.', '{"why":"Gradient is change in distance divided by change in time.","sol":"Step 1: Change in distance = 160 - 40 = 120 km.\nStep 2: Change in time = 5 - 2 = 3 h.\nStep 3: Gradient = 120 ÷ 3.\nStep 4: Gradient = 40 km/h.","steps":["Step 1: Change in distance = 160 - 40 = 120 km.","Step 2: Change in time = 5 - 2 = 3 h.","Step 3: Gradient = 120 ÷ 3.","Step 4: Gradient = 40 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 1),
  (78, 17, 'A distance-time graph has a gradient of 60 km/h. What does this tell you about the object''s speed?', 'text', 1, 'The gradient represents speed.', '{"why":"Gradient on a distance-time graph gives speed.","sol":"Step 1: For a distance-time graph, gradient represents speed.\nStep 2: The gradient is 60 km/h.\nStep 3: Therefore, the object''s speed is 60 km/h.","steps":["Step 1: For a distance-time graph, gradient represents speed.","Step 2: The gradient is 60 km/h.","Step 3: Therefore, the object''s speed is 60 km/h."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 2),
  (79, 17, 'Which object is faster: one with a distance-time gradient of 30 km/h or one with 50 km/h?', 'text', 1, 'A larger gradient means greater speed.', '{"why":"A greater gradient represents a greater speed.","sol":"Step 1: First object''s speed = 30 km/h.\nStep 2: Second object''s speed = 50 km/h.\nStep 3: 50 km/h is greater than 30 km/h.\nStep 4: Therefore, the second object is faster.","steps":["Step 1: First object''s speed = 30 km/h.","Step 2: Second object''s speed = 50 km/h.","Step 3: 50 km/h is greater than 30 km/h.","Step 4: Therefore, the second object is faster."],"options":[],"conceptId":"math_linear_motion_gradient_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Gradient of a Distance-Time Graph"}', 3),
  (80, 18, 'A distance-time graph is horizontal from 2 h to 5 h. What is happening?', 'text', 1, 'A horizontal line means distance is not changing.', '{"why":"A horizontal distance-time graph means there is no change in distance.","sol":"Step 1: The distance remains constant.\nStep 2: Time continues to pass.\nStep 3: Therefore, the object is stationary.","steps":["Step 1: The distance remains constant.","Step 2: Time continues to pass.","Step 3: Therefore, the object is stationary."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 0),
  (81, 18, 'An object is stationary from 4 h to 6 h. How long is it stationary?', 'text', 1, 'Subtract the starting time from the ending time.', '{"why":"The length of a stationary period is the difference between the two times.","sol":"Step 1: Starting time = 4 h.\nStep 2: Ending time = 6 h.\nStep 3: Time = 6 - 4 = 2 h.","steps":["Step 1: Starting time = 4 h.","Step 2: Ending time = 6 h.","Step 3: Time = 6 - 4 = 2 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 1),
  (82, 18, 'A horizontal section runs from 1.5 h to 2.5 h. How long is the stationary period?', 'text', 1, 'Calculate 2.5 - 1.5.', '{"why":"The object remains at the same distance for the one-hour interval.","sol":"Step 1: Starting time = 1.5 h.\nStep 2: Ending time = 2.5 h.\nStep 3: Time = 2.5 - 1.5 = 1 h.","steps":["Step 1: Starting time = 1.5 h.","Step 2: Ending time = 2.5 h.","Step 3: Time = 2.5 - 1.5 = 1 h."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 2),
  (83, 18, 'What does a horizontal line on a distance-time graph tell us about speed?', 'text', 1, 'If distance is not changing, what is the rate of change of distance?', '{"why":"No change in distance over time means zero speed.","sol":"Step 1: Speed is change in distance divided by time.\nStep 2: A horizontal line means change in distance is zero.\nStep 3: Therefore, speed is zero.","steps":["Step 1: Speed is change in distance divided by time.","Step 2: A horizontal line means change in distance is zero.","Step 3: Therefore, speed is zero."],"options":[],"conceptId":"math_linear_motion_interpreting_a_horizontal_section_of_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Interpreting a Horizontal Section of a Distance-Time Graph"}', 3),
  (84, 19, 'A car travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: Speed = 70 km/h.\nStep 2: Time = 3 h.\nStep 3: Distance = 70 × 3.\nStep 4: Distance = 210 km.","steps":["Step 1: Speed = 70 km/h.","Step 2: Time = 3 h.","Step 3: Distance = 70 × 3.","Step 4: Distance = 210 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 0),
  (85, 19, 'A cyclist travels at 20 km/h for 5 hours. Find the distance.', 'text', 1, 'Multiply 20 by 5.', '{"why":"The cyclist covers 20 km in each hour for 5 hours.","sol":"Step 1: Speed = 20 km/h.\nStep 2: Time = 5 h.\nStep 3: Distance = 20 × 5.\nStep 4: Distance = 100 km.","steps":["Step 1: Speed = 20 km/h.","Step 2: Time = 5 h.","Step 3: Distance = 20 × 5.","Step 4: Distance = 100 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 1),
  (86, 19, 'A bus travels at 90 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"Multiplying the rate by the time gives the total distance.","sol":"Step 1: Speed = 90 km/h.\nStep 2: Time = 2.5 h.\nStep 3: Distance = 90 × 2.5.\nStep 4: Distance = 225 km.","steps":["Step 1: Speed = 90 km/h.","Step 2: Time = 2.5 h.","Step 3: Distance = 90 × 2.5.","Step 4: Distance = 225 km."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 2),
  (87, 19, 'Which formula gives distance when speed and time are known?', 'text', 1, 'Think about multiplying the rate by the amount of time.', '{"why":"Distance equals speed multiplied by time.","sol":"Step 1: Speed tells us distance covered per unit of time.\nStep 2: Multiplying speed by time gives the total distance.\nStep 3: Therefore, d = st.","steps":["Step 1: Speed tells us distance covered per unit of time.","Step 2: Multiplying speed by time gives the total distance.","Step 3: Therefore, d = st."],"options":[],"conceptId":"math_linear_motion_distance_speed_time_relationship","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Distance-Speed-Time Relationship"}', 3),
  (88, 20, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: Distance = 300 km.\nStep 2: Speed = 75 km/h.\nStep 3: Time = 300 ÷ 75.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 300 km.","Step 2: Speed = 75 km/h.","Step 3: Time = 300 ÷ 75.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 0),
  (89, 20, 'A cyclist travels 120 km at 40 km/h. Find the time.', 'text', 1, 'Divide 120 by 40.', '{"why":"The time is the distance divided by the distance covered per hour.","sol":"Step 1: Distance = 120 km.\nStep 2: Speed = 40 km/h.\nStep 3: Time = 120 ÷ 40.\nStep 4: Time = 3 hours.","steps":["Step 1: Distance = 120 km.","Step 2: Speed = 40 km/h.","Step 3: Time = 120 ÷ 40.","Step 4: Time = 3 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 1),
  (90, 20, 'A train travels 360 km at 90 km/h. Find the time.', 'text', 1, 'Use time = distance ÷ speed.', '{"why":"Dividing distance by speed gives the time taken.","sol":"Step 1: Distance = 360 km.\nStep 2: Speed = 90 km/h.\nStep 3: Time = 360 ÷ 90.\nStep 4: Time = 4 hours.","steps":["Step 1: Distance = 360 km.","Step 2: Speed = 90 km/h.","Step 3: Time = 360 ÷ 90.","Step 4: Time = 4 hours."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 2),
  (91, 20, 'Which formula should you use to find time when distance and speed are known?', 'text', 1, 'Rearrange d = st so that time is alone.', '{"why":"Rearranging the distance-speed-time relationship gives time.","sol":"Step 1: Start with d = st.\nStep 2: Divide both sides by s.\nStep 3: This gives t = d/s.","steps":["Step 1: Start with d = st.","Step 2: Divide both sides by s.","Step 3: This gives t = d/s."],"options":[],"conceptId":"math_linear_motion_finding_time_from_distance_and_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Time from Distance and Speed"}', 3),
  (92, 21, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: Distance = 300 km.\nStep 2: Time = 5 h.\nStep 3: Speed = 300 ÷ 5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 300 km.","Step 2: Time = 5 h.","Step 3: Speed = 300 ÷ 5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 0),
  (93, 21, 'A runner covers 24 km in 2 hours. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The speed tells how much distance is covered per hour.","sol":"Step 1: Distance = 24 km.\nStep 2: Time = 2 h.\nStep 3: Speed = 24 ÷ 2.\nStep 4: Speed = 12 km/h.","steps":["Step 1: Distance = 24 km.","Step 2: Time = 2 h.","Step 3: Speed = 24 ÷ 2.","Step 4: Speed = 12 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 1),
  (94, 21, 'A bus travels 280 km in 4 hours. Find its speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Dividing the total distance by total time gives speed.","sol":"Step 1: Distance = 280 km.\nStep 2: Time = 4 h.\nStep 3: Speed = 280 ÷ 4.\nStep 4: Speed = 70 km/h.","steps":["Step 1: Distance = 280 km.","Step 2: Time = 4 h.","Step 3: Speed = 280 ÷ 4.","Step 4: Speed = 70 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 2),
  (95, 21, 'A cyclist travels 90 km in 1.5 hours. Find the speed.', 'text', 1, 'Divide 90 by 1.5.', '{"why":"Speed is the distance travelled per unit of time.","sol":"Step 1: Distance = 90 km.\nStep 2: Time = 1.5 h.\nStep 3: Speed = 90 ÷ 1.5.\nStep 4: Speed = 60 km/h.","steps":["Step 1: Distance = 90 km.","Step 2: Time = 1.5 h.","Step 3: Speed = 90 ÷ 1.5.","Step 4: Speed = 60 km/h."],"options":[],"conceptId":"math_linear_motion_finding_speed_from_distance_and_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Speed from Distance and Time"}', 3),
  (96, 22, 'A car travels at 80 km/h while another car travels at 55 km/h in the same direction. Find their relative speed.', 'text', 1, 'For objects moving in the same direction, subtract the smaller speed from the larger speed.', '{"why":"The faster car gains on the slower car at the difference between their speeds.","sol":"Step 1: Relative speed = 80 − 55\nStep 2: Relative speed = 25 km/h","steps":["Step 1: Relative speed = 80 − 55","Step 2: Relative speed = 25 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 0),
  (97, 22, 'A bus travels at 72 km/h and a truck travels at 60 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract the two speeds.', '{"why":"The distance between the two vehicles changes at 12 km/h.","sol":"Step 1: Relative speed = 72 − 60\nStep 2: Relative speed = 12 km/h","steps":["Step 1: Relative speed = 72 − 60","Step 2: Relative speed = 12 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 1),
  (98, 22, 'Two cyclists travel in the same direction at 30 km/h and 22 km/h. Find the relative speed.', 'text', 1, 'Same direction means subtraction.', '{"why":"The faster cyclist gains 8 km on the slower cyclist every hour.","sol":"Step 1: Relative speed = 30 − 22\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 30 − 22","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 2),
  (99, 22, 'A car travels at 90 km/h while a bus travels at 60 km/h in the same direction. Find their relative speed.', 'text', 1, 'Subtract the smaller speed from the larger speed.', '{"why":"The car gains on the bus at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60\nStep 2: Relative speed = 30 km/h","steps":["Step 1: Relative speed = 90 − 60","Step 2: Relative speed = 30 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 3),
  (100, 22, 'Two cyclists travel in the same direction at 28 km/h and 20 km/h. Find their relative speed.', 'text', 1, 'Same direction means subtract.', '{"why":"The faster cyclist reduces the separation by 8 km every hour.","sol":"Step 1: Relative speed = 28 − 20\nStep 2: Relative speed = 8 km/h","steps":["Step 1: Relative speed = 28 − 20","Step 2: Relative speed = 8 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 4),
  (101, 22, 'A truck moves at 55 km/h and a car moves at 75 km/h in the same direction. Find the relative speed.', 'text', 1, 'Subtract 55 from 75.', '{"why":"The car gains on the truck at 20 km/h.","sol":"Step 1: Relative speed = 75 − 55\nStep 2: Relative speed = 20 km/h","steps":["Step 1: Relative speed = 75 − 55","Step 2: Relative speed = 20 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_the_same_direction","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in the Same Direction"}', 5),
  (102, 23, 'Two cars travel towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean the speeds are added.', '{"why":"Both cars reduce the distance between them, so their speeds add.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 0),
  (103, 23, 'Two cyclists move towards each other at 25 km/h and 15 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The cyclists are approaching each other from opposite directions.","sol":"Step 1: Relative speed = 25 + 15\nStep 2: Relative speed = 40 km/h","steps":["Step 1: Relative speed = 25 + 15","Step 2: Relative speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 1),
  (104, 23, 'A train travels east at 90 km/h while another train travels west at 80 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because the trains are moving towards each other.","sol":"Step 1: Relative speed = 90 + 80\nStep 2: Relative speed = 170 km/h","steps":["Step 1: Relative speed = 90 + 80","Step 2: Relative speed = 170 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 2),
  (105, 23, 'Two cars move towards each other at 70 km/h and 50 km/h. Find their relative speed.', 'text', 1, 'Opposite directions mean add the speeds.', '{"why":"Both cars reduce the distance between them.","sol":"Step 1: Relative speed = 70 + 50\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 70 + 50","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 3),
  (106, 23, 'Two cyclists approach each other at 20 km/h and 30 km/h. Find their relative speed.', 'text', 1, 'They are moving towards each other.', '{"why":"Their speeds combine because they move in opposite directions.","sol":"Step 1: Relative speed = 20 + 30\nStep 2: Relative speed = 50 km/h","steps":["Step 1: Relative speed = 20 + 30","Step 2: Relative speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 4),
  (107, 23, 'A bus and a car approach each other at 45 km/h and 75 km/h. Find their relative speed.', 'text', 1, 'Add the two speeds.', '{"why":"The distance between them decreases at the sum of their speeds.","sol":"Step 1: Relative speed = 45 + 75\nStep 2: Relative speed = 120 km/h","steps":["Step 1: Relative speed = 45 + 75","Step 2: Relative speed = 120 km/h"],"options":[],"conceptId":"math_linear_motion_relative_speed_in_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Relative Speed in Opposite Directions"}', 5),
  (108, 24, 'Two cars travel in the same direction at 90 km/h and 70 km/h. How much does the distance between them change in 3 hours?', 'text', 1, 'First find relative speed, then multiply by time.', '{"why":"The faster car gains 20 km every hour, so in 3 hours it gains 60 km.","sol":"Step 1: Relative speed = 90 − 70 = 20 km/h\nStep 2: Change in distance = 20 × 3\nStep 3: Change in distance = 60 km","steps":["Step 1: Relative speed = 90 − 70 = 20 km/h","Step 2: Change in distance = 20 × 3","Step 3: Change in distance = 60 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 0),
  (109, 24, 'Two vehicles move towards each other at 60 km/h and 40 km/h. How much distance do they close in 2 hours?', 'text', 1, 'Find the relative speed first.', '{"why":"The vehicles approach each other at a combined rate of 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Change in distance = 100 × 2\nStep 3: Change in distance = 200 km","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Change in distance = 100 × 2","Step 3: Change in distance = 200 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 1),
  (110, 24, 'A bus travels at 75 km/h and a car ahead travels at 55 km/h. How much distance does the bus gain in 5 hours?', 'text', 1, 'Subtract their speeds before multiplying by time.', '{"why":"The bus gains 20 km every hour on the car.","sol":"Step 1: Relative speed = 75 − 55 = 20 km/h\nStep 2: Distance gained = 20 × 5\nStep 3: Distance gained = 100 km","steps":["Step 1: Relative speed = 75 − 55 = 20 km/h","Step 2: Distance gained = 20 × 5","Step 3: Distance gained = 100 km"],"options":[],"conceptId":"math_linear_motion_finding_distance_between_moving_objects","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Between Moving Objects"}', 2),
  (111, 25, 'Two cars move in the same direction at 90 km/h and 60 km/h. How much does the faster car gain in 4 hours?', 'text', 1, 'First find the relative speed.', '{"why":"The faster car gains 30 km every hour.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Gain = 30 × 4\nStep 3: Gain = 120 km","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Gain = 30 × 4","Step 3: Gain = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 0),
  (112, 25, 'Two vehicles approach each other at 50 km/h and 40 km/h. How much does their separation decrease in 3 hours?', 'text', 1, 'Add their speeds first.', '{"why":"Their combined motion closes the gap at 90 km/h.","sol":"Step 1: Relative speed = 50 + 40 = 90 km/h\nStep 2: Decrease = 90 × 3\nStep 3: Decrease = 270 km","steps":["Step 1: Relative speed = 50 + 40 = 90 km/h","Step 2: Decrease = 90 × 3","Step 3: Decrease = 270 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 1),
  (113, 25, 'A bus travels at 70 km/h while a car travels at 100 km/h in the same direction. Find the distance gained by the car in 5 hours.', 'text', 1, 'Relative speed = 100 − 70.', '{"why":"The car gains 30 km on the bus every hour.","sol":"Step 1: Relative speed = 100 − 70 = 30 km/h\nStep 2: Gain = 30 × 5\nStep 3: Gain = 150 km","steps":["Step 1: Relative speed = 100 − 70 = 30 km/h","Step 2: Gain = 30 × 5","Step 3: Gain = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_separation_using_relative_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Separation Using Relative Speed"}', 2),
  (114, 26, 'A car travels at 50 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = 50 × 4\nStep 2: d = 200 km","steps":["Step 1: d = 50 × 4","Step 2: d = 200 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 0),
  (115, 26, 'A cyclist travels at 24 km/h for 2.5 hours. Find the distance travelled.', 'text', 1, 'Multiply 24 by 2.5.', '{"why":"The cyclist covers 24 km in each hour.","sol":"Step 1: d = 24 × 2.5\nStep 2: d = 60 km","steps":["Step 1: d = 24 × 2.5","Step 2: d = 60 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 1),
  (116, 26, 'A train travels at 90 km/h for 2 hours. Find the distance travelled.', 'text', 1, 'Use distance = speed × time.', '{"why":"The train covers 90 km each hour for 2 hours.","sol":"Step 1: d = 90 × 2\nStep 2: d = 180 km","steps":["Step 1: d = 90 × 2","Step 2: d = 180 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 2),
  (117, 26, 'A vehicle travels at 70 km/h for 3 hours. Find the distance.', 'text', 1, 'Distance = speed × time.', '{"why":"The vehicle covers 70 km each hour for 3 hours.","sol":"Step 1: d = st\nStep 2: d = 70 × 3\nStep 3: d = 210 km","steps":["Step 1: d = st","Step 2: d = 70 × 3","Step 3: d = 210 km"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 3),
  (118, 26, 'A cyclist covers 120 km in 4 hours. Find the speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed tells us how much distance is covered in one hour.","sol":"Step 1: s = d/t\nStep 2: s = 120/4\nStep 3: s = 30 km/h","steps":["Step 1: s = d/t","Step 2: s = 120/4","Step 3: s = 30 km/h"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 4),
  (119, 26, 'A bus travels at 60 km/h and covers 300 km. Find the time.', 'text', 1, 'Time = distance ÷ speed.', '{"why":"Dividing total distance by the speed gives the travel time.","sol":"Step 1: t = d/s\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: t = d/s","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_translating_motion_words_into_an_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Translating Motion Words into an Equation"}', 5),
  (120, 27, 'A car travels 300 km at 75 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"Time is found by dividing distance by speed.","sol":"Step 1: t = 300 / 75\nStep 2: t = 4 hours","steps":["Step 1: t = 300 / 75","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 0),
  (121, 27, 'A bus travels 180 km at 60 km/h. Find the time taken.', 'text', 1, 'Divide the distance by the speed.', '{"why":"At 60 km/h, the bus needs 3 hours to cover 180 km.","sol":"Step 1: t = 180 / 60\nStep 2: t = 3 hours","steps":["Step 1: t = 180 / 60","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 1),
  (122, 27, 'A cyclist travels 100 km at 20 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"The cyclist covers 20 km each hour.","sol":"Step 1: t = 100 / 20\nStep 2: t = 5 hours","steps":["Step 1: t = 100 / 20","Step 2: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 2),
  (123, 27, 'A car travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Use t = d/s.', '{"why":"At 90 km/h, the car covers 90 km in each hour.","sol":"Step 1: t = 360/90\nStep 2: t = 4 hours","steps":["Step 1: t = 360/90","Step 2: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 3),
  (124, 27, 'A bus travels 420 km at 70 km/h. Find the travel time.', 'text', 1, 'Divide distance by speed.', '{"why":"Six groups of 70 km make 420 km.","sol":"Step 1: t = 420/70\nStep 2: t = 6 hours","steps":["Step 1: t = 420/70","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 4),
  (125, 27, 'A cyclist travels 150 km at 25 km/h. Find the time.', 'text', 1, 'Use t = 150/25.', '{"why":"The cyclist needs six hours to cover 150 km at 25 km/h.","sol":"Step 1: t = 150/25\nStep 2: t = 6 hours","steps":["Step 1: t = 150/25","Step 2: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_time_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Time in a Motion Problem"}', 5),
  (126, 28, 'A car travels 360 km in 6 hours. Find its speed.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 360 / 6\nStep 2: s = 60 km/h","steps":["Step 1: s = 360 / 6","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 0),
  (127, 28, 'A bus covers 240 km in 4 hours. Find its speed.', 'text', 1, 'Divide distance by time.', '{"why":"The bus covers 60 km during each hour.","sol":"Step 1: s = 240 / 4\nStep 2: s = 60 km/h","steps":["Step 1: s = 240 / 4","Step 2: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 1),
  (128, 28, 'A cyclist covers 75 km in 3 hours. Find the speed.', 'text', 1, 'Use s = d/t.', '{"why":"The cyclist covers 25 km in each hour.","sol":"Step 1: s = 75 / 3\nStep 2: s = 25 km/h","steps":["Step 1: s = 75 / 3","Step 2: s = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_speed_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Speed in a Motion Problem"}', 2),
  (129, 29, 'A car travels at 80 km/h for 6 hours. Find the distance.', 'text', 1, 'Multiply speed by time.', '{"why":"The car covers 80 km each hour for 6 hours.","sol":"Step 1: d = 80 × 6\nStep 2: d = 480 km","steps":["Step 1: d = 80 × 6","Step 2: d = 480 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 0),
  (130, 29, 'A cyclist travels at 30 km/h for 2.5 hours. Find the distance.', 'text', 1, 'Use d = st.', '{"why":"The cyclist covers 30 km per hour, so 2.5 hours gives 75 km.","sol":"Step 1: d = 30 × 2.5\nStep 2: d = 75 km","steps":["Step 1: d = 30 × 2.5","Step 2: d = 75 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 1),
  (131, 29, 'A train travels at 90 km/h for 1.5 hours. Find the distance.', 'text', 1, 'Multiply 90 by 1.5.', '{"why":"The train covers 90 km in the first hour and another 45 km in half an hour.","sol":"Step 1: d = 90 × 1.5\nStep 2: d = 135 km","steps":["Step 1: d = 90 × 1.5","Step 2: d = 135 km"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_in_a_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance in a Motion Problem"}', 2),
  (132, 30, 'Two cars are 200 km apart and travel towards each other at 60 km/h and 40 km/h. Find their meeting time.', 'text', 1, 'Add their speeds first.', '{"why":"Their combined approach speed is 100 km/h.","sol":"Step 1: Relative speed = 60 + 40 = 100 km/h\nStep 2: Time = 200 / 100\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 60 + 40 = 100 km/h","Step 2: Time = 200 / 100","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 0),
  (133, 30, 'Two cyclists are 150 km apart and move towards each other at 40 km/h and 35 km/h. Find when they meet.', 'text', 1, 'Use time = distance ÷ relative speed.', '{"why":"Together they close 75 km of separation each hour.","sol":"Step 1: Relative speed = 40 + 35 = 75 km/h\nStep 2: Time = 150 / 75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 40 + 35 = 75 km/h","Step 2: Time = 150 / 75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 1),
  (134, 30, 'Two buses are 300 km apart and travel towards each other at 70 km/h and 80 km/h. Find the meeting time.', 'text', 1, 'Add 70 and 80.', '{"why":"Their combined speed towards each other is 150 km/h.","sol":"Step 1: Relative speed = 70 + 80 = 150 km/h\nStep 2: Time = 300 / 150\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 80 = 150 km/h","Step 2: Time = 300 / 150","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time"}', 2),
  (135, 31, 'Two cars are 180 km apart and travel towards each other at 60 km/h and 30 km/h. Find the distance travelled by the 60 km/h car before they meet.', 'text', 1, 'First find the meeting time.', '{"why":"The faster car travels at 60 km/h for the 2 hours before meeting.","sol":"Step 1: Relative speed = 60 + 30 = 90 km/h\nStep 2: Meeting time = 180 / 90 = 2 h\nStep 3: Distance = 60 × 2\nStep 4: Distance = 120 km","steps":["Step 1: Relative speed = 60 + 30 = 90 km/h","Step 2: Meeting time = 180 / 90 = 2 h","Step 3: Distance = 60 × 2","Step 4: Distance = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 0),
  (136, 31, 'Two cyclists are 120 km apart and travel towards each other at 40 km/h and 20 km/h. Find the distance travelled by the slower cyclist before meeting.', 'text', 1, 'Find the meeting time, then use d = st.', '{"why":"The slower cyclist travels for the same 2 hours at 20 km/h.","sol":"Step 1: Relative speed = 40 + 20 = 60 km/h\nStep 2: Meeting time = 120 / 60 = 2 h\nStep 3: Distance = 20 × 2\nStep 4: Distance = 40 km","steps":["Step 1: Relative speed = 40 + 20 = 60 km/h","Step 2: Meeting time = 120 / 60 = 2 h","Step 3: Distance = 20 × 2","Step 4: Distance = 40 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 1),
  (137, 31, 'Two buses are 300 km apart and travel towards each other at 75 km/h and 50 km/h. Find the distance travelled by the 75 km/h bus before they meet.', 'text', 1, 'Find time first.', '{"why":"The faster bus travels 75 km/h for 2.4 hours.","sol":"Step 1: Relative speed = 75 + 50 = 125 km/h\nStep 2: Meeting time = 300 / 125 = 2.4 h\nStep 3: Distance = 75 × 2.4\nStep 4: Distance = 180 km","steps":["Step 1: Relative speed = 75 + 50 = 125 km/h","Step 2: Meeting time = 300 / 125 = 2.4 h","Step 3: Distance = 75 × 2.4","Step 4: Distance = 180 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 2),
  (138, 31, 'Two cars meet after 3 hours. The first car travels at 50 km/h. How far has it travelled to the meeting point?', 'text', 1, 'Use distance = speed × time.', '{"why":"The first car travels 50 km every hour for 3 hours.","sol":"Step 1: d = 50 × 3\nStep 2: d = 150 km","steps":["Step 1: d = 50 × 3","Step 2: d = 150 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 3),
  (139, 31, 'Two cyclists meet after 2 hours. The first cyclist travels at 35 km/h. Find the distance from the first cyclist''s starting point to the meeting point.', 'text', 1, 'Multiply 35 by 2.', '{"why":"The cyclist covers 35 km each hour for two hours.","sol":"Step 1: d = 35 × 2\nStep 2: d = 70 km","steps":["Step 1: d = 35 × 2","Step 2: d = 70 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 4),
  (140, 31, 'Two buses meet after 4 hours. The first bus travels at 60 km/h. Find its distance to the meeting point.', 'text', 1, 'Use d = st.', '{"why":"The first bus covers 240 km before reaching the meeting point.","sol":"Step 1: d = 60 × 4\nStep 2: d = 240 km","steps":["Step 1: d = 60 × 4","Step 2: d = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_the_meeting_point","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding the Meeting Point"}', 5),
  (141, 32, 'A car travelling at 90 km/h is 30 km behind a bus travelling at 60 km/h. Find the time needed to catch the bus.', 'text', 1, 'Subtract the speeds, then divide the gap by the relative speed.', '{"why":"The car closes the 30 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 30 / 30\nStep 3: Time = 1 hour","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 30 / 30","Step 3: Time = 1 hour"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 0),
  (142, 32, 'A cyclist travelling at 25 km/h is 20 km behind another cyclist travelling at 15 km/h. Find the catching time.', 'text', 1, 'Relative speed = 25 − 15.', '{"why":"The faster cyclist gains 10 km every hour.","sol":"Step 1: Relative speed = 25 − 15 = 10 km/h\nStep 2: Time = 20 / 10\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 − 15 = 10 km/h","Step 2: Time = 20 / 10","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 1),
  (143, 32, 'A motorcycle travelling at 100 km/h is 45 km behind a car travelling at 85 km/h. Find the time needed to catch it.', 'text', 1, 'Find the relative speed first.', '{"why":"The motorcycle closes the gap at 15 km/h.","sol":"Step 1: Relative speed = 100 − 85 = 15 km/h\nStep 2: Time = 45 / 15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 100 − 85 = 15 km/h","Step 2: Time = 45 / 15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_overtaking_a_slower_object","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Overtaking a Slower Object"}', 2),
  (144, 33, 'Two cars are 240 km apart and travel towards each other at 70 km/h and 50 km/h. Find the meeting time.', 'text', 1, 'Relative speed = 70 + 50.', '{"why":"Together the cars close 120 km of separation every hour.","sol":"Step 1: Relative speed = 70 + 50 = 120 km/h\nStep 2: Time = 240/120\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 70 + 50 = 120 km/h","Step 2: Time = 240/120","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 0),
  (145, 33, 'Two cyclists are 150 km apart and travel towards each other at 25 km/h and 50 km/h. Find when they meet.', 'text', 1, 'Add the speeds.', '{"why":"Their combined closing speed is 75 km/h.","sol":"Step 1: Relative speed = 25 + 50 = 75 km/h\nStep 2: Time = 150/75\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 25 + 50 = 75 km/h","Step 2: Time = 150/75","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 1),
  (146, 33, 'Two buses are 360 km apart and travel towards each other at 80 km/h and 40 km/h. Find the meeting time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"At a combined speed of 120 km/h, 360 km is covered in 3 hours.","sol":"Step 1: Relative speed = 80 + 40 = 120 km/h\nStep 2: Time = 360/120\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 80 + 40 = 120 km/h","Step 2: Time = 360/120","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_meeting_time_from_opposite_directions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Meeting Time from Opposite Directions"}', 2),
  (147, 34, 'A car is 60 km behind a bus. The car travels at 90 km/h and the bus at 60 km/h. Find the overtaking time.', 'text', 1, 'Relative speed = 90 − 60.', '{"why":"The car closes the 60 km gap at 30 km/h.","sol":"Step 1: Relative speed = 90 − 60 = 30 km/h\nStep 2: Time = 60/30\nStep 3: Time = 2 hours","steps":["Step 1: Relative speed = 90 − 60 = 30 km/h","Step 2: Time = 60/30","Step 3: Time = 2 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 0),
  (148, 34, 'A cyclist is 20 km behind another cyclist. Their speeds are 30 km/h and 25 km/h. Find the time to catch up.', 'text', 1, 'Subtract the speeds first.', '{"why":"The faster cyclist gains 5 km every hour.","sol":"Step 1: Relative speed = 30 − 25 = 5 km/h\nStep 2: Time = 20/5\nStep 3: Time = 4 hours","steps":["Step 1: Relative speed = 30 − 25 = 5 km/h","Step 2: Time = 20/5","Step 3: Time = 4 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 1),
  (149, 34, 'A car is 45 km behind a truck. The car travels at 75 km/h and the truck at 60 km/h. Find the overtaking time.', 'text', 1, 'Use time = separation ÷ relative speed.', '{"why":"The car closes the 45 km gap at 15 km/h.","sol":"Step 1: Relative speed = 75 − 60 = 15 km/h\nStep 2: Time = 45/15\nStep 3: Time = 3 hours","steps":["Step 1: Relative speed = 75 − 60 = 15 km/h","Step 2: Time = 45/15","Step 3: Time = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_overtaking_time","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Overtaking Time"}', 2),
  (150, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"Each kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000 = 5000\nStep 2: Therefore, 5 km = 5000 m","steps":["Step 1: 5 × 1000 = 5000","Step 2: Therefore, 5 km = 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 0),
  (151, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are changed to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000 = 2400\nStep 2: Therefore, 2.4 km = 2400 m","steps":["Step 1: 2.4 × 1000 = 2400","Step 2: Therefore, 2.4 km = 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 1),
  (152, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 of a kilometre is 350 metres.","sol":"Step 1: 0.35 × 1000 = 350\nStep 2: Therefore, 0.35 km = 350 m","steps":["Step 1: 0.35 × 1000 = 350","Step 2: Therefore, 0.35 km = 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 2),
  (153, 35, 'Convert 5 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"One kilometre contains 1000 metres.","sol":"Step 1: 5 × 1000\nStep 2: 5000 m","steps":["Step 1: 5 × 1000","Step 2: 5000 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 3),
  (154, 35, 'Convert 2.4 km to metres.', 'text', 1, 'Multiply 2.4 by 1000.', '{"why":"Kilometres are converted to metres by multiplying by 1000.","sol":"Step 1: 2.4 × 1000\nStep 2: 2400 m","steps":["Step 1: 2.4 × 1000","Step 2: 2400 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 4),
  (155, 35, 'Convert 0.35 km to metres.', 'text', 1, 'Multiply by 1000.', '{"why":"0.35 kilometres contains 350 metres.","sol":"Step 1: 0.35 × 1000\nStep 2: 350 m","steps":["Step 1: 0.35 × 1000","Step 2: 350 m"],"options":[],"conceptId":"math_linear_motion_converting_kilometres_to_metres","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Converting Kilometres to Metres"}', 5),
  (156, 36, 'Convert 6 minutes to seconds.', 'text', 1, '1 minute = 60 seconds.', '{"why":"Each minute contains 60 seconds.","sol":"Step 1: 6 × 60 = 360\nStep 2: Therefore, 6 minutes = 360 seconds","steps":["Step 1: 6 × 60 = 360","Step 2: Therefore, 6 minutes = 360 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 0),
  (157, 36, 'Convert 4.5 minutes to seconds.', 'text', 1, 'Multiply 4.5 by 60.', '{"why":"The conversion factor from minutes to seconds is 60.","sol":"Step 1: 4.5 × 60 = 270\nStep 2: Therefore, 4.5 minutes = 270 seconds","steps":["Step 1: 4.5 × 60 = 270","Step 2: Therefore, 4.5 minutes = 270 seconds"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 1),
  (158, 36, 'Convert 3 hours to minutes.', 'text', 1, '1 hour = 60 minutes.', '{"why":"Each hour contains 60 minutes.","sol":"Step 1: 3 × 60 = 180\nStep 2: Therefore, 3 hours = 180 minutes","steps":["Step 1: 3 × 60 = 180","Step 2: Therefore, 3 hours = 180 minutes"],"options":[],"conceptId":"math_linear_motion_converting_minutes_and_seconds","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes and Seconds"}', 2),
  (159, 37, 'Convert 18 km/h to m/s.', 'text', 1, 'Multiply by 5/18.', '{"why":"The conversion factor from km/h to m/s is 5/18.","sol":"Step 1: 18 × 5/18\nStep 2: 18 ÷ 18 = 1\nStep 3: 1 × 5 = 5 m/s","steps":["Step 1: 18 × 5/18","Step 2: 18 ÷ 18 = 1","Step 3: 1 × 5 = 5 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 0),
  (160, 37, 'Convert 90 km/h to m/s.', 'text', 1, 'Use 5/18.', '{"why":"90 km/h is equivalent to 25 metres per second.","sol":"Step 1: 90 × 5/18\nStep 2: 90 ÷ 18 = 5\nStep 3: 5 × 5 = 25 m/s","steps":["Step 1: 90 × 5/18","Step 2: 90 ÷ 18 = 5","Step 3: 5 × 5 = 25 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 1),
  (161, 37, 'Convert 108 km/h to m/s.', 'text', 1, 'Multiply 108 by 5/18.', '{"why":"The unit conversion gives 30 metres per second.","sol":"Step 1: 108 × 5/18\nStep 2: 108 ÷ 18 = 6\nStep 3: 6 × 5 = 30 m/s","steps":["Step 1: 108 × 5/18","Step 2: 108 ÷ 18 = 6","Step 3: 6 × 5 = 30 m/s"],"options":[],"conceptId":"math_linear_motion_converting_speed_between_km_h_and_m_s","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Speed Between km/h and m/s"}', 2),
  (162, 38, 'Convert 5 m/s to km/h.', 'text', 1, 'Multiply by 18/5.', '{"why":"The conversion factor from m/s to km/h is 18/5.","sol":"Step 1: 5 × 18/5\nStep 2: 5 ÷ 5 = 1\nStep 3: 1 × 18 = 18 km/h","steps":["Step 1: 5 × 18/5","Step 2: 5 ÷ 5 = 1","Step 3: 1 × 18 = 18 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 0),
  (163, 38, 'Convert 15 m/s to km/h.', 'text', 1, 'Use 18/5.', '{"why":"15 metres per second is equivalent to 54 kilometres per hour.","sol":"Step 1: 15 × 18/5\nStep 2: 15 ÷ 5 = 3\nStep 3: 3 × 18 = 54 km/h","steps":["Step 1: 15 × 18/5","Step 2: 15 ÷ 5 = 3","Step 3: 3 × 18 = 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 1),
  (164, 38, 'Convert 30 m/s to km/h.', 'text', 1, 'Multiply 30 by 18/5.', '{"why":"The converted speed is 108 kilometres per hour.","sol":"Step 1: 30 × 18/5\nStep 2: 30 ÷ 5 = 6\nStep 3: 6 × 18 = 108 km/h","steps":["Step 1: 30 × 18/5","Step 2: 30 ÷ 5 = 6","Step 3: 6 × 18 = 108 km/h"],"options":[],"conceptId":"math_linear_motion_converting_m_s_to_km_h","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting m/s to km/h"}', 2),
  (165, 39, 'Convert 20 minutes to hours.', 'text', 1, 'Divide 20 by 60.', '{"why":"An hour contains 60 minutes, so minutes are divided by 60.","sol":"Step 1: 20/60 = 1/3\nStep 2: 1/3 hour ≈ 0.333 hour","steps":["Step 1: 20/60 = 1/3","Step 2: 1/3 hour ≈ 0.333 hour"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 0),
  (166, 39, 'Convert 30 minutes to hours.', 'text', 1, 'Divide by 60.', '{"why":"Thirty minutes is half of one hour.","sol":"Step 1: 30/60\nStep 2: 0.5 hours","steps":["Step 1: 30/60","Step 2: 0.5 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 1),
  (167, 39, 'Convert 120 minutes to hours.', 'text', 1, 'Divide 120 by 60.', '{"why":"Two groups of 60 minutes make 120 minutes.","sol":"Step 1: 120/60\nStep 2: 2 hours","steps":["Step 1: 120/60","Step 2: 2 hours"],"options":[],"conceptId":"math_linear_motion_converting_minutes_to_hours","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Minutes to Hours"}', 2),
  (168, 40, 'Convert 10 m/s to km/h.', 'text', 1, 'Multiply by 3.6.', '{"why":"Every 1 m/s is equivalent to 3.6 km/h.","sol":"Step 1: 10 × 3.6\nStep 2: 36 km/h","steps":["Step 1: 10 × 3.6","Step 2: 36 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 0),
  (169, 40, 'Convert 15 m/s to km/h.', 'text', 1, 'Use km/h = m/s × 3.6.', '{"why":"Multiplying by 3.6 converts the speed into kilometres per hour.","sol":"Step 1: 15 × 3.6\nStep 2: 54 km/h","steps":["Step 1: 15 × 3.6","Step 2: 54 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 1),
  (170, 40, 'Convert 25 m/s to km/h.', 'text', 1, 'Multiply 25 by 3.6.', '{"why":"25 m/s is equivalent to 90 km/h.","sol":"Step 1: 25 × 3.6\nStep 2: 90 km/h","steps":["Step 1: 25 × 3.6","Step 2: 90 km/h"],"options":[],"conceptId":"math_linear_motion_converting_metres_per_second_to_kilometres_per_hour","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Converting Metres per Second to Kilometres per Hour"}', 2),
  (171, 41, 'A car travels at 60 km/h for 2 hours and then at 40 km/h for 1 hour. Find the distance travelled in each stage.', 'text', 1, 'Calculate each stage separately.', '{"why":"Each stage has its own speed and time.","sol":"Step 1: Stage 1: 60 × 2 = 120 km\nStep 2: Stage 2: 40 × 1 = 40 km","steps":["Step 1: Stage 1: 60 × 2 = 120 km","Step 2: Stage 2: 40 × 1 = 40 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 0),
  (172, 41, 'A cyclist travels at 25 km/h for 2 hours and then at 20 km/h for 3 hours. Find the distance in each stage.', 'text', 1, 'Use d = st for each stage.', '{"why":"The distance for each stage is calculated from that stage''s speed and time.","sol":"Step 1: Stage 1: 25 × 2 = 50 km\nStep 2: Stage 2: 20 × 3 = 60 km","steps":["Step 1: Stage 1: 25 × 2 = 50 km","Step 2: Stage 2: 20 × 3 = 60 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 1),
  (173, 41, 'A bus travels at 70 km/h for 1.5 hours and then at 50 km/h for 2 hours. Find the distance in each stage.', 'text', 1, 'Treat the two stages separately.', '{"why":"The speed changes after the first stage, so each stage must be calculated separately.","sol":"Step 1: Stage 1: 70 × 1.5 = 105 km\nStep 2: Stage 2: 50 × 2 = 100 km","steps":["Step 1: Stage 1: 70 × 1.5 = 105 km","Step 2: Stage 2: 50 × 2 = 100 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 2),
  (174, 41, 'A vehicle travels 120 km and then 80 km. Find the total distance.', 'text', 1, 'Add the distances of the two stages.', '{"why":"Total distance is the sum of the distances travelled in all stages.","sol":"Step 1: Stage 1 = 120 km\nStep 2: Stage 2 = 80 km\nStep 3: Total = 120 + 80\nStep 4: Total = 200 km","steps":["Step 1: Stage 1 = 120 km","Step 2: Stage 2 = 80 km","Step 3: Total = 120 + 80","Step 4: Total = 200 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 3),
  (175, 41, 'A journey takes 3 hours in the first stage and 2 hours in the second stage. Find the total time.', 'text', 1, 'Add the stage times.', '{"why":"The journey takes both stages consecutively.","sol":"Step 1: Stage 1 = 3 h\nStep 2: Stage 2 = 2 h\nStep 3: Total = 3 + 2\nStep 4: Total = 5 h","steps":["Step 1: Stage 1 = 3 h","Step 2: Stage 2 = 2 h","Step 3: Total = 3 + 2","Step 4: Total = 5 h"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 4),
  (176, 41, 'A cyclist travels 50 km and then another 25 km. Find the total distance.', 'text', 1, 'Add the two distances.', '{"why":"Both stages contribute to the total distance.","sol":"Step 1: Total distance = 50 + 25\nStep 2: Total distance = 75 km","steps":["Step 1: Total distance = 50 + 25","Step 2: Total distance = 75 km"],"options":[],"conceptId":"math_linear_motion_representing_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Representing a Multi-Stage Journey"}', 5),
  (177, 42, 'A car travels at 50 km/h for 2 hours and then at 70 km/h for 1 hour. Find the total distance.', 'text', 1, 'Find each stage distance, then add them.', '{"why":"The total journey distance is the sum of the distances in both stages.","sol":"Step 1: Stage 1 = 50 × 2 = 100 km\nStep 2: Stage 2 = 70 × 1 = 70 km\nStep 3: Total distance = 100 + 70 = 170 km","steps":["Step 1: Stage 1 = 50 × 2 = 100 km","Step 2: Stage 2 = 70 × 1 = 70 km","Step 3: Total distance = 100 + 70 = 170 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 0),
  (178, 42, 'A cyclist travels at 30 km/h for 2 hours and then at 20 km/h for 3 hours. Find the total distance.', 'text', 1, 'Calculate both stage distances.', '{"why":"Both stage distances are added to obtain the complete journey distance.","sol":"Step 1: Stage 1 = 30 × 2 = 60 km\nStep 2: Stage 2 = 20 × 3 = 60 km\nStep 3: Total distance = 60 + 60 = 120 km","steps":["Step 1: Stage 1 = 30 × 2 = 60 km","Step 2: Stage 2 = 20 × 3 = 60 km","Step 3: Total distance = 60 + 60 = 120 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 1),
  (179, 42, 'A bus travels at 80 km/h for 1.5 hours and then at 60 km/h for 2 hours. Find the total distance.', 'text', 1, 'Use d = st for each stage.', '{"why":"The total distance is the sum of both stage distances.","sol":"Step 1: Stage 1 = 80 × 1.5 = 120 km\nStep 2: Stage 2 = 60 × 2 = 120 km\nStep 3: Total distance = 120 + 120 = 240 km","steps":["Step 1: Stage 1 = 80 × 1.5 = 120 km","Step 2: Stage 2 = 60 × 2 = 120 km","Step 3: Total distance = 120 + 120 = 240 km"],"options":[],"conceptId":"math_linear_motion_finding_total_distance_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Distance in a Multi-Stage Journey"}', 2),
  (180, 43, 'A car travels 180 km at 60 km/h and then 100 km at 50 km/h. Find the total time.', 'text', 1, 'Find the time for each stage using t = d/s.', '{"why":"The total travelling time is the sum of the times for both stages.","sol":"Step 1: Stage 1 = 180 / 60 = 3 h\nStep 2: Stage 2 = 100 / 50 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 180 / 60 = 3 h","Step 2: Stage 2 = 100 / 50 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 0),
  (181, 43, 'A cyclist travels 90 km at 30 km/h and then 40 km at 20 km/h. Find the total time.', 'text', 1, 'Calculate each stage time.', '{"why":"Both stage times must be included in the total journey time.","sol":"Step 1: Stage 1 = 90 / 30 = 3 h\nStep 2: Stage 2 = 40 / 20 = 2 h\nStep 3: Total time = 3 + 2 = 5 h","steps":["Step 1: Stage 1 = 90 / 30 = 3 h","Step 2: Stage 2 = 40 / 20 = 2 h","Step 3: Total time = 3 + 2 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 1),
  (182, 43, 'A bus travels 240 km at 80 km/h and then 150 km at 50 km/h. Find the total time.', 'text', 1, 'Use t = d/s for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 240 / 80 = 3 h\nStep 2: Stage 2 = 150 / 50 = 3 h\nStep 3: Total time = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 240 / 80 = 3 h","Step 2: Stage 2 = 150 / 50 = 3 h","Step 3: Total time = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 2),
  (183, 43, 'A car travels 100 km at 50 km/h and then 120 km at 60 km/h. Find the total travel time.', 'text', 1, 'Find each stage time first.', '{"why":"The total journey time is the sum of the times spent on both stages.","sol":"Step 1: Stage 1 time = 100/50 = 2 h\nStep 2: Stage 2 time = 120/60 = 2 h\nStep 3: Total time = 2 + 2 = 4 h","steps":["Step 1: Stage 1 time = 100/50 = 2 h","Step 2: Stage 2 time = 120/60 = 2 h","Step 3: Total time = 2 + 2 = 4 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q4","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 3),
  (184, 43, 'A bus travels 150 km at 50 km/h and then 180 km at 60 km/h. Find the total time.', 'text', 1, 'Calculate t₁ and t₂ separately.', '{"why":"Both stages occur one after another, so their times are added.","sol":"Step 1: Stage 1 = 150/50 = 3 h\nStep 2: Stage 2 = 180/60 = 3 h\nStep 3: Total = 3 + 3 = 6 h","steps":["Step 1: Stage 1 = 150/50 = 3 h","Step 2: Stage 2 = 180/60 = 3 h","Step 3: Total = 3 + 3 = 6 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q5","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 4),
  (185, 43, 'A cyclist travels 60 km at 30 km/h and then 45 km at 15 km/h. Find the total travel time.', 'text', 1, 'Use time = distance ÷ speed for each stage.', '{"why":"The complete journey takes the sum of the two stage times.","sol":"Step 1: Stage 1 = 60/30 = 2 h\nStep 2: Stage 2 = 45/15 = 3 h\nStep 3: Total = 2 + 3 = 5 h","steps":["Step 1: Stage 1 = 60/30 = 2 h","Step 2: Stage 2 = 45/15 = 3 h","Step 3: Total = 2 + 3 = 5 h"],"options":[],"conceptId":"math_linear_motion_finding_total_time_in_a_multi_stage_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q6","subject":"math","chapter":"linear_motion","topic":"Finding Total Time in a Multi-Stage Journey"}', 5),
  (186, 44, 'A car travels 150 km at 50 km/h. Find the time for this stage.', 'text', 1, 'Use t = d/s.', '{"why":"The time for a stage is its distance divided by its speed.","sol":"Step 1: t = 150/50\nStep 2: t = 3 hours","steps":["Step 1: t = 150/50","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 0),
  (187, 44, 'A bus travels 200 km at 80 km/h. Find the time taken.', 'text', 1, 'Divide 200 by 80.', '{"why":"At 80 km/h, 200 km requires 2.5 hours.","sol":"Step 1: t = 200/80\nStep 2: t = 2.5 hours","steps":["Step 1: t = 200/80","Step 2: t = 2.5 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 1),
  (188, 44, 'A cyclist travels 90 km at 30 km/h. Find the time.', 'text', 1, 'Use t = 90/30.', '{"why":"The cyclist covers 30 km every hour.","sol":"Step 1: t = 90/30\nStep 2: t = 3 hours","steps":["Step 1: t = 90/30","Step 2: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_time_for_each_stage","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time for Each Stage"}', 2),
  (189, 45, 'An object is at position +7. Describe its position relative to the origin.', 'text', 1, 'A positive position lies to the right of zero.', '{"why":"Positive positions are measured to the right of zero.","sol":"Step 1: The position is +7.\nStep 2: The positive sign means the object is to the right of the origin.\nStep 3: Its distance from the origin is 7 units.","steps":["Step 1: The position is +7.","Step 2: The positive sign means the object is to the right of the origin.","Step 3: Its distance from the origin is 7 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 0),
  (190, 45, 'An object is at position −5. Describe its position relative to the origin.', 'text', 1, 'A negative position lies to the left of zero.', '{"why":"Negative positions are measured to the left of zero.","sol":"Step 1: The position is −5.\nStep 2: The negative sign means the object is to the left of the origin.\nStep 3: Its distance from the origin is 5 units.","steps":["Step 1: The position is −5.","Step 2: The negative sign means the object is to the left of the origin.","Step 3: Its distance from the origin is 5 units."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 1),
  (191, 45, 'Which position is farther to the right: −4 or +2?', 'text', 1, 'Look at their positions on the number line.', '{"why":"Numbers increase as we move from left to right on a number line.","sol":"Step 1: −4 lies to the left of zero.\nStep 2: +2 lies to the right of zero.\nStep 3: Therefore +2 is farther to the right.","steps":["Step 1: −4 lies to the left of zero.","Step 2: +2 lies to the right of zero.","Step 3: Therefore +2 is farther to the right."],"options":[],"conceptId":"math_linear_motion_representing_position_on_a_number_line","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing Position on a Number Line"}', 2),
  (192, 46, 'An object moves from position +3 to position +10. Find its displacement.', 'text', 1, 'Use final position − initial position.', '{"why":"The object moved 7 units in the positive direction.","sol":"Step 1: Displacement = 10 − 3\nStep 2: Displacement = +7 units","steps":["Step 1: Displacement = 10 − 3","Step 2: Displacement = +7 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 0),
  (193, 46, 'An object moves from position +9 to position +4. Find its displacement.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The negative displacement shows movement in the negative direction.","sol":"Step 1: Displacement = 4 − 9\nStep 2: Displacement = −5 units","steps":["Step 1: Displacement = 4 − 9","Step 2: Displacement = −5 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 1),
  (194, 46, 'An object moves from position −6 to position +3. Find its displacement.', 'text', 1, 'Be careful with the negative initial position.', '{"why":"Moving from −6 to +3 requires a positive change of 9 units.","sol":"Step 1: Displacement = 3 − (−6)\nStep 2: Displacement = 3 + 6\nStep 3: Displacement = +9 units","steps":["Step 1: Displacement = 3 − (−6)","Step 2: Displacement = 3 + 6","Step 3: Displacement = +9 units"],"options":[],"conceptId":"math_linear_motion_finding_displacement_from_two_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Displacement from Two Positions"}', 2),
  (195, 47, 'An object moves from position +1 to +8. Find the distance travelled.', 'text', 1, 'Find the change in position and take its absolute value.', '{"why":"The object covers 7 units between the two positions.","sol":"Step 1: Change = 8 − 1 = 7\nStep 2: Distance = |7| = 7 units","steps":["Step 1: Change = 8 − 1 = 7","Step 2: Distance = |7| = 7 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 0),
  (196, 47, 'An object moves from +10 to +4. Find the distance travelled.', 'text', 1, 'Distance cannot be negative.', '{"why":"The negative sign describes direction, but distance measures only the amount travelled.","sol":"Step 1: Change = 4 − 10 = −6\nStep 2: Distance = |−6|\nStep 3: Distance = 6 units","steps":["Step 1: Change = 4 − 10 = −6","Step 2: Distance = |−6|","Step 3: Distance = 6 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 1),
  (197, 47, 'An object moves from −3 to +7. Find the distance travelled.', 'text', 1, 'Subtract the initial position from the final position.', '{"why":"The object moves through 10 units between −3 and +7.","sol":"Step 1: Change = 7 − (−3)\nStep 2: Change = 10\nStep 3: Distance = 10 units","steps":["Step 1: Change = 7 − (−3)","Step 2: Change = 10","Step 3: Distance = 10 units"],"options":[],"conceptId":"math_linear_motion_finding_distance_travelled_from_positions","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance Travelled from Positions"}', 2),
  (198, 48, 'An object starts at position 8 m and moves at 2 m/s. Write its position equation.', 'text', 1, 'Use x = x₀ + st.', '{"why":"The object begins at 8 m and gains 2 m of position every second.","sol":"Step 1: x₀ = 8\nStep 2: s = 2\nStep 3: x = 8 + 2t","steps":["Step 1: x₀ = 8","Step 2: s = 2","Step 3: x = 8 + 2t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 0),
  (199, 48, 'An object starts at position 15 m and moves at 5 m/s. Write its position equation.', 'text', 1, 'Substitute the initial position and speed.', '{"why":"The initial position is 15 m and the position increases by 5 m each second.","sol":"Step 1: x₀ = 15\nStep 2: s = 5\nStep 3: x = 15 + 5t","steps":["Step 1: x₀ = 15","Step 2: s = 5","Step 3: x = 15 + 5t"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 1),
  (200, 48, 'An object starts at 10 m and moves at 6 m/s. Find its position after 4 seconds.', 'text', 1, 'First write x = 10 + 6t, then substitute t = 4.', '{"why":"In 4 seconds the object travels 24 m from its starting position of 10 m.","sol":"Step 1: x = 10 + 6t\nStep 2: x = 10 + 6(4)\nStep 3: x = 10 + 24\nStep 4: x = 34 m","steps":["Step 1: x = 10 + 6t","Step 2: x = 10 + 6(4)","Step 3: x = 10 + 24","Step 4: x = 34 m"],"options":[],"conceptId":"math_linear_motion_writing_a_position_equation_for_constant_speed","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Writing a Position Equation for Constant Speed"}', 2),
  (201, 49, 'Given x = 4 + 5t, find x when t = 3.', 'text', 1, 'Replace t with 3.', '{"why":"Substituting t = 3 gives the position at 3 units of time.","sol":"Step 1: x = 4 + 5(3)\nStep 2: x = 4 + 15\nStep 3: x = 19","steps":["Step 1: x = 4 + 5(3)","Step 2: x = 4 + 15","Step 3: x = 19"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 0),
  (202, 49, 'Given x = 8 + 2t, find x when t = 6.', 'text', 1, 'Substitute t = 6.', '{"why":"The equation gives the position directly once the time is known.","sol":"Step 1: x = 8 + 2(6)\nStep 2: x = 8 + 12\nStep 3: x = 20","steps":["Step 1: x = 8 + 2(6)","Step 2: x = 8 + 12","Step 3: x = 20"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 1),
  (203, 49, 'Given x = 15 + 7t, find x when t = 2.', 'text', 1, 'Replace t by 2.', '{"why":"At t = 2, the position is obtained by substituting 2 into the equation.","sol":"Step 1: x = 15 + 7(2)\nStep 2: x = 15 + 14\nStep 3: x = 29","steps":["Step 1: x = 15 + 7(2)","Step 2: x = 15 + 14","Step 3: x = 29"],"options":[],"conceptId":"math_linear_motion_finding_position_from_a_linear_motion_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Position from a Linear Motion Equation"}', 2),
  (204, 50, 'Given x = 4 + 2t, find t when x = 14.', 'text', 1, 'Substitute x = 14 and solve the linear equation.', '{"why":"Solving the position equation gives the time at which the object reaches position 14.","sol":"Step 1: 14 = 4 + 2t\nStep 2: 10 = 2t\nStep 3: t = 5","steps":["Step 1: 14 = 4 + 2t","Step 2: 10 = 2t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 0),
  (205, 50, 'Given x = 7 + 3t, find t when x = 22.', 'text', 1, 'Subtract 7 first.', '{"why":"The unknown time is found by solving the linear equation.","sol":"Step 1: 22 = 7 + 3t\nStep 2: 15 = 3t\nStep 3: t = 5","steps":["Step 1: 22 = 7 + 3t","Step 2: 15 = 3t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 1),
  (206, 50, 'Given x = 12 + 4t, find t when x = 32.', 'text', 1, 'Subtract 12, then divide by 4.', '{"why":"The equation tells us the position at every time, so we can solve it backwards for time.","sol":"Step 1: 32 = 12 + 4t\nStep 2: 20 = 4t\nStep 3: t = 5","steps":["Step 1: 32 = 12 + 4t","Step 2: 20 = 4t","Step 3: t = 5"],"options":[],"conceptId":"math_linear_motion_finding_time_from_a_position_equation","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Time from a Position Equation"}', 2),
  (207, 51, 'A person walks 5 km away from home and 5 km back. Find the total distance.', 'text', 1, 'Add the outward and return distances.', '{"why":"Both the outward and return parts contribute to total distance.","sol":"Step 1: Total distance = 5 + 5\nStep 2: Total distance = 10 km","steps":["Step 1: Total distance = 5 + 5","Step 2: Total distance = 10 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 0),
  (208, 51, 'A cyclist travels 8 km from A to B and then 3 km back towards A. Find the total distance travelled.', 'text', 1, 'Add both parts.', '{"why":"Distance counts every part of the path travelled.","sol":"Step 1: Outward distance = 8 km\nStep 2: Return distance = 3 km\nStep 3: Total distance = 8 + 3 = 11 km","steps":["Step 1: Outward distance = 8 km","Step 2: Return distance = 3 km","Step 3: Total distance = 8 + 3 = 11 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 1),
  (209, 51, 'A car travels 20 km east and then 12 km west. Find the total distance travelled.', 'text', 1, 'Direction does not make distance negative.', '{"why":"Total distance is the complete length of the path.","sol":"Step 1: First distance = 20 km\nStep 2: Second distance = 12 km\nStep 3: Total distance = 20 + 12\nStep 4: Total distance = 32 km","steps":["Step 1: First distance = 20 km","Step 2: Second distance = 12 km","Step 3: Total distance = 20 + 12","Step 4: Total distance = 32 km"],"options":[],"conceptId":"math_linear_motion_distance_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Distance in a Return Journey"}', 2),
  (210, 52, 'A person walks 7 km east and then 7 km west. Find the displacement.', 'text', 1, 'The person finishes at the starting point.', '{"why":"The final position is the same as the initial position.","sol":"Step 1: Initial position = 0\nStep 2: Final position = 0\nStep 3: Displacement = 0 − 0 = 0 km","steps":["Step 1: Initial position = 0","Step 2: Final position = 0","Step 3: Displacement = 0 − 0 = 0 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 0),
  (211, 52, 'A cyclist travels 12 km east and then 5 km west. Find the displacement.', 'text', 1, 'Take east as positive.', '{"why":"The cyclist finishes 7 km east of the starting point.","sol":"Step 1: Final position = 12 − 5\nStep 2: Final position = +7 km\nStep 3: Displacement = +7 km","steps":["Step 1: Final position = 12 − 5","Step 2: Final position = +7 km","Step 3: Displacement = +7 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 1),
  (212, 52, 'A car travels 15 km west and then 10 km east. Find its displacement.', 'text', 1, 'Take east as positive, so west is negative.', '{"why":"The car finishes 5 km west of its starting point.","sol":"Step 1: First movement = −15 km\nStep 2: Second movement = +10 km\nStep 3: Final position = −15 + 10 = −5 km\nStep 4: Displacement = −5 km","steps":["Step 1: First movement = −15 km","Step 2: Second movement = +10 km","Step 3: Final position = −15 + 10 = −5 km","Step 4: Displacement = −5 km"],"options":[],"conceptId":"math_linear_motion_displacement_in_a_return_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Displacement in a Return Journey"}', 2),
  (213, 53, 'An object starts at 0 m, moves 10 m east and then 4 m west. Find its final position.', 'text', 1, 'Take east as positive.', '{"why":"The object finishes 6 m east of its starting point.","sol":"Step 1: Final position = 0 + 10 − 4\nStep 2: Final position = +6 m","steps":["Step 1: Final position = 0 + 10 − 4","Step 2: Final position = +6 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 0),
  (214, 53, 'An object starts at 8 m, moves 5 m west and then 2 m east. Find its final position.', 'text', 1, 'West is negative and east is positive.', '{"why":"The two movements change the starting position of 8 m.","sol":"Step 1: Final position = 8 − 5 + 2\nStep 2: Final position = 5 m","steps":["Step 1: Final position = 8 − 5 + 2","Step 2: Final position = 5 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 1),
  (215, 53, 'An object starts at −4 m, moves 9 m east and then 3 m west. Find its final position.', 'text', 1, 'Add +9 and −3 to the initial position.', '{"why":"The signed movements take the object from −4 m to +2 m.","sol":"Step 1: Final position = −4 + 9 − 3\nStep 2: Final position = +2 m","steps":["Step 1: Final position = −4 + 9 − 3","Step 2: Final position = +2 m"],"options":[],"conceptId":"math_linear_motion_finding_the_final_position_after_several_movements","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding the Final Position After Several Movements"}', 2),
  (216, 54, 'A bus starts at 8:00 a.m. and a car starts at 10:00 a.m. If t is the number of hours after 8:00 a.m., express the car''s travel time.', 'text', 1, 'The car starts 2 hours after the reference time.', '{"why":"The car has been travelling for two fewer hours than the elapsed time measured from 8:00 a.m.","sol":"Step 1: The delay is 2 hours.\nStep 2: Elapsed time = t.\nStep 3: Car travel time = t − 2.","steps":["Step 1: The delay is 2 hours.","Step 2: Elapsed time = t.","Step 3: Car travel time = t − 2."],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 0),
  (217, 54, 'A cyclist starts at 7:00 a.m. and another starts at 8:00 a.m. If t is measured from 7:00 a.m., express the second cyclist''s travel time.', 'text', 1, 'The second cyclist starts 1 hour later.', '{"why":"The second cyclist loses one hour of travel time because of the delayed start.","sol":"Step 1: Delay = 1 hour\nStep 2: Elapsed time = t\nStep 3: Travel time = t − 1","steps":["Step 1: Delay = 1 hour","Step 2: Elapsed time = t","Step 3: Travel time = t − 1"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 1),
  (218, 54, 'A vehicle starts at 6:00 a.m. and another starts at 6:30 a.m. If t is measured from 6:00 a.m., express the second vehicle''s travel time.', 'text', 1, 'Convert 30 minutes to hours.', '{"why":"The second vehicle begins half an hour after the first.","sol":"Step 1: 30 minutes = 0.5 hours\nStep 2: Delay = 0.5 hours\nStep 3: Travel time = t − 0.5","steps":["Step 1: 30 minutes = 0.5 hours","Step 2: Delay = 0.5 hours","Step 3: Travel time = t − 0.5"],"options":[],"conceptId":"math_linear_motion_representing_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Representing a Delayed Start"}', 2),
  (219, 55, 'A car starts 2 hours after a bus and travels at 70 km/h. If t is measured from the bus''s starting time, write the car''s distance equation.', 'text', 1, 'The car travels for t − 2 hours.', '{"why":"The car''s actual travel time is t − 2 because it starts two hours late.","sol":"Step 1: Car travel time = t − 2\nStep 2: Distance = speed × time\nStep 3: Distance = 70(t − 2)","steps":["Step 1: Car travel time = t − 2","Step 2: Distance = speed × time","Step 3: Distance = 70(t − 2)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 0),
  (220, 55, 'A cyclist starts 1 hour after another cyclist and travels at 30 km/h. Write its distance equation using t as time from the first cyclist''s start.', 'text', 1, 'Subtract the 1-hour delay from t.', '{"why":"The cyclist travels for one hour less than the elapsed time t.","sol":"Step 1: Travel time = t − 1\nStep 2: Distance = 30(t − 1)","steps":["Step 1: Travel time = t − 1","Step 2: Distance = 30(t − 1)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 1),
  (221, 55, 'A bus starts 0.5 hours after a car and travels at 60 km/h. Write its distance equation.', 'text', 1, 'The delay is half an hour.', '{"why":"The bus has only travelled for t − 0.5 hours.","sol":"Step 1: Travel time = t − 0.5\nStep 2: Distance = 60(t − 0.5)","steps":["Step 1: Travel time = t − 0.5","Step 2: Distance = 60(t − 0.5)"],"options":[],"conceptId":"math_linear_motion_finding_distance_after_a_delayed_start","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Distance After a Delayed Start"}', 2),
  (222, 56, 'A bus leaves at 8:00 a.m. at 40 km/h. A car leaves at 10:00 a.m. at 60 km/h. How many hours after 8:00 a.m. does the car catch the bus?', 'text', 1, 'Set 40t equal to 60(t − 2).', '{"why":"At the catching point both vehicles have travelled the same distance from the starting point.","sol":"Step 1: Bus distance = 40t\nStep 2: Car distance = 60(t − 2)\nStep 3: 40t = 60(t − 2)\nStep 4: 40t = 60t − 120\nStep 5: 120 = 20t\nStep 6: t = 6 hours","steps":["Step 1: Bus distance = 40t","Step 2: Car distance = 60(t − 2)","Step 3: 40t = 60(t − 2)","Step 4: 40t = 60t − 120","Step 5: 120 = 20t","Step 6: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 0),
  (223, 56, 'A cyclist leaves at 7:00 a.m. at 20 km/h. Another leaves at 9:00 a.m. at 30 km/h. Find the catching time measured from 7:00 a.m.', 'text', 1, 'Use 20t = 30(t − 2).', '{"why":"The second cyclist makes up the initial two-hour disadvantage because they travel faster.","sol":"Step 1: 20t = 30(t − 2)\nStep 2: 20t = 30t − 60\nStep 3: 60 = 10t\nStep 4: t = 6 hours","steps":["Step 1: 20t = 30(t − 2)","Step 2: 20t = 30t − 60","Step 3: 60 = 10t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 1),
  (224, 56, 'A truck leaves at 6:00 a.m. at 50 km/h. A car leaves at 8:00 a.m. at 75 km/h. Find when the car catches the truck, measured from 6:00 a.m.', 'text', 1, 'Set 50t = 75(t − 2).', '{"why":"Equal distances indicate the exact moment the car catches the truck.","sol":"Step 1: 50t = 75(t − 2)\nStep 2: 50t = 75t − 150\nStep 3: 150 = 25t\nStep 4: t = 6 hours","steps":["Step 1: 50t = 75(t − 2)","Step 2: 50t = 75t − 150","Step 3: 150 = 25t","Step 4: t = 6 hours"],"options":[],"conceptId":"math_linear_motion_finding_when_a_delayed_object_catches_up","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding When a Delayed Object Catches Up"}', 2),
  (225, 57, 'A car travels at 80 km/h for t hours and covers 240 km. Find t.', 'text', 1, 'Use 240 = 80t.', '{"why":"The unknown time is obtained by dividing distance by speed.","sol":"Step 1: 240 = 80t\nStep 2: t = 240/80\nStep 3: t = 3 hours","steps":["Step 1: 240 = 80t","Step 2: t = 240/80","Step 3: t = 3 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 0),
  (226, 57, 'A cyclist travels at x km/h for 5 hours and covers 125 km. Find x.', 'text', 1, 'Use 125 = 5x.', '{"why":"The unknown speed is distance divided by time.","sol":"Step 1: 125 = 5x\nStep 2: x = 125/5\nStep 3: x = 25 km/h","steps":["Step 1: 125 = 5x","Step 2: x = 125/5","Step 3: x = 25 km/h"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 1),
  (227, 57, 'A bus travels at 60 km/h for t hours and covers 300 km. Find t.', 'text', 1, 'Form the equation 300 = 60t.', '{"why":"The equation follows directly from distance = speed × time.","sol":"Step 1: 300 = 60t\nStep 2: t = 300/60\nStep 3: t = 5 hours","steps":["Step 1: 300 = 60t","Step 2: t = 300/60","Step 3: t = 5 hours"],"options":[],"conceptId":"math_linear_motion_finding_an_unknown_distance_algebraically","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding an Unknown Distance Algebraically"}', 2),
  (228, 58, 'A car covers 180 km at 60 km/h while a bus covers the same distance at 45 km/h. Find the difference in their travel times.', 'text', 1, 'Find each time using t = d/s.', '{"why":"The slower bus requires one extra hour to cover the same distance.","sol":"Step 1: Car time = 180/60 = 3 h\nStep 2: Bus time = 180/45 = 4 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: Car time = 180/60 = 3 h","Step 2: Bus time = 180/45 = 4 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 0),
  (229, 58, 'A cyclist covers 120 km at 30 km/h while another covers it at 40 km/h. Find the difference in time.', 'text', 1, 'Calculate both times.', '{"why":"The lower speed results in a longer travel time.","sol":"Step 1: First time = 120/30 = 4 h\nStep 2: Second time = 120/40 = 3 h\nStep 3: Difference = 4 − 3 = 1 h","steps":["Step 1: First time = 120/30 = 4 h","Step 2: Second time = 120/40 = 3 h","Step 3: Difference = 4 − 3 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 1),
  (230, 58, 'A train covers 300 km at 75 km/h while another covers the same distance at 60 km/h. Find the difference in travel time.', 'text', 1, 'Use distance divided by speed for each train.', '{"why":"The second train takes one additional hour to cover the same distance.","sol":"Step 1: First time = 300/75 = 4 h\nStep 2: Second time = 300/60 = 5 h\nStep 3: Difference = 5 − 4 = 1 h","steps":["Step 1: First time = 300/75 = 4 h","Step 2: Second time = 300/60 = 5 h","Step 3: Difference = 5 − 4 = 1 h"],"options":[],"conceptId":"math_linear_motion_using_algebra_to_compare_two_travel_times","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Algebra to Compare Two Travel Times"}', 2),
  (231, 59, 'A 150 km journey takes 3 hours for one car and 5 hours for another. Find both speeds.', 'text', 1, 'Use speed = distance ÷ time for each car.', '{"why":"Each speed is found by dividing the common distance by that vehicle''s travel time.","sol":"Step 1: First speed = 150/3 = 50 km/h\nStep 2: Second speed = 150/5 = 30 km/h","steps":["Step 1: First speed = 150/3 = 50 km/h","Step 2: Second speed = 150/5 = 30 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 0),
  (232, 59, 'A 200 km journey takes 4 hours for one vehicle and 5 hours for another. Find both speeds.', 'text', 1, 'Calculate each speed separately.', '{"why":"The same distance divided by different times gives different speeds.","sol":"Step 1: First speed = 200/4 = 50 km/h\nStep 2: Second speed = 200/5 = 40 km/h","steps":["Step 1: First speed = 200/4 = 50 km/h","Step 2: Second speed = 200/5 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 1),
  (233, 59, 'A 360 km journey takes 6 hours for one vehicle and 9 hours for another. Find both speeds.', 'text', 1, 'Use s = d/t.', '{"why":"Speed is distance divided by the time taken.","sol":"Step 1: First speed = 360/6 = 60 km/h\nStep 2: Second speed = 360/9 = 40 km/h","steps":["Step 1: First speed = 360/6 = 60 km/h","Step 2: Second speed = 360/9 = 40 km/h"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_time_difference","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Time Difference"}', 2),
  (234, 60, 'A car travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Use d = st.', '{"why":"Distance is found by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 0),
  (235, 60, 'A runner moves at 8 m/s for 25 seconds. Find the distance travelled.', 'text', 1, 'Multiply speed by time.', '{"why":"The runner covers 8 metres every second for 25 seconds.","sol":"Step 1: d = st\nStep 2: d = 8 × 25\nStep 3: d = 200 m","steps":["Step 1: d = st","Step 2: d = 8 × 25","Step 3: d = 200 m"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 1),
  (236, 60, 'A vehicle travels 360 km at 90 km/h. Find the time taken.', 'text', 1, 'Rearrange d = st to make t the subject.', '{"why":"Time is distance divided by speed.","sol":"Step 1: 360 = 90t\nStep 2: t = 360 ÷ 90\nStep 3: t = 4 hours","steps":["Step 1: 360 = 90t","Step 2: t = 360 ÷ 90","Step 3: t = 4 hours"],"options":[],"conceptId":"math_linear_motion_using_distance_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Distance-Time Relationships"}', 2),
  (237, 61, 'A car travels 300 km in 5 hours. Find its speed.', 'text', 1, 'Speed = distance ÷ time.', '{"why":"Speed measures how much distance is covered in each unit of time.","sol":"Step 1: s = d/t\nStep 2: s = 300 ÷ 5\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 300 ÷ 5","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 0),
  (238, 61, 'A cyclist covers 180 m in 30 seconds. Find the speed.', 'text', 1, 'Divide distance by time.', '{"why":"The cyclist covers 6 metres during each second.","sol":"Step 1: s = d/t\nStep 2: s = 180 ÷ 30\nStep 3: s = 6 m/s","steps":["Step 1: s = d/t","Step 2: s = 180 ÷ 30","Step 3: s = 6 m/s"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 1),
  (239, 61, 'A train travels 450 km in 6 hours. Find its average speed.', 'text', 1, 'Average speed = total distance ÷ total time.', '{"why":"Average speed uses the total distance and the total time.","sol":"Step 1: Average speed = 450 ÷ 6\nStep 2: Average speed = 75 km/h","steps":["Step 1: Average speed = 450 ÷ 6","Step 2: Average speed = 75 km/h"],"options":[],"conceptId":"math_linear_motion_using_speed_time_relationships","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Using Speed-Time Relationships"}', 2),
  (240, 62, 'A distance-time graph passes through (2 s, 8 m) and (6 s, 28 m). Find the speed.', 'text', 1, 'Find change in distance and divide by change in time.', '{"why":"The gradient of a distance-time graph represents speed.","sol":"Step 1: Change in distance = 28 − 8 = 20 m\nStep 2: Change in time = 6 − 2 = 4 s\nStep 3: Speed = 20 ÷ 4\nStep 4: Speed = 5 m/s","steps":["Step 1: Change in distance = 28 − 8 = 20 m","Step 2: Change in time = 6 − 2 = 4 s","Step 3: Speed = 20 ÷ 4","Step 4: Speed = 5 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 0),
  (241, 62, 'A graph passes through (0 s, 0 m) and (10 s, 60 m). Find the speed.', 'text', 1, 'Use gradient = change in distance ÷ change in time.', '{"why":"The graph''s gradient gives the speed.","sol":"Step 1: Change in distance = 60 m\nStep 2: Change in time = 10 s\nStep 3: Speed = 60 ÷ 10\nStep 4: Speed = 6 m/s","steps":["Step 1: Change in distance = 60 m","Step 2: Change in time = 10 s","Step 3: Speed = 60 ÷ 10","Step 4: Speed = 6 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 1),
  (242, 62, 'A distance-time graph passes through (4 s, 12 m) and (9 s, 32 m). Find the speed.', 'text', 1, 'Subtract the coordinates first.', '{"why":"Speed is the gradient of the distance-time graph.","sol":"Step 1: Change in distance = 32 − 12 = 20 m\nStep 2: Change in time = 9 − 4 = 5 s\nStep 3: Speed = 20 ÷ 5\nStep 4: Speed = 4 m/s","steps":["Step 1: Change in distance = 32 − 12 = 20 m","Step 2: Change in time = 9 − 4 = 5 s","Step 3: Speed = 20 ÷ 5","Step 4: Speed = 4 m/s"],"options":[],"conceptId":"math_linear_motion_finding_speed_from_a_distance_time_graph","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Finding Speed from a Distance-Time Graph"}', 2),
  (243, 63, 'A car travels 80 km in 2 hours and then 120 km in 3 hours. Find its average speed.', 'text', 1, 'Add the distances and add the times before dividing.', '{"why":"Average speed is based on total distance divided by total time.","sol":"Step 1: Total distance = 80 + 120 = 200 km\nStep 2: Total time = 2 + 3 = 5 hours\nStep 3: Average speed = 200 ÷ 5\nStep 4: Average speed = 40 km/h","steps":["Step 1: Total distance = 80 + 120 = 200 km","Step 2: Total time = 2 + 3 = 5 hours","Step 3: Average speed = 200 ÷ 5","Step 4: Average speed = 40 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 0),
  (244, 63, 'A cyclist travels 40 km in 2 hours and 30 km in 1 hour. Find the average speed.', 'text', 1, 'Do not average 20 km/h and 30 km/h directly.', '{"why":"The two parts take different amounts of time, so the total distance and total time must be used.","sol":"Step 1: Total distance = 40 + 30 = 70 km\nStep 2: Total time = 2 + 1 = 3 hours\nStep 3: Average speed = 70 ÷ 3\nStep 4: Average speed ≈ 23.33 km/h","steps":["Step 1: Total distance = 40 + 30 = 70 km","Step 2: Total time = 2 + 1 = 3 hours","Step 3: Average speed = 70 ÷ 3","Step 4: Average speed ≈ 23.33 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 1),
  (245, 63, 'A vehicle travels 150 km in 3 hours and 100 km in 2 hours. Find the average speed.', 'text', 1, 'Find total distance and total time.', '{"why":"Average speed measures the entire journey rather than treating each section separately.","sol":"Step 1: Total distance = 150 + 100 = 250 km\nStep 2: Total time = 3 + 2 = 5 hours\nStep 3: Average speed = 250 ÷ 5\nStep 4: Average speed = 50 km/h","steps":["Step 1: Total distance = 150 + 100 = 250 km","Step 2: Total time = 3 + 2 = 5 hours","Step 3: Average speed = 250 ÷ 5","Step 4: Average speed = 50 km/h"],"options":[],"conceptId":"math_linear_motion_average_speed_for_different_parts_of_a_journey","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Average Speed for Different Parts of a Journey"}', 2),
  (246, 64, 'A vehicle travels at 70 km/h for 4 hours. Find the distance travelled.', 'text', 1, 'Identify speed and time, then use d = st.', '{"why":"Distance is obtained by multiplying speed by time.","sol":"Step 1: d = st\nStep 2: d = 70 × 4\nStep 3: d = 280 km","steps":["Step 1: d = st","Step 2: d = 70 × 4","Step 3: d = 280 km"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q1","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 0),
  (247, 64, 'A bus travels 360 km in 6 hours. Find its average speed.', 'text', 1, 'Use speed = distance ÷ time.', '{"why":"Average speed is total distance divided by total time.","sol":"Step 1: s = d/t\nStep 2: s = 360 ÷ 6\nStep 3: s = 60 km/h","steps":["Step 1: s = d/t","Step 2: s = 360 ÷ 6","Step 3: s = 60 km/h"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q2","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 1),
  (248, 64, 'A car travels 120 km at 60 km/h and then 180 km at 90 km/h. Find the total time.', 'text', 1, 'Find the time for each section separately, then add them.', '{"why":"The journey has two stages, so their individual times must be added.","sol":"Step 1: First section: t = 120 ÷ 60 = 2 hours\nStep 2: Second section: t = 180 ÷ 90 = 2 hours\nStep 3: Total time = 2 + 2\nStep 4: Total time = 4 hours","steps":["Step 1: First section: t = 120 ÷ 60 = 2 hours","Step 2: Second section: t = 180 ÷ 90 = 2 hours","Step 3: Total time = 2 + 2","Step 4: Total time = 4 hours"],"options":[],"conceptId":"math_linear_motion_solving_a_complete_motion_problem","skillId":"math_linear_motion","subskillId":"math_linear_motion_q3","subject":"math","chapter":"linear_motion","topic":"Solving a Complete Motion Problem"}', 2),
  (249, 65, 'Evaluate 3x + 5 when x = 2', 'text', 1, 'substitute first', '{"why":"Substitution must be done before simplifying","sol":"Step 1: Replace x with 2 → 3(2) + 5\nStep 2: Multiply → 6 + 5\nStep 3: = 11","steps":["Step 1: Replace x with 2 → 3(2) + 5","Step 2: Multiply → 6 + 5","Step 3: = 11"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 0),
  (250, 65, 'Simplify 2x + 3x', 'text', 1, 'like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 2x + 3x\nStep 2: (2 + 3)x\nStep 3: = 5x","steps":["Step 1: 2x + 3x","Step 2: (2 + 3)x","Step 3: = 5x"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (251, 65, 'Identify: 4y + 7', 'text', 1, 'expression parts', '{"why":"It has variables and constants but no equation","sol":"Step 1: Contains variable y\nStep 2: Contains constant 7\nStep 3: No equals sign","steps":["Step 1: Contains variable y","Step 2: Contains constant 7","Step 3: No equals sign"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 2),
  (252, 65, 'Translate: ‘5 less than a number x’', 'text', 1, 'subtract 5', '{"why":"Word phrases convert into algebraic expressions","sol":"Step 1: number x → x\nStep 2: 5 less → −5\nStep 3: x − 5","steps":["Step 1: number x → x","Step 2: 5 less → −5","Step 3: x − 5"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 3),
  (253, 66, 'Simplify 3x + 4x + 2', 'text', 1, 'group like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 3x + 4x = 7x\nStep 2: +2 remains unchanged\nStep 3: 7x + 2","steps":["Step 1: 3x + 4x = 7x","Step 2: +2 remains unchanged","Step 3: 7x + 2"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 0),
  (254, 66, 'Simplify 6a - 2a', 'text', 1, 'subtract coefficients', '{"why":"Same variable means combine coefficients","sol":"Step 1: 6a − 2a\nStep 2: (6 − 2)a = 4a","steps":["Step 1: 6a − 2a","Step 2: (6 − 2)a = 4a"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 1),
  (255, 66, 'Simplify 2x + 3y + 5x', 'text', 1, 'group x terms', '{"why":"Like terms grouped together","sol":"Step 1: (2x + 5x) + 3y\nStep 2: 7x + 3y","steps":["Step 1: (2x + 5x) + 3y","Step 2: 7x + 3y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 2),
  (256, 66, 'Simplify x + 2x + y + 3y', 'text', 1, 'group both variables', '{"why":"Combine each variable separately","sol":"Step 1: (x + 2x) + (y + 3y)\nStep 2: 3x + 4y","steps":["Step 1: (x + 2x) + (y + 3y)","Step 2: 3x + 4y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 3),
  (257, 67, 'Solve x + 5 = 12', 'text', 1, 'inverse operation', '{"why":"Maintain balance by doing same operation on both sides","sol":"Step 1: Subtract 5 from both sides\nStep 2: x = 12 − 5\nStep 3: x = 7","steps":["Step 1: Subtract 5 from both sides","Step 2: x = 12 − 5","Step 3: x = 7"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Linear equations"}', 0),
  (258, 67, 'Solve 2x = 10', 'text', 1, 'divide both sides', '{"why":"Inverse of multiplication is division","sol":"Step 1: Divide both sides by 2\nStep 2: x = 5","steps":["Step 1: Divide both sides by 2","Step 2: x = 5"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Linear equations"}', 1),
  (259, 67, 'Solve 3x + 2 = 11', 'text', 1, 'remove constant first', '{"why":"Isolate variable step by step","sol":"Step 1: 3x = 11 − 2\nStep 2: 3x = 9\nStep 3: x = 3","steps":["Step 1: 3x = 11 − 2","Step 2: 3x = 9","Step 3: x = 3"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Linear equations"}', 2),
  (260, 67, 'Solve 4x − 6 = 10', 'text', 1, 'add 6 first', '{"why":"Move constants using inverse operations","sol":"Step 1: 4x = 10 + 6\nStep 2: 4x = 16\nStep 3: x = 4","steps":["Step 1: 4x = 10 + 6","Step 2: 4x = 16","Step 3: x = 4"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Linear equations"}', 3),
  (261, 68, 'If x = 3, find x + 4', 'text', 1, 'replace x first', '{"why":"Substitution replaces variables with numbers","sol":"Step 1: Substitute x = 3\nStep 2: 3 + 4\nStep 3: = 7","steps":["Step 1: Substitute x = 3","Step 2: 3 + 4","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Substitution"}', 0),
  (262, 68, 'If x = 2, find 2x + 1', 'text', 1, 'multiply first', '{"why":"Follow multiplication before addition","sol":"Step 1: Substitute → 2(2) + 1\nStep 2: Multiply → 4 + 1\nStep 3: = 5","steps":["Step 1: Substitute → 2(2) + 1","Step 2: Multiply → 4 + 1","Step 3: = 5"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Substitution"}', 1),
  (263, 68, 'If x = 4, y = 3, find x + y', 'text', 1, 'replace both variables', '{"why":"Both variables must be replaced","sol":"Step 1: Substitute → 4 + 3\nStep 2: Simplify\nStep 3: = 7","steps":["Step 1: Substitute → 4 + 3","Step 2: Simplify","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Substitution"}', 2),
  (264, 68, 'If x = 5, find 3x − 2', 'text', 1, 'multiply then subtract', '{"why":"Substitution followed by order of operations","sol":"Step 1: 3 × 5 = 15\nStep 2: 15 − 2\nStep 3: = 13","steps":["Step 1: 3 × 5 = 15","Step 2: 15 − 2","Step 3: = 13"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Substitution"}', 3),
  (265, 69, 'Expand 2(x + 3)', 'text', 1, 'multiply each term', '{"why":"Distributive law multiplies each term inside bracket","sol":"Step 1: 2 × x = 2x\nStep 2: 2 × 3 = 6\nStep 3: Combine → 2x + 6","steps":["Step 1: 2 × x = 2x","Step 2: 2 × 3 = 6","Step 3: Combine → 2x + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 0),
  (266, 69, 'Expand 3(a + 2)', 'text', 1, 'distribute 3', '{"why":"Each term inside bracket must be multiplied","sol":"Step 1: 3 × a = 3a\nStep 2: 3 × 2 = 6\nStep 3: 3a + 6","steps":["Step 1: 3 × a = 3a","Step 2: 3 × 2 = 6","Step 3: 3a + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 1),
  (267, 69, 'Expand 4(x + 1)', 'text', 1, 'multiply each term', '{"why":"Distributive property applies to all terms","sol":"Step 1: 4 × x = 4x\nStep 2: 4 × 1 = 4\nStep 3: 4x + 4","steps":["Step 1: 4 × x = 4x","Step 2: 4 × 1 = 4","Step 3: 4x + 4"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 2),
  (268, 69, 'What is the distributive law?', 'text', 1, 'a(b + c)', '{"why":"It ensures correct expansion of brackets","sol":"Step 1: Multiply outside term\nStep 2: Multiply each inside term\nStep 3: Combine results","steps":["Step 1: Multiply outside term","Step 2: Multiply each inside term","Step 3: Combine results"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 3),
  (269, 70, 'Classify an angle of 24°.', 'text', 1, 'Compare it with 90°.', '{"why":"An acute angle is greater than 0° but less than 90°.","sol":"Step 1: 24° is less than 90°.\nStep 2: An angle between 0° and 90° is acute.","steps":["Step 1: 24° is less than 90°.","Step 2: An angle between 0° and 90° is acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 0),
  (270, 70, 'Classify an angle of 112°.', 'text', 1, 'Is it between 90° and 180°?', '{"why":"An obtuse angle is larger than a right angle but smaller than a straight angle.","sol":"Step 1: 90° < 112° < 180°.\nStep 2: An angle between 90° and 180° is obtuse.","steps":["Step 1: 90° < 112° < 180°.","Step 2: An angle between 90° and 180° is obtuse."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 1),
  (271, 70, 'An angle measures exactly 90°. What type is it?', 'text', 1, 'Think of a quarter-turn.', '{"why":"A right angle measures exactly 90°.","sol":"Step 1: The angle measures exactly 90°.\nStep 2: Therefore, it is a right angle.","steps":["Step 1: The angle measures exactly 90°.","Step 2: Therefore, it is a right angle."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 2),
  (272, 70, 'Can an angle of 180° be acute?', 'text', 1, 'An acute angle must be smaller than 90°.', '{"why":"Angle classification depends on the measured size.","sol":"Step 1: An acute angle is less than 90°.\nStep 2: 180° is a straight angle.\nStep 3: Therefore, it cannot be acute.","steps":["Step 1: An acute angle is less than 90°.","Step 2: 180° is a straight angle.","Step 3: Therefore, it cannot be acute."],"options":[],"conceptId":"math_geometry_classifying_angles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Classifying Angles"}', 3),
  (273, 71, 'Two adjacent angles on a straight line are 127° and x°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Angles forming a straight line total 180°.","sol":"Step 1: 127° + x = 180°\nStep 2: x = 180° - 127°\nStep 3: x = 53°.","steps":["Step 1: 127° + x = 180°","Step 2: x = 180° - 127°","Step 3: x = 53°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 0),
  (274, 71, 'Angles 2x° and 70° lie on a straight line. Find x.', 'text', 1, 'Write 2x + 70 = 180.', '{"why":"Use the straight-line angle sum to form an equation.","sol":"Step 1: 2x + 70 = 180\nStep 2: 2x = 110\nStep 3: x = 110 / 2\nStep 4: x = 55.","steps":["Step 1: 2x + 70 = 180","Step 2: 2x = 110","Step 3: x = 110 / 2","Step 4: x = 55."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 1),
  (275, 71, 'Three angles on a straight line are 42°, 91° and x°. Find x.', 'text', 1, 'Add the known angles, then subtract from 180°.', '{"why":"All adjacent angles forming the straight angle sum to 180°.","sol":"Step 1: 42° + 91° = 133°\nStep 2: 133° + x = 180°\nStep 3: x = 180° - 133°\nStep 4: x = 47°.","steps":["Step 1: 42° + 91° = 133°","Step 2: 133° + x = 180°","Step 3: x = 180° - 133°","Step 4: x = 47°."],"options":[],"conceptId":"math_geometry_angles_on_a_straight_line","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles on a Straight Line"}', 2),
  (276, 72, 'Angles around a point are 75°, 125° and x°. Find x.', 'text', 1, 'A complete turn is 360°.', '{"why":"Angles around a point make one complete turn of 360°.","sol":"Step 1: 75° + 125° = 200°\nStep 2: x = 360° - 200°\nStep 3: x = 160°.","steps":["Step 1: 75° + 125° = 200°","Step 2: x = 360° - 200°","Step 3: x = 160°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 0),
  (277, 72, 'Five equal angles meet at a point. Find each angle.', 'text', 1, 'Divide 360° equally among five angles.', '{"why":"Equal angles share the complete turn equally.","sol":"Step 1: Total angle = 360°\nStep 2: Each angle = 360° / 5\nStep 3: Each angle = 72°.","steps":["Step 1: Total angle = 360°","Step 2: Each angle = 360° / 5","Step 3: Each angle = 72°."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 1),
  (278, 72, 'Angles x°, 2x°, 3x° and 60° meet at a point. Find x.', 'text', 1, 'Their sum is 360°.', '{"why":"Use the 360° total to form an equation.","sol":"Step 1: x + 2x + 3x + 60 = 360\nStep 2: 6x + 60 = 360\nStep 3: 6x = 300\nStep 4: x = 50.","steps":["Step 1: x + 2x + 3x + 60 = 360","Step 2: 6x + 60 = 360","Step 3: 6x = 300","Step 4: x = 50."],"options":[],"conceptId":"math_geometry_angles_around_a_point","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Angles Around a Point"}', 2),
  (279, 73, 'Two straight lines cross. One angle is 83°. Find the vertically opposite angle.', 'text', 1, 'Opposite angles formed by intersecting lines are equal.', '{"why":"Vertically opposite angles are equal.","sol":"Step 1: The given angle is 83°.\nStep 2: The opposite angle equals it.\nStep 3: Answer = 83°.","steps":["Step 1: The given angle is 83°.","Step 2: The opposite angle equals it.","Step 3: Answer = 83°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 0),
  (280, 73, 'Opposite angles are (5x - 8)° and 72°. Find x.', 'text', 1, 'Set the two angle expressions equal.', '{"why":"Equal vertically opposite angles give an equation.","sol":"Step 1: 5x - 8 = 72\nStep 2: 5x = 80\nStep 3: x = 16.","steps":["Step 1: 5x - 8 = 72","Step 2: 5x = 80","Step 3: x = 16."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 1),
  (281, 73, 'An angle at an intersection is 121°. Find the smaller adjacent angle.', 'text', 1, 'Adjacent angles on a straight line total 180°.', '{"why":"The adjacent angle and 121° form a straight angle.","sol":"Step 1: Adjacent angle = 180° - 121°\nStep 2: Adjacent angle = 59°.","steps":["Step 1: Adjacent angle = 180° - 121°","Step 2: Adjacent angle = 59°."],"options":[],"conceptId":"math_geometry_vertically_opposite_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Vertically Opposite Angles"}', 2),
  (282, 74, 'Two parallel lines are crossed by a transversal. A corresponding angle is 74°. Find its partner.', 'text', 1, 'Corresponding angles are equal for parallel lines.', '{"why":"Corresponding angles are equal when the lines are parallel.","sol":"Step 1: The lines are parallel.\nStep 2: Corresponding angles are equal.\nStep 3: The required angle is 74°.","steps":["Step 1: The lines are parallel.","Step 2: Corresponding angles are equal.","Step 3: The required angle is 74°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 0),
  (283, 74, 'One alternate interior angle is 126°. Find the other alternate interior angle.', 'text', 1, 'Alternate interior angles are equal.', '{"why":"The alternate interior angle rule applies to parallel lines.","sol":"Step 1: The lines are parallel.\nStep 2: Alternate interior angles are equal.\nStep 3: The required angle is 126°.","steps":["Step 1: The lines are parallel.","Step 2: Alternate interior angles are equal.","Step 3: The required angle is 126°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 1),
  (284, 74, 'Co-interior angles are (2x + 10)° and 110°. Find x.', 'text', 1, 'Co-interior angles add up to 180°.', '{"why":"Co-interior angles on parallel lines are supplementary.","sol":"Step 1: 2x + 10 + 110 = 180\nStep 2: 2x + 120 = 180\nStep 3: 2x = 60\nStep 4: x = 30.","steps":["Step 1: 2x + 10 + 110 = 180","Step 2: 2x + 120 = 180","Step 3: 2x = 60","Step 4: x = 30."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 2),
  (285, 74, 'A co-interior angle is 97°. Find the other angle.', 'text', 1, 'Subtract 97° from 180°.', '{"why":"The two co-interior angles add up to 180°.","sol":"Step 1: Other angle = 180° - 97°\nStep 2: Other angle = 83°.","steps":["Step 1: Other angle = 180° - 97°","Step 2: Other angle = 83°."],"options":[],"conceptId":"math_geometry_parallel_lines_and_a_transversal","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Parallel Lines and a Transversal"}', 3),
  (286, 75, 'A triangle has angles 45°, 65° and x°. Find x.', 'text', 1, 'Add 45° and 65°, then subtract their sum from 180°.', '{"why":"The missing angle is the difference between 180° and the sum of the two known angles.","sol":"Step 1: The interior angles of a triangle add up to 180°.\nStep 2: 45° + 65° + x = 180°.\nStep 3: 110° + x = 180°.\nStep 4: x = 180° - 110° = 70°.","steps":["Step 1: The interior angles of a triangle add up to 180°.","Step 2: 45° + 65° + x = 180°.","Step 3: 110° + x = 180°.","Step 4: x = 180° - 110° = 70°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 0),
  (287, 75, 'Two angles of a triangle are 28° and 92°. Calculate the third angle.', 'text', 1, 'Find 28° + 92° first.', '{"why":"The three interior angles must total exactly 180°.","sol":"Step 1: Add the known angles: 28° + 92° = 120°.\nStep 2: Subtract their sum from 180°.\nStep 3: x = 180° - 120° = 60°.","steps":["Step 1: Add the known angles: 28° + 92° = 120°.","Step 2: Subtract their sum from 180°.","Step 3: x = 180° - 120° = 60°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 1),
  (288, 75, 'The angles of a triangle are x°, 2x° and 30°. Find x.', 'text', 1, 'Form the equation x + 2x + 30 = 180.', '{"why":"The equation represents all three angles. Substituting x = 50° gives 50°, 100° and 30°, which total 180°.","sol":"Step 1: Write the angle-sum equation: x + 2x + 30 = 180.\nStep 2: Collect like terms: 3x + 30 = 180.\nStep 3: Subtract 30: 3x = 150.\nStep 4: Divide by 3: x = 50°.","steps":["Step 1: Write the angle-sum equation: x + 2x + 30 = 180.","Step 2: Collect like terms: 3x + 30 = 180.","Step 3: Subtract 30: 3x = 150.","Step 4: Divide by 3: x = 50°."],"options":[],"conceptId":"math_geometry_triangle_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Triangle Angle Sum"}', 2),
  (289, 76, 'An isosceles triangle has a top angle of 36°. Find each base angle.', 'text', 1, 'Subtract 36° from 180°, then divide the result by 2.', '{"why":"The base angles are equal and together they must total 144°.","sol":"Step 1: The two base angles share the remaining angle sum.\nStep 2: 180° - 36° = 144°.\nStep 3: 144° ÷ 2 = 72°.\nStep 4: Each base angle is 72°.","steps":["Step 1: The two base angles share the remaining angle sum.","Step 2: 180° - 36° = 144°.","Step 3: 144° ÷ 2 = 72°.","Step 4: Each base angle is 72°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 0),
  (290, 76, 'Each base angle of an isosceles triangle is 48°. Find its top angle.', 'text', 1, 'Add the base angles before subtracting from 180°.', '{"why":"The top angle is the remaining part of the triangle''s 180° angle sum.","sol":"Step 1: Add the base angles: 48° + 48° = 96°.\nStep 2: Subtract from 180°: 180° - 96° = 84°.","steps":["Step 1: Add the base angles: 48° + 48° = 96°.","Step 2: Subtract from 180°: 180° - 96° = 84°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 1),
  (291, 76, 'An isosceles triangle has angles x°, x° and 4x°. Find x.', 'text', 1, 'Write x + x + 4x = 180.', '{"why":"The two equal base angles are both 30°, while the third angle is four times x.","sol":"Step 1: Combine the angles: x + x + 4x = 180.\nStep 2: Simplify: 6x = 180.\nStep 3: Divide by 6: x = 30°.\nStep 4: The angles are 30°, 30° and 120°.","steps":["Step 1: Combine the angles: x + x + 4x = 180.","Step 2: Simplify: 6x = 180.","Step 3: Divide by 6: x = 30°.","Step 4: The angles are 30°, 30° and 120°."],"options":[],"conceptId":"math_geometry_isosceles_triangle_base_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Isosceles Triangle Base Angles"}', 2),
  (292, 77, 'The two opposite interior angles of a triangle are 38° and 72°. Find the exterior angle.', 'text', 1, 'Add the two opposite interior angles.', '{"why":"An exterior angle equals the sum of the two opposite interior angles.","sol":"Step 1: Use the exterior angle rule.\nStep 2: Exterior angle = 38° + 72°.\nStep 3: Exterior angle = 110°.","steps":["Step 1: Use the exterior angle rule.","Step 2: Exterior angle = 38° + 72°.","Step 3: Exterior angle = 110°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 0),
  (293, 77, 'An exterior angle is 132°. One opposite interior angle is 57°. Find the other opposite interior angle.', 'text', 1, 'Subtract 57° from 132°.', '{"why":"The two opposite interior angles together equal the exterior angle.","sol":"Step 1: Let the missing angle be x.\nStep 2: 132° = 57° + x.\nStep 3: x = 132° - 57°.\nStep 4: x = 75°.","steps":["Step 1: Let the missing angle be x.","Step 2: 132° = 57° + x.","Step 3: x = 132° - 57°.","Step 4: x = 75°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 1),
  (294, 77, 'An exterior angle of a triangle is 118°. Calculate the interior angle next to it.', 'text', 1, 'The two adjacent angles on a straight line add up to 180°.', '{"why":"The adjacent interior and exterior angles form a straight line, so they add up to 180°.","sol":"Step 1: Let the adjacent interior angle be x.\nStep 2: x + 118° = 180°.\nStep 3: x = 180° - 118°.\nStep 4: x = 62°.","steps":["Step 1: Let the adjacent interior angle be x.","Step 2: x + 118° = 180°.","Step 3: x = 180° - 118°.","Step 4: x = 62°."],"options":[],"conceptId":"math_geometry_exterior_angle_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angle of a Triangle"}', 2),
  (295, 78, 'A triangle has sides 9 cm, 9 cm and 9 cm. Classify it by its sides.', 'text', 1, 'Check whether all three lengths are equal.', '{"why":"An equilateral triangle has three equal sides.","sol":"Step 1: Compare the three side lengths.\nStep 2: All three sides are 9 cm.\nStep 3: Therefore, the triangle is equilateral.","steps":["Step 1: Compare the three side lengths.","Step 2: All three sides are 9 cm.","Step 3: Therefore, the triangle is equilateral."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 0),
  (296, 78, 'A triangle has sides 8 cm, 8 cm and 5 cm. Classify it by its sides.', 'text', 1, 'Count how many sides have the same length.', '{"why":"An isosceles triangle has two equal sides.","sol":"Step 1: Two sides are 8 cm.\nStep 2: The third side is 5 cm.\nStep 3: Exactly two sides are equal, so it is isosceles.","steps":["Step 1: Two sides are 8 cm.","Step 2: The third side is 5 cm.","Step 3: Exactly two sides are equal, so it is isosceles."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 1),
  (297, 78, 'A learner says a triangle with sides 3 cm, 4 cm and 8 cm is scalene. Is the learner correct?', 'text', 1, 'Before classifying, check whether the lengths can form a triangle.', '{"why":"Having three different lengths is not enough. The sum of the two shorter sides must be greater than the longest side.","sol":"Step 1: Add the two shorter sides: 3 + 4 = 7.\nStep 2: Compare this sum with the longest side, 8.\nStep 3: Since 7 is not greater than 8, the triangle inequality fails.\nStep 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect.","steps":["Step 1: Add the two shorter sides: 3 + 4 = 7.","Step 2: Compare this sum with the longest side, 8.","Step 3: Since 7 is not greater than 8, the triangle inequality fails.","Step 4: These lengths cannot form a triangle, so classifying them as a scalene triangle is incorrect."],"options":[],"conceptId":"math_geometry_classifying_triangles_by_sides","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Classifying Triangles by Sides"}', 2),
  (298, 79, 'A right-angled triangle has shorter sides of 9 cm and 12 cm. Find the hypotenuse.', 'text', 1, 'Use c² = 9² + 12².', '{"why":"The hypotenuse is found by adding the squares of the two shorter sides and then taking the square root.","sol":"Step 1: c² = 9² + 12².\nStep 2: c² = 81 + 144.\nStep 3: c² = 225.\nStep 4: c = √225.\nStep 5: c = 15 cm.","steps":["Step 1: c² = 9² + 12².","Step 2: c² = 81 + 144.","Step 3: c² = 225.","Step 4: c = √225.","Step 5: c = 15 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 0),
  (299, 79, 'A right-angled triangle has a hypotenuse of 17 m and one shorter side of 8 m. Find the other shorter side.', 'text', 1, 'Use b² = c² - a².', '{"why":"When finding a shorter side, subtract the square of the known shorter side from the square of the hypotenuse.","sol":"Step 1: 17² = 8² + b².\nStep 2: 289 = 64 + b².\nStep 3: 289 - 64 = b².\nStep 4: 225 = b².\nStep 5: b = √225.\nStep 6: b = 15 m.","steps":["Step 1: 17² = 8² + b².","Step 2: 289 = 64 + b².","Step 3: 289 - 64 = b².","Step 4: 225 = b².","Step 5: b = √225.","Step 6: b = 15 m."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 1),
  (300, 79, 'A learner uses 10² = 6² - 8² to find the hypotenuse of a triangle with shorter sides 6 cm and 8 cm. Identify the error and find the correct hypotenuse.', 'text', 1, 'When finding the hypotenuse, the two shorter-side squares are added.', '{"why":"The learner subtracted the squares. To find the hypotenuse, the squares of the two shorter sides must be added.","sol":"Step 1: The hypotenuse is found using c² = a² + b².\nStep 2: c² = 6² + 8².\nStep 3: c² = 36 + 64.\nStep 4: c² = 100.\nStep 5: c = √100.\nStep 6: c = 10 cm.","steps":["Step 1: The hypotenuse is found using c² = a² + b².","Step 2: c² = 6² + 8².","Step 3: c² = 36 + 64.","Step 4: c² = 100.","Step 5: c = √100.","Step 6: c = 10 cm."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 2),
  (301, 79, 'The sides of a triangle are 7 cm, 24 cm and 25 cm. The triangle is right-angled. Verify Pythagoras'' theorem.', 'text', 1, 'The longest side is the hypotenuse.', '{"why":"The square of the hypotenuse equals the sum of the squares of the two shorter sides.","sol":"Step 1: The hypotenuse is 25 cm.\nStep 2: 25² = 625.\nStep 3: 7² + 24² = 49 + 576.\nStep 4: 7² + 24² = 625.\nStep 5: Therefore, 25² = 7² + 24².","steps":["Step 1: The hypotenuse is 25 cm.","Step 2: 25² = 625.","Step 3: 7² + 24² = 49 + 576.","Step 4: 7² + 24² = 625.","Step 5: Therefore, 25² = 7² + 24²."],"options":[],"conceptId":"math_geometry_pythagoras_theorem","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Pythagoras'' Theorem"}', 3),
  (302, 80, 'Three angles of a quadrilateral are 70°, 110° and 95°. Find the fourth angle.', 'text', 1, 'Add the three known angles and subtract from 360°.', '{"why":"The four interior angles of a quadrilateral total 360°.","sol":"Step 1: Add the known angles: 70° + 110° + 95° = 275°.\nStep 2: Subtract from 360°: 360° - 275° = 85°.","steps":["Step 1: Add the known angles: 70° + 110° + 95° = 275°.","Step 2: Subtract from 360°: 360° - 275° = 85°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 0),
  (303, 80, 'A quadrilateral has angles 90°, 90°, 90° and x°. Find x.', 'text', 1, 'Three right angles total 270°.', '{"why":"The missing angle must complete the quadrilateral''s 360° total.","sol":"Step 1: Add the known angles: 90° + 90° + 90° = 270°.\nStep 2: Subtract from 360°: x = 360° - 270°.\nStep 3: Therefore, x = 90°.","steps":["Step 1: Add the known angles: 90° + 90° + 90° = 270°.","Step 2: Subtract from 360°: x = 360° - 270°.","Step 3: Therefore, x = 90°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 1),
  (304, 80, 'The angles of a quadrilateral are x°, 2x°, 3x° and 60°. Find x.', 'text', 1, 'Form the equation x + 2x + 3x + 60 = 360.', '{"why":"The four angles must total 360°. Substitution gives 50°, 100°, 150° and 60°, which total 360°.","sol":"Step 1: Add the angles: x + 2x + 3x + 60 = 360.\nStep 2: Collect like terms: 6x + 60 = 360.\nStep 3: Subtract 60: 6x = 300.\nStep 4: Divide by 6: x = 50°.","steps":["Step 1: Add the angles: x + 2x + 3x + 60 = 360.","Step 2: Collect like terms: 6x + 60 = 360.","Step 3: Subtract 60: 6x = 300.","Step 4: Divide by 6: x = 50°."],"options":[],"conceptId":"math_geometry_quadrilateral_interior_angle_sum","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Quadrilateral Interior Angle Sum"}', 2),
  (305, 81, 'A parallelogram has AB = 14 cm. If CD is opposite AB, find CD.', 'text', 1, 'Opposite sides of a parallelogram are equal.', '{"why":"Opposite sides of a parallelogram have equal lengths.","sol":"Step 1: AB and CD are opposite sides.\nStep 2: Therefore, AB = CD.\nStep 3: CD = 14 cm.","steps":["Step 1: AB and CD are opposite sides.","Step 2: Therefore, AB = CD.","Step 3: CD = 14 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 0),
  (306, 81, 'Opposite sides of a parallelogram are (4x - 3) cm and 21 cm. Find x.', 'text', 1, 'Set 4x - 3 equal to 21.', '{"why":"The two expressions describe opposite sides, which must have equal lengths.","sol":"Step 1: Set the opposite sides equal: 4x - 3 = 21.\nStep 2: Add 3 to both sides: 4x = 24.\nStep 3: Divide both sides by 4: x = 6.","steps":["Step 1: Set the opposite sides equal: 4x - 3 = 21.","Step 2: Add 3 to both sides: 4x = 24.","Step 3: Divide both sides by 4: x = 6."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 1),
  (307, 81, 'A parallelogram has adjacent sides of 11 cm and 7 cm. A learner says every side must be 11 cm. Explain the error and calculate the perimeter.', 'text', 1, 'Only opposite sides must be equal. Add all four sides.', '{"why":"A parallelogram has equal opposite sides, not necessarily four equal sides.","sol":"Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.\nStep 2: The sides of length 11 cm are opposite each other.\nStep 3: The sides of length 7 cm are also opposite each other.\nStep 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm.","steps":["Step 1: The side lengths are 11 cm, 7 cm, 11 cm and 7 cm.","Step 2: The sides of length 11 cm are opposite each other.","Step 3: The sides of length 7 cm are also opposite each other.","Step 4: Perimeter = 11 + 7 + 11 + 7 = 36 cm."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_sides_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Sides Are Equal"}', 2),
  (308, 82, 'One angle of a parallelogram is 112°. Find its opposite angle.', 'text', 1, 'Opposite angles are equal.', '{"why":"Opposite angles of a parallelogram have equal measures.","sol":"Step 1: Identify the angle opposite 112°.\nStep 2: Opposite angles are equal.\nStep 3: The missing angle is 112°.","steps":["Step 1: Identify the angle opposite 112°.","Step 2: Opposite angles are equal.","Step 3: The missing angle is 112°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 0),
  (309, 82, 'Opposite angles are (5x - 20)° and 80°. Find x.', 'text', 1, 'Set 5x - 20 equal to 80.', '{"why":"The angles are opposite, so their expressions must have equal values.","sol":"Step 1: Write 5x - 20 = 80.\nStep 2: Add 20 to both sides: 5x = 100.\nStep 3: Divide by 5: x = 20.","steps":["Step 1: Write 5x - 20 = 80.","Step 2: Add 20 to both sides: 5x = 100.","Step 3: Divide by 5: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 1),
  (310, 82, 'A parallelogram has one angle of 64°. Find the other three angles.', 'text', 1, 'The opposite angle equals 64°. Each adjacent angle is 180° - 64°.', '{"why":"Opposite angles are equal, while adjacent angles are supplementary.","sol":"Step 1: The opposite angle is 64°.\nStep 2: Calculate each adjacent angle: 180° - 64° = 116°.\nStep 3: The four angles are 64°, 116°, 64° and 116°.","steps":["Step 1: The opposite angle is 64°.","Step 2: Calculate each adjacent angle: 180° - 64° = 116°.","Step 3: The four angles are 64°, 116°, 64° and 116°."],"options":[],"conceptId":"math_geometry_parallelogram_opposite_angles_are_equal","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Opposite Angles Are Equal"}', 2),
  (311, 83, 'One angle of a parallelogram is 83°. Find an adjacent angle.', 'text', 1, 'Subtract 83° from 180°.', '{"why":"The adjacent angle must complete the 180° total.","sol":"Step 1: Adjacent angles add to 180°.\nStep 2: 83° + x = 180°.\nStep 3: x = 180° - 83° = 97°.","steps":["Step 1: Adjacent angles add to 180°.","Step 2: 83° + x = 180°.","Step 3: x = 180° - 83° = 97°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 0),
  (312, 83, 'Adjacent angles are (4x + 5)° and 95°. Find x.', 'text', 1, 'Their sum is 180°.', '{"why":"Adjacent angles in a parallelogram are supplementary.","sol":"Step 1: Write 4x + 5 + 95 = 180.\nStep 2: Simplify: 4x + 100 = 180.\nStep 3: Subtract 100: 4x = 80.\nStep 4: Divide by 4: x = 20.","steps":["Step 1: Write 4x + 5 + 95 = 180.","Step 2: Simplify: 4x + 100 = 180.","Step 3: Subtract 100: 4x = 80.","Step 4: Divide by 4: x = 20."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 1),
  (313, 83, 'Two adjacent angles of a parallelogram are in the ratio 4:5. Find both angles.', 'text', 1, 'Represent the angles as 4x and 5x and use their 180° sum.', '{"why":"The ratio gives the relative sizes, and the supplementary-angle rule supplies their total.","sol":"Step 1: Let the angles be 4x and 5x.\nStep 2: 4x + 5x = 180.\nStep 3: 9x = 180, so x = 20.\nStep 4: The angles are 4(20) = 80° and 5(20) = 100°.","steps":["Step 1: Let the angles be 4x and 5x.","Step 2: 4x + 5x = 180.","Step 3: 9x = 180, so x = 20.","Step 4: The angles are 4(20) = 80° and 5(20) = 100°."],"options":[],"conceptId":"math_geometry_parallelogram_adjacent_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Parallelogram: Adjacent Angles"}', 2),
  (314, 84, 'A circle has radius 7 cm. Calculate its diameter.', 'text', 1, 'Multiply the radius by 2.', '{"why":"A diameter consists of two radii placed end to end through the centre.","sol":"Step 1: Diameter = 2 × radius.\nStep 2: Diameter = 2 × 7.\nStep 3: Diameter = 14 cm.","steps":["Step 1: Diameter = 2 × radius.","Step 2: Diameter = 2 × 7.","Step 3: Diameter = 14 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 0),
  (315, 84, 'The diameter of a circle is 26 cm. Find its radius.', 'text', 1, 'Divide the diameter by 2.', '{"why":"The radius is half the diameter.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: Radius = 26 ÷ 2.\nStep 3: Radius = 13 cm.","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: Radius = 26 ÷ 2.","Step 3: Radius = 13 cm."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 1),
  (316, 84, 'A learner says a circle with radius 8 cm has diameter 8 cm. Identify the error and give the correct diameter.', 'text', 1, 'The learner has treated the radius and diameter as the same length.', '{"why":"The diameter passes through the centre and spans two radii.","sol":"Step 1: The radius is 8 cm.\nStep 2: Diameter = 2 × radius.\nStep 3: Diameter = 2 × 8 = 16 cm.\nStep 4: The learner forgot that the diameter is twice the radius.","steps":["Step 1: The radius is 8 cm.","Step 2: Diameter = 2 × radius.","Step 3: Diameter = 2 × 8 = 16 cm.","Step 4: The learner forgot that the diameter is twice the radius."],"options":[],"conceptId":"math_geometry_circle_radius_and_diameter","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circle: Radius and Diameter"}', 2),
  (317, 85, 'A circle has radius 5 cm. Find its circumference in terms of π.', 'text', 1, 'Use C = 2πr.', '{"why":"The radius formula multiplies the radius by 2π.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 5.\nStep 3: C = 2 × π × 5 = 10π cm.","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 5.","Step 3: C = 2 × π × 5 = 10π cm."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 0),
  (318, 85, 'A circle has diameter 14 m. Find its circumference in terms of π.', 'text', 1, 'Use C = πd because the diameter is given.', '{"why":"The circumference equals π multiplied by the diameter.","sol":"Step 1: Use C = πd.\nStep 2: Substitute d = 14.\nStep 3: C = 14π m.","steps":["Step 1: Use C = πd.","Step 2: Substitute d = 14.","Step 3: C = 14π m."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 1),
  (319, 85, 'A learner calculates the circumference of a circle with radius 4 cm as 16π cm². Identify the error and give the correct answer.', 'text', 1, 'Check both the formula and the unit.', '{"why":"The learner used an incorrect calculation and a square unit. Circumference is a one-dimensional length.","sol":"Step 1: Use C = 2πr.\nStep 2: Substitute r = 4: C = 2 × π × 4.\nStep 3: C = 8π cm.\nStep 4: Circumference is a length, so the unit is cm, not cm².","steps":["Step 1: Use C = 2πr.","Step 2: Substitute r = 4: C = 2 × π × 4.","Step 3: C = 8π cm.","Step 4: Circumference is a length, so the unit is cm, not cm²."],"options":[],"conceptId":"math_geometry_circumference_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circumference of a Circle"}', 2),
  (320, 86, 'A circle has a radius of 6 cm. Find its area. Use π = 3.142.', 'text', 1, 'Use A = πr² and remember to square the radius.', '{"why":"The area of a circle is found by multiplying π by the square of its radius.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 6².\nStep 3: 6² = 36.\nStep 4: A = 3.142 × 36.\nStep 5: A = 113.112 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 6².","Step 3: 6² = 36.","Step 4: A = 3.142 × 36.","Step 5: A = 113.112 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 0),
  (321, 86, 'A circle has a diameter of 14 cm. Find its area. Use π = 22/7.', 'text', 1, 'Find the radius first.', '{"why":"The area formula requires the radius, so the diameter must first be divided by 2.","sol":"Step 1: Radius = diameter ÷ 2.\nStep 2: r = 14 ÷ 2 = 7 cm.\nStep 3: A = πr².\nStep 4: A = 22/7 × 7².\nStep 5: A = 22/7 × 49.\nStep 6: A = 154 cm².","steps":["Step 1: Radius = diameter ÷ 2.","Step 2: r = 14 ÷ 2 = 7 cm.","Step 3: A = πr².","Step 4: A = 22/7 × 7².","Step 5: A = 22/7 × 49.","Step 6: A = 154 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 1),
  (322, 86, 'A circle has a radius of 8 m. Find its area using π = 3.142.', 'text', 1, 'Square 8 before multiplying by π.', '{"why":"The radius is squared before multiplying by π.","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 8².\nStep 3: 8² = 64.\nStep 4: A = 3.142 × 64.\nStep 5: A = 201.088 m².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 8².","Step 3: 8² = 64.","Step 4: A = 3.142 × 64.","Step 5: A = 201.088 m²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 2),
  (323, 86, 'A learner says that the area of a circle with radius 5 cm is 31.42 cm². Identify the error and calculate the correct area using π = 3.142.', 'text', 1, 'Check whether the radius was squared.', '{"why":"The learner multiplied π by 5 instead of multiplying π by 5².","sol":"Step 1: A = πr².\nStep 2: A = 3.142 × 5².\nStep 3: 5² = 25.\nStep 4: A = 3.142 × 25.\nStep 5: A = 78.55 cm².","steps":["Step 1: A = πr².","Step 2: A = 3.142 × 5².","Step 3: 5² = 25.","Step 4: A = 3.142 × 25.","Step 5: A = 78.55 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_circle","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Circle"}', 3),
  (324, 87, 'A rectangle has length 12 cm and width 5 cm. Find its perimeter.', 'text', 1, 'Use P = 2(l + w).', '{"why":"The formula adds the length and width and doubles their sum to include all four sides.","sol":"Step 1: Write P = 2(l + w).\nStep 2: Substitute: P = 2(12 + 5).\nStep 3: P = 2 × 17 = 34 cm.","steps":["Step 1: Write P = 2(l + w).","Step 2: Substitute: P = 2(12 + 5).","Step 3: P = 2 × 17 = 34 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 0),
  (325, 87, 'A rectangle has perimeter 40 m and length 13 m. Find its width.', 'text', 1, 'Start with 40 = 2(13 + w).', '{"why":"Half the perimeter equals one length plus one width.","sol":"Step 1: 40 = 2(13 + w).\nStep 2: Divide by 2: 20 = 13 + w.\nStep 3: Subtract 13: w = 7 m.","steps":["Step 1: 40 = 2(13 + w).","Step 2: Divide by 2: 20 = 13 + w.","Step 3: Subtract 13: w = 7 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 1),
  (326, 87, 'A learner calculates the perimeter of a 7 cm by 4 cm rectangle as 28 cm. Explain the mistake and give the correct perimeter.', 'text', 1, 'Check whether the learner multiplied the dimensions instead of adding all four sides.', '{"why":"Perimeter adds boundary lengths; multiplying length by width calculates area.","sol":"Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².\nStep 2: Perimeter = 2(7 + 4).\nStep 3: Perimeter = 2 × 11 = 22 cm.","steps":["Step 1: Multiplying 7 × 4 gives 28, which is the area in cm².","Step 2: Perimeter = 2(7 + 4).","Step 3: Perimeter = 2 × 11 = 22 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Rectangle"}', 2),
  (327, 88, 'A square has sides of 11 cm. Find its perimeter.', 'text', 1, 'Multiply one side by 4.', '{"why":"A square has four equal sides.","sol":"Step 1: P = 4s.\nStep 2: P = 4 × 11.\nStep 3: P = 44 cm.","steps":["Step 1: P = 4s.","Step 2: P = 4 × 11.","Step 3: P = 44 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 0),
  (328, 88, 'The perimeter of a square is 52 m. Find the length of one side.', 'text', 1, 'Divide the perimeter by 4.', '{"why":"The total perimeter is shared equally among the four sides.","sol":"Step 1: P = 4s.\nStep 2: 52 = 4s.\nStep 3: s = 52 ÷ 4 = 13 m.","steps":["Step 1: P = 4s.","Step 2: 52 = 4s.","Step 3: s = 52 ÷ 4 = 13 m."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 1),
  (329, 88, 'A learner says a square with side 8 cm has perimeter 64 cm. Identify the error and calculate the correct perimeter.', 'text', 1, 'Compare 4 × side with side × side.', '{"why":"Perimeter uses four times the side length; squaring the side gives area.","sol":"Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².\nStep 2: Perimeter = 4 × 8.\nStep 3: Perimeter = 32 cm.","steps":["Step 1: The learner calculated 8 × 8 = 64, which is the area in cm².","Step 2: Perimeter = 4 × 8.","Step 3: Perimeter = 32 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Square"}', 2),
  (330, 89, 'A triangle has sides 6 cm, 8 cm and 11 cm. Find its perimeter.', 'text', 1, 'Add all three side lengths.', '{"why":"The perimeter is the total distance around the triangle.","sol":"Step 1: P = 6 + 8 + 11.\nStep 2: P = 25 cm.","steps":["Step 1: P = 6 + 8 + 11.","Step 2: P = 25 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 0),
  (331, 89, 'A triangle has perimeter 31 cm. Two sides measure 9 cm and 13 cm. Find the third side.', 'text', 1, 'Subtract the two known sides from the perimeter.', '{"why":"The missing side is the total perimeter minus the two known sides.","sol":"Step 1: Let the missing side be x.\nStep 2: 9 + 13 + x = 31.\nStep 3: 22 + x = 31.\nStep 4: x = 9 cm.","steps":["Step 1: Let the missing side be x.","Step 2: 9 + 13 + x = 31.","Step 3: 22 + x = 31.","Step 4: x = 9 cm."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 1),
  (332, 89, 'An equilateral triangle has perimeter 57 cm. A learner says each side is 19 cm². Correct the answer and explain the unit.', 'text', 1, 'Divide by 3, and remember that side length is a distance.', '{"why":"Dividing the perimeter by three gives one side, which is a length.","sol":"Step 1: All three sides are equal.\nStep 2: Side length = 57 ÷ 3 = 19.\nStep 3: The correct side length is 19 cm, not 19 cm².\nStep 4: Centimetres measure length; square centimetres measure area.","steps":["Step 1: All three sides are equal.","Step 2: Side length = 57 ÷ 3 = 19.","Step 3: The correct side length is 19 cm, not 19 cm².","Step 4: Centimetres measure length; square centimetres measure area."],"options":[],"conceptId":"math_geometry_perimeter_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Perimeter of a Triangle"}', 2),
  (333, 90, 'A rectangle is 13 m long and 4 m wide. Find its area.', 'text', 1, 'Multiply length by width.', '{"why":"The rectangle''s surface is measured by multiplying its length by its width.","sol":"Step 1: A = l × w.\nStep 2: A = 13 × 4.\nStep 3: A = 52 m².","steps":["Step 1: A = l × w.","Step 2: A = 13 × 4.","Step 3: A = 52 m²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 0),
  (334, 90, 'A rectangle has area 96 cm² and width 8 cm. Find its length.', 'text', 1, 'Divide the area by the width.', '{"why":"Dividing area by one dimension gives the other dimension.","sol":"Step 1: A = l × w.\nStep 2: 96 = l × 8.\nStep 3: l = 96 ÷ 8.\nStep 4: l = 12 cm.","steps":["Step 1: A = l × w.","Step 2: 96 = l × 8.","Step 3: l = 96 ÷ 8.","Step 4: l = 12 cm."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 1),
  (335, 90, 'A learner finds the area of a rectangle measuring 10 cm by 6 cm as 32 cm². Identify the likely mistake and calculate the correct area.', 'text', 1, 'Check whether the learner added the dimensions.', '{"why":"The area formula is length multiplied by width, not their sum.","sol":"Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.\nStep 2: Area must be calculated by multiplication.\nStep 3: A = 10 × 6.\nStep 4: A = 60 cm².","steps":["Step 1: Adding the dimensions gives 10 + 6 = 16, not 32.","Step 2: Area must be calculated by multiplication.","Step 3: A = 10 × 6.","Step 4: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_rectangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Rectangle"}', 2),
  (336, 91, 'A square has side length 12 cm. Find its area.', 'text', 1, 'Multiply 12 by 12.', '{"why":"The area of a square is its side length multiplied by itself.","sol":"Step 1: A = s².\nStep 2: A = 12 × 12.\nStep 3: A = 144 cm².","steps":["Step 1: A = s².","Step 2: A = 12 × 12.","Step 3: A = 144 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 0),
  (337, 91, 'A square has area 121 cm². Find its side length.', 'text', 1, 'Find the positive square root of 121.', '{"why":"The side length is the positive number whose square equals the area.","sol":"Step 1: A = s².\nStep 2: 121 = s².\nStep 3: s = √121 = 11 cm.","steps":["Step 1: A = s².","Step 2: 121 = s².","Step 3: s = √121 = 11 cm."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 1),
  (338, 91, 'A learner says a square with side 9 m has area 36 m² because 4 × 9 = 36. Explain the error and calculate the correct area.', 'text', 1, 'The learner used the perimeter calculation instead of the area formula.', '{"why":"Area squares the side length; multiplying by four calculates the perimeter.","sol":"Step 1: 4 × 9 calculates the perimeter, which is 36 m.\nStep 2: Area = side × side.\nStep 3: Area = 9 × 9 = 81 m².","steps":["Step 1: 4 × 9 calculates the perimeter, which is 36 m.","Step 2: Area = side × side.","Step 3: Area = 9 × 9 = 81 m²."],"options":[],"conceptId":"math_geometry_area_of_a_square","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Square"}', 2),
  (339, 92, 'A triangle has base 14 cm and perpendicular height 8 cm. Find its area.', 'text', 1, 'Multiply 14 by 8, then divide by 2.', '{"why":"The triangle occupies half the area of a rectangle with the same base and perpendicular height.","sol":"Step 1: A = ½ × b × h.\nStep 2: A = ½ × 14 × 8.\nStep 3: A = ½ × 112 = 56 cm².","steps":["Step 1: A = ½ × b × h.","Step 2: A = ½ × 14 × 8.","Step 3: A = ½ × 112 = 56 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 0),
  (340, 92, 'A triangle has area 54 m² and base 12 m. Find its perpendicular height.', 'text', 1, 'Start with 54 = ½ × 12 × h.', '{"why":"Rearranging the area formula gives height = 2 × area ÷ base.","sol":"Step 1: 54 = ½ × 12 × h.\nStep 2: Simplify: 54 = 6h.\nStep 3: Divide by 6: h = 9 m.","steps":["Step 1: 54 = ½ × 12 × h.","Step 2: Simplify: 54 = 6h.","Step 3: Divide by 6: h = 9 m."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 1),
  (341, 92, 'A learner calculates the area of a triangle with base 9 cm and perpendicular height 4 cm as 36 cm². Identify the error and calculate the correct area.', 'text', 1, 'The learner multiplied base by height but forgot to take half.', '{"why":"The area formula includes the factor ½.","sol":"Step 1: Multiply base by height: 9 × 4 = 36.\nStep 2: Take half: 36 ÷ 2 = 18.\nStep 3: The correct area is 18 cm².","steps":["Step 1: Multiply base by height: 9 × 4 = 36.","Step 2: Take half: 36 ÷ 2 = 18.","Step 3: The correct area is 18 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_triangle","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Triangle"}', 2),
  (342, 93, 'A parallelogram has a base of 15 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Use A = base × perpendicular height.', '{"why":"The area of a parallelogram is found by multiplying its base by its perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: A = 15 × 6.\nStep 3: A = 90 cm².","steps":["Step 1: A = b × h.","Step 2: A = 15 × 6.","Step 3: A = 90 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 0),
  (343, 93, 'A parallelogram has an area of 72 m² and a base of 9 m. Find its perpendicular height.', 'text', 1, 'Start with 72 = 9 × h.', '{"why":"When the area and base are known, divide the area by the base to find the perpendicular height.","sol":"Step 1: A = b × h.\nStep 2: 72 = 9 × h.\nStep 3: h = 72 ÷ 9.\nStep 4: h = 8 m.","steps":["Step 1: A = b × h.","Step 2: 72 = 9 × h.","Step 3: h = 72 ÷ 9.","Step 4: h = 8 m."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 1),
  (344, 93, 'A parallelogram has an area of 120 cm² and a perpendicular height of 8 cm. Find its base.', 'text', 1, 'Start with 120 = b × 8.', '{"why":"When the area and perpendicular height are known, divide the area by the height to find the base.","sol":"Step 1: A = b × h.\nStep 2: 120 = b × 8.\nStep 3: b = 120 ÷ 8.\nStep 4: b = 15 cm.","steps":["Step 1: A = b × h.","Step 2: 120 = b × 8.","Step 3: b = 120 ÷ 8.","Step 4: b = 15 cm."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 2),
  (345, 93, 'A learner uses the sloping side of a parallelogram as its height. Explain why this can give the wrong area.', 'text', 1, 'Think about what the word perpendicular means.', '{"why":"The formula A = base × height requires the perpendicular height, not simply any side length.","sol":"Step 1: The height must meet the base at 90°.\nStep 2: A sloping side may not meet the base at 90°.\nStep 3: Therefore, the sloping side cannot automatically be used as the height.\nStep 4: The perpendicular height must be used.","steps":["Step 1: The height must meet the base at 90°.","Step 2: A sloping side may not meet the base at 90°.","Step 3: Therefore, the sloping side cannot automatically be used as the height.","Step 4: The perpendicular height must be used."],"options":[],"conceptId":"math_geometry_area_of_a_parallelogram","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Parallelogram"}', 3),
  (346, 94, 'A trapezium has parallel sides of 7 cm and 13 cm and a perpendicular height of 6 cm. Find its area.', 'text', 1, 'Add the two parallel sides first, then multiply by half the height.', '{"why":"The area is half the sum of the two parallel sides multiplied by the perpendicular height.","sol":"Step 1: A = ½ × (a + b) × h.\nStep 2: A = ½ × (7 + 13) × 6.\nStep 3: A = ½ × 20 × 6.\nStep 4: A = 10 × 6.\nStep 5: A = 60 cm².","steps":["Step 1: A = ½ × (a + b) × h.","Step 2: A = ½ × (7 + 13) × 6.","Step 3: A = ½ × 20 × 6.","Step 4: A = 10 × 6.","Step 5: A = 60 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 0),
  (347, 94, 'A trapezium has parallel sides of 12 m and 18 m and an area of 150 m². Find its perpendicular height.', 'text', 1, 'Substitute into 150 = ½ × (12 + 18) × h.', '{"why":"After adding the parallel sides and taking half, divide the area by that value to find the height.","sol":"Step 1: 150 = ½ × (12 + 18) × h.\nStep 2: 150 = ½ × 30 × h.\nStep 3: 150 = 15h.\nStep 4: h = 150 ÷ 15.\nStep 5: h = 10 m.","steps":["Step 1: 150 = ½ × (12 + 18) × h.","Step 2: 150 = ½ × 30 × h.","Step 3: 150 = 15h.","Step 4: h = 150 ÷ 15.","Step 5: h = 10 m."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 1),
  (348, 94, 'A trapezium has parallel sides of 9 cm and 15 cm and a perpendicular height of 8 cm. A learner calculates its area as 192 cm². Identify the error and find the correct area.', 'text', 1, 'Check whether the learner added the parallel sides and then multiplied by the height without taking half.', '{"why":"The learner forgot the factor ½. Without taking half, the result is twice the correct area.","sol":"Step 1: A = ½ × (9 + 15) × 8.\nStep 2: A = ½ × 24 × 8.\nStep 3: A = 12 × 8.\nStep 4: A = 96 cm².","steps":["Step 1: A = ½ × (9 + 15) × 8.","Step 2: A = ½ × 24 × 8.","Step 3: A = 12 × 8.","Step 4: A = 96 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 2),
  (349, 94, 'A trapezium has parallel sides of 10 cm and 20 cm and a perpendicular height of 7 cm. Find its area.', 'text', 1, 'Use A = ½ × (a + b) × h.', '{"why":"The average of the parallel sides is 15 cm, and 15 × 7 gives the area.","sol":"Step 1: A = ½ × (10 + 20) × 7.\nStep 2: A = ½ × 30 × 7.\nStep 3: A = 15 × 7.\nStep 4: A = 105 cm².","steps":["Step 1: A = ½ × (10 + 20) × 7.","Step 2: A = ½ × 30 × 7.","Step 3: A = 15 × 7.","Step 4: A = 105 cm²."],"options":[],"conceptId":"math_geometry_area_of_a_trapezium","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area of a Trapezium"}', 3),
  (350, 95, 'Find the sum of the interior angles of an octagon.', 'text', 1, 'An octagon has 8 sides. Use (n − 2) × 180°.', '{"why":"An octagon can be divided into 6 triangles, and each triangle has an angle sum of 180°.","sol":"Step 1: n = 8.\nStep 2: Sum = (8 − 2) × 180°.\nStep 3: Sum = 6 × 180°.\nStep 4: Sum = 1080°.","steps":["Step 1: n = 8.","Step 2: Sum = (8 − 2) × 180°.","Step 3: Sum = 6 × 180°.","Step 4: Sum = 1080°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 0),
  (351, 95, 'A polygon has 10 sides. Find the sum of its interior angles.', 'text', 1, 'Substitute n = 10 into (n − 2) × 180°.', '{"why":"A 10-sided polygon can be divided into 8 triangles.","sol":"Step 1: n = 10.\nStep 2: Sum = (10 − 2) × 180°.\nStep 3: Sum = 8 × 180°.\nStep 4: Sum = 1440°.","steps":["Step 1: n = 10.","Step 2: Sum = (10 − 2) × 180°.","Step 3: Sum = 8 × 180°.","Step 4: Sum = 1440°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 1),
  (352, 95, 'A polygon has an interior angle sum of 1260°. How many sides does it have?', 'text', 1, 'Start with 1260 = (n − 2) × 180.', '{"why":"A polygon with 9 sides has 7 triangles, giving an interior angle sum of 7 × 180° = 1260°.","sol":"Step 1: 1260 = (n − 2) × 180.\nStep 2: 1260 ÷ 180 = n − 2.\nStep 3: 7 = n − 2.\nStep 4: n = 9.","steps":["Step 1: 1260 = (n − 2) × 180.","Step 2: 1260 ÷ 180 = n − 2.","Step 3: 7 = n − 2.","Step 4: n = 9."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 2),
  (353, 95, 'A learner says that the interior angle sum of a hexagon is 1080°. Identify the error and find the correct answer.', 'text', 1, 'Check the number of triangles formed using n − 2.', '{"why":"The learner did not use the correct number of triangles. A hexagon forms 4 triangles, not 6.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Number of triangles = 6 − 2 = 4.\nStep 3: Interior angle sum = 4 × 180°.\nStep 4: Interior angle sum = 720°.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Number of triangles = 6 − 2 = 4.","Step 3: Interior angle sum = 4 × 180°.","Step 4: Interior angle sum = 720°."],"options":[],"conceptId":"math_geometry_interior_angle_sum_of_polygons","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Interior Angle Sum of Polygons"}', 3),
  (354, 96, 'The exterior angles of a polygon are 90°, 80°, 70° and 60°. Find the fifth exterior angle.', 'text', 1, 'All exterior angles together add to 360°.', '{"why":"The exterior angles of a polygon make one complete turn, which is 360°.","sol":"Step 1: Total exterior angle sum = 360°.\nStep 2: 90° + 80° + 70° + 60° = 300°.\nStep 3: Missing angle = 360° − 300°.\nStep 4: Missing angle = 60°.","steps":["Step 1: Total exterior angle sum = 360°.","Step 2: 90° + 80° + 70° + 60° = 300°.","Step 3: Missing angle = 360° − 300°.","Step 4: Missing angle = 60°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 0),
  (355, 96, 'Find each exterior angle of a regular pentagon.', 'text', 1, 'Divide 360° by the number of sides.', '{"why":"A regular polygon has equal exterior angles, and together they total 360°.","sol":"Step 1: A pentagon has 5 sides.\nStep 2: Each exterior angle = 360° ÷ 5.\nStep 3: Each exterior angle = 72°.","steps":["Step 1: A pentagon has 5 sides.","Step 2: Each exterior angle = 360° ÷ 5.","Step 3: Each exterior angle = 72°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 1),
  (356, 96, 'Each exterior angle of a regular polygon is 30°. How many sides does the polygon have?', 'text', 1, 'Use n = 360° ÷ exterior angle.', '{"why":"There are 360° in one complete turn, so 30° exterior angles require 12 equal turns.","sol":"Step 1: n = 360° ÷ 30°.\nStep 2: n = 12.","steps":["Step 1: n = 360° ÷ 30°.","Step 2: n = 12."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 2),
  (357, 96, 'A regular polygon has an interior angle of 135°. Find each exterior angle.', 'text', 1, 'Interior angle + exterior angle = 180°.', '{"why":"The interior and exterior angles at the same vertex form a straight line.","sol":"Step 1: Interior angle + exterior angle = 180°.\nStep 2: 135° + exterior angle = 180°.\nStep 3: Exterior angle = 180° − 135°.\nStep 4: Exterior angle = 45°.","steps":["Step 1: Interior angle + exterior angle = 180°.","Step 2: 135° + exterior angle = 180°.","Step 3: Exterior angle = 180° − 135°.","Step 4: Exterior angle = 45°."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 3),
  (358, 96, 'A learner says that each exterior angle of a regular hexagon is 30°. Identify the error and find the correct angle.', 'text', 1, 'A hexagon has 6 equal exterior angles whose total is 360°.', '{"why":"The sum of the exterior angles is 360°, not 180°.","sol":"Step 1: A hexagon has 6 sides.\nStep 2: Each exterior angle = 360° ÷ 6.\nStep 3: Each exterior angle = 60°.\nStep 4: The learner used 180° ÷ 6 instead of 360° ÷ 6.","steps":["Step 1: A hexagon has 6 sides.","Step 2: Each exterior angle = 360° ÷ 6.","Step 3: Each exterior angle = 60°.","Step 4: The learner used 180° ÷ 6 instead of 360° ÷ 6."],"options":[],"conceptId":"math_geometry_exterior_angles_of_a_polygon","skillId":"math_geometry","subskillId":"math_geometry_q5","subject":"math","chapter":"geometry","topic":"Exterior Angles of a Polygon"}', 4),
  (359, 97, 'A farmer must choose how much land to use for maize and beans while trying to obtain the greatest profit. What mathematical method can be used?', 'text', 1, 'Think about choosing quantities while working under a restriction.', '{"why":"Linear programming is used to find the best choice while satisfying restrictions.","sol":"Step 1: The farmer must choose quantities for two crops.\nStep 2: The available land is limited.\nStep 3: There is a goal of obtaining the greatest profit.\nStep 4: Therefore, this is a linear programming situation.","steps":["Step 1: The farmer must choose quantities for two crops.","Step 2: The available land is limited.","Step 3: There is a goal of obtaining the greatest profit.","Step 4: Therefore, this is a linear programming situation."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 0),
  (360, 97, 'A business has limited money and must choose how many of two products to buy. What makes this a linear programming situation?', 'text', 1, 'Identify the choice, restriction and goal.', '{"why":"These are the basic ingredients of a linear programming problem.","sol":"Step 1: The business chooses quantities of the products.\nStep 2: The money available is limited.\nStep 3: The business wants the best possible choice.\nStep 4: Therefore, the situation can be handled using linear programming.","steps":["Step 1: The business chooses quantities of the products.","Step 2: The money available is limited.","Step 3: The business wants the best possible choice.","Step 4: Therefore, the situation can be handled using linear programming."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 1),
  (361, 97, 'Does linear programming require the use of a computer?', 'text', 1, 'Look at what the word programming means in this topic.', '{"why":"Linear programming is a mathematical optimisation method, not computer programming.","sol":"Step 1: The word programming in linear programming means planning.\nStep 2: It does not refer to writing computer code.\nStep 3: Therefore, a computer is not required to define the method.","steps":["Step 1: The word programming in linear programming means planning.","Step 2: It does not refer to writing computer code.","Step 3: Therefore, a computer is not required to define the method."],"options":[],"conceptId":"math_linear_programming_meaning_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Linear Programming"}', 2),
  (362, 98, 'A farmer grows maize and beans. Let x represent hectares of maize and y represent hectares of beans. Which are the decision variables?', 'text', 1, 'Look for the quantities whose values must be decided.', '{"why":"Decision variables represent the quantities that must be chosen.","sol":"Step 1: x represents hectares of maize.\nStep 2: y represents hectares of beans.\nStep 3: Both quantities must be decided.\nStep 4: Therefore, x and y are the decision variables.","steps":["Step 1: x represents hectares of maize.","Step 2: y represents hectares of beans.","Step 3: Both quantities must be decided.","Step 4: Therefore, x and y are the decision variables."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 0),
  (363, 98, 'A shop sells shoes and shirts. Choose suitable decision variables.', 'text', 1, 'Use x and y to represent the two quantities.', '{"why":"The variables must clearly identify the quantities being decided.","sol":"Step 1: Let x represent the number of shoes.\nStep 2: Let y represent the number of shirts.\nStep 3: These are the quantities the shop must decide.","steps":["Step 1: Let x represent the number of shoes.","Step 2: Let y represent the number of shirts.","Step 3: These are the quantities the shop must decide."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 1),
  (364, 98, 'Why should we state what x represents before solving a linear programming problem?', 'text', 1, 'Think about what x = 20 would mean without a definition.', '{"why":"A numerical answer is useful only when we know what quantity it represents.","sol":"Step 1: The letter x alone has no specific meaning.\nStep 2: We need to know what quantity x represents.\nStep 3: This allows us to interpret the final answer correctly.","steps":["Step 1: The letter x alone has no specific meaning.","Step 2: We need to know what quantity x represents.","Step 3: This allows us to interpret the final answer correctly."],"options":[],"conceptId":"math_linear_programming_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Decision Variables"}', 2),
  (365, 99, 'A farmer has at most 15 hectares for two crops. If x and y are the hectares used for the two crops, write the land constraint.', 'text', 1, 'At most means the total cannot exceed 15.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: The total land used is x + y.\nStep 2: The available land is 15 hectares.\nStep 3: The total cannot be greater than 15.\nStep 4: Therefore, x + y ≤ 15.","steps":["Step 1: The total land used is x + y.","Step 2: The available land is 15 hectares.","Step 3: The total cannot be greater than 15.","Step 4: Therefore, x + y ≤ 15."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 0),
  (366, 99, 'A factory can make at most 80 products of two types in one day. If x and y are the quantities, write the constraint.', 'text', 1, 'At most 80 means not more than 80.', '{"why":"The total number of products cannot be greater than 80.","sol":"Step 1: Total production is x + y.\nStep 2: Production cannot exceed 80.\nStep 3: Therefore, x + y ≤ 80.","steps":["Step 1: Total production is x + y.","Step 2: Production cannot exceed 80.","Step 3: Therefore, x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 1),
  (367, 99, 'In a constraint, what does the restriction actually do?', 'text', 1, 'Think about allowed and forbidden choices.', '{"why":"Constraints describe the conditions that every acceptable solution must satisfy.","sol":"Step 1: Without a constraint, many values might be possible.\nStep 2: The constraint removes values that violate the condition.\nStep 3: The remaining values are the allowed choices.","steps":["Step 1: Without a constraint, many values might be possible.","Step 2: The constraint removes values that violate the condition.","Step 3: The remaining values are the allowed choices."],"options":[],"conceptId":"math_linear_programming_understanding_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Understanding Constraints"}', 2),
  (368, 100, 'A farmer has at most 40 hectares for two crops. If x and y are the hectares used, write the constraint.', 'text', 1, 'At most means not greater than.', '{"why":"At most 40 means the total is less than or equal to 40.","sol":"Step 1: The total land is x + y.\nStep 2: The maximum available is 40 hectares.\nStep 3: Therefore the total cannot exceed 40.\nStep 4: So x + y ≤ 40.","steps":["Step 1: The total land is x + y.","Step 2: The maximum available is 40 hectares.","Step 3: Therefore the total cannot exceed 40.","Step 4: So x + y ≤ 40."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 0),
  (369, 100, 'A school must have at least 300 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means not below.', '{"why":"At least 300 means the total must be greater than or equal to 300.","sol":"Step 1: The total number of learners is x + y.\nStep 2: The minimum required is 300.\nStep 3: Therefore the total must be 300 or more.\nStep 4: So x + y ≥ 300.","steps":["Step 1: The total number of learners is x + y.","Step 2: The minimum required is 300.","Step 3: Therefore the total must be 300 or more.","Step 4: So x + y ≥ 300."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 1),
  (370, 100, 'A factory has no more than 120 kg of material. If x and y are the amounts used for two products, write the constraint.', 'text', 1, 'No more than means the same idea as at most.', '{"why":"No more than means less than or equal to.","sol":"Step 1: Total material used is x + y.\nStep 2: The available amount is 120 kg.\nStep 3: The amount used cannot exceed 120 kg.\nStep 4: Therefore x + y ≤ 120.","steps":["Step 1: Total material used is x + y.","Step 2: The available amount is 120 kg.","Step 3: The amount used cannot exceed 120 kg.","Step 4: Therefore x + y ≤ 120."],"options":[],"conceptId":"math_linear_programming_writing_a_constraint_from_a_statement","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing a Constraint from a Statement"}', 2),
  (371, 101, 'Does x = 6 satisfy x ≤ 10?', 'text', 1, 'Compare 6 with 10.', '{"why":"6 is less than 10.","sol":"Step 1: Substitute x = 6.\nStep 2: We get 6 ≤ 10.\nStep 3: This statement is true.\nStep 4: Therefore x = 6 satisfies the inequality.","steps":["Step 1: Substitute x = 6.","Step 2: We get 6 ≤ 10.","Step 3: This statement is true.","Step 4: Therefore x = 6 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 0),
  (372, 101, 'Does x = 10 satisfy x ≤ 10?', 'text', 1, 'Remember that ≤ includes equality.', '{"why":"The symbol ≤ allows the value to equal 10.","sol":"Step 1: Substitute x = 10.\nStep 2: We get 10 ≤ 10.\nStep 3: Equality is allowed by ≤.\nStep 4: Therefore x = 10 satisfies the inequality.","steps":["Step 1: Substitute x = 10.","Step 2: We get 10 ≤ 10.","Step 3: Equality is allowed by ≤.","Step 4: Therefore x = 10 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 1),
  (373, 101, 'Does x = 11 satisfy x ≤ 10?', 'text', 1, 'Is 11 less than or equal to 10?', '{"why":"11 is greater than 10.","sol":"Step 1: Substitute x = 11.\nStep 2: We get 11 ≤ 10.\nStep 3: This is false.\nStep 4: Therefore x = 11 does not satisfy the inequality.","steps":["Step 1: Substitute x = 11.","Step 2: We get 11 ≤ 10.","Step 3: This is false.","Step 4: Therefore x = 11 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_less_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Less Than or Equal To"}', 2),
  (374, 102, 'Does x = 30 satisfy x ≥ 20?', 'text', 1, 'Is 30 greater than or equal to 20?', '{"why":"30 is greater than 20.","sol":"Step 1: Substitute x = 30.\nStep 2: We get 30 ≥ 20.\nStep 3: This is true.\nStep 4: Therefore x = 30 satisfies the inequality.","steps":["Step 1: Substitute x = 30.","Step 2: We get 30 ≥ 20.","Step 3: This is true.","Step 4: Therefore x = 30 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 0),
  (375, 102, 'Does x = 20 satisfy x ≥ 20?', 'text', 1, 'Does ≥ include equality?', '{"why":"The symbol ≥ includes equality.","sol":"Step 1: Substitute x = 20.\nStep 2: We get 20 ≥ 20.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 20 satisfies the inequality.","steps":["Step 1: Substitute x = 20.","Step 2: We get 20 ≥ 20.","Step 3: Equality is allowed.","Step 4: Therefore x = 20 satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 1),
  (376, 102, 'Does x = 18 satisfy x ≥ 20?', 'text', 1, 'Compare 18 and 20.', '{"why":"18 is less than 20.","sol":"Step 1: Substitute x = 18.\nStep 2: We get 18 ≥ 20.\nStep 3: This is false.\nStep 4: Therefore x = 18 does not satisfy the inequality.","steps":["Step 1: Substitute x = 18.","Step 2: We get 18 ≥ 20.","Step 3: This is false.","Step 4: Therefore x = 18 does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_meaning_of_greater_than_or_equal_to","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Greater Than or Equal To"}', 2),
  (377, 103, 'If x represents the number of desks produced, write its non-negativity constraint.', 'text', 1, 'The number of desks cannot be negative.', '{"why":"The quantity represented by x cannot be negative.","sol":"Step 1: x represents a quantity.\nStep 2: A quantity of desks cannot be below zero.\nStep 3: Therefore x must be at least zero.","steps":["Step 1: x represents a quantity.","Step 2: A quantity of desks cannot be below zero.","Step 3: Therefore x must be at least zero."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 0),
  (378, 103, 'If y represents kilograms of flour used, can y = -5 satisfy the non-negativity constraint?', 'text', 1, 'Check whether -5 is greater than or equal to zero.', '{"why":"A negative quantity does not satisfy the non-negativity constraint.","sol":"Step 1: The constraint is y ≥ 0.\nStep 2: Substitute y = -5.\nStep 3: We get -5 ≥ 0.\nStep 4: This is false.","steps":["Step 1: The constraint is y ≥ 0.","Step 2: Substitute y = -5.","Step 3: We get -5 ≥ 0.","Step 4: This is false."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 1),
  (379, 103, 'Does x = 0 satisfy x ≥ 0?', 'text', 1, 'The symbol ≥ includes equality.', '{"why":"Non-negativity allows zero.","sol":"Step 1: Substitute x = 0.\nStep 2: We get 0 ≥ 0.\nStep 3: Equality is allowed.\nStep 4: Therefore x = 0 is allowed.","steps":["Step 1: Substitute x = 0.","Step 2: We get 0 ≥ 0.","Step 3: Equality is allowed.","Step 4: Therefore x = 0 is allowed."],"options":[],"conceptId":"math_linear_programming_non_negativity_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Non-Negativity Constraints"}', 2),
  (380, 104, 'A farmer has at most 25 hectares for two crops. What is the constraint if x and y are the hectares used?', 'text', 1, 'Identify the condition that limits the total land.', '{"why":"The 25 hectares limit the total amount of land that can be used.","sol":"Step 1: The total land used is x + y.\nStep 2: The farmer has at most 25 hectares.\nStep 3: The total cannot exceed 25.\nStep 4: Therefore x + y ≤ 25.","steps":["Step 1: The total land used is x + y.","Step 2: The farmer has at most 25 hectares.","Step 3: The total cannot exceed 25.","Step 4: Therefore x + y ≤ 25."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 0),
  (381, 104, 'A factory has no more than 90 hours available. If x and y are hours used for two activities, write the constraint.', 'text', 1, 'No more than means the total cannot exceed the available amount.', '{"why":"The available time places a maximum on the total time used.","sol":"Step 1: Total time used is x + y.\nStep 2: The maximum available time is 90 hours.\nStep 3: Therefore x + y ≤ 90.","steps":["Step 1: Total time used is x + y.","Step 2: The maximum available time is 90 hours.","Step 3: Therefore x + y ≤ 90."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 1),
  (382, 104, 'A school requires at least 400 learners in two programmes. If x and y are the numbers of learners, write the constraint.', 'text', 1, 'At least means the total must reach or exceed the number.', '{"why":"The school requires a minimum total of 400 learners.","sol":"Step 1: Total learners are x + y.\nStep 2: The minimum required is 400.\nStep 3: Therefore the total must be at least 400.\nStep 4: So x + y ≥ 400.","steps":["Step 1: Total learners are x + y.","Step 2: The minimum required is 400.","Step 3: Therefore the total must be at least 400.","Step 4: So x + y ≥ 400."],"options":[],"conceptId":"math_linear_programming_identifying_constraints_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying Constraints in a Word Problem"}', 2),
  (383, 105, 'A farmer has at most 30 hectares. Is x + y ≥ 30 the correct constraint?', 'text', 1, 'Try a value greater than 30.', '{"why":"At most means the total cannot exceed 30.","sol":"Step 1: At most 30 means values greater than 30 must not be allowed.\nStep 2: But x + y ≥ 30 allows 40, 50, and other larger values.\nStep 3: Therefore it does not represent the condition.\nStep 4: The correct inequality is x + y ≤ 30.","steps":["Step 1: At most 30 means values greater than 30 must not be allowed.","Step 2: But x + y ≥ 30 allows 40, 50, and other larger values.","Step 3: Therefore it does not represent the condition.","Step 4: The correct inequality is x + y ≤ 30."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 0),
  (384, 105, 'A school needs at least 200 learners. Is x + y ≥ 200 correct?', 'text', 1, 'Check whether the inequality allows 200 and values above 200.', '{"why":"Greater than or equal to represents at least.","sol":"Step 1: At least 200 means 200 is allowed.\nStep 2: Values greater than 200 must also be allowed.\nStep 3: x + y ≥ 200 allows exactly these values.\nStep 4: Therefore it is correct.","steps":["Step 1: At least 200 means 200 is allowed.","Step 2: Values greater than 200 must also be allowed.","Step 3: x + y ≥ 200 allows exactly these values.","Step 4: Therefore it is correct."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 1),
  (385, 105, 'A factory has no more than 70 kg of material. Does x + y ≤ 70 represent this condition?', 'text', 1, 'Check values below, equal to, and above 70.', '{"why":"Less than or equal to represents no more than.","sol":"Step 1: Values below 70 are allowed.\nStep 2: 70 itself is allowed.\nStep 3: Values above 70 are not allowed.\nStep 4: That exactly matches no more than 70.","steps":["Step 1: Values below 70 are allowed.","Step 2: 70 itself is allowed.","Step 3: Values above 70 are not allowed.","Step 4: That exactly matches no more than 70."],"options":[],"conceptId":"math_linear_programming_checking_whether_an_inequality_matches_a_condition","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether an Inequality Matches a Condition"}', 2),
  (386, 106, 'A farmer uses x hectares for maize and y hectares for beans. There are at most 50 hectares available. Write the complete basic set of constraints.', 'text', 1, 'Include the land restriction and non-negativity.', '{"why":"All three conditions are required for an acceptable choice.","sol":"Step 1: The total land is x + y.\nStep 2: At most 50 hectares gives x + y ≤ 50.\nStep 3: Land cannot be negative, so x ≥ 0.\nStep 4: Land cannot be negative, so y ≥ 0.","steps":["Step 1: The total land is x + y.","Step 2: At most 50 hectares gives x + y ≤ 50.","Step 3: Land cannot be negative, so x ≥ 0.","Step 4: Land cannot be negative, so y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 0),
  (387, 106, 'A factory produces x units of A and y units of B. It can produce at most 120 units. Write the complete basic constraints.', 'text', 1, 'Do not forget the meaning of the quantities.', '{"why":"The production limit and non-negativity together define the basic restrictions.","sol":"Step 1: Total production is x + y.\nStep 2: At most 120 gives x + y ≤ 120.\nStep 3: Production cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: Total production is x + y.","Step 2: At most 120 gives x + y ≤ 120.","Step 3: Production cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 1),
  (388, 106, 'A school requires at least 600 learners in two programmes. Let x and y be the numbers of learners. Write the complete basic set of constraints.', 'text', 1, 'Translate at least first, then add non-negativity.', '{"why":"The complete set must contain the total requirement and the non-negativity restrictions.","sol":"Step 1: The total number of learners is x + y.\nStep 2: At least 600 gives x + y ≥ 600.\nStep 3: Numbers of learners cannot be negative.\nStep 4: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The total number of learners is x + y.","Step 2: At least 600 gives x + y ≥ 600.","Step 3: Numbers of learners cannot be negative.","Step 4: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_writing_the_complete_set_of_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Writing the Complete Set of Constraints"}', 2),
  (389, 107, 'Find the boundary equation for x + y ≤ 8.', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary contains the points where the inequality reaches its limit.","sol":"Step 1: Start with x + y ≤ 8.\nStep 2: The boundary occurs at the limit.\nStep 3: Replace ≤ with =.\nStep 4: Therefore x + y = 8.","steps":["Step 1: Start with x + y ≤ 8.","Step 2: The boundary occurs at the limit.","Step 3: Replace ≤ with =.","Step 4: Therefore x + y = 8."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 0),
  (390, 107, 'Find the boundary equation for 2x + 3y ≥ 12.', 'text', 1, 'Only change the inequality symbol to =.', '{"why":"The equality gives the line separating the two regions.","sol":"Step 1: Start with 2x + 3y ≥ 12.\nStep 2: Replace ≥ with =.\nStep 3: Therefore 2x + 3y = 12.","steps":["Step 1: Start with 2x + 3y ≥ 12.","Step 2: Replace ≥ with =.","Step 3: Therefore 2x + 3y = 12."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 1),
  (391, 107, 'What is the boundary equation of 4x + y ≤ 20?', 'text', 1, 'Replace ≤ with =.', '{"why":"The boundary is formed where the inequality becomes an equality.","sol":"Step 1: Start with 4x + y ≤ 20.\nStep 2: Replace ≤ by =.\nStep 3: The boundary is 4x + y = 20.","steps":["Step 1: Start with 4x + y ≤ 20.","Step 2: Replace ≤ by =.","Step 3: The boundary is 4x + y = 20."],"options":[],"conceptId":"math_linear_programming_turning_an_inequality_into_a_boundary_equation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Turning an Inequality into a Boundary Equation"}', 2),
  (392, 108, 'Find the x-intercept of x + y = 7.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: x + 0 = 7.\nStep 3: Therefore x = 7.\nStep 4: The point is (7, 0).","steps":["Step 1: Set y = 0.","Step 2: x + 0 = 7.","Step 3: Therefore x = 7.","Step 4: The point is (7, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 0),
  (393, 108, 'Find the x-intercept of 2x + y = 10.', 'text', 1, 'Put y = 0.', '{"why":"Setting y = 0 gives the point where the line crosses the x-axis.","sol":"Step 1: Set y = 0.\nStep 2: 2x + 0 = 10.\nStep 3: 2x = 10.\nStep 4: x = 5.\nStep 5: Therefore the point is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 2x + 0 = 10.","Step 3: 2x = 10.","Step 4: x = 5.","Step 5: Therefore the point is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 1),
  (394, 108, 'Find the x-intercept of 4x + 2y = 20.', 'text', 1, 'Set y = 0 and solve for x.', '{"why":"The x-intercept always has y-coordinate zero.","sol":"Step 1: Set y = 0.\nStep 2: 4x + 2(0) = 20.\nStep 3: 4x = 20.\nStep 4: x = 5.\nStep 5: Therefore the x-intercept is (5, 0).","steps":["Step 1: Set y = 0.","Step 2: 4x + 2(0) = 20.","Step 3: 4x = 20.","Step 4: x = 5.","Step 5: Therefore the x-intercept is (5, 0)."],"options":[],"conceptId":"math_linear_programming_finding_the_x_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the x-Intercept"}', 2),
  (395, 109, 'Find the y-intercept of x + y = 8.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 0 + y = 8.\nStep 3: Therefore y = 8.\nStep 4: The point is (0, 8).","steps":["Step 1: Set x = 0.","Step 2: 0 + y = 8.","Step 3: Therefore y = 8.","Step 4: The point is (0, 8)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 0),
  (396, 109, 'Find the y-intercept of 2x + y = 14.', 'text', 1, 'Put x = 0.', '{"why":"Setting x = 0 gives the point where the line crosses the y-axis.","sol":"Step 1: Set x = 0.\nStep 2: 2(0) + y = 14.\nStep 3: Therefore y = 14.\nStep 4: The point is (0, 14).","steps":["Step 1: Set x = 0.","Step 2: 2(0) + y = 14.","Step 3: Therefore y = 14.","Step 4: The point is (0, 14)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 1),
  (397, 109, 'Find the y-intercept of 4x + 2y = 20.', 'text', 1, 'Set x = 0 and solve for y.', '{"why":"The y-intercept always has x-coordinate zero.","sol":"Step 1: Set x = 0.\nStep 2: 4(0) + 2y = 20.\nStep 3: 2y = 20.\nStep 4: y = 10.\nStep 5: Therefore the y-intercept is (0, 10).","steps":["Step 1: Set x = 0.","Step 2: 4(0) + 2y = 20.","Step 3: 2y = 20.","Step 4: y = 10.","Step 5: Therefore the y-intercept is (0, 10)."],"options":[],"conceptId":"math_linear_programming_finding_the_y_intercept","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the y-Intercept"}', 2),
  (398, 110, 'Draw the boundary line x + y = 6. Which two intercepts should you plot?', 'text', 1, 'Find the x-intercept and y-intercept.', '{"why":"These two points lie on the boundary line and are easy to obtain.","sol":"Step 1: For the x-intercept, set y = 0.\nStep 2: Then x = 6, giving (6,0).\nStep 3: For the y-intercept, set x = 0.\nStep 4: Then y = 6, giving (0,6).","steps":["Step 1: For the x-intercept, set y = 0.","Step 2: Then x = 6, giving (6,0).","Step 3: For the y-intercept, set x = 0.","Step 4: Then y = 6, giving (0,6)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 0),
  (399, 110, 'Find the two intercepts needed to draw 2x + y = 10.', 'text', 1, 'Set y = 0 for the x-intercept and x = 0 for the y-intercept.', '{"why":"The line is determined by these two intercepts.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 1),
  (400, 110, 'Find the two intercepts of 3x + y = 12.', 'text', 1, 'Use y = 0 and then x = 0.', '{"why":"The two intercepts provide the two points needed to draw the boundary.","sol":"Step 1: Set y = 0: 3x = 12, so x = 4.\nStep 2: The x-intercept is (4,0).\nStep 3: Set x = 0: y = 12.\nStep 4: The y-intercept is (0,12).","steps":["Step 1: Set y = 0: 3x = 12, so x = 4.","Step 2: The x-intercept is (4,0).","Step 3: Set x = 0: y = 12.","Step 4: The y-intercept is (0,12)."],"options":[],"conceptId":"math_linear_programming_drawing_a_boundary_line_from_its_intercepts","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Drawing a Boundary Line from Its Intercepts"}', 2),
  (401, 111, 'Should the boundary of x + y ≤ 10 be solid or broken?', 'text', 1, 'Does ≤ include equality?', '{"why":"≤ includes equality.","sol":"Step 1: The inequality is ≤.\nStep 2: Equality is included.\nStep 3: Therefore points on the boundary are included.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≤.","Step 2: Equality is included.","Step 3: Therefore points on the boundary are included.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 0),
  (402, 111, 'Should the boundary of 2x + y ≥ 8 be solid or broken?', 'text', 1, 'Check whether ≥ includes equality.', '{"why":"≥ includes equality.","sol":"Step 1: The inequality is ≥.\nStep 2: Equality is included.\nStep 3: Therefore the boundary belongs to the solution.\nStep 4: Use a solid line.","steps":["Step 1: The inequality is ≥.","Step 2: Equality is included.","Step 3: Therefore the boundary belongs to the solution.","Step 4: Use a solid line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 1),
  (403, 111, 'Should the boundary of x + y > 5 be solid or broken?', 'text', 1, 'Is equality included in >?', '{"why":"> excludes equality.","sol":"Step 1: The inequality is >.\nStep 2: Equality is not included.\nStep 3: Therefore the boundary itself is excluded.\nStep 4: Use a broken line.","steps":["Step 1: The inequality is >.","Step 2: Equality is not included.","Step 3: Therefore the boundary itself is excluded.","Step 4: Use a broken line."],"options":[],"conceptId":"math_linear_programming_solid_and_broken_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Solid and Broken Boundary Lines"}', 2),
  (404, 112, 'Does (0,0) satisfy x + y ≤ 12?', 'text', 1, 'Substitute x = 0 and y = 0.', '{"why":"The point makes the inequality true.","sol":"Step 1: 0 + 0 ≤ 12.\nStep 2: 0 ≤ 12 is true.\nStep 3: Therefore (0,0) satisfies the inequality.","steps":["Step 1: 0 + 0 ≤ 12.","Step 2: 0 ≤ 12 is true.","Step 3: Therefore (0,0) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 0),
  (405, 112, 'Does (0,0) satisfy 2x + y ≥ 10?', 'text', 1, 'Substitute both coordinates.', '{"why":"The inequality becomes false at (0,0).","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore (0,0) does not satisfy the inequality.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore (0,0) does not satisfy the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 1),
  (406, 112, 'Does (2,4) satisfy x + y ≤ 8?', 'text', 1, 'Calculate 2 + 4 first.', '{"why":"The point makes the inequality true.","sol":"Step 1: Substitute x = 2 and y = 4.\nStep 2: 2 + 4 ≤ 8.\nStep 3: 6 ≤ 8 is true.\nStep 4: Therefore (2,4) satisfies the inequality.","steps":["Step 1: Substitute x = 2 and y = 4.","Step 2: 2 + 4 ≤ 8.","Step 3: 6 ≤ 8 is true.","Step 4: Therefore (2,4) satisfies the inequality."],"options":[],"conceptId":"math_linear_programming_testing_a_point_in_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Testing a Point in an Inequality"}', 2),
  (407, 113, 'For x + y ≤ 6, does the region containing (0,0) satisfy the inequality?', 'text', 1, 'Test (0,0).', '{"why":"The test point satisfies the inequality.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 6.\nStep 3: 0 ≤ 6 is true.\nStep 4: Therefore the region containing (0,0) is the solution region.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 6.","Step 3: 0 ≤ 6 is true.","Step 4: Therefore the region containing (0,0) is the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 0),
  (408, 113, 'For 2x + y ≤ 10, should the side containing (0,0) be shaded?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point makes the inequality true.","sol":"Step 1: 2(0) + 0 ≤ 10.\nStep 2: 0 ≤ 10 is true.\nStep 3: Therefore (0,0) is in the solution region.\nStep 4: Shade the side containing (0,0).","steps":["Step 1: 2(0) + 0 ≤ 10.","Step 2: 0 ≤ 10 is true.","Step 3: Therefore (0,0) is in the solution region.","Step 4: Shade the side containing (0,0)."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 1),
  (409, 113, 'Why is testing a point safer than simply memorising ''shade below the line''?', 'text', 1, 'Think about lines with different slopes and rearrangements.', '{"why":"Testing a point works regardless of the orientation of the boundary line.","sol":"Step 1: Different inequalities can have different line arrangements.\nStep 2: The words above and below can become misleading.\nStep 3: A test point directly checks whether a region satisfies the original inequality.\nStep 4: Therefore testing is more reliable.","steps":["Step 1: Different inequalities can have different line arrangements.","Step 2: The words above and below can become misleading.","Step 3: A test point directly checks whether a region satisfies the original inequality.","Step 4: Therefore testing is more reliable."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≤"}', 2),
  (410, 114, 'For x + y ≥ 8, does (0,0) lie in the solution region?', 'text', 1, 'Test the point.', '{"why":"The point does not satisfy the inequality.","sol":"Step 1: 0 + 0 ≥ 8.\nStep 2: 0 ≥ 8 is false.\nStep 3: Therefore (0,0) is not in the solution region.","steps":["Step 1: 0 + 0 ≥ 8.","Step 2: 0 ≥ 8 is false.","Step 3: Therefore (0,0) is not in the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 0),
  (411, 114, 'For 2x + y ≥ 10, is the region containing (0,0) the solution region?', 'text', 1, 'Substitute (0,0).', '{"why":"The test point fails the inequality.","sol":"Step 1: 2(0) + 0 ≥ 10.\nStep 2: 0 ≥ 10 is false.\nStep 3: Therefore the region containing (0,0) is not the solution region.","steps":["Step 1: 2(0) + 0 ≥ 10.","Step 2: 0 ≥ 10 is false.","Step 3: Therefore the region containing (0,0) is not the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 1),
  (412, 114, 'For x + y ≥ 6, does (4,3) belong to the solution region?', 'text', 1, 'Calculate 4 + 3.', '{"why":"The coordinates make the inequality true.","sol":"Step 1: 4 + 3 ≥ 6.\nStep 2: 7 ≥ 6 is true.\nStep 3: Therefore (4,3) belongs to the solution region.","steps":["Step 1: 4 + 3 ≥ 6.","Step 2: 7 ≥ 6 is true.","Step 3: Therefore (4,3) belongs to the solution region."],"options":[],"conceptId":"math_linear_programming_shading_the_region_for","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Shading the Region for ≥"}', 2),
  (413, 115, 'Find the two intercepts of 2x + 3y = 12.', 'text', 1, 'Set y = 0, then set x = 0.', '{"why":"The coefficients determine the intercepts.","sol":"Step 1: For the x-intercept, y = 0.\nStep 2: 2x = 12, so x = 6.\nStep 3: Therefore the x-intercept is (6,0).\nStep 4: For the y-intercept, x = 0.\nStep 5: 3y = 12, so y = 4.\nStep 6: Therefore the y-intercept is (0,4).","steps":["Step 1: For the x-intercept, y = 0.","Step 2: 2x = 12, so x = 6.","Step 3: Therefore the x-intercept is (6,0).","Step 4: For the y-intercept, x = 0.","Step 5: 3y = 12, so y = 4.","Step 6: Therefore the y-intercept is (0,4)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 0),
  (414, 115, 'Find the x-intercept of 5x + 2y = 20.', 'text', 1, 'Set y = 0.', '{"why":"The x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 5x = 20.\nStep 3: x = 4.\nStep 4: Therefore the x-intercept is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 5x = 20.","Step 3: x = 4.","Step 4: Therefore the x-intercept is (4,0)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 1),
  (415, 115, 'Find the y-intercept of 3x + 4y = 24.', 'text', 1, 'Set x = 0.', '{"why":"The y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: 4y = 24.\nStep 3: y = 6.\nStep 4: Therefore the y-intercept is (0,6).","steps":["Step 1: Set x = 0.","Step 2: 4y = 24.","Step 3: y = 6.","Step 4: Therefore the y-intercept is (0,6)."],"options":[],"conceptId":"math_linear_programming_graphing_an_inequality_with_different_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing an Inequality with Different Coefficients"}', 2),
  (416, 116, 'A point must satisfy x + y ≤ 10 and x ≥ 2. Does (1,4) satisfy both?', 'text', 1, 'Test the point in each inequality separately.', '{"why":"A feasible point must satisfy every constraint.","sol":"Step 1: First: 1 + 4 ≤ 10, which is true.\nStep 2: Second: 1 ≥ 2, which is false.\nStep 3: Because one condition fails, the point is not in the common region.","steps":["Step 1: First: 1 + 4 ≤ 10, which is true.","Step 2: Second: 1 ≥ 2, which is false.","Step 3: Because one condition fails, the point is not in the common region."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 0),
  (417, 116, 'Does (3,4) satisfy x + y ≤ 10 and x ≥ 2?', 'text', 1, 'Check both inequalities.', '{"why":"The point lies in the overlap of the two solution regions.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 2 is also true.\nStep 3: Therefore the point satisfies both constraints.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 2 is also true.","Step 3: Therefore the point satisfies both constraints."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 1),
  (418, 116, 'Why do we need the overlap when graphing two inequalities?', 'text', 1, 'Think about what ''satisfying both'' means.', '{"why":"The intersection of the regions represents choices that obey every constraint.","sol":"Step 1: Each inequality imposes a separate condition.\nStep 2: A valid point must obey the first condition.\nStep 3: It must also obey the second condition.\nStep 4: Therefore only the common region is acceptable.","steps":["Step 1: Each inequality imposes a separate condition.","Step 2: A valid point must obey the first condition.","Step 3: It must also obey the second condition.","Step 4: Therefore only the common region is acceptable."],"options":[],"conceptId":"math_linear_programming_graphing_two_inequalities_together","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphing Two Inequalities Together"}', 2),
  (419, 117, 'What is a feasible region?', 'text', 1, 'Think about all the constraints together.', '{"why":"Feasibility means that a choice obeys all restrictions.","sol":"Step 1: Each constraint limits the possible choices.\nStep 2: A feasible point must satisfy every constraint.\nStep 3: The collection of all such points forms the feasible region.","steps":["Step 1: Each constraint limits the possible choices.","Step 2: A feasible point must satisfy every constraint.","Step 3: The collection of all such points forms the feasible region."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 0),
  (420, 117, 'Does the point (3,4) satisfy x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"A point is feasible when every constraint is satisfied.","sol":"Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.\nStep 2: 3 ≥ 0 is true.\nStep 3: 4 ≥ 0 is true.\nStep 4: Therefore the point satisfies every constraint.","steps":["Step 1: 3 + 4 ≤ 10 gives 7 ≤ 10, true.","Step 2: 3 ≥ 0 is true.","Step 3: 4 ≥ 0 is true.","Step 4: Therefore the point satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 1),
  (421, 117, 'A point satisfies two constraints but violates a third. Is it feasible?', 'text', 1, 'Feasible means all conditions must hold.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: Every constraint must be satisfied.\nStep 2: The point violates one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: Every constraint must be satisfied.","Step 2: The point violates one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_meaning_of_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of the Feasible Region"}', 2),
  (422, 118, 'If two inequalities are graphed, what part of the graph is feasible?', 'text', 1, 'Think about what both inequalities require.', '{"why":"The feasible region must satisfy all constraints.","sol":"Step 1: Each inequality creates a solution region.\nStep 2: A feasible point must satisfy both.\nStep 3: Therefore the overlapping part is feasible.","steps":["Step 1: Each inequality creates a solution region.","Step 2: A feasible point must satisfy both.","Step 3: Therefore the overlapping part is feasible."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 0),
  (423, 118, 'If x ≥ 0 and y ≥ 0 are constraints, which part of the coordinate plane can contain feasible points?', 'text', 1, 'Think about the signs of x and y.', '{"why":"Both coordinates must be zero or positive.","sol":"Step 1: x ≥ 0 means x cannot be negative.\nStep 2: y ≥ 0 means y cannot be negative.\nStep 3: Therefore both coordinates must be non-negative.\nStep 4: This is the first quadrant together with its axes.","steps":["Step 1: x ≥ 0 means x cannot be negative.","Step 2: y ≥ 0 means y cannot be negative.","Step 3: Therefore both coordinates must be non-negative.","Step 4: This is the first quadrant together with its axes."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 1),
  (424, 118, 'A point lies in the region satisfying the first constraint but outside the region satisfying the second. Is it feasible?', 'text', 1, 'Does it satisfy every condition?', '{"why":"Feasibility requires all constraints to be satisfied.","sol":"Step 1: The point satisfies the first condition.\nStep 2: It violates the second condition.\nStep 3: Therefore it does not satisfy all constraints.","steps":["Step 1: The point satisfies the first condition.","Step 2: It violates the second condition.","Step 3: Therefore it does not satisfy all constraints."],"options":[],"conceptId":"math_linear_programming_identifying_the_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Feasible Region"}', 2),
  (425, 119, 'Is (2,6) feasible for x + y ≤ 10, x ≥ 0 and y ≥ 0?', 'text', 1, 'Check all three conditions.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.\nStep 2: 2 ≥ 0 is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: All constraints are satisfied.","steps":["Step 1: 2 + 6 ≤ 10 gives 8 ≤ 10, true.","Step 2: 2 ≥ 0 is true.","Step 3: 6 ≥ 0 is true.","Step 4: All constraints are satisfied."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 0),
  (426, 119, 'Is (1,5) feasible for x + y ≤ 10 and x ≥ 2?', 'text', 1, 'One constraint may fail.', '{"why":"The point violates x ≥ 2.","sol":"Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.\nStep 2: But 1 ≥ 2 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 1 + 5 ≤ 10 gives 6 ≤ 10, true.","Step 2: But 1 ≥ 2 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 1),
  (427, 119, 'Is (5,4) feasible for 2x + y ≤ 12, x ≥ 0 and y ≥ 0?', 'text', 1, 'Start with 2x + y.', '{"why":"The point violates the first constraint.","sol":"Step 1: 2(5) + 4 = 14.\nStep 2: 14 ≤ 12 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 2(5) + 4 = 14.","Step 2: 14 ≤ 12 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_point_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Point Is Feasible"}', 2),
  (428, 120, 'For x + y ≤ 8, x ≥ 0 and y ≥ 0, which side of x + y = 8 contains the feasible region?', 'text', 1, 'Test the origin.', '{"why":"The origin satisfies the inequality and the non-negativity constraints.","sol":"Step 1: Substitute (0,0).\nStep 2: 0 + 0 ≤ 8 is true.\nStep 3: Therefore the side containing (0,0) satisfies the inequality.\nStep 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible.","steps":["Step 1: Substitute (0,0).","Step 2: 0 + 0 ≤ 8 is true.","Step 3: Therefore the side containing (0,0) satisfies the inequality.","Step 4: Because x and y must also be non-negative, only the first-quadrant portion is feasible."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 0),
  (429, 120, 'For 2x + y ≤ 10, x ≥ 0 and y ≥ 0, find the boundary intercepts.', 'text', 1, 'Set y = 0 and then x = 0.', '{"why":"These are the axis points of the boundary.","sol":"Step 1: Set y = 0: 2x = 10, so x = 5.\nStep 2: The x-intercept is (5,0).\nStep 3: Set x = 0: y = 10.\nStep 4: The y-intercept is (0,10).","steps":["Step 1: Set y = 0: 2x = 10, so x = 5.","Step 2: The x-intercept is (5,0).","Step 3: Set x = 0: y = 10.","Step 4: The y-intercept is (0,10)."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 1),
  (430, 120, 'What must be true of every point inside the feasible region?', 'text', 1, 'Think about the definition of feasible.', '{"why":"The feasible region is the common solution to all constraints.","sol":"Step 1: A feasible point is an allowed choice.\nStep 2: Every restriction must be satisfied.\nStep 3: Therefore every point in the feasible region satisfies every constraint.","steps":["Step 1: A feasible point is an allowed choice.","Step 2: Every restriction must be satisfied.","Step 3: Therefore every point in the feasible region satisfies every constraint."],"options":[],"conceptId":"math_linear_programming_constructing_a_feasible_region_from_three_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Constructing a Feasible Region from Three Constraints"}', 2),
  (431, 121, 'If x represents shirts and y represents trousers, what does the point (6,4) represent?', 'text', 1, 'Read the x-coordinate first and the y-coordinate second.', '{"why":"Coordinates give the values of the decision variables.","sol":"Step 1: The x-coordinate is 6.\nStep 2: x represents shirts.\nStep 3: The y-coordinate is 4.\nStep 4: y represents trousers.","steps":["Step 1: The x-coordinate is 6.","Step 2: x represents shirts.","Step 3: The y-coordinate is 4.","Step 4: y represents trousers."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 0),
  (432, 121, 'If x represents hectares of maize and y represents hectares of beans, what does (3,7) mean?', 'text', 1, 'Match each coordinate to its variable.', '{"why":"The coordinates describe the chosen quantities.","sol":"Step 1: x = 3, so maize uses 3 hectares.\nStep 2: y = 7, so beans use 7 hectares.","steps":["Step 1: x = 3, so maize uses 3 hectares.","Step 2: y = 7, so beans use 7 hectares."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 1),
  (433, 121, 'If a point lies inside the feasible region, what does that tell us about the corresponding choice?', 'text', 1, 'Think about what feasible means.', '{"why":"The feasible region represents allowed combinations of the decision variables.","sol":"Step 1: Every point in the feasible region satisfies every constraint.\nStep 2: Therefore the corresponding choice obeys all restrictions.","steps":["Step 1: Every point in the feasible region satisfies every constraint.","Step 2: Therefore the corresponding choice obeys all restrictions."],"options":[],"conceptId":"math_linear_programming_reading_a_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Reading a Feasible Region"}', 2),
  (434, 122, 'What does x + y = 50 represent if x and y are quantities of two products?', 'text', 1, 'Look at the equality.', '{"why":"The boundary equation represents the limiting value itself.","sol":"Step 1: x + y gives the total quantity.\nStep 2: The equality says the total is exactly 50.\nStep 3: Therefore the boundary represents combinations whose total is 50.","steps":["Step 1: x + y gives the total quantity.","Step 2: The equality says the total is exactly 50.","Step 3: Therefore the boundary represents combinations whose total is 50."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 0),
  (435, 122, 'For x + y ≤ 100, is (40,50) within the allowed region?', 'text', 1, 'Add the coordinates.', '{"why":"The total is below the maximum of 100.","sol":"Step 1: 40 + 50 = 90.\nStep 2: 90 ≤ 100 is true.\nStep 3: Therefore the point satisfies the constraint.","steps":["Step 1: 40 + 50 = 90.","Step 2: 90 ≤ 100 is true.","Step 3: Therefore the point satisfies the constraint."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 1),
  (436, 122, 'For x + y ≤ 100, is (70,40) allowed?', 'text', 1, 'Calculate the total first.', '{"why":"The total exceeds the maximum allowed value.","sol":"Step 1: 70 + 40 = 110.\nStep 2: 110 ≤ 100 is false.\nStep 3: Therefore the point is outside the allowed region.","steps":["Step 1: 70 + 40 = 110.","Step 2: 110 ≤ 100 is false.","Step 3: Therefore the point is outside the allowed region."],"options":[],"conceptId":"math_linear_programming_interpreting_the_boundary_and_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Interpreting the Boundary and Feasible Region"}', 2),
  (437, 123, 'Find where 2x + y = 8 meets the x-axis.', 'text', 1, 'Set y = 0.', '{"why":"Every point on the x-axis has y = 0.","sol":"Step 1: Set y = 0.\nStep 2: 2x = 8.\nStep 3: x = 4.\nStep 4: Therefore the point is (4,0).","steps":["Step 1: Set y = 0.","Step 2: 2x = 8.","Step 3: x = 4.","Step 4: Therefore the point is (4,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 0),
  (438, 123, 'Find where 2x + y = 8 meets the y-axis.', 'text', 1, 'Set x = 0.', '{"why":"Every point on the y-axis has x = 0.","sol":"Step 1: Set x = 0.\nStep 2: y = 8.\nStep 3: Therefore the point is (0,8).","steps":["Step 1: Set x = 0.","Step 2: y = 8.","Step 3: Therefore the point is (0,8)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 1),
  (439, 123, 'Find the x-axis point on 3x + y = 15.', 'text', 1, 'Set y = 0.', '{"why":"Setting y to zero gives the x-axis intersection.","sol":"Step 1: Set y = 0.\nStep 2: 3x = 15.\nStep 3: x = 5.\nStep 4: Therefore the point is (5,0).","steps":["Step 1: Set y = 0.","Step 2: 3x = 15.","Step 3: x = 5.","Step 4: Therefore the point is (5,0)."],"options":[],"conceptId":"math_linear_programming_finding_a_corner_point_on_an_axis","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding a Corner Point on an Axis"}', 2),
  (440, 124, 'Find the intersection of x + y = 6 and x + 2y = 10.', 'text', 1, 'Subtract the first equation from the second.', '{"why":"The point satisfies both boundary equations.","sol":"Step 1: (x + 2y) - (x + y) = 10 - 6.\nStep 2: y = 4.\nStep 3: Substitute into x + y = 6.\nStep 4: x + 4 = 6.\nStep 5: x = 2.\nStep 6: Therefore the intersection is (2,4).","steps":["Step 1: (x + 2y) - (x + y) = 10 - 6.","Step 2: y = 4.","Step 3: Substitute into x + y = 6.","Step 4: x + 4 = 6.","Step 5: x = 2.","Step 6: Therefore the intersection is (2,4)."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 0),
  (441, 124, 'Find the intersection of 2x + y = 9 and x + y = 6.', 'text', 1, 'Subtract the second equation from the first.', '{"why":"The point lies on both boundary lines.","sol":"Step 1: (2x + y) - (x + y) = 9 - 6.\nStep 2: x = 3.\nStep 3: Substitute into x + y = 6.\nStep 4: 3 + y = 6.\nStep 5: y = 3.","steps":["Step 1: (2x + y) - (x + y) = 9 - 6.","Step 2: x = 3.","Step 3: Substitute into x + y = 6.","Step 4: 3 + y = 6.","Step 5: y = 3."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 1),
  (442, 124, 'Why must an intersection point still be checked against the other constraints?', 'text', 1, 'A point can lie on two boundaries but violate another restriction.', '{"why":"A feasible corner must satisfy every constraint, not just the two equations that produced it.","sol":"Step 1: The intersection satisfies the two equations used to find it.\nStep 2: A linear programming problem may have additional constraints.\nStep 3: The point must satisfy those as well.\nStep 4: Therefore the intersection is only a candidate until checked.","steps":["Step 1: The intersection satisfies the two equations used to find it.","Step 2: A linear programming problem may have additional constraints.","Step 3: The point must satisfy those as well.","Step 4: Therefore the intersection is only a candidate until checked."],"options":[],"conceptId":"math_linear_programming_finding_the_intersection_of_two_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Intersection of Two Boundary Lines"}', 2),
  (443, 125, 'Is (6,4) feasible for x + y ≤ 10, x + 2y ≤ 14, x ≥ 0 and y ≥ 0?', 'text', 1, 'Test every condition.', '{"why":"The point satisfies every constraint.","sol":"Step 1: 6 + 4 = 10, so the first condition is true.\nStep 2: 6 + 2(4) = 14, so the second condition is true.\nStep 3: 6 ≥ 0 is true.\nStep 4: 4 ≥ 0 is true.\nStep 5: Therefore the point is feasible.","steps":["Step 1: 6 + 4 = 10, so the first condition is true.","Step 2: 6 + 2(4) = 14, so the second condition is true.","Step 3: 6 ≥ 0 is true.","Step 4: 4 ≥ 0 is true.","Step 5: Therefore the point is feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 0),
  (444, 125, 'Is (4,5) feasible for x + y ≤ 10 and x ≥ 5?', 'text', 1, 'One constraint fails.', '{"why":"A single violated constraint makes the point infeasible.","sol":"Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.\nStep 2: But 4 ≥ 5 is false.\nStep 3: Therefore the point is not feasible.","steps":["Step 1: 4 + 5 = 9, so x + y ≤ 10 is true.","Step 2: But 4 ≥ 5 is false.","Step 3: Therefore the point is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 1),
  (445, 125, 'Can (-2,4) be a feasible point when x ≥ 0 is a constraint?', 'text', 1, 'Check the x-coordinate.', '{"why":"The point violates the non-negativity constraint.","sol":"Step 1: The x-coordinate is -2.\nStep 2: The constraint requires x ≥ 0.\nStep 3: -2 ≥ 0 is false.\nStep 4: Therefore the point cannot be feasible.","steps":["Step 1: The x-coordinate is -2.","Step 2: The constraint requires x ≥ 0.","Step 3: -2 ≥ 0 is false.","Step 4: Therefore the point cannot be feasible."],"options":[],"conceptId":"math_linear_programming_checking_an_intersection_against_all_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking an Intersection Against All Constraints"}', 2),
  (446, 126, 'Find the three corner points for x + y ≤ 6, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find the two intercepts and include the origin.', '{"why":"The boundary and the coordinate axes form the triangular feasible region.","sol":"Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).\nStep 2: y-intercept: set x = 0, giving y = 6 → (0,6).\nStep 3: The axes meet at (0,0).\nStep 4: Therefore the corners are (0,0), (6,0), and (0,6).","steps":["Step 1: x-intercept: set y = 0, giving x = 6 → (6,0).","Step 2: y-intercept: set x = 0, giving y = 6 → (0,6).","Step 3: The axes meet at (0,0).","Step 4: Therefore the corners are (0,0), (6,0), and (0,6)."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 0),
  (447, 126, 'Find the axis corner points for 2x + y ≤ 12, x ≥ 0 and y ≥ 0.', 'text', 1, 'Find both intercepts.', '{"why":"These are the points where the boundary and axes meet.","sol":"Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).\nStep 2: Set x = 0: y = 12 → (0,12).\nStep 3: The origin is also a corner.","steps":["Step 1: Set y = 0: 2x = 12, so x = 6 → (6,0).","Step 2: Set x = 0: y = 12 → (0,12).","Step 3: The origin is also a corner."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 1),
  (448, 126, 'Why is (0,0) often a corner point when x ≥ 0 and y ≥ 0?', 'text', 1, 'Where do the x-axis and y-axis meet?', '{"why":"The non-negativity constraints make the axes boundaries of the feasible region.","sol":"Step 1: x ≥ 0 restricts the graph to the non-negative x side.\nStep 2: y ≥ 0 restricts it to the non-negative y side.\nStep 3: The two axes meet at (0,0).\nStep 4: Therefore the origin can form a corner of the feasible region.","steps":["Step 1: x ≥ 0 restricts the graph to the non-negative x side.","Step 2: y ≥ 0 restricts it to the non-negative y side.","Step 3: The two axes meet at (0,0).","Step 4: Therefore the origin can form a corner of the feasible region."],"options":[],"conceptId":"math_linear_programming_finding_corner_points_from_axes_and_boundary_lines","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding Corner Points from Axes and Boundary Lines"}', 2),
  (449, 127, 'A product gives KSh 400 profit per unit of x and KSh 300 profit per unit of y. What is the objective function?', 'text', 1, 'Multiply each profit per unit by the number of units.', '{"why":"The objective function represents the total profit.","sol":"Step 1: Profit from x units = 400x.\nStep 2: Profit from y units = 300y.\nStep 3: Add the two amounts.\nStep 4: Therefore P = 400x + 300y.","steps":["Step 1: Profit from x units = 400x.","Step 2: Profit from y units = 300y.","Step 3: Add the two amounts.","Step 4: Therefore P = 400x + 300y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 0),
  (450, 127, 'A company spends KSh 200 on each unit of x and KSh 500 on each unit of y. Write the total cost.', 'text', 1, 'Cost = cost per unit × number of units.', '{"why":"The expression represents the total cost.","sol":"Step 1: Cost of x units = 200x.\nStep 2: Cost of y units = 500y.\nStep 3: Add them.\nStep 4: C = 200x + 500y.","steps":["Step 1: Cost of x units = 200x.","Step 2: Cost of y units = 500y.","Step 3: Add them.","Step 4: C = 200x + 500y."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 1),
  (451, 127, 'If P = 700x + 400y represents profit, and the aim is to obtain the greatest profit, what should be done to P?', 'text', 1, 'The greatest value is the maximum.', '{"why":"The objective is to make profit as large as possible.","sol":"Step 1: P represents profit.\nStep 2: The aim is to obtain the greatest profit.\nStep 3: Therefore P must be maximized.","steps":["Step 1: P represents profit.","Step 2: The aim is to obtain the greatest profit.","Step 3: Therefore P must be maximized."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Objective Function"}', 2),
  (452, 128, 'A company wants to obtain the greatest profit. What is the objective?', 'text', 1, 'What quantity is being made greatest?', '{"why":"Profit is the quantity the company wants to maximize.","sol":"Step 1: Read the phrase ''greatest profit''.\nStep 2: The quantity being considered is profit.\nStep 3: Therefore the objective is profit.","steps":["Step 1: Read the phrase ''greatest profit''.","Step 2: The quantity being considered is profit.","Step 3: Therefore the objective is profit."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 0),
  (453, 128, 'A manufacturer wants to spend the least amount of money. What is the objective?', 'text', 1, 'What quantity should be as small as possible?', '{"why":"The problem is trying to minimize the cost.","sol":"Step 1: The phrase ''least amount of money'' refers to expenditure or cost.\nStep 2: The amount must be made as small as possible.\nStep 3: Therefore the objective is cost.","steps":["Step 1: The phrase ''least amount of money'' refers to expenditure or cost.","Step 2: The amount must be made as small as possible.","Step 3: Therefore the objective is cost."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 1),
  (454, 128, 'A business wants the highest possible sales income. What is the objective?', 'text', 1, 'Sales income is another name for revenue.', '{"why":"Revenue is the quantity being made as large as possible.","sol":"Step 1: Sales income means revenue.\nStep 2: The word ''highest'' means maximum.\nStep 3: Therefore the objective is to maximize revenue.","steps":["Step 1: Sales income means revenue.","Step 2: The word ''highest'' means maximum.","Step 3: Therefore the objective is to maximize revenue."],"options":[],"conceptId":"math_linear_programming_identifying_the_objective_in_a_word_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Identifying the Objective in a Word Problem"}', 2),
  (455, 129, 'A pen gives KSh 20 profit and a book gives KSh 50 profit. If x pens and y books are sold, form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Total profit is the sum of the profits from both products.","sol":"Step 1: Pen profit = 20x.\nStep 2: Book profit = 50y.\nStep 3: Add the two profits.\nStep 4: P = 20x + 50y.","steps":["Step 1: Pen profit = 20x.","Step 2: Book profit = 50y.","Step 3: Add the two profits.","Step 4: P = 20x + 50y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 0),
  (456, 129, 'A farmer earns KSh 900 per bag of maize and KSh 700 per bag of beans. Form the profit function.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"Each coefficient represents the profit from one unit.","sol":"Step 1: Maize profit = 900x.\nStep 2: Bean profit = 700y.\nStep 3: Add the two.\nStep 4: P = 900x + 700y.","steps":["Step 1: Maize profit = 900x.","Step 2: Bean profit = 700y.","Step 3: Add the two.","Step 4: P = 900x + 700y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 1),
  (457, 129, 'A shop earns KSh 150 on each shirt and KSh 250 on each jacket. Form the profit function.', 'text', 1, 'Use x for shirts and y for jackets.', '{"why":"The function adds the profit contributed by each product.","sol":"Step 1: Shirt profit = 150x.\nStep 2: Jacket profit = 250y.\nStep 3: Total profit = 150x + 250y.","steps":["Step 1: Shirt profit = 150x.","Step 2: Jacket profit = 250y.","Step 3: Total profit = 150x + 250y."],"options":[],"conceptId":"math_linear_programming_forming_a_profit_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Profit Objective Function"}', 2),
  (458, 130, 'A material costs KSh 400 per unit and another costs KSh 600 per unit. Form the total cost function.', 'text', 1, 'Let x and y be the quantities.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: First material costs 400x.\nStep 2: Second material costs 600y.\nStep 3: Add them.\nStep 4: C = 400x + 600y.","steps":["Step 1: First material costs 400x.","Step 2: Second material costs 600y.","Step 3: Add them.","Step 4: C = 400x + 600y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 0),
  (459, 130, 'Pens cost KSh 15 each and books cost KSh 80 each. Form the total cost function.', 'text', 1, 'Let x be pens and y be books.', '{"why":"Each coefficient is the cost of one unit.","sol":"Step 1: Pen cost = 15x.\nStep 2: Book cost = 80y.\nStep 3: Total cost = 15x + 80y.","steps":["Step 1: Pen cost = 15x.","Step 2: Book cost = 80y.","Step 3: Total cost = 15x + 80y."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 1),
  (460, 130, 'A company wants to spend the least possible amount and its cost function is C = 700x + 500y. What is the objective?', 'text', 1, 'Least means minimum.', '{"why":"The objective is to make the total cost as small as possible.","sol":"Step 1: C represents total cost.\nStep 2: The problem asks for the least cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The problem asks for the least cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_forming_a_cost_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Cost Objective Function"}', 2),
  (461, 131, 'A product sells for KSh 500 per unit and another sells for KSh 800 per unit. Form the revenue function.', 'text', 1, 'Revenue = selling price × quantity.', '{"why":"Revenue comes from multiplying selling price by the number sold.","sol":"Step 1: Revenue from the first product = 500x.\nStep 2: Revenue from the second product = 800y.\nStep 3: Add them.\nStep 4: R = 500x + 800y.","steps":["Step 1: Revenue from the first product = 500x.","Step 2: Revenue from the second product = 800y.","Step 3: Add them.","Step 4: R = 500x + 800y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 0),
  (462, 131, 'A farmer sells maize at KSh 3,500 per bag and beans at KSh 4,000 per bag. Form the revenue function.', 'text', 1, 'Use x for maize and y for beans.', '{"why":"The coefficients are the selling prices per unit.","sol":"Step 1: Maize revenue = 3500x.\nStep 2: Bean revenue = 4000y.\nStep 3: Add the revenues.\nStep 4: R = 3500x + 4000y.","steps":["Step 1: Maize revenue = 3500x.","Step 2: Bean revenue = 4000y.","Step 3: Add the revenues.","Step 4: R = 3500x + 4000y."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 1),
  (463, 131, 'If R = 120x + 200y represents revenue and the aim is to get the highest revenue, what should be done?', 'text', 1, 'Highest means maximum.', '{"why":"The objective is to make revenue as large as possible.","sol":"Step 1: R represents revenue.\nStep 2: The aim is the highest revenue.\nStep 3: Therefore R should be maximized.","steps":["Step 1: R represents revenue.","Step 2: The aim is the highest revenue.","Step 3: Therefore R should be maximized."],"options":[],"conceptId":"math_linear_programming_forming_a_revenue_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Forming a Revenue Objective Function"}', 2),
  (464, 132, 'A product gives KSh 900 profit per unit. If x units are produced, what expression represents the profit?', 'text', 1, 'Multiply 900 by x.', '{"why":"The per-unit profit becomes the coefficient of x.","sol":"Step 1: Profit per unit = 900.\nStep 2: Number of units = x.\nStep 3: Total profit = 900 × x.\nStep 4: Therefore profit = 900x.","steps":["Step 1: Profit per unit = 900.","Step 2: Number of units = x.","Step 3: Total profit = 900 × x.","Step 4: Therefore profit = 900x."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 0),
  (465, 132, 'A chair costs KSh 700 each. If y chairs are bought, write the cost.', 'text', 1, 'Cost = 700 × number of chairs.', '{"why":"The number 700 tells us the cost of each chair.","sol":"Step 1: Cost per chair = 700.\nStep 2: Number of chairs = y.\nStep 3: Total cost = 700 × y.\nStep 4: Therefore cost = 700y.","steps":["Step 1: Cost per chair = 700.","Step 2: Number of chairs = y.","Step 3: Total cost = 700 × y.","Step 4: Therefore cost = 700y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 1),
  (466, 132, 'A shirt gives KSh 250 profit each and a trouser gives KSh 400 profit each. Let x be shirts and y be trousers. Form the profit function.', 'text', 1, 'Use 250 with x and 400 with y.', '{"why":"Each per-unit profit becomes the coefficient of its corresponding variable.","sol":"Step 1: Shirt profit = 250x.\nStep 2: Trouser profit = 400y.\nStep 3: Add them.\nStep 4: P = 250x + 400y.","steps":["Step 1: Shirt profit = 250x.","Step 2: Trouser profit = 400y.","Step 3: Add them.","Step 4: P = 250x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_per_unit_wording_into_coefficients","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Per-Unit Wording into Coefficients"}', 2),
  (467, 133, 'Find P = 400x + 200y at (3, 5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"The coordinates replace x and y in the objective function.","sol":"Step 1: P = 400(3) + 200(5).\nStep 2: P = 1200 + 1000.\nStep 3: P = 2200.","steps":["Step 1: P = 400(3) + 200(5).","Step 2: P = 1200 + 1000.","Step 3: P = 2200."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 0),
  (468, 133, 'Find C = 300x + 600y at (2, 4).', 'text', 1, 'Substitute x = 2 and y = 4.', '{"why":"The point tells us the values of x and y.","sol":"Step 1: C = 300(2) + 600(4).\nStep 2: C = 600 + 2400.\nStep 3: C = 3000.","steps":["Step 1: C = 300(2) + 600(4).","Step 2: C = 600 + 2400.","Step 3: C = 3000."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 1),
  (469, 133, 'Find R = 800x + 500y at (4, 3).', 'text', 1, 'Replace x by 4 and y by 3.', '{"why":"Evaluating the objective means calculating its value at the given point.","sol":"Step 1: R = 800(4) + 500(3).\nStep 2: R = 3200 + 1500.\nStep 3: R = 4700.","steps":["Step 1: R = 800(4) + 500(3).","Step 2: R = 3200 + 1500.","Step 3: R = 4700."],"options":[],"conceptId":"math_linear_programming_evaluating_an_objective_function_at_a_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating an Objective Function at a Point"}', 2),
  (470, 134, 'P = 400x + 300y. Which point gives the greater profit: (2,3) or (4,1)?', 'text', 1, 'Calculate P at both points.', '{"why":"The second point produces the greater objective value.","sol":"Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.\nStep 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.\nStep 3: Compare 1700 and 1900.\nStep 4: 1900 is greater.","steps":["Step 1: At (2,3): P = 400(2) + 300(3) = 800 + 900 = 1700.","Step 2: At (4,1): P = 400(4) + 300(1) = 1600 + 300 = 1900.","Step 3: Compare 1700 and 1900.","Step 4: 1900 is greater."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 0),
  (471, 134, 'C = 500x + 200y. Which point gives the lower cost: (2,4) or (5,1)?', 'text', 1, 'Calculate both costs.', '{"why":"The first point gives the smaller cost.","sol":"Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.\nStep 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.\nStep 3: Compare 1800 and 2700.\nStep 4: 1800 is lower.","steps":["Step 1: At (2,4): C = 500(2) + 200(4) = 1000 + 800 = 1800.","Step 2: At (5,1): C = 500(5) + 200(1) = 2500 + 200 = 2700.","Step 3: Compare 1800 and 2700.","Step 4: 1800 is lower."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 1),
  (472, 134, 'R = 300x + 400y. Compare (3,2) and (1,5).', 'text', 1, 'Evaluate R at each point.', '{"why":"The objective value at (1,5) is larger.","sol":"Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.\nStep 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.\nStep 3: 2300 is greater than 1700.","steps":["Step 1: At (3,2): R = 300(3) + 400(2) = 900 + 800 = 1700.","Step 2: At (1,5): R = 300(1) + 400(5) = 300 + 2000 = 2300.","Step 3: 2300 is greater than 1700."],"options":[],"conceptId":"math_linear_programming_comparing_objective_values_at_two_points","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Comparing Objective Values at Two Points"}', 2),
  (473, 135, 'What does maximise P mean?', 'text', 1, 'Think about the word maximum.', '{"why":"Maximisation always seeks the largest objective value.","sol":"Step 1: Maximum means greatest.\nStep 2: P is the objective function.\nStep 3: Therefore maximise P means find the greatest possible value of P.","steps":["Step 1: Maximum means greatest.","Step 2: P is the objective function.","Step 3: Therefore maximise P means find the greatest possible value of P."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 0),
  (474, 135, 'P = 400x + 200y. If two feasible points give P = 1800 and P = 2200, which value is preferred when maximising P?', 'text', 1, 'Choose the larger value.', '{"why":"Maximisation chooses the greater objective value.","sol":"Step 1: The values are 1800 and 2200.\nStep 2: 2200 is greater than 1800.\nStep 3: Therefore 2200 is preferred.","steps":["Step 1: The values are 1800 and 2200.","Step 2: 2200 is greater than 1800.","Step 3: Therefore 2200 is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 1),
  (475, 135, 'A farmer wants maximum profit. If one feasible production plan gives KSh 8,000 and another gives KSh 9,500, which plan is better?', 'text', 1, 'Maximum profit means greater profit.', '{"why":"The objective is to obtain the greatest profit.","sol":"Step 1: Compare KSh 8,000 and KSh 9,500.\nStep 2: KSh 9,500 is greater.\nStep 3: Therefore the plan producing KSh 9,500 is better.","steps":["Step 1: Compare KSh 8,000 and KSh 9,500.","Step 2: KSh 9,500 is greater.","Step 3: Therefore the plan producing KSh 9,500 is better."],"options":[],"conceptId":"math_linear_programming_meaning_of_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Maximisation"}', 2),
  (476, 136, 'What does minimise C mean?', 'text', 1, 'Think about the word minimum.', '{"why":"Minimisation seeks the lowest objective value.","sol":"Step 1: Minimum means smallest.\nStep 2: C is the objective function.\nStep 3: Therefore minimise C means find the smallest possible value of C.","steps":["Step 1: Minimum means smallest.","Step 2: C is the objective function.","Step 3: Therefore minimise C means find the smallest possible value of C."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 0),
  (477, 136, 'A company wants minimum cost. Two feasible plans cost KSh 3,500 and KSh 4,200. Which is preferred?', 'text', 1, 'Choose the lower cost.', '{"why":"Minimum cost means choosing the smaller cost.","sol":"Step 1: Compare 3500 and 4200.\nStep 2: 3500 is smaller.\nStep 3: Therefore the KSh 3,500 plan is preferred.","steps":["Step 1: Compare 3500 and 4200.","Step 2: 3500 is smaller.","Step 3: Therefore the KSh 3,500 plan is preferred."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 1),
  (478, 136, 'Three feasible solutions give costs of KSh 7,000, KSh 5,500 and KSh 6,200. What is the minimum cost?', 'text', 1, 'Find the smallest number.', '{"why":"The minimum is the smallest objective value.","sol":"Step 1: Compare 7000, 5500 and 6200.\nStep 2: 5500 is the smallest.\nStep 3: Therefore the minimum cost is KSh 5,500.","steps":["Step 1: Compare 7000, 5500 and 6200.","Step 2: 5500 is the smallest.","Step 3: Therefore the minimum cost is KSh 5,500."],"options":[],"conceptId":"math_linear_programming_meaning_of_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of Minimisation"}', 2),
  (479, 137, 'Three feasible plans give profits of KSh 4,000, KSh 6,000 and KSh 5,000. Which is optimal when profit is maximized?', 'text', 1, 'Choose the greatest profit.', '{"why":"Maximum profit requires the greatest feasible profit.","sol":"Step 1: Compare 4000, 6000 and 5000.\nStep 2: 6000 is the greatest.\nStep 3: Therefore the plan giving KSh 6,000 is optimal.","steps":["Step 1: Compare 4000, 6000 and 5000.","Step 2: 6000 is the greatest.","Step 3: Therefore the plan giving KSh 6,000 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 0),
  (480, 137, 'Three feasible plans cost KSh 8,000, KSh 6,500 and KSh 7,200. Which is optimal when cost is minimized?', 'text', 1, 'Choose the smallest cost.', '{"why":"Minimum cost requires the smallest feasible cost.","sol":"Step 1: Compare 8000, 6500 and 7200.\nStep 2: 6500 is the smallest.\nStep 3: Therefore the KSh 6,500 plan is optimal.","steps":["Step 1: Compare 8000, 6500 and 7200.","Step 2: 6500 is the smallest.","Step 3: Therefore the KSh 6,500 plan is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 1),
  (481, 137, 'If two feasible points give objective values 3,200 and 3,800, which is optimal when maximizing?', 'text', 1, 'Maximum means greatest.', '{"why":"The greater objective value is preferred during maximisation.","sol":"Step 1: Compare 3200 and 3800.\nStep 2: 3800 is greater.\nStep 3: Therefore the point giving 3800 is optimal.","steps":["Step 1: Compare 3200 and 3800.","Step 2: 3800 is greater.","Step 3: Therefore the point giving 3800 is optimal."],"options":[],"conceptId":"math_linear_programming_meaning_of_an_optimal_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Meaning of an Optimal Solution"}', 2),
  (482, 138, 'Why do we test corner points in a linear programming problem?', 'text', 1, 'Think about where the optimum occurs for a linear objective.', '{"why":"The corner-point method allows us to find the optimum without checking every feasible point.","sol":"Step 1: The feasible region contains many possible points.\nStep 2: The objective function is linear.\nStep 3: When an optimum exists, its best value occurs at a corner point.\nStep 4: Therefore we test the corner points.","steps":["Step 1: The feasible region contains many possible points.","Step 2: The objective function is linear.","Step 3: When an optimum exists, its best value occurs at a corner point.","Step 4: Therefore we test the corner points."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 0),
  (483, 138, 'A feasible region has four corner points. Should a point outside the region be tested as a possible optimum?', 'text', 1, 'First ask whether the point is feasible.', '{"why":"Only feasible points can be considered as solutions.","sol":"Step 1: An optimum must satisfy all constraints.\nStep 2: A point outside the feasible region violates at least one constraint.\nStep 3: Therefore it cannot be an allowed solution.","steps":["Step 1: An optimum must satisfy all constraints.","Step 2: A point outside the feasible region violates at least one constraint.","Step 3: Therefore it cannot be an allowed solution."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 1),
  (484, 138, 'A feasible region has corners A, B, C and D. What points should normally be tested for the optimum?', 'text', 1, 'Use the corner-point method.', '{"why":"The corner points are the candidates for the optimum.","sol":"Step 1: The feasible region has four corner points.\nStep 2: The objective should be evaluated at those corners.\nStep 3: Therefore test A, B, C and D.","steps":["Step 1: The feasible region has four corner points.","Step 2: The objective should be evaluated at those corners.","Step 3: Therefore test A, B, C and D."],"options":[],"conceptId":"math_linear_programming_why_corner_points_are_tested","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Why Corner Points Are Tested"}', 2),
  (485, 139, 'P = 300x + 200y. Find P at (4,2).', 'text', 1, 'Substitute x = 4 and y = 2.', '{"why":"The coordinates are substituted into the objective function.","sol":"Step 1: P = 300(4) + 200(2).\nStep 2: P = 1200 + 400.\nStep 3: P = 1600.","steps":["Step 1: P = 300(4) + 200(2).","Step 2: P = 1200 + 400.","Step 3: P = 1600."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 0),
  (486, 139, 'C = 500x + 100y. Find C at (3,5).', 'text', 1, 'Use x = 3 and y = 5.', '{"why":"Evaluating a corner means calculating the objective value at that point.","sol":"Step 1: C = 500(3) + 100(5).\nStep 2: C = 1500 + 500.\nStep 3: C = 2000.","steps":["Step 1: C = 500(3) + 100(5).","Step 2: C = 1500 + 500.","Step 3: C = 2000."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 1),
  (487, 139, 'P = 600x + 400y. Find P at (2,3).', 'text', 1, 'Replace x by 2 and y by 3.', '{"why":"The point gives the values of x and y used in the objective.","sol":"Step 1: P = 600(2) + 400(3).\nStep 2: P = 1200 + 1200.\nStep 3: P = 2400.","steps":["Step 1: P = 600(2) + 400(3).","Step 2: P = 1200 + 1200.","Step 3: P = 2400."],"options":[],"conceptId":"math_linear_programming_evaluating_the_objective_at_every_corner_point","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Evaluating the Objective at Every Corner Point"}', 2),
  (488, 140, 'The objective values at four corners are 900, 1400, 1800 and 1200. What is the maximum?', 'text', 1, 'Choose the greatest number.', '{"why":"Maximum means greatest.","sol":"Step 1: Compare 900, 1400, 1800 and 1200.\nStep 2: 1800 is the greatest.\nStep 3: Therefore the maximum is 1800.","steps":["Step 1: Compare 900, 1400, 1800 and 1200.","Step 2: 1800 is the greatest.","Step 3: Therefore the maximum is 1800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 0),
  (489, 140, 'A profit function gives 2,100, 2,700 and 2,400 at three feasible corners. Which gives maximum profit?', 'text', 1, 'Choose the largest profit.', '{"why":"The greatest profit is the maximum.","sol":"Step 1: Compare 2100, 2700 and 2400.\nStep 2: 2700 is greatest.\nStep 3: Therefore the second corner gives maximum profit.","steps":["Step 1: Compare 2100, 2700 and 2400.","Step 2: 2700 is greatest.","Step 3: Therefore the second corner gives maximum profit."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 1),
  (490, 140, 'The corner values of P are 3,000, 2,500, 3,800 and 3,200. Which value is the maximum?', 'text', 1, 'Find the largest value.', '{"why":"Maximization selects the greatest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 3800 is the greatest.\nStep 3: Therefore the maximum value is 3800.","steps":["Step 1: Compare all four values.","Step 2: 3800 is the greatest.","Step 3: Therefore the maximum value is 3800."],"options":[],"conceptId":"math_linear_programming_finding_the_maximum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Maximum from Corner Values"}', 2),
  (491, 141, 'The objective values at four corners are 2,000, 1,500, 1,800 and 2,200. What is the minimum?', 'text', 1, 'Choose the smallest value.', '{"why":"Minimum means smallest.","sol":"Step 1: Compare 2000, 1500, 1800 and 2200.\nStep 2: 1500 is the smallest.\nStep 3: Therefore the minimum is 1500.","steps":["Step 1: Compare 2000, 1500, 1800 and 2200.","Step 2: 1500 is the smallest.","Step 3: Therefore the minimum is 1500."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 0),
  (492, 141, 'Three feasible points give costs of KSh 4,000, KSh 3,200 and KSh 3,700. Which gives minimum cost?', 'text', 1, 'Choose the lowest cost.', '{"why":"Minimum cost means choosing the smallest feasible cost.","sol":"Step 1: Compare 4000, 3200 and 3700.\nStep 2: 3200 is the smallest.\nStep 3: Therefore the second point gives minimum cost.","steps":["Step 1: Compare 4000, 3200 and 3700.","Step 2: 3200 is the smallest.","Step 3: Therefore the second point gives minimum cost."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 1),
  (493, 141, 'The corner values of C are 700, 900, 650 and 800. Which is the minimum?', 'text', 1, 'Find the smallest number.', '{"why":"Minimization selects the smallest objective value.","sol":"Step 1: Compare all four values.\nStep 2: 650 is the smallest.\nStep 3: Therefore the minimum is 650.","steps":["Step 1: Compare all four values.","Step 2: 650 is the smallest.","Step 3: Therefore the minimum is 650."],"options":[],"conceptId":"math_linear_programming_finding_the_minimum_from_corner_values","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Minimum from Corner Values"}', 2),
  (494, 142, 'A maximum objective value of 5,000 occurs at (4,3). What is the optimal point?', 'text', 1, 'The optimal point is the point where the maximum occurs.', '{"why":"The optimal point identifies the variable values producing the best result.","sol":"Step 1: The maximum value is 5000.\nStep 2: It occurs at (4,3).\nStep 3: Therefore the optimal point is (4,3).","steps":["Step 1: The maximum value is 5000.","Step 2: It occurs at (4,3).","Step 3: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 0),
  (495, 142, 'A minimum cost of KSh 2,400 occurs at (2,5). What is the minimum cost?', 'text', 1, 'The optimal value is the value of the objective.', '{"why":"The optimal value is the minimum value of the objective function.","sol":"Step 1: The problem states that the minimum cost is 2400.\nStep 2: Therefore the optimal value is KSh 2,400.","steps":["Step 1: The problem states that the minimum cost is 2400.","Step 2: Therefore the optimal value is KSh 2,400."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 1),
  (496, 142, 'Maximum profit is KSh 8,000 at (5,2). State both the optimal point and optimal value.', 'text', 1, 'Give both pieces of information.', '{"why":"A complete optimisation answer identifies both the quantities and the resulting objective value.","sol":"Step 1: The point is (5,2).\nStep 2: The maximum profit is KSh 8,000.\nStep 3: Therefore report both.","steps":["Step 1: The point is (5,2).","Step 2: The maximum profit is KSh 8,000.","Step 3: Therefore report both."],"options":[],"conceptId":"math_linear_programming_finding_the_optimal_point_and_optimal_value","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Finding the Optimal Point and Optimal Value"}', 2),
  (497, 143, 'P = 400x + 300y. The corner points are (0,0), (5,0), (3,4), (0,4). Which point gives the maximum P?', 'text', 1, 'Evaluate P at all four points.', '{"why":"The point (3,4) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 400(5) = 2000.\nStep 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.\nStep 4: At (0,4): P = 1200.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 400(5) = 2000.","Step 3: At (3,4): P = 400(3) + 300(4) = 1200 + 1200 = 2400.","Step 4: At (0,4): P = 1200.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 0),
  (498, 143, 'P = 600x + 200y. The corners are (0,0), (4,0), (3,2), (0,3). Find the maximum P.', 'text', 1, 'Calculate P at every corner.', '{"why":"The corner (4,0) gives the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (4,0): P = 600(4) = 2400.\nStep 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.\nStep 4: At (0,3): P = 600.\nStep 5: The greatest value is 2400.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (4,0): P = 600(4) = 2400.","Step 3: At (3,2): P = 600(3) + 200(2) = 1800 + 400 = 2200.","Step 4: At (0,3): P = 600.","Step 5: The greatest value is 2400."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 1),
  (499, 143, 'P = 300x + 500y. The corners are (0,0), (6,0), (4,3), (0,5). Find the optimal point and maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The optimal point is the feasible corner producing the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (6,0): P = 300(6) = 1800.\nStep 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.\nStep 4: At (0,5): P = 500(5) = 2500.\nStep 5: The greatest value is 2700.\nStep 6: Therefore the optimal point is (4,3).","steps":["Step 1: At (0,0): P = 0.","Step 2: At (6,0): P = 300(6) = 1800.","Step 3: At (4,3): P = 300(4) + 500(3) = 1200 + 1500 = 2700.","Step 4: At (0,5): P = 500(5) = 2500.","Step 5: The greatest value is 2700.","Step 6: Therefore the optimal point is (4,3)."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_maximisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Maximisation"}', 2),
  (500, 144, 'C = 300x + 200y. The corner points are (1,1), (4,1), (3,3), (1,4). Find the minimum cost.', 'text', 1, 'Evaluate C at every corner and choose the smallest.', '{"why":"The point (1,1) produces the smallest feasible cost.","sol":"Step 1: At (1,1): C = 300 + 200 = 500.\nStep 2: At (4,1): C = 1200 + 200 = 1400.\nStep 3: At (3,3): C = 900 + 600 = 1500.\nStep 4: At (1,4): C = 300 + 800 = 1100.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 300 + 200 = 500.","Step 2: At (4,1): C = 1200 + 200 = 1400.","Step 3: At (3,3): C = 900 + 600 = 1500.","Step 4: At (1,4): C = 300 + 800 = 1100.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (501, 144, 'C = 500x + 400y. The corners are (1,2), (4,2), (3,5). Which gives the minimum?', 'text', 1, 'Calculate all three costs.', '{"why":"The first point gives the smallest objective value.","sol":"Step 1: At (1,2): C = 500 + 800 = 1300.\nStep 2: At (4,2): C = 2000 + 800 = 2800.\nStep 3: At (3,5): C = 1500 + 2000 = 3500.\nStep 4: The smallest value is 1300.","steps":["Step 1: At (1,2): C = 500 + 800 = 1300.","Step 2: At (4,2): C = 2000 + 800 = 2800.","Step 3: At (3,5): C = 1500 + 2000 = 3500.","Step 4: The smallest value is 1300."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 1),
  (502, 144, 'C = 200x + 600y. The corners are (2,1), (5,1), (4,3), (2,4). Find the optimal point and minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The optimal point is the feasible corner with the smallest objective value.","sol":"Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.\nStep 2: At (5,1): C = 1000 + 600 = 1600.\nStep 3: At (4,3): C = 800 + 1800 = 2600.\nStep 4: At (2,4): C = 400 + 2400 = 2800.\nStep 5: The smallest value is 1000.","steps":["Step 1: At (2,1): C = 200(2) + 600(1) = 400 + 600 = 1000.","Step 2: At (5,1): C = 1000 + 600 = 1600.","Step 3: At (4,3): C = 800 + 1800 = 2600.","Step 4: At (2,4): C = 400 + 2400 = 2800.","Step 5: The smallest value is 1000."],"options":[],"conceptId":"math_linear_programming_complete_corner_point_minimisation","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Corner-Point Minimisation"}', 2),
  (503, 145, 'A feasible region has corners (0,0), (5,0), (3,4), (0,6). P = 300x + 400y. Find the maximum P.', 'text', 1, 'Evaluate P at all four corners.', '{"why":"The corner (3,4) produces the greatest objective value.","sol":"Step 1: At (0,0): P = 0.\nStep 2: At (5,0): P = 300(5) = 1500.\nStep 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.\nStep 4: At (0,6): P = 400(6) = 2400.\nStep 5: The greatest value is 2500.","steps":["Step 1: At (0,0): P = 0.","Step 2: At (5,0): P = 300(5) = 1500.","Step 3: At (3,4): P = 300(3) + 400(4) = 900 + 1600 = 2500.","Step 4: At (0,6): P = 400(6) = 2400.","Step 5: The greatest value is 2500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 0),
  (504, 145, 'A feasible region has corners (1,1), (5,1), (4,3), (1,4). C = 200x + 300y. Find the minimum C.', 'text', 1, 'Evaluate C at each corner.', '{"why":"The point (1,1) gives the smallest feasible cost.","sol":"Step 1: At (1,1): C = 200 + 300 = 500.\nStep 2: At (5,1): C = 1000 + 300 = 1300.\nStep 3: At (4,3): C = 800 + 900 = 1700.\nStep 4: At (1,4): C = 200 + 1200 = 1400.\nStep 5: The smallest value is 500.","steps":["Step 1: At (1,1): C = 200 + 300 = 500.","Step 2: At (5,1): C = 1000 + 300 = 1300.","Step 3: At (4,3): C = 800 + 900 = 1700.","Step 4: At (1,4): C = 200 + 1200 = 1400.","Step 5: The smallest value is 500."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 1),
  (505, 145, 'Why must you check every relevant corner point before declaring the maximum or minimum?', 'text', 1, 'Could an unchecked corner have a better value?', '{"why":"Checking every relevant corner prevents us from missing the best feasible solution.","sol":"Step 1: Each corner is a candidate for the optimum.\nStep 2: An unchecked corner could have a greater value when maximizing.\nStep 3: It could also have a smaller value when minimizing.\nStep 4: Therefore all relevant corner points must be evaluated.","steps":["Step 1: Each corner is a candidate for the optimum.","Step 2: An unchecked corner could have a greater value when maximizing.","Step 3: It could also have a smaller value when minimizing.","Step 4: Therefore all relevant corner points must be evaluated."],"options":[],"conceptId":"math_linear_programming_complete_linear_programming_solution","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Complete Linear Programming Solution"}', 2),
  (506, 146, 'A shop sells shirts and trousers. Let x represent shirts and y represent trousers. What does x represent?', 'text', 1, 'Read the variable definition.', '{"why":"A decision variable must have a clearly defined meaning.","sol":"Step 1: The problem defines x as the number of shirts.\nStep 2: Therefore x represents the number of shirts.","steps":["Step 1: The problem defines x as the number of shirts.","Step 2: Therefore x represents the number of shirts."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 0),
  (507, 146, 'A farmer produces maize and beans. Define x as maize and y as beans.', 'text', 1, 'State exactly what each variable counts.', '{"why":"Clear variable definitions make the later mathematical model understandable.","sol":"Step 1: Let x represent the number of bags of maize.\nStep 2: Let y represent the number of bags of beans.","steps":["Step 1: Let x represent the number of bags of maize.","Step 2: Let y represent the number of bags of beans."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 1),
  (508, 146, 'A factory makes tables and chairs. What could x and y represent?', 'text', 1, 'Use the two products as the two variables.', '{"why":"The variables represent the quantities the factory chooses to produce.","sol":"Step 1: Let x represent the number of tables.\nStep 2: Let y represent the number of chairs.","steps":["Step 1: Let x represent the number of tables.","Step 2: Let y represent the number of chairs."],"options":[],"conceptId":"math_linear_programming_defining_decision_variables","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Defining Decision Variables"}', 2),
  (509, 147, 'A farmer can plant at most 40 acres. If x is the number of acres planted, write the inequality.', 'text', 1, 'At most means no more than.', '{"why":"At most means the quantity cannot exceed the stated limit.","sol":"Step 1: The maximum allowed is 40.\nStep 2: The planted area can be 40 or less.\nStep 3: Therefore x ≤ 40.","steps":["Step 1: The maximum allowed is 40.","Step 2: The planted area can be 40 or less.","Step 3: Therefore x ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 0),
  (510, 147, 'A truck can carry at most 500 kg. If x kg is loaded, write the inequality.', 'text', 1, 'Can the load be greater than 500 kg?', '{"why":"The load must not exceed 500 kg.","sol":"Step 1: The maximum load is 500 kg.\nStep 2: The load may be less than or equal to 500 kg.\nStep 3: Therefore x ≤ 500.","steps":["Step 1: The maximum load is 500 kg.","Step 2: The load may be less than or equal to 500 kg.","Step 3: Therefore x ≤ 500."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 1),
  (511, 147, 'A school has at most 60 computers. If x and y are two types of computers, write the total constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The total is limited to 60 or fewer.","sol":"Step 1: The total number of computers is x + y.\nStep 2: The total cannot exceed 60.\nStep 3: Therefore x + y ≤ 60.","steps":["Step 1: The total number of computers is x + y.","Step 2: The total cannot exceed 60.","Step 3: Therefore x + y ≤ 60."],"options":[],"conceptId":"math_linear_programming_translating_at_most_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Most'' into an Inequality"}', 2),
  (512, 148, 'A factory must produce at least 50 units. If x is the number produced, write the inequality.', 'text', 1, 'At least means no less than.', '{"why":"At least means the quantity must not fall below the stated amount.","sol":"Step 1: The required minimum is 50.\nStep 2: The number produced can be 50 or more.\nStep 3: Therefore x ≥ 50.","steps":["Step 1: The required minimum is 50.","Step 2: The number produced can be 50 or more.","Step 3: Therefore x ≥ 50."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 0),
  (513, 148, 'A farmer must produce at least 100 bags of maize and beans combined. If x and y are the quantities, write the inequality.', 'text', 1, 'Add the two quantities.', '{"why":"The combined production must be 100 or greater.","sol":"Step 1: Total production = x + y.\nStep 2: The total must be at least 100.\nStep 3: Therefore x + y ≥ 100.","steps":["Step 1: Total production = x + y.","Step 2: The total must be at least 100.","Step 3: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 1),
  (514, 148, 'A school requires at least 20 computers. If x represents the number of computers, write the inequality.', 'text', 1, 'The number cannot be below 20.', '{"why":"At least describes a lower limit.","sol":"Step 1: Minimum required = 20.\nStep 2: The number may be 20 or more.\nStep 3: Therefore x ≥ 20.","steps":["Step 1: Minimum required = 20.","Step 2: The number may be 20 or more.","Step 3: Therefore x ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_at_least_into_an_inequality","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating ''At Least'' into an Inequality"}', 2),
  (515, 149, 'A table uses 4 hours and a chair uses 2 hours. There are at most 40 hours available. Form the constraint.', 'text', 1, 'Total time used must not exceed 40.', '{"why":"The total machine time cannot exceed the available 40 hours.","sol":"Step 1: Tables use 4x hours.\nStep 2: Chairs use 2y hours.\nStep 3: Total = 4x + 2y.\nStep 4: At most 40 means ≤ 40.\nStep 5: Therefore 4x + 2y ≤ 40.","steps":["Step 1: Tables use 4x hours.","Step 2: Chairs use 2y hours.","Step 3: Total = 4x + 2y.","Step 4: At most 40 means ≤ 40.","Step 5: Therefore 4x + 2y ≤ 40."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 0),
  (516, 149, 'A product A uses 3 kg and product B uses 5 kg. There are 90 kg available. Form the constraint.', 'text', 1, 'Multiply each material use by its quantity.', '{"why":"The total material used must not exceed the available material.","sol":"Step 1: A uses 3x kg.\nStep 2: B uses 5y kg.\nStep 3: Total = 3x + 5y.\nStep 4: The total cannot exceed 90 kg.\nStep 5: Therefore 3x + 5y ≤ 90.","steps":["Step 1: A uses 3x kg.","Step 2: B uses 5y kg.","Step 3: Total = 3x + 5y.","Step 4: The total cannot exceed 90 kg.","Step 5: Therefore 3x + 5y ≤ 90."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 1),
  (517, 149, 'Product A costs KSh 100 and product B costs KSh 250. The budget is KSh 5,000. Form the constraint.', 'text', 1, 'Total cost must not exceed the budget.', '{"why":"Production spending cannot exceed the available budget.","sol":"Step 1: Cost of A = 100x.\nStep 2: Cost of B = 250y.\nStep 3: Total cost = 100x + 250y.\nStep 4: The budget is 5000.\nStep 5: Therefore 100x + 250y ≤ 5000.","steps":["Step 1: Cost of A = 100x.","Step 2: Cost of B = 250y.","Step 3: Total cost = 100x + 250y.","Step 4: The budget is 5000.","Step 5: Therefore 100x + 250y ≤ 5000."],"options":[],"conceptId":"math_linear_programming_translating_a_resource_limit_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Resource Limit into a Constraint"}', 2),
  (518, 150, 'A factory must produce at least 30 items. If x is the number produced, write the constraint.', 'text', 1, 'At least means ≥.', '{"why":"The production requirement gives a lower limit.","sol":"Step 1: The minimum is 30.\nStep 2: Production must be 30 or greater.\nStep 3: Therefore x ≥ 30.","steps":["Step 1: The minimum is 30.","Step 2: Production must be 30 or greater.","Step 3: Therefore x ≥ 30."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 0),
  (519, 150, 'A factory can produce at most 80 items. If x and y are two products, write the constraint.', 'text', 1, 'At most means ≤.', '{"why":"The total production cannot exceed 80.","sol":"Step 1: Total production = x + y.\nStep 2: The maximum allowed is 80.\nStep 3: Therefore x + y ≤ 80.","steps":["Step 1: Total production = x + y.","Step 2: The maximum allowed is 80.","Step 3: Therefore x + y ≤ 80."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 1),
  (520, 150, 'A company must produce at least 100 units of two products combined. Write the constraint.', 'text', 1, 'Add the quantities first.', '{"why":"The company must reach a minimum total production of 100.","sol":"Step 1: Let x and y be the quantities.\nStep 2: Combined production = x + y.\nStep 3: At least 100 means ≥ 100.\nStep 4: Therefore x + y ≥ 100.","steps":["Step 1: Let x and y be the quantities.","Step 2: Combined production = x + y.","Step 3: At least 100 means ≥ 100.","Step 4: Therefore x + y ≥ 100."],"options":[],"conceptId":"math_linear_programming_translating_a_production_requirement_into_a_constraint","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Production Requirement into a Constraint"}', 2),
  (521, 151, 'If x represents the number of tables produced, what condition must x satisfy?', 'text', 1, 'Can the number of tables be negative?', '{"why":"A quantity being counted cannot be negative.","sol":"Step 1: The number of tables cannot be negative.\nStep 2: Therefore x must be zero or positive.\nStep 3: So x ≥ 0.","steps":["Step 1: The number of tables cannot be negative.","Step 2: Therefore x must be zero or positive.","Step 3: So x ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 0),
  (522, 151, 'If x represents shirts and y represents trousers, write the non-negativity constraints.', 'text', 1, 'Write one condition for each variable.', '{"why":"Both decision variables represent quantities.","sol":"Step 1: The number of shirts cannot be negative: x ≥ 0.\nStep 2: The number of trousers cannot be negative: y ≥ 0.","steps":["Step 1: The number of shirts cannot be negative: x ≥ 0.","Step 2: The number of trousers cannot be negative: y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 1),
  (523, 151, 'Why is x ≥ 0 normally included in a production model?', 'text', 1, 'Think about what x represents.', '{"why":"Non-negativity keeps the mathematical model consistent with the meaning of the variables.","sol":"Step 1: x represents a quantity such as products produced.\nStep 2: A negative quantity has no physical meaning here.\nStep 3: Therefore x must be zero or positive.","steps":["Step 1: x represents a quantity such as products produced.","Step 2: A negative quantity has no physical meaning here.","Step 3: Therefore x must be zero or positive."],"options":[],"conceptId":"math_linear_programming_translating_non_negativity_conditions","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Non-Negativity Conditions"}', 2),
  (524, 152, 'A table gives KSh 600 profit and a chair gives KSh 400 profit. Let x be tables and y be chairs. Form the profit function.', 'text', 1, 'Multiply each unit profit by its quantity.', '{"why":"Each unit profit becomes the coefficient of its variable.","sol":"Step 1: Table profit = 600x.\nStep 2: Chair profit = 400y.\nStep 3: Total profit = 600x + 400y.","steps":["Step 1: Table profit = 600x.","Step 2: Chair profit = 400y.","Step 3: Total profit = 600x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 0),
  (525, 152, 'A farmer earns KSh 1,200 per maize bag and KSh 900 per bean bag. Form the objective function for maximum profit.', 'text', 1, 'Let x be maize and y be beans.', '{"why":"The function represents total profit and the aim is to make it as large as possible.","sol":"Step 1: Maize profit = 1200x.\nStep 2: Bean profit = 900y.\nStep 3: Total profit = 1200x + 900y.\nStep 4: The word maximum means this function is maximized.","steps":["Step 1: Maize profit = 1200x.","Step 2: Bean profit = 900y.","Step 3: Total profit = 1200x + 900y.","Step 4: The word maximum means this function is maximized."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 1),
  (526, 152, 'A bakery earns KSh 30 per loaf and KSh 80 per cake. Write the objective for maximum profit.', 'text', 1, 'Use x for loaves and y for cakes.', '{"why":"The objective function adds the profit from both products.","sol":"Step 1: Loaf profit = 30x.\nStep 2: Cake profit = 80y.\nStep 3: Total profit = 30x + 80y.\nStep 4: Maximum profit means maximize P.","steps":["Step 1: Loaf profit = 30x.","Step 2: Cake profit = 80y.","Step 3: Total profit = 30x + 80y.","Step 4: Maximum profit means maximize P."],"options":[],"conceptId":"math_linear_programming_translating_profit_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Profit Wording into an Objective Function"}', 2),
  (527, 153, 'Material A costs KSh 200 per unit and B costs KSh 400 per unit. Form the cost function.', 'text', 1, 'Multiply each cost per unit by its quantity.', '{"why":"The total cost is the sum of the two individual costs.","sol":"Step 1: A costs 200x.\nStep 2: B costs 400y.\nStep 3: Total cost = 200x + 400y.","steps":["Step 1: A costs 200x.","Step 2: B costs 400y.","Step 3: Total cost = 200x + 400y."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 0),
  (528, 153, 'A company wants the lowest cost. If C = 500x + 300y, what is the objective?', 'text', 1, 'Lowest means minimum.', '{"why":"Minimum cost means finding the smallest possible value of C.","sol":"Step 1: C represents total cost.\nStep 2: The company wants the lowest cost.\nStep 3: Therefore C must be minimized.","steps":["Step 1: C represents total cost.","Step 2: The company wants the lowest cost.","Step 3: Therefore C must be minimized."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 1),
  (529, 153, 'A notebook costs KSh 40 and a textbook KSh 200. If x notebooks and y textbooks are bought, write the objective for minimum cost.', 'text', 1, 'First form total cost.', '{"why":"The objective combines the cost of both types of items.","sol":"Step 1: Notebook cost = 40x.\nStep 2: Textbook cost = 200y.\nStep 3: Total cost = 40x + 200y.\nStep 4: Minimum cost means minimize C.","steps":["Step 1: Notebook cost = 40x.","Step 2: Textbook cost = 200y.","Step 3: Total cost = 40x + 200y.","Step 4: Minimum cost means minimize C."],"options":[],"conceptId":"math_linear_programming_translating_cost_wording_into_an_objective_function","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating Cost Wording into an Objective Function"}', 2),
  (530, 154, 'A factory makes tables and chairs. Let x be tables and y be chairs. Each table uses 2 hours and each chair 3 hours. There are at most 30 hours. Write the resource constraint.', 'text', 1, 'Total hours must not exceed 30.', '{"why":"The constraint represents the limited labour time.","sol":"Step 1: Tables use 2x hours.\nStep 2: Chairs use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 30 means ≤ 30.\nStep 5: Therefore 2x + 3y ≤ 30.","steps":["Step 1: Tables use 2x hours.","Step 2: Chairs use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 30 means ≤ 30.","Step 5: Therefore 2x + 3y ≤ 30."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 0),
  (531, 154, 'A business earns KSh 400 per table and KSh 600 per chair. Write the profit objective.', 'text', 1, 'Multiply each profit by its quantity.', '{"why":"The objective represents total profit.","sol":"Step 1: Table profit = 400x.\nStep 2: Chair profit = 600y.\nStep 3: Total profit = 400x + 600y.\nStep 4: For maximum profit, maximize this expression.","steps":["Step 1: Table profit = 400x.","Step 2: Chair profit = 600y.","Step 3: Total profit = 400x + 600y.","Step 4: For maximum profit, maximize this expression."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 1),
  (532, 154, 'Why are x ≥ 0 and y ≥ 0 included in the model?', 'text', 1, 'Think about what x and y represent.', '{"why":"Non-negativity connects the mathematical variables to their real meaning.","sol":"Step 1: x and y represent numbers of products.\nStep 2: Product quantities cannot be negative.\nStep 3: Therefore x and y must be non-negative.","steps":["Step 1: x and y represent numbers of products.","Step 2: Product quantities cannot be negative.","Step 3: Therefore x and y must be non-negative."],"options":[],"conceptId":"math_linear_programming_building_a_complete_linear_programming_model","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Complete Linear Programming Model"}', 2),
  (533, 155, 'A farm has at most 50 acres. Maize uses 2 acres per bag and beans use 1 acre per bag. Form the land constraint.', 'text', 1, 'Total land used must not exceed 50.', '{"why":"The inequality represents the limited amount of land.","sol":"Step 1: Maize uses 2x acres.\nStep 2: Beans use y acres.\nStep 3: Total = 2x + y.\nStep 4: At most 50 means ≤ 50.\nStep 5: Therefore 2x + y ≤ 50.","steps":["Step 1: Maize uses 2x acres.","Step 2: Beans use y acres.","Step 3: Total = 2x + y.","Step 4: At most 50 means ≤ 50.","Step 5: Therefore 2x + y ≤ 50."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 0),
  (534, 155, 'A farmer must produce at least 20 bags of maize and beans combined. Form the production constraint.', 'text', 1, 'Add the two quantities.', '{"why":"The farmer must reach a minimum combined production.","sol":"Step 1: Total bags = x + y.\nStep 2: At least 20 means ≥ 20.\nStep 3: Therefore x + y ≥ 20.","steps":["Step 1: Total bags = x + y.","Step 2: At least 20 means ≥ 20.","Step 3: Therefore x + y ≥ 20."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 1),
  (535, 155, 'If x and y represent numbers of bags, what non-negativity conditions are required?', 'text', 1, 'Can a bag quantity be negative?', '{"why":"The variables represent quantities of physical products.","sol":"Step 1: The number of maize bags cannot be negative.\nStep 2: The number of bean bags cannot be negative.\nStep 3: Therefore x ≥ 0 and y ≥ 0.","steps":["Step 1: The number of maize bags cannot be negative.","Step 2: The number of bean bags cannot be negative.","Step 3: Therefore x ≥ 0 and y ≥ 0."],"options":[],"conceptId":"math_linear_programming_translating_a_full_word_problem_into_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Translating a Full Word Problem into Constraints"}', 2),
  (536, 156, 'Check whether (5,10) satisfies 2x + y ≤ 25.', 'text', 1, 'Substitute x = 5 and y = 10.', '{"why":"The point makes the inequality true.","sol":"Step 1: 2(5) + 10 ≤ 25.\nStep 2: 10 + 10 ≤ 25.\nStep 3: 20 ≤ 25.\nStep 4: The statement is true.","steps":["Step 1: 2(5) + 10 ≤ 25.","Step 2: 10 + 10 ≤ 25.","Step 3: 20 ≤ 25.","Step 4: The statement is true."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 0),
  (537, 156, 'Check whether (10,8) satisfies x + y ≥ 20.', 'text', 1, 'Add the two coordinates.', '{"why":"The point fails the minimum-production constraint.","sol":"Step 1: 10 + 8 ≥ 20.\nStep 2: 18 ≥ 20.\nStep 3: This is false.","steps":["Step 1: 10 + 8 ≥ 20.","Step 2: 18 ≥ 20.","Step 3: This is false."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 1),
  (538, 156, 'A point satisfies three constraints but fails one constraint. Is it feasible?', 'text', 1, 'Feasible means satisfying all restrictions.', '{"why":"One violated constraint is enough to make a point infeasible.","sol":"Step 1: A feasible point must satisfy every constraint.\nStep 2: The point fails one constraint.\nStep 3: Therefore it is not feasible.","steps":["Step 1: A feasible point must satisfy every constraint.","Step 2: The point fails one constraint.","Step 3: Therefore it is not feasible."],"options":[],"conceptId":"math_linear_programming_checking_whether_a_proposed_production_plan_is_feasible","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Checking Whether a Proposed Production Plan Is Feasible"}', 2),
  (539, 157, 'In the bakery problem, what does x represent?', 'text', 1, 'Look at the variable definition.', '{"why":"Every later equation depends on this variable meaning.","sol":"Step 1: x was defined as the number of loaves.\nStep 2: Therefore x represents the number of loaves.","steps":["Step 1: x was defined as the number of loaves.","Step 2: Therefore x represents the number of loaves."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 0),
  (540, 157, 'In the bakery problem, what inequality represents the labour limit?', 'text', 1, 'Bread uses 2 hours and cakes use 3 hours.', '{"why":"The inequality represents the limited labour resource.","sol":"Step 1: Bread uses 2x hours.\nStep 2: Cakes use 3y hours.\nStep 3: Total = 2x + 3y.\nStep 4: At most 60 means ≤ 60.\nStep 5: Therefore 2x + 3y ≤ 60.","steps":["Step 1: Bread uses 2x hours.","Step 2: Cakes use 3y hours.","Step 3: Total = 2x + 3y.","Step 4: At most 60 means ≤ 60.","Step 5: Therefore 2x + 3y ≤ 60."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 1),
  (541, 157, 'What is the complete objective function for the bakery?', 'text', 1, 'Use the profit per loaf and profit per cake.', '{"why":"The objective combines the profit contributions from both products.","sol":"Step 1: Bread profit = 40x.\nStep 2: Cake profit = 100y.\nStep 3: Total profit = 40x + 100y.\nStep 4: The aim is maximum profit.","steps":["Step 1: Bread profit = 40x.","Step 2: Cake profit = 100y.","Step 3: Total profit = 40x + 100y.","Step 4: The aim is maximum profit."],"options":[],"conceptId":"math_linear_programming_building_a_linear_programming_model_from_a_complete_problem","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Building a Linear Programming Model from a Complete Problem"}', 2),
  (542, 158, 'In the fraction 7/12, what is the numerator?', 'text', 1, 'Look at the top number.', '{"why":"The numerator is the number written above the fraction bar.","sol":"Step 1: Identify the top number.\nStep 2: The top number is 7.","steps":["Step 1: Identify the top number.","Step 2: The top number is 7."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 0),
  (543, 158, 'In the fraction 7/12, what is the denominator?', 'text', 1, 'Look at the bottom number.', '{"why":"The denominator is the number written below the fraction bar.","sol":"Step 1: Identify the bottom number.\nStep 2: The bottom number is 12.","steps":["Step 1: Identify the bottom number.","Step 2: The bottom number is 12."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 1),
  (544, 158, 'Is 5/8 a proper or improper fraction?', 'text', 1, 'Compare numerator and denominator.', '{"why":"A proper fraction has a numerator smaller than its denominator.","sol":"Step 1: Numerator = 5.\nStep 2: Denominator = 8.\nStep 3: 5 is smaller than 8.","steps":["Step 1: Numerator = 5.","Step 2: Denominator = 8.","Step 3: 5 is smaller than 8."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 2),
  (545, 158, 'Convert 2 3/4 to an improper fraction.', 'text', 1, 'Multiply the whole number by the denominator first.', '{"why":"A mixed number is converted by multiplying the whole number by the denominator and adding the numerator.","sol":"Step 1: 2 × 4 = 8.\nStep 2: 8 + 3 = 11.\nStep 3: Keep denominator 4.\nStep 4: The result is 11/4.","steps":["Step 1: 2 × 4 = 8.","Step 2: 8 + 3 = 11.","Step 3: Keep denominator 4.","Step 4: The result is 11/4."],"options":[],"conceptId":"math_fractions_understanding_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Understanding Fractions"}', 3),
  (546, 159, 'Find an equivalent fraction to 3/4 with denominator 20.', 'text', 1, '4 must become 20.', '{"why":"Both numerator and denominator must be multiplied by the same factor.","sol":"Step 1: 4 × 5 = 20.\nStep 2: Multiply the numerator by 5.\nStep 3: 3 × 5 = 15.","steps":["Step 1: 4 × 5 = 20.","Step 2: Multiply the numerator by 5.","Step 3: 3 × 5 = 15."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 0),
  (547, 159, 'Simplify 12/18.', 'text', 1, 'Find a common factor of 12 and 18.', '{"why":"Dividing numerator and denominator by their greatest common factor gives simplest form.","sol":"Step 1: The greatest common factor is 6.\nStep 2: 12 ÷ 6 = 2.\nStep 3: 18 ÷ 6 = 3.","steps":["Step 1: The greatest common factor is 6.","Step 2: 12 ÷ 6 = 2.","Step 3: 18 ÷ 6 = 3."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 1),
  (548, 159, 'Are 2/3 and 8/12 equivalent?', 'text', 1, 'Simplify 8/12.', '{"why":"Equivalent fractions represent the same value.","sol":"Step 1: Divide 8 and 12 by 4.\nStep 2: 8/12 = 2/3.\nStep 3: Therefore the fractions have the same value.","steps":["Step 1: Divide 8 and 12 by 4.","Step 2: 8/12 = 2/3.","Step 3: Therefore the fractions have the same value."],"options":[],"conceptId":"math_fractions_equivalent_fractions_and_simplifying","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Equivalent Fractions and Simplifying"}', 2),
  (549, 160, 'Which is greater: 5/9 or 2/9?', 'text', 1, 'The denominators are already equal.', '{"why":"With equal positive denominators, the larger numerator gives the larger fraction.","sol":"Step 1: Both denominators are 9.\nStep 2: Compare numerators 5 and 2.\nStep 3: 5 > 2.","steps":["Step 1: Both denominators are 9.","Step 2: Compare numerators 5 and 2.","Step 3: 5 > 2."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 0),
  (550, 160, 'Which is greater: 1/3 or 1/7?', 'text', 1, 'The numerators are equal.', '{"why":"For positive fractions with the same numerator, the smaller denominator gives the larger value.","sol":"Step 1: Both numerators are 1.\nStep 2: Compare denominators.\nStep 3: A third is larger than a seventh.","steps":["Step 1: Both numerators are 1.","Step 2: Compare denominators.","Step 3: A third is larger than a seventh."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 1),
  (551, 160, 'Which is greater: 3/4 or 5/8?', 'text', 1, 'Use a common denominator.', '{"why":"Converting to a common denominator makes comparison direct.","sol":"Step 1: Convert 3/4 to eighths.\nStep 2: 3/4 = 6/8.\nStep 3: Compare 6/8 and 5/8.\nStep 4: 6/8 is greater.","steps":["Step 1: Convert 3/4 to eighths.","Step 2: 3/4 = 6/8.","Step 3: Compare 6/8 and 5/8.","Step 4: 6/8 is greater."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 2),
  (552, 160, 'Which is greater: 4/7 or 5/9?', 'text', 1, 'Cross-multiply.', '{"why":"Cross-products can be compared when determining which of two positive fractions is larger.","sol":"Step 1: 4 × 9 = 36.\nStep 2: 5 × 7 = 35.\nStep 3: 36 > 35.","steps":["Step 1: 4 × 9 = 36.","Step 2: 5 × 7 = 35.","Step 3: 36 > 35."],"options":[],"conceptId":"math_fractions_comparing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Comparing Fractions"}', 3),
  (553, 161, 'Calculate 2/5 + 1/5.', 'text', 1, 'The denominators are already equal.', '{"why":"When denominators are equal, add only the numerators.","sol":"Step 1: Add numerators: 2 + 1 = 3.\nStep 2: Keep denominator 5.\nStep 3: Result = 3/5.","steps":["Step 1: Add numerators: 2 + 1 = 3.","Step 2: Keep denominator 5.","Step 3: Result = 3/5."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 0),
  (554, 161, 'Calculate 1/2 + 1/4.', 'text', 1, 'Change 1/2 into quarters.', '{"why":"A common denominator is required before adding fractions.","sol":"Step 1: LCM of 2 and 4 = 4.\nStep 2: 1/2 = 2/4.\nStep 3: 2/4 + 1/4 = 3/4.","steps":["Step 1: LCM of 2 and 4 = 4.","Step 2: 1/2 = 2/4.","Step 3: 2/4 + 1/4 = 3/4."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 1),
  (555, 161, 'Calculate 5/6 - 1/3.', 'text', 1, 'Convert 1/3 to sixths.', '{"why":"The fractions are first expressed with the same denominator.","sol":"Step 1: 1/3 = 2/6.\nStep 2: 5/6 - 2/6 = 3/6.\nStep 3: Simplify 3/6 to 1/2.","steps":["Step 1: 1/3 = 2/6.","Step 2: 5/6 - 2/6 = 3/6.","Step 3: Simplify 3/6 to 1/2."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 2),
  (556, 161, 'Calculate 2/3 + 3/4.', 'text', 1, 'Use 12 as the common denominator.', '{"why":"The LCM of 3 and 4 is 12.","sol":"Step 1: 2/3 = 8/12.\nStep 2: 3/4 = 9/12.\nStep 3: 8/12 + 9/12 = 17/12.","steps":["Step 1: 2/3 = 8/12.","Step 2: 3/4 = 9/12.","Step 3: 8/12 + 9/12 = 17/12."],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Adding and Subtracting Fractions"}', 3),
  (557, 162, 'Calculate 3/5 × 2/7.', 'text', 1, 'Multiply straight across.', '{"why":"Fractions are multiplied by multiplying corresponding numerators and denominators.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 5 × 7 = 35.\nStep 3: Write the result as 6/35.","steps":["Step 1: 3 × 2 = 6.","Step 2: 5 × 7 = 35.","Step 3: Write the result as 6/35."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 0),
  (558, 162, 'Calculate 2/3 × 3/4.', 'text', 1, 'Multiply and simplify.', '{"why":"The resulting fraction must be simplified.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 6/12 = 1/2.","steps":["Step 1: 2 × 3 = 6.","Step 2: 3 × 4 = 12.","Step 3: 6/12 = 1/2."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 1),
  (559, 162, 'Calculate 4/9 × 3/8.', 'text', 1, 'Cancel common factors first.', '{"why":"Common factors can be cancelled before multiplication.","sol":"Step 1: Cancel 4 with 8 to get 1 and 2.\nStep 2: Cancel 3 with 9 to get 1 and 3.\nStep 3: Multiply 1/3 × 1/2.\nStep 4: Result = 1/6.","steps":["Step 1: Cancel 4 with 8 to get 1 and 2.","Step 2: Cancel 3 with 9 to get 1 and 3.","Step 3: Multiply 1/3 × 1/2.","Step 4: Result = 1/6."],"options":[],"conceptId":"math_fractions_multiplying_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Multiplying Fractions"}', 2),
  (560, 163, 'Calculate 3/4 ÷ 1/2.', 'text', 1, 'Flip the second fraction.', '{"why":"Dividing by a fraction is equivalent to multiplying by its reciprocal.","sol":"Step 1: Keep 3/4.\nStep 2: Change ÷ to ×.\nStep 3: Flip 1/2 to 2/1.\nStep 4: 3/4 × 2/1 = 6/4 = 3/2.","steps":["Step 1: Keep 3/4.","Step 2: Change ÷ to ×.","Step 3: Flip 1/2 to 2/1.","Step 4: 3/4 × 2/1 = 6/4 = 3/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 0),
  (561, 163, 'Calculate 5/6 ÷ 1/3.', 'text', 1, 'The reciprocal of 1/3 is 3.', '{"why":"The second fraction is replaced by its reciprocal.","sol":"Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.\nStep 2: Multiply to get 15/6.\nStep 3: Simplify to 5/2.","steps":["Step 1: 5/6 ÷ 1/3 = 5/6 × 3/1.","Step 2: Multiply to get 15/6.","Step 3: Simplify to 5/2."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 1),
  (562, 163, 'Calculate 2/5 ÷ 2/5.', 'text', 1, 'A non-zero number divided by itself equals 1.', '{"why":"Any non-zero number divided by itself equals 1.","sol":"Step 1: Flip the second fraction: 5/2.\nStep 2: 2/5 × 5/2.\nStep 3: Cancel common factors.\nStep 4: Result = 1.","steps":["Step 1: Flip the second fraction: 5/2.","Step 2: 2/5 × 5/2.","Step 3: Cancel common factors.","Step 4: Result = 1."],"options":[],"conceptId":"math_fractions_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Dividing Fractions"}', 2),
  (563, 164, 'Convert 0.6 to a fraction in simplest form.', 'text', 1, 'Write it over 10.', '{"why":"One decimal place represents tenths.","sol":"Step 1: 0.6 = 6/10.\nStep 2: Divide numerator and denominator by 2.\nStep 3: 6/10 = 3/5.","steps":["Step 1: 0.6 = 6/10.","Step 2: Divide numerator and denominator by 2.","Step 3: 6/10 = 3/5."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 0),
  (564, 164, 'Convert 0.75 to a fraction in simplest form.', 'text', 1, 'Write it over 100.', '{"why":"Two decimal places represent hundredths.","sol":"Step 1: 0.75 = 75/100.\nStep 2: Divide numerator and denominator by 25.\nStep 3: 75/100 = 3/4.","steps":["Step 1: 0.75 = 75/100.","Step 2: Divide numerator and denominator by 25.","Step 3: 75/100 = 3/4."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 1),
  (565, 164, 'Convert 5/8 to a decimal.', 'text', 1, 'Divide 5 by 8.', '{"why":"A fraction can be converted to a decimal by dividing numerator by denominator.","sol":"Step 1: 5 ÷ 8.\nStep 2: 5/8 = 0.625.","steps":["Step 1: 5 ÷ 8.","Step 2: 5/8 = 0.625."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 2),
  (566, 164, 'Convert 7/10 to a decimal.', 'text', 1, 'The denominator is already 10.', '{"why":"A denominator of 10 corresponds directly to one decimal place.","sol":"Step 1: 7/10 represents seven tenths.\nStep 2: Seven tenths is written as 0.7.","steps":["Step 1: 7/10 represents seven tenths.","Step 2: Seven tenths is written as 0.7."],"options":[],"conceptId":"math_fractions_decimals_and_fractions","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Decimals and Fractions"}', 3),
  (567, 165, 'Convert 0.666... to a fraction.', 'text', 1, 'Let x = 0.666... and multiply by 10.', '{"why":"Multiplication by 10 shifts a single repeating digit, allowing subtraction to eliminate the repetition.","sol":"Step 1: x = 0.666...\nStep 2: 10x = 6.666...\nStep 3: 10x − x = 6.\nStep 4: 9x = 6.\nStep 5: x = 6/9 = 2/3.","steps":["Step 1: x = 0.666...","Step 2: 10x = 6.666...","Step 3: 10x − x = 6.","Step 4: 9x = 6.","Step 5: x = 6/9 = 2/3."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 0),
  (568, 165, 'Convert 0.444... to a fraction.', 'text', 1, 'Use x = 0.444... and multiply by 10.', '{"why":"A single repeating digit is eliminated by subtracting x from 10x.","sol":"Step 1: x = 0.444...\nStep 2: 10x = 4.444...\nStep 3: 10x − x = 4.\nStep 4: 9x = 4.\nStep 5: x = 4/9.","steps":["Step 1: x = 0.444...","Step 2: 10x = 4.444...","Step 3: 10x − x = 4.","Step 4: 9x = 4.","Step 5: x = 4/9."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 1),
  (569, 165, 'Convert 0.121212... to a fraction.', 'text', 1, 'Two digits repeat, so use 100.', '{"why":"A two-digit repeating block requires multiplication by 100 to align the repeating parts.","sol":"Step 1: x = 0.121212...\nStep 2: 100x = 12.121212...\nStep 3: 100x − x = 12.\nStep 4: 99x = 12.\nStep 5: x = 12/99 = 4/33.","steps":["Step 1: x = 0.121212...","Step 2: 100x = 12.121212...","Step 3: 100x − x = 12.","Step 4: 99x = 12.","Step 5: x = 12/99 = 4/33."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 2),
  (570, 165, 'Convert 0.090909... to a fraction.', 'text', 1, 'The repeating block is 09.', '{"why":"The repeating block has two digits, so multiplying by 100 aligns the repeating portions.","sol":"Step 1: x = 0.090909...\nStep 2: 100x = 9.090909...\nStep 3: 100x − x = 9.\nStep 4: 99x = 9.\nStep 5: x = 9/99 = 1/11.","steps":["Step 1: x = 0.090909...","Step 2: 100x = 9.090909...","Step 3: 100x − x = 9.","Step 4: 99x = 9.","Step 5: x = 9/99 = 1/11."],"options":[],"conceptId":"math_fractions_recurring_decimals","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Recurring Decimals"}', 3),
  (571, 166, 'Find the area of a rectangle with length 8 cm and width 3 cm.', 'text', 1, 'Use A = l × w.', '{"why":"The area of a rectangle is found by multiplying its length by its width.","sol":"Step 1: Write the formula: A = l × w.\nStep 2: Substitute l = 8 and w = 3.\nStep 3: A = 8 × 3.\nStep 4: A = 24.","steps":["Step 1: Write the formula: A = l × w.","Step 2: Substitute l = 8 and w = 3.","Step 3: A = 8 × 3.","Step 4: A = 24."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 0),
  (572, 166, 'Find the area of a square with side 7 cm.', 'text', 1, 'A = side².', '{"why":"All sides of a square are equal, so its area is side × side.","sol":"Step 1: A = side × side.\nStep 2: A = 7 × 7.\nStep 3: A = 49.","steps":["Step 1: A = side × side.","Step 2: A = 7 × 7.","Step 3: A = 49."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 1),
  (573, 166, 'A rectangle has area 45 cm² and width 5 cm. Find its length.', 'text', 1, 'Length = area ÷ width.', '{"why":"The missing length is found by rearranging A = l × w.","sol":"Step 1: A = l × w.\nStep 2: 45 = l × 5.\nStep 3: Divide both sides by 5.\nStep 4: l = 9.","steps":["Step 1: A = l × w.","Step 2: 45 = l × 5.","Step 3: Divide both sides by 5.","Step 4: l = 9."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 2),
  (574, 166, 'A rectangle has length 9 cm and width 5 cm. What is its area?', 'text', 1, 'Multiply 9 by 5.', '{"why":"Area measures the two-dimensional space inside the rectangle.","sol":"Step 1: A = 9 × 5.\nStep 2: A = 45.","steps":["Step 1: A = 9 × 5.","Step 2: A = 45."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 3),
  (575, 166, 'Which formula gives the area of a rectangle?', 'text', 1, 'Think about its two dimensions.', '{"why":"Rectangle area is length multiplied by width.","sol":"Step 1: A rectangle has length and width.\nStep 2: Multiply the two dimensions.\nStep 3: A = l × w.","steps":["Step 1: A rectangle has length and width.","Step 2: Multiply the two dimensions.","Step 3: A = l × w."],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Area of Rectangles and Squares"}', 4),
  (576, 167, 'Find the area of a triangle with base 12 cm and height 4 cm.', 'text', 1, 'Use A = 1/2 × b × h.', '{"why":"Triangle area is half the product of its base and perpendicular height.","sol":"Step 1: A = 1/2 × 12 × 4.\nStep 2: 12 ÷ 2 = 6.\nStep 3: 6 × 4 = 24.","steps":["Step 1: A = 1/2 × 12 × 4.","Step 2: 12 ÷ 2 = 6.","Step 3: 6 × 4 = 24."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 0),
  (577, 167, 'A triangle has base 14 cm and height 6 cm. Find its area.', 'text', 1, 'Multiply the base and height, then divide by 2.', '{"why":"The factor 1/2 is required because a triangle occupies half the corresponding base-height rectangle.","sol":"Step 1: A = 1/2 × 14 × 6.\nStep 2: 14 × 6 = 84.\nStep 3: 84 ÷ 2 = 42.","steps":["Step 1: A = 1/2 × 14 × 6.","Step 2: 14 × 6 = 84.","Step 3: 84 ÷ 2 = 42."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 1),
  (578, 167, 'A triangle has area 40 cm² and base 10 cm. Find its perpendicular height.', 'text', 1, 'h = 2A ÷ b.', '{"why":"Rearranging A = 1/2bh gives h = 2A ÷ b.","sol":"Step 1: h = 2A ÷ b.\nStep 2: h = (2 × 40) ÷ 10.\nStep 3: h = 80 ÷ 10.\nStep 4: h = 8.","steps":["Step 1: h = 2A ÷ b.","Step 2: h = (2 × 40) ÷ 10.","Step 3: h = 80 ÷ 10.","Step 4: h = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 2),
  (579, 167, 'A triangle has area 24 cm² and height 6 cm. Find its base.', 'text', 1, 'b = 2A ÷ h.', '{"why":"The formula can be rearranged to find an unknown base.","sol":"Step 1: b = 2A ÷ h.\nStep 2: b = (2 × 24) ÷ 6.\nStep 3: b = 48 ÷ 6.\nStep 4: b = 8.","steps":["Step 1: b = 2A ÷ h.","Step 2: b = (2 × 24) ÷ 6.","Step 3: b = 48 ÷ 6.","Step 4: b = 8."],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of Triangles"}', 3),
  (580, 168, 'Find the volume of a cuboid measuring 8 cm × 3 cm × 2 cm.', 'text', 1, 'Multiply all three dimensions.', '{"why":"Cuboid volume is the product of its three dimensions.","sol":"Step 1: V = l × w × h.\nStep 2: V = 8 × 3 × 2.\nStep 3: V = 48.","steps":["Step 1: V = l × w × h.","Step 2: V = 8 × 3 × 2.","Step 3: V = 48."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 0),
  (581, 168, 'Find the volume of a cube with side 5 cm.', 'text', 1, 'V = s³.', '{"why":"A cube has three equal dimensions, so its volume is side cubed.","sol":"Step 1: V = 5 × 5 × 5.\nStep 2: 5 × 5 = 25.\nStep 3: 25 × 5 = 125.","steps":["Step 1: V = 5 × 5 × 5.","Step 2: 5 × 5 = 25.","Step 3: 25 × 5 = 125."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 1),
  (582, 168, 'A cuboid has volume 60 cm³, length 5 cm and width 3 cm. Find its height.', 'text', 1, 'h = V ÷ (lw).', '{"why":"Rearranging V = lwh gives h = V ÷ (lw).","sol":"Step 1: h = V ÷ (lw).\nStep 2: h = 60 ÷ (5 × 3).\nStep 3: h = 60 ÷ 15.\nStep 4: h = 4.","steps":["Step 1: h = V ÷ (lw).","Step 2: h = 60 ÷ (5 × 3).","Step 3: h = 60 ÷ 15.","Step 4: h = 4."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 2),
  (583, 168, 'Which formula gives the volume of a cuboid?', 'text', 1, 'A cuboid has three dimensions.', '{"why":"Volume of a cuboid is the product of its length, width and height.","sol":"Step 1: Identify the three dimensions.\nStep 2: Multiply length, width and height.","steps":["Step 1: Identify the three dimensions.","Step 2: Multiply length, width and height."],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Volume of Cubes and Cuboids"}', 3),
  (584, 169, 'Find the surface area of a cube with side 5 cm.', 'text', 1, 'Use SA = 6s².', '{"why":"A cube has six equal square faces.","sol":"Step 1: SA = 6 × 5².\nStep 2: 5² = 25.\nStep 3: 6 × 25 = 150.","steps":["Step 1: SA = 6 × 5².","Step 2: 5² = 25.","Step 3: 6 × 25 = 150."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 0),
  (585, 169, 'Find the surface area of a cube with side 3 cm.', 'text', 1, 'Square the side, then multiply by 6.', '{"why":"The six faces of the cube each have area 9 cm².","sol":"Step 1: 3² = 9.\nStep 2: 6 × 9 = 54.","steps":["Step 1: 3² = 9.","Step 2: 6 × 9 = 54."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 1),
  (586, 169, 'Find the surface area of a cuboid with length 4 cm, width 3 cm and height 2 cm.', 'text', 1, 'Use SA = 2(lw + lh + wh).', '{"why":"The three different face areas each occur twice.","sol":"Step 1: lw = 4 × 3 = 12.\nStep 2: lh = 4 × 2 = 8.\nStep 3: wh = 3 × 2 = 6.\nStep 4: Add: 12 + 8 + 6 = 26.\nStep 5: Multiply by 2: 2 × 26 = 52.","steps":["Step 1: lw = 4 × 3 = 12.","Step 2: lh = 4 × 2 = 8.","Step 3: wh = 3 × 2 = 6.","Step 4: Add: 12 + 8 + 6 = 26.","Step 5: Multiply by 2: 2 × 26 = 52."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 2),
  (587, 169, 'Which formula gives the surface area of a cuboid?', 'text', 1, 'There are three pairs of equal faces.', '{"why":"A cuboid has two faces of each of its three different dimensions.","sol":"Step 1: Identify the three face areas: lw, lh and wh.\nStep 2: Add them.\nStep 3: Multiply by 2.","steps":["Step 1: Identify the three face areas: lw, lh and wh.","Step 2: Add them.","Step 3: Multiply by 2."],"options":[],"conceptId":"math_measurement_surface_area_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Surface Area of Cubes and Cuboids"}', 3),
  (588, 170, 'What unit should be used for the area of a rectangle measured in centimetres?', 'text', 1, 'Area uses squared units.', '{"why":"Area measures two dimensions, so its units are squared.","sol":"Step 1: The quantity is area.\nStep 2: Area uses square units.\nStep 3: Therefore the unit is cm².","steps":["Step 1: The quantity is area.","Step 2: Area uses square units.","Step 3: Therefore the unit is cm²."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 0),
  (589, 170, 'What unit should be used for the volume of a cuboid measured in centimetres?', 'text', 1, 'Volume uses three dimensions.', '{"why":"Volume measures three dimensions, so its units are cubed.","sol":"Step 1: The quantity is volume.\nStep 2: Volume uses cubic units.\nStep 3: Therefore the unit is cm³.","steps":["Step 1: The quantity is volume.","Step 2: Volume uses cubic units.","Step 3: Therefore the unit is cm³."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 1),
  (590, 170, 'Convert 1 m² to cm².', 'text', 1, '1 m = 100 cm, then square the conversion factor.', '{"why":"Area conversion factors must be squared.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Square both sides.\nStep 3: 1 m² = 100² cm².\nStep 4: 100² = 10,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Square both sides.","Step 3: 1 m² = 100² cm².","Step 4: 100² = 10,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 2),
  (591, 170, 'Convert 1 m³ to cm³.', 'text', 1, '1 m = 100 cm, then cube the conversion factor.', '{"why":"Volume conversion factors must be cubed.","sol":"Step 1: 1 m = 100 cm.\nStep 2: Cube both sides.\nStep 3: 1 m³ = 100³ cm³.\nStep 4: 100³ = 1,000,000.","steps":["Step 1: 1 m = 100 cm.","Step 2: Cube both sides.","Step 3: 1 m³ = 100³ cm³.","Step 4: 100³ = 1,000,000."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 3),
  (592, 170, 'Which is larger: 1 m² or 100 cm²?', 'text', 1, 'Convert 1 m² into cm².', '{"why":"Squared units require the length conversion factor to be squared.","sol":"Step 1: 1 m² = 10,000 cm².\nStep 2: Compare 10,000 cm² and 100 cm².\nStep 3: 10,000 cm² is larger.","steps":["Step 1: 1 m² = 10,000 cm².","Step 2: Compare 10,000 cm² and 100 cm².","Step 3: 10,000 cm² is larger."],"options":[],"conceptId":"math_measurement_measurement_units_and_dimensions","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Measurement Units and Dimensions"}', 4),
  (593, 171, 'Find the distance between points (2,3) and (6,7)', 'text', 1, 'distance formula', '{"why":"Distance between two points is found using Euclidean formula","sol":"Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)\nStep 2: Substitute values (6−2) and (7−3)\nStep 3: Compute 4² and 4²\nStep 4: Add results\nStep 5: Take square root","steps":["Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)","Step 2: Substitute values (6−2) and (7−3)","Step 3: Compute 4² and 4²","Step 4: Add results","Step 5: Take square root"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 0),
  (594, 171, 'Find midpoint of (2,4) and (8,10)', 'text', 1, 'midpoint formula', '{"why":"Midpoint is average of coordinates","sol":"Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)\nStep 2: Substitute values\nStep 3: Compute x-coordinate\nStep 4: Compute y-coordinate\nStep 5: Form midpoint","steps":["Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)","Step 2: Substitute values","Step 3: Compute x-coordinate","Step 4: Compute y-coordinate","Step 5: Form midpoint"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 1),
  (595, 171, 'Determine the coordinates after moving from (3,5) by +4 in x and −2 in y', 'text', 1, 'translation', '{"why":"Translation shifts points by vector addition","sol":"Step 1: Start at (3,5)\nStep 2: Add 4 to x-coordinate\nStep 3: Subtract 2 from y-coordinate\nStep 4: Write new coordinates","steps":["Step 1: Start at (3,5)","Step 2: Add 4 to x-coordinate","Step 3: Subtract 2 from y-coordinate","Step 4: Write new coordinates"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 2),
  (596, 171, 'Find slope between points (1,2) and (5,10)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change between two points","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute numerator 8\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute numerator 8","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 3),
  (597, 171, 'Find equation of line passing through (0,0) with slope 3', 'text', 1, 'y = mx + c', '{"why":"Line equation is determined by slope and intercept","sol":"Step 1: Use y = mx + c\nStep 2: Substitute m = 3\nStep 3: Use point (0,0) to find c\nStep 4: Solve for c\nStep 5: Write final equation","steps":["Step 1: Use y = mx + c","Step 2: Substitute m = 3","Step 3: Use point (0,0) to find c","Step 4: Solve for c","Step 5: Write final equation"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 4),
  (598, 172, 'Locate the point (3, -2) on a coordinate plane and describe its movement from origin', 'text', 1, 'x then y movement', '{"why":"Coordinates represent horizontal (x) and vertical (y) displacement from origin","sol":"Step 1: Start at origin (0,0)\nStep 2: Move +3 units along x-axis\nStep 3: Move −2 units along y-axis\nStep 4: Mark final position on plane","steps":["Step 1: Start at origin (0,0)","Step 2: Move +3 units along x-axis","Step 3: Move −2 units along y-axis","Step 4: Mark final position on plane"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Plotting points"}', 0),
  (599, 172, 'Find coordinates after moving 5 units right and 4 units up from origin', 'text', 1, 'directional movement', '{"why":"Positive x and y values place the point in the first quadrant","sol":"Step 1: Start at (0,0)\nStep 2: Move +5 along x-axis\nStep 3: Move +4 along y-axis\nStep 4: Plot final point","steps":["Step 1: Start at (0,0)","Step 2: Move +5 along x-axis","Step 3: Move +4 along y-axis","Step 4: Plot final point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Plotting points"}', 1),
  (600, 172, 'Determine location of point (0, -6) on coordinate plane', 'text', 1, 'axis identification', '{"why":"x = 0 means the point lies directly on the y-axis","sol":"Step 1: Check x = 0\nStep 2: Move only along y-axis\nStep 3: Locate negative direction\nStep 4: Identify axis position","steps":["Step 1: Check x = 0","Step 2: Move only along y-axis","Step 3: Locate negative direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Plotting points"}', 2),
  (601, 172, 'Determine location of point (4, 0) on coordinate plane', 'text', 1, 'axis rule', '{"why":"y = 0 means the point lies on the x-axis","sol":"Step 1: Check y = 0\nStep 2: Move only along x-axis\nStep 3: Locate positive direction\nStep 4: Identify axis position","steps":["Step 1: Check y = 0","Step 2: Move only along x-axis","Step 3: Locate positive direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Plotting points"}', 3),
  (602, 172, 'Identify the reference starting point for all coordinate plotting', 'text', 1, 'origin concept', '{"why":"All coordinates are measured from the origin","sol":"Step 1: Locate intersection of axes\nStep 2: Identify x = 0 and y = 0\nStep 3: Mark central reference point","steps":["Step 1: Locate intersection of axes","Step 2: Identify x = 0 and y = 0","Step 3: Mark central reference point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Plotting points"}', 4),
  (603, 173, 'Plot a line graph for points (1,2), (2,3), (3,5)', 'text', 1, 'coordinate plotting', '{"why":"Increasing y-values show upward trend","sol":"Step 1: Draw x-axis and y-axis\nStep 2: Plot (1,2), (2,3), (3,5)\nStep 3: Check correct positions on plane\nStep 4: Join points in order with straight lines","steps":["Step 1: Draw x-axis and y-axis","Step 2: Plot (1,2), (2,3), (3,5)","Step 3: Check correct positions on plane","Step 4: Join points in order with straight lines"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Line graphs"}', 0),
  (604, 173, 'Identify change when graph goes from (1,5) to (3,5)', 'text', 1, 'constant value', '{"why":"Equal y-values form a horizontal line","sol":"Step 1: Compare y-values at both points\nStep 2: 5 and 5 are equal\nStep 3: Determine slope behavior\nStep 4: Classify trend","steps":["Step 1: Compare y-values at both points","Step 2: 5 and 5 are equal","Step 3: Determine slope behavior","Step 4: Classify trend"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Line graphs"}', 1),
  (605, 173, 'Determine trend of points (1,4), (2,3), (3,2)', 'text', 1, 'decreasing pattern', '{"why":"Y-values reduce as x increases","sol":"Step 1: Observe y-values\nStep 2: 4 → 3 → 2\nStep 3: Check direction of change\nStep 4: Classify graph behavior","steps":["Step 1: Observe y-values","Step 2: 4 → 3 → 2","Step 3: Check direction of change","Step 4: Classify graph behavior"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Line graphs"}', 2),
  (606, 173, 'Find slope between points (1,1) and (4,7)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change in a line graph","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute 7 − 1 = 6\nStep 4: Compute 4 − 1 = 3\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute 7 − 1 = 6","Step 4: Compute 4 − 1 = 3","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Line graphs"}', 3),
  (607, 173, 'Find missing point pattern if graph is linear: (1,2), (2,?), (3,6)', 'text', 1, 'linear pattern', '{"why":"Linear graphs have constant rate of change","sol":"Step 1: Observe change from 1 to 3 in x\nStep 2: Observe change from 2 to 6 in y\nStep 3: Determine pattern increase\nStep 4: Find middle value","steps":["Step 1: Observe change from 1 to 3 in x","Step 2: Observe change from 2 to 6 in y","Step 3: Determine pattern increase","Step 4: Find middle value"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Line graphs"}', 4),
  (608, 174, 'Find gradient when rise = 12 and run = 3', 'text', 1, 'm = rise ÷ run', '{"why":"Gradient measures vertical change per unit horizontal change","sol":"Step 1: Write m = rise ÷ run\nStep 2: Substitute m = 12 ÷ 3\nStep 3: Compute division\nStep 4: Simplify result","steps":["Step 1: Write m = rise ÷ run","Step 2: Substitute m = 12 ÷ 3","Step 3: Compute division","Step 4: Simplify result"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Gradient"}', 0),
  (609, 174, 'Find gradient between points (2,5) and (6,1)', 'text', 1, 'use coordinate formula', '{"why":"Gradient is found using change in y over change in x","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values (1 − 5)/(6 − 2)\nStep 3: Compute numerator −4\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values (1 − 5)/(6 − 2)","Step 3: Compute numerator −4","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Gradient"}', 1),
  (610, 174, 'Interpret gradient m = -3 in a line', 'text', 1, 'direction', '{"why":"Negative gradient shows downward movement from left to right","sol":"Step 1: Identify sign of gradient\nStep 2: m < 0 indicates negative slope\nStep 3: For each 1 step right, y decreases by 3\nStep 4: Describe direction","steps":["Step 1: Identify sign of gradient","Step 2: m < 0 indicates negative slope","Step 3: For each 1 step right, y decreases by 3","Step 4: Describe direction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Gradient"}', 2),
  (611, 174, 'Interpret gradient m = 0', 'text', 1, 'flat line', '{"why":"Zero gradient means constant y-value across x","sol":"Step 1: Check gradient value\nStep 2: m = 0 means no vertical change\nStep 3: y-value remains constant\nStep 4: Describe graph","steps":["Step 1: Check gradient value","Step 2: m = 0 means no vertical change","Step 3: y-value remains constant","Step 4: Describe graph"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Gradient"}', 3),
  (612, 175, 'Why are graphs important?', 'text', 1, 'show data visually', '{"why":"Graphs convert numerical data into visual form, making patterns and trends easier to understand","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand\nStep 3: State the final conclusion: data visualization","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand","Step 3: State the final conclusion: data visualization"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 0),
  (613, 175, 'What do graphs help us identify?', 'text', 1, 'look at shape of graph', '{"why":"Graphs show how data changes over time or categories, revealing hidden patterns","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns\nStep 3: State the final conclusion: patterns and trends","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns","Step 3: State the final conclusion: patterns and trends"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 1),
  (614, 175, 'Give one real-life use of graphs', 'text', 1, 'daily applications', '{"why":"Graphs are widely used to analyze weather, sales, population, and scientific data","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data\nStep 3: State the final conclusion: weather forecasting or business analysis","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data","Step 3: State the final conclusion: weather forecasting or business analysis"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 2),
  (615, 176, 'Simplify the ratio 24:36', 'text', 1, 'HCF method', '{"why":"Ratios are simplified by dividing both terms by their highest common factor","sol":"Step 1: Find HCF of 24 and 36\nStep 2: HCF = 12\nStep 3: Divide both terms by 12\nStep 4: 24 ÷ 12 and 36 ÷ 12\nStep 5: Write simplified ratio","steps":["Step 1: Find HCF of 24 and 36","Step 2: HCF = 12","Step 3: Divide both terms by 12","Step 4: 24 ÷ 12 and 36 ÷ 12","Step 5: Write simplified ratio"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 0),
  (616, 176, 'Divide 60 in the ratio 2:3', 'text', 1, 'total parts method', '{"why":"Total is split according to ratio parts","sol":"Step 1: Add ratio parts 2 + 3 = 5\nStep 2: Divide 60 by 5\nStep 3: One part = 12\nStep 4: Multiply 2 × 12 and 3 × 12\nStep 5: Find each share","steps":["Step 1: Add ratio parts 2 + 3 = 5","Step 2: Divide 60 by 5","Step 3: One part = 12","Step 4: Multiply 2 × 12 and 3 × 12","Step 5: Find each share"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 1),
  (617, 176, 'Find ratio of 45 to 15 in simplest form', 'text', 1, 'divide both terms', '{"why":"Simplification reduces ratio to smallest whole numbers","sol":"Step 1: Write ratio 45:15\nStep 2: Find HCF = 15\nStep 3: Divide both terms by 15\nStep 4: Simplify result","steps":["Step 1: Write ratio 45:15","Step 2: Find HCF = 15","Step 3: Divide both terms by 15","Step 4: Simplify result"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 2),
  (618, 176, 'Check if ratios 4:6 and 2:3 are equivalent', 'text', 1, 'compare simplified forms', '{"why":"Equivalent ratios reduce to the same simplest form","sol":"Step 1: Simplify 4:6\nStep 2: Divide both by 2 → 2:3\nStep 3: Compare with 2:3\nStep 4: Conclude equivalence","steps":["Step 1: Simplify 4:6","Step 2: Divide both by 2 → 2:3","Step 3: Compare with 2:3","Step 4: Conclude equivalence"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 3),
  (619, 177, 'Divide 120 in the ratio 3:2', 'text', 1, 'total parts method', '{"why":"Total is distributed proportionally using ratio parts","sol":"Step 1: Add ratio parts 3 + 2 = 5\nStep 2: Divide 120 by 5\nStep 3: One part = 24\nStep 4: Multiply 3 × 24\nStep 5: Multiply 2 × 24\nStep 6: Write final split","steps":["Step 1: Add ratio parts 3 + 2 = 5","Step 2: Divide 120 by 5","Step 3: One part = 24","Step 4: Multiply 3 × 24","Step 5: Multiply 2 × 24","Step 6: Write final split"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 0),
  (620, 177, 'Divide 250 in the ratio 5:3', 'text', 1, 'part value method', '{"why":"Each share is proportional to its ratio weight","sol":"Step 1: Add ratio parts 5 + 3 = 8\nStep 2: Divide 250 by 8\nStep 3: One part = 31.25\nStep 4: Multiply 5 × 31.25\nStep 5: Multiply 3 × 31.25\nStep 6: Write final values","steps":["Step 1: Add ratio parts 5 + 3 = 8","Step 2: Divide 250 by 8","Step 3: One part = 31.25","Step 4: Multiply 5 × 31.25","Step 5: Multiply 3 × 31.25","Step 6: Write final values"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 1),
  (621, 177, 'Check if 40:60 simplifies correctly to 2:3', 'text', 1, 'simplification check', '{"why":"Both ratios represent the same proportional relationship","sol":"Step 1: Write ratio 40:60\nStep 2: Find HCF = 20\nStep 3: Divide both terms by 20\nStep 4: Get simplified form\nStep 5: Compare with 2:3","steps":["Step 1: Write ratio 40:60","Step 2: Find HCF = 20","Step 3: Divide both terms by 20","Step 4: Get simplified form","Step 5: Compare with 2:3"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 2),
  (622, 177, 'Find value of one part if 84 is divided in ratio 2:5', 'text', 1, 'total parts method', '{"why":"Each unit of ratio is found by dividing total by sum of parts","sol":"Step 1: Add ratio parts 2 + 5 = 7\nStep 2: Divide 84 by 7\nStep 3: One part = 12\nStep 4: Use part value for distribution","steps":["Step 1: Add ratio parts 2 + 5 = 7","Step 2: Divide 84 by 7","Step 3: One part = 12","Step 4: Use part value for distribution"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 3),
  (623, 178, 'Solve for x: 6:9 = x:27', 'text', 1, 'cross multiplication', '{"why":"Cross multiplication removes ratios and forms a solvable equation","sol":"Step 1: Write proportion 6/9 = x/27\nStep 2: Cross multiply → 6 × 27 = 9x\nStep 3: Compute 162 = 9x\nStep 4: Divide both sides by 9\nStep 5: Solve for x","steps":["Step 1: Write proportion 6/9 = x/27","Step 2: Cross multiply → 6 × 27 = 9x","Step 3: Compute 162 = 9x","Step 4: Divide both sides by 9","Step 5: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Proportion"}', 0),
  (624, 178, 'Solve for x: 8:12 = 20:x', 'text', 1, 'diagonal multiplication', '{"why":"Proportions are solved by equating cross products","sol":"Step 1: Write 8/12 = 20/x\nStep 2: Cross multiply → 8x = 240\nStep 3: Divide both sides by 8\nStep 4: Solve for x","steps":["Step 1: Write 8/12 = 20/x","Step 2: Cross multiply → 8x = 240","Step 3: Divide both sides by 8","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Proportion"}', 1),
  (625, 178, 'Check if 3:5 and 12:20 form a proportion', 'text', 1, 'simplify ratio', '{"why":"Equivalent ratios form a valid proportion","sol":"Step 1: Simplify 12:20 by dividing by 4\nStep 2: Get 3:5\nStep 3: Compare both ratios\nStep 4: Confirm equality","steps":["Step 1: Simplify 12:20 by dividing by 4","Step 2: Get 3:5","Step 3: Compare both ratios","Step 4: Confirm equality"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Proportion"}', 2),
  (626, 178, 'What is the value of x in 7/ x = 14/28', 'text', 1, 'cross multiply', '{"why":"Cross multiplication converts proportion into linear equation","sol":"Step 1: Cross multiply → 7 × 28 = 14x\nStep 2: Compute 196 = 14x\nStep 3: Divide both sides by 14\nStep 4: Solve for x","steps":["Step 1: Cross multiply → 7 × 28 = 14x","Step 2: Compute 196 = 14x","Step 3: Divide both sides by 14","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Proportion"}', 3),
  (627, 179, 'If 6 notebooks cost 90, find the cost of 1 notebook', 'text', 1, 'unit rate', '{"why":"Unit cost is found by dividing total cost by number of items","sol":"Step 1: Write total cost = 90 and quantity = 6\nStep 2: Compute 90 ÷ 6\nStep 3: Find cost per notebook\nStep 4: State unit price","steps":["Step 1: Write total cost = 90 and quantity = 6","Step 2: Compute 90 ÷ 6","Step 3: Find cost per notebook","Step 4: State unit price"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 0),
  (628, 179, 'Find k if y = kx, when y = 36 and x = 9', 'text', 1, 'constant of proportionality', '{"why":"k represents constant ratio between y and x","sol":"Step 1: Write y = kx\nStep 2: Substitute 36 = k × 9\nStep 3: Divide both sides by 9\nStep 4: Solve for k","steps":["Step 1: Write y = kx","Step 2: Substitute 36 = k × 9","Step 3: Divide both sides by 9","Step 4: Solve for k"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 1),
  (629, 179, 'If y = 5x, find y when x = 7', 'text', 1, 'substitution', '{"why":"Direct proportion uses substitution into linear equation","sol":"Step 1: Write equation y = 5x\nStep 2: Substitute x = 7\nStep 3: Multiply 5 × 7\nStep 4: Compute y value","steps":["Step 1: Write equation y = 5x","Step 2: Substitute x = 7","Step 3: Multiply 5 × 7","Step 4: Compute y value"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 2),
  (630, 179, 'If x doubles in y = 3x, what happens to y when x changes from 4 to 8?', 'text', 1, 'scaling', '{"why":"In direct proportion, scaling x scales y by same factor","sol":"Step 1: Compute y when x = 4 → y = 3 × 4\nStep 2: Compute y when x = 8 → y = 3 × 8\nStep 3: Compare both results\nStep 4: Identify relationship","steps":["Step 1: Compute y when x = 4 → y = 3 × 4","Step 2: Compute y when x = 8 → y = 3 × 8","Step 3: Compare both results","Step 4: Identify relationship"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 3),
  (631, 180, 'If y is inversely proportional to x and x = 6, y = 12, find k in x × y = k', 'text', 1, 'constant of inverse proportion', '{"why":"In inverse proportion, the product of x and y stays constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute values k = 6 × 12\nStep 3: Multiply to find k","steps":["Step 1: Write k = x × y","Step 2: Substitute values k = 6 × 12","Step 3: Multiply to find k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 0),
  (632, 180, 'If x = 9 and y = 8 in an inverse proportion, find k', 'text', 1, 'multiply values', '{"why":"Inverse proportion means x × y remains constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute k = 9 × 8\nStep 3: Compute product","steps":["Step 1: Write k = x × y","Step 2: Substitute k = 9 × 8","Step 3: Compute product"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 1),
  (633, 180, 'If y is inversely proportional to x and x = 3, y = 20, find k', 'text', 1, 'constant product rule', '{"why":"The product of variables remains unchanged in inverse proportion","sol":"Step 1: Use k = x × y\nStep 2: Substitute 3 × 20\nStep 3: Calculate k","steps":["Step 1: Use k = x × y","Step 2: Substitute 3 × 20","Step 3: Calculate k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 2),
  (634, 180, 'If x = 5 and y = 14 in inverse proportion, determine k', 'text', 1, 'multiply', '{"why":"Inverse proportion keeps product of variables constant","sol":"Step 1: Write formula k = x × y\nStep 2: Substitute values 5 × 14\nStep 3: Compute result","steps":["Step 1: Write formula k = x × y","Step 2: Substitute values 5 × 14","Step 3: Compute result"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 3),
  (635, 180, 'If y is inversely proportional to x and x = 2, y = 30, find k', 'text', 1, 'constant product', '{"why":"Inverse proportion is defined by a constant product relationship","sol":"Step 1: Write k = x × y\nStep 2: Substitute 2 × 30\nStep 3: Multiply to get k","steps":["Step 1: Write k = x × y","Step 2: Substitute 2 × 30","Step 3: Multiply to get k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q5","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 4),
  (636, 181, 'A teacher records the marks 34, 47, 51 and 63 for four learners. What do these recorded values represent?', 'text', 1, 'Think about what recorded observations are called.', '{"why":"The marks are recorded information, so they form a data set.","sol":"Step 1: The numbers are recorded observations.\nStep 2: A collection of recorded observations is called data.","steps":["Step 1: The numbers are recorded observations.","Step 2: A collection of recorded observations is called data."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 0),
  (637, 181, 'A class records the favourite fruits of its learners as mango, banana, orange and mango. Are these observations data?', 'text', 1, 'Data does not have to be numerical.', '{"why":"Data can be numerical or non-numerical.","sol":"Step 1: The fruit names are recorded observations.\nStep 2: Recorded observations are data even when they are words rather than numbers.","steps":["Step 1: The fruit names are recorded observations.","Step 2: Recorded observations are data even when they are words rather than numbers."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 1),
  (638, 181, 'A learner writes 12, 15, 9 and 20 after counting the books read by four learners. What are these values?', 'text', 1, 'They are recorded observations.', '{"why":"The numbers are recorded information collected for a purpose.","sol":"Step 1: The learner has recorded four observations.\nStep 2: Those observations form a data set.","steps":["Step 1: The learner has recorded four observations.","Step 2: Those observations form a data set."],"options":[],"conceptId":"math_statistics_meaning_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Data"}', 2),
  (639, 182, 'A teacher calculates the average mark of a class from the recorded test scores. Is the teacher using data or statistics?', 'text', 1, 'The marks are data. What is being done to the marks?', '{"why":"The teacher is performing a statistical operation on collected data.","sol":"Step 1: The recorded marks are data.\nStep 2: Calculating an average is analysing the data.\nStep 3: Analysing data is part of statistics.","steps":["Step 1: The recorded marks are data.","Step 2: Calculating an average is analysing the data.","Step 3: Analysing data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 0),
  (640, 182, 'A school records the ages of 100 learners. Are the recorded ages themselves statistics?', 'text', 1, 'Separate the information collected from what we do with it.', '{"why":"The recorded ages are the raw information being used in statistics.","sol":"Step 1: The ages are recorded observations.\nStep 2: Recorded observations are data.\nStep 3: They become part of statistical work when they are organised, analysed or interpreted.","steps":["Step 1: The ages are recorded observations.","Step 2: Recorded observations are data.","Step 3: They become part of statistical work when they are organised, analysed or interpreted."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 1),
  (641, 182, 'A learner draws a graph from a table of collected marks. Is this part of statistics?', 'text', 1, 'Think about representing data.', '{"why":"Representing data is one of the main activities in statistics.","sol":"Step 1: The marks are data.\nStep 2: The learner is representing the data graphically.\nStep 3: Representation of data is part of statistics.","steps":["Step 1: The marks are data.","Step 2: The learner is representing the data graphically.","Step 3: Representation of data is part of statistics."],"options":[],"conceptId":"math_statistics_meaning_of_statistics","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Statistics"}', 2),
  (642, 183, 'A learner asks 20 classmates how much money they spend on lunch each day and records their answers. Is this primary or secondary data?', 'text', 1, 'Who collected the information?', '{"why":"It was collected directly by the investigator.","sol":"Step 1: The learner directly asked the classmates.\nStep 2: The learner collected the information for the investigation.\nStep 3: Therefore, the data is primary data.","steps":["Step 1: The learner directly asked the classmates.","Step 2: The learner collected the information for the investigation.","Step 3: Therefore, the data is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Primary Data"}', 0),
  (643, 183, 'A teacher measures the heights of learners in her class for a school investigation. What type of data is collected?', 'text', 1, 'The teacher is collecting the measurements directly.', '{"why":"The measurements come directly from the original investigation.","sol":"Step 1: The teacher measures the learners herself.\nStep 2: The measurements are collected directly.\nStep 3: Therefore, they are primary data.","steps":["Step 1: The teacher measures the learners herself.","Step 2: The measurements are collected directly.","Step 3: Therefore, they are primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Primary Data"}', 1),
  (644, 183, 'A researcher interviews 50 farmers and records their answers. Is the information primary data?', 'text', 1, 'Look at who obtained the information.', '{"why":"The researcher collected the information directly.","sol":"Step 1: The researcher directly interviews the farmers.\nStep 2: The researcher obtains the information firsthand.\nStep 3: Therefore, the information is primary data.","steps":["Step 1: The researcher directly interviews the farmers.","Step 2: The researcher obtains the information firsthand.","Step 3: Therefore, the information is primary data."],"options":[],"conceptId":"math_statistics_primary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Primary Data"}', 2),
  (645, 184, 'A student uses population figures from a published government report. Is this primary or secondary data?', 'text', 1, 'Did the student collect the population figures herself?', '{"why":"The information was collected previously by another source.","sol":"Step 1: The figures had already been collected and published.\nStep 2: The student is using existing information.\nStep 3: Therefore, the data is secondary data.","steps":["Step 1: The figures had already been collected and published.","Step 2: The student is using existing information.","Step 3: Therefore, the data is secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 0),
  (646, 184, 'A researcher uses rainfall records collected by another organisation five years earlier. What type of data is this?', 'text', 1, 'The researcher did not originally collect the measurements.', '{"why":"The researcher is using previously collected information.","sol":"Step 1: The rainfall measurements already existed.\nStep 2: Another organisation collected them.\nStep 3: Therefore, they are secondary data for the researcher.","steps":["Step 1: The rainfall measurements already existed.","Step 2: Another organisation collected them.","Step 3: Therefore, they are secondary data for the researcher."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 1),
  (647, 184, 'A learner measures today''s temperature herself and records it. Is this secondary data?', 'text', 1, 'Who collected the measurement?', '{"why":"The learner collected the measurement directly.","sol":"Step 1: The learner directly measures the temperature.\nStep 2: The measurement is collected firsthand.\nStep 3: Therefore, it is primary data, not secondary data.","steps":["Step 1: The learner directly measures the temperature.","Step 2: The measurement is collected firsthand.","Step 3: Therefore, it is primary data, not secondary data."],"options":[],"conceptId":"math_statistics_secondary_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Secondary Data"}', 2),
  (648, 185, 'A school records the favourite subjects of learners as Mathematics, English, Biology and Physics. What type of data is this?', 'text', 1, 'Are the values measurements or categories?', '{"why":"The observations describe categories rather than numerical measurements.","sol":"Step 1: The values are names of subjects.\nStep 2: Subject names are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The values are names of subjects.","Step 2: Subject names are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 0),
  (649, 185, 'A survey records eye colours as brown, black and blue. Is this qualitative data?', 'text', 1, 'Eye colour is a category.', '{"why":"Eye colour describes a category or quality.","sol":"Step 1: The observations identify types of eye colour.\nStep 2: These are categories.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: The observations identify types of eye colour.","Step 2: These are categories.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 1),
  (650, 185, 'A survey records transport methods as bus, walking, bicycle and motorcycle. What type of data is this?', 'text', 1, 'Look at what the observations represent.', '{"why":"The observations are categories describing types of transport.","sol":"Step 1: Each response identifies a transport category.\nStep 2: The responses are not measurements.\nStep 3: Therefore, the data is qualitative.","steps":["Step 1: Each response identifies a transport category.","Step 2: The responses are not measurements.","Step 3: Therefore, the data is qualitative."],"options":[],"conceptId":"math_statistics_qualitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Qualitative Data"}', 2),
  (651, 186, 'A teacher records the marks 45, 56, 72 and 81. What type of data are the marks?', 'text', 1, 'The observations are numerical.', '{"why":"The marks are numerical values.","sol":"Step 1: The observations are numbers.\nStep 2: They represent measured or counted quantities.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: The observations are numbers.","Step 2: They represent measured or counted quantities.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 0),
  (652, 186, 'A survey records the number of siblings for five learners as 0, 2, 1, 3 and 4. What type of data is this?', 'text', 1, 'The numbers are counts.', '{"why":"The observations are numerical counts.","sol":"Step 1: Each value counts the number of siblings.\nStep 2: Counts are numerical data.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Each value counts the number of siblings.","Step 2: Counts are numerical data.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 1),
  (653, 186, 'A teacher records the heights of learners in centimetres. Is this quantitative data?', 'text', 1, 'Height is measured using numbers.', '{"why":"Height is a numerical measurement.","sol":"Step 1: Height is measured numerically.\nStep 2: The measurements are expressed in centimetres.\nStep 3: Therefore, the data is quantitative.","steps":["Step 1: Height is measured numerically.","Step 2: The measurements are expressed in centimetres.","Step 3: Therefore, the data is quantitative."],"options":[],"conceptId":"math_statistics_quantitative_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Quantitative Data"}', 2),
  (654, 187, 'The number of books owned by learners is recorded. Is this discrete or continuous data?', 'text', 1, 'Are books counted or measured?', '{"why":"The number of books is obtained by counting separate objects.","sol":"Step 1: Books are counted.\nStep 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Books are counted.","Step 2: A learner can have 4 books or 5 books, but not 4.5 books as a count of complete books.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 0),
  (655, 187, 'A school records the number of learners in each class. What type of quantitative data is this?', 'text', 1, 'Learners are counted.', '{"why":"The number of learners is a count.","sol":"Step 1: The school counts the learners.\nStep 2: The values are separate whole-number counts.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: The school counts the learners.","Step 2: The values are separate whole-number counts.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 1),
  (656, 187, 'A team records the number of goals scored in each match. Is the number of goals discrete?', 'text', 1, 'Can goals be counted?', '{"why":"The number of goals is a count of separate events.","sol":"Step 1: Goals occur as separate events.\nStep 2: The number of goals is counted.\nStep 3: Therefore, the data is discrete.","steps":["Step 1: Goals occur as separate events.","Step 2: The number of goals is counted.","Step 3: Therefore, the data is discrete."],"options":[],"conceptId":"math_statistics_discrete_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Discrete Data"}', 2),
  (657, 188, 'The heights of learners are measured in centimetres. Is height discrete or continuous?', 'text', 1, 'Height is measured, not counted.', '{"why":"Height can take measured values within a range.","sol":"Step 1: Height is obtained by measurement.\nStep 2: A height such as 160 cm can be measured more precisely as 160.4 cm.\nStep 3: Therefore, height is continuous data.","steps":["Step 1: Height is obtained by measurement.","Step 2: A height such as 160 cm can be measured more precisely as 160.4 cm.","Step 3: Therefore, height is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 0),
  (658, 188, 'The time taken by runners to complete a race is recorded. Is time discrete or continuous?', 'text', 1, 'Can time have values between two whole numbers?', '{"why":"Time can take many possible values within an interval.","sol":"Step 1: Time is measured.\nStep 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.\nStep 3: Therefore, time is continuous.","steps":["Step 1: Time is measured.","Step 2: A runner can take 12.1 seconds, 12.15 seconds, 12.153 seconds, and so on.","Step 3: Therefore, time is continuous."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 1),
  (659, 188, 'The mass of bags of maize is measured. What type of data is the mass?', 'text', 1, 'Mass is measured using units such as kilograms.', '{"why":"Mass can take measured values between whole numbers.","sol":"Step 1: Mass is obtained by measurement.\nStep 2: It can have decimal values such as 49.5 kg.\nStep 3: Therefore, mass is continuous data.","steps":["Step 1: Mass is obtained by measurement.","Step 2: It can have decimal values such as 49.5 kg.","Step 3: Therefore, mass is continuous data."],"options":[],"conceptId":"math_statistics_continuous_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Continuous Data"}', 2),
  (660, 189, 'A school wants to study the heights of all 800 learners in the school. What is the population?', 'text', 1, 'Identify the complete group being studied.', '{"why":"The population is the complete group that the investigation is about.","sol":"Step 1: The investigation concerns all learners in the school.\nStep 2: There are 800 learners.\nStep 3: Therefore, all 800 learners form the population.","steps":["Step 1: The investigation concerns all learners in the school.","Step 2: There are 800 learners.","Step 3: Therefore, all 800 learners form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Population"}', 0),
  (661, 189, 'A factory wants to study all 2,000 bottles produced on Monday. What is the population?', 'text', 1, 'Look for the entire group under investigation.', '{"why":"The population is the complete set of objects being studied.","sol":"Step 1: The investigation concerns bottles produced on Monday.\nStep 2: There were 2,000 such bottles.\nStep 3: Therefore, all 2,000 bottles form the population.","steps":["Step 1: The investigation concerns bottles produced on Monday.","Step 2: There were 2,000 such bottles.","Step 3: Therefore, all 2,000 bottles form the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Population"}', 1),
  (662, 189, 'A researcher wants to study all Form 2 learners in a school. Are five selected Form 2 learners the population?', 'text', 1, 'Compare five learners with the complete group.', '{"why":"The population is the entire group being studied, not just part of it.","sol":"Step 1: The investigation concerns all Form 2 learners.\nStep 2: Five learners are only part of the complete group.\nStep 3: Therefore, the five learners are not the population.","steps":["Step 1: The investigation concerns all Form 2 learners.","Step 2: Five learners are only part of the complete group.","Step 3: Therefore, the five learners are not the population."],"options":[],"conceptId":"math_statistics_population","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Population"}', 2),
  (663, 190, 'A school has 1,200 learners and a researcher selects 120 learners for a study. What is the sample?', 'text', 1, 'The sample is the selected part.', '{"why":"A sample is the selected part of the population.","sol":"Step 1: The population contains all 1,200 learners.\nStep 2: The researcher selected 120 learners.\nStep 3: Therefore, the 120 selected learners form the sample.","steps":["Step 1: The population contains all 1,200 learners.","Step 2: The researcher selected 120 learners.","Step 3: Therefore, the 120 selected learners form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sample"}', 0),
  (664, 190, 'A factory produces 4,000 items and an inspector checks 100 of them. What is the population?', 'text', 1, 'The population is the complete group.', '{"why":"The population is the complete group under investigation.","sol":"Step 1: All 4,000 items were produced.\nStep 2: Only 100 were selected for inspection.\nStep 3: Therefore, the population is all 4,000 items.","steps":["Step 1: All 4,000 items were produced.","Step 2: Only 100 were selected for inspection.","Step 3: Therefore, the population is all 4,000 items."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sample"}', 1),
  (665, 190, 'A researcher wants to study 2,000 students but selects 200 students for the investigation. Which group is the sample?', 'text', 1, 'Which group was actually selected?', '{"why":"The sample is the selected subset of the population.","sol":"Step 1: The 2,000 students form the complete population.\nStep 2: The researcher selected 200 students.\nStep 3: Therefore, the 200 selected students form the sample.","steps":["Step 1: The 2,000 students form the complete population.","Step 2: The researcher selected 200 students.","Step 3: Therefore, the 200 selected students form the sample."],"options":[],"conceptId":"math_statistics_sample","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sample"}', 2),
  (666, 191, 'A teacher asks learners which subjects they like most. What is the source of the data?', 'text', 1, 'Who provides the information?', '{"why":"The source is the person or record from which the information comes.","sol":"Step 1: The teacher asks the learners.\nStep 2: The learners provide the answers.\nStep 3: Therefore, the learners are the source of the data.","steps":["Step 1: The teacher asks the learners.","Step 2: The learners provide the answers.","Step 3: Therefore, the learners are the source of the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 0),
  (667, 191, 'A researcher uses a school''s admission records to find the number of learners enrolled. What is the source?', 'text', 1, 'Where did the information come from?', '{"why":"The records contain the information being used.","sol":"Step 1: The researcher did not create the original records.\nStep 2: The information comes from the school''s admission records.\nStep 3: Therefore, the records are the source.","steps":["Step 1: The researcher did not create the original records.","Step 2: The information comes from the school''s admission records.","Step 3: Therefore, the records are the source."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 1),
  (668, 191, 'A researcher measures the heights of learners. Are the measuring instruments the main source of the data?', 'text', 1, 'The instrument measures, but whose height is being recorded?', '{"why":"The instrument is a collection tool; the source is the group from which the information originates.","sol":"Step 1: The instrument is used to obtain the measurements.\nStep 2: The measurements describe the learners.\nStep 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data.","steps":["Step 1: The instrument is used to obtain the measurements.","Step 2: The measurements describe the learners.","Step 3: Therefore, the learners are the source, while the instrument is a tool for collecting the data."],"options":[],"conceptId":"math_statistics_sources_of_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Sources of Data"}', 2),
  (669, 192, 'A researcher gives 100 learners a form containing questions and collects their completed answers. Which method is being used?', 'text', 1, 'Think about a written set of questions.', '{"why":"A questionnaire collects information through a set of questions.","sol":"Step 1: The learners are given questions to answer.\nStep 2: Their answers are collected using a form.\nStep 3: Therefore, the method is a questionnaire.","steps":["Step 1: The learners are given questions to answer.","Step 2: Their answers are collected using a form.","Step 3: Therefore, the method is a questionnaire."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 0),
  (670, 192, 'A researcher watches vehicles passing a road and records their numbers. Which method is being used?', 'text', 1, 'The researcher is watching and recording.', '{"why":"The information is obtained by watching and recording events.","sol":"Step 1: The researcher does not ask the drivers questions.\nStep 2: The researcher watches what happens.\nStep 3: Therefore, the method is observation.","steps":["Step 1: The researcher does not ask the drivers questions.","Step 2: The researcher watches what happens.","Step 3: Therefore, the method is observation."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 1),
  (671, 192, 'A teacher uses a measuring tape to record the heights of learners. Which method is used?', 'text', 1, 'What is the teacher doing to obtain the values?', '{"why":"The values are obtained by directly measuring a characteristic.","sol":"Step 1: The teacher uses an instrument.\nStep 2: The teacher obtains numerical values by measuring height.\nStep 3: Therefore, the method is measurement.","steps":["Step 1: The teacher uses an instrument.","Step 2: The teacher obtains numerical values by measuring height.","Step 3: Therefore, the method is measurement."],"options":[],"conceptId":"math_statistics_methods_of_collecting_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Methods of Collecting Data"}', 2),
  (672, 193, 'A value occurs 8 times. How many tally marks should be recorded?', 'text', 1, 'Separate the 8 observations into groups of five.', '{"why":"Tally marks record each occurrence, with groups of five making counting easier.","sol":"Step 1: The first five observations make one group of five.\nStep 2: There are 3 observations remaining.\nStep 3: Therefore, the tally represents 5 + 3 = 8.","steps":["Step 1: The first five observations make one group of five.","Step 2: There are 3 observations remaining.","Step 3: Therefore, the tally represents 5 + 3 = 8."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 0),
  (673, 193, 'A value has tally marks representing 5 + 5 + 2 observations. What is its frequency?', 'text', 1, 'Add the groups.', '{"why":"The frequency is the total number represented by all the tally groups.","sol":"Step 1: The first group represents 5.\nStep 2: The second group represents 5.\nStep 3: The remaining marks represent 2.\nStep 4: 5 + 5 + 2 = 12.","steps":["Step 1: The first group represents 5.","Step 2: The second group represents 5.","Step 3: The remaining marks represent 2.","Step 4: 5 + 5 + 2 = 12."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 1),
  (674, 193, 'A tally shows one group of five and four additional marks. What frequency does it represent?', 'text', 1, 'A complete tally group represents 5.', '{"why":"The tally represents nine occurrences.","sol":"Step 1: One complete group = 5.\nStep 2: Four additional marks = 4.\nStep 3: 5 + 4 = 9.","steps":["Step 1: One complete group = 5.","Step 2: Four additional marks = 4.","Step 3: 5 + 4 = 9."],"options":[],"conceptId":"math_statistics_tally_marks","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Tally Marks"}', 2),
  (675, 194, 'Find the frequency of 7 in the data: 3, 7, 5, 7, 2, 7, 4.', 'text', 1, 'Count how many times 7 appears.', '{"why":"Frequency is the number of times a value occurs.","sol":"Step 1: Read through the data.\nStep 2: The value 7 appears in the second position.\nStep 3: It appears again in the fourth position.\nStep 4: It appears again in the sixth position.\nStep 5: Therefore, it appears 3 times.","steps":["Step 1: Read through the data.","Step 2: The value 7 appears in the second position.","Step 3: It appears again in the fourth position.","Step 4: It appears again in the sixth position.","Step 5: Therefore, it appears 3 times."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency"}', 0),
  (676, 194, 'Find the frequency of 4 in: 4, 2, 5, 4, 6, 4, 1, 4.', 'text', 1, 'Count every occurrence of 4.', '{"why":"The value 4 occurs four times.","sol":"Step 1: 4 appears first.\nStep 2: 4 appears again in the fourth position.\nStep 3: 4 appears again in the sixth position.\nStep 4: 4 appears again in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: 4 appears first.","Step 2: 4 appears again in the fourth position.","Step 3: 4 appears again in the sixth position.","Step 4: 4 appears again in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency"}', 1),
  (677, 194, 'In the data 2, 2, 3, 4, 2, 5, 6, 2, what is the frequency of 2?', 'text', 1, 'Count all the 2s.', '{"why":"The value 2 occurs four times.","sol":"Step 1: There is a 2 in the first position.\nStep 2: There is a 2 in the second position.\nStep 3: There is a 2 in the fifth position.\nStep 4: There is a 2 in the eighth position.\nStep 5: Therefore, the frequency is 4.","steps":["Step 1: There is a 2 in the first position.","Step 2: There is a 2 in the second position.","Step 3: There is a 2 in the fifth position.","Step 4: There is a 2 in the eighth position.","Step 5: Therefore, the frequency is 4."],"options":[],"conceptId":"math_statistics_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency"}', 2),
  (678, 195, 'For the data 1, 2, 1, 3, 2, 1, identify the frequency of 1.', 'text', 1, 'Count the number of times 1 occurs.', '{"why":"The frequency tells us how many observations have the value 1.","sol":"Step 1: The value 1 occurs first.\nStep 2: It occurs again in the third position.\nStep 3: It occurs again in the sixth position.\nStep 4: Therefore, its frequency is 3.","steps":["Step 1: The value 1 occurs first.","Step 2: It occurs again in the third position.","Step 3: It occurs again in the sixth position.","Step 4: Therefore, its frequency is 3."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 0),
  (679, 195, 'For the data 2, 4, 2, 5, 4, 2, what is the frequency of 4?', 'text', 1, 'Count the 4s.', '{"why":"The value 4 appears twice.","sol":"Step 1: 4 occurs in the second position.\nStep 2: 4 occurs again in the fifth position.\nStep 3: Therefore, the frequency of 4 is 2.","steps":["Step 1: 4 occurs in the second position.","Step 2: 4 occurs again in the fifth position.","Step 3: Therefore, the frequency of 4 is 2."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 1),
  (680, 195, 'A frequency table has frequencies 3, 5, 2 and 4. How many observations are represented altogether?', 'text', 1, 'Add all frequencies.', '{"why":"The sum of all frequencies gives the total number of observations.","sol":"Step 1: Frequency 1 = 3.\nStep 2: Frequency 2 = 5.\nStep 3: Frequency 3 = 2.\nStep 4: Frequency 4 = 4.\nStep 5: 3 + 5 + 2 + 4 = 14.","steps":["Step 1: Frequency 1 = 3.","Step 2: Frequency 2 = 5.","Step 3: Frequency 3 = 2.","Step 4: Frequency 4 = 4.","Step 5: 3 + 5 + 2 + 4 = 14."],"options":[],"conceptId":"math_statistics_frequency_distribution_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Frequency Distribution Table"}', 2),
  (681, 196, 'Construct the frequencies for the data: 1, 2, 1, 3, 2, 1.', 'text', 1, 'List 1, 2 and 3, then count each.', '{"why":"Each frequency is obtained by counting that value in the original data.","sol":"Step 1: Value 1 occurs 3 times.\nStep 2: Value 2 occurs 2 times.\nStep 3: Value 3 occurs 1 time.\nStep 4: Therefore, the frequencies are 3, 2 and 1 respectively.","steps":["Step 1: Value 1 occurs 3 times.","Step 2: Value 2 occurs 2 times.","Step 3: Value 3 occurs 1 time.","Step 4: Therefore, the frequencies are 3, 2 and 1 respectively."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 0),
  (682, 196, 'Construct the frequency table for 2, 4, 2, 3, 4, 2, 3, 4.', 'text', 1, 'The different values are 2, 3 and 4.', '{"why":"The frequency table summarises how often each distinct value occurs.","sol":"Step 1: 2 occurs 3 times.\nStep 2: 3 occurs 2 times.\nStep 3: 4 occurs 3 times.\nStep 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations.","steps":["Step 1: 2 occurs 3 times.","Step 2: 3 occurs 2 times.","Step 3: 4 occurs 3 times.","Step 4: The frequencies total 3 + 2 + 3 = 8, matching the 8 observations."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 1),
  (683, 196, 'A data set is 5, 6, 5, 7, 6, 5. What is the frequency of each value?', 'text', 1, 'Count each distinct value.', '{"why":"Each frequency comes directly from counting the original observations.","sol":"Step 1: 5 occurs 3 times.\nStep 2: 6 occurs 2 times.\nStep 3: 7 occurs 1 time.","steps":["Step 1: 5 occurs 3 times.","Step 2: 6 occurs 2 times.","Step 3: 7 occurs 1 time."],"options":[],"conceptId":"math_statistics_constructing_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing an Ungrouped Frequency Table"}', 2),
  (684, 197, 'A frequency table shows that the value 4 has frequency 6. What does this mean?', 'text', 1, 'Frequency tells how many times the value occurs.', '{"why":"Frequency tells the number of observations having that value.","sol":"Step 1: The value is 4.\nStep 2: Its frequency is 6.\nStep 3: Therefore, 4 occurs six times.","steps":["Step 1: The value is 4.","Step 2: Its frequency is 6.","Step 3: Therefore, 4 occurs six times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 0),
  (685, 197, 'A table shows that the number of books 2 has frequency 8. How many learners have 2 books?', 'text', 1, 'The frequency tells you the number of learners.', '{"why":"The frequency tells how many observations have the value 2.","sol":"Step 1: The value 2 represents the number of books.\nStep 2: Its frequency is 8.\nStep 3: Therefore, 8 learners have 2 books.","steps":["Step 1: The value 2 represents the number of books.","Step 2: Its frequency is 8.","Step 3: Therefore, 8 learners have 2 books."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 1),
  (686, 197, 'A value has frequency 12. Does this mean the value itself is 12?', 'text', 1, 'Separate value from frequency.', '{"why":"A frequency of 12 does not change the value; it tells how often the value occurs.","sol":"Step 1: The value identifies the observation.\nStep 2: The frequency tells how many times it occurs.\nStep 3: Therefore, a frequency of 12 means the observation occurs 12 times.","steps":["Step 1: The value identifies the observation.","Step 2: The frequency tells how many times it occurs.","Step 3: Therefore, a frequency of 12 means the observation occurs 12 times."],"options":[],"conceptId":"math_statistics_reading_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading an Ungrouped Frequency Table"}', 2),
  (687, 198, 'Find the total frequency: 4, 5, 3 and 8.', 'text', 1, 'Add all the frequencies.', '{"why":"The total frequency is the sum of all frequencies.","sol":"Step 1: 4 + 5 = 9.\nStep 2: 9 + 3 = 12.\nStep 3: 12 + 8 = 20.","steps":["Step 1: 4 + 5 = 9.","Step 2: 9 + 3 = 12.","Step 3: 12 + 8 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 0),
  (688, 198, 'A frequency table has frequencies 2, 7, 6 and 5. How many observations are represented?', 'text', 1, 'The total number of observations equals the total frequency.', '{"why":"Adding all frequencies gives the total number of observations.","sol":"Step 1: 2 + 7 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 5 = 20.","steps":["Step 1: 2 + 7 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 5 = 20."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 1),
  (689, 198, 'A raw data set contains 25 observations. A frequency table made from it has frequencies 5, 8, 4 and 7. Is the table complete?', 'text', 1, 'Compare the total frequency with 25.', '{"why":"A complete frequency table should have total frequency equal to the number of original observations.","sol":"Step 1: 5 + 8 + 4 + 7 = 24.\nStep 2: The original data contains 25 observations.\nStep 3: The frequency total is only 24.\nStep 4: Therefore, one observation is missing from the table.","steps":["Step 1: 5 + 8 + 4 + 7 = 24.","Step 2: The original data contains 25 observations.","Step 3: The frequency total is only 24.","Step 4: Therefore, one observation is missing from the table."],"options":[],"conceptId":"math_statistics_total_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Total Frequency"}', 2),
  (690, 199, 'A data set has 20 observations. A frequency table has frequencies 6, 8 and 6. Does the total-frequency check pass?', 'text', 1, 'Add the three frequencies.', '{"why":"The total frequency equals the number of original observations.","sol":"Step 1: 6 + 8 + 6 = 20.\nStep 2: The original data contains 20 observations.\nStep 3: The totals agree.","steps":["Step 1: 6 + 8 + 6 = 20.","Step 2: The original data contains 20 observations.","Step 3: The totals agree."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 0),
  (691, 199, 'A data set contains 30 observations. A table has frequencies 9, 8 and 11. Is the table consistent with the total number of observations?', 'text', 1, 'Add 9, 8 and 11.', '{"why":"The frequencies do not add to the original total of 30.","sol":"Step 1: 9 + 8 = 17.\nStep 2: 17 + 11 = 28.\nStep 3: The table represents 28 observations, not 30.","steps":["Step 1: 9 + 8 = 17.","Step 2: 17 + 11 = 28.","Step 3: The table represents 28 observations, not 30."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 1),
  (692, 199, 'A frequency table represents 18 observations and its frequencies are 5, 4, 6 and 3. What should you conclude?', 'text', 1, 'Check the sum.', '{"why":"The frequencies account for all 18 observations.","sol":"Step 1: 5 + 4 = 9.\nStep 2: 9 + 6 = 15.\nStep 3: 15 + 3 = 18.\nStep 4: The total agrees with the original number of observations.","steps":["Step 1: 5 + 4 = 9.","Step 2: 9 + 6 = 15.","Step 3: 15 + 3 = 18.","Step 4: The total agrees with the original number of observations."],"options":[],"conceptId":"math_statistics_checking_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Checking a Frequency Table"}', 2),
  (693, 200, 'A table represents 20 observations. Two frequencies are 6 and 9. Find the missing frequency.', 'text', 1, 'Subtract the known frequencies from the total.', '{"why":"All frequencies together must equal the total number of observations.","sol":"Step 1: Add the known frequencies: 6 + 9 = 15.\nStep 2: The total number of observations is 20.\nStep 3: Missing frequency = 20 - 15.\nStep 4: Therefore, the missing frequency is 5.","steps":["Step 1: Add the known frequencies: 6 + 9 = 15.","Step 2: The total number of observations is 20.","Step 3: Missing frequency = 20 - 15.","Step 4: Therefore, the missing frequency is 5."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 0),
  (694, 200, 'A frequency table represents 30 observations. The known frequencies are 8, 7 and x. Find x.', 'text', 1, 'First find the total of the known frequencies.', '{"why":"The missing frequency must account for all observations not represented by the known frequencies.","sol":"Step 1: 8 + 7 = 15.\nStep 2: The table must contain 30 observations altogether.\nStep 3: x = 30 - 15.\nStep 4: Therefore, x = 15.","steps":["Step 1: 8 + 7 = 15.","Step 2: The table must contain 30 observations altogether.","Step 3: x = 30 - 15.","Step 4: Therefore, x = 15."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 1),
  (695, 200, 'A table has a total frequency of 40. The known frequencies are 12, 9, 7 and x. Find x.', 'text', 1, 'Add the known frequencies first.', '{"why":"The missing frequency is whatever remains after accounting for the known frequencies.","sol":"Step 1: 12 + 9 + 7 = 28.\nStep 2: The total frequency is 40.\nStep 3: x = 40 - 28.\nStep 4: Therefore, x = 12.","steps":["Step 1: 12 + 9 + 7 = 28.","Step 2: The total frequency is 40.","Step 3: x = 40 - 28.","Step 4: Therefore, x = 12."],"options":[],"conceptId":"math_statistics_finding_a_missing_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Finding a Missing Frequency"}', 2),
  (696, 201, 'A teacher records learners'' ages using the intervals 10–12, 13–15 and 16–18. Is this grouped data?', 'text', 1, 'Are individual ages being listed separately?', '{"why":"Grouped data places observations into classes or intervals.","sol":"Step 1: The ages have been placed into intervals.\nStep 2: The intervals represent groups of possible values.\nStep 3: Therefore, the data is grouped data.","steps":["Step 1: The ages have been placed into intervals.","Step 2: The intervals represent groups of possible values.","Step 3: Therefore, the data is grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 0),
  (697, 201, 'Which is grouped data: 12, 13, 14, 15 or 10–12, 13–15?', 'text', 1, 'Look for intervals.', '{"why":"Grouped data organises observations into intervals.","sol":"Step 1: 12, 13, 14, 15 are individual observations.\nStep 2: 10–12 and 13–15 are intervals.\nStep 3: Therefore, 10–12, 13–15 represents grouped data.","steps":["Step 1: 12, 13, 14, 15 are individual observations.","Step 2: 10–12 and 13–15 are intervals.","Step 3: Therefore, 10–12, 13–15 represents grouped data."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 1),
  (698, 201, 'Why might 500 measurements be grouped into intervals?', 'text', 1, 'Think about making a large data set easier to read.', '{"why":"Grouping makes a large data set easier to handle.","sol":"Step 1: Listing 500 individual measurements can be difficult to read.\nStep 2: Grouping them into intervals summarises the data.\nStep 3: Therefore, grouping makes a large data set easier to organise and interpret.","steps":["Step 1: Listing 500 individual measurements can be difficult to read.","Step 2: Grouping them into intervals summarises the data.","Step 3: Therefore, grouping makes a large data set easier to organise and interpret."],"options":[],"conceptId":"math_statistics_meaning_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Meaning of Grouped Data"}', 2),
  (699, 202, 'Which of the following is a class interval: 17 or 15–19?', 'text', 1, 'A class interval represents a range.', '{"why":"A class interval contains a range of values.","sol":"Step 1: 17 represents one value.\nStep 2: 15–19 represents a range of values.\nStep 3: Therefore, 15–19 is the class interval.","steps":["Step 1: 17 represents one value.","Step 2: 15–19 represents a range of values.","Step 3: Therefore, 15–19 is the class interval."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Interval"}', 0),
  (700, 202, 'Which whole-number values are included in the class interval 20–24?', 'text', 1, 'Start at 20 and continue to 24.', '{"why":"The interval includes every whole-number value from 20 to 24.","sol":"Step 1: Start with 20.\nStep 2: Then 21, 22 and 23.\nStep 3: Finally 24.\nStep 4: Therefore, the values are 20, 21, 22, 23 and 24.","steps":["Step 1: Start with 20.","Step 2: Then 21, 22 and 23.","Step 3: Finally 24.","Step 4: Therefore, the values are 20, 21, 22, 23 and 24."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Interval"}', 1),
  (701, 202, 'In a table, the class intervals are 5–9, 10–14 and 15–19. Which interval contains the value 13?', 'text', 1, 'Check where 13 falls.', '{"why":"13 lies within the limits 10 and 14.","sol":"Step 1: 13 is greater than or equal to 10.\nStep 2: 13 is less than or equal to 14.\nStep 3: Therefore, 13 belongs to the interval 10–14.","steps":["Step 1: 13 is greater than or equal to 10.","Step 2: 13 is less than or equal to 14.","Step 3: Therefore, 13 belongs to the interval 10–14."],"options":[],"conceptId":"math_statistics_class_interval","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Interval"}', 2),
  (702, 203, 'Find the lower and upper class limits of 30–39.', 'text', 1, 'Look at the first and last values.', '{"why":"The class limits are the smallest and largest stated values.","sol":"Step 1: The first value is 30.\nStep 2: The last value is 39.\nStep 3: Therefore, lower limit = 30 and upper limit = 39.","steps":["Step 1: The first value is 30.","Step 2: The last value is 39.","Step 3: Therefore, lower limit = 30 and upper limit = 39."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Limits"}', 0),
  (703, 203, 'What is the upper class limit of 50–59?', 'text', 1, 'Look at the last value in the interval.', '{"why":"The upper limit is the largest stated value in the class.","sol":"Step 1: The interval starts at 50.\nStep 2: It ends at 59.\nStep 3: Therefore, the upper class limit is 59.","steps":["Step 1: The interval starts at 50.","Step 2: It ends at 59.","Step 3: Therefore, the upper class limit is 59."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Limits"}', 1),
  (704, 203, 'What is the lower class limit of 70–79?', 'text', 1, 'Look at the first value.', '{"why":"The lower limit is the smallest stated value in the class.","sol":"Step 1: The interval begins at 70.\nStep 2: Therefore, the lower class limit is 70.","steps":["Step 1: The interval begins at 70.","Step 2: Therefore, the lower class limit is 70."],"options":[],"conceptId":"math_statistics_class_limits","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Limits"}', 2),
  (705, 204, 'Find the class width of 5–9.', 'text', 1, 'Use upper limit − lower limit + 1.', '{"why":"The interval contains the five values 5, 6, 7, 8 and 9.","sol":"Step 1: Upper limit = 9.\nStep 2: Lower limit = 5.\nStep 3: 9 − 5 + 1 = 5.","steps":["Step 1: Upper limit = 9.","Step 2: Lower limit = 5.","Step 3: 9 − 5 + 1 = 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Width"}', 0),
  (706, 204, 'Find the class width of 20–29.', 'text', 1, 'Subtract the lower limit from the upper limit, then add 1.', '{"why":"There are ten whole-number values from 20 through 29.","sol":"Step 1: 29 − 20 = 9.\nStep 2: 9 + 1 = 10.\nStep 3: Therefore, the class width is 10.","steps":["Step 1: 29 − 20 = 9.","Step 2: 9 + 1 = 10.","Step 3: Therefore, the class width is 10."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Width"}', 1),
  (707, 204, 'A class interval is 50–54. What is its width?', 'text', 1, 'Count the whole-number values or use the formula.', '{"why":"The interval contains 50, 51, 52, 53 and 54.","sol":"Step 1: 54 − 50 + 1 = 5.\nStep 2: Therefore, the class width is 5.","steps":["Step 1: 54 − 50 + 1 = 5.","Step 2: Therefore, the class width is 5."],"options":[],"conceptId":"math_statistics_class_width","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Width"}', 2),
  (708, 205, 'Do the intervals 10–19 and 20–29 overlap?', 'text', 1, 'Check whether they share any whole-number values.', '{"why":"The intervals are separate, so each whole-number observation has one class.","sol":"Step 1: The first interval ends at 19.\nStep 2: The second begins at 20.\nStep 3: They share no values.","steps":["Step 1: The first interval ends at 19.","Step 2: The second begins at 20.","Step 3: They share no values."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 0),
  (709, 205, 'Why is 10–20 and 20–30 a poor choice for whole-number classes?', 'text', 1, 'Think about the value 20.', '{"why":"An observation should not have two possible classes.","sol":"Step 1: 20 is included in 10–20.\nStep 2: 20 is also included in 20–30.\nStep 3: Therefore, the value 20 has two possible classes.","steps":["Step 1: 20 is included in 10–20.","Step 2: 20 is also included in 20–30.","Step 3: Therefore, the value 20 has two possible classes."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 1),
  (710, 205, 'Which set is better for whole-number data: 30–39, 40–49 or 30–40, 40–50?', 'text', 1, 'Look for an overlapping boundary.', '{"why":"The classes do not overlap.","sol":"Step 1: 30–39 and 40–49 do not share a value.\nStep 2: 30–40 and 40–50 both contain 40.\nStep 3: Therefore, 30–39 and 40–49 is the better set.","steps":["Step 1: 30–39 and 40–49 do not share a value.","Step 2: 30–40 and 40–50 both contain 40.","Step 3: Therefore, 30–39 and 40–49 is the better set."],"options":[],"conceptId":"math_statistics_non_overlapping_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Non-Overlapping Class Intervals"}', 2),
  (711, 206, 'Find the boundary between the classes 20–29 and 30–39.', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"29.5 is halfway between 29 and 30 and forms the common boundary.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: Find their midpoint: (29 + 30) ÷ 2.\nStep 4: 59 ÷ 2 = 29.5.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: Find their midpoint: (29 + 30) ÷ 2.","Step 4: 59 ÷ 2 = 29.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 0),
  (712, 206, 'What are the boundaries of the class 40–49?', 'text', 1, 'Move 0.5 below 40 and 0.5 above 49.', '{"why":"The boundaries extend halfway to the neighbouring whole-number values.","sol":"Step 1: The lower boundary is 40 − 0.5 = 39.5.\nStep 2: The upper boundary is 49 + 0.5 = 49.5.","steps":["Step 1: The lower boundary is 40 − 0.5 = 39.5.","Step 2: The upper boundary is 49 + 0.5 = 49.5."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 1),
  (713, 206, 'What is the difference between the class limit 29 and the boundary 29.5?', 'text', 1, 'One is an included whole-number value; the other separates classes.', '{"why":"Limits describe the stated values in a class, while boundaries separate continuous classes.","sol":"Step 1: 29 is the upper class limit of a whole-number class.\nStep 2: 29.5 is the boundary between that class and the next class.\nStep 3: Therefore, they have different roles.","steps":["Step 1: 29 is the upper class limit of a whole-number class.","Step 2: 29.5 is the boundary between that class and the next class.","Step 3: Therefore, they have different roles."],"options":[],"conceptId":"math_statistics_class_boundaries","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Boundaries"}', 2),
  (714, 207, 'The data ranges from 14 to 46. Using a class width of 10, which set of intervals can cover all the data?', 'text', 1, 'Start at a convenient value below 14.', '{"why":"These intervals cover the entire data range without overlapping.","sol":"Step 1: Start with 10–19.\nStep 2: Continue with 20–29.\nStep 3: Continue with 30–39.\nStep 4: Continue with 40–49.\nStep 5: The smallest value 14 and largest value 46 are both covered.","steps":["Step 1: Start with 10–19.","Step 2: Continue with 20–29.","Step 3: Continue with 30–39.","Step 4: Continue with 40–49.","Step 5: The smallest value 14 and largest value 46 are both covered."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 0),
  (715, 207, 'The data ranges from 31 to 68. Give class intervals of width 10 that cover the data.', 'text', 1, 'Start with an interval containing 31.', '{"why":"The intervals cover every value from 31 through 68.","sol":"Step 1: 31 belongs to 30–39.\nStep 2: Continue with 40–49.\nStep 3: Then 50–59.\nStep 4: Then 60–69.\nStep 5: The largest value 68 is included.","steps":["Step 1: 31 belongs to 30–39.","Step 2: Continue with 40–49.","Step 3: Then 50–59.","Step 4: Then 60–69.","Step 5: The largest value 68 is included."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 1),
  (716, 207, 'Why would 10–19, 20–29 and 30–39 be unsuitable for data containing the value 45?', 'text', 1, 'Check whether 45 belongs to any class.', '{"why":"Class intervals must cover every observation in the data set.","sol":"Step 1: 45 is greater than 39.\nStep 2: The last class ends at 39.\nStep 3: Therefore, 45 is not covered.\nStep 4: Another class must be added.","steps":["Step 1: 45 is greater than 39.","Step 2: The last class ends at 39.","Step 3: Therefore, 45 is not covered.","Step 4: Another class must be added."],"options":[],"conceptId":"math_statistics_constructing_class_intervals","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing Class Intervals"}', 2),
  (717, 208, 'Find the midpoint of 10–19.', 'text', 1, 'Add the limits and divide by 2.', '{"why":"The midpoint is halfway between the two class limits.","sol":"Step 1: 10 + 19 = 29.\nStep 2: 29 ÷ 2 = 14.5.","steps":["Step 1: 10 + 19 = 29.","Step 2: 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 0),
  (718, 208, 'Find the midpoint of 30–39.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"34.5 is exactly halfway between 30 and 39.","sol":"Step 1: 30 + 39 = 69.\nStep 2: 69 ÷ 2 = 34.5.","steps":["Step 1: 30 + 39 = 69.","Step 2: 69 ÷ 2 = 34.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 1),
  (719, 208, 'Find the midpoint of 50–59.', 'text', 1, 'Add 50 and 59, then divide by 2.', '{"why":"The midpoint is the centre of the class interval.","sol":"Step 1: 50 + 59 = 109.\nStep 2: 109 ÷ 2 = 54.5.","steps":["Step 1: 50 + 59 = 109.","Step 2: 109 ÷ 2 = 54.5."],"options":[],"conceptId":"math_statistics_class_midpoint","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Class Midpoint"}', 2),
  (720, 209, 'The frequencies are 3, 5 and 4. Find the cumulative frequencies.', 'text', 1, 'Keep adding each new frequency to the previous total.', '{"why":"Each cumulative frequency includes all frequencies up to that point.","sol":"Step 1: First cumulative frequency = 3.\nStep 2: Second = 3 + 5 = 8.\nStep 3: Third = 8 + 4 = 12.","steps":["Step 1: First cumulative frequency = 3.","Step 2: Second = 3 + 5 = 8.","Step 3: Third = 8 + 4 = 12."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 0),
  (721, 209, 'A frequency is 6 and the previous cumulative frequency is 9. What is the new cumulative frequency?', 'text', 1, 'Add the new frequency to the previous total.', '{"why":"Cumulative frequency is obtained by adding the current frequency to the previous running total.","sol":"Step 1: Previous cumulative frequency = 9.\nStep 2: New frequency = 6.\nStep 3: 9 + 6 = 15.","steps":["Step 1: Previous cumulative frequency = 9.","Step 2: New frequency = 6.","Step 3: 9 + 6 = 15."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 1),
  (722, 209, 'A table has frequencies 2, 4, 7 and 3. What is the final cumulative frequency?', 'text', 1, 'The final cumulative frequency equals the total frequency.', '{"why":"The final cumulative frequency represents all observations in the table.","sol":"Step 1: 2 + 4 = 6.\nStep 2: 6 + 7 = 13.\nStep 3: 13 + 3 = 16.","steps":["Step 1: 2 + 4 = 6.","Step 2: 6 + 7 = 13.","Step 3: 13 + 3 = 16."],"options":[],"conceptId":"math_statistics_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Cumulative Frequency"}', 2),
  (723, 210, 'A table shows that the cumulative frequency at value 4 is 11. What does 11 mean?', 'text', 1, 'Think ''up to and including''.', '{"why":"Cumulative frequency is the running total up to that value.","sol":"Step 1: Cumulative frequency includes all frequencies before this value.\nStep 2: It also includes the frequency at value 4.\nStep 3: Therefore, 11 observations have values up to and including 4.","steps":["Step 1: Cumulative frequency includes all frequencies before this value.","Step 2: It also includes the frequency at value 4.","Step 3: Therefore, 11 observations have values up to and including 4."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 0),
  (724, 210, 'The cumulative frequency at 20 is 18. What does this tell you?', 'text', 1, 'Translate the cumulative frequency into words.', '{"why":"Cumulative frequency represents the number of observations accumulated so far.","sol":"Step 1: The cumulative frequency is 18.\nStep 2: It counts all observations up to and including 20.\nStep 3: Therefore, 18 observations have values up to and including 20.","steps":["Step 1: The cumulative frequency is 18.","Step 2: It counts all observations up to and including 20.","Step 3: Therefore, 18 observations have values up to and including 20."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 1),
  (725, 210, 'A table has cumulative frequencies 4, 9, 15 and 20. What is the total number of observations?', 'text', 1, 'Look at the final cumulative frequency.', '{"why":"The final cumulative frequency equals the total frequency.","sol":"Step 1: The final cumulative frequency includes every observation.\nStep 2: The final value is 20.\nStep 3: Therefore, there are 20 observations altogether.","steps":["Step 1: The final cumulative frequency includes every observation.","Step 2: The final value is 20.","Step 3: Therefore, there are 20 observations altogether."],"options":[],"conceptId":"math_statistics_reading_cumulative_frequency","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading Cumulative Frequency"}', 2),
  (726, 211, 'Find the mean of 4, 6 and 8.', 'text', 1, 'Add the three values, then divide by 3.', '{"why":"The mean is the total shared equally among the three observations.","sol":"Step 1: 4 + 6 + 8 = 18.\nStep 2: There are 3 values.\nStep 3: Mean = 18 ÷ 3.\nStep 4: Mean = 6.","steps":["Step 1: 4 + 6 + 8 = 18.","Step 2: There are 3 values.","Step 3: Mean = 18 ÷ 3.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 0),
  (727, 211, 'Find the mean of 5, 7, 9 and 11.', 'text', 1, 'Find the total first.', '{"why":"The total of 32 is shared equally among 4 observations.","sol":"Step 1: 5 + 7 + 9 + 11 = 32.\nStep 2: There are 4 values.\nStep 3: Mean = 32 ÷ 4.\nStep 4: Mean = 8.","steps":["Step 1: 5 + 7 + 9 + 11 = 32.","Step 2: There are 4 values.","Step 3: Mean = 32 ÷ 4.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 1),
  (728, 211, 'Find the mean of 2, 6, 8, 9 and 10.', 'text', 1, 'Add all five values and divide by 5.', '{"why":"The mean represents the equal share of the total 35 among 5 observations.","sol":"Step 1: 2 + 6 + 8 + 9 + 10 = 35.\nStep 2: There are 5 values.\nStep 3: Mean = 35 ÷ 5.\nStep 4: Mean = 7.","steps":["Step 1: 2 + 6 + 8 + 9 + 10 = 35.","Step 2: There are 5 values.","Step 3: Mean = 35 ÷ 5.","Step 4: Mean = 7."],"options":[],"conceptId":"math_statistics_31_meaning_of_the_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"31. Meaning of the Mean"}', 2),
  (729, 212, 'Find the mean of 8, 10, 12 and 14.', 'text', 1, 'There are 4 values.', '{"why":"The mean is the total divided by the number of observations.","sol":"Step 1: 8 + 10 + 12 + 14 = 44.\nStep 2: There are 4 observations.\nStep 3: Mean = 44 ÷ 4.\nStep 4: Mean = 11.","steps":["Step 1: 8 + 10 + 12 + 14 = 44.","Step 2: There are 4 observations.","Step 3: Mean = 44 ÷ 4.","Step 4: Mean = 11."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 0),
  (730, 212, 'Find the mean of 5, 7, 12, 16 and 20.', 'text', 1, 'Add all five values before dividing by 5.', '{"why":"The five values have a total of 60, so each would receive 12 if the total were shared equally.","sol":"Step 1: 5 + 7 + 12 + 16 + 20 = 60.\nStep 2: There are 5 observations.\nStep 3: Mean = 60 ÷ 5.\nStep 4: Mean = 12.","steps":["Step 1: 5 + 7 + 12 + 16 + 20 = 60.","Step 2: There are 5 observations.","Step 3: Mean = 60 ÷ 5.","Step 4: Mean = 12."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 1),
  (731, 212, 'The numbers of books read by four learners are 3, 5, 6 and 10. Find the mean.', 'text', 1, 'The number of observations is 4.', '{"why":"The total of 24 books is shared equally among 4 learners.","sol":"Step 1: 3 + 5 + 6 + 10 = 24.\nStep 2: There are 4 learners.\nStep 3: Mean = 24 ÷ 4.\nStep 4: Mean = 6.","steps":["Step 1: 3 + 5 + 6 + 10 = 24.","Step 2: There are 4 learners.","Step 3: Mean = 24 ÷ 4.","Step 4: Mean = 6."],"options":[],"conceptId":"math_statistics_32_finding_mean_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"32. Finding Mean from Raw Data"}', 2),
  (732, 213, 'The total of 5 observations is 40. Find the mean.', 'text', 1, 'Divide the total by 5.', '{"why":"The total 40 is divided into 5 equal shares.","sol":"Step 1: Total = 40.\nStep 2: Number of observations = 5.\nStep 3: Mean = 40 ÷ 5.\nStep 4: Mean = 8.","steps":["Step 1: Total = 40.","Step 2: Number of observations = 5.","Step 3: Mean = 40 ÷ 5.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 0),
  (733, 213, 'The total of 8 values is 64. Find the mean.', 'text', 1, 'Use total ÷ number of observations.', '{"why":"There are 8 observations, so the total is divided into 8 equal shares.","sol":"Step 1: Total = 64.\nStep 2: Number of observations = 8.\nStep 3: Mean = 64 ÷ 8.\nStep 4: Mean = 8.","steps":["Step 1: Total = 64.","Step 2: Number of observations = 8.","Step 3: Mean = 64 ÷ 8.","Step 4: Mean = 8."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 1),
  (734, 213, 'A learner has four test scores with a total of 70. What is the mean score?', 'text', 1, 'There are 4 test scores.', '{"why":"The total score is shared equally across the four tests.","sol":"Step 1: Total score = 70.\nStep 2: Number of scores = 4.\nStep 3: Mean = 70 ÷ 4.\nStep 4: Mean = 17.5.","steps":["Step 1: Total score = 70.","Step 2: Number of scores = 4.","Step 3: Mean = 70 ÷ 4.","Step 4: Mean = 17.5."],"options":[],"conceptId":"math_statistics_33_why_we_divide_by_the_number_of_values","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"33. Why We Divide by the Number of Values"}', 2),
  (735, 214, 'Find the mean from this table: x = 2, 4 and f = 2, 1 respectively.', 'text', 1, 'The data is 2, 2, 4.', '{"why":"Frequency tells us how many times each value contributes to the total.","sol":"Step 1: The value 2 occurs twice: 2 + 2 = 4.\nStep 2: The value 4 occurs once: 4.\nStep 3: Total = 4 + 4 = 8.\nStep 4: Total frequency = 2 + 1 = 3.\nStep 5: Mean = 8 ÷ 3 = 2.67 approximately.","steps":["Step 1: The value 2 occurs twice: 2 + 2 = 4.","Step 2: The value 4 occurs once: 4.","Step 3: Total = 4 + 4 = 8.","Step 4: Total frequency = 2 + 1 = 3.","Step 5: Mean = 8 ÷ 3 = 2.67 approximately."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 0),
  (736, 214, 'Find the mean when x = 3, 5 and f = 2, 3 respectively.', 'text', 1, 'Expand the frequencies first.', '{"why":"There are five observations altogether, so the total is divided by five.","sol":"Step 1: 3 occurs twice: 3 + 3 = 6.\nStep 2: 5 occurs three times: 5 + 5 + 5 = 15.\nStep 3: Total = 21.\nStep 4: Total frequency = 2 + 3 = 5.\nStep 5: Mean = 21 ÷ 5 = 4.2.","steps":["Step 1: 3 occurs twice: 3 + 3 = 6.","Step 2: 5 occurs three times: 5 + 5 + 5 = 15.","Step 3: Total = 21.","Step 4: Total frequency = 2 + 3 = 5.","Step 5: Mean = 21 ÷ 5 = 4.2."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 1),
  (737, 214, 'Find the mean when x = 4, 6 and f = 1, 4 respectively.', 'text', 1, 'The value 6 occurs four times.', '{"why":"The frequency determines how many observations are represented by each value.","sol":"Step 1: 4 occurs once: 4.\nStep 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.\nStep 3: Total = 4 + 24 = 28.\nStep 4: Total frequency = 1 + 4 = 5.\nStep 5: Mean = 28 ÷ 5 = 5.6.","steps":["Step 1: 4 occurs once: 4.","Step 2: 6 occurs four times: 6 + 6 + 6 + 6 = 24.","Step 3: Total = 4 + 24 = 28.","Step 4: Total frequency = 1 + 4 = 5.","Step 5: Mean = 28 ÷ 5 = 5.6."],"options":[],"conceptId":"math_statistics_34_mean_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"34. Mean from an Ungrouped Frequency Table"}', 2),
  (738, 215, 'Find fx when x = 6 and f = 4.', 'text', 1, 'Use fx = f × x.', '{"why":"Four observations of 6 contribute 24 altogether.","sol":"Step 1: f = 4.\nStep 2: x = 6.\nStep 3: fx = 4 × 6.\nStep 4: fx = 24.","steps":["Step 1: f = 4.","Step 2: x = 6.","Step 3: fx = 4 × 6.","Step 4: fx = 24."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 0),
  (739, 215, 'Find fx when x = 9 and f = 5.', 'text', 1, 'Multiply 9 by 5.', '{"why":"Five occurrences of 9 have a combined total of 45.","sol":"Step 1: f = 5.\nStep 2: x = 9.\nStep 3: fx = 5 × 9.\nStep 4: fx = 45.","steps":["Step 1: f = 5.","Step 2: x = 9.","Step 3: fx = 5 × 9.","Step 4: fx = 45."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 1),
  (740, 215, 'For x = 4, 7 and f = 3, 2 respectively, find the two fx values.', 'text', 1, 'Multiply each x by its corresponding frequency.', '{"why":"Each value must be multiplied by its own frequency.","sol":"Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.\nStep 2: For x = 7 and f = 2: fx = 2 × 7 = 14.","steps":["Step 1: For x = 4 and f = 3: fx = 3 × 4 = 12.","Step 2: For x = 7 and f = 2: fx = 2 × 7 = 14."],"options":[],"conceptId":"math_statistics_35_understanding_fx","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"35. Understanding fx"}', 2),
  (741, 216, 'Find the mean from x = 2, 4 and f = 3, 2 respectively.', 'text', 1, 'Calculate fx first.', '{"why":"The formula divides the total represented value by the total number of observations.","sol":"Step 1: For x = 2: fx = 2 × 3 = 6.\nStep 2: For x = 4: fx = 4 × 2 = 8.\nStep 3: Σfx = 6 + 8 = 14.\nStep 4: Σf = 3 + 2 = 5.\nStep 5: Mean = 14 ÷ 5 = 2.8.","steps":["Step 1: For x = 2: fx = 2 × 3 = 6.","Step 2: For x = 4: fx = 4 × 2 = 8.","Step 3: Σfx = 6 + 8 = 14.","Step 4: Σf = 3 + 2 = 5.","Step 5: Mean = 14 ÷ 5 = 2.8."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 0),
  (742, 216, 'Find the mean from x = 5, 10, 15 and f = 2, 3, 1 respectively.', 'text', 1, 'Find all three fx values.', '{"why":"The total represented value is 55 and there are 6 observations.","sol":"Step 1: 5 × 2 = 10.\nStep 2: 10 × 3 = 30.\nStep 3: 15 × 1 = 15.\nStep 4: Σfx = 10 + 30 + 15 = 55.\nStep 5: Σf = 2 + 3 + 1 = 6.\nStep 6: Mean = 55 ÷ 6 = 9.17 approximately.","steps":["Step 1: 5 × 2 = 10.","Step 2: 10 × 3 = 30.","Step 3: 15 × 1 = 15.","Step 4: Σfx = 10 + 30 + 15 = 55.","Step 5: Σf = 2 + 3 + 1 = 6.","Step 6: Mean = 55 ÷ 6 = 9.17 approximately."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 1),
  (743, 216, 'Find the mean from x = 4, 8 and f = 5, 5 respectively.', 'text', 1, 'The total frequency is 10.', '{"why":"There are 10 observations whose combined value is 60.","sol":"Step 1: 4 × 5 = 20.\nStep 2: 8 × 5 = 40.\nStep 3: Σfx = 20 + 40 = 60.\nStep 4: Σf = 5 + 5 = 10.\nStep 5: Mean = 60 ÷ 10 = 6.","steps":["Step 1: 4 × 5 = 20.","Step 2: 8 × 5 = 40.","Step 3: Σfx = 20 + 40 = 60.","Step 4: Σf = 5 + 5 = 10.","Step 5: Mean = 60 ÷ 10 = 6."],"options":[],"conceptId":"math_statistics_36_finding_mean_using_fx_f","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"36. Finding Mean Using Σfx ÷ Σf"}', 2),
  (744, 217, 'Find the estimated mean for classes 0–9 and 10–19 with frequencies 2 and 3 respectively.', 'text', 1, 'First find the two midpoints.', '{"why":"Each class is represented by its midpoint because the individual observations inside the class are unknown.","sol":"Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.\nStep 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.\nStep 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.\nStep 4: Σfx = 52.5.\nStep 5: Σf = 5.\nStep 6: Mean = 52.5 ÷ 5 = 10.5.","steps":["Step 1: Midpoint of 0–9 = (0 + 9) ÷ 2 = 4.5.","Step 2: Midpoint of 10–19 = (10 + 19) ÷ 2 = 14.5.","Step 3: fx values are 4.5 × 2 = 9 and 14.5 × 3 = 43.5.","Step 4: Σfx = 52.5.","Step 5: Σf = 5.","Step 6: Mean = 52.5 ÷ 5 = 10.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 0),
  (745, 217, 'Find the estimated mean for classes 10–19, 20–29 with frequencies 2 and 4 respectively.', 'text', 1, 'Use midpoints 14.5 and 24.5.', '{"why":"The midpoint represents each class when calculating the estimated grouped mean.","sol":"Step 1: Midpoint of 10–19 = 14.5.\nStep 2: Midpoint of 20–29 = 24.5.\nStep 3: 14.5 × 2 = 29.\nStep 4: 24.5 × 4 = 98.\nStep 5: Σfx = 127.\nStep 6: Σf = 6.\nStep 7: Mean = 127 ÷ 6 = 21.17 approximately.","steps":["Step 1: Midpoint of 10–19 = 14.5.","Step 2: Midpoint of 20–29 = 24.5.","Step 3: 14.5 × 2 = 29.","Step 4: 24.5 × 4 = 98.","Step 5: Σfx = 127.","Step 6: Σf = 6.","Step 7: Mean = 127 ÷ 6 = 21.17 approximately."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 1),
  (746, 217, 'Find the estimated mean for classes 20–29, 30–39 with frequencies 3 and 2 respectively.', 'text', 1, 'Find the midpoint of each class first.', '{"why":"The grouped mean is calculated from the representative midpoint of each class.","sol":"Step 1: Midpoint of 20–29 = 24.5.\nStep 2: Midpoint of 30–39 = 34.5.\nStep 3: 24.5 × 3 = 73.5.\nStep 4: 34.5 × 2 = 69.\nStep 5: Σfx = 142.5.\nStep 6: Σf = 5.\nStep 7: Mean = 142.5 ÷ 5 = 28.5.","steps":["Step 1: Midpoint of 20–29 = 24.5.","Step 2: Midpoint of 30–39 = 34.5.","Step 3: 24.5 × 3 = 73.5.","Step 4: 34.5 × 2 = 69.","Step 5: Σfx = 142.5.","Step 6: Σf = 5.","Step 7: Mean = 142.5 ÷ 5 = 28.5."],"options":[],"conceptId":"math_statistics_37_finding_mean_from_a_grouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"37. Finding Mean from a Grouped Frequency Table"}', 2),
  (747, 218, 'Find the midpoint of the class 5–14.', 'text', 1, 'Add the two class limits and divide by 2.', '{"why":"The midpoint is the central value between the two class limits.","sol":"Step 1: Lower limit = 5.\nStep 2: Upper limit = 14.\nStep 3: Midpoint = (5 + 14) ÷ 2.\nStep 4: Midpoint = 19 ÷ 2 = 9.5.","steps":["Step 1: Lower limit = 5.","Step 2: Upper limit = 14.","Step 3: Midpoint = (5 + 14) ÷ 2.","Step 4: Midpoint = 19 ÷ 2 = 9.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 0),
  (748, 218, 'Find the midpoint of 40–49.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"44.5 is halfway between 40 and 49.","sol":"Step 1: 40 + 49 = 89.\nStep 2: 89 ÷ 2 = 44.5.\nStep 3: Therefore the midpoint is 44.5.","steps":["Step 1: 40 + 49 = 89.","Step 2: 89 ÷ 2 = 44.5.","Step 3: Therefore the midpoint is 44.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 1),
  (749, 218, 'Why is 24.5 used as the midpoint of the class 20–29?', 'text', 1, 'Calculate the midpoint.', '{"why":"24.5 is halfway between the lower and upper class limits.","sol":"Step 1: Lower limit = 20.\nStep 2: Upper limit = 29.\nStep 3: Midpoint = (20 + 29) ÷ 2.\nStep 4: Midpoint = 49 ÷ 2 = 24.5.","steps":["Step 1: Lower limit = 20.","Step 2: Upper limit = 29.","Step 3: Midpoint = (20 + 29) ÷ 2.","Step 4: Midpoint = 49 ÷ 2 = 24.5."],"options":[],"conceptId":"math_statistics_38_why_midpoints_are_used_for_grouped_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"38. Why Midpoints Are Used for Grouped Mean"}', 2),
  (750, 219, 'The mean of 5, 7 and x is 9. Find x.', 'text', 1, 'Required total = 9 × 3.', '{"why":"The three values must have a total of 27 for their mean to be 9.","sol":"Step 1: Required total = 9 × 3 = 27.\nStep 2: Known total = 5 + 7 = 12.\nStep 3: x = 27 − 12.\nStep 4: x = 15.\nStep 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9.","steps":["Step 1: Required total = 9 × 3 = 27.","Step 2: Known total = 5 + 7 = 12.","Step 3: x = 27 − 12.","Step 4: x = 15.","Step 5: Check: (5 + 7 + 15) ÷ 3 = 27 ÷ 3 = 9."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (751, 219, 'The mean of four numbers is 10. Three numbers are 6, 11 and 8. Find the fourth number.', 'text', 1, 'First find the required total.', '{"why":"A mean of 10 for four values requires a total of 40.","sol":"Step 1: Required total = 10 × 4 = 40.\nStep 2: Known total = 6 + 11 + 8 = 25.\nStep 3: Missing value = 40 − 25.\nStep 4: Missing value = 15.","steps":["Step 1: Required total = 10 × 4 = 40.","Step 2: Known total = 6 + 11 + 8 = 25.","Step 3: Missing value = 40 − 25.","Step 4: Missing value = 15."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 1),
  (752, 219, 'The mean of six numbers is 14. Five numbers are 10, 12, 15, 16 and 13. Find the missing number.', 'text', 1, 'Required total = 14 × 6.', '{"why":"The six values must total 84 to have a mean of 14.","sol":"Step 1: Required total = 14 × 6 = 84.\nStep 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.\nStep 3: Missing value = 84 − 66.\nStep 4: Missing value = 18.","steps":["Step 1: Required total = 14 × 6 = 84.","Step 2: Known total = 10 + 12 + 15 + 16 + 13 = 66.","Step 3: Missing value = 84 − 66.","Step 4: Missing value = 18."],"options":[],"conceptId":"math_statistics_39_finding_a_missing_value_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"39. Finding a Missing Value from a Known Mean"}', 2),
  (753, 220, 'A table has x = 2 with frequency 1 and x = 6 with frequency f. The mean is 4. Find f.', 'text', 1, 'Use 4 = (2 + 6f) ÷ (1 + f).', '{"why":"The missing frequency must make the weighted mean equal to 4.","sol":"Step 1: 4 = (2 + 6f) ÷ (1 + f).\nStep 2: 4(1 + f) = 2 + 6f.\nStep 3: 4 + 4f = 2 + 6f.\nStep 4: 2 = 2f.\nStep 5: f = 1.","steps":["Step 1: 4 = (2 + 6f) ÷ (1 + f).","Step 2: 4(1 + f) = 2 + 6f.","Step 3: 4 + 4f = 2 + 6f.","Step 4: 2 = 2f.","Step 5: f = 1."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 0),
  (754, 220, 'A table has x = 3 with frequency 2 and x = 7 with frequency f. The mean is 5. Find f.', 'text', 1, 'Write the weighted mean equation first.', '{"why":"A frequency of 2 makes the weighted mean equal to 5.","sol":"Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.\nStep 2: Σf = 2 + f.\nStep 3: 5 = (6 + 7f) ÷ (2 + f).\nStep 4: 5(2 + f) = 6 + 7f.\nStep 5: 10 + 5f = 6 + 7f.\nStep 6: 4 = 2f.\nStep 7: f = 2.","steps":["Step 1: Σfx = 3 × 2 + 7f = 6 + 7f.","Step 2: Σf = 2 + f.","Step 3: 5 = (6 + 7f) ÷ (2 + f).","Step 4: 5(2 + f) = 6 + 7f.","Step 5: 10 + 5f = 6 + 7f.","Step 6: 4 = 2f.","Step 7: f = 2."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 1),
  (755, 220, 'A table has x = 2 with frequency 3 and x = 8 with frequency f. The mean is 5. Find f.', 'text', 1, 'Use Σfx = 6 + 8f and Σf = 3 + f.', '{"why":"Three occurrences of 8 together with three occurrences of 2 produce a mean of 5.","sol":"Step 1: 5 = (6 + 8f) ÷ (3 + f).\nStep 2: 5(3 + f) = 6 + 8f.\nStep 3: 15 + 5f = 6 + 8f.\nStep 4: 9 = 3f.\nStep 5: f = 3.","steps":["Step 1: 5 = (6 + 8f) ÷ (3 + f).","Step 2: 5(3 + f) = 6 + 8f.","Step 3: 15 + 5f = 6 + 8f.","Step 4: 9 = 3f.","Step 5: f = 3."],"options":[],"conceptId":"math_statistics_40_finding_a_missing_frequency_from_a_known_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"40. Finding a Missing Frequency from a Known Mean"}', 2),
  (756, 221, 'Find the median of 4, 9, 2, 7 and 5.', 'text', 1, 'Arrange the values first.', '{"why":"The median is the middle value after ordering the data.","sol":"Step 1: Arrange the data: 2, 4, 5, 7, 9.\nStep 2: There are 5 values.\nStep 3: The middle value is 5.\nStep 4: Median = 5.","steps":["Step 1: Arrange the data: 2, 4, 5, 7, 9.","Step 2: There are 5 values.","Step 3: The middle value is 5.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 0),
  (757, 221, 'Find the median of 11, 3, 8, 5 and 9.', 'text', 1, 'Put the values from smallest to largest.', '{"why":"The third value is the middle of five ordered observations.","sol":"Step 1: Ordered data: 3, 5, 8, 9, 11.\nStep 2: There are 5 values.\nStep 3: The middle value is 8.\nStep 4: Median = 8.","steps":["Step 1: Ordered data: 3, 5, 8, 9, 11.","Step 2: There are 5 values.","Step 3: The middle value is 8.","Step 4: Median = 8."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 1),
  (758, 221, 'Find the median of 2, 7, 4, 10, 6, 9 and 5.', 'text', 1, 'There are 7 observations, so look for the fourth value after ordering.', '{"why":"Six has three observations below it and three above it.","sol":"Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.\nStep 2: There are 7 values.\nStep 3: The fourth value is 6.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 4, 5, 6, 7, 9, 10.","Step 2: There are 7 values.","Step 3: The fourth value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_41_meaning_of_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"41. Meaning of the Median"}', 2),
  (759, 222, 'A dataset has 5 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"For five ordered observations, the third observation has two values on each side.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2.\nStep 3: Median position = 3.\nStep 4: Therefore the median is at the 3rd position.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2.","Step 3: Median position = 3.","Step 4: Therefore the median is at the 3rd position."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 0),
  (760, 222, 'Find the median of 8, 2, 10, 5 and 6.', 'text', 1, 'There are 5 observations, so use the 3rd position.', '{"why":"The median is the value occupying the third position in five ordered observations.","sol":"Step 1: n = 5.\nStep 2: Median position = (5 + 1) ÷ 2 = 3rd.\nStep 3: Ordered data: 2, 5, 6, 8, 10.\nStep 4: The 3rd value is 6.\nStep 5: Median = 6.","steps":["Step 1: n = 5.","Step 2: Median position = (5 + 1) ÷ 2 = 3rd.","Step 3: Ordered data: 2, 5, 6, 8, 10.","Step 4: The 3rd value is 6.","Step 5: Median = 6."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 1),
  (761, 222, 'Find the median of 12, 4, 8, 15, 6, 10 and 2.', 'text', 1, 'There are 7 observations, so the median is at the 4th position.', '{"why":"Eight has three ordered observations below it and three above it.","sol":"Step 1: n = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.\nStep 4: The 4th value is 8.\nStep 5: Median = 8.","steps":["Step 1: n = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Ordered data: 2, 4, 6, 8, 10, 12, 15.","Step 4: The 4th value is 8.","Step 5: Median = 8."],"options":[],"conceptId":"math_statistics_42_median_of_an_odd_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"42. Median of an Odd-Sized Dataset"}', 2),
  (762, 223, 'Find the median of 2, 4, 6 and 8.', 'text', 1, 'The two middle values are 4 and 6.', '{"why":"With four observations, the median is the average of the 2nd and 3rd values.","sol":"Step 1: The data is already ordered.\nStep 2: The two middle values are 4 and 6.\nStep 3: Median = (4 + 6) ÷ 2.\nStep 4: Median = 5.","steps":["Step 1: The data is already ordered.","Step 2: The two middle values are 4 and 6.","Step 3: Median = (4 + 6) ÷ 2.","Step 4: Median = 5."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 0),
  (763, 223, 'Find the median of 3, 10, 7, 5, 2 and 8.', 'text', 1, 'Order the six values first.', '{"why":"The two central observations are 5 and 7, so their average is the median.","sol":"Step 1: Ordered data: 2, 3, 5, 7, 8, 10.\nStep 2: The two middle values are 5 and 7.\nStep 3: Median = (5 + 7) ÷ 2.\nStep 4: Median = 6.","steps":["Step 1: Ordered data: 2, 3, 5, 7, 8, 10.","Step 2: The two middle values are 5 and 7.","Step 3: Median = (5 + 7) ÷ 2.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 1),
  (764, 223, 'Find the median of 4, 12, 8, 20, 10 and 6.', 'text', 1, 'There are six observations.', '{"why":"For an even-sized dataset, the median lies halfway between the two middle values.","sol":"Step 1: Ordered data: 4, 6, 8, 10, 12, 20.\nStep 2: The two middle values are 8 and 10.\nStep 3: Median = (8 + 10) ÷ 2.\nStep 4: Median = 9.","steps":["Step 1: Ordered data: 4, 6, 8, 10, 12, 20.","Step 2: The two middle values are 8 and 10.","Step 3: Median = (8 + 10) ÷ 2.","Step 4: Median = 9."],"options":[],"conceptId":"math_statistics_43_median_of_an_even_sized_dataset","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"43. Median of an Even-Sized Dataset"}', 2),
  (765, 224, 'Find the median from x = 2, 4, 6 with frequencies 2, 3, 2 respectively.', 'text', 1, 'There are 7 observations. Find the 4th position.', '{"why":"The fourth ordered observation is represented by the value 4.","sol":"Step 1: Total frequency = 2 + 3 + 2 = 7.\nStep 2: Median position = (7 + 1) ÷ 2 = 4th.\nStep 3: Cumulative frequencies are 2, 5, 7.\nStep 4: The 4th observation lies at x = 4.\nStep 5: Median = 4.","steps":["Step 1: Total frequency = 2 + 3 + 2 = 7.","Step 2: Median position = (7 + 1) ÷ 2 = 4th.","Step 3: Cumulative frequencies are 2, 5, 7.","Step 4: The 4th observation lies at x = 4.","Step 5: Median = 4."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 0),
  (766, 224, 'Find the median from x = 1, 3, 5 with frequencies 2, 4, 2 respectively.', 'text', 1, 'There are 8 observations, so inspect positions 4 and 5.', '{"why":"Both middle observations fall among the four occurrences of 3.","sol":"Step 1: Total frequency = 2 + 4 + 2 = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: Cumulative frequency at x = 1 is 2.\nStep 4: Cumulative frequency at x = 3 is 6.\nStep 5: Therefore both the 4th and 5th observations are 3.\nStep 6: Median = 3.","steps":["Step 1: Total frequency = 2 + 4 + 2 = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: Cumulative frequency at x = 1 is 2.","Step 4: Cumulative frequency at x = 3 is 6.","Step 5: Therefore both the 4th and 5th observations are 3.","Step 6: Median = 3."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 1),
  (767, 224, 'Find the median from x = 10, 20, 30, 40 with frequencies 1, 2, 4, 2 respectively.', 'text', 1, 'There are 9 observations, so find the 5th position.', '{"why":"The cumulative frequency reaches 7 at 30, so the fifth observation is 30.","sol":"Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 1, 3, 7, 9.\nStep 4: The 5th observation falls at x = 30.\nStep 5: Median = 30.","steps":["Step 1: Total frequency = 1 + 2 + 4 + 2 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 1, 3, 7, 9.","Step 4: The 5th observation falls at x = 30.","Step 5: Median = 30."],"options":[],"conceptId":"math_statistics_44_median_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"44. Median from an Ungrouped Frequency Table"}', 2),
  (768, 225, 'There are 7 observations. What is the median position?', 'text', 1, 'Use (n + 1) ÷ 2.', '{"why":"Seven ordered observations have one central position: the fourth.","sol":"Step 1: n = 7.\nStep 2: (7 + 1) ÷ 2 = 4.\nStep 3: The median is at the 4th position.","steps":["Step 1: n = 7.","Step 2: (7 + 1) ÷ 2 = 4.","Step 3: The median is at the 4th position."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 0),
  (769, 225, 'There are 10 observations. What are the two median positions?', 'text', 1, 'Find n ÷ 2, then add 1.', '{"why":"An even-sized dataset has two central observations.","sol":"Step 1: n ÷ 2 = 10 ÷ 2 = 5.\nStep 2: The first middle position is 5th.\nStep 3: The second middle position is 6th.\nStep 4: Therefore the middle positions are 5th and 6th.","steps":["Step 1: n ÷ 2 = 10 ÷ 2 = 5.","Step 2: The first middle position is 5th.","Step 3: The second middle position is 6th.","Step 4: Therefore the middle positions are 5th and 6th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 1),
  (770, 225, 'There are 14 observations. What are the two middle positions?', 'text', 1, '14 ÷ 2 gives the first middle position.', '{"why":"The median for an even dataset lies between the two central positions.","sol":"Step 1: 14 ÷ 2 = 7.\nStep 2: First middle position = 7th.\nStep 3: Second middle position = 8th.\nStep 4: Therefore the middle positions are 7th and 8th.","steps":["Step 1: 14 ÷ 2 = 7.","Step 2: First middle position = 7th.","Step 3: Second middle position = 8th.","Step 4: Therefore the middle positions are 7th and 8th."],"options":[],"conceptId":"math_statistics_45_finding_the_median_position","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"45. Finding the Median Position"}', 2),
  (771, 226, 'Find the median class for classes 0–9, 10–19 and 20–29 with frequencies 3, 5 and 2.', 'text', 1, 'Find the total frequency and the middle position.', '{"why":"The middle observations fall inside the 10–19 class.","sol":"Step 1: Total frequency = 3 + 5 + 2 = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: Cumulative frequencies are 3, 8, 10.\nStep 4: Both the 5th and 6th observations lie in 10–19.\nStep 5: Median class = 10–19.","steps":["Step 1: Total frequency = 3 + 5 + 2 = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: Cumulative frequencies are 3, 8, 10.","Step 4: Both the 5th and 6th observations lie in 10–19.","Step 5: Median class = 10–19."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 0),
  (772, 226, 'Find the median class for classes 10–19, 20–29 and 30–39 with frequencies 2, 4 and 5.', 'text', 1, 'There are 11 observations.', '{"why":"The sixth observation is the last observation represented by the 20–29 class.","sol":"Step 1: Total frequency = 2 + 4 + 5 = 11.\nStep 2: Median position = (11 + 1) ÷ 2 = 6th.\nStep 3: Cumulative frequencies are 2, 6, 11.\nStep 4: The 6th observation is in the 20–29 class.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 2 + 4 + 5 = 11.","Step 2: Median position = (11 + 1) ÷ 2 = 6th.","Step 3: Cumulative frequencies are 2, 6, 11.","Step 4: The 6th observation is in the 20–29 class.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 1),
  (773, 226, 'Find the median class for classes 0–9, 10–19, 20–29 and 30–39 with frequencies 1, 3, 6 and 2.', 'text', 1, 'There are 12 observations, so inspect positions 6 and 7.', '{"why":"The cumulative frequency reaches 10 in the 20–29 class, containing both middle observations.","sol":"Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.\nStep 2: Middle positions are 6th and 7th.\nStep 3: Cumulative frequencies are 1, 4, 10, 12.\nStep 4: Both the 6th and 7th observations lie in 20–29.\nStep 5: Median class = 20–29.","steps":["Step 1: Total frequency = 1 + 3 + 6 + 2 = 12.","Step 2: Middle positions are 6th and 7th.","Step 3: Cumulative frequencies are 1, 4, 10, 12.","Step 4: Both the 6th and 7th observations lie in 20–29.","Step 5: Median class = 20–29."],"options":[],"conceptId":"math_statistics_46_median_of_grouped_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"46. Median of Grouped Data"}', 2),
  (774, 227, 'Cumulative frequencies are 3, 8, 14 and 20. If the median position is 10th, which class contains the median?', 'text', 1, 'Find the first cumulative frequency that is at least 10.', '{"why":"The third class contains observations 9 through 14.","sol":"Step 1: The cumulative frequencies are 3, 8, 14 and 20.\nStep 2: The 10th observation is beyond 8.\nStep 3: The next cumulative frequency is 14.\nStep 4: Therefore the median is in the third class.","steps":["Step 1: The cumulative frequencies are 3, 8, 14 and 20.","Step 2: The 10th observation is beyond 8.","Step 3: The next cumulative frequency is 14.","Step 4: Therefore the median is in the third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 0),
  (775, 227, 'A grouped table has cumulative frequencies 4, 9, 15 and 21. If the median position is 8th, which class is the median class?', 'text', 1, 'Locate 8 using the cumulative frequencies.', '{"why":"The second class contains observations 5 through 9.","sol":"Step 1: The first cumulative frequency is 4, which is below 8.\nStep 2: The second cumulative frequency is 9, which reaches 8.\nStep 3: Therefore the median lies in the second class.","steps":["Step 1: The first cumulative frequency is 4, which is below 8.","Step 2: The second cumulative frequency is 9, which reaches 8.","Step 3: Therefore the median lies in the second class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 1),
  (776, 227, 'Cumulative frequencies are 2, 7, 13 and 18. If the middle positions are 9th and 10th, which class contains both?', 'text', 1, 'Find where positions 9 and 10 fall.', '{"why":"The third class contains observations 8 through 13.","sol":"Step 1: The first two cumulative frequencies are 2 and 7.\nStep 2: The third cumulative frequency is 13.\nStep 3: Therefore positions 9 and 10 lie in the third class.\nStep 4: Median class = third class.","steps":["Step 1: The first two cumulative frequencies are 2 and 7.","Step 2: The third cumulative frequency is 13.","Step 3: Therefore positions 9 and 10 lie in the third class.","Step 4: Median class = third class."],"options":[],"conceptId":"math_statistics_47_identifying_the_median_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"47. Identifying the Median Class"}', 2),
  (777, 228, 'The values 5, 10 and 15 have frequencies 3, 2 and 4. Find the median.', 'text', 1, 'There are 9 observations, so find the 5th observation.', '{"why":"The cumulative frequency reaches 5 at the value 10.","sol":"Step 1: Total frequency = 3 + 2 + 4 = 9.\nStep 2: Median position = (9 + 1) ÷ 2 = 5th.\nStep 3: Cumulative frequencies are 3, 5, 9.\nStep 4: The 5th observation is 10.\nStep 5: Median = 10.","steps":["Step 1: Total frequency = 3 + 2 + 4 = 9.","Step 2: Median position = (9 + 1) ÷ 2 = 5th.","Step 3: Cumulative frequencies are 3, 5, 9.","Step 4: The 5th observation is 10.","Step 5: Median = 10."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 0),
  (778, 228, 'The values 2, 4 and 6 have frequencies 2, 3 and 5. Find the median.', 'text', 1, 'There are 10 observations. Find the 5th and 6th positions.', '{"why":"The two middle observations are 4 and 6.","sol":"Step 1: Total frequency = 10.\nStep 2: Middle positions are 5th and 6th.\nStep 3: The cumulative frequencies are 2, 5, 10.\nStep 4: The 5th observation is 4.\nStep 5: The 6th observation is 6.\nStep 6: Median = (4 + 6) ÷ 2 = 5.","steps":["Step 1: Total frequency = 10.","Step 2: Middle positions are 5th and 6th.","Step 3: The cumulative frequencies are 2, 5, 10.","Step 4: The 5th observation is 4.","Step 5: The 6th observation is 6.","Step 6: Median = (4 + 6) ÷ 2 = 5."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 1),
  (779, 228, 'The values 10, 20 and 30 have frequencies 2, 5 and 1. Find the median.', 'text', 1, 'There are 8 observations.', '{"why":"Both middle observations are among the five occurrences of 20.","sol":"Step 1: Total frequency = 8.\nStep 2: Middle positions are 4th and 5th.\nStep 3: The cumulative frequency at 20 is 7.\nStep 4: Therefore both positions 4 and 5 correspond to 20.\nStep 5: Median = 20.","steps":["Step 1: Total frequency = 8.","Step 2: Middle positions are 4th and 5th.","Step 3: The cumulative frequency at 20 is 7.","Step 4: Therefore both positions 4 and 5 correspond to 20.","Step 5: Median = 20."],"options":[],"conceptId":"math_statistics_48_using_cumulative_frequency_to_locate_the_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"48. Using Cumulative Frequency to Locate the Median"}', 2),
  (780, 229, 'For the data 2, 4, 6, 8, 10, find the mean and median.', 'text', 1, 'Calculate the mean and identify the middle value.', '{"why":"The dataset is balanced around 6, so both measures give the same value.","sol":"Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.\nStep 2: Mean = 30 ÷ 5 = 6.\nStep 3: The middle value is 6.\nStep 4: Median = 6.","steps":["Step 1: Mean = (2 + 4 + 6 + 8 + 10) ÷ 5.","Step 2: Mean = 30 ÷ 5 = 6.","Step 3: The middle value is 6.","Step 4: Median = 6."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 0),
  (781, 229, 'For the data 2, 3, 4, 5, 26, find the mean and median.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 26 raises the mean, while the median remains the middle value.","sol":"Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.\nStep 2: Mean = 40 ÷ 5 = 8.\nStep 3: The middle value is 4.\nStep 4: Median = 4.","steps":["Step 1: Mean = (2 + 3 + 4 + 5 + 26) ÷ 5.","Step 2: Mean = 40 ÷ 5 = 8.","Step 3: The middle value is 4.","Step 4: Median = 4."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 1),
  (782, 229, 'Which measure is more affected by the value 100 in the data 5, 6, 7, 8, 100: mean or median?', 'text', 1, 'Calculate both or consider how each is found.', '{"why":"The mean uses every numerical value, so an extreme value can strongly affect it.","sol":"Step 1: Mean = 25.2.\nStep 2: Median = 7.\nStep 3: The mean changed substantially because 100 contributes directly to the total.\nStep 4: The median remains the middle position.","steps":["Step 1: Mean = 25.2.","Step 2: Median = 7.","Step 3: The mean changed substantially because 100 contributes directly to the total.","Step 4: The median remains the middle position."],"options":[],"conceptId":"math_statistics_49_comparing_median_and_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"49. Comparing Median and Mean"}', 2),
  (783, 230, 'For the data 4, 5, 6, 7 and 8, which measure gives a good description of the centre: mean or median?', 'text', 1, 'Check whether there is an extreme value.', '{"why":"The data is balanced and contains no extreme observation.","sol":"Step 1: There is no unusually large or small value.\nStep 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.\nStep 3: Median = 6.\nStep 4: Both describe the centre well.","steps":["Step 1: There is no unusually large or small value.","Step 2: Mean = (4 + 5 + 6 + 7 + 8) ÷ 5 = 6.","Step 3: Median = 6.","Step 4: Both describe the centre well."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 0),
  (784, 230, 'For the data 3, 4, 5, 6 and 50, which measure better represents the centre of most observations?', 'text', 1, 'Calculate the mean and compare it with the median.', '{"why":"The extreme value 50 pulls the mean upward.","sol":"Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.\nStep 2: Mean = 68 ÷ 5 = 13.6.\nStep 3: Median = 5.\nStep 4: Most observations are between 3 and 6.\nStep 5: The median is closer to the centre of most observations.","steps":["Step 1: Mean = (3 + 4 + 5 + 6 + 50) ÷ 5.","Step 2: Mean = 68 ÷ 5 = 13.6.","Step 3: Median = 5.","Step 4: Most observations are between 3 and 6.","Step 5: The median is closer to the centre of most observations."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 1),
  (785, 230, 'A dataset contains one extremely large value compared with all the others. Which measure is generally less affected by that extreme value?', 'text', 1, 'Think about whether the measure uses every value or only position.', '{"why":"The median is based on position rather than adding every value.","sol":"Step 1: The mean uses every value in its calculation.\nStep 2: An extremely large value therefore changes the total.\nStep 3: The median depends on the middle position.\nStep 4: Therefore the median is generally less affected.","steps":["Step 1: The mean uses every value in its calculation.","Step 2: An extremely large value therefore changes the total.","Step 3: The median depends on the middle position.","Step 4: Therefore the median is generally less affected."],"options":[],"conceptId":"math_statistics_50_choosing_between_mean_and_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"50. Choosing Between Mean and Median"}', 2),
  (786, 231, 'Find the mode of 2, 3, 3, 5 and 7.', 'text', 1, 'Count how many times each value occurs.', '{"why":"The mode is the value occurring most frequently.","sol":"Step 1: 2 occurs once.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2 for the value 3.","steps":["Step 1: 2 occurs once.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2 for the value 3."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 0),
  (787, 231, 'Find the mode of 4, 6, 6, 8, 9, 6.', 'text', 1, 'Which value appears most often?', '{"why":"Six has the highest frequency.","sol":"Step 1: 4 occurs once.\nStep 2: 6 occurs three times.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 6.","steps":["Step 1: 4 occurs once.","Step 2: 6 occurs three times.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 6."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 1),
  (788, 231, 'Find the mode of 5, 5, 7, 8, 9, 5, 10.', 'text', 1, 'Count the occurrences of 5.', '{"why":"Five occurs more often than every other value.","sol":"Step 1: 5 occurs three times.\nStep 2: 7 occurs once.\nStep 3: 8 occurs once.\nStep 4: 9 occurs once.\nStep 5: 10 occurs once.\nStep 6: Therefore the mode is 5.","steps":["Step 1: 5 occurs three times.","Step 2: 7 occurs once.","Step 3: 8 occurs once.","Step 4: 9 occurs once.","Step 5: 10 occurs once.","Step 6: Therefore the mode is 5."],"options":[],"conceptId":"math_statistics_51_meaning_of_the_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"51. Meaning of the Mode"}', 2),
  (789, 232, 'Find the mode of 3, 5, 3, 7, 3 and 9.', 'text', 1, 'Count each value.', '{"why":"Three occurs more frequently than every other value.","sol":"Step 1: 3 occurs three times.\nStep 2: 5 occurs once.\nStep 3: 7 occurs once.\nStep 4: 9 occurs once.\nStep 5: Therefore the mode is 3.","steps":["Step 1: 3 occurs three times.","Step 2: 5 occurs once.","Step 3: 7 occurs once.","Step 4: 9 occurs once.","Step 5: Therefore the mode is 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 0),
  (790, 232, 'Find the mode of 2, 4, 4, 6, 4, 8 and 9.', 'text', 1, 'Find the value with the highest frequency.', '{"why":"Four has the highest frequency of three.","sol":"Step 1: 2 occurs once.\nStep 2: 4 occurs three times.\nStep 3: 6 occurs once.\nStep 4: 8 occurs once.\nStep 5: 9 occurs once.\nStep 6: Therefore the mode is 4.","steps":["Step 1: 2 occurs once.","Step 2: 4 occurs three times.","Step 3: 6 occurs once.","Step 4: 8 occurs once.","Step 5: 9 occurs once.","Step 6: Therefore the mode is 4."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 1),
  (791, 232, 'Find the mode of 2, 2, 3, 3, 5, 7.', 'text', 1, 'Check whether one value occurs more often than the others.', '{"why":"Both 2 and 3 occur twice, which is the highest frequency.","sol":"Step 1: 2 occurs twice.\nStep 2: 3 occurs twice.\nStep 3: 5 occurs once.\nStep 4: 7 occurs once.\nStep 5: The highest frequency is 2.\nStep 6: Therefore the dataset has two modes: 2 and 3.","steps":["Step 1: 2 occurs twice.","Step 2: 3 occurs twice.","Step 3: 5 occurs once.","Step 4: 7 occurs once.","Step 5: The highest frequency is 2.","Step 6: Therefore the dataset has two modes: 2 and 3."],"options":[],"conceptId":"math_statistics_52_finding_mode_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"52. Finding Mode from Raw Data"}', 2),
  (792, 233, 'Find the mode from x = 2, 4, 6 with frequencies 3, 7, 2 respectively.', 'text', 1, 'Find the largest frequency.', '{"why":"The value 4 occurs seven times, more than any other value.","sol":"Step 1: The frequencies are 3, 7 and 2.\nStep 2: The largest frequency is 7.\nStep 3: Frequency 7 belongs to x = 4.\nStep 4: Mode = 4.","steps":["Step 1: The frequencies are 3, 7 and 2.","Step 2: The largest frequency is 7.","Step 3: Frequency 7 belongs to x = 4.","Step 4: Mode = 4."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 0),
  (793, 233, 'Find the mode from x = 5, 10, 15 with frequencies 2, 6, 4 respectively.', 'text', 1, 'The mode corresponds to the highest frequency.', '{"why":"Ten has the highest frequency.","sol":"Step 1: The frequencies are 2, 6 and 4.\nStep 2: The largest frequency is 6.\nStep 3: Frequency 6 belongs to x = 10.\nStep 4: Mode = 10.","steps":["Step 1: The frequencies are 2, 6 and 4.","Step 2: The largest frequency is 6.","Step 3: Frequency 6 belongs to x = 10.","Step 4: Mode = 10."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 1),
  (794, 233, 'Find the mode from x = 1, 2, 3, 4 with frequencies 3, 5, 5, 2.', 'text', 1, 'There are two equal highest frequencies.', '{"why":"Both values occur with the highest frequency.","sol":"Step 1: The largest frequency is 5.\nStep 2: x = 2 has frequency 5.\nStep 3: x = 3 also has frequency 5.\nStep 4: Therefore the modes are 2 and 3.","steps":["Step 1: The largest frequency is 5.","Step 2: x = 2 has frequency 5.","Step 3: x = 3 also has frequency 5.","Step 4: Therefore the modes are 2 and 3."],"options":[],"conceptId":"math_statistics_53_mode_from_an_ungrouped_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"53. Mode from an Ungrouped Frequency Table"}', 2),
  (795, 234, 'Find the modal class for classes 0–9, 10–19 and 20–29 with frequencies 4, 9 and 6.', 'text', 1, 'Find the class with the largest frequency.', '{"why":"The modal class is the class with the highest frequency.","sol":"Step 1: The frequencies are 4, 9 and 6.\nStep 2: The largest frequency is 9.\nStep 3: Frequency 9 belongs to 10–19.\nStep 4: Modal class = 10–19.","steps":["Step 1: The frequencies are 4, 9 and 6.","Step 2: The largest frequency is 9.","Step 3: Frequency 9 belongs to 10–19.","Step 4: Modal class = 10–19."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 0),
  (796, 234, 'Find the modal class for classes 10–14, 15–19, 20–24 and 25–29 with frequencies 3, 5, 8 and 4.', 'text', 1, 'Look for frequency 8.', '{"why":"The 20–24 class contains the greatest number of observations.","sol":"Step 1: The largest frequency is 8.\nStep 2: Frequency 8 belongs to class 20–24.\nStep 3: Modal class = 20–24.","steps":["Step 1: The largest frequency is 8.","Step 2: Frequency 8 belongs to class 20–24.","Step 3: Modal class = 20–24."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 1),
  (797, 234, 'Classes 0–9, 10–19, 20–29 and 30–39 have frequencies 5, 7, 7 and 3. Identify the modal classes.', 'text', 1, 'Check which classes share the highest frequency.', '{"why":"Both classes have the highest frequency.","sol":"Step 1: The highest frequency is 7.\nStep 2: 10–19 has frequency 7.\nStep 3: 20–29 also has frequency 7.\nStep 4: Therefore both are modal classes.","steps":["Step 1: The highest frequency is 7.","Step 2: 10–19 has frequency 7.","Step 3: 20–29 also has frequency 7.","Step 4: Therefore both are modal classes."],"options":[],"conceptId":"math_statistics_54_identifying_the_modal_class","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"54. Identifying the Modal Class"}', 2),
  (798, 235, 'Find the mean, median and mode of 2, 3, 3, 4 and 8.', 'text', 1, 'Calculate each measure separately.', '{"why":"Each measure uses a different method to describe the dataset.","sol":"Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: The middle value is 3, so median = 3.\nStep 3: The value 3 occurs twice, so mode = 3.","steps":["Step 1: Mean = (2 + 3 + 3 + 4 + 8) ÷ 5 = 20 ÷ 5 = 4.","Step 2: The middle value is 3, so median = 3.","Step 3: The value 3 occurs twice, so mode = 3."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 0),
  (799, 235, 'Find the mean, median and mode of 4, 5, 5, 5 and 6.', 'text', 1, 'Notice that 5 occurs most frequently.', '{"why":"All three measures happen to give the same value.","sol":"Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.\nStep 2: Median = 5.\nStep 3: Mode = 5 because 5 occurs three times.","steps":["Step 1: Mean = (4 + 5 + 5 + 5 + 6) ÷ 5 = 25 ÷ 5 = 5.","Step 2: Median = 5.","Step 3: Mode = 5 because 5 occurs three times."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 1),
  (800, 235, 'Find the mean, median and mode of 1, 2, 2, 3 and 12.', 'text', 1, 'The data is already ordered.', '{"why":"The extreme value 12 affects the mean but does not change the middle position or most frequent value.","sol":"Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.\nStep 2: Median = 2.\nStep 3: Mode = 2 because it occurs twice.","steps":["Step 1: Mean = (1 + 2 + 2 + 3 + 12) ÷ 5 = 20 ÷ 5 = 4.","Step 2: Median = 2.","Step 3: Mode = 2 because it occurs twice."],"options":[],"conceptId":"math_statistics_55_comparing_mean_median_and_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"55. Comparing Mean, Median and Mode"}', 2),
  (801, 236, 'Find the range of 2, 5, 7, 9 and 11.', 'text', 1, 'Subtract the smallest value from the largest.', '{"why":"Range measures the distance between the largest and smallest values.","sol":"Step 1: Largest value = 11.\nStep 2: Smallest value = 2.\nStep 3: Range = 11 − 2.\nStep 4: Range = 9.","steps":["Step 1: Largest value = 11.","Step 2: Smallest value = 2.","Step 3: Range = 11 − 2.","Step 4: Range = 9."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 0),
  (802, 236, 'Find the range of 15, 8, 20, 12 and 5.', 'text', 1, 'Identify 20 and 5 first.', '{"why":"The largest value is 15 units above the smallest value.","sol":"Step 1: Largest value = 20.\nStep 2: Smallest value = 5.\nStep 3: Range = 20 − 5.\nStep 4: Range = 15.","steps":["Step 1: Largest value = 20.","Step 2: Smallest value = 5.","Step 3: Range = 20 − 5.","Step 4: Range = 15."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 1),
  (803, 236, 'Find the range of 7, 7, 7, 7.', 'text', 1, 'The largest and smallest values are the same.', '{"why":"There is no spread because every observation has the same value.","sol":"Step 1: Largest value = 7.\nStep 2: Smallest value = 7.\nStep 3: Range = 7 − 7.\nStep 4: Range = 0.","steps":["Step 1: Largest value = 7.","Step 2: Smallest value = 7.","Step 3: Range = 7 − 7.","Step 4: Range = 0."],"options":[],"conceptId":"math_statistics_56_meaning_of_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"56. Meaning of Range"}', 2),
  (804, 237, 'Find the range of 4, 10, 7, 15 and 6.', 'text', 1, 'Largest minus smallest.', '{"why":"The range is the distance from the smallest observation to the largest.","sol":"Step 1: Largest = 15.\nStep 2: Smallest = 4.\nStep 3: Range = 15 − 4.\nStep 4: Range = 11.","steps":["Step 1: Largest = 15.","Step 2: Smallest = 4.","Step 3: Range = 15 − 4.","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 0),
  (805, 237, 'Find the range of 22, 8, 31, 14 and 5.', 'text', 1, 'Find 31 and 5.', '{"why":"The largest and smallest values determine the range.","sol":"Step 1: Largest = 31.\nStep 2: Smallest = 5.\nStep 3: Range = 31 − 5.\nStep 4: Range = 26.","steps":["Step 1: Largest = 31.","Step 2: Smallest = 5.","Step 3: Range = 31 − 5.","Step 4: Range = 26."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 1),
  (806, 237, 'Find the range of −5, 2, 4, −1 and 8.', 'text', 1, 'The smallest value is negative.', '{"why":"Subtracting a negative value increases the distance between the extremes.","sol":"Step 1: Largest = 8.\nStep 2: Smallest = −5.\nStep 3: Range = 8 − (−5).\nStep 4: Range = 8 + 5.\nStep 5: Range = 13.","steps":["Step 1: Largest = 8.","Step 2: Smallest = −5.","Step 3: Range = 8 − (−5).","Step 4: Range = 8 + 5.","Step 5: Range = 13."],"options":[],"conceptId":"math_statistics_57_finding_range_from_raw_data","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"57. Finding Range from Raw Data"}', 2),
  (807, 238, 'Find the range from x = 2, 5, 8 with frequencies 4, 3, 2.', 'text', 1, 'Ignore the frequencies when calculating the range.', '{"why":"Range depends on the smallest and largest values, not their frequencies.","sol":"Step 1: Smallest value = 2.\nStep 2: Largest value = 8.\nStep 3: Range = 8 − 2.\nStep 4: Range = 6.","steps":["Step 1: Smallest value = 2.","Step 2: Largest value = 8.","Step 3: Range = 8 − 2.","Step 4: Range = 6."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 0),
  (808, 238, 'Find the range from x = 10, 20, 35, 40 with frequencies 2, 4, 3, 1.', 'text', 1, 'Use 10 and 40.', '{"why":"The extreme values are 10 and 40.","sol":"Step 1: Smallest value = 10.\nStep 2: Largest value = 40.\nStep 3: Range = 40 − 10.\nStep 4: Range = 30.","steps":["Step 1: Smallest value = 10.","Step 2: Largest value = 40.","Step 3: Range = 40 − 10.","Step 4: Range = 30."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 1),
  (809, 238, 'Find the range from x = −2, 4 and 9 with frequencies 3, 5 and 2.', 'text', 1, 'Subtract the negative smallest value.', '{"why":"The distance from −2 to 9 is 11.","sol":"Step 1: Largest = 9.\nStep 2: Smallest = −2.\nStep 3: Range = 9 − (−2).\nStep 4: Range = 11.","steps":["Step 1: Largest = 9.","Step 2: Smallest = −2.","Step 3: Range = 9 − (−2).","Step 4: Range = 11."],"options":[],"conceptId":"math_statistics_58_finding_range_from_a_frequency_table","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"58. Finding Range from a Frequency Table"}', 2),
  (810, 239, 'Dataset A is 2, 5, 7, 10. Dataset B is 1, 4, 8, 15. Which has the greater range?', 'text', 1, 'Calculate both ranges.', '{"why":"Dataset B has a larger distance between its smallest and largest values.","sol":"Step 1: Range A = 10 − 2 = 8.\nStep 2: Range B = 15 − 1 = 14.\nStep 3: 14 is greater than 8.\nStep 4: Therefore Dataset B has the greater range.","steps":["Step 1: Range A = 10 − 2 = 8.","Step 2: Range B = 15 − 1 = 14.","Step 3: 14 is greater than 8.","Step 4: Therefore Dataset B has the greater range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 0),
  (811, 239, 'Dataset A has smallest value 10 and largest value 25. Dataset B has smallest value 5 and largest value 18. Which has the smaller range?', 'text', 1, 'Find both ranges.', '{"why":"Dataset B''s extreme values are 13 units apart.","sol":"Step 1: Range A = 25 − 10 = 15.\nStep 2: Range B = 18 − 5 = 13.\nStep 3: 13 is smaller than 15.\nStep 4: Therefore Dataset B has the smaller range.","steps":["Step 1: Range A = 25 − 10 = 15.","Step 2: Range B = 18 − 5 = 13.","Step 3: 13 is smaller than 15.","Step 4: Therefore Dataset B has the smaller range."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 1),
  (812, 239, 'Dataset A has range 7. Dataset B has range 12. Which dataset has greater spread according to the range?', 'text', 1, 'Compare 7 and 12.', '{"why":"A larger range indicates a larger distance between the extreme values.","sol":"Step 1: Range A = 7.\nStep 2: Range B = 12.\nStep 3: 12 is greater than 7.\nStep 4: Therefore Dataset B has greater spread.","steps":["Step 1: Range A = 7.","Step 2: Range B = 12.","Step 3: 12 is greater than 7.","Step 4: Therefore Dataset B has greater spread."],"options":[],"conceptId":"math_statistics_59_comparing_two_data_sets_using_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"59. Comparing Two Data Sets Using Range"}', 2),
  (813, 240, 'The data is 3, 5, 7, 9. A value of 20 is added. What is the new range?', 'text', 1, '20 becomes the new largest value.', '{"why":"The new value 20 becomes the largest observation.","sol":"Step 1: New largest value = 20.\nStep 2: Smallest value = 3.\nStep 3: New range = 20 − 3.\nStep 4: New range = 17.","steps":["Step 1: New largest value = 20.","Step 2: Smallest value = 3.","Step 3: New range = 20 − 3.","Step 4: New range = 17."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 0),
  (814, 240, 'The data is 4, 8, 10, 12. A value of 6 is added. What is the new range?', 'text', 1, 'Does 6 become the smallest or largest value?', '{"why":"Adding a value inside the existing extremes does not change the range.","sol":"Step 1: Original smallest = 4.\nStep 2: Original largest = 12.\nStep 3: The new value 6 lies between 4 and 12.\nStep 4: New range = 12 − 4 = 8.","steps":["Step 1: Original smallest = 4.","Step 2: Original largest = 12.","Step 3: The new value 6 lies between 4 and 12.","Step 4: New range = 12 − 4 = 8."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 1),
  (815, 240, 'The data is 10, 12, 15, 18. A value of 2 is added. What is the new range?', 'text', 1, '2 becomes the new smallest value.', '{"why":"The new value 2 extends the lower extreme of the dataset.","sol":"Step 1: New smallest value = 2.\nStep 2: Largest value = 18.\nStep 3: New range = 18 − 2.\nStep 4: New range = 16.","steps":["Step 1: New smallest value = 2.","Step 2: Largest value = 18.","Step 3: New range = 18 − 2.","Step 4: New range = 16."],"options":[],"conceptId":"math_statistics_60_effect_of_an_extreme_value_on_range","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"60. Effect of an Extreme Value on Range"}', 2),
  (816, 241, 'A bar graph shows 12 learners chose Biology. What does the height of the Biology bar represent?', 'text', 1, 'Read the value represented by the Biology bar.', '{"why":"The height of a bar represents the frequency or quantity for that category.","sol":"Step 1: Find the Biology category.\nStep 2: Read the height of its bar.\nStep 3: The height represents the number of learners.\nStep 4: The value is 12.","steps":["Step 1: Find the Biology category.","Step 2: Read the height of its bar.","Step 3: The height represents the number of learners.","Step 4: The value is 12."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 0),
  (817, 241, 'A bar graph shows 25 books for Monday and 18 books for Tuesday. How many more books were recorded on Monday?', 'text', 1, 'Subtract Tuesday''s value from Monday''s value.', '{"why":"The difference between the two bar heights is 7.","sol":"Step 1: Monday = 25.\nStep 2: Tuesday = 18.\nStep 3: Difference = 25 − 18.\nStep 4: 25 − 18 = 7.","steps":["Step 1: Monday = 25.","Step 2: Tuesday = 18.","Step 3: Difference = 25 − 18.","Step 4: 25 − 18 = 7."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 1),
  (818, 241, 'The bars for A, B and C have heights 9, 14 and 11 respectively. Which category has the greatest frequency?', 'text', 1, 'Find the greatest bar height.', '{"why":"The tallest bar represents the greatest frequency.","sol":"Step 1: A = 9.\nStep 2: B = 14.\nStep 3: C = 11.\nStep 4: The greatest value is 14.\nStep 5: Therefore B has the greatest frequency.","steps":["Step 1: A = 9.","Step 2: B = 14.","Step 3: C = 11.","Step 4: The greatest value is 14.","Step 5: Therefore B has the greatest frequency."],"options":[],"conceptId":"math_statistics_reading_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Bar Graph"}', 2),
  (819, 242, 'A table contains A = 5, B = 10 and C = 15. What should be the height of the bar for B?', 'text', 1, 'The bar height equals the frequency.', '{"why":"Each bar must reach the frequency of its category.","sol":"Step 1: Find the value for B.\nStep 2: B has a frequency of 10.\nStep 3: Therefore the B bar must reach 10.","steps":["Step 1: Find the value for B.","Step 2: B has a frequency of 10.","Step 3: Therefore the B bar must reach 10."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 0),
  (820, 242, 'A dataset has frequencies 10, 20, 30 and 40. Give a suitable simple vertical scale.', 'text', 1, 'The largest value is 40.', '{"why":"The scale covers all values using equal intervals.","sol":"Step 1: Find the largest value: 40.\nStep 2: Use equal intervals on the vertical axis.\nStep 3: A suitable scale is 0, 10, 20, 30, 40.","steps":["Step 1: Find the largest value: 40.","Step 2: Use equal intervals on the vertical axis.","Step 3: A suitable scale is 0, 10, 20, 30, 40."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 1),
  (821, 242, 'A category has frequency 18. If the vertical scale is marked every 5 units, where should its bar end?', 'text', 1, 'The bar must represent exactly 18.', '{"why":"The bar height must represent the actual frequency, even when it lies between scale marks.","sol":"Step 1: The scale has marks at 15 and 20.\nStep 2: 18 lies between 15 and 20.\nStep 3: Draw the bar to the level representing 18.","steps":["Step 1: The scale has marks at 15 and 20.","Step 2: 18 lies between 15 and 20.","Step 3: Draw the bar to the level representing 18."],"options":[],"conceptId":"math_statistics_constructing_a_bar_graph","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Bar Graph"}', 2),
  (822, 243, 'A histogram has a bar of height 12 for the class 30–39. What does 12 represent?', 'text', 1, 'The vertical axis represents frequency.', '{"why":"Histogram bar height represents the frequency of the class.","sol":"Step 1: Find the class 30–39.\nStep 2: Its bar has height 12.\nStep 3: The height represents frequency.\nStep 4: Therefore 12 observations are in the class.","steps":["Step 1: Find the class 30–39.","Step 2: Its bar has height 12.","Step 3: The height represents frequency.","Step 4: Therefore 12 observations are in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 0),
  (823, 243, 'The frequencies of three histogram classes are 4, 11 and 7. Which class has the tallest bar?', 'text', 1, 'Find the greatest frequency.', '{"why":"The greatest frequency produces the tallest bar.","sol":"Step 1: Compare 4, 11 and 7.\nStep 2: The greatest frequency is 11.\nStep 3: Therefore the class with frequency 11 has the tallest bar.","steps":["Step 1: Compare 4, 11 and 7.","Step 2: The greatest frequency is 11.","Step 3: Therefore the class with frequency 11 has the tallest bar."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 1),
  (824, 243, 'A histogram shows 6 observations in the class 40–49. How many observations belong to this class?', 'text', 1, 'Read the frequency from the bar.', '{"why":"Frequency tells how many observations belong to a class.","sol":"Step 1: Locate the class 40–49.\nStep 2: Its frequency is 6.\nStep 3: Therefore there are 6 observations in the class.","steps":["Step 1: Locate the class 40–49.","Step 2: Its frequency is 6.","Step 3: Therefore there are 6 observations in the class."],"options":[],"conceptId":"math_statistics_reading_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Histogram"}', 2),
  (825, 244, 'A grouped table has classes 0–9, 10–19 and 20–29 with frequencies 3, 6 and 5. What are the heights of the three histogram bars?', 'text', 1, 'Bar height equals frequency.', '{"why":"Each histogram bar reaches its class frequency.","sol":"Step 1: 0–9 has frequency 3.\nStep 2: 10–19 has frequency 6.\nStep 3: 20–29 has frequency 5.\nStep 4: Therefore the bar heights are 3, 6 and 5.","steps":["Step 1: 0–9 has frequency 3.","Step 2: 10–19 has frequency 6.","Step 3: 20–29 has frequency 5.","Step 4: Therefore the bar heights are 3, 6 and 5."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 0),
  (826, 244, 'What boundary comes immediately between the classes 20–29 and 30–39?', 'text', 1, 'Find the midpoint between 29 and 30.', '{"why":"Class boundaries remove the gap between consecutive whole-number class limits.","sol":"Step 1: The upper limit of the first class is 29.\nStep 2: The lower limit of the next class is 30.\nStep 3: The boundary is halfway between them.\nStep 4: 29.5 is the boundary.","steps":["Step 1: The upper limit of the first class is 29.","Step 2: The lower limit of the next class is 30.","Step 3: The boundary is halfway between them.","Step 4: 29.5 is the boundary."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 1),
  (827, 244, 'A histogram has frequencies 5, 9 and 7. Which bar should be tallest?', 'text', 1, 'Find the greatest frequency.', '{"why":"The largest frequency gives the tallest histogram bar.","sol":"Step 1: Compare 5, 9 and 7.\nStep 2: The greatest value is 9.\nStep 3: Therefore the bar with frequency 9 is tallest.","steps":["Step 1: Compare 5, 9 and 7.","Step 2: The greatest value is 9.","Step 3: Therefore the bar with frequency 9 is tallest."],"options":[],"conceptId":"math_statistics_constructing_a_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Histogram"}', 2),
  (828, 245, 'A graph shows the number of learners choosing Mathematics, English and Biology. Should it be a bar graph or histogram?', 'text', 1, 'Are the values categories or numerical intervals?', '{"why":"Bar graphs represent separate categories.","sol":"Step 1: Mathematics, English and Biology are categories.\nStep 2: They are not numerical class intervals.\nStep 3: Therefore a bar graph is appropriate.","steps":["Step 1: Mathematics, English and Biology are categories.","Step 2: They are not numerical class intervals.","Step 3: Therefore a bar graph is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 0),
  (829, 245, 'Marks are grouped into 0–9, 10–19 and 20–29. Which graph is appropriate?', 'text', 1, 'These are numerical intervals.', '{"why":"Histograms represent grouped numerical data.","sol":"Step 1: The data are marks.\nStep 2: The marks have been grouped into numerical intervals.\nStep 3: Therefore a histogram is appropriate.","steps":["Step 1: The data are marks.","Step 2: The marks have been grouped into numerical intervals.","Step 3: Therefore a histogram is appropriate."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 1),
  (830, 245, 'Why do histogram bars touch while bar graph bars normally have spaces?', 'text', 1, 'Think about what the horizontal axis represents.', '{"why":"The touching bars show that the numerical intervals are continuous or consecutive.","sol":"Step 1: Bar graphs represent separate categories.\nStep 2: Histograms represent consecutive numerical intervals.\nStep 3: Consecutive intervals join one another.\nStep 4: Therefore histogram bars touch.","steps":["Step 1: Bar graphs represent separate categories.","Step 2: Histograms represent consecutive numerical intervals.","Step 3: Consecutive intervals join one another.","Step 4: Therefore histogram bars touch."],"options":[],"conceptId":"math_statistics_bar_graph_versus_histogram","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Bar Graph versus Histogram"}', 2),
  (831, 246, 'A point on a frequency polygon is (25, 8). What is its frequency?', 'text', 1, 'The second coordinate represents frequency.', '{"why":"The vertical coordinate of a frequency polygon point represents frequency.","sol":"Step 1: The point is (25, 8).\nStep 2: The first coordinate is the midpoint.\nStep 3: The second coordinate is the frequency.\nStep 4: Therefore frequency = 8.","steps":["Step 1: The point is (25, 8).","Step 2: The first coordinate is the midpoint.","Step 3: The second coordinate is the frequency.","Step 4: Therefore frequency = 8."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 0),
  (832, 246, 'A frequency polygon has points with frequencies 3, 9 and 5. Which point is highest?', 'text', 1, 'The largest frequency gives the highest point.', '{"why":"Higher frequency is represented by a higher point.","sol":"Step 1: Compare 3, 9 and 5.\nStep 2: The largest value is 9.\nStep 3: Therefore the point with frequency 9 is highest.","steps":["Step 1: Compare 3, 9 and 5.","Step 2: The largest value is 9.","Step 3: Therefore the point with frequency 9 is highest."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 1),
  (833, 246, 'A point is plotted at (14.5, 6). What does 14.5 represent?', 'text', 1, 'Look at the first coordinate.', '{"why":"Frequency polygons plot frequency against class midpoint.","sol":"Step 1: The point is (14.5, 6).\nStep 2: The first coordinate gives the horizontal position.\nStep 3: In a frequency polygon this represents the class midpoint.\nStep 4: Therefore 14.5 is the class midpoint.","steps":["Step 1: The point is (14.5, 6).","Step 2: The first coordinate gives the horizontal position.","Step 3: In a frequency polygon this represents the class midpoint.","Step 4: Therefore 14.5 is the class midpoint."],"options":[],"conceptId":"math_statistics_reading_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Reading a Frequency Polygon"}', 2),
  (834, 247, 'Find the midpoint of the class 10–19.', 'text', 1, 'Use (lower limit + upper limit) ÷ 2.', '{"why":"The midpoint is the average of the two class limits.","sol":"Step 1: Lower limit = 10.\nStep 2: Upper limit = 19.\nStep 3: Midpoint = (10 + 19) ÷ 2.\nStep 4: Midpoint = 29 ÷ 2 = 14.5.","steps":["Step 1: Lower limit = 10.","Step 2: Upper limit = 19.","Step 3: Midpoint = (10 + 19) ÷ 2.","Step 4: Midpoint = 29 ÷ 2 = 14.5."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 0),
  (835, 247, 'A class has midpoint 24.5 and frequency 6. What point should be plotted?', 'text', 1, 'Use (midpoint, frequency).', '{"why":"Frequency polygons plot class midpoint against frequency.","sol":"Step 1: Horizontal coordinate = midpoint = 24.5.\nStep 2: Vertical coordinate = frequency = 6.\nStep 3: Therefore the point is (24.5, 6).","steps":["Step 1: Horizontal coordinate = midpoint = 24.5.","Step 2: Vertical coordinate = frequency = 6.","Step 3: Therefore the point is (24.5, 6)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 1),
  (836, 247, 'For the class 30–39 with frequency 9, what point is plotted?', 'text', 1, 'First find the midpoint.', '{"why":"The midpoint becomes the x-coordinate and frequency becomes the y-coordinate.","sol":"Step 1: Midpoint = (30 + 39) ÷ 2.\nStep 2: Midpoint = 69 ÷ 2.\nStep 3: Midpoint = 34.5.\nStep 4: Frequency = 9.\nStep 5: Therefore the point is (34.5, 9).","steps":["Step 1: Midpoint = (30 + 39) ÷ 2.","Step 2: Midpoint = 69 ÷ 2.","Step 3: Midpoint = 34.5.","Step 4: Frequency = 9.","Step 5: Therefore the point is (34.5, 9)."],"options":[],"conceptId":"math_statistics_constructing_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Constructing a Frequency Polygon"}', 2),
  (837, 248, 'A frequency polygon has frequencies 4, 9 and 6. Which class has the greatest frequency?', 'text', 1, 'Find the largest frequency.', '{"why":"The highest point represents the greatest frequency.","sol":"Step 1: Compare 4, 9 and 6.\nStep 2: The largest is 9.\nStep 3: Therefore the class represented by frequency 9 has the greatest frequency.","steps":["Step 1: Compare 4, 9 and 6.","Step 2: The largest is 9.","Step 3: Therefore the class represented by frequency 9 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 0),
  (838, 248, 'Two consecutive classes have frequencies 10 and 7. How many fewer observations are in the second class?', 'text', 1, 'Subtract the smaller frequency from the larger one.', '{"why":"The second class contains 3 fewer observations.","sol":"Step 1: First class = 10.\nStep 2: Second class = 7.\nStep 3: Difference = 10 − 7.\nStep 4: Difference = 3.","steps":["Step 1: First class = 10.","Step 2: Second class = 7.","Step 3: Difference = 10 − 7.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 1),
  (839, 248, 'A frequency polygon reaches its highest point at midpoint 44.5. What does this tell you?', 'text', 1, 'Think about what the highest point means.', '{"why":"The highest point of a frequency polygon corresponds to the greatest frequency.","sol":"Step 1: The highest point represents the greatest frequency.\nStep 2: Its midpoint is 44.5.\nStep 3: Therefore the class centred at 44.5 has the greatest frequency.","steps":["Step 1: The highest point represents the greatest frequency.","Step 2: Its midpoint is 44.5.","Step 3: Therefore the class centred at 44.5 has the greatest frequency."],"options":[],"conceptId":"math_statistics_interpreting_a_frequency_polygon","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Interpreting a Frequency Polygon"}', 2),
  (840, 249, 'Representation A has frequencies 4, 7, 6. Representation B also has 4, 7, 6. Do they agree?', 'text', 1, 'Compare corresponding frequencies.', '{"why":"The two representations contain the same frequencies for every class.","sol":"Step 1: First frequency: 4 = 4.\nStep 2: Second frequency: 7 = 7.\nStep 3: Third frequency: 6 = 6.\nStep 4: All corresponding frequencies agree.","steps":["Step 1: First frequency: 4 = 4.","Step 2: Second frequency: 7 = 7.","Step 3: Third frequency: 6 = 6.","Step 4: All corresponding frequencies agree."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 0),
  (841, 249, 'One representation gives a frequency of 9 while another gives 6 for the same class. What is the difference?', 'text', 1, 'Subtract 6 from 9.', '{"why":"The representations disagree by 3 observations for that class.","sol":"Step 1: First frequency = 9.\nStep 2: Second frequency = 6.\nStep 3: Difference = 9 − 6.\nStep 4: Difference = 3.","steps":["Step 1: First frequency = 9.","Step 2: Second frequency = 6.","Step 3: Difference = 9 − 6.","Step 4: Difference = 3."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 1),
  (842, 249, 'Why should corresponding class frequencies be compared when checking two graphs?', 'text', 1, 'Think about what a graph is representing.', '{"why":"Matching corresponding frequencies verifies that the representations agree.","sol":"Step 1: Each graph represents frequencies for particular classes.\nStep 2: The same class must have the same frequency if the graphs represent the same data.\nStep 3: Therefore corresponding classes must be compared.","steps":["Step 1: Each graph represents frequencies for particular classes.","Step 2: The same class must have the same frequency if the graphs represent the same data.","Step 3: Therefore corresponding classes must be compared."],"options":[],"conceptId":"math_statistics_comparing_two_data_representations","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Comparing Two Data Representations"}', 2),
  (843, 250, 'A school wants to compare the number of learners in four houses. Which representation is appropriate?', 'text', 1, 'The houses are separate categories.', '{"why":"Bar graphs are appropriate for comparing separate categories.","sol":"Step 1: The data are grouped by house.\nStep 2: Each house is a separate category.\nStep 3: A bar graph is suitable for separate categories.","steps":["Step 1: The data are grouped by house.","Step 2: Each house is a separate category.","Step 3: A bar graph is suitable for separate categories."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 0),
  (844, 250, 'Marks are grouped as 0–9, 10–19, 20–29 and 30–39. Which representation is appropriate?', 'text', 1, 'These are numerical class intervals.', '{"why":"Histograms represent grouped numerical intervals.","sol":"Step 1: The data are marks.\nStep 2: They are grouped into numerical intervals.\nStep 3: A histogram is suitable for grouped numerical data.","steps":["Step 1: The data are marks.","Step 2: They are grouped into numerical intervals.","Step 3: A histogram is suitable for grouped numerical data."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 1),
  (845, 250, 'A teacher wants to show frequencies plotted against class midpoints and joined by straight lines. Which representation should be used?', 'text', 1, 'This description defines one particular graph.', '{"why":"A frequency polygon plots frequency against class midpoint and joins the points.","sol":"Step 1: The horizontal values are class midpoints.\nStep 2: The vertical values are frequencies.\nStep 3: The points are joined by straight lines.\nStep 4: This is a frequency polygon.","steps":["Step 1: The horizontal values are class midpoints.","Step 2: The vertical values are frequencies.","Step 3: The points are joined by straight lines.","Step 4: This is a frequency polygon."],"options":[],"conceptId":"math_statistics_choosing_the_appropriate_data_representation","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Choosing the Appropriate Data Representation"}', 2),
  (846, 251, 'A coin is tossed once. Is this a probability experiment?', 'text', 1, 'Ask whether the possible outcomes are known but the actual result is unknown.', '{"why":"A probability experiment has known possible outcomes but an uncertain actual outcome.","sol":"Step 1: The possible outcomes are Head and Tail.\nStep 2: The actual result is not known before the coin is tossed.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are Head and Tail.","Step 2: The actual result is not known before the coin is tossed.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 0),
  (847, 251, 'A six-sided die is rolled once. Is this a probability experiment?', 'text', 1, 'List what can happen before deciding.', '{"why":"The possible outcomes are known, but the actual outcome cannot be predicted with certainty.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: The number that will appear is not known before the roll.\nStep 3: Therefore, it is a probability experiment.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: The number that will appear is not known before the roll.","Step 3: Therefore, it is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 1),
  (848, 251, 'A bag contains red and green balls. One ball is drawn without looking. Explain why this is a probability experiment.', 'text', 1, 'Think about what is known and what is unknown.', '{"why":"Probability experiments involve uncertainty about which known possible outcome will occur.","sol":"Step 1: The possible outcomes include red and green.\nStep 2: The colour of the ball is not known before the draw.\nStep 3: Therefore, the draw is a probability experiment.","steps":["Step 1: The possible outcomes include red and green.","Step 2: The colour of the ball is not known before the draw.","Step 3: Therefore, the draw is a probability experiment."],"options":[],"conceptId":"math_probability_probability_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Experiment"}', 2),
  (849, 252, 'A coin is tossed once. List all possible outcomes.', 'text', 1, 'A coin has two possible results.', '{"why":"These are the two possible results of one coin toss.","sol":"Step 1: A coin can land on Head.\nStep 2: A coin can land on Tail.\nStep 3: Therefore the outcomes are {H, T}.","steps":["Step 1: A coin can land on Head.","Step 2: A coin can land on Tail.","Step 3: Therefore the outcomes are {H, T}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 0),
  (850, 252, 'A standard die is rolled once. List all possible outcomes.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Each face of the die represents one possible outcome.","sol":"Step 1: The die can show 1.\nStep 2: It can show 2, 3, 4, 5 or 6.\nStep 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The die can show 1.","Step 2: It can show 2, 3, 4, 5 or 6.","Step 3: Therefore the outcomes are {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 1),
  (851, 252, 'A bag contains red, blue and yellow balls. One ball is selected. What are the possible colour outcomes?', 'text', 1, 'Record colours, not individual balls.', '{"why":"The question asks for possible colour outcomes.","sol":"Step 1: A red ball may be selected.\nStep 2: A blue ball may be selected.\nStep 3: A yellow ball may be selected.\nStep 4: Therefore the outcomes are {Red, Blue, Yellow}.","steps":["Step 1: A red ball may be selected.","Step 2: A blue ball may be selected.","Step 3: A yellow ball may be selected.","Step 4: Therefore the outcomes are {Red, Blue, Yellow}."],"options":[],"conceptId":"math_probability_outcomes_of_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Outcomes of an Experiment"}', 2),
  (852, 253, 'A coin is tossed 8 times and gives H, T, H, H, T, H, T, H. How many Heads occurred?', 'text', 1, 'Count every H.', '{"why":"Frequency tells us how many times an outcome occurred.","sol":"Step 1: The Heads are in positions 1, 3, 4, 6 and 8.\nStep 2: There are 5 Heads.\nStep 3: Therefore, the frequency of Heads is 5.","steps":["Step 1: The Heads are in positions 1, 3, 4, 6 and 8.","Step 2: There are 5 Heads.","Step 3: Therefore, the frequency of Heads is 5."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 0),
  (853, 253, 'A die is rolled 10 times. The number 4 appears 3 times. What is the frequency of 4?', 'text', 1, 'Frequency means the number of times an outcome occurs.', '{"why":"The frequency of an outcome is simply how many times it occurred.","sol":"Step 1: The number 4 occurred 3 times.\nStep 2: Therefore, its frequency is 3.","steps":["Step 1: The number 4 occurred 3 times.","Step 2: Therefore, its frequency is 3."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 1),
  (854, 253, 'A coin is tossed 20 times. Heads occur 11 times. How many Tails occurred?', 'text', 1, 'Every trial gives either Head or Tail.', '{"why":"The Head and Tail frequencies must add to the total number of tosses.","sol":"Step 1: Total tosses = 20.\nStep 2: Heads = 11.\nStep 3: Tails = 20 − 11.\nStep 4: Tails = 9.","steps":["Step 1: Total tosses = 20.","Step 2: Heads = 11.","Step 3: Tails = 20 − 11.","Step 4: Tails = 9."],"options":[],"conceptId":"math_probability_recording_experimental_results","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recording Experimental Results"}', 2),
  (855, 254, 'A coin is tossed 50 times and Heads occur 27 times. Find the experimental probability of Heads.', 'text', 1, 'Use frequency of Heads ÷ total tosses.', '{"why":"Experimental probability uses the observed frequency divided by the total number of trials.","sol":"Step 1: Heads occurred 27 times.\nStep 2: Total tosses = 50.\nStep 3: P(Head) = 27 ÷ 50.\nStep 4: P(Head) = 27/50.","steps":["Step 1: Heads occurred 27 times.","Step 2: Total tosses = 50.","Step 3: P(Head) = 27 ÷ 50.","Step 4: P(Head) = 27/50."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 0),
  (856, 254, 'A die is rolled 40 times and the number 3 appears 7 times. Find the experimental probability of rolling 3.', 'text', 1, 'Divide 7 by 40.', '{"why":"The observed frequency of 3 is 7 out of 40 rolls.","sol":"Step 1: Frequency of 3 = 7.\nStep 2: Total trials = 40.\nStep 3: P(3) = 7 ÷ 40.\nStep 4: P(3) = 7/40.","steps":["Step 1: Frequency of 3 = 7.","Step 2: Total trials = 40.","Step 3: P(3) = 7 ÷ 40.","Step 4: P(3) = 7/40."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 1),
  (857, 254, 'A spinner is spun 25 times and lands on blue 10 times. Find the experimental probability of blue.', 'text', 1, 'Observed blue outcomes ÷ total spins.', '{"why":"The experiment produced 10 blue results in 25 trials.","sol":"Step 1: Blue occurred 10 times.\nStep 2: Total spins = 25.\nStep 3: P(Blue) = 10 ÷ 25.\nStep 4: P(Blue) = 2/5.","steps":["Step 1: Blue occurred 10 times.","Step 2: Total spins = 25.","Step 3: P(Blue) = 10 ÷ 25.","Step 4: P(Blue) = 2/5."],"options":[],"conceptId":"math_probability_calculating_experimental_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Calculating Experimental Probability"}', 2),
  (858, 255, 'A fair coin has a theoretical probability of 1/2 of getting Head. In 10 tosses, Head occurs 7 times. Find the experimental probability.', 'text', 1, 'Use observed Heads ÷ total tosses.', '{"why":"Experimental probability is calculated from the actual results of the experiment.","sol":"Step 1: Heads occurred 7 times.\nStep 2: Total tosses = 10.\nStep 3: Experimental probability = 7 ÷ 10.\nStep 4: Experimental probability = 7/10.","steps":["Step 1: Heads occurred 7 times.","Step 2: Total tosses = 10.","Step 3: Experimental probability = 7 ÷ 10.","Step 4: Experimental probability = 7/10."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 0),
  (859, 255, 'A fair die has a theoretical probability of 1/6 of rolling a 6. In 60 rolls, 12 sixes occur. Find the experimental probability.', 'text', 1, 'Divide the number of sixes by the number of rolls.', '{"why":"The experimental probability comes from the observed frequency, not the theoretical value.","sol":"Step 1: Six occurred 12 times.\nStep 2: Total rolls = 60.\nStep 3: Experimental probability = 12 ÷ 60.\nStep 4: Experimental probability = 1/5.","steps":["Step 1: Six occurred 12 times.","Step 2: Total rolls = 60.","Step 3: Experimental probability = 12 ÷ 60.","Step 4: Experimental probability = 1/5."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 1),
  (860, 255, 'A fair coin is tossed 100 times and gives 49 Heads. Is the experimental probability close to the theoretical probability of 1/2?', 'text', 1, 'Calculate the experimental probability first.', '{"why":"A large number of trials often produces an experimental probability close to the theoretical probability.","sol":"Step 1: Experimental probability = 49 ÷ 100.\nStep 2: Experimental probability = 0.49.\nStep 3: Theoretical probability = 0.50.\nStep 4: The difference is 0.01.\nStep 5: Therefore, the experimental probability is close to the theoretical probability.","steps":["Step 1: Experimental probability = 49 ÷ 100.","Step 2: Experimental probability = 0.49.","Step 3: Theoretical probability = 0.50.","Step 4: The difference is 0.01.","Step 5: Therefore, the experimental probability is close to the theoretical probability."],"options":[],"conceptId":"math_probability_comparing_experimental_and_theoretical_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Comparing Experimental and Theoretical Probability"}', 2),
  (861, 256, 'A coin is tossed once. Write the probability space.', 'text', 1, 'Think of every result that can occur when one coin is tossed.', '{"why":"A single coin toss has exactly two possible outcomes: Head and Tail.","sol":"Step 1: A coin can land showing a Head or a Tail.\nStep 2: Write both possible outcomes.\nStep 3: Therefore S = {H, T}.","steps":["Step 1: A coin can land showing a Head or a Tail.","Step 2: Write both possible outcomes.","Step 3: Therefore S = {H, T}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 0),
  (862, 256, 'A standard die is rolled once. Write the probability space.', 'text', 1, 'A standard die has six numbered faces.', '{"why":"Any one of the six faces can appear when the die is rolled.","sol":"Step 1: The smallest number on the die is 1.\nStep 2: The numbers continue through 2, 3, 4 and 5.\nStep 3: The largest number is 6.\nStep 4: Therefore S = {1, 2, 3, 4, 5, 6}.","steps":["Step 1: The smallest number on the die is 1.","Step 2: The numbers continue through 2, 3, 4 and 5.","Step 3: The largest number is 6.","Step 4: Therefore S = {1, 2, 3, 4, 5, 6}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 1),
  (863, 256, 'A card is chosen from cards labelled A, B, C and D. Write the probability space.', 'text', 1, 'List every label that can be selected.', '{"why":"The probability space contains every possible result of selecting one card.","sol":"Step 1: The possible cards are A, B, C and D.\nStep 2: Each one is a possible result of the experiment.\nStep 3: Therefore S = {A, B, C, D}.","steps":["Step 1: The possible cards are A, B, C and D.","Step 2: Each one is a possible result of the experiment.","Step 3: Therefore S = {A, B, C, D}."],"options":[],"conceptId":"math_probability_complete_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Complete Probability Space"}', 2),
  (864, 257, 'A spinner has four equal sections labelled 1, 2, 3 and 4. List all possible outcomes.', 'text', 1, 'Every label on the spinner can be obtained.', '{"why":"Every labelled section is a possible outcome.","sol":"Step 1: The spinner contains section 1.\nStep 2: It also contains sections 2, 3 and 4.\nStep 3: Any of these sections can be selected.\nStep 4: Therefore S = {1, 2, 3, 4}.","steps":["Step 1: The spinner contains section 1.","Step 2: It also contains sections 2, 3 and 4.","Step 3: Any of these sections can be selected.","Step 4: Therefore S = {1, 2, 3, 4}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 0),
  (865, 257, 'One letter is selected from {M, N, P}. List the probability space.', 'text', 1, 'The selected letter can be M, N or P.', '{"why":"These are all the choices available in the experiment.","sol":"Step 1: M is a possible result.\nStep 2: N is a possible result.\nStep 3: P is a possible result.\nStep 4: Therefore S = {M, N, P}.","steps":["Step 1: M is a possible result.","Step 2: N is a possible result.","Step 3: P is a possible result.","Step 4: Therefore S = {M, N, P}."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 1),
  (866, 257, 'A die is rolled once. A student writes {1, 2, 3, 4, 5}. Is this a complete probability space?', 'text', 1, 'Check whether every possible die result has been included.', '{"why":"A complete probability space for one die must include 6.","sol":"Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.\nStep 2: The student''s list does not contain 6.\nStep 3: Therefore one possible outcome is missing.\nStep 4: The list is not complete.","steps":["Step 1: A standard die can produce 1, 2, 3, 4, 5 or 6.","Step 2: The student''s list does not contain 6.","Step 3: Therefore one possible outcome is missing.","Step 4: The list is not complete."],"options":[],"conceptId":"math_probability_listing_outcomes_of_a_single_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Listing Outcomes of a Single Experiment"}', 2),
  (867, 258, 'A coin is tossed twice. Write the complete probability space.', 'text', 1, 'Start with H on the first toss, then T on the first toss.', '{"why":"Each of the two tosses can be H or T, producing four ordered outcomes.","sol":"Step 1: If the first toss is H, the second toss can be H or T: HH, HT.\nStep 2: If the first toss is T, the second toss can be H or T: TH, TT.\nStep 3: Combine all four outcomes.\nStep 4: Therefore S = {HH, HT, TH, TT}.","steps":["Step 1: If the first toss is H, the second toss can be H or T: HH, HT.","Step 2: If the first toss is T, the second toss can be H or T: TH, TT.","Step 3: Combine all four outcomes.","Step 4: Therefore S = {HH, HT, TH, TT}."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 0),
  (868, 258, 'A student says that HH and TT are the only possible outcomes when a coin is tossed twice. What is wrong?', 'text', 1, 'Consider what happens when the two tosses are different.', '{"why":"Two tosses can have different results, not only matching results.","sol":"Step 1: The first toss can be H and the second T, giving HT.\nStep 2: The first toss can also be T and the second H, giving TH.\nStep 3: Therefore HT and TH are also possible.\nStep 4: The student''s list is incomplete.","steps":["Step 1: The first toss can be H and the second T, giving HT.","Step 2: The first toss can also be T and the second H, giving TH.","Step 3: Therefore HT and TH are also possible.","Step 4: The student''s list is incomplete."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 1),
  (869, 258, 'Explain why HT and TH are different outcomes.', 'text', 1, 'Look at the order of the two tosses.', '{"why":"An outcome of a repeated experiment records what happened at each stage.","sol":"Step 1: HT means H occurs first and T occurs second.\nStep 2: TH means T occurs first and H occurs second.\nStep 3: The order of the results is different.\nStep 4: Therefore they represent different outcomes.","steps":["Step 1: HT means H occurs first and T occurs second.","Step 2: TH means T occurs first and H occurs second.","Step 3: The order of the results is different.","Step 4: Therefore they represent different outcomes."],"options":[],"conceptId":"math_probability_probability_space_for_two_coin_tosses","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Space for Two Coin Tosses"}', 2),
  (870, 259, 'A die is rolled and then a coin is tossed. List all possible outcomes.', 'text', 1, 'For every die result, attach H and T.', '{"why":"Each of the 6 die results can be followed by either H or T.","sol":"Step 1: The die can give 1, 2, 3, 4, 5 or 6.\nStep 2: For each die result, the coin can give H or T.\nStep 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.\nStep 4: There are 12 outcomes.","steps":["Step 1: The die can give 1, 2, 3, 4, 5 or 6.","Step 2: For each die result, the coin can give H or T.","Step 3: Therefore the outcomes are 1H, 1T, 2H, 2T, 3H, 3T, 4H, 4T, 5H, 5T, 6H, 6T.","Step 4: There are 12 outcomes."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 0),
  (871, 259, 'A spinner has A or B. A coin is then tossed. List all possible outcomes.', 'text', 1, 'Start with A, then start with B.', '{"why":"Every first-stage outcome must be paired with every possible second-stage outcome.","sol":"Step 1: If the spinner gives A, the coin can give H or T: AH, AT.\nStep 2: If the spinner gives B, the coin can give H or T: BH, BT.\nStep 3: Therefore S = {AH, AT, BH, BT}.","steps":["Step 1: If the spinner gives A, the coin can give H or T: AH, AT.","Step 2: If the spinner gives B, the coin can give H or T: BH, BT.","Step 3: Therefore S = {AH, AT, BH, BT}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 1),
  (872, 259, 'A two-stage experiment has first-stage outcomes P and Q, and second-stage outcomes 1, 2 and 3. List all possible outcomes.', 'text', 1, 'Pair P with all three numbers, then Q with all three numbers.', '{"why":"There are 2 choices at the first stage and 3 choices at the second stage, giving 6 combinations.","sol":"Step 1: Starting with P gives P1, P2 and P3.\nStep 2: Starting with Q gives Q1, Q2 and Q3.\nStep 3: Combine the outcomes.\nStep 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}.","steps":["Step 1: Starting with P gives P1, P2 and P3.","Step 2: Starting with Q gives Q1, Q2 and Q3.","Step 3: Combine the outcomes.","Step 4: Therefore S = {P1, P2, P3, Q1, Q2, Q3}."],"options":[],"conceptId":"math_probability_systematically_listing_two_stage_outcomes","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Systematically Listing Two-Stage Outcomes"}', 2),
  (873, 260, 'A fair die is rolled. Find the probability of getting 5.', 'text', 1, 'First write the complete probability space.', '{"why":"One of the six equally likely die outcomes is 5.","sol":"Step 1: The probability space is {1, 2, 3, 4, 5, 6}.\nStep 2: Only 5 is favourable, so there is 1 favourable outcome.\nStep 3: There are 6 possible outcomes in total.\nStep 4: Therefore P(5) = 1/6.","steps":["Step 1: The probability space is {1, 2, 3, 4, 5, 6}.","Step 2: Only 5 is favourable, so there is 1 favourable outcome.","Step 3: There are 6 possible outcomes in total.","Step 4: Therefore P(5) = 1/6."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 0),
  (874, 260, 'A fair die is rolled. Find the probability of getting an odd number.', 'text', 1, 'Identify the odd outcomes in {1, 2, 3, 4, 5, 6}.', '{"why":"Three of the six equally likely die outcomes are odd.","sol":"Step 1: The odd outcomes are 1, 3 and 5.\nStep 2: There are 3 favourable outcomes.\nStep 3: There are 6 total outcomes.\nStep 4: Therefore P(odd) = 3/6.\nStep 5: Simplify 3/6 by dividing by 3.\nStep 6: P(odd) = 1/2.","steps":["Step 1: The odd outcomes are 1, 3 and 5.","Step 2: There are 3 favourable outcomes.","Step 3: There are 6 total outcomes.","Step 4: Therefore P(odd) = 3/6.","Step 5: Simplify 3/6 by dividing by 3.","Step 6: P(odd) = 1/2."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 1),
  (875, 260, 'A fair coin is tossed twice. Find the probability of getting exactly two tails.', 'text', 1, 'Use the probability space for two coin tosses.', '{"why":"TT is the only outcome containing two tails.","sol":"Step 1: The probability space is {HH, HT, TH, TT}.\nStep 2: Exactly two tails occurs only in TT.\nStep 3: There is 1 favourable outcome.\nStep 4: There are 4 total outcomes.\nStep 5: Therefore P(two tails) = 1/4.","steps":["Step 1: The probability space is {HH, HT, TH, TT}.","Step 2: Exactly two tails occurs only in TT.","Step 3: There is 1 favourable outcome.","Step 4: There are 4 total outcomes.","Step 5: Therefore P(two tails) = 1/4."],"options":[],"conceptId":"math_probability_theoretical_probability_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Theoretical Probability from a Probability Space"}', 2),
  (876, 261, 'A standard die is rolled. What is the probability of getting 9?', 'text', 1, 'Check whether 9 is one of the possible die outcomes.', '{"why":"A standard die cannot produce 9.","sol":"Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: 9 is not a possible outcome.\nStep 3: Therefore there are 0 favourable outcomes.\nStep 4: P(9) = 0/6 = 0.","steps":["Step 1: The possible outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: 9 is not a possible outcome.","Step 3: Therefore there are 0 favourable outcomes.","Step 4: P(9) = 0/6 = 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Impossible Events"}', 0),
  (877, 261, 'A bag contains only red and blue balls. One ball is selected. What is the probability of selecting a green ball?', 'text', 1, 'Is green one of the possible colours in the bag?', '{"why":"There is no green ball available to be selected.","sol":"Step 1: The only possible colours are red and blue.\nStep 2: Green is not in the bag.\nStep 3: Therefore selecting green is impossible.\nStep 4: The probability is 0.","steps":["Step 1: The only possible colours are red and blue.","Step 2: Green is not in the bag.","Step 3: Therefore selecting green is impossible.","Step 4: The probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Impossible Events"}', 1),
  (878, 261, 'A coin is tossed once. What is the probability of getting both Head and Tail?', 'text', 1, 'A single toss produces only one result.', '{"why":"One coin toss gives one outcome, not two outcomes at the same time.","sol":"Step 1: The possible outcomes are H and T.\nStep 2: One toss cannot produce H and T simultaneously.\nStep 3: Therefore the event is impossible.\nStep 4: Its probability is 0.","steps":["Step 1: The possible outcomes are H and T.","Step 2: One toss cannot produce H and T simultaneously.","Step 3: Therefore the event is impossible.","Step 4: Its probability is 0."],"options":[],"conceptId":"math_probability_impossible_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Impossible Events"}', 2),
  (879, 262, 'A standard die is rolled. Find the probability of getting a number less than 7.', 'text', 1, 'Check every possible result of the die.', '{"why":"Every possible result of a standard die is less than 7.","sol":"Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.\nStep 2: Every one of these numbers is less than 7.\nStep 3: Therefore there are 6 favourable outcomes out of 6.\nStep 4: P(number less than 7) = 6/6 = 1.","steps":["Step 1: The outcomes are 1, 2, 3, 4, 5 and 6.","Step 2: Every one of these numbers is less than 7.","Step 3: Therefore there are 6 favourable outcomes out of 6.","Step 4: P(number less than 7) = 6/6 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Certain Events"}', 0),
  (880, 262, 'A coin is tossed once. What is the probability of getting either Head or Tail?', 'text', 1, 'These are the only two possible outcomes.', '{"why":"A coin must show either Head or Tail when tossed.","sol":"Step 1: The probability space is {H, T}.\nStep 2: Both possible outcomes satisfy the event.\nStep 3: Therefore there are 2 favourable outcomes out of 2.\nStep 4: P(event) = 2/2 = 1.","steps":["Step 1: The probability space is {H, T}.","Step 2: Both possible outcomes satisfy the event.","Step 3: Therefore there are 2 favourable outcomes out of 2.","Step 4: P(event) = 2/2 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Certain Events"}', 1),
  (881, 262, 'Cards labelled 2, 4 and 6 are placed in a bag. One card is selected. Find the probability of selecting an even number.', 'text', 1, 'Check each card.', '{"why":"Every available card contains an even number.","sol":"Step 1: The possible outcomes are 2, 4 and 6.\nStep 2: All three numbers are even.\nStep 3: Therefore there are 3 favourable outcomes out of 3.\nStep 4: P(even) = 3/3 = 1.","steps":["Step 1: The possible outcomes are 2, 4 and 6.","Step 2: All three numbers are even.","Step 3: Therefore there are 3 favourable outcomes out of 3.","Step 4: P(even) = 3/3 = 1."],"options":[],"conceptId":"math_probability_certain_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Certain Events"}', 2),
  (882, 263, 'Which of the following can be a probability: 0, 0.4, 1 or 1.3?', 'text', 1, 'A probability must lie from 0 to 1 inclusive.', '{"why":"Valid probabilities satisfy 0 ≤ P(E) ≤ 1.","sol":"Step 1: 0 is allowed because an impossible event has probability 0.\nStep 2: 0.4 is between 0 and 1.\nStep 3: 1 is allowed because a certain event has probability 1.\nStep 4: 1.3 is greater than 1 and therefore cannot be a probability.","steps":["Step 1: 0 is allowed because an impossible event has probability 0.","Step 2: 0.4 is between 0 and 1.","Step 3: 1 is allowed because a certain event has probability 1.","Step 4: 1.3 is greater than 1 and therefore cannot be a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 0),
  (883, 263, 'Can 1.2 be the probability of an event? Explain.', 'text', 1, 'Compare 1.2 with the upper limit of probability.', '{"why":"A probability cannot be greater than 1.","sol":"Step 1: The greatest possible probability is 1.\nStep 2: 1.2 is greater than 1.\nStep 3: Therefore 1.2 cannot represent a probability.","steps":["Step 1: The greatest possible probability is 1.","Step 2: 1.2 is greater than 1.","Step 3: Therefore 1.2 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 1),
  (884, 263, 'Can -0.3 be the probability of an event? Explain.', 'text', 1, 'Compare -0.3 with the lower limit of probability.', '{"why":"A probability cannot be negative.","sol":"Step 1: The smallest possible probability is 0.\nStep 2: -0.3 is less than 0.\nStep 3: Therefore -0.3 cannot represent a probability.","steps":["Step 1: The smallest possible probability is 0.","Step 2: -0.3 is less than 0.","Step 3: Therefore -0.3 cannot represent a probability."],"options":[],"conceptId":"math_probability_probability_between_0_and_1","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Between 0 and 1"}', 2),
  (885, 264, 'What does a probability of 0 mean?', 'text', 1, 'Think about whether the event can happen.', '{"why":"Probability 0 represents an event that cannot occur.","sol":"Step 1: A probability of 0 is the lowest possible probability.\nStep 2: An event with probability 0 cannot happen.\nStep 3: Therefore the event is impossible.","steps":["Step 1: A probability of 0 is the lowest possible probability.","Step 2: An event with probability 0 cannot happen.","Step 3: Therefore the event is impossible."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 0),
  (886, 264, 'What does a probability of 1 mean?', 'text', 1, 'Think about the highest possible probability.', '{"why":"Probability 1 represents an event that must occur.","sol":"Step 1: A probability of 1 is the highest possible probability.\nStep 2: An event with probability 1 must happen.\nStep 3: Therefore the event is certain.","steps":["Step 1: A probability of 1 is the highest possible probability.","Step 2: An event with probability 1 must happen.","Step 3: Therefore the event is certain."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 1),
  (887, 264, 'Which event is more certain: Event A with probability 0.2 or Event B with probability 0.8?', 'text', 1, 'Compare the two values.', '{"why":"A larger probability represents a greater likelihood of the event occurring.","sol":"Step 1: Event A has probability 0.2.\nStep 2: Event B has probability 0.8.\nStep 3: 0.8 is closer to 1 than 0.2.\nStep 4: Therefore Event B is more likely to occur.","steps":["Step 1: Event A has probability 0.2.","Step 2: Event B has probability 0.8.","Step 3: 0.8 is closer to 1 than 0.2.","Step 4: Therefore Event B is more likely to occur."],"options":[],"conceptId":"math_probability_interpreting_probability_values","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Interpreting Probability Values"}', 2),
  (888, 265, 'Is 0.65 a valid probability?', 'text', 1, 'Check whether 0.65 lies between 0 and 1.', '{"why":"0.65 lies within the probability range from 0 to 1.","sol":"Step 1: 0.65 is greater than 0.\nStep 2: 0.65 is less than 1.\nStep 3: Therefore 0 ≤ 0.65 ≤ 1.\nStep 4: So 0.65 is a valid probability.","steps":["Step 1: 0.65 is greater than 0.","Step 2: 0.65 is less than 1.","Step 3: Therefore 0 ≤ 0.65 ≤ 1.","Step 4: So 0.65 is a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 0),
  (889, 265, 'Is -1/3 a valid probability?', 'text', 1, 'A probability cannot be less than 0.', '{"why":"Probabilities cannot be negative.","sol":"Step 1: -1/3 is less than 0.\nStep 2: Therefore it violates the lower limit.\nStep 3: So -1/3 cannot be a probability.","steps":["Step 1: -1/3 is less than 0.","Step 2: Therefore it violates the lower limit.","Step 3: So -1/3 cannot be a probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 1),
  (890, 265, 'Is 7/6 a valid probability?', 'text', 1, 'Compare 7/6 with 1.', '{"why":"The value is greater than the maximum possible probability, 1.","sol":"Step 1: 7/6 is greater than 6/6.\nStep 2: 6/6 = 1.\nStep 3: Therefore 7/6 > 1.\nStep 4: A probability cannot be greater than 1.\nStep 5: So 7/6 is not a valid probability.","steps":["Step 1: 7/6 is greater than 6/6.","Step 2: 6/6 = 1.","Step 3: Therefore 7/6 > 1.","Step 4: A probability cannot be greater than 1.","Step 5: So 7/6 is not a valid probability."],"options":[],"conceptId":"math_probability_checking_whether_a_probability_is_valid","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Checking Whether a Probability Is Valid"}', 2),
  (891, 266, 'A coin is tossed once. Are getting Head and getting Tail mutually exclusive?', 'text', 1, 'Can one toss produce both results at the same time?', '{"why":"Head and Tail cannot occur together in one coin toss.","sol":"Step 1: One coin toss produces one result.\nStep 2: The result can be Head or Tail.\nStep 3: It cannot be Head and Tail at the same time.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: One coin toss produces one result.","Step 2: The result can be Head or Tail.","Step 3: It cannot be Head and Tail at the same time.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 0),
  (892, 266, 'A die is rolled once. Are getting 2 and getting 6 mutually exclusive?', 'text', 1, 'Can one roll have both 2 and 6 as its result?', '{"why":"A single die roll cannot produce two different numbers.","sol":"Step 1: One die roll produces one number.\nStep 2: The result cannot be both 2 and 6.\nStep 3: Therefore the two events cannot occur together.\nStep 4: They are mutually exclusive.","steps":["Step 1: One die roll produces one number.","Step 2: The result cannot be both 2 and 6.","Step 3: Therefore the two events cannot occur together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 1),
  (893, 266, 'One card is selected. Are selecting a red card and selecting a blue card mutually exclusive?', 'text', 1, 'Only one card is selected.', '{"why":"One selected card cannot belong to two different colours at the same time.","sol":"Step 1: Only one card is selected.\nStep 2: That card cannot be red and blue at the same time.\nStep 3: Therefore the two events cannot happen together.\nStep 4: They are mutually exclusive.","steps":["Step 1: Only one card is selected.","Step 2: That card cannot be red and blue at the same time.","Step 3: Therefore the two events cannot happen together.","Step 4: They are mutually exclusive."],"options":[],"conceptId":"math_probability_meaning_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Mutually Exclusive Events"}', 2),
  (894, 267, 'A die is rolled once. Event A is getting {1, 2, 3}. Event B is getting {4, 5, 6}. Are they mutually exclusive?', 'text', 1, 'Look for a number appearing in both sets.', '{"why":"The two events have no outcome in common.","sol":"Step 1: Event A contains 1, 2 and 3.\nStep 2: Event B contains 4, 5 and 6.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Event A contains 1, 2 and 3.","Step 2: Event B contains 4, 5 and 6.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 0),
  (895, 267, 'A die is rolled once. Event A is getting {2, 4, 6}. Event B is getting {1, 2, 3}. Are they mutually exclusive?', 'text', 1, 'Check whether the two sets have a common number.', '{"why":"The events share the outcome 2.","sol":"Step 1: Event A contains 2, 4 and 6.\nStep 2: Event B contains 1, 2 and 3.\nStep 3: The number 2 appears in both events.\nStep 4: Therefore both events can occur when the die shows 2.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2, 4 and 6.","Step 2: Event B contains 1, 2 and 3.","Step 3: The number 2 appears in both events.","Step 4: Therefore both events can occur when the die shows 2.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 1),
  (896, 267, 'A die is rolled once. Event A is getting a number less than 3. Event B is getting a number greater than 4. Are they mutually exclusive?', 'text', 1, 'Write the outcomes belonging to each event.', '{"why":"No die result can be both less than 3 and greater than 4.","sol":"Step 1: Numbers less than 3 are {1, 2}.\nStep 2: Numbers greater than 4 are {5, 6}.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: Numbers less than 3 are {1, 2}.","Step 2: Numbers greater than 4 are {5, 6}.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_identifying_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Identifying Mutually Exclusive Events"}', 2),
  (897, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {1, 2} and B = {3, 4}, determine whether A and B are mutually exclusive.', 'text', 1, 'Look for a common outcome.', '{"why":"The two events do not share any possible outcome.","sol":"Step 1: Event A contains 1 and 2.\nStep 2: Event B contains 3 and 4.\nStep 3: There is no outcome common to both events.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: Event A contains 1 and 2.","Step 2: Event B contains 3 and 4.","Step 3: There is no outcome common to both events.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 0),
  (898, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 4} and B = {1, 3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Compare the two sets.', '{"why":"The events have no common outcome.","sol":"Step 1: A contains 2 and 4.\nStep 2: B contains 1, 3 and 5.\nStep 3: There is no number common to both.\nStep 4: Therefore A and B are mutually exclusive.","steps":["Step 1: A contains 2 and 4.","Step 2: B contains 1, 3 and 5.","Step 3: There is no number common to both.","Step 4: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 1),
  (899, 268, 'Given S = {1, 2, 3, 4, 5, 6}, A = {2, 3} and B = {3, 5}, determine whether A and B are mutually exclusive.', 'text', 1, 'Check the number 3.', '{"why":"The events share the outcome 3.","sol":"Step 1: Event A contains 2 and 3.\nStep 2: Event B contains 3 and 5.\nStep 3: The outcome 3 belongs to both events.\nStep 4: Therefore both events can occur when the outcome is 3.\nStep 5: They are not mutually exclusive.","steps":["Step 1: Event A contains 2 and 3.","Step 2: Event B contains 3 and 5.","Step 3: The outcome 3 belongs to both events.","Step 4: Therefore both events can occur when the outcome is 3.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events from a Probability Space"}', 2),
  (900, 269, 'A die is rolled once. A is getting an odd number and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Can one number be both odd and even?', '{"why":"A number cannot be both odd and even.","sol":"Step 1: The possible results are 1, 2, 3, 4, 5 and 6.\nStep 2: Odd results are 1, 3 and 5.\nStep 3: Even results are 2, 4 and 6.\nStep 4: No result is both odd and even.\nStep 5: Therefore A and B are mutually exclusive.","steps":["Step 1: The possible results are 1, 2, 3, 4, 5 and 6.","Step 2: Odd results are 1, 3 and 5.","Step 3: Even results are 2, 4 and 6.","Step 4: No result is both odd and even.","Step 5: Therefore A and B are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 0),
  (901, 269, 'A die is rolled once. A is getting 1 and B is getting an even number. Are A and B mutually exclusive?', 'text', 1, 'Is 1 an even number?', '{"why":"Getting 1 cannot occur at the same time as getting an even number.","sol":"Step 1: Event A happens only when the result is 1.\nStep 2: Event B happens when the result is 2, 4 or 6.\nStep 3: The result 1 is not even.\nStep 4: Therefore no result can make both events happen.\nStep 5: They are mutually exclusive.","steps":["Step 1: Event A happens only when the result is 1.","Step 2: Event B happens when the result is 2, 4 or 6.","Step 3: The result 1 is not even.","Step 4: Therefore no result can make both events happen.","Step 5: They are mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 1),
  (902, 269, 'A die is rolled once. A is getting an even number and B is getting a number greater than 3. Are A and B mutually exclusive?', 'text', 1, 'Try the outcome 4.', '{"why":"The outcome 4 belongs to both events.","sol":"Step 1: 4 is an even number.\nStep 2: 4 is also greater than 3.\nStep 3: Therefore outcome 4 makes both A and B happen.\nStep 4: So the events can happen together.\nStep 5: They are not mutually exclusive.","steps":["Step 1: 4 is an even number.","Step 2: 4 is also greater than 3.","Step 3: Therefore outcome 4 makes both A and B happen.","Step 4: So the events can happen together.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_mutually_exclusive_events_in_an_experiment","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Mutually Exclusive Events in an Experiment"}', 2),
  (903, 270, 'A = {1, 2} and B = {4, 5}. Are the events mutually exclusive?', 'text', 1, 'Check whether A and B have a common outcome.', '{"why":"The two events cannot occur from the same outcome.","sol":"Step 1: A contains 1 and 2.\nStep 2: B contains 4 and 5.\nStep 3: There is no common outcome.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1 and 2.","Step 2: B contains 4 and 5.","Step 3: There is no common outcome.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 0),
  (904, 270, 'A = {2, 3, 4} and B = {4, 5, 6}. Are the events mutually exclusive?', 'text', 1, 'Look carefully at both sets.', '{"why":"The events share outcome 4.","sol":"Step 1: A contains 2, 3 and 4.\nStep 2: B contains 4, 5 and 6.\nStep 3: The outcome 4 appears in both sets.\nStep 4: Therefore both events can occur for the same outcome.\nStep 5: They are not mutually exclusive.","steps":["Step 1: A contains 2, 3 and 4.","Step 2: B contains 4, 5 and 6.","Step 3: The outcome 4 appears in both sets.","Step 4: Therefore both events can occur for the same outcome.","Step 5: They are not mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 1),
  (905, 270, 'A = {1, 3, 5} and B = {2, 4, 6}. Are the events mutually exclusive?', 'text', 1, 'Compare every outcome in A with the outcomes in B.', '{"why":"The two events have no common outcome.","sol":"Step 1: A contains 1, 3 and 5.\nStep 2: B contains 2, 4 and 6.\nStep 3: No outcome appears in both sets.\nStep 4: Therefore the events are mutually exclusive.","steps":["Step 1: A contains 1, 3 and 5.","Step 2: B contains 2, 4 and 6.","Step 3: No outcome appears in both sets.","Step 4: Therefore the events are mutually exclusive."],"options":[],"conceptId":"math_probability_testing_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Testing Mutually Exclusive Events"}', 2),
  (906, 271, 'A fair coin is tossed twice. If the first toss is Head, does this change the probability of Head on the second toss?', 'text', 1, 'The first toss does not change the coin.', '{"why":"The two coin tosses are independent.","sol":"Step 1: A fair coin has P(Head) = 1/2.\nStep 2: The first toss produces Head.\nStep 3: The second toss is still a toss of the same fair coin.\nStep 4: Therefore P(Head on the second toss) remains 1/2.\nStep 5: The first result did not affect the second probability.","steps":["Step 1: A fair coin has P(Head) = 1/2.","Step 2: The first toss produces Head.","Step 3: The second toss is still a toss of the same fair coin.","Step 4: Therefore P(Head on the second toss) remains 1/2.","Step 5: The first result did not affect the second probability."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 0),
  (907, 271, 'A die is rolled twice. The first roll is 4. Does this change the probability of getting 6 on the second roll?', 'text', 1, 'Ask whether the first roll changes the die.', '{"why":"The first die roll does not affect the second roll.","sol":"Step 1: A standard die has six possible results.\nStep 2: The first roll gives 4.\nStep 3: The die still has all six faces for the second roll.\nStep 4: Therefore P(6 on the second roll) is still 1/6.","steps":["Step 1: A standard die has six possible results.","Step 2: The first roll gives 4.","Step 3: The die still has all six faces for the second roll.","Step 4: Therefore P(6 on the second roll) is still 1/6."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 1),
  (908, 271, 'A coin is tossed and then a die is rolled. Does getting Head on the coin change the probability of getting 5 on the die?', 'text', 1, 'Does the coin result change the die?', '{"why":"The two experiments do not affect each other''s probabilities.","sol":"Step 1: Getting Head is an outcome of the coin experiment.\nStep 2: The die still has six possible outcomes.\nStep 3: Therefore the probability of 5 on the die remains 1/6.\nStep 4: The coin result does not affect the die.","steps":["Step 1: Getting Head is an outcome of the coin experiment.","Step 2: The die still has six possible outcomes.","Step 3: Therefore the probability of 5 on the die remains 1/6.","Step 4: The coin result does not affect the die."],"options":[],"conceptId":"math_probability_meaning_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Meaning of Independent Events"}', 2),
  (909, 272, 'A coin is tossed twice. Are getting Head on the first toss and Head on the second toss independent events?', 'text', 1, 'Does the first toss change the second toss?', '{"why":"The result of the first toss does not affect the second toss.","sol":"Step 1: The first toss does not change the coin.\nStep 2: The second toss still has P(Head) = 1/2.\nStep 3: Therefore knowing the first result does not change the second probability.\nStep 4: The events are independent.","steps":["Step 1: The first toss does not change the coin.","Step 2: The second toss still has P(Head) = 1/2.","Step 3: Therefore knowing the first result does not change the second probability.","Step 4: The events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 0),
  (910, 272, 'A die is rolled twice. Are getting 3 first and 6 second independent events?', 'text', 1, 'Does rolling 3 remove anything from the die?', '{"why":"One die roll does not affect a later die roll.","sol":"Step 1: The first roll gives 3.\nStep 2: The die still has all six faces for the second roll.\nStep 3: The probability of 6 remains 1/6.\nStep 4: Therefore the events are independent.","steps":["Step 1: The first roll gives 3.","Step 2: The die still has all six faces for the second roll.","Step 3: The probability of 6 remains 1/6.","Step 4: Therefore the events are independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 1),
  (911, 272, 'A bag contains 3 red balls and 2 blue balls. One ball is selected and kept outside the bag. Is the colour of the second selection independent of the first selection?', 'text', 1, 'Does removing the first ball change the contents of the bag?', '{"why":"Removing the first ball changes the composition of the bag.","sol":"Step 1: There are initially 5 balls.\nStep 2: The first ball is not returned.\nStep 3: Therefore only 4 balls remain.\nStep 4: The numbers of red and blue balls remaining depend on the first colour selected.\nStep 5: Therefore the second probability can change.\nStep 6: The selections are not independent.","steps":["Step 1: There are initially 5 balls.","Step 2: The first ball is not returned.","Step 3: Therefore only 4 balls remain.","Step 4: The numbers of red and blue balls remaining depend on the first colour selected.","Step 5: Therefore the second probability can change.","Step 6: The selections are not independent."],"options":[],"conceptId":"math_probability_recognising_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Recognising Independent Events"}', 2),
  (912, 273, 'A bag contains 4 red balls and 1 blue ball. A ball is selected, replaced, and another ball is selected. What is the probability of red on the second selection?', 'text', 1, 'The first ball is returned before the second selection.', '{"why":"Replacement restores the original contents of the bag.","sol":"Step 1: There are 4 red and 1 blue ball initially.\nStep 2: The first ball is replaced.\nStep 3: Therefore the bag still has 4 red and 1 blue ball.\nStep 4: Total balls = 4 + 1 = 5.\nStep 5: P(Red on second selection) = 4/5.","steps":["Step 1: There are 4 red and 1 blue ball initially.","Step 2: The first ball is replaced.","Step 3: Therefore the bag still has 4 red and 1 blue ball.","Step 4: Total balls = 4 + 1 = 5.","Step 5: P(Red on second selection) = 4/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 0),
  (913, 273, 'A bag contains 2 green balls and 3 yellow balls. A green ball is selected and replaced. What is the probability of yellow on the second selection?', 'text', 1, 'The green ball is returned before the second selection.', '{"why":"Replacing the first ball leaves the second selection with the original probabilities.","sol":"Step 1: Initially there are 2 green and 3 yellow balls.\nStep 2: The green ball is replaced.\nStep 3: The bag therefore still contains 2 green and 3 yellow balls.\nStep 4: Total balls = 5.\nStep 5: P(Yellow) = 3/5.","steps":["Step 1: Initially there are 2 green and 3 yellow balls.","Step 2: The green ball is replaced.","Step 3: The bag therefore still contains 2 green and 3 yellow balls.","Step 4: Total balls = 5.","Step 5: P(Yellow) = 3/5."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 1),
  (914, 273, 'A bag contains 5 red balls and 5 blue balls. A ball is selected and replaced. Does the first selection change the probability of red on the second selection?', 'text', 1, 'Compare the bag before and after replacement.', '{"why":"Replacement restores exactly the original collection.","sol":"Step 1: Initially there are 5 red and 5 blue balls.\nStep 2: The selected ball is returned.\nStep 3: The bag again contains 5 red and 5 blue balls.\nStep 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.\nStep 5: The first selection does not change the second probability.","steps":["Step 1: Initially there are 5 red and 5 blue balls.","Step 2: The selected ball is returned.","Step 3: The bag again contains 5 red and 5 blue balls.","Step 4: Therefore P(Red on the second selection) remains 5/10 = 1/2.","Step 5: The first selection does not change the second probability."],"options":[],"conceptId":"math_probability_independence_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence With Replacement"}', 2),
  (915, 274, 'A bag contains 4 red balls and 2 blue balls. A red ball is selected and not replaced. What is the probability of red on the second selection?', 'text', 1, 'Remove one red ball before calculating the second probability.', '{"why":"Removing the first red ball changes both the number of red balls and the total number of balls.","sol":"Step 1: Initially there are 4 red and 2 blue balls.\nStep 2: One red ball is removed.\nStep 3: Red balls remaining = 4 - 1 = 3.\nStep 4: Total balls remaining = 6 - 1 = 5.\nStep 5: Therefore P(Red on second selection) = 3/5.","steps":["Step 1: Initially there are 4 red and 2 blue balls.","Step 2: One red ball is removed.","Step 3: Red balls remaining = 4 - 1 = 3.","Step 4: Total balls remaining = 6 - 1 = 5.","Step 5: Therefore P(Red on second selection) = 3/5."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 0),
  (916, 274, 'A bag contains 3 green balls and 2 yellow balls. A yellow ball is selected and not replaced. What is the probability of green on the second selection?', 'text', 1, 'Removing a yellow ball leaves all the green balls in the bag.', '{"why":"The total number of balls changes after the first ball is removed.","sol":"Step 1: Initially there are 3 green and 2 yellow balls.\nStep 2: One yellow ball is removed.\nStep 3: Green balls remaining = 3.\nStep 4: Total balls remaining = 5 - 1 = 4.\nStep 5: Therefore P(Green on second selection) = 3/4.","steps":["Step 1: Initially there are 3 green and 2 yellow balls.","Step 2: One yellow ball is removed.","Step 3: Green balls remaining = 3.","Step 4: Total balls remaining = 5 - 1 = 4.","Step 5: Therefore P(Green on second selection) = 3/4."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 1),
  (917, 274, 'A bag contains 5 red and 1 blue ball. A red ball is selected and not replaced. Was the probability of selecting red changed?', 'text', 1, 'Compare the original and second-selection probabilities.', '{"why":"Removing a red ball changes the composition of the bag.","sol":"Step 1: Initially P(Red) = 5/6.\nStep 2: After one red is removed, 4 red balls remain.\nStep 3: There are now 5 balls in total.\nStep 4: The second probability is 4/5.\nStep 5: Since 5/6 is different from 4/5, the probability changed.","steps":["Step 1: Initially P(Red) = 5/6.","Step 2: After one red is removed, 4 red balls remain.","Step 3: There are now 5 balls in total.","Step 4: The second probability is 4/5.","Step 5: Since 5/6 is different from 4/5, the probability changed."],"options":[],"conceptId":"math_probability_independence_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Independence Without Replacement"}', 2),
  (918, 275, 'A fair die is rolled twice. Are the two rolls independent or dependent?', 'text', 1, 'Does the first roll change the die?', '{"why":"The first roll does not affect the second roll.","sol":"Step 1: The first roll produces one number.\nStep 2: Nothing is removed from or added to the die.\nStep 3: The die still has the same six possible outcomes.\nStep 4: Therefore the second probability is unchanged.\nStep 5: The rolls are independent.","steps":["Step 1: The first roll produces one number.","Step 2: Nothing is removed from or added to the die.","Step 3: The die still has the same six possible outcomes.","Step 4: Therefore the second probability is unchanged.","Step 5: The rolls are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 0),
  (919, 275, 'A ball is selected from a bag and kept outside. A second ball is selected. Are the two selections independent or dependent?', 'text', 1, 'Does removing the first ball change the bag?', '{"why":"The first selection changes the contents available for the second selection.","sol":"Step 1: The first ball is removed from the bag.\nStep 2: The contents of the bag therefore change.\nStep 3: The probability of the second selection can change.\nStep 4: Therefore the selections are dependent.","steps":["Step 1: The first ball is removed from the bag.","Step 2: The contents of the bag therefore change.","Step 3: The probability of the second selection can change.","Step 4: Therefore the selections are dependent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 1),
  (920, 275, 'A ball is selected from a bag, returned to the bag, and the bag is mixed. A second ball is selected. Are the selections independent or dependent?', 'text', 1, 'Compare the contents before the first and second selections.', '{"why":"Replacement restores the original conditions before the second selection.","sol":"Step 1: The first ball is selected.\nStep 2: It is returned to the bag.\nStep 3: The original collection is restored.\nStep 4: Therefore the probabilities for the second selection remain unchanged.\nStep 5: The selections are independent.","steps":["Step 1: The first ball is selected.","Step 2: It is returned to the bag.","Step 3: The original collection is restored.","Step 4: Therefore the probabilities for the second selection remain unchanged.","Step 5: The selections are independent."],"options":[],"conceptId":"math_probability_distinguishing_independent_and_dependent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Distinguishing Independent and Dependent Events"}', 2),
  (921, 276, 'A fair die is rolled. Find the probability of getting 1 or 4.', 'text', 1, 'Getting 1 and getting 4 are mutually exclusive.', '{"why":"There are two separate favourable outcomes, 1 and 4, out of six.","sol":"Step 1: P(1) = 1/6.\nStep 2: P(4) = 1/6.\nStep 3: The two events are mutually exclusive.\nStep 4: Therefore P(1 or 4) = 1/6 + 1/6.\nStep 5: P(1 or 4) = 2/6 = 1/3.","steps":["Step 1: P(1) = 1/6.","Step 2: P(4) = 1/6.","Step 3: The two events are mutually exclusive.","Step 4: Therefore P(1 or 4) = 1/6 + 1/6.","Step 5: P(1 or 4) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 0),
  (922, 276, 'A fair die is rolled. Find the probability of getting 3 or 6.', 'text', 1, 'Find each probability, then add them.', '{"why":"Getting 3 and getting 6 are mutually exclusive outcomes.","sol":"Step 1: P(3) = 1/6.\nStep 2: P(6) = 1/6.\nStep 3: The events cannot occur together in one roll.\nStep 4: Therefore P(3 or 6) = 1/6 + 1/6.\nStep 5: P(3 or 6) = 2/6 = 1/3.","steps":["Step 1: P(3) = 1/6.","Step 2: P(6) = 1/6.","Step 3: The events cannot occur together in one roll.","Step 4: Therefore P(3 or 6) = 1/6 + 1/6.","Step 5: P(3 or 6) = 2/6 = 1/3."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 1),
  (923, 276, 'A fair die is rolled. Find the probability of getting an odd number or an even number.', 'text', 1, 'Odd and even outcomes together cover all six die results.', '{"why":"Every possible die result is either odd or even.","sol":"Step 1: P(Odd) = 3/6 = 1/2.\nStep 2: P(Even) = 3/6 = 1/2.\nStep 3: Odd and even are mutually exclusive.\nStep 4: Therefore P(Odd or Even) = 1/2 + 1/2.\nStep 5: P(Odd or Even) = 1.","steps":["Step 1: P(Odd) = 3/6 = 1/2.","Step 2: P(Even) = 3/6 = 1/2.","Step 3: Odd and even are mutually exclusive.","Step 4: Therefore P(Odd or Even) = 1/2 + 1/2.","Step 5: P(Odd or Even) = 1."],"options":[],"conceptId":"math_probability_adding_probabilities_of_mutually_exclusive_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Adding Probabilities of Mutually Exclusive Events"}', 2),
  (924, 277, 'A fair die is rolled. Event A is {1, 2}. Event B is {5}. Find P(A or B).', 'text', 1, 'Count the favourable outcomes in both events.', '{"why":"There are three favourable outcomes: 1, 2 and 5.","sol":"Step 1: A has two favourable outcomes: 1 and 2.\nStep 2: B has one favourable outcome: 5.\nStep 3: The events are mutually exclusive.\nStep 4: Therefore P(A) = 2/6 and P(B) = 1/6.\nStep 5: P(A or B) = 2/6 + 1/6.\nStep 6: P(A or B) = 3/6 = 1/2.","steps":["Step 1: A has two favourable outcomes: 1 and 2.","Step 2: B has one favourable outcome: 5.","Step 3: The events are mutually exclusive.","Step 4: Therefore P(A) = 2/6 and P(B) = 1/6.","Step 5: P(A or B) = 2/6 + 1/6.","Step 6: P(A or B) = 3/6 = 1/2."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 0),
  (925, 277, 'A fair die is rolled. Event A is {1, 3, 5}. Event B is {2}. Find P(A or B).', 'text', 1, 'The two events have no common outcome.', '{"why":"The favourable outcomes are 1, 3, 5 and 2, giving four out of six.","sol":"Step 1: A has 3 favourable outcomes.\nStep 2: Therefore P(A) = 3/6 = 1/2.\nStep 3: B has 1 favourable outcome.\nStep 4: Therefore P(B) = 1/6.\nStep 5: P(A or B) = 1/2 + 1/6.\nStep 6: 1/2 = 3/6.\nStep 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3.","steps":["Step 1: A has 3 favourable outcomes.","Step 2: Therefore P(A) = 3/6 = 1/2.","Step 3: B has 1 favourable outcome.","Step 4: Therefore P(B) = 1/6.","Step 5: P(A or B) = 1/2 + 1/6.","Step 6: 1/2 = 3/6.","Step 7: Therefore P(A or B) = 3/6 + 1/6 = 4/6 = 2/3."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 1),
  (926, 277, 'A fair die is rolled. Event A is {1, 2, 3}. Event B is {5, 6}. Find P(A or B).', 'text', 1, 'Add the probabilities because there is no overlap.', '{"why":"Five of the six possible die outcomes belong to A or B.","sol":"Step 1: P(A) = 3/6 = 1/2.\nStep 2: P(B) = 2/6 = 1/3.\nStep 3: A and B are mutually exclusive.\nStep 4: Therefore P(A or B) = 1/2 + 1/3.\nStep 5: 1/2 = 3/6 and 1/3 = 2/6.\nStep 6: Therefore P(A or B) = 5/6.","steps":["Step 1: P(A) = 3/6 = 1/2.","Step 2: P(B) = 2/6 = 1/3.","Step 3: A and B are mutually exclusive.","Step 4: Therefore P(A or B) = 1/2 + 1/3.","Step 5: 1/2 = 3/6 and 1/3 = 2/6.","Step 6: Therefore P(A or B) = 5/6."],"options":[],"conceptId":"math_probability_the_addition_law_from_a_probability_space","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"The Addition Law from a Probability Space"}', 2),
  (927, 278, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses.', 'text', 1, 'The two tosses are independent.', '{"why":"Both independent events must occur, so their probabilities are multiplied.","sol":"Step 1: P(Head on first toss) = 1/2.\nStep 2: P(Head on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(H and H) = 1/2 × 1/2.\nStep 5: P(H and H) = 1/4.","steps":["Step 1: P(Head on first toss) = 1/2.","Step 2: P(Head on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(H and H) = 1/2 × 1/2.","Step 5: P(H and H) = 1/4."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 0),
  (928, 278, 'A fair die is rolled twice. Find the probability of getting 3 on both rolls.', 'text', 1, 'Each roll has probability 1/6 of giving 3.', '{"why":"The probability of each independent 3 must occur, so the probabilities are multiplied.","sol":"Step 1: P(3 on first roll) = 1/6.\nStep 2: P(3 on second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore P(3 and 3) = 1/6 × 1/6.\nStep 5: P(3 and 3) = 1/36.","steps":["Step 1: P(3 on first roll) = 1/6.","Step 2: P(3 on second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore P(3 and 3) = 1/6 × 1/6.","Step 5: P(3 and 3) = 1/36."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 1),
  (929, 278, 'A fair coin is tossed and a fair die is rolled. Find the probability of getting Tail and 2.', 'text', 1, 'Find each probability separately, then multiply.', '{"why":"The two independent events must both occur.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: P(2) = 1/6.\nStep 3: The coin toss and die roll are independent.\nStep 4: Therefore P(Tail and 2) = 1/2 × 1/6.\nStep 5: P(Tail and 2) = 1/12.","steps":["Step 1: P(Tail) = 1/2.","Step 2: P(2) = 1/6.","Step 3: The coin toss and die roll are independent.","Step 4: Therefore P(Tail and 2) = 1/2 × 1/6.","Step 5: P(Tail and 2) = 1/12."],"options":[],"conceptId":"math_probability_multiplying_probabilities_of_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplying Probabilities of Independent Events"}', 2),
  (930, 279, 'A fair coin is tossed twice. Find the probability of getting Tail on both tosses.', 'text', 1, 'Each Tail has probability 1/2 and the tosses are independent.', '{"why":"Both independent Tail events must occur.","sol":"Step 1: P(Tail on first toss) = 1/2.\nStep 2: P(Tail on second toss) = 1/2.\nStep 3: The tosses are independent.\nStep 4: Therefore P(T and T) = 1/2 × 1/2.\nStep 5: P(T and T) = 1/4.","steps":["Step 1: P(Tail on first toss) = 1/2.","Step 2: P(Tail on second toss) = 1/2.","Step 3: The tosses are independent.","Step 4: Therefore P(T and T) = 1/2 × 1/2.","Step 5: P(T and T) = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 0),
  (931, 279, 'A fair die is rolled twice. Find the probability of getting an odd number on both rolls.', 'text', 1, 'There are 3 odd numbers out of 6 on each roll.', '{"why":"The probability of an odd result is 1/2 on each independent roll.","sol":"Step 1: Odd outcomes are 1, 3 and 5.\nStep 2: Therefore P(Odd) = 3/6 = 1/2.\nStep 3: The same probability applies to the second roll.\nStep 4: The rolls are independent.\nStep 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4.","steps":["Step 1: Odd outcomes are 1, 3 and 5.","Step 2: Therefore P(Odd) = 3/6 = 1/2.","Step 3: The same probability applies to the second roll.","Step 4: The rolls are independent.","Step 5: Therefore P(Odd and Odd) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 1),
  (932, 279, 'A fair coin is tossed and a fair die is rolled. Find the probability of Tail and an even number.', 'text', 1, 'P(Tail) = 1/2 and P(Even) = 3/6.', '{"why":"The independent probabilities are multiplied.","sol":"Step 1: P(Tail) = 1/2.\nStep 2: The even die outcomes are 2, 4 and 6.\nStep 3: Therefore P(Even) = 3/6 = 1/2.\nStep 4: The coin and die experiments are independent.\nStep 5: Therefore P(Tail and Even) = 1/2 × 1/2.\nStep 6: The answer is 1/4.","steps":["Step 1: P(Tail) = 1/2.","Step 2: The even die outcomes are 2, 4 and 6.","Step 3: Therefore P(Even) = 3/6 = 1/2.","Step 4: The coin and die experiments are independent.","Step 5: Therefore P(Tail and Even) = 1/2 × 1/2.","Step 6: The answer is 1/4."],"options":[],"conceptId":"math_probability_multiplication_law_with_independent_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Multiplication Law with Independent Events"}', 2),
  (933, 280, 'A fair die is rolled. Find the probability of getting 1 or 3. Should you add or multiply?', 'text', 1, 'Can 1 and 3 occur on the same roll?', '{"why":"The events are mutually exclusive.","sol":"Step 1: A single die roll gives one number.\nStep 2: It cannot give both 1 and 3.\nStep 3: Therefore the events are mutually exclusive.\nStep 4: For mutually exclusive events asking for ''or'', we add.\nStep 5: P(1 or 3) = 1/6 + 1/6 = 1/3.","steps":["Step 1: A single die roll gives one number.","Step 2: It cannot give both 1 and 3.","Step 3: Therefore the events are mutually exclusive.","Step 4: For mutually exclusive events asking for ''or'', we add.","Step 5: P(1 or 3) = 1/6 + 1/6 = 1/3."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 0),
  (934, 280, 'A fair coin is tossed twice. Find the probability of getting Head on both tosses. Should you add or multiply?', 'text', 1, 'Both events must happen, and the tosses are independent.', '{"why":"Both independent events must occur.","sol":"Step 1: We need Head on the first toss and Head on the second toss.\nStep 2: The two tosses are independent.\nStep 3: For independent events asking for both events, we multiply.\nStep 4: P(H and H) = 1/2 × 1/2 = 1/4.","steps":["Step 1: We need Head on the first toss and Head on the second toss.","Step 2: The two tosses are independent.","Step 3: For independent events asking for both events, we multiply.","Step 4: P(H and H) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 1),
  (935, 280, 'A fair die is rolled twice. Find the probability of getting 6 on both rolls. Should you add or multiply?', 'text', 1, 'Both rolls must produce 6.', '{"why":"The two independent events must both happen.","sol":"Step 1: P(6 on the first roll) = 1/6.\nStep 2: P(6 on the second roll) = 1/6.\nStep 3: The two rolls are independent.\nStep 4: Therefore we multiply.\nStep 5: P(6 and 6) = 1/6 × 1/6 = 1/36.","steps":["Step 1: P(6 on the first roll) = 1/6.","Step 2: P(6 on the second roll) = 1/6.","Step 3: The two rolls are independent.","Step 4: Therefore we multiply.","Step 5: P(6 and 6) = 1/6 × 1/6 = 1/36."],"options":[],"conceptId":"math_probability_choosing_addition_or_multiplication","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Choosing Addition or Multiplication"}', 2),
  (936, 281, 'A coin is tossed twice. How many complete paths are possible?', 'text', 1, 'List HH, HT, TH and TT.', '{"why":"A complete path contains the result of both tosses.","sol":"Step 1: The first toss has 2 possible results: H or T.\nStep 2: Each first result can be followed by H or T.\nStep 3: The complete paths are HH, HT, TH and TT.\nStep 4: Therefore there are 4 complete paths.","steps":["Step 1: The first toss has 2 possible results: H or T.","Step 2: Each first result can be followed by H or T.","Step 3: The complete paths are HH, HT, TH and TT.","Step 4: Therefore there are 4 complete paths."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 0),
  (937, 281, 'A die is rolled twice. How many complete paths are possible?', 'text', 1, 'There are 6 choices at each stage.', '{"why":"Every first-roll result can be paired with every second-roll result.","sol":"Step 1: The first roll has 6 possible results.\nStep 2: For each first result, the second roll has 6 possible results.\nStep 3: Number of complete paths = 6 × 6.\nStep 4: 6 × 6 = 36.","steps":["Step 1: The first roll has 6 possible results.","Step 2: For each first result, the second roll has 6 possible results.","Step 3: Number of complete paths = 6 × 6.","Step 4: 6 × 6 = 36."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 1),
  (938, 281, 'For two coin tosses, is HT a branch or a complete path?', 'text', 1, 'HT contains results from both stages.', '{"why":"A complete path contains an outcome from every stage.","sol":"Step 1: The first letter H gives the first-stage result.\nStep 2: The second letter T gives the second-stage result.\nStep 3: Therefore HT describes the entire experiment.","steps":["Step 1: The first letter H gives the first-stage result.","Step 2: The second letter T gives the second-stage result.","Step 3: Therefore HT describes the entire experiment."],"options":[],"conceptId":"math_probability_reading_a_probability_tree_diagram","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Reading a Probability Tree Diagram"}', 2),
  (939, 282, 'A coin is tossed twice. How many branches leave the first stage?', 'text', 1, 'What can one coin toss produce?', '{"why":"The first toss has exactly two possible outcomes.","sol":"Step 1: One coin toss can produce Head or Tail.\nStep 2: Therefore the first stage has two possible results.\nStep 3: Each possible result needs one branch.","steps":["Step 1: One coin toss can produce Head or Tail.","Step 2: Therefore the first stage has two possible results.","Step 3: Each possible result needs one branch."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 0),
  (940, 282, 'A die is rolled and then a coin is tossed. How many complete paths are possible?', 'text', 1, 'Multiply the number of choices at each stage.', '{"why":"Every one of the 6 die outcomes can be paired with either H or T.","sol":"Step 1: The die has 6 possible results.\nStep 2: The coin has 2 possible results.\nStep 3: Each die result can be followed by either coin result.\nStep 4: 6 × 2 = 12.","steps":["Step 1: The die has 6 possible results.","Step 2: The coin has 2 possible results.","Step 3: Each die result can be followed by either coin result.","Step 4: 6 × 2 = 12."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 1),
  (941, 282, 'A spinner has R, B and G and is spun twice. List all paths beginning with B.', 'text', 1, 'After B, the second result can still be R, B or G.', '{"why":"Each possible second-stage result creates one path from B.","sol":"Step 1: The first result is fixed as B.\nStep 2: The second result can be R, B or G.\nStep 3: Therefore the paths are BR, BB and BG.","steps":["Step 1: The first result is fixed as B.","Step 2: The second result can be R, B or G.","Step 3: Therefore the paths are BR, BB and BG."],"options":[],"conceptId":"math_probability_building_a_two_stage_probability_tree","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Building a Two-Stage Probability Tree"}', 2),
  (942, 283, 'A fair die is rolled. What probability should be written on the branch for getting 4?', 'text', 1, 'There are 6 equally likely die outcomes.', '{"why":"One of the six equally likely outcomes is 4.","sol":"Step 1: A fair die has 6 equally likely outcomes.\nStep 2: Only one outcome is 4.\nStep 3: Therefore P(4) = 1/6.","steps":["Step 1: A fair die has 6 equally likely outcomes.","Step 2: Only one outcome is 4.","Step 3: Therefore P(4) = 1/6."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 0),
  (943, 283, 'A bag has 4 red balls and 6 blue balls. Find P(R).', 'text', 1, 'First find the total number of balls.', '{"why":"Probability equals favourable outcomes divided by total outcomes.","sol":"Step 1: Total balls = 4 + 6 = 10.\nStep 2: There are 4 red balls.\nStep 3: P(R) = 4/10.\nStep 4: Simplify 4/10 to 2/5.","steps":["Step 1: Total balls = 4 + 6 = 10.","Step 2: There are 4 red balls.","Step 3: P(R) = 4/10.","Step 4: Simplify 4/10 to 2/5."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 1),
  (944, 283, 'A box has 2 green, 3 yellow and 5 blue counters. Check the branch probabilities.', 'text', 1, 'Calculate each probability and add them.', '{"why":"All possible first-stage outcomes must account for the whole probability.","sol":"Step 1: Total = 2 + 3 + 5 = 10.\nStep 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.\nStep 3: Add them: 2/10 + 3/10 + 5/10.\nStep 4: The result is 10/10 = 1.","steps":["Step 1: Total = 2 + 3 + 5 = 10.","Step 2: P(G) = 2/10, P(Y) = 3/10, P(B) = 5/10.","Step 3: Add them: 2/10 + 3/10 + 5/10.","Step 4: The result is 10/10 = 1."],"options":[],"conceptId":"math_probability_probabilities_on_tree_branches","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probabilities on Tree Branches"}', 2),
  (945, 284, 'A fair coin is tossed twice. Find P(HH).', 'text', 1, 'Follow H on the first stage and H on the second stage.', '{"why":"Both heads must occur along the same complete path.","sol":"Step 1: P(H on first toss) = 1/2.\nStep 2: P(H on second toss) = 1/2.\nStep 3: Multiply along the path.\nStep 4: P(HH) = 1/2 × 1/2 = 1/4.","steps":["Step 1: P(H on first toss) = 1/2.","Step 2: P(H on second toss) = 1/2.","Step 3: Multiply along the path.","Step 4: P(HH) = 1/2 × 1/2 = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 0),
  (946, 284, 'A fair coin is tossed twice. Find P(HT).', 'text', 1, 'Multiply the probability of H by the probability of T.', '{"why":"HT is one complete path through the two-stage experiment.","sol":"Step 1: P(H) = 1/2.\nStep 2: P(T) = 1/2.\nStep 3: P(HT) = 1/2 × 1/2.\nStep 4: P(HT) = 1/4.","steps":["Step 1: P(H) = 1/2.","Step 2: P(T) = 1/2.","Step 3: P(HT) = 1/2 × 1/2.","Step 4: P(HT) = 1/4."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 1),
  (947, 284, 'A fair die is rolled and then a fair coin is tossed. Find P(6H).', 'text', 1, 'P(6) = 1/6 and P(H) = 1/2.', '{"why":"The path requires both a 6 and then a Head.","sol":"Step 1: P(6) = 1/6.\nStep 2: P(H) = 1/2.\nStep 3: Multiply along the complete path.\nStep 4: P(6H) = 1/6 × 1/2 = 1/12.","steps":["Step 1: P(6) = 1/6.","Step 2: P(H) = 1/2.","Step 3: Multiply along the complete path.","Step 4: P(6H) = 1/6 × 1/2 = 1/12."],"options":[],"conceptId":"math_probability_probability_along_a_complete_path","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Probability Along a Complete Path"}', 2),
  (948, 285, 'A bag has 3 red and 2 blue balls. A ball is replaced after the first draw. Find P(RR).', 'text', 1, 'Replacement means there are still 3 red out of 5.', '{"why":"Replacement restores the original contents before the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.\nStep 3: Second P(R) = 3/5.\nStep 4: P(RR) = 3/5 × 3/5 = 9/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The red ball is replaced, so the bag returns to 3 red and 2 blue.","Step 3: Second P(R) = 3/5.","Step 4: P(RR) = 3/5 × 3/5 = 9/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 0),
  (949, 285, 'Using the same bag with replacement, find P(RB).', 'text', 1, 'Both stages have the original probabilities.', '{"why":"The replacement means 2 blue balls are still available for the second draw.","sol":"Step 1: First P(R) = 3/5.\nStep 2: The ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(RB) = 3/5 × 2/5 = 6/25.","steps":["Step 1: First P(R) = 3/5.","Step 2: The ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(RB) = 3/5 × 2/5 = 6/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 1),
  (950, 285, 'With replacement, what is P(BB) for a bag with 3 red and 2 blue balls?', 'text', 1, 'P(B) is 2/5 on both stages.', '{"why":"The number of blue balls returns to 2 before the second selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: The selected blue ball is replaced.\nStep 3: Second P(B) = 2/5.\nStep 4: P(BB) = 2/5 × 2/5 = 4/25.","steps":["Step 1: First P(B) = 2/5.","Step 2: The selected blue ball is replaced.","Step 3: Second P(B) = 2/5.","Step 4: P(BB) = 2/5 × 2/5 = 4/25."],"options":[],"conceptId":"math_probability_tree_diagrams_with_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams With Replacement"}', 2),
  (951, 286, 'A bag has 3 red and 2 blue balls. A red ball is removed without replacement. What is P(R) on the second draw?', 'text', 1, 'One red has already been removed.', '{"why":"Without replacement, the first red is no longer available.","sol":"Step 1: Initially there are 3 red and 2 blue, giving 5 balls.\nStep 2: One red is removed.\nStep 3: Red remaining = 3 − 1 = 2.\nStep 4: Total remaining = 5 − 1 = 4.\nStep 5: Therefore P(R) = 2/4 = 1/2.","steps":["Step 1: Initially there are 3 red and 2 blue, giving 5 balls.","Step 2: One red is removed.","Step 3: Red remaining = 3 − 1 = 2.","Step 4: Total remaining = 5 − 1 = 4.","Step 5: Therefore P(R) = 2/4 = 1/2."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 0),
  (952, 286, 'A bag has 3 red and 2 blue balls. Find P(RR) without replacement.', 'text', 1, 'Use 3/5 first, then 2/4.', '{"why":"The number of red balls falls from 3 to 2 after the first red is removed.","sol":"Step 1: First P(R) = 3/5.\nStep 2: After removing red, 2 red remain out of 4 balls.\nStep 3: Second P(R) = 2/4.\nStep 4: P(RR) = 3/5 × 2/4.\nStep 5: P(RR) = 6/20 = 3/10.","steps":["Step 1: First P(R) = 3/5.","Step 2: After removing red, 2 red remain out of 4 balls.","Step 3: Second P(R) = 2/4.","Step 4: P(RR) = 3/5 × 2/4.","Step 5: P(RR) = 6/20 = 3/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 1),
  (953, 286, 'A bag has 3 red and 2 blue balls. Find P(BB) without replacement.', 'text', 1, 'After removing the first blue, only 1 blue remains.', '{"why":"Without replacement, one blue ball disappears after the first blue selection.","sol":"Step 1: First P(B) = 2/5.\nStep 2: After removing blue, 1 blue remains out of 4 balls.\nStep 3: Second P(B) = 1/4.\nStep 4: P(BB) = 2/5 × 1/4.\nStep 5: P(BB) = 2/20 = 1/10.","steps":["Step 1: First P(B) = 2/5.","Step 2: After removing blue, 1 blue remains out of 4 balls.","Step 3: Second P(B) = 1/4.","Step 4: P(BB) = 2/5 × 1/4.","Step 5: P(BB) = 2/20 = 1/10."],"options":[],"conceptId":"math_probability_tree_diagrams_without_replacement","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Tree Diagrams Without Replacement"}', 2),
  (954, 287, 'How many rows are in A = [[4,7,2],[1,5,9]]?', 'text', 1, 'Count the horizontal lines, not the individual numbers.', '{"why":"Each horizontal line of entries forms one row.","sol":"Step 1: The first row is [4,7,2].\nStep 2: The second row is [1,5,9].\nStep 3: There are 2 horizontal rows.","steps":["Step 1: The first row is [4,7,2].","Step 2: The second row is [1,5,9].","Step 3: There are 2 horizontal rows."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 0),
  (955, 287, 'How many columns are in B = [[3,8],[1,6],[5,9]]?', 'text', 1, 'Count the vertical positions from left to right.', '{"why":"Entries directly above and below one another occupy the same column.","sol":"Step 1: The first column contains 3, 1 and 5.\nStep 2: The second column contains 8, 6 and 9.\nStep 3: There are 2 vertical columns.","steps":["Step 1: The first column contains 3, 1 and 5.","Step 2: The second column contains 8, 6 and 9.","Step 3: There are 2 vertical columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 1),
  (956, 287, 'A = [[2,4,6,8],[1,3,5,7]]. State the number of rows and columns.', 'text', 1, 'Count horizontal lines first, then entries across a row.', '{"why":"Rows are counted horizontally and columns vertically.","sol":"Step 1: There are 2 horizontal lines, so there are 2 rows.\nStep 2: Each row has 4 entries.\nStep 3: The matrix therefore has 4 columns.","steps":["Step 1: There are 2 horizontal lines, so there are 2 rows.","Step 2: Each row has 4 entries.","Step 3: The matrix therefore has 4 columns."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 2),
  (957, 287, 'Which is a row: [2,5,8] or [[2],[5],[8]]?', 'text', 1, 'A row is arranged horizontally.', '{"why":"A row is a horizontal arrangement of entries.","sol":"Step 1: [2,5,8] places the entries side by side.\nStep 2: The entries in [[2],[5],[8]] are arranged vertically.\nStep 3: Therefore [2,5,8] is a row.","steps":["Step 1: [2,5,8] places the entries side by side.","Step 2: The entries in [[2],[5],[8]] are arranged vertically.","Step 3: Therefore [2,5,8] is a row."],"options":[],"conceptId":"math_matrices_introduction_to_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Introduction to Matrices"}', 3),
  (958, 288, 'Find the order of A = [[4,7,2],[1,5,9]].', 'text', 1, 'Count the rows first and the columns second.', '{"why":"The order of a matrix is written as rows × columns.","sol":"Step 1: There are 2 horizontal rows.\nStep 2: There are 3 entries across each row, so there are 3 columns.\nStep 3: Write rows first: 2 × 3.","steps":["Step 1: There are 2 horizontal rows.","Step 2: There are 3 entries across each row, so there are 3 columns.","Step 3: Write rows first: 2 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 0),
  (959, 288, 'Find the order of B = [[1,2],[3,4],[5,6],[7,8]].', 'text', 1, 'Count the horizontal lines before the vertical positions.', '{"why":"The first number in the order always gives the number of rows.","sol":"Step 1: There are 4 horizontal rows.\nStep 2: There are 2 columns.\nStep 3: Write the row count first: 4 × 2.","steps":["Step 1: There are 4 horizontal rows.","Step 2: There are 2 columns.","Step 3: Write the row count first: 4 × 2."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 1),
  (960, 288, 'A matrix has 5 rows and 3 columns. State its order.', 'text', 1, 'Do not reverse the two numbers.', '{"why":"Rows are written first and columns second.","sol":"Step 1: Rows = 5.\nStep 2: Columns = 3.\nStep 3: Order = 5 × 3.","steps":["Step 1: Rows = 5.","Step 2: Columns = 3.","Step 3: Order = 5 × 3."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 2),
  (961, 288, 'How many entries are in a matrix of order 4 × 3?', 'text', 1, 'Each of the 4 rows contains 3 entries.', '{"why":"The total number of entries is the number of rows multiplied by the number of columns.","sol":"Step 1: There are 4 rows.\nStep 2: Each row contains 3 entries.\nStep 3: Total entries = 3 + 3 + 3 + 3 = 12.\nStep 4: Equivalently, 4 × 3 = 12.","steps":["Step 1: There are 4 rows.","Step 2: Each row contains 3 entries.","Step 3: Total entries = 3 + 3 + 3 + 3 = 12.","Step 4: Equivalently, 4 × 3 = 12."],"options":[],"conceptId":"math_matrices_order_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Order of a Matrix"}', 3),
  (962, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₂₃.', 'text', 1, 'Select row 2 first, then the third entry in that row.', '{"why":"The subscripts mean row 2, column 3.","sol":"Step 1: Row 2 is [9,5,6].\nStep 2: The first entry is 9, the second is 5 and the third is 6.\nStep 3: Therefore a₂₃ = 6.","steps":["Step 1: Row 2 is [9,5,6].","Step 2: The first entry is 9, the second is 5 and the third is 6.","Step 3: Therefore a₂₃ = 6."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 0),
  (963, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₃₁.', 'text', 1, 'Go to the third row and choose its first entry.', '{"why":"The first subscript identifies row 3; the second identifies column 1.","sol":"Step 1: Row 3 is [1,8,3].\nStep 2: Column 1 is the first entry in that row.\nStep 3: The first entry is 1.","steps":["Step 1: Row 3 is [1,8,3].","Step 2: Column 1 is the first entry in that row.","Step 3: The first entry is 1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 1),
  (964, 289, 'Given A = [[4,7,2],[9,5,6],[1,8,3]], find a₁₂.', 'text', 1, 'Select row 1 and then count to column 2.', '{"why":"a₁₂ refers to the entry in row 1, column 2.","sol":"Step 1: Row 1 is [4,7,2].\nStep 2: The second entry in row 1 is 7.\nStep 3: Therefore a₁₂ = 7.","steps":["Step 1: Row 1 is [4,7,2].","Step 2: The second entry in row 1 is 7.","Step 3: Therefore a₁₂ = 7."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 2),
  (965, 289, 'Given B = [[2,-1,5],[4,3,7]], find b₁₂.', 'text', 1, 'Do not drop the negative sign from an entry.', '{"why":"The element is -1, and its negative sign is part of its value.","sol":"Step 1: Row 1 is [2,-1,5].\nStep 2: Column 2 selects the second entry.\nStep 3: The second entry is -1.","steps":["Step 1: Row 1 is [2,-1,5].","Step 2: Column 2 selects the second entry.","Step 3: The second entry is -1."],"options":[],"conceptId":"math_matrices_elements_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Elements of a Matrix"}', 3),
  (966, 290, 'What type of matrix is A = [[3,5,7]]?', 'text', 1, 'Count the rows in the entire matrix.', '{"why":"A row matrix has exactly one row.","sol":"Step 1: The entries 3, 5 and 7 are on one horizontal line.\nStep 2: There is exactly 1 row.\nStep 3: Therefore A is a row matrix.","steps":["Step 1: The entries 3, 5 and 7 are on one horizontal line.","Step 2: There is exactly 1 row.","Step 3: Therefore A is a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 0),
  (967, 290, 'Find the order of B = [[2,-4,6,8]].', 'text', 1, 'Count rows first and entries across second.', '{"why":"The order is the number of rows followed by the number of columns.","sol":"Step 1: There is 1 horizontal row.\nStep 2: There are 4 entries across the row.\nStep 3: Order = 1 × 4.","steps":["Step 1: There is 1 horizontal row.","Step 2: There are 4 entries across the row.","Step 3: Order = 1 × 4."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 1),
  (968, 290, 'Is C = [[1,2],[3,4]] a row matrix?', 'text', 1, 'A row matrix must have exactly one row.', '{"why":"A matrix with two rows does not meet the definition of a row matrix.","sol":"Step 1: The first horizontal line is [1,2].\nStep 2: The second horizontal line is [3,4].\nStep 3: There are 2 rows, not 1.\nStep 4: Therefore C is not a row matrix.","steps":["Step 1: The first horizontal line is [1,2].","Step 2: The second horizontal line is [3,4].","Step 3: There are 2 rows, not 1.","Step 4: Therefore C is not a row matrix."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 2),
  (969, 290, 'Write a row matrix containing 6, -3 and 10.', 'text', 1, 'Place all three entries on one horizontal line.', '{"why":"All entries are arranged in one horizontal row.","sol":"Step 1: A row matrix has one row.\nStep 2: Place 6, -3 and 10 side by side.\nStep 3: The resulting matrix is [6,-3,10].","steps":["Step 1: A row matrix has one row.","Step 2: Place 6, -3 and 10 side by side.","Step 3: The resulting matrix is [6,-3,10]."],"options":[],"conceptId":"math_matrices_row_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Row Matrix"}', 3),
  (970, 291, 'What type of matrix is A = [[3],[5],[7]]?', 'text', 1, 'Count the vertical columns.', '{"why":"A column matrix has exactly one column.","sol":"Step 1: The entries 3, 5 and 7 are arranged vertically.\nStep 2: There is exactly 1 column.\nStep 3: Therefore A is a column matrix.","steps":["Step 1: The entries 3, 5 and 7 are arranged vertically.","Step 2: There is exactly 1 column.","Step 3: Therefore A is a column matrix."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 0),
  (971, 291, 'Find the order of B = [[2],[-4],[6],[8]].', 'text', 1, 'Count the horizontal rows first.', '{"why":"The order records rows first and columns second.","sol":"Step 1: There are 4 horizontal positions, so there are 4 rows.\nStep 2: There is only 1 vertical column.\nStep 3: Order = 4 × 1.","steps":["Step 1: There are 4 horizontal positions, so there are 4 rows.","Step 2: There is only 1 vertical column.","Step 3: Order = 4 × 1."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 1),
  (972, 291, 'Is C = [[1,2],[3,4],[5,6]] a column matrix?', 'text', 1, 'Count the columns, not the rows.', '{"why":"C has two columns, so it is not a column matrix.","sol":"Step 1: The first column contains 1, 3 and 5.\nStep 2: The second column contains 2, 4 and 6.\nStep 3: There are 2 columns.\nStep 4: A column matrix must have exactly 1 column.","steps":["Step 1: The first column contains 1, 3 and 5.","Step 2: The second column contains 2, 4 and 6.","Step 3: There are 2 columns.","Step 4: A column matrix must have exactly 1 column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 2),
  (973, 291, 'Write a column matrix containing 7, -1 and 5 in that order.', 'text', 1, 'Put each entry on a new line, keeping the given order.', '{"why":"The entries are arranged vertically in one column.","sol":"Step 1: Place 7 in the first row.\nStep 2: Place -1 in the second row.\nStep 3: Place 5 in the third row.\nStep 4: Use one vertical column.","steps":["Step 1: Place 7 in the first row.","Step 2: Place -1 in the second row.","Step 3: Place 5 in the third row.","Step 4: Use one vertical column."],"options":[],"conceptId":"math_matrices_column_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Column Matrix"}', 3),
  (974, 292, 'Determine whether A = [[4,7],[2,5]] is a square matrix.', 'text', 1, 'Compare the number of rows with the number of columns.', '{"why":"A square matrix has an equal number of rows and columns.","sol":"Step 1: A has 2 rows.\nStep 2: A has 2 columns.\nStep 3: Since the number of rows equals the number of columns, A is square.","steps":["Step 1: A has 2 rows.","Step 2: A has 2 columns.","Step 3: Since the number of rows equals the number of columns, A is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 0),
  (975, 292, 'Determine whether B = [[3,8,1],[5,2,7]] is a square matrix.', 'text', 1, 'Count both dimensions.', '{"why":"The matrix has 2 rows but 3 columns.","sol":"Step 1: B has 2 rows.\nStep 2: B has 3 columns.\nStep 3: 2 is not equal to 3.\nStep 4: Therefore B is not square.","steps":["Step 1: B has 2 rows.","Step 2: B has 3 columns.","Step 3: 2 is not equal to 3.","Step 4: Therefore B is not square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 1),
  (976, 292, 'A matrix has order 4 × 4. Is it a square matrix?', 'text', 1, 'For a square matrix, the two dimensions must be equal.', '{"why":"A 4 × 4 matrix has the same number of rows and columns.","sol":"Step 1: The matrix has 4 rows.\nStep 2: The matrix has 4 columns.\nStep 3: 4 equals 4.\nStep 4: Therefore the matrix is square.","steps":["Step 1: The matrix has 4 rows.","Step 2: The matrix has 4 columns.","Step 3: 4 equals 4.","Step 4: Therefore the matrix is square."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 2),
  (977, 292, 'A student says [[1,2,3],[4,5,6]] is square because it contains 6 numbers arranged evenly. Is the student correct?', 'text', 1, 'The number of entries is not the test for being square.', '{"why":"Being square depends on equal rows and columns, not on the total number of entries.","sol":"Step 1: The matrix has 2 rows.\nStep 2: It has 3 columns.\nStep 3: A square matrix requires the number of rows to equal the number of columns.\nStep 4: 2 is not equal to 3.\nStep 5: Therefore the student is incorrect.","steps":["Step 1: The matrix has 2 rows.","Step 2: It has 3 columns.","Step 3: A square matrix requires the number of rows to equal the number of columns.","Step 4: 2 is not equal to 3.","Step 5: Therefore the student is incorrect."],"options":[],"conceptId":"math_matrices_square_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Square Matrix"}', 3),
  (978, 293, 'Is [[0,0],[0,0]] a zero matrix?', 'text', 1, 'Check every entry.', '{"why":"Every element of the matrix is zero.","sol":"Step 1: The first row contains only zeros.\nStep 2: The second row contains only zeros.\nStep 3: Every element is zero.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: The first row contains only zeros.","Step 2: The second row contains only zeros.","Step 3: Every element is zero.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 0),
  (979, 293, 'Is [[0,0,0],[0,0,0]] a zero matrix?', 'text', 1, 'The matrix does not have to be square.', '{"why":"A zero matrix can be rectangular; all that matters is that every entry is zero.","sol":"Step 1: There are 2 rows and 3 columns.\nStep 2: Every entry is zero.\nStep 3: The dimensions do not affect whether it is a zero matrix.\nStep 4: Therefore it is a zero matrix.","steps":["Step 1: There are 2 rows and 3 columns.","Step 2: Every entry is zero.","Step 3: The dimensions do not affect whether it is a zero matrix.","Step 4: Therefore it is a zero matrix."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 1),
  (980, 293, 'Is [[0,0],[0,4]] a zero matrix?', 'text', 1, 'Look carefully at every entry.', '{"why":"A single non-zero element means the matrix is not a zero matrix.","sol":"Step 1: Three entries are zero.\nStep 2: The bottom-right entry is 4.\nStep 3: 4 is not zero.\nStep 4: Therefore not every entry is zero.","steps":["Step 1: Three entries are zero.","Step 2: The bottom-right entry is 4.","Step 3: 4 is not zero.","Step 4: Therefore not every entry is zero."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 2),
  (981, 293, 'Write a zero matrix of order 2 × 3.', 'text', 1, 'Use 2 rows, 3 columns, and put zero in every position.', '{"why":"It has the required dimensions and every element is zero.","sol":"Step 1: Create 2 horizontal rows.\nStep 2: Put 3 entries in each row.\nStep 3: Make every entry zero.\nStep 4: The matrix is [[0,0,0],[0,0,0]].","steps":["Step 1: Create 2 horizontal rows.","Step 2: Put 3 entries in each row.","Step 3: Make every entry zero.","Step 4: The matrix is [[0,0,0],[0,0,0]]."],"options":[],"conceptId":"math_matrices_zero_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Zero Matrix"}', 3),
  (982, 294, 'Is [[4,0,0],[0,7,0],[0,0,9]] a diagonal matrix?', 'text', 1, 'Check the entries outside the main diagonal.', '{"why":"Every off-diagonal entry is zero.","sol":"Step 1: The main diagonal is 4, 7, 9.\nStep 2: Every entry outside that diagonal is zero.\nStep 3: Therefore the matrix satisfies the definition of a diagonal matrix.","steps":["Step 1: The main diagonal is 4, 7, 9.","Step 2: Every entry outside that diagonal is zero.","Step 3: Therefore the matrix satisfies the definition of a diagonal matrix."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 0),
  (983, 294, 'Is [[3,0,0],[0,4,2],[0,0,7]] diagonal?', 'text', 1, 'Look at row 2, column 3.', '{"why":"The off-diagonal entry 2 violates the definition.","sol":"Step 1: The main diagonal is 3, 4, 7.\nStep 2: The entry in row 2, column 3 is 2.\nStep 3: That entry is outside the main diagonal.\nStep 4: A diagonal matrix requires it to be zero.\nStep 5: Therefore the matrix is not diagonal.","steps":["Step 1: The main diagonal is 3, 4, 7.","Step 2: The entry in row 2, column 3 is 2.","Step 3: That entry is outside the main diagonal.","Step 4: A diagonal matrix requires it to be zero.","Step 5: Therefore the matrix is not diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 1),
  (984, 294, 'Is [[5,0],[0,0]] a diagonal matrix?', 'text', 1, 'A zero is allowed on the main diagonal.', '{"why":"Diagonal entries may be zero; only off-diagonal entries must be zero.","sol":"Step 1: The main diagonal contains 5 and 0.\nStep 2: The only entry outside the main diagonal is 0.\nStep 3: Therefore all off-diagonal entries are zero.\nStep 4: The matrix is diagonal.","steps":["Step 1: The main diagonal contains 5 and 0.","Step 2: The only entry outside the main diagonal is 0.","Step 3: Therefore all off-diagonal entries are zero.","Step 4: The matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 2),
  (985, 294, 'A student says [[0,0],[0,0]] cannot be diagonal because the diagonal entries are zero. Is the student correct?', 'text', 1, 'The definition places the restriction on entries outside the diagonal.', '{"why":"A zero matrix is also a diagonal matrix because all of its off-diagonal entries are zero.","sol":"Step 1: The main diagonal contains 0 and 0.\nStep 2: Both entries outside the main diagonal are also zero.\nStep 3: There is no requirement that diagonal entries be non-zero.\nStep 4: Therefore the matrix is diagonal.","steps":["Step 1: The main diagonal contains 0 and 0.","Step 2: Both entries outside the main diagonal are also zero.","Step 3: There is no requirement that diagonal entries be non-zero.","Step 4: Therefore the matrix is diagonal."],"options":[],"conceptId":"math_matrices_diagonal_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Diagonal Matrix"}', 3),
  (986, 295, 'Is [[1,0],[0,1]] an identity matrix?', 'text', 1, 'Check the diagonal and the entries outside it.', '{"why":"It satisfies both identity-matrix conditions.","sol":"Step 1: The matrix is square: 2 rows and 2 columns.\nStep 2: The main diagonal contains 1 and 1.\nStep 3: The off-diagonal entries are both 0.\nStep 4: Therefore it is I₂.","steps":["Step 1: The matrix is square: 2 rows and 2 columns.","Step 2: The main diagonal contains 1 and 1.","Step 3: The off-diagonal entries are both 0.","Step 4: Therefore it is I₂."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 0),
  (987, 295, 'Is [[1,0],[0,2]] an identity matrix?', 'text', 1, 'Check every entry on the main diagonal.', '{"why":"The diagonal must contain only 1s.","sol":"Step 1: The main diagonal contains 1 and 2.\nStep 2: An identity matrix requires every diagonal entry to be 1.\nStep 3: The second diagonal entry is 2.\nStep 4: Therefore it is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 2.","Step 2: An identity matrix requires every diagonal entry to be 1.","Step 3: The second diagonal entry is 2.","Step 4: Therefore it is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 1),
  (988, 295, 'Is [[1,0],[1,1]] an identity matrix?', 'text', 1, 'The diagonal is correct, but check outside the diagonal.', '{"why":"Every off-diagonal entry must be zero.","sol":"Step 1: The main diagonal contains 1 and 1.\nStep 2: The bottom-left entry is outside the main diagonal.\nStep 3: That entry is 1, but it must be 0.\nStep 4: Therefore the matrix is not an identity matrix.","steps":["Step 1: The main diagonal contains 1 and 1.","Step 2: The bottom-left entry is outside the main diagonal.","Step 3: That entry is 1, but it must be 0.","Step 4: Therefore the matrix is not an identity matrix."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 2),
  (989, 295, 'Which matrix is I₃: A = [[1,0,0],[0,1,0],[0,0,1]] or B = [[1,0,0],[0,2,0],[0,0,1]]?', 'text', 1, 'The diagonal of an identity matrix must contain only 1s.', '{"why":"A has 1s on the entire main diagonal and zeros everywhere else.","sol":"Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.\nStep 2: For B, the main diagonal is 1, 2, 1.\nStep 3: The 2 in B violates the identity-matrix condition.\nStep 4: Therefore A is I₃.","steps":["Step 1: For A, the main diagonal is 1, 1, 1 and all other entries are zero.","Step 2: For B, the main diagonal is 1, 2, 1.","Step 3: The 2 in B violates the identity-matrix condition.","Step 4: Therefore A is I₃."],"options":[],"conceptId":"math_matrices_identity_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Identity Matrix"}', 3),
  (990, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,9]] equal?', 'text', 1, 'First compare their orders, then compare corresponding entries.', '{"why":"The matrices have the same order and all corresponding elements are equal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare 2 with 2: equal.\nStep 3: Compare 5 with 5: equal.\nStep 4: Compare 7 with 7: equal.\nStep 5: Compare 9 with 9: equal.\nStep 6: All corresponding elements are equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare 2 with 2: equal.","Step 3: Compare 5 with 5: equal.","Step 4: Compare 7 with 7: equal.","Step 5: Compare 9 with 9: equal.","Step 6: All corresponding elements are equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 0),
  (991, 296, 'Are A = [[2,5],[7,9]] and B = [[2,5],[7,4]] equal?', 'text', 1, 'Look for even one corresponding pair that is different.', '{"why":"All corresponding elements must be equal; one mismatch makes the matrices unequal.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: The first three corresponding entries agree.\nStep 3: Compare the bottom-right entries: 9 and 4.\nStep 4: Since 9 is not equal to 4, the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: The first three corresponding entries agree.","Step 3: Compare the bottom-right entries: 9 and 4.","Step 4: Since 9 is not equal to 4, the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 1),
  (992, 296, 'If [[x,4],[2,9]] = [[7,4],[2,9]], find x.', 'text', 1, 'Equal matrices have equal corresponding elements.', '{"why":"Corresponding elements of equal matrices must have the same value.","sol":"Step 1: Compare the top-left entries.\nStep 2: The first matrix has x there.\nStep 3: The second matrix has 7 there.\nStep 4: Therefore x = 7.\nStep 5: The remaining corresponding entries already agree.","steps":["Step 1: Compare the top-left entries.","Step 2: The first matrix has x there.","Step 3: The second matrix has 7 there.","Step 4: Therefore x = 7.","Step 5: The remaining corresponding entries already agree."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 2),
  (993, 296, 'Can a 2 × 3 matrix be equal to a 3 × 2 matrix?', 'text', 1, 'Compare the orders before looking at the entries.', '{"why":"Equal matrices must have exactly the same number of rows and columns.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second matrix has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Matrices with different orders cannot be equal.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second matrix has order 3 × 2.","Step 3: Their orders are different.","Step 4: Matrices with different orders cannot be equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 3),
  (994, 296, 'A student says [[1,2],[3,4]] and [[2,1],[4,3]] are equal because they contain the same four numbers. Is the student correct?', 'text', 1, 'Equality depends on corresponding positions, not merely the numbers present.', '{"why":"The same numbers must also occur in the same corresponding positions.","sol":"Step 1: Both matrices have order 2 × 2.\nStep 2: Compare the top-left entries: 1 and 2.\nStep 3: They are different.\nStep 4: Therefore the matrices are not equal.","steps":["Step 1: Both matrices have order 2 × 2.","Step 2: Compare the top-left entries: 1 and 2.","Step 3: They are different.","Step 4: Therefore the matrices are not equal."],"options":[],"conceptId":"math_matrices_equality_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Equality of Matrices"}', 4),
  (995, 297, 'Find [[2,5],[7,3]] + [[4,1],[6,8]].', 'text', 1, 'Add entries occupying the same position.', '{"why":"Matrix addition is performed element-by-element at corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 1 = 6.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 3 + 8 = 11.\nStep 5: Place each result in its original position.","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 1 = 6.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 3 + 8 = 11.","Step 5: Place each result in its original position."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 0),
  (996, 297, 'Find [[5,-3],[4,6]] + [[-2,7],[8,-1]].', 'text', 1, 'Treat each negative number as part of the calculation.', '{"why":"Corresponding elements are added, including their signs.","sol":"Step 1: 5 + (-2) = 3.\nStep 2: -3 + 7 = 4.\nStep 3: 4 + 8 = 12.\nStep 4: 6 + (-1) = 5.\nStep 5: Therefore the result is [[3,4],[12,5]].","steps":["Step 1: 5 + (-2) = 3.","Step 2: -3 + 7 = 4.","Step 3: 4 + 8 = 12.","Step 4: 6 + (-1) = 5.","Step 5: Therefore the result is [[3,4],[12,5]]."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 1),
  (997, 297, 'Can a 2 × 3 matrix be added to a 3 × 2 matrix?', 'text', 1, 'Matrix addition requires the same order.', '{"why":"Matrices must have the same order before they can be added.","sol":"Step 1: The first matrix has order 2 × 3.\nStep 2: The second has order 3 × 2.\nStep 3: Their orders are different.\nStep 4: Therefore corresponding positions cannot be matched.","steps":["Step 1: The first matrix has order 2 × 3.","Step 2: The second has order 3 × 2.","Step 3: Their orders are different.","Step 4: Therefore corresponding positions cannot be matched."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 2),
  (998, 297, 'A student calculates [[1,2],[3,4]] + [[5,6],[7,8]] as [[6,8],[10,12]]. Explain whether the answer is correct.', 'text', 1, 'Check each corresponding position.', '{"why":"Every corresponding pair has been added correctly and placed in the correct position.","sol":"Step 1: Top-left: 1 + 5 = 6.\nStep 2: Top-right: 2 + 6 = 8.\nStep 3: Bottom-left: 3 + 7 = 10.\nStep 4: Bottom-right: 4 + 8 = 12.\nStep 5: Every entry is correct.","steps":["Step 1: Top-left: 1 + 5 = 6.","Step 2: Top-right: 2 + 6 = 8.","Step 3: Bottom-left: 3 + 7 = 10.","Step 4: Bottom-right: 4 + 8 = 12.","Step 5: Every entry is correct."],"options":[],"conceptId":"math_matrices_matrix_addition","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Addition"}', 3),
  (999, 298, 'Find [[9,7],[6,5]] - [[4,2],[1,3]].', 'text', 1, 'Subtract the second matrix from the first at each corresponding position.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 6 - 1 = 5.\nStep 4: 5 - 3 = 2.\nStep 5: Therefore the result is [[5,5],[5,2]].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 6 - 1 = 5.","Step 4: 5 - 3 = 2.","Step 5: Therefore the result is [[5,5],[5,2]]."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 0),
  (1000, 298, 'Find [[4,-2],[3,8]] - [[7,-5],[1,4]].', 'text', 1, 'Pay special attention to -2 - (-5).', '{"why":"Subtracting a negative number is equivalent to adding its positive value.","sol":"Step 1: 4 - 7 = -3.\nStep 2: -2 - (-5) = -2 + 5 = 3.\nStep 3: 3 - 1 = 2.\nStep 4: 8 - 4 = 4.","steps":["Step 1: 4 - 7 = -3.","Step 2: -2 - (-5) = -2 + 5 = 3.","Step 3: 3 - 1 = 2.","Step 4: 8 - 4 = 4."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 1);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1001, 298, 'Given A = [[8,5],[6,4]] and B = [[3,2],[1,7]], find A - B.', 'text', 1, 'The first matrix always supplies the number being subtracted from.', '{"why":"A - B means corresponding elements of B are subtracted from corresponding elements of A.","sol":"Step 1: 8 - 3 = 5.\nStep 2: 5 - 2 = 3.\nStep 3: 6 - 1 = 5.\nStep 4: 4 - 7 = -3.","steps":["Step 1: 8 - 3 = 5.","Step 2: 5 - 2 = 3.","Step 3: 6 - 1 = 5.","Step 4: 4 - 7 = -3."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 2),
  (1002, 298, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Compare their orders.', '{"why":"Both matrices must have the same order.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second has 2 rows and 3 columns.\nStep 3: Their orders are different.\nStep 4: Therefore subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second has 2 rows and 3 columns.","Step 3: Their orders are different.","Step 4: Therefore subtraction is not defined."],"options":[],"conceptId":"math_matrices_matrix_subtraction","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Subtraction"}', 3),
  (1003, 299, 'Find 3[[2,4],[3,5]].', 'text', 1, 'Multiply every entry by 3.', '{"why":"A scalar multiplies every element of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 3 = 9.\nStep 4: 3 × 5 = 15.\nStep 5: Keep the results in their original positions.","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 3 = 9.","Step 4: 3 × 5 = 15.","Step 5: Keep the results in their original positions."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 0),
  (1004, 299, 'Find -2[[3,-4],[5,1]].', 'text', 1, 'Apply -2 separately to each entry.', '{"why":"The negative scalar changes the sign of positive entries and must also be applied to negative entries.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × 5 = -10.\nStep 4: -2 × 1 = -2.","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × 5 = -10.","Step 4: -2 × 1 = -2."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 1),
  (1005, 299, 'If A is a 2 × 3 matrix, what is the order of 5A?', 'text', 1, 'Scalar multiplication changes values, not dimensions.', '{"why":"Scalar multiplication does not change the order of a matrix.","sol":"Step 1: A has 2 rows and 3 columns.\nStep 2: Multiplying each entry by 5 does not create or remove entries.\nStep 3: Therefore 5A still has 2 rows and 3 columns.","steps":["Step 1: A has 2 rows and 3 columns.","Step 2: Multiplying each entry by 5 does not create or remove entries.","Step 3: Therefore 5A still has 2 rows and 3 columns."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 2),
  (1006, 299, 'Find 0[[7,-2],[4,9]].', 'text', 1, 'Every number multiplied by zero becomes zero.', '{"why":"Multiplying every element by zero produces the zero matrix.","sol":"Step 1: 0 × 7 = 0.\nStep 2: 0 × (-2) = 0.\nStep 3: 0 × 4 = 0.\nStep 4: 0 × 9 = 0.\nStep 5: Therefore every element becomes zero.","steps":["Step 1: 0 × 7 = 0.","Step 2: 0 × (-2) = 0.","Step 3: 0 × 4 = 0.","Step 4: 0 × 9 = 0.","Step 5: Therefore every element becomes zero."],"options":[],"conceptId":"math_matrices_scalar_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication"}', 3),
  (1007, 300, 'Find AB where A = [[2,3],[1,5]] and B = [[4,1],[2,3]].', 'text', 1, 'For each answer entry, use a row from A and a column from B.', '{"why":"Each result entry comes from the dot product of a row of A with a column of B.","sol":"Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.\nStep 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.\nStep 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.\nStep 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.\nStep 5: Therefore AB = [[14,11],[14,16]].","steps":["Step 1: Top-left: (2×4) + (3×2) = 8 + 6 = 14.","Step 2: Top-right: (2×1) + (3×3) = 2 + 9 = 11.","Step 3: Bottom-left: (1×4) + (5×2) = 4 + 10 = 14.","Step 4: Bottom-right: (1×1) + (5×3) = 1 + 15 = 16.","Step 5: Therefore AB = [[14,11],[14,16]]."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 0),
  (1008, 300, 'Can a 2 × 3 matrix be multiplied by a 2 × 2 matrix?', 'text', 1, 'Compare the columns of the first matrix with the rows of the second.', '{"why":"For AB to exist, the number of columns in A must equal the number of rows in B.","sol":"Step 1: The first matrix has 3 columns.\nStep 2: The second matrix has 2 rows.\nStep 3: The inner dimensions are 3 and 2.\nStep 4: Since 3 is not equal to 2, multiplication is not possible.","steps":["Step 1: The first matrix has 3 columns.","Step 2: The second matrix has 2 rows.","Step 3: The inner dimensions are 3 and 2.","Step 4: Since 3 is not equal to 2, multiplication is not possible."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 1),
  (1009, 300, 'Find the top-left entry of AB if A = [[1,2,3],[4,5,6]] and B = [[2,1],[0,3],[1,2]].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"The top-left entry is the dot product of the first row of A and first column of B.","sol":"Step 1: Row 1 of A is [1,2,3].\nStep 2: Column 1 of B is [2,0,1].\nStep 3: Multiply corresponding values: (1×2), (2×0), (3×1).\nStep 4: Add: 2 + 0 + 3 = 5.","steps":["Step 1: Row 1 of A is [1,2,3].","Step 2: Column 1 of B is [2,0,1].","Step 3: Multiply corresponding values: (1×2), (2×0), (3×1).","Step 4: Add: 2 + 0 + 3 = 5."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 2),
  (1010, 300, 'A student calculates the top-left entry of [[2,3],[1,5]] × [[4,1],[2,3]] as 2 × 4 = 8. What is wrong?', 'text', 1, 'One product is not enough.', '{"why":"Matrix multiplication requires multiplying all corresponding row-column pairs and adding the products.","sol":"Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.\nStep 2: Those values are [2,3] and [4,2].\nStep 3: Calculate both products: 2×4 = 8 and 3×2 = 6.\nStep 4: Add the products: 8 + 6 = 14.\nStep 5: Therefore 8 is incomplete.","steps":["Step 1: The top-left entry requires row 1 of the first matrix and column 1 of the second.","Step 2: Those values are [2,3] and [4,2].","Step 3: Calculate both products: 2×4 = 8 and 3×2 = 6.","Step 4: Add the products: 8 + 6 = 14.","Step 5: Therefore 8 is incomplete."],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 3),
  (1011, 301, 'Find the transpose of A = [2 5 7; 1 4 6].', 'text', 1, 'Turn the first row into the first column and the second row into the second column.', '{"why":"Each row of the original matrix becomes the corresponding column of its transpose.","sol":"Step 1: The first row is 2, 5, 7.\nStep 2: Write 2, 5, 7 vertically as the first column.\nStep 3: The second row is 1, 4, 6.\nStep 4: Write 1, 4, 6 vertically as the second column.\nStep 5: Therefore Aᵀ = [2 1; 5 4; 7 6].","steps":["Step 1: The first row is 2, 5, 7.","Step 2: Write 2, 5, 7 vertically as the first column.","Step 3: The second row is 1, 4, 6.","Step 4: Write 1, 4, 6 vertically as the second column.","Step 5: Therefore Aᵀ = [2 1; 5 4; 7 6]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 0),
  (1012, 301, 'Find the transpose of B = [3 8; 5 1; 7 4].', 'text', 1, 'There are three rows, so each of the three rows becomes a column.', '{"why":"The transpose changes the orientation of every row from horizontal to vertical.","sol":"Step 1: Row 1 is 3, 8, so it becomes column 1.\nStep 2: Row 2 is 5, 1, so it becomes column 2.\nStep 3: Row 3 is 7, 4, so it becomes column 3.\nStep 4: Therefore Bᵀ = [3 5 7; 8 1 4].","steps":["Step 1: Row 1 is 3, 8, so it becomes column 1.","Step 2: Row 2 is 5, 1, so it becomes column 2.","Step 3: Row 3 is 7, 4, so it becomes column 3.","Step 4: Therefore Bᵀ = [3 5 7; 8 1 4]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 1),
  (1013, 301, 'Find the transpose of C = [-2 4; 6 -5].', 'text', 1, 'Do not change the negative signs. Only move the entries.', '{"why":"Transposition changes positions, not values or signs.","sol":"Step 1: The first row is -2, 4.\nStep 2: It becomes the first column: -2, 4.\nStep 3: The second row is 6, -5.\nStep 4: It becomes the second column: 6, -5.\nStep 5: Therefore Cᵀ = [-2 6; 4 -5].","steps":["Step 1: The first row is -2, 4.","Step 2: It becomes the first column: -2, 4.","Step 3: The second row is 6, -5.","Step 4: It becomes the second column: 6, -5.","Step 5: Therefore Cᵀ = [-2 6; 4 -5]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 2),
  (1014, 301, 'Find the transpose of D = [1 2 3; 4 5 6; 7 8 9].', 'text', 1, 'Move row 1 to column 1, row 2 to column 2, and row 3 to column 3.', '{"why":"Every row becomes the corresponding column.","sol":"Step 1: Row 1, 1 2 3, becomes column 1.\nStep 2: Row 2, 4 5 6, becomes column 2.\nStep 3: Row 3, 7 8 9, becomes column 3.\nStep 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9].","steps":["Step 1: Row 1, 1 2 3, becomes column 1.","Step 2: Row 2, 4 5 6, becomes column 2.","Step 3: Row 3, 7 8 9, becomes column 3.","Step 4: Therefore Dᵀ = [1 4 7; 2 5 8; 3 6 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 3),
  (1015, 301, 'A = [4 7; 2 9]. Which matrix is Aᵀ?', 'text', 1, 'The 4 stays in the top-left position. The 7 and 2 exchange their positions.', '{"why":"Transposition swaps the row and column position of each entry.","sol":"Step 1: The first row 4, 7 becomes the first column.\nStep 2: The second row 2, 9 becomes the second column.\nStep 3: So the transpose is [4 2; 7 9].","steps":["Step 1: The first row 4, 7 becomes the first column.","Step 2: The second row 2, 9 becomes the second column.","Step 3: So the transpose is [4 2; 7 9]."],"options":[],"conceptId":"math_matrices_transpose_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Transpose of a Matrix"}', 4),
  (1016, 302, 'Find A + B if A = [2 5; 7 1] and B = [4 3; 6 8].', 'text', 1, 'Add entries occupying the same positions.', '{"why":"Matrix addition is performed entry-by-entry using corresponding positions.","sol":"Step 1: Top-left: 2 + 4 = 6.\nStep 2: Top-right: 5 + 3 = 8.\nStep 3: Bottom-left: 7 + 6 = 13.\nStep 4: Bottom-right: 1 + 8 = 9.\nStep 5: Therefore A + B = [6 8; 13 9].","steps":["Step 1: Top-left: 2 + 4 = 6.","Step 2: Top-right: 5 + 3 = 8.","Step 3: Bottom-left: 7 + 6 = 13.","Step 4: Bottom-right: 1 + 8 = 9.","Step 5: Therefore A + B = [6 8; 13 9]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 0),
  (1017, 302, 'Find P + Q if P = [6 -3; -2 5] and Q = [-4 7; 8 -1].', 'text', 1, 'Remember that adding a negative number is ordinary integer addition.', '{"why":"Each corresponding pair of entries is added independently.","sol":"Step 1: 6 + (-4) = 2.\nStep 2: -3 + 7 = 4.\nStep 3: -2 + 8 = 6.\nStep 4: 5 + (-1) = 4.\nStep 5: Therefore P + Q = [2 4; 6 4].","steps":["Step 1: 6 + (-4) = 2.","Step 2: -3 + 7 = 4.","Step 3: -2 + 8 = 6.","Step 4: 5 + (-1) = 4.","Step 5: Therefore P + Q = [2 4; 6 4]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 1),
  (1018, 302, 'Can [1 2; 3 4] be added to [5 6 7; 8 9 10]?', 'text', 1, 'Compare the sizes of the two matrices.', '{"why":"Two matrices must have the same size before matrix addition is possible.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore corresponding positions cannot be matched throughout.\nStep 5: The matrices cannot be added.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore corresponding positions cannot be matched throughout.","Step 5: The matrices cannot be added."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 2),
  (1019, 302, 'Find X + Y if X = [1 4 7; 2 5 8] and Y = [3 2 1; 6 4 2].', 'text', 1, 'Add each position separately.', '{"why":"Corresponding entries are added while their positions remain unchanged.","sol":"Step 1: 1 + 3 = 4.\nStep 2: 4 + 2 = 6.\nStep 3: 7 + 1 = 8.\nStep 4: 2 + 6 = 8.\nStep 5: 5 + 4 = 9.\nStep 6: 8 + 2 = 10.\nStep 7: Therefore X + Y = [4 6 8; 8 9 10].","steps":["Step 1: 1 + 3 = 4.","Step 2: 4 + 2 = 6.","Step 3: 7 + 1 = 8.","Step 4: 2 + 6 = 8.","Step 5: 5 + 4 = 9.","Step 6: 8 + 2 = 10.","Step 7: Therefore X + Y = [4 6 8; 8 9 10]."],"options":[],"conceptId":"math_matrices_addition_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Addition of Matrices"}', 3),
  (1020, 303, 'Find A - B if A = [9 7; 5 3] and B = [4 2; 1 6].', 'text', 1, 'Subtract corresponding entries: A entry minus B entry.', '{"why":"Matrix subtraction is performed position by position.","sol":"Step 1: 9 - 4 = 5.\nStep 2: 7 - 2 = 5.\nStep 3: 5 - 1 = 4.\nStep 4: 3 - 6 = -3.\nStep 5: Therefore A - B = [5 5; 4 -3].","steps":["Step 1: 9 - 4 = 5.","Step 2: 7 - 2 = 5.","Step 3: 5 - 1 = 4.","Step 4: 3 - 6 = -3.","Step 5: Therefore A - B = [5 5; 4 -3]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 0),
  (1021, 303, 'Find P - Q if P = [6 -2; -4 7] and Q = [-3 5; 2 -1].', 'text', 1, 'Be especially careful when subtracting negative numbers.', '{"why":"The subtraction follows the order P minus Q at every corresponding position.","sol":"Step 1: 6 - (-3) = 9.\nStep 2: -2 - 5 = -7.\nStep 3: -4 - 2 = -6.\nStep 4: 7 - (-1) = 8.\nStep 5: Therefore P - Q = [9 -7; -6 8].","steps":["Step 1: 6 - (-3) = 9.","Step 2: -2 - 5 = -7.","Step 3: -4 - 2 = -6.","Step 4: 7 - (-1) = 8.","Step 5: Therefore P - Q = [9 -7; -6 8]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 1),
  (1022, 303, 'Using A = [8 5; 3 1] and B = [2 4; 6 7], find A - B.', 'text', 1, 'Keep A first throughout the calculation.', '{"why":"Changing the order of subtraction changes the signs of the corresponding differences.","sol":"Step 1: 8 - 2 = 6.\nStep 2: 5 - 4 = 1.\nStep 3: 3 - 6 = -3.\nStep 4: 1 - 7 = -6.\nStep 5: Therefore A - B = [6 1; -3 -6].","steps":["Step 1: 8 - 2 = 6.","Step 2: 5 - 4 = 1.","Step 3: 3 - 6 = -3.","Step 4: 1 - 7 = -6.","Step 5: Therefore A - B = [6 1; -3 -6]."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 2),
  (1023, 303, 'Can a 2 × 2 matrix be subtracted from a 2 × 3 matrix?', 'text', 1, 'Check whether the two matrices have the same size.', '{"why":"Matrices must have the same size for subtraction.","sol":"Step 1: The first matrix has 2 rows and 2 columns.\nStep 2: The second matrix has 2 rows and 3 columns.\nStep 3: Their sizes are different.\nStep 4: Therefore matrix subtraction is not defined.","steps":["Step 1: The first matrix has 2 rows and 2 columns.","Step 2: The second matrix has 2 rows and 3 columns.","Step 3: Their sizes are different.","Step 4: Therefore matrix subtraction is not defined."],"options":[],"conceptId":"math_matrices_subtraction_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Subtraction of Matrices"}', 3),
  (1024, 304, 'Find 3A if A = [2 4; 5 1].', 'text', 1, 'Multiply every entry by 3.', '{"why":"Scalar multiplication applies the scalar to every entry of the matrix.","sol":"Step 1: 3 × 2 = 6.\nStep 2: 3 × 4 = 12.\nStep 3: 3 × 5 = 15.\nStep 4: 3 × 1 = 3.\nStep 5: Therefore 3A = [6 12; 15 3].","steps":["Step 1: 3 × 2 = 6.","Step 2: 3 × 4 = 12.","Step 3: 3 × 5 = 15.","Step 4: 3 × 1 = 3.","Step 5: Therefore 3A = [6 12; 15 3]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 0),
  (1025, 304, 'Find -2B if B = [3 -4; -5 2].', 'text', 1, 'Multiply each entry by -2 and carefully handle the signs.', '{"why":"The negative scalar changes the sign of each non-zero entry according to multiplication rules.","sol":"Step 1: -2 × 3 = -6.\nStep 2: -2 × (-4) = 8.\nStep 3: -2 × (-5) = 10.\nStep 4: -2 × 2 = -4.\nStep 5: Therefore -2B = [-6 8; 10 -4].","steps":["Step 1: -2 × 3 = -6.","Step 2: -2 × (-4) = 8.","Step 3: -2 × (-5) = 10.","Step 4: -2 × 2 = -4.","Step 5: Therefore -2B = [-6 8; 10 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 1),
  (1026, 304, 'Find 1/2 C if C = [6 10; 4 8].', 'text', 1, 'Half of each entry is the same as multiplying each entry by 1/2.', '{"why":"A scalar multiplies every entry independently.","sol":"Step 1: Half of 6 is 3.\nStep 2: Half of 10 is 5.\nStep 3: Half of 4 is 2.\nStep 4: Half of 8 is 4.\nStep 5: Therefore 1/2 C = [3 5; 2 4].","steps":["Step 1: Half of 6 is 3.","Step 2: Half of 10 is 5.","Step 3: Half of 4 is 2.","Step 4: Half of 8 is 4.","Step 5: Therefore 1/2 C = [3 5; 2 4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 2),
  (1027, 304, 'Find 4D if D = [1 -2 3; 0 5 -1].', 'text', 1, 'There are six entries, so all six must be multiplied by 4.', '{"why":"Every entry receives the same scalar multiplication.","sol":"Step 1: 4 × 1 = 4.\nStep 2: 4 × (-2) = -8.\nStep 3: 4 × 3 = 12.\nStep 4: 4 × 0 = 0.\nStep 5: 4 × 5 = 20.\nStep 6: 4 × (-1) = -4.\nStep 7: Therefore 4D = [4 -8 12; 0 20 -4].","steps":["Step 1: 4 × 1 = 4.","Step 2: 4 × (-2) = -8.","Step 3: 4 × 3 = 12.","Step 4: 4 × 0 = 0.","Step 5: 4 × 5 = 20.","Step 6: 4 × (-1) = -4.","Step 7: Therefore 4D = [4 -8 12; 0 20 -4]."],"options":[],"conceptId":"math_matrices_scalar_multiplication_of_a_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Scalar Multiplication of a Matrix"}', 3),
  (1028, 305, 'Find AB if A = [2 3; 1 4] and B = [5 2; 6 1].', 'text', 1, 'For each answer position, use a row from A and a column from B.', '{"why":"Each entry is formed by multiplying corresponding entries of one row and one column, then adding the products.","sol":"Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.\nStep 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.\nStep 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.\nStep 5: Therefore AB = [28 7; 29 6].","steps":["Step 1: Top-left: (2 × 5) + (3 × 6) = 10 + 18 = 28.","Step 2: Top-right: (2 × 2) + (3 × 1) = 4 + 3 = 7.","Step 3: Bottom-left: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 4: Bottom-right: (1 × 2) + (4 × 1) = 2 + 4 = 6.","Step 5: Therefore AB = [28 7; 29 6]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 0),
  (1029, 305, 'Find the top-left entry of AB if A = [4 1; 2 3] and B = [7 5; 6 8].', 'text', 1, 'Use row 1 of A and column 1 of B.', '{"why":"A matrix product entry is obtained from a row-column multiplication.","sol":"Step 1: Row 1 of A is [4 1].\nStep 2: Column 1 of B is [7; 6].\nStep 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.\nStep 4: Add: 28 + 6 = 34.\nStep 5: Therefore the top-left entry is 34.","steps":["Step 1: Row 1 of A is [4 1].","Step 2: Column 1 of B is [7; 6].","Step 3: Multiply: 4 × 7 = 28 and 1 × 6 = 6.","Step 4: Add: 28 + 6 = 34.","Step 5: Therefore the top-left entry is 34."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 1),
  (1030, 305, 'Find AB if A = [3 2; 1 4] and B = [5; 6].', 'text', 1, 'There is only one column in B, so each row of A produces one answer.', '{"why":"Each row of A is combined with the single column of B.","sol":"Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.\nStep 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.\nStep 3: Therefore AB = [27; 29].","steps":["Step 1: First row: (3 × 5) + (2 × 6) = 15 + 12 = 27.","Step 2: Second row: (1 × 5) + (4 × 6) = 5 + 24 = 29.","Step 3: Therefore AB = [27; 29]."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 2),
  (1031, 305, 'Can A = [1 2 3; 4 5 6] be multiplied by B = [7 8; 9 10] in the order AB?', 'text', 1, 'Compare the number of columns in A with the number of rows in B.', '{"why":"Matrix multiplication requires the number of columns of the first matrix to equal the number of rows of the second matrix.","sol":"Step 1: A has 3 columns.\nStep 2: B has 2 rows.\nStep 3: For AB to exist, these two numbers must be equal.\nStep 4: Since 3 is not equal to 2, AB cannot be formed.","steps":["Step 1: A has 3 columns.","Step 2: B has 2 rows.","Step 3: For AB to exist, these two numbers must be equal.","Step 4: Since 3 is not equal to 2, AB cannot be formed."],"options":[],"conceptId":"math_matrices_multiplication_of_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Multiplication of Matrices"}', 3),
  (1032, 306, 'Find the determinant of A = [3 2; 5 4].', 'text', 1, 'Use ad - bc.', '{"why":"For a 2 × 2 matrix [a b; c d], the determinant is ad - bc.","sol":"Step 1: Multiply the main diagonal: 3 × 4 = 12.\nStep 2: Multiply the other diagonal: 2 × 5 = 10.\nStep 3: Subtract: 12 - 10 = 2.\nStep 4: Therefore det(A) = 2.","steps":["Step 1: Multiply the main diagonal: 3 × 4 = 12.","Step 2: Multiply the other diagonal: 2 × 5 = 10.","Step 3: Subtract: 12 - 10 = 2.","Step 4: Therefore det(A) = 2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 0),
  (1033, 306, 'Find the determinant of B = [2 7; 5 3].', 'text', 1, 'Calculate 2 × 3 first, then subtract 7 × 5.', '{"why":"The determinant uses the difference between the two diagonal products.","sol":"Step 1: 2 × 3 = 6.\nStep 2: 7 × 5 = 35.\nStep 3: 6 - 35 = -29.\nStep 4: Therefore det(B) = -29.","steps":["Step 1: 2 × 3 = 6.","Step 2: 7 × 5 = 35.","Step 3: 6 - 35 = -29.","Step 4: Therefore det(B) = -29."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 1),
  (1034, 306, 'Find the determinant of C = [-2 4; 3 -5].', 'text', 1, 'Be careful with the two negative entries.', '{"why":"The negative signs are handled during ordinary multiplication before the final subtraction.","sol":"Step 1: (-2) × (-5) = 10.\nStep 2: 4 × 3 = 12.\nStep 3: 10 - 12 = -2.\nStep 4: Therefore det(C) = -2.","steps":["Step 1: (-2) × (-5) = 10.","Step 2: 4 × 3 = 12.","Step 3: 10 - 12 = -2.","Step 4: Therefore det(C) = -2."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 2),
  (1035, 306, 'Find the determinant of D = [2 4; 1 2].', 'text', 1, 'Multiply the two diagonal pairs and subtract.', '{"why":"The two diagonal products are equal, so their difference is zero.","sol":"Step 1: 2 × 2 = 4.\nStep 2: 4 × 1 = 4.\nStep 3: 4 - 4 = 0.\nStep 4: Therefore det(D) = 0.","steps":["Step 1: 2 × 2 = 4.","Step 2: 4 × 1 = 4.","Step 3: 4 - 4 = 0.","Step 4: Therefore det(D) = 0."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 3),
  (1036, 306, 'Which calculation gives the determinant of [5 2; 3 4]?', 'text', 1, 'Identify a, b, c and d before applying ad - bc.', '{"why":"The determinant is ad - bc, so the second diagonal product must be subtracted.","sol":"Step 1: a = 5, b = 2, c = 3, d = 4.\nStep 2: ad = 5 × 4 = 20.\nStep 3: bc = 2 × 3 = 6.\nStep 4: Therefore det(A) = 20 - 6 = 14.","steps":["Step 1: a = 5, b = 2, c = 3, d = 4.","Step 2: ad = 5 × 4 = 20.","Step 3: bc = 2 × 3 = 6.","Step 4: Therefore det(A) = 20 - 6 = 14."],"options":[],"conceptId":"math_matrices_determinant_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Determinant of a 2 × 2 Matrix"}', 4),
  (1037, 307, 'Find the determinant of A = [1 2 3; 0 4 5; 1 0 6].', 'text', 1, 'Expand along the first row using the signs +, -, +.', '{"why":"The determinant is obtained by expanding along the first row and calculating each 2 × 2 minor.","sol":"Step 1: First minor: (4 × 6) - (5 × 0) = 24.\nStep 2: First contribution: 1 × 24 = 24.\nStep 3: Second minor: (0 × 6) - (5 × 1) = -5.\nStep 4: Second contribution: -2 × (-5) = 10.\nStep 5: Third minor: (0 × 0) - (4 × 1) = -4.\nStep 6: Third contribution: 3 × (-4) = -12.\nStep 7: det(A) = 24 + 10 - 12 = 22.","steps":["Step 1: First minor: (4 × 6) - (5 × 0) = 24.","Step 2: First contribution: 1 × 24 = 24.","Step 3: Second minor: (0 × 6) - (5 × 1) = -5.","Step 4: Second contribution: -2 × (-5) = 10.","Step 5: Third minor: (0 × 0) - (4 × 1) = -4.","Step 6: Third contribution: 3 × (-4) = -12.","Step 7: det(A) = 24 + 10 - 12 = 22."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 0),
  (1038, 307, 'Find the determinant of B = [2 0 1; 3 4 5; 1 2 6].', 'text', 1, 'The middle first-row entry is zero, so its entire contribution is zero.', '{"why":"Each first-row entry is combined with the determinant of the 2 × 2 matrix left after removing its row and column.","sol":"Step 1: First minor: (4 × 6) - (5 × 2) = 14.\nStep 2: First contribution: 2 × 14 = 28.\nStep 3: Second contribution: 0.\nStep 4: Third minor: (3 × 2) - (4 × 1) = 2.\nStep 5: Third contribution: 1 × 2 = 2.\nStep 6: det(B) = 28 + 0 + 2 = 30.","steps":["Step 1: First minor: (4 × 6) - (5 × 2) = 14.","Step 2: First contribution: 2 × 14 = 28.","Step 3: Second contribution: 0.","Step 4: Third minor: (3 × 2) - (4 × 1) = 2.","Step 5: Third contribution: 1 × 2 = 2.","Step 6: det(B) = 28 + 0 + 2 = 30."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 1),
  (1039, 307, 'Find the determinant of C = [1 2 0; 3 4 5; 6 7 8].', 'text', 1, 'Use +, -, + across the first row.', '{"why":"The signs in the first-row expansion are positive, negative, positive.","sol":"Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.\nStep 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.\nStep 3: Third contribution is zero.\nStep 4: det(C) = -3 + 12 = 9.","steps":["Step 1: First contribution: 1[(4 × 8) - (5 × 7)] = -3.","Step 2: Second contribution: -2[(3 × 8) - (5 × 6)] = -2(-6) = 12.","Step 3: Third contribution is zero.","Step 4: det(C) = -3 + 12 = 9."],"options":[],"conceptId":"math_matrices_determinant_of_a_3_3_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinant of a 3 × 3 Matrix"}', 2),
  (1040, 308, 'Determine whether A = [2 4; 1 2] is singular or non-singular.', 'text', 1, 'Find the determinant first.', '{"why":"A square matrix is singular when its determinant is zero.","sol":"Step 1: det(A) = (2 × 2) - (4 × 1).\nStep 2: det(A) = 4 - 4 = 0.\nStep 3: A determinant of zero means the matrix is singular.","steps":["Step 1: det(A) = (2 × 2) - (4 × 1).","Step 2: det(A) = 4 - 4 = 0.","Step 3: A determinant of zero means the matrix is singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 0),
  (1041, 308, 'Determine whether B = [3 2; 5 4] is singular or non-singular.', 'text', 1, 'Calculate 3 × 4 - 2 × 5.', '{"why":"A non-zero determinant means the matrix is non-singular.","sol":"Step 1: det(B) = (3 × 4) - (2 × 5).\nStep 2: det(B) = 12 - 10 = 2.\nStep 3: 2 is not zero.\nStep 4: Therefore B is non-singular.","steps":["Step 1: det(B) = (3 × 4) - (2 × 5).","Step 2: det(B) = 12 - 10 = 2.","Step 3: 2 is not zero.","Step 4: Therefore B is non-singular."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 1),
  (1042, 308, 'Find x if [x 2; 3 6] is singular.', 'text', 1, 'Set the determinant equal to zero.', '{"why":"Singularity requires the determinant to equal zero.","sol":"Step 1: det(A) = (x × 6) - (2 × 3).\nStep 2: 6x - 6 = 0.\nStep 3: 6x = 6.\nStep 4: x = 1.","steps":["Step 1: det(A) = (x × 6) - (2 × 3).","Step 2: 6x - 6 = 0.","Step 3: 6x = 6.","Step 4: x = 1."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 2),
  (1043, 308, 'Find x if [x 1; 2 3] is singular.', 'text', 1, 'Set 3x - 2 equal to zero.', '{"why":"The value of x must make the determinant equal to zero.","sol":"Step 1: det(A) = 3x - 2.\nStep 2: 3x - 2 = 0.\nStep 3: 3x = 2.\nStep 4: x = 2/3.","steps":["Step 1: det(A) = 3x - 2.","Step 2: 3x - 2 = 0.","Step 3: 3x = 2.","Step 4: x = 2/3."],"options":[],"conceptId":"math_matrices_singular_and_non_singular_matrices","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Singular and Non-Singular Matrices"}', 3),
  (1044, 309, 'Find the inverse of A = [3 2; 1 4].', 'text', 1, 'First calculate the determinant.', '{"why":"The inverse of a 2 × 2 matrix follows the fixed inverse formula.","sol":"Step 1: det(A) = 3 × 4 - 2 × 1 = 10.\nStep 2: Swap 3 and 4.\nStep 3: Change 2 to -2 and 1 to -1.\nStep 4: Multiply the resulting matrix by 1/10.\nStep 5: A⁻¹ = [2/5 -1/5; -1/10 3/10].","steps":["Step 1: det(A) = 3 × 4 - 2 × 1 = 10.","Step 2: Swap 3 and 4.","Step 3: Change 2 to -2 and 1 to -1.","Step 4: Multiply the resulting matrix by 1/10.","Step 5: A⁻¹ = [2/5 -1/5; -1/10 3/10]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 0),
  (1045, 309, 'Find the inverse of B = [2 1; 5 3].', 'text', 1, 'The determinant is 1.', '{"why":"The determinant is 1, so the reciprocal factor is also 1.","sol":"Step 1: det(B) = 2 × 3 - 1 × 5 = 1.\nStep 2: Swap 2 and 3.\nStep 3: Change 1 to -1 and 5 to -5.\nStep 4: Multiply by 1/1.\nStep 5: B⁻¹ = [3 -1; -5 2].","steps":["Step 1: det(B) = 2 × 3 - 1 × 5 = 1.","Step 2: Swap 2 and 3.","Step 3: Change 1 to -1 and 5 to -5.","Step 4: Multiply by 1/1.","Step 5: B⁻¹ = [3 -1; -5 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 1),
  (1046, 309, 'Does C = [2 4; 1 2] have an inverse?', 'text', 1, 'Calculate its determinant.', '{"why":"A 2 × 2 matrix cannot have an inverse when its determinant is zero.","sol":"Step 1: det(C) = 2 × 2 - 4 × 1.\nStep 2: det(C) = 0.\nStep 3: An inverse requires a non-zero determinant.\nStep 4: Therefore C has no inverse.","steps":["Step 1: det(C) = 2 × 2 - 4 × 1.","Step 2: det(C) = 0.","Step 3: An inverse requires a non-zero determinant.","Step 4: Therefore C has no inverse."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 2),
  (1047, 309, 'Find the inverse of D = [4 1; 2 1].', 'text', 1, 'The determinant is 2.', '{"why":"The inverse is obtained by rearranging the entries and multiplying by the reciprocal of the determinant.","sol":"Step 1: det(D) = 4 × 1 - 1 × 2 = 2.\nStep 2: Swap 4 and 1.\nStep 3: Change 1 to -1 and 2 to -2.\nStep 4: Multiply by 1/2.\nStep 5: D⁻¹ = [1/2 -1/2; -1 2].","steps":["Step 1: det(D) = 4 × 1 - 1 × 2 = 2.","Step 2: Swap 4 and 1.","Step 3: Change 1 to -1 and 2 to -2.","Step 4: Multiply by 1/2.","Step 5: D⁻¹ = [1/2 -1/2; -1 2]."],"options":[],"conceptId":"math_matrices_inverse_of_a_2_2_matrix","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Inverse of a 2 × 2 Matrix"}', 3),
  (1048, 310, 'Find X if X + [2 3; 4 5] = [7 9; 10 12].', 'text', 1, 'Subtract the known matrix from both sides.', '{"why":"Subtracting the known matrix isolates X.","sol":"Step 1: 7 - 2 = 5.\nStep 2: 9 - 3 = 6.\nStep 3: 10 - 4 = 6.\nStep 4: 12 - 5 = 7.\nStep 5: Therefore X = [5 6; 6 7].","steps":["Step 1: 7 - 2 = 5.","Step 2: 9 - 3 = 6.","Step 3: 10 - 4 = 6.","Step 4: 12 - 5 = 7.","Step 5: Therefore X = [5 6; 6 7]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 0),
  (1049, 310, 'Find X if 3X = [12 15; 9 18].', 'text', 1, 'Divide every entry by 3.', '{"why":"The scalar 3 affects every entry, so every entry is divided by 3 to isolate X.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 3 = 5.\nStep 3: 9 ÷ 3 = 3.\nStep 4: 18 ÷ 3 = 6.\nStep 5: Therefore X = [4 5; 3 6].","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 3 = 5.","Step 3: 9 ÷ 3 = 3.","Step 4: 18 ÷ 3 = 6.","Step 5: Therefore X = [4 5; 3 6]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 1),
  (1050, 310, 'Find X if X - [3 1; 2 4] = [5 7; 8 6].', 'text', 1, 'Add the known matrix to both sides.', '{"why":"Adding the subtracted matrix reverses the subtraction and isolates X.","sol":"Step 1: 5 + 3 = 8.\nStep 2: 7 + 1 = 8.\nStep 3: 8 + 2 = 10.\nStep 4: 6 + 4 = 10.\nStep 5: Therefore X = [8 8; 10 10].","steps":["Step 1: 5 + 3 = 8.","Step 2: 7 + 1 = 8.","Step 3: 8 + 2 = 10.","Step 4: 6 + 4 = 10.","Step 5: Therefore X = [8 8; 10 10]."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 2),
  (1051, 310, 'Find x and y if [x 4; 7 y] + [3 2; 1 5] = [8 6; 8 12].', 'text', 1, 'Use the top-left position to find x and the bottom-right position to find y.', '{"why":"Each unknown is determined by comparing the corresponding entries.","sol":"Step 1: Top-left: x + 3 = 8.\nStep 2: Therefore x = 5.\nStep 3: Bottom-right: y + 5 = 12.\nStep 4: Therefore y = 7.","steps":["Step 1: Top-left: x + 3 = 8.","Step 2: Therefore x = 5.","Step 3: Bottom-right: y + 5 = 12.","Step 4: Therefore y = 7."],"options":[],"conceptId":"math_matrices_solving_matrix_equations","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Solving Matrix Equations"}', 3),
  (1052, 311, 'Find the vector AB if A(2,3) and B(7,5).', 'text', 1, 'Final point minus starting point.', '{"why":"The vector from A to B is found by subtracting the coordinates of A from the coordinates of B.","sol":"Step 1: Starting point A = (2,3)\nStep 2: Final point B = (7,5)\nStep 3: Subtract x-coordinates: 7 - 2 = 5\nStep 4: Subtract y-coordinates: 5 - 3 = 2\nStep 5: Therefore AB = (5,2)","steps":["Step 1: Starting point A = (2,3)","Step 2: Final point B = (7,5)","Step 3: Subtract x-coordinates: 7 - 2 = 5","Step 4: Subtract y-coordinates: 5 - 3 = 2","Step 5: Therefore AB = (5,2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 0),
  (1053, 311, 'Find the vector PQ if P(-3,4) and Q(2,-1).', 'text', 1, 'Subtract P from Q.', '{"why":"Vector PQ describes the movement from P to Q.","sol":"Step 1: Starting point P = (-3,4)\nStep 2: Final point Q = (2,-1)\nStep 3: x-component: 2 - (-3) = 5\nStep 4: y-component: -1 - 4 = -5\nStep 5: Therefore PQ = (5,-5)","steps":["Step 1: Starting point P = (-3,4)","Step 2: Final point Q = (2,-1)","Step 3: x-component: 2 - (-3) = 5","Step 4: y-component: -1 - 4 = -5","Step 5: Therefore PQ = (5,-5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 1),
  (1054, 311, 'Find the vector CD if C(6,-2) and D(1,4).', 'text', 1, 'Use final point minus starting point.', '{"why":"Subtracting the starting coordinates from the final coordinates gives the vector.","sol":"Step 1: Starting point C = (6,-2)\nStep 2: Final point D = (1,4)\nStep 3: x-component: 1 - 6 = -5\nStep 4: y-component: 4 - (-2) = 6\nStep 5: Therefore CD = (-5,6)","steps":["Step 1: Starting point C = (6,-2)","Step 2: Final point D = (1,4)","Step 3: x-component: 1 - 6 = -5","Step 4: y-component: 4 - (-2) = 6","Step 5: Therefore CD = (-5,6)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 2),
  (1055, 311, 'If A(2,3) and B(7,5), find BA.', 'text', 1, 'BA moves from B back to A.', '{"why":"Reversing the direction of a vector changes the signs of both components.","sol":"Step 1: Starting point B = (7,5)\nStep 2: Final point A = (2,3)\nStep 3: x-component: 2 - 7 = -5\nStep 4: y-component: 3 - 5 = -2\nStep 5: Therefore BA = (-5,-2)","steps":["Step 1: Starting point B = (7,5)","Step 2: Final point A = (2,3)","Step 3: x-component: 2 - 7 = -5","Step 4: y-component: 3 - 5 = -2","Step 5: Therefore BA = (-5,-2)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 3),
  (1056, 311, 'If AB = (4,-3), what is BA?', 'text', 1, 'The reverse vector is the negative of the original.', '{"why":"BA = -AB, so reversing a vector changes the signs of both components.","sol":"Step 1: AB = (4,-3)\nStep 2: Reverse the direction\nStep 3: Change both signs\nStep 4: BA = (-4,3)","steps":["Step 1: AB = (4,-3)","Step 2: Reverse the direction","Step 3: Change both signs","Step 4: BA = (-4,3)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 4),
  (1057, 311, 'A point A is (1,2). A vector AB is (5,3). Find the coordinates of B.', 'text', 1, 'Move from A by the vector AB.', '{"why":"The vector tells us how far and in which direction to move from A to reach B.","sol":"Step 1: Start at A = (1,2)\nStep 2: Add the x-component: 1 + 5 = 6\nStep 3: Add the y-component: 2 + 3 = 5\nStep 4: Therefore B = (6,5)","steps":["Step 1: Start at A = (1,2)","Step 2: Add the x-component: 1 + 5 = 6","Step 3: Add the y-component: 2 + 3 = 5","Step 4: Therefore B = (6,5)"],"options":[],"conceptId":"math_vectors_vector_from_one_point_to_another","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Vector From One Point to Another"}', 5),
  (1058, 312, 'In the directed line segment A → B, which point is the starting point?', 'text', 1, 'Follow the direction of the arrow.', '{"why":"The starting point is where the vector begins before following the arrow.","sol":"Step 1: The arrow points from A toward B.\nStep 2: Therefore the vector begins at A.\nStep 3: A is the starting point.","steps":["Step 1: The arrow points from A toward B.","Step 2: Therefore the vector begins at A.","Step 3: A is the starting point."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 0),
  (1059, 312, 'In P ← Q, which point is the starting point?', 'text', 1, 'The arrow points toward P.', '{"why":"The arrowhead shows the direction of movement, so the vector starts at Q.","sol":"Step 1: The arrowhead points toward P.\nStep 2: Therefore the vector is moving from Q toward P.\nStep 3: The vector starts at Q.","steps":["Step 1: The arrowhead points toward P.","Step 2: Therefore the vector is moving from Q toward P.","Step 3: The vector starts at Q."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 1),
  (1060, 312, 'Two directed line segments have equal lengths but point in opposite directions. Are they the same vector?', 'text', 1, 'A vector needs both magnitude and direction.', '{"why":"Equal magnitude alone is not enough; vectors must also have the same direction.","sol":"Step 1: Equal lengths mean equal magnitudes.\nStep 2: However, the directions are opposite.\nStep 3: Therefore the vectors are not the same.","steps":["Step 1: Equal lengths mean equal magnitudes.","Step 2: However, the directions are opposite.","Step 3: Therefore the vectors are not the same."],"options":[],"conceptId":"math_vectors_a_vector_as_a_directed_line_segment","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"A Vector as a Directed Line Segment"}', 2),
  (1061, 313, 'A vector moves from A to B. Write its vector notation.', 'text', 1, 'Write the starting point first.', '{"why":"The notation ⃗AB represents movement from A to B.","sol":"Step 1: The vector starts at A.\nStep 2: It ends at B.\nStep 3: Write the starting point first and ending point second.","steps":["Step 1: The vector starts at A.","Step 2: It ends at B.","Step 3: Write the starting point first and ending point second."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 0),
  (1062, 313, 'A vector moves from X to Y. Which notation represents it: ⃗XY or ⃗YX?', 'text', 1, 'The first letter must be the starting point.', '{"why":"The order of the letters records the direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: Therefore X must come first.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: Therefore X must come first."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 1),
  (1063, 313, 'What does ⃗PQ mean?', 'text', 1, 'Read the letters from left to right.', '{"why":"Two-point vector notation records the starting point followed by the ending point.","sol":"Step 1: The first letter is P.\nStep 2: The second letter is Q.\nStep 3: Therefore the vector starts at P and ends at Q.","steps":["Step 1: The first letter is P.","Step 2: The second letter is Q.","Step 3: Therefore the vector starts at P and ends at Q."],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 2),
  (1064, 314, 'A vector starts at P and ends at Q. Name it.', 'text', 1, 'Put the starting point first.', '{"why":"A vector is named by writing its initial point followed by its terminal point.","sol":"Step 1: Starting point = P.\nStep 2: Ending point = Q.\nStep 3: Therefore the vector is ⃗PQ.","steps":["Step 1: Starting point = P.","Step 2: Ending point = Q.","Step 3: Therefore the vector is ⃗PQ."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 0),
  (1065, 314, 'A vector starts at X and ends at Y. A student writes ⃗YX. Is this correct?', 'text', 1, 'Compare the order with the actual direction.', '{"why":"⃗YX represents movement from Y to X, which is the opposite direction.","sol":"Step 1: The vector starts at X.\nStep 2: The vector ends at Y.\nStep 3: The correct order is X then Y.\nStep 4: Therefore ⃗XY is correct, not ⃗YX.","steps":["Step 1: The vector starts at X.","Step 2: The vector ends at Y.","Step 3: The correct order is X then Y.","Step 4: Therefore ⃗XY is correct, not ⃗YX."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 1),
  (1066, 314, 'In the directed segment B ← A, what is the vector name?', 'text', 1, 'The arrow points toward B.', '{"why":"The arrow determines the direction, not the position of the letters on the page.","sol":"Step 1: The arrowhead is at B.\nStep 2: Therefore the vector moves from A to B.\nStep 3: Write A first and B second.","steps":["Step 1: The arrowhead is at B.","Step 2: Therefore the vector moves from A to B.","Step 3: Write A first and B second."],"options":[],"conceptId":"math_vectors_naming_a_vector_from_its_initial_and_terminal_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Naming a Vector from Its Initial and Terminal Points"}', 2),
  (1067, 315, 'Vector A has magnitude 10 N east. Vector B has magnitude 10 N east. Are they equivalent?', 'text', 1, 'Check both magnitude and direction.', '{"why":"Equivalent vectors have the same magnitude and the same direction.","sol":"Step 1: Vector A has magnitude 10 N.\nStep 2: Vector B has magnitude 10 N.\nStep 3: Both point east.\nStep 4: Therefore they have the same magnitude and direction.","steps":["Step 1: Vector A has magnitude 10 N.","Step 2: Vector B has magnitude 10 N.","Step 3: Both point east.","Step 4: Therefore they have the same magnitude and direction."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 0),
  (1068, 315, 'Vector A has magnitude 6 m north. Vector B has magnitude 6 m south. Are they equivalent?', 'text', 1, 'Their magnitudes are equal. What about their directions?', '{"why":"Equal magnitude is not enough; equivalent vectors must also have the same direction.","sol":"Step 1: Both vectors have magnitude 6 m.\nStep 2: A points north.\nStep 3: B points south.\nStep 4: The directions are opposite.\nStep 5: Therefore they are not equivalent.","steps":["Step 1: Both vectors have magnitude 6 m.","Step 2: A points north.","Step 3: B points south.","Step 4: The directions are opposite.","Step 5: Therefore they are not equivalent."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 1),
  (1069, 315, 'Two vectors have the same magnitude and direction but are drawn at different positions on a page. Can they still be equivalent?', 'text', 1, 'Does the starting position form part of the definition of an equivalent vector?', '{"why":"Equivalent vectors can be drawn in different positions as long as magnitude and direction are unchanged.","sol":"Step 1: Compare their magnitudes.\nStep 2: They are the same.\nStep 3: Compare their directions.\nStep 4: They are also the same.\nStep 5: Their positions are different, but position does not prevent equivalence.","steps":["Step 1: Compare their magnitudes.","Step 2: They are the same.","Step 3: Compare their directions.","Step 4: They are also the same.","Step 5: Their positions are different, but position does not prevent equivalence."],"options":[],"conceptId":"math_vectors_equivalent_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Equivalent Vectors"}', 2),
  (1070, 316, 'A vector is 12 m east. What is its opposite vector?', 'text', 1, 'Keep the magnitude and reverse the direction.', '{"why":"Opposite vectors have the same magnitude but opposite directions.","sol":"Step 1: The original magnitude is 12 m.\nStep 2: Keep the magnitude at 12 m.\nStep 3: The opposite of east is west.\nStep 4: Therefore the opposite vector is 12 m west.","steps":["Step 1: The original magnitude is 12 m.","Step 2: Keep the magnitude at 12 m.","Step 3: The opposite of east is west.","Step 4: Therefore the opposite vector is 12 m west."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 0),
  (1071, 316, 'If ⃗a = 8 N upward, what is -⃗a?', 'text', 1, 'The negative sign reverses the direction.', '{"why":"A negative vector has the same magnitude but points in the opposite direction.","sol":"Step 1: The magnitude of ⃗a is 8 N.\nStep 2: Keep the magnitude as 8 N.\nStep 3: Reverse upward to downward.\nStep 4: Therefore -⃗a = 8 N downward.","steps":["Step 1: The magnitude of ⃗a is 8 N.","Step 2: Keep the magnitude as 8 N.","Step 3: Reverse upward to downward.","Step 4: Therefore -⃗a = 8 N downward."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 1),
  (1072, 316, 'If ⃗AB represents movement from A to B, which vector represents the opposite direction?', 'text', 1, 'Reverse the starting and ending points.', '{"why":"Reversing the direction changes the vector from ⃗AB to ⃗BA.","sol":"Step 1: ⃗AB means movement from A to B.\nStep 2: The opposite movement must be from B to A.\nStep 3: Therefore the opposite vector is ⃗BA.","steps":["Step 1: ⃗AB means movement from A to B.","Step 2: The opposite movement must be from B to A.","Step 3: Therefore the opposite vector is ⃗BA."],"options":[],"conceptId":"math_vectors_opposite_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Opposite Vectors"}', 2),
  (1073, 317, 'Which of the following is a scalar quantity: mass, force, displacement, or velocity?', 'text', 1, 'Ask whether the quantity requires a direction.', '{"why":"A scalar quantity is completely described by its magnitude without direction.","sol":"Step 1: Mass tells us how much matter an object contains.\nStep 2: Mass does not require a direction.\nStep 3: Therefore, mass is the scalar quantity.","steps":["Step 1: Mass tells us how much matter an object contains.","Step 2: Mass does not require a direction.","Step 3: Therefore, mass is the scalar quantity."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 0),
  (1074, 317, 'A student spends 30 minutes studying. Is the 30 minutes a scalar quantity?', 'text', 1, 'Does time require a direction?', '{"why":"Time has magnitude but does not require direction.","sol":"Step 1: The quantity being described is time.\nStep 2: The student studied for 30 minutes.\nStep 3: No direction is required to describe the time.\nStep 4: Therefore, time is scalar.","steps":["Step 1: The quantity being described is time.","Step 2: The student studied for 30 minutes.","Step 3: No direction is required to describe the time.","Step 4: Therefore, time is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 1),
  (1075, 317, 'A bottle contains 2 litres of water. Is volume a scalar quantity?', 'text', 1, 'Does volume need a direction?', '{"why":"Volume is described by its amount only.","sol":"Step 1: The quantity is volume.\nStep 2: The amount of water is 2 litres.\nStep 3: A direction is not needed to describe the volume.\nStep 4: Therefore, volume is scalar.","steps":["Step 1: The quantity is volume.","Step 2: The amount of water is 2 litres.","Step 3: A direction is not needed to describe the volume.","Step 4: Therefore, volume is scalar."],"options":[],"conceptId":"math_vectors_scalar_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar Quantities"}', 2),
  (1076, 318, 'A person walks 12 m east. What is the magnitude and what is the direction?', 'text', 1, 'The number gives magnitude; the word describing the way gives direction.', '{"why":"A vector is described using both magnitude and direction.","sol":"Step 1: The distance given is 12 m.\nStep 2: Therefore the magnitude is 12 m.\nStep 3: The direction given is east.","steps":["Step 1: The distance given is 12 m.","Step 2: Therefore the magnitude is 12 m.","Step 3: The direction given is east."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 0),
  (1077, 318, 'A force of 20 N acts downward. What is its magnitude?', 'text', 1, 'Ignore the direction for this question.', '{"why":"Magnitude tells us the size or amount of the vector quantity.","sol":"Step 1: The force is given as 20 N downward.\nStep 2: The numerical size of the force is 20 N.\nStep 3: Therefore its magnitude is 20 N.","steps":["Step 1: The force is given as 20 N downward.","Step 2: The numerical size of the force is 20 N.","Step 3: Therefore its magnitude is 20 N."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 1),
  (1078, 318, 'A displacement is 8 km west. What information identifies its direction?', 'text', 1, 'Look for the word that tells which way the movement occurred.', '{"why":"Direction tells us which way the vector points.","sol":"Step 1: The displacement is given as 8 km west.\nStep 2: 8 km gives the magnitude.\nStep 3: West gives the direction.","steps":["Step 1: The displacement is given as 8 km west.","Step 2: 8 km gives the magnitude.","Step 3: West gives the direction."],"options":[],"conceptId":"math_vectors_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Quantities"}', 2),
  (1079, 319, 'Classify mass as scalar or vector.', 'text', 1, 'Does mass need a direction?', '{"why":"Mass has magnitude only and does not require direction.","sol":"Step 1: Mass tells us the amount of matter in an object.\nStep 2: A direction is not needed.\nStep 3: Therefore mass is scalar.","steps":["Step 1: Mass tells us the amount of matter in an object.","Step 2: A direction is not needed.","Step 3: Therefore mass is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 0),
  (1080, 319, 'Classify displacement as scalar or vector.', 'text', 1, 'Does displacement need direction?', '{"why":"Displacement requires both magnitude and direction.","sol":"Step 1: Displacement describes a change in position.\nStep 2: The change in position must have a size and a direction.\nStep 3: Therefore displacement is vector.","steps":["Step 1: Displacement describes a change in position.","Step 2: The change in position must have a size and a direction.","Step 3: Therefore displacement is vector."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 1),
  (1081, 319, 'A runner''s speed is 12 m/s. Is speed scalar or vector?', 'text', 1, 'Does speed itself tell you which direction the runner is moving?', '{"why":"Speed gives magnitude of motion without direction.","sol":"Step 1: Speed tells how fast the runner is moving.\nStep 2: The value 12 m/s does not specify a direction.\nStep 3: Therefore speed is scalar.","steps":["Step 1: Speed tells how fast the runner is moving.","Step 2: The value 12 m/s does not specify a direction.","Step 3: Therefore speed is scalar."],"options":[],"conceptId":"math_vectors_scalar_vs_vector_quantities","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Scalar vs Vector Quantities"}', 2),
  (1082, 320, 'A force of 25 N acts upward. What is its magnitude?', 'text', 1, 'The direction is not needed to find magnitude.', '{"why":"Magnitude is the size of the vector quantity.","sol":"Step 1: The force is given as 25 N upward.\nStep 2: 25 N gives the size of the force.\nStep 3: Upward gives the direction.\nStep 4: Therefore the magnitude is 25 N.","steps":["Step 1: The force is given as 25 N upward.","Step 2: 25 N gives the size of the force.","Step 3: Upward gives the direction.","Step 4: Therefore the magnitude is 25 N."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 0),
  (1083, 320, 'A displacement is 14 km west. What is its magnitude?', 'text', 1, 'Separate the amount from the direction.', '{"why":"The numerical size of the displacement is its magnitude.","sol":"Step 1: 14 km gives the amount of displacement.\nStep 2: West gives the direction.\nStep 3: Therefore the magnitude is 14 km.","steps":["Step 1: 14 km gives the amount of displacement.","Step 2: West gives the direction.","Step 3: Therefore the magnitude is 14 km."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 1),
  (1084, 320, 'A velocity is 30 m/s south. What is its magnitude?', 'text', 1, 'South describes direction.', '{"why":"Magnitude is the size of a vector, while south is its direction.","sol":"Step 1: The velocity is 30 m/s south.\nStep 2: 30 m/s gives the numerical size.\nStep 3: South gives direction.\nStep 4: Therefore the magnitude is 30 m/s.","steps":["Step 1: The velocity is 30 m/s south.","Step 2: 30 m/s gives the numerical size.","Step 3: South gives direction.","Step 4: Therefore the magnitude is 30 m/s."],"options":[],"conceptId":"math_vectors_magnitude_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude of a Vector"}', 2),
  (1085, 321, 'A displacement is 18 m east. What is its direction?', 'text', 1, 'Look for the word that tells which way the displacement points.', '{"why":"The direction is the part of the vector description that tells which way it points.","sol":"Step 1: The displacement is written as 18 m east.\nStep 2: 18 m is the magnitude.\nStep 3: East tells us the direction.","steps":["Step 1: The displacement is written as 18 m east.","Step 2: 18 m is the magnitude.","Step 3: East tells us the direction."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 0),
  (1086, 321, 'A force of 50 N acts downward. What is the direction of the force?', 'text', 1, '50 N tells you the size. Which word tells you the way?', '{"why":"Direction describes the way in which the vector acts.","sol":"Step 1: 50 N gives the magnitude.\nStep 2: Downward tells us which way the force acts.\nStep 3: Therefore the direction is downward.","steps":["Step 1: 50 N gives the magnitude.","Step 2: Downward tells us which way the force acts.","Step 3: Therefore the direction is downward."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 1),
  (1087, 321, 'Two vectors have magnitudes of 12 m. One points east and the other points west. Do they have the same direction?', 'text', 1, 'Compare east and west.', '{"why":"Vectors with the same magnitude can still have different directions.","sol":"Step 1: The first vector points east.\nStep 2: The second vector points west.\nStep 3: East and west are opposite directions.\nStep 4: Therefore their directions are not the same.","steps":["Step 1: The first vector points east.","Step 2: The second vector points west.","Step 3: East and west are opposite directions.","Step 4: Therefore their directions are not the same."],"options":[],"conceptId":"math_vectors_direction_of_a_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Direction of a Vector"}', 2),
  (1088, 322, 'What does the column vector (3, 5) represent?', 'text', 1, 'Read the top number first, then the bottom number.', '{"why":"The top component gives horizontal movement and the bottom component gives vertical movement.","sol":"Step 1: The top number is 3, so move 3 units right.\nStep 2: The bottom number is 5, so move 5 units up.\nStep 3: Therefore the vector represents 3 units right and 5 units up.","steps":["Step 1: The top number is 3, so move 3 units right.","Step 2: The bottom number is 5, so move 5 units up.","Step 3: Therefore the vector represents 3 units right and 5 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 0),
  (1089, 322, 'What movement is represented by the column vector (-2, 4)?', 'text', 1, 'A negative horizontal component means left.', '{"why":"The negative sign reverses the horizontal direction.","sol":"Step 1: The top number is -2.\nStep 2: Therefore move 2 units left.\nStep 3: The bottom number is 4.\nStep 4: Therefore move 4 units up.","steps":["Step 1: The top number is -2.","Step 2: Therefore move 2 units left.","Step 3: The bottom number is 4.","Step 4: Therefore move 4 units up."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 1),
  (1090, 322, 'What movement is represented by the column vector (7, -3)?', 'text', 1, 'The negative bottom component means downward movement.', '{"why":"The top component controls horizontal movement and the bottom component controls vertical movement.","sol":"Step 1: The top number is 7, so move 7 units right.\nStep 2: The bottom number is -3, so move 3 units down.","steps":["Step 1: The top number is 7, so move 7 units right.","Step 2: The bottom number is -3, so move 3 units down."],"options":[],"conceptId":"math_vectors_column_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Notation"}', 2),
  (1091, 323, 'Interpret the column vector (-6, -4).', 'text', 1, 'Look at the sign of each component.', '{"why":"Negative horizontal means left and negative vertical means down.","sol":"Step 1: The horizontal component is -6, so move 6 units left.\nStep 2: The vertical component is -4, so move 4 units down.","steps":["Step 1: The horizontal component is -6, so move 6 units left.","Step 2: The vertical component is -4, so move 4 units down."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 0),
  (1092, 323, 'Write the column vector for 8 units right and 3 units down.', 'text', 1, 'Right is positive and down is negative.', '{"why":"Horizontal movement is written first, followed by vertical movement.","sol":"Step 1: Horizontal movement = 8 units right, so the first component is +8.\nStep 2: Vertical movement = 3 units down, so the second component is -3.\nStep 3: Therefore the column vector is (8, -3).","steps":["Step 1: Horizontal movement = 8 units right, so the first component is +8.","Step 2: Vertical movement = 3 units down, so the second component is -3.","Step 3: Therefore the column vector is (8, -3)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 1),
  (1093, 323, 'Write the column vector for 5 units left and 2 units up.', 'text', 1, 'Left is negative; up is positive.', '{"why":"The signs record the directions of the two components.","sol":"Step 1: Horizontal movement = 5 units left, so the first component is -5.\nStep 2: Vertical movement = 2 units up, so the second component is +2.\nStep 3: Therefore the vector is (-5, 2).","steps":["Step 1: Horizontal movement = 5 units left, so the first component is -5.","Step 2: Vertical movement = 2 units up, so the second component is +2.","Step 3: Therefore the vector is (-5, 2)."],"options":[],"conceptId":"math_vectors_reading_a_column_vector_as_movement","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Reading a Column Vector as Movement"}', 2),
  (1094, 324, 'What is the horizontal component of (6, -2)?', 'text', 1, 'The horizontal component is always the top entry.', '{"why":"The first component of a two-dimensional column vector represents horizontal movement.","sol":"Step 1: A column vector is written with horizontal movement first.\nStep 2: The top entry is 6.\nStep 3: Therefore the horizontal component is 6.","steps":["Step 1: A column vector is written with horizontal movement first.","Step 2: The top entry is 6.","Step 3: Therefore the horizontal component is 6."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 0),
  (1095, 324, 'What is the vertical component of (-3, 8)?', 'text', 1, 'The vertical component is the bottom entry.', '{"why":"The second component represents vertical movement.","sol":"Step 1: The bottom entry represents vertical movement.\nStep 2: The bottom entry is 8.\nStep 3: Therefore the vertical component is 8.","steps":["Step 1: The bottom entry represents vertical movement.","Step 2: The bottom entry is 8.","Step 3: Therefore the vertical component is 8."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 1),
  (1096, 324, 'A vector has horizontal component -7 and vertical component -5. Write it as a column vector.', 'text', 1, 'Put horizontal first and vertical second.', '{"why":"Column-vector notation places the horizontal component above the vertical component.","sol":"Step 1: Horizontal component = -7.\nStep 2: Vertical component = -5.\nStep 3: Place -7 on top and -5 underneath.","steps":["Step 1: Horizontal component = -7.","Step 2: Vertical component = -5.","Step 3: Place -7 on top and -5 underneath."],"options":[],"conceptId":"math_vectors_horizontal_and_vertical_components","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Horizontal and Vertical Components"}', 2),
  (1097, 325, 'A vector moves 8 units right and 5 units up. Write its column vector.', 'text', 1, 'Both directions are positive.', '{"why":"The geometric movement is converted directly into horizontal and vertical components.","sol":"Step 1: Right gives horizontal component +8.\nStep 2: Up gives vertical component +5.\nStep 3: Put horizontal first and vertical second.","steps":["Step 1: Right gives horizontal component +8.","Step 2: Up gives vertical component +5.","Step 3: Put horizontal first and vertical second."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 0),
  (1098, 325, 'A vector moves 4 units left and 6 units down. Write its column vector.', 'text', 1, 'Both left and down have negative signs.', '{"why":"Left and down represent negative movement on the coordinate plane.","sol":"Step 1: Left gives horizontal component -4.\nStep 2: Down gives vertical component -6.\nStep 3: Therefore the column vector is (-4, -6).","steps":["Step 1: Left gives horizontal component -4.","Step 2: Down gives vertical component -6.","Step 3: Therefore the column vector is (-4, -6)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 1),
  (1099, 325, 'A vector moves 9 units right and 3 units down. Write its column vector.', 'text', 1, 'Right is positive; down is negative.', '{"why":"The signs record the direction of each component.","sol":"Step 1: Horizontal component = +9.\nStep 2: Vertical component = -3.\nStep 3: Therefore the vector is (9, -3).","steps":["Step 1: Horizontal component = +9.","Step 2: Vertical component = -3.","Step 3: Therefore the vector is (9, -3)."],"options":[],"conceptId":"math_vectors_representing_a_geometric_vector_as_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Representing a Geometric Vector as a Column Vector"}', 2),
  (1100, 326, 'Find the column vector from A(2, 1) to B(7, 4).', 'text', 1, 'Calculate B − A, coordinate by coordinate.', '{"why":"The vector records the change from the starting point to the destination.","sol":"Step 1: Horizontal change = 7 - 2 = 5.\nStep 2: Vertical change = 4 - 1 = 3.\nStep 3: Therefore the vector is (5, 3).","steps":["Step 1: Horizontal change = 7 - 2 = 5.","Step 2: Vertical change = 4 - 1 = 3.","Step 3: Therefore the vector is (5, 3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 0),
  (1101, 326, 'Find the column vector from P(6, 5) to Q(2, 1).', 'text', 1, 'Use final coordinate minus starting coordinate.', '{"why":"Negative components show that the movement is left and down.","sol":"Step 1: Horizontal change = 2 - 6 = -4.\nStep 2: Vertical change = 1 - 5 = -4.\nStep 3: Therefore the vector is (-4, -4).","steps":["Step 1: Horizontal change = 2 - 6 = -4.","Step 2: Vertical change = 1 - 5 = -4.","Step 3: Therefore the vector is (-4, -4)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 1),
  (1102, 326, 'Find the column vector from C(-3, 2) to D(4, -1).', 'text', 1, 'Subtract C''s coordinates from D''s coordinates.', '{"why":"The vector describes the exact horizontal and vertical changes needed to move from C to D.","sol":"Step 1: Horizontal change = 4 - (-3) = 7.\nStep 2: Vertical change = -1 - 2 = -3.\nStep 3: Therefore the vector is (7, -3).","steps":["Step 1: Horizontal change = 4 - (-3) = 7.","Step 2: Vertical change = -1 - 2 = -3.","Step 3: Therefore the vector is (7, -3)."],"options":[],"conceptId":"math_vectors_finding_the_column_vector_between_two_points","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Column Vector Between Two Points"}', 2),
  (1103, 327, 'What is the position vector of point A called if A is any point on a Cartesian plane?', 'text', 1, 'A position vector starts at the origin.', '{"why":"A position vector of A is the vector drawn from the origin O to A.","sol":"Step 1: The origin is O.\nStep 2: The position vector must start at O.\nStep 3: It ends at A.\nStep 4: Therefore the position vector is OA.","steps":["Step 1: The origin is O.","Step 2: The position vector must start at O.","Step 3: It ends at A.","Step 4: Therefore the position vector is OA."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 0),
  (1104, 327, 'Point B is at (-2, 4). Which vector represents its position vector?', 'text', 1, 'Start at O and finish at B.', '{"why":"The position vector of a point always runs from the origin to that point.","sol":"Step 1: The starting point is the origin O.\nStep 2: The ending point is B.\nStep 3: Therefore the position vector is OB.","steps":["Step 1: The starting point is the origin O.","Step 2: The ending point is B.","Step 3: Therefore the position vector is OB."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 1),
  (1105, 327, 'Point C is at (5, -3). Explain what OC represents.', 'text', 1, 'Think about where the vector starts and finishes.', '{"why":"A position vector describes the location of its endpoint relative to the origin.","sol":"Step 1: OC starts at the origin O.\nStep 2: It finishes at point C.\nStep 3: Therefore it describes the position of C relative to the origin.","steps":["Step 1: OC starts at the origin O.","Step 2: It finishes at point C.","Step 3: Therefore it describes the position of C relative to the origin."],"options":[],"conceptId":"math_vectors_meaning_of_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of a Position Vector"}', 2),
  (1106, 328, 'A = (6, 4). Find OA.', 'text', 1, 'Use the coordinates directly.', '{"why":"The coordinates of A are the components of its position vector.","sol":"Step 1: A = (6, 4).\nStep 2: The x-coordinate is 6.\nStep 3: The y-coordinate is 4.\nStep 4: Therefore OA = (6, 4).","steps":["Step 1: A = (6, 4).","Step 2: The x-coordinate is 6.","Step 3: The y-coordinate is 4.","Step 4: Therefore OA = (6, 4)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 0),
  (1107, 328, 'B = (-5, 3). Find OB.', 'text', 1, 'Keep the negative sign.', '{"why":"The x-coordinate -5 means the vector moves 5 units to the left.","sol":"Step 1: B = (-5, 3).\nStep 2: The horizontal component is -5.\nStep 3: The vertical component is 3.\nStep 4: Therefore OB = (-5, 3).","steps":["Step 1: B = (-5, 3).","Step 2: The horizontal component is -5.","Step 3: The vertical component is 3.","Step 4: Therefore OB = (-5, 3)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 1),
  (1108, 328, 'C = (2, -7). Find OC.', 'text', 1, 'The negative number is the vertical component.', '{"why":"The coordinates directly give the horizontal and vertical components of the position vector.","sol":"Step 1: C = (2, -7).\nStep 2: The horizontal component is 2.\nStep 3: The vertical component is -7.\nStep 4: Therefore OC = (2, -7).","steps":["Step 1: C = (2, -7).","Step 2: The horizontal component is 2.","Step 3: The vertical component is -7.","Step 4: Therefore OC = (2, -7)."],"options":[],"conceptId":"math_vectors_finding_a_position_vector_from_coordinates","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Position Vector from Coordinates"}', 2),
  (1109, 329, 'OA = (5, 8). Find the coordinates of A.', 'text', 1, 'The two components become the two coordinates.', '{"why":"The components of a position vector give the coordinates of its endpoint.","sol":"Step 1: The first component is 5, so x = 5.\nStep 2: The second component is 8, so y = 8.\nStep 3: Therefore A = (5, 8).","steps":["Step 1: The first component is 5, so x = 5.","Step 2: The second component is 8, so y = 8.","Step 3: Therefore A = (5, 8)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 0),
  (1110, 329, 'OB = (-3, 7). Find the coordinates of B.', 'text', 1, 'Keep the negative x-coordinate.', '{"why":"The negative first component means B lies to the left of the origin.","sol":"Step 1: The first component is -3.\nStep 2: The second component is 7.\nStep 3: Therefore B = (-3, 7).","steps":["Step 1: The first component is -3.","Step 2: The second component is 7.","Step 3: Therefore B = (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 1),
  (1111, 329, 'OC = (-4, -2). Find the coordinates of C.', 'text', 1, 'Both components are negative.', '{"why":"Both negative components are retained because they describe C''s position relative to the origin.","sol":"Step 1: The first component is -4.\nStep 2: The second component is -2.\nStep 3: Therefore C = (-4, -2).","steps":["Step 1: The first component is -4.","Step 2: The second component is -2.","Step 3: Therefore C = (-4, -2)."],"options":[],"conceptId":"math_vectors_finding_coordinates_from_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding Coordinates from a Position Vector"}', 2),
  (1112, 330, 'A = (1, 4) and B = (6, 9). Find AB.', 'text', 1, 'Use AB = OB - OA.', '{"why":"The vector from A to B is found by subtracting A''s position vector from B''s.","sol":"Step 1: OA = (1, 4).\nStep 2: OB = (6, 9).\nStep 3: AB = OB - OA.\nStep 4: AB = (6, 9) - (1, 4).\nStep 5: Horizontal: 6 - 1 = 5.\nStep 6: Vertical: 9 - 4 = 5.\nStep 7: Therefore AB = (5, 5).","steps":["Step 1: OA = (1, 4).","Step 2: OB = (6, 9).","Step 3: AB = OB - OA.","Step 4: AB = (6, 9) - (1, 4).","Step 5: Horizontal: 6 - 1 = 5.","Step 6: Vertical: 9 - 4 = 5.","Step 7: Therefore AB = (5, 5)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 0),
  (1113, 330, 'A = (-2, 5) and B = (4, 1). Find AB.', 'text', 1, 'Subtract (-2, 5) from (4, 1).', '{"why":"The positive horizontal component means right, while the negative vertical component means down.","sol":"Step 1: OA = (-2, 5).\nStep 2: OB = (4, 1).\nStep 3: AB = OB - OA.\nStep 4: AB = (4, 1) - (-2, 5).\nStep 5: Horizontal: 4 - (-2) = 6.\nStep 6: Vertical: 1 - 5 = -4.\nStep 7: Therefore AB = (6, -4).","steps":["Step 1: OA = (-2, 5).","Step 2: OB = (4, 1).","Step 3: AB = OB - OA.","Step 4: AB = (4, 1) - (-2, 5).","Step 5: Horizontal: 4 - (-2) = 6.","Step 6: Vertical: 1 - 5 = -4.","Step 7: Therefore AB = (6, -4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 1),
  (1114, 330, 'A = (5, -1) and B = (-2, 3). Find AB.', 'text', 1, 'Destination minus starting point.', '{"why":"The vector moves 7 units left and 4 units up from A to B.","sol":"Step 1: OA = (5, -1).\nStep 2: OB = (-2, 3).\nStep 3: AB = OB - OA.\nStep 4: AB = (-2, 3) - (5, -1).\nStep 5: Horizontal: -2 - 5 = -7.\nStep 6: Vertical: 3 - (-1) = 4.\nStep 7: Therefore AB = (-7, 4).","steps":["Step 1: OA = (5, -1).","Step 2: OB = (-2, 3).","Step 3: AB = OB - OA.","Step 4: AB = (-2, 3) - (5, -1).","Step 5: Horizontal: -2 - 5 = -7.","Step 6: Vertical: 3 - (-1) = 4.","Step 7: Therefore AB = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_a_vector_between_two_points_using_position_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Vector Between Two Points Using Position Vectors"}', 2),
  (1115, 331, 'A = (1, 2) and AB = (3, 4). Find B.', 'text', 1, 'Use OB = OA + AB.', '{"why":"Starting at A and moving by AB gives the position of B.","sol":"Step 1: OA = (1, 2).\nStep 2: AB = (3, 4).\nStep 3: OB = OA + AB.\nStep 4: OB = (1, 2) + (3, 4).\nStep 5: Horizontal: 1 + 3 = 4.\nStep 6: Vertical: 2 + 4 = 6.\nStep 7: Therefore B = (4, 6).","steps":["Step 1: OA = (1, 2).","Step 2: AB = (3, 4).","Step 3: OB = OA + AB.","Step 4: OB = (1, 2) + (3, 4).","Step 5: Horizontal: 1 + 3 = 4.","Step 6: Vertical: 2 + 4 = 6.","Step 7: Therefore B = (4, 6)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 0),
  (1116, 331, 'A = (-2, 5) and AB = (6, -3). Find B.', 'text', 1, 'Add the components of OA and AB.', '{"why":"The movement AB is applied to the starting position A.","sol":"Step 1: OA = (-2, 5).\nStep 2: AB = (6, -3).\nStep 3: OB = OA + AB.\nStep 4: OB = (-2, 5) + (6, -3).\nStep 5: Horizontal: -2 + 6 = 4.\nStep 6: Vertical: 5 + (-3) = 2.\nStep 7: Therefore B = (4, 2).","steps":["Step 1: OA = (-2, 5).","Step 2: AB = (6, -3).","Step 3: OB = OA + AB.","Step 4: OB = (-2, 5) + (6, -3).","Step 5: Horizontal: -2 + 6 = 4.","Step 6: Vertical: 5 + (-3) = 2.","Step 7: Therefore B = (4, 2)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 1),
  (1117, 331, 'A = (8, -4) and AB = (-5, 7). Find B.', 'text', 1, 'Remember that adding a negative number means moving in the opposite direction.', '{"why":"Starting at (8, -4), moving 5 units left and 7 units up reaches (3, 3).","sol":"Step 1: OA = (8, -4).\nStep 2: AB = (-5, 7).\nStep 3: OB = OA + AB.\nStep 4: OB = (8, -4) + (-5, 7).\nStep 5: Horizontal: 8 + (-5) = 3.\nStep 6: Vertical: -4 + 7 = 3.\nStep 7: Therefore B = (3, 3).","steps":["Step 1: OA = (8, -4).","Step 2: AB = (-5, 7).","Step 3: OB = OA + AB.","Step 4: OB = (8, -4) + (-5, 7).","Step 5: Horizontal: 8 + (-5) = 3.","Step 6: Vertical: -4 + 7 = 3.","Step 7: Therefore B = (3, 3)."],"options":[],"conceptId":"math_vectors_finding_an_unknown_point_using_a_vector_and_a_position_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding an Unknown Point Using a Vector and a Position Vector"}', 2),
  (1118, 332, 'A vector represents 4 units to the right and another represents 3 units to the right. What is their resultant movement?', 'text', 1, 'Both movements are in the same direction.', '{"why":"Two movements in the same direction combine by adding their magnitudes.","sol":"Step 1: The first movement is 4 units right.\nStep 2: The second movement is 3 units right.\nStep 3: Add the two movements: 4 + 3 = 7.\nStep 4: Therefore the resultant movement is 7 units right.","steps":["Step 1: The first movement is 4 units right.","Step 2: The second movement is 3 units right.","Step 3: Add the two movements: 4 + 3 = 7.","Step 4: Therefore the resultant movement is 7 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 0),
  (1119, 332, 'A vector represents 5 units upward and another represents 6 units upward. Find the resultant movement.', 'text', 1, 'Both vectors point upward.', '{"why":"The movements have the same direction, so their magnitudes are added.","sol":"Step 1: First movement = 5 units up.\nStep 2: Second movement = 6 units up.\nStep 3: Add them: 5 + 6 = 11.\nStep 4: Therefore the resultant movement is 11 units upward.","steps":["Step 1: First movement = 5 units up.","Step 2: Second movement = 6 units up.","Step 3: Add them: 5 + 6 = 11.","Step 4: Therefore the resultant movement is 11 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 1),
  (1120, 332, 'A movement of 3 units right is followed by a movement of 4 units up. Are the two movements added by simply calculating 3 + 4 = 7 units in one direction?', 'text', 1, 'The two movements are in different directions.', '{"why":"Vectors have direction, so movements in different directions cannot be treated like ordinary scalar quantities.","sol":"Step 1: The first movement is horizontal.\nStep 2: The second movement is vertical.\nStep 3: They therefore affect different components of the movement.\nStep 4: The resultant must preserve both the horizontal and vertical parts.","steps":["Step 1: The first movement is horizontal.","Step 2: The second movement is vertical.","Step 3: They therefore affect different components of the movement.","Step 4: The resultant must preserve both the horizontal and vertical parts."],"options":[],"conceptId":"math_vectors_meaning_of_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Addition"}', 2),
  (1121, 333, 'Vector a is 5 units right and vector b is 2 units right. Find a + b.', 'text', 1, 'Join the vectors head-to-tail.', '{"why":"The two vectors point in the same direction, so their movements combine directly.","sol":"Step 1: a moves 5 units right.\nStep 2: b moves 2 units right.\nStep 3: The total movement is 5 + 2 = 7 units right.\nStep 4: Therefore a + b = 7 units right.","steps":["Step 1: a moves 5 units right.","Step 2: b moves 2 units right.","Step 3: The total movement is 5 + 2 = 7 units right.","Step 4: Therefore a + b = 7 units right."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 0),
  (1122, 333, 'Vector a is 3 units up and vector b is 4 units up. Find a + b.', 'text', 1, 'Add the two upward movements.', '{"why":"The two vectors have the same direction.","sol":"Step 1: a moves 3 units up.\nStep 2: b moves 4 units up.\nStep 3: Total upward movement = 3 + 4 = 7.\nStep 4: Therefore a + b = 7 units up.","steps":["Step 1: a moves 3 units up.","Step 2: b moves 4 units up.","Step 3: Total upward movement = 3 + 4 = 7.","Step 4: Therefore a + b = 7 units up."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 1),
  (1123, 333, 'Vector a is 6 units right and vector b is 2 units up. Describe the resultant a + b.', 'text', 1, 'Keep both movements.', '{"why":"The resultant contains the combined horizontal and vertical movements.","sol":"Step 1: a contributes 6 units horizontally.\nStep 2: b contributes 2 units vertically.\nStep 3: Therefore the resultant has horizontal component 6.\nStep 4: The resultant has vertical component 2.\nStep 5: So a + b = (6, 2).","steps":["Step 1: a contributes 6 units horizontally.","Step 2: b contributes 2 units vertically.","Step 3: Therefore the resultant has horizontal component 6.","Step 4: The resultant has vertical component 2.","Step 5: So a + b = (6, 2)."],"options":[],"conceptId":"math_vectors_geometric_addition_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Addition of Vectors"}', 2),
  (1124, 334, 'Add (2, 4) and (3, 5).', 'text', 1, 'Add horizontal components together and vertical components together.', '{"why":"Corresponding vector components are added separately.","sol":"Step 1: Horizontal: 2 + 3 = 5.\nStep 2: Vertical: 4 + 5 = 9.\nStep 3: Therefore the resultant is (5, 9).","steps":["Step 1: Horizontal: 2 + 3 = 5.","Step 2: Vertical: 4 + 5 = 9.","Step 3: Therefore the resultant is (5, 9)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 0),
  (1125, 334, 'Add (-3, 5) and (7, 2).', 'text', 1, 'Be careful with the negative first component.', '{"why":"The horizontal components combine to give 4 and the vertical components combine to give 7.","sol":"Step 1: Horizontal: -3 + 7 = 4.\nStep 2: Vertical: 5 + 2 = 7.\nStep 3: Therefore the resultant is (4, 7).","steps":["Step 1: Horizontal: -3 + 7 = 4.","Step 2: Vertical: 5 + 2 = 7.","Step 3: Therefore the resultant is (4, 7)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 1),
  (1126, 334, 'Add (8, -4) and (-3, 6).', 'text', 1, 'Treat -4 and -3 as signed numbers.', '{"why":"Vector components are ordinary signed numbers, so normal integer addition applies to each component.","sol":"Step 1: Horizontal: 8 + (-3) = 5.\nStep 2: Vertical: -4 + 6 = 2.\nStep 3: Therefore the resultant is (5, 2).","steps":["Step 1: Horizontal: 8 + (-3) = 5.","Step 2: Vertical: -4 + 6 = 2.","Step 3: Therefore the resultant is (5, 2)."],"options":[],"conceptId":"math_vectors_column_vector_addition","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Addition"}', 2),
  (1127, 335, 'Find the resultant of (4, 2) and (3, 5).', 'text', 1, 'Add the two vectors component by component.', '{"why":"The resultant contains the total horizontal and vertical movement.","sol":"Step 1: Horizontal: 4 + 3 = 7.\nStep 2: Vertical: 2 + 5 = 7.\nStep 3: Therefore the resultant is (7, 7).","steps":["Step 1: Horizontal: 4 + 3 = 7.","Step 2: Vertical: 2 + 5 = 7.","Step 3: Therefore the resultant is (7, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 0),
  (1128, 335, 'Find the resultant of (-5, 3) and (2, 4).', 'text', 1, 'Keep the negative sign on the first horizontal component.', '{"why":"The total horizontal movement is 3 units left and the total vertical movement is 7 units up.","sol":"Step 1: Horizontal: -5 + 2 = -3.\nStep 2: Vertical: 3 + 4 = 7.\nStep 3: Therefore the resultant is (-3, 7).","steps":["Step 1: Horizontal: -5 + 2 = -3.","Step 2: Vertical: 3 + 4 = 7.","Step 3: Therefore the resultant is (-3, 7)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 1),
  (1129, 335, 'Find the resultant of (1, 2), (3, -1), and (-2, 5).', 'text', 1, 'You can combine the vectors one pair at a time.', '{"why":"Adding the three vectors gives a total movement of 2 units horizontally and 6 units vertically.","sol":"Step 1: First add (1, 2) and (3, -1).\nStep 2: (1, 2) + (3, -1) = (4, 1).\nStep 3: Now add (-2, 5).\nStep 4: (4, 1) + (-2, 5) = (2, 6).\nStep 5: Therefore the resultant is (2, 6).","steps":["Step 1: First add (1, 2) and (3, -1).","Step 2: (1, 2) + (3, -1) = (4, 1).","Step 3: Now add (-2, 5).","Step 4: (4, 1) + (-2, 5) = (2, 6).","Step 5: Therefore the resultant is (2, 6)."],"options":[],"conceptId":"math_vectors_finding_a_resultant_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding a Resultant Vector"}', 2),
  (1130, 336, 'AB = (4, 2) and BC = (3, 5). Find AC.', 'text', 1, 'To go from A to C, follow A to B and then B to C.', '{"why":"The route from A to C consists of the movement A to B followed by B to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (4, 2) + (3, 5).\nStep 3: Horizontal: 4 + 3 = 7.\nStep 4: Vertical: 2 + 5 = 7.\nStep 5: Therefore AC = (7, 7).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (4, 2) + (3, 5).","Step 3: Horizontal: 4 + 3 = 7.","Step 4: Vertical: 2 + 5 = 7.","Step 5: Therefore AC = (7, 7)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 0),
  (1131, 336, 'AB = (-2, 4) and BC = (5, -1). Find AC.', 'text', 1, 'Add the two consecutive vectors.', '{"why":"The resultant combines both movements along the route from A to C.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (-2, 4) + (5, -1).\nStep 3: Horizontal: -2 + 5 = 3.\nStep 4: Vertical: 4 + (-1) = 3.\nStep 5: Therefore AC = (3, 3).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (-2, 4) + (5, -1).","Step 3: Horizontal: -2 + 5 = 3.","Step 4: Vertical: 4 + (-1) = 3.","Step 5: Therefore AC = (3, 3)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 1),
  (1132, 336, 'In triangle ABC, AB = (6, -2) and BC = (-3, 7). Find AC.', 'text', 1, 'Travel from A to B and then from B to C.', '{"why":"Adding consecutive vectors gives the direct resultant from the first point to the final point.","sol":"Step 1: AC = AB + BC.\nStep 2: AC = (6, -2) + (-3, 7).\nStep 3: Horizontal: 6 + (-3) = 3.\nStep 4: Vertical: -2 + 7 = 5.\nStep 5: Therefore AC = (3, 5).","steps":["Step 1: AC = AB + BC.","Step 2: AC = (6, -2) + (-3, 7).","Step 3: Horizontal: 6 + (-3) = 3.","Step 4: Vertical: -2 + 7 = 5.","Step 5: Therefore AC = (3, 5)."],"options":[],"conceptId":"math_vectors_vector_addition_in_geometrical_problems","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Addition in Geometrical Problems"}', 2),
  (1133, 337, 'A vector is 9 units right and another is 4 units right. Find the difference.', 'text', 1, 'Subtract the second movement from the first.', '{"why":"Subtracting the smaller rightward movement from the larger one leaves 5 units right.","sol":"Step 1: First movement = 9 units right.\nStep 2: Second movement = 4 units right.\nStep 3: 9 - 4 = 5.\nStep 4: Therefore the difference is 5 units right.","steps":["Step 1: First movement = 9 units right.","Step 2: Second movement = 4 units right.","Step 3: 9 - 4 = 5.","Step 4: Therefore the difference is 5 units right."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 0),
  (1134, 337, 'A vector is 10 units upward and another is 6 units upward. Find the difference.', 'text', 1, 'Both movements are vertical.', '{"why":"The vertical movement is reduced by 6 units.","sol":"Step 1: First movement = 10 units up.\nStep 2: Second movement = 6 units up.\nStep 3: 10 - 6 = 4.\nStep 4: Therefore the difference is 4 units upward.","steps":["Step 1: First movement = 10 units up.","Step 2: Second movement = 6 units up.","Step 3: 10 - 6 = 4.","Step 4: Therefore the difference is 4 units upward."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 1),
  (1135, 337, 'Find (8, 6) - (3, 2).', 'text', 1, 'Subtract corresponding components.', '{"why":"Vector subtraction acts separately on the horizontal and vertical components.","sol":"Step 1: Horizontal: 8 - 3 = 5.\nStep 2: Vertical: 6 - 2 = 4.\nStep 3: Therefore the difference is (5, 4).","steps":["Step 1: Horizontal: 8 - 3 = 5.","Step 2: Vertical: 6 - 2 = 4.","Step 3: Therefore the difference is (5, 4)."],"options":[],"conceptId":"math_vectors_meaning_of_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Vector Subtraction"}', 2),
  (1136, 338, 'Find the negative of (5, 3).', 'text', 1, 'Change the sign of both components.', '{"why":"Changing both signs reverses both horizontal and vertical directions.","sol":"Step 1: The vector is (5, 3).\nStep 2: Change 5 to -5.\nStep 3: Change 3 to -3.\nStep 4: Therefore the negative vector is (-5, -3).","steps":["Step 1: The vector is (5, 3).","Step 2: Change 5 to -5.","Step 3: Change 3 to -3.","Step 4: Therefore the negative vector is (-5, -3)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 0),
  (1137, 338, 'Find the negative of (-4, 7).', 'text', 1, 'Both signs must change.', '{"why":"The negative vector points in the exact opposite direction.","sol":"Step 1: -4 becomes 4.\nStep 2: 7 becomes -7.\nStep 3: Therefore the negative vector is (4, -7).","steps":["Step 1: -4 becomes 4.","Step 2: 7 becomes -7.","Step 3: Therefore the negative vector is (4, -7)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 1),
  (1138, 338, 'If a = (2, -6), find -a.', 'text', 1, 'Reverse the sign of each component.', '{"why":"Both components change sign when a vector is reversed.","sol":"Step 1: a = (2, -6).\nStep 2: 2 becomes -2.\nStep 3: -6 becomes 6.\nStep 4: Therefore -a = (-2, 6).","steps":["Step 1: a = (2, -6).","Step 2: 2 becomes -2.","Step 3: -6 becomes 6.","Step 4: Therefore -a = (-2, 6)."],"options":[],"conceptId":"math_vectors_negative_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Negative Vectors"}', 2),
  (1139, 339, 'a = (7, 4) and b = (2, 1). Find a - b using the negative of b.', 'text', 1, 'First find -b.', '{"why":"Subtracting b is equivalent to adding the vector pointing opposite to b.","sol":"Step 1: b = (2, 1).\nStep 2: -b = (-2, -1).\nStep 3: a - b = a + (-b).\nStep 4: (7, 4) + (-2, -1) = (5, 3).\nStep 5: Therefore a - b = (5, 3).","steps":["Step 1: b = (2, 1).","Step 2: -b = (-2, -1).","Step 3: a - b = a + (-b).","Step 4: (7, 4) + (-2, -1) = (5, 3).","Step 5: Therefore a - b = (5, 3)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 0),
  (1140, 339, 'a = (6, 2) and b = (-3, 4). Find a - b.', 'text', 1, 'Reverse both components of b first.', '{"why":"The negative of (-3, 4) is (3, -4), which is then added to a.","sol":"Step 1: b = (-3, 4).\nStep 2: -b = (3, -4).\nStep 3: a - b = a + (-b).\nStep 4: (6, 2) + (3, -4) = (9, -2).\nStep 5: Therefore a - b = (9, -2).","steps":["Step 1: b = (-3, 4).","Step 2: -b = (3, -4).","Step 3: a - b = a + (-b).","Step 4: (6, 2) + (3, -4) = (9, -2).","Step 5: Therefore a - b = (9, -2)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 1),
  (1141, 339, 'a = (-4, 5) and b = (2, -3). Find a - b.', 'text', 1, 'Change the signs of b before adding.', '{"why":"Subtracting b means adding its opposite vector.","sol":"Step 1: b = (2, -3).\nStep 2: -b = (-2, 3).\nStep 3: a - b = a + (-b).\nStep 4: (-4, 5) + (-2, 3) = (-6, 8).\nStep 5: Therefore a - b = (-6, 8).","steps":["Step 1: b = (2, -3).","Step 2: -b = (-2, 3).","Step 3: a - b = a + (-b).","Step 4: (-4, 5) + (-2, 3) = (-6, 8).","Step 5: Therefore a - b = (-6, 8)."],"options":[],"conceptId":"math_vectors_geometric_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Geometric Vector Subtraction"}', 2),
  (1142, 340, 'Find (9, 7) - (4, 3).', 'text', 1, 'Subtract corresponding components.', '{"why":"Each component is subtracted from the corresponding component.","sol":"Step 1: Horizontal: 9 - 4 = 5.\nStep 2: Vertical: 7 - 3 = 4.\nStep 3: Therefore the answer is (5, 4).","steps":["Step 1: Horizontal: 9 - 4 = 5.","Step 2: Vertical: 7 - 3 = 4.","Step 3: Therefore the answer is (5, 4)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 0),
  (1143, 340, 'Find (5, 2) - (-3, 4).', 'text', 1, 'Remember that subtracting a negative number becomes addition.', '{"why":"5 - (-3) becomes 5 + 3, while the vertical component remains 2 - 4.","sol":"Step 1: Horizontal: 5 - (-3) = 8.\nStep 2: Vertical: 2 - 4 = -2.\nStep 3: Therefore the answer is (8, -2).","steps":["Step 1: Horizontal: 5 - (-3) = 8.","Step 2: Vertical: 2 - 4 = -2.","Step 3: Therefore the answer is (8, -2)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 1),
  (1144, 340, 'Find (-6, 3) - (2, -5).', 'text', 1, 'Work on each component separately.', '{"why":"Subtracting -5 from 3 gives 8.","sol":"Step 1: Horizontal: -6 - 2 = -8.\nStep 2: Vertical: 3 - (-5) = 8.\nStep 3: Therefore the answer is (-8, 8).","steps":["Step 1: Horizontal: -6 - 2 = -8.","Step 2: Vertical: 3 - (-5) = 8.","Step 3: Therefore the answer is (-8, 8)."],"options":[],"conceptId":"math_vectors_column_vector_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Column Vector Subtraction"}', 2),
  (1145, 341, 'a = (7, 5) and b = (2, 1). Find a - b.', 'text', 1, 'Start with a.', '{"why":"The requested order is a minus b.","sol":"Step 1: a - b = (7, 5) - (2, 1).\nStep 2: Horizontal: 7 - 2 = 5.\nStep 3: Vertical: 5 - 1 = 4.\nStep 4: Therefore a - b = (5, 4).","steps":["Step 1: a - b = (7, 5) - (2, 1).","Step 2: Horizontal: 7 - 2 = 5.","Step 3: Vertical: 5 - 1 = 4.","Step 4: Therefore a - b = (5, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 0),
  (1146, 341, 'a = (-4, 6) and b = (3, 2). Find a - b.', 'text', 1, 'Subtract the components of b from the corresponding components of a.', '{"why":"The negative horizontal component results from -4 - 3.","sol":"Step 1: a - b = (-4, 6) - (3, 2).\nStep 2: Horizontal: -4 - 3 = -7.\nStep 3: Vertical: 6 - 2 = 4.\nStep 4: Therefore a - b = (-7, 4).","steps":["Step 1: a - b = (-4, 6) - (3, 2).","Step 2: Horizontal: -4 - 3 = -7.","Step 3: Vertical: 6 - 2 = 4.","Step 4: Therefore a - b = (-7, 4)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 1),
  (1147, 341, 'a = (6, -2) and b = (-3, 5). Find a - b.', 'text', 1, 'Be especially careful with the two negative numbers.', '{"why":"Subtracting the negative horizontal component gives 9, while the vertical components give -7.","sol":"Step 1: a - b = (6, -2) - (-3, 5).\nStep 2: Horizontal: 6 - (-3) = 9.\nStep 3: Vertical: -2 - 5 = -7.\nStep 4: Therefore a - b = (9, -7).","steps":["Step 1: a - b = (6, -2) - (-3, 5).","Step 2: Horizontal: 6 - (-3) = 9.","Step 3: Vertical: -2 - 5 = -7.","Step 4: Therefore a - b = (9, -7)."],"options":[],"conceptId":"math_vectors_finding_the_difference_between_two_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Finding the Difference Between Two Vectors"}', 2),
  (1148, 342, 'Given a = (5, 2), find 3a.', 'text', 1, 'Multiply both components by 3.', '{"why":"A scalar multiplies every component of the vector.","sol":"Step 1: Start with a = (5, 2).\nStep 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).\nStep 3: Calculate: 3a = (15, 6).","steps":["Step 1: Start with a = (5, 2).","Step 2: Multiply each component by 3: 3a = (3 × 5, 3 × 2).","Step 3: Calculate: 3a = (15, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 0),
  (1149, 342, 'Given b = (-4, 3), find 2b.', 'text', 1, 'Multiply -4 and 3 separately by 2.', '{"why":"Both components are multiplied by the scalar.","sol":"Step 1: Start with b = (-4, 3).\nStep 2: 2b = (2 × -4, 2 × 3).\nStep 3: Therefore 2b = (-8, 6).","steps":["Step 1: Start with b = (-4, 3).","Step 2: 2b = (2 × -4, 2 × 3).","Step 3: Therefore 2b = (-8, 6)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 1),
  (1150, 342, 'Given c = (6, -5), find 4c.', 'text', 1, 'Multiply 6 and -5 by 4.', '{"why":"Scalar multiplication applies to every component.","sol":"Step 1: 4c = (4 × 6, 4 × -5).\nStep 2: 4 × 6 = 24.\nStep 3: 4 × -5 = -20.\nStep 4: Therefore 4c = (24, -20).","steps":["Step 1: 4c = (4 × 6, 4 × -5).","Step 2: 4 × 6 = 24.","Step 3: 4 × -5 = -20.","Step 4: Therefore 4c = (24, -20)."],"options":[],"conceptId":"math_vectors_meaning_of_scalar_multiplication","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Meaning of Scalar Multiplication"}', 2),
  (1151, 343, 'Is (10, 15) a scalar multiple of (2, 3)?', 'text', 1, 'Divide corresponding components.', '{"why":"Both components are multiplied by the same scalar, 5.","sol":"Step 1: 10 ÷ 2 = 5.\nStep 2: 15 ÷ 3 = 5.\nStep 3: The same scalar is obtained.\nStep 4: Therefore (10, 15) = 5(2, 3).","steps":["Step 1: 10 ÷ 2 = 5.","Step 2: 15 ÷ 3 = 5.","Step 3: The same scalar is obtained.","Step 4: Therefore (10, 15) = 5(2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 0),
  (1152, 343, 'Is (-8, 12) a scalar multiple of (-2, 3)?', 'text', 1, 'Find the multiplier from each component.', '{"why":"Both components have the same scalar multiplier.","sol":"Step 1: -8 ÷ -2 = 4.\nStep 2: 12 ÷ 3 = 4.\nStep 3: The same multiplier is obtained.\nStep 4: Therefore (-8, 12) = 4(-2, 3).","steps":["Step 1: -8 ÷ -2 = 4.","Step 2: 12 ÷ 3 = 4.","Step 3: The same multiplier is obtained.","Step 4: Therefore (-8, 12) = 4(-2, 3)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 1),
  (1153, 343, 'Is (12, 15) a scalar multiple of (3, 4)?', 'text', 1, 'Compare 12 ÷ 3 with 15 ÷ 4.', '{"why":"A scalar multiple requires one common multiplier.","sol":"Step 1: 12 ÷ 3 = 4.\nStep 2: 15 ÷ 4 = 3.75.\nStep 3: The multipliers are different.\nStep 4: Therefore (12, 15) is not a scalar multiple of (3, 4).","steps":["Step 1: 12 ÷ 3 = 4.","Step 2: 15 ÷ 4 = 3.75.","Step 3: The multipliers are different.","Step 4: Therefore (12, 15) is not a scalar multiple of (3, 4)."],"options":[],"conceptId":"math_vectors_recognising_a_scalar_multiple","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Recognising a Scalar Multiple"}', 2),
  (1154, 344, 'Simplify 4a + 3a.', 'text', 1, 'Both terms contain a.', '{"why":"Like vector terms can be combined by adding their scalar coefficients.","sol":"Step 1: The terms are like terms because both contain a.\nStep 2: Add the coefficients: 4 + 3 = 7.\nStep 3: Therefore 4a + 3a = 7a.","steps":["Step 1: The terms are like terms because both contain a.","Step 2: Add the coefficients: 4 + 3 = 7.","Step 3: Therefore 4a + 3a = 7a."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 0),
  (1155, 344, 'Simplify 8b + 5b.', 'text', 1, 'Add 8 and 5.', '{"why":"The vector b remains while its coefficients are added.","sol":"Step 1: Both terms contain b.\nStep 2: 8 + 5 = 13.\nStep 3: Therefore 8b + 5b = 13b.","steps":["Step 1: Both terms contain b.","Step 2: 8 + 5 = 13.","Step 3: Therefore 8b + 5b = 13b."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 1),
  (1156, 344, 'Simplify 2c + 9c.', 'text', 1, 'Treat c as the common vector.', '{"why":"Like vector terms are combined by adding their coefficients.","sol":"Step 1: Both terms contain c.\nStep 2: 2 + 9 = 11.\nStep 3: Therefore 2c + 9c = 11c.","steps":["Step 1: Both terms contain c.","Step 2: 2 + 9 = 11.","Step 3: Therefore 2c + 9c = 11c."],"options":[],"conceptId":"math_vectors_adding_like_vector_terms","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Adding Like Vector Terms"}', 2),
  (1157, 345, 'Find the magnitude of a = (6, 8).', 'text', 1, 'Use |a| = √(x² + y²).', '{"why":"The magnitude is the hypotenuse formed by the two components.","sol":"Step 1: |a| = √(6² + 8²).\nStep 2: |a| = √(36 + 64).\nStep 3: |a| = √100.\nStep 4: |a| = 10.","steps":["Step 1: |a| = √(6² + 8²).","Step 2: |a| = √(36 + 64).","Step 3: |a| = √100.","Step 4: |a| = 10."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 0),
  (1158, 345, 'Find the magnitude of b = (-5, 12).', 'text', 1, 'Remember that (-5)² is positive.', '{"why":"Squaring the negative component makes its contribution positive.","sol":"Step 1: |b| = √((-5)² + 12²).\nStep 2: |b| = √(25 + 144).\nStep 3: |b| = √169.\nStep 4: |b| = 13.","steps":["Step 1: |b| = √((-5)² + 12²).","Step 2: |b| = √(25 + 144).","Step 3: |b| = √169.","Step 4: |b| = 13."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 1),
  (1159, 345, 'Find the magnitude of c = (8, 15).', 'text', 1, 'Square both components, add, then take the square root.', '{"why":"The vector length is obtained from Pythagoras'' theorem.","sol":"Step 1: |c| = √(8² + 15²).\nStep 2: |c| = √(64 + 225).\nStep 3: |c| = √289.\nStep 4: |c| = 17.","steps":["Step 1: |c| = √(8² + 15²).","Step 2: |c| = √(64 + 225).","Step 3: |c| = √289.","Step 4: |c| = 17."],"options":[],"conceptId":"math_vectors_magnitude_from_a_column_vector","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude from a Column Vector"}', 2),
  (1160, 346, 'Find gradient of curve using dy/dx at a point', 'text', 1, 'differentiate then substitute', '{"why":"Gradient of a curve is found using differentiation at a specific point","sol":"Step 1: Start with function y = f(x)\nStep 2: Differentiate to find dy/dx\nStep 3: Substitute the given x-value\nStep 4: Compute gradient at that point","steps":["Step 1: Start with function y = f(x)","Step 2: Differentiate to find dy/dx","Step 3: Substitute the given x-value","Step 4: Compute gradient at that point"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 0),
  (1161, 346, 'Find dy/dx for y = x² and evaluate at x = 3', 'text', 1, 'power rule', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 3\nStep 3: Compute 2 × 3\nStep 4: Get final gradient","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 3","Step 3: Compute 2 × 3","Step 4: Get final gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 1),
  (1162, 346, 'Find gradient of y = 2x + 3', 'text', 1, 'linear function rule', '{"why":"In linear equations, gradient is the coefficient of x","sol":"Step 1: Identify equation y = mx + c\nStep 2: Recognize coefficient of x\nStep 3: Extract m value\nStep 4: State gradient","steps":["Step 1: Identify equation y = mx + c","Step 2: Recognize coefficient of x","Step 3: Extract m value","Step 4: State gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 2),
  (1163, 346, 'Find dy/dx of y = 3x² at x = 2', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = 3x² → dy/dx = 6x\nStep 2: Substitute x = 2\nStep 3: Multiply 6 × 2\nStep 4: Compute gradient","steps":["Step 1: Differentiate y = 3x² → dy/dx = 6x","Step 2: Substitute x = 2","Step 3: Multiply 6 × 2","Step 4: Compute gradient"],"options":[],"conceptId":"math_calculus_gradient_of_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Gradient of a Curve"}', 3),
  (1164, 347, 'Find rate of change of y with respect to x for y = 3x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Rate of change is found using differentiation and substitution","sol":"Step 1: Start with y = 3x²\nStep 2: Differentiate → dy/dx = 6x\nStep 3: Substitute x = 2\nStep 4: Compute 6 × 2\nStep 5: Final value of rate of change","steps":["Step 1: Start with y = 3x²","Step 2: Differentiate → dy/dx = 6x","Step 3: Substitute x = 2","Step 4: Compute 6 × 2","Step 5: Final value of rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 0),
  (1165, 347, 'Find dy/dx for y = 5x at any point', 'text', 1, 'linear rule', '{"why":"Linear functions have constant rate of change equal to slope","sol":"Step 1: Identify y = mx form\nStep 2: Differentiate → dy/dx = 5\nStep 3: Note constant slope\nStep 4: State rate of change","steps":["Step 1: Identify y = mx form","Step 2: Differentiate → dy/dx = 5","Step 3: Note constant slope","Step 4: State rate of change"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 1),
  (1166, 347, 'A car travels distance s = 4t². Find speed at t = 3', 'text', 1, 'differentiate distance', '{"why":"Speed is rate of change of distance with respect to time","sol":"Step 1: Start with s = 4t²\nStep 2: Differentiate → ds/dt = 8t\nStep 3: Substitute t = 3\nStep 4: Compute 8 × 3\nStep 5: Final speed value","steps":["Step 1: Start with s = 4t²","Step 2: Differentiate → ds/dt = 8t","Step 3: Substitute t = 3","Step 4: Compute 8 × 3","Step 5: Final speed value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 2),
  (1167, 347, 'Find rate of change of y = x³ at x = 1', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = x³ → dy/dx = 3x²\nStep 2: Substitute x = 1\nStep 3: Compute 3 × 1²\nStep 4: Final value","steps":["Step 1: Differentiate y = x³ → dy/dx = 3x²","Step 2: Substitute x = 1","Step 3: Compute 3 × 1²","Step 4: Final value"],"options":[],"conceptId":"math_calculus_rate_of_change","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Rate of Change"}', 3),
  (1168, 348, 'Find turning point and determine maximum/minimum for y = -x² + 6x - 5', 'text', 1, 'differentiate and classify', '{"why":"Negative x² means the parabola opens downward, giving a maximum","sol":"Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6\nStep 2: Set dy/dx = 0 → -2x + 6 = 0\nStep 3: Solve → 2x = 6\nStep 4: x = 3\nStep 5: Since coefficient of x² is negative, curve opens downward\nStep 6: Therefore turning point is a maximum","steps":["Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6","Step 2: Set dy/dx = 0 → -2x + 6 = 0","Step 3: Solve → 2x = 6","Step 4: x = 3","Step 5: Since coefficient of x² is negative, curve opens downward","Step 6: Therefore turning point is a maximum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 0),
  (1169, 348, 'Find maximum point of y = -2x² + 8x + 1', 'text', 1, 'dy/dx = 0', '{"why":"Vertex gives highest value because parabola opens downward","sol":"Step 1: Differentiate → dy/dx = -4x + 8\nStep 2: Set dy/dx = 0 → -4x + 8 = 0\nStep 3: Solve → 4x = 8\nStep 4: x = 2\nStep 5: Substitute into original function → y = -2(2²) + 8(2) + 1\nStep 6: y = -8 + 16 + 1 = 9","steps":["Step 1: Differentiate → dy/dx = -4x + 8","Step 2: Set dy/dx = 0 → -4x + 8 = 0","Step 3: Solve → 4x = 8","Step 4: x = 2","Step 5: Substitute into original function → y = -2(2²) + 8(2) + 1","Step 6: y = -8 + 16 + 1 = 9"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 1),
  (1170, 348, 'Find minimum point of y = x² + 8x + 12', 'text', 1, 'complete or differentiate', '{"why":"Positive x² means parabola opens upward giving a minimum","sol":"Step 1: Differentiate → dy/dx = 2x + 8\nStep 2: Set dy/dx = 0 → 2x + 8 = 0\nStep 3: Solve → 2x = -8\nStep 4: x = -4\nStep 5: Substitute into function → y = (-4)² + 8(-4) + 12\nStep 6: y = 16 - 32 + 12 = -4","steps":["Step 1: Differentiate → dy/dx = 2x + 8","Step 2: Set dy/dx = 0 → 2x + 8 = 0","Step 3: Solve → 2x = -8","Step 4: x = -4","Step 5: Substitute into function → y = (-4)² + 8(-4) + 12","Step 6: y = 16 - 32 + 12 = -4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 2),
  (1171, 348, 'Find stationary point of y = x² - 10x + 25 and classify it', 'text', 1, 'perfect square form', '{"why":"Perfect square quadratic always has a minimum vertex","sol":"Step 1: Differentiate → dy/dx = 2x - 10\nStep 2: Set dy/dx = 0 → 2x - 10 = 0\nStep 3: Solve → 2x = 10\nStep 4: x = 5\nStep 5: Substitute → y = 25 - 50 + 25 = 0\nStep 6: Since coefficient of x² is positive, it is a minimum","steps":["Step 1: Differentiate → dy/dx = 2x - 10","Step 2: Set dy/dx = 0 → 2x - 10 = 0","Step 3: Solve → 2x = 10","Step 4: x = 5","Step 5: Substitute → y = 25 - 50 + 25 = 0","Step 6: Since coefficient of x² is positive, it is a minimum"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 3),
  (1172, 348, 'Find maximum value of y = 3x - x²', 'text', 1, 'rearrange quadratic', '{"why":"Negative x² ensures a maximum at vertex","sol":"Step 1: Rewrite y = -x² + 3x\nStep 2: Differentiate → dy/dx = -2x + 3\nStep 3: Set dy/dx = 0 → -2x + 3 = 0\nStep 4: Solve → 2x = 3\nStep 5: x = 3/2\nStep 6: Substitute → y = 3(3/2) - (3/2)²\nStep 7: y = 9/2 - 9/4 = 9/4","steps":["Step 1: Rewrite y = -x² + 3x","Step 2: Differentiate → dy/dx = -2x + 3","Step 3: Set dy/dx = 0 → -2x + 3 = 0","Step 4: Solve → 2x = 3","Step 5: x = 3/2","Step 6: Substitute → y = 3(3/2) - (3/2)²","Step 7: y = 9/2 - 9/4 = 9/4"],"options":[],"conceptId":"math_calculus_maxima_and_minima","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Maxima and Minima"}', 4),
  (1173, 349, 'Find slope of tangent to y = x² at x = 4', 'text', 1, 'differentiate and substitute', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 4\nStep 3: Compute 2 × 4\nStep 4: Final slope value","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 4","Step 3: Compute 2 × 4","Step 4: Final slope value"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 0),
  (1174, 349, 'If tangent slope is 3, what is slope of normal?', 'text', 1, 'negative reciprocal', '{"why":"Perpendicular lines have slopes that multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Use formula slope(normal) = -1/m\nStep 3: Compute -1/3\nStep 4: Final result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Use formula slope(normal) = -1/m","Step 3: Compute -1/3","Step 4: Final result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 1),
  (1175, 349, 'Find equation of tangent to y = x² at (2, 4)', 'text', 1, 'point-slope form', '{"why":"Tangent is a straight line touching the curve at a point","sol":"Step 1: Differentiate to find slope at x = 2\nStep 2: dy/dx = 2x → slope = 4\nStep 3: Use point (2, 4) and slope 4\nStep 4: Equation: y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate to find slope at x = 2","Step 2: dy/dx = 2x → slope = 4","Step 3: Use point (2, 4) and slope 4","Step 4: Equation: y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 2),
  (1176, 349, 'Find equation of tangent slope for y = x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Tangent slope is found using derivative at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2\nStep 3: Compute 2 × 2\nStep 4: Tangent slope = 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2","Step 3: Compute 2 × 2","Step 4: Tangent slope = 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 3),
  (1177, 349, 'Find equation of normal slope if tangent slope is 3', 'text', 1, 'negative reciprocal', '{"why":"Normal is perpendicular to tangent, so slopes multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Apply normal formula = -1/m\nStep 3: Substitute values → -1/3\nStep 4: Simplify result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Apply normal formula = -1/m","Step 3: Substitute values → -1/3","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 4),
  (1178, 349, 'Find slope of tangent for y = 3x² + 2x at x = 1', 'text', 1, 'differentiate first', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y → dy/dx = 6x + 2\nStep 2: Substitute x = 1\nStep 3: Compute 6(1) + 2\nStep 4: Final slope = 8","steps":["Step 1: Differentiate y → dy/dx = 6x + 2","Step 2: Substitute x = 1","Step 3: Compute 6(1) + 2","Step 4: Final slope = 8"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q6","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 5),
  (1179, 349, 'Find normal slope if tangent slope is -5', 'text', 1, 'negative reciprocal rule', '{"why":"Normal is perpendicular so slope is negative reciprocal","sol":"Step 1: Tangent slope m = -5\nStep 2: Apply formula -1/m\nStep 3: Compute -1 / (-5)\nStep 4: Simplify result","steps":["Step 1: Tangent slope m = -5","Step 2: Apply formula -1/m","Step 3: Compute -1 / (-5)","Step 4: Simplify result"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q7","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 6),
  (1180, 349, 'Find equation of tangent to y = x² at point (2, 4)', 'text', 1, 'first find slope, then use point-slope form', '{"why":"Tangent is a line touching curve at a point; its slope is the derivative value at that point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2 → slope m = 4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation becomes y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2 → slope m = 4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation becomes y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q8","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 7),
  (1181, 349, 'Find equation of normal to y = x² at (2, 4)', 'text', 1, 'use perpendicular slope', '{"why":"Normal is perpendicular to tangent at the same point, hence negative reciprocal slope","sol":"Step 1: Slope of tangent at x = 2 is m = 4\nStep 2: Normal slope is perpendicular → -1/4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation: y - 4 = -1/4(x - 2)\nStep 5: Simplify to standard form","steps":["Step 1: Slope of tangent at x = 2 is m = 4","Step 2: Normal slope is perpendicular → -1/4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation: y - 4 = -1/4(x - 2)","Step 5: Simplify to standard form"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q9","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 8),
  (1182, 349, 'Find x-intercept of tangent to y = x² at x = 3', 'text', 1, 'first find tangent equation', '{"why":"The tangent line has a specific slope and passes through the point, allowing its intercepts to be calculated","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: At x = 3, slope m = 2(3) = 6\nStep 3: Point is (3, 3²) = (3, 9)\nStep 4: Tangent equation: y - 9 = 6(x - 3)\nStep 5: Set y = 0 to find x-intercept → -9 = 6x - 18\nStep 6: Solve for x → x = 9/6 = 3/2","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: At x = 3, slope m = 2(3) = 6","Step 3: Point is (3, 3²) = (3, 9)","Step 4: Tangent equation: y - 9 = 6(x - 3)","Step 5: Set y = 0 to find x-intercept → -9 = 6x - 18","Step 6: Solve for x → x = 9/6 = 3/2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q10","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 9),
  (1183, 349, 'At what x-value is tangent to y = x² parallel to line y = 4x + 1?', 'text', 1, 'slopes must be equal', '{"why":"Parallel lines have equal slopes, so we equate tangent slope to line slope and solve for x","sol":"Step 1: Slope of given line is 4\nStep 2: Slope of tangent is derivative dy/dx = 2x\nStep 3: Set slopes equal → 2x = 4\nStep 4: Solve for x → x = 2","steps":["Step 1: Slope of given line is 4","Step 2: Slope of tangent is derivative dy/dx = 2x","Step 3: Set slopes equal → 2x = 4","Step 4: Solve for x → x = 2"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q11","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 10),
  (1184, 349, 'Find the perpendicular distance from origin (0, 0) to tangent of y = x² at x = 4', 'text', 1, 'find tangent equation first', '{"why":"Perpendicular distance formula is used to find distance from origin to the calculated tangent line","sol":"Step 1: At x = 4, slope m = 2(4) = 8\nStep 2: Point is (4, 4²) = (4, 16)\nStep 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0\nStep 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)\nStep 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)\nStep 6: Simplify → distance = 16 / sqrt(65)","steps":["Step 1: At x = 4, slope m = 2(4) = 8","Step 2: Point is (4, 4²) = (4, 16)","Step 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0","Step 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)","Step 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)","Step 6: Simplify → distance = 16 / sqrt(65)"],"options":[],"conceptId":"math_calculus_tangents_and_normals","skillId":"math_calculus","subskillId":"math_calculus_q12","subject":"math","chapter":"calculus","topic":"Tangents and Normals"}', 11),
  (1185, 350, 'Why is differentiation important?', 'text', 1, 'rate of change', '{"why":"It quantifies how one variable changes with respect to another","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It quantifies how one variable changes with respect to another\nStep 3: State the final conclusion: measures change","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It quantifies how one variable changes with respect to another","Step 3: State the final conclusion: measures change"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 0),
  (1186, 350, 'Give real-life use', 'text', 1, 'motion or business', '{"why":"Used in physics for velocity and in economics for maximizing profit","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit\nStep 3: State the final conclusion: speed or profit optimization","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit","Step 3: State the final conclusion: speed or profit optimization"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 1),
  (1187, 350, 'What does f''(x) represent?', 'text', 1, 'derivative meaning', '{"why":"It represents instantaneous rate of change of a function","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It represents instantaneous rate of change of a function\nStep 3: State the final conclusion: rate of change or slope","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It represents instantaneous rate of change of a function","Step 3: State the final conclusion: rate of change or slope"],"options":[],"conceptId":"math_calculus_applications_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Differentiation"}', 2),
  (1188, 351, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 0),
  (1189, 351, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 1),
  (1190, 351, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 2),
  (1191, 351, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_area_under_a_curve","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Area Under a Curve"}', 3),
  (1192, 352, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 0),
  (1193, 352, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 1),
  (1194, 352, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 2),
  (1195, 352, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 3),
  (1196, 352, 'Why does integration represent area under a curve?', 'text', 1, 'limit of rectangles', '{"why":"Integration is the limit of summing thin rectangles","sol":"Step 1: Divide area under curve into small rectangles\nStep 2: Approximate each rectangle’s area\nStep 3: Increase number of rectangles\nStep 4: Make width approach zero\nStep 5: Sum becomes exact area","steps":["Step 1: Divide area under curve into small rectangles","Step 2: Approximate each rectangle’s area","Step 3: Increase number of rectangles","Step 4: Make width approach zero","Step 5: Sum becomes exact area"],"options":[],"conceptId":"math_calculus_indefinite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q5","subject":"math","chapter":"calculus","topic":"Indefinite Integrals"}', 4),
  (1197, 353, 'Evaluate definite integral ∫ from 1 to 2 of x dx', 'text', 1, 'definite integral with limits', '{"why":"Definite integrals calculate net area under a curve between two points","sol":"Step 1: Find antiderivative of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 1 → (1²)/2 = 1/2\nStep 4: Subtract upper limit value from lower limit value\nStep 5: Result = 2 - 1/2 = 3/2","steps":["Step 1: Find antiderivative of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 1 → (1²)/2 = 1/2","Step 4: Subtract upper limit value from lower limit value","Step 5: Result = 2 - 1/2 = 3/2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 0),
  (1198, 353, 'Find area under y = x² from 0 to 3', 'text', 1, 'use definite integral', '{"why":"Definite integral of a function over an interval gives the area under that curve","sol":"Step 1: Set up integral ∫ from 0 to 3 of x² dx\nStep 2: Integrate x² → x³/3\nStep 3: Apply limits → (3³/3) - (0³/3)\nStep 4: Simplify → 27/3 - 0\nStep 5: Final area = 9","steps":["Step 1: Set up integral ∫ from 0 to 3 of x² dx","Step 2: Integrate x² → x³/3","Step 3: Apply limits → (3³/3) - (0³/3)","Step 4: Simplify → 27/3 - 0","Step 5: Final area = 9"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 1),
  (1199, 353, 'Evaluate ∫ from 0 to 1 of (2x + 1) dx', 'text', 1, 'integrate term by term', '{"why":"Integrate each term separately and evaluate over the given interval","sol":"Step 1: Integrate 2x → x²\nStep 2: Integrate 1 → x\nStep 3: Combine → x² + x\nStep 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)\nStep 5: Result = 2 - 0 = 2","steps":["Step 1: Integrate 2x → x²","Step 2: Integrate 1 → x","Step 3: Combine → x² + x","Step 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)","Step 5: Result = 2 - 0 = 2"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 2),
  (1200, 353, 'What is difference between ∫ x dx and ∫₀¹ x dx?', 'text', 1, 'limits vs no limits', '{"why":"Limits define the interval and produce a single value instead of a function","sol":"Step 1: ∫ x dx has no limits\nStep 2: Result is family of functions → x²/2 + C\nStep 3: ∫₀¹ x dx has limits\nStep 4: Result is numerical value → 1/2\nStep 5: Compare both results","steps":["Step 1: ∫ x dx has no limits","Step 2: Result is family of functions → x²/2 + C","Step 3: ∫₀¹ x dx has limits","Step 4: Result is numerical value → 1/2","Step 5: Compare both results"],"options":[],"conceptId":"math_calculus_definite_integrals","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Definite Integrals"}', 3),
  (1201, 354, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 0),
  (1202, 354, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 1),
  (1203, 354, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 2),
  (1204, 354, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_integration_as_reverse_of_differentiation","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Integration as Reverse of Differentiation"}', 3),
  (1205, 355, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q1","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 0),
  (1206, 355, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q2","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 1),
  (1207, 355, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q3","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 2),
  (1208, 355, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_calculus_applications_of_integration","skillId":"math_calculus","subskillId":"math_calculus_q4","subject":"math","chapter":"calculus","topic":"Applications of Integration"}', 3),
  (1209, 356, 'A person walks 10 m forward and 10 m back. Find distance and displacement.', 'text', 1, 'Distance = total path, Displacement = change in position', '{"why":"Distance is total path covered, while displacement depends on change in position.","sol":"Step 1: Forward distance = 10 m\nStep 2: Backward distance = 10 m\nStep 3: Total distance = 10 + 10 = 20 m\nStep 4: Final position = starting point\nStep 5: Displacement = 0 m","steps":["Step 1: Forward distance = 10 m","Step 2: Backward distance = 10 m","Step 3: Total distance = 10 + 10 = 20 m","Step 4: Final position = starting point","Step 5: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 0),
  (1210, 356, 'Why can displacement be zero but distance not?', 'text', 1, 'starting and ending point', '{"why":"If you return to the starting point, displacement becomes zero but distance still adds up.","sol":"Step 1: Identify key concept: Define the required principles for Displacement & Distance.\nStep 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.\nStep 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position.","steps":["Step 1: Identify key concept: Define the required principles for Displacement & Distance.","Step 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.","Step 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position."],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 1),
  (1211, 356, 'A car moves 30 m east and then 40 m east. Find distance and displacement.', 'text', 1, 'same direction → add directly', '{"why":"When motion is in one direction, distance equals displacement.","sol":"Step 1: Distance = 30 + 40 = 70 m\nStep 2: Both in same direction (east)\nStep 3: Displacement = 70 m east","steps":["Step 1: Distance = 30 + 40 = 70 m","Step 2: Both in same direction (east)","Step 3: Displacement = 70 m east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 2),
  (1212, 356, 'A person walks 15 m north then 5 m south. Find distance and displacement.', 'text', 1, 'opposite directions → subtract', '{"why":"Displacement depends on net movement, not total path.","sol":"Step 1: Distance = 15 + 5 = 20 m\nStep 2: Net movement = 15 - 5 = 10 m\nStep 3: Direction = north","steps":["Step 1: Distance = 15 + 5 = 20 m","Step 2: Net movement = 15 - 5 = 10 m","Step 3: Direction = north"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 3),
  (1213, 356, 'A car travels 100 m east, then 100 m west. Find distance and displacement.', 'text', 1, 'returns to start', '{"why":"Opposite equal movements cancel displacement.","sol":"Step 1: Distance = 100 + 100 = 200 m\nStep 2: Final position = starting point\nStep 3: Displacement = 0 m","steps":["Step 1: Distance = 100 + 100 = 200 m","Step 2: Final position = starting point","Step 3: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 4),
  (1214, 356, 'A person walks 8 m east, then 6 m west. Find displacement.', 'text', 1, 'subtract opposite directions', '{"why":"Displacement is the net movement considering direction.","sol":"Step 1: Identify directions → east and west\nStep 2: Subtract → 8 - 6 = 2\nStep 3: Direction = east","steps":["Step 1: Identify directions → east and west","Step 2: Subtract → 8 - 6 = 2","Step 3: Direction = east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 5),
  (1215, 357, 'A runner covers 200 m in 25 s. Find speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Speed is the rate of covering distance per unit time.","sol":"Step 1: Identify values → s = 200 m, t = 25 s\nStep 2: Substitute → v = 200 ÷ 25\nStep 3: Calculate → v = 8 m/s","steps":["Step 1: Identify values → s = 200 m, t = 25 s","Step 2: Substitute → v = 200 ÷ 25","Step 3: Calculate → v = 8 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Speed"}', 0),
  (1216, 357, 'A car travels 360 km in 6 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed in km/h is calculated using total distance divided by total time.","sol":"Step 1: s = 360 km, t = 6 h\nStep 2: v = 360 ÷ 6\nStep 3: v = 60 km/h","steps":["Step 1: s = 360 km, t = 6 h","Step 2: v = 360 ÷ 6","Step 3: v = 60 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Speed"}', 1),
  (1217, 357, 'A body moves 500 m in 50 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed measures how fast distance is covered.","sol":"Step 1: s = 500 m, t = 50 s\nStep 2: v = 500 ÷ 50\nStep 3: v = 10 m/s","steps":["Step 1: s = 500 m, t = 50 s","Step 2: v = 500 ÷ 50","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Speed"}', 2),
  (1218, 357, 'A cyclist moves 120 km in 4 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 120 km, t = 4 h\nStep 2: v = 120 ÷ 4\nStep 3: v = 30 km/h","steps":["Step 1: s = 120 km, t = 4 h","Step 2: v = 120 ÷ 4","Step 3: v = 30 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Speed"}', 3),
  (1219, 357, 'A car travels 75 m in 5 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed is proportional to distance and inversely proportional to time.","sol":"Step 1: s = 75 m, t = 5 s\nStep 2: v = 75 ÷ 5\nStep 3: v = 15 m/s","steps":["Step 1: s = 75 m, t = 5 s","Step 2: v = 75 ÷ 5","Step 3: v = 15 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Speed"}', 4),
  (1220, 357, 'A train covers 900 m in 30 s. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed measures how quickly distance is covered.","sol":"Step 1: s = 900 m, t = 30 s\nStep 2: v = 900 ÷ 30\nStep 3: v = 30 m/s","steps":["Step 1: s = 900 m, t = 30 s","Step 2: v = 900 ÷ 30","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Speed"}', 5),
  (1221, 357, 'A car covers 1.2 km in 60 s. Find speed in m/s.', 'text', 1, 'convert km to m first', '{"why":"Always convert distance into SI units before calculating speed.","sol":"Step 1: Convert 1.2 km → 1200 m\nStep 2: t = 60 s\nStep 3: v = 1200 ÷ 60\nStep 4: v = 20 m/s","steps":["Step 1: Convert 1.2 km → 1200 m","Step 2: t = 60 s","Step 3: v = 1200 ÷ 60","Step 4: v = 20 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Speed"}', 6),
  (1222, 358, 'A car travels 150 m in 5 s. Find its velocity.', 'text', 1, 'Use v = distance ÷ time', '{"why":"Velocity is the rate of change of displacement with time.","sol":"Step 1: Identify values → s = 150 m, t = 5 s\nStep 2: Substitute into formula → v = 150 ÷ 5\nStep 3: Calculate → v = 30 m/s","steps":["Step 1: Identify values → s = 150 m, t = 5 s","Step 2: Substitute into formula → v = 150 ÷ 5","Step 3: Calculate → v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Velocity"}', 0),
  (1223, 358, 'A runner covers 100 m in 20 s. Find velocity.', 'text', 1, 'Use v = s / t', '{"why":"Velocity tells how fast and in what direction an object moves.","sol":"Step 1: s = 100 m, t = 20 s\nStep 2: v = 100 ÷ 20\nStep 3: v = 5 m/s","steps":["Step 1: s = 100 m, t = 20 s","Step 2: v = 100 ÷ 20","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Velocity"}', 1),
  (1224, 358, 'A body moves with velocity 12 m/s for 8 s. Find distance covered.', 'text', 1, 'Use s = v × t', '{"why":"Distance is product of velocity and time when motion is uniform.","sol":"Step 1: v = 12 m/s, t = 8 s\nStep 2: s = 12 × 8\nStep 3: s = 96 m","steps":["Step 1: v = 12 m/s, t = 8 s","Step 2: s = 12 × 8","Step 3: s = 96 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Velocity"}', 2),
  (1225, 358, 'A train moves 300 m in 10 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity depends on displacement per time.","sol":"Step 1: s = 300 m, t = 10 s\nStep 2: v = 300 ÷ 10\nStep 3: v = 30 m/s","steps":["Step 1: s = 300 m, t = 10 s","Step 2: v = 300 ÷ 10","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Velocity"}', 3),
  (1226, 358, 'A car covers 240 m in 12 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity shows rate of motion.","sol":"Step 1: s = 240 m, t = 12 s\nStep 2: v = 240 ÷ 12\nStep 3: v = 20 m/s","steps":["Step 1: s = 240 m, t = 12 s","Step 2: v = 240 ÷ 12","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Velocity"}', 4),
  (1227, 358, 'A cyclist moves 60 m in 6 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is constant motion over time.","sol":"Step 1: s = 60 m, t = 6 s\nStep 2: v = 60 ÷ 6\nStep 3: v = 10 m/s","steps":["Step 1: s = 60 m, t = 6 s","Step 2: v = 60 ÷ 6","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Velocity"}', 5),
  (1228, 358, 'A body travels 500 m in 25 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 500 m, t = 25 s\nStep 2: v = 500 ÷ 25\nStep 3: v = 20 m/s","steps":["Step 1: s = 500 m, t = 25 s","Step 2: v = 500 ÷ 25","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Velocity"}', 6),
  (1229, 358, 'A car moves at 15 m/s for 10 s. Find distance.', 'text', 1, 's = vt', '{"why":"Distance is product of velocity and time.","sol":"Step 1: v = 15 m/s, t = 10 s\nStep 2: s = 15 × 10\nStep 3: s = 150 m","steps":["Step 1: v = 15 m/s, t = 10 s","Step 2: s = 15 × 10","Step 3: s = 150 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Velocity"}', 7),
  (1230, 358, 'A runner moves 200 m in 40 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity measures how fast distance is covered.","sol":"Step 1: s = 200 m, t = 40 s\nStep 2: v = 200 ÷ 40\nStep 3: v = 5 m/s","steps":["Step 1: s = 200 m, t = 40 s","Step 2: v = 200 ÷ 40","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Velocity"}', 8),
  (1231, 358, 'A vehicle covers 360 m in 18 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 360 m, t = 18 s\nStep 2: v = 360 ÷ 18\nStep 3: v = 20 m/s","steps":["Step 1: s = 360 m, t = 18 s","Step 2: v = 360 ÷ 18","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Velocity"}', 9),
  (1232, 359, 'A car speeds up from 0 m/s to 20 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Acceleration measures change in velocity per unit time.","sol":"Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s\nStep 2: Substitute into formula → a = (20 - 0) / 5\nStep 3: Calculate → a = 4 m/s²","steps":["Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s","Step 2: Substitute into formula → a = (20 - 0) / 5","Step 3: Calculate → a = 4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Acceleration"}', 0),
  (1233, 359, 'A car slows from 30 m/s to 10 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: u = 30 m/s, v = 10 m/s, t = 5 s\nStep 2: a = (10 - 30) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 30 m/s, v = 10 m/s, t = 5 s","Step 2: a = (10 - 30) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Acceleration"}', 1),
  (1234, 359, 'A bike increases speed from 5 m/s to 25 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The bike is speeding up uniformly.","sol":"Step 1: u = 5, v = 25, t = 10\nStep 2: a = (25 - 5) / 10\nStep 3: a = 20 / 10\nStep 4: a = 2 m/s²","steps":["Step 1: u = 5, v = 25, t = 10","Step 2: a = (25 - 5) / 10","Step 3: a = 20 / 10","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Acceleration"}', 2),
  (1235, 359, 'A train slows from 40 m/s to 20 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The train is decelerating.","sol":"Step 1: u = 40, v = 20, t = 8\nStep 2: a = (20 - 40) / 8\nStep 3: a = -20 / 8\nStep 4: a = -2.5 m/s²","steps":["Step 1: u = 40, v = 20, t = 8","Step 2: a = (20 - 40) / 8","Step 3: a = -20 / 8","Step 4: a = -2.5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Acceleration"}', 3),
  (1236, 359, 'A car accelerates from 10 m/s to 30 m/s in 4 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily over time.","sol":"Step 1: u = 10, v = 30, t = 4\nStep 2: a = (30 - 10) / 4\nStep 3: a = 20 / 4\nStep 4: a = 5 m/s²","steps":["Step 1: u = 10, v = 30, t = 4","Step 2: a = (30 - 10) / 4","Step 3: a = 20 / 4","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Acceleration"}', 4),
  (1237, 359, 'A body slows from 50 m/s to 10 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Large negative acceleration shows rapid slowing.","sol":"Step 1: u = 50, v = 10, t = 8\nStep 2: a = (10 - 50) / 8\nStep 3: a = -40 / 8\nStep 4: a = -5 m/s²","steps":["Step 1: u = 50, v = 10, t = 8","Step 2: a = (10 - 50) / 8","Step 3: a = -40 / 8","Step 4: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Acceleration"}', 5),
  (1238, 359, 'A motorcycle increases speed from 12 m/s to 24 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Acceleration is constant during motion.","sol":"Step 1: u = 12, v = 24, t = 6\nStep 2: a = (24 - 12) / 6\nStep 3: a = 12 / 6\nStep 4: a = 2 m/s²","steps":["Step 1: u = 12, v = 24, t = 6","Step 2: a = (24 - 12) / 6","Step 3: a = 12 / 6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Acceleration"}', 6),
  (1239, 359, 'A bus slows from 60 m/s to 30 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Bus is decelerating uniformly.","sol":"Step 1: u = 60, v = 30, t = 10\nStep 2: a = (30 - 60) / 10\nStep 3: a = -30 / 10\nStep 4: a = -3 m/s²","steps":["Step 1: u = 60, v = 30, t = 10","Step 2: a = (30 - 60) / 10","Step 3: a = -30 / 10","Step 4: a = -3 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Acceleration"}', 7),
  (1240, 359, 'A car increases speed from 8 m/s to 32 m/s in 12 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily.","sol":"Step 1: u = 8, v = 32, t = 12\nStep 2: a = (32 - 8) / 12\nStep 3: a = 24 / 12\nStep 4: a = 2 m/s²","steps":["Step 1: u = 8, v = 32, t = 12","Step 2: a = (32 - 8) / 12","Step 3: a = 24 / 12","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Acceleration"}', 8),
  (1241, 359, 'A train slows from 70 m/s to 40 m/s in 15 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Train slows down steadily.","sol":"Step 1: u = 70, v = 40, t = 15\nStep 2: a = (40 - 70) / 15\nStep 3: a = -30 / 15\nStep 4: a = -2 m/s²","steps":["Step 1: u = 70, v = 40, t = 15","Step 2: a = (40 - 70) / 15","Step 3: a = -30 / 15","Step 4: a = -2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Acceleration"}', 9),
  (1242, 359, 'A car goes from 15 m/s to 45 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Car gains speed quickly.","sol":"Step 1: u = 15, v = 45, t = 6\nStep 2: a = (45 - 15) / 6\nStep 3: a = 30 / 6\nStep 4: a = 5 m/s²","steps":["Step 1: u = 15, v = 45, t = 6","Step 2: a = (45 - 15) / 6","Step 3: a = 30 / 6","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Acceleration"}', 10),
  (1243, 359, 'A vehicle slows from 25 m/s to 5 m/s in 5 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Vehicle is slowing down steadily.","sol":"Step 1: u = 25, v = 5, t = 5\nStep 2: a = (5 - 25) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 25, v = 5, t = 5","Step 2: a = (5 - 25) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Acceleration"}', 11),
  (1244, 360, 'A body starts from rest and accelerates at 2 m/s² for 6 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time from rest.","sol":"Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s\nStep 2: Substitute → v = 0 + (2 × 6)\nStep 3: Multiply → v = 12 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s","Step 2: Substitute → v = 0 + (2 × 6)","Step 3: Multiply → v = 12 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 0),
  (1245, 360, 'A car moves with u = 5 m/s, a = 3 m/s², t = 4 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration adds to initial velocity over time.","sol":"Step 1: Identify values → u = 5, a = 3, t = 4\nStep 2: Multiply → a × t = 12\nStep 3: Add → v = 5 + 12 = 17 m/s","steps":["Step 1: Identify values → u = 5, a = 3, t = 4","Step 2: Multiply → a × t = 12","Step 3: Add → v = 5 + 12 = 17 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 1),
  (1246, 360, 'A body has u = 20 m/s, a = -2 m/s², t = 5 s. Find final velocity.', 'text', 1, 'Negative acceleration means deceleration', '{"why":"Negative acceleration reduces velocity over time.","sol":"Step 1: u = 20, a = -2, t = 5\nStep 2: Multiply → -2 × 5 = -10\nStep 3: v = 20 - 10 = 10 m/s","steps":["Step 1: u = 20, a = -2, t = 5","Step 2: Multiply → -2 × 5 = -10","Step 3: v = 20 - 10 = 10 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 2),
  (1247, 360, 'A body has u = 0 m/s, a = 4 m/s², t = 3 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement increases as object accelerates from rest.","sol":"Step 1: u = 0, a = 4, t = 3\nStep 2: ut = 0\nStep 3: t² = 9\nStep 4: s = 1/2 × 4 × 9\nStep 5: s = 2 × 9 = 18 m","steps":["Step 1: u = 0, a = 4, t = 3","Step 2: ut = 0","Step 3: t² = 9","Step 4: s = 1/2 × 4 × 9","Step 5: s = 2 × 9 = 18 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 3),
  (1248, 360, 'A body moves with u = 8 m/s, a = 2 m/s², t = 5 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement is total distance covered under acceleration.","sol":"Step 1: ut = 8 × 5 = 40\nStep 2: t² = 25\nStep 3: 1/2 × 2 × 25 = 25\nStep 4: s = 40 + 25 = 65 m","steps":["Step 1: ut = 8 × 5 = 40","Step 2: t² = 25","Step 3: 1/2 × 2 × 25 = 25","Step 4: s = 40 + 25 = 65 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 4),
  (1249, 360, 'A body has u = 10 m/s, v = 30 m/s, a = 4 m/s². Find time.', 'text', 1, 'Use v = u + at', '{"why":"Time is found from change in velocity divided by acceleration.","sol":"Step 1: v = 30, u = 10, a = 4\nStep 2: v - u = 20\nStep 3: t = 20 / 4\nStep 4: t = 5 s","steps":["Step 1: v = 30, u = 10, a = 4","Step 2: v - u = 20","Step 3: t = 20 / 4","Step 4: t = 5 s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 5),
  (1250, 360, 'A body has u = 4 m/s, v = 20 m/s, s = 24 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"This equation links velocity change with displacement and acceleration.","sol":"Step 1: 20² = 400\nStep 2: 4² = 16\nStep 3: 400 = 16 + 2a(24)\nStep 4: 400 - 16 = 384\nStep 5: 384 = 48a\nStep 6: a = 8 m/s²","steps":["Step 1: 20² = 400","Step 2: 4² = 16","Step 3: 400 = 16 + 2a(24)","Step 4: 400 - 16 = 384","Step 5: 384 = 48a","Step 6: a = 8 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 6);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1251, 360, 'A body has u = 15 m/s, v = 5 m/s, s = 20 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: 5² = 25\nStep 2: 15² = 225\nStep 3: 25 = 225 + 2a(20)\nStep 4: 25 - 225 = 40a\nStep 5: -200 = 40a\nStep 6: a = -5 m/s²","steps":["Step 1: 5² = 25","Step 2: 15² = 225","Step 3: 25 = 225 + 2a(20)","Step 4: 25 - 225 = 40a","Step 5: -200 = 40a","Step 6: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 7),
  (1252, 360, 'A body starts from rest and travels 50 m in 5 s. Find acceleration.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Used when initial velocity is zero.","sol":"Step 1: u = 0, s = 50, t = 5\nStep 2: s = 1/2 a t²\nStep 3: 50 = 1/2 a × 25\nStep 4: 50 = 12.5a\nStep 5: a = 4 m/s²","steps":["Step 1: u = 0, s = 50, t = 5","Step 2: s = 1/2 a t²","Step 3: 50 = 1/2 a × 25","Step 4: 50 = 12.5a","Step 5: a = 4 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 8),
  (1253, 360, 'A body has u = 6 m/s, a = 2 m/s², t = 8 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Final velocity depends on initial velocity plus acceleration effect.","sol":"Step 1: a × t = 16\nStep 2: v = 6 + 16\nStep 3: v = 22 m/s","steps":["Step 1: a × t = 16","Step 2: v = 6 + 16","Step 3: v = 22 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 9),
  (1254, 360, 'A car starts from rest and accelerates at 3 m/s² for 5 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time, so final velocity depends on initial velocity plus change due to acceleration.","sol":"Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s\nStep 2: Substitute into formula → v = 0 + (3 × 5)\nStep 3: Multiply → v = 15 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s","Step 2: Substitute into formula → v = 0 + (3 × 5)","Step 3: Multiply → v = 15 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 10),
  (1255, 360, 'A body moves with u = 10 m/s, a = 2 m/s², t = 4 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement under acceleration includes both initial motion and extra distance due to speeding up.","sol":"Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s\nStep 2: Calculate first term → ut = 10 × 4 = 40\nStep 3: Calculate second term → 1/2 × 2 × 4²\nStep 4: Square time → 4² = 16\nStep 5: Multiply → 1/2 × 2 × 16 = 16\nStep 6: Add both terms → 40 + 16 = 56 m","steps":["Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s","Step 2: Calculate first term → ut = 10 × 4 = 40","Step 3: Calculate second term → 1/2 × 2 × 4²","Step 4: Square time → 4² = 16","Step 5: Multiply → 1/2 × 2 × 16 = 16","Step 6: Add both terms → 40 + 16 = 56 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 11),
  (1256, 360, 'When do we use v² = u² + 2as?', 'text', 1, 'no time given', '{"why":"This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","sol":"Step 1: Identify key concept: Define the required principles for Equations of Motion.\nStep 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.\nStep 3: State the final conclusion: When time is not given in the problem.","steps":["Step 1: Identify key concept: Define the required principles for Equations of Motion.","Step 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","Step 3: State the final conclusion: When time is not given in the problem."],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 12),
  (1257, 361, 'What is the role of friction when walking?', 'text', 1, 'grip between surfaces', '{"why":"Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.\nStep 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","Step 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Friction"}', 0),
  (1258, 361, 'Why do smooth surfaces have less friction?', 'text', 1, 'surface irregularities', '{"why":"Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.\nStep 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","Step 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Friction"}', 1),
  (1259, 361, 'Is friction always bad? Explain.', 'text', 1, 'useful and harmful effects', '{"why":"Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.\nStep 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","Step 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Friction"}', 2),
  (1260, 361, 'A force of 50 N is applied to move a box, and friction force is 20 N. Find the resultant force.', 'text', 1, 'net force = applied force − friction', '{"why":"Friction opposes motion, reducing the effective force.","sol":"Step 1: Identify values → applied force = 50 N, friction = 20 N\nStep 2: Apply formula → F_net = 50 − 20\nStep 3: Calculate → F_net = 30 N","steps":["Step 1: Identify values → applied force = 50 N, friction = 20 N","Step 2: Apply formula → F_net = 50 − 20","Step 3: Calculate → F_net = 30 N"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Friction"}', 3),
  (1261, 361, 'A 10 kg object is pulled with a force of 15 N against friction. Will it move?', 'text', 1, 'compare forces', '{"why":"An object moves only when applied force exceeds friction.","sol":"Step 1: Identify applied force = 15 N\nStep 2: Compare with friction (assume friction = 15 N threshold)\nStep 3: If equal or less → no acceleration\nStep 4: Conclusion → object is just about to move or stays at rest","steps":["Step 1: Identify applied force = 15 N","Step 2: Compare with friction (assume friction = 15 N threshold)","Step 3: If equal or less → no acceleration","Step 4: Conclusion → object is just about to move or stays at rest"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Friction"}', 4),
  (1262, 361, 'A box is pushed with 25 N and friction is 10 N. Find net force and motion direction.', 'text', 1, 'net force = difference', '{"why":"Net force determines both magnitude and direction of motion.","sol":"Step 1: Applied force = 25 N, friction = 10 N\nStep 2: F_net = 25 − 10\nStep 3: F_net = 15 N\nStep 4: Direction is same as applied force","steps":["Step 1: Applied force = 25 N, friction = 10 N","Step 2: F_net = 25 − 10","Step 3: F_net = 15 N","Step 4: Direction is same as applied force"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Friction"}', 5),
  (1263, 361, 'A surface has friction of 6 N. A force of 6 N is applied. What happens?', 'text', 1, 'balanced forces', '{"why":"When forces are balanced, there is no change in motion.","sol":"Step 1: Applied = 6 N, friction = 6 N\nStep 2: F_net = 6 − 6\nStep 3: F_net = 0 N\nStep 4: No acceleration occurs","steps":["Step 1: Applied = 6 N, friction = 6 N","Step 2: F_net = 6 − 6","Step 3: F_net = 0 N","Step 4: No acceleration occurs"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Friction"}', 6),
  (1264, 361, 'A 5 kg object is pushed with 40 N and friction is 15 N. Find acceleration (take g not needed).', 'text', 1, 'F = ma and net force first', '{"why":"Acceleration depends on net force after friction is considered.","sol":"Step 1: Find net force → 40 − 15 = 25 N\nStep 2: Use F = ma\nStep 3: a = F/m = 25/5\nStep 4: a = 5 m/s²","steps":["Step 1: Find net force → 40 − 15 = 25 N","Step 2: Use F = ma","Step 3: a = F/m = 25/5","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Friction"}', 7),
  (1265, 362, 'A mass of 8 kg is hanging on a rope. Find its weight.', 'text', 1, 'Use W = mg', '{"why":"Weight is the gravitational force acting on a mass.","sol":"Step 1: Identify values → m = 8 kg, g = 10 m/s²\nStep 2: Substitute → W = 8 × 10\nStep 3: Multiply → W = 80 N","steps":["Step 1: Identify values → m = 8 kg, g = 10 m/s²","Step 2: Substitute → W = 8 × 10","Step 3: Multiply → W = 80 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 0),
  (1266, 362, 'What happens to weight on the Moon?', 'text', 1, 'gravity is weaker', '{"why":"Mass stays constant, but weight changes because it depends on gravitational field strength.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.\nStep 3: State the final conclusion: Weight decreases because gravitational field strength is lower.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.","Step 3: State the final conclusion: Weight decreases because gravitational field strength is lower."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 1),
  (1267, 362, 'What direction does tension act?', 'text', 1, 'along rope', '{"why":"Tension is a pulling force transmitted through a string, rope, or cable.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.\nStep 3: State the final conclusion: Along the rope, always pulling away from the object.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.","Step 3: State the final conclusion: Along the rope, always pulling away from the object."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 2),
  (1268, 362, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases directly with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 3),
  (1269, 362, 'A 12 kg object is lifted on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight is the force due to gravity acting on a mass.","sol":"Step 1: m = 12 kg, g = 10 m/s²\nStep 2: W = 12 × 10\nStep 3: W = 120 N","steps":["Step 1: m = 12 kg, g = 10 m/s²","Step 2: W = 12 × 10","Step 3: W = 120 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 4),
  (1270, 362, 'A 3 kg object is on the Moon where g = 1.6 m/s². Find its weight.', 'text', 1, 'use W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 5),
  (1271, 362, 'A 6 kg object experiences a force of 60 N. Find acceleration.', 'text', 1, 'Use F = ma', '{"why":"Acceleration depends on force and mass.","sol":"Step 1: F = 60 N, m = 6 kg\nStep 2: a = F / m\nStep 3: a = 60 / 6\nStep 4: a = 10 m/s²","steps":["Step 1: F = 60 N, m = 6 kg","Step 2: a = F / m","Step 3: a = 60 / 6","Step 4: a = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 6),
  (1272, 362, 'A 10 kg object has weight 100 N. Find gravitational field strength.', 'text', 1, 'g = W / m', '{"why":"Gravitational field strength is weight per unit mass.","sol":"Step 1: W = 100 N, m = 10 kg\nStep 2: g = 100 / 10\nStep 3: g = 10 m/s²","steps":["Step 1: W = 100 N, m = 10 kg","Step 2: g = 100 / 10","Step 3: g = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 7),
  (1273, 362, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass toward the center of the Earth.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 8),
  (1274, 362, 'A 2 kg object is taken to a planet where g = 5 m/s². Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight changes with gravitational field strength.","sol":"Step 1: m = 2 kg, g = 5 m/s²\nStep 2: W = 2 × 5\nStep 3: W = 10 N","steps":["Step 1: m = 2 kg, g = 5 m/s²","Step 2: W = 2 × 5","Step 3: W = 10 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 9),
  (1275, 363, 'What force keeps a car moving in a circular path?', 'text', 1, 'towards centre', '{"why":"Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.\nStep 3: State the final conclusion: Friction provides centripetal force.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","Step 3: State the final conclusion: Friction provides centripetal force."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 0),
  (1276, 363, 'What provides centripetal force for a satellite?', 'text', 1, 'Earth attraction', '{"why":"The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.\nStep 3: State the final conclusion: Gravity.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","Step 3: State the final conclusion: Gravity."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 1),
  (1277, 363, 'Why are roads banked on curves?', 'text', 1, 'safe turning', '{"why":"Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.\nStep 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","Step 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 2),
  (1278, 363, 'What happens if a string holding a rotating stone breaks?', 'text', 1, 'inertia', '{"why":"When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.\nStep 3: State the final conclusion: The stone moves in a straight line due to inertia.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","Step 3: State the final conclusion: The stone moves in a straight line due to inertia."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 3),
  (1279, 363, 'A car moves in a circle of radius 10 m at a speed of 5 m/s. Find centripetal acceleration.', 'text', 1, 'use a = v²/r', '{"why":"Centripetal acceleration depends on speed and radius of the circular path.","sol":"Step 1: Identify values → v = 5 m/s, r = 10 m\nStep 2: Apply formula → a = v² / r\nStep 3: Square velocity → 5² = 25\nStep 4: Substitute → a = 25 / 10\nStep 5: Calculate → a = 2.5 m/s²","steps":["Step 1: Identify values → v = 5 m/s, r = 10 m","Step 2: Apply formula → a = v² / r","Step 3: Square velocity → 5² = 25","Step 4: Substitute → a = 25 / 10","Step 5: Calculate → a = 2.5 m/s²"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 4),
  (1280, 363, 'A stone of mass 2 kg moves in a circle of radius 4 m at speed 3 m/s. Find centripetal force.', 'text', 1, 'use F = mv²/r', '{"why":"Centripetal force increases with mass and speed, and decreases with radius.","sol":"Step 1: m = 2 kg, v = 3 m/s, r = 4 m\nStep 2: Square velocity → 3² = 9\nStep 3: Apply formula → F = (2 × 9) / 4\nStep 4: Multiply → F = 18 / 4\nStep 5: Final answer → F = 4.5 N","steps":["Step 1: m = 2 kg, v = 3 m/s, r = 4 m","Step 2: Square velocity → 3² = 9","Step 3: Apply formula → F = (2 × 9) / 4","Step 4: Multiply → F = 18 / 4","Step 5: Final answer → F = 4.5 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 5),
  (1281, 363, 'A satellite orbits Earth at constant speed. If gravity is 800 N, what force keeps it in orbit?', 'text', 1, 'centripetal = gravity', '{"why":"For satellites, gravity alone provides the centripetal force.","sol":"Step 1: Identify forces acting → gravity acts inward\nStep 2: Recognize circular motion condition\nStep 3: Centripetal force equals gravitational force\nStep 4: Therefore F = 800 N","steps":["Step 1: Identify forces acting → gravity acts inward","Step 2: Recognize circular motion condition","Step 3: Centripetal force equals gravitational force","Step 4: Therefore F = 800 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 6),
  (1282, 363, 'Why does an object in circular motion need a force?', 'text', 1, 'changing direction', '{"why":"Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.\nStep 3: State the final conclusion: Because its direction is constantly changing.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","Step 3: State the final conclusion: Because its direction is constantly changing."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 7),
  (1283, 364, 'What is the value of g on Earth?', 'text', 1, 'acceleration due to gravity', '{"why":"The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.\nStep 3: State the final conclusion: 10 m/s² (approx)","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","Step 3: State the final conclusion: 10 m/s² (approx)"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Gravitation"}', 0),
  (1284, 364, 'What happens to gravitational force when distance increases?', 'text', 1, 'inverse square law', '{"why":"Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.\nStep 3: State the final conclusion: It decreases rapidly (inverse square law).","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","Step 3: State the final conclusion: It decreases rapidly (inverse square law)."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Gravitation"}', 1),
  (1285, 364, 'Is gravity only on Earth? Explain.', 'text', 1, 'universal force', '{"why":"Gravity is a universal force that attracts all objects with mass, not just those on Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.\nStep 3: State the final conclusion: No, gravity exists between all objects with mass in the universe.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.","Step 3: State the final conclusion: No, gravity exists between all objects with mass in the universe."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Gravitation"}', 2),
  (1286, 364, 'A mass of 2 kg is acted on by gravity. Find its weight on Earth.', 'text', 1, 'use W = mg', '{"why":"Weight is the gravitational force acting on an object.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s²\nStep 2: Apply formula → W = m × g\nStep 3: Substitute → W = 2 × 10\nStep 4: Calculate → W = 20 N","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s²","Step 2: Apply formula → W = m × g","Step 3: Substitute → W = 2 × 10","Step 4: Calculate → W = 20 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Gravitation"}', 3),
  (1287, 364, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Gravitation"}', 4),
  (1288, 364, 'A 3 kg object is taken to the Moon where g = 1.6 m/s². Find weight.', 'text', 1, 'W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Gravitation"}', 5),
  (1289, 364, 'A planet has g = 20 m/s². Find weight of a 2 kg object.', 'text', 1, 'W = mg', '{"why":"Stronger gravity produces greater weight.","sol":"Step 1: m = 2 kg, g = 20 m/s²\nStep 2: W = 2 × 20\nStep 3: W = 40 N","steps":["Step 1: m = 2 kg, g = 20 m/s²","Step 2: W = 2 × 20","Step 3: W = 40 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Gravitation"}', 6),
  (1290, 364, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass towards the center of Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Gravitation"}', 7),
  (1291, 364, 'What is the difference between mass and weight?', 'text', 1, 'gravity dependence', '{"why":"Mass is the amount of matter, while weight is the force due to gravity.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.\nStep 3: State the final conclusion: Mass is constant, weight depends on gravity.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.","Step 3: State the final conclusion: Mass is constant, weight depends on gravity."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Gravitation"}', 8),
  (1292, 364, 'A 4 kg object is taken from Earth (g = 10 m/s²) to a planet where g = 5 m/s². Find change in weight.', 'text', 1, 'W = mg', '{"why":"Weight decreases when gravitational field strength decreases.","sol":"Step 1: Earth weight → W₁ = 4 × 10 = 40 N\nStep 2: New weight → W₂ = 4 × 5 = 20 N\nStep 3: Change in weight → 40 - 20\nStep 4: Result → 20 N decrease","steps":["Step 1: Earth weight → W₁ = 4 × 10 = 40 N","Step 2: New weight → W₂ = 4 × 5 = 20 N","Step 3: Change in weight → 40 - 20","Step 4: Result → 20 N decrease"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Gravitation"}', 9),
  (1293, 365, 'State Newton’s First Law of Motion.', 'text', 1, 'inertia', '{"why":"This law is also called the law of inertia because objects resist changes in their state of motion.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.\nStep 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.","Step 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 0),
  (1294, 365, 'What is the formula for Newton’s Second Law?', 'text', 1, 'force, mass, acceleration', '{"why":"Force is directly proportional to mass and acceleration of an object.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.\nStep 3: State the final conclusion: F = ma","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.","Step 3: State the final conclusion: F = ma"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 1),
  (1295, 365, 'Why do rockets move upward?', 'text', 1, 'action-reaction', '{"why":"Newton’s Third Law explains rocket propulsion through equal and opposite forces.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.\nStep 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.","Step 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 2),
  (1296, 365, 'A force of 10N acts on a mass of 2kg. Find acceleration.', 'text', 1, 'use F = ma', '{"why":"Acceleration increases when force increases or mass decreases.","sol":"Step 1: Write values → F = 10N, m = 2kg\nStep 2: Apply formula → a = F/m\nStep 3: Substitute → a = 10/2\nStep 4: Calculate → a = 5 m/s²","steps":["Step 1: Write values → F = 10N, m = 2kg","Step 2: Apply formula → a = F/m","Step 3: Substitute → a = 10/2","Step 4: Calculate → a = 5 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 3),
  (1297, 365, 'A 4kg object accelerates at 3 m/s². Find force.', 'text', 1, 'F = ma', '{"why":"Force depends on both mass and acceleration.","sol":"Step 1: m = 4kg, a = 3 m/s²\nStep 2: Substitute → F = 4 × 3\nStep 3: Calculate → F = 12N","steps":["Step 1: m = 4kg, a = 3 m/s²","Step 2: Substitute → F = 4 × 3","Step 3: Calculate → F = 12N"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 4),
  (1298, 365, 'What does Newton’s Third Law state?', 'text', 1, 'action-reaction', '{"why":"Forces always occur in pairs acting on different objects.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Forces always occur in pairs acting on different objects.\nStep 3: State the final conclusion: For every action, there is an equal and opposite reaction.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Forces always occur in pairs acting on different objects.","Step 3: State the final conclusion: For every action, there is an equal and opposite reaction."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 5),
  (1299, 365, 'A 6kg object is acted on by a 12N force. Find acceleration.', 'text', 1, 'F = ma', '{"why":"Acceleration is directly proportional to force.","sol":"Step 1: F = 12N, m = 6kg\nStep 2: a = F/m\nStep 3: a = 12/6\nStep 4: a = 2 m/s²","steps":["Step 1: F = 12N, m = 6kg","Step 2: a = F/m","Step 3: a = 12/6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 6),
  (1300, 365, 'Why do passengers move forward when a bus stops suddenly?', 'text', 1, 'inertia', '{"why":"The lower part stops with the bus, but the upper body continues moving.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.\nStep 3: State the final conclusion: Because of inertia, their bodies continue moving forward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.","Step 3: State the final conclusion: Because of inertia, their bodies continue moving forward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 7),
  (1301, 365, 'A force of 30N produces an acceleration of 5 m/s². Find mass.', 'text', 1, 'rearrange F = ma', '{"why":"Mass is resistance to acceleration.","sol":"Step 1: F = 30N, a = 5 m/s²\nStep 2: m = F/a\nStep 3: m = 30/5\nStep 4: m = 6kg","steps":["Step 1: F = 30N, a = 5 m/s²","Step 2: m = F/a","Step 3: m = 30/5","Step 4: m = 6kg"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 8),
  (1302, 365, 'What is inertia?', 'text', 1, 'resistance to change', '{"why":"More mass means more inertia.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: More mass means more inertia.\nStep 3: State the final conclusion: The tendency of an object to resist changes in its state of motion.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: More mass means more inertia.","Step 3: State the final conclusion: The tendency of an object to resist changes in its state of motion."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 9),
  (1303, 366, 'A force of 20N moves an object 3m. Find work done.', 'text', 1, 'Use W = F × d', '{"why":"Work is done when a force causes displacement in its direction.","sol":"Step 1: Identify values → F = 20 N, d = 3 m\nStep 2: Write formula → W = F × d\nStep 3: Substitute values → W = 20 × 3\nStep 4: Calculate → W = 60 J","steps":["Step 1: Identify values → F = 20 N, d = 3 m","Step 2: Write formula → W = F × d","Step 3: Substitute values → W = 20 × 3","Step 4: Calculate → W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Work"}', 0),
  (1304, 366, 'Why is no work done when pushing a wall?', 'text', 1, 'no movement', '{"why":"Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.\nStep 3: State the final conclusion: Because there is no displacement, so work done is zero.","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","Step 3: State the final conclusion: Because there is no displacement, so work done is zero."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Work"}', 1),
  (1305, 366, 'Do machines reduce total work done? Explain.', 'text', 1, 'energy conservation', '{"why":"Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.\nStep 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses).","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","Step 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses)."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Work"}', 2),
  (1306, 366, 'A force of 10N moves an object 6m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases when force or distance increases.","sol":"Step 1: F = 10 N, d = 6 m\nStep 2: W = 10 × 6\nStep 3: W = 60 J","steps":["Step 1: F = 10 N, d = 6 m","Step 2: W = 10 × 6","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Work"}', 3),
  (1307, 366, 'A force of 15N moves an object 4m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends directly on force and displacement.","sol":"Step 1: F = 15 N, d = 4 m\nStep 2: W = 15 × 4\nStep 3: W = 60 J","steps":["Step 1: F = 15 N, d = 4 m","Step 2: W = 15 × 4","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Work"}', 4),
  (1308, 366, 'A force of 25N moves an object 2m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases with force applied.","sol":"Step 1: F = 25 N, d = 2 m\nStep 2: W = 25 × 2\nStep 3: W = 50 J","steps":["Step 1: F = 25 N, d = 2 m","Step 2: W = 25 × 2","Step 3: W = 50 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Work"}', 5),
  (1309, 366, 'A force of 30N moves an object 5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"More force or distance means more work done.","sol":"Step 1: F = 30 N, d = 5 m\nStep 2: W = 30 × 5\nStep 3: W = 150 J","steps":["Step 1: F = 30 N, d = 5 m","Step 2: W = 30 × 5","Step 3: W = 150 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Work"}', 6),
  (1310, 366, 'A force of 40N moves an object 1.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work can involve decimal distances.","sol":"Step 1: F = 40 N, d = 1.5 m\nStep 2: W = 40 × 1.5\nStep 3: W = 60 J","steps":["Step 1: F = 40 N, d = 1.5 m","Step 2: W = 40 × 1.5","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Work"}', 7),
  (1311, 366, 'A force of 12N moves an object 8m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends on both force and displacement.","sol":"Step 1: F = 12 N, d = 8 m\nStep 2: W = 12 × 8\nStep 3: W = 96 J","steps":["Step 1: F = 12 N, d = 8 m","Step 2: W = 12 × 8","Step 3: W = 96 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Work"}', 8),
  (1312, 366, 'A force of 50N moves an object 0.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Even small distances produce work when force is large.","sol":"Step 1: F = 50 N, d = 0.5 m\nStep 2: W = 50 × 0.5\nStep 3: W = 25 J","steps":["Step 1: F = 50 N, d = 0.5 m","Step 2: W = 50 × 0.5","Step 3: W = 25 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Work"}', 9),
  (1313, 367, 'A machine uses 500J in 5s. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per unit time.","sol":"Step 1: Identify values → W = 500 J, t = 5 s\nStep 2: Write formula → P = W / t\nStep 3: Substitute → P = 500 / 5\nStep 4: Calculate → P = 100 W","steps":["Step 1: Identify values → W = 500 J, t = 5 s","Step 2: Write formula → P = W / t","Step 3: Substitute → P = 500 / 5","Step 4: Calculate → P = 100 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Power"}', 0),
  (1314, 367, 'What is the unit of power?', 'text', 1, 'SI unit', '{"why":"Power is measured in watts, where 1 watt = 1 joule per second.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.\nStep 3: State the final conclusion: Watt (W)","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.","Step 3: State the final conclusion: Watt (W)"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Power"}', 1),
  (1315, 367, 'Why do power companies use high voltage transmission?', 'text', 1, 'reduce energy loss', '{"why":"Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.\nStep 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses).","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","Step 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses)."],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Power"}', 2),
  (1316, 367, 'A device uses 1200 J of energy in 6 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how quickly energy is used.","sol":"Step 1: W = 1200 J, t = 6 s\nStep 2: P = 1200 / 6\nStep 3: P = 200 W","steps":["Step 1: W = 1200 J, t = 6 s","Step 2: P = 1200 / 6","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Power"}', 3),
  (1317, 367, 'A motor does 3000 J of work in 10 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power shows energy transfer rate.","sol":"Step 1: W = 3000 J, t = 10 s\nStep 2: P = 3000 / 10\nStep 3: P = 300 W","steps":["Step 1: W = 3000 J, t = 10 s","Step 2: P = 3000 / 10","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Power"}', 4),
  (1318, 367, 'A bulb uses 600 J in 3 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Electrical devices convert energy per second.","sol":"Step 1: W = 600 J, t = 3 s\nStep 2: P = 600 / 3\nStep 3: P = 200 W","steps":["Step 1: W = 600 J, t = 3 s","Step 2: P = 600 / 3","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Power"}', 5),
  (1319, 367, 'A heater uses 4500 J in 15 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power depends on how fast energy is used.","sol":"Step 1: W = 4500 J, t = 15 s\nStep 2: P = 4500 / 15\nStep 3: P = 300 W","steps":["Step 1: W = 4500 J, t = 15 s","Step 2: P = 4500 / 15","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Power"}', 6),
  (1320, 367, 'A machine uses 9000 J in 30 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is energy per unit time.","sol":"Step 1: W = 9000 J, t = 30 s\nStep 2: P = 9000 / 30\nStep 3: P = 300 W","steps":["Step 1: W = 9000 J, t = 30 s","Step 2: P = 9000 / 30","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Power"}', 7),
  (1321, 367, 'A motor transfers 1500 J in 5 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is directly proportional to energy and inversely to time.","sol":"Step 1: W = 1500 J, t = 5 s\nStep 2: P = 1500 / 5\nStep 3: P = 300 W","steps":["Step 1: W = 1500 J, t = 5 s","Step 2: P = 1500 / 5","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Power"}', 8),
  (1322, 367, 'A device uses 2400 J in 8 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power tells how fast energy is used.","sol":"Step 1: W = 2400 J, t = 8 s\nStep 2: P = 2400 / 8\nStep 3: P = 300 W","steps":["Step 1: W = 2400 J, t = 8 s","Step 2: P = 2400 / 8","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Power"}', 9),
  (1323, 367, 'A generator produces 10000 J in 20 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Generators convert mechanical energy into electrical power.","sol":"Step 1: W = 10000 J, t = 20 s\nStep 2: P = 10000 / 20\nStep 3: P = 500 W","steps":["Step 1: W = 10000 J, t = 20 s","Step 2: P = 10000 / 20","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Power"}', 10),
  (1324, 368, 'What happens to energy when a car moves?', 'text', 1, 'fuel transformation', '{"why":"The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.\nStep 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","Step 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 0),
  (1325, 368, 'Is energy ever destroyed?', 'text', 1, 'law of conservation', '{"why":"According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.\nStep 3: State the final conclusion: No, energy is always conserved and only changes form.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","Step 3: State the final conclusion: No, energy is always conserved and only changes form."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 1),
  (1326, 368, 'What energy change happens in a falling object?', 'text', 1, 'height to motion', '{"why":"As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.\nStep 3: State the final conclusion: Gravitational potential energy → kinetic energy","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","Step 3: State the final conclusion: Gravitational potential energy → kinetic energy"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 2),
  (1327, 368, 'A 2 kg object is lifted to a height of 5 m. Find its potential energy (g = 10 m/s²).', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravitational field strength.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m\nStep 2: Substitute into formula → PE = 2 × 10 × 5\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m","Step 2: Substitute into formula → PE = 2 × 10 × 5","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 3),
  (1328, 368, 'A 3 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'Use KE = 1/2 mv²', '{"why":"Kinetic energy increases with velocity squared.","sol":"Step 1: m = 3 kg, v = 4 m/s\nStep 2: Square velocity → 4² = 16\nStep 3: Substitute → KE = 1/2 × 3 × 16\nStep 4: Multiply → KE = 24 J","steps":["Step 1: m = 3 kg, v = 4 m/s","Step 2: Square velocity → 4² = 16","Step 3: Substitute → KE = 1/2 × 3 × 16","Step 4: Multiply → KE = 24 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 4),
  (1329, 368, 'A car engine does 5000 J of work in 10 seconds. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per second.","sol":"Step 1: W = 5000 J, t = 10 s\nStep 2: Substitute → P = 5000 / 10\nStep 3: Calculate → P = 500 W","steps":["Step 1: W = 5000 J, t = 10 s","Step 2: Substitute → P = 5000 / 10","Step 3: Calculate → P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 5),
  (1330, 368, 'A 4 kg object is lifted 3 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher mass or height increases potential energy.","sol":"Step 1: m = 4 kg, g = 10 m/s², h = 3 m\nStep 2: Substitute → PE = 4 × 10 × 3\nStep 3: Multiply → PE = 120 J","steps":["Step 1: m = 4 kg, g = 10 m/s², h = 3 m","Step 2: Substitute → PE = 4 × 10 × 3","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 6),
  (1331, 368, 'A 5 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = 1/2 mv²', '{"why":"Even small velocity changes affect kinetic energy significantly.","sol":"Step 1: m = 5 kg, v = 2 m/s\nStep 2: v² = 4\nStep 3: KE = 1/2 × 5 × 4\nStep 4: KE = 10 J","steps":["Step 1: m = 5 kg, v = 2 m/s","Step 2: v² = 4","Step 3: KE = 1/2 × 5 × 4","Step 4: KE = 10 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 7),
  (1332, 368, 'A machine converts 2000 J of energy in 4 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how fast energy is used or transferred.","sol":"Step 1: W = 2000 J, t = 4 s\nStep 2: P = 2000 / 4\nStep 3: P = 500 W","steps":["Step 1: W = 2000 J, t = 4 s","Step 2: P = 2000 / 4","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 8),
  (1333, 368, 'A 1 kg object falls from 10 m. Find potential energy before falling.', 'text', 1, 'PE = mgh', '{"why":"All potential energy becomes kinetic energy during fall.","sol":"Step 1: m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: PE = 1 × 10 × 10\nStep 3: PE = 100 J","steps":["Step 1: m = 1 kg, g = 10 m/s², h = 10 m","Step 2: PE = 1 × 10 × 10","Step 3: PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 9),
  (1334, 368, 'A system has 600 J of energy input and 150 J is lost as heat. Find useful energy output.', 'text', 1, 'useful = input - loss', '{"why":"Some energy is always lost, usually as heat or sound.","sol":"Step 1: Input = 600 J\nStep 2: Loss = 150 J\nStep 3: Useful = 600 - 150\nStep 4: Useful = 450 J","steps":["Step 1: Input = 600 J","Step 2: Loss = 150 J","Step 3: Useful = 600 - 150","Step 4: Useful = 450 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 10),
  (1335, 369, 'A 2kg object falls from 5m. Find total energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"mgh = 2 × 10 × 5 = 100J","steps":["Step 1: Identify the given values: mass (m) = 2kg, height (h) = 5m, and gravitational acceleration (g) ≈ 10m/s².","Step 2: Recall the formula for gravitational potential energy: PE = m × g × h.","Step 3: Substitute the known values into the equation: PE = 2 × 10 × 5.","Step 4: Calculate the final value to find the total mechanical energy: 100 Joules (100J)."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 0),
  (1336, 369, 'A 5kg object is lifted to a height of 8m. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = mgh = 5 × 10 × 8 = 400J","steps":["Step 1: Identify the values: m = 5kg, h = 8m, g = 10m/s².","Step 2: Recall the formula PE = m × g × h.","Step 3: Substitute the values: PE = 5 × 10 × 8.","Step 4: Calculate the answer: 400 Joules."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 1),
  (1337, 369, 'A 4kg object moves at 6m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½mv² = ½ × 4 × 6² = 72J","steps":["Step 1: Identify the mass (4kg) and velocity (6m/s).","Step 2: Recall the formula KE = ½mv².","Step 3: Square the velocity: 6² = 36.","Step 4: Calculate: ½ × 4 × 36 = 72J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 2),
  (1338, 369, 'A car of mass 1000kg travels at 20m/s. Calculate its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 1000 × 20² = 200000J","steps":["Step 1: Identify m = 1000kg and v = 20m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the speed: 20² = 400.","Step 4: Calculate: ½ × 1000 × 400 = 200000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 3),
  (1339, 369, 'A 10N force moves an object through 6m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = Force × Distance = 10 × 6 = 60J","steps":["Step 1: Identify force = 10N and distance = 6m.","Step 2: Recall the formula Work = Force × Distance.","Step 3: Substitute the values: 10 × 6.","Step 4: Calculate the work done: 60J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 4),
  (1340, 369, 'A machine does 500J of work in 10 seconds. Calculate its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = Work ÷ Time = 500 ÷ 10 = 50W","steps":["Step 1: Identify work = 500J and time = 10s.","Step 2: Recall the formula Power = Work ÷ Time.","Step 3: Substitute the values into the formula.","Step 4: Divide 500 by 10 to obtain 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 5),
  (1341, 369, 'A 3kg object is raised 15m above the ground. Find its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 3 × 10 × 15 = 450J","steps":["Step 1: Identify m = 3kg, h = 15m, g = 10m/s².","Step 2: Recall PE = mgh.","Step 3: Substitute: 3 × 10 × 15.","Step 4: Calculate: 450J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 6),
  (1342, 369, 'A 6kg object moves with a speed of 5m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 6 × 5² = 75J","steps":["Step 1: Identify mass and velocity.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 5² = 25.","Step 4: Calculate: ½ × 6 × 25 = 75J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 7),
  (1343, 369, 'A 50N force pushes a box for 12m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 50 × 12 = 600J","steps":["Step 1: Identify force = 50N and distance = 12m.","Step 2: Recall Work = Force × Distance.","Step 3: Multiply the given values.","Step 4: The work done is 600J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 8),
  (1344, 369, 'A motor produces 2400J of work in 60 seconds. Find its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 2400 ÷ 60 = 40W","steps":["Step 1: Identify work = 2400J and time = 60s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 2400 by 60 to get 40W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 9),
  (1345, 369, 'A 7kg object is placed 9m above the ground. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 7 × 10 × 9 = 630J","steps":["Step 1: Identify m = 7kg, h = 9m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values using g = 10m/s².","Step 4: Calculate 630J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 10),
  (1346, 369, 'A cyclist and bicycle have a combined mass of 80kg and move at 10m/s. Calculate the kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 80 × 10² = 4000J","steps":["Step 1: Identify mass = 80kg and velocity = 10m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 10² = 100.","Step 4: Calculate: ½ × 80 × 100 = 4000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q12","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 11),
  (1347, 369, 'A crane lifts a 200kg load by 5m. Calculate the gain in potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 200 × 10 × 5 = 10000J","steps":["Step 1: Identify m = 200kg and h = 5m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values.","Step 4: Calculate the gain in potential energy: 10000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q13","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 12),
  (1348, 369, 'A machine uses 1500J of energy in 30 seconds. Find its power output.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 1500 ÷ 30 = 50W","steps":["Step 1: Identify work = 1500J and time = 30s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 1500 by 30 to get 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q14","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 13),
  (1349, 369, 'A 12N force moves an object 15m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 12 × 15 = 180J","steps":["Step 1: Identify force = 12N and distance = 15m.","Step 2: Recall Work = Force × Distance.","Step 3: Substitute the values.","Step 4: Calculate: 180J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q15","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 14),
  (1350, 370, 'A 2 kg object moves at 3 m/s. Find kinetic energy.', 'text', 1, 'Use KE = ½mv²', '{"why":"Kinetic energy depends on mass and the square of velocity.","sol":"Step 1: Identify values → m = 2 kg, v = 3 m/s\nStep 2: Substitute into formula → KE = 1/2 × 2 × 3²\nStep 3: Square velocity → 3² = 9\nStep 4: Multiply → KE = 1 × 9\nStep 5: Final answer → KE = 9 J","steps":["Step 1: Identify values → m = 2 kg, v = 3 m/s","Step 2: Substitute into formula → KE = 1/2 × 2 × 3²","Step 3: Square velocity → 3² = 9","Step 4: Multiply → KE = 1 × 9","Step 5: Final answer → KE = 9 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 0),
  (1351, 370, 'A 3 kg object is raised to a height of 4 m. Find potential energy.', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravity.","sol":"Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m\nStep 2: Substitute → PE = 3 × 10 × 4\nStep 3: Multiply → PE = 120 J","steps":["Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m","Step 2: Substitute → PE = 3 × 10 × 4","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 1),
  (1352, 370, 'What happens to potential energy when an object falls?', 'text', 1, 'energy conversion', '{"why":"As height decreases, potential energy is transformed into motion energy.","sol":"Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.\nStep 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.\nStep 3: State the final conclusion: It is converted into kinetic energy.","steps":["Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.","Step 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.","Step 3: State the final conclusion: It is converted into kinetic energy."],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 2),
  (1353, 370, 'A 5 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy increases with mass and velocity squared.","sol":"Step 1: m = 5 kg, v = 4 m/s\nStep 2: Substitute → KE = 1/2 × 5 × 4²\nStep 3: 4² = 16\nStep 4: KE = 2.5 × 16\nStep 5: KE = 40 J","steps":["Step 1: m = 5 kg, v = 4 m/s","Step 2: Substitute → KE = 1/2 × 5 × 4²","Step 3: 4² = 16","Step 4: KE = 2.5 × 16","Step 5: KE = 40 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 3),
  (1354, 370, 'A 2 kg object is lifted to 6 m. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher height increases potential energy.","sol":"Step 1: m = 2 kg, g = 10, h = 6 m\nStep 2: Substitute → PE = 2 × 10 × 6\nStep 3: Calculate → PE = 120 J","steps":["Step 1: m = 2 kg, g = 10, h = 6 m","Step 2: Substitute → PE = 2 × 10 × 6","Step 3: Calculate → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 4),
  (1355, 370, 'A 4 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy depends on velocity squared.","sol":"Step 1: m = 4 kg, v = 2 m/s\nStep 2: Substitute → KE = 1/2 × 4 × 2²\nStep 3: 2² = 4\nStep 4: KE = 2 × 4\nStep 5: KE = 8 J","steps":["Step 1: m = 4 kg, v = 2 m/s","Step 2: Substitute → KE = 1/2 × 4 × 2²","Step 3: 2² = 4","Step 4: KE = 2 × 4","Step 5: KE = 8 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 5),
  (1356, 370, 'A 1 kg object is lifted 10 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Potential energy increases with both height and mass because more work is needed to lift an object higher in a gravitational field.","sol":"Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: Substitute into formula → PE = 1 × 10 × 10\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m","Step 2: Substitute into formula → PE = 1 × 10 × 10","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 6),
  (1357, 371, 'A wave travels at 15 m/s and has frequency 3 Hz. Find wavelength.', 'text', 1, 'Use v = fλ', '{"why":"Wavelength is found by dividing wave speed by frequency.","sol":"Step 1: Identify values → v = 15 m/s, f = 3 Hz\nStep 2: Use formula → λ = v / f\nStep 3: Substitute → λ = 15 / 3\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 15 m/s, f = 3 Hz","Step 2: Use formula → λ = v / f","Step 3: Substitute → λ = 15 / 3","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wave properties"}', 0),
  (1358, 371, 'A wave has wavelength 4 m and frequency 6 Hz. Find wave speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 6 Hz, λ = 4 m\nStep 2: Use formula → v = f × λ\nStep 3: Substitute → v = 6 × 4\nStep 4: Calculate → v = 24 m/s","steps":["Step 1: Identify values → f = 6 Hz, λ = 4 m","Step 2: Use formula → v = f × λ","Step 3: Substitute → v = 6 × 4","Step 4: Calculate → v = 24 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wave properties"}', 1),
  (1359, 371, 'Time period is 0.5 s. Find frequency.', 'text', 1, 'f = 1/T', '{"why":"Frequency is the number of waves per second.","sol":"Step 1: Identify time period → T = 0.5 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 0.5\nStep 4: Calculate → f = 2 Hz","steps":["Step 1: Identify time period → T = 0.5 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 0.5","Step 4: Calculate → f = 2 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wave properties"}', 2),
  (1360, 371, 'A wave has speed 40 m/s and wavelength 8 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency equals speed divided by wavelength.","sol":"Step 1: Identify values → v = 40 m/s, λ = 8 m\nStep 2: Use formula → f = v / λ\nStep 3: Substitute → f = 40 / 8\nStep 4: Calculate → f = 5 Hz","steps":["Step 1: Identify values → v = 40 m/s, λ = 8 m","Step 2: Use formula → f = v / λ","Step 3: Substitute → f = 40 / 8","Step 4: Calculate → f = 5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Wave properties"}', 3),
  (1361, 371, 'A wave has frequency 10 Hz and speed 50 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: Identify values → v = 50 m/s, f = 10 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 50 / 10\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 50 m/s, f = 10 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 50 / 10","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Wave properties"}', 4),
  (1362, 371, 'A wave takes 2 s to complete 1 cycle. Find frequency.', 'text', 1, 'T = 1/f', '{"why":"Frequency is inversely proportional to time period.","sol":"Step 1: Identify time period → T = 2 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 2\nStep 4: Calculate → f = 0.5 Hz","steps":["Step 1: Identify time period → T = 2 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 2","Step 4: Calculate → f = 0.5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Wave properties"}', 5),
  (1363, 371, 'A wave has wavelength 2 m and speed 12 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is found by dividing speed by wavelength.","sol":"Step 1: Identify values → v = 12 m/s, λ = 2 m\nStep 2: Apply formula → f = v / λ\nStep 3: Substitute → f = 12 / 2\nStep 4: Calculate → f = 6 Hz","steps":["Step 1: Identify values → v = 12 m/s, λ = 2 m","Step 2: Apply formula → f = v / λ","Step 3: Substitute → f = 12 / 2","Step 4: Calculate → f = 6 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Wave properties"}', 6),
  (1364, 371, 'A wave has frequency 50 Hz and wavelength 0.2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed equals frequency times wavelength.","sol":"Step 1: Identify values → f = 50 Hz, λ = 0.2 m\nStep 2: Apply formula → v = f × λ\nStep 3: Substitute → v = 50 × 0.2\nStep 4: Calculate → v = 10 m/s","steps":["Step 1: Identify values → f = 50 Hz, λ = 0.2 m","Step 2: Apply formula → v = f × λ","Step 3: Substitute → v = 50 × 0.2","Step 4: Calculate → v = 10 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Wave properties"}', 7),
  (1365, 371, 'A wave travels 100 m in 5 s. Find its speed.', 'text', 1, 'speed = distance/time', '{"why":"Speed is distance divided by time.","sol":"Step 1: Identify values → d = 100 m, t = 5 s\nStep 2: Use formula → v = d / t\nStep 3: Substitute → v = 100 / 5\nStep 4: Calculate → v = 20 m/s","steps":["Step 1: Identify values → d = 100 m, t = 5 s","Step 2: Use formula → v = d / t","Step 3: Substitute → v = 100 / 5","Step 4: Calculate → v = 20 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Wave properties"}', 8),
  (1366, 371, 'A wave has speed 30 m/s and frequency 5 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength equals speed divided by frequency.","sol":"Step 1: Identify values → v = 30 m/s, f = 5 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 30 / 5\nStep 4: Calculate → λ = 6 m","steps":["Step 1: Identify values → v = 30 m/s, f = 5 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 30 / 5","Step 4: Calculate → λ = 6 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Wave properties"}', 9),
  (1367, 372, 'A sound wave has frequency 200 Hz and wavelength 1.5 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Speed of sound is found by multiplying frequency and wavelength.","sol":"Step 1: Identify values → f = 200 Hz, λ = 1.5 m\nStep 2: Apply formula → v = fλ\nStep 3: Substitute → v = 200 × 1.5\nStep 4: Calculate → v = 300 m/s","steps":["Step 1: Identify values → f = 200 Hz, λ = 1.5 m","Step 2: Apply formula → v = fλ","Step 3: Substitute → v = 200 × 1.5","Step 4: Calculate → v = 300 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Sound waves"}', 0),
  (1368, 372, 'A sound wave has frequency 100 Hz and wavelength 2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed depends on both frequency and wavelength.","sol":"Step 1: f = 100 Hz, λ = 2 m\nStep 2: v = fλ\nStep 3: v = 100 × 2\nStep 4: v = 200 m/s","steps":["Step 1: f = 100 Hz, λ = 2 m","Step 2: v = fλ","Step 3: v = 100 × 2","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Sound waves"}', 1),
  (1369, 372, 'A sound wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: v = 340 m/s, f = 170 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/170\nStep 4: λ = 2 m","steps":["Step 1: v = 340 m/s, f = 170 Hz","Step 2: λ = v/f","Step 3: λ = 340/170","Step 4: λ = 2 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Sound waves"}', 2),
  (1370, 372, 'A sound wave has wavelength 0.5 m and speed 150 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is calculated by dividing speed by wavelength.","sol":"Step 1: v = 150 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 150/0.5\nStep 4: f = 300 Hz","steps":["Step 1: v = 150 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 150/0.5","Step 4: f = 300 Hz"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Sound waves"}', 3),
  (1371, 372, 'Why can''t sound travel in space?', 'text', 1, 'no particles', '{"why":"Sound needs particles to vibrate, but space is a vacuum with no particles.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.\nStep 3: State the final conclusion: Because there is no medium for sound waves to travel through.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.","Step 3: State the final conclusion: Because there is no medium for sound waves to travel through."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Sound waves"}', 4),
  (1372, 372, 'What determines loudness of sound?', 'text', 1, 'wave height', '{"why":"Greater amplitude means louder sound, lower amplitude means softer sound.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.\nStep 3: State the final conclusion: Amplitude","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.","Step 3: State the final conclusion: Amplitude"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Sound waves"}', 5),
  (1373, 372, 'What determines pitch of sound?', 'text', 1, 'frequency', '{"why":"High frequency produces high pitch sound and low frequency produces low pitch.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.\nStep 3: State the final conclusion: Frequency","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.","Step 3: State the final conclusion: Frequency"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Sound waves"}', 6),
  (1374, 372, 'What is a sound wave?', 'text', 1, 'vibration', '{"why":"Sound waves travel through air, liquids, or solids by particle vibration.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.\nStep 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.","Step 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Sound waves"}', 7),
  (1375, 372, 'What type of wave is sound?', 'text', 1, 'mechanical', '{"why":"Sound requires a medium to travel, so it is a mechanical wave.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.\nStep 3: State the final conclusion: A mechanical wave","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.","Step 3: State the final conclusion: A mechanical wave"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Sound waves"}', 8),
  (1376, 372, 'A sound wave has frequency 50 Hz and speed 340 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength depends on speed and frequency.","sol":"Step 1: v = 340 m/s, f = 50 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/50\nStep 4: λ = 6.8 m","steps":["Step 1: v = 340 m/s, f = 50 Hz","Step 2: λ = v/f","Step 3: λ = 340/50","Step 4: λ = 6.8 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Sound waves"}', 9),
  (1377, 372, 'What is echo?', 'text', 1, 'reflection of sound', '{"why":"Sound reflects off surfaces and returns to the listener after a delay.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.\nStep 3: State the final conclusion: Echo is the reflection of sound waves.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.","Step 3: State the final conclusion: Echo is the reflection of sound waves."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Sound waves"}', 10),
  (1378, 372, 'Why is sound faster in solids than in air?', 'text', 1, 'particle spacing', '{"why":"Closer particles transfer vibrations faster in solids than in gases.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.\nStep 3: State the final conclusion: Because particles are closer together in solids.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.","Step 3: State the final conclusion: Because particles are closer together in solids."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Sound waves"}', 11),
  (1379, 373, 'A light wave has frequency 4 × 10^14 Hz and wavelength 7.5 × 10^-7 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m\nStep 2: Write formula → v = fλ\nStep 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)\nStep 4: Multiply numbers → 4 × 7.5 = 30\nStep 5: Add powers → 10^14 × 10^-7 = 10^7\nStep 6: Final result → v = 3 × 10^8 m/s","steps":["Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m","Step 2: Write formula → v = fλ","Step 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)","Step 4: Multiply numbers → 4 × 7.5 = 30","Step 5: Add powers → 10^14 × 10^-7 = 10^7","Step 6: Final result → v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Light waves"}', 0),
  (1380, 373, 'A wave has frequency 2 × 10^6 Hz and wavelength 0.15 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Speed is directly proportional to frequency and wavelength.","sol":"Step 1: f = 2 × 10^6 Hz, λ = 0.15 m\nStep 2: v = fλ\nStep 3: v = (2 × 10^6) × 0.15\nStep 4: 2 × 0.15 = 0.3\nStep 5: v = 0.3 × 10^6\nStep 6: v = 3 × 10^5 m/s","steps":["Step 1: f = 2 × 10^6 Hz, λ = 0.15 m","Step 2: v = fλ","Step 3: v = (2 × 10^6) × 0.15","Step 4: 2 × 0.15 = 0.3","Step 5: v = 0.3 × 10^6","Step 6: v = 3 × 10^5 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Light waves"}', 1),
  (1381, 373, 'A wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is found by dividing speed by frequency.","sol":"Step 1: Identify values → v = 340 m/s, f = 170 Hz\nStep 2: Write formula → λ = v/f\nStep 3: Substitute → λ = 340/170\nStep 4: Calculate → λ = 2 m","steps":["Step 1: Identify values → v = 340 m/s, f = 170 Hz","Step 2: Write formula → λ = v/f","Step 3: Substitute → λ = 340/170","Step 4: Calculate → λ = 2 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Light waves"}', 2),
  (1382, 373, 'A wave has wavelength 0.5 m and speed 200 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is speed divided by wavelength.","sol":"Step 1: v = 200 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 200/0.5\nStep 4: f = 400 Hz","steps":["Step 1: v = 200 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 200/0.5","Step 4: f = 400 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Light waves"}', 3),
  (1383, 373, 'A wave has frequency 5 × 10^5 Hz and speed 1 × 10^8 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength increases when frequency decreases.","sol":"Step 1: v = 1 × 10^8, f = 5 × 10^5\nStep 2: λ = v/f\nStep 3: λ = (1 × 10^8) / (5 × 10^5)\nStep 4: 1/5 = 0.2\nStep 5: 10^8 / 10^5 = 10^3\nStep 6: λ = 0.2 × 10^3 = 200 m","steps":["Step 1: v = 1 × 10^8, f = 5 × 10^5","Step 2: λ = v/f","Step 3: λ = (1 × 10^8) / (5 × 10^5)","Step 4: 1/5 = 0.2","Step 5: 10^8 / 10^5 = 10^3","Step 6: λ = 0.2 × 10^3 = 200 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Light waves"}', 4),
  (1384, 373, 'A wave has wavelength 3 m and frequency 50 Hz. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed is product of frequency and wavelength.","sol":"Step 1: f = 50 Hz, λ = 3 m\nStep 2: v = fλ\nStep 3: v = 50 × 3\nStep 4: v = 150 m/s","steps":["Step 1: f = 50 Hz, λ = 3 m","Step 2: v = fλ","Step 3: v = 50 × 3","Step 4: v = 150 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Light waves"}', 5),
  (1385, 373, 'A light wave has frequency 6 × 10^14 Hz and wavelength 5 × 10^-7 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Light speed in vacuum is constant.","sol":"Step 1: f = 6 × 10^14, λ = 5 × 10^-7\nStep 2: v = fλ\nStep 3: Multiply → 6 × 5 = 30\nStep 4: Add powers → 10^14 × 10^-7 = 10^7\nStep 5: v = 3 × 10^8 m/s","steps":["Step 1: f = 6 × 10^14, λ = 5 × 10^-7","Step 2: v = fλ","Step 3: Multiply → 6 × 5 = 30","Step 4: Add powers → 10^14 × 10^-7 = 10^7","Step 5: v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Light waves"}', 6),
  (1386, 373, 'A wave travels 600 m in 3 seconds. Find its speed.', 'text', 1, 'v = d/t', '{"why":"Speed is distance divided by time.","sol":"Step 1: d = 600 m, t = 3 s\nStep 2: v = d/t\nStep 3: v = 600/3\nStep 4: v = 200 m/s","steps":["Step 1: d = 600 m, t = 3 s","Step 2: v = d/t","Step 3: v = 600/3","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Light waves"}', 7),
  (1387, 373, 'A wave has speed 300 m/s and wavelength 0.6 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency depends on speed and wavelength.","sol":"Step 1: v = 300 m/s, λ = 0.6 m\nStep 2: f = v/λ\nStep 3: f = 300/0.6\nStep 4: f = 500 Hz","steps":["Step 1: v = 300 m/s, λ = 0.6 m","Step 2: f = v/λ","Step 3: f = 300/0.6","Step 4: f = 500 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Light waves"}', 8),
  (1388, 373, 'Why can light travel in space?', 'text', 1, 'no medium required', '{"why":"Unlike sound, light can travel through a vacuum because it does not rely on particles.","sol":"Step 1: Identify key concept: Define the required principles for Light waves.\nStep 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.\nStep 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium.","steps":["Step 1: Identify key concept: Define the required principles for Light waves.","Step 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.","Step 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium."],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Light waves"}', 9),
  (1389, 374, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 0),
  (1390, 374, 'A ray of light hits a mirror at 60°. Find angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that the angle of incidence equals the angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Use law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Use law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 1),
  (1391, 374, 'A light ray strikes a mirror at 30°. Calculate the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"Reflection follows the law i = r, meaning angles are equal.","sol":"Step 1: Identify angle of incidence → i = 30°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 30°","steps":["Step 1: Identify angle of incidence → i = 30°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 30°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 2),
  (1392, 374, 'A ray hits a mirror at 45°. What is the angle between the incident ray and reflected ray?', 'text', 1, 'sum of angles', '{"why":"The angle between incident and reflected rays equals twice the angle of incidence.","sol":"Step 1: Identify incidence angle → i = 45°\nStep 2: Reflection angle → r = 45°\nStep 3: Add angles → 45° + 45°\nStep 4: Result = 90°","steps":["Step 1: Identify incidence angle → i = 45°","Step 2: Reflection angle → r = 45°","Step 3: Add angles → 45° + 45°","Step 4: Result = 90°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 3),
  (1393, 374, 'A light ray travels from air into glass and slows down. What happens to its direction?', 'text', 1, 'refraction effect', '{"why":"When light enters a denser medium, it slows down and bends towards the normal line.","sol":"Step 1: Light enters denser medium (air → glass)\nStep 2: Speed decreases\nStep 3: Ray bends towards the normal\nStep 4: New direction is closer to normal line","steps":["Step 1: Light enters denser medium (air → glass)","Step 2: Speed decreases","Step 3: Ray bends towards the normal","Step 4: New direction is closer to normal line"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 4),
  (1394, 374, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 5),
  (1395, 374, 'A ray of light hits a mirror at 60°. Find the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that angle of incidence equals angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 6),
  (1396, 374, 'A ray of light strikes a plane mirror at 35°. Calculate the angle of reflection.', 'text', 1, 'i = r', '{"why":"Reflection obeys i = r at all times.","sol":"Step 1: Given angle of incidence → i = 35°\nStep 2: Apply law of reflection → r = i\nStep 3: Substitute → r = 35°","steps":["Step 1: Given angle of incidence → i = 35°","Step 2: Apply law of reflection → r = i","Step 3: Substitute → r = 35°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 7),
  (1397, 374, 'A light ray is incident on a mirror at 40°. Find the angle between the incident ray and reflected ray.', 'text', 1, 'geometry of reflection', '{"why":"The geometry of reflection gives angle between incident and reflected rays as 2i.","sol":"Step 1: Identify incidence angle → i = 40°\nStep 2: Use relation → angle between rays = 2i\nStep 3: Substitute → 2 × 40°\nStep 4: Calculate → 80°","steps":["Step 1: Identify incidence angle → i = 40°","Step 2: Use relation → angle between rays = 2i","Step 3: Substitute → 2 × 40°","Step 4: Calculate → 80°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 8),
  (1398, 374, 'A ray passes from air into glass. Refractive index of glass is 1.5. If angle of incidence is 30°, calculate angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Snell’s law relates angles of incidence and refraction using refractive indices.","sol":"Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°\nStep 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r\nStep 3: Substitute → 0.5 = 1.5 sin r\nStep 4: Solve → sin r = 0.333\nStep 5: Find r → r ≈ 19.5°","steps":["Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°","Step 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r","Step 3: Substitute → 0.5 = 1.5 sin r","Step 4: Solve → sin r = 0.333","Step 5: Find r → r ≈ 19.5°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 9),
  (1399, 374, 'A ray enters glass (n = 1.5) from air at 45°. Find angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Light bends towards the normal when entering a denser medium.","sol":"Step 1: n1 = 1, n2 = 1.5, i = 45°\nStep 2: Apply formula → sin r = (1 × sin45°)/1.5\nStep 3: sin45° = 0.707\nStep 4: sin r = 0.707/1.5 = 0.471\nStep 5: r ≈ 28.1°","steps":["Step 1: n1 = 1, n2 = 1.5, i = 45°","Step 2: Apply formula → sin r = (1 × sin45°)/1.5","Step 3: sin45° = 0.707","Step 4: sin r = 0.707/1.5 = 0.471","Step 5: r ≈ 28.1°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 10),
  (1400, 375, 'Why does sound bend around corners?', 'text', 1, 'wave spreading', '{"why":"Diffraction is the spreading of waves when they pass around obstacles or through gaps.","sol":"Step 1: Identify wave type → sound is a wave\nStep 2: Waves can bend when passing obstacles\nStep 3: This bending is called diffraction\nStep 4: Apply concept → sound spreads around corners","steps":["Step 1: Identify wave type → sound is a wave","Step 2: Waves can bend when passing obstacles","Step 3: This bending is called diffraction","Step 4: Apply concept → sound spreads around corners"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 0),
  (1401, 375, 'What happens in destructive interference?', 'text', 1, 'opposite phases', '{"why":"Destructive interference occurs when waves meet out of phase and reduce total amplitude.","sol":"Step 1: Two waves meet\nStep 2: One crest meets a trough\nStep 3: They cancel each other partially or fully\nStep 4: Resulting amplitude decreases","steps":["Step 1: Two waves meet","Step 2: One crest meets a trough","Step 3: They cancel each other partially or fully","Step 4: Resulting amplitude decreases"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 1),
  (1402, 375, 'If two identical waves meet crest to crest, what happens?', 'text', 1, 'same phase', '{"why":"Constructive interference occurs when waves combine in phase, increasing total amplitude.","sol":"Step 1: Identify phase → crest meets crest\nStep 2: Waves are in phase\nStep 3: Add amplitudes\nStep 4: Result = increased amplitude","steps":["Step 1: Identify phase → crest meets crest","Step 2: Waves are in phase","Step 3: Add amplitudes","Step 4: Result = increased amplitude"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 2),
  (1403, 375, 'Two identical waves each have amplitude 3 cm. They meet crest to crest. Find resultant amplitude.', 'text', 1, 'Use constructive interference (add amplitudes)', '{"why":"Constructive interference increases amplitude when waves meet in phase.","sol":"Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm\nStep 2: Waves meet crest to crest → constructive interference\nStep 3: Apply formula → A_result = A1 + A2\nStep 4: Substitute → A_result = 3 + 3\nStep 5: Calculate → A_result = 6 cm","steps":["Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm","Step 2: Waves meet crest to crest → constructive interference","Step 3: Apply formula → A_result = A1 + A2","Step 4: Substitute → A_result = 3 + 3","Step 5: Calculate → A_result = 6 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 3),
  (1404, 375, 'Two waves of amplitude 5 cm and 3 cm meet crest to trough. Find resultant amplitude.', 'text', 1, 'Use destructive interference (subtract amplitudes)', '{"why":"Destructive interference reduces amplitude when waves are out of phase.","sol":"Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm\nStep 2: Crest meets trough → destructive interference\nStep 3: Apply formula → A_result = A1 - A2\nStep 4: Substitute → A_result = 5 - 3\nStep 5: Calculate → A_result = 2 cm","steps":["Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm","Step 2: Crest meets trough → destructive interference","Step 3: Apply formula → A_result = A1 - A2","Step 4: Substitute → A_result = 5 - 3","Step 5: Calculate → A_result = 2 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 4),
  (1405, 375, 'A wave travels 340 m in 2 seconds. Find its speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Wave speed is distance covered per unit time.","sol":"Step 1: Identify values → d = 340 m, t = 2 s\nStep 2: Write formula → v = d / t\nStep 3: Substitute → v = 340 / 2\nStep 4: Calculate → v = 170 m/s","steps":["Step 1: Identify values → d = 340 m, t = 2 s","Step 2: Write formula → v = d / t","Step 3: Substitute → v = 340 / 2","Step 4: Calculate → v = 170 m/s"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 5),
  (1406, 376, 'A charge of 18C flows in 3s. Find current.', 'text', 1, 'Use I = Q / t', '{"why":"Current is the rate of flow of charge per unit time.","sol":"Step 1: Identify values → Q = 18C, t = 3s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 18 / 3\nStep 4: Calculate → I = 6A","steps":["Step 1: Identify values → Q = 18C, t = 3s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 18 / 3","Step 4: Calculate → I = 6A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 0),
  (1407, 376, 'Find current if V = 12V and R = 3Ω.', 'text', 1, 'Use Ohm''s Law I = V / R', '{"why":"Ohm''s Law relates voltage, current, and resistance.","sol":"Step 1: Identify values → V = 12V, R = 3Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 12 / 3\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 12V, R = 3Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 12 / 3","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 1),
  (1408, 376, 'Find the resistance if V = 24V and I = 6A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance opposes the flow of electric current.","sol":"Step 1: Identify values → V = 24V, I = 6A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 24 / 6\nStep 4: Calculate → R = 4Ω","steps":["Step 1: Identify values → V = 24V, I = 6A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 24 / 6","Step 4: Calculate → R = 4Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 2),
  (1409, 376, 'Find the voltage if I = 5A and R = 8Ω.', 'text', 1, 'Use V = IR', '{"why":"Voltage is the electrical energy supplied per unit charge.","sol":"Step 1: Identify values → I = 5A, R = 8Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 5 × 8\nStep 4: Calculate → V = 40V","steps":["Step 1: Identify values → I = 5A, R = 8Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 5 × 8","Step 4: Calculate → V = 40V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 3),
  (1410, 376, 'A charge of 60C flows in 12s. Find the current.', 'text', 1, 'Use I = Q / t', '{"why":"Current tells us how much charge passes a point each second.","sol":"Step 1: Identify values → Q = 60C, t = 12s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 60 / 12\nStep 4: Calculate → I = 5A","steps":["Step 1: Identify values → Q = 60C, t = 12s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 60 / 12","Step 4: Calculate → I = 5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 4),
  (1411, 376, 'A bulb uses 120W at 240V. Find the current.', 'text', 1, 'Use P = VI', '{"why":"Power equals voltage multiplied by current.","sol":"Step 1: Identify values → P = 120W, V = 240V\nStep 2: Rearrange formula → I = P / V\nStep 3: Substitute values → I = 120 / 240\nStep 4: Calculate → I = 0.5A","steps":["Step 1: Identify values → P = 120W, V = 240V","Step 2: Rearrange formula → I = P / V","Step 3: Substitute values → I = 120 / 240","Step 4: Calculate → I = 0.5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 5),
  (1412, 376, 'A circuit has V = 18V and I = 3A. Find the power.', 'text', 1, 'Use P = VI', '{"why":"Electrical power is the rate at which electrical energy is used.","sol":"Step 1: Identify values → V = 18V, I = 3A\nStep 2: Write formula → P = VI\nStep 3: Substitute values → P = 18 × 3\nStep 4: Calculate → P = 54W","steps":["Step 1: Identify values → V = 18V, I = 3A","Step 2: Write formula → P = VI","Step 3: Substitute values → P = 18 × 3","Step 4: Calculate → P = 54W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 6),
  (1413, 376, 'An appliance uses 1000J of energy in 50s. Find the power.', 'text', 1, 'Use P = E / t', '{"why":"Power measures how quickly energy is transferred.","sol":"Step 1: Identify values → E = 1000J, t = 50s\nStep 2: Write formula → P = E / t\nStep 3: Substitute values → P = 1000 / 50\nStep 4: Calculate → P = 20W","steps":["Step 1: Identify values → E = 1000J, t = 50s","Step 2: Write formula → P = E / t","Step 3: Substitute values → P = 1000 / 50","Step 4: Calculate → P = 20W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 7),
  (1414, 376, 'A resistor of 5Ω carries a current of 4A. Find the voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage across a resistor depends on current and resistance.","sol":"Step 1: Identify values → I = 4A, R = 5Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 4 × 5\nStep 4: Calculate → V = 20V","steps":["Step 1: Identify values → I = 4A, R = 5Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 4 × 5","Step 4: Calculate → V = 20V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 8),
  (1415, 376, 'Find the resistance if V = 30V and I = 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance determines how much a material opposes current flow.","sol":"Step 1: Identify values → V = 30V, I = 5A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 30 / 5\nStep 4: Calculate → R = 6Ω","steps":["Step 1: Identify values → V = 30V, I = 5A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 30 / 5","Step 4: Calculate → R = 6Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 9),
  (1416, 376, 'A battery supplies 48V to a 12Ω resistor. Find the current.', 'text', 1, 'Use I = V / R', '{"why":"Current increases when voltage increases or resistance decreases.","sol":"Step 1: Identify values → V = 48V, R = 12Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 48 / 12\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 48V, R = 12Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 48 / 12","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 10),
  (1417, 377, 'In a parallel circuit, branch currents are 2A, 3A and 5A. Find total current.', 'text', 1, 'Add all branch currents', '{"why":"In parallel circuits, total current is the sum of currents in all branches.","sol":"I(total) = 2 + 3 + 5 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In parallel circuits, total current is the sum of currents in all branches.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 0),
  (1418, 377, 'A series circuit has a current of 3A. What is the current through each resistor?', 'text', 1, 'Series = same current everywhere', '{"why":"In a series circuit, current is the same at all points because there is only one path.","sol":"I1 = I2 = I3 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In a series circuit, current is the same at all points because there is only one path.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 1),
  (1419, 377, 'A voltage of 12V is applied across a resistor of 4Ω. Find the current.', 'text', 1, 'Use Ohm’s Law: I = V / R', '{"why":"Ohm’s Law states that current equals voltage divided by resistance.","sol":"I = 12 / 4 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Ohm’s Law states that current equals voltage divided by resistance.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 2),
  (1420, 377, 'Find resistance if voltage is 20V and current is 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance is found by dividing voltage by current.","sol":"R = 20 / 5 = 4Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Resistance is found by dividing voltage by current.","Step 3: State the final conclusion: 4Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 3),
  (1421, 377, 'A circuit has two branches carrying 1.5A and 2.5A. Find total current.', 'text', 1, 'Sum branch currents', '{"why":"Total current in a parallel circuit is the sum of all branch currents.","sol":"1.5 + 2.5 = 4A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in a parallel circuit is the sum of all branch currents.","Step 3: State the final conclusion: 4A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 4),
  (1422, 377, 'If a 9V battery pushes 3A through a circuit, find resistance.', 'text', 1, 'R = V / I', '{"why":"Divide voltage by current to get resistance.","sol":"R = 9 / 3 = 3Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Divide voltage by current to get resistance.","Step 3: State the final conclusion: 3Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 5),
  (1423, 377, 'In a parallel circuit, total current is 8A. If one branch is 3A, find the other branch current.', 'text', 1, 'Subtract known current', '{"why":"Total current equals sum of branch currents, so subtract to find missing value.","sol":"8 - 3 = 5A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current equals sum of branch currents, so subtract to find missing value.","Step 3: State the final conclusion: 5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 6),
  (1424, 377, 'A resistor has 6Ω resistance and current of 2A. Find voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage equals current multiplied by resistance.","sol":"V = 2 × 6 = 12V","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Voltage equals current multiplied by resistance.","Step 3: State the final conclusion: 12V"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 7),
  (1425, 377, 'Two identical bulbs in series each carry 1.5A. What is total current?', 'text', 1, 'Series current rule', '{"why":"In series circuits, current is constant throughout the circuit.","sol":"Same current flows in series circuit","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In series circuits, current is constant throughout the circuit.","Step 3: State the final conclusion: 1.5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 8),
  (1426, 377, 'A circuit has 3 parallel branches carrying 2A, 2A and 6A. Find total current.', 'text', 1, 'Add all values', '{"why":"Total current in parallel circuits is the sum of branch currents.","sol":"2 + 2 + 6 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in parallel circuits is the sum of branch currents.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 9),
  (1427, 378, 'What is a magnetic field?', 'text', 1, 'region of influence', '{"why":"Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.\nStep 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","Step 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 0),
  (1428, 378, 'What do magnetic field lines show?', 'text', 1, 'direction + strength', '{"why":"Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.\nStep 3: State the final conclusion: They show the direction and strength of a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","Step 3: State the final conclusion: They show the direction and strength of a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 1),
  (1429, 378, 'In which direction do magnetic field lines flow outside a magnet?', 'text', 1, 'N to S', '{"why":"Outside the magnet, field lines always go from North to South, and inside they return from South to North.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.\nStep 3: State the final conclusion: From North pole to South pole.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.","Step 3: State the final conclusion: From North pole to South pole."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 2),
  (1430, 378, 'What are magnetic domains?', 'text', 1, 'tiny magnets', '{"why":"Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.\nStep 3: State the final conclusion: Small regions inside a material that behave like tiny magnets.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","Step 3: State the final conclusion: Small regions inside a material that behave like tiny magnets."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 3),
  (1431, 378, 'Why is a material unmagnetised?', 'text', 1, 'random orientation', '{"why":"Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.\nStep 3: State the final conclusion: Because its magnetic domains are randomly arranged.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","Step 3: State the final conclusion: Because its magnetic domains are randomly arranged."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 4),
  (1432, 378, 'What happens to magnetic domains when a material is magnetised?', 'text', 1, 'alignment', '{"why":"Aligned domains reinforce each other, producing a strong net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.\nStep 3: State the final conclusion: They align in the same direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.","Step 3: State the final conclusion: They align in the same direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 5),
  (1433, 378, 'Why is repulsion the only sure test for polarity?', 'text', 1, 'attraction is not enough', '{"why":"Only repulsion confirms that two poles are the same type (N–N or S–S).","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).\nStep 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).","Step 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 6),
  (1434, 378, 'What causes demagnetisation?', 'text', 1, 'heat, shock, AC', '{"why":"These disturb the alignment of magnetic domains, reducing or removing magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.\nStep 3: State the final conclusion: Heat, hammering, or alternating current.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.","Step 3: State the final conclusion: Heat, hammering, or alternating current."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 7),
  (1435, 378, 'Why does a compass needle align north-south?', 'text', 1, 'Earth is a magnet', '{"why":"The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.\nStep 3: State the final conclusion: Because Earth has a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","Step 3: State the final conclusion: Because Earth has a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 8),
  (1436, 378, 'How does stroking magnetise a material?', 'text', 1, 'domain alignment', '{"why":"Repeated stroking forces domains to line up, creating a net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.\nStep 3: State the final conclusion: It aligns magnetic domains in one direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.","Step 3: State the final conclusion: It aligns magnetic domains in one direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 9),
  (1437, 379, 'What is electromagnetism?', 'text', 1, 'electricity + magnetism', '{"why":"Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.\nStep 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","Step 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 0),
  (1438, 379, 'What happens when current flows in a wire?', 'text', 1, 'magnetic field forms', '{"why":"Moving electric charges (current) generate a magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field is produced around the wire.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field is produced around the wire."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 1),
  (1439, 379, 'Why is a solenoid stronger than a straight wire?', 'text', 1, 'many loops', '{"why":"Each loop produces a magnetic field and they add together, making the overall field stronger.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.\nStep 3: State the final conclusion: Because magnetic fields from each coil turn combine.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.","Step 3: State the final conclusion: Because magnetic fields from each coil turn combine."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 2),
  (1440, 379, 'How do you increase the strength of an electromagnet?', 'text', 1, 'current, turns, core', '{"why":"All these factors increase the strength of the magnetic field produced.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.\nStep 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.","Step 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 3),
  (1441, 379, 'What is the role of a soft iron core in an electromagnet?', 'text', 1, 'magnetic enhancement', '{"why":"Soft iron becomes magnetized easily and concentrates magnetic field lines.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.\nStep 3: State the final conclusion: It increases the strength of the magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.","Step 3: State the final conclusion: It increases the strength of the magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 4),
  (1442, 379, 'Why does reversing current reverse magnetic field direction?', 'text', 1, 'direction of charge flow', '{"why":"Changing current direction changes the motion of charges, reversing the field.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.\nStep 3: State the final conclusion: Because magnetic field direction depends on current direction.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.","Step 3: State the final conclusion: Because magnetic field direction depends on current direction."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 5),
  (1443, 379, 'What is produced around a current-carrying conductor?', 'text', 1, 'invisible force field', '{"why":"Electric current generates a circular magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 6),
  (1444, 379, 'Why do electromagnets stop working when current is switched off?', 'text', 1, 'temporary magnet', '{"why":"Without current, moving charges stop, so the magnetic field disappears.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.\nStep 3: State the final conclusion: Because the magnetic field depends on electric current.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.","Step 3: State the final conclusion: Because the magnetic field depends on electric current."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 7),
  (1445, 380, 'A voltage of 20V produces a current of 5A. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 20 / 5 = 4Ω","steps":["Step 1: Identify the given values: V = 20V and I = 5A.","Step 2: Recall Ohm''s Law for resistance: R = V / I.","Step 3: Substitute the values: R = 20 / 5.","Step 4: Calculate: R = 4Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 0),
  (1446, 380, 'Find the current if V = 12V and R = 3Ω.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 12 / 3 = 4A","steps":["Step 1: Identify the given values: V = 12V and R = 3Ω.","Step 2: Recall the formula: I = V / R.","Step 3: Substitute the values: I = 12 / 3.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 1),
  (1447, 380, 'State Ohm''s Law.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 2),
  (1448, 380, 'A battery supplies 24V to a resistor of 6Ω. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 24 / 6 = 4A","steps":["Step 1: Identify V = 24V and R = 6Ω.","Step 2: Use the formula I = V / R.","Step 3: Substitute the values: I = 24 / 6.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 3),
  (1449, 380, 'A current of 2A flows through a resistor of 10Ω. Find the voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"V = IR = 2 × 10 = 20V","steps":["Step 1: Identify I = 2A and R = 10Ω.","Step 2: Recall the formula: V = IR.","Step 3: Substitute the values: V = 2 × 10.","Step 4: Calculate: V = 20V."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 4),
  (1450, 380, 'A resistor has a voltage of 18V and a current of 3A. Find its resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 18 / 3 = 6Ω","steps":["Step 1: Identify V = 18V and I = 3A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 18 / 3.","Step 4: Calculate: R = 6Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 5),
  (1451, 380, 'A charge of 40C passes through a conductor in 8 seconds. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 40 / 8 = 5A","steps":["Step 1: Identify Q = 40C and t = 8s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 40 / 8.","Step 4: Calculate: I = 5A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 6),
  (1452, 380, 'A charge of 72C flows for 9 seconds. Calculate the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 72 / 9 = 8A","steps":["Step 1: Identify Q = 72C and t = 9s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 72 / 9.","Step 4: Calculate: I = 8A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 7),
  (1453, 380, 'A current of 5A flows for 12 seconds. Find the charge transferred.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 5 × 12 = 60C","steps":["Step 1: Identify I = 5A and t = 12s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 5 × 12.","Step 4: Calculate: Q = 60C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 8),
  (1454, 380, 'A current of 3A flows for 15 seconds. Calculate the charge.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 3 × 15 = 45C","steps":["Step 1: Identify I = 3A and t = 15s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 3 × 15.","Step 4: Calculate: Q = 45C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 9),
  (1455, 380, 'An electric heater operates at 240V and draws a current of 5A. Find the power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 240 × 5 = 1200W","steps":["Step 1: Identify V = 240V and I = 5A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 240 × 5.","Step 4: Calculate: P = 1200W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 10),
  (1456, 380, 'A bulb operates at 12V and draws 2A. Calculate its power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 12 × 2 = 24W","steps":["Step 1: Identify V = 12V and I = 2A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 12 × 2.","Step 4: Calculate: P = 24W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q12","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 11),
  (1457, 380, 'A motor uses 600W from a 200V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 600 / 200 = 3A","steps":["Step 1: Identify P = 600W and V = 200V.","Step 2: Rearrange the power formula: I = P / V.","Step 3: Substitute the values: I = 600 / 200.","Step 4: Calculate: I = 3A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q13","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 12),
  (1458, 380, 'An appliance consumes 1000W on a 250V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 1000 / 250 = 4A","steps":["Step 1: Identify P = 1000W and V = 250V.","Step 2: Use the formula: I = P / V.","Step 3: Substitute the values: I = 1000 / 250.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q14","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 13),
  (1459, 380, 'A resistor carries a current of 8A when connected to a 40V supply. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 40 / 8 = 5Ω","steps":["Step 1: Identify V = 40V and I = 8A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 40 / 8.","Step 4: Calculate: R = 5Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q15","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 14),
  (1460, 380, 'What is electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q16","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 15),
  (1461, 380, 'State the SI unit of electric current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of electric current is the ampere (A).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of electric current is the ampere (A)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q17","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 16),
  (1462, 380, 'State the SI unit of resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of resistance is the ohm (Ω).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of resistance is the ohm (Ω)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q18","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 17),
  (1463, 380, 'State the SI unit of voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of voltage is the volt (V).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of voltage is the volt (V)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q19","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 18),
  (1464, 380, 'What instrument is used to measure electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An ammeter is used to measure electric current.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An ammeter is used to measure electric current."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q20","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 19),
  (1465, 381, 'Why do ships float on water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"A floating object remains in equilibrium when the buoyant force equals its weight.","sol":"Step 1: Recall that water exerts an upward force called upthrust (buoyant force).\nStep 2: Compare the ship''s weight with the upthrust acting on it.\nStep 3: When the upthrust equals the weight of the ship, the ship floats.\nStep 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust.","steps":["Step 1: Recall that water exerts an upward force called upthrust (buoyant force).","Step 2: Compare the ship''s weight with the upthrust acting on it.","Step 3: When the upthrust equals the weight of the ship, the ship floats.","Step 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Fluids"}', 0),
  (1466, 381, 'Why does a stone sink in water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Objects sink when the downward force exceeds the buoyant force.","sol":"Step 1: Identify the weight of the stone acting downward.\nStep 2: Identify the upthrust provided by the water acting upward.\nStep 3: Compare the two forces.\nStep 4: Since the stone''s weight is greater than the upthrust, it sinks.","steps":["Step 1: Identify the weight of the stone acting downward.","Step 2: Identify the upthrust provided by the water acting upward.","Step 3: Compare the two forces.","Step 4: Since the stone''s weight is greater than the upthrust, it sinks."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Fluids"}', 1),
  (1467, 381, 'State Archimedes'' Principle.', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"This principle explains floating and sinking.","sol":"Step 1: Consider an object immersed in a fluid.\nStep 2: The object displaces some of the fluid.\nStep 3: The displaced fluid has weight.\nStep 4: The upthrust equals the weight of the displaced fluid.","steps":["Step 1: Consider an object immersed in a fluid.","Step 2: The object displaces some of the fluid.","Step 3: The displaced fluid has weight.","Step 4: The upthrust equals the weight of the displaced fluid."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Fluids"}', 2),
  (1468, 381, 'Why is it easier to swim in seawater than in fresh water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Greater density increases the buoyant force.","sol":"Step 1: Compare the densities of seawater and fresh water.\nStep 2: Note that seawater is denser because of dissolved salts.\nStep 3: Denser water produces a greater upthrust.\nStep 4: Greater upthrust makes floating easier.","steps":["Step 1: Compare the densities of seawater and fresh water.","Step 2: Note that seawater is denser because of dissolved salts.","Step 3: Denser water produces a greater upthrust.","Step 4: Greater upthrust makes floating easier."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Fluids"}', 3),
  (1469, 381, 'A force of 200N acts on an area of 4m². Calculate the pressure.', 'text', 1, 'Pressure = Force ÷ Area', '{"why":"Pressure is the force acting per unit area.","sol":"Step 1: Identify the values: Force = 200N and Area = 4m².\nStep 2: Write the formula: P = F ÷ A.\nStep 3: Substitute the values: P = 200 ÷ 4.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify the values: Force = 200N and Area = 4m².","Step 2: Write the formula: P = F ÷ A.","Step 3: Substitute the values: P = 200 ÷ 4.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q5","subject":"physics","chapter":"fluids","topic":"Fluids"}', 4),
  (1470, 381, 'A force of 150N acts on an area of 3m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure increases when force increases or area decreases.","sol":"Step 1: Identify Force = 150N and Area = 3m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 150 ÷ 3.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify Force = 150N and Area = 3m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 150 ÷ 3.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q6","subject":"physics","chapter":"fluids","topic":"Fluids"}', 5),
  (1471, 381, 'A pressure of 80Pa acts over an area of 5m². Calculate the force.', 'text', 1, 'Force = Pressure × Area', '{"why":"Force equals pressure multiplied by area.","sol":"Step 1: Identify Pressure = 80Pa and Area = 5m².\nStep 2: Write the formula: F = PA.\nStep 3: Substitute: F = 80 × 5.\nStep 4: Calculate: F = 400N.","steps":["Step 1: Identify Pressure = 80Pa and Area = 5m².","Step 2: Write the formula: F = PA.","Step 3: Substitute: F = 80 × 5.","Step 4: Calculate: F = 400N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q7","subject":"physics","chapter":"fluids","topic":"Fluids"}', 6),
  (1472, 381, 'A pressure of 300Pa is produced by a force of 600N. Find the area.', 'text', 1, 'Area = Force ÷ Pressure', '{"why":"Area is obtained by dividing force by pressure.","sol":"Step 1: Identify Force = 600N and Pressure = 300Pa.\nStep 2: Rearrange the formula: A = F ÷ P.\nStep 3: Substitute: A = 600 ÷ 300.\nStep 4: Calculate: A = 2m².","steps":["Step 1: Identify Force = 600N and Pressure = 300Pa.","Step 2: Rearrange the formula: A = F ÷ P.","Step 3: Substitute: A = 600 ÷ 300.","Step 4: Calculate: A = 2m²."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q8","subject":"physics","chapter":"fluids","topic":"Fluids"}', 7),
  (1473, 381, 'A force of 900N acts on an area of 9m². Calculate the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is directly proportional to force and inversely proportional to area.","sol":"Step 1: Identify Force = 900N and Area = 9m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 900 ÷ 9.\nStep 4: Calculate: P = 100 Pa.","steps":["Step 1: Identify Force = 900N and Area = 9m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 900 ÷ 9.","Step 4: Calculate: P = 100 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q9","subject":"physics","chapter":"fluids","topic":"Fluids"}', 8),
  (1474, 381, 'A pressure of 250Pa acts over an area of 8m². Find the force.', 'text', 1, 'Use F = PA', '{"why":"Increasing either pressure or area increases the force.","sol":"Step 1: Identify Pressure = 250Pa and Area = 8m².\nStep 2: Write the formula F = PA.\nStep 3: Substitute: F = 250 × 8.\nStep 4: Calculate: F = 2000N.","steps":["Step 1: Identify Pressure = 250Pa and Area = 8m².","Step 2: Write the formula F = PA.","Step 3: Substitute: F = 250 × 8.","Step 4: Calculate: F = 2000N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q10","subject":"physics","chapter":"fluids","topic":"Fluids"}', 9),
  (1475, 381, 'A force of 360N acts on an area of 12m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is measured in pascals (Pa).","sol":"Step 1: Identify Force = 360N and Area = 12m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 360 ÷ 12.\nStep 4: Calculate: P = 30 Pa.","steps":["Step 1: Identify Force = 360N and Area = 12m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 360 ÷ 12.","Step 4: Calculate: P = 30 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q11","subject":"physics","chapter":"fluids","topic":"Fluids"}', 10),
  (1476, 382, 'What is radioactivity?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Unstable nuclei lose excess energy by emitting radiation to become more stable.","sol":"Step 1: Recall that some atomic nuclei are unstable.\nStep 2: An unstable nucleus emits radiation without any external influence.\nStep 3: This emission may include alpha particles, beta particles, or gamma rays.\nStep 4: The process continues until the nucleus becomes more stable.","steps":["Step 1: Recall that some atomic nuclei are unstable.","Step 2: An unstable nucleus emits radiation without any external influence.","Step 3: This emission may include alpha particles, beta particles, or gamma rays.","Step 4: The process continues until the nucleus becomes more stable."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 0),
  (1477, 382, 'What is an alpha particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Alpha particles are emitted by heavy unstable nuclei.","sol":"Step 1: Recall the three common types of radioactive emissions.\nStep 2: Identify that an alpha particle contains protons and neutrons.\nStep 3: State its composition.\nStep 4: Give the definition.","steps":["Step 1: Recall the three common types of radioactive emissions.","Step 2: Identify that an alpha particle contains protons and neutrons.","Step 3: State its composition.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 1),
  (1478, 382, 'What is a beta particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Beta decay helps unstable nuclei achieve greater stability.","sol":"Step 1: Recall radioactive emissions.\nStep 2: Identify the beta particle as a fast-moving electron.\nStep 3: State that it is emitted from the nucleus.\nStep 4: Give the definition.","steps":["Step 1: Recall radioactive emissions.","Step 2: Identify the beta particle as a fast-moving electron.","Step 3: State that it is emitted from the nucleus.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 2),
  (1479, 382, 'What are gamma rays?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Gamma rays carry excess energy away from unstable nuclei.","sol":"Step 1: Recall that gamma rays are a type of radiation.\nStep 2: Identify that they are electromagnetic waves.\nStep 3: Note that they have no mass and no charge.\nStep 4: State the definition.","steps":["Step 1: Recall that gamma rays are a type of radiation.","Step 2: Identify that they are electromagnetic waves.","Step 3: Note that they have no mass and no charge.","Step 4: State the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 3),
  (1480, 382, 'State one property of alpha particles.', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They contain two positively charged protons.","sol":"Step 1: Recall the characteristics of alpha particles.\nStep 2: Identify one property.\nStep 3: State the property clearly.","steps":["Step 1: Recall the characteristics of alpha particles.","Step 2: Identify one property.","Step 3: State the property clearly."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q5","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 4),
  (1481, 382, 'Why are gamma rays more penetrating than alpha particles?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They interact less with matter than charged particles.","sol":"Step 1: Compare the masses of alpha particles and gamma rays.\nStep 2: Recall that gamma rays have no mass or charge.\nStep 3: Less interaction with matter allows deeper penetration.\nStep 4: State the conclusion.","steps":["Step 1: Compare the masses of alpha particles and gamma rays.","Step 2: Recall that gamma rays have no mass or charge.","Step 3: Less interaction with matter allows deeper penetration.","Step 4: State the conclusion."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q6","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 5),
  (1482, 382, 'Name two applications of modern physics.', 'text', 1, 'Think medicine and energy.', '{"why":"Both rely on atomic and nuclear physics.","sol":"Step 1: Identify one medical application.\nStep 2: Identify one energy application.\nStep 3: State both applications.","steps":["Step 1: Identify one medical application.","Step 2: Identify one energy application.","Step 3: State both applications."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q7","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 6),
  (1483, 382, 'State one medical application of radioactivity.', 'text', 1, 'Think hospitals.', '{"why":"Radiation destroys cancer cells.","sol":"Step 1: Recall how radiation is used in medicine.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in medicine.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q8","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 7),
  (1484, 382, 'State one industrial application of radioactivity.', 'text', 1, 'Think manufacturing.', '{"why":"Radiation helps monitor product quality.","sol":"Step 1: Recall industrial uses of radiation.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall industrial uses of radiation.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q9","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 8),
  (1485, 382, 'State one agricultural application of radioactivity.', 'text', 1, 'Think crops.', '{"why":"Radiation can produce useful genetic variations.","sol":"Step 1: Recall how radiation is used in agriculture.\nStep 2: Identify one use.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in agriculture.","Step 2: Identify one use.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q10","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 9),
  (1486, 382, 'State one disadvantage of radioactivity.', 'text', 1, 'Think health effects.', '{"why":"Ionising radiation damages body cells and DNA.","sol":"Step 1: Recall the harmful effects of radiation.\nStep 2: Identify one effect.\nStep 3: State the disadvantage.","steps":["Step 1: Recall the harmful effects of radiation.","Step 2: Identify one effect.","Step 3: State the disadvantage."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q11","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 10),
  (1487, 382, 'Why must radioactive materials be handled carefully?', 'text', 1, 'Think safety.', '{"why":"Proper handling reduces exposure and protects human health.","sol":"Step 1: Recall that radiation can damage living tissue.\nStep 2: Consider long-term exposure effects.\nStep 3: State why safety precautions are necessary.","steps":["Step 1: Recall that radiation can damage living tissue.","Step 2: Consider long-term exposure effects.","Step 3: State why safety precautions are necessary."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q12","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 11),
  (1488, 383, 'What are cathode rays?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Cathode rays consist of negatively charged electrons.","sol":"Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.\nStep 2: Electrons are emitted from the cathode when a high voltage is applied.\nStep 3: The electrons travel across the vacuum toward the anode.\nStep 4: These moving electrons are called cathode rays.","steps":["Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.","Step 2: Electrons are emitted from the cathode when a high voltage is applied.","Step 3: The electrons travel across the vacuum toward the anode.","Step 4: These moving electrons are called cathode rays."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 0),
  (1489, 383, 'State two properties of cathode rays.', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"These properties were demonstrated using cathode ray tubes.","sol":"Step 1: Recall the characteristics of cathode rays.\nStep 2: Identify that they travel in straight lines.\nStep 3: Identify that they are negatively charged.\nStep 4: State both properties.","steps":["Step 1: Recall the characteristics of cathode rays.","Step 2: Identify that they travel in straight lines.","Step 3: Identify that they are negatively charged.","Step 4: State both properties."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 1),
  (1490, 383, 'Why do cathode rays produce shadows?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Straight-line motion causes shadow formation.","sol":"Step 1: Recall that cathode rays travel in straight lines.\nStep 2: Place an object in their path.\nStep 3: The object blocks the rays.\nStep 4: A shadow forms behind the object.","steps":["Step 1: Recall that cathode rays travel in straight lines.","Step 2: Place an object in their path.","Step 3: The object blocks the rays.","Step 4: A shadow forms behind the object."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 2),
  (1491, 383, 'Why do cathode rays cause fluorescence?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"The kinetic energy of electrons is converted into light energy.","sol":"Step 1: Cathode rays strike a fluorescent material.\nStep 2: The electrons transfer energy to the material.\nStep 3: The material emits visible light.\nStep 4: The screen glows.","steps":["Step 1: Cathode rays strike a fluorescent material.","Step 2: The electrons transfer energy to the material.","Step 3: The material emits visible light.","Step 4: The screen glows."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q4","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 3),
  (1492, 383, 'Why can cathode rays turn a light paddle wheel?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"This demonstrates that cathode rays are particles.","sol":"Step 1: Recall that cathode rays are streams of particles.\nStep 2: The particles strike the paddle wheel.\nStep 3: They transfer momentum to the wheel.\nStep 4: The wheel rotates.","steps":["Step 1: Recall that cathode rays are streams of particles.","Step 2: The particles strike the paddle wheel.","Step 3: They transfer momentum to the wheel.","Step 4: The wheel rotates."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q5","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 4),
  (1493, 383, 'Why are cathode rays deflected in electric fields?', 'text', 1, 'Think about their charge.', '{"why":"Charged particles experience forces in electric fields.","sol":"Step 1: Recall that cathode rays are electrons.\nStep 2: Electrons have a negative charge.\nStep 3: Electric fields exert forces on charged particles.\nStep 4: Therefore, cathode rays are deflected toward the positive plate.","steps":["Step 1: Recall that cathode rays are electrons.","Step 2: Electrons have a negative charge.","Step 3: Electric fields exert forces on charged particles.","Step 4: Therefore, cathode rays are deflected toward the positive plate."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q6","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 5),
  (1494, 383, 'Why are cathode rays deflected by magnetic fields?', 'text', 1, 'Think about moving charges.', '{"why":"Magnetic fields affect moving charged particles.","sol":"Step 1: Recall that cathode rays are moving electrons.\nStep 2: Moving charges experience magnetic forces.\nStep 3: The magnetic field changes their direction.\nStep 4: The rays are deflected.","steps":["Step 1: Recall that cathode rays are moving electrons.","Step 2: Moving charges experience magnetic forces.","Step 3: The magnetic field changes their direction.","Step 4: The rays are deflected."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q7","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 6),
  (1495, 383, 'What happens when cathode rays strike a metal target?', 'text', 1, 'Think X-rays.', '{"why":"Rapid deceleration of electrons produces X-rays.","sol":"Step 1: Cathode rays move at very high speed.\nStep 2: They collide with the metal target.\nStep 3: They lose energy suddenly.\nStep 4: X-rays are produced.","steps":["Step 1: Cathode rays move at very high speed.","Step 2: They collide with the metal target.","Step 3: They lose energy suddenly.","Step 4: X-rays are produced."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q8","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 7),
  (1496, 383, 'Why is a vacuum needed in a cathode ray tube?', 'text', 1, 'Think collisions.', '{"why":"The rays can travel efficiently only in a vacuum.","sol":"Step 1: Recall that air contains many particles.\nStep 2: Electrons would collide with air molecules.\nStep 3: These collisions would reduce their energy.\nStep 4: A vacuum allows electrons to travel freely.","steps":["Step 1: Recall that air contains many particles.","Step 2: Electrons would collide with air molecules.","Step 3: These collisions would reduce their energy.","Step 4: A vacuum allows electrons to travel freely."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q9","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 8),
  (1497, 383, 'How do cathode rays demonstrate that electrons are particles?', 'text', 1, 'Think mass and momentum.', '{"why":"Objects with mass behave as particles.","sol":"Step 1: Observe that cathode rays can move a light paddle wheel.\nStep 2: Only particles with mass can transfer momentum.\nStep 3: The wheel rotates after being struck.\nStep 4: Therefore, cathode rays are particles.","steps":["Step 1: Observe that cathode rays can move a light paddle wheel.","Step 2: Only particles with mass can transfer momentum.","Step 3: The wheel rotates after being struck.","Step 4: Therefore, cathode rays are particles."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q10","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 9),
  (1498, 384, 'What is photoelectric emission?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photons transfer their energy to electrons in the metal, causing them to escape if energy exceeds work function.","sol":"Step 1: Identify incident radiation (light of sufficient frequency).\nStep 2: Identify the surface (metal surface).\nStep 3: State the emission of electrons (photoelectrons).","steps":["Step 1: Identify incident radiation (light of sufficient frequency).","Step 2: Identify the surface (metal surface).","Step 3: State the emission of electrons (photoelectrons)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 0),
  (1499, 384, 'Define threshold frequency (f₀) in photoelectric effect.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"If light frequency is below threshold frequency, individual photon energy is less than the work function.","sol":"Step 1: Consider the frequency of incident radiation.\nStep 2: Define the minimum boundary required for emission.\nStep 3: Explain that light below this frequency causes no electron ejection regardless of intensity.","steps":["Step 1: Consider the frequency of incident radiation.","Step 2: Define the minimum boundary required for emission.","Step 3: Explain that light below this frequency causes no electron ejection regardless of intensity."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 1),
  (1500, 384, 'Define the work function (φ) of a metal.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Electrons are bound to metal atoms and require a specific threshold energy to escape.","sol":"Step 1: Consider the binding energy of electrons in a metal.\nStep 2: Define the minimum energy required.\nStep 3: State that it is the minimum energy needed to free an electron from the metal surface.","steps":["Step 1: Consider the binding energy of electrons in a metal.","Step 2: Define the minimum energy required.","Step 3: State that it is the minimum energy needed to free an electron from the metal surface."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1501, 384, 'State Einstein''s photoelectric equation.', 'text', 1, 'Think energy of photon = work function + max kinetic energy.', '{"why":"Incident photon energy (hf) is used to overcome work function (φ) and any remaining energy becomes kinetic energy of photoelectron.","sol":"Step 1: Write photon energy (hf).\nStep 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).\nStep 3: State equation: hf = φ + KEmax or KEmax = hf - φ.","steps":["Step 1: Write photon energy (hf).","Step 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).","Step 3: State equation: hf = φ + KEmax or KEmax = hf - φ."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q4","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 3),
  (1502, 384, 'What effect does increasing the intensity of incident light have on photoelectric emission?', 'text', 1, 'Think number of photons vs energy per photon.', '{"why":"Intensity determines the photon flux, while light frequency determines individual photon energy.","sol":"Step 1: Understand that higher intensity means more photons per second.\nStep 2: State that each photon interacts with one electron.\nStep 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant.","steps":["Step 1: Understand that higher intensity means more photons per second.","Step 2: State that each photon interacts with one electron.","Step 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q5","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 4),
  (1503, 384, 'Why does light below threshold frequency fail to emit electrons even if intensity is increased?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photoelectric absorption is a one-to-one photon-electron interaction.","sol":"Step 1: Recognize that one photon interacts with one electron.\nStep 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.\nStep 3: Conclude that increasing intensity only supplies more low-energy photons.","steps":["Step 1: Recognize that one photon interacts with one electron.","Step 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.","Step 3: Conclude that increasing intensity only supplies more low-energy photons."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q6","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 5),
  (1504, 384, 'Calculate the energy of a photon of light with frequency 6.0 × 10¹⁴ Hz. (Planck''s constant h = 6.63 × 10⁻³⁴ J·s)', 'text', 1, 'Use E = hf', '{"why":"Photon energy is directly proportional to frequency via Planck''s constant.","sol":"Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.\nStep 2: Apply formula E = h × f.\nStep 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).\nStep 4: Calculate: E = 3.978 × 10⁻¹⁹ J.","steps":["Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.","Step 2: Apply formula E = h × f.","Step 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).","Step 4: Calculate: E = 3.978 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q7","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 6),
  (1505, 384, 'A metal has a work function of 2.5 × 10⁻¹⁹ J. If incident light delivers photon energy of 4.2 × 10⁻¹⁹ J, find the maximum kinetic energy of the emitted photoelectrons.', 'text', 1, 'Use KEmax = hf - φ', '{"why":"The excess energy above the work function becomes the maximum kinetic energy of the emitted photoelectron.","sol":"Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.\nStep 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.\nStep 3: Apply KEmax = hf - φ.\nStep 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J.","steps":["Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.","Step 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.","Step 3: Apply KEmax = hf - φ.","Step 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q8","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 7),
  (1506, 384, 'What is stopping potential in the photoelectric effect?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"At stopping potential, work done against electric field equals maximum kinetic energy of photoelectrons (eVs = KEmax).","sol":"Step 1: Define opposing electric potential applied to anode.\nStep 2: State the minimum retarding potential that stops the fastest photoelectrons.\nStep 3: Relate to maximum kinetic energy (eVs = KEmax).","steps":["Step 1: Define opposing electric potential applied to anode.","Step 2: State the minimum retarding potential that stops the fastest photoelectrons.","Step 3: Relate to maximum kinetic energy (eVs = KEmax)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q9","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 8),
  (1507, 384, 'State two practical applications of photoelectric emission.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"These devices convert incident light energy directly into electrical signals using photoelectric principles.","sol":"Step 1: Identify technology utilizing light detection.\nStep 2: Give solar cells / solar panels.\nStep 3: Give light sensors in cameras or automatic doors.","steps":["Step 1: Identify technology utilizing light detection.","Step 2: Give solar cells / solar panels.","Step 3: Give light sensors in cameras or automatic doors."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q10","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 9),
  (1508, 385, 'What is chemistry?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"The definition covers both substances themselves and the changes that occur when they interact.","sol":"Step 1: Identify what chemistry studies.\nStep 2: Chemistry studies matter, its composition, structure, properties and changes.\nStep 3: State this as the definition.","steps":["Step 1: Identify what chemistry studies.","Step 2: Chemistry studies matter, its composition, structure, properties and changes.","Step 3: State this as the definition."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 0),
  (1509, 385, 'A student burns magnesium in oxygen. Why is this a chemical process?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Formation of a new substance is evidence of a chemical change.","sol":"Step 1: Identify the substances before the reaction: magnesium and oxygen.\nStep 2: Observe that they react.\nStep 3: A new substance, magnesium oxide, is formed.","steps":["Step 1: Identify the substances before the reaction: magnesium and oxygen.","Step 2: Observe that they react.","Step 3: A new substance, magnesium oxide, is formed."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 1),
  (1510, 385, 'State two things studied in chemistry.', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Chemistry investigates both the nature of substances and how they change.","sol":"Step 1: Chemistry studies matter.\nStep 2: It also studies the changes and reactions involving matter.","steps":["Step 1: Chemistry studies matter.","Step 2: It also studies the changes and reactions involving matter."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 2),
  (1511, 385, 'A learner says that chemistry only involves mixing chemicals together. Correct the statement.', 'text', 1, 'Think about everything chemistry studies, not only reactions.', '{"why":"Chemical reactions are only one part of chemistry.","sol":"Step 1: Chemistry studies matter.\nStep 2: It studies composition, structure and properties.\nStep 3: It also studies changes and reactions involving matter.","steps":["Step 1: Chemistry studies matter.","Step 2: It studies composition, structure and properties.","Step 3: It also studies changes and reactions involving matter."],"options":[],"conceptId":"chemistry_chemistry_foundations_meaning_of_chemistry","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Meaning of Chemistry"}', 3),
  (1512, 386, 'Why should chemicals never be tasted in the laboratory?', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"The appearance of a chemical cannot be used to determine whether it is safe to consume.","sol":"Step 1: Chemicals are not necessarily safe for consumption.\nStep 2: Some chemicals are poisonous or corrosive.\nStep 3: Therefore tasting them could cause serious injury or poisoning.","steps":["Step 1: Chemicals are not necessarily safe for consumption.","Step 2: Some chemicals are poisonous or corrosive.","Step 3: Therefore tasting them could cause serious injury or poisoning."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 0),
  (1513, 386, 'Why should a student wear safety goggles during practical work?', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"The eyes are particularly vulnerable to chemical injury.","sol":"Step 1: Chemicals may splash during experiments.\nStep 2: Splashes can damage the eyes.\nStep 3: Goggles provide protection against such splashes.","steps":["Step 1: Chemicals may splash during experiments.","Step 2: Splashes can damage the eyes.","Step 3: Goggles provide protection against such splashes."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 1),
  (1514, 386, 'State three laboratory safety rules.', 'text', 1, 'Focus on the core principle of Laboratory Safety Rules.', '{"why":"These rules reduce exposure to hazardous substances and help accidents receive immediate attention.","sol":"Step 1: Recall rules designed to prevent chemical or physical accidents.\nStep 2: Give three distinct rules.","steps":["Step 1: Recall rules designed to prevent chemical or physical accidents.","Step 2: Give three distinct rules."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 2),
  (1515, 386, 'A student spills a chemical and decides to leave it because nobody was injured. What should the student have done?', 'text', 1, 'Think about the rule concerning spills.', '{"why":"A spill can remain hazardous even when nobody is immediately injured.","sol":"Step 1: Recognise that the chemical spill may still be hazardous.\nStep 2: Leaving it could expose other people to danger.\nStep 3: Report the spill immediately and follow the laboratory''s spill procedure.","steps":["Step 1: Recognise that the chemical spill may still be hazardous.","Step 2: Leaving it could expose other people to danger.","Step 3: Report the spill immediately and follow the laboratory''s spill procedure."],"options":[],"conceptId":"chemistry_chemistry_foundations_laboratory_safety_rules","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Laboratory Safety Rules"}', 3),
  (1516, 387, 'What does a flammable hazard symbol warn a user about?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Flammable substances ignite readily when exposed to a suitable source of ignition.","sol":"Step 1: Identify the property represented by the symbol.\nStep 2: Flammable substances can ignite.\nStep 3: State the associated danger.","steps":["Step 1: Identify the property represented by the symbol.","Step 2: Flammable substances can ignite.","Step 3: State the associated danger."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 0),
  (1517, 387, 'What does the corrosive hazard symbol indicate?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Corrosive substances can cause serious chemical burns and damage equipment.","sol":"Step 1: Identify the meaning of corrosive.\nStep 2: A corrosive substance can attack materials or living tissue.\nStep 3: State the warning.","steps":["Step 1: Identify the meaning of corrosive.","Step 2: A corrosive substance can attack materials or living tissue.","Step 3: State the warning."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 1),
  (1518, 387, 'Why are hazard symbols placed on chemical containers?', 'text', 1, 'Focus on the core principle of Chemical Hazard Symbols.', '{"why":"Hazard information helps users choose appropriate precautions.","sol":"Step 1: Users need to know potential dangers before handling a chemical.\nStep 2: Symbols provide a quick warning about the nature of the hazard.","steps":["Step 1: Users need to know potential dangers before handling a chemical.","Step 2: Symbols provide a quick warning about the nature of the hazard."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 2),
  (1519, 387, 'A chemical container has a flammable warning. State one important precaution.', 'text', 1, 'Think about what could cause a flammable substance to ignite.', '{"why":"Removing ignition sources reduces the chance of the substance catching fire.","sol":"Step 1: Flammable substances can catch fire.\nStep 2: Flames and other ignition sources can start combustion.\nStep 3: Keep the chemical away from ignition sources.","steps":["Step 1: Flammable substances can catch fire.","Step 2: Flames and other ignition sources can start combustion.","Step 3: Keep the chemical away from ignition sources."],"options":[],"conceptId":"chemistry_chemistry_foundations_chemical_hazard_symbols","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Chemical Hazard Symbols"}', 3),
  (1520, 388, 'Why should a chemical label be read before using the chemical?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Correct handling depends on knowing the properties and hazards of the chemical.","sol":"Step 1: The label provides information about the substance.\nStep 2: It may include hazards and handling instructions.\nStep 3: Reading it helps the user select appropriate precautions.","steps":["Step 1: The label provides information about the substance.","Step 2: It may include hazards and handling instructions.","Step 3: Reading it helps the user select appropriate precautions."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 0),
  (1521, 388, 'How should a student safely detect the smell of a chemical when instructed to do so?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Direct inhalation may expose the respiratory system to a high concentration of harmful vapour.","sol":"Step 1: Do not place the nose directly over the container.\nStep 2: Hold the container at a safe distance.\nStep 3: Gently waft vapour towards the nose.","steps":["Step 1: Do not place the nose directly over the container.","Step 2: Hold the container at a safe distance.","Step 3: Gently waft vapour towards the nose."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 1),
  (1522, 388, 'Why should unused chemicals generally not be returned to their original containers?', 'text', 1, 'Focus on the core principle of Safe Handling of Chemicals.', '{"why":"Contamination of the main stock can make the chemical unsafe or unsuitable for later experiments.","sol":"Step 1: The unused chemical may have become contaminated.\nStep 2: Returning it could contaminate the entire stock.\nStep 3: Therefore unused chemicals should be disposed of according to laboratory instructions.","steps":["Step 1: The unused chemical may have become contaminated.","Step 2: Returning it could contaminate the entire stock.","Step 3: Therefore unused chemicals should be disposed of according to laboratory instructions."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 2),
  (1523, 388, 'A learner smells a chemical by placing their nose directly above the container. Identify the mistake and give the correct method.', 'text', 1, 'Think about how vapour should reach the nose.', '{"why":"Wafting reduces direct exposure to concentrated vapour.","sol":"Step 1: Directly inhaling from the container is unsafe.\nStep 2: Harmful vapour may enter the respiratory system at high concentration.\nStep 3: The correct method is to waft vapour gently towards the nose when instructed.","steps":["Step 1: Directly inhaling from the container is unsafe.","Step 2: Harmful vapour may enter the respiratory system at high concentration.","Step 3: The correct method is to waft vapour gently towards the nose when instructed."],"options":[],"conceptId":"chemistry_chemistry_foundations_safe_handling_of_chemicals","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Safe Handling of Chemicals"}', 3),
  (1524, 389, 'Which apparatus is used to measure the mass of a substance?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A balance measures mass.","sol":"Step 1: Identify the physical quantity: mass.\nStep 2: Select the apparatus designed to measure mass.","steps":["Step 1: Identify the physical quantity: mass.","Step 2: Select the apparatus designed to measure mass."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 0),
  (1525, 389, 'Which apparatus is used to transfer a fixed accurate volume of liquid?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A volumetric pipette is designed to transfer a specified fixed volume accurately.","sol":"Step 1: The volume must be fixed.\nStep 2: The apparatus must be designed for accurate transfer.\nStep 3: Select the pipette.","steps":["Step 1: The volume must be fixed.","Step 2: The apparatus must be designed for accurate transfer.","Step 3: Select the pipette."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 1),
  (1526, 389, 'Which apparatus is commonly used to measure a variable volume accurately during titration?', 'text', 1, 'Focus on the core principle of Measuring Apparatus.', '{"why":"A burette allows a variable volume of solution to be delivered and measured accurately.","sol":"Step 1: Titration requires controlled delivery of a solution.\nStep 2: The volume delivered must be measured.\nStep 3: A burette is designed for this purpose.","steps":["Step 1: Titration requires controlled delivery of a solution.","Step 2: The volume delivered must be measured.","Step 3: A burette is designed for this purpose."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 2),
  (1527, 389, 'A student needs to transfer exactly 25.0 cm³ of a solution into a flask. Which apparatus is most appropriate?', 'text', 1, 'The volume is fixed and accuracy is important.', '{"why":"A volumetric pipette is designed to transfer a fixed volume accurately.","sol":"Step 1: The required volume is fixed at 25.0 cm³.\nStep 2: High accuracy is required.\nStep 3: Use a 25.0 cm³ volumetric pipette.","steps":["Step 1: The required volume is fixed at 25.0 cm³.","Step 2: High accuracy is required.","Step 3: Use a 25.0 cm³ volumetric pipette."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Apparatus"}', 3),
  (1528, 390, 'What is the function of a Bunsen burner?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"It is a common laboratory source of heat.","sol":"Step 1: Identify the apparatus as a source of heat.\nStep 2: State what it provides.","steps":["Step 1: Identify the apparatus as a source of heat.","Step 2: State what it provides."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 0),
  (1529, 390, 'What is the function of wire gauze?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"It provides a stable support and reduces direct concentration of heat on one part of the vessel.","sol":"Step 1: Identify its position between the heat source and supported vessel.\nStep 2: It supports the glassware.\nStep 3: It also helps distribute heat.","steps":["Step 1: Identify its position between the heat source and supported vessel.","Step 2: It supports the glassware.","Step 3: It also helps distribute heat."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 1),
  (1530, 390, 'What is a crucible used for?', 'text', 1, 'Focus on the core principle of Heating Apparatus.', '{"why":"Its material and shape allow it to withstand high temperatures.","sol":"Step 1: A crucible is made to withstand strong heating.\nStep 2: It holds small amounts of solid substances.","steps":["Step 1: A crucible is made to withstand strong heating.","Step 2: It holds small amounts of solid substances."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 2),
  (1531, 390, 'A student places a glass beaker directly on a Bunsen burner flame. Why might this be unsafe or unsuitable?', 'text', 1, 'Think about how heat reaches the glass.', '{"why":"Even distribution of heat reduces the risk of thermal shock.","sol":"Step 1: Direct heating can concentrate heat on one region.\nStep 2: Uneven heating can cause thermal stress.\nStep 3: The glass may crack or break.\nStep 4: Appropriate support and wire gauze should be used where required.","steps":["Step 1: Direct heating can concentrate heat on one region.","Step 2: Uneven heating can cause thermal stress.","Step 3: The glass may crack or break.","Step 4: Appropriate support and wire gauze should be used where required."],"options":[],"conceptId":"chemistry_chemistry_foundations_heating_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Heating Apparatus"}', 3),
  (1532, 391, 'What is the function of filter paper?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Filtration separates components based mainly on particle size and insolubility.","sol":"Step 1: Filter paper contains very small pores.\nStep 2: Liquid can pass through the pores.\nStep 3: Insoluble solid particles are retained.","steps":["Step 1: Filter paper contains very small pores.","Step 2: Liquid can pass through the pores.","Step 3: Insoluble solid particles are retained."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 0),
  (1533, 391, 'What is the function of a condenser?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Condensation is the change from gas to liquid caused by cooling.","sol":"Step 1: During distillation, liquid is heated and forms vapour.\nStep 2: The vapour enters the condenser.\nStep 3: Cooling causes the vapour to condense into liquid.","steps":["Step 1: During distillation, liquid is heated and forms vapour.","Step 2: The vapour enters the condenser.","Step 3: Cooling causes the vapour to condense into liquid."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 1),
  (1534, 391, 'What is a separating funnel used to separate?', 'text', 1, 'Focus on the core principle of Separation Apparatus.', '{"why":"Immiscible liquids form separate layers that can be drained separately.","sol":"Step 1: Identify the type of mixture.\nStep 2: The liquids must not mix with each other.\nStep 3: The liquids form separate layers because of differences in density.","steps":["Step 1: Identify the type of mixture.","Step 2: The liquids must not mix with each other.","Step 3: The liquids form separate layers because of differences in density."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 2),
  (1535, 391, 'A mixture contains sand and water. Which apparatus is required for the first separation step?', 'text', 1, 'Sand is an insoluble solid.', '{"why":"The filter paper retains the sand while water passes through.","sol":"Step 1: Sand is insoluble in water.\nStep 2: An insoluble solid can be separated from a liquid by filtration.\nStep 3: Use a filter funnel and filter paper.","steps":["Step 1: Sand is insoluble in water.","Step 2: An insoluble solid can be separated from a liquid by filtration.","Step 3: Use a filter funnel and filter paper."],"options":[],"conceptId":"chemistry_chemistry_foundations_separation_apparatus","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Separation Apparatus"}', 3),
  (1536, 392, 'What is the function of a burette in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"Its graduated scale and tap allow controlled measurement of the volume delivered.","sol":"Step 1: A titration requires a variable volume of solution.\nStep 2: The volume delivered must be measured accurately.\nStep 3: The burette provides controlled delivery and measurement.","steps":["Step 1: A titration requires a variable volume of solution.","Step 2: The volume delivered must be measured accurately.","Step 3: The burette provides controlled delivery and measurement."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 0),
  (1537, 392, 'What is the function of a pipette in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"The pipette provides a more accurate fixed volume than an ordinary measuring cylinder.","sol":"Step 1: A known fixed volume of solution is required.\nStep 2: A pipette is designed to transfer a fixed volume accurately.","steps":["Step 1: A known fixed volume of solution is required.","Step 2: A pipette is designed to transfer a fixed volume accurately."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 1),
  (1538, 392, 'Why is a conical flask commonly used in titration?', 'text', 1, 'Focus on the core principle of Apparatus Used in Titration.', '{"why":"Its shape is suitable for mixing solutions during addition from the burette.","sol":"Step 1: The flask must contain the solution being titrated.\nStep 2: The contents must be mixed without easily spilling.\nStep 3: The shape allows the solution to be swirled safely.","steps":["Step 1: The flask must contain the solution being titrated.","Step 2: The contents must be mixed without easily spilling.","Step 3: The shape allows the solution to be swirled safely."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 2),
  (1539, 392, 'A learner leaves a funnel in the top of the burette while taking a burette reading. Why can this cause a problem?', 'text', 1, 'Think about whether liquid left in the funnel could enter the burette.', '{"why":"The burette reading must represent only the controlled volume delivered through the tap.","sol":"Step 1: Liquid may remain inside the funnel.\nStep 2: That liquid could enter the burette unexpectedly.\nStep 3: This would change the amount of solution delivered and affect the reading.","steps":["Step 1: Liquid may remain inside the funnel.","Step 2: That liquid could enter the burette unexpectedly.","Step 3: This would change the amount of solution delivered and affect the reading."],"options":[],"conceptId":"chemistry_chemistry_foundations_apparatus_used_in_titration","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Apparatus Used in Titration"}', 3),
  (1540, 393, 'A container has a mass of 25.0 g. The container and a chemical together have a mass of 43.5 g. Calculate the mass of the chemical.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"The mass of the chemical is the combined mass minus the mass of the empty container.","sol":"Step 1: Write the combined mass: 43.5 g.\nStep 2: Subtract the mass of the empty container: 25.0 g.\nStep 3: 43.5 − 25.0 = 18.5 g.","steps":["Step 1: Write the combined mass: 43.5 g.","Step 2: Subtract the mass of the empty container: 25.0 g.","Step 3: 43.5 − 25.0 = 18.5 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 0),
  (1541, 393, 'Convert 2.5 kg to grams.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"Each kilogram contains 1000 grams.","sol":"Step 1: 1 kg = 1000 g.\nStep 2: Multiply 2.5 by 1000.\nStep 3: 2.5 × 1000 = 2500 g.","steps":["Step 1: 1 kg = 1000 g.","Step 2: Multiply 2.5 by 1000.","Step 3: 2.5 × 1000 = 2500 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 1),
  (1542, 393, 'Convert 750 mg to grams.', 'text', 1, 'Focus on the core principle of Measuring Mass.', '{"why":"Milligrams are smaller than grams, so the numerical value decreases when converting mg to g.","sol":"Step 1: 1 g = 1000 mg.\nStep 2: Divide 750 mg by 1000.\nStep 3: 750 ÷ 1000 = 0.750 g.","steps":["Step 1: 1 g = 1000 mg.","Step 2: Divide 750 mg by 1000.","Step 3: 750 ÷ 1000 = 0.750 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 2),
  (1543, 393, 'A student records the mass of a container and chemical as 58.2 g but forgets to subtract the empty container mass of 20.0 g. What error has been made?', 'text', 1, 'The required quantity is the mass of the chemical alone.', '{"why":"The container''s mass must be removed from the combined measurement.","sol":"Step 1: The recorded 58.2 g includes both the container and chemical.\nStep 2: The container has a mass of 20.0 g.\nStep 3: Subtract 20.0 g from 58.2 g.\nStep 4: 58.2 − 20.0 = 38.2 g.","steps":["Step 1: The recorded 58.2 g includes both the container and chemical.","Step 2: The container has a mass of 20.0 g.","Step 3: Subtract 20.0 g from 58.2 g.","Step 4: 58.2 − 20.0 = 38.2 g."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_mass","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Mass"}', 3),
  (1544, 394, 'Convert 2.5 L to mL.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"Each litre contains 1000 millilitres.","sol":"Step 1: 1 L = 1000 mL.\nStep 2: Multiply 2.5 by 1000.\nStep 3: 2.5 × 1000 = 2500 mL.","steps":["Step 1: 1 L = 1000 mL.","Step 2: Multiply 2.5 by 1000.","Step 3: 2.5 × 1000 = 2500 mL."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 0),
  (1545, 394, 'Convert 450 mL to cm³.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"A millilitre and a cubic centimetre represent equal volumes.","sol":"Step 1: Use the relationship 1 mL = 1 cm³.\nStep 2: Therefore the numerical value remains unchanged.","steps":["Step 1: Use the relationship 1 mL = 1 cm³.","Step 2: Therefore the numerical value remains unchanged."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 1),
  (1546, 394, 'A measuring cylinder contains 75 mL of water. Express this volume in litres.', 'text', 1, 'Focus on the core principle of Measuring Volume.', '{"why":"To convert millilitres to litres, divide by 1000.","sol":"Step 1: 1 L = 1000 mL.\nStep 2: Divide 75 mL by 1000.\nStep 3: 75 ÷ 1000 = 0.075 L.","steps":["Step 1: 1 L = 1000 mL.","Step 2: Divide 75 mL by 1000.","Step 3: 75 ÷ 1000 = 0.075 L."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 2),
  (1547, 394, 'A learner reads the liquid level from above the measuring cylinder rather than at eye level. Why can this produce an inaccurate result?', 'text', 1, 'Think about the position of the eye relative to the scale.', '{"why":"Viewing the scale from above or below changes the apparent position of the liquid level.","sol":"Step 1: The apparent position of the liquid changes when viewed from an angle.\nStep 2: This causes parallax error.\nStep 3: The eye should be level with the meniscus when taking the reading.","steps":["Step 1: The apparent position of the liquid changes when viewed from an angle.","Step 2: This causes parallax error.","Step 3: The eye should be level with the meniscus when taking the reading."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_volume","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Volume"}', 3),
  (1548, 395, 'A solution has an initial temperature of 22°C and a final temperature of 35°C. Calculate the temperature change.', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"Temperature change is calculated by subtracting the initial temperature from the final temperature.","sol":"Step 1: Write the final temperature: 35°C.\nStep 2: Write the initial temperature: 22°C.\nStep 3: Subtract initial from final: 35 − 22 = 13°C.","steps":["Step 1: Write the final temperature: 35°C.","Step 2: Write the initial temperature: 22°C.","Step 3: Subtract initial from final: 35 − 22 = 13°C."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 0),
  (1549, 395, 'A substance cools from 80°C to 45°C. Calculate the decrease in temperature.', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"For a cooling process, the decrease is the initial temperature minus the final temperature.","sol":"Step 1: Initial temperature = 80°C.\nStep 2: Final temperature = 45°C.\nStep 3: Calculate the decrease: 80 − 45 = 35°C.","steps":["Step 1: Initial temperature = 80°C.","Step 2: Final temperature = 45°C.","Step 3: Calculate the decrease: 80 − 45 = 35°C."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 1),
  (1550, 395, 'Why should a thermometer reading be taken after the temperature has become steady?', 'text', 1, 'Focus on the core principle of Measuring Temperature.', '{"why":"A changing thermometer reading has not yet reached the temperature of the substance.","sol":"Step 1: Immediately after placing a thermometer in a substance, its reading may still be changing.\nStep 2: A changing reading does not represent the stable temperature.\nStep 3: Wait until the reading becomes steady before recording it.","steps":["Step 1: Immediately after placing a thermometer in a substance, its reading may still be changing.","Step 2: A changing reading does not represent the stable temperature.","Step 3: Wait until the reading becomes steady before recording it."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 2),
  (1551, 395, 'A student places the thermometer bulb against the bottom of a heated container. Explain why this can give an inaccurate temperature.', 'text', 1, 'Think about what the thermometer is actually touching.', '{"why":"The thermometer should measure the substance itself rather than a potentially hotter or colder part of the apparatus.","sol":"Step 1: The container''s bottom may be hotter than the substance.\nStep 2: The thermometer can therefore measure the temperature of the hot surface rather than the substance.\nStep 3: Keep the sensing part properly immersed without touching the container where appropriate.","steps":["Step 1: The container''s bottom may be hotter than the substance.","Step 2: The thermometer can therefore measure the temperature of the hot surface rather than the substance.","Step 3: Keep the sensing part properly immersed without touching the container where appropriate."],"options":[],"conceptId":"chemistry_chemistry_foundations_measuring_temperature","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Measuring Temperature"}', 3),
  (1552, 396, 'A scale runs from 0 cm³ to 50 cm³ and has 10 equal divisions. What is the value of each division?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"The value of one division is the total scale range divided by the number of equal divisions.","sol":"Step 1: Find the total change in the scale: 50 − 0 = 50 cm³.\nStep 2: Count the divisions: 10.\nStep 3: Divide 50 by 10.\nStep 4: 50 ÷ 10 = 5 cm³.","steps":["Step 1: Find the total change in the scale: 50 − 0 = 50 cm³.","Step 2: Count the divisions: 10.","Step 3: Divide 50 by 10.","Step 4: 50 ÷ 10 = 5 cm³."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q1","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 0),
  (1553, 396, 'A measuring instrument has markings at 20, 30 and 40. There are five equal intervals between 20 and 30. What is the value of each interval?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"The difference between two labelled marks is divided by the number of equal intervals between them.","sol":"Step 1: Find the difference between 30 and 20: 10.\nStep 2: There are 5 equal intervals.\nStep 3: 10 ÷ 5 = 2.","steps":["Step 1: Find the difference between 30 and 20: 10.","Step 2: There are 5 equal intervals.","Step 3: 10 ÷ 5 = 2."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q2","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 1),
  (1554, 396, 'Why must the unit be included when recording a measurement?', 'text', 1, 'Focus on the core principle of Reading Measuring Instruments.', '{"why":"For example, 25 could mean 25 mL, 25 cm³, 25 g or another unit.","sol":"Step 1: A numerical value alone does not identify the quantity''s unit.\nStep 2: The same number can represent different quantities depending on the unit.\nStep 3: Therefore the numerical value and unit should be recorded together.","steps":["Step 1: A numerical value alone does not identify the quantity''s unit.","Step 2: The same number can represent different quantities depending on the unit.","Step 3: Therefore the numerical value and unit should be recorded together."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q3","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 2),
  (1555, 396, 'A learner reads a liquid level as 26 mL by looking from above the meniscus. The correct eye-level reading is 24 mL. What type of error has occurred?', 'text', 1, 'Think about an incorrect viewing angle.', '{"why":"Parallax occurs when an instrument is viewed from an incorrect angle.","sol":"Step 1: The learner did not place the eye at the correct level.\nStep 2: The apparent position of the meniscus changed.\nStep 3: This is called parallax error.","steps":["Step 1: The learner did not place the eye at the correct level.","Step 2: The apparent position of the meniscus changed.","Step 3: This is called parallax error."],"options":[],"conceptId":"chemistry_chemistry_foundations_reading_measuring_instruments","skillId":"chemistry_chemistry_foundations","subskillId":"chemistry_chemistry_foundations_q4","subject":"chemistry","chapter":"chemistry_foundations","topic":"Reading Measuring Instruments"}', 3),
  (1556, 397, 'What is matter?', 'text', 1, 'Focus on the core principle of Meaning of Matter.', '{"why":"Having mass and occupying space are the two basic properties used to identify matter.","sol":"Step 1: Identify the two properties used to define matter.\nStep 2: Matter has mass.\nStep 3: Matter occupies space.\nStep 4: Combine the two properties into the definition.","steps":["Step 1: Identify the two properties used to define matter.","Step 2: Matter has mass.","Step 3: Matter occupies space.","Step 4: Combine the two properties into the definition."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 0),
  (1557, 397, 'Why is air considered to be matter?', 'text', 1, 'Focus on the core principle of Meaning of Matter.', '{"why":"Being invisible does not mean that something is not matter.","sol":"Step 1: Matter must have mass.\nStep 2: Air has mass.\nStep 3: Matter must also occupy space.\nStep 4: Air occupies space.","steps":["Step 1: Matter must have mass.","Step 2: Air has mass.","Step 3: Matter must also occupy space.","Step 4: Air occupies space."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 1),
  (1558, 397, 'A stone is placed on a balance and then put into a measuring cylinder containing water. What two properties of matter are demonstrated?', 'text', 1, 'Focus on the core principle of Meaning of Matter.', '{"why":"These are the two defining properties of matter.","sol":"Step 1: The balance demonstrates that the stone has mass.\nStep 2: The measuring cylinder demonstrates that the stone occupies space because it displaces water.","steps":["Step 1: The balance demonstrates that the stone has mass.","Step 2: The measuring cylinder demonstrates that the stone occupies space because it displaces water."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 2),
  (1559, 397, 'A student says that air is not matter because it cannot be seen. Correct the statement.', 'text', 1, 'Use the definition of matter.', '{"why":"Visibility is not a requirement for something to be matter.","sol":"Step 1: Matter does not have to be visible.\nStep 2: Check whether air has mass.\nStep 3: Check whether air occupies space.\nStep 4: Air satisfies both conditions.","steps":["Step 1: Matter does not have to be visible.","Step 2: Check whether air has mass.","Step 3: Check whether air occupies space.","Step 4: Air satisfies both conditions."],"options":[],"conceptId":"chemistry_matter_separation_meaning_of_matter","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Meaning of Matter"}', 3),
  (1560, 398, 'What is a physical property?', 'text', 1, 'Focus on the core principle of Physical Properties.', '{"why":"The key feature is that the chemical identity of the substance remains unchanged.","sol":"Step 1: Identify what is being observed or measured.\nStep 2: Check whether the substance''s chemical identity changes.\nStep 3: If it does not change, the characteristic is a physical property.","steps":["Step 1: Identify what is being observed or measured.","Step 2: Check whether the substance''s chemical identity changes.","Step 3: If it does not change, the characteristic is a physical property."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 0),
  (1561, 398, 'Is density a physical property? Explain.', 'text', 1, 'Focus on the core principle of Physical Properties.', '{"why":"The substance retains its chemical identity while its density is measured.","sol":"Step 1: Density can be measured from mass and volume.\nStep 2: Measuring density does not require changing the substance into another substance.\nStep 3: Therefore density is a physical property.","steps":["Step 1: Density can be measured from mass and volume.","Step 2: Measuring density does not require changing the substance into another substance.","Step 3: Therefore density is a physical property."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 1),
  (1562, 398, 'Classify colour, boiling point and electrical conductivity as physical or chemical properties.', 'text', 1, 'Focus on the core principle of Physical Properties.', '{"why":"None of these measurements requires the substance to become a different chemical substance.","sol":"Step 1: Colour can be observed without changing the substance.\nStep 2: Boiling point can be measured without changing its chemical identity.\nStep 3: Electrical conductivity can be measured without converting it into a new substance.","steps":["Step 1: Colour can be observed without changing the substance.","Step 2: Boiling point can be measured without changing its chemical identity.","Step 3: Electrical conductivity can be measured without converting it into a new substance."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 2),
  (1563, 398, 'A learner says that boiling point is a chemical property because boiling involves a change. Is the learner correct?', 'text', 1, 'Ask whether a new chemical substance is formed.', '{"why":"A change in physical state does not necessarily mean a chemical change.","sol":"Step 1: Boiling changes a liquid into a gas.\nStep 2: The substance itself remains chemically the same.\nStep 3: Therefore boiling point is a physical property.","steps":["Step 1: Boiling changes a liquid into a gas.","Step 2: The substance itself remains chemically the same.","Step 3: Therefore boiling point is a physical property."],"options":[],"conceptId":"chemistry_matter_separation_physical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Physical Properties"}', 3),
  (1564, 399, 'What is a chemical property?', 'text', 1, 'Focus on the core principle of Chemical Properties.', '{"why":"Chemical properties concern how substances react chemically.","sol":"Step 1: Consider how the substance behaves during a chemical change.\nStep 2: A chemical property describes the substance''s ability to undergo such a change.\nStep 3: New substances are formed during the chemical change.","steps":["Step 1: Consider how the substance behaves during a chemical change.","Step 2: A chemical property describes the substance''s ability to undergo such a change.","Step 3: New substances are formed during the chemical change."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 0),
  (1565, 399, 'Why is flammability a chemical property?', 'text', 1, 'Focus on the core principle of Chemical Properties.', '{"why":"The property describes the substance''s ability to undergo a chemical change.","sol":"Step 1: Flammability describes whether a substance can burn.\nStep 2: Burning is a chemical reaction.\nStep 3: New substances are produced during combustion.","steps":["Step 1: Flammability describes whether a substance can burn.","Step 2: Burning is a chemical reaction.","Step 3: New substances are produced during combustion."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 1),
  (1566, 399, 'Why is the ability of iron to rust a chemical property?', 'text', 1, 'Focus on the core principle of Chemical Properties.', '{"why":"The property involves the chemical reactivity of iron.","sol":"Step 1: Rusting involves iron reacting with oxygen and water.\nStep 2: New substances are formed.\nStep 3: Therefore the ability of iron to rust is a chemical property.","steps":["Step 1: Rusting involves iron reacting with oxygen and water.","Step 2: New substances are formed.","Step 3: Therefore the ability of iron to rust is a chemical property."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 2),
  (1567, 399, 'A student says that the melting point of iron is a chemical property. Correct the statement.', 'text', 1, 'Ask whether melting produces a new chemical substance.', '{"why":"Chemical properties involve chemical reactions and formation of new substances.","sol":"Step 1: Melting changes iron from solid to liquid.\nStep 2: The substance remains iron.\nStep 3: No new chemical substance is formed.\nStep 4: Therefore melting point is a physical property.","steps":["Step 1: Melting changes iron from solid to liquid.","Step 2: The substance remains iron.","Step 3: No new chemical substance is formed.","Step 4: Therefore melting point is a physical property."],"options":[],"conceptId":"chemistry_matter_separation_chemical_properties","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Chemical Properties"}', 3),
  (1568, 400, 'Why do solids have a fixed shape?', 'text', 1, 'Focus on the core principle of Solids.', '{"why":"The particles cannot move freely past one another.","sol":"Step 1: Particles in a solid are closely packed.\nStep 2: They are held in relatively fixed positions.\nStep 3: Therefore the bulk solid retains a fixed shape.","steps":["Step 1: Particles in a solid are closely packed.","Step 2: They are held in relatively fixed positions.","Step 3: Therefore the bulk solid retains a fixed shape."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 0),
  (1569, 400, 'Describe the movement of particles in a solid.', 'text', 1, 'Focus on the core principle of Solids.', '{"why":"The strong attraction and close arrangement restrict their movement.","sol":"Step 1: Solid particles are held in fixed positions.\nStep 2: They cannot move freely from place to place.\nStep 3: They vibrate about their fixed positions.","steps":["Step 1: Solid particles are held in fixed positions.","Step 2: They cannot move freely from place to place.","Step 3: They vibrate about their fixed positions."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 1),
  (1570, 400, 'Why are solids difficult to compress?', 'text', 1, 'Focus on the core principle of Solids.', '{"why":"Compression requires particles to be pushed closer together.","sol":"Step 1: Particles in solids are already very close together.\nStep 2: There is little empty space between them.\nStep 3: There is therefore little room to reduce the volume.","steps":["Step 1: Particles in solids are already very close together.","Step 2: There is little empty space between them.","Step 3: There is therefore little room to reduce the volume."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 2),
  (1571, 400, 'A student says that particles in a solid do not move. Correct the statement.', 'text', 1, 'Think about what particles do even when the solid remains in one place.', '{"why":"Particles in matter are continuously moving; their movement is simply restricted in a solid.","sol":"Step 1: Solid particles are restricted to fixed positions.\nStep 2: They still possess kinetic energy.\nStep 3: They vibrate about their fixed positions.","steps":["Step 1: Solid particles are restricted to fixed positions.","Step 2: They still possess kinetic energy.","Step 3: They vibrate about their fixed positions."],"options":[],"conceptId":"chemistry_matter_separation_solids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Solids"}', 3),
  (1572, 401, 'Why do liquids take the shape of their containers?', 'text', 1, 'Focus on the core principle of Liquids.', '{"why":"The particles are not held in fixed positions as they are in solids.","sol":"Step 1: Liquid particles are close together.\nStep 2: Unlike solid particles, they are not fixed in position.\nStep 3: They can move past one another.\nStep 4: This allows the liquid to flow and take the container''s shape.","steps":["Step 1: Liquid particles are close together.","Step 2: Unlike solid particles, they are not fixed in position.","Step 3: They can move past one another.","Step 4: This allows the liquid to flow and take the container''s shape."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 0),
  (1573, 401, 'Why does a liquid have a fixed volume but no fixed shape?', 'text', 1, 'Focus on the core principle of Liquids.', '{"why":"The arrangement allows flow without allowing easy compression.","sol":"Step 1: Liquid particles remain relatively close together, maintaining a definite amount of space.\nStep 2: The particles can move past one another.\nStep 3: Therefore the volume remains approximately fixed while the shape changes.","steps":["Step 1: Liquid particles remain relatively close together, maintaining a definite amount of space.","Step 2: The particles can move past one another.","Step 3: Therefore the volume remains approximately fixed while the shape changes."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 1),
  (1574, 401, 'Why are liquids difficult to compress?', 'text', 1, 'Focus on the core principle of Liquids.', '{"why":"There is not enough empty space for the particles to be pushed significantly closer together.","sol":"Step 1: Liquid particles are already relatively close together.\nStep 2: There is little empty space between them.\nStep 3: Therefore their volume cannot be reduced easily.","steps":["Step 1: Liquid particles are already relatively close together.","Step 2: There is little empty space between them.","Step 3: Therefore their volume cannot be reduced easily."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 2),
  (1575, 401, 'A learner says that a liquid has no volume because it has no fixed shape. Explain why this is wrong.', 'text', 1, 'Separate the ideas of shape and volume.', '{"why":"Having no fixed shape does not mean having no volume.","sol":"Step 1: Shape describes the form of an object.\nStep 2: Volume describes the amount of space occupied.\nStep 3: Liquid particles remain close together, so the liquid has a definite volume.\nStep 4: The particles can rearrange, so the liquid does not have a fixed shape.","steps":["Step 1: Shape describes the form of an object.","Step 2: Volume describes the amount of space occupied.","Step 3: Liquid particles remain close together, so the liquid has a definite volume.","Step 4: The particles can rearrange, so the liquid does not have a fixed shape."],"options":[],"conceptId":"chemistry_matter_separation_liquids","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Liquids"}', 3),
  (1576, 402, 'Why can gases be compressed easily?', 'text', 1, 'Focus on the core principle of Gases.', '{"why":"Compression mainly reduces the empty spaces between gas particles.","sol":"Step 1: Gas particles are far apart.\nStep 2: There are large spaces between the particles.\nStep 3: Applying pressure can reduce these spaces.","steps":["Step 1: Gas particles are far apart.","Step 2: There are large spaces between the particles.","Step 3: Applying pressure can reduce these spaces."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 0),
  (1577, 402, 'Why does a gas fill its container?', 'text', 1, 'Focus on the core principle of Gases.', '{"why":"Gas particles are not restricted to fixed positions.","sol":"Step 1: Gas particles are not fixed in position.\nStep 2: They move freely and randomly in all directions.\nStep 3: They spread throughout the available space.","steps":["Step 1: Gas particles are not fixed in position.","Step 2: They move freely and randomly in all directions.","Step 3: They spread throughout the available space."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 1),
  (1578, 402, 'Why do gases exert pressure on the walls of their containers?', 'text', 1, 'Focus on the core principle of Gases.', '{"why":"The combined effect of many particle collisions produces gas pressure.","sol":"Step 1: Gas particles move continuously.\nStep 2: They collide with the walls of the container.\nStep 3: These collisions exert forces on the walls.","steps":["Step 1: Gas particles move continuously.","Step 2: They collide with the walls of the container.","Step 3: These collisions exert forces on the walls."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 2),
  (1579, 402, 'A gas is transferred from a 1 L container into a 5 L container. What happens to the gas volume if temperature and pressure conditions allow the gas to occupy the available space?', 'text', 1, 'Think about whether gas particles have fixed positions.', '{"why":"A gas has no fixed volume and spreads throughout the space available to it.","sol":"Step 1: Gas particles move freely.\nStep 2: They spread through the available space.\nStep 3: The gas therefore expands to occupy the larger container.","steps":["Step 1: Gas particles move freely.","Step 2: They spread through the available space.","Step 3: The gas therefore expands to occupy the larger container."],"options":[],"conceptId":"chemistry_matter_separation_gases","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Gases"}', 3),
  (1580, 403, 'Describe the arrangement of particles in a solid.', 'text', 1, 'Focus on the core principle of Particle Arrangement.', '{"why":"Their close, fixed arrangement gives solids a definite shape and volume.","sol":"Step 1: Consider the distance between particles.\nStep 2: Consider their order.\nStep 3: Solid particles are closely packed and relatively ordered.","steps":["Step 1: Consider the distance between particles.","Step 2: Consider their order.","Step 3: Solid particles are closely packed and relatively ordered."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 0),
  (1581, 403, 'Describe the arrangement of particles in a liquid.', 'text', 1, 'Focus on the core principle of Particle Arrangement.', '{"why":"This arrangement allows liquids to flow while retaining a nearly fixed volume.","sol":"Step 1: Liquid particles remain relatively close together.\nStep 2: They are not held in fixed positions.\nStep 3: Their arrangement is less ordered than in a solid.","steps":["Step 1: Liquid particles remain relatively close together.","Step 2: They are not held in fixed positions.","Step 3: Their arrangement is less ordered than in a solid."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 1),
  (1582, 403, 'State the main difference between the particle arrangement in a liquid and a gas.', 'text', 1, 'Focus on the core principle of Particle Arrangement.', '{"why":"The greater separation of gas particles explains their high compressibility and ability to fill a container.","sol":"Step 1: Liquid particles are relatively close together.\nStep 2: Gas particles are widely separated.\nStep 3: Gas particles therefore have much more empty space between them.","steps":["Step 1: Liquid particles are relatively close together.","Step 2: Gas particles are widely separated.","Step 3: Gas particles therefore have much more empty space between them."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 2),
  (1583, 403, 'Arrange the states solid, liquid and gas in order from particles closest together to particles furthest apart.', 'text', 1, 'Compare the spaces between neighbouring particles.', '{"why":"The average separation between particles increases from solids to liquids to gases.","sol":"Step 1: Solid particles are closest together.\nStep 2: Liquid particles are slightly more separated.\nStep 3: Gas particles are furthest apart.","steps":["Step 1: Solid particles are closest together.","Step 2: Liquid particles are slightly more separated.","Step 3: Gas particles are furthest apart."],"options":[],"conceptId":"chemistry_matter_separation_particle_arrangement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Particle Arrangement"}', 3),
  (1584, 404, 'How do particles move in a solid?', 'text', 1, 'Focus on the core principle of Particle Movement.', '{"why":"The particles have kinetic energy but are strongly restricted by neighbouring particles.","sol":"Step 1: Solid particles are held in fixed positions.\nStep 2: They cannot move freely from place to place.\nStep 3: They vibrate about their fixed positions.","steps":["Step 1: Solid particles are held in fixed positions.","Step 2: They cannot move freely from place to place.","Step 3: They vibrate about their fixed positions."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 0),
  (1585, 404, 'How do particles move in a gas?', 'text', 1, 'Focus on the core principle of Particle Movement.', '{"why":"Large spaces between particles and relatively weak intermolecular attractions allow considerable freedom of movement.","sol":"Step 1: Gas particles are not fixed in position.\nStep 2: They have considerable freedom of movement.\nStep 3: They move rapidly and randomly in all directions.","steps":["Step 1: Gas particles are not fixed in position.","Step 2: They have considerable freedom of movement.","Step 3: They move rapidly and randomly in all directions."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 1),
  (1586, 404, 'What is diffusion?', 'text', 1, 'Focus on the core principle of Particle Movement.', '{"why":"Random motion causes particles to spread until they become more evenly distributed.","sol":"Step 1: Particles are always moving randomly.\nStep 2: This random movement causes particles to spread.\nStep 3: The net movement is from higher concentration to lower concentration.","steps":["Step 1: Particles are always moving randomly.","Step 2: This random movement causes particles to spread.","Step 3: The net movement is from higher concentration to lower concentration."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 2),
  (1587, 404, 'A smell released at one end of a room is eventually detected at the other end. Explain this using particle movement.', 'text', 1, 'Think about gas particles and diffusion.', '{"why":"Diffusion is caused by continuous random particle motion.","sol":"Step 1: The smell-producing substance releases particles into the air.\nStep 2: Gas particles move randomly in all directions.\nStep 3: The particles diffuse from the region of higher concentration.\nStep 4: Eventually some particles reach the other side of the room.","steps":["Step 1: The smell-producing substance releases particles into the air.","Step 2: Gas particles move randomly in all directions.","Step 3: The particles diffuse from the region of higher concentration.","Step 4: Eventually some particles reach the other side of the room."],"options":[],"conceptId":"chemistry_matter_separation_particle_movement","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Particle Movement"}', 3),
  (1588, 405, 'What happens to particle movement when the temperature of a substance increases?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Particles.', '{"why":"Temperature is related to the average kinetic energy of particles.","sol":"Step 1: Heating transfers energy to the particles.\nStep 2: The particles gain kinetic energy.\nStep 3: Their average movement becomes faster.","steps":["Step 1: Heating transfers energy to the particles.","Step 2: The particles gain kinetic energy.","Step 3: Their average movement becomes faster."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 0),
  (1589, 405, 'Why does diffusion generally occur faster at higher temperatures?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Particles.', '{"why":"Faster particle movement increases the rate at which particles spread.","sol":"Step 1: Increasing temperature gives particles more kinetic energy.\nStep 2: The particles move faster.\nStep 3: Faster random movement causes particles to spread more quickly.","steps":["Step 1: Increasing temperature gives particles more kinetic energy.","Step 2: The particles move faster.","Step 3: Faster random movement causes particles to spread more quickly."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 1),
  (1590, 405, 'What happens to particle movement when a substance is cooled?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Particles.', '{"why":"Lower temperature corresponds to lower average kinetic energy.","sol":"Step 1: Cooling removes thermal energy from the substance.\nStep 2: The average kinetic energy of the particles decreases.\nStep 3: The particles move more slowly on average.","steps":["Step 1: Cooling removes thermal energy from the substance.","Step 2: The average kinetic energy of the particles decreases.","Step 3: The particles move more slowly on average."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 2),
  (1591, 405, 'Two identical beakers contain equal volumes of water. Food colouring is added to both. The colouring spreads faster in the warm water than in the cold water. Explain why.', 'text', 1, 'Compare the kinetic energy of the particles.', '{"why":"Higher temperature increases the average kinetic energy of particles.","sol":"Step 1: The warm water has a higher temperature.\nStep 2: Its particles have greater average kinetic energy.\nStep 3: They move faster.\nStep 4: Faster particle movement increases the rate of diffusion.","steps":["Step 1: The warm water has a higher temperature.","Step 2: Its particles have greater average kinetic energy.","Step 3: They move faster.","Step 4: Faster particle movement increases the rate of diffusion."],"options":[],"conceptId":"chemistry_matter_separation_effect_of_temperature_on_particles","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Effect of Temperature on Particles"}', 3),
  (1592, 406, 'What is melting?', 'text', 1, 'Focus on the core principle of Melting.', '{"why":"Heating gives the particles enough energy to leave their fixed positions and move past one another.","sol":"Step 1: Identify the initial state.\nStep 2: Identify the final state.\nStep 3: A solid changes into a liquid.","steps":["Step 1: Identify the initial state.","Step 2: Identify the final state.","Step 3: A solid changes into a liquid."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 0),
  (1593, 406, 'What happens to the particles of a solid as it is heated towards its melting point?', 'text', 1, 'Focus on the core principle of Melting.', '{"why":"The change from solid to liquid requires particles to become less restricted in their movement.","sol":"Step 1: Heating transfers energy to the particles.\nStep 2: Their kinetic energy increases.\nStep 3: They vibrate more strongly about their fixed positions.\nStep 4: At the melting point, they can begin moving past one another.","steps":["Step 1: Heating transfers energy to the particles.","Step 2: Their kinetic energy increases.","Step 3: They vibrate more strongly about their fixed positions.","Step 4: At the melting point, they can begin moving past one another."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 1),
  (1594, 406, 'Ice melts at 0°C at standard atmospheric pressure. What is the melting point of pure ice under these conditions?', 'text', 1, 'Focus on the core principle of Melting.', '{"why":"The melting point is the temperature at which a pure substance changes from solid to liquid under stated conditions.","sol":"Step 1: Identify the stated temperature.\nStep 2: The temperature at which the solid changes to liquid is the melting point.","steps":["Step 1: Identify the stated temperature.","Step 2: The temperature at which the solid changes to liquid is the melting point."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 2),
  (1595, 406, 'A learner says that melting ice produces a new substance. Is this correct?', 'text', 1, 'Compare the chemical identity of ice and liquid water.', '{"why":"A change of state does not create a different chemical substance.","sol":"Step 1: Ice is solid H₂O.\nStep 2: Liquid water is also H₂O.\nStep 3: The physical state changes, but the chemical substance does not.","steps":["Step 1: Ice is solid H₂O.","Step 2: Liquid water is also H₂O.","Step 3: The physical state changes, but the chemical substance does not."],"options":[],"conceptId":"chemistry_matter_separation_melting","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Melting"}', 3),
  (1596, 407, 'What is freezing?', 'text', 1, 'Focus on the core principle of Freezing.', '{"why":"Cooling removes energy from the particles, causing them to move less and become fixed in a solid arrangement.","sol":"Step 1: Identify the initial state: liquid.\nStep 2: Identify the final state: solid.\nStep 3: State the name of the change.","steps":["Step 1: Identify the initial state: liquid.","Step 2: Identify the final state: solid.","Step 3: State the name of the change."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 0),
  (1597, 407, 'What happens to particles when a liquid freezes?', 'text', 1, 'Focus on the core principle of Freezing.', '{"why":"Reduced particle movement allows the solid structure to form.","sol":"Step 1: Cooling removes thermal energy.\nStep 2: The particles lose kinetic energy.\nStep 3: Their movement becomes slower.\nStep 4: They become arranged in relatively fixed positions.","steps":["Step 1: Cooling removes thermal energy.","Step 2: The particles lose kinetic energy.","Step 3: Their movement becomes slower.","Step 4: They become arranged in relatively fixed positions."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 1),
  (1598, 407, 'Water freezes at approximately 0°C at standard atmospheric pressure. What happens to water when it reaches its freezing point and continues to lose heat?', 'text', 1, 'Focus on the core principle of Freezing.', '{"why":"Freezing is the liquid-to-solid change of state.","sol":"Step 1: Water is initially liquid.\nStep 2: At its freezing point, the liquid begins changing to solid.\nStep 3: Continued heat removal allows more liquid to become ice.","steps":["Step 1: Water is initially liquid.","Step 2: At its freezing point, the liquid begins changing to solid.","Step 3: Continued heat removal allows more liquid to become ice."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 2),
  (1599, 407, 'A student says that freezing is a chemical change because the water becomes hard ice. Correct the statement.', 'text', 1, 'Check whether the chemical substance has changed.', '{"why":"No new chemical substance is formed during freezing.","sol":"Step 1: Liquid water consists of H₂O.\nStep 2: Ice also consists of H₂O.\nStep 3: Only the physical state has changed.","steps":["Step 1: Liquid water consists of H₂O.","Step 2: Ice also consists of H₂O.","Step 3: Only the physical state has changed."],"options":[],"conceptId":"chemistry_matter_separation_freezing","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Freezing"}', 3),
  (1600, 408, 'What is evaporation?', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"Only particles at or near the surface can escape directly into the gas state.","sol":"Step 1: Identify the initial state: liquid.\nStep 2: Particles escape from the liquid surface.\nStep 3: They enter the gas state.","steps":["Step 1: Identify the initial state: liquid.","Step 2: Particles escape from the liquid surface.","Step 3: They enter the gas state."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 0),
  (1601, 408, 'Why can evaporation occur below the boiling point?', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"Not all particles have the same kinetic energy.","sol":"Step 1: Liquid particles have different kinetic energies.\nStep 2: Some surface particles have enough energy to escape.\nStep 3: Therefore particles can leave the surface even when the whole liquid has not reached its boiling point.","steps":["Step 1: Liquid particles have different kinetic energies.","Step 2: Some surface particles have enough energy to escape.","Step 3: Therefore particles can leave the surface even when the whole liquid has not reached its boiling point."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 1),
  (1602, 408, 'Why does evaporation generally become faster when the temperature of a liquid increases?', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"Higher temperature increases the number of particles capable of escaping from the surface.","sol":"Step 1: Increasing temperature increases the average kinetic energy of the particles.\nStep 2: More surface particles have enough energy to escape.\nStep 3: More particles escape per unit time.\nStep 4: The rate of evaporation therefore increases.","steps":["Step 1: Increasing temperature increases the average kinetic energy of the particles.","Step 2: More surface particles have enough energy to escape.","Step 3: More particles escape per unit time.","Step 4: The rate of evaporation therefore increases."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 2),
  (1603, 408, 'Wet clothes dry faster on a windy day than on a still day. Explain why.', 'text', 1, 'Think about what moving air does to water vapour near the clothes.', '{"why":"Removing vapour near the surface helps maintain a concentration gradient that favours further evaporation.","sol":"Step 1: Water evaporates from the surface of the clothes.\nStep 2: Moving air removes water vapour from near the surface.\nStep 3: This allows more water particles to escape.\nStep 4: The rate of evaporation increases.","steps":["Step 1: Water evaporates from the surface of the clothes.","Step 2: Moving air removes water vapour from near the surface.","Step 3: This allows more water particles to escape.","Step 4: The rate of evaporation increases."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 3),
  (1604, 408, 'What is evaporation used for in separation of mixtures?', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"The solvent is removed as vapour while the non-volatile solute remains.","sol":"Step 1: Start with a solution containing a dissolved solid.\nStep 2: Heat or allow the solvent to evaporate.\nStep 3: The solvent becomes vapour.\nStep 4: The dissolved solid remains.","steps":["Step 1: Start with a solution containing a dissolved solid.","Step 2: Heat or allow the solvent to evaporate.","Step 3: The solvent becomes vapour.","Step 4: The dissolved solid remains."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q5","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 4),
  (1605, 408, 'Describe how salt can be obtained from salt solution by evaporation.', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"Water is removed as vapour while the salt remains.","sol":"Step 1: Pour the salt solution into an evaporating basin.\nStep 2: Heat the solution gently.\nStep 3: Water evaporates.\nStep 4: Salt remains in the evaporating basin.","steps":["Step 1: Pour the salt solution into an evaporating basin.","Step 2: Heat the solution gently.","Step 3: Water evaporates.","Step 4: Salt remains in the evaporating basin."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q6","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 5),
  (1606, 408, 'Why is evaporation not the best method if both salt and water are required?', 'text', 1, 'Focus on the core principle of Evaporation.', '{"why":"Distillation condenses the vapour and collects the solvent.","sol":"Step 1: During evaporation, water changes into vapour.\nStep 2: The vapour is normally allowed to escape.\nStep 3: Therefore, the water is not recovered.\nStep 4: If both products are required, distillation should be used.","steps":["Step 1: During evaporation, water changes into vapour.","Step 2: The vapour is normally allowed to escape.","Step 3: Therefore, the water is not recovered.","Step 4: If both products are required, distillation should be used."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q7","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 6),
  (1607, 408, 'Which method can be used to obtain sodium chloride from salt solution when only the salt is required?', 'text', 1, 'The water does not need to be collected.', '{"why":"Evaporation removes the solvent and leaves the dissolved salt.","sol":"Step 1: Salt is dissolved in water.\nStep 2: The desired product is the solid salt.\nStep 3: Remove the water by evaporation.","steps":["Step 1: Salt is dissolved in water.","Step 2: The desired product is the solid salt.","Step 3: Remove the water by evaporation."],"options":[],"conceptId":"chemistry_matter_separation_evaporation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q8","subject":"chemistry","chapter":"matter_separation","topic":"Evaporation"}', 7),
  (1608, 409, 'What is boiling?', 'text', 1, 'Focus on the core principle of Boiling.', '{"why":"Boiling differs from evaporation because vapour formation occurs throughout the liquid.","sol":"Step 1: Identify the initial state: liquid.\nStep 2: The liquid reaches its boiling point.\nStep 3: Vapour bubbles form throughout the liquid.\nStep 4: The liquid changes to gas.","steps":["Step 1: Identify the initial state: liquid.","Step 2: The liquid reaches its boiling point.","Step 3: Vapour bubbles form throughout the liquid.","Step 4: The liquid changes to gas."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 0),
  (1609, 409, 'What happens inside a liquid when it boils?', 'text', 1, 'Focus on the core principle of Boiling.', '{"why":"Boiling is a bulk process rather than only a surface process.","sol":"Step 1: The liquid reaches its boiling point.\nStep 2: Vapour forms within the liquid.\nStep 3: Bubbles of vapour rise through the liquid.\nStep 4: The vapour escapes at the surface.","steps":["Step 1: The liquid reaches its boiling point.","Step 2: Vapour forms within the liquid.","Step 3: Bubbles of vapour rise through the liquid.","Step 4: The vapour escapes at the surface."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 1),
  (1610, 409, 'Water boils at approximately 100°C at standard atmospheric pressure. What does this temperature represent?', 'text', 1, 'Focus on the core principle of Boiling.', '{"why":"Boiling point depends on pressure, so the pressure condition must be stated.","sol":"Step 1: Identify the process occurring.\nStep 2: The temperature at which a liquid boils is its boiling point.","steps":["Step 1: Identify the process occurring.","Step 2: The temperature at which a liquid boils is its boiling point."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 2),
  (1611, 409, 'A learner says that a puddle evaporating in the sun is boiling. Explain the mistake.', 'text', 1, 'Compare where the change occurs and the temperature required.', '{"why":"Evaporation and boiling are both liquid-to-gas changes but occur differently.","sol":"Step 1: A puddle can evaporate without reaching its boiling point.\nStep 2: Evaporation occurs only at the surface.\nStep 3: Boiling occurs throughout the liquid at its boiling point.","steps":["Step 1: A puddle can evaporate without reaching its boiling point.","Step 2: Evaporation occurs only at the surface.","Step 3: Boiling occurs throughout the liquid at its boiling point."],"options":[],"conceptId":"chemistry_matter_separation_boiling","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Boiling"}', 3),
  (1612, 410, 'What is condensation?', 'text', 1, 'Focus on the core principle of Condensation.', '{"why":"Cooling removes energy from gas particles, allowing them to come closer together.","sol":"Step 1: Identify the initial state: gas.\nStep 2: Identify the final state: liquid.\nStep 3: State the name of the change.","steps":["Step 1: Identify the initial state: gas.","Step 2: Identify the final state: liquid.","Step 3: State the name of the change."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 0),
  (1613, 410, 'What happens to gas particles when condensation occurs?', 'text', 1, 'Focus on the core principle of Condensation.', '{"why":"Reduced kinetic energy allows attractive forces between particles to become more effective.","sol":"Step 1: The gas is cooled.\nStep 2: Particles lose kinetic energy.\nStep 3: They move more slowly.\nStep 4: They come closer together and form a liquid.","steps":["Step 1: The gas is cooled.","Step 2: Particles lose kinetic energy.","Step 3: They move more slowly.","Step 4: They come closer together and form a liquid."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 1),
  (1614, 410, 'Why do water droplets form on the outside of a cold glass containing a cold drink?', 'text', 1, 'Focus on the core principle of Condensation.', '{"why":"The droplets come from water vapour in the air, not from water passing through the glass.","sol":"Step 1: The air around the glass contains water vapour.\nStep 2: The cold glass cools the nearby air and water vapour.\nStep 3: The water vapour loses energy.\nStep 4: It condenses into liquid water droplets.","steps":["Step 1: The air around the glass contains water vapour.","Step 2: The cold glass cools the nearby air and water vapour.","Step 3: The water vapour loses energy.","Step 4: It condenses into liquid water droplets."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 2),
  (1615, 410, 'A student claims that water droplets on a cold bottle have leaked through the bottle. Explain why this is not normally the case.', 'text', 1, 'Think about the water vapour in the surrounding air.', '{"why":"The gas-to-liquid change occurs when the water vapour is cooled.","sol":"Step 1: Air contains water vapour.\nStep 2: The bottle surface is cold.\nStep 3: Water vapour touching the cold surface loses energy.\nStep 4: It condenses into liquid droplets.","steps":["Step 1: Air contains water vapour.","Step 2: The bottle surface is cold.","Step 3: Water vapour touching the cold surface loses energy.","Step 4: It condenses into liquid droplets."],"options":[],"conceptId":"chemistry_matter_separation_condensation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Condensation"}', 3),
  (1616, 411, 'What is sublimation?', 'text', 1, 'Focus on the core principle of Sublimation.', '{"why":"Sublimation is a direct solid-to-gas change.","sol":"Step 1: Identify the starting state: solid.\nStep 2: Identify the final state: gas.\nStep 3: Check whether the liquid state is passed through.\nStep 4: The liquid state is skipped.","steps":["Step 1: Identify the starting state: solid.","Step 2: Identify the final state: gas.","Step 3: Check whether the liquid state is passed through.","Step 4: The liquid state is skipped."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 0),
  (1617, 411, 'What happens to the particles during sublimation?', 'text', 1, 'Focus on the core principle of Sublimation.', '{"why":"The particles do not need to form a liquid first.","sol":"Step 1: Energy is supplied to the solid.\nStep 2: The particles gain kinetic energy.\nStep 3: Some particles gain enough energy to escape the solid.\nStep 4: They enter the gas state directly.","steps":["Step 1: Energy is supplied to the solid.","Step 2: The particles gain kinetic energy.","Step 3: Some particles gain enough energy to escape the solid.","Step 4: They enter the gas state directly."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 1),
  (1618, 411, 'Dry ice is solid carbon dioxide. What happens when dry ice changes directly into carbon dioxide gas?', 'text', 1, 'Focus on the core principle of Sublimation.', '{"why":"A direct solid-to-gas change is sublimation.","sol":"Step 1: The starting state is solid.\nStep 2: The final state is gas.\nStep 3: No liquid state is involved.\nStep 4: Therefore the process is sublimation.","steps":["Step 1: The starting state is solid.","Step 2: The final state is gas.","Step 3: No liquid state is involved.","Step 4: Therefore the process is sublimation."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 2),
  (1619, 411, 'A learner says that dry ice melts into a liquid before becoming gas. Correct the statement.', 'text', 1, 'Consider the meaning of sublimation.', '{"why":"Sublimation is the direct solid-to-gas change.","sol":"Step 1: Dry ice is solid CO₂.\nStep 2: Under ordinary atmospheric conditions, it changes directly to CO₂ gas.\nStep 3: It does not pass through the liquid state under these conditions.","steps":["Step 1: Dry ice is solid CO₂.","Step 2: Under ordinary atmospheric conditions, it changes directly to CO₂ gas.","Step 3: It does not pass through the liquid state under these conditions."],"options":[],"conceptId":"chemistry_matter_separation_sublimation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Sublimation"}', 3),
  (1620, 412, 'What is deposition?', 'text', 1, 'Focus on the core principle of Deposition.', '{"why":"Deposition is a direct gas-to-solid change.","sol":"Step 1: Identify the starting state: gas.\nStep 2: Identify the final state: solid.\nStep 3: Check whether the liquid state is skipped.\nStep 4: The liquid state is skipped.","steps":["Step 1: Identify the starting state: gas.","Step 2: Identify the final state: solid.","Step 3: Check whether the liquid state is skipped.","Step 4: The liquid state is skipped."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 0),
  (1621, 412, 'What happens to particles during deposition?', 'text', 1, 'Focus on the core principle of Deposition.', '{"why":"Cooling reduces particle motion enough for the particles to form a fixed solid arrangement.","sol":"Step 1: The gas is cooled.\nStep 2: Particles lose kinetic energy.\nStep 3: Their movement becomes slower.\nStep 4: They become arranged in a solid structure.","steps":["Step 1: The gas is cooled.","Step 2: Particles lose kinetic energy.","Step 3: Their movement becomes slower.","Step 4: They become arranged in a solid structure."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 1),
  (1622, 412, 'How is deposition related to sublimation?', 'text', 1, 'Focus on the core principle of Deposition.', '{"why":"Sublimation changes a solid directly to a gas, while deposition changes a gas directly to a solid.","sol":"Step 1: Sublimation is solid → gas.\nStep 2: Deposition is gas → solid.\nStep 3: The two processes move in opposite directions.","steps":["Step 1: Sublimation is solid → gas.","Step 2: Deposition is gas → solid.","Step 3: The two processes move in opposite directions."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 2),
  (1623, 412, 'Frost forms directly from water vapour on a very cold surface. Which change of state has occurred?', 'text', 1, 'Water vapour is a gas and frost is solid ice.', '{"why":"Deposition is the direct change from gas to solid.","sol":"Step 1: Water vapour is a gas.\nStep 2: Frost is solid water.\nStep 3: The change is gas → solid.\nStep 4: Gas → solid directly is deposition.","steps":["Step 1: Water vapour is a gas.","Step 2: Frost is solid water.","Step 3: The change is gas → solid.","Step 4: Gas → solid directly is deposition."],"options":[],"conceptId":"chemistry_matter_separation_deposition","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Deposition"}', 3),
  (1624, 413, 'What is an element?', 'text', 1, 'Focus on the core principle of Elements.', '{"why":"The defining feature of an element is that all its atoms have the same proton number.","sol":"Step 1: An element is a pure substance.\nStep 2: It contains only one type of atom.\nStep 3: Therefore, an element is a pure substance made of one type of atom.","steps":["Step 1: An element is a pure substance.","Step 2: It contains only one type of atom.","Step 3: Therefore, an element is a pure substance made of one type of atom."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 0),
  (1625, 413, 'Is O₂ an element or a compound?', 'text', 1, 'Focus on the core principle of Elements.', '{"why":"An element can exist as molecules such as O₂. It remains an element because it contains only oxygen atoms.","sol":"Step 1: O₂ contains two atoms.\nStep 2: Both atoms are oxygen atoms.\nStep 3: Only one type of atom is present.\nStep 4: Therefore, O₂ is an element.","steps":["Step 1: O₂ contains two atoms.","Step 2: Both atoms are oxygen atoms.","Step 3: Only one type of atom is present.","Step 4: Therefore, O₂ is an element."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 1),
  (1626, 413, 'Classify Fe, H₂O and Cu as elements or compounds.', 'text', 1, 'Focus on the core principle of Elements.', '{"why":"Elements contain one type of atom, while compounds contain two or more different elements chemically combined.","sol":"Step 1: Fe contains only iron atoms → element.\nStep 2: H₂O contains hydrogen and oxygen chemically combined → compound.\nStep 3: Cu contains only copper atoms → element.","steps":["Step 1: Fe contains only iron atoms → element.","Step 2: H₂O contains hydrogen and oxygen chemically combined → compound.","Step 3: Cu contains only copper atoms → element."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 2),
  (1627, 413, 'A substance contains only chlorine atoms. Classify it.', 'text', 1, 'Ask how many types of atoms are present.', '{"why":"A substance containing only one type of atom is an element.","sol":"Step 1: Only chlorine atoms are present.\nStep 2: Therefore, only one type of atom is present.\nStep 3: The substance is an element.","steps":["Step 1: Only chlorine atoms are present.","Step 2: Therefore, only one type of atom is present.","Step 3: The substance is an element."],"options":[],"conceptId":"chemistry_matter_separation_elements","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Elements"}', 3),
  (1628, 414, 'What is a compound?', 'text', 1, 'Focus on the core principle of Compounds.', '{"why":"Chemical combination and fixed composition distinguish compounds from mixtures.","sol":"Step 1: A compound is a pure substance.\nStep 2: It contains two or more different elements.\nStep 3: The elements are chemically combined.\nStep 4: They occur in a fixed ratio.","steps":["Step 1: A compound is a pure substance.","Step 2: It contains two or more different elements.","Step 3: The elements are chemically combined.","Step 4: They occur in a fixed ratio."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 0),
  (1629, 414, 'Why is water, H₂O, a compound?', 'text', 1, 'Focus on the core principle of Compounds.', '{"why":"A compound contains different elements chemically joined in a fixed composition.","sol":"Step 1: Water contains hydrogen and oxygen.\nStep 2: Hydrogen and oxygen are different elements.\nStep 3: They are chemically bonded.\nStep 4: They occur in a fixed 2:1 ratio.\nStep 5: Therefore, water is a compound.","steps":["Step 1: Water contains hydrogen and oxygen.","Step 2: Hydrogen and oxygen are different elements.","Step 3: They are chemically bonded.","Step 4: They occur in a fixed 2:1 ratio.","Step 5: Therefore, water is a compound."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 1),
  (1630, 414, 'Is sodium chloride, NaCl, an element or a compound? Explain.', 'text', 1, 'Focus on the core principle of Compounds.', '{"why":"It contains two different elements chemically combined in a fixed ratio.","sol":"Step 1: NaCl contains sodium and chlorine.\nStep 2: Sodium and chlorine are different elements.\nStep 3: They are chemically combined.\nStep 4: Therefore, NaCl is a compound.","steps":["Step 1: NaCl contains sodium and chlorine.","Step 2: Sodium and chlorine are different elements.","Step 3: They are chemically combined.","Step 4: Therefore, NaCl is a compound."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 2),
  (1631, 414, 'A substance contains carbon and oxygen chemically combined in a fixed ratio. What type of substance is it?', 'text', 1, 'Look for different elements that are chemically combined.', '{"why":"Different elements chemically combined in a fixed ratio form a compound.","sol":"Step 1: Carbon and oxygen are different elements.\nStep 2: They are chemically combined.\nStep 3: Therefore, the substance is a compound.","steps":["Step 1: Carbon and oxygen are different elements.","Step 2: They are chemically combined.","Step 3: Therefore, the substance is a compound."],"options":[],"conceptId":"chemistry_matter_separation_compounds","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Compounds"}', 3),
  (1632, 415, 'What is a mixture?', 'text', 1, 'Focus on the core principle of Mixtures.', '{"why":"The components of a mixture retain their identities and can generally be separated using physical methods.","sol":"Step 1: A mixture contains two or more substances.\nStep 2: The substances are physically combined.\nStep 3: They are not chemically bonded to form a new substance.\nStep 4: Therefore, the result is a mixture.","steps":["Step 1: A mixture contains two or more substances.","Step 2: The substances are physically combined.","Step 3: They are not chemically bonded to form a new substance.","Step 4: Therefore, the result is a mixture."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 0),
  (1633, 415, 'Why is air a mixture?', 'text', 1, 'Focus on the core principle of Mixtures.', '{"why":"The gases in air retain their individual identities and are not chemically combined in a fixed ratio.","sol":"Step 1: Air contains several gases, including nitrogen and oxygen.\nStep 2: These gases are not chemically combined into one fixed compound.\nStep 3: Their proportions can vary.\nStep 4: Therefore, air is a mixture.","steps":["Step 1: Air contains several gases, including nitrogen and oxygen.","Step 2: These gases are not chemically combined into one fixed compound.","Step 3: Their proportions can vary.","Step 4: Therefore, air is a mixture."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 1),
  (1634, 415, 'A student mixes iron filings with sulfur powder without heating them. Is the result a mixture or compound?', 'text', 1, 'Focus on the core principle of Mixtures.', '{"why":"Iron and sulfur are only physically mixed. A compound would require chemical combination.","sol":"Step 1: Iron and sulfur are placed together.\nStep 2: They have not chemically reacted.\nStep 3: Each substance retains its own properties.\nStep 4: Therefore, the result is a mixture.","steps":["Step 1: Iron and sulfur are placed together.","Step 2: They have not chemically reacted.","Step 3: Each substance retains its own properties.","Step 4: Therefore, the result is a mixture."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 2),
  (1635, 415, 'A sample contains water and sand. Classify it.', 'text', 1, 'Ask whether the substances are chemically combined.', '{"why":"Water and sand are physically combined and can be separated by physical methods.","sol":"Step 1: Water and sand are two different substances.\nStep 2: They are not chemically combined.\nStep 3: Therefore, the sample is a mixture.","steps":["Step 1: Water and sand are two different substances.","Step 2: They are not chemically combined.","Step 3: Therefore, the sample is a mixture."],"options":[],"conceptId":"chemistry_matter_separation_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Mixtures"}', 3),
  (1636, 416, 'What is a homogeneous mixture?', 'text', 1, 'Focus on the core principle of Homogeneous Mixtures.', '{"why":"Uniform distribution is the defining feature of a homogeneous mixture.","sol":"Step 1: It contains two or more substances.\nStep 2: The substances are physically combined.\nStep 3: They are distributed uniformly throughout the mixture.\nStep 4: Therefore, it is a homogeneous mixture.","steps":["Step 1: It contains two or more substances.","Step 2: The substances are physically combined.","Step 3: They are distributed uniformly throughout the mixture.","Step 4: Therefore, it is a homogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 0),
  (1637, 416, 'Classify salt water as homogeneous or heterogeneous when all the salt has dissolved.', 'text', 1, 'Focus on the core principle of Homogeneous Mixtures.', '{"why":"The dissolved salt is evenly distributed throughout the solution.","sol":"Step 1: Salt and water are different substances.\nStep 2: They are physically mixed.\nStep 3: The dissolved salt is uniformly distributed throughout the water.\nStep 4: Therefore, the mixture is homogeneous.","steps":["Step 1: Salt and water are different substances.","Step 2: They are physically mixed.","Step 3: The dissolved salt is uniformly distributed throughout the water.","Step 4: Therefore, the mixture is homogeneous."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 1),
  (1638, 416, 'Why is air classified as a homogeneous mixture?', 'text', 1, 'Focus on the core principle of Homogeneous Mixtures.', '{"why":"A homogeneous mixture has a uniform composition throughout.","sol":"Step 1: Air contains several gases.\nStep 2: These gases are physically mixed.\nStep 3: The gases are distributed fairly uniformly throughout a sample of air.\nStep 4: Therefore, air is a homogeneous mixture.","steps":["Step 1: Air contains several gases.","Step 2: These gases are physically mixed.","Step 3: The gases are distributed fairly uniformly throughout a sample of air.","Step 4: Therefore, air is a homogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 2),
  (1639, 416, 'A solution has the same composition at the top, middle and bottom. What type of mixture is it?', 'text', 1, 'Uniform composition is the key.', '{"why":"Homogeneous mixtures have uniform composition throughout.","sol":"Step 1: The composition is the same throughout.\nStep 2: Uniform composition means homogeneous.\nStep 3: Therefore, it is a homogeneous mixture.","steps":["Step 1: The composition is the same throughout.","Step 2: Uniform composition means homogeneous.","Step 3: Therefore, it is a homogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_homogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Homogeneous Mixtures"}', 3),
  (1640, 417, 'What is a heterogeneous mixture?', 'text', 1, 'Focus on the core principle of Heterogeneous Mixtures.', '{"why":"Uneven distribution of components distinguishes heterogeneous mixtures from homogeneous mixtures.","sol":"Step 1: It contains two or more substances.\nStep 2: The substances are physically combined.\nStep 3: They are not distributed uniformly.\nStep 4: Therefore, it is a heterogeneous mixture.","steps":["Step 1: It contains two or more substances.","Step 2: The substances are physically combined.","Step 3: They are not distributed uniformly.","Step 4: Therefore, it is a heterogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 0),
  (1641, 417, 'Classify a mixture of oil and water.', 'text', 1, 'Focus on the core principle of Heterogeneous Mixtures.', '{"why":"The oil and water form separate regions, so the composition is not uniform.","sol":"Step 1: Oil and water are different substances.\nStep 2: They do not mix uniformly.\nStep 3: Separate layers are formed.\nStep 4: Therefore, the mixture is heterogeneous.","steps":["Step 1: Oil and water are different substances.","Step 2: They do not mix uniformly.","Step 3: Separate layers are formed.","Step 4: Therefore, the mixture is heterogeneous."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 1),
  (1642, 417, 'Why is sand and water a heterogeneous mixture?', 'text', 1, 'Focus on the core principle of Heterogeneous Mixtures.', '{"why":"The components remain physically distinct and are unevenly distributed.","sol":"Step 1: Sand and water are physically combined.\nStep 2: Sand does not dissolve uniformly in the water.\nStep 3: Different parts of the sample contain different amounts of sand and water.\nStep 4: Therefore, it is heterogeneous.","steps":["Step 1: Sand and water are physically combined.","Step 2: Sand does not dissolve uniformly in the water.","Step 3: Different parts of the sample contain different amounts of sand and water.","Step 4: Therefore, it is heterogeneous."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 2),
  (1643, 417, 'A mixture contains visible particles of two different substances. Classify it.', 'text', 1, 'Visible separate components usually indicate non-uniform composition.', '{"why":"Heterogeneous mixtures have non-uniform composition and may have visibly distinct components.","sol":"Step 1: The components can be distinguished.\nStep 2: The composition is therefore not uniform.\nStep 3: The mixture is heterogeneous.","steps":["Step 1: The components can be distinguished.","Step 2: The composition is therefore not uniform.","Step 3: The mixture is heterogeneous."],"options":[],"conceptId":"chemistry_matter_separation_heterogeneous_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Heterogeneous Mixtures"}', 3),
  (1644, 418, 'What are the two types of pure substances?', 'text', 1, 'Focus on the core principle of Identifying Pure Substances.', '{"why":"Elements and compounds are the two main classes of pure substances.","sol":"Step 1: Pure substances have fixed composition.\nStep 2: A pure substance can contain one type of atom → element.\nStep 3: It can also contain different elements chemically combined → compound.","steps":["Step 1: Pure substances have fixed composition.","Step 2: A pure substance can contain one type of atom → element.","Step 3: It can also contain different elements chemically combined → compound."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 0),
  (1645, 418, 'Classify pure water, H₂O, as an element or compound.', 'text', 1, 'Focus on the core principle of Identifying Pure Substances.', '{"why":"Pure water contains hydrogen and oxygen chemically combined in a fixed ratio.","sol":"Step 1: H₂O contains hydrogen and oxygen.\nStep 2: These are two different elements.\nStep 3: They are chemically combined in a fixed ratio.\nStep 4: Therefore, H₂O is a compound.","steps":["Step 1: H₂O contains hydrogen and oxygen.","Step 2: These are two different elements.","Step 3: They are chemically combined in a fixed ratio.","Step 4: Therefore, H₂O is a compound."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 1),
  (1646, 418, 'Classify pure copper, Cu.', 'text', 1, 'Focus on the core principle of Identifying Pure Substances.', '{"why":"Copper contains only one type of atom.","sol":"Step 1: Cu represents copper.\nStep 2: Only copper atoms are present.\nStep 3: Therefore, it is an element.\nStep 4: Since it contains only one type of substance, pure copper is a pure substance.","steps":["Step 1: Cu represents copper.","Step 2: Only copper atoms are present.","Step 3: Therefore, it is an element.","Step 4: Since it contains only one type of substance, pure copper is a pure substance."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 2),
  (1647, 418, 'A sample contains only NaCl particles. Is it a pure substance?', 'text', 1, 'Ask whether only one substance is present.', '{"why":"Pure NaCl contains only one compound.","sol":"Step 1: Only NaCl is present.\nStep 2: Therefore, only one substance is present.\nStep 3: The sample is a pure substance.\nStep 4: NaCl contains sodium and chlorine chemically combined, so it is a compound.","steps":["Step 1: Only NaCl is present.","Step 2: Therefore, only one substance is present.","Step 3: The sample is a pure substance.","Step 4: NaCl contains sodium and chlorine chemically combined, so it is a compound."],"options":[],"conceptId":"chemistry_matter_separation_identifying_pure_substances","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Pure Substances"}', 3),
  (1648, 419, 'Classify salt water as pure substance, homogeneous mixture or heterogeneous mixture.', 'text', 1, 'Focus on the core principle of Identifying Mixtures.', '{"why":"Salt water contains more than one substance, but the dissolved salt is uniformly distributed.","sol":"Step 1: Salt and water are two different substances.\nStep 2: Therefore, it is a mixture.\nStep 3: If the salt is completely dissolved, it is uniformly distributed.\nStep 4: Therefore, it is a homogeneous mixture.","steps":["Step 1: Salt and water are two different substances.","Step 2: Therefore, it is a mixture.","Step 3: If the salt is completely dissolved, it is uniformly distributed.","Step 4: Therefore, it is a homogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 0),
  (1649, 419, 'Classify oil and water.', 'text', 1, 'Focus on the core principle of Identifying Mixtures.', '{"why":"The components are not uniformly distributed and form separate layers.","sol":"Step 1: Oil and water are different substances.\nStep 2: Therefore, the sample is a mixture.\nStep 3: Oil and water form separate layers.\nStep 4: The composition is not uniform.\nStep 5: Therefore, it is a heterogeneous mixture.","steps":["Step 1: Oil and water are different substances.","Step 2: Therefore, the sample is a mixture.","Step 3: Oil and water form separate layers.","Step 4: The composition is not uniform.","Step 5: Therefore, it is a heterogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 1),
  (1650, 419, 'Classify each substance: O₂, H₂O, air and sand mixed with water.', 'text', 1, 'Focus on the core principle of Identifying Mixtures.', '{"why":"Classification depends on the number of substances present, whether they are chemically combined, and whether a mixture is uniform.","sol":"Step 1: O₂ contains only oxygen atoms → element → pure substance.\nStep 2: H₂O contains hydrogen and oxygen chemically combined → compound → pure substance.\nStep 3: Air contains several gases physically mixed and is generally uniform → homogeneous mixture.\nStep 4: Sand and water are physically mixed and non-uniform → heterogeneous mixture.","steps":["Step 1: O₂ contains only oxygen atoms → element → pure substance.","Step 2: H₂O contains hydrogen and oxygen chemically combined → compound → pure substance.","Step 3: Air contains several gases physically mixed and is generally uniform → homogeneous mixture.","Step 4: Sand and water are physically mixed and non-uniform → heterogeneous mixture."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 2),
  (1651, 419, 'Classify a sample containing Fe, S and Cu particles that have not reacted chemically.', 'text', 1, 'Determine whether the substances are chemically combined.', '{"why":"Several substances are physically combined without chemical bonding, and the separate particles make the composition non-uniform.","sol":"Step 1: Iron, sulfur and copper are separate substances.\nStep 2: They have not chemically reacted.\nStep 3: Therefore, they form a mixture.\nStep 4: If the particles are distributed unevenly, it is heterogeneous.","steps":["Step 1: Iron, sulfur and copper are separate substances.","Step 2: They have not chemically reacted.","Step 3: Therefore, they form a mixture.","Step 4: If the particles are distributed unevenly, it is heterogeneous."],"options":[],"conceptId":"chemistry_matter_separation_identifying_mixtures","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Identifying Mixtures"}', 3),
  (1652, 420, 'What type of mixture can be separated by filtration?', 'text', 1, 'Focus on the core principle of Filtration.', '{"why":"The insoluble solid is trapped by the filter paper while the liquid passes through.","sol":"Step 1: Identify the phases present.\nStep 2: Filtration separates a solid from a liquid.\nStep 3: The solid must be insoluble in the liquid.","steps":["Step 1: Identify the phases present.","Step 2: Filtration separates a solid from a liquid.","Step 3: The solid must be insoluble in the liquid."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 0),
  (1653, 420, 'Describe how to separate sand from water by filtration.', 'text', 1, 'Focus on the core principle of Filtration.', '{"why":"Sand is insoluble and its particles are retained by the filter paper.","sol":"Step 1: Place filter paper in a filter funnel.\nStep 2: Place the funnel over a clean container.\nStep 3: Pour the sand-water mixture through the filter paper.\nStep 4: Sand remains on the filter paper as the residue.\nStep 5: Water passes through as the filtrate.","steps":["Step 1: Place filter paper in a filter funnel.","Step 2: Place the funnel over a clean container.","Step 3: Pour the sand-water mixture through the filter paper.","Step 4: Sand remains on the filter paper as the residue.","Step 5: Water passes through as the filtrate."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 1),
  (1654, 420, 'In filtration, what is the difference between residue and filtrate?', 'text', 1, 'Focus on the core principle of Filtration.', '{"why":"These terms describe the two products obtained during filtration.","sol":"Step 1: The residue is the material retained by the filter.\nStep 2: The filtrate is the material that passes through the filter.\nStep 3: In sand and water, sand is retained while water passes through.","steps":["Step 1: The residue is the material retained by the filter.","Step 2: The filtrate is the material that passes through the filter.","Step 3: In sand and water, sand is retained while water passes through."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 2),
  (1655, 420, 'A mixture contains chalk powder and water. Which method should be used?', 'text', 1, 'Ask whether the solid dissolves in water.', '{"why":"Filtration separates an insoluble solid from a liquid.","sol":"Step 1: Chalk is an insoluble solid.\nStep 2: The other component is a liquid.\nStep 3: Therefore, filtration is appropriate.","steps":["Step 1: Chalk is an insoluble solid.","Step 2: The other component is a liquid.","Step 3: Therefore, filtration is appropriate."],"options":[],"conceptId":"chemistry_matter_separation_filtration","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Filtration"}', 3),
  (1656, 421, 'What is crystallisation used for?', 'text', 1, 'Focus on the core principle of Crystallisation.', '{"why":"Cooling a concentrated solution can cause the dissolved substance to crystallise.","sol":"Step 1: Start with a solution containing a dissolved solid.\nStep 2: Concentrate the solution.\nStep 3: Allow it to cool.\nStep 4: Crystals form from the solution.","steps":["Step 1: Start with a solution containing a dissolved solid.","Step 2: Concentrate the solution.","Step 3: Allow it to cool.","Step 4: Crystals form from the solution."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 0),
  (1657, 421, 'Describe the main steps used to obtain crystals from a solution.', 'text', 1, 'Focus on the core principle of Crystallisation.', '{"why":"Cooling reduces the amount of solute that can remain dissolved, causing crystals to form.","sol":"Step 1: Heat the solution to concentrate it.\nStep 2: Stop heating before the solvent is completely removed.\nStep 3: Allow the concentrated solution to cool.\nStep 4: Crystals form.\nStep 5: Filter the crystals.\nStep 6: Wash and dry them.","steps":["Step 1: Heat the solution to concentrate it.","Step 2: Stop heating before the solvent is completely removed.","Step 3: Allow the concentrated solution to cool.","Step 4: Crystals form.","Step 5: Filter the crystals.","Step 6: Wash and dry them."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 1),
  (1658, 421, 'Why should a crystallisation solution not normally be evaporated completely?', 'text', 1, 'Focus on the core principle of Crystallisation.', '{"why":"Crystallisation is a controlled method of obtaining solid crystals from a concentrated solution.","sol":"Step 1: Crystallisation requires some solvent to remain.\nStep 2: Cooling the concentrated solution allows crystals to form.\nStep 3: Complete evaporation removes the solvent before controlled crystal formation occurs.\nStep 4: Therefore, the solution is normally concentrated rather than completely evaporated.","steps":["Step 1: Crystallisation requires some solvent to remain.","Step 2: Cooling the concentrated solution allows crystals to form.","Step 3: Complete evaporation removes the solvent before controlled crystal formation occurs.","Step 4: Therefore, the solution is normally concentrated rather than completely evaporated."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 2),
  (1659, 421, 'A student wants to obtain pure crystals of a soluble solid from its solution. Which method is suitable?', 'text', 1, 'The desired product is crystals, not simply a dry solid.', '{"why":"Crystallisation is specifically used to obtain a dissolved solid as crystals.","sol":"Step 1: The solid is dissolved in a solution.\nStep 2: The desired product is crystals.\nStep 3: Concentrate the solution and cool it.\nStep 4: Therefore, crystallisation is suitable.","steps":["Step 1: The solid is dissolved in a solution.","Step 2: The desired product is crystals.","Step 3: Concentrate the solution and cool it.","Step 4: Therefore, crystallisation is suitable."],"options":[],"conceptId":"chemistry_matter_separation_crystallisation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Crystallisation"}', 3),
  (1660, 422, 'What is the principle of simple distillation?', 'text', 1, 'Focus on the core principle of Simple Distillation.', '{"why":"The component that vaporises is separated and then recovered as a liquid.","sol":"Step 1: Components of the mixture have different boiling points.\nStep 2: Heating causes the more volatile liquid to vaporise.\nStep 3: The vapour is cooled.\nStep 4: It condenses and is collected.","steps":["Step 1: Components of the mixture have different boiling points.","Step 2: Heating causes the more volatile liquid to vaporise.","Step 3: The vapour is cooled.","Step 4: It condenses and is collected."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 0),
  (1661, 422, 'Describe how pure water can be obtained from salt solution by simple distillation.', 'text', 1, 'Focus on the core principle of Simple Distillation.', '{"why":"Water is volatile and can be vaporised and then condensed, while salt remains in the flask.","sol":"Step 1: Heat the salt solution.\nStep 2: Water vaporises while the salt remains behind.\nStep 3: The water vapour enters the condenser.\nStep 4: Cold water around the condenser cools the vapour.\nStep 5: The water vapour condenses.\nStep 6: Collect the liquid water as the distillate.","steps":["Step 1: Heat the salt solution.","Step 2: Water vaporises while the salt remains behind.","Step 3: The water vapour enters the condenser.","Step 4: Cold water around the condenser cools the vapour.","Step 5: The water vapour condenses.","Step 6: Collect the liquid water as the distillate."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 1),
  (1662, 422, 'What is the function of the condenser during distillation?', 'text', 1, 'Focus on the core principle of Simple Distillation.', '{"why":"Condensation converts the separated vapour back into a liquid that can be collected.","sol":"Step 1: The liquid is heated and forms vapour.\nStep 2: The vapour enters the condenser.\nStep 3: Cooling water removes heat from the vapour.\nStep 4: The vapour changes back into liquid.","steps":["Step 1: The liquid is heated and forms vapour.","Step 2: The vapour enters the condenser.","Step 3: Cooling water removes heat from the vapour.","Step 4: The vapour changes back into liquid."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 2),
  (1663, 422, 'Which method should be used to obtain water from salt solution if the water must be collected?', 'text', 1, 'The solvent is the desired product.', '{"why":"The water vapour is condensed and collected.","sol":"Step 1: Water is the desired product.\nStep 2: Evaporation would lose the water as vapour.\nStep 3: Distillation vaporises and then condenses the water.\nStep 4: Therefore, simple distillation is suitable.","steps":["Step 1: Water is the desired product.","Step 2: Evaporation would lose the water as vapour.","Step 3: Distillation vaporises and then condenses the water.","Step 4: Therefore, simple distillation is suitable."],"options":[],"conceptId":"chemistry_matter_separation_simple_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Simple Distillation"}', 3),
  (1664, 423, 'What type of mixture is separated by fractional distillation?', 'text', 1, 'Focus on the core principle of Fractional Distillation.', '{"why":"Fractional distillation separates liquids according to differences in boiling points.","sol":"Step 1: The mixture contains liquids.\nStep 2: The liquids must be miscible.\nStep 3: They have different boiling points.\nStep 4: Therefore, fractional distillation can separate them.","steps":["Step 1: The mixture contains liquids.","Step 2: The liquids must be miscible.","Step 3: They have different boiling points.","Step 4: Therefore, fractional distillation can separate them."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 0),
  (1665, 423, 'Why is a fractionating column used?', 'text', 1, 'Focus on the core principle of Fractional Distillation.', '{"why":"Repeated equilibrium between liquid and vapour phases gives better separation.","sol":"Step 1: Liquids with close boiling points are difficult to separate in one vaporisation step.\nStep 2: The column allows repeated vaporisation and condensation.\nStep 3: This enriches the vapour in the more volatile component.\nStep 4: Therefore, separation becomes more effective.","steps":["Step 1: Liquids with close boiling points are difficult to separate in one vaporisation step.","Step 2: The column allows repeated vaporisation and condensation.","Step 3: This enriches the vapour in the more volatile component.","Step 4: Therefore, separation becomes more effective."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 1),
  (1666, 423, 'State one important difference between simple and fractional distillation.', 'text', 1, 'Focus on the core principle of Fractional Distillation.', '{"why":"The column improves separation by repeated vaporisation and condensation.","sol":"Step 1: Simple distillation is commonly used to recover a solvent from a solution or separate liquids with sufficiently different boiling points.\nStep 2: Fractional distillation uses a fractionating column.\nStep 3: It is especially useful for separating miscible liquids with relatively close boiling points.","steps":["Step 1: Simple distillation is commonly used to recover a solvent from a solution or separate liquids with sufficiently different boiling points.","Step 2: Fractional distillation uses a fractionating column.","Step 3: It is especially useful for separating miscible liquids with relatively close boiling points."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 2),
  (1667, 423, 'Which method is used to separate different hydrocarbon fractions in crude oil?', 'text', 1, 'Crude oil contains many miscible hydrocarbons with different boiling ranges.', '{"why":"The different hydrocarbons have different boiling ranges.","sol":"Step 1: Crude oil contains several hydrocarbons.\nStep 2: These hydrocarbons have different boiling ranges.\nStep 3: Fractional distillation separates them into fractions.","steps":["Step 1: Crude oil contains several hydrocarbons.","Step 2: These hydrocarbons have different boiling ranges.","Step 3: Fractional distillation separates them into fractions."],"options":[],"conceptId":"chemistry_matter_separation_fractional_distillation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Fractional Distillation"}', 3),
  (1668, 424, 'What is chromatography used for?', 'text', 1, 'Focus on the core principle of Chromatography.', '{"why":"Different components have different attractions to the stationary and mobile phases.","sol":"Step 1: A mixture is placed on a stationary material.\nStep 2: A mobile solvent moves through the material.\nStep 3: Different components move at different rates.\nStep 4: The components become separated.","steps":["Step 1: A mixture is placed on a stationary material.","Step 2: A mobile solvent moves through the material.","Step 3: Different components move at different rates.","Step 4: The components become separated."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 0),
  (1669, 424, 'Why is pencil used to draw the baseline in paper chromatography?', 'text', 1, 'Focus on the core principle of Chromatography.', '{"why":"Ink can dissolve and produce additional spots, making the results unreliable.","sol":"Step 1: The baseline must remain in position during the experiment.\nStep 2: Ink contains dyes.\nStep 3: The solvent could dissolve the ink and produce extra spots.\nStep 4: Pencil graphite does not dissolve in the solvent under normal conditions.\nStep 5: Therefore, pencil is used.","steps":["Step 1: The baseline must remain in position during the experiment.","Step 2: Ink contains dyes.","Step 3: The solvent could dissolve the ink and produce extra spots.","Step 4: Pencil graphite does not dissolve in the solvent under normal conditions.","Step 5: Therefore, pencil is used."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 1),
  (1670, 424, 'A chromatogram shows four separate spots from one ink sample. What does this indicate?', 'text', 1, 'Focus on the core principle of Chromatography.', '{"why":"Different components travel different distances and appear as separate spots.","sol":"Step 1: Each separated spot represents a component under the conditions used.\nStep 2: Four distinct spots are present.\nStep 3: Therefore, the ink contains at least four separable components.","steps":["Step 1: Each separated spot represents a component under the conditions used.","Step 2: Four distinct spots are present.","Step 3: Therefore, the ink contains at least four separable components."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 2),
  (1671, 424, 'A black ink separates into three spots during paper chromatography. What can you conclude?', 'text', 1, 'Each spot represents a separated component.', '{"why":"Chromatography separates different components into different positions.","sol":"Step 1: Observe the number of spots.\nStep 2: There are three distinct spots.\nStep 3: Therefore, the ink contains at least three components that separated under those conditions.","steps":["Step 1: Observe the number of spots.","Step 2: There are three distinct spots.","Step 3: Therefore, the ink contains at least three components that separated under those conditions."],"options":[],"conceptId":"chemistry_matter_separation_chromatography","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Chromatography"}', 3),
  (1672, 425, 'What is decantation?', 'text', 1, 'Focus on the core principle of Decantation.', '{"why":"The method relies on the components separating into different layers or the solid settling due to density differences.","sol":"Step 1: Allow a denser insoluble solid to settle.\nStep 2: The solid forms sediment at the bottom.\nStep 3: Carefully pour the liquid into another container.","steps":["Step 1: Allow a denser insoluble solid to settle.","Step 2: The solid forms sediment at the bottom.","Step 3: Carefully pour the liquid into another container."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 0),
  (1673, 425, 'Describe how sand and water can be separated by decantation.', 'text', 1, 'Focus on the core principle of Decantation.', '{"why":"The sand settles because it is denser than water.","sol":"Step 1: Leave the mixture undisturbed.\nStep 2: Sand settles at the bottom.\nStep 3: Carefully pour the water into another container.\nStep 4: Leave the settled sand behind.","steps":["Step 1: Leave the mixture undisturbed.","Step 2: Sand settles at the bottom.","Step 3: Carefully pour the water into another container.","Step 4: Leave the settled sand behind."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 1),
  (1674, 425, 'Why is filtration usually better than decantation for very fine suspended particles?', 'text', 1, 'Focus on the core principle of Decantation.', '{"why":"Decantation depends on settling, while filtration physically traps insoluble particles.","sol":"Step 1: Very fine particles may remain suspended in the liquid.\nStep 2: If they do not settle completely, they can be poured out during decantation.\nStep 3: Filter paper can retain these insoluble particles.\nStep 4: Therefore, filtration gives a more effective separation.","steps":["Step 1: Very fine particles may remain suspended in the liquid.","Step 2: If they do not settle completely, they can be poured out during decantation.","Step 3: Filter paper can retain these insoluble particles.","Step 4: Therefore, filtration gives a more effective separation."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 2),
  (1675, 425, 'A mixture contains muddy water and the mud has settled at the bottom. Which simple method can be used to remove most of the water?', 'text', 1, 'The solid has already settled.', '{"why":"Decantation separates a liquid from a settled solid by carefully pouring off the liquid.","sol":"Step 1: The mud has settled at the bottom.\nStep 2: The water is above the sediment.\nStep 3: Carefully pour off the water.","steps":["Step 1: The mud has settled at the bottom.","Step 2: The water is above the sediment.","Step 3: Carefully pour off the water."],"options":[],"conceptId":"chemistry_matter_separation_decantation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Decantation"}', 3),
  (1676, 426, 'What property is used in magnetic separation?', 'text', 1, 'Focus on the core principle of Magnetic Separation.', '{"why":"A magnet attracts the magnetic component while leaving the non-magnetic component behind.","sol":"Step 1: Identify the physical property being exploited.\nStep 2: One component must be attracted to a magnet.\nStep 3: The other component should not be attracted.\nStep 4: Therefore, magnetic properties allow separation.","steps":["Step 1: Identify the physical property being exploited.","Step 2: One component must be attracted to a magnet.","Step 3: The other component should not be attracted.","Step 4: Therefore, magnetic properties allow separation."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q1","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 0),
  (1677, 426, 'How can iron filings be separated from sulfur powder?', 'text', 1, 'Focus on the core principle of Magnetic Separation.', '{"why":"Iron is attracted to a magnet whereas sulfur is not.","sol":"Step 1: Place the mixture on a suitable surface.\nStep 2: Bring a magnet close to the mixture.\nStep 3: Iron filings are attracted to the magnet.\nStep 4: Sulfur remains behind.\nStep 5: Remove the iron filings from the magnet.","steps":["Step 1: Place the mixture on a suitable surface.","Step 2: Bring a magnet close to the mixture.","Step 3: Iron filings are attracted to the magnet.","Step 4: Sulfur remains behind.","Step 5: Remove the iron filings from the magnet."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q2","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 1),
  (1678, 426, 'Why can a magnet separate iron from sulfur without causing a chemical reaction?', 'text', 1, 'Focus on the core principle of Magnetic Separation.', '{"why":"Magnetic separation changes only the arrangement of the components, not their chemical identities.","sol":"Step 1: The iron and sulfur are physically mixed.\nStep 2: A magnet acts on the magnetic property of iron.\nStep 3: No new substance is produced.\nStep 4: Therefore, the separation is a physical process.","steps":["Step 1: The iron and sulfur are physically mixed.","Step 2: A magnet acts on the magnetic property of iron.","Step 3: No new substance is produced.","Step 4: Therefore, the separation is a physical process."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q3","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 2),
  (1679, 426, 'Which method should be used to separate iron filings from copper powder?', 'text', 1, 'One of the metals is strongly attracted to a magnet.', '{"why":"The method exploits the difference in magnetic properties.","sol":"Step 1: Iron is attracted to a magnet.\nStep 2: Copper is not attracted in the same way.\nStep 3: Use a magnet to remove the iron.","steps":["Step 1: Iron is attracted to a magnet.","Step 2: Copper is not attracted in the same way.","Step 3: Use a magnet to remove the iron."],"options":[],"conceptId":"chemistry_matter_separation_magnetic_separation","skillId":"chemistry_matter_separation","subskillId":"chemistry_matter_separation_q4","subject":"chemistry","chapter":"matter_separation","topic":"Magnetic Separation"}', 3),
  (1680, 427, 'Name the three main subatomic particles and state their charges.', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"These are the three main subatomic particles and their relative electrical charges.","sol":"Step 1: The positively charged particle is the proton.\nStep 2: The particle with no charge is the neutron.\nStep 3: The negatively charged particle is the electron.","steps":["Step 1: The positively charged particle is the proton.","Step 2: The particle with no charge is the neutron.","Step 3: The negatively charged particle is the electron."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 0),
  (1681, 427, 'Where are protons, neutrons and electrons found in an atom?', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"The nucleus contains almost all of the atom''s mass, while electrons occupy the surrounding region.","sol":"Step 1: Protons are located in the nucleus.\nStep 2: Neutrons are located in the nucleus.\nStep 3: Electrons occupy energy levels around the nucleus.","steps":["Step 1: Protons are located in the nucleus.","Step 2: Neutrons are located in the nucleus.","Step 3: Electrons occupy energy levels around the nucleus."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 1),
  (1682, 427, 'Why is a normal atom electrically neutral?', 'text', 1, 'Focus on the core principle of Structure of the Atom.', '{"why":"Equal positive and negative charges give a net charge of zero.","sol":"Step 1: Each proton contributes +1 charge.\nStep 2: Each electron contributes −1 charge.\nStep 3: A normal atom has equal numbers of protons and electrons.\nStep 4: The positive and negative charges cancel.","steps":["Step 1: Each proton contributes +1 charge.","Step 2: Each electron contributes −1 charge.","Step 3: A normal atom has equal numbers of protons and electrons.","Step 4: The positive and negative charges cancel."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 2),
  (1683, 427, 'An atom contains 11 protons and 11 electrons. What is its overall charge?', 'text', 1, 'Add the positive and negative charges.', '{"why":"The positive and negative charges are equal and cancel.","sol":"Step 1: 11 protons give +11.\nStep 2: 11 electrons give −11.\nStep 3: +11 + (−11) = 0.","steps":["Step 1: 11 protons give +11.","Step 2: 11 electrons give −11.","Step 3: +11 + (−11) = 0."],"options":[],"conceptId":"chemistry_atomic_structure_structure_of_the_atom","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Structure of the Atom"}', 3),
  (1684, 428, 'What is the relative charge of a proton?', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"The proton carries one unit of positive relative charge.","sol":"Step 1: A proton is the positively charged subatomic particle.\nStep 2: Its relative charge is assigned as +1.","steps":["Step 1: A proton is the positively charged subatomic particle.","Step 2: Its relative charge is assigned as +1."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 0),
  (1685, 428, 'Where is a proton found in an atom?', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"The nucleus contains protons and neutrons.","sol":"Step 1: Protons are subatomic particles.\nStep 2: They are located in the central nucleus.","steps":["Step 1: Protons are subatomic particles.","Step 2: They are located in the central nucleus."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 1),
  (1686, 428, 'An atom has 17 protons. Which element is it?', 'text', 1, 'Focus on the core principle of Protons.', '{"why":"Every chlorine atom has 17 protons.","sol":"Step 1: The number of protons is the atomic number.\nStep 2: Atomic number 17 corresponds to chlorine.\nStep 3: Therefore, the atom is chlorine.","steps":["Step 1: The number of protons is the atomic number.","Step 2: Atomic number 17 corresponds to chlorine.","Step 3: Therefore, the atom is chlorine."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 2),
  (1687, 428, 'An atom contains 12 protons. Identify the element.', 'text', 1, 'The proton number is the atomic number.', '{"why":"Magnesium has atomic number 12.","sol":"Step 1: Atomic number = number of protons = 12.\nStep 2: Atomic number 12 is magnesium.","steps":["Step 1: Atomic number = number of protons = 12.","Step 2: Atomic number 12 is magnesium."],"options":[],"conceptId":"chemistry_atomic_structure_protons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Protons"}', 3),
  (1688, 429, 'What is the relative charge of a neutron?', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"A neutron has no electrical charge.","sol":"Step 1: A neutron is electrically neutral.\nStep 2: Therefore, its relative charge is zero.","steps":["Step 1: A neutron is electrically neutral.","Step 2: Therefore, its relative charge is zero."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 0),
  (1689, 429, 'An atom has a mass number of 23 and an atomic number of 11. Calculate the number of neutrons.', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"The mass number contains protons and neutrons, while the atomic number gives the number of protons.","sol":"Step 1: Use neutrons = mass number − atomic number.\nStep 2: Neutrons = 23 − 11.\nStep 3: Neutrons = 12.","steps":["Step 1: Use neutrons = mass number − atomic number.","Step 2: Neutrons = 23 − 11.","Step 3: Neutrons = 12."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 1),
  (1690, 429, 'An atom has 19 protons and 20 neutrons. Calculate its mass number.', 'text', 1, 'Focus on the core principle of Neutrons.', '{"why":"Mass number is the total number of protons and neutrons.","sol":"Step 1: Mass number = protons + neutrons.\nStep 2: Mass number = 19 + 20.\nStep 3: Mass number = 39.","steps":["Step 1: Mass number = protons + neutrons.","Step 2: Mass number = 19 + 20.","Step 3: Mass number = 39."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 2),
  (1691, 429, 'An atom has mass number 40 and atomic number 20. How many neutrons does it contain?', 'text', 1, 'Neutrons = mass number − atomic number.', '{"why":"The atom contains 20 protons and 20 neutrons.","sol":"Step 1: 40 − 20 = 20.","steps":["Step 1: 40 − 20 = 20."],"options":[],"conceptId":"chemistry_atomic_structure_neutrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Neutrons"}', 3),
  (1692, 430, 'What is the relative charge of an electron?', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"The electron is the negatively charged subatomic particle.","sol":"Step 1: An electron carries negative charge.\nStep 2: Its relative charge is −1.","steps":["Step 1: An electron carries negative charge.","Step 2: Its relative charge is −1."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 0),
  (1693, 430, 'A neutral atom has 8 protons. How many electrons does it have?', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"Equal numbers of protons and electrons make the atom neutral.","sol":"Step 1: A neutral atom has equal numbers of protons and electrons.\nStep 2: The atom has 8 protons.\nStep 3: Therefore, it has 8 electrons.","steps":["Step 1: A neutral atom has equal numbers of protons and electrons.","Step 2: The atom has 8 protons.","Step 3: Therefore, it has 8 electrons."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 1),
  (1694, 430, 'An atom loses two electrons. What happens to its charge?', 'text', 1, 'Focus on the core principle of Electrons.', '{"why":"Removing two negatively charged electrons produces a net positive charge of +2.","sol":"Step 1: Electrons have negative charge.\nStep 2: Losing negative charge leaves more positive charge.\nStep 3: The atom becomes a positively charged ion.\nStep 4: Losing two electrons gives a charge of +2.","steps":["Step 1: Electrons have negative charge.","Step 2: Losing negative charge leaves more positive charge.","Step 3: The atom becomes a positively charged ion.","Step 4: Losing two electrons gives a charge of +2."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 2),
  (1695, 430, 'A neutral atom has 15 protons. How many electrons are present?', 'text', 1, 'A neutral atom has equal numbers of protons and electrons.', '{"why":"The positive charge from 15 protons is balanced by 15 electrons.","sol":"Step 1: Number of electrons = number of protons.\nStep 2: Therefore, electrons = 15.","steps":["Step 1: Number of electrons = number of protons.","Step 2: Therefore, electrons = 15."],"options":[],"conceptId":"chemistry_atomic_structure_electrons","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Electrons"}', 3),
  (1696, 431, 'What is atomic number?', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"Each element has a unique number of protons.","sol":"Step 1: Atomic number identifies an element.\nStep 2: It is defined as the number of protons in the nucleus.","steps":["Step 1: Atomic number identifies an element.","Step 2: It is defined as the number of protons in the nucleus."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 0),
  (1697, 431, 'An element has atomic number 8. How many protons does it have?', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"Atomic number directly gives the number of protons.","sol":"Step 1: Atomic number = number of protons.\nStep 2: Atomic number = 8.\nStep 3: Therefore, protons = 8.","steps":["Step 1: Atomic number = number of protons.","Step 2: Atomic number = 8.","Step 3: Therefore, protons = 8."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 1),
  (1698, 431, 'A neutral atom has atomic number 12. How many electrons does it have?', 'text', 1, 'Focus on the core principle of Atomic Number.', '{"why":"Neutrality requires equal numbers of protons and electrons.","sol":"Step 1: Atomic number = number of protons = 12.\nStep 2: A neutral atom has equal protons and electrons.\nStep 3: Therefore, electrons = 12.","steps":["Step 1: Atomic number = number of protons = 12.","Step 2: A neutral atom has equal protons and electrons.","Step 3: Therefore, electrons = 12."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 2),
  (1699, 431, 'An atom has 13 protons. What is its atomic number?', 'text', 1, 'Atomic number equals the number of protons.', '{"why":"The atomic number is defined by the number of protons.","sol":"Step 1: Count the protons.\nStep 2: There are 13 protons.\nStep 3: Atomic number = 13.","steps":["Step 1: Count the protons.","Step 2: There are 13 protons.","Step 3: Atomic number = 13."],"options":[],"conceptId":"chemistry_atomic_structure_atomic_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Atomic Number"}', 3),
  (1700, 432, 'What is mass number?', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"Protons and neutrons make up almost all of the atom''s mass.","sol":"Step 1: Identify the particles that contribute almost all of the atom''s mass.\nStep 2: These are protons and neutrons.\nStep 3: Add their numbers.","steps":["Step 1: Identify the particles that contribute almost all of the atom''s mass.","Step 2: These are protons and neutrons.","Step 3: Add their numbers."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 0),
  (1701, 432, 'An atom has 8 protons and 8 neutrons. Calculate its mass number.', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"The mass number is the total number of protons and neutrons.","sol":"Step 1: Mass number = protons + neutrons.\nStep 2: Mass number = 8 + 8.\nStep 3: Mass number = 16.","steps":["Step 1: Mass number = protons + neutrons.","Step 2: Mass number = 8 + 8.","Step 3: Mass number = 16."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 1),
  (1702, 432, 'An atom has mass number 27 and 13 protons. Calculate the number of neutrons.', 'text', 1, 'Focus on the core principle of Mass Number.', '{"why":"Mass number equals protons plus neutrons.","sol":"Step 1: Neutrons = mass number − protons.\nStep 2: Neutrons = 27 − 13.\nStep 3: Neutrons = 14.","steps":["Step 1: Neutrons = mass number − protons.","Step 2: Neutrons = 27 − 13.","Step 3: Neutrons = 14."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 2),
  (1703, 432, 'An atom has 17 protons and 18 neutrons. What is its mass number?', 'text', 1, 'Add protons and neutrons.', '{"why":"Mass number is the total number of protons and neutrons.","sol":"Step 1: Mass number = 17 + 18.\nStep 2: Mass number = 35.","steps":["Step 1: Mass number = 17 + 18.","Step 2: Mass number = 35."],"options":[],"conceptId":"chemistry_atomic_structure_mass_number","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Mass Number"}', 3),
  (1704, 433, 'Write the electron arrangement of sodium, atomic number 11.', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"The 11 electrons are distributed as 2 in the first level, 8 in the second and 1 in the third.","sol":"Step 1: Sodium has 11 electrons because it is neutral.\nStep 2: Put 2 electrons in the first energy level.\nStep 3: Put 8 electrons in the second energy level.\nStep 4: The remaining electron goes into the third energy level.\nStep 5: Arrangement = 2,8,1.","steps":["Step 1: Sodium has 11 electrons because it is neutral.","Step 2: Put 2 electrons in the first energy level.","Step 3: Put 8 electrons in the second energy level.","Step 4: The remaining electron goes into the third energy level.","Step 5: Arrangement = 2,8,1."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 0),
  (1705, 433, 'Write the electron arrangement of chlorine, atomic number 17.', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"The 17 electrons fill the first three energy levels as 2, 8 and 7.","sol":"Step 1: Chlorine has 17 electrons.\nStep 2: Put 2 in the first level.\nStep 3: Put 8 in the second level.\nStep 4: The remaining 7 go into the third level.\nStep 5: Arrangement = 2,8,7.","steps":["Step 1: Chlorine has 17 electrons.","Step 2: Put 2 in the first level.","Step 3: Put 8 in the second level.","Step 4: The remaining 7 go into the third level.","Step 5: Arrangement = 2,8,7."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 1),
  (1706, 433, 'An atom has electron arrangement 2,8,8,2. How many electrons does it have?', 'text', 1, 'Focus on the core principle of Electron Arrangement.', '{"why":"The total electron arrangement gives the total number of electrons.","sol":"Step 1: Add the electrons in all energy levels.\nStep 2: 2 + 8 + 8 + 2 = 20.\nStep 3: Therefore, the atom has 20 electrons.","steps":["Step 1: Add the electrons in all energy levels.","Step 2: 2 + 8 + 8 + 2 = 20.","Step 3: Therefore, the atom has 20 electrons."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 2),
  (1707, 433, 'Write the electron arrangement of magnesium, atomic number 12.', 'text', 1, 'Distribute 12 electrons as 2, then 8, then the remainder.', '{"why":"Magnesium has 12 electrons arranged as 2,8,2.","sol":"Step 1: First level = 2.\nStep 2: Second level = 8.\nStep 3: Remaining electrons = 12 − 10 = 2.\nStep 4: Arrangement = 2,8,2.","steps":["Step 1: First level = 2.","Step 2: Second level = 8.","Step 3: Remaining electrons = 12 − 10 = 2.","Step 4: Arrangement = 2,8,2."],"options":[],"conceptId":"chemistry_atomic_structure_electron_arrangement","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Electron Arrangement"}', 3),
  (1708, 434, 'What are isotopes?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"The proton number determines the element, while changing the neutron number changes the mass number.","sol":"Step 1: Isotopes belong to the same element.\nStep 2: Therefore, they must have the same number of protons.\nStep 3: They differ in their number of neutrons.\nStep 4: This gives them different mass numbers.","steps":["Step 1: Isotopes belong to the same element.","Step 2: Therefore, they must have the same number of protons.","Step 3: They differ in their number of neutrons.","Step 4: This gives them different mass numbers."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 0),
  (1709, 434, 'How many neutrons are present in carbon-14 if carbon has atomic number 6?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Mass number is the sum of protons and neutrons.","sol":"Step 1: Mass number = 14.\nStep 2: Atomic number = protons = 6.\nStep 3: Neutrons = 14 − 6.\nStep 4: Neutrons = 8.","steps":["Step 1: Mass number = 14.","Step 2: Atomic number = protons = 6.","Step 3: Neutrons = 14 − 6.","Step 4: Neutrons = 8."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 1),
  (1710, 434, 'Why are carbon-12 and carbon-14 both carbon?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"The number of protons determines the identity of an element.","sol":"Step 1: Carbon has atomic number 6.\nStep 2: Both carbon-12 and carbon-14 contain 6 protons.\nStep 3: Therefore, both have the identity of carbon.\nStep 4: They differ only in their numbers of neutrons.","steps":["Step 1: Carbon has atomic number 6.","Step 2: Both carbon-12 and carbon-14 contain 6 protons.","Step 3: Therefore, both have the identity of carbon.","Step 4: They differ only in their numbers of neutrons."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 2),
  (1711, 434, 'Two atoms each contain 17 protons, but one has 18 neutrons and the other has 20 neutrons. What are they?', 'text', 1, 'Same protons but different neutrons.', '{"why":"They have the same proton number but different neutron numbers.","sol":"Step 1: Both atoms have 17 protons.\nStep 2: Therefore, both are chlorine atoms.\nStep 3: Their neutron numbers are different.\nStep 4: Therefore, they are isotopes of chlorine.","steps":["Step 1: Both atoms have 17 protons.","Step 2: Therefore, both are chlorine atoms.","Step 3: Their neutron numbers are different.","Step 4: Therefore, they are isotopes of chlorine."],"options":[],"conceptId":"chemistry_atomic_structure_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Isotopes"}', 3),
  (1712, 435, 'Atom X has 8 protons and 8 neutrons. Atom Y has 8 protons and 10 neutrons. Are they isotopes?', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"They have the same number of protons but different numbers of neutrons.","sol":"Step 1: Compare proton numbers: 8 and 8.\nStep 2: The proton numbers are the same.\nStep 3: Compare neutron numbers: 8 and 10.\nStep 4: The neutron numbers are different.\nStep 5: Therefore, they are isotopes.","steps":["Step 1: Compare proton numbers: 8 and 8.","Step 2: The proton numbers are the same.","Step 3: Compare neutron numbers: 8 and 10.","Step 4: The neutron numbers are different.","Step 5: Therefore, they are isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 0),
  (1713, 435, 'Atom A has 11 protons and 12 neutrons. Atom B has 12 protons and 12 neutrons. Are they isotopes?', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"Isotopes must have the same proton number.","sol":"Step 1: Compare proton numbers.\nStep 2: Atom A has 11 protons while Atom B has 12.\nStep 3: Their proton numbers are different.\nStep 4: Therefore, they are different elements and are not isotopes.","steps":["Step 1: Compare proton numbers.","Step 2: Atom A has 11 protons while Atom B has 12.","Step 3: Their proton numbers are different.","Step 4: Therefore, they are different elements and are not isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 1),
  (1714, 435, 'Determine whether chlorine-35 and chlorine-37 are isotopes. Chlorine has atomic number 17.', 'text', 1, 'Focus on the core principle of Identifying Isotopes.', '{"why":"They have the same proton number but different neutron numbers.","sol":"Step 1: Both have atomic number 17.\nStep 2: Therefore, both have 17 protons.\nStep 3: Chlorine-35 has 35 − 17 = 18 neutrons.\nStep 4: Chlorine-37 has 37 − 17 = 20 neutrons.\nStep 5: Same protons but different neutrons means isotopes.","steps":["Step 1: Both have atomic number 17.","Step 2: Therefore, both have 17 protons.","Step 3: Chlorine-35 has 35 − 17 = 18 neutrons.","Step 4: Chlorine-37 has 37 − 17 = 20 neutrons.","Step 5: Same protons but different neutrons means isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 2),
  (1715, 435, 'Are atoms with proton numbers 12 and 12 but neutron numbers 12 and 13 isotopes?', 'text', 1, 'Compare the proton numbers first.', '{"why":"Same proton number and different neutron number is the definition of isotopes.","sol":"Step 1: Both have 12 protons.\nStep 2: Their neutron numbers are different.\nStep 3: Therefore, they are isotopes.","steps":["Step 1: Both have 12 protons.","Step 2: Their neutron numbers are different.","Step 3: Therefore, they are isotopes."],"options":[],"conceptId":"chemistry_atomic_structure_identifying_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Identifying Isotopes"}', 3),
  (1716, 436, 'What is a radioisotope?', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"Radioisotopes undergo radioactive decay because their nuclei are unstable.","sol":"Step 1: Isotopes are atoms of the same element with different neutron numbers.\nStep 2: Some isotopes have unstable nuclei.\nStep 3: Unstable nuclei emit radiation.\nStep 4: Such isotopes are called radioisotopes.","steps":["Step 1: Isotopes are atoms of the same element with different neutron numbers.","Step 2: Some isotopes have unstable nuclei.","Step 3: Unstable nuclei emit radiation.","Step 4: Such isotopes are called radioisotopes."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 0),
  (1717, 436, 'Give one medical use of radioisotopes.', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"Radiation from a tracer can be detected and used to follow biological processes.","sol":"Step 1: Radioisotopes can emit detectable radiation.\nStep 2: This radiation can be monitored when a radioisotope is used as a tracer.\nStep 3: Therefore, radioisotopes can help doctors study processes inside the body.","steps":["Step 1: Radioisotopes can emit detectable radiation.","Step 2: This radiation can be monitored when a radioisotope is used as a tracer.","Step 3: Therefore, radioisotopes can help doctors study processes inside the body."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 1),
  (1718, 436, 'Why must radioisotopes be handled carefully?', 'text', 1, 'Focus on the core principle of Uses of Isotopes.', '{"why":"Ionising radiation can cause biological damage.","sol":"Step 1: Radioisotopes can emit ionising radiation.\nStep 2: Ionising radiation can damage living cells.\nStep 3: Therefore, exposure must be controlled.","steps":["Step 1: Radioisotopes can emit ionising radiation.","Step 2: Ionising radiation can damage living cells.","Step 3: Therefore, exposure must be controlled."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 2),
  (1719, 436, 'State one use of radioactive isotopes in industry.', 'text', 1, 'Think about checking materials or tracing substances.', '{"why":"Radiation intensity can be used to monitor material thickness in industrial processes.","sol":"Step 1: Radiation can be detected through or from materials.\nStep 2: This allows radioactive sources to be used for industrial measurements.\nStep 3: One example is checking material thickness.","steps":["Step 1: Radiation can be detected through or from materials.","Step 2: This allows radioactive sources to be used for industrial measurements.","Step 3: One example is checking material thickness."],"options":[],"conceptId":"chemistry_atomic_structure_uses_of_isotopes","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Uses of Isotopes"}', 3),
  (1720, 437, 'What is an ion?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Changing the number of electrons changes the balance between positive and negative charge.","sol":"Step 1: A neutral atom has equal numbers of protons and electrons.\nStep 2: If electrons are gained or lost, this balance changes.\nStep 3: The particle now has a net charge.\nStep 4: Therefore, it is an ion.","steps":["Step 1: A neutral atom has equal numbers of protons and electrons.","Step 2: If electrons are gained or lost, this balance changes.","Step 3: The particle now has a net charge.","Step 4: Therefore, it is an ion."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 0),
  (1721, 437, 'What happens when a sodium atom loses one electron?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Loss of one electron produces a net charge of +1.","sol":"Step 1: Sodium initially has equal numbers of protons and electrons.\nStep 2: It loses one negatively charged electron.\nStep 3: There is now one more positive charge than negative charge.\nStep 4: Sodium forms Na⁺.","steps":["Step 1: Sodium initially has equal numbers of protons and electrons.","Step 2: It loses one negatively charged electron.","Step 3: There is now one more positive charge than negative charge.","Step 4: Sodium forms Na⁺."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 1),
  (1722, 437, 'What happens when a chlorine atom gains one electron?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Gaining one electron gives chlorine one extra unit of negative charge.","sol":"Step 1: Chlorine gains one negatively charged electron.\nStep 2: There is now one more electron than the number of protons.\nStep 3: The particle has a net charge of −1.\nStep 4: It forms Cl⁻.","steps":["Step 1: Chlorine gains one negatively charged electron.","Step 2: There is now one more electron than the number of protons.","Step 3: The particle has a net charge of −1.","Step 4: It forms Cl⁻."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 2),
  (1723, 437, 'An atom gains two electrons. What charge will its ion have?', 'text', 1, 'Electrons carry negative charge.', '{"why":"Gaining two electrons gives a net charge of −2.","sol":"Step 1: Each gained electron contributes −1.\nStep 2: Two electrons contribute −2.\nStep 3: Therefore, the ion has a charge of −2.","steps":["Step 1: Each gained electron contributes −1.","Step 2: Two electrons contribute −2.","Step 3: Therefore, the ion has a charge of −2."],"options":[],"conceptId":"chemistry_atomic_structure_ion_formation","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Ion Formation"}', 3),
  (1724, 438, 'An ion has 12 protons and 10 electrons. Calculate its charge.', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"There are two more positive charges than negative charges.","sol":"Step 1: Use charge = protons − electrons.\nStep 2: Charge = 12 − 10.\nStep 3: Charge = +2.","steps":["Step 1: Use charge = protons − electrons.","Step 2: Charge = 12 − 10.","Step 3: Charge = +2."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q1","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 0),
  (1725, 438, 'An ion has 17 protons and 18 electrons. Calculate its charge.', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"There is one more electron than proton, giving a net −1 charge.","sol":"Step 1: Charge = protons − electrons.\nStep 2: Charge = 17 − 18.\nStep 3: Charge = −1.","steps":["Step 1: Charge = protons − electrons.","Step 2: Charge = 17 − 18.","Step 3: Charge = −1."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q2","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 1),
  (1726, 438, 'An aluminium atom has atomic number 13. It loses three electrons. What ion does it form?', 'text', 1, 'Focus on the core principle of Writing Ion Charges.', '{"why":"Aluminium loses three negatively charged electrons, leaving a net +3 charge.","sol":"Step 1: Atomic number 13 means aluminium has 13 protons.\nStep 2: Losing three electrons gives it 10 electrons.\nStep 3: Charge = 13 − 10.\nStep 4: Charge = +3.\nStep 5: Therefore, the ion is Al³⁺.","steps":["Step 1: Atomic number 13 means aluminium has 13 protons.","Step 2: Losing three electrons gives it 10 electrons.","Step 3: Charge = 13 − 10.","Step 4: Charge = +3.","Step 5: Therefore, the ion is Al³⁺."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q3","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 2),
  (1727, 438, 'An oxygen atom gains two electrons. Write the charge of the ion formed.', 'text', 1, 'Each gained electron adds one negative charge.', '{"why":"Gaining two electrons produces a 2− ion.","sol":"Step 1: Oxygen gains 2 electrons.\nStep 2: Each electron has charge −1.\nStep 3: Total charge gained = −2.\nStep 4: The ion is O²⁻.","steps":["Step 1: Oxygen gains 2 electrons.","Step 2: Each electron has charge −1.","Step 3: Total charge gained = −2.","Step 4: The ion is O²⁻."],"options":[],"conceptId":"chemistry_atomic_structure_writing_ion_charges","skillId":"chemistry_atomic_structure","subskillId":"chemistry_atomic_structure_q4","subject":"chemistry","chapter":"atomic_structure","topic":"Writing Ion Charges"}', 3),
  (1728, 439, 'How are elements arranged in the modern periodic table?', 'text', 1, 'Focus on the core principle of Arrangement of the Periodic Table.', '{"why":"Atomic number gives the number of protons and uniquely identifies each element.","sol":"Step 1: Elements are identified by their atomic numbers.\nStep 2: The atomic numbers increase across the table.\nStep 3: Therefore, elements are arranged in order of increasing atomic number.","steps":["Step 1: Elements are identified by their atomic numbers.","Step 2: The atomic numbers increase across the table.","Step 3: Therefore, elements are arranged in order of increasing atomic number."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 0),
  (1729, 439, 'What are the horizontal rows in the periodic table called?', 'text', 1, 'Focus on the core principle of Arrangement of the Periodic Table.', '{"why":"A period is a horizontal row in the periodic table.","sol":"Step 1: Look at the horizontal arrangement of elements.\nStep 2: Horizontal rows are called periods.","steps":["Step 1: Look at the horizontal arrangement of elements.","Step 2: Horizontal rows are called periods."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 1),
  (1730, 439, 'What are the vertical columns in the periodic table called?', 'text', 1, 'Focus on the core principle of Arrangement of the Periodic Table.', '{"why":"A group is a vertical column in the periodic table.","sol":"Step 1: Look at the vertical arrangement of elements.\nStep 2: Vertical columns are called groups.","steps":["Step 1: Look at the vertical arrangement of elements.","Step 2: Vertical columns are called groups."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 2),
  (1731, 439, 'Which element has atomic number 17?', 'text', 1, 'Use the atomic number to identify the element.', '{"why":"Chlorine has 17 protons and therefore atomic number 17.","sol":"Step 1: Find atomic number 17.\nStep 2: Atomic number 17 corresponds to chlorine.","steps":["Step 1: Find atomic number 17.","Step 2: Atomic number 17 corresponds to chlorine."],"options":[],"conceptId":"chemistry_periodic_table_arrangement_of_the_periodic_table","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Arrangement of the Periodic Table"}', 3),
  (1732, 440, 'What is a group in the periodic table?', 'text', 1, 'Focus on the core principle of Groups.', '{"why":"Groups contain elements with related outer-electron arrangements and similar chemical properties.","sol":"Step 1: Identify the direction of the column.\nStep 2: A vertical column is called a group.","steps":["Step 1: Identify the direction of the column.","Step 2: A vertical column is called a group."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 0),
  (1733, 440, 'Why do elements in the same group often have similar chemical properties?', 'text', 1, 'Focus on the core principle of Groups.', '{"why":"The outer electrons strongly influence how an element reacts.","sol":"Step 1: Chemical reactions involve electrons, especially outer electrons.\nStep 2: Elements in the same group have similar outer-electron arrangements.\nStep 3: Therefore, they tend to react in similar ways.","steps":["Step 1: Chemical reactions involve electrons, especially outer electrons.","Step 2: Elements in the same group have similar outer-electron arrangements.","Step 3: Therefore, they tend to react in similar ways."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 1),
  (1734, 440, 'Sodium has electron arrangement 2,8,1. Which group does it belong to?', 'text', 1, 'Focus on the core principle of Groups.', '{"why":"For the first 20 elements, the number of outer electrons helps identify the group.","sol":"Step 1: Count the electrons in the outermost energy level.\nStep 2: Sodium has 1 outer electron.\nStep 3: It belongs to Group 1.","steps":["Step 1: Count the electrons in the outermost energy level.","Step 2: Sodium has 1 outer electron.","Step 3: It belongs to Group 1."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 2),
  (1735, 440, 'An element has electron arrangement 2,8,7. Which group does it belong to?', 'text', 1, 'Count the electrons in the outermost energy level.', '{"why":"The first 20 elements with seven outer electrons are placed in Group 7.","sol":"Step 1: The outermost level contains 7 electrons.\nStep 2: An element with 7 outer electrons belongs to Group 7.\nStep 3: Therefore, the element is in Group 7.","steps":["Step 1: The outermost level contains 7 electrons.","Step 2: An element with 7 outer electrons belongs to Group 7.","Step 3: Therefore, the element is in Group 7."],"options":[],"conceptId":"chemistry_periodic_table_groups","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Groups"}', 3),
  (1736, 441, 'What is a period in the periodic table?', 'text', 1, 'Focus on the core principle of Periods.', '{"why":"Elements in the same period have the same number of occupied principal energy levels.","sol":"Step 1: Identify the horizontal rows.\nStep 2: A horizontal row is called a period.","steps":["Step 1: Identify the horizontal rows.","Step 2: A horizontal row is called a period."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 0),
  (1737, 441, 'An element has electron arrangement 2,8,1. Which period is it in?', 'text', 1, 'Focus on the core principle of Periods.', '{"why":"Three occupied energy levels correspond to Period 3.","sol":"Step 1: Count the occupied energy levels.\nStep 2: There are three energy levels: 2, 8 and 1.\nStep 3: Therefore, the element is in Period 3.","steps":["Step 1: Count the occupied energy levels.","Step 2: There are three energy levels: 2, 8 and 1.","Step 3: Therefore, the element is in Period 3."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 1),
  (1738, 441, 'An element has electron arrangement 2,8,8,2. Which period is it in?', 'text', 1, 'Focus on the core principle of Periods.', '{"why":"The number of occupied energy levels gives the period for the first 20 elements.","sol":"Step 1: Count the energy levels.\nStep 2: There are four occupied energy levels.\nStep 3: Therefore, the element is in Period 4.","steps":["Step 1: Count the energy levels.","Step 2: There are four occupied energy levels.","Step 3: Therefore, the element is in Period 4."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 2),
  (1739, 441, 'An element has electron arrangement 2,6. Which period is it in?', 'text', 1, 'Count the occupied energy levels.', '{"why":"Two occupied energy levels indicate Period 2.","sol":"Step 1: There are two occupied energy levels.\nStep 2: Therefore, the element is in Period 2.","steps":["Step 1: There are two occupied energy levels.","Step 2: Therefore, the element is in Period 2."],"options":[],"conceptId":"chemistry_periodic_table_periods","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Periods"}', 3),
  (1740, 442, 'Determine the group and period of an element with electron arrangement 2,8,1.', 'text', 1, 'Focus on the core principle of Electronic Structure and Periodic Position.', '{"why":"The three energy levels determine the period and the one outer electron determines the group.","sol":"Step 1: Count occupied energy levels: 3.\nStep 2: Therefore, period = 3.\nStep 3: Count outer electrons: 1.\nStep 4: Therefore, group = 1.","steps":["Step 1: Count occupied energy levels: 3.","Step 2: Therefore, period = 3.","Step 3: Count outer electrons: 1.","Step 4: Therefore, group = 1."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 0),
  (1741, 442, 'Determine the group and period of an element with electron arrangement 2,8,6.', 'text', 1, 'Focus on the core principle of Electronic Structure and Periodic Position.', '{"why":"The number of occupied levels gives the period while the outer-electron number gives the group for these elements.","sol":"Step 1: There are three occupied energy levels.\nStep 2: Period = 3.\nStep 3: There are six outer electrons.\nStep 4: Group = 6.","steps":["Step 1: There are three occupied energy levels.","Step 2: Period = 3.","Step 3: There are six outer electrons.","Step 4: Group = 6."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 1),
  (1742, 442, 'An element is in Group 2 and Period 3. Write its electron arrangement.', 'text', 1, 'Focus on the core principle of Electronic Structure and Periodic Position.', '{"why":"The group gives the outer-electron number and the period gives the number of occupied energy levels.","sol":"Step 1: Period 3 means three occupied energy levels.\nStep 2: Group 2 means two outer electrons.\nStep 3: Fill the first level with 2 electrons.\nStep 4: Fill the second level with 8 electrons.\nStep 5: Put 2 electrons in the third level.\nStep 6: Arrangement = 2,8,2.","steps":["Step 1: Period 3 means three occupied energy levels.","Step 2: Group 2 means two outer electrons.","Step 3: Fill the first level with 2 electrons.","Step 4: Fill the second level with 8 electrons.","Step 5: Put 2 electrons in the third level.","Step 6: Arrangement = 2,8,2."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 2),
  (1743, 442, 'An element has electron arrangement 2,8,7. State its group and period.', 'text', 1, 'Use outer electrons for the group and occupied levels for the period.', '{"why":"The electron arrangement directly gives both its group and period.","sol":"Step 1: Seven outer electrons → Group 7.\nStep 2: Three occupied energy levels → Period 3.","steps":["Step 1: Seven outer electrons → Group 7.","Step 2: Three occupied energy levels → Period 3."],"options":[],"conceptId":"chemistry_periodic_table_electronic_structure_and_periodic_position","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Electronic Structure and Periodic Position"}', 3),
  (1744, 443, 'Why are lithium, sodium and potassium placed in the same group?', 'text', 1, 'Focus on the core principle of Group 1 Elements.', '{"why":"Similar outer-electron arrangements give Group 1 elements similar chemical behaviour.","sol":"Step 1: Lithium has one outer electron.\nStep 2: Sodium has one outer electron.\nStep 3: Potassium has one outer electron.\nStep 4: Therefore, they belong to the same group.","steps":["Step 1: Lithium has one outer electron.","Step 2: Sodium has one outer electron.","Step 3: Potassium has one outer electron.","Step 4: Therefore, they belong to the same group."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 0),
  (1745, 443, 'Write the general word equation for the reaction of a Group 1 metal with water.', 'text', 1, 'Focus on the core principle of Group 1 Elements.', '{"why":"This is the characteristic reaction of Group 1 metals with water.","sol":"Step 1: The metal reacts with water.\nStep 2: A metal hydroxide is formed.\nStep 3: Hydrogen gas is also produced.","steps":["Step 1: The metal reacts with water.","Step 2: A metal hydroxide is formed.","Step 3: Hydrogen gas is also produced."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 1),
  (1746, 443, 'Which is more reactive, lithium or potassium?', 'text', 1, 'Focus on the core principle of Group 1 Elements.', '{"why":"Group 1 metals generally become more reactive down the group.","sol":"Step 1: Lithium and potassium are both Group 1 metals.\nStep 2: Potassium is lower down the group.\nStep 3: Reactivity of Group 1 metals increases down the group.\nStep 4: Therefore, potassium is more reactive.","steps":["Step 1: Lithium and potassium are both Group 1 metals.","Step 2: Potassium is lower down the group.","Step 3: Reactivity of Group 1 metals increases down the group.","Step 4: Therefore, potassium is more reactive."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 2),
  (1747, 443, 'Which Group 1 metal is more reactive: sodium or potassium?', 'text', 1, 'Reactivity increases down Group 1.', '{"why":"Potassium is lower in Group 1 than sodium.","sol":"Step 1: Potassium is below sodium in Group 1.\nStep 2: Reactivity increases down the group.\nStep 3: Therefore, potassium is more reactive.","steps":["Step 1: Potassium is below sodium in Group 1.","Step 2: Reactivity increases down the group.","Step 3: Therefore, potassium is more reactive."],"options":[],"conceptId":"chemistry_periodic_table_group_1_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 1 Elements"}', 3),
  (1748, 444, 'How many outer electrons does a Group 2 element have?', 'text', 1, 'Focus on the core principle of Group 2 Elements.', '{"why":"The outer-electron arrangement is characteristic of Group 2.","sol":"Step 1: Group 2 elements have two electrons in their outermost energy level.\nStep 2: Therefore, the number of outer electrons is 2.","steps":["Step 1: Group 2 elements have two electrons in their outermost energy level.","Step 2: Therefore, the number of outer electrons is 2."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 0),
  (1749, 444, 'What ion is commonly formed when a Group 2 atom loses its outer electrons?', 'text', 1, 'Focus on the core principle of Group 2 Elements.', '{"why":"Loss of two electrons produces a net charge of +2.","sol":"Step 1: A Group 2 atom has two outer electrons.\nStep 2: It can lose both electrons.\nStep 3: Losing two negative electrons leaves a +2 charge.","steps":["Step 1: A Group 2 atom has two outer electrons.","Step 2: It can lose both electrons.","Step 3: Losing two negative electrons leaves a +2 charge."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 1),
  (1750, 444, 'Write the electron arrangement of calcium, atomic number 20.', 'text', 1, 'Focus on the core principle of Group 2 Elements.', '{"why":"Calcium has 20 electrons distributed among four occupied energy levels.","sol":"Step 1: Calcium has 20 electrons.\nStep 2: First energy level = 2.\nStep 3: Second = 8.\nStep 4: Third = 8.\nStep 5: Remaining electrons = 2.\nStep 6: Arrangement = 2,8,8,2.","steps":["Step 1: Calcium has 20 electrons.","Step 2: First energy level = 2.","Step 3: Second = 8.","Step 4: Third = 8.","Step 5: Remaining electrons = 2.","Step 6: Arrangement = 2,8,8,2."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1751, 444, 'An element has electron arrangement 2,8,2. Which group does it belong to?', 'text', 1, 'Look at the outermost energy level.', '{"why":"Group 2 elements have two outer electrons.","sol":"Step 1: The outermost level contains 2 electrons.\nStep 2: Therefore, the element belongs to Group 2.","steps":["Step 1: The outermost level contains 2 electrons.","Step 2: Therefore, the element belongs to Group 2."],"options":[],"conceptId":"chemistry_periodic_table_group_2_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 2 Elements"}', 3),
  (1752, 445, 'How many outer electrons does a Group 7 element have?', 'text', 1, 'Focus on the core principle of Group 7 Elements.', '{"why":"The seven outer electrons are characteristic of the halogens.","sol":"Step 1: Group 7 elements are characterised by seven outer electrons.\nStep 2: Therefore, the number is 7.","steps":["Step 1: Group 7 elements are characterised by seven outer electrons.","Step 2: Therefore, the number is 7."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 0),
  (1753, 445, 'Why does chlorine tend to gain one electron?', 'text', 1, 'Focus on the core principle of Group 7 Elements.', '{"why":"A full outer energy level gives the atom a more stable electron arrangement.","sol":"Step 1: Chlorine has electron arrangement 2,8,7.\nStep 2: Its outer level contains 7 electrons.\nStep 3: Gaining one electron gives 8 outer electrons.\nStep 4: Therefore, chlorine tends to gain one electron.","steps":["Step 1: Chlorine has electron arrangement 2,8,7.","Step 2: Its outer level contains 7 electrons.","Step 3: Gaining one electron gives 8 outer electrons.","Step 4: Therefore, chlorine tends to gain one electron."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 1),
  (1754, 445, 'Which is more reactive: fluorine or chlorine?', 'text', 1, 'Focus on the core principle of Group 7 Elements.', '{"why":"Halogens generally become less reactive down Group 7.","sol":"Step 1: Fluorine and chlorine are both Group 7 elements.\nStep 2: Fluorine is above chlorine.\nStep 3: Halogen reactivity generally decreases down the group.\nStep 4: Therefore, fluorine is more reactive.","steps":["Step 1: Fluorine and chlorine are both Group 7 elements.","Step 2: Fluorine is above chlorine.","Step 3: Halogen reactivity generally decreases down the group.","Step 4: Therefore, fluorine is more reactive."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 2),
  (1755, 445, 'An atom has electron arrangement 2,8,7. Which type of element is it likely to be?', 'text', 1, 'Seven outer electrons identify a particular chemical family.', '{"why":"The electron arrangement identifies the halogen family.","sol":"Step 1: The atom has seven outer electrons.\nStep 2: Seven outer electrons correspond to Group 7.\nStep 3: Group 7 elements are halogens.","steps":["Step 1: The atom has seven outer electrons.","Step 2: Seven outer electrons correspond to Group 7.","Step 3: Group 7 elements are halogens."],"options":[],"conceptId":"chemistry_periodic_table_group_7_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 7 Elements"}', 3),
  (1756, 446, 'Why are Group 0 elements generally unreactive?', 'text', 1, 'Focus on the core principle of Group 0 Elements.', '{"why":"A full outer energy level reduces the tendency to undergo chemical reactions.","sol":"Step 1: Their outer energy levels are full.\nStep 2: They do not normally need to gain, lose or share electrons.\nStep 3: Therefore, they have low chemical reactivity.","steps":["Step 1: Their outer energy levels are full.","Step 2: They do not normally need to gain, lose or share electrons.","Step 3: Therefore, they have low chemical reactivity."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 0),
  (1757, 446, 'Write the electron arrangement of neon, atomic number 10.', 'text', 1, 'Focus on the core principle of Group 0 Elements.', '{"why":"Neon has a complete first and second energy level.","sol":"Step 1: Neon has 10 electrons.\nStep 2: Put 2 in the first energy level.\nStep 3: The remaining 8 go into the second level.\nStep 4: Arrangement = 2,8.","steps":["Step 1: Neon has 10 electrons.","Step 2: Put 2 in the first energy level.","Step 3: The remaining 8 go into the second level.","Step 4: Arrangement = 2,8."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 1),
  (1758, 446, 'Why does helium belong to Group 0 even though it has only two electrons?', 'text', 1, 'Focus on the core principle of Group 0 Elements.', '{"why":"Helium has a stable full outer energy level even though the first level holds only two electrons.","sol":"Step 1: The first energy level can hold a maximum of 2 electrons.\nStep 2: Helium has 2 electrons.\nStep 3: Its only energy level is therefore full.\nStep 4: A full outer energy level makes helium a noble gas.","steps":["Step 1: The first energy level can hold a maximum of 2 electrons.","Step 2: Helium has 2 electrons.","Step 3: Its only energy level is therefore full.","Step 4: A full outer energy level makes helium a noble gas."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 2),
  (1759, 446, 'An element has electron arrangement 2,8,8. Which group does it belong to?', 'text', 1, 'The outermost energy level is completely full.', '{"why":"Group 0 elements have full outer energy levels.","sol":"Step 1: The outermost energy level contains 8 electrons.\nStep 2: This is a full outer level for the first 20 elements.\nStep 3: The element belongs to Group 0.","steps":["Step 1: The outermost energy level contains 8 electrons.","Step 2: This is a full outer level for the first 20 elements.","Step 3: The element belongs to Group 0."],"options":[],"conceptId":"chemistry_periodic_table_group_0_elements","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Group 0 Elements"}', 3),
  (1760, 447, 'State two typical physical properties of metals.', 'text', 1, 'Focus on the core principle of Metals and Non-metals.', '{"why":"These are characteristic physical properties of many metals.","sol":"Step 1: Metals generally conduct heat well.\nStep 2: Metals generally conduct electricity well.\nStep 3: Metals are also commonly malleable and ductile.","steps":["Step 1: Metals generally conduct heat well.","Step 2: Metals generally conduct electricity well.","Step 3: Metals are also commonly malleable and ductile."],"options":[],"conceptId":"chemistry_periodic_table_metals_and_non_metals","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Metals and Non-metals"}', 0),
  (1761, 447, 'State two typical properties of non-metals.', 'text', 1, 'Focus on the core principle of Metals and Non-metals.', '{"why":"These properties distinguish many non-metals from metals.","sol":"Step 1: Most non-metals are poor electrical conductors.\nStep 2: Many solid non-metals are brittle.\nStep 3: Many also have relatively low melting and boiling points.","steps":["Step 1: Most non-metals are poor electrical conductors.","Step 2: Many solid non-metals are brittle.","Step 3: Many also have relatively low melting and boiling points."],"options":[],"conceptId":"chemistry_periodic_table_metals_and_non_metals","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Metals and Non-metals"}', 1),
  (1762, 447, 'Where are most metals found in the periodic table?', 'text', 1, 'Focus on the core principle of Metals and Non-metals.', '{"why":"The periodic table broadly separates metallic and non-metallic elements.","sol":"Step 1: Examine the broad regions of the periodic table.\nStep 2: Most metals occur on the left and central regions.\nStep 3: Therefore, metals are mainly found on the left and centre.","steps":["Step 1: Examine the broad regions of the periodic table.","Step 2: Most metals occur on the left and central regions.","Step 3: Therefore, metals are mainly found on the left and centre."],"options":[],"conceptId":"chemistry_periodic_table_metals_and_non_metals","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Metals and Non-metals"}', 2),
  (1763, 447, 'An element is a good conductor of electricity and is malleable. Is it more likely to be a metal or non-metal?', 'text', 1, 'Think about the typical properties of metals.', '{"why":"Electrical conductivity and malleability are typical metallic properties.","sol":"Step 1: Good electrical conductivity is characteristic of metals.\nStep 2: Malleability is also characteristic of metals.\nStep 3: Therefore, the element is likely to be a metal.","steps":["Step 1: Good electrical conductivity is characteristic of metals.","Step 2: Malleability is also characteristic of metals.","Step 3: Therefore, the element is likely to be a metal."],"options":[],"conceptId":"chemistry_periodic_table_metals_and_non_metals","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Metals and Non-metals"}', 3),
  (1764, 448, 'What is meant by a periodic trend?', 'text', 1, 'Focus on the core principle of Periodic Trends.', '{"why":"The repeating electron arrangements produce repeating chemical and physical behaviour.","sol":"Step 1: Elements are arranged systematically in the periodic table.\nStep 2: Their properties show repeating patterns.\nStep 3: These patterns are called periodic trends.","steps":["Step 1: Elements are arranged systematically in the periodic table.","Step 2: Their properties show repeating patterns.","Step 3: These patterns are called periodic trends."],"options":[],"conceptId":"chemistry_periodic_table_periodic_trends","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Periodic Trends"}', 0),
  (1765, 448, 'How does the reactivity of Group 1 metals change down the group?', 'text', 1, 'Focus on the core principle of Periodic Trends.', '{"why":"The outer electron becomes easier to remove as atomic size increases.","sol":"Step 1: Compare Group 1 elements from top to bottom.\nStep 2: The outer electron is farther from the nucleus in larger atoms.\nStep 3: It becomes easier to lose the outer electron.\nStep 4: Therefore, reactivity increases down Group 1.","steps":["Step 1: Compare Group 1 elements from top to bottom.","Step 2: The outer electron is farther from the nucleus in larger atoms.","Step 3: It becomes easier to lose the outer electron.","Step 4: Therefore, reactivity increases down Group 1."],"options":[],"conceptId":"chemistry_periodic_table_periodic_trends","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Periodic Trends"}', 1),
  (1766, 448, 'How does the reactivity of Group 7 elements change down the group?', 'text', 1, 'Focus on the core principle of Periodic Trends.', '{"why":"The attraction for an incoming electron becomes weaker as the atomic size increases.","sol":"Step 1: Group 7 elements react by gaining an electron.\nStep 2: Down the group, atoms become larger.\nStep 3: The nucleus attracts an incoming electron less strongly.\nStep 4: Therefore, reactivity decreases down Group 7.","steps":["Step 1: Group 7 elements react by gaining an electron.","Step 2: Down the group, atoms become larger.","Step 3: The nucleus attracts an incoming electron less strongly.","Step 4: Therefore, reactivity decreases down Group 7."],"options":[],"conceptId":"chemistry_periodic_table_periodic_trends","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Periodic Trends"}', 2),
  (1767, 448, 'Which is more reactive in Group 1: lithium or potassium?', 'text', 1, 'Group 1 reactivity increases down the group.', '{"why":"Group 1 metals become more reactive down the group.","sol":"Step 1: Potassium is below lithium.\nStep 2: Reactivity increases down Group 1.\nStep 3: Therefore, potassium is more reactive.","steps":["Step 1: Potassium is below lithium.","Step 2: Reactivity increases down Group 1.","Step 3: Therefore, potassium is more reactive."],"options":[],"conceptId":"chemistry_periodic_table_periodic_trends","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Periodic Trends"}', 3),
  (1768, 449, 'Why does atomic size generally increase down a group?', 'text', 1, 'Focus on the core principle of Atomic Size.', '{"why":"Each new energy level increases the distance between the nucleus and the outermost electrons.","sol":"Step 1: Moving down a group adds another occupied energy level.\nStep 2: The outer electrons are therefore farther from the nucleus.\nStep 3: The atom becomes larger.","steps":["Step 1: Moving down a group adds another occupied energy level.","Step 2: The outer electrons are therefore farther from the nucleus.","Step 3: The atom becomes larger."],"options":[],"conceptId":"chemistry_periodic_table_atomic_size","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q1","subject":"chemistry","chapter":"periodic_table","topic":"Atomic Size"}', 0),
  (1769, 449, 'Which atom is larger: sodium or potassium?', 'text', 1, 'Focus on the core principle of Atomic Size.', '{"why":"Potassium has an additional occupied energy level compared with sodium.","sol":"Step 1: Sodium and potassium are in Group 1.\nStep 2: Potassium is below sodium.\nStep 3: Atomic size increases down a group.\nStep 4: Therefore, potassium is larger.","steps":["Step 1: Sodium and potassium are in Group 1.","Step 2: Potassium is below sodium.","Step 3: Atomic size increases down a group.","Step 4: Therefore, potassium is larger."],"options":[],"conceptId":"chemistry_periodic_table_atomic_size","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q2","subject":"chemistry","chapter":"periodic_table","topic":"Atomic Size"}', 1),
  (1770, 449, 'How does atomic size generally change from left to right across a period?', 'text', 1, 'Focus on the core principle of Atomic Size.', '{"why":"Increasing nuclear charge attracts the electrons more strongly across the same main energy level.","sol":"Step 1: Proton number increases across the period.\nStep 2: Electrons are added to the same main energy level.\nStep 3: The increasing nuclear attraction pulls the electrons closer.\nStep 4: Therefore, atomic size generally decreases.","steps":["Step 1: Proton number increases across the period.","Step 2: Electrons are added to the same main energy level.","Step 3: The increasing nuclear attraction pulls the electrons closer.","Step 4: Therefore, atomic size generally decreases."],"options":[],"conceptId":"chemistry_periodic_table_atomic_size","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q3","subject":"chemistry","chapter":"periodic_table","topic":"Atomic Size"}', 2),
  (1771, 449, 'Which is larger, lithium or sodium?', 'text', 1, 'Both are in Group 1. Look at their positions.', '{"why":"Sodium has one more occupied energy level than lithium.","sol":"Step 1: Lithium is above sodium in Group 1.\nStep 2: Atomic size increases down a group.\nStep 3: Therefore, sodium is larger.","steps":["Step 1: Lithium is above sodium in Group 1.","Step 2: Atomic size increases down a group.","Step 3: Therefore, sodium is larger."],"options":[],"conceptId":"chemistry_periodic_table_atomic_size","skillId":"chemistry_periodic_table","subskillId":"chemistry_periodic_table_q4","subject":"chemistry","chapter":"periodic_table","topic":"Atomic Size"}', 3),
  (1772, 450, 'Why do atoms form chemical bonds?', 'text', 1, 'Focus on the core principle of Why Atoms Bond.', '{"why":"Bonding allows atoms to obtain a more stable outer-electron arrangement.","sol":"Step 1: Atoms have electrons arranged in energy levels.\nStep 2: The outer electrons are involved in chemical bonding.\nStep 3: Atoms can become more stable by gaining, losing or sharing electrons.\nStep 4: Therefore, atoms form bonds to achieve a more stable electron arrangement.","steps":["Step 1: Atoms have electrons arranged in energy levels.","Step 2: The outer electrons are involved in chemical bonding.","Step 3: Atoms can become more stable by gaining, losing or sharing electrons.","Step 4: Therefore, atoms form bonds to achieve a more stable electron arrangement."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 0),
  (1773, 450, 'Which electrons are mainly involved in chemical bonding?', 'text', 1, 'Focus on the core principle of Why Atoms Bond.', '{"why":"Valence electrons are the outermost electrons and are mainly responsible for chemical bonding.","sol":"Step 1: Examine the electron arrangement of an atom.\nStep 2: The electrons in the outermost energy level are called valence electrons.\nStep 3: These electrons participate mainly in bonding.","steps":["Step 1: Examine the electron arrangement of an atom.","Step 2: The electrons in the outermost energy level are called valence electrons.","Step 3: These electrons participate mainly in bonding."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 1),
  (1774, 450, 'State the three main ways atoms can achieve a more stable electron arrangement.', 'text', 1, 'Focus on the core principle of Why Atoms Bond.', '{"why":"These processes allow atoms to achieve more stable outer-electron arrangements.","sol":"Step 1: An atom can remove outer electrons.\nStep 2: An atom can receive electrons.\nStep 3: Atoms can also share electrons.","steps":["Step 1: An atom can remove outer electrons.","Step 2: An atom can receive electrons.","Step 3: Atoms can also share electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 2),
  (1775, 450, 'An atom has one electron in its outermost energy level. What could it do to become more stable?', 'text', 1, 'Consider whether losing one outer electron could leave a full inner level.', '{"why":"Losing the outer electron can leave a stable full energy level.","sol":"Step 1: The atom has one outer electron.\nStep 2: Losing that electron leaves the next lower energy level as the outer level.\nStep 3: If that level is full, the atom becomes more stable.","steps":["Step 1: The atom has one outer electron.","Step 2: Losing that electron leaves the next lower energy level as the outer level.","Step 3: If that level is full, the atom becomes more stable."],"options":[],"conceptId":"chemistry_chemical_bonding_why_atoms_bond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Why Atoms Bond"}', 3),
  (1776, 451, 'What is meant by valency?', 'text', 1, 'Focus on the core principle of Valency.', '{"why":"Valency helps determine how atoms combine to form compounds.","sol":"Step 1: Valency describes the combining capacity of an atom.\nStep 2: It is related to the number of electrons involved in forming bonds.","steps":["Step 1: Valency describes the combining capacity of an atom.","Step 2: It is related to the number of electrons involved in forming bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 0),
  (1777, 451, 'What is the common valency of sodium?', 'text', 1, 'Focus on the core principle of Valency.', '{"why":"Sodium commonly loses one outer electron when forming compounds.","sol":"Step 1: Sodium has electron arrangement 2,8,1.\nStep 2: It has one outer electron.\nStep 3: It commonly loses one electron.\nStep 4: Therefore, its common valency is 1.","steps":["Step 1: Sodium has electron arrangement 2,8,1.","Step 2: It has one outer electron.","Step 3: It commonly loses one electron.","Step 4: Therefore, its common valency is 1."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 1),
  (1778, 451, 'What is the common valency of magnesium?', 'text', 1, 'Focus on the core principle of Valency.', '{"why":"Magnesium commonly loses its two outer electrons during compound formation.","sol":"Step 1: Magnesium has electron arrangement 2,8,2.\nStep 2: It has two outer electrons.\nStep 3: It commonly loses two electrons.\nStep 4: Therefore, its common valency is 2.","steps":["Step 1: Magnesium has electron arrangement 2,8,2.","Step 2: It has two outer electrons.","Step 3: It commonly loses two electrons.","Step 4: Therefore, its common valency is 2."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 2),
  (1779, 451, 'What is the common valency of chlorine?', 'text', 1, 'Chlorine has seven outer electrons.', '{"why":"Chlorine commonly gains or shares one electron when forming compounds.","sol":"Step 1: Chlorine has seven outer electrons.\nStep 2: It needs one more electron to complete the outer level.\nStep 3: Therefore, its common valency is 1.","steps":["Step 1: Chlorine has seven outer electrons.","Step 2: It needs one more electron to complete the outer level.","Step 3: Therefore, its common valency is 1."],"options":[],"conceptId":"chemistry_chemical_bonding_valency","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Valency"}', 3),
  (1780, 452, 'What is ionic bonding?', 'text', 1, 'Focus on the core principle of Ionic Bonding.', '{"why":"The attraction between positive and negative ions holds an ionic compound together.","sol":"Step 1: Ionic bonding involves charged particles called ions.\nStep 2: One atom loses electrons and another gains electrons.\nStep 3: Positive and negative ions are produced.\nStep 4: The oppositely charged ions attract each other.","steps":["Step 1: Ionic bonding involves charged particles called ions.","Step 2: One atom loses electrons and another gains electrons.","Step 3: Positive and negative ions are produced.","Step 4: The oppositely charged ions attract each other."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 0),
  (1781, 452, 'Which type of elements commonly form ionic compounds?', 'text', 1, 'Focus on the core principle of Ionic Bonding.', '{"why":"Electron transfer between a metal and a non-metal commonly produces ionic bonding.","sol":"Step 1: Metals tend to lose electrons.\nStep 2: Non-metals tend to gain electrons.\nStep 3: This produces oppositely charged ions.\nStep 4: The ions attract to form an ionic compound.","steps":["Step 1: Metals tend to lose electrons.","Step 2: Non-metals tend to gain electrons.","Step 3: This produces oppositely charged ions.","Step 4: The ions attract to form an ionic compound."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 1),
  (1782, 452, 'What holds sodium chloride together?', 'text', 1, 'Focus on the core principle of Ionic Bonding.', '{"why":"Oppositely charged ions attract each other strongly.","sol":"Step 1: Sodium loses an electron to form Na⁺.\nStep 2: Chlorine gains an electron to form Cl⁻.\nStep 3: Na⁺ and Cl⁻ have opposite charges.\nStep 4: They attract electrostatically.","steps":["Step 1: Sodium loses an electron to form Na⁺.","Step 2: Chlorine gains an electron to form Cl⁻.","Step 3: Na⁺ and Cl⁻ have opposite charges.","Step 4: They attract electrostatically."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 2),
  (1783, 452, 'What type of bond is formed when electrons are transferred from a metal to a non-metal?', 'text', 1, 'Think about the ions produced after electron transfer.', '{"why":"Ionic bonding results from attraction between oppositely charged ions.","sol":"Step 1: Electron transfer produces positive and negative ions.\nStep 2: The ions attract each other.\nStep 3: This attraction is ionic bonding.","steps":["Step 1: Electron transfer produces positive and negative ions.","Step 2: The ions attract each other.","Step 3: This attraction is ionic bonding."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic Bonding"}', 3),
  (1784, 453, 'What happens to sodium when it reacts with chlorine?', 'text', 1, 'Focus on the core principle of Electron Transfer.', '{"why":"Loss of one electron gives sodium a more stable electron arrangement.","sol":"Step 1: Sodium has electron arrangement 2,8,1.\nStep 2: It has one outer electron.\nStep 3: Sodium loses this electron.\nStep 4: It forms Na⁺.","steps":["Step 1: Sodium has electron arrangement 2,8,1.","Step 2: It has one outer electron.","Step 3: Sodium loses this electron.","Step 4: It forms Na⁺."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 0),
  (1785, 453, 'What happens to chlorine when it reacts with sodium?', 'text', 1, 'Focus on the core principle of Electron Transfer.', '{"why":"Gaining one electron gives chlorine a full outer energy level.","sol":"Step 1: Chlorine has electron arrangement 2,8,7.\nStep 2: It needs one electron to complete its outer level.\nStep 3: Chlorine gains one electron.\nStep 4: It forms Cl⁻.","steps":["Step 1: Chlorine has electron arrangement 2,8,7.","Step 2: It needs one electron to complete its outer level.","Step 3: Chlorine gains one electron.","Step 4: It forms Cl⁻."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 1),
  (1786, 453, 'Write the electron-transfer equations for sodium and chlorine.', 'text', 1, 'Focus on the core principle of Electron Transfer.', '{"why":"The equations show the transfer of one electron from sodium to chlorine.","sol":"Step 1: Sodium loses one electron: Na → Na⁺ + e⁻.\nStep 2: Chlorine gains one electron: Cl + e⁻ → Cl⁻.\nStep 3: The electron lost by sodium is gained by chlorine.","steps":["Step 1: Sodium loses one electron: Na → Na⁺ + e⁻.","Step 2: Chlorine gains one electron: Cl + e⁻ → Cl⁻.","Step 3: The electron lost by sodium is gained by chlorine."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 2),
  (1787, 453, 'How many electrons are transferred when one sodium atom reacts with one chlorine atom?', 'text', 1, 'Compare their outer-electron arrangements.', '{"why":"Sodium loses one electron and chlorine gains one electron.","sol":"Step 1: Sodium has one outer electron.\nStep 2: Chlorine needs one electron.\nStep 3: Therefore, one electron is transferred.","steps":["Step 1: Sodium has one outer electron.","Step 2: Chlorine needs one electron.","Step 3: Therefore, one electron is transferred."],"options":[],"conceptId":"chemistry_chemical_bonding_electron_transfer","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Electron Transfer"}', 3),
  (1788, 454, 'How is a positive ion formed?', 'text', 1, 'Focus on the core principle of Formation of Positive Ions.', '{"why":"Loss of negatively charged electrons gives the particle a net positive charge.","sol":"Step 1: An atom loses one or more electrons.\nStep 2: Electrons have negative charges.\nStep 3: Removing negative charge leaves more positive charge than negative charge.\nStep 4: The atom becomes a positive ion.","steps":["Step 1: An atom loses one or more electrons.","Step 2: Electrons have negative charges.","Step 3: Removing negative charge leaves more positive charge than negative charge.","Step 4: The atom becomes a positive ion."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 0),
  (1789, 454, 'Write the equation for formation of a sodium ion.', 'text', 1, 'Focus on the core principle of Formation of Positive Ions.', '{"why":"Sodium loses one electron to form Na⁺.","sol":"Step 1: Sodium has one outer electron.\nStep 2: Sodium loses this electron.\nStep 3: The resulting ion has a +1 charge.","steps":["Step 1: Sodium has one outer electron.","Step 2: Sodium loses this electron.","Step 3: The resulting ion has a +1 charge."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 1),
  (1790, 454, 'Write the equation for formation of a magnesium ion.', 'text', 1, 'Focus on the core principle of Formation of Positive Ions.', '{"why":"Magnesium loses two electrons to form Mg²⁺.","sol":"Step 1: Magnesium has two outer electrons.\nStep 2: Magnesium loses both electrons.\nStep 3: Losing two electrons gives a +2 charge.","steps":["Step 1: Magnesium has two outer electrons.","Step 2: Magnesium loses both electrons.","Step 3: Losing two electrons gives a +2 charge."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 2),
  (1791, 454, 'An atom loses three electrons. What charge will its ion have?', 'text', 1, 'Each lost electron leaves one extra positive charge.', '{"why":"The loss of three negatively charged electrons produces a net charge of +3.","sol":"Step 1: Losing one electron gives +1.\nStep 2: Losing three electrons gives +3.\nStep 3: Therefore, the ion has a 3+ charge.","steps":["Step 1: Losing one electron gives +1.","Step 2: Losing three electrons gives +3.","Step 3: Therefore, the ion has a 3+ charge."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_positive_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Positive Ions"}', 3),
  (1792, 455, 'How is a negative ion formed?', 'text', 1, 'Focus on the core principle of Formation of Negative Ions.', '{"why":"The gained electrons give the particle a net negative charge.","sol":"Step 1: An atom gains one or more electrons.\nStep 2: Electrons carry negative charges.\nStep 3: Gaining electrons increases the negative charge.\nStep 4: The atom becomes a negative ion.","steps":["Step 1: An atom gains one or more electrons.","Step 2: Electrons carry negative charges.","Step 3: Gaining electrons increases the negative charge.","Step 4: The atom becomes a negative ion."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 0),
  (1793, 455, 'Write the equation for formation of a chloride ion.', 'text', 1, 'Focus on the core principle of Formation of Negative Ions.', '{"why":"Chlorine gains one electron to complete its outer energy level.","sol":"Step 1: Chlorine has seven outer electrons.\nStep 2: It gains one electron.\nStep 3: It forms a 1− ion.","steps":["Step 1: Chlorine has seven outer electrons.","Step 2: It gains one electron.","Step 3: It forms a 1− ion."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 1),
  (1794, 455, 'Write the equation for formation of an oxide ion.', 'text', 1, 'Focus on the core principle of Formation of Negative Ions.', '{"why":"Oxygen gains two electrons to achieve a stable outer-electron arrangement.","sol":"Step 1: Oxygen has six outer electrons.\nStep 2: It needs two more electrons for a full outer level.\nStep 3: Oxygen gains two electrons.\nStep 4: It forms O²⁻.","steps":["Step 1: Oxygen has six outer electrons.","Step 2: It needs two more electrons for a full outer level.","Step 3: Oxygen gains two electrons.","Step 4: It forms O²⁻."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 2),
  (1795, 455, 'An atom gains two electrons. What charge will its ion have?', 'text', 1, 'Each gained electron adds one negative charge.', '{"why":"Gaining two electrons produces a net charge of −2.","sol":"Step 1: One gained electron gives −1.\nStep 2: Two gained electrons give −2.\nStep 3: Therefore, the ion has a 2− charge.","steps":["Step 1: One gained electron gives −1.","Step 2: Two gained electrons give −2.","Step 3: Therefore, the ion has a 2− charge."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_negative_ions","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Negative Ions"}', 3),
  (1796, 456, 'Write the formula of sodium chloride using Na⁺ and Cl⁻.', 'text', 1, 'Focus on the core principle of Formation of Ionic Compounds.', '{"why":"One Na⁺ balances one Cl⁻.","sol":"Step 1: Na⁺ has charge +1.\nStep 2: Cl⁻ has charge −1.\nStep 3: One of each gives total charge 0.\nStep 4: Therefore, the formula is NaCl.","steps":["Step 1: Na⁺ has charge +1.","Step 2: Cl⁻ has charge −1.","Step 3: One of each gives total charge 0.","Step 4: Therefore, the formula is NaCl."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 0),
  (1797, 456, 'Write the formula of magnesium chloride using Mg²⁺ and Cl⁻.', 'text', 1, 'Focus on the core principle of Formation of Ionic Compounds.', '{"why":"Two chloride ions are needed to balance the +2 charge of magnesium.","sol":"Step 1: Mg²⁺ has charge +2.\nStep 2: Each Cl⁻ has charge −1.\nStep 3: Two Cl⁻ ions give total charge −2.\nStep 4: +2 + (−2) = 0.\nStep 5: Therefore, the formula is MgCl₂.","steps":["Step 1: Mg²⁺ has charge +2.","Step 2: Each Cl⁻ has charge −1.","Step 3: Two Cl⁻ ions give total charge −2.","Step 4: +2 + (−2) = 0.","Step 5: Therefore, the formula is MgCl₂."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 1),
  (1798, 456, 'Write the formula of aluminium oxide using Al³⁺ and O²⁻.', 'text', 1, 'Focus on the core principle of Formation of Ionic Compounds.', '{"why":"Two Al³⁺ ions and three O²⁻ ions produce a neutral compound.","sol":"Step 1: Al³⁺ has charge +3.\nStep 2: O²⁻ has charge −2.\nStep 3: Two Al³⁺ ions give +6.\nStep 4: Three O²⁻ ions give −6.\nStep 5: The total charge is 0.\nStep 6: Therefore, the formula is Al₂O₃.","steps":["Step 1: Al³⁺ has charge +3.","Step 2: O²⁻ has charge −2.","Step 3: Two Al³⁺ ions give +6.","Step 4: Three O²⁻ ions give −6.","Step 5: The total charge is 0.","Step 6: Therefore, the formula is Al₂O₃."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 2),
  (1799, 456, 'Write the formula of calcium chloride using Ca²⁺ and Cl⁻.', 'text', 1, 'Make the total positive and negative charges equal.', '{"why":"Two chloride ions balance the +2 charge of one calcium ion.","sol":"Step 1: Ca²⁺ contributes +2.\nStep 2: Each Cl⁻ contributes −1.\nStep 3: Two Cl⁻ ions give −2.\nStep 4: The total charge is zero.\nStep 5: Formula = CaCl₂.","steps":["Step 1: Ca²⁺ contributes +2.","Step 2: Each Cl⁻ contributes −1.","Step 3: Two Cl⁻ ions give −2.","Step 4: The total charge is zero.","Step 5: Formula = CaCl₂."],"options":[],"conceptId":"chemistry_chemical_bonding_formation_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Formation of Ionic Compounds"}', 3),
  (1800, 457, 'Why do ionic compounds generally have high melting points?', 'text', 1, 'Focus on the core principle of Properties of Ionic Compounds.', '{"why":"Strong ionic attractions hold the lattice together.","sol":"Step 1: Ionic compounds contain positive and negative ions.\nStep 2: The ions are held together by strong electrostatic attractions.\nStep 3: A large amount of energy is required to overcome these attractions.\nStep 4: Therefore, ionic compounds generally have high melting points.","steps":["Step 1: Ionic compounds contain positive and negative ions.","Step 2: The ions are held together by strong electrostatic attractions.","Step 3: A large amount of energy is required to overcome these attractions.","Step 4: Therefore, ionic compounds generally have high melting points."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 0),
  (1801, 457, 'Why does solid sodium chloride not conduct electricity?', 'text', 1, 'Focus on the core principle of Properties of Ionic Compounds.', '{"why":"Electrical conduction requires mobile charged particles.","sol":"Step 1: Sodium chloride contains charged Na⁺ and Cl⁻ ions.\nStep 2: In the solid lattice, these ions are fixed in position.\nStep 3: They cannot move through the solid.\nStep 4: Therefore, they cannot carry electric current.","steps":["Step 1: Sodium chloride contains charged Na⁺ and Cl⁻ ions.","Step 2: In the solid lattice, these ions are fixed in position.","Step 3: They cannot move through the solid.","Step 4: Therefore, they cannot carry electric current."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 1),
  (1802, 457, 'Why can molten sodium chloride conduct electricity?', 'text', 1, 'Focus on the core principle of Properties of Ionic Compounds.', '{"why":"Mobile ions allow an electric current to pass through the molten compound.","sol":"Step 1: Heating sodium chloride until it melts breaks the fixed lattice arrangement.\nStep 2: The Na⁺ and Cl⁻ ions become free to move.\nStep 3: Moving ions carry electric charge.\nStep 4: Therefore, molten sodium chloride conducts electricity.","steps":["Step 1: Heating sodium chloride until it melts breaks the fixed lattice arrangement.","Step 2: The Na⁺ and Cl⁻ ions become free to move.","Step 3: Moving ions carry electric charge.","Step 4: Therefore, molten sodium chloride conducts electricity."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 2),
  (1803, 457, 'State whether solid or molten sodium chloride conducts electricity.', 'text', 1, 'Ask whether the ions can move.', '{"why":"Only the molten state provides mobile ions.","sol":"Step 1: In solid sodium chloride, ions are fixed.\nStep 2: In molten sodium chloride, ions can move.\nStep 3: Therefore, molten sodium chloride conducts electricity but solid sodium chloride does not.","steps":["Step 1: In solid sodium chloride, ions are fixed.","Step 2: In molten sodium chloride, ions can move.","Step 3: Therefore, molten sodium chloride conducts electricity but solid sodium chloride does not."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_ionic_compounds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Ionic Compounds"}', 3),
  (1804, 458, 'What is covalent bonding?', 'text', 1, 'Focus on the core principle of Covalent Bonding.', '{"why":"Shared electron pairs hold the covalently bonded atoms together.","sol":"Step 1: Identify the atoms involved.\nStep 2: The atoms share electrons rather than completely transferring them.\nStep 3: The shared electrons form covalent bonds.","steps":["Step 1: Identify the atoms involved.","Step 2: The atoms share electrons rather than completely transferring them.","Step 3: The shared electrons form covalent bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 0),
  (1805, 458, 'Which type of elements commonly form covalent bonds?', 'text', 1, 'Focus on the core principle of Covalent Bonding.', '{"why":"Non-metal atoms commonly achieve stable arrangements by sharing electrons.","sol":"Step 1: Covalent bonding involves sharing electrons.\nStep 2: Non-metal atoms commonly share electrons with other non-metal atoms.\nStep 3: Therefore, covalent compounds commonly form between non-metals.","steps":["Step 1: Covalent bonding involves sharing electrons.","Step 2: Non-metal atoms commonly share electrons with other non-metal atoms.","Step 3: Therefore, covalent compounds commonly form between non-metals."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 1),
  (1806, 458, 'How is a hydrogen molecule, H₂, formed?', 'text', 1, 'Focus on the core principle of Covalent Bonding.', '{"why":"The shared pair gives each hydrogen atom access to two electrons.","sol":"Step 1: Each hydrogen atom has one electron.\nStep 2: Each hydrogen atom needs one more electron for a full first energy level.\nStep 3: The two hydrogen atoms share one pair of electrons.\nStep 4: A single covalent bond forms.","steps":["Step 1: Each hydrogen atom has one electron.","Step 2: Each hydrogen atom needs one more electron for a full first energy level.","Step 3: The two hydrogen atoms share one pair of electrons.","Step 4: A single covalent bond forms."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 2),
  (1807, 458, 'What type of bond holds the two hydrogen atoms together in H₂?', 'text', 1, 'The atoms share electrons.', '{"why":"One shared pair of electrons forms one covalent bond.","sol":"Step 1: The hydrogen atoms share a pair of electrons.\nStep 2: A shared electron pair forms a covalent bond.\nStep 3: Therefore, H₂ contains a single covalent bond.","steps":["Step 1: The hydrogen atoms share a pair of electrons.","Step 2: A shared electron pair forms a covalent bond.","Step 3: Therefore, H₂ contains a single covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_covalent_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Covalent Bonding"}', 3),
  (1808, 459, 'What is a single covalent bond?', 'text', 1, 'Focus on the core principle of Single Covalent Bonds.', '{"why":"The shared pair provides the bonding interaction between the atoms.","sol":"Step 1: Covalent bonding involves sharing electrons.\nStep 2: If one pair of electrons is shared, one covalent bond is formed.\nStep 3: Therefore, one shared pair is a single covalent bond.","steps":["Step 1: Covalent bonding involves sharing electrons.","Step 2: If one pair of electrons is shared, one covalent bond is formed.","Step 3: Therefore, one shared pair is a single covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 0),
  (1809, 459, 'How many electron pairs are shared in H₂?', 'text', 1, 'Focus on the core principle of Single Covalent Bonds.', '{"why":"H₂ contains one single covalent bond.","sol":"Step 1: H₂ contains one H—H bond.\nStep 2: A single covalent bond contains one shared pair.\nStep 3: Therefore, one electron pair is shared.","steps":["Step 1: H₂ contains one H—H bond.","Step 2: A single covalent bond contains one shared pair.","Step 3: Therefore, one electron pair is shared."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 1),
  (1810, 459, 'How many electron pairs are shared in Cl₂?', 'text', 1, 'Focus on the core principle of Single Covalent Bonds.', '{"why":"Cl₂ contains one single covalent bond.","sol":"Step 1: Each chlorine atom contributes one electron to bonding.\nStep 2: The atoms share one pair.\nStep 3: Therefore, Cl₂ has one shared electron pair.","steps":["Step 1: Each chlorine atom contributes one electron to bonding.","Step 2: The atoms share one pair.","Step 3: Therefore, Cl₂ has one shared electron pair."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 2),
  (1811, 459, 'How many covalent bonds are present in HCl?', 'text', 1, 'Hydrogen and chlorine share one pair of electrons.', '{"why":"The hydrogen and chlorine atoms share one electron pair.","sol":"Step 1: HCl contains H—Cl.\nStep 2: One shared pair forms one covalent bond.\nStep 3: Therefore, HCl contains one covalent bond.","steps":["Step 1: HCl contains H—Cl.","Step 2: One shared pair forms one covalent bond.","Step 3: Therefore, HCl contains one covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_single_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Single Covalent Bonds"}', 3),
  (1812, 460, 'What is a double covalent bond?', 'text', 1, 'Focus on the core principle of Double Covalent Bonds.', '{"why":"Two shared pairs provide the bonding between the two atoms.","sol":"Step 1: Covalent bonds involve shared electron pairs.\nStep 2: A double bond contains two shared pairs.\nStep 3: Therefore, a double covalent bond contains two shared electron pairs.","steps":["Step 1: Covalent bonds involve shared electron pairs.","Step 2: A double bond contains two shared pairs.","Step 3: Therefore, a double covalent bond contains two shared electron pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 0),
  (1813, 460, 'Why does O₂ form a double covalent bond?', 'text', 1, 'Focus on the core principle of Double Covalent Bonds.', '{"why":"Each oxygen atom needs two additional electrons.","sol":"Step 1: Each oxygen atom has six outer electrons.\nStep 2: Each oxygen atom needs two more electrons for a full outer level.\nStep 3: The atoms share two pairs of electrons.\nStep 4: Therefore, O₂ has a double covalent bond.","steps":["Step 1: Each oxygen atom has six outer electrons.","Step 2: Each oxygen atom needs two more electrons for a full outer level.","Step 3: The atoms share two pairs of electrons.","Step 4: Therefore, O₂ has a double covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 1),
  (1814, 460, 'How many shared electron pairs are present in O₂?', 'text', 1, 'Focus on the core principle of Double Covalent Bonds.', '{"why":"A double covalent bond consists of two shared electron pairs.","sol":"Step 1: O₂ contains an O=O double bond.\nStep 2: A double bond contains two shared pairs.\nStep 3: Therefore, O₂ has two shared electron pairs.","steps":["Step 1: O₂ contains an O=O double bond.","Step 2: A double bond contains two shared pairs.","Step 3: Therefore, O₂ has two shared electron pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 2),
  (1815, 460, 'How many covalent bonds are represented by O=O?', 'text', 1, 'Count the shared electron pairs represented by the double bond.', '{"why":"A double covalent bond contains two shared electron pairs.","sol":"Step 1: The double line represents two shared electron pairs.\nStep 2: Each shared pair is one covalent bond.\nStep 3: Therefore, there are two covalent bonds.","steps":["Step 1: The double line represents two shared electron pairs.","Step 2: Each shared pair is one covalent bond.","Step 3: Therefore, there are two covalent bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_double_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Double Covalent Bonds"}', 3),
  (1816, 461, 'What is a triple covalent bond?', 'text', 1, 'Focus on the core principle of Triple Covalent Bonds.', '{"why":"Three shared electron pairs form the triple bond.","sol":"Step 1: Covalent bonds involve shared electron pairs.\nStep 2: A triple bond contains three shared pairs.\nStep 3: Therefore, a triple covalent bond contains three shared electron pairs.","steps":["Step 1: Covalent bonds involve shared electron pairs.","Step 2: A triple bond contains three shared pairs.","Step 3: Therefore, a triple covalent bond contains three shared electron pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 0),
  (1817, 461, 'Why does N₂ form a triple covalent bond?', 'text', 1, 'Focus on the core principle of Triple Covalent Bonds.', '{"why":"Each nitrogen atom needs three additional electrons.","sol":"Step 1: Each nitrogen atom has five outer electrons.\nStep 2: Each nitrogen atom needs three more electrons for a full outer level.\nStep 3: The nitrogen atoms share three pairs of electrons.\nStep 4: Therefore, N₂ has a triple covalent bond.","steps":["Step 1: Each nitrogen atom has five outer electrons.","Step 2: Each nitrogen atom needs three more electrons for a full outer level.","Step 3: The nitrogen atoms share three pairs of electrons.","Step 4: Therefore, N₂ has a triple covalent bond."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 1),
  (1818, 461, 'How many shared electron pairs are present in N₂?', 'text', 1, 'Focus on the core principle of Triple Covalent Bonds.', '{"why":"A triple covalent bond consists of three shared electron pairs.","sol":"Step 1: N₂ contains an N≡N triple bond.\nStep 2: A triple bond contains three shared pairs.\nStep 3: Therefore, N₂ has three shared electron pairs.","steps":["Step 1: N₂ contains an N≡N triple bond.","Step 2: A triple bond contains three shared pairs.","Step 3: Therefore, N₂ has three shared electron pairs."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 2),
  (1819, 461, 'How many covalent bonds are represented by N≡N?', 'text', 1, 'A triple bond contains three shared pairs.', '{"why":"N₂ contains one triple covalent bond made of three shared electron pairs.","sol":"Step 1: The triple bond represents three shared electron pairs.\nStep 2: Each shared pair forms one covalent bond.\nStep 3: Therefore, there are three covalent bonds.","steps":["Step 1: The triple bond represents three shared electron pairs.","Step 2: Each shared pair forms one covalent bond.","Step 3: Therefore, there are three covalent bonds."],"options":[],"conceptId":"chemistry_chemical_bonding_triple_covalent_bonds","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Triple Covalent Bonds"}', 3),
  (1820, 462, 'What does a dot-and-cross diagram show?', 'text', 1, 'Focus on the core principle of Dot-and-Cross Diagrams.', '{"why":"The diagram makes electron sharing or transfer visible.","sol":"Step 1: Identify the outer electrons of the atoms.\nStep 2: Show which electrons are contributed by each atom.\nStep 3: Show shared electron pairs between bonded atoms.\nStep 4: Therefore, the diagram represents electron involvement in bonding.","steps":["Step 1: Identify the outer electrons of the atoms.","Step 2: Show which electrons are contributed by each atom.","Step 3: Show shared electron pairs between bonded atoms.","Step 4: Therefore, the diagram represents electron involvement in bonding."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 0),
  (1821, 462, 'How many electrons are present in the shared pair of a single covalent bond?', 'text', 1, 'Focus on the core principle of Dot-and-Cross Diagrams.', '{"why":"A shared electron pair contains two electrons.","sol":"Step 1: A covalent bond is formed by sharing electrons.\nStep 2: A single bond contains one shared pair.\nStep 3: One pair contains two electrons.","steps":["Step 1: A covalent bond is formed by sharing electrons.","Step 2: A single bond contains one shared pair.","Step 3: One pair contains two electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 1),
  (1822, 462, 'How many electrons are shared in a double covalent bond?', 'text', 1, 'Focus on the core principle of Dot-and-Cross Diagrams.', '{"why":"Two shared pairs contain four electrons altogether.","sol":"Step 1: A double bond contains two shared pairs.\nStep 2: Each pair contains two electrons.\nStep 3: 2 × 2 = 4 electrons.","steps":["Step 1: A double bond contains two shared pairs.","Step 2: Each pair contains two electrons.","Step 3: 2 × 2 = 4 electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 2),
  (1823, 462, 'How many electrons are shared in a triple covalent bond?', 'text', 1, 'A triple bond contains three shared pairs.', '{"why":"Three shared electron pairs contain six electrons.","sol":"Step 1: A triple bond has three shared pairs.\nStep 2: Each pair contains two electrons.\nStep 3: 3 × 2 = 6 electrons.","steps":["Step 1: A triple bond has three shared pairs.","Step 2: Each pair contains two electrons.","Step 3: 3 × 2 = 6 electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_dot_and_cross_diagrams","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Dot-and-Cross Diagrams"}', 3),
  (1824, 463, 'Why do many simple covalent substances have low melting points?', 'text', 1, 'Focus on the core principle of Properties of Simple Covalent Substances.', '{"why":"Melting a simple molecular substance mainly involves overcoming intermolecular attractions, not breaking the covalent bonds inside the molecules.","sol":"Step 1: A simple covalent substance consists of separate molecules.\nStep 2: Strong covalent bonds hold atoms together within each molecule.\nStep 3: The forces between separate molecules are generally much weaker.\nStep 4: Less energy is therefore needed to separate the molecules.\nStep 5: Hence, many simple covalent substances have low melting points.","steps":["Step 1: A simple covalent substance consists of separate molecules.","Step 2: Strong covalent bonds hold atoms together within each molecule.","Step 3: The forces between separate molecules are generally much weaker.","Step 4: Less energy is therefore needed to separate the molecules.","Step 5: Hence, many simple covalent substances have low melting points."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 0),
  (1825, 463, 'Why do simple covalent substances generally not conduct electricity?', 'text', 1, 'Focus on the core principle of Properties of Simple Covalent Substances.', '{"why":"The electrons are involved in covalent bonds and there are generally no mobile ions.","sol":"Step 1: Electrical conduction requires mobile charged particles.\nStep 2: Simple covalent substances generally do not contain mobile ions.\nStep 3: Their electrons are held in covalent bonds rather than being freely mobile.\nStep 4: Therefore, they generally do not conduct electricity.","steps":["Step 1: Electrical conduction requires mobile charged particles.","Step 2: Simple covalent substances generally do not contain mobile ions.","Step 3: Their electrons are held in covalent bonds rather than being freely mobile.","Step 4: Therefore, they generally do not conduct electricity."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 1),
  (1826, 463, 'State two physical states in which simple covalent substances can exist.', 'text', 1, 'Focus on the core principle of Properties of Simple Covalent Substances.', '{"why":"Different molecular substances have different intermolecular forces and structures.","sol":"Step 1: Simple covalent substances are not restricted to one physical state.\nStep 2: Some exist as gases.\nStep 3: Others exist as liquids or solids.","steps":["Step 1: Simple covalent substances are not restricted to one physical state.","Step 2: Some exist as gases.","Step 3: Others exist as liquids or solids."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 2),
  (1827, 463, 'A simple molecular substance has a low boiling point and does not conduct electricity. Is this consistent with covalent bonding?', 'text', 1, 'Consider the typical properties of simple molecular substances.', '{"why":"Low boiling points and poor electrical conductivity are typical properties of many simple covalent substances.","sol":"Step 1: Simple molecular covalent substances often have relatively low boiling points.\nStep 2: They generally lack mobile ions or freely moving electrons.\nStep 3: Therefore, they generally do not conduct electricity.\nStep 4: Both observations are consistent with a simple covalent substance.","steps":["Step 1: Simple molecular covalent substances often have relatively low boiling points.","Step 2: They generally lack mobile ions or freely moving electrons.","Step 3: Therefore, they generally do not conduct electricity.","Step 4: Both observations are consistent with a simple covalent substance."],"options":[],"conceptId":"chemistry_chemical_bonding_properties_of_simple_covalent_substances","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Properties of Simple Covalent Substances"}', 3),
  (1828, 464, 'What is a giant covalent structure?', 'text', 1, 'Focus on the core principle of Giant Covalent Structures.', '{"why":"The covalent bonds extend throughout the entire structure rather than forming separate small molecules.","sol":"Step 1: Identify the type of bonding.\nStep 2: Covalent bonds connect atoms throughout a continuous structure.\nStep 3: The structure contains a very large number of bonded atoms.","steps":["Step 1: Identify the type of bonding.","Step 2: Covalent bonds connect atoms throughout a continuous structure.","Step 3: The structure contains a very large number of bonded atoms."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 0),
  (1829, 464, 'Name two giant covalent substances.', 'text', 1, 'Focus on the core principle of Giant Covalent Structures.', '{"why":"Both are forms of carbon with giant covalent structures.","sol":"Step 1: Recall common examples of giant covalent structures.\nStep 2: Diamond is one example.\nStep 3: Graphite is another example.","steps":["Step 1: Recall common examples of giant covalent structures.","Step 2: Diamond is one example.","Step 3: Graphite is another example."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 1),
  (1830, 464, 'Why do giant covalent substances generally have high melting points?', 'text', 1, 'Focus on the core principle of Giant Covalent Structures.', '{"why":"Melting requires breaking many strong covalent bonds.","sol":"Step 1: Their atoms are joined by strong covalent bonds.\nStep 2: These bonds extend throughout the structure.\nStep 3: A large amount of energy is needed to break them.\nStep 4: Therefore, the substances generally have high melting points.","steps":["Step 1: Their atoms are joined by strong covalent bonds.","Step 2: These bonds extend throughout the structure.","Step 3: A large amount of energy is needed to break them.","Step 4: Therefore, the substances generally have high melting points."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 2),
  (1831, 464, 'Is diamond a simple molecular substance or a giant covalent structure?', 'text', 1, 'Think about whether its carbon atoms form separate molecules.', '{"why":"Diamond has a continuous network of covalently bonded carbon atoms.","sol":"Step 1: Diamond contains carbon atoms joined by covalent bonds.\nStep 2: The bonds form a continuous structure rather than separate molecules.\nStep 3: Therefore, diamond is a giant covalent structure.","steps":["Step 1: Diamond contains carbon atoms joined by covalent bonds.","Step 2: The bonds form a continuous structure rather than separate molecules.","Step 3: Therefore, diamond is a giant covalent structure."],"options":[],"conceptId":"chemistry_chemical_bonding_giant_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Giant Covalent Structures"}', 3),
  (1832, 465, 'How many carbon atoms is each carbon atom bonded to in diamond?', 'text', 1, 'Focus on the core principle of Diamond.', '{"why":"Each carbon atom in diamond forms four covalent bonds.","sol":"Step 1: Diamond has a three-dimensional giant covalent structure.\nStep 2: Each carbon atom forms four covalent bonds.\nStep 3: Therefore, each carbon atom is bonded to four other carbon atoms.","steps":["Step 1: Diamond has a three-dimensional giant covalent structure.","Step 2: Each carbon atom forms four covalent bonds.","Step 3: Therefore, each carbon atom is bonded to four other carbon atoms."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 0),
  (1833, 465, 'Why is diamond very hard?', 'text', 1, 'Focus on the core principle of Diamond.', '{"why":"The continuous covalent network prevents the carbon atoms from moving easily.","sol":"Step 1: Diamond contains strong covalent bonds.\nStep 2: These bonds form a rigid three-dimensional structure.\nStep 3: The atoms cannot easily slide past one another.\nStep 4: Therefore, diamond is very hard.","steps":["Step 1: Diamond contains strong covalent bonds.","Step 2: These bonds form a rigid three-dimensional structure.","Step 3: The atoms cannot easily slide past one another.","Step 4: Therefore, diamond is very hard."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 1),
  (1834, 465, 'Why does diamond not conduct electricity?', 'text', 1, 'Focus on the core principle of Diamond.', '{"why":"The outer electrons are held in covalent bonds.","sol":"Step 1: Carbon atoms in diamond use their outer electrons in covalent bonds.\nStep 2: There are no freely mobile electrons.\nStep 3: There are also no mobile ions.\nStep 4: Therefore, diamond does not conduct electricity.","steps":["Step 1: Carbon atoms in diamond use their outer electrons in covalent bonds.","Step 2: There are no freely mobile electrons.","Step 3: There are also no mobile ions.","Step 4: Therefore, diamond does not conduct electricity."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 2),
  (1835, 465, 'State one important property of diamond that makes it useful for cutting hard materials.', 'text', 1, 'Think about its resistance to scratching.', '{"why":"Its rigid giant covalent structure makes it resistant to scratching and wear.","sol":"Step 1: Diamond has a rigid giant covalent structure.\nStep 2: Strong covalent bonds hold the carbon atoms together.\nStep 3: Therefore, diamond is extremely hard.","steps":["Step 1: Diamond has a rigid giant covalent structure.","Step 2: Strong covalent bonds hold the carbon atoms together.","Step 3: Therefore, diamond is extremely hard."],"options":[],"conceptId":"chemistry_chemical_bonding_diamond","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Diamond"}', 3),
  (1836, 466, 'How many carbon atoms is each carbon atom bonded to in graphite?', 'text', 1, 'Focus on the core principle of Graphite.', '{"why":"Each carbon atom in graphite forms three covalent bonds.","sol":"Step 1: Graphite has layers of carbon atoms.\nStep 2: Each carbon atom forms three covalent bonds.\nStep 3: Therefore, each carbon atom is bonded to three other carbon atoms.","steps":["Step 1: Graphite has layers of carbon atoms.","Step 2: Each carbon atom forms three covalent bonds.","Step 3: Therefore, each carbon atom is bonded to three other carbon atoms."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 0),
  (1837, 466, 'Why does graphite conduct electricity?', 'text', 1, 'Focus on the core principle of Graphite.', '{"why":"Mobile delocalised electrons allow graphite to conduct electricity.","sol":"Step 1: Each carbon atom forms three covalent bonds.\nStep 2: One outer electron remains delocalised.\nStep 3: These electrons can move through the structure.\nStep 4: Moving electrons carry electric charge.\nStep 5: Therefore, graphite conducts electricity.","steps":["Step 1: Each carbon atom forms three covalent bonds.","Step 2: One outer electron remains delocalised.","Step 3: These electrons can move through the structure.","Step 4: Moving electrons carry electric charge.","Step 5: Therefore, graphite conducts electricity."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 1),
  (1838, 466, 'Why is graphite softer than diamond?', 'text', 1, 'Focus on the core principle of Graphite.', '{"why":"The layered structure allows the graphite layers to move relative to each other.","sol":"Step 1: Graphite consists of layers of carbon atoms.\nStep 2: Strong covalent bonds hold atoms within each layer.\nStep 3: The forces between layers are relatively weak.\nStep 4: The layers can slide over one another.\nStep 5: Therefore, graphite is relatively soft.","steps":["Step 1: Graphite consists of layers of carbon atoms.","Step 2: Strong covalent bonds hold atoms within each layer.","Step 3: The forces between layers are relatively weak.","Step 4: The layers can slide over one another.","Step 5: Therefore, graphite is relatively soft."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 2),
  (1839, 466, 'Which form of carbon conducts electricity: diamond or graphite?', 'text', 1, 'Look for the form with mobile electrons.', '{"why":"Graphite contains delocalised electrons that can carry electric charge.","sol":"Step 1: Diamond has no freely mobile electrons.\nStep 2: Graphite has delocalised electrons.\nStep 3: Therefore, graphite conducts electricity.","steps":["Step 1: Diamond has no freely mobile electrons.","Step 2: Graphite has delocalised electrons.","Step 3: Therefore, graphite conducts electricity."],"options":[],"conceptId":"chemistry_chemical_bonding_graphite","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Graphite"}', 3),
  (1840, 467, 'What is the main structural difference between an ionic compound and a simple covalent substance?', 'text', 1, 'Focus on the core principle of Ionic and Covalent Structures.', '{"why":"Different structures produce different physical properties.","sol":"Step 1: Ionic compounds contain positive and negative ions arranged in a lattice.\nStep 2: Simple covalent substances contain separate molecules.\nStep 3: Therefore, their particles are arranged differently.","steps":["Step 1: Ionic compounds contain positive and negative ions arranged in a lattice.","Step 2: Simple covalent substances contain separate molecules.","Step 3: Therefore, their particles are arranged differently."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 0),
  (1841, 467, 'Why can molten ionic compounds conduct electricity but simple covalent substances generally cannot?', 'text', 1, 'Focus on the core principle of Ionic and Covalent Structures.', '{"why":"Electrical conduction requires mobile charged particles.","sol":"Step 1: Molten ionic compounds contain mobile charged ions.\nStep 2: Moving ions carry electric charge.\nStep 3: Simple covalent substances generally contain no mobile ions.\nStep 4: Their electrons are not freely mobile.\nStep 5: Therefore, molten ionic compounds conduct while simple covalent substances generally do not.","steps":["Step 1: Molten ionic compounds contain mobile charged ions.","Step 2: Moving ions carry electric charge.","Step 3: Simple covalent substances generally contain no mobile ions.","Step 4: Their electrons are not freely mobile.","Step 5: Therefore, molten ionic compounds conduct while simple covalent substances generally do not."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 1),
  (1842, 467, 'Why do giant covalent substances generally have high melting points?', 'text', 1, 'Focus on the core principle of Ionic and Covalent Structures.', '{"why":"The continuous covalent network makes melting energetically difficult.","sol":"Step 1: Their atoms are joined by strong covalent bonds throughout the structure.\nStep 2: Many strong bonds must be broken to melt the substance.\nStep 3: This requires a large amount of energy.","steps":["Step 1: Their atoms are joined by strong covalent bonds throughout the structure.","Step 2: Many strong bonds must be broken to melt the substance.","Step 3: This requires a large amount of energy."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 2),
  (1843, 467, 'A substance has a giant lattice of positive and negative ions. What type of bonding does it contain?', 'text', 1, 'Think about attraction between oppositely charged particles.', '{"why":"Ionic structures consist of oppositely charged ions held by electrostatic attraction.","sol":"Step 1: The particles are positive and negative ions.\nStep 2: Oppositely charged ions attract each other.\nStep 3: This attraction is ionic bonding.","steps":["Step 1: The particles are positive and negative ions.","Step 2: Oppositely charged ions attract each other.","Step 3: This attraction is ionic bonding."],"options":[],"conceptId":"chemistry_chemical_bonding_ionic_and_covalent_structures","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Ionic and Covalent Structures"}', 3),
  (1844, 468, 'What is metallic bonding?', 'text', 1, 'Focus on the core principle of Metallic Bonding.', '{"why":"The attraction between the positive ions and delocalised electrons holds the metal structure together.","sol":"Step 1: Identify the particles present in a metal.\nStep 2: Metals contain positive metal ions and delocalised electrons.\nStep 3: Metallic bonding is the electrostatic attraction between these opposite charges.","steps":["Step 1: Identify the particles present in a metal.","Step 2: Metals contain positive metal ions and delocalised electrons.","Step 3: Metallic bonding is the electrostatic attraction between these opposite charges."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 0),
  (1845, 468, 'What happens to the outer electrons of metal atoms in metallic bonding?', 'text', 1, 'Focus on the core principle of Metallic Bonding.', '{"why":"Delocalisation allows the outer electrons to move through the metal rather than remaining attached to individual atoms.","sol":"Step 1: Consider the outer electrons of metal atoms.\nStep 2: These electrons are not restricted to one metal atom.\nStep 3: They become delocalised throughout the metal structure.","steps":["Step 1: Consider the outer electrons of metal atoms.","Step 2: These electrons are not restricted to one metal atom.","Step 3: They become delocalised throughout the metal structure."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 1),
  (1846, 468, 'What particles are attracted to each other in metallic bonding?', 'text', 1, 'Focus on the core principle of Metallic Bonding.', '{"why":"The electrostatic attraction between them produces metallic bonding.","sol":"Step 1: Identify the positive particles in the metal.\nStep 2: Identify the negatively charged electrons.\nStep 3: Opposite charges attract.","steps":["Step 1: Identify the positive particles in the metal.","Step 2: Identify the negatively charged electrons.","Step 3: Opposite charges attract."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 2),
  (1847, 468, 'A learner says metallic bonding is the attraction between metal atoms and shared electrons. Correct this statement.', 'text', 1, 'Think about the charge of the metal particles and the movement of the outer electrons.', '{"why":"The metal structure consists of positive ions surrounded by delocalised electrons.","sol":"Step 1: In metallic bonding, the metal atoms form positive ions.\nStep 2: Their outer electrons become delocalised.\nStep 3: The attraction is between the positive ions and delocalised electrons.","steps":["Step 1: In metallic bonding, the metal atoms form positive ions.","Step 2: Their outer electrons become delocalised.","Step 3: The attraction is between the positive ions and delocalised electrons."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding"}', 3),
  (1848, 469, 'What are delocalised electrons?', 'text', 1, 'Focus on the core principle of Delocalised Electrons in Metals.', '{"why":"Their freedom of movement is a key feature of metallic bonding.","sol":"Step 1: Consider electrons in a metal.\nStep 2: They are not confined to one metal atom.\nStep 3: They can move throughout the metal structure.","steps":["Step 1: Consider electrons in a metal.","Step 2: They are not confined to one metal atom.","Step 3: They can move throughout the metal structure."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 0),
  (1849, 469, 'Which particles remain in fixed positions in a metallic structure?', 'text', 1, 'Focus on the core principle of Delocalised Electrons in Metals.', '{"why":"The positive ions form the fixed arrangement while the delocalised electrons move through it.","sol":"Step 1: Identify the particles forming the regular structure.\nStep 2: These particles are positive metal ions.\nStep 3: The electrons are the particles that move through the structure.","steps":["Step 1: Identify the particles forming the regular structure.","Step 2: These particles are positive metal ions.","Step 3: The electrons are the particles that move through the structure."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 1),
  (1850, 469, 'Why can metals conduct electricity?', 'text', 1, 'Focus on the core principle of Delocalised Electrons in Metals.', '{"why":"The mobile electrons carry electrical charge through the metal.","sol":"Step 1: Electrical conduction requires charged particles that can move.\nStep 2: Metals contain delocalised electrons.\nStep 3: These electrons can move through the metal when a potential difference is applied.","steps":["Step 1: Electrical conduction requires charged particles that can move.","Step 2: Metals contain delocalised electrons.","Step 3: These electrons can move through the metal when a potential difference is applied."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 2),
  (1851, 469, 'A metal contains positive ions but no mobile electrons. Would the metallic bonding model explain good electrical conductivity?', 'text', 1, 'Ask which particle carries electrical charge through a metal.', '{"why":"The fixed positive ions cannot move through the metal to carry electrical charge.","sol":"Step 1: Electrical conduction requires mobile charged particles.\nStep 2: The positive metal ions are fixed in the structure.\nStep 3: Delocalised electrons provide the mobile charged particles.","steps":["Step 1: Electrical conduction requires mobile charged particles.","Step 2: The positive metal ions are fixed in the structure.","Step 3: Delocalised electrons provide the mobile charged particles."],"options":[],"conceptId":"chemistry_chemical_bonding_delocalised_electrons_in_metals","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Delocalised Electrons in Metals"}', 3),
  (1852, 470, 'Why do metals conduct electricity?', 'text', 1, 'Focus on the core principle of Metallic Bonding and Metal Properties.', '{"why":"The mobile electrons carry electrical charge.","sol":"Step 1: Electrical conduction requires mobile charged particles.\nStep 2: Metals contain delocalised electrons.\nStep 3: These electrons can move through the metal.","steps":["Step 1: Electrical conduction requires mobile charged particles.","Step 2: Metals contain delocalised electrons.","Step 3: These electrons can move through the metal."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q1","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 0),
  (1853, 470, 'Why are metals malleable?', 'text', 1, 'Focus on the core principle of Metallic Bonding and Metal Properties.', '{"why":"The delocalised electrons continue to attract the positive ions even when the layers shift.","sol":"Step 1: Consider what happens when a force is applied to the metal.\nStep 2: Layers of metal ions can slide past one another.\nStep 3: The delocalised electrons continue to hold the ions together.","steps":["Step 1: Consider what happens when a force is applied to the metal.","Step 2: Layers of metal ions can slide past one another.","Step 3: The delocalised electrons continue to hold the ions together."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q2","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 1),
  (1854, 470, 'Why do many metals have high melting points?', 'text', 1, 'Focus on the core principle of Metallic Bonding and Metal Properties.', '{"why":"The strong attraction between positive metal ions and delocalised electrons holds the structure together.","sol":"Step 1: Identify the force holding the metal structure together.\nStep 2: Metallic bonding involves strong electrostatic attraction.\nStep 3: A large amount of energy is required to overcome this attraction.","steps":["Step 1: Identify the force holding the metal structure together.","Step 2: Metallic bonding involves strong electrostatic attraction.","Step 3: A large amount of energy is required to overcome this attraction."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q3","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 2),
  (1855, 470, 'A student says metals are malleable because their atoms are weakly bonded. What is the better explanation?', 'text', 1, 'Think about what happens to the layers of metal ions when a force is applied.', '{"why":"Malleability is caused by the structure of metallic bonding, not simply by weak bonding.","sol":"Step 1: Metallic bonding is strong.\nStep 2: Layers of metal ions can nevertheless slide past one another.\nStep 3: Delocalised electrons maintain attraction between the shifted layers.","steps":["Step 1: Metallic bonding is strong.","Step 2: Layers of metal ions can nevertheless slide past one another.","Step 3: Delocalised electrons maintain attraction between the shifted layers."],"options":[],"conceptId":"chemistry_chemical_bonding_metallic_bonding_and_metal_properties","skillId":"chemistry_chemical_bonding","subskillId":"chemistry_chemical_bonding_q4","subject":"chemistry","chapter":"chemical_bonding","topic":"Metallic Bonding and Metal Properties"}', 3),
  (1856, 471, 'Why is valency important when writing chemical formulae?', 'text', 1, 'Focus on the core principle of Valency and Chemical Formulae.', '{"why":"The correct ratio ensures that the combining capacities are satisfied.","sol":"Step 1: Valency indicates the combining capacity of an element.\nStep 2: The valencies of the combining elements determine their ratio.\nStep 3: The formula must represent a compound with the correct ratio of atoms or ions.","steps":["Step 1: Valency indicates the combining capacity of an element.","Step 2: The valencies of the combining elements determine their ratio.","Step 3: The formula must represent a compound with the correct ratio of atoms or ions."],"options":[],"conceptId":"chemistry_chemical_formulae_valency_and_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency and Chemical Formulae"}', 0),
  (1857, 471, 'What is the valency of magnesium?', 'text', 1, 'Focus on the core principle of Valency and Chemical Formulae.', '{"why":"Magnesium has two outer electrons and commonly has valency 2.","sol":"Step 1: Magnesium is in Group 2.\nStep 2: It commonly loses two electrons.\nStep 3: Therefore, its common valency is 2.","steps":["Step 1: Magnesium is in Group 2.","Step 2: It commonly loses two electrons.","Step 3: Therefore, its common valency is 2."],"options":[],"conceptId":"chemistry_chemical_formulae_valency_and_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency and Chemical Formulae"}', 1),
  (1858, 471, 'What is the valency of oxygen?', 'text', 1, 'Focus on the core principle of Valency and Chemical Formulae.', '{"why":"Oxygen commonly gains or shares two electrons when forming compounds.","sol":"Step 1: Oxygen has six outer electrons.\nStep 2: It needs two more electrons to complete its outer energy level.\nStep 3: Therefore, its common valency is 2.","steps":["Step 1: Oxygen has six outer electrons.","Step 2: It needs two more electrons to complete its outer energy level.","Step 3: Therefore, its common valency is 2."],"options":[],"conceptId":"chemistry_chemical_formulae_valency_and_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency and Chemical Formulae"}', 2),
  (1859, 471, 'A metal has valency 2 and chlorine has valency 1. What ratio of metal atoms to chlorine atoms is required?', 'text', 1, 'The two chlorine atoms provide a total valency of 2.', '{"why":"Two chlorine atoms are required to balance the valency of one divalent metal atom.","sol":"Step 1: The metal has valency 2.\nStep 2: Each chlorine atom has valency 1.\nStep 3: Two chlorine atoms provide a total valency of 2.\nStep 4: Therefore, the ratio is 1 metal atom : 2 chlorine atoms.","steps":["Step 1: The metal has valency 2.","Step 2: Each chlorine atom has valency 1.","Step 3: Two chlorine atoms provide a total valency of 2.","Step 4: Therefore, the ratio is 1 metal atom : 2 chlorine atoms."],"options":[],"conceptId":"chemistry_chemical_formulae_valency_and_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Valency and Chemical Formulae"}', 3),
  (1860, 472, 'Write the formula of magnesium chloride. Magnesium has valency 2 and chlorine has valency 1.', 'text', 1, 'Focus on the core principle of Writing Chemical Formulae.', '{"why":"One Mg atom combines with two Cl atoms to balance the valencies.","sol":"Step 1: Write the symbols: Mg and Cl.\nStep 2: Magnesium has valency 2.\nStep 3: Chlorine has valency 1.\nStep 4: One Mg atom gives a combining capacity of 2.\nStep 5: Two Cl atoms give a combining capacity of 2.\nStep 6: Therefore, the formula is MgCl₂.","steps":["Step 1: Write the symbols: Mg and Cl.","Step 2: Magnesium has valency 2.","Step 3: Chlorine has valency 1.","Step 4: One Mg atom gives a combining capacity of 2.","Step 5: Two Cl atoms give a combining capacity of 2.","Step 6: Therefore, the formula is MgCl₂."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 0),
  (1861, 472, 'Write the formula of aluminium oxide. Aluminium has valency 3 and oxygen has valency 2.', 'text', 1, 'Focus on the core principle of Writing Chemical Formulae.', '{"why":"Two Al atoms and three O atoms give equal total combining capacities.","sol":"Step 1: Write Al and O.\nStep 2: Al has valency 3 and O has valency 2.\nStep 3: The lowest common total is 6.\nStep 4: Two Al atoms give 2 × 3 = 6.\nStep 5: Three O atoms give 3 × 2 = 6.\nStep 6: Therefore, the formula is Al₂O₃.","steps":["Step 1: Write Al and O.","Step 2: Al has valency 3 and O has valency 2.","Step 3: The lowest common total is 6.","Step 4: Two Al atoms give 2 × 3 = 6.","Step 5: Three O atoms give 3 × 2 = 6.","Step 6: Therefore, the formula is Al₂O₃."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 1),
  (1862, 472, 'Write the formula of calcium oxide. Calcium has valency 2 and oxygen has valency 2.', 'text', 1, 'Focus on the core principle of Writing Chemical Formulae.', '{"why":"The two valencies are equal, so one calcium atom combines with one oxygen atom.","sol":"Step 1: Write Ca and O.\nStep 2: Calcium has valency 2.\nStep 3: Oxygen has valency 2.\nStep 4: One Ca atom gives 2.\nStep 5: One O atom gives 2.\nStep 6: Therefore, the simplest formula is CaO.","steps":["Step 1: Write Ca and O.","Step 2: Calcium has valency 2.","Step 3: Oxygen has valency 2.","Step 4: One Ca atom gives 2.","Step 5: One O atom gives 2.","Step 6: Therefore, the simplest formula is CaO."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 2),
  (1863, 472, 'Write the formula of sodium oxide. Sodium has valency 1 and oxygen has valency 2.', 'text', 1, 'Two sodium atoms are needed to balance one oxygen atom.', '{"why":"Two sodium atoms balance the valency of one oxygen atom.","sol":"Step 1: Sodium has valency 1.\nStep 2: Oxygen has valency 2.\nStep 3: Two Na atoms give a total valency of 2.\nStep 4: One O atom gives a total valency of 2.\nStep 5: Therefore, the formula is Na₂O.","steps":["Step 1: Sodium has valency 1.","Step 2: Oxygen has valency 2.","Step 3: Two Na atoms give a total valency of 2.","Step 4: One O atom gives a total valency of 2.","Step 5: Therefore, the formula is Na₂O."],"options":[],"conceptId":"chemistry_chemical_formulae_writing_chemical_formulae","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Writing Chemical Formulae"}', 3),
  (1864, 473, 'Write the formula of calcium chloride using Ca²⁺ and Cl⁻.', 'text', 1, 'Focus on the core principle of Formulae of Ionic Compounds.', '{"why":"Two chloride ions are needed to balance one calcium ion.","sol":"Step 1: Ca²⁺ has charge +2.\nStep 2: Cl⁻ has charge −1.\nStep 3: Two Cl⁻ ions give −2.\nStep 4: +2 + (−2) = 0.\nStep 5: Therefore, the formula is CaCl₂.","steps":["Step 1: Ca²⁺ has charge +2.","Step 2: Cl⁻ has charge −1.","Step 3: Two Cl⁻ ions give −2.","Step 4: +2 + (−2) = 0.","Step 5: Therefore, the formula is CaCl₂."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 0),
  (1865, 473, 'Write the formula of magnesium oxide using Mg²⁺ and O²⁻.', 'text', 1, 'Focus on the core principle of Formulae of Ionic Compounds.', '{"why":"The +2 and −2 charges balance in a 1:1 ratio.","sol":"Step 1: Mg²⁺ has charge +2.\nStep 2: O²⁻ has charge −2.\nStep 3: One Mg²⁺ balances one O²⁻.\nStep 4: The total charge is zero.\nStep 5: Therefore, the formula is MgO.","steps":["Step 1: Mg²⁺ has charge +2.","Step 2: O²⁻ has charge −2.","Step 3: One Mg²⁺ balances one O²⁻.","Step 4: The total charge is zero.","Step 5: Therefore, the formula is MgO."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 1),
  (1866, 473, 'Write the formula of aluminium oxide using Al³⁺ and O²⁻.', 'text', 1, 'Focus on the core principle of Formulae of Ionic Compounds.', '{"why":"Two aluminium ions and three oxide ions produce a neutral compound.","sol":"Step 1: Al³⁺ has charge +3.\nStep 2: O²⁻ has charge −2.\nStep 3: Two Al³⁺ ions give +6.\nStep 4: Three O²⁻ ions give −6.\nStep 5: +6 + (−6) = 0.\nStep 6: Therefore, the formula is Al₂O₃.","steps":["Step 1: Al³⁺ has charge +3.","Step 2: O²⁻ has charge −2.","Step 3: Two Al³⁺ ions give +6.","Step 4: Three O²⁻ ions give −6.","Step 5: +6 + (−6) = 0.","Step 6: Therefore, the formula is Al₂O₃."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 2),
  (1867, 473, 'Write the formula of aluminium chloride using Al³⁺ and Cl⁻.', 'text', 1, 'Find the smallest number of chloride ions needed to balance +3.', '{"why":"Three chloride ions balance the +3 charge of one aluminium ion.","sol":"Step 1: Al³⁺ contributes +3.\nStep 2: Each Cl⁻ contributes −1.\nStep 3: Three Cl⁻ ions contribute −3.\nStep 4: The total charge becomes zero.\nStep 5: Therefore, the formula is AlCl₃.","steps":["Step 1: Al³⁺ contributes +3.","Step 2: Each Cl⁻ contributes −1.","Step 3: Three Cl⁻ ions contribute −3.","Step 4: The total charge becomes zero.","Step 5: Therefore, the formula is AlCl₃."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_ionic_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Ionic Compounds"}', 3),
  (1868, 474, 'What does the formula H₂O tell us about water?', 'text', 1, 'Focus on the core principle of Formulae of Covalent Compounds.', '{"why":"Subscripts show the number of atoms of each element in the formula.","sol":"Step 1: The symbol H represents hydrogen.\nStep 2: The subscript 2 means there are two hydrogen atoms.\nStep 3: O represents oxygen with no subscript.\nStep 4: No subscript means one oxygen atom.\nStep 5: Therefore, H₂O contains two hydrogen atoms and one oxygen atom.","steps":["Step 1: The symbol H represents hydrogen.","Step 2: The subscript 2 means there are two hydrogen atoms.","Step 3: O represents oxygen with no subscript.","Step 4: No subscript means one oxygen atom.","Step 5: Therefore, H₂O contains two hydrogen atoms and one oxygen atom."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 0),
  (1869, 474, 'What does the formula CO₂ tell us about carbon dioxide?', 'text', 1, 'Focus on the core principle of Formulae of Covalent Compounds.', '{"why":"The subscript 2 applies only to oxygen.","sol":"Step 1: C represents carbon.\nStep 2: There is no subscript after C, so there is one carbon atom.\nStep 3: The subscript 2 after O means two oxygen atoms.\nStep 4: Therefore, one carbon atom combines with two oxygen atoms.","steps":["Step 1: C represents carbon.","Step 2: There is no subscript after C, so there is one carbon atom.","Step 3: The subscript 2 after O means two oxygen atoms.","Step 4: Therefore, one carbon atom combines with two oxygen atoms."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 1),
  (1870, 474, 'What does the formula NH₃ tell us about ammonia?', 'text', 1, 'Focus on the core principle of Formulae of Covalent Compounds.', '{"why":"The subscript 3 applies to hydrogen only.","sol":"Step 1: N represents nitrogen.\nStep 2: There is no subscript after N, so there is one nitrogen atom.\nStep 3: The subscript 3 after H means three hydrogen atoms.\nStep 4: Therefore, NH₃ contains one nitrogen atom and three hydrogen atoms.","steps":["Step 1: N represents nitrogen.","Step 2: There is no subscript after N, so there is one nitrogen atom.","Step 3: The subscript 3 after H means three hydrogen atoms.","Step 4: Therefore, NH₃ contains one nitrogen atom and three hydrogen atoms."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 2),
  (1871, 474, 'How many atoms are present in one molecule of CO₂?', 'text', 1, 'Count the carbon atom and the two oxygen atoms.', '{"why":"One carbon atom plus two oxygen atoms gives three atoms.","sol":"Step 1: CO₂ contains one carbon atom.\nStep 2: It contains two oxygen atoms.\nStep 3: Total atoms = 1 + 2.\nStep 4: Total atoms = 3.","steps":["Step 1: CO₂ contains one carbon atom.","Step 2: It contains two oxygen atoms.","Step 3: Total atoms = 1 + 2.","Step 4: Total atoms = 3."],"options":[],"conceptId":"chemistry_chemical_formulae_formulae_of_covalent_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Formulae of Covalent Compounds"}', 3),
  (1872, 475, 'Name NaCl.', 'text', 1, 'Focus on the core principle of Naming Compounds.', '{"why":"Ionic compounds are named by stating the positive ion followed by the negative ion.","sol":"Step 1: Na is sodium.\nStep 2: Cl forms chloride in the compound name.\nStep 3: Name the positive ion first.\nStep 4: Therefore, NaCl is sodium chloride.","steps":["Step 1: Na is sodium.","Step 2: Cl forms chloride in the compound name.","Step 3: Name the positive ion first.","Step 4: Therefore, NaCl is sodium chloride."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Compounds"}', 0),
  (1873, 475, 'Name MgO.', 'text', 1, 'Focus on the core principle of Naming Compounds.', '{"why":"The metal is named first and oxygen becomes oxide.","sol":"Step 1: Mg is magnesium.\nStep 2: O forms oxide in the compound name.\nStep 3: Combine the names.\nStep 4: MgO is magnesium oxide.","steps":["Step 1: Mg is magnesium.","Step 2: O forms oxide in the compound name.","Step 3: Combine the names.","Step 4: MgO is magnesium oxide."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Compounds"}', 1),
  (1874, 475, 'Name CO₂.', 'text', 1, 'Focus on the core principle of Naming Compounds.', '{"why":"The prefix di- indicates two oxygen atoms.","sol":"Step 1: C is carbon.\nStep 2: There is one carbon atom, so mono- is normally omitted for the first element.\nStep 3: There are two oxygen atoms, so use di-.\nStep 4: Oxygen becomes oxide.\nStep 5: Therefore, CO₂ is carbon dioxide.","steps":["Step 1: C is carbon.","Step 2: There is one carbon atom, so mono- is normally omitted for the first element.","Step 3: There are two oxygen atoms, so use di-.","Step 4: Oxygen becomes oxide.","Step 5: Therefore, CO₂ is carbon dioxide."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Compounds"}', 2),
  (1875, 475, 'Name CaCl₂.', 'text', 1, 'Identify calcium and the chloride ion.', '{"why":"The compound contains calcium ions and chloride ions.","sol":"Step 1: Ca is calcium.\nStep 2: Cl is named chloride in the compound.\nStep 3: Therefore, CaCl₂ is calcium chloride.","steps":["Step 1: Ca is calcium.","Step 2: Cl is named chloride in the compound.","Step 3: Therefore, CaCl₂ is calcium chloride."],"options":[],"conceptId":"chemistry_chemical_formulae_naming_compounds","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"Naming Compounds"}', 3),
  (1876, 476, 'What does (s) mean in a chemical equation?', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"(s) indicates that the substance is in the solid state.","sol":"Step 1: Identify the state symbol.\nStep 2: The symbol (s) represents a solid.","steps":["Step 1: Identify the state symbol.","Step 2: The symbol (s) represents a solid."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q1","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 0),
  (1877, 476, 'What does (aq) mean in a chemical equation?', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"(aq) tells us that the substance is present as a solution in water.","sol":"Step 1: The letters aq stand for aqueous.\nStep 2: Aqueous means the substance is dissolved in water.","steps":["Step 1: The letters aq stand for aqueous.","Step 2: Aqueous means the substance is dissolved in water."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q2","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 1),
  (1878, 476, 'State the meaning of each symbol: (s), (l), (g) and (aq).', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"These four symbols identify the physical state or solution state of substances in chemical equations.","sol":"Step 1: (s) means solid.\nStep 2: (l) means liquid.\nStep 3: (g) means gas.\nStep 4: (aq) means aqueous, or dissolved in water.","steps":["Step 1: (s) means solid.","Step 2: (l) means liquid.","Step 3: (g) means gas.","Step 4: (aq) means aqueous, or dissolved in water."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q3","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 2),
  (1879, 476, 'What state symbol should be used for carbon dioxide gas?', 'text', 1, 'Carbon dioxide is gaseous under ordinary conditions.', '{"why":"(g) represents the gaseous state.","sol":"Step 1: Carbon dioxide is a gas.\nStep 2: The state symbol for a gas is (g).\nStep 3: Therefore, carbon dioxide is written as CO₂(g).","steps":["Step 1: Carbon dioxide is a gas.","Step 2: The state symbol for a gas is (g).","Step 3: Therefore, carbon dioxide is written as CO₂(g)."],"options":[],"conceptId":"chemistry_chemical_formulae_state_symbols","skillId":"chemistry_chemical_formulae","subskillId":"chemistry_chemical_formulae_q4","subject":"chemistry","chapter":"chemical_formulae","topic":"State Symbols"}', 3),
  (1880, 477, 'What is a mole?', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"The mole provides a convenient way of counting extremely large numbers of particles.","sol":"Step 1: A mole is a unit for measuring amount of substance.\nStep 2: One mole contains 6.02 × 10²³ specified particles.\nStep 3: Therefore, a mole represents a fixed number of particles.","steps":["Step 1: A mole is a unit for measuring amount of substance.","Step 2: One mole contains 6.02 × 10²³ specified particles.","Step 3: Therefore, a mole represents a fixed number of particles."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 0),
  (1881, 477, 'How many particles are present in one mole of a substance?', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"This is the number of particles defined as one mole.","sol":"Step 1: Recall the Avogadro constant.\nStep 2: One mole contains 6.02 × 10²³ particles.","steps":["Step 1: Recall the Avogadro constant.","Step 2: One mole contains 6.02 × 10²³ particles."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 1),
  (1882, 477, 'How many molecules are present in 1 mole of water?', 'text', 1, 'Focus on the core principle of Meaning of Mole.', '{"why":"The particles being counted are molecules of water.","sol":"Step 1: One mole always contains 6.02 × 10²³ specified particles.\nStep 2: For water, the particles are water molecules.\nStep 3: Therefore, 1 mole of water contains 6.02 × 10²³ molecules.","steps":["Step 1: One mole always contains 6.02 × 10²³ specified particles.","Step 2: For water, the particles are water molecules.","Step 3: Therefore, 1 mole of water contains 6.02 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 2),
  (1883, 477, 'How many atoms are present in 1 mole of sodium atoms?', 'text', 1, 'One mole contains the Avogadro constant number of particles.', '{"why":"One mole of any specified particles contains the Avogadro constant number of particles.","sol":"Step 1: The specified particles are sodium atoms.\nStep 2: One mole contains 6.02 × 10²³ particles.\nStep 3: Therefore, there are 6.02 × 10²³ sodium atoms.","steps":["Step 1: The specified particles are sodium atoms.","Step 2: One mole contains 6.02 × 10²³ particles.","Step 3: Therefore, there are 6.02 × 10²³ sodium atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_meaning_of_mole","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Meaning of Mole"}', 3),
  (1884, 478, 'Calculate the number of particles in 2 moles of a substance.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"The number of particles is proportional to the number of moles.","sol":"Step 1: Use N = nNₐ.\nStep 2: n = 2 mol.\nStep 3: Nₐ = 6.02 × 10²³ mol⁻¹.\nStep 4: N = 2 × 6.02 × 10²³.\nStep 5: N = 12.04 × 10²³.\nStep 6: N = 1.204 × 10²⁴ particles.","steps":["Step 1: Use N = nNₐ.","Step 2: n = 2 mol.","Step 3: Nₐ = 6.02 × 10²³ mol⁻¹.","Step 4: N = 2 × 6.02 × 10²³.","Step 5: N = 12.04 × 10²³.","Step 6: N = 1.204 × 10²⁴ particles."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 0),
  (1885, 478, 'Calculate the number of particles in 0.5 mol of a substance.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"Half a mole contains half of the Avogadro constant number of particles.","sol":"Step 1: Use N = nNₐ.\nStep 2: n = 0.5 mol.\nStep 3: N = 0.5 × 6.02 × 10²³.\nStep 4: N = 3.01 × 10²³ particles.","steps":["Step 1: Use N = nNₐ.","Step 2: n = 0.5 mol.","Step 3: N = 0.5 × 6.02 × 10²³.","Step 4: N = 3.01 × 10²³ particles."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 1),
  (1886, 478, 'Calculate the number of moles in 3.01 × 10²³ particles.', 'text', 1, 'Focus on the core principle of Avogadro Constant.', '{"why":"3.01 × 10²³ particles is half of 6.02 × 10²³ particles.","sol":"Step 1: Use n = N ÷ Nₐ.\nStep 2: N = 3.01 × 10²³.\nStep 3: Nₐ = 6.02 × 10²³.\nStep 4: n = (3.01 × 10²³) ÷ (6.02 × 10²³).\nStep 5: n = 0.5 mol.","steps":["Step 1: Use n = N ÷ Nₐ.","Step 2: N = 3.01 × 10²³.","Step 3: Nₐ = 6.02 × 10²³.","Step 4: n = (3.01 × 10²³) ÷ (6.02 × 10²³).","Step 5: n = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 2),
  (1887, 478, 'How many molecules are present in 0.25 mol of water?', 'text', 1, 'Use N = nNₐ.', '{"why":"The number of molecules equals the number of moles multiplied by the Avogadro constant.","sol":"Step 1: N = nNₐ.\nStep 2: N = 0.25 × 6.02 × 10²³.\nStep 3: N = 1.505 × 10²³ molecules.","steps":["Step 1: N = nNₐ.","Step 2: N = 0.25 × 6.02 × 10²³.","Step 3: N = 1.505 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_avogadro_constant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Avogadro Constant"}', 3),
  (1888, 479, 'What is meant by relative atomic mass?', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"Relative atomic mass allows the masses of atoms to be compared.","sol":"Step 1: Atomic masses are compared using a standard reference.\nStep 2: The resulting value is called relative atomic mass.\nStep 3: It is represented by Aᵣ.","steps":["Step 1: Atomic masses are compared using a standard reference.","Step 2: The resulting value is called relative atomic mass.","Step 3: It is represented by Aᵣ."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 0),
  (1889, 479, 'State the relative atomic mass of oxygen.', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"Oxygen has a commonly used relative atomic mass of 16.","sol":"Step 1: Locate oxygen in the periodic table.\nStep 2: Its commonly used relative atomic mass is 16.","steps":["Step 1: Locate oxygen in the periodic table.","Step 2: Its commonly used relative atomic mass is 16."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 1),
  (1890, 479, 'State the relative atomic mass of chlorine used in calculations.', 'text', 1, 'Focus on the core principle of Relative Atomic Mass.', '{"why":"Chlorine has a relative atomic mass of approximately 35.5.","sol":"Step 1: Locate chlorine in the periodic table.\nStep 2: The commonly used value is 35.5.","steps":["Step 1: Locate chlorine in the periodic table.","Step 2: The commonly used value is 35.5."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 2),
  (1891, 479, 'What relative atomic mass would you use for sodium in a basic mole calculation?', 'text', 1, 'Use the standard periodic-table value.', '{"why":"The commonly used relative atomic mass of sodium is 23.","sol":"Step 1: Locate sodium.\nStep 2: Sodium has relative atomic mass 23.","steps":["Step 1: Locate sodium.","Step 2: Sodium has relative atomic mass 23."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_atomic_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Atomic Mass"}', 3),
  (1892, 480, 'Calculate the relative formula mass of H₂O.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"The formula mass is found by adding the masses of all atoms in the formula.","sol":"Step 1: H has Aᵣ = 1.\nStep 2: O has Aᵣ = 16.\nStep 3: There are two H atoms.\nStep 4: Mᵣ = (2 × 1) + 16.\nStep 5: Mᵣ = 18.","steps":["Step 1: H has Aᵣ = 1.","Step 2: O has Aᵣ = 16.","Step 3: There are two H atoms.","Step 4: Mᵣ = (2 × 1) + 16.","Step 5: Mᵣ = 18."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 0),
  (1893, 480, 'Calculate the relative formula mass of CO₂.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"One carbon atom contributes 12 and two oxygen atoms contribute 32.","sol":"Step 1: C has Aᵣ = 12.\nStep 2: O has Aᵣ = 16.\nStep 3: There are two O atoms.\nStep 4: Mᵣ = 12 + (2 × 16).\nStep 5: Mᵣ = 44.","steps":["Step 1: C has Aᵣ = 12.","Step 2: O has Aᵣ = 16.","Step 3: There are two O atoms.","Step 4: Mᵣ = 12 + (2 × 16).","Step 5: Mᵣ = 44."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 1),
  (1894, 480, 'Calculate the relative formula mass of CaCl₂.', 'text', 1, 'Focus on the core principle of Relative Formula Mass.', '{"why":"The formula contains one calcium atom and two chlorine atoms.","sol":"Step 1: Ca has Aᵣ = 40.\nStep 2: Cl has Aᵣ = 35.5.\nStep 3: There are two Cl atoms.\nStep 4: Mᵣ = 40 + (2 × 35.5).\nStep 5: Mᵣ = 40 + 71.\nStep 6: Mᵣ = 111.","steps":["Step 1: Ca has Aᵣ = 40.","Step 2: Cl has Aᵣ = 35.5.","Step 3: There are two Cl atoms.","Step 4: Mᵣ = 40 + (2 × 35.5).","Step 5: Mᵣ = 40 + 71.","Step 6: Mᵣ = 111."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 2),
  (1895, 480, 'Calculate the relative formula mass of MgO. Mg = 24 and O = 16.', 'text', 1, 'Add the relative atomic masses of Mg and O.', '{"why":"MgO contains one magnesium atom and one oxygen atom.","sol":"Step 1: Mg = 24.\nStep 2: O = 16.\nStep 3: Mᵣ = 24 + 16.\nStep 4: Mᵣ = 40.","steps":["Step 1: Mg = 24.","Step 2: O = 16.","Step 3: Mᵣ = 24 + 16.","Step 4: Mᵣ = 40."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_relative_formula_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Relative Formula Mass"}', 3),
  (1896, 481, 'What is the molar mass of water, H₂O?', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"One mole of water has a mass of 18 grams.","sol":"Step 1: Calculate Mᵣ of H₂O.\nStep 2: Mᵣ = (2 × 1) + 16 = 18.\nStep 3: Therefore, molar mass = 18 g mol⁻¹.","steps":["Step 1: Calculate Mᵣ of H₂O.","Step 2: Mᵣ = (2 × 1) + 16 = 18.","Step 3: Therefore, molar mass = 18 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 0),
  (1897, 481, 'What is the molar mass of carbon dioxide, CO₂?', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"One mole of carbon dioxide has a mass of 44 grams.","sol":"Step 1: Calculate Mᵣ.\nStep 2: Mᵣ = 12 + (2 × 16).\nStep 3: Mᵣ = 44.\nStep 4: Therefore, molar mass = 44 g mol⁻¹.","steps":["Step 1: Calculate Mᵣ.","Step 2: Mᵣ = 12 + (2 × 16).","Step 3: Mᵣ = 44.","Step 4: Therefore, molar mass = 44 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 1),
  (1898, 481, 'What is the molar mass of calcium carbonate, CaCO₃? Ca = 40, C = 12, O = 16.', 'text', 1, 'Focus on the core principle of Molar Mass.', '{"why":"The formula contains one Ca, one C and three O atoms.","sol":"Step 1: Ca = 40.\nStep 2: C = 12.\nStep 3: Three O atoms contribute 3 × 16 = 48.\nStep 4: Mᵣ = 40 + 12 + 48.\nStep 5: Mᵣ = 100.\nStep 6: Molar mass = 100 g mol⁻¹.","steps":["Step 1: Ca = 40.","Step 2: C = 12.","Step 3: Three O atoms contribute 3 × 16 = 48.","Step 4: Mᵣ = 40 + 12 + 48.","Step 5: Mᵣ = 100.","Step 6: Molar mass = 100 g mol⁻¹."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 2),
  (1899, 481, 'What is the unit of molar mass?', 'text', 1, 'Molar mass is mass per mole.', '{"why":"Molar mass expresses the mass of one mole of a substance.","sol":"Step 1: Mass is measured in grams.\nStep 2: Amount of substance is measured in moles.\nStep 3: Therefore, molar mass is measured in grams per mole.","steps":["Step 1: Mass is measured in grams.","Step 2: Amount of substance is measured in moles.","Step 3: Therefore, molar mass is measured in grams per mole."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molar_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molar Mass"}', 3),
  (1900, 482, 'Calculate the number of moles in 36 g of water. Molar mass of water = 18 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"The mass is divided by the mass of one mole.","sol":"Step 1: Use n = m ÷ M.\nStep 2: m = 36 g.\nStep 3: M = 18 g mol⁻¹.\nStep 4: n = 36 ÷ 18.\nStep 5: n = 2 mol.","steps":["Step 1: Use n = m ÷ M.","Step 2: m = 36 g.","Step 3: M = 18 g mol⁻¹.","Step 4: n = 36 ÷ 18.","Step 5: n = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 0),
  (1901, 482, 'Calculate the number of moles in 44 g of CO₂. Molar mass = 44 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"A mass equal to the molar mass contains exactly one mole.","sol":"Step 1: n = m ÷ M.\nStep 2: n = 44 ÷ 44.\nStep 3: n = 1 mol.","steps":["Step 1: n = m ÷ M.","Step 2: n = 44 ÷ 44.","Step 3: n = 1 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 1),
  (1902, 482, 'Calculate the number of moles in 20 g of calcium carbonate. Molar mass = 100 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Moles from Mass.', '{"why":"The sample has one-fifth of the mass of one mole.","sol":"Step 1: n = m ÷ M.\nStep 2: m = 20 g.\nStep 3: M = 100 g mol⁻¹.\nStep 4: n = 20 ÷ 100.\nStep 5: n = 0.20 mol.","steps":["Step 1: n = m ÷ M.","Step 2: m = 20 g.","Step 3: M = 100 g mol⁻¹.","Step 4: n = 20 ÷ 100.","Step 5: n = 0.20 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 2),
  (1903, 482, 'Calculate the number of moles in 9 g of water. Molar mass = 18 g mol⁻¹.', 'text', 1, 'Use n = m ÷ M.', '{"why":"9 g is half the mass of one mole of water.","sol":"Step 1: n = 9 ÷ 18.\nStep 2: n = 0.5 mol.","steps":["Step 1: n = 9 ÷ 18.","Step 2: n = 0.5 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_moles_from_mass","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Moles from Mass"}', 3),
  (1904, 483, 'Calculate the mass of 3 mol of water. Molar mass = 18 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"Three moles have three times the mass of one mole.","sol":"Step 1: Use m = n × M.\nStep 2: n = 3 mol.\nStep 3: M = 18 g mol⁻¹.\nStep 4: m = 3 × 18.\nStep 5: m = 54 g.","steps":["Step 1: Use m = n × M.","Step 2: n = 3 mol.","Step 3: M = 18 g mol⁻¹.","Step 4: m = 3 × 18.","Step 5: m = 54 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 0),
  (1905, 483, 'Calculate the mass of 0.5 mol of CO₂. Molar mass = 44 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"Half a mole has half the mass of one mole.","sol":"Step 1: m = n × M.\nStep 2: m = 0.5 × 44.\nStep 3: m = 22 g.","steps":["Step 1: m = n × M.","Step 2: m = 0.5 × 44.","Step 3: m = 22 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 1),
  (1906, 483, 'Calculate the mass of 2.5 mol of NaCl. Molar mass = 58.5 g mol⁻¹.', 'text', 1, 'Focus on the core principle of Calculating Mass from Moles.', '{"why":"Mass equals amount in moles multiplied by molar mass.","sol":"Step 1: m = n × M.\nStep 2: n = 2.5 mol.\nStep 3: M = 58.5 g mol⁻¹.\nStep 4: m = 2.5 × 58.5.\nStep 5: m = 146.25 g.","steps":["Step 1: m = n × M.","Step 2: n = 2.5 mol.","Step 3: M = 58.5 g mol⁻¹.","Step 4: m = 2.5 × 58.5.","Step 5: m = 146.25 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 2),
  (1907, 483, 'What is the mass of 0.25 mol of water? Molar mass = 18 g mol⁻¹.', 'text', 1, 'Use m = n × M.', '{"why":"A quarter of a mole has a quarter of the mass of one mole.","sol":"Step 1: m = 0.25 × 18.\nStep 2: m = 4.5 g.","steps":["Step 1: m = 0.25 × 18.","Step 2: m = 4.5 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_mass_from_moles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Mass from Moles"}', 3),
  (1908, 484, 'How many molecules are present in 2 mol of CO₂?', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"Each mole contains 6.02 × 10²³ molecules.","sol":"Step 1: Use N = nNₐ.\nStep 2: n = 2 mol.\nStep 3: N = 2 × 6.02 × 10²³.\nStep 4: N = 1.204 × 10²⁴ molecules.","steps":["Step 1: Use N = nNₐ.","Step 2: n = 2 mol.","Step 3: N = 2 × 6.02 × 10²³.","Step 4: N = 1.204 × 10²⁴ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 0),
  (1909, 484, 'How many atoms are present in 0.1 mol of carbon atoms?', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"0.1 mole contains one-tenth of the Avogadro constant number of atoms.","sol":"Step 1: N = nNₐ.\nStep 2: N = 0.1 × 6.02 × 10²³.\nStep 3: N = 6.02 × 10²² atoms.","steps":["Step 1: N = nNₐ.","Step 2: N = 0.1 × 6.02 × 10²³.","Step 3: N = 6.02 × 10²² atoms."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 1),
  (1910, 484, 'How many moles are represented by 1.204 × 10²⁴ molecules?', 'text', 1, 'Focus on the core principle of Moles and Particles.', '{"why":"1.204 × 10²⁴ is twice the Avogadro constant.","sol":"Step 1: Use n = N ÷ Nₐ.\nStep 2: n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).\nStep 3: n = 2 mol.","steps":["Step 1: Use n = N ÷ Nₐ.","Step 2: n = (1.204 × 10²⁴) ÷ (6.02 × 10²³).","Step 3: n = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 2),
  (1911, 484, 'How many molecules are present in 0.5 mol of oxygen molecules?', 'text', 1, 'Multiply 0.5 by the Avogadro constant.', '{"why":"Half a mole contains half the Avogadro constant number of molecules.","sol":"Step 1: N = nNₐ.\nStep 2: N = 0.5 × 6.02 × 10²³.\nStep 3: N = 3.01 × 10²³ molecules.","steps":["Step 1: N = nNₐ.","Step 2: N = 0.5 × 6.02 × 10²³.","Step 3: N = 3.01 × 10²³ molecules."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_moles_and_particles","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Moles and Particles"}', 3),
  (1912, 485, 'What is the mole ratio of H₂ : O₂ : H₂O in 2H₂ + O₂ → 2H₂O?', 'text', 1, 'Focus on the core principle of Mole Ratios.', '{"why":"The coefficients in a balanced equation represent the mole ratio.","sol":"Step 1: Read the coefficient of H₂: 2.\nStep 2: Read the coefficient of O₂: 1.\nStep 3: Read the coefficient of H₂O: 2.\nStep 4: Therefore, the ratio is 2 : 1 : 2.","steps":["Step 1: Read the coefficient of H₂: 2.","Step 2: Read the coefficient of O₂: 1.","Step 3: Read the coefficient of H₂O: 2.","Step 4: Therefore, the ratio is 2 : 1 : 2."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_mole_ratios","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Mole Ratios"}', 0),
  (1913, 485, 'How many moles of oxygen react with 4 mol of hydrogen in 2H₂ + O₂ → 2H₂O?', 'text', 1, 'Focus on the core principle of Mole Ratios.', '{"why":"The balanced equation requires half as many moles of O₂ as H₂.","sol":"Step 1: The equation gives H₂ : O₂ = 2 : 1.\nStep 2: 2 mol H₂ require 1 mol O₂.\nStep 3: 4 mol H₂ is twice 2 mol.\nStep 4: Therefore, oxygen required = 2 mol.","steps":["Step 1: The equation gives H₂ : O₂ = 2 : 1.","Step 2: 2 mol H₂ require 1 mol O₂.","Step 3: 4 mol H₂ is twice 2 mol.","Step 4: Therefore, oxygen required = 2 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_mole_ratios","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Mole Ratios"}', 1),
  (1914, 485, 'How many moles of water are produced when 3 mol of O₂ react completely in 2H₂ + O₂ → 2H₂O?', 'text', 1, 'Focus on the core principle of Mole Ratios.', '{"why":"The balanced equation shows that twice as many moles of water are produced as oxygen consumed.","sol":"Step 1: The ratio O₂ : H₂O is 1 : 2.\nStep 2: 1 mol O₂ produces 2 mol H₂O.\nStep 3: 3 mol O₂ produces 3 × 2 mol H₂O.\nStep 4: Water produced = 6 mol.","steps":["Step 1: The ratio O₂ : H₂O is 1 : 2.","Step 2: 1 mol O₂ produces 2 mol H₂O.","Step 3: 3 mol O₂ produces 3 × 2 mol H₂O.","Step 4: Water produced = 6 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_mole_ratios","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Mole Ratios"}', 2),
  (1915, 485, 'In N₂ + 3H₂ → 2NH₃, how many moles of NH₃ are produced from 2 mol of N₂?', 'text', 1, 'Use the ratio N₂ : NH₃ = 1 : 2.', '{"why":"The mole ratio of nitrogen to ammonia is 1:2.","sol":"Step 1: The equation gives 1 mol N₂ → 2 mol NH₃.\nStep 2: 2 mol N₂ → 2 × 2 mol NH₃.\nStep 3: NH₃ produced = 4 mol.","steps":["Step 1: The equation gives 1 mol N₂ → 2 mol NH₃.","Step 2: 2 mol N₂ → 2 × 2 mol NH₃.","Step 3: NH₃ produced = 4 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_mole_ratios","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Mole Ratios"}', 3),
  (1916, 486, 'How many moles of O₂ are required to react with 6 mol H₂ in 2H₂ + O₂ → 2H₂O?', 'text', 1, 'Focus on the core principle of Calculating Reactant Amount.', '{"why":"The balanced equation requires one mole of oxygen for every two moles of hydrogen.","sol":"Step 1: H₂ : O₂ = 2 : 1.\nStep 2: 2 mol H₂ require 1 mol O₂.\nStep 3: 6 mol H₂ is three times 2 mol.\nStep 4: O₂ required = 3 × 1.\nStep 5: O₂ required = 3 mol.","steps":["Step 1: H₂ : O₂ = 2 : 1.","Step 2: 2 mol H₂ require 1 mol O₂.","Step 3: 6 mol H₂ is three times 2 mol.","Step 4: O₂ required = 3 × 1.","Step 5: O₂ required = 3 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_reactant_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Reactant Amount"}', 0),
  (1917, 486, 'How many moles of H₂ are required to react with 5 mol N₂ in N₂ + 3H₂ → 2NH₃?', 'text', 1, 'Focus on the core principle of Calculating Reactant Amount.', '{"why":"The balanced equation gives a 1:3 mole ratio between N₂ and H₂.","sol":"Step 1: N₂ : H₂ = 1 : 3.\nStep 2: 1 mol N₂ requires 3 mol H₂.\nStep 3: 5 mol N₂ requires 5 × 3 mol H₂.\nStep 4: H₂ required = 15 mol.","steps":["Step 1: N₂ : H₂ = 1 : 3.","Step 2: 1 mol N₂ requires 3 mol H₂.","Step 3: 5 mol N₂ requires 5 × 3 mol H₂.","Step 4: H₂ required = 15 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_reactant_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Reactant Amount"}', 1),
  (1918, 486, 'How many moles of oxygen are required to burn 4 mol CH₄ completely? CH₄ + 2O₂ → CO₂ + 2H₂O.', 'text', 1, 'Focus on the core principle of Calculating Reactant Amount.', '{"why":"Complete combustion of methane requires two moles of oxygen for every mole of methane.","sol":"Step 1: CH₄ : O₂ = 1 : 2.\nStep 2: 1 mol CH₄ requires 2 mol O₂.\nStep 3: 4 mol CH₄ requires 4 × 2 mol O₂.\nStep 4: O₂ required = 8 mol.","steps":["Step 1: CH₄ : O₂ = 1 : 2.","Step 2: 1 mol CH₄ requires 2 mol O₂.","Step 3: 4 mol CH₄ requires 4 × 2 mol O₂.","Step 4: O₂ required = 8 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_reactant_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Reactant Amount"}', 2),
  (1919, 486, 'How many moles of oxygen are required to react with 2 mol of magnesium? 2Mg + O₂ → 2MgO.', 'text', 1, 'Use the ratio Mg : O₂ = 2 : 1.', '{"why":"The balanced equation gives a 2:1 mole ratio.","sol":"Step 1: 2 mol Mg require 1 mol O₂.\nStep 2: The given amount is exactly 2 mol Mg.\nStep 3: Therefore, O₂ required = 1 mol.","steps":["Step 1: 2 mol Mg require 1 mol O₂.","Step 2: The given amount is exactly 2 mol Mg.","Step 3: Therefore, O₂ required = 1 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_reactant_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Reactant Amount"}', 3),
  (1920, 487, 'How many moles of NH₃ are produced from 4 mol N₂ in N₂ + 3H₂ → 2NH₃?', 'text', 1, 'Focus on the core principle of Calculating Product Amount.', '{"why":"The balanced equation shows that two moles of ammonia are produced per mole of nitrogen.","sol":"Step 1: N₂ : NH₃ = 1 : 2.\nStep 2: 1 mol N₂ produces 2 mol NH₃.\nStep 3: 4 mol N₂ produces 4 × 2 mol NH₃.\nStep 4: NH₃ = 8 mol.","steps":["Step 1: N₂ : NH₃ = 1 : 2.","Step 2: 1 mol N₂ produces 2 mol NH₃.","Step 3: 4 mol N₂ produces 4 × 2 mol NH₃.","Step 4: NH₃ = 8 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_product_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Product Amount"}', 0),
  (1921, 487, 'How many moles of CO₂ are produced from 3 mol CH₄? CH₄ + 2O₂ → CO₂ + 2H₂O.', 'text', 1, 'Focus on the core principle of Calculating Product Amount.', '{"why":"Methane and carbon dioxide have a 1:1 mole ratio in the balanced equation.","sol":"Step 1: CH₄ : CO₂ = 1 : 1.\nStep 2: 1 mol CH₄ produces 1 mol CO₂.\nStep 3: 3 mol CH₄ produces 3 mol CO₂.","steps":["Step 1: CH₄ : CO₂ = 1 : 1.","Step 2: 1 mol CH₄ produces 1 mol CO₂.","Step 3: 3 mol CH₄ produces 3 mol CO₂."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_product_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Product Amount"}', 1),
  (1922, 487, 'How many moles of H₂O are produced from 5 mol O₂ in 2H₂ + O₂ → 2H₂O?', 'text', 1, 'Focus on the core principle of Calculating Product Amount.', '{"why":"The balanced equation gives a 1:2 ratio between oxygen and water.","sol":"Step 1: O₂ : H₂O = 1 : 2.\nStep 2: 1 mol O₂ produces 2 mol H₂O.\nStep 3: 5 mol O₂ produces 5 × 2 mol H₂O.\nStep 4: H₂O = 10 mol.","steps":["Step 1: O₂ : H₂O = 1 : 2.","Step 2: 1 mol O₂ produces 2 mol H₂O.","Step 3: 5 mol O₂ produces 5 × 2 mol H₂O.","Step 4: H₂O = 10 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_product_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Product Amount"}', 2),
  (1923, 487, 'How many moles of MgO are formed from 3 mol Mg? 2Mg + O₂ → 2MgO.', 'text', 1, 'Compare the coefficients of Mg and MgO.', '{"why":"The balanced equation gives a 1:1 mole ratio between Mg and MgO.","sol":"Step 1: Mg : MgO = 2 : 2.\nStep 2: This simplifies to 1 : 1.\nStep 3: Therefore, 3 mol Mg produce 3 mol MgO.","steps":["Step 1: Mg : MgO = 2 : 2.","Step 2: This simplifies to 1 : 1.","Step 3: Therefore, 3 mol Mg produce 3 mol MgO."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_calculating_product_amount","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Calculating Product Amount"}', 3),
  (1924, 488, 'Find the empirical formula of a compound containing 12 g of carbon and 16 g of oxygen. C = 12, O = 16.', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"The simplest mole ratio of carbon to oxygen is 1:1.","sol":"Step 1: Calculate moles of C: 12 ÷ 12 = 1 mol.\nStep 2: Calculate moles of O: 16 ÷ 16 = 1 mol.\nStep 3: Divide by the smallest value, 1.\nStep 4: C : O = 1 : 1.\nStep 5: Therefore, the empirical formula is CO.","steps":["Step 1: Calculate moles of C: 12 ÷ 12 = 1 mol.","Step 2: Calculate moles of O: 16 ÷ 16 = 1 mol.","Step 3: Divide by the smallest value, 1.","Step 4: C : O = 1 : 1.","Step 5: Therefore, the empirical formula is CO."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_empirical_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Empirical Formula"}', 0),
  (1925, 488, 'Find the empirical formula of a compound containing 24 g carbon and 8 g hydrogen. C = 12, H = 1.', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"The simplest whole-number ratio of C:H is 1:4.","sol":"Step 1: Moles of C = 24 ÷ 12 = 2 mol.\nStep 2: Moles of H = 8 ÷ 1 = 8 mol.\nStep 3: Divide by the smallest value, 2.\nStep 4: C = 2 ÷ 2 = 1.\nStep 5: H = 8 ÷ 2 = 4.\nStep 6: Ratio = 1 : 4.\nStep 7: Empirical formula = CH₄.","steps":["Step 1: Moles of C = 24 ÷ 12 = 2 mol.","Step 2: Moles of H = 8 ÷ 1 = 8 mol.","Step 3: Divide by the smallest value, 2.","Step 4: C = 2 ÷ 2 = 1.","Step 5: H = 8 ÷ 2 = 4.","Step 6: Ratio = 1 : 4.","Step 7: Empirical formula = CH₄."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_empirical_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Empirical Formula"}', 1),
  (1926, 488, 'A compound contains 14 g nitrogen and 16 g oxygen. Find its empirical formula. N = 14, O = 16.', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"The simplest mole ratio is one nitrogen atom to one oxygen atom.","sol":"Step 1: Moles of N = 14 ÷ 14 = 1 mol.\nStep 2: Moles of O = 16 ÷ 16 = 1 mol.\nStep 3: Divide by the smallest value, 1.\nStep 4: Ratio N:O = 1:1.\nStep 5: Empirical formula = NO.","steps":["Step 1: Moles of N = 14 ÷ 14 = 1 mol.","Step 2: Moles of O = 16 ÷ 16 = 1 mol.","Step 3: Divide by the smallest value, 1.","Step 4: Ratio N:O = 1:1.","Step 5: Empirical formula = NO."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_empirical_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Empirical Formula"}', 2),
  (1927, 488, 'A compound contains 4 g hydrogen and 32 g oxygen. Find its empirical formula.', 'text', 1, 'First convert each mass into moles.', '{"why":"The simplest whole-number ratio of H:O is 2:1.","sol":"Step 1: H moles = 4 ÷ 1 = 4 mol.\nStep 2: O moles = 32 ÷ 16 = 2 mol.\nStep 3: Divide both by the smallest value, 2.\nStep 4: H = 4 ÷ 2 = 2.\nStep 5: O = 2 ÷ 2 = 1.\nStep 6: Empirical formula = H₂O.","steps":["Step 1: H moles = 4 ÷ 1 = 4 mol.","Step 2: O moles = 32 ÷ 16 = 2 mol.","Step 3: Divide both by the smallest value, 2.","Step 4: H = 4 ÷ 2 = 2.","Step 5: O = 2 ÷ 2 = 1.","Step 6: Empirical formula = H₂O."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_empirical_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Empirical Formula"}', 3),
  (1928, 489, 'The empirical formula of a compound is CH₂ and its molecular mass is 28. Find the molecular formula. C = 12, H = 1.', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"The molecular formula is twice the empirical formula.","sol":"Step 1: Empirical formula mass = 12 + (2 × 1) = 14.\nStep 2: Multiplier = molecular mass ÷ empirical formula mass.\nStep 3: Multiplier = 28 ÷ 14 = 2.\nStep 4: Multiply the subscripts in CH₂ by 2.\nStep 5: Molecular formula = C₂H₄.","steps":["Step 1: Empirical formula mass = 12 + (2 × 1) = 14.","Step 2: Multiplier = molecular mass ÷ empirical formula mass.","Step 3: Multiplier = 28 ÷ 14 = 2.","Step 4: Multiply the subscripts in CH₂ by 2.","Step 5: Molecular formula = C₂H₄."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molecular_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molecular Formula"}', 0),
  (1929, 489, 'The empirical formula is NO₂ and the molecular mass is 92. Find the molecular formula. N = 14, O = 16.', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"The molecular mass is twice the empirical formula mass.","sol":"Step 1: Empirical formula mass = 14 + (2 × 16) = 46.\nStep 2: Multiplier = 92 ÷ 46 = 2.\nStep 3: Multiply N₁O₂ by 2.\nStep 4: Molecular formula = N₂O₄.","steps":["Step 1: Empirical formula mass = 14 + (2 × 16) = 46.","Step 2: Multiplier = 92 ÷ 46 = 2.","Step 3: Multiply N₁O₂ by 2.","Step 4: Molecular formula = N₂O₄."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molecular_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molecular Formula"}', 1),
  (1930, 489, 'The empirical formula is CH and the molecular mass is 78. Find the molecular formula. C = 12, H = 1.', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"Six empirical formula units make one molecule with molecular mass 78.","sol":"Step 1: Empirical formula mass = 12 + 1 = 13.\nStep 2: Multiplier = 78 ÷ 13.\nStep 3: Multiplier = 6.\nStep 4: Multiply CH by 6.\nStep 5: Molecular formula = C₆H₆.","steps":["Step 1: Empirical formula mass = 12 + 1 = 13.","Step 2: Multiplier = 78 ÷ 13.","Step 3: Multiplier = 6.","Step 4: Multiply CH by 6.","Step 5: Molecular formula = C₆H₆."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molecular_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molecular Formula"}', 2),
  (1931, 489, 'The empirical formula is H₂O and the molecular mass is 18. What is the molecular formula?', 'text', 1, 'Compare the molecular mass with the empirical formula mass.', '{"why":"The molecular formula is already in its simplest ratio.","sol":"Step 1: Empirical formula mass = 18.\nStep 2: Multiplier = 18 ÷ 18 = 1.\nStep 3: Multiply H₂O by 1.\nStep 4: Molecular formula = H₂O.","steps":["Step 1: Empirical formula mass = 18.","Step 2: Multiplier = 18 ÷ 18 = 1.","Step 3: Multiply H₂O by 1.","Step 4: Molecular formula = H₂O."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_molecular_formula","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Molecular Formula"}', 3),
  (1932, 490, 'Calculate the percentage of hydrogen in H₂O. H = 1, O = 16.', 'text', 1, 'Focus on the core principle of Percentage Composition.', '{"why":"Hydrogen contributes 2 g to every 18 g of water.","sol":"Step 1: Molar mass of H₂O = (2 × 1) + 16 = 18.\nStep 2: Mass of hydrogen = 2.\nStep 3: %H = (2 ÷ 18) × 100.\nStep 4: %H = 11.1% approximately.","steps":["Step 1: Molar mass of H₂O = (2 × 1) + 16 = 18.","Step 2: Mass of hydrogen = 2.","Step 3: %H = (2 ÷ 18) × 100.","Step 4: %H = 11.1% approximately."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_composition","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Composition"}', 0),
  (1933, 490, 'Calculate the percentage of oxygen in H₂O. H = 1, O = 16.', 'text', 1, 'Focus on the core principle of Percentage Composition.', '{"why":"Oxygen contributes 16 g to every 18 g of water.","sol":"Step 1: Molar mass = 18.\nStep 2: Mass of oxygen = 16.\nStep 3: %O = (16 ÷ 18) × 100.\nStep 4: %O = 88.9% approximately.","steps":["Step 1: Molar mass = 18.","Step 2: Mass of oxygen = 16.","Step 3: %O = (16 ÷ 18) × 100.","Step 4: %O = 88.9% approximately."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_composition","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Composition"}', 1),
  (1934, 490, 'Calculate the percentage of carbon in CO₂. C = 12, O = 16.', 'text', 1, 'Focus on the core principle of Percentage Composition.', '{"why":"Carbon contributes 12 g to every 44 g of carbon dioxide.","sol":"Step 1: Molar mass of CO₂ = 12 + (2 × 16) = 44.\nStep 2: Mass of carbon = 12.\nStep 3: %C = (12 ÷ 44) × 100.\nStep 4: %C = 27.3% approximately.","steps":["Step 1: Molar mass of CO₂ = 12 + (2 × 16) = 44.","Step 2: Mass of carbon = 12.","Step 3: %C = (12 ÷ 44) × 100.","Step 4: %C = 27.3% approximately."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_composition","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Composition"}', 2),
  (1935, 490, 'Calculate the percentage of oxygen in CO₂.', 'text', 1, 'There are two oxygen atoms, each with relative atomic mass 16.', '{"why":"Oxygen contributes 32 g of the total 44 g molar mass.","sol":"Step 1: Molar mass of CO₂ = 44.\nStep 2: Oxygen mass = 2 × 16 = 32.\nStep 3: %O = (32 ÷ 44) × 100.\nStep 4: %O = 72.7% approximately.","steps":["Step 1: Molar mass of CO₂ = 44.","Step 2: Oxygen mass = 2 × 16 = 32.","Step 3: %O = (32 ÷ 44) × 100.","Step 4: %O = 72.7% approximately."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_composition","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Composition"}', 3),
  (1936, 491, 'What is a limiting reactant?', 'text', 1, 'Focus on the core principle of Limiting Reactant.', '{"why":"Once the limiting reactant is exhausted, the reaction cannot continue.","sol":"Step 1: Reactants combine in a fixed mole ratio.\nStep 2: One reactant may be completely consumed before another.\nStep 3: The reactant consumed first limits the amount of product formed.","steps":["Step 1: Reactants combine in a fixed mole ratio.","Step 2: One reactant may be completely consumed before another.","Step 3: The reactant consumed first limits the amount of product formed."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_limiting_reactant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Limiting Reactant"}', 0),
  (1937, 491, 'In 2H₂ + O₂ → 2H₂O, 3 mol H₂ are mixed with 2 mol O₂. Which reactant is limiting?', 'text', 1, 'Focus on the core principle of Limiting Reactant.', '{"why":"The available hydrogen is insufficient to react with all the available oxygen.","sol":"Step 1: The equation requires 2 mol H₂ for every 1 mol O₂.\nStep 2: 3 mol H₂ require 3 ÷ 2 = 1.5 mol O₂.\nStep 3: 2 mol O₂ are available.\nStep 4: Oxygen is therefore in excess.\nStep 5: Hydrogen is completely used first.\nStep 6: H₂ is the limiting reactant.","steps":["Step 1: The equation requires 2 mol H₂ for every 1 mol O₂.","Step 2: 3 mol H₂ require 3 ÷ 2 = 1.5 mol O₂.","Step 3: 2 mol O₂ are available.","Step 4: Oxygen is therefore in excess.","Step 5: Hydrogen is completely used first.","Step 6: H₂ is the limiting reactant."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_limiting_reactant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Limiting Reactant"}', 1),
  (1938, 491, 'In N₂ + 3H₂ → 2NH₃, 2 mol N₂ are mixed with 5 mol H₂. Which reactant is limiting?', 'text', 1, 'Focus on the core principle of Limiting Reactant.', '{"why":"Six moles of hydrogen would be required to react completely with 2 moles of nitrogen, but only five are available.","sol":"Step 1: 1 mol N₂ requires 3 mol H₂.\nStep 2: 2 mol N₂ require 2 × 3 = 6 mol H₂.\nStep 3: Only 5 mol H₂ are available.\nStep 4: Hydrogen is therefore used up first.\nStep 5: H₂ is the limiting reactant.","steps":["Step 1: 1 mol N₂ requires 3 mol H₂.","Step 2: 2 mol N₂ require 2 × 3 = 6 mol H₂.","Step 3: Only 5 mol H₂ are available.","Step 4: Hydrogen is therefore used up first.","Step 5: H₂ is the limiting reactant."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_limiting_reactant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Limiting Reactant"}', 2),
  (1939, 491, 'In 2Mg + O₂ → 2MgO, 4 mol Mg are mixed with 3 mol O₂. Which reactant is limiting?', 'text', 1, 'Determine how much oxygen is required for 4 mol Mg.', '{"why":"The available oxygen is more than enough to react with all the magnesium.","sol":"Step 1: 2 mol Mg require 1 mol O₂.\nStep 2: 4 mol Mg require 2 mol O₂.\nStep 3: 3 mol O₂ are available.\nStep 4: Oxygen is in excess.\nStep 5: Mg is used up first.","steps":["Step 1: 2 mol Mg require 1 mol O₂.","Step 2: 4 mol Mg require 2 mol O₂.","Step 3: 3 mol O₂ are available.","Step 4: Oxygen is in excess.","Step 5: Mg is used up first."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_limiting_reactant","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Limiting Reactant"}', 3),
  (1940, 492, 'Calculate the volume occupied by 2 mol of a gas at room temperature and pressure.', 'text', 1, 'Focus on the core principle of Gas Volumes at Room Conditions.', '{"why":"One mole occupies approximately 24 dm³ at room temperature and pressure.","sol":"Step 1: Use V = n × 24.\nStep 2: n = 2 mol.\nStep 3: V = 2 × 24.\nStep 4: V = 48 dm³.","steps":["Step 1: Use V = n × 24.","Step 2: n = 2 mol.","Step 3: V = 2 × 24.","Step 4: V = 48 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volumes_at_room_conditions","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volumes at Room Conditions"}', 0),
  (1941, 492, 'Calculate the volume occupied by 0.5 mol of a gas at room temperature and pressure.', 'text', 1, 'Focus on the core principle of Gas Volumes at Room Conditions.', '{"why":"Half a mole occupies half the volume of one mole.","sol":"Step 1: V = n × 24.\nStep 2: V = 0.5 × 24.\nStep 3: V = 12 dm³.","steps":["Step 1: V = n × 24.","Step 2: V = 0.5 × 24.","Step 3: V = 12 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volumes_at_room_conditions","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volumes at Room Conditions"}', 1),
  (1942, 492, 'Calculate the number of moles in 72 dm³ of a gas at room temperature and pressure.', 'text', 1, 'Focus on the core principle of Gas Volumes at Room Conditions.', '{"why":"72 dm³ contains three times the volume occupied by one mole.","sol":"Step 1: Use n = V ÷ 24.\nStep 2: n = 72 ÷ 24.\nStep 3: n = 3 mol.","steps":["Step 1: Use n = V ÷ 24.","Step 2: n = 72 ÷ 24.","Step 3: n = 3 mol."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volumes_at_room_conditions","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volumes at Room Conditions"}', 2),
  (1943, 492, 'Convert 12 dm³ into cm³.', 'text', 1, '1 dm³ = 1000 cm³.', '{"why":"Each cubic decimetre contains 1000 cubic centimetres.","sol":"Step 1: 1 dm³ = 1000 cm³.\nStep 2: 12 dm³ = 12 × 1000 cm³.\nStep 3: 12 dm³ = 12,000 cm³.","steps":["Step 1: 1 dm³ = 1000 cm³.","Step 2: 12 dm³ = 12 × 1000 cm³.","Step 3: 12 dm³ = 12,000 cm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volumes_at_room_conditions","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volumes at Room Conditions"}', 3),
  (1944, 493, 'In N₂ + 3H₂ → 2NH₃, what volume of H₂ reacts with 10 dm³ of N₂ under the same conditions?', 'text', 1, 'Focus on the core principle of Gas Volume Calculations.', '{"why":"Gas volumes at the same temperature and pressure follow the coefficients of the balanced equation.","sol":"Step 1: N₂ : H₂ = 1 : 3.\nStep 2: 1 volume of N₂ requires 3 volumes of H₂.\nStep 3: 10 dm³ N₂ requires 10 × 3 dm³ H₂.\nStep 4: H₂ required = 30 dm³.","steps":["Step 1: N₂ : H₂ = 1 : 3.","Step 2: 1 volume of N₂ requires 3 volumes of H₂.","Step 3: 10 dm³ N₂ requires 10 × 3 dm³ H₂.","Step 4: H₂ required = 30 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volume_calculations","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volume Calculations"}', 0),
  (1945, 493, 'In N₂ + 3H₂ → 2NH₃, what volume of NH₃ is produced from 10 dm³ of N₂ under the same conditions?', 'text', 1, 'Focus on the core principle of Gas Volume Calculations.', '{"why":"The equation gives a 1:2 volume ratio between nitrogen and ammonia.","sol":"Step 1: N₂ : NH₃ = 1 : 2.\nStep 2: 1 volume N₂ produces 2 volumes NH₃.\nStep 3: 10 dm³ N₂ produces 10 × 2 dm³ NH₃.\nStep 4: NH₃ produced = 20 dm³.","steps":["Step 1: N₂ : NH₃ = 1 : 2.","Step 2: 1 volume N₂ produces 2 volumes NH₃.","Step 3: 10 dm³ N₂ produces 10 × 2 dm³ NH₃.","Step 4: NH₃ produced = 20 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volume_calculations","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volume Calculations"}', 1),
  (1946, 493, 'In 2H₂ + O₂ → 2H₂O(g), what volume of oxygen reacts with 40 dm³ hydrogen under the same conditions?', 'text', 1, 'Focus on the core principle of Gas Volume Calculations.', '{"why":"The gas-volume ratio follows the balanced equation coefficients.","sol":"Step 1: H₂ : O₂ = 2 : 1.\nStep 2: 2 volumes H₂ require 1 volume O₂.\nStep 3: 40 dm³ H₂ requires 40 ÷ 2 dm³ O₂.\nStep 4: O₂ required = 20 dm³.","steps":["Step 1: H₂ : O₂ = 2 : 1.","Step 2: 2 volumes H₂ require 1 volume O₂.","Step 3: 40 dm³ H₂ requires 40 ÷ 2 dm³ O₂.","Step 4: O₂ required = 20 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volume_calculations","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volume Calculations"}', 2),
  (1947, 493, 'In CH₄ + 2O₂ → CO₂ + 2H₂O(g), what volume of oxygen is required to burn 5 dm³ of methane completely?', 'text', 1, 'The ratio CH₄ : O₂ is 1 : 2.', '{"why":"The balanced equation gives a 1:2 gas-volume ratio.","sol":"Step 1: 1 volume CH₄ requires 2 volumes O₂.\nStep 2: 5 dm³ CH₄ requires 5 × 2 dm³ O₂.\nStep 3: O₂ required = 10 dm³.","steps":["Step 1: 1 volume CH₄ requires 2 volumes O₂.","Step 2: 5 dm³ CH₄ requires 5 × 2 dm³ O₂.","Step 3: O₂ required = 10 dm³."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_gas_volume_calculations","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Gas Volume Calculations"}', 3),
  (1948, 494, 'Calculate the percentage yield when the theoretical yield is 10 g and the actual yield is 8 g.', 'text', 1, 'Focus on the core principle of Percentage Yield.', '{"why":"The actual yield is 80% of the theoretical maximum.","sol":"Step 1: Use % yield = (actual ÷ theoretical) × 100.\nStep 2: % yield = (8 ÷ 10) × 100.\nStep 3: % yield = 80%.","steps":["Step 1: Use % yield = (actual ÷ theoretical) × 100.","Step 2: % yield = (8 ÷ 10) × 100.","Step 3: % yield = 80%."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_yield","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q1","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Yield"}', 0),
  (1949, 494, 'A reaction has a theoretical yield of 25 g and an actual yield of 20 g. Calculate the percentage yield.', 'text', 1, 'Focus on the core principle of Percentage Yield.', '{"why":"The actual yield is four-fifths of the theoretical yield.","sol":"Step 1: % yield = (actual ÷ theoretical) × 100.\nStep 2: % yield = (20 ÷ 25) × 100.\nStep 3: % yield = 0.8 × 100.\nStep 4: % yield = 80%.","steps":["Step 1: % yield = (actual ÷ theoretical) × 100.","Step 2: % yield = (20 ÷ 25) × 100.","Step 3: % yield = 0.8 × 100.","Step 4: % yield = 80%."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_yield","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q2","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Yield"}', 1),
  (1950, 494, 'A reaction has a theoretical yield of 50 g and an actual yield of 35 g. Calculate the percentage yield.', 'text', 1, 'Focus on the core principle of Percentage Yield.', '{"why":"The actual yield is 70% of the calculated theoretical yield.","sol":"Step 1: % yield = (35 ÷ 50) × 100.\nStep 2: 35 ÷ 50 = 0.70.\nStep 3: 0.70 × 100 = 70%.","steps":["Step 1: % yield = (35 ÷ 50) × 100.","Step 2: 35 ÷ 50 = 0.70.","Step 3: 0.70 × 100 = 70%."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_yield","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q3","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Yield"}', 2),
  (1951, 494, 'The theoretical yield of a reaction is 40 g and the percentage yield is 75%. Calculate the actual yield.', 'text', 1, 'Rearrange % yield = (actual ÷ theoretical) × 100.', '{"why":"A 75% yield means the actual product is 75% of the theoretical amount.","sol":"Step 1: 75 = (actual ÷ 40) × 100.\nStep 2: 75 ÷ 100 = actual ÷ 40.\nStep 3: 0.75 = actual ÷ 40.\nStep 4: actual = 0.75 × 40.\nStep 5: actual = 30 g.","steps":["Step 1: 75 = (actual ÷ 40) × 100.","Step 2: 75 ÷ 100 = actual ÷ 40.","Step 3: 0.75 = actual ÷ 40.","Step 4: actual = 0.75 × 40.","Step 5: actual = 30 g."],"options":[],"conceptId":"chemistry_moles_quantitative_chemistry_percentage_yield","skillId":"chemistry_moles_quantitative_chemistry","subskillId":"chemistry_moles_quantitative_chemistry_q4","subject":"chemistry","chapter":"moles_quantitative_chemistry","topic":"Percentage Yield"}', 3),
  (1952, 495, 'What is a chemical reaction?', 'text', 1, 'Focus on the core principle of Chemical Reactions.', '{"why":"The formation of new substances distinguishes a chemical reaction from a physical change.","sol":"Step 1: A chemical reaction involves substances changing.\nStep 2: New substances are formed.\nStep 3: The new substances have different properties from the original substances.","steps":["Step 1: A chemical reaction involves substances changing.","Step 2: New substances are formed.","Step 3: The new substances have different properties from the original substances."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 0),
  (1953, 495, 'Identify the reactants and product in: magnesium + oxygen → magnesium oxide.', 'text', 1, 'Focus on the core principle of Chemical Reactions.', '{"why":"Reactants are changed during the reaction, while products are formed.","sol":"Step 1: Look at the substances before the arrow.\nStep 2: Magnesium and oxygen are before the arrow, so they are the reactants.\nStep 3: Magnesium oxide is after the arrow, so it is the product.","steps":["Step 1: Look at the substances before the arrow.","Step 2: Magnesium and oxygen are before the arrow, so they are the reactants.","Step 3: Magnesium oxide is after the arrow, so it is the product."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 1),
  (1954, 495, 'What happens to atoms during a chemical reaction?', 'text', 1, 'Focus on the core principle of Chemical Reactions.', '{"why":"Chemical reactions involve rearrangement of atoms.","sol":"Step 1: Atoms in the reactants are present before the reaction.\nStep 2: The atoms become rearranged into new combinations.\nStep 3: The atoms are therefore conserved.","steps":["Step 1: Atoms in the reactants are present before the reaction.","Step 2: The atoms become rearranged into new combinations.","Step 3: The atoms are therefore conserved."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 2),
  (1955, 495, 'A student reacts iron with sulphur to form iron(II) sulphide. Identify the reactants and product.', 'text', 1, 'Reactants are the substances present before the arrow.', '{"why":"The starting substances are reactants and the newly formed substance is the product.","sol":"Step 1: Iron and sulphur are used at the beginning.\nStep 2: Therefore they are the reactants.\nStep 3: Iron(II) sulphide is formed.","steps":["Step 1: Iron and sulphur are used at the beginning.","Step 2: Therefore they are the reactants.","Step 3: Iron(II) sulphide is formed."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Reactions"}', 3),
  (1956, 496, 'What are reactants?', 'text', 1, 'Focus on the core principle of Reactants.', '{"why":"Reactants provide the atoms that are rearranged to form products.","sol":"Step 1: Identify the substances present before a reaction occurs.\nStep 2: These substances take part in the reaction.\nStep 3: They are called reactants.","steps":["Step 1: Identify the substances present before a reaction occurs.","Step 2: These substances take part in the reaction.","Step 3: They are called reactants."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 0),
  (1957, 496, 'Identify the reactants in: CaCO₃ → CaO + CO₂.', 'text', 1, 'Focus on the core principle of Reactants.', '{"why":"The substance on the left of the reaction arrow is the reactant.","sol":"Step 1: Look at the left-hand side of the arrow.\nStep 2: CaCO₃ is on the left.\nStep 3: Therefore CaCO₃ is the reactant.","steps":["Step 1: Look at the left-hand side of the arrow.","Step 2: CaCO₃ is on the left.","Step 3: Therefore CaCO₃ is the reactant."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 1),
  (1958, 496, 'Identify all reactants in: 2H₂ + O₂ → 2H₂O.', 'text', 1, 'Focus on the core principle of Reactants.', '{"why":"Both substances participate in forming water.","sol":"Step 1: Look to the left of the arrow.\nStep 2: H₂ and O₂ are written there.\nStep 3: Both are therefore reactants.","steps":["Step 1: Look to the left of the arrow.","Step 2: H₂ and O₂ are written there.","Step 3: Both are therefore reactants."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 2),
  (1959, 496, 'In Zn + 2HCl → ZnCl₂ + H₂, identify the reactants.', 'text', 1, 'Look at the left side of the arrow.', '{"why":"Reactants are written before the reaction arrow.","sol":"Step 1: The left side contains Zn and 2HCl.\nStep 2: These are the substances that react.","steps":["Step 1: The left side contains Zn and 2HCl.","Step 2: These are the substances that react."],"options":[],"conceptId":"chemistry_chemical_reactions_reactants","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Reactants"}', 3),
  (1960, 497, 'What are products?', 'text', 1, 'Focus on the core principle of Products.', '{"why":"They are the substances produced after the reactants have changed.","sol":"Step 1: A chemical reaction produces new substances.\nStep 2: The new substances formed are called products.","steps":["Step 1: A chemical reaction produces new substances.","Step 2: The new substances formed are called products."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 0),
  (1961, 497, 'Identify the product in: 2Mg + O₂ → 2MgO.', 'text', 1, 'Focus on the core principle of Products.', '{"why":"The product is written after the reaction arrow.","sol":"Step 1: Look at the right-hand side of the arrow.\nStep 2: MgO is on the right.\nStep 3: Therefore magnesium oxide is the product.","steps":["Step 1: Look at the right-hand side of the arrow.","Step 2: MgO is on the right.","Step 3: Therefore magnesium oxide is the product."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 1),
  (1962, 497, 'Identify the product in: CaCO₃ → CaO + CO₂.', 'text', 1, 'Focus on the core principle of Products.', '{"why":"A reaction can form more than one product.","sol":"Step 1: Look to the right of the arrow.\nStep 2: CaO and CO₂ are on the right.\nStep 3: Both are products.","steps":["Step 1: Look to the right of the arrow.","Step 2: CaO and CO₂ are on the right.","Step 3: Both are products."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 2),
  (1963, 497, 'In Fe + S → FeS, identify the product.', 'text', 1, 'Look to the right of the arrow.', '{"why":"Products are formed during the reaction and appear on the right.","sol":"Step 1: FeS is written after the arrow.\nStep 2: Therefore it is the substance formed.","steps":["Step 1: FeS is written after the arrow.","Step 2: Therefore it is the substance formed."],"options":[],"conceptId":"chemistry_chemical_reactions_products","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Products"}', 3),
  (1964, 498, 'State three signs that may indicate that a chemical reaction has occurred.', 'text', 1, 'Focus on the core principle of Signs of Chemical Reaction.', '{"why":"Chemical reactions often produce observable changes because new substances are formed.","sol":"Step 1: Consider observable changes during a reaction.\nStep 2: Examples include gas production, colour change and temperature change.\nStep 3: A precipitate may also form.","steps":["Step 1: Consider observable changes during a reaction.","Step 2: Examples include gas production, colour change and temperature change.","Step 3: A precipitate may also form."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reaction","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reaction"}', 0),
  (1965, 498, 'What is a precipitate?', 'text', 1, 'Focus on the core principle of Signs of Chemical Reaction.', '{"why":"The formation of an insoluble solid is evidence that a new substance has formed.","sol":"Step 1: Two solutions may react when mixed.\nStep 2: An insoluble solid may form.\nStep 3: This solid is called a precipitate.","steps":["Step 1: Two solutions may react when mixed.","Step 2: An insoluble solid may form.","Step 3: This solid is called a precipitate."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reaction","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reaction"}', 1),
  (1966, 498, 'Why can a temperature change indicate a chemical reaction?', 'text', 1, 'Focus on the core principle of Signs of Chemical Reaction.', '{"why":"Energy changes accompany many chemical reactions.","sol":"Step 1: Chemical reactions involve energy changes.\nStep 2: Energy may be released or absorbed.\nStep 3: This can cause the temperature of the surroundings to change.","steps":["Step 1: Chemical reactions involve energy changes.","Step 2: Energy may be released or absorbed.","Step 3: This can cause the temperature of the surroundings to change."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reaction","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reaction"}', 2),
  (1967, 498, 'A colourless solution produces bubbles when another solution is added. What evidence suggests that a chemical reaction has occurred?', 'text', 1, 'Look at what is being produced.', '{"why":"A gas may be a new product formed during the reaction.","sol":"Step 1: Bubbles indicate that a gas is being produced.\nStep 2: Gas production is an observable sign of a chemical reaction.","steps":["Step 1: Bubbles indicate that a gas is being produced.","Step 2: Gas production is an observable sign of a chemical reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_signs_of_chemical_reaction","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Signs of Chemical Reaction"}', 3),
  (1968, 499, 'State the law of conservation of mass.', 'text', 1, 'Focus on the core principle of Conservation of Mass.', '{"why":"The atoms present before the reaction are rearranged rather than created or destroyed.","sol":"Step 1: Consider the total mass before a chemical reaction.\nStep 2: Compare it with the total mass after the reaction.\nStep 3: They are equal in a closed system.","steps":["Step 1: Consider the total mass before a chemical reaction.","Step 2: Compare it with the total mass after the reaction.","Step 3: They are equal in a closed system."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 0),
  (1969, 499, '10 g of calcium carbonate decomposes to form 5.6 g of calcium oxide and carbon dioxide. Calculate the mass of carbon dioxide.', 'text', 1, 'Focus on the core principle of Conservation of Mass.', '{"why":"The total mass of products must equal the total mass of reactants.","sol":"Step 1: Total mass of reactants = 10 g.\nStep 2: Total mass of products must also be 10 g.\nStep 3: Mass of carbon dioxide = 10 − 5.6.\nStep 4: Mass of carbon dioxide = 4.4 g.","steps":["Step 1: Total mass of reactants = 10 g.","Step 2: Total mass of products must also be 10 g.","Step 3: Mass of carbon dioxide = 10 − 5.6.","Step 4: Mass of carbon dioxide = 4.4 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 1),
  (1970, 499, '12 g of magnesium reacts with oxygen to form 20 g of magnesium oxide. Calculate the mass of oxygen that reacted.', 'text', 1, 'Focus on the core principle of Conservation of Mass.', '{"why":"The mass of the product equals the total mass of the reactants.","sol":"Step 1: Mass of reactants = mass of magnesium + mass of oxygen.\nStep 2: Total mass of reactants must equal 20 g.\nStep 3: Mass of oxygen = 20 − 12.\nStep 4: Mass of oxygen = 8 g.","steps":["Step 1: Mass of reactants = mass of magnesium + mass of oxygen.","Step 2: Total mass of reactants must equal 20 g.","Step 3: Mass of oxygen = 20 − 12.","Step 4: Mass of oxygen = 8 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 2),
  (1971, 499, 'A reaction has 25 g of reactants and produces 18 g of one product. What is the mass of the other product?', 'text', 1, 'Use total reactant mass = total product mass.', '{"why":"Mass is conserved during the reaction.","sol":"Step 1: Total product mass must be 25 g.\nStep 2: One product has a mass of 18 g.\nStep 3: Other product = 25 − 18.\nStep 4: Other product = 7 g.","steps":["Step 1: Total product mass must be 25 g.","Step 2: One product has a mass of 18 g.","Step 3: Other product = 25 − 18.","Step 4: Other product = 7 g."],"options":[],"conceptId":"chemistry_chemical_reactions_conservation_of_mass","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Conservation of Mass"}', 3),
  (1972, 500, 'What is a chemical equation?', 'text', 1, 'Focus on the core principle of Chemical Equations.', '{"why":"Chemical equations provide a concise way of representing chemical reactions.","sol":"Step 1: A chemical reaction can be represented using symbols and formulae.\nStep 2: The reactants are written on the left.\nStep 3: The products are written on the right.","steps":["Step 1: A chemical reaction can be represented using symbols and formulae.","Step 2: The reactants are written on the left.","Step 3: The products are written on the right."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 0),
  (1973, 500, 'What does the arrow in a chemical equation mean?', 'text', 1, 'Focus on the core principle of Chemical Equations.', '{"why":"The arrow connects the reactants to the products.","sol":"Step 1: Look at the direction of the reaction.\nStep 2: Reactants are placed before the arrow.\nStep 3: Products are placed after the arrow.","steps":["Step 1: Look at the direction of the reaction.","Step 2: Reactants are placed before the arrow.","Step 3: Products are placed after the arrow."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 1),
  (1974, 500, 'Write the word equation for magnesium reacting with oxygen to form magnesium oxide.', 'text', 1, 'Focus on the core principle of Chemical Equations.', '{"why":"A word equation names the substances instead of using chemical formulae.","sol":"Step 1: Identify the reactants: magnesium and oxygen.\nStep 2: Identify the product: magnesium oxide.\nStep 3: Arrange them as reactants → product.","steps":["Step 1: Identify the reactants: magnesium and oxygen.","Step 2: Identify the product: magnesium oxide.","Step 3: Arrange them as reactants → product."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 2),
  (1975, 500, 'In the equation H₂ + Cl₂ → 2HCl, identify the reactants and products.', 'text', 1, 'Use the position relative to the arrow.', '{"why":"Reactants are on the left and products are on the right.","sol":"Step 1: H₂ and Cl₂ are on the left.\nStep 2: 2HCl is on the right.\nStep 3: Therefore H₂ and Cl₂ are reactants and HCl is the product.","steps":["Step 1: H₂ and Cl₂ are on the left.","Step 2: 2HCl is on the right.","Step 3: Therefore H₂ and Cl₂ are reactants and HCl is the product."],"options":[],"conceptId":"chemistry_chemical_reactions_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Chemical Equations"}', 3),
  (1976, 501, 'Write the chemical equation for magnesium reacting with oxygen to form magnesium oxide before balancing.', 'text', 1, 'Focus on the core principle of Writing Chemical Equations.', '{"why":"The correct chemical formulae must be used before balancing.","sol":"Step 1: Magnesium has the formula Mg.\nStep 2: Oxygen gas has the formula O₂.\nStep 3: Magnesium oxide has the formula MgO.\nStep 4: Write the reactants on the left and product on the right.","steps":["Step 1: Magnesium has the formula Mg.","Step 2: Oxygen gas has the formula O₂.","Step 3: Magnesium oxide has the formula MgO.","Step 4: Write the reactants on the left and product on the right."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 0),
  (1977, 501, 'Write the chemical equation for hydrogen reacting with chlorine to form hydrogen chloride before balancing.', 'text', 1, 'Focus on the core principle of Writing Chemical Equations.', '{"why":"The formulae represent the substances taking part in the reaction.","sol":"Step 1: Hydrogen gas is H₂.\nStep 2: Chlorine gas is Cl₂.\nStep 3: Hydrogen chloride is HCl.\nStep 4: Arrange them as reactants → product.","steps":["Step 1: Hydrogen gas is H₂.","Step 2: Chlorine gas is Cl₂.","Step 3: Hydrogen chloride is HCl.","Step 4: Arrange them as reactants → product."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 1),
  (1978, 501, 'Write the chemical equation for calcium carbonate decomposing into calcium oxide and carbon dioxide.', 'text', 1, 'Focus on the core principle of Writing Chemical Equations.', '{"why":"The equation represents one compound breaking down into two products.","sol":"Step 1: Calcium carbonate is CaCO₃.\nStep 2: Calcium oxide is CaO.\nStep 3: Carbon dioxide is CO₂.\nStep 4: Write the reactant first and products after the arrow.","steps":["Step 1: Calcium carbonate is CaCO₃.","Step 2: Calcium oxide is CaO.","Step 3: Carbon dioxide is CO₂.","Step 4: Write the reactant first and products after the arrow."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 2),
  (1979, 501, 'Write the unbalanced equation for zinc reacting with hydrochloric acid to form zinc chloride and hydrogen.', 'text', 1, 'Use Zn, HCl, ZnCl₂ and H₂.', '{"why":"The correct formulae must be written before balancing.","sol":"Step 1: Zinc = Zn.\nStep 2: Hydrochloric acid = HCl.\nStep 3: Zinc chloride = ZnCl₂.\nStep 4: Hydrogen gas = H₂.\nStep 5: Arrange the substances.","steps":["Step 1: Zinc = Zn.","Step 2: Hydrochloric acid = HCl.","Step 3: Zinc chloride = ZnCl₂.","Step 4: Hydrogen gas = H₂.","Step 5: Arrange the substances."],"options":[],"conceptId":"chemistry_chemical_reactions_writing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Writing Chemical Equations"}', 3),
  (1980, 502, 'What does (s) mean in a chemical equation?', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"(s) is the standard state symbol for a solid.","sol":"Step 1: Identify the state symbol.\nStep 2: (s) represents a solid.","steps":["Step 1: Identify the state symbol.","Step 2: (s) represents a solid."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 0),
  (1981, 502, 'What does (aq) mean?', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"The symbol (aq) indicates an aqueous solution.","sol":"Step 1: Recognise that aq means aqueous.\nStep 2: Aqueous means dissolved in water.","steps":["Step 1: Recognise that aq means aqueous.","Step 2: Aqueous means dissolved in water."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 1),
  (1982, 502, 'Identify the physical state of each substance in: Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g).', 'text', 1, 'Focus on the core principle of State Symbols.', '{"why":"Each state symbol describes the physical state of the substance.","sol":"Step 1: Mg(s) is a solid.\nStep 2: HCl(aq) is aqueous.\nStep 3: MgCl₂(aq) is aqueous.\nStep 4: H₂(g) is a gas.","steps":["Step 1: Mg(s) is a solid.","Step 2: HCl(aq) is aqueous.","Step 3: MgCl₂(aq) is aqueous.","Step 4: H₂(g) is a gas."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 2),
  (1983, 502, 'Write the correct state symbol for oxygen gas.', 'text', 1, 'Oxygen under ordinary conditions is a gas.', '{"why":"(g) represents the gaseous state.","sol":"Step 1: Oxygen exists as a gas under ordinary conditions.\nStep 2: The state symbol for gas is (g).","steps":["Step 1: Oxygen exists as a gas under ordinary conditions.","Step 2: The state symbol for gas is (g)."],"options":[],"conceptId":"chemistry_chemical_reactions_state_symbols","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"State Symbols"}', 3),
  (1984, 503, 'What does it mean for a chemical equation to be balanced?', 'text', 1, 'Focus on the core principle of Balancing Chemical Equations.', '{"why":"Atoms are conserved during a chemical reaction.","sol":"Step 1: Count the atoms of each element on the reactant side.\nStep 2: Count the atoms of each element on the product side.\nStep 3: The numbers must be equal for every element.","steps":["Step 1: Count the atoms of each element on the reactant side.","Step 2: Count the atoms of each element on the product side.","Step 3: The numbers must be equal for every element."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 0),
  (1985, 503, 'What should be changed when balancing an equation?', 'text', 1, 'Focus on the core principle of Balancing Chemical Equations.', '{"why":"Changing subscripts would change the substances themselves.","sol":"Step 1: Keep the chemical formulae unchanged.\nStep 2: Add numbers in front of formulae.\nStep 3: These numbers are called coefficients.","steps":["Step 1: Keep the chemical formulae unchanged.","Step 2: Add numbers in front of formulae.","Step 3: These numbers are called coefficients."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 1),
  (1986, 503, 'Why must the small numbers inside formulae not be changed when balancing?', 'text', 1, 'Focus on the core principle of Balancing Chemical Equations.', '{"why":"Balancing changes the number of particles, not the identity of the substances.","sol":"Step 1: The small numbers are subscripts.\nStep 2: They define the composition of a substance.\nStep 3: Changing them would create a different substance.","steps":["Step 1: The small numbers are subscripts.","Step 2: They define the composition of a substance.","Step 3: Changing them would create a different substance."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 2),
  (1987, 503, 'Balance: H₂ + O₂ → H₂O.', 'text', 1, 'First balance oxygen, then hydrogen.', '{"why":"Both hydrogen and oxygen now have equal numbers of atoms on both sides.","sol":"Step 1: There are 2 oxygen atoms in O₂ but 1 in H₂O.\nStep 2: Put 2 before H₂O: H₂ + O₂ → 2H₂O.\nStep 3: There are now 4 hydrogen atoms on the right.\nStep 4: Put 2 before H₂.\nStep 5: Final equation: 2H₂ + O₂ → 2H₂O.","steps":["Step 1: There are 2 oxygen atoms in O₂ but 1 in H₂O.","Step 2: Put 2 before H₂O: H₂ + O₂ → 2H₂O.","Step 3: There are now 4 hydrogen atoms on the right.","Step 4: Put 2 before H₂.","Step 5: Final equation: 2H₂ + O₂ → 2H₂O."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_chemical_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Chemical Equations"}', 3),
  (1988, 504, 'Balance: Mg + O₂ → MgO.', 'text', 1, 'Focus on the core principle of Balancing Simple Equations.', '{"why":"There are 2 magnesium atoms and 2 oxygen atoms on both sides.","sol":"Step 1: Oxygen has 2 atoms on the left and 1 on the right.\nStep 2: Put 2 before MgO.\nStep 3: Magnesium now has 2 atoms on the right.\nStep 4: Put 2 before Mg.\nStep 5: Check both elements.","steps":["Step 1: Oxygen has 2 atoms on the left and 1 on the right.","Step 2: Put 2 before MgO.","Step 3: Magnesium now has 2 atoms on the right.","Step 4: Put 2 before Mg.","Step 5: Check both elements."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_simple_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Simple Equations"}', 0),
  (1989, 504, 'Balance: H₂ + Cl₂ → HCl.', 'text', 1, 'Focus on the core principle of Balancing Simple Equations.', '{"why":"The coefficient 2 gives two hydrogen atoms and two chlorine atoms in the products.","sol":"Step 1: There are 2 hydrogen atoms on the left.\nStep 2: There are 2 chlorine atoms on the left.\nStep 3: Put 2 before HCl.\nStep 4: The equation becomes H₂ + Cl₂ → 2HCl.","steps":["Step 1: There are 2 hydrogen atoms on the left.","Step 2: There are 2 chlorine atoms on the left.","Step 3: Put 2 before HCl.","Step 4: The equation becomes H₂ + Cl₂ → 2HCl."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_simple_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Simple Equations"}', 1),
  (1990, 504, 'Balance: Na + Cl₂ → NaCl.', 'text', 1, 'Focus on the core principle of Balancing Simple Equations.', '{"why":"Both sodium and chlorine atoms are equal on both sides.","sol":"Step 1: Chlorine has 2 atoms on the left.\nStep 2: Put 2 before NaCl.\nStep 3: There are now 2 sodium atoms on the right.\nStep 4: Put 2 before Na.","steps":["Step 1: Chlorine has 2 atoms on the left.","Step 2: Put 2 before NaCl.","Step 3: There are now 2 sodium atoms on the right.","Step 4: Put 2 before Na."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_simple_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Simple Equations"}', 2),
  (1991, 504, 'Balance: Ca + O₂ → CaO.', 'text', 1, 'Oxygen occurs as O₂, so balance oxygen first.', '{"why":"There are two calcium atoms and two oxygen atoms on both sides.","sol":"Step 1: O₂ contains 2 oxygen atoms.\nStep 2: Put 2 before CaO.\nStep 3: This gives 2 calcium atoms on the right.\nStep 4: Put 2 before Ca.","steps":["Step 1: O₂ contains 2 oxygen atoms.","Step 2: Put 2 before CaO.","Step 3: This gives 2 calcium atoms on the right.","Step 4: Put 2 before Ca."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_simple_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing Simple Equations"}', 3),
  (1992, 505, 'Balance: Fe + O₂ → Fe₂O₃.', 'text', 1, 'Focus on the core principle of Balancing More Complex Equations.', '{"why":"There are 4 iron atoms and 6 oxygen atoms on each side.","sol":"Step 1: Fe₂O₃ contains 2 Fe atoms and 3 O atoms.\nStep 2: Use 2Fe₂O₃ to give 4 Fe atoms and 6 O atoms.\nStep 3: Put 4 before Fe.\nStep 4: Put 3 before O₂ to give 6 oxygen atoms.\nStep 5: Check both elements.","steps":["Step 1: Fe₂O₃ contains 2 Fe atoms and 3 O atoms.","Step 2: Use 2Fe₂O₃ to give 4 Fe atoms and 6 O atoms.","Step 3: Put 4 before Fe.","Step 4: Put 3 before O₂ to give 6 oxygen atoms.","Step 5: Check both elements."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_more_complex_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing More Complex Equations"}', 0),
  (1993, 505, 'Balance: Al + O₂ → Al₂O₃.', 'text', 1, 'Focus on the core principle of Balancing More Complex Equations.', '{"why":"Both elements have equal numbers of atoms on both sides.","sol":"Step 1: Use 2Al₂O₃ to give 4 aluminium atoms and 6 oxygen atoms.\nStep 2: Put 4 before Al.\nStep 3: Put 3 before O₂.\nStep 4: Check aluminium and oxygen.","steps":["Step 1: Use 2Al₂O₃ to give 4 aluminium atoms and 6 oxygen atoms.","Step 2: Put 4 before Al.","Step 3: Put 3 before O₂.","Step 4: Check aluminium and oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_more_complex_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing More Complex Equations"}', 1),
  (1994, 505, 'Balance: CH₄ + O₂ → CO₂ + H₂O.', 'text', 1, 'Focus on the core principle of Balancing More Complex Equations.', '{"why":"There is 1 carbon, 4 hydrogen and 4 oxygen atoms on each side.","sol":"Step 1: Carbon is already balanced with 1 C on each side.\nStep 2: CH₄ contains 4 hydrogen atoms, so put 2 before H₂O.\nStep 3: Products now contain 4 oxygen atoms.\nStep 4: Put 2 before O₂.\nStep 5: Check all elements.","steps":["Step 1: Carbon is already balanced with 1 C on each side.","Step 2: CH₄ contains 4 hydrogen atoms, so put 2 before H₂O.","Step 3: Products now contain 4 oxygen atoms.","Step 4: Put 2 before O₂.","Step 5: Check all elements."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_more_complex_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing More Complex Equations"}', 2),
  (1995, 505, 'Balance: N₂ + H₂ → NH₃.', 'text', 1, 'Balance nitrogen first, then hydrogen.', '{"why":"There are 2 nitrogen atoms and 6 hydrogen atoms on both sides.","sol":"Step 1: N₂ contains 2 nitrogen atoms.\nStep 2: Put 2 before NH₃.\nStep 3: There are now 6 hydrogen atoms on the right.\nStep 4: Put 3 before H₂.\nStep 5: Check nitrogen and hydrogen.","steps":["Step 1: N₂ contains 2 nitrogen atoms.","Step 2: Put 2 before NH₃.","Step 3: There are now 6 hydrogen atoms on the right.","Step 4: Put 3 before H₂.","Step 5: Check nitrogen and hydrogen."],"options":[],"conceptId":"chemistry_chemical_reactions_balancing_more_complex_equations","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Balancing More Complex Equations"}', 3),
  (1996, 506, 'What is a combination reaction?', 'text', 1, 'Focus on the core principle of Combination Reactions.', '{"why":"The defining feature is the formation of a single product from multiple reactants.","sol":"Step 1: Identify the number of reactants.\nStep 2: Two or more substances react together.\nStep 3: They form one product.","steps":["Step 1: Identify the number of reactants.","Step 2: Two or more substances react together.","Step 3: They form one product."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 0),
  (1997, 506, 'Classify: 2Mg + O₂ → 2MgO.', 'text', 1, 'Focus on the core principle of Combination Reactions.', '{"why":"Two reactants combine to form one product.","sol":"Step 1: There are two reactants: Mg and O₂.\nStep 2: There is one product: MgO.\nStep 3: Therefore it is a combination reaction.","steps":["Step 1: There are two reactants: Mg and O₂.","Step 2: There is one product: MgO.","Step 3: Therefore it is a combination reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 1),
  (1998, 506, 'Write a balanced equation for iron reacting with sulphur to form iron(II) sulphide.', 'text', 1, 'Focus on the core principle of Combination Reactions.', '{"why":"Iron and sulphur combine to form one product.","sol":"Step 1: Iron = Fe.\nStep 2: Sulphur = S.\nStep 3: Iron(II) sulphide = FeS.\nStep 4: Write Fe + S → FeS.\nStep 5: The atoms are already balanced.","steps":["Step 1: Iron = Fe.","Step 2: Sulphur = S.","Step 3: Iron(II) sulphide = FeS.","Step 4: Write Fe + S → FeS.","Step 5: The atoms are already balanced."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 2),
  (1999, 506, 'Is CaO + H₂O → Ca(OH)₂ a combination reaction?', 'text', 1, 'Count the reactants and products.', '{"why":"Two substances combine to form a single product.","sol":"Step 1: CaO and H₂O are two reactants.\nStep 2: Ca(OH)₂ is one product.\nStep 3: Therefore the reaction is a combination reaction.","steps":["Step 1: CaO and H₂O are two reactants.","Step 2: Ca(OH)₂ is one product.","Step 3: Therefore the reaction is a combination reaction."],"options":[],"conceptId":"chemistry_chemical_reactions_combination_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Combination Reactions"}', 3),
  (2000, 507, 'What is a decomposition reaction?', 'text', 1, 'Focus on the core principle of Decomposition Reactions.', '{"why":"The reactant is decomposed into simpler products.","sol":"Step 1: Start with one compound.\nStep 2: The compound breaks down.\nStep 3: Two or more simpler substances are formed.","steps":["Step 1: Start with one compound.","Step 2: The compound breaks down.","Step 3: Two or more simpler substances are formed."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 0);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2001, 507, 'Classify: CaCO₃ → CaO + CO₂.', 'text', 1, 'Focus on the core principle of Decomposition Reactions.', '{"why":"One compound breaks down into two products.","sol":"Step 1: There is one reactant, CaCO₃.\nStep 2: There are two products, CaO and CO₂.\nStep 3: Therefore it is decomposition.","steps":["Step 1: There is one reactant, CaCO₃.","Step 2: There are two products, CaO and CO₂.","Step 3: Therefore it is decomposition."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 1),
  (2002, 507, 'Write the products formed when copper(II) carbonate decomposes: CuCO₃ → ?', 'text', 1, 'Focus on the core principle of Decomposition Reactions.', '{"why":"Metal carbonates commonly decompose on heating to form the metal oxide and carbon dioxide.","sol":"Step 1: A metal carbonate decomposes to form the metal oxide and carbon dioxide.\nStep 2: Copper(II) carbonate forms copper(II) oxide.\nStep 3: Carbon dioxide is also produced.","steps":["Step 1: A metal carbonate decomposes to form the metal oxide and carbon dioxide.","Step 2: Copper(II) carbonate forms copper(II) oxide.","Step 3: Carbon dioxide is also produced."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 2),
  (2003, 507, 'Classify: 2KClO₃ → 2KCl + 3O₂.', 'text', 1, 'Look at the number of reactants and products.', '{"why":"One compound breaks down into simpler substances.","sol":"Step 1: There is one reactant, KClO₃.\nStep 2: Two products are formed.\nStep 3: Therefore it is decomposition.","steps":["Step 1: There is one reactant, KClO₃.","Step 2: Two products are formed.","Step 3: Therefore it is decomposition."],"options":[],"conceptId":"chemistry_chemical_reactions_decomposition_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Decomposition Reactions"}', 3),
  (2004, 508, 'What is a displacement reaction?', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"The relative reactivity of the elements determines whether displacement occurs.","sol":"Step 1: An element reacts with a compound.\nStep 2: The more reactive element replaces a less reactive element.\nStep 3: A new compound and displaced element are formed.","steps":["Step 1: An element reacts with a compound.","Step 2: The more reactive element replaces a less reactive element.","Step 3: A new compound and displaced element are formed."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 0),
  (2005, 508, 'Explain why zinc displaces copper from copper(II) sulphate.', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"A more reactive metal can displace a less reactive metal from its compound.","sol":"Step 1: Zinc is higher than copper in the reactivity series.\nStep 2: Therefore zinc is more reactive than copper.\nStep 3: Zinc can displace copper from CuSO₄.","steps":["Step 1: Zinc is higher than copper in the reactivity series.","Step 2: Therefore zinc is more reactive than copper.","Step 3: Zinc can displace copper from CuSO₄."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 1),
  (2006, 508, 'Complete and balance: Zn + CuSO₄ → ?', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"Zinc replaces copper while the sulphate group remains together.","sol":"Step 1: Zinc displaces copper.\nStep 2: The products are ZnSO₄ and Cu.\nStep 3: Write the equation.\nStep 4: Check the atoms.","steps":["Step 1: Zinc displaces copper.","Step 2: The products are ZnSO₄ and Cu.","Step 3: Write the equation.","Step 4: Check the atoms."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 2),
  (2007, 508, 'Will copper displace zinc from zinc sulphate? Explain.', 'text', 1, 'Compare copper and zinc in the reactivity series.', '{"why":"Displacement requires the free element to be more reactive than the element it replaces.","sol":"Step 1: Zinc is more reactive than copper.\nStep 2: Copper is less reactive than zinc.\nStep 3: A less reactive metal cannot displace a more reactive metal.","steps":["Step 1: Zinc is more reactive than copper.","Step 2: Copper is less reactive than zinc.","Step 3: A less reactive metal cannot displace a more reactive metal."],"options":[],"conceptId":"chemistry_chemical_reactions_displacement_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Displacement Reactions"}', 3),
  (2008, 509, 'What is neutralisation?', 'text', 1, 'Focus on the core principle of Neutralisation Reactions.', '{"why":"The acidic and basic properties are neutralised during the reaction.","sol":"Step 1: An acid reacts with a base or alkali.\nStep 2: The reaction forms a salt.\nStep 3: Water is also formed.","steps":["Step 1: An acid reacts with a base or alkali.","Step 2: The reaction forms a salt.","Step 3: Water is also formed."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 0),
  (2009, 509, 'Complete: HCl + NaOH → ?', 'text', 1, 'Focus on the core principle of Neutralisation Reactions.', '{"why":"Hydrochloric acid and sodium hydroxide undergo neutralisation.","sol":"Step 1: HCl is hydrochloric acid.\nStep 2: NaOH is sodium hydroxide.\nStep 3: The salt formed is sodium chloride, NaCl.\nStep 4: Water, H₂O, is also formed.","steps":["Step 1: HCl is hydrochloric acid.","Step 2: NaOH is sodium hydroxide.","Step 3: The salt formed is sodium chloride, NaCl.","Step 4: Water, H₂O, is also formed."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 1),
  (2010, 509, 'Balance: H₂SO₄ + NaOH → Na₂SO₄ + H₂O.', 'text', 1, 'Focus on the core principle of Neutralisation Reactions.', '{"why":"The atoms of every element are equal on both sides.","sol":"Step 1: Na₂SO₄ requires 2 sodium atoms.\nStep 2: Put 2 before NaOH.\nStep 3: There are now 2 OH groups, forming 2H₂O.\nStep 4: Check hydrogen and oxygen.","steps":["Step 1: Na₂SO₄ requires 2 sodium atoms.","Step 2: Put 2 before NaOH.","Step 3: There are now 2 OH groups, forming 2H₂O.","Step 4: Check hydrogen and oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 2),
  (2011, 509, 'What type of reaction occurs between hydrochloric acid and sodium hydroxide?', 'text', 1, 'An acid reacts with an alkali.', '{"why":"An acid reacting with an alkali to form salt and water is neutralisation.","sol":"Step 1: Hydrochloric acid is an acid.\nStep 2: Sodium hydroxide is an alkali.\nStep 3: Acid + alkali gives salt + water.","steps":["Step 1: Hydrochloric acid is an acid.","Step 2: Sodium hydroxide is an alkali.","Step 3: Acid + alkali gives salt + water."],"options":[],"conceptId":"chemistry_chemical_reactions_neutralisation_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Neutralisation Reactions"}', 3),
  (2012, 510, 'What is combustion?', 'text', 1, 'Focus on the core principle of Combustion Reactions.', '{"why":"Burning is a chemical reaction involving oxygen and energy release.","sol":"Step 1: A substance reacts with oxygen.\nStep 2: Energy is released.\nStep 3: This process is called combustion.","steps":["Step 1: A substance reacts with oxygen.","Step 2: Energy is released.","Step 3: This process is called combustion."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q1","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 0),
  (2013, 510, 'What are the products of complete combustion of a hydrocarbon?', 'text', 1, 'Focus on the core principle of Combustion Reactions.', '{"why":"With sufficient oxygen, carbon is fully oxidised to CO₂ and hydrogen forms H₂O.","sol":"Step 1: A hydrocarbon contains carbon and hydrogen.\nStep 2: In complete combustion, carbon forms carbon dioxide.\nStep 3: Hydrogen forms water.","steps":["Step 1: A hydrocarbon contains carbon and hydrogen.","Step 2: In complete combustion, carbon forms carbon dioxide.","Step 3: Hydrogen forms water."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q2","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 1),
  (2014, 510, 'Balance: CH₄ + O₂ → CO₂ + H₂O.', 'text', 1, 'Focus on the core principle of Combustion Reactions.', '{"why":"The balanced equation has equal numbers of C, H and O atoms on both sides.","sol":"Step 1: Carbon is already balanced.\nStep 2: There are 4 hydrogen atoms in CH₄, so put 2 before H₂O.\nStep 3: Products now contain 4 oxygen atoms.\nStep 4: Put 2 before O₂.","steps":["Step 1: Carbon is already balanced.","Step 2: There are 4 hydrogen atoms in CH₄, so put 2 before H₂O.","Step 3: Products now contain 4 oxygen atoms.","Step 4: Put 2 before O₂."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q3","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 2),
  (2015, 510, 'What two substances are needed for combustion to occur?', 'text', 1, 'Think about what is required for burning.', '{"why":"Oxygen supports combustion and reacts with the substance being burned.","sol":"Step 1: Combustion is burning.\nStep 2: Burning requires a substance that can burn.\nStep 3: It also requires oxygen.","steps":["Step 1: Combustion is burning.","Step 2: Burning requires a substance that can burn.","Step 3: It also requires oxygen."],"options":[],"conceptId":"chemistry_chemical_reactions_combustion_reactions","skillId":"chemistry_chemical_reactions","subskillId":"chemistry_chemical_reactions_q4","subject":"chemistry","chapter":"chemical_reactions","topic":"Combustion Reactions"}', 3),
  (2016, 511, 'State three properties of acids.', 'text', 1, 'Focus on the core principle of Properties of Acids.', '{"why":"These are characteristic properties of acidic substances.","sol":"Step 1: Acids have pH values below 7.\nStep 2: They turn blue litmus red.\nStep 3: They react with suitable metals, carbonates and bases.","steps":["Step 1: Acids have pH values below 7.","Step 2: They turn blue litmus red.","Step 3: They react with suitable metals, carbonates and bases."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 0),
  (2017, 511, 'What ion is responsible for the acidic nature of an aqueous acid?', 'text', 1, 'Focus on the core principle of Properties of Acids.', '{"why":"The presence of hydrogen ions gives aqueous acids their acidic properties.","sol":"Step 1: An acid dissolves in water.\nStep 2: It produces hydrogen ions.\nStep 3: The hydrogen ion is H⁺.","steps":["Step 1: An acid dissolves in water.","Step 2: It produces hydrogen ions.","Step 3: The hydrogen ion is H⁺."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 1),
  (2018, 511, 'What happens to blue litmus paper in an acidic solution?', 'text', 1, 'Focus on the core principle of Properties of Acids.', '{"why":"Litmus is an indicator that changes colour according to whether a solution is acidic or basic.","sol":"Step 1: Place blue litmus paper in the acid.\nStep 2: Acidic conditions affect the indicator.\nStep 3: Blue litmus changes to red.","steps":["Step 1: Place blue litmus paper in the acid.","Step 2: Acidic conditions affect the indicator.","Step 3: Blue litmus changes to red."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 2),
  (2019, 511, 'A solution has a pH of 3. Is it acidic or basic?', 'text', 1, 'Compare its pH with 7.', '{"why":"A pH value below 7 indicates an acidic solution.","sol":"Step 1: Neutral solutions have pH 7.\nStep 2: A pH below 7 is acidic.\nStep 3: Therefore pH 3 is acidic.","steps":["Step 1: Neutral solutions have pH 7.","Step 2: A pH below 7 is acidic.","Step 3: Therefore pH 3 is acidic."],"options":[],"conceptId":"chemistry_acids_bases_salts_properties_of_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Properties of Acids"}', 3),
  (2020, 512, 'What are the products when a suitable metal reacts with a dilute acid?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metals.', '{"why":"This is the characteristic reaction of suitable metals with dilute acids.","sol":"Step 1: Identify the reaction pattern.\nStep 2: The acid reacts with the metal.\nStep 3: A salt and hydrogen gas are formed.","steps":["Step 1: Identify the reaction pattern.","Step 2: The acid reacts with the metal.","Step 3: A salt and hydrogen gas are formed."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 0),
  (2021, 512, 'Write the balanced equation for magnesium reacting with hydrochloric acid.', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metals.', '{"why":"Two HCl molecules provide two chlorine atoms for MgCl₂ and two hydrogen atoms for H₂.","sol":"Step 1: Magnesium = Mg.\nStep 2: Hydrochloric acid = HCl.\nStep 3: Magnesium chloride = MgCl₂.\nStep 4: Hydrogen = H₂.\nStep 5: Balance the chlorine and hydrogen atoms.","steps":["Step 1: Magnesium = Mg.","Step 2: Hydrochloric acid = HCl.","Step 3: Magnesium chloride = MgCl₂.","Step 4: Hydrogen = H₂.","Step 5: Balance the chlorine and hydrogen atoms."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 1),
  (2022, 512, 'What gas is produced when zinc reacts with dilute sulphuric(VI) acid?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metals.', '{"why":"Suitable metals reacting with dilute acids produce hydrogen gas.","sol":"Step 1: Zinc reacts with dilute sulphuric(VI) acid.\nStep 2: The general reaction is acid + metal → salt + hydrogen.\nStep 3: Therefore the gas is hydrogen.","steps":["Step 1: Zinc reacts with dilute sulphuric(VI) acid.","Step 2: The general reaction is acid + metal → salt + hydrogen.","Step 3: Therefore the gas is hydrogen."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 2),
  (2023, 512, 'How can the gas produced when magnesium reacts with dilute hydrochloric acid be identified?', 'text', 1, 'Use the standard test for hydrogen.', '{"why":"The pop test is the standard laboratory test for hydrogen.","sol":"Step 1: Collect the gas.\nStep 2: Bring a lighted splint to the gas.\nStep 3: Hydrogen burns with a characteristic ''pop'' sound.","steps":["Step 1: Collect the gas.","Step 2: Bring a lighted splint to the gas.","Step 3: Hydrogen burns with a characteristic ''pop'' sound."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metals"}', 3),
  (2024, 513, 'What are the products of the reaction between an acid and a carbonate?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Carbonates.', '{"why":"Carbonates release carbon dioxide when they react with acids.","sol":"Step 1: An acid reacts with a carbonate.\nStep 2: The products are a salt, water and carbon dioxide.","steps":["Step 1: An acid reacts with a carbonate.","Step 2: The products are a salt, water and carbon dioxide."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 0),
  (2025, 513, 'Write the balanced equation for calcium carbonate reacting with hydrochloric acid.', 'text', 1, 'Focus on the core principle of Reactions of Acids with Carbonates.', '{"why":"The atoms of Ca, C, O, H and Cl are equal on both sides.","sol":"Step 1: Calcium carbonate = CaCO₃.\nStep 2: Hydrochloric acid = HCl.\nStep 3: Products are calcium chloride, water and carbon dioxide.\nStep 4: Balance the equation.","steps":["Step 1: Calcium carbonate = CaCO₃.","Step 2: Hydrochloric acid = HCl.","Step 3: Products are calcium chloride, water and carbon dioxide.","Step 4: Balance the equation."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 1),
  (2026, 513, 'How can carbon dioxide produced in this reaction be tested?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Carbonates.', '{"why":"Carbon dioxide reacts with calcium hydroxide in limewater to form insoluble calcium carbonate.","sol":"Step 1: Pass the gas into limewater.\nStep 2: Observe the limewater.\nStep 3: Carbon dioxide turns limewater milky.","steps":["Step 1: Pass the gas into limewater.","Step 2: Observe the limewater.","Step 3: Carbon dioxide turns limewater milky."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 2),
  (2027, 513, 'A carbonate reacts with hydrochloric acid and produces fizzing. What gas causes the fizzing?', 'text', 1, 'Think about the products of acid + carbonate.', '{"why":"Carbon dioxide gas is released during the reaction.","sol":"Step 1: Acid + carbonate produces salt, water and carbon dioxide.\nStep 2: Carbon dioxide is gaseous.\nStep 3: The gas escaping causes the fizzing.","steps":["Step 1: Acid + carbonate produces salt, water and carbon dioxide.","Step 2: Carbon dioxide is gaseous.","Step 3: The gas escaping causes the fizzing."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Carbonates"}', 3),
  (2028, 514, 'What products are formed when an acid reacts with a hydrogen carbonate?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Hydrogen Carbonates.', '{"why":"Hydrogen carbonates react with acids in the same characteristic pattern as carbonates.","sol":"Step 1: Identify the reaction as acid + hydrogen carbonate.\nStep 2: The hydrogen carbonate releases carbon dioxide.\nStep 3: The products are salt, water and carbon dioxide.","steps":["Step 1: Identify the reaction as acid + hydrogen carbonate.","Step 2: The hydrogen carbonate releases carbon dioxide.","Step 3: The products are salt, water and carbon dioxide."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 0),
  (2029, 514, 'Write the equation for sodium hydrogen carbonate reacting with hydrochloric acid.', 'text', 1, 'Focus on the core principle of Reactions of Acids with Hydrogen Carbonates.', '{"why":"The equation represents the reaction of a hydrogen carbonate with an acid.","sol":"Step 1: Sodium hydrogen carbonate = NaHCO₃.\nStep 2: Hydrochloric acid = HCl.\nStep 3: Sodium chloride = NaCl.\nStep 4: The other products are water and carbon dioxide.","steps":["Step 1: Sodium hydrogen carbonate = NaHCO₃.","Step 2: Hydrochloric acid = HCl.","Step 3: Sodium chloride = NaCl.","Step 4: The other products are water and carbon dioxide."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 1),
  (2030, 514, 'What observation occurs when sodium hydrogen carbonate reacts with hydrochloric acid?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Hydrogen Carbonates.', '{"why":"The escaping gas produces visible bubbles.","sol":"Step 1: The reaction produces carbon dioxide.\nStep 2: Carbon dioxide escapes as bubbles.\nStep 3: Therefore effervescence is observed.","steps":["Step 1: The reaction produces carbon dioxide.","Step 2: Carbon dioxide escapes as bubbles.","Step 3: Therefore effervescence is observed."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 2),
  (2031, 514, 'How would you distinguish the gas produced from hydrogen?', 'text', 1, 'Use limewater.', '{"why":"The limewater test distinguishes carbon dioxide from hydrogen.","sol":"Step 1: Pass the gas into limewater.\nStep 2: Carbon dioxide turns limewater milky.\nStep 3: Hydrogen does not turn limewater milky.","steps":["Step 1: Pass the gas into limewater.","Step 2: Carbon dioxide turns limewater milky.","Step 3: Hydrogen does not turn limewater milky."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_hydrogen_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Hydrogen Carbonates"}', 3),
  (2032, 515, 'What products are formed when an acid reacts with a metal oxide?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metal Oxides.', '{"why":"Metal oxides neutralise acids to form salts and water.","sol":"Step 1: Identify the reaction as acid + metal oxide.\nStep 2: The products are a salt and water.","steps":["Step 1: Identify the reaction as acid + metal oxide.","Step 2: The products are a salt and water."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 0),
  (2033, 515, 'Write the equation for copper(II) oxide reacting with sulphuric(VI) acid.', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metal Oxides.', '{"why":"The reaction is an acid-metal oxide neutralisation.","sol":"Step 1: Copper(II) oxide = CuO.\nStep 2: Sulphuric(VI) acid = H₂SO₄.\nStep 3: Copper(II) sulphate = CuSO₄.\nStep 4: Water is also formed.","steps":["Step 1: Copper(II) oxide = CuO.","Step 2: Sulphuric(VI) acid = H₂SO₄.","Step 3: Copper(II) sulphate = CuSO₄.","Step 4: Water is also formed."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 1),
  (2034, 515, 'Why does copper(II) oxide react with an acid even though it is not an alkali?', 'text', 1, 'Focus on the core principle of Reactions of Acids with Metal Oxides.', '{"why":"Basic metal oxides can neutralise acids.","sol":"Step 1: Copper(II) oxide is a basic metal oxide.\nStep 2: Basic oxides react with acids.\nStep 3: The products are a salt and water.","steps":["Step 1: Copper(II) oxide is a basic metal oxide.","Step 2: Basic oxides react with acids.","Step 3: The products are a salt and water."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 2),
  (2035, 515, 'What type of reaction occurs between CuO and H₂SO₄?', 'text', 1, 'Identify what an acid reacts with.', '{"why":"The basic metal oxide neutralises the acid.","sol":"Step 1: H₂SO₄ is an acid.\nStep 2: CuO is a metal oxide.\nStep 3: Acid + metal oxide gives salt + water.","steps":["Step 1: H₂SO₄ is an acid.","Step 2: CuO is a metal oxide.","Step 3: Acid + metal oxide gives salt + water."],"options":[],"conceptId":"chemistry_acids_bases_salts_reactions_of_acids_with_metal_oxides","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Reactions of Acids with Metal Oxides"}', 3),
  (2036, 516, 'What is a base?', 'text', 1, 'Focus on the core principle of Bases.', '{"why":"The ability to neutralise acids is a defining chemical property of bases.","sol":"Step 1: A base reacts with an acid.\nStep 2: The reaction forms a salt and water.\nStep 3: Therefore a base can neutralise an acid.","steps":["Step 1: A base reacts with an acid.","Step 2: The reaction forms a salt and water.","Step 3: Therefore a base can neutralise an acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 0),
  (2037, 516, 'Give two examples of bases.', 'text', 1, 'Focus on the core principle of Bases.', '{"why":"Both are basic metal oxides.","sol":"Step 1: Metal oxides and hydroxides can be bases.\nStep 2: Examples include CuO and MgO.","steps":["Step 1: Metal oxides and hydroxides can be bases.","Step 2: Examples include CuO and MgO."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 1),
  (2038, 516, 'What is the difference between a base and an alkali?', 'text', 1, 'Focus on the core principle of Bases.', '{"why":"Solubility in water distinguishes alkalis from insoluble bases.","sol":"Step 1: A base can neutralise an acid.\nStep 2: An alkali is a base that dissolves in water.\nStep 3: Therefore not every base is necessarily an alkali.","steps":["Step 1: A base can neutralise an acid.","Step 2: An alkali is a base that dissolves in water.","Step 3: Therefore not every base is necessarily an alkali."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 2),
  (2039, 516, 'Is copper(II) oxide an alkali?', 'text', 1, 'Consider whether it dissolves in water.', '{"why":"Alkalis are water-soluble bases.","sol":"Step 1: CuO is a base.\nStep 2: It is not soluble in water.\nStep 3: Therefore it is not an alkali.","steps":["Step 1: CuO is a base.","Step 2: It is not soluble in water.","Step 3: Therefore it is not an alkali."],"options":[],"conceptId":"chemistry_acids_bases_salts_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Bases"}', 3),
  (2040, 517, 'What is an alkali?', 'text', 1, 'Focus on the core principle of Alkalis.', '{"why":"Soluble bases form alkaline solutions.","sol":"Step 1: Start with the definition of a base.\nStep 2: Consider its solubility in water.\nStep 3: A soluble base is called an alkali.","steps":["Step 1: Start with the definition of a base.","Step 2: Consider its solubility in water.","Step 3: A soluble base is called an alkali."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 0),
  (2041, 517, 'What ion is associated with alkaline solutions?', 'text', 1, 'Focus on the core principle of Alkalis.', '{"why":"Hydroxide ions are responsible for alkaline properties.","sol":"Step 1: Alkalis dissolve in water.\nStep 2: They produce hydroxide ions.\nStep 3: Hydroxide ions are OH⁻.","steps":["Step 1: Alkalis dissolve in water.","Step 2: They produce hydroxide ions.","Step 3: Hydroxide ions are OH⁻."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 1),
  (2042, 517, 'Is sodium hydroxide an alkali?', 'text', 1, 'Focus on the core principle of Alkalis.', '{"why":"NaOH dissolves in water and produces hydroxide ions.","sol":"Step 1: Sodium hydroxide is NaOH.\nStep 2: NaOH dissolves in water.\nStep 3: Therefore it is a soluble base.","steps":["Step 1: Sodium hydroxide is NaOH.","Step 2: NaOH dissolves in water.","Step 3: Therefore it is a soluble base."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 2),
  (2043, 517, 'A solution has a pH of 11. Is it likely to be an alkali?', 'text', 1, 'Compare the pH with 7.', '{"why":"Alkaline solutions have pH values above 7.","sol":"Step 1: pH 7 is neutral.\nStep 2: Values above 7 are alkaline.\nStep 3: pH 11 is therefore alkaline.","steps":["Step 1: pH 7 is neutral.","Step 2: Values above 7 are alkaline.","Step 3: pH 11 is therefore alkaline."],"options":[],"conceptId":"chemistry_acids_bases_salts_alkalis","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Alkalis"}', 3),
  (2044, 518, 'What happens to blue litmus in an acid?', 'text', 1, 'Focus on the core principle of Litmus.', '{"why":"This is the characteristic litmus response to an acid.","sol":"Step 1: Blue litmus is placed in the acidic solution.\nStep 2: Acidic conditions change its colour.\nStep 3: It turns red.","steps":["Step 1: Blue litmus is placed in the acidic solution.","Step 2: Acidic conditions change its colour.","Step 3: It turns red."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 0),
  (2045, 518, 'What happens to red litmus in an alkali?', 'text', 1, 'Focus on the core principle of Litmus.', '{"why":"This is the characteristic litmus response to an alkali.","sol":"Step 1: Red litmus is placed in the alkaline solution.\nStep 2: The alkaline conditions change its colour.\nStep 3: It turns blue.","steps":["Step 1: Red litmus is placed in the alkaline solution.","Step 2: The alkaline conditions change its colour.","Step 3: It turns blue."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 1),
  (2046, 518, 'What happens to litmus in a neutral solution?', 'text', 1, 'Focus on the core principle of Litmus.', '{"why":"Litmus changes colour in acidic or alkaline conditions.","sol":"Step 1: A neutral solution does not have acidic or alkaline properties.\nStep 2: Litmus therefore does not undergo the acid or alkali colour change.","steps":["Step 1: A neutral solution does not have acidic or alkaline properties.","Step 2: Litmus therefore does not undergo the acid or alkali colour change."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 2),
  (2047, 518, 'A solution turns red litmus blue. What does this tell you?', 'text', 1, 'Think about what causes red litmus to turn blue.', '{"why":"Alkaline solutions turn red litmus blue.","sol":"Step 1: Red litmus turns blue in an alkaline solution.\nStep 2: Therefore the solution is alkaline.","steps":["Step 1: Red litmus turns blue in an alkaline solution.","Step 2: Therefore the solution is alkaline."],"options":[],"conceptId":"chemistry_acids_bases_salts_litmus","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Litmus"}', 3),
  (2048, 519, 'What is universal indicator used for?', 'text', 1, 'Focus on the core principle of Universal Indicator.', '{"why":"Universal indicator gives different colours across the pH scale.","sol":"Step 1: Universal indicator changes colour in different solutions.\nStep 2: Its colour is compared with a pH chart.\nStep 3: This gives an estimate of pH.","steps":["Step 1: Universal indicator changes colour in different solutions.","Step 2: Its colour is compared with a pH chart.","Step 3: This gives an estimate of pH."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 0),
  (2049, 519, 'What colour does universal indicator usually show in a neutral solution?', 'text', 1, 'Focus on the core principle of Universal Indicator.', '{"why":"Green corresponds approximately to neutral pH 7.","sol":"Step 1: Neutral corresponds to pH 7.\nStep 2: Universal indicator is green around pH 7.","steps":["Step 1: Neutral corresponds to pH 7.","Step 2: Universal indicator is green around pH 7."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 1),
  (2050, 519, 'A solution turns universal indicator purple. What does this suggest?', 'text', 1, 'Focus on the core principle of Universal Indicator.', '{"why":"Purple corresponds to a high pH.","sol":"Step 1: Purple occurs at the alkaline end of the universal indicator scale.\nStep 2: Therefore the solution is strongly alkaline.","steps":["Step 1: Purple occurs at the alkaline end of the universal indicator scale.","Step 2: Therefore the solution is strongly alkaline."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 2),
  (2051, 519, 'Universal indicator turns orange in a solution. Is the solution acidic or alkaline?', 'text', 1, 'Orange occurs below pH 7.', '{"why":"Orange indicates an acidic pH.","sol":"Step 1: Orange is found on the acidic side of the indicator scale.\nStep 2: Therefore the solution is acidic.","steps":["Step 1: Orange is found on the acidic side of the indicator scale.","Step 2: Therefore the solution is acidic."],"options":[],"conceptId":"chemistry_acids_bases_salts_universal_indicator","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Universal Indicator"}', 3),
  (2052, 520, 'What does a pH of 7 indicate?', 'text', 1, 'Focus on the core principle of pH Scale.', '{"why":"pH 7 is conventionally neutral at ordinary conditions.","sol":"Step 1: Locate 7 on the pH scale.\nStep 2: pH 7 represents the neutral point.","steps":["Step 1: Locate 7 on the pH scale.","Step 2: pH 7 represents the neutral point."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 0),
  (2053, 520, 'Classify pH 2, pH 7 and pH 12.', 'text', 1, 'Focus on the core principle of pH Scale.', '{"why":"The position of a pH value relative to 7 determines whether the solution is acidic, neutral or alkaline.","sol":"Step 1: Values below 7 are acidic.\nStep 2: 7 is neutral.\nStep 3: Values above 7 are alkaline.","steps":["Step 1: Values below 7 are acidic.","Step 2: 7 is neutral.","Step 3: Values above 7 are alkaline."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 1),
  (2054, 520, 'Which is more acidic: a solution of pH 2 or pH 5?', 'text', 1, 'Focus on the core principle of pH Scale.', '{"why":"A lower pH indicates greater acidity.","sol":"Step 1: Both values are below 7.\nStep 2: Lower pH means greater acidity.\nStep 3: 2 is lower than 5.","steps":["Step 1: Both values are below 7.","Step 2: Lower pH means greater acidity.","Step 3: 2 is lower than 5."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 2),
  (2055, 520, 'A solution has pH 9. Classify it.', 'text', 1, 'Compare 9 with 7.', '{"why":"A pH above 7 indicates an alkaline solution.","sol":"Step 1: pH 7 is neutral.\nStep 2: pH 9 is above 7.\nStep 3: Therefore it is alkaline.","steps":["Step 1: pH 7 is neutral.","Step 2: pH 9 is above 7.","Step 3: Therefore it is alkaline."],"options":[],"conceptId":"chemistry_acids_bases_salts_ph_scale","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"pH Scale"}', 3),
  (2056, 521, 'Which solution is more acidic: pH 3 or pH 6?', 'text', 1, 'Focus on the core principle of Interpreting pH.', '{"why":"Lower pH indicates greater acidity.","sol":"Step 1: Both solutions are acidic because both pH values are below 7.\nStep 2: Compare the values.\nStep 3: pH 3 is lower than pH 6.","steps":["Step 1: Both solutions are acidic because both pH values are below 7.","Step 2: Compare the values.","Step 3: pH 3 is lower than pH 6."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 0),
  (2057, 521, 'Which solution is more alkaline: pH 8 or pH 12?', 'text', 1, 'Focus on the core principle of Interpreting pH.', '{"why":"Higher pH indicates greater alkalinity.","sol":"Step 1: Both are above 7 and therefore alkaline.\nStep 2: Compare the values.\nStep 3: pH 12 is higher.","steps":["Step 1: Both are above 7 and therefore alkaline.","Step 2: Compare the values.","Step 3: pH 12 is higher."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 1),
  (2058, 521, 'Arrange these from most acidic to most alkaline: pH 11, pH 3, pH 7, pH 5.', 'text', 1, 'Focus on the core principle of Interpreting pH.', '{"why":"Moving from low to high pH moves from acidic through neutral to alkaline.","sol":"Step 1: The lowest pH is the most acidic.\nStep 2: Order the values from lowest to highest.\nStep 3: 3 < 5 < 7 < 11.","steps":["Step 1: The lowest pH is the most acidic.","Step 2: Order the values from lowest to highest.","Step 3: 3 < 5 < 7 < 11."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 2),
  (2059, 521, 'A solution changes from pH 4 to pH 2. Has its acidity increased or decreased?', 'text', 1, 'Compare the two pH values.', '{"why":"A decrease in pH indicates increased acidity.","sol":"Step 1: The pH decreases from 4 to 2.\nStep 2: Lower pH means greater acidity.","steps":["Step 1: The pH decreases from 4 to 2.","Step 2: Lower pH means greater acidity."],"options":[],"conceptId":"chemistry_acids_bases_salts_interpreting_ph","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Interpreting pH"}', 3),
  (2060, 522, 'What is a strong acid?', 'text', 1, 'Focus on the core principle of Strong and Weak Acids.', '{"why":"Extensive ionisation produces many hydrogen ions in solution.","sol":"Step 1: Consider what happens when the acid dissolves in water.\nStep 2: A strong acid ionises extensively.\nStep 3: This produces a high concentration of H⁺ ions.","steps":["Step 1: Consider what happens when the acid dissolves in water.","Step 2: A strong acid ionises extensively.","Step 3: This produces a high concentration of H⁺ ions."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 0),
  (2061, 522, 'What is a weak acid?', 'text', 1, 'Focus on the core principle of Strong and Weak Acids.', '{"why":"Weak acids establish an equilibrium between ionised and unionised molecules.","sol":"Step 1: A weak acid is dissolved in water.\nStep 2: Only part of its molecules ionise.\nStep 3: Therefore ionisation is incomplete.","steps":["Step 1: A weak acid is dissolved in water.","Step 2: Only part of its molecules ionise.","Step 3: Therefore ionisation is incomplete."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 1),
  (2062, 522, 'Is ethanoic acid strong or weak?', 'text', 1, 'Focus on the core principle of Strong and Weak Acids.', '{"why":"Ethanoic acid undergoes partial ionisation in water.","sol":"Step 1: Ethanoic acid is CH₃COOH.\nStep 2: It ionises only partially in water.\nStep 3: Therefore it is a weak acid.","steps":["Step 1: Ethanoic acid is CH₃COOH.","Step 2: It ionises only partially in water.","Step 3: Therefore it is a weak acid."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 2),
  (2063, 522, 'Explain why a strong acid is not necessarily more concentrated than a weak acid.', 'text', 1, 'Separate the ideas of strength and concentration.', '{"why":"A dilute strong acid and a concentrated weak acid can exist.","sol":"Step 1: Strength describes the extent of ionisation.\nStep 2: Concentration describes the amount of solute in a given volume.\nStep 3: Therefore they describe different properties.","steps":["Step 1: Strength describes the extent of ionisation.","Step 2: Concentration describes the amount of solute in a given volume.","Step 3: Therefore they describe different properties."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_acids","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Acids"}', 3),
  (2064, 523, 'What is a strong base?', 'text', 1, 'Focus on the core principle of Strong and Weak Bases.', '{"why":"Extensive ionisation produces many hydroxide ions.","sol":"Step 1: A strong base is placed in water.\nStep 2: It ionises extensively.\nStep 3: It produces a high concentration of OH⁻ ions.","steps":["Step 1: A strong base is placed in water.","Step 2: It ionises extensively.","Step 3: It produces a high concentration of OH⁻ ions."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 0),
  (2065, 523, 'What is a weak base?', 'text', 1, 'Focus on the core principle of Strong and Weak Bases.', '{"why":"Weak bases do not ionise completely in aqueous solution.","sol":"Step 1: A weak base interacts with water.\nStep 2: Ionisation is only partial.\nStep 3: Therefore fewer hydroxide ions are produced than by a comparable strong base.","steps":["Step 1: A weak base interacts with water.","Step 2: Ionisation is only partial.","Step 3: Therefore fewer hydroxide ions are produced than by a comparable strong base."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 1),
  (2066, 523, 'Is aqueous ammonia a strong or weak base?', 'text', 1, 'Focus on the core principle of Strong and Weak Bases.', '{"why":"Aqueous ammonia is only partially ionised in water.","sol":"Step 1: Ammonia reacts partially with water.\nStep 2: It does not ionise completely.\nStep 3: Therefore it is a weak base.","steps":["Step 1: Ammonia reacts partially with water.","Step 2: It does not ionise completely.","Step 3: Therefore it is a weak base."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 2),
  (2067, 523, 'State the difference between a strong base and a weak base.', 'text', 1, 'Compare their ionisation in water.', '{"why":"The difference is based on the extent of ionisation.","sol":"Step 1: Strong bases ionise extensively.\nStep 2: Weak bases ionise partially.\nStep 3: Therefore the extent of ionisation distinguishes them.","steps":["Step 1: Strong bases ionise extensively.","Step 2: Weak bases ionise partially.","Step 3: Therefore the extent of ionisation distinguishes them."],"options":[],"conceptId":"chemistry_acids_bases_salts_strong_and_weak_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Strong and Weak Bases"}', 3),
  (2068, 524, 'Define neutralisation.', 'text', 1, 'Focus on the core principle of Neutralisation.', '{"why":"The acidic and alkaline properties are neutralised.","sol":"Step 1: An acid reacts with a base or alkali.\nStep 2: A salt is formed.\nStep 3: Water is also formed.","steps":["Step 1: An acid reacts with a base or alkali.","Step 2: A salt is formed.","Step 3: Water is also formed."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 0),
  (2069, 524, 'Write the ionic equation for neutralisation between a strong acid and a strong alkali.', 'text', 1, 'Focus on the core principle of Neutralisation.', '{"why":"This represents the essential chemical change in strong acid–strong alkali neutralisation.","sol":"Step 1: Acids provide H⁺ ions.\nStep 2: Alkalis provide OH⁻ ions.\nStep 3: These ions combine to form water.","steps":["Step 1: Acids provide H⁺ ions.","Step 2: Alkalis provide OH⁻ ions.","Step 3: These ions combine to form water."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 1),
  (2070, 524, 'Write the balanced equation for nitric acid reacting with sodium hydroxide.', 'text', 1, 'Focus on the core principle of Neutralisation.', '{"why":"The acid and alkali react in a 1:1 ratio.","sol":"Step 1: Nitric acid = HNO₃.\nStep 2: Sodium hydroxide = NaOH.\nStep 3: The salt is sodium nitrate, NaNO₃.\nStep 4: Water is formed.\nStep 5: The equation is already balanced.","steps":["Step 1: Nitric acid = HNO₃.","Step 2: Sodium hydroxide = NaOH.","Step 3: The salt is sodium nitrate, NaNO₃.","Step 4: Water is formed.","Step 5: The equation is already balanced."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 2),
  (2071, 524, 'What ions react directly during neutralisation?', 'text', 1, 'Think about the ions supplied by acids and alkalis.', '{"why":"These ions combine to form water.","sol":"Step 1: Acids supply H⁺.\nStep 2: Alkalis supply OH⁻.\nStep 3: H⁺ combines with OH⁻.","steps":["Step 1: Acids supply H⁺.","Step 2: Alkalis supply OH⁻.","Step 3: H⁺ combines with OH⁻."],"options":[],"conceptId":"chemistry_acids_bases_salts_neutralisation","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Neutralisation"}', 3),
  (2072, 525, 'What is a soluble salt?', 'text', 1, 'Focus on the core principle of Soluble Salts.', '{"why":"Solubility refers to the ability of a substance to dissolve in a solvent.","sol":"Step 1: Consider what happens when the salt is added to water.\nStep 2: If it dissolves, it forms an aqueous solution.\nStep 3: Such a salt is called soluble.","steps":["Step 1: Consider what happens when the salt is added to water.","Step 2: If it dissolves, it forms an aqueous solution.","Step 3: Such a salt is called soluble."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 0),
  (2073, 525, 'Give two examples of soluble salts.', 'text', 1, 'Focus on the core principle of Soluble Salts.', '{"why":"Both form aqueous solutions when dissolved in water.","sol":"Step 1: Sodium chloride dissolves in water.\nStep 2: Copper(II) sulphate also dissolves in water.","steps":["Step 1: Sodium chloride dissolves in water.","Step 2: Copper(II) sulphate also dissolves in water."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 1),
  (2074, 525, 'Why can a soluble salt be obtained by crystallisation?', 'text', 1, 'Focus on the core principle of Soluble Salts.', '{"why":"Crystallisation separates a dissolved solid from its solution.","sol":"Step 1: Dissolve the salt in water.\nStep 2: Concentrate the solution by removing some water.\nStep 3: On cooling, crystals of the salt can form.","steps":["Step 1: Dissolve the salt in water.","Step 2: Concentrate the solution by removing some water.","Step 3: On cooling, crystals of the salt can form."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 2),
  (2075, 525, 'Is sodium chloride soluble in water?', 'text', 1, 'Consider ordinary table salt.', '{"why":"Sodium chloride dissolves in water to form an aqueous solution.","sol":"Step 1: Sodium chloride is common table salt.\nStep 2: It dissolves in water.\nStep 3: Therefore it is soluble.","steps":["Step 1: Sodium chloride is common table salt.","Step 2: It dissolves in water.","Step 3: Therefore it is soluble."],"options":[],"conceptId":"chemistry_acids_bases_salts_soluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Soluble Salts"}', 3),
  (2076, 526, 'What is an insoluble salt?', 'text', 1, 'Focus on the core principle of Insoluble Salts.', '{"why":"Its low solubility means that much of the salt remains as a solid.","sol":"Step 1: Add the salt to water.\nStep 2: If it does not dissolve appreciably, it is insoluble.\nStep 3: Therefore its solid remains present.","steps":["Step 1: Add the salt to water.","Step 2: If it does not dissolve appreciably, it is insoluble.","Step 3: Therefore its solid remains present."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 0),
  (2077, 526, 'What is a precipitate?', 'text', 1, 'Focus on the core principle of Insoluble Salts.', '{"why":"The product comes out of solution as a solid.","sol":"Step 1: Two aqueous solutions are mixed.\nStep 2: A new insoluble substance may form.\nStep 3: The insoluble solid is called a precipitate.","steps":["Step 1: Two aqueous solutions are mixed.","Step 2: A new insoluble substance may form.","Step 3: The insoluble solid is called a precipitate."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 1),
  (2078, 526, 'Identify the precipitate in: Pb(NO₃)₂(aq) + 2NaCl(aq) → PbCl₂(s) + 2NaNO₃(aq).', 'text', 1, 'Focus on the core principle of Insoluble Salts.', '{"why":"The solid product is the insoluble precipitate.","sol":"Step 1: Look for the product marked (s).\nStep 2: PbCl₂ is marked (s).\nStep 3: Therefore PbCl₂ is the precipitate.","steps":["Step 1: Look for the product marked (s).","Step 2: PbCl₂ is marked (s).","Step 3: Therefore PbCl₂ is the precipitate."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 2),
  (2079, 526, 'What method is used to separate an insoluble salt formed as a precipitate from the solution?', 'text', 1, 'The solid must be separated from a liquid.', '{"why":"Filtration separates an insoluble solid from a liquid.","sol":"Step 1: The insoluble salt is a solid.\nStep 2: The remaining solution is liquid.\nStep 3: Filtration separates the solid from the liquid.","steps":["Step 1: The insoluble salt is a solid.","Step 2: The remaining solution is liquid.","Step 3: Filtration separates the solid from the liquid."],"options":[],"conceptId":"chemistry_acids_bases_salts_insoluble_salts","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Insoluble Salts"}', 3),
  (2080, 527, 'Why is excess metal added when preparing a soluble salt using an acid and metal?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Metals.', '{"why":"This prevents excess acid from remaining in the salt solution.","sol":"Step 1: The aim is to ensure that all the acid reacts.\nStep 2: Adding excess metal ensures that acid is not left unreacted.\nStep 3: The excess metal can be removed by filtration.","steps":["Step 1: The aim is to ensure that all the acid reacts.","Step 2: Adding excess metal ensures that acid is not left unreacted.","Step 3: The excess metal can be removed by filtration."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 0),
  (2081, 527, 'What method is used to remove excess metal after the reaction?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Metals.', '{"why":"Filtration separates the unreacted solid metal from the salt solution.","sol":"Step 1: The metal is insoluble and remains solid.\nStep 2: The salt is dissolved in the solution.\nStep 3: Filtration removes the excess solid metal.","steps":["Step 1: The metal is insoluble and remains solid.","Step 2: The salt is dissolved in the solution.","Step 3: Filtration removes the excess solid metal."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 1),
  (2082, 527, 'Why is the salt solution concentrated before crystallisation?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Metals.', '{"why":"Crystallisation requires a sufficiently concentrated solution.","sol":"Step 1: A dilute solution contains a large amount of water.\nStep 2: Some water is evaporated.\nStep 3: The solution becomes more concentrated.\nStep 4: Crystals can then form more readily on cooling.","steps":["Step 1: A dilute solution contains a large amount of water.","Step 2: Some water is evaporated.","Step 3: The solution becomes more concentrated.","Step 4: Crystals can then form more readily on cooling."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 2),
  (2083, 527, 'Outline the main steps for preparing magnesium chloride crystals from magnesium and dilute hydrochloric acid.', 'text', 1, 'Think reaction → filtration → concentration → crystallisation.', '{"why":"These steps produce relatively pure magnesium chloride crystals.","sol":"Step 1: Add excess magnesium to dilute hydrochloric acid.\nStep 2: Allow the reaction to finish.\nStep 3: Filter off excess magnesium.\nStep 4: Concentrate the filtrate.\nStep 5: Cool to form crystals.\nStep 6: Filter and dry the crystals.","steps":["Step 1: Add excess magnesium to dilute hydrochloric acid.","Step 2: Allow the reaction to finish.","Step 3: Filter off excess magnesium.","Step 4: Concentrate the filtrate.","Step 5: Cool to form crystals.","Step 6: Filter and dry the crystals."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_metals","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Metals"}', 3),
  (2084, 528, 'Why is an insoluble base added in excess?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Insoluble Bases.', '{"why":"This prevents excess acid from contaminating the salt solution.","sol":"Step 1: The aim is to use up all the acid.\nStep 2: Excess insoluble base remains as a solid.\nStep 3: The excess can be removed by filtration.","steps":["Step 1: The aim is to use up all the acid.","Step 2: Excess insoluble base remains as a solid.","Step 3: The excess can be removed by filtration."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 0),
  (2085, 528, 'Write the equation for preparing copper(II) sulphate from copper(II) oxide and sulphuric(VI) acid.', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Insoluble Bases.', '{"why":"The basic copper(II) oxide neutralises sulphuric(VI) acid.","sol":"Step 1: CuO is copper(II) oxide.\nStep 2: H₂SO₄ is sulphuric(VI) acid.\nStep 3: The salt formed is CuSO₄.\nStep 4: Water is also formed.","steps":["Step 1: CuO is copper(II) oxide.","Step 2: H₂SO₄ is sulphuric(VI) acid.","Step 3: The salt formed is CuSO₄.","Step 4: Water is also formed."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 1),
  (2086, 528, 'Why is filtration necessary after adding excess copper(II) oxide?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Insoluble Bases.', '{"why":"Filtration separates the unreacted solid from the soluble salt solution.","sol":"Step 1: Copper(II) oxide is insoluble.\nStep 2: Any excess remains as a solid.\nStep 3: Filtration removes the solid from the copper(II) sulphate solution.","steps":["Step 1: Copper(II) oxide is insoluble.","Step 2: Any excess remains as a solid.","Step 3: Filtration removes the solid from the copper(II) sulphate solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 2),
  (2087, 528, 'Which type of salt can be prepared using an insoluble metal oxide and an acid?', 'text', 1, 'Consider whether the resulting salt can remain in solution.', '{"why":"The soluble salt remains dissolved after the insoluble base is removed.","sol":"Step 1: The acid reacts with the insoluble base.\nStep 2: A salt and water are formed.\nStep 3: If the salt is soluble, it remains in solution.","steps":["Step 1: The acid reacts with the insoluble base.","Step 2: A salt and water are formed.","Step 3: If the salt is soluble, it remains in solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_insoluble_bases","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Insoluble Bases"}', 3),
  (2088, 529, 'Why is an excess carbonate used when preparing a soluble salt?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Carbonates.', '{"why":"This prevents unreacted acid from remaining in the salt solution.","sol":"Step 1: The carbonate is added to the acid.\nStep 2: Excess carbonate ensures that all the acid reacts.\nStep 3: The remaining solid carbonate can be removed by filtration.","steps":["Step 1: The carbonate is added to the acid.","Step 2: Excess carbonate ensures that all the acid reacts.","Step 3: The remaining solid carbonate can be removed by filtration."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 0),
  (2089, 529, 'Write the equation for calcium carbonate reacting with nitric acid.', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Carbonates.', '{"why":"Two nitric acid molecules are needed to provide the two nitrate ions in calcium nitrate.","sol":"Step 1: Calcium carbonate = CaCO₃.\nStep 2: Nitric acid = HNO₃.\nStep 3: Calcium nitrate = Ca(NO₃)₂.\nStep 4: Water and carbon dioxide are also formed.\nStep 5: Balance the equation.","steps":["Step 1: Calcium carbonate = CaCO₃.","Step 2: Nitric acid = HNO₃.","Step 3: Calcium nitrate = Ca(NO₃)₂.","Step 4: Water and carbon dioxide are also formed.","Step 5: Balance the equation."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 1),
  (2090, 529, 'How do you know that the reaction between an acid and carbonate has finished?', 'text', 1, 'Focus on the core principle of Preparing Soluble Salts from Acids and Carbonates.', '{"why":"The absence of further carbon dioxide production indicates that the acid has been consumed.","sol":"Step 1: Carbonate reacts with acid and produces carbon dioxide.\nStep 2: While acid remains, added carbonate continues to fizz.\nStep 3: When no more fizzing occurs after adding carbonate, the acid has been used up.","steps":["Step 1: Carbonate reacts with acid and produces carbon dioxide.","Step 2: While acid remains, added carbonate continues to fizz.","Step 3: When no more fizzing occurs after adding carbonate, the acid has been used up."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 2),
  (2091, 529, 'What gas must be removed or allowed to escape during this salt preparation?', 'text', 1, 'Acid + carbonate produces three products.', '{"why":"Carbon dioxide is produced during the reaction.","sol":"Step 1: Acid + carbonate produces salt, water and carbon dioxide.\nStep 2: Carbon dioxide is a gas.\nStep 3: It escapes from the reaction mixture.","steps":["Step 1: Acid + carbonate produces salt, water and carbon dioxide.","Step 2: Carbon dioxide is a gas.","Step 3: It escapes from the reaction mixture."],"options":[],"conceptId":"chemistry_acids_bases_salts_preparing_soluble_salts_from_acids_and_carbonates","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Preparing Soluble Salts from Acids and Carbonates"}', 3),
  (2092, 530, 'What is titration used for?', 'text', 1, 'Focus on the core principle of Titration.', '{"why":"The measured volume can be used to calculate unknown quantities or concentrations.","sol":"Step 1: A known volume of one solution is measured.\nStep 2: Another solution is added until the reaction is complete.\nStep 3: The volume required is measured.","steps":["Step 1: A known volume of one solution is measured.","Step 2: Another solution is added until the reaction is complete.","Step 3: The volume required is measured."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q1","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 0),
  (2093, 530, 'A burette reading is 0.20 cm³ initially and 24.60 cm³ finally. Calculate the titre.', 'text', 1, 'Focus on the core principle of Titration.', '{"why":"The titre is the volume delivered from the burette.","sol":"Step 1: Use titre = final reading − initial reading.\nStep 2: Titre = 24.60 − 0.20.\nStep 3: Titre = 24.40 cm³.","steps":["Step 1: Use titre = final reading − initial reading.","Step 2: Titre = 24.60 − 0.20.","Step 3: Titre = 24.40 cm³."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q2","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 1),
  (2094, 530, 'Why is an indicator used during titration?', 'text', 1, 'Focus on the core principle of Titration.', '{"why":"The indicator provides a visible signal that the required reaction point has been reached.","sol":"Step 1: The reaction reaches an end point.\nStep 2: The indicator changes colour near the end point.\nStep 3: This allows the experimenter to know when to stop adding the burette solution.","steps":["Step 1: The reaction reaches an end point.","Step 2: The indicator changes colour near the end point.","Step 3: This allows the experimenter to know when to stop adding the burette solution."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q3","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 2),
  (2095, 530, 'A burette has an initial reading of 1.10 cm³ and a final reading of 25.35 cm³. Calculate the titre.', 'text', 1, 'Titre = final reading − initial reading.', '{"why":"The titre is the volume of solution delivered from the burette.","sol":"Step 1: Final reading = 25.35 cm³.\nStep 2: Initial reading = 1.10 cm³.\nStep 3: Titre = 25.35 − 1.10.\nStep 4: Titre = 24.25 cm³.","steps":["Step 1: Final reading = 25.35 cm³.","Step 2: Initial reading = 1.10 cm³.","Step 3: Titre = 25.35 − 1.10.","Step 4: Titre = 24.25 cm³."],"options":[],"conceptId":"chemistry_acids_bases_salts_titration","skillId":"chemistry_acids_bases_salts","subskillId":"chemistry_acids_bases_salts_q4","subject":"chemistry","chapter":"acids_bases_salts","topic":"Titration"}', 3),
  (2096, 531, 'What is an exothermic reaction?', 'text', 1, 'Focus on the core principle of Exothermic Reactions.', '{"why":"The surroundings receive energy from the reacting substances.","sol":"Step 1: Consider the energy change during the reaction.\nStep 2: Energy is transferred from the reacting system to the surroundings.\nStep 3: Therefore the reaction releases energy.","steps":["Step 1: Consider the energy change during the reaction.","Step 2: Energy is transferred from the reacting system to the surroundings.","Step 3: Therefore the reaction releases energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 0),
  (2097, 531, 'What happens to the temperature of the surroundings during an exothermic reaction?', 'text', 1, 'Focus on the core principle of Exothermic Reactions.', '{"why":"Heat is transferred from the reaction to the surroundings.","sol":"Step 1: An exothermic reaction releases energy.\nStep 2: Some of this energy is transferred as heat.\nStep 3: The surroundings therefore become warmer.","steps":["Step 1: An exothermic reaction releases energy.","Step 2: Some of this energy is transferred as heat.","Step 3: The surroundings therefore become warmer."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 1),
  (2098, 531, 'Give two examples of exothermic reactions.', 'text', 1, 'Focus on the core principle of Exothermic Reactions.', '{"why":"Both processes release energy to their surroundings.","sol":"Step 1: Combustion releases energy.\nStep 2: Acid-alkali neutralisation also releases energy.","steps":["Step 1: Combustion releases energy.","Step 2: Acid-alkali neutralisation also releases energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 2),
  (2099, 531, 'A reaction causes the temperature of the surrounding solution to rise from 22°C to 31°C. Is the reaction likely to be exothermic or endothermic?', 'text', 1, 'Look at whether heat has entered or left the surroundings.', '{"why":"The rise in surrounding temperature indicates that energy was released.","sol":"Step 1: The temperature increased.\nStep 2: This means heat was transferred to the surroundings.\nStep 3: A reaction that releases heat is exothermic.","steps":["Step 1: The temperature increased.","Step 2: This means heat was transferred to the surroundings.","Step 3: A reaction that releases heat is exothermic."],"options":[],"conceptId":"chemistry_energy_rate_reaction_exothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Exothermic Reactions"}', 3),
  (2100, 532, 'What is an endothermic reaction?', 'text', 1, 'Focus on the core principle of Endothermic Reactions.', '{"why":"Energy must enter the reacting system for the reaction to occur.","sol":"Step 1: Consider the direction of energy transfer.\nStep 2: Energy is absorbed by the reacting system.\nStep 3: Therefore the reaction is endothermic.","steps":["Step 1: Consider the direction of energy transfer.","Step 2: Energy is absorbed by the reacting system.","Step 3: Therefore the reaction is endothermic."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 0),
  (2101, 532, 'What usually happens to the temperature of the surroundings during an endothermic reaction?', 'text', 1, 'Focus on the core principle of Endothermic Reactions.', '{"why":"Heat is transferred from the surroundings into the reaction.","sol":"Step 1: The reaction absorbs energy from the surroundings.\nStep 2: The surroundings lose thermal energy.\nStep 3: Their temperature usually decreases.","steps":["Step 1: The reaction absorbs energy from the surroundings.","Step 2: The surroundings lose thermal energy.","Step 3: Their temperature usually decreases."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 1),
  (2102, 532, 'Is thermal decomposition of calcium carbonate endothermic or exothermic?', 'text', 1, 'Focus on the core principle of Endothermic Reactions.', '{"why":"Energy is absorbed during the thermal decomposition.","sol":"Step 1: Calcium carbonate requires heating to decompose.\nStep 2: Energy must be supplied to the reaction.\nStep 3: Therefore the decomposition is endothermic.","steps":["Step 1: Calcium carbonate requires heating to decompose.","Step 2: Energy must be supplied to the reaction.","Step 3: Therefore the decomposition is endothermic."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 2),
  (2103, 532, 'A reaction causes the temperature of the surrounding water to fall from 25°C to 18°C. What type of reaction is this?', 'text', 1, 'The surroundings have lost heat.', '{"why":"An endothermic reaction absorbs energy from the surroundings.","sol":"Step 1: The temperature decreased.\nStep 2: Heat has been removed from the surroundings.\nStep 3: The reaction absorbed that energy.","steps":["Step 1: The temperature decreased.","Step 2: Heat has been removed from the surroundings.","Step 3: The reaction absorbed that energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_endothermic_reactions","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Endothermic Reactions"}', 3),
  (2104, 533, 'What does an energy profile diagram show?', 'text', 1, 'Focus on the core principle of Energy Profile Diagrams.', '{"why":"The diagram allows the energy change and activation energy to be identified.","sol":"Step 1: The diagram represents energy during a reaction.\nStep 2: It shows the energy level of reactants and products.\nStep 3: It also shows the energy barrier between them.","steps":["Step 1: The diagram represents energy during a reaction.","Step 2: It shows the energy level of reactants and products.","Step 3: It also shows the energy barrier between them."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 0),
  (2105, 533, 'Where are the products located relative to the reactants in an exothermic energy profile?', 'text', 1, 'Focus on the core principle of Energy Profile Diagrams.', '{"why":"Energy has been released during the reaction.","sol":"Step 1: An exothermic reaction releases energy.\nStep 2: The products therefore contain less chemical energy than the reactants.\nStep 3: Products are drawn at a lower energy level.","steps":["Step 1: An exothermic reaction releases energy.","Step 2: The products therefore contain less chemical energy than the reactants.","Step 3: Products are drawn at a lower energy level."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 1),
  (2106, 533, 'Where are the products located relative to the reactants in an endothermic energy profile?', 'text', 1, 'Focus on the core principle of Energy Profile Diagrams.', '{"why":"Energy has been absorbed by the reaction.","sol":"Step 1: An endothermic reaction absorbs energy.\nStep 2: The products therefore have more chemical energy than the reactants.\nStep 3: Products are drawn at a higher energy level.","steps":["Step 1: An endothermic reaction absorbs energy.","Step 2: The products therefore have more chemical energy than the reactants.","Step 3: Products are drawn at a higher energy level."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 2),
  (2107, 533, 'On an energy profile, the products are 40 kJ lower than the reactants. What type of reaction is represented?', 'text', 1, 'Products are at a lower energy level.', '{"why":"Products having lower energy than reactants indicates an overall release of energy.","sol":"Step 1: Compare product energy with reactant energy.\nStep 2: Products are lower by 40 kJ.\nStep 3: Energy has been released.","steps":["Step 1: Compare product energy with reactant energy.","Step 2: Products are lower by 40 kJ.","Step 3: Energy has been released."],"options":[],"conceptId":"chemistry_energy_rate_reaction_energy_profile_diagrams","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Energy Profile Diagrams"}', 3),
  (2108, 534, 'What is activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"Particles need sufficient energy to overcome the energy barrier to reaction.","sol":"Step 1: Reacting particles must collide.\nStep 2: The collision must have enough energy.\nStep 3: The minimum required energy is called activation energy.","steps":["Step 1: Reacting particles must collide.","Step 2: The collision must have enough energy.","Step 3: The minimum required energy is called activation energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 0),
  (2109, 534, 'Why does a fuel require a spark before it burns?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"The reaction cannot begin effectively until particles have enough energy to overcome the activation barrier.","sol":"Step 1: Combustion requires activation energy.\nStep 2: The spark supplies enough energy to start the reaction.\nStep 3: Once started, the combustion can release energy.","steps":["Step 1: Combustion requires activation energy.","Step 2: The spark supplies enough energy to start the reaction.","Step 3: Once started, the combustion can release energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 1),
  (2110, 534, 'Does an exothermic reaction require activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"Overall energy release and activation energy describe different parts of the reaction.","sol":"Step 1: Exothermic describes the overall energy change.\nStep 2: Activation energy describes the energy barrier that must be overcome.\nStep 3: Therefore an exothermic reaction can still require activation energy.","steps":["Step 1: Exothermic describes the overall energy change.","Step 2: Activation energy describes the energy barrier that must be overcome.","Step 3: Therefore an exothermic reaction can still require activation energy."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 2),
  (2111, 534, 'A reaction has an activation energy of 80 kJ mol⁻¹. What does this value mean?', 'text', 1, 'Activation energy is the minimum energy needed for successful reaction.', '{"why":"Activation energy is the minimum energy required for successful reaction.","sol":"Step 1: Identify the value: 80 kJ mol⁻¹.\nStep 2: It represents the minimum energy barrier for the reacting particles.\nStep 3: Particles must have sufficient energy to overcome it.","steps":["Step 1: Identify the value: 80 kJ mol⁻¹.","Step 2: It represents the minimum energy barrier for the reacting particles.","Step 3: Particles must have sufficient energy to overcome it."],"options":[],"conceptId":"chemistry_energy_rate_reaction_activation_energy","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Activation Energy"}', 3),
  (2112, 535, 'Define specific heat capacity.', 'text', 1, 'Focus on the core principle of Specific Heat Capacity.', '{"why":"Specific heat capacity measures how much thermal energy a substance requires for a given temperature rise.","sol":"Step 1: Consider a mass of 1 kg.\nStep 2: Consider increasing its temperature by 1°C.\nStep 3: The heat required is its specific heat capacity.","steps":["Step 1: Consider a mass of 1 kg.","Step 2: Consider increasing its temperature by 1°C.","Step 3: The heat required is its specific heat capacity."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 0),
  (2113, 535, 'State the formula used to calculate heat energy from specific heat capacity.', 'text', 1, 'Focus on the core principle of Specific Heat Capacity.', '{"why":"The heat energy depends on mass, specific heat capacity and temperature change.","sol":"Step 1: Identify the quantities involved: mass, specific heat capacity and temperature change.\nStep 2: Combine them using the heat equation.","steps":["Step 1: Identify the quantities involved: mass, specific heat capacity and temperature change.","Step 2: Combine them using the heat equation."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 1),
  (2114, 535, 'What unit is commonly used for specific heat capacity?', 'text', 1, 'Focus on the core principle of Specific Heat Capacity.', '{"why":"The unit represents joules required per kilogram per degree Celsius.","sol":"Step 1: Heat energy is measured in joules.\nStep 2: Mass is measured in kilograms.\nStep 3: Temperature change is measured in degrees Celsius.","steps":["Step 1: Heat energy is measured in joules.","Step 2: Mass is measured in kilograms.","Step 3: Temperature change is measured in degrees Celsius."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 2),
  (2115, 535, 'Calculate the heat required to raise the temperature of 2 kg of water by 5°C if c = 4200 J kg⁻¹ °C⁻¹.', 'text', 1, 'Use Q = mcΔT.', '{"why":"The heat energy is found by multiplying mass, specific heat capacity and temperature change.","sol":"Step 1: m = 2 kg.\nStep 2: c = 4200 J kg⁻¹ °C⁻¹.\nStep 3: ΔT = 5°C.\nStep 4: Q = mcΔT.\nStep 5: Q = 2 × 4200 × 5.\nStep 6: Q = 42,000 J.","steps":["Step 1: m = 2 kg.","Step 2: c = 4200 J kg⁻¹ °C⁻¹.","Step 3: ΔT = 5°C.","Step 4: Q = mcΔT.","Step 5: Q = 2 × 4200 × 5.","Step 6: Q = 42,000 J."],"options":[],"conceptId":"chemistry_energy_rate_reaction_specific_heat_capacity","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Specific Heat Capacity"}', 3),
  (2116, 536, 'Calculate the heat required to raise 0.5 kg of water from 20°C to 60°C. Take c = 4200 J kg⁻¹ °C⁻¹.', 'text', 1, 'Focus on the core principle of Heat Energy Calculations.', '{"why":"The temperature change is 40°C, so Q = 0.5 × 4200 × 40.","sol":"Step 1: m = 0.5 kg.\nStep 2: Temperature change = 60 − 20 = 40°C.\nStep 3: c = 4200 J kg⁻¹ °C⁻¹.\nStep 4: Q = mcΔT.\nStep 5: Q = 0.5 × 4200 × 40.\nStep 6: Q = 84,000 J.","steps":["Step 1: m = 0.5 kg.","Step 2: Temperature change = 60 − 20 = 40°C.","Step 3: c = 4200 J kg⁻¹ °C⁻¹.","Step 4: Q = mcΔT.","Step 5: Q = 0.5 × 4200 × 40.","Step 6: Q = 84,000 J."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 0),
  (2117, 536, 'A substance absorbs 18,000 J of heat. Its mass is 2 kg and its temperature rises by 10°C. Calculate its specific heat capacity.', 'text', 1, 'Focus on the core principle of Heat Energy Calculations.', '{"why":"Specific heat capacity is calculated by dividing heat energy by mass and temperature change.","sol":"Step 1: Q = 18,000 J.\nStep 2: m = 2 kg.\nStep 3: ΔT = 10°C.\nStep 4: c = Q ÷ (mΔT).\nStep 5: c = 18,000 ÷ (2 × 10).\nStep 6: c = 900 J kg⁻¹ °C⁻¹.","steps":["Step 1: Q = 18,000 J.","Step 2: m = 2 kg.","Step 3: ΔT = 10°C.","Step 4: c = Q ÷ (mΔT).","Step 5: c = 18,000 ÷ (2 × 10).","Step 6: c = 900 J kg⁻¹ °C⁻¹."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 1),
  (2118, 536, 'A 1 kg substance has a specific heat capacity of 500 J kg⁻¹ °C⁻¹ and absorbs 10,000 J. Calculate its temperature rise.', 'text', 1, 'Focus on the core principle of Heat Energy Calculations.', '{"why":"The temperature rise depends on the energy supplied, mass and specific heat capacity.","sol":"Step 1: Q = 10,000 J.\nStep 2: m = 1 kg.\nStep 3: c = 500 J kg⁻¹ °C⁻¹.\nStep 4: ΔT = Q ÷ (mc).\nStep 5: ΔT = 10,000 ÷ (1 × 500).\nStep 6: ΔT = 20°C.","steps":["Step 1: Q = 10,000 J.","Step 2: m = 1 kg.","Step 3: c = 500 J kg⁻¹ °C⁻¹.","Step 4: ΔT = Q ÷ (mc).","Step 5: ΔT = 10,000 ÷ (1 × 500).","Step 6: ΔT = 20°C."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 2),
  (2119, 536, 'A 0.2 kg sample is heated from 25°C to 75°C. If c = 1000 J kg⁻¹ °C⁻¹, calculate the heat absorbed.', 'text', 1, 'First calculate ΔT.', '{"why":"The temperature change is 50°C and Q = mcΔT.","sol":"Step 1: ΔT = 75 − 25 = 50°C.\nStep 2: Q = mcΔT.\nStep 3: Q = 0.2 × 1000 × 50.\nStep 4: Q = 10,000 J.","steps":["Step 1: ΔT = 75 − 25 = 50°C.","Step 2: Q = mcΔT.","Step 3: Q = 0.2 × 1000 × 50.","Step 4: Q = 10,000 J."],"options":[],"conceptId":"chemistry_energy_rate_reaction_heat_energy_calculations","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Heat Energy Calculations"}', 3),
  (2120, 537, 'What is specific latent heat of fusion?', 'text', 1, 'Focus on the core principle of Latent Heat of Fusion.', '{"why":"The energy is used for the change of state rather than increasing temperature.","sol":"Step 1: Consider a solid at its melting point.\nStep 2: Energy is supplied without raising its temperature.\nStep 3: The solid changes to liquid.","steps":["Step 1: Consider a solid at its melting point.","Step 2: Energy is supplied without raising its temperature.","Step 3: The solid changes to liquid."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 0),
  (2121, 537, 'State the formula for latent heat of fusion.', 'text', 1, 'Focus on the core principle of Latent Heat of Fusion.', '{"why":"The total latent heat is proportional to the mass undergoing the change of state.","sol":"Step 1: Heat energy depends on mass.\nStep 2: It also depends on the specific latent heat.\nStep 3: Multiply the two quantities.","steps":["Step 1: Heat energy depends on mass.","Step 2: It also depends on the specific latent heat.","Step 3: Multiply the two quantities."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 1),
  (2122, 537, 'Why does the temperature remain constant while a pure substance melts?', 'text', 1, 'Focus on the core principle of Latent Heat of Fusion.', '{"why":"Temperature measures average kinetic energy, while the supplied energy during melting mainly changes potential energy.","sol":"Step 1: Heat is continuously supplied.\nStep 2: The energy is used to overcome attractive forces between particles.\nStep 3: Therefore the average kinetic energy does not increase.","steps":["Step 1: Heat is continuously supplied.","Step 2: The energy is used to overcome attractive forces between particles.","Step 3: Therefore the average kinetic energy does not increase."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 2),
  (2123, 537, 'Calculate the energy required to melt 2 kg of a substance with a specific latent heat of fusion of 300,000 J kg⁻¹.', 'text', 1, 'Use Q = mL_f.', '{"why":"The latent heat is proportional to the mass being melted.","sol":"Step 1: m = 2 kg.\nStep 2: L_f = 300,000 J kg⁻¹.\nStep 3: Q = mL_f.\nStep 4: Q = 2 × 300,000.\nStep 5: Q = 600,000 J.","steps":["Step 1: m = 2 kg.","Step 2: L_f = 300,000 J kg⁻¹.","Step 3: Q = mL_f.","Step 4: Q = 2 × 300,000.","Step 5: Q = 600,000 J."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_fusion","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Fusion"}', 3),
  (2124, 538, 'What is specific latent heat of vaporisation?', 'text', 1, 'Focus on the core principle of Latent Heat of Vaporisation.', '{"why":"The energy supplied is used for the change of state.","sol":"Step 1: Consider a liquid at its boiling point.\nStep 2: Energy is supplied without increasing temperature.\nStep 3: The liquid changes into gas.","steps":["Step 1: Consider a liquid at its boiling point.","Step 2: Energy is supplied without increasing temperature.","Step 3: The liquid changes into gas."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 0),
  (2125, 538, 'State the formula for latent heat of vaporisation.', 'text', 1, 'Focus on the core principle of Latent Heat of Vaporisation.', '{"why":"The total latent heat depends on the mass and the specific latent heat.","sol":"Step 1: Identify the mass.\nStep 2: Identify the specific latent heat of vaporisation.\nStep 3: Multiply them.","steps":["Step 1: Identify the mass.","Step 2: Identify the specific latent heat of vaporisation.","Step 3: Multiply them."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 1),
  (2126, 538, 'Why does the temperature of boiling water remain constant while it is boiling?', 'text', 1, 'Focus on the core principle of Latent Heat of Vaporisation.', '{"why":"The energy during boiling mainly changes the physical state.","sol":"Step 1: Heat continues to enter the water.\nStep 2: The energy is used to separate liquid particles.\nStep 3: Therefore the temperature does not increase while the liquid is changing to gas.","steps":["Step 1: Heat continues to enter the water.","Step 2: The energy is used to separate liquid particles.","Step 3: Therefore the temperature does not increase while the liquid is changing to gas."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 2),
  (2127, 538, 'Calculate the energy required to vaporise 0.5 kg of a liquid with L_v = 2,000,000 J kg⁻¹.', 'text', 1, 'Use Q = mL_v.', '{"why":"The required energy is the mass multiplied by the specific latent heat of vaporisation.","sol":"Step 1: m = 0.5 kg.\nStep 2: L_v = 2,000,000 J kg⁻¹.\nStep 3: Q = 0.5 × 2,000,000.\nStep 4: Q = 1,000,000 J.","steps":["Step 1: m = 0.5 kg.","Step 2: L_v = 2,000,000 J kg⁻¹.","Step 3: Q = 0.5 × 2,000,000.","Step 4: Q = 1,000,000 J."],"options":[],"conceptId":"chemistry_energy_rate_reaction_latent_heat_of_vaporisation","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Latent Heat of Vaporisation"}', 3),
  (2128, 539, 'What is meant by the rate of a chemical reaction?', 'text', 1, 'Focus on the core principle of Rate of Reaction.', '{"why":"Rate measures the change in a chemical system over time.","sol":"Step 1: Consider how quickly a reaction occurs.\nStep 2: Measure how much reactant is used or product is formed.\nStep 3: Relate this change to the time taken.","steps":["Step 1: Consider how quickly a reaction occurs.","Step 2: Measure how much reactant is used or product is formed.","Step 3: Relate this change to the time taken."],"options":[],"conceptId":"chemistry_energy_rate_reaction_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Rate of Reaction"}', 0),
  (2129, 539, 'What does a high rate of reaction mean?', 'text', 1, 'Focus on the core principle of Rate of Reaction.', '{"why":"A high rate means reactants are consumed or products are formed rapidly.","sol":"Step 1: Rate describes how quickly a reaction occurs.\nStep 2: A high rate means a large change occurs in a short time.","steps":["Step 1: Rate describes how quickly a reaction occurs.","Step 2: A high rate means a large change occurs in a short time."],"options":[],"conceptId":"chemistry_energy_rate_reaction_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Rate of Reaction"}', 1),
  (2130, 539, 'A reaction produces 40 cm³ of gas in 20 seconds. Calculate the average rate of gas production.', 'text', 1, 'Focus on the core principle of Rate of Reaction.', '{"why":"The average rate is the gas volume produced divided by the time taken.","sol":"Step 1: Use rate = volume ÷ time.\nStep 2: Volume = 40 cm³.\nStep 3: Time = 20 s.\nStep 4: Rate = 40 ÷ 20.\nStep 5: Rate = 2 cm³/s.","steps":["Step 1: Use rate = volume ÷ time.","Step 2: Volume = 40 cm³.","Step 3: Time = 20 s.","Step 4: Rate = 40 ÷ 20.","Step 5: Rate = 2 cm³/s."],"options":[],"conceptId":"chemistry_energy_rate_reaction_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Rate of Reaction"}', 2),
  (2131, 539, 'A reaction produces 60 cm³ of gas in 30 seconds. Calculate the average rate.', 'text', 1, 'Rate = volume ÷ time.', '{"why":"Average rate is calculated by dividing the change in volume by time.","sol":"Step 1: Volume = 60 cm³.\nStep 2: Time = 30 s.\nStep 3: Rate = 60 ÷ 30.\nStep 4: Rate = 2 cm³/s.","steps":["Step 1: Volume = 60 cm³.","Step 2: Time = 30 s.","Step 3: Rate = 60 ÷ 30.","Step 4: Rate = 2 cm³/s."],"options":[],"conceptId":"chemistry_energy_rate_reaction_rate_of_reaction","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Rate of Reaction"}', 3),
  (2132, 540, 'What happens to the rate of most chemical reactions when temperature is increased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Rate.', '{"why":"There are more frequent successful collisions when temperature is increased.","sol":"Step 1: Increasing temperature gives particles more kinetic energy.\nStep 2: Particles move faster and collide more frequently.\nStep 3: More collisions have enough energy to react.","steps":["Step 1: Increasing temperature gives particles more kinetic energy.","Step 2: Particles move faster and collide more frequently.","Step 3: More collisions have enough energy to react."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 0),
  (2133, 540, 'Why does increasing temperature increase the rate of reaction?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Rate.', '{"why":"The collision frequency and number of successful collisions both increase.","sol":"Step 1: Particles gain kinetic energy.\nStep 2: They collide more frequently.\nStep 3: A larger proportion of collisions exceed the activation energy.\nStep 4: More successful collisions occur per second.","steps":["Step 1: Particles gain kinetic energy.","Step 2: They collide more frequently.","Step 3: A larger proportion of collisions exceed the activation energy.","Step 4: More successful collisions occur per second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 1),
  (2134, 540, 'Why does a reaction usually become slower when temperature is decreased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Rate.', '{"why":"Lower temperature reduces the frequency and effectiveness of collisions.","sol":"Step 1: Particles lose kinetic energy.\nStep 2: They move more slowly.\nStep 3: Collisions become less frequent and fewer have enough energy to react.","steps":["Step 1: Particles lose kinetic energy.","Step 2: They move more slowly.","Step 3: Collisions become less frequent and fewer have enough energy to react."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 2),
  (2135, 540, 'Two identical reactions are carried out at 20°C and 40°C. Which is likely to finish first?', 'text', 1, 'Compare the temperatures.', '{"why":"Increasing temperature generally increases the rate of reaction.","sol":"Step 1: 40°C is higher than 20°C.\nStep 2: Higher temperature generally gives particles more kinetic energy.\nStep 3: The reaction at 40°C is therefore faster.","steps":["Step 1: 40°C is higher than 20°C.","Step 2: Higher temperature generally gives particles more kinetic energy.","Step 3: The reaction at 40°C is therefore faster."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_temperature_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Temperature on Rate"}', 3),
  (2136, 541, 'What happens to the rate of reaction when the concentration of a reactant solution is increased?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Rate.', '{"why":"Higher concentration increases the frequency of collisions between reacting particles.","sol":"Step 1: A higher concentration means more particles are present in a given volume.\nStep 2: More particles produce more frequent collisions.\nStep 3: More successful collisions occur per second.","steps":["Step 1: A higher concentration means more particles are present in a given volume.","Step 2: More particles produce more frequent collisions.","Step 3: More successful collisions occur per second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 0),
  (2137, 541, 'Why does a concentrated acid usually react faster with a solid carbonate than a dilute acid under otherwise similar conditions?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Rate.', '{"why":"Higher concentration increases collision frequency.","sol":"Step 1: The concentrated acid contains more acid particles per unit volume.\nStep 2: These particles collide with the carbonate surface more frequently.\nStep 3: More successful collisions occur per second.","steps":["Step 1: The concentrated acid contains more acid particles per unit volume.","Step 2: These particles collide with the carbonate surface more frequently.","Step 3: More successful collisions occur per second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 1),
  (2138, 541, 'If the concentration of a reactant is reduced, what generally happens to the reaction rate?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Rate.', '{"why":"Lower concentration reduces collision frequency.","sol":"Step 1: Fewer reacting particles are present in the same volume.\nStep 2: Collisions occur less frequently.\nStep 3: The number of successful collisions per second decreases.","steps":["Step 1: Fewer reacting particles are present in the same volume.","Step 2: Collisions occur less frequently.","Step 3: The number of successful collisions per second decreases."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 2),
  (2139, 541, 'Which is likely to react faster with the same mass of magnesium: 2.0 mol/dm³ hydrochloric acid or 0.5 mol/dm³ hydrochloric acid?', 'text', 1, 'Compare the concentrations.', '{"why":"Higher concentration generally produces a faster reaction.","sol":"Step 1: 2.0 mol/dm³ is more concentrated than 0.5 mol/dm³.\nStep 2: It contains more HCl particles per unit volume.\nStep 3: More frequent successful collisions occur.","steps":["Step 1: 2.0 mol/dm³ is more concentrated than 0.5 mol/dm³.","Step 2: It contains more HCl particles per unit volume.","Step 3: More frequent successful collisions occur."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_concentration_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Concentration on Rate"}', 3),
  (2140, 542, 'What happens to the rate of reaction when the surface area of a solid reactant is increased?', 'text', 1, 'Focus on the core principle of Effect of Surface Area on Rate.', '{"why":"A larger surface area provides more sites for collisions.","sol":"Step 1: More of the solid surface becomes exposed.\nStep 2: More reacting particles can collide with the other reactant.\nStep 3: More successful collisions occur per second.","steps":["Step 1: More of the solid surface becomes exposed.","Step 2: More reacting particles can collide with the other reactant.","Step 3: More successful collisions occur per second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 0),
  (2141, 542, 'Why does powdered calcium carbonate react faster with hydrochloric acid than large pieces of calcium carbonate?', 'text', 1, 'Focus on the core principle of Effect of Surface Area on Rate.', '{"why":"Greater surface area increases the number of available collision sites.","sol":"Step 1: Powder has a larger total surface area.\nStep 2: More calcium carbonate particles are exposed to the acid.\nStep 3: Collisions occur more frequently.\nStep 4: More successful collisions occur each second.","steps":["Step 1: Powder has a larger total surface area.","Step 2: More calcium carbonate particles are exposed to the acid.","Step 3: Collisions occur more frequently.","Step 4: More successful collisions occur each second."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 1),
  (2142, 542, 'Why must the mass of solid be kept the same when comparing the effect of particle size on reaction rate?', 'text', 1, 'Focus on the core principle of Effect of Surface Area on Rate.', '{"why":"A fair experiment changes one independent variable while keeping other important factors constant.","sol":"Step 1: The experiment should test only one variable.\nStep 2: Changing the mass would also change the amount of reactant.\nStep 3: Keeping mass constant makes particle size/surface area the main changing variable.","steps":["Step 1: The experiment should test only one variable.","Step 2: Changing the mass would also change the amount of reactant.","Step 3: Keeping mass constant makes particle size/surface area the main changing variable."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 2),
  (2143, 542, 'Which reacts faster with acid under otherwise identical conditions: 10 g of powdered marble or 10 g of marble chips?', 'text', 1, 'Compare their surface areas.', '{"why":"The larger surface area gives a higher frequency of successful collisions.","sol":"Step 1: Both samples have the same mass.\nStep 2: Powdered marble has a larger total surface area.\nStep 3: More surface is exposed to the acid.","steps":["Step 1: Both samples have the same mass.","Step 2: Powdered marble has a larger total surface area.","Step 3: More surface is exposed to the acid."],"options":[],"conceptId":"chemistry_energy_rate_reaction_effect_of_surface_area_on_rate","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Effect of Surface Area on Rate"}', 3),
  (2144, 543, 'What is a catalyst?', 'text', 1, 'Focus on the core principle of Catalysts.', '{"why":"A catalyst participates in an alternative reaction pathway but is regenerated.","sol":"Step 1: A catalyst affects the rate of a reaction.\nStep 2: It increases the reaction rate.\nStep 3: It is not permanently consumed.","steps":["Step 1: A catalyst affects the rate of a reaction.","Step 2: It increases the reaction rate.","Step 3: It is not permanently consumed."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q1","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 0),
  (2145, 543, 'How does a catalyst increase the rate of reaction?', 'text', 1, 'Focus on the core principle of Catalysts.', '{"why":"Lower activation energy means a greater proportion of collisions can result in reaction.","sol":"Step 1: A catalyst provides an alternative reaction pathway.\nStep 2: This pathway has a lower activation energy.\nStep 3: More particles can therefore react successfully.","steps":["Step 1: A catalyst provides an alternative reaction pathway.","Step 2: This pathway has a lower activation energy.","Step 3: More particles can therefore react successfully."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q2","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 1),
  (2146, 543, 'Does a catalyst become permanently used up?', 'text', 1, 'Focus on the core principle of Catalysts.', '{"why":"The catalyst is regenerated during the catalytic process.","sol":"Step 1: A catalyst participates in the reaction pathway.\nStep 2: It is regenerated rather than permanently consumed.\nStep 3: Therefore it can continue to catalyse further reaction.","steps":["Step 1: A catalyst participates in the reaction pathway.","Step 2: It is regenerated rather than permanently consumed.","Step 3: Therefore it can continue to catalyse further reaction."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q3","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 2),
  (2147, 543, 'A reaction has an activation energy of 100 kJ mol⁻¹. A catalyst provides an alternative pathway requiring 60 kJ mol⁻¹. By how much has the activation energy been reduced?', 'text', 1, 'Subtract the new activation energy from the original.', '{"why":"The catalyst lowers the activation energy from 100 to 60 kJ mol⁻¹.","sol":"Step 1: Original activation energy = 100 kJ mol⁻¹.\nStep 2: Catalysed activation energy = 60 kJ mol⁻¹.\nStep 3: Reduction = 100 − 60.\nStep 4: Reduction = 40 kJ mol⁻¹.","steps":["Step 1: Original activation energy = 100 kJ mol⁻¹.","Step 2: Catalysed activation energy = 60 kJ mol⁻¹.","Step 3: Reduction = 100 − 60.","Step 4: Reduction = 40 kJ mol⁻¹."],"options":[],"conceptId":"chemistry_energy_rate_reaction_catalysts","skillId":"chemistry_energy_rate_reaction","subskillId":"chemistry_energy_rate_reaction_q4","subject":"chemistry","chapter":"energy_rate_reaction","topic":"Catalysts"}', 3),
  (2148, 544, 'State three physical properties of metals.', 'text', 1, 'Focus on the core principle of Physical Properties of Metals.', '{"why":"These are characteristic physical properties of many metals.","sol":"Step 1: Recall the common physical properties of metals.\nStep 2: Select three properties.\nStep 3: Examples include good electrical conductivity, good thermal conductivity and malleability.","steps":["Step 1: Recall the common physical properties of metals.","Step 2: Select three properties.","Step 3: Examples include good electrical conductivity, good thermal conductivity and malleability."],"options":[],"conceptId":"chemistry_metals_extraction_physical_properties_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Physical Properties of Metals"}', 0),
  (2149, 544, 'State two physical properties of aluminium.', 'text', 1, 'Focus on the core principle of Physical Properties of Metals.', '{"why":"Aluminium has the characteristic physical properties of metals.","sol":"Step 1: Identify aluminium as a metal.\nStep 2: Apply the common physical properties of metals.\nStep 3: Aluminium is malleable and conducts electricity.","steps":["Step 1: Identify aluminium as a metal.","Step 2: Apply the common physical properties of metals.","Step 3: Aluminium is malleable and conducts electricity."],"options":[],"conceptId":"chemistry_metals_extraction_physical_properties_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Physical Properties of Metals"}', 1),
  (2150, 544, 'Why is copper suitable for making electrical wires?', 'text', 1, 'Focus on the core principle of Physical Properties of Metals.', '{"why":"Electrical wires need materials that allow electric current to pass easily.","sol":"Step 1: Identify the property needed in an electrical wire.\nStep 2: The material must conduct electricity.\nStep 3: Copper is a good electrical conductor.","steps":["Step 1: Identify the property needed in an electrical wire.","Step 2: The material must conduct electricity.","Step 3: Copper is a good electrical conductor."],"options":[],"conceptId":"chemistry_metals_extraction_physical_properties_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Physical Properties of Metals"}', 2),
  (2151, 544, 'A student says that metals are all gases at room temperature. Is this correct?', 'text', 1, 'Think about the physical state of common metals such as iron and copper.', '{"why":"Most metals exist as solids under ordinary room conditions.","sol":"Step 1: Consider common metals at room temperature.\nStep 2: Iron and copper are solids.\nStep 3: Therefore the statement is incorrect.","steps":["Step 1: Consider common metals at room temperature.","Step 2: Iron and copper are solids.","Step 3: Therefore the statement is incorrect."],"options":[],"conceptId":"chemistry_metals_extraction_physical_properties_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Physical Properties of Metals"}', 3),
  (2152, 545, 'Why do metals conduct electricity?', 'text', 1, 'Focus on the core principle of Electrical Conductivity.', '{"why":"The movement of charged electrons allows electric current to pass through a metal.","sol":"Step 1: Metals contain electrons that are able to move through the metal.\nStep 2: Moving electrons carry electric charge.\nStep 3: Therefore metals can conduct electricity.","steps":["Step 1: Metals contain electrons that are able to move through the metal.","Step 2: Moving electrons carry electric charge.","Step 3: Therefore metals can conduct electricity."],"options":[],"conceptId":"chemistry_metals_extraction_electrical_conductivity","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Electrical Conductivity"}', 0),
  (2153, 545, 'Why is copper commonly used for electrical wires?', 'text', 1, 'Focus on the core principle of Electrical Conductivity.', '{"why":"Both conductivity and the ability to form wires make copper suitable.","sol":"Step 1: Electrical wires need a good electrical conductor.\nStep 2: Copper conducts electricity well.\nStep 3: Copper can also be drawn into thin wires.","steps":["Step 1: Electrical wires need a good electrical conductor.","Step 2: Copper conducts electricity well.","Step 3: Copper can also be drawn into thin wires."],"options":[],"conceptId":"chemistry_metals_extraction_electrical_conductivity","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Electrical Conductivity"}', 1),
  (2154, 545, 'Why is plastic used to cover electrical wires?', 'text', 1, 'Focus on the core principle of Electrical Conductivity.', '{"why":"An insulating covering reduces the risk of electric shock.","sol":"Step 1: The metal inside the wire conducts electricity.\nStep 2: The outside covering should prevent current from reaching the user.\nStep 3: Plastic is an electrical insulator.","steps":["Step 1: The metal inside the wire conducts electricity.","Step 2: The outside covering should prevent current from reaching the user.","Step 3: Plastic is an electrical insulator."],"options":[],"conceptId":"chemistry_metals_extraction_electrical_conductivity","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Electrical Conductivity"}', 2),
  (2155, 545, 'A metal wire is replaced with a plastic wire. What happens to electrical conduction?', 'text', 1, 'Compare conductors with insulators.', '{"why":"Plastic does not have freely moving charge carriers like a metal.","sol":"Step 1: Metals are good electrical conductors.\nStep 2: Plastic is generally an electrical insulator.\nStep 3: Therefore the plastic will not conduct electricity effectively.","steps":["Step 1: Metals are good electrical conductors.","Step 2: Plastic is generally an electrical insulator.","Step 3: Therefore the plastic will not conduct electricity effectively."],"options":[],"conceptId":"chemistry_metals_extraction_electrical_conductivity","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Electrical Conductivity"}', 3),
  (2156, 546, 'Define malleability.', 'text', 1, 'Focus on the core principle of Malleability.', '{"why":"Metals can often be shaped into sheets because their particles can shift without the whole structure immediately breaking.","sol":"Step 1: Identify malleability as a physical property.\nStep 2: It describes the ability to be shaped by hammering or pressing.\nStep 3: The material forms sheets instead of breaking.","steps":["Step 1: Identify malleability as a physical property.","Step 2: It describes the ability to be shaped by hammering or pressing.","Step 3: The material forms sheets instead of breaking."],"options":[],"conceptId":"chemistry_metals_extraction_malleability","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Malleability"}', 0),
  (2157, 546, 'Why can aluminium be made into foil?', 'text', 1, 'Focus on the core principle of Malleability.', '{"why":"Malleability allows aluminium to be shaped into thin sheets.","sol":"Step 1: Aluminium is a metal.\nStep 2: Aluminium is malleable.\nStep 3: Therefore it can be rolled into thin sheets.","steps":["Step 1: Aluminium is a metal.","Step 2: Aluminium is malleable.","Step 3: Therefore it can be rolled into thin sheets."],"options":[],"conceptId":"chemistry_metals_extraction_malleability","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Malleability"}', 1),
  (2158, 546, 'Distinguish between malleability and brittleness.', 'text', 1, 'Focus on the core principle of Malleability.', '{"why":"The two properties describe how materials respond to applied force.","sol":"Step 1: Malleability involves being shaped without breaking.\nStep 2: Brittleness involves breaking when force is applied.\nStep 3: Therefore the properties describe opposite behaviours.","steps":["Step 1: Malleability involves being shaped without breaking.","Step 2: Brittleness involves breaking when force is applied.","Step 3: Therefore the properties describe opposite behaviours."],"options":[],"conceptId":"chemistry_metals_extraction_malleability","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Malleability"}', 2),
  (2159, 546, 'A metal is hammered into a sheet without cracking. Which property is demonstrated?', 'text', 1, 'Think of the property that allows metals to form sheets.', '{"why":"Malleability is the ability to form sheets without breaking.","sol":"Step 1: The metal is being hammered.\nStep 2: It forms a sheet without breaking.\nStep 3: This is malleability.","steps":["Step 1: The metal is being hammered.","Step 2: It forms a sheet without breaking.","Step 3: This is malleability."],"options":[],"conceptId":"chemistry_metals_extraction_malleability","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Malleability"}', 3),
  (2160, 547, 'Define ductility.', 'text', 1, 'Focus on the core principle of Ductility.', '{"why":"Ductile materials can undergo deformation while remaining intact.","sol":"Step 1: Ductility is a physical property.\nStep 2: It describes the ability of a material to be drawn or stretched.\nStep 3: The material forms a wire without breaking.","steps":["Step 1: Ductility is a physical property.","Step 2: It describes the ability of a material to be drawn or stretched.","Step 3: The material forms a wire without breaking."],"options":[],"conceptId":"chemistry_metals_extraction_ductility","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Ductility"}', 0),
  (2161, 547, 'Why is copper suitable for making wires?', 'text', 1, 'Focus on the core principle of Ductility.', '{"why":"Ductility allows a metal to be formed into long thin wires.","sol":"Step 1: Wires need to be formed into long thin shapes.\nStep 2: Copper is ductile.\nStep 3: Therefore copper can be drawn into wires.","steps":["Step 1: Wires need to be formed into long thin shapes.","Step 2: Copper is ductile.","Step 3: Therefore copper can be drawn into wires."],"options":[],"conceptId":"chemistry_metals_extraction_ductility","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Ductility"}', 1),
  (2162, 547, 'Distinguish between ductility and malleability.', 'text', 1, 'Focus on the core principle of Ductility.', '{"why":"Both involve shaping metals, but the final forms are different.","sol":"Step 1: Ductility concerns forming wires.\nStep 2: Malleability concerns forming sheets.\nStep 3: Therefore they describe different ways metals can be shaped.","steps":["Step 1: Ductility concerns forming wires.","Step 2: Malleability concerns forming sheets.","Step 3: Therefore they describe different ways metals can be shaped."],"options":[],"conceptId":"chemistry_metals_extraction_ductility","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Ductility"}', 2),
  (2163, 547, 'A metal can be pulled into a long thin wire without breaking. What property does it show?', 'text', 1, 'The answer involves forming wires.', '{"why":"Ductility is the ability to be drawn into wires.","sol":"Step 1: The metal is being pulled into a wire.\nStep 2: It does not break.\nStep 3: This demonstrates ductility.","steps":["Step 1: The metal is being pulled into a wire.","Step 2: It does not break.","Step 3: This demonstrates ductility."],"options":[],"conceptId":"chemistry_metals_extraction_ductility","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Ductility"}', 3),
  (2164, 548, 'Which is more reactive, magnesium or copper?', 'text', 1, 'Focus on the core principle of Reactivity Series.', '{"why":"A metal higher in the reactivity series is generally more reactive.","sol":"Step 1: Locate magnesium in the reactivity series.\nStep 2: Locate copper in the reactivity series.\nStep 3: Magnesium is above copper.\nStep 4: Therefore magnesium is more reactive.","steps":["Step 1: Locate magnesium in the reactivity series.","Step 2: Locate copper in the reactivity series.","Step 3: Magnesium is above copper.","Step 4: Therefore magnesium is more reactive."],"options":[],"conceptId":"chemistry_metals_extraction_reactivity_series","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Reactivity Series"}', 0),
  (2165, 548, 'Which is more reactive, zinc or iron?', 'text', 1, 'Focus on the core principle of Reactivity Series.', '{"why":"Zinc occurs above iron in the reactivity series.","sol":"Step 1: Locate zinc in the series.\nStep 2: Locate iron in the series.\nStep 3: Zinc is above iron.\nStep 4: Therefore zinc is more reactive.","steps":["Step 1: Locate zinc in the series.","Step 2: Locate iron in the series.","Step 3: Zinc is above iron.","Step 4: Therefore zinc is more reactive."],"options":[],"conceptId":"chemistry_metals_extraction_reactivity_series","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Reactivity Series"}', 1),
  (2166, 548, 'Arrange magnesium, copper, zinc and iron from most reactive to least reactive.', 'text', 1, 'Focus on the core principle of Reactivity Series.', '{"why":"The order follows their positions in the reactivity series.","sol":"Step 1: Locate the four metals in the reactivity series.\nStep 2: Magnesium is highest among the four.\nStep 3: Zinc comes next, followed by iron.\nStep 4: Copper is lowest among the four.","steps":["Step 1: Locate the four metals in the reactivity series.","Step 2: Magnesium is highest among the four.","Step 3: Zinc comes next, followed by iron.","Step 4: Copper is lowest among the four."],"options":[],"conceptId":"chemistry_metals_extraction_reactivity_series","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Reactivity Series"}', 2),
  (2167, 548, 'A student places copper above zinc in the reactivity series. Is this correct?', 'text', 1, 'Compare the positions of copper and zinc.', '{"why":"Zinc is higher than copper in the reactivity series.","sol":"Step 1: Zinc is above iron and hydrogen.\nStep 2: Copper is below hydrogen.\nStep 3: Therefore zinc is more reactive than copper.","steps":["Step 1: Zinc is above iron and hydrogen.","Step 2: Copper is below hydrogen.","Step 3: Therefore zinc is more reactive than copper."],"options":[],"conceptId":"chemistry_metals_extraction_reactivity_series","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Reactivity Series"}', 3),
  (2168, 549, 'Will iron displace copper from copper(II) sulphate?', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"Iron is more reactive than copper.","sol":"Step 1: Compare iron and copper in the reactivity series.\nStep 2: Iron is above copper.\nStep 3: Therefore iron is more reactive.\nStep 4: Iron can displace copper.","steps":["Step 1: Compare iron and copper in the reactivity series.","Step 2: Iron is above copper.","Step 3: Therefore iron is more reactive.","Step 4: Iron can displace copper."],"options":[],"conceptId":"chemistry_metals_extraction_displacement_reactions","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Displacement Reactions"}', 0),
  (2169, 549, 'Write the equation for the reaction between zinc and copper(II) sulphate.', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"Zinc is above copper in the reactivity series.","sol":"Step 1: Zinc is more reactive than copper.\nStep 2: Zinc displaces copper.\nStep 3: The products are zinc sulphate and copper.\nStep 4: Write the balanced equation.","steps":["Step 1: Zinc is more reactive than copper.","Step 2: Zinc displaces copper.","Step 3: The products are zinc sulphate and copper.","Step 4: Write the balanced equation."],"options":[],"conceptId":"chemistry_metals_extraction_displacement_reactions","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Displacement Reactions"}', 1),
  (2170, 549, 'Will copper displace zinc from zinc sulphate?', 'text', 1, 'Focus on the core principle of Displacement Reactions.', '{"why":"A less reactive metal cannot displace a more reactive metal from its compound.","sol":"Step 1: Compare copper and zinc in the reactivity series.\nStep 2: Zinc is more reactive than copper.\nStep 3: Copper is therefore unable to displace zinc.","steps":["Step 1: Compare copper and zinc in the reactivity series.","Step 2: Zinc is more reactive than copper.","Step 3: Copper is therefore unable to displace zinc."],"options":[],"conceptId":"chemistry_metals_extraction_displacement_reactions","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Displacement Reactions"}', 2),
  (2171, 549, 'A student predicts that Cu + MgSO₄ → CuSO₄ + Mg. Is this correct?', 'text', 1, 'Compare copper and magnesium in the reactivity series.', '{"why":"Copper is less reactive than magnesium.","sol":"Step 1: Magnesium is above copper in the reactivity series.\nStep 2: Magnesium is therefore more reactive.\nStep 3: Copper cannot displace magnesium.","steps":["Step 1: Magnesium is above copper in the reactivity series.","Step 2: Magnesium is therefore more reactive.","Step 3: Copper cannot displace magnesium."],"options":[],"conceptId":"chemistry_metals_extraction_displacement_reactions","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Displacement Reactions"}', 3),
  (2172, 550, 'What is an ore?', 'text', 1, 'Focus on the core principle of Ores.', '{"why":"Not every mineral containing a metal is considered an ore; economic extraction is important.","sol":"Step 1: An ore occurs naturally in the Earth''s crust.\nStep 2: It contains a metal or metal compound.\nStep 3: The metal can be extracted economically from the ore.","steps":["Step 1: An ore occurs naturally in the Earth''s crust.","Step 2: It contains a metal or metal compound.","Step 3: The metal can be extracted economically from the ore."],"options":[],"conceptId":"chemistry_metals_extraction_ores","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Ores"}', 0),
  (2173, 550, 'Name the main ore of aluminium.', 'text', 1, 'Focus on the core principle of Ores.', '{"why":"Bauxite is the main ore from which aluminium is obtained.","sol":"Step 1: Recall the common ores of important metals.\nStep 2: Aluminium is obtained from bauxite.\nStep 3: Therefore the main ore is bauxite.","steps":["Step 1: Recall the common ores of important metals.","Step 2: Aluminium is obtained from bauxite.","Step 3: Therefore the main ore is bauxite."],"options":[],"conceptId":"chemistry_metals_extraction_ores","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Ores"}', 1),
  (2174, 550, 'Name an important ore of iron.', 'text', 1, 'Focus on the core principle of Ores.', '{"why":"Hematite is an important source of iron.","sol":"Step 1: Recall common iron ores.\nStep 2: Hematite contains iron(III) oxide.\nStep 3: Therefore hematite is an important iron ore.","steps":["Step 1: Recall common iron ores.","Step 2: Hematite contains iron(III) oxide.","Step 3: Therefore hematite is an important iron ore."],"options":[],"conceptId":"chemistry_metals_extraction_ores","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Ores"}', 2),
  (2175, 550, 'A rock contains a small amount of copper, but extracting the copper costs more than the copper is worth. Is the rock necessarily an ore?', 'text', 1, 'Consider the economic part of the definition.', '{"why":"Economic extraction is part of the definition of an ore.","sol":"Step 1: An ore must contain a useful metal or metal compound.\nStep 2: The metal must also be economically extractable.\nStep 3: If extraction costs more than the value obtained, it does not satisfy the economic requirement.","steps":["Step 1: An ore must contain a useful metal or metal compound.","Step 2: The metal must also be economically extractable.","Step 3: If extraction costs more than the value obtained, it does not satisfy the economic requirement."],"options":[],"conceptId":"chemistry_metals_extraction_ores","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Ores"}', 3),
  (2176, 551, 'What is reduction in terms of oxygen?', 'text', 1, 'Focus on the core principle of Reduction.', '{"why":"This is the oxygen-based definition commonly used when discussing extraction of metals.","sol":"Step 1: Look at the oxygen content of the substance.\nStep 2: If oxygen is removed, the substance is reduced.\nStep 3: Therefore reduction can be described as removal of oxygen.","steps":["Step 1: Look at the oxygen content of the substance.","Step 2: If oxygen is removed, the substance is reduced.","Step 3: Therefore reduction can be described as removal of oxygen."],"options":[],"conceptId":"chemistry_metals_extraction_reduction","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Reduction"}', 0),
  (2177, 551, 'Identify the substance being reduced in Fe₂O₃ + 3CO → 2Fe + 3CO₂.', 'text', 1, 'Focus on the core principle of Reduction.', '{"why":"Iron(III) oxide loses oxygen to form iron.","sol":"Step 1: Compare the reactant and product containing iron.\nStep 2: Fe₂O₃ changes into Fe.\nStep 3: Oxygen has been removed from the iron compound.","steps":["Step 1: Compare the reactant and product containing iron.","Step 2: Fe₂O₃ changes into Fe.","Step 3: Oxygen has been removed from the iron compound."],"options":[],"conceptId":"chemistry_metals_extraction_reduction","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Reduction"}', 1),
  (2178, 551, 'In CuO + H₂ → Cu + H₂O, which substance is reduced?', 'text', 1, 'Focus on the core principle of Reduction.', '{"why":"CuO loses oxygen and forms copper.","sol":"Step 1: Identify the copper-containing reactant.\nStep 2: CuO changes into Cu.\nStep 3: Oxygen is removed from CuO.","steps":["Step 1: Identify the copper-containing reactant.","Step 2: CuO changes into Cu.","Step 3: Oxygen is removed from CuO."],"options":[],"conceptId":"chemistry_metals_extraction_reduction","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Reduction"}', 2),
  (2179, 551, 'A student says oxidation is the removal of oxygen. Is this correct?', 'text', 1, 'Recall the oxygen definitions of oxidation and reduction.', '{"why":"These are the oxygen-based definitions of reduction and oxidation.","sol":"Step 1: Oxidation involves gain of oxygen.\nStep 2: Reduction involves loss of oxygen.\nStep 3: Therefore the statement is incorrect.","steps":["Step 1: Oxidation involves gain of oxygen.","Step 2: Reduction involves loss of oxygen.","Step 3: Therefore the statement is incorrect."],"options":[],"conceptId":"chemistry_metals_extraction_reduction","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Reduction"}', 3),
  (2180, 552, 'Write the equation for the reduction of iron(III) oxide by carbon monoxide.', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"Carbon monoxide removes oxygen from iron(III) oxide, reducing it to iron.","sol":"Step 1: Write the reactants: Fe₂O₃ and CO.\nStep 2: The products are Fe and CO₂.\nStep 3: Balance iron: Fe₂O₃ gives 2Fe.\nStep 4: Balance carbon monoxide and carbon dioxide.\nStep 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂.","steps":["Step 1: Write the reactants: Fe₂O₃ and CO.","Step 2: The products are Fe and CO₂.","Step 3: Balance iron: Fe₂O₃ gives 2Fe.","Step 4: Balance carbon monoxide and carbon dioxide.","Step 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂."],"options":[],"conceptId":"chemistry_metals_extraction_extraction_of_iron","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Extraction of Iron"}', 0),
  (2181, 552, 'What is the role of carbon monoxide in the blast furnace?', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"CO removes oxygen from Fe₂O₃.","sol":"Step 1: Identify the compound that must be changed into iron.\nStep 2: Iron(III) oxide must lose oxygen.\nStep 3: Carbon monoxide removes oxygen from the oxide.","steps":["Step 1: Identify the compound that must be changed into iron.","Step 2: Iron(III) oxide must lose oxygen.","Step 3: Carbon monoxide removes oxygen from the oxide."],"options":[],"conceptId":"chemistry_metals_extraction_extraction_of_iron","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Extraction of Iron"}', 1),
  (2182, 552, 'What is the role of limestone in the extraction of iron?', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"The calcium oxide formed from limestone reacts with acidic silica impurity.","sol":"Step 1: Iron ore contains unwanted impurities such as silica.\nStep 2: Limestone decomposes to form calcium oxide.\nStep 3: Calcium oxide reacts with silica to form calcium silicate slag.","steps":["Step 1: Iron ore contains unwanted impurities such as silica.","Step 2: Limestone decomposes to form calcium oxide.","Step 3: Calcium oxide reacts with silica to form calcium silicate slag."],"options":[],"conceptId":"chemistry_metals_extraction_extraction_of_iron","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Extraction of Iron"}', 2),
  (2183, 552, 'A student writes Fe₂O₃ + CO → Fe + CO₂ as the balanced equation. What is wrong?', 'text', 1, 'Count iron, carbon and oxygen atoms on both sides.', '{"why":"The original equation does not conserve the number of atoms.","sol":"Step 1: Fe₂O₃ contains two iron atoms.\nStep 2: Therefore two Fe atoms are needed on the product side.\nStep 3: Balancing carbon and oxygen then requires three CO and three CO₂.","steps":["Step 1: Fe₂O₃ contains two iron atoms.","Step 2: Therefore two Fe atoms are needed on the product side.","Step 3: Balancing carbon and oxygen then requires three CO and three CO₂."],"options":[],"conceptId":"chemistry_metals_extraction_extraction_of_iron","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Extraction of Iron"}', 3),
  (2184, 553, 'What is rusting?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Both oxygen and water are required for ordinary rusting.","sol":"Step 1: Identify the metal involved.\nStep 2: Rusting specifically refers to corrosion of iron and steel.\nStep 3: It occurs when iron reacts in the presence of oxygen and water.","steps":["Step 1: Identify the metal involved.","Step 2: Rusting specifically refers to corrosion of iron and steel.","Step 3: It occurs when iron reacts in the presence of oxygen and water."],"options":[],"conceptId":"chemistry_metals_extraction_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Rusting"}', 0),
  (2185, 553, 'State the two main conditions required for rusting.', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Rusting requires both oxygen and water.","sol":"Step 1: Iron must have access to oxygen.\nStep 2: Iron must also have access to water.\nStep 3: Therefore both oxygen and water are required.","steps":["Step 1: Iron must have access to oxygen.","Step 2: Iron must also have access to water.","Step 3: Therefore both oxygen and water are required."],"options":[],"conceptId":"chemistry_metals_extraction_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Rusting"}', 1),
  (2186, 553, 'State two effects of rusting.', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Corrosion gradually changes and removes useful metal.","sol":"Step 1: Rust forms on iron surfaces.\nStep 2: Continued corrosion removes and weakens the metal.\nStep 3: Therefore iron structures can lose strength and become damaged.","steps":["Step 1: Rust forms on iron surfaces.","Step 2: Continued corrosion removes and weakens the metal.","Step 3: Therefore iron structures can lose strength and become damaged."],"options":[],"conceptId":"chemistry_metals_extraction_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Rusting"}', 2),
  (2187, 553, 'Iron nails are stored completely dry in a sealed container containing no oxygen. Will ordinary rusting occur?', 'text', 1, 'Rusting needs both water and oxygen.', '{"why":"Both conditions are necessary for ordinary rusting.","sol":"Step 1: Rusting requires water.\nStep 2: Rusting also requires oxygen.\nStep 3: The nails have neither available oxygen nor water.\nStep 4: Ordinary rusting will therefore not occur.","steps":["Step 1: Rusting requires water.","Step 2: Rusting also requires oxygen.","Step 3: The nails have neither available oxygen nor water.","Step 4: Ordinary rusting will therefore not occur."],"options":[],"conceptId":"chemistry_metals_extraction_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Rusting"}', 3),
  (2188, 554, 'Why does a dry iron nail not rust readily?', 'text', 1, 'Focus on the core principle of Conditions for Rusting.', '{"why":"Water is one of the conditions required for rusting.","sol":"Step 1: Rusting requires oxygen and water.\nStep 2: A dry nail has little or no water available.\nStep 3: Therefore the rusting reaction is prevented or greatly reduced.","steps":["Step 1: Rusting requires oxygen and water.","Step 2: A dry nail has little or no water available.","Step 3: Therefore the rusting reaction is prevented or greatly reduced."],"options":[],"conceptId":"chemistry_metals_extraction_conditions_for_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Conditions for Rusting"}', 0),
  (2189, 554, 'Why can boiled water covered with oil reduce rusting of an iron nail?', 'text', 1, 'Focus on the core principle of Conditions for Rusting.', '{"why":"The experiment removes or excludes oxygen while water is still present.","sol":"Step 1: Boiling removes much of the dissolved oxygen from water.\nStep 2: The oil layer prevents oxygen from entering the water easily.\nStep 3: The nail therefore has very little oxygen available.","steps":["Step 1: Boiling removes much of the dissolved oxygen from water.","Step 2: The oil layer prevents oxygen from entering the water easily.","Step 3: The nail therefore has very little oxygen available."],"options":[],"conceptId":"chemistry_metals_extraction_conditions_for_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Conditions for Rusting"}', 1),
  (2190, 554, 'An iron nail is placed in ordinary water exposed to air. Will it rust?', 'text', 1, 'Focus on the core principle of Conditions for Rusting.', '{"why":"Both water and oxygen are available.","sol":"Step 1: The nail has access to water.\nStep 2: It also has access to oxygen from the air.\nStep 3: Both conditions for rusting are present.","steps":["Step 1: The nail has access to water.","Step 2: It also has access to oxygen from the air.","Step 3: Both conditions for rusting are present."],"options":[],"conceptId":"chemistry_metals_extraction_conditions_for_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Conditions for Rusting"}', 2),
  (2191, 554, 'A nail is placed in dry air. Why is rusting greatly reduced?', 'text', 1, 'What substance is missing from dry air?', '{"why":"Rusting requires both oxygen and water.","sol":"Step 1: Dry air provides oxygen.\nStep 2: However, it contains very little water.\nStep 3: Without sufficient water, ordinary rusting is greatly reduced.","steps":["Step 1: Dry air provides oxygen.","Step 2: However, it contains very little water.","Step 3: Without sufficient water, ordinary rusting is greatly reduced."],"options":[],"conceptId":"chemistry_metals_extraction_conditions_for_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Conditions for Rusting"}', 3),
  (2192, 555, 'How does painting prevent rusting?', 'text', 1, 'Focus on the core principle of Prevention of Rusting.', '{"why":"Removing contact with the required conditions reduces rusting.","sol":"Step 1: Rusting requires contact with oxygen and water.\nStep 2: Paint forms a protective layer over the iron.\nStep 3: The layer prevents water and oxygen from reaching the iron.","steps":["Step 1: Rusting requires contact with oxygen and water.","Step 2: Paint forms a protective layer over the iron.","Step 3: The layer prevents water and oxygen from reaching the iron."],"options":[],"conceptId":"chemistry_metals_extraction_prevention_of_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Prevention of Rusting"}', 0),
  (2193, 555, 'Why is grease applied to a bicycle chain?', 'text', 1, 'Focus on the core principle of Prevention of Rusting.', '{"why":"The grease acts as a barrier against the conditions needed for rusting.","sol":"Step 1: A bicycle chain is made largely of iron or steel.\nStep 2: Iron and steel can rust when exposed to water and oxygen.\nStep 3: Grease forms a protective barrier.","steps":["Step 1: A bicycle chain is made largely of iron or steel.","Step 2: Iron and steel can rust when exposed to water and oxygen.","Step 3: Grease forms a protective barrier."],"options":[],"conceptId":"chemistry_metals_extraction_prevention_of_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Prevention of Rusting"}', 1),
  (2194, 555, 'What is galvanising?', 'text', 1, 'Focus on the core principle of Prevention of Rusting.', '{"why":"The zinc coating separates the steel from the environment and also provides sacrificial protection.","sol":"Step 1: Identify the metal used as the protective coating.\nStep 2: Iron or steel is coated with zinc.\nStep 3: This process is called galvanising.","steps":["Step 1: Identify the metal used as the protective coating.","Step 2: Iron or steel is coated with zinc.","Step 3: This process is called galvanising."],"options":[],"conceptId":"chemistry_metals_extraction_prevention_of_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Prevention of Rusting"}', 2),
  (2195, 555, 'A painted iron gate develops rust after the paint is scratched away. Why?', 'text', 1, 'Think about what the scratch exposes.', '{"why":"The protective barrier has been broken.","sol":"Step 1: Paint normally acts as a barrier.\nStep 2: The scratch exposes the iron.\nStep 3: Water and oxygen can reach the exposed iron.\nStep 4: Rusting can therefore begin at the damaged area.","steps":["Step 1: Paint normally acts as a barrier.","Step 2: The scratch exposes the iron.","Step 3: Water and oxygen can reach the exposed iron.","Step 4: Rusting can therefore begin at the damaged area."],"options":[],"conceptId":"chemistry_metals_extraction_prevention_of_rusting","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Prevention of Rusting"}', 3),
  (2196, 556, 'What is an alloy?', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Alloys are produced by combining elements to obtain useful properties.","sol":"Step 1: Identify an alloy as a mixture.\nStep 2: It contains a metal and one or more other elements.\nStep 3: Therefore it is not usually a pure element.","steps":["Step 1: Identify an alloy as a mixture.","Step 2: It contains a metal and one or more other elements.","Step 3: Therefore it is not usually a pure element."],"options":[],"conceptId":"chemistry_metals_extraction_alloys","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Alloys"}', 0),
  (2197, 556, 'Name the elements that make up brass.', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Brass is an alloy of copper and zinc.","sol":"Step 1: Recall the common composition of brass.\nStep 2: Brass contains copper.\nStep 3: Brass also contains zinc.","steps":["Step 1: Recall the common composition of brass.","Step 2: Brass contains copper.","Step 3: Brass also contains zinc."],"options":[],"conceptId":"chemistry_metals_extraction_alloys","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Alloys"}', 1),
  (2198, 556, 'Name the main metals in bronze.', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Bronze is mainly an alloy of copper and tin.","sol":"Step 1: Recall the common composition of bronze.\nStep 2: Bronze contains copper.\nStep 3: Tin is added to copper to form bronze.","steps":["Step 1: Recall the common composition of bronze.","Step 2: Bronze contains copper.","Step 3: Tin is added to copper to form bronze."],"options":[],"conceptId":"chemistry_metals_extraction_alloys","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Alloys"}', 2),
  (2199, 556, 'Why are alloys often preferred to pure metals?', 'text', 1, 'Think about how their properties can change.', '{"why":"Alloying is used to modify the properties of metals.","sol":"Step 1: Combining elements changes the structure of the material.\nStep 2: This can change properties such as strength and hardness.\nStep 3: Therefore an alloy can have properties more suitable for a particular use.","steps":["Step 1: Combining elements changes the structure of the material.","Step 2: This can change properties such as strength and hardness.","Step 3: Therefore an alloy can have properties more suitable for a particular use."],"options":[],"conceptId":"chemistry_metals_extraction_alloys","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Alloys"}', 3),
  (2200, 557, 'Why is copper used for electrical wiring?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Its conductivity allows current to flow and its ductility allows wires to be formed.","sol":"Step 1: Electrical wires need a good conductor.\nStep 2: Copper conducts electricity well.\nStep 3: Copper is also ductile and can be drawn into wires.","steps":["Step 1: Electrical wires need a good conductor.","Step 2: Copper conducts electricity well.","Step 3: Copper is also ductile and can be drawn into wires."],"options":[],"conceptId":"chemistry_metals_extraction_uses_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q1","subject":"chemistry","chapter":"metals_extraction","topic":"Uses of Metals"}', 0),
  (2201, 557, 'Why is aluminium useful for aircraft construction?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Low mass is especially valuable in aircraft construction.","sol":"Step 1: Aircraft construction benefits from materials with low density.\nStep 2: Aluminium is relatively light.\nStep 3: Aluminium also has useful strength and corrosion resistance.","steps":["Step 1: Aircraft construction benefits from materials with low density.","Step 2: Aluminium is relatively light.","Step 3: Aluminium also has useful strength and corrosion resistance."],"options":[],"conceptId":"chemistry_metals_extraction_uses_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q2","subject":"chemistry","chapter":"metals_extraction","topic":"Uses of Metals"}', 1),
  (2202, 557, 'Why is steel used to make bridges?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Strong materials are required to support the loads acting on bridges.","sol":"Step 1: A bridge must support large loads.\nStep 2: Steel is strong and can be formed into structural shapes.\nStep 3: Therefore steel is suitable for bridges.","steps":["Step 1: A bridge must support large loads.","Step 2: Steel is strong and can be formed into structural shapes.","Step 3: Therefore steel is suitable for bridges."],"options":[],"conceptId":"chemistry_metals_extraction_uses_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q3","subject":"chemistry","chapter":"metals_extraction","topic":"Uses of Metals"}', 2),
  (2203, 557, 'A manufacturer wants a material for electrical cables that can be drawn into thin wires and conducts electricity well. Which metal is suitable: copper or sulphur?', 'text', 1, 'Compare their conductivity and ductility.', '{"why":"Copper has the required electrical conductivity and ductility.","sol":"Step 1: Electrical cables need good electrical conductivity.\nStep 2: They also need a material that can form wires.\nStep 3: Copper is a good conductor and is ductile.\nStep 4: Sulphur is a non-metal and is not suitable.","steps":["Step 1: Electrical cables need good electrical conductivity.","Step 2: They also need a material that can form wires.","Step 3: Copper is a good conductor and is ductile.","Step 4: Sulphur is a non-metal and is not suitable."],"options":[],"conceptId":"chemistry_metals_extraction_uses_of_metals","skillId":"chemistry_metals_extraction","subskillId":"chemistry_metals_extraction_q4","subject":"chemistry","chapter":"metals_extraction","topic":"Uses of Metals"}', 3),
  (2204, 558, 'What is an electrolyte?', 'text', 1, 'Focus on the core principle of Electrolytes.', '{"why":"Electric current through an electrolyte is carried by moving ions.","sol":"Step 1: An electrolyte contains charged particles that can move.\nStep 2: These particles are usually ions.\nStep 3: Their movement allows electric current to pass.","steps":["Step 1: An electrolyte contains charged particles that can move.","Step 2: These particles are usually ions.","Step 3: Their movement allows electric current to pass."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 0),
  (2205, 558, 'Why does molten sodium chloride conduct electricity?', 'text', 1, 'Focus on the core principle of Electrolytes.', '{"why":"Mobile ions are required for conduction through an electrolyte.","sol":"Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: In solid sodium chloride, the ions are fixed in position.\nStep 3: Melting allows the ions to move freely.\nStep 4: The moving ions carry electric charge.","steps":["Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: In solid sodium chloride, the ions are fixed in position.","Step 3: Melting allows the ions to move freely.","Step 4: The moving ions carry electric charge."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 1),
  (2206, 558, 'Why does solid sodium chloride not conduct electricity effectively?', 'text', 1, 'Focus on the core principle of Electrolytes.', '{"why":"The ions become mobile only when the substance is molten or dissolved.","sol":"Step 1: Solid NaCl contains ions.\nStep 2: The ions are held in fixed positions in the lattice.\nStep 3: They cannot move freely through the solid.\nStep 4: Therefore they cannot carry current through the substance.","steps":["Step 1: Solid NaCl contains ions.","Step 2: The ions are held in fixed positions in the lattice.","Step 3: They cannot move freely through the solid.","Step 4: Therefore they cannot carry current through the substance."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 2),
  (2207, 558, 'A student says that solid NaCl conducts electricity because it contains ions. Is the statement complete?', 'text', 1, 'Ask whether the ions can move.', '{"why":"Electrical conduction requires mobile charged particles.","sol":"Step 1: Solid NaCl contains ions.\nStep 2: The ions are fixed in the crystal lattice.\nStep 3: Therefore they cannot move freely.","steps":["Step 1: Solid NaCl contains ions.","Step 2: The ions are fixed in the crystal lattice.","Step 3: Therefore they cannot move freely."],"options":[],"conceptId":"chemistry_electrochemistry_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolytes"}', 3),
  (2208, 559, 'Define electrolysis.', 'text', 1, 'Focus on the core principle of Meaning of Electrolysis.', '{"why":"Electrical energy drives a non-spontaneous chemical decomposition.","sol":"Step 1: Identify electrolysis as a chemical process.\nStep 2: An ionic substance is decomposed.\nStep 3: Electrical energy is supplied to cause the decomposition.","steps":["Step 1: Identify electrolysis as a chemical process.","Step 2: An ionic substance is decomposed.","Step 3: Electrical energy is supplied to cause the decomposition."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 0),
  (2209, 559, 'What happens to molten sodium chloride during electrolysis?', 'text', 1, 'Focus on the core principle of Meaning of Electrolysis.', '{"why":"The electric current causes the ions to discharge at the electrodes.","sol":"Step 1: Molten NaCl contains mobile Na⁺ and Cl⁻ ions.\nStep 2: Na⁺ ions move towards the negative electrode.\nStep 3: Cl⁻ ions move towards the positive electrode.\nStep 4: Sodium and chlorine are formed.","steps":["Step 1: Molten NaCl contains mobile Na⁺ and Cl⁻ ions.","Step 2: Na⁺ ions move towards the negative electrode.","Step 3: Cl⁻ ions move towards the positive electrode.","Step 4: Sodium and chlorine are formed."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 1),
  (2210, 559, 'Write the overall equation for electrolysis of molten sodium chloride.', 'text', 1, 'Focus on the core principle of Meaning of Electrolysis.', '{"why":"The equation conserves sodium and chlorine atoms.","sol":"Step 1: Sodium chloride provides Na⁺ and Cl⁻ ions.\nStep 2: Two chloride ions form one Cl₂ molecule.\nStep 3: Two sodium ions form two sodium atoms.\nStep 4: Balance the equation.","steps":["Step 1: Sodium chloride provides Na⁺ and Cl⁻ ions.","Step 2: Two chloride ions form one Cl₂ molecule.","Step 3: Two sodium ions form two sodium atoms.","Step 4: Balance the equation."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 2),
  (2211, 559, 'Can electrolysis occur in a solid ionic compound under ordinary conditions?', 'text', 1, 'Think about whether its ions can move.', '{"why":"Mobile ions are required to carry the current.","sol":"Step 1: Electrolysis requires mobile ions.\nStep 2: Ions in a solid ionic lattice are not free to move.\nStep 3: Therefore the solid cannot normally undergo electrolysis.","steps":["Step 1: Electrolysis requires mobile ions.","Step 2: Ions in a solid ionic lattice are not free to move.","Step 3: Therefore the solid cannot normally undergo electrolysis."],"options":[],"conceptId":"chemistry_electrochemistry_meaning_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Meaning of Electrolysis"}', 3),
  (2212, 560, 'What is an electrode?', 'text', 1, 'Focus on the core principle of Electrodes.', '{"why":"Electrodes connect the external circuit to the ions in the electrolyte.","sol":"Step 1: An electrode is placed in contact with the electrolyte.\nStep 2: It provides a conducting path for electric current.\nStep 3: Therefore it allows current to enter or leave the electrolyte.","steps":["Step 1: An electrode is placed in contact with the electrolyte.","Step 2: It provides a conducting path for electric current.","Step 3: Therefore it allows current to enter or leave the electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 0),
  (2213, 560, 'Which electrode attracts positive ions during electrolysis?', 'text', 1, 'Focus on the core principle of Electrodes.', '{"why":"Positive ions are attracted to the negative cathode.","sol":"Step 1: Positive ions are cations.\nStep 2: Opposite charges attract.\nStep 3: Therefore positive ions move towards the negative electrode.\nStep 4: The negative electrode is the cathode.","steps":["Step 1: Positive ions are cations.","Step 2: Opposite charges attract.","Step 3: Therefore positive ions move towards the negative electrode.","Step 4: The negative electrode is the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 1),
  (2214, 560, 'Which electrode attracts negative ions?', 'text', 1, 'Focus on the core principle of Electrodes.', '{"why":"Negative ions are attracted to the positive anode.","sol":"Step 1: Negative ions are anions.\nStep 2: Opposite charges attract.\nStep 3: Negative ions move towards the positive electrode.\nStep 4: The positive electrode is the anode.","steps":["Step 1: Negative ions are anions.","Step 2: Opposite charges attract.","Step 3: Negative ions move towards the positive electrode.","Step 4: The positive electrode is the anode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 2),
  (2215, 560, 'A student says Cl⁻ ions move to the cathode. Correct the statement.', 'text', 1, 'Cl⁻ is negatively charged.', '{"why":"Negative ions are attracted to the positive electrode.","sol":"Step 1: Cl⁻ has a negative charge.\nStep 2: It is attracted to the positive electrode.\nStep 3: The positive electrode is the anode.","steps":["Step 1: Cl⁻ has a negative charge.","Step 2: It is attracted to the positive electrode.","Step 3: The positive electrode is the anode."],"options":[],"conceptId":"chemistry_electrochemistry_electrodes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrodes"}', 3),
  (2216, 561, 'What is the charge of the anode during electrolysis?', 'text', 1, 'Focus on the core principle of Anode.', '{"why":"In an electrolytic cell, the external power supply makes the anode positive.","sol":"Step 1: Recall the electrodes in an electrolytic cell.\nStep 2: The cathode is negative.\nStep 3: Therefore the anode is positive.","steps":["Step 1: Recall the electrodes in an electrolytic cell.","Step 2: The cathode is negative.","Step 3: Therefore the anode is positive."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 0),
  (2217, 561, 'What happens to chloride ions at the anode?', 'text', 1, 'Focus on the core principle of Anode.', '{"why":"Loss of electrons is oxidation, and oxidation occurs at the anode.","sol":"Step 1: Chloride ions are negative ions.\nStep 2: They move towards the positive anode.\nStep 3: At the anode they lose electrons.\nStep 4: Two chloride ions form one chlorine molecule.","steps":["Step 1: Chloride ions are negative ions.","Step 2: They move towards the positive anode.","Step 3: At the anode they lose electrons.","Step 4: Two chloride ions form one chlorine molecule."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 1),
  (2218, 561, 'What type of process occurs at the anode?', 'text', 1, 'Focus on the core principle of Anode.', '{"why":"The anode is the site of oxidation.","sol":"Step 1: Ions at the anode lose electrons.\nStep 2: Loss of electrons is oxidation.\nStep 3: Therefore oxidation occurs at the anode.","steps":["Step 1: Ions at the anode lose electrons.","Step 2: Loss of electrons is oxidation.","Step 3: Therefore oxidation occurs at the anode."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 2),
  (2219, 561, 'At which electrode would Br⁻ ions be discharged during electrolysis?', 'text', 1, 'Br⁻ is negatively charged.', '{"why":"Negative ions are attracted to the positive anode.","sol":"Step 1: Br⁻ is an anion.\nStep 2: Anions move towards the positive electrode.\nStep 3: The positive electrode is the anode.","steps":["Step 1: Br⁻ is an anion.","Step 2: Anions move towards the positive electrode.","Step 3: The positive electrode is the anode."],"options":[],"conceptId":"chemistry_electrochemistry_anode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Anode"}', 3),
  (2220, 562, 'What is the charge of the cathode during electrolysis?', 'text', 1, 'Focus on the core principle of Cathode.', '{"why":"The external power supply makes the cathode negative in an electrolytic cell.","sol":"Step 1: Recall the two electrodes.\nStep 2: The anode is positive.\nStep 3: Therefore the cathode is negative.","steps":["Step 1: Recall the two electrodes.","Step 2: The anode is positive.","Step 3: Therefore the cathode is negative."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 0),
  (2221, 562, 'What happens to sodium ions at the cathode?', 'text', 1, 'Focus on the core principle of Cathode.', '{"why":"Gain of electrons is reduction, and reduction occurs at the cathode.","sol":"Step 1: Na⁺ is a positive ion.\nStep 2: It moves towards the negative cathode.\nStep 3: It gains one electron.\nStep 4: It forms a sodium atom.","steps":["Step 1: Na⁺ is a positive ion.","Step 2: It moves towards the negative cathode.","Step 3: It gains one electron.","Step 4: It forms a sodium atom."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 1),
  (2222, 562, 'What type of process occurs at the cathode?', 'text', 1, 'Focus on the core principle of Cathode.', '{"why":"The cathode is the site of reduction.","sol":"Step 1: Positive ions gain electrons at the cathode.\nStep 2: Gain of electrons is reduction.\nStep 3: Therefore reduction occurs at the cathode.","steps":["Step 1: Positive ions gain electrons at the cathode.","Step 2: Gain of electrons is reduction.","Step 3: Therefore reduction occurs at the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 2),
  (2223, 562, 'A student says that positive ions move to the anode during electrolysis. Correct the statement.', 'text', 1, 'Positive ions are attracted to which electrode?', '{"why":"Opposite charges attract.","sol":"Step 1: Positive ions are attracted to negative charges.\nStep 2: The cathode is negative during electrolysis.\nStep 3: Therefore positive ions move to the cathode.","steps":["Step 1: Positive ions are attracted to negative charges.","Step 2: The cathode is negative during electrolysis.","Step 3: Therefore positive ions move to the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_cathode","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Cathode"}', 3),
  (2224, 563, 'What are the products of electrolysis of molten sodium chloride?', 'text', 1, 'Focus on the core principle of Electrolysis of Molten Compounds.', '{"why":"Na⁺ forms sodium at the cathode while Cl⁻ forms chlorine at the anode.","sol":"Step 1: Molten NaCl contains Na⁺ and Cl⁻ ions.\nStep 2: Na⁺ is reduced at the cathode to form sodium.\nStep 3: Cl⁻ is oxidised at the anode to form chlorine.\nStep 4: Therefore the products are sodium and chlorine.","steps":["Step 1: Molten NaCl contains Na⁺ and Cl⁻ ions.","Step 2: Na⁺ is reduced at the cathode to form sodium.","Step 3: Cl⁻ is oxidised at the anode to form chlorine.","Step 4: Therefore the products are sodium and chlorine."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 0),
  (2225, 563, 'Write the half-equation for sodium ions at the cathode.', 'text', 1, 'Focus on the core principle of Electrolysis of Molten Compounds.', '{"why":"The sodium ion is reduced by gaining an electron.","sol":"Step 1: Sodium ion has a +1 charge.\nStep 2: It must gain one electron to become neutral.\nStep 3: Write the half-equation.","steps":["Step 1: Sodium ion has a +1 charge.","Step 2: It must gain one electron to become neutral.","Step 3: Write the half-equation."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 1),
  (2226, 563, 'Write the half-equation for chloride ions at the anode.', 'text', 1, 'Focus on the core principle of Electrolysis of Molten Compounds.', '{"why":"Chloride ions are oxidised to chlorine gas.","sol":"Step 1: Chloride ions lose electrons at the anode.\nStep 2: Two chloride ions form one chlorine molecule.\nStep 3: Two electrons are released.","steps":["Step 1: Chloride ions lose electrons at the anode.","Step 2: Two chloride ions form one chlorine molecule.","Step 3: Two electrons are released."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 2),
  (2227, 563, 'Why is sodium not produced from solid sodium chloride during electrolysis?', 'text', 1, 'Think about the movement of ions in solid NaCl.', '{"why":"The compound must be molten or dissolved for its ions to carry current.","sol":"Step 1: Solid NaCl has ions fixed in a lattice.\nStep 2: The ions cannot move freely.\nStep 3: Therefore electrolysis cannot proceed normally.","steps":["Step 1: Solid NaCl has ions fixed in a lattice.","Step 2: The ions cannot move freely.","Step 3: Therefore electrolysis cannot proceed normally."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_molten_compounds","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Molten Compounds"}', 3),
  (2228, 564, 'Why is electrolysis of an aqueous solution different from electrolysis of a molten compound?', 'text', 1, 'Focus on the core principle of Electrolysis of Aqueous Solutions.', '{"why":"The presence of water changes which species are available at the electrodes.","sol":"Step 1: A molten compound mainly contains ions from the compound.\nStep 2: An aqueous solution contains ions from the compound and ions associated with water.\nStep 3: These ions can compete for discharge.","steps":["Step 1: A molten compound mainly contains ions from the compound.","Step 2: An aqueous solution contains ions from the compound and ions associated with water.","Step 3: These ions can compete for discharge."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 0),
  (2229, 564, 'Name the four ions commonly considered when aqueous sodium chloride is electrolysed.', 'text', 1, 'Focus on the core principle of Electrolysis of Aqueous Solutions.', '{"why":"These are the ions available for consideration in aqueous sodium chloride.","sol":"Step 1: Sodium chloride supplies Na⁺ and Cl⁻.\nStep 2: Water supplies H⁺ and OH⁻ for the electrolysis analysis.\nStep 3: List all four ions.","steps":["Step 1: Sodium chloride supplies Na⁺ and Cl⁻.","Step 2: Water supplies H⁺ and OH⁻ for the electrolysis analysis.","Step 3: List all four ions."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 1),
  (2230, 564, 'Why can water affect the products obtained during electrolysis of an aqueous solution?', 'text', 1, 'Focus on the core principle of Electrolysis of Aqueous Solutions.', '{"why":"The final products depend on which ions are preferentially discharged.","sol":"Step 1: Water provides additional ions.\nStep 2: These ions can move towards the electrodes.\nStep 3: They may be discharged instead of ions from the dissolved salt.","steps":["Step 1: Water provides additional ions.","Step 2: These ions can move towards the electrodes.","Step 3: They may be discharged instead of ions from the dissolved salt."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 2),
  (2231, 564, 'A student treats aqueous NaCl as though it contains only Na⁺ and Cl⁻. What important ions have been omitted?', 'text', 1, 'Consider the water in the solution.', '{"why":"Water introduces additional ionic species into an aqueous electrolyte.","sol":"Step 1: Aqueous NaCl contains Na⁺ and Cl⁻ from the salt.\nStep 2: Water also contributes H⁺ and OH⁻ to the electrolysis analysis.\nStep 3: Therefore two additional ions must be considered.","steps":["Step 1: Aqueous NaCl contains Na⁺ and Cl⁻ from the salt.","Step 2: Water also contributes H⁺ and OH⁻ to the electrolysis analysis.","Step 3: Therefore two additional ions must be considered."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_aqueous_solutions","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Aqueous Solutions"}', 3),
  (2232, 565, 'Which substance is deposited at the cathode during electrolysis of aqueous copper(II) sulphate using inert electrodes?', 'text', 1, 'Focus on the core principle of Electrolysis of Copper(II) Sulphate.', '{"why":"Cu²⁺ ions are reduced to copper atoms at the cathode.","sol":"Step 1: Copper(II) sulphate provides Cu²⁺ ions.\nStep 2: Cu²⁺ ions move to the negative cathode.\nStep 3: Cu²⁺ gains two electrons.\nStep 4: Copper metal is deposited.","steps":["Step 1: Copper(II) sulphate provides Cu²⁺ ions.","Step 2: Cu²⁺ ions move to the negative cathode.","Step 3: Cu²⁺ gains two electrons.","Step 4: Copper metal is deposited."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 0),
  (2233, 565, 'Write the cathode half-equation for aqueous copper(II) sulphate.', 'text', 1, 'Focus on the core principle of Electrolysis of Copper(II) Sulphate.', '{"why":"Copper(II) ions gain electrons and are reduced to copper.","sol":"Step 1: Copper(II) ion is Cu²⁺.\nStep 2: It needs two electrons to become neutral copper.\nStep 3: Write the balanced half-equation.","steps":["Step 1: Copper(II) ion is Cu²⁺.","Step 2: It needs two electrons to become neutral copper.","Step 3: Write the balanced half-equation."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 1),
  (2234, 565, 'What gas is produced at the anode when inert electrodes are used?', 'text', 1, 'Focus on the core principle of Electrolysis of Copper(II) Sulphate.', '{"why":"Oxidation of water produces oxygen at the inert anode.","sol":"Step 1: Sulphate ions are not preferentially discharged under these conditions.\nStep 2: Water/OH⁻ is oxidised at the anode.\nStep 3: Oxygen is formed.","steps":["Step 1: Sulphate ions are not preferentially discharged under these conditions.","Step 2: Water/OH⁻ is oxidised at the anode.","Step 3: Oxygen is formed."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 2),
  (2235, 565, 'A student predicts that copper metal will form at the anode during electrolysis of aqueous CuSO₄ using inert electrodes. Correct the prediction.', 'text', 1, 'Copper(II) ions are positive. Which electrode attracts them?', '{"why":"Cu²⁺ ions are reduced at the cathode.","sol":"Step 1: Cu²⁺ ions are positively charged.\nStep 2: They move towards the negative cathode.\nStep 3: They gain electrons there.\nStep 4: Copper is therefore deposited at the cathode.","steps":["Step 1: Cu²⁺ ions are positively charged.","Step 2: They move towards the negative cathode.","Step 3: They gain electrons there.","Step 4: Copper is therefore deposited at the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_electrolysis_of_copper_ii_sulphate","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electrolysis of Copper(II) Sulphate"}', 3),
  (2236, 566, 'What is electroplating?', 'text', 1, 'Focus on the core principle of Electroplating.', '{"why":"Electrolysis can be used to deposit metal ions onto an object''s surface.","sol":"Step 1: Identify electroplating as an electrolysis process.\nStep 2: A layer of one metal is deposited onto another object.\nStep 3: The deposited metal forms a coating.","steps":["Step 1: Identify electroplating as an electrolysis process.","Step 2: A layer of one metal is deposited onto another object.","Step 3: The deposited metal forms a coating."],"options":[],"conceptId":"chemistry_electrochemistry_electroplating","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Electroplating"}', 0),
  (2237, 566, 'Which electrode is the object being plated?', 'text', 1, 'Focus on the core principle of Electroplating.', '{"why":"Positive metal ions are reduced and deposited at the negative cathode.","sol":"Step 1: Metal ions are positively charged.\nStep 2: Positive metal ions move towards the negative electrode.\nStep 3: Therefore the object must be connected to the negative electrode.","steps":["Step 1: Metal ions are positively charged.","Step 2: Positive metal ions move towards the negative electrode.","Step 3: Therefore the object must be connected to the negative electrode."],"options":[],"conceptId":"chemistry_electrochemistry_electroplating","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Electroplating"}', 1),
  (2238, 566, 'Write the half-equation for copper deposition during copper electroplating.', 'text', 1, 'Focus on the core principle of Electroplating.', '{"why":"Copper ions gain electrons and become copper metal.","sol":"Step 1: Copper ions are Cu²⁺.\nStep 2: Each Cu²⁺ ion needs two electrons.\nStep 3: Write the reduction equation.","steps":["Step 1: Copper ions are Cu²⁺.","Step 2: Each Cu²⁺ ion needs two electrons.","Step 3: Write the reduction equation."],"options":[],"conceptId":"chemistry_electrochemistry_electroplating","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Electroplating"}', 2),
  (2239, 566, 'A student connects the object to be plated to the positive terminal. Will metal ions normally deposit on it?', 'text', 1, 'The object being plated must attract positive metal ions.', '{"why":"Positive metal ions are deposited at the negative cathode.","sol":"Step 1: Metal ions are positively charged.\nStep 2: They are attracted to the negative electrode.\nStep 3: The object being plated should therefore be the cathode.","steps":["Step 1: Metal ions are positively charged.","Step 2: They are attracted to the negative electrode.","Step 3: The object being plated should therefore be the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_electroplating","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Electroplating"}', 3),
  (2240, 567, 'State two applications of electrolysis.', 'text', 1, 'Focus on the core principle of Applications of Electrolysis.', '{"why":"Electrical energy can drive both metal deposition and decomposition of ionic compounds.","sol":"Step 1: Recall the major uses of electrolysis.\nStep 2: Select any two distinct applications.\nStep 3: Examples include electroplating and extraction of reactive metals.","steps":["Step 1: Recall the major uses of electrolysis.","Step 2: Select any two distinct applications.","Step 3: Examples include electroplating and extraction of reactive metals."],"options":[],"conceptId":"chemistry_electrochemistry_applications_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Applications of Electrolysis"}', 0),
  (2241, 567, 'Why is electrolysis used to extract aluminium?', 'text', 1, 'Focus on the core principle of Applications of Electrolysis.', '{"why":"The high reactivity of aluminium makes electrolysis necessary for its extraction.","sol":"Step 1: Aluminium is high in the reactivity series.\nStep 2: Its compounds are difficult to reduce using carbon.\nStep 3: Molten aluminium oxide can be decomposed by electrolysis.\nStep 4: Aluminium is produced at the cathode.","steps":["Step 1: Aluminium is high in the reactivity series.","Step 2: Its compounds are difficult to reduce using carbon.","Step 3: Molten aluminium oxide can be decomposed by electrolysis.","Step 4: Aluminium is produced at the cathode."],"options":[],"conceptId":"chemistry_electrochemistry_applications_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Applications of Electrolysis"}', 1),
  (2242, 567, 'State two products obtained from electrolysis of brine.', 'text', 1, 'Focus on the core principle of Applications of Electrolysis.', '{"why":"Electrolysis of brine separates the components into useful industrial products.","sol":"Step 1: Brine is concentrated aqueous sodium chloride.\nStep 2: Electrolysis produces chlorine at the anode.\nStep 3: Hydrogen is produced at the cathode.\nStep 4: Sodium hydroxide remains in the solution.","steps":["Step 1: Brine is concentrated aqueous sodium chloride.","Step 2: Electrolysis produces chlorine at the anode.","Step 3: Hydrogen is produced at the cathode.","Step 4: Sodium hydroxide remains in the solution."],"options":[],"conceptId":"chemistry_electrochemistry_applications_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Applications of Electrolysis"}', 2),
  (2243, 567, 'A student claims electrolysis is useful only for extracting metals. Give one other application.', 'text', 1, 'Think about depositing a metal onto an object.', '{"why":"Electrolysis is used to coat objects with a layer of another metal.","sol":"Step 1: Electrolysis can cause metal ions to gain electrons.\nStep 2: The metal can be deposited onto an object.\nStep 3: This process is electroplating.","steps":["Step 1: Electrolysis can cause metal ions to gain electrons.","Step 2: The metal can be deposited onto an object.","Step 3: This process is electroplating."],"options":[],"conceptId":"chemistry_electrochemistry_applications_of_electrolysis","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Applications of Electrolysis"}', 3),
  (2244, 568, 'What is a simple cell?', 'text', 1, 'Focus on the core principle of Simple Cells.', '{"why":"Chemical reactions in the cell produce the electron flow that supplies electrical energy.","sol":"Step 1: A simple cell contains two electrodes and an electrolyte.\nStep 2: Chemical reactions occur at the electrodes.\nStep 3: These reactions cause electrons to flow through an external circuit.\nStep 4: The cell therefore converts chemical energy into electrical energy.","steps":["Step 1: A simple cell contains two electrodes and an electrolyte.","Step 2: Chemical reactions occur at the electrodes.","Step 3: These reactions cause electrons to flow through an external circuit.","Step 4: The cell therefore converts chemical energy into electrical energy."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 0),
  (2245, 568, 'State three main components of a simple cell.', 'text', 1, 'Focus on the core principle of Simple Cells.', '{"why":"These components allow the chemical reaction to produce a flow of electrons through the external circuit.","sol":"Step 1: Identify the substances involved in the electrochemical reaction.\nStep 2: The cell needs two electrodes.\nStep 3: The electrodes must be in contact with an electrolyte.\nStep 4: An external circuit provides a path for electron flow.","steps":["Step 1: Identify the substances involved in the electrochemical reaction.","Step 2: The cell needs two electrodes.","Step 3: The electrodes must be in contact with an electrolyte.","Step 4: An external circuit provides a path for electron flow."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 1),
  (2246, 568, 'What form of energy is converted into electrical energy in a simple cell?', 'text', 1, 'Focus on the core principle of Simple Cells.', '{"why":"A simple cell obtains its electrical output from chemical reactions.","sol":"Step 1: Chemical reactions occur inside the cell.\nStep 2: These reactions provide the energy needed to drive electron flow.\nStep 3: Therefore, chemical energy is converted into electrical energy.","steps":["Step 1: Chemical reactions occur inside the cell.","Step 2: These reactions provide the energy needed to drive electron flow.","Step 3: Therefore, chemical energy is converted into electrical energy."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 2),
  (2247, 568, 'A student connects two different metal electrodes in an electrolyte but does not connect them through an external circuit. Why is there no useful current through an external device?', 'text', 1, 'Think about the path required for electrons to flow.', '{"why":"A useful current requires a complete circuit.","sol":"Step 1: Chemical reactions can cause a potential difference between the electrodes.\nStep 2: Electrons need a conducting path between the electrodes.\nStep 3: Without an external circuit, there is no complete path through the external device.","steps":["Step 1: Chemical reactions can cause a potential difference between the electrodes.","Step 2: Electrons need a conducting path between the electrodes.","Step 3: Without an external circuit, there is no complete path through the external device."],"options":[],"conceptId":"chemistry_electrochemistry_simple_cells","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Simple Cells"}', 3),
  (2248, 569, 'What is the unit used to measure the voltage of a chemical cell?', 'text', 1, 'Focus on the core principle of Chemical Cell Voltage.', '{"why":"The volt is the SI unit for potential difference.","sol":"Step 1: Voltage is a measure of potential difference.\nStep 2: Potential difference is measured in volts.\nStep 3: Therefore, the unit is V.","steps":["Step 1: Voltage is a measure of potential difference.","Step 2: Potential difference is measured in volts.","Step 3: Therefore, the unit is V."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 0),
  (2249, 569, 'Two identical cells each produce 1.5 V. They are connected in series in the same direction. Calculate the total voltage.', 'text', 1, 'Focus on the core principle of Chemical Cell Voltage.', '{"why":"The voltages of cells connected in series in the same direction add together.","sol":"Step 1: Voltage of first cell = 1.5 V.\nStep 2: Voltage of second cell = 1.5 V.\nStep 3: Cells are connected in series in the same direction.\nStep 4: Add their voltages: 1.5 + 1.5 = 3.0 V.","steps":["Step 1: Voltage of first cell = 1.5 V.","Step 2: Voltage of second cell = 1.5 V.","Step 3: Cells are connected in series in the same direction.","Step 4: Add their voltages: 1.5 + 1.5 = 3.0 V."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 1),
  (2250, 569, 'Three cells each produce 2 V and are connected in series in the same direction. What is the total voltage?', 'text', 1, 'Focus on the core principle of Chemical Cell Voltage.', '{"why":"The voltages of series-connected cells add together.","sol":"Step 1: Each cell produces 2 V.\nStep 2: There are 3 cells.\nStep 3: Total voltage = 2 + 2 + 2.\nStep 4: Total voltage = 6 V.","steps":["Step 1: Each cell produces 2 V.","Step 2: There are 3 cells.","Step 3: Total voltage = 2 + 2 + 2.","Step 4: Total voltage = 6 V."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2251, 569, 'A circuit requires 6 V. You have four identical cells, each rated at 1.5 V. How should they be connected to obtain 6 V?', 'text', 1, 'Add the voltages of cells connected in series.', '{"why":"Four 1.5 V cells produce 6 V when their voltages are added in series.","sol":"Step 1: Each cell produces 1.5 V.\nStep 2: Four cells are available.\nStep 3: Total voltage = 1.5 × 4.\nStep 4: Total voltage = 6 V.\nStep 5: Therefore, connect the four cells in series in the same direction.","steps":["Step 1: Each cell produces 1.5 V.","Step 2: Four cells are available.","Step 3: Total voltage = 1.5 × 4.","Step 4: Total voltage = 6 V.","Step 5: Therefore, connect the four cells in series in the same direction."],"options":[],"conceptId":"chemistry_electrochemistry_chemical_cell_voltage","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Chemical Cell Voltage"}', 3),
  (2252, 570, 'What is a battery?', 'text', 1, 'Focus on the core principle of Batteries.', '{"why":"A battery uses electrochemical cells as its source of electrical energy.","sol":"Step 1: An electrochemical cell produces electrical energy from chemical reactions.\nStep 2: A battery consists of one or more electrochemical cells arranged to supply electrical energy.\nStep 3: Therefore, a battery is an arrangement of electrochemical cells.","steps":["Step 1: An electrochemical cell produces electrical energy from chemical reactions.","Step 2: A battery consists of one or more electrochemical cells arranged to supply electrical energy.","Step 3: Therefore, a battery is an arrangement of electrochemical cells."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 0),
  (2253, 570, 'What is the difference between a primary battery and a secondary battery?', 'text', 1, 'Focus on the core principle of Batteries.', '{"why":"Charging a secondary battery reverses or restores the chemical changes that occur during discharge.","sol":"Step 1: Consider whether the battery can be restored by charging.\nStep 2: Primary batteries are generally not designed to be recharged.\nStep 3: Secondary batteries can be recharged.","steps":["Step 1: Consider whether the battery can be restored by charging.","Step 2: Primary batteries are generally not designed to be recharged.","Step 3: Secondary batteries can be recharged."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 1),
  (2254, 570, 'Four identical 1.5 V cells are connected in series. Calculate the total voltage.', 'text', 1, 'Focus on the core principle of Batteries.', '{"why":"Cells connected in series have their voltages added.","sol":"Step 1: Voltage of one cell = 1.5 V.\nStep 2: Number of cells = 4.\nStep 3: Total voltage = 1.5 × 4.\nStep 4: Total voltage = 6 V.","steps":["Step 1: Voltage of one cell = 1.5 V.","Step 2: Number of cells = 4.","Step 3: Total voltage = 1.5 × 4.","Step 4: Total voltage = 6 V."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 2),
  (2255, 570, 'A student connects three 1.5 V cells in series but one cell is connected in the opposite direction. What is the resulting voltage if the opposing cell subtracts from the other two?', 'text', 1, 'Add the two cells in the same direction, then subtract the opposing cell.', '{"why":"The voltage of the oppositely connected cell opposes the voltage of the other two cells.","sol":"Step 1: Two cells in the same direction give 1.5 + 1.5 = 3.0 V.\nStep 2: The opposing cell contributes −1.5 V.\nStep 3: Resulting voltage = 3.0 − 1.5.\nStep 4: Resulting voltage = 1.5 V.","steps":["Step 1: Two cells in the same direction give 1.5 + 1.5 = 3.0 V.","Step 2: The opposing cell contributes −1.5 V.","Step 3: Resulting voltage = 3.0 − 1.5.","Step 4: Resulting voltage = 1.5 V."],"options":[],"conceptId":"chemistry_electrochemistry_batteries","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Batteries"}', 3),
  (2256, 571, 'What is a strong electrolyte?', 'text', 1, 'Focus on the core principle of Strong Electrolytes.', '{"why":"The large concentration of mobile ions allows electrical charge to move through the solution.","sol":"Step 1: A strong electrolyte is dissolved in water.\nStep 2: It completely dissociates or ionises into ions.\nStep 3: The ions are free to move through the solution.\nStep 4: The mobile ions allow the solution to conduct electricity well.","steps":["Step 1: A strong electrolyte is dissolved in water.","Step 2: It completely dissociates or ionises into ions.","Step 3: The ions are free to move through the solution.","Step 4: The mobile ions allow the solution to conduct electricity well."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 0),
  (2257, 571, 'Write the ionic equation for sodium chloride dissolving in water.', 'text', 1, 'Focus on the core principle of Strong Electrolytes.', '{"why":"Sodium chloride separates into sodium ions and chloride ions in aqueous solution.","sol":"Step 1: Identify the ions in sodium chloride.\nStep 2: Sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 3: Dissolving separates the ions.\nStep 4: Write the equation as NaCl(aq) → Na⁺(aq) + Cl⁻(aq).","steps":["Step 1: Identify the ions in sodium chloride.","Step 2: Sodium chloride contains Na⁺ and Cl⁻ ions.","Step 3: Dissolving separates the ions.","Step 4: Write the equation as NaCl(aq) → Na⁺(aq) + Cl⁻(aq)."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 1),
  (2258, 571, 'Why does a strong electrolyte conduct electricity well?', 'text', 1, 'Focus on the core principle of Strong Electrolytes.', '{"why":"Electrical conduction in an electrolyte solution occurs through the movement of ions.","sol":"Step 1: The substance produces many ions in solution.\nStep 2: The ions are free to move.\nStep 3: Moving charged particles carry electrical charge.","steps":["Step 1: The substance produces many ions in solution.","Step 2: The ions are free to move.","Step 3: Moving charged particles carry electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 2),
  (2259, 571, 'A solution contains a substance that completely dissociates into ions and conducts electricity strongly. How would you classify the substance?', 'text', 1, 'Think about the extent of ion formation.', '{"why":"Complete ionisation or dissociation produces many mobile ions and strong electrical conductivity.","sol":"Step 1: The substance completely dissociates into ions.\nStep 2: The solution therefore contains many mobile ions.\nStep 3: This is characteristic of a strong electrolyte.","steps":["Step 1: The substance completely dissociates into ions.","Step 2: The solution therefore contains many mobile ions.","Step 3: This is characteristic of a strong electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_strong_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Strong Electrolytes"}', 3),
  (2260, 572, 'What is a weak electrolyte?', 'text', 1, 'Focus on the core principle of Weak Electrolytes.', '{"why":"Incomplete ionisation means fewer mobile ions are present compared with a strong electrolyte of similar concentration.","sol":"Step 1: A weak electrolyte is dissolved in water.\nStep 2: Only part of the substance ionises or dissociates.\nStep 3: Both ions and un-ionised particles remain in the solution.","steps":["Step 1: A weak electrolyte is dissolved in water.","Step 2: Only part of the substance ionises or dissociates.","Step 3: Both ions and un-ionised particles remain in the solution."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 0),
  (2261, 572, 'Why does a weak electrolyte conduct electricity less strongly than a strong electrolyte of similar concentration?', 'text', 1, 'Focus on the core principle of Weak Electrolytes.', '{"why":"Electrical conductivity depends on the availability and movement of charged particles.","sol":"Step 1: A weak electrolyte only partially ionises.\nStep 2: Therefore, fewer mobile ions are produced.\nStep 3: Fewer mobile ions carry less electrical charge through the solution.","steps":["Step 1: A weak electrolyte only partially ionises.","Step 2: Therefore, fewer mobile ions are produced.","Step 3: Fewer mobile ions carry less electrical charge through the solution."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 1),
  (2262, 572, 'Write the ionisation equation for ethanoic acid in water.', 'text', 1, 'Focus on the core principle of Weak Electrolytes.', '{"why":"Only some ethanoic acid molecules ionise, so the process is represented as reversible.","sol":"Step 1: Ethanoic acid has the formula CH₃COOH.\nStep 2: It forms hydrogen ions and ethanoate ions.\nStep 3: Because it is a weak electrolyte, use a reversible arrow.\nStep 4: Write CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq).","steps":["Step 1: Ethanoic acid has the formula CH₃COOH.","Step 2: It forms hydrogen ions and ethanoate ions.","Step 3: Because it is a weak electrolyte, use a reversible arrow.","Step 4: Write CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq)."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 2),
  (2263, 572, 'A student says, ''A weak electrolyte does not contain ions.'' Is the statement correct?', 'text', 1, 'Weak means partial ionisation, not zero ionisation.', '{"why":"Weak electrolytes produce fewer ions because their ionisation is incomplete.","sol":"Step 1: A weak electrolyte partially ionises in water.\nStep 2: Partial ionisation produces some ions.\nStep 3: Therefore, ions are present even though many particles remain un-ionised.","steps":["Step 1: A weak electrolyte partially ionises in water.","Step 2: Partial ionisation produces some ions.","Step 3: Therefore, ions are present even though many particles remain un-ionised."],"options":[],"conceptId":"chemistry_electrochemistry_weak_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Weak Electrolytes"}', 3),
  (2264, 573, 'What is a non-electrolyte?', 'text', 1, 'Focus on the core principle of Non-electrolytes.', '{"why":"There are no mobile ions available to carry electrical charge.","sol":"Step 1: A non-electrolyte dissolves without producing mobile ions.\nStep 2: Without mobile ions, electrical charge cannot be carried through the solution by ions.\nStep 3: Therefore, its aqueous solution does not conduct electricity.","steps":["Step 1: A non-electrolyte dissolves without producing mobile ions.","Step 2: Without mobile ions, electrical charge cannot be carried through the solution by ions.","Step 3: Therefore, its aqueous solution does not conduct electricity."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q1","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 0),
  (2265, 573, 'Why does a sugar solution not conduct electricity like a sodium chloride solution?', 'text', 1, 'Focus on the core principle of Non-electrolytes.', '{"why":"Electrical conduction in aqueous electrolyte solutions depends on the movement of ions.","sol":"Step 1: Sugar dissolves as neutral molecules.\nStep 2: It does not produce ions in the solution.\nStep 3: Sodium chloride produces Na⁺ and Cl⁻ ions.\nStep 4: The sodium chloride ions can move and carry electrical charge.","steps":["Step 1: Sugar dissolves as neutral molecules.","Step 2: It does not produce ions in the solution.","Step 3: Sodium chloride produces Na⁺ and Cl⁻ ions.","Step 4: The sodium chloride ions can move and carry electrical charge."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q2","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 1),
  (2266, 573, 'Classify sodium chloride solution, ethanoic acid solution and sugar solution as strong electrolyte, weak electrolyte or non-electrolyte.', 'text', 1, 'Focus on the core principle of Non-electrolytes.', '{"why":"The classification depends on how extensively the substance produces mobile ions in solution.","sol":"Step 1: Sodium chloride produces ions in solution and is treated as a strong electrolyte.\nStep 2: Ethanoic acid only partially ionises, so it is a weak electrolyte.\nStep 3: Sugar does not produce ions, so it is a non-electrolyte.","steps":["Step 1: Sodium chloride produces ions in solution and is treated as a strong electrolyte.","Step 2: Ethanoic acid only partially ionises, so it is a weak electrolyte.","Step 3: Sugar does not produce ions, so it is a non-electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q3","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 2),
  (2267, 573, 'Three solutions are tested for electrical conductivity. Solution A conducts strongly, Solution B conducts weakly and Solution C does not conduct. Classify each solution.', 'text', 1, 'Match conductivity with the amount of mobile ions produced.', '{"why":"The three categories differ according to the extent to which mobile ions are produced in solution.","sol":"Step 1: Strong conductivity indicates many mobile ions.\nStep 2: Weak conductivity indicates fewer mobile ions.\nStep 3: No conductivity indicates no significant mobile ions.\nStep 4: Therefore, A is a strong electrolyte, B is a weak electrolyte and C is a non-electrolyte.","steps":["Step 1: Strong conductivity indicates many mobile ions.","Step 2: Weak conductivity indicates fewer mobile ions.","Step 3: No conductivity indicates no significant mobile ions.","Step 4: Therefore, A is a strong electrolyte, B is a weak electrolyte and C is a non-electrolyte."],"options":[],"conceptId":"chemistry_electrochemistry_non_electrolytes","skillId":"chemistry_electrochemistry","subskillId":"chemistry_electrochemistry_q4","subject":"chemistry","chapter":"electrochemistry","topic":"Non-electrolytes"}', 3),
  (2268, 574, 'What is organic chemistry?', 'text', 1, 'Focus on the core principle of Introduction to Organic Chemistry.', '{"why":"Carbon forms an enormous number of compounds with hydrogen and other elements.","sol":"Step 1: Organic chemistry deals mainly with compounds of carbon.\nStep 2: Many of these compounds contain carbon and hydrogen.\nStep 3: Therefore organic chemistry is the study of carbon compounds, especially hydrocarbons and their derivatives.","steps":["Step 1: Organic chemistry deals mainly with compounds of carbon.","Step 2: Many of these compounds contain carbon and hydrogen.","Step 3: Therefore organic chemistry is the study of carbon compounds, especially hydrocarbons and their derivatives."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 0),
  (2269, 574, 'State two examples of organic compounds.', 'text', 1, 'Focus on the core principle of Introduction to Organic Chemistry.', '{"why":"Both are carbon-containing organic compounds.","sol":"Step 1: Identify compounds containing carbon and hydrogen.\nStep 2: Methane contains carbon and hydrogen.\nStep 3: Ethanol also contains carbon and hydrogen.","steps":["Step 1: Identify compounds containing carbon and hydrogen.","Step 2: Methane contains carbon and hydrogen.","Step 3: Ethanol also contains carbon and hydrogen."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 1),
  (2270, 574, 'Is carbon dioxide an organic compound?', 'text', 1, 'Focus on the core principle of Introduction to Organic Chemistry.', '{"why":"Certain simple carbon compounds, including CO₂, are treated as inorganic in school chemistry.","sol":"Step 1: Carbon dioxide contains carbon.\nStep 2: However, not every carbon-containing compound is classified as organic.\nStep 3: CO₂ is treated as an inorganic carbon compound.","steps":["Step 1: Carbon dioxide contains carbon.","Step 2: However, not every carbon-containing compound is classified as organic.","Step 3: CO₂ is treated as an inorganic carbon compound."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 2),
  (2271, 574, 'A student says every compound containing carbon is organic. Is this correct?', 'text', 1, 'Think about carbon dioxide.', '{"why":"The presence of carbon alone does not make a compound organic.","sol":"Step 1: CO₂ contains carbon.\nStep 2: CO₂ is normally classified as inorganic.\nStep 3: Therefore not every carbon-containing compound is organic.","steps":["Step 1: CO₂ contains carbon.","Step 2: CO₂ is normally classified as inorganic.","Step 3: Therefore not every carbon-containing compound is organic."],"options":[],"conceptId":"chemistry_organic_chemistry_introduction_to_organic_chemistry","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Introduction to Organic Chemistry"}', 3),
  (2272, 575, 'What is meant by tetravalency of carbon?', 'text', 1, 'Focus on the core principle of Tetravalency of Carbon.', '{"why":"Carbon''s bonding capacity allows it to form many different compounds.","sol":"Step 1: Carbon has four electrons in its outer shell.\nStep 2: Carbon commonly forms four covalent bonds.\nStep 3: This ability is called tetravalency.","steps":["Step 1: Carbon has four electrons in its outer shell.","Step 2: Carbon commonly forms four covalent bonds.","Step 3: This ability is called tetravalency."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 0),
  (2273, 575, 'How many covalent bonds does carbon form in methane, CH₄?', 'text', 1, 'Focus on the core principle of Tetravalency of Carbon.', '{"why":"Carbon is tetravalent.","sol":"Step 1: Methane contains one carbon atom.\nStep 2: Its formula is CH₄.\nStep 3: Carbon bonds to four hydrogen atoms.\nStep 4: Therefore carbon forms four covalent bonds.","steps":["Step 1: Methane contains one carbon atom.","Step 2: Its formula is CH₄.","Step 3: Carbon bonds to four hydrogen atoms.","Step 4: Therefore carbon forms four covalent bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 1),
  (2274, 575, 'How many carbon atoms and hydrogen atoms are present in C₂H₆?', 'text', 1, 'Focus on the core principle of Tetravalency of Carbon.', '{"why":"Subscripts in a chemical formula show the number of atoms of each element.","sol":"Step 1: The subscript after C is 2.\nStep 2: Therefore there are 2 carbon atoms.\nStep 3: The subscript after H is 6.\nStep 4: Therefore there are 6 hydrogen atoms.","steps":["Step 1: The subscript after C is 2.","Step 2: Therefore there are 2 carbon atoms.","Step 3: The subscript after H is 6.","Step 4: Therefore there are 6 hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 2),
  (2275, 575, 'A student says carbon forms only two covalent bonds. Is this correct?', 'text', 1, 'Recall the meaning of tetravalency.', '{"why":"Carbon''s tetravalency is one reason it forms many organic compounds.","sol":"Step 1: Carbon is tetravalent.\nStep 2: Tetravalent means it can form four covalent bonds.\nStep 3: Therefore the statement is incorrect.","steps":["Step 1: Carbon is tetravalent.","Step 2: Tetravalent means it can form four covalent bonds.","Step 3: Therefore the statement is incorrect."],"options":[],"conceptId":"chemistry_organic_chemistry_tetravalency_of_carbon","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Tetravalency of Carbon"}', 3),
  (2276, 576, 'What is catenation?', 'text', 1, 'Focus on the core principle of Catenation.', '{"why":"Carbon-carbon bonding allows organic compounds to have many different structures.","sol":"Step 1: Identify bonding between atoms of the same element.\nStep 2: Carbon can bond strongly to other carbon atoms.\nStep 3: This allows chains, branches and rings to form.","steps":["Step 1: Identify bonding between atoms of the same element.","Step 2: Carbon can bond strongly to other carbon atoms.","Step 3: This allows chains, branches and rings to form."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 0),
  (2277, 576, 'Why can carbon form long chains?', 'text', 1, 'Focus on the core principle of Catenation.', '{"why":"Carbon''s ability to bond to itself is called catenation.","sol":"Step 1: Carbon atoms can form strong covalent bonds with other carbon atoms.\nStep 2: One carbon atom can bond to another carbon atom.\nStep 3: The process can continue repeatedly.\nStep 4: Long carbon chains can therefore form.","steps":["Step 1: Carbon atoms can form strong covalent bonds with other carbon atoms.","Step 2: One carbon atom can bond to another carbon atom.","Step 3: The process can continue repeatedly.","Step 4: Long carbon chains can therefore form."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 1),
  (2278, 576, 'How many carbon atoms are joined together in propane, C₃H₈?', 'text', 1, 'Focus on the core principle of Catenation.', '{"why":"The formula C₃H₈ contains three carbon atoms.","sol":"Step 1: Read the subscript after C.\nStep 2: The subscript is 3.\nStep 3: Therefore propane contains three carbon atoms.","steps":["Step 1: Read the subscript after C.","Step 2: The subscript is 3.","Step 3: Therefore propane contains three carbon atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 2),
  (2279, 576, 'Which property of carbon allows carbon atoms to form carbon chains?', 'text', 1, 'Think about carbon bonding to itself.', '{"why":"Catenation is carbon''s ability to bond to itself.","sol":"Step 1: Carbon atoms can bond to other carbon atoms.\nStep 2: This produces chains and other structures.\nStep 3: This property is catenation.","steps":["Step 1: Carbon atoms can bond to other carbon atoms.","Step 2: This produces chains and other structures.","Step 3: This property is catenation."],"options":[],"conceptId":"chemistry_organic_chemistry_catenation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Catenation"}', 3),
  (2280, 577, 'What is a hydrocarbon?', 'text', 1, 'Focus on the core principle of Hydrocarbons.', '{"why":"The name hydrocarbon reflects hydrogen and carbon.","sol":"Step 1: Identify the elements present.\nStep 2: A hydrocarbon contains carbon.\nStep 3: It also contains hydrogen.\nStep 4: No other elements are present in a hydrocarbon.","steps":["Step 1: Identify the elements present.","Step 2: A hydrocarbon contains carbon.","Step 3: It also contains hydrogen.","Step 4: No other elements are present in a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 0),
  (2281, 577, 'Is ethanol, C₂H₅OH, a hydrocarbon?', 'text', 1, 'Focus on the core principle of Hydrocarbons.', '{"why":"Hydrocarbons contain only carbon and hydrogen.","sol":"Step 1: Check the elements present.\nStep 2: Ethanol contains carbon and hydrogen.\nStep 3: It also contains oxygen.\nStep 4: Therefore it is not a hydrocarbon.","steps":["Step 1: Check the elements present.","Step 2: Ethanol contains carbon and hydrogen.","Step 3: It also contains oxygen.","Step 4: Therefore it is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 1),
  (2282, 577, 'Classify ethene, C₂H₄, as an alkane, alkene or alkyne.', 'text', 1, 'Focus on the core principle of Hydrocarbons.', '{"why":"Alkenes contain at least one carbon-carbon double bond.","sol":"Step 1: Ethene contains a carbon-carbon double bond.\nStep 2: Compounds containing a C=C double bond are alkenes.\nStep 3: Therefore ethene is an alkene.","steps":["Step 1: Ethene contains a carbon-carbon double bond.","Step 2: Compounds containing a C=C double bond are alkenes.","Step 3: Therefore ethene is an alkene."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 2),
  (2283, 577, 'A compound contains carbon, hydrogen and chlorine. Is it a hydrocarbon?', 'text', 1, 'Hydrocarbons contain how many elements?', '{"why":"A hydrocarbon must contain only carbon and hydrogen.","sol":"Step 1: A hydrocarbon contains only carbon and hydrogen.\nStep 2: The compound also contains chlorine.\nStep 3: Therefore it is not a hydrocarbon.","steps":["Step 1: A hydrocarbon contains only carbon and hydrogen.","Step 2: The compound also contains chlorine.","Step 3: Therefore it is not a hydrocarbon."],"options":[],"conceptId":"chemistry_organic_chemistry_hydrocarbons","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Hydrocarbons"}', 3),
  (2284, 578, 'What is an alkane?', 'text', 1, 'Focus on the core principle of Alkanes.', '{"why":"The absence of carbon-carbon multiple bonds makes an open-chain alkane saturated.","sol":"Step 1: Identify the type of hydrocarbon.\nStep 2: Alkanes contain only carbon-carbon single bonds.\nStep 3: Therefore they are saturated hydrocarbons.","steps":["Step 1: Identify the type of hydrocarbon.","Step 2: Alkanes contain only carbon-carbon single bonds.","Step 3: Therefore they are saturated hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 0),
  (2285, 578, 'State the general formula of open-chain alkanes.', 'text', 1, 'Focus on the core principle of Alkanes.', '{"why":"This formula applies to open-chain saturated hydrocarbons.","sol":"Step 1: Recall the alkane general formula.\nStep 2: Substitute the number of carbon atoms with n.\nStep 3: The formula is CₙH₂ₙ₊₂.","steps":["Step 1: Recall the alkane general formula.","Step 2: Substitute the number of carbon atoms with n.","Step 3: The formula is CₙH₂ₙ₊₂."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 1),
  (2286, 578, 'Find the molecular formula of the alkane with 6 carbon atoms.', 'text', 1, 'Focus on the core principle of Alkanes.', '{"why":"The alkane formula is CₙH₂ₙ₊₂.","sol":"Step 1: Use CₙH₂ₙ₊₂.\nStep 2: Substitute n = 6.\nStep 3: H = 2(6) + 2.\nStep 4: H = 12 + 2 = 14.","steps":["Step 1: Use CₙH₂ₙ₊₂.","Step 2: Substitute n = 6.","Step 3: H = 2(6) + 2.","Step 4: H = 12 + 2 = 14."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 2),
  (2287, 578, 'A student gives C₄H₈ as the formula of an open-chain alkane. Check the answer.', 'text', 1, 'Use CₙH₂ₙ₊₂.', '{"why":"C₄H₈ does not satisfy the general formula for an open-chain alkane.","sol":"Step 1: For n = 4, H = 2(4) + 2.\nStep 2: H = 8 + 2 = 10.\nStep 3: Therefore the alkane formula should contain 10 hydrogen atoms.","steps":["Step 1: For n = 4, H = 2(4) + 2.","Step 2: H = 8 + 2 = 10.","Step 3: Therefore the alkane formula should contain 10 hydrogen atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkanes"}', 3),
  (2288, 579, 'What is an alkene?', 'text', 1, 'Focus on the core principle of Alkenes.', '{"why":"The double bond means the carbon atoms do not contain the maximum possible number of hydrogen atoms.","sol":"Step 1: Identify the type of hydrocarbon.\nStep 2: Alkenes contain a carbon-carbon double bond.\nStep 3: Therefore they are unsaturated hydrocarbons.","steps":["Step 1: Identify the type of hydrocarbon.","Step 2: Alkenes contain a carbon-carbon double bond.","Step 3: Therefore they are unsaturated hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 0),
  (2289, 579, 'State the general formula for open-chain alkenes with one double bond.', 'text', 1, 'Focus on the core principle of Alkenes.', '{"why":"This is the general formula for open-chain alkenes containing one double bond.","sol":"Step 1: Recall the alkene general formula.\nStep 2: Express it using n carbon atoms.\nStep 3: The formula is CₙH₂ₙ.","steps":["Step 1: Recall the alkene general formula.","Step 2: Express it using n carbon atoms.","Step 3: The formula is CₙH₂ₙ."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 1),
  (2290, 579, 'Find the molecular formula of an alkene containing 5 carbon atoms.', 'text', 1, 'Focus on the core principle of Alkenes.', '{"why":"The formula CₙH₂ₙ gives C₅H₁₀ when n = 5.","sol":"Step 1: Use CₙH₂ₙ.\nStep 2: Substitute n = 5.\nStep 3: H = 2(5) = 10.","steps":["Step 1: Use CₙH₂ₙ.","Step 2: Substitute n = 5.","Step 3: H = 2(5) = 10."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 2),
  (2291, 579, 'A compound has formula C₄H₈ and is an open-chain hydrocarbon with one double bond. Is it an alkene?', 'text', 1, 'Compare its formula with CₙH₂ₙ.', '{"why":"The formula is consistent with an alkene containing one double bond.","sol":"Step 1: For n = 4, CₙH₂ₙ gives C₄H₈.\nStep 2: The formula matches the general formula.\nStep 3: Therefore it can be an alkene.","steps":["Step 1: For n = 4, CₙH₂ₙ gives C₄H₈.","Step 2: The formula matches the general formula.","Step 3: Therefore it can be an alkene."],"options":[],"conceptId":"chemistry_organic_chemistry_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkenes"}', 3),
  (2292, 580, 'What is an alkyne?', 'text', 1, 'Focus on the core principle of Alkynes.', '{"why":"The triple bond is the defining structural feature of an alkyne.","sol":"Step 1: Identify the type of hydrocarbon.\nStep 2: Alkynes contain a carbon-carbon triple bond.\nStep 3: Therefore they are unsaturated hydrocarbons.","steps":["Step 1: Identify the type of hydrocarbon.","Step 2: Alkynes contain a carbon-carbon triple bond.","Step 3: Therefore they are unsaturated hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 0),
  (2293, 580, 'State the general formula for an open-chain alkyne with one triple bond.', 'text', 1, 'Focus on the core principle of Alkynes.', '{"why":"This is the general formula for an open-chain alkyne containing one triple bond.","sol":"Step 1: Recall the alkyne general formula.\nStep 2: Express it using n carbon atoms.\nStep 3: The formula is CₙH₂ₙ₋₂.","steps":["Step 1: Recall the alkyne general formula.","Step 2: Express it using n carbon atoms.","Step 3: The formula is CₙH₂ₙ₋₂."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 1),
  (2294, 580, 'Find the molecular formula of an alkyne containing 4 carbon atoms.', 'text', 1, 'Focus on the core principle of Alkynes.', '{"why":"The formula CₙH₂ₙ₋₂ gives C₄H₆ when n = 4.","sol":"Step 1: Use CₙH₂ₙ₋₂.\nStep 2: Substitute n = 4.\nStep 3: H = 2(4) − 2.\nStep 4: H = 8 − 2 = 6.","steps":["Step 1: Use CₙH₂ₙ₋₂.","Step 2: Substitute n = 4.","Step 3: H = 2(4) − 2.","Step 4: H = 8 − 2 = 6."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 2),
  (2295, 580, 'A student gives C₃H₈ as the formula of an open-chain alkyne. Check the answer.', 'text', 1, 'Use CₙH₂ₙ₋₂.', '{"why":"C₃H₈ is an alkane formula, not an open-chain alkyne formula.","sol":"Step 1: Substitute n = 3.\nStep 2: H = 2(3) − 2.\nStep 3: H = 6 − 2 = 4.\nStep 4: Therefore the alkyne should be C₃H₄.","steps":["Step 1: Substitute n = 3.","Step 2: H = 2(3) − 2.","Step 3: H = 6 − 2 = 4.","Step 4: Therefore the alkyne should be C₃H₄."],"options":[],"conceptId":"chemistry_organic_chemistry_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alkynes"}', 3),
  (2296, 581, 'What is a homologous series?', 'text', 1, 'Focus on the core principle of Homologous Series.', '{"why":"These similarities produce related chemical properties within the series.","sol":"Step 1: Identify it as a family of related organic compounds.\nStep 2: Members have the same general formula and functional group.\nStep 3: Successive members differ by CH₂.","steps":["Step 1: Identify it as a family of related organic compounds.","Step 2: Members have the same general formula and functional group.","Step 3: Successive members differ by CH₂."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 0),
  (2297, 581, 'What is the difference between ethane, C₂H₆, and propane, C₃H₈?', 'text', 1, 'Focus on the core principle of Homologous Series.', '{"why":"Successive members of a homologous series differ by CH₂.","sol":"Step 1: Compare the carbon atoms: 3 − 2 = 1.\nStep 2: Compare the hydrogen atoms: 8 − 6 = 2.\nStep 3: The difference is CH₂.","steps":["Step 1: Compare the carbon atoms: 3 − 2 = 1.","Step 2: Compare the hydrogen atoms: 8 − 6 = 2.","Step 3: The difference is CH₂."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 1),
  (2298, 581, 'Are methane, ethane and propane members of the same homologous series?', 'text', 1, 'Focus on the core principle of Homologous Series.', '{"why":"They satisfy the defining characteristics of a homologous series.","sol":"Step 1: Methane, ethane and propane are all alkanes.\nStep 2: They have the same general formula, CₙH₂ₙ₊₂.\nStep 3: Each successive member differs by CH₂.","steps":["Step 1: Methane, ethane and propane are all alkanes.","Step 2: They have the same general formula, CₙH₂ₙ₊₂.","Step 3: Each successive member differs by CH₂."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 2),
  (2299, 581, 'A student says ethene and ethane belong to the same homologous series because both contain carbon and hydrogen. Is this correct?', 'text', 1, 'Check their bonding and general formulae.', '{"why":"Members of a homologous series must share the same characteristic structural type and general formula.","sol":"Step 1: Ethane is an alkane.\nStep 2: Ethene is an alkene.\nStep 3: They have different general formulae and different types of carbon-carbon bonds.","steps":["Step 1: Ethane is an alkane.","Step 2: Ethene is an alkene.","Step 3: They have different general formulae and different types of carbon-carbon bonds."],"options":[],"conceptId":"chemistry_organic_chemistry_homologous_series","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Homologous Series"}', 3),
  (2300, 582, 'Find the formula of an alkane containing 8 carbon atoms.', 'text', 1, 'Focus on the core principle of General Formula of Alkanes.', '{"why":"The alkane general formula is CₙH₂ₙ₊₂.","sol":"Step 1: Use CₙH₂ₙ₊₂.\nStep 2: Substitute n = 8.\nStep 3: H = 2(8) + 2.\nStep 4: H = 16 + 2 = 18.","steps":["Step 1: Use CₙH₂ₙ₊₂.","Step 2: Substitute n = 8.","Step 3: H = 2(8) + 2.","Step 4: H = 16 + 2 = 18."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 0),
  (2301, 582, 'Find the formula of an alkane containing 12 carbon atoms.', 'text', 1, 'Focus on the core principle of General Formula of Alkanes.', '{"why":"The formula follows the alkane general formula.","sol":"Step 1: Use CₙH₂ₙ₊₂.\nStep 2: Substitute n = 12.\nStep 3: H = 2(12) + 2.\nStep 4: H = 24 + 2 = 26.","steps":["Step 1: Use CₙH₂ₙ₊₂.","Step 2: Substitute n = 12.","Step 3: H = 2(12) + 2.","Step 4: H = 24 + 2 = 26."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 1),
  (2302, 582, 'An alkane has the formula C₉Hₓ. Find x.', 'text', 1, 'Focus on the core principle of General Formula of Alkanes.', '{"why":"The number of hydrogen atoms in an open-chain alkane is 2n + 2.","sol":"Step 1: Use H = 2n + 2.\nStep 2: n = 9.\nStep 3: H = 2(9) + 2.\nStep 4: H = 18 + 2 = 20.","steps":["Step 1: Use H = 2n + 2.","Step 2: n = 9.","Step 3: H = 2(9) + 2.","Step 4: H = 18 + 2 = 20."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 2),
  (2303, 582, 'A learner writes C₇H₁₄ as the formula of an alkane. What is the correct formula?', 'text', 1, 'Substitute n = 7 into CₙH₂ₙ₊₂.', '{"why":"C₇H₁₆ follows the general formula of an open-chain alkane.","sol":"Step 1: H = 2(7) + 2.\nStep 2: H = 14 + 2.\nStep 3: H = 16.","steps":["Step 1: H = 2(7) + 2.","Step 2: H = 14 + 2.","Step 3: H = 16."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formula_of_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formula of Alkanes"}', 3),
  (2304, 583, 'Find the formula of an alkene containing 7 carbon atoms.', 'text', 1, 'Focus on the core principle of General Formulae of Alkenes and Alkynes.', '{"why":"Open-chain alkenes with one double bond follow CₙH₂ₙ.","sol":"Step 1: Use the alkene formula CₙH₂ₙ.\nStep 2: Substitute n = 7.\nStep 3: H = 2(7) = 14.","steps":["Step 1: Use the alkene formula CₙH₂ₙ.","Step 2: Substitute n = 7.","Step 3: H = 2(7) = 14."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 0),
  (2305, 583, 'Find the formula of an alkyne containing 6 carbon atoms.', 'text', 1, 'Focus on the core principle of General Formulae of Alkenes and Alkynes.', '{"why":"Open-chain alkynes with one triple bond follow CₙH₂ₙ₋₂.","sol":"Step 1: Use CₙH₂ₙ₋₂.\nStep 2: Substitute n = 6.\nStep 3: H = 2(6) − 2.\nStep 4: H = 12 − 2 = 10.","steps":["Step 1: Use CₙH₂ₙ₋₂.","Step 2: Substitute n = 6.","Step 3: H = 2(6) − 2.","Step 4: H = 12 − 2 = 10."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 1),
  (2306, 583, 'An alkene has the formula C₈Hₓ. Find x.', 'text', 1, 'Focus on the core principle of General Formulae of Alkenes and Alkynes.', '{"why":"The general formula for an open-chain alkene is CₙH₂ₙ.","sol":"Step 1: Use H = 2n.\nStep 2: n = 8.\nStep 3: H = 2(8) = 16.","steps":["Step 1: Use H = 2n.","Step 2: n = 8.","Step 3: H = 2(8) = 16."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 2),
  (2307, 583, 'A learner says C₅H₈ is an alkene. Check the formula.', 'text', 1, 'For an open-chain alkene, use CₙH₂ₙ.', '{"why":"Alkenes follow CₙH₂ₙ, while alkynes follow CₙH₂ₙ₋₂.","sol":"Step 1: For n = 5, an alkene should have H = 2(5) = 10.\nStep 2: Therefore an alkene would be C₅H₁₀.\nStep 3: C₅H₈ instead matches the alkyne formula.","steps":["Step 1: For n = 5, an alkene should have H = 2(5) = 10.","Step 2: Therefore an alkene would be C₅H₁₀.","Step 3: C₅H₈ instead matches the alkyne formula."],"options":[],"conceptId":"chemistry_organic_chemistry_general_formulae_of_alkenes_and_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"General Formulae of Alkenes and Alkynes"}', 3),
  (2308, 584, 'Write the structural formula of ethane, C₂H₆.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"Each carbon forms four covalent bonds, so the two carbon atoms each bond to three hydrogen atoms.","sol":"Step 1: Ethane contains two carbon atoms.\nStep 2: The two carbon atoms are joined by a single bond.\nStep 3: Each carbon needs three hydrogen atoms to complete four bonds.\nStep 4: The structural formula is CH₃–CH₃.","steps":["Step 1: Ethane contains two carbon atoms.","Step 2: The two carbon atoms are joined by a single bond.","Step 3: Each carbon needs three hydrogen atoms to complete four bonds.","Step 4: The structural formula is CH₃–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 0),
  (2309, 584, 'Write the structural formula of propane, C₃H₈.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"The middle carbon has two carbon bonds and therefore needs two hydrogen atoms, while each end carbon needs three.","sol":"Step 1: Arrange the three carbon atoms in a chain.\nStep 2: Join them using single carbon-carbon bonds.\nStep 3: The two end carbons each have three hydrogen atoms.\nStep 4: The middle carbon has two hydrogen atoms.\nStep 5: The structural formula is CH₃–CH₂–CH₃.","steps":["Step 1: Arrange the three carbon atoms in a chain.","Step 2: Join them using single carbon-carbon bonds.","Step 3: The two end carbons each have three hydrogen atoms.","Step 4: The middle carbon has two hydrogen atoms.","Step 5: The structural formula is CH₃–CH₂–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 1),
  (2310, 584, 'Write the structural formula of propene, C₃H₆.', 'text', 1, 'Focus on the core principle of Structural Formulae.', '{"why":"Propene contains one carbon-carbon double bond, which must appear in its structural formula.","sol":"Step 1: Propene contains three carbon atoms.\nStep 2: The suffix ''-ene'' indicates a carbon-carbon double bond.\nStep 3: Place the double bond between carbon 1 and carbon 2.\nStep 4: Complete the remaining carbon bonds with hydrogen.\nStep 5: The structural formula is CH₂=CH–CH₃.","steps":["Step 1: Propene contains three carbon atoms.","Step 2: The suffix ''-ene'' indicates a carbon-carbon double bond.","Step 3: Place the double bond between carbon 1 and carbon 2.","Step 4: Complete the remaining carbon bonds with hydrogen.","Step 5: The structural formula is CH₂=CH–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 2),
  (2311, 584, 'Write the structural formula of butane, C₄H₁₀.', 'text', 1, 'Arrange four carbon atoms in a straight chain and complete each carbon''s four bonds.', '{"why":"Butane is a four-carbon alkane with only single carbon-carbon bonds.","sol":"Step 1: Arrange four carbon atoms in a chain.\nStep 2: Join adjacent carbon atoms with single bonds.\nStep 3: Complete the valencies with hydrogen atoms.\nStep 4: The structural formula is CH₃–CH₂–CH₂–CH₃.","steps":["Step 1: Arrange four carbon atoms in a chain.","Step 2: Join adjacent carbon atoms with single bonds.","Step 3: Complete the valencies with hydrogen atoms.","Step 4: The structural formula is CH₃–CH₂–CH₂–CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Formulae"}', 3),
  (2312, 585, 'Write the condensed structural formula of propane.', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"The condensed formula groups the hydrogen atoms with each carbon while preserving the carbon chain.","sol":"Step 1: Propane contains three carbon atoms.\nStep 2: The first carbon is CH₃.\nStep 3: The middle carbon is CH₂.\nStep 4: The final carbon is CH₃.\nStep 5: Combine the groups: CH₃CH₂CH₃.","steps":["Step 1: Propane contains three carbon atoms.","Step 2: The first carbon is CH₃.","Step 3: The middle carbon is CH₂.","Step 4: The final carbon is CH₃.","Step 5: Combine the groups: CH₃CH₂CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 0),
  (2313, 585, 'How many carbon atoms are present in CH₃CH₂CH₂CH₂CH₃?', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"Each CH₃ or CH₂ group contains one carbon atom.","sol":"Step 1: Count each carbon represented by CH₃ or CH₂.\nStep 2: There are five carbon groups.\nStep 3: Therefore, there are five carbon atoms.","steps":["Step 1: Count each carbon represented by CH₃ or CH₂.","Step 2: There are five carbon groups.","Step 3: Therefore, there are five carbon atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 1),
  (2314, 585, 'Write the condensed structural formula of pentane.', 'text', 1, 'Focus on the core principle of Condensed Structural Formulae.', '{"why":"Pentane is a straight-chain five-carbon alkane.","sol":"Step 1: Pentane contains five carbon atoms.\nStep 2: The two terminal carbons are CH₃.\nStep 3: The three internal carbons are CH₂.\nStep 4: Combine them in order.\nStep 5: CH₃CH₂CH₂CH₂CH₃.","steps":["Step 1: Pentane contains five carbon atoms.","Step 2: The two terminal carbons are CH₃.","Step 3: The three internal carbons are CH₂.","Step 4: Combine them in order.","Step 5: CH₃CH₂CH₂CH₂CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 2),
  (2315, 585, 'Write the condensed structural formula for hexane.', 'text', 1, 'Hexane contains six carbon atoms in a straight chain.', '{"why":"A straight-chain six-carbon alkane has two terminal CH₃ groups and four internal CH₂ groups.","sol":"Step 1: The first and last carbons are CH₃.\nStep 2: The four internal carbons are CH₂.\nStep 3: Write them in order.\nStep 4: CH₃CH₂CH₂CH₂CH₂CH₃.","steps":["Step 1: The first and last carbons are CH₃.","Step 2: The four internal carbons are CH₂.","Step 3: Write them in order.","Step 4: CH₃CH₂CH₂CH₂CH₂CH₃."],"options":[],"conceptId":"chemistry_organic_chemistry_condensed_structural_formulae","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Condensed Structural Formulae"}', 3),
  (2316, 586, 'Name CH₃CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"A straight-chain alkane containing three carbon atoms is propane.","sol":"Step 1: Count the carbon atoms: 3.\nStep 2: The three-carbon prefix is prop-.\nStep 3: It is an alkane, so use the ending -ane.\nStep 4: The name is propane.","steps":["Step 1: Count the carbon atoms: 3.","Step 2: The three-carbon prefix is prop-.","Step 3: It is an alkane, so use the ending -ane.","Step 4: The name is propane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 0),
  (2317, 586, 'Name CH₃CH₂CH₂CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"Pentane is the five-carbon straight-chain alkane.","sol":"Step 1: Count the carbon atoms: 5.\nStep 2: The five-carbon prefix is pent-.\nStep 3: Add the alkane ending -ane.\nStep 4: The name is pentane.","steps":["Step 1: Count the carbon atoms: 5.","Step 2: The five-carbon prefix is pent-.","Step 3: Add the alkane ending -ane.","Step 4: The name is pentane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 1),
  (2318, 586, 'Name CH₃CH₂CH₂CH₂CH₂CH₃.', 'text', 1, 'Focus on the core principle of Naming Straight-Chain Alkanes.', '{"why":"A six-carbon straight-chain alkane is hexane.","sol":"Step 1: Count the carbon atoms: 6.\nStep 2: The six-carbon prefix is hex-.\nStep 3: Add -ane.\nStep 4: The name is hexane.","steps":["Step 1: Count the carbon atoms: 6.","Step 2: The six-carbon prefix is hex-.","Step 3: Add -ane.","Step 4: The name is hexane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 2),
  (2319, 586, 'Name CH₃CH₂CH₂CH₂CH₂CH₂CH₃.', 'text', 1, 'Count the carbon atoms before choosing the prefix.', '{"why":"The molecule contains seven carbon atoms and only single carbon-carbon bonds.","sol":"Step 1: Count seven carbon atoms.\nStep 2: The prefix for seven carbons is hept-.\nStep 3: Add -ane.\nStep 4: The name is heptane.","steps":["Step 1: Count seven carbon atoms.","Step 2: The prefix for seven carbons is hept-.","Step 3: Add -ane.","Step 4: The name is heptane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_straight_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Straight-Chain Alkanes"}', 3),
  (2320, 587, 'Name CH₃–CH(CH₃)–CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The longest chain is three carbons and the methyl substituent is attached to carbon 2.","sol":"Step 1: Find the longest continuous carbon chain. It contains three carbons.\nStep 2: The parent name is propane.\nStep 3: There is a methyl branch.\nStep 4: The methyl branch is attached to carbon 2.\nStep 5: Combine the parts: 2-methylpropane.","steps":["Step 1: Find the longest continuous carbon chain. It contains three carbons.","Step 2: The parent name is propane.","Step 3: There is a methyl branch.","Step 4: The methyl branch is attached to carbon 2.","Step 5: Combine the parts: 2-methylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 0),
  (2321, 587, 'Name CH₃–CH(CH₃)–CH₂–CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The four-carbon parent chain is butane and the methyl substituent receives the lowest possible number, 2.","sol":"Step 1: The longest continuous chain contains four carbons.\nStep 2: The parent name is butane.\nStep 3: There is a methyl branch.\nStep 4: Numbering from the nearer end places the methyl group on carbon 2.\nStep 5: The name is 2-methylbutane.","steps":["Step 1: The longest continuous chain contains four carbons.","Step 2: The parent name is butane.","Step 3: There is a methyl branch.","Step 4: Numbering from the nearer end places the methyl group on carbon 2.","Step 5: The name is 2-methylbutane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 1),
  (2322, 587, 'Name CH₃–CH₂–CH(CH₃)–CH₂–CH₃.', 'text', 1, 'Focus on the core principle of Naming Branched-Chain Alkanes.', '{"why":"The longest chain has five carbons and the methyl group is attached to the third carbon.","sol":"Step 1: Find the longest chain: five carbon atoms.\nStep 2: The parent name is pentane.\nStep 3: There is a methyl substituent.\nStep 4: The substituent is on carbon 3.\nStep 5: The name is 3-methylpentane.","steps":["Step 1: Find the longest chain: five carbon atoms.","Step 2: The parent name is pentane.","Step 3: There is a methyl substituent.","Step 4: The substituent is on carbon 3.","Step 5: The name is 3-methylpentane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 2),
  (2323, 587, 'Name CH₃–CH(CH₃)–CH₂–CH₂–CH₃.', 'text', 1, 'First identify the longest carbon chain before identifying the branch.', '{"why":"The longest chain is pentane and the methyl substituent is at carbon 2.","sol":"Step 1: The longest chain contains five carbon atoms.\nStep 2: The parent name is pentane.\nStep 3: There is a methyl substituent.\nStep 4: Number from the nearer end so the substituent gets the lowest number.\nStep 5: The methyl group is on carbon 2.\nStep 6: The name is 2-methylpentane.","steps":["Step 1: The longest chain contains five carbon atoms.","Step 2: The parent name is pentane.","Step 3: There is a methyl substituent.","Step 4: Number from the nearer end so the substituent gets the lowest number.","Step 5: The methyl group is on carbon 2.","Step 6: The name is 2-methylpentane."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_branched_chain_alkanes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Branched-Chain Alkanes"}', 3),
  (2324, 588, 'Name CH₂=CH₂.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"Ethene is the two-carbon alkene.","sol":"Step 1: Count the two carbon atoms.\nStep 2: The prefix is eth-.\nStep 3: The molecule contains a double bond.\nStep 4: Use the ending -ene.\nStep 5: The name is ethene.","steps":["Step 1: Count the two carbon atoms.","Step 2: The prefix is eth-.","Step 3: The molecule contains a double bond.","Step 4: Use the ending -ene.","Step 5: The name is ethene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 0),
  (2325, 588, 'Name CH₂=CH–CH₂–CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"The four-carbon chain is but- and the double bond starts at carbon 1.","sol":"Step 1: The longest chain contains four carbons.\nStep 2: The parent name is butene.\nStep 3: Number from the end nearest the double bond.\nStep 4: The double bond begins at carbon 1.\nStep 5: The name is but-1-ene.","steps":["Step 1: The longest chain contains four carbons.","Step 2: The parent name is butene.","Step 3: Number from the end nearest the double bond.","Step 4: The double bond begins at carbon 1.","Step 5: The name is but-1-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 1),
  (2326, 588, 'Name CH₃–CH=CH–CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkenes.', '{"why":"The double bond begins at carbon 2 in the four-carbon chain.","sol":"Step 1: The longest chain contains four carbons.\nStep 2: The parent name is butene.\nStep 3: Numbering from either end places the double bond between carbon 2 and carbon 3.\nStep 4: The double bond therefore starts at carbon 2.\nStep 5: The name is but-2-ene.","steps":["Step 1: The longest chain contains four carbons.","Step 2: The parent name is butene.","Step 3: Numbering from either end places the double bond between carbon 2 and carbon 3.","Step 4: The double bond therefore starts at carbon 2.","Step 5: The name is but-2-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 2),
  (2327, 588, 'Name CH₂=CH–CH₂–CH₂–CH₃.', 'text', 1, 'Number from the end closest to the double bond.', '{"why":"The five-carbon chain contains a double bond beginning at carbon 1.","sol":"Step 1: The longest chain has five carbons.\nStep 2: The parent name is pentene.\nStep 3: The double bond begins at carbon 1.\nStep 4: The name is pent-1-ene.","steps":["Step 1: The longest chain has five carbons.","Step 2: The parent name is pentene.","Step 3: The double bond begins at carbon 1.","Step 4: The name is pent-1-ene."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkenes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkenes"}', 3),
  (2328, 589, 'Name HC≡CH.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"Ethyne is the two-carbon alkyne.","sol":"Step 1: Count the carbon atoms: 2.\nStep 2: The prefix is eth-.\nStep 3: The molecule contains a triple bond.\nStep 4: Use the ending -yne.\nStep 5: The name is ethyne.","steps":["Step 1: Count the carbon atoms: 2.","Step 2: The prefix is eth-.","Step 3: The molecule contains a triple bond.","Step 4: Use the ending -yne.","Step 5: The name is ethyne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 0),
  (2329, 589, 'Name HC≡C–CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"A three-carbon molecule containing a triple bond is propyne.","sol":"Step 1: The chain contains three carbon atoms.\nStep 2: The prefix is prop-.\nStep 3: There is a triple bond.\nStep 4: Use the ending -yne.\nStep 5: The name is propyne.","steps":["Step 1: The chain contains three carbon atoms.","Step 2: The prefix is prop-.","Step 3: There is a triple bond.","Step 4: Use the ending -yne.","Step 5: The name is propyne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 1),
  (2330, 589, 'Name CH₃–C≡C–CH₃.', 'text', 1, 'Focus on the core principle of Naming Alkynes.', '{"why":"The four-carbon chain has a triple bond beginning at carbon 2.","sol":"Step 1: The longest chain contains four carbon atoms.\nStep 2: The parent name is butyne.\nStep 3: Number the chain from either end.\nStep 4: The triple bond begins at carbon 2.\nStep 5: The name is but-2-yne.","steps":["Step 1: The longest chain contains four carbon atoms.","Step 2: The parent name is butyne.","Step 3: Number the chain from either end.","Step 4: The triple bond begins at carbon 2.","Step 5: The name is but-2-yne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 2),
  (2331, 589, 'Name HC≡C–CH₂–CH₂–CH₃.', 'text', 1, 'Count the longest chain and number from the end nearest the triple bond.', '{"why":"The five-carbon chain has a triple bond beginning at carbon 1.","sol":"Step 1: The longest chain contains five carbon atoms.\nStep 2: The parent name is pent-yne.\nStep 3: The triple bond begins at carbon 1.\nStep 4: The name is pent-1-yne.","steps":["Step 1: The longest chain contains five carbon atoms.","Step 2: The parent name is pent-yne.","Step 3: The triple bond begins at carbon 1.","Step 4: The name is pent-1-yne."],"options":[],"conceptId":"chemistry_organic_chemistry_naming_alkynes","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Naming Alkynes"}', 3),
  (2332, 590, 'What is meant by structural isomerism?', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"The molecular formula remains the same, while the connectivity of the atoms changes.","sol":"Step 1: Structural isomers have the same molecular formula.\nStep 2: Their atoms are connected in different arrangements.\nStep 3: Therefore, structural isomerism is the existence of compounds with the same molecular formula but different structural arrangements.","steps":["Step 1: Structural isomers have the same molecular formula.","Step 2: Their atoms are connected in different arrangements.","Step 3: Therefore, structural isomerism is the existence of compounds with the same molecular formula but different structural arrangements."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 0),
  (2333, 590, 'Write the two structural isomers of C₄H₁₀.', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"Both structures contain four carbon atoms and ten hydrogen atoms, but their carbon atoms are connected differently.","sol":"Step 1: Draw the straight four-carbon chain: CH₃–CH₂–CH₂–CH₃.\nStep 2: This is butane.\nStep 3: Rearrange the carbon skeleton to form a three-carbon main chain with a methyl branch.\nStep 4: The second structure is CH₃–CH(CH₃)–CH₃.\nStep 5: This is 2-methylpropane.","steps":["Step 1: Draw the straight four-carbon chain: CH₃–CH₂–CH₂–CH₃.","Step 2: This is butane.","Step 3: Rearrange the carbon skeleton to form a three-carbon main chain with a methyl branch.","Step 4: The second structure is CH₃–CH(CH₃)–CH₃.","Step 5: This is 2-methylpropane."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 1),
  (2334, 590, 'How many structural isomers does C₅H₁₂ have?', 'text', 1, 'Focus on the core principle of Structural Isomerism.', '{"why":"Pentane has three distinct possible carbon skeletons.","sol":"Step 1: Draw the straight chain: pentane.\nStep 2: Rearrange the chain to form 2-methylbutane.\nStep 3: Rearrange it further to form 2,2-dimethylpropane.\nStep 4: No other distinct carbon skeletons are possible.\nStep 5: Therefore, C₅H₁₂ has three structural isomers.","steps":["Step 1: Draw the straight chain: pentane.","Step 2: Rearrange the chain to form 2-methylbutane.","Step 3: Rearrange it further to form 2,2-dimethylpropane.","Step 4: No other distinct carbon skeletons are possible.","Step 5: Therefore, C₅H₁₂ has three structural isomers."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 2),
  (2335, 590, 'Are CH₃CH₂CH₂CH₃ and CH₃CH(CH₃)CH₃ structural isomers?', 'text', 1, 'Compare both their molecular formulae and their atom arrangements.', '{"why":"They have the same molecular formula but different carbon skeletons.","sol":"Step 1: Both compounds have four carbon atoms and ten hydrogen atoms.\nStep 2: Their molecular formula is therefore C₄H₁₀.\nStep 3: Their carbon arrangements are different.\nStep 4: Therefore, they are structural isomers.","steps":["Step 1: Both compounds have four carbon atoms and ten hydrogen atoms.","Step 2: Their molecular formula is therefore C₄H₁₀.","Step 3: Their carbon arrangements are different.","Step 4: Therefore, they are structural isomers."],"options":[],"conceptId":"chemistry_organic_chemistry_structural_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Structural Isomerism"}', 3),
  (2336, 591, 'What is geometric isomerism?', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"The double bond restricts rotation, allowing different fixed arrangements.","sol":"Step 1: Geometric isomers have the same molecular formula.\nStep 2: They have the same order of connectivity.\nStep 3: Their groups have different spatial arrangements around a double bond.\nStep 4: Therefore, geometric isomerism results from different spatial arrangements around a restricted carbon-carbon double bond.","steps":["Step 1: Geometric isomers have the same molecular formula.","Step 2: They have the same order of connectivity.","Step 3: Their groups have different spatial arrangements around a double bond.","Step 4: Therefore, geometric isomerism results from different spatial arrangements around a restricted carbon-carbon double bond."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 0),
  (2337, 591, 'What is the difference between cis-but-2-ene and trans-but-2-ene?', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"The two forms differ only in the spatial arrangement around the carbon-carbon double bond.","sol":"Step 1: Both compounds have the same molecular formula, C₄H₈.\nStep 2: Both have the same carbon-carbon connectivity.\nStep 3: In cis-but-2-ene, the similar groups are on the same side of the double bond.\nStep 4: In trans-but-2-ene, the similar groups are on opposite sides.","steps":["Step 1: Both compounds have the same molecular formula, C₄H₈.","Step 2: Both have the same carbon-carbon connectivity.","Step 3: In cis-but-2-ene, the similar groups are on the same side of the double bond.","Step 4: In trans-but-2-ene, the similar groups are on opposite sides."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 1),
  (2338, 591, 'Why can but-2-ene show geometric isomerism?', 'text', 1, 'Focus on the core principle of Geometric Isomerism.', '{"why":"Both conditions are needed for the common cis-trans form of geometric isomerism.","sol":"Step 1: But-2-ene contains a carbon-carbon double bond.\nStep 2: Rotation around the double bond is restricted.\nStep 3: Each double-bonded carbon has two different groups attached to it.\nStep 4: The groups can therefore occupy different fixed spatial arrangements.\nStep 5: But-2-ene can therefore exist as cis and trans forms.","steps":["Step 1: But-2-ene contains a carbon-carbon double bond.","Step 2: Rotation around the double bond is restricted.","Step 3: Each double-bonded carbon has two different groups attached to it.","Step 4: The groups can therefore occupy different fixed spatial arrangements.","Step 5: But-2-ene can therefore exist as cis and trans forms."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 2),
  (2339, 591, 'Is butane capable of cis-trans geometric isomerism?', 'text', 1, 'Check whether butane contains a carbon-carbon double bond.', '{"why":"Butane has only single carbon-carbon bonds and therefore does not have the restricted double bond required for cis-trans isomerism.","sol":"Step 1: Butane contains only carbon-carbon single bonds.\nStep 2: Single bonds allow rotation.\nStep 3: Butane therefore does not have the required restricted C=C bond for cis-trans isomerism.\nStep 4: Therefore, butane does not show cis-trans geometric isomerism.","steps":["Step 1: Butane contains only carbon-carbon single bonds.","Step 2: Single bonds allow rotation.","Step 3: Butane therefore does not have the required restricted C=C bond for cis-trans isomerism.","Step 4: Therefore, butane does not show cis-trans geometric isomerism."],"options":[],"conceptId":"chemistry_organic_chemistry_geometric_isomerism","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Geometric Isomerism"}', 3),
  (2340, 592, 'What functional group is present in alcohols?', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"Alcohols are characterised by the presence of a hydroxyl group attached to carbon.","sol":"Step 1: Identify the characteristic group of alcohols.\nStep 2: The group contains oxygen and hydrogen.\nStep 3: It is written as –OH.\nStep 4: Therefore, the functional group is the hydroxyl group.","steps":["Step 1: Identify the characteristic group of alcohols.","Step 2: The group contains oxygen and hydrogen.","Step 3: It is written as –OH.","Step 4: Therefore, the functional group is the hydroxyl group."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 0),
  (2341, 592, 'Is CH₃CH₂OH an alcohol?', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"CH₃CH₂OH contains the hydroxyl functional group and is ethanol.","sol":"Step 1: Look at the structure.\nStep 2: It contains an –OH group.\nStep 3: The –OH group is attached to a carbon-containing chain.\nStep 4: Therefore, CH₃CH₂OH is an alcohol.","steps":["Step 1: Look at the structure.","Step 2: It contains an –OH group.","Step 3: The –OH group is attached to a carbon-containing chain.","Step 4: Therefore, CH₃CH₂OH is an alcohol."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 1),
  (2342, 592, 'Identify the functional group in CH₃CH₂CH₂OH.', 'text', 1, 'Focus on the core principle of Alcohols.', '{"why":"The –OH group is the characteristic functional group of alcohols.","sol":"Step 1: Examine the formula.\nStep 2: Locate the oxygen and hydrogen joined together.\nStep 3: The group is –OH.\nStep 4: Therefore, the functional group is hydroxyl.","steps":["Step 1: Examine the formula.","Step 2: Locate the oxygen and hydrogen joined together.","Step 3: The group is –OH.","Step 4: Therefore, the functional group is hydroxyl."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 2),
  (2343, 592, 'Write the structural formula of propanol.', 'text', 1, 'Propanol has three carbon atoms and contains the –OH group.', '{"why":"Propanol is a three-carbon alcohol containing the –OH functional group.","sol":"Step 1: Arrange three carbon atoms in a chain.\nStep 2: Attach the hydroxyl group to the carbon chain.\nStep 3: Complete the remaining valencies with hydrogen.\nStep 4: The structural formula is CH₃CH₂CH₂OH.","steps":["Step 1: Arrange three carbon atoms in a chain.","Step 2: Attach the hydroxyl group to the carbon chain.","Step 3: Complete the remaining valencies with hydrogen.","Step 4: The structural formula is CH₃CH₂CH₂OH."],"options":[],"conceptId":"chemistry_organic_chemistry_alcohols","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Alcohols"}', 3),
  (2344, 593, 'What is the molecular formula of ethanol?', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"Ethanol contains two carbon atoms, six hydrogen atoms and one oxygen atom.","sol":"Step 1: Ethanol is a two-carbon alcohol.\nStep 2: Its formula can be written as C₂H₅OH.\nStep 3: Count the hydrogen atoms: 5 + 1 = 6.\nStep 4: Therefore, the molecular formula is C₂H₆O.","steps":["Step 1: Ethanol is a two-carbon alcohol.","Step 2: Its formula can be written as C₂H₅OH.","Step 3: Count the hydrogen atoms: 5 + 1 = 6.","Step 4: Therefore, the molecular formula is C₂H₆O."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 0),
  (2345, 593, 'Write the structural formula of ethanol.', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"Ethanol is the two-carbon alcohol containing the –OH group.","sol":"Step 1: Ethanol contains two carbon atoms.\nStep 2: Join them using a carbon-carbon single bond.\nStep 3: Attach the hydroxyl group to the second carbon.\nStep 4: Complete the valencies with hydrogen.\nStep 5: The structural formula is CH₃CH₂OH.","steps":["Step 1: Ethanol contains two carbon atoms.","Step 2: Join them using a carbon-carbon single bond.","Step 3: Attach the hydroxyl group to the second carbon.","Step 4: Complete the valencies with hydrogen.","Step 5: The structural formula is CH₃CH₂OH."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 1),
  (2346, 593, 'Calculate the relative molecular mass of ethanol, C₂H₆O. Use C = 12, H = 1 and O = 16.', 'text', 1, 'Focus on the core principle of Ethanol.', '{"why":"The relative molecular mass is obtained by adding the relative atomic masses of all atoms in the molecule.","sol":"Step 1: Carbon contribution = 2 × 12 = 24.\nStep 2: Hydrogen contribution = 6 × 1 = 6.\nStep 3: Oxygen contribution = 1 × 16 = 16.\nStep 4: Add the contributions: 24 + 6 + 16 = 46.","steps":["Step 1: Carbon contribution = 2 × 12 = 24.","Step 2: Hydrogen contribution = 6 × 1 = 6.","Step 3: Oxygen contribution = 1 × 16 = 16.","Step 4: Add the contributions: 24 + 6 + 16 = 46."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 2),
  (2347, 593, 'How many oxygen atoms are present in one molecule of ethanol?', 'text', 1, 'Look at the formula C₂H₅OH.', '{"why":"The formula C₂H₅OH contains one oxygen atom.","sol":"Step 1: Examine C₂H₅OH.\nStep 2: There is one O symbol.\nStep 3: Therefore, one molecule of ethanol contains one oxygen atom.","steps":["Step 1: Examine C₂H₅OH.","Step 2: There is one O symbol.","Step 3: Therefore, one molecule of ethanol contains one oxygen atom."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanol"}', 3),
  (2348, 594, 'State two physical properties of ethanol.', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"These are physical properties because they can be observed without changing ethanol into another substance.","sol":"Step 1: Recall the observable properties of ethanol.\nStep 2: Ethanol is a colourless liquid.\nStep 3: It is also volatile and miscible with water.\nStep 4: Any two of these are acceptable.","steps":["Step 1: Recall the observable properties of ethanol.","Step 2: Ethanol is a colourless liquid.","Step 3: It is also volatile and miscible with water.","Step 4: Any two of these are acceptable."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 0),
  (2349, 594, 'What happens when ethanol burns completely in oxygen?', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"Complete combustion of an organic compound containing carbon and hydrogen produces carbon dioxide and water.","sol":"Step 1: Complete combustion requires oxygen.\nStep 2: Ethanol contains carbon and hydrogen.\nStep 3: Carbon forms carbon dioxide.\nStep 4: Hydrogen forms water.\nStep 5: Therefore, complete combustion produces carbon dioxide and water.","steps":["Step 1: Complete combustion requires oxygen.","Step 2: Ethanol contains carbon and hydrogen.","Step 3: Carbon forms carbon dioxide.","Step 4: Hydrogen forms water.","Step 5: Therefore, complete combustion produces carbon dioxide and water."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 1),
  (2350, 594, 'Balance the equation: C₂H₅OH + O₂ → CO₂ + H₂O.', 'text', 1, 'Focus on the core principle of Properties of Ethanol.', '{"why":"The balanced equation has equal numbers of carbon, hydrogen and oxygen atoms on both sides.","sol":"Step 1: There are 2 carbon atoms, so place 2 before CO₂.\nStep 2: There are 6 hydrogen atoms, so place 3 before H₂O.\nStep 3: The products now contain 4 + 3 = 7 oxygen atoms.\nStep 4: Ethanol already contains 1 oxygen atom, so oxygen gas must supply 6 more oxygen atoms.\nStep 5: Six oxygen atoms require 3O₂.\nStep 6: The balanced equation is C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O.","steps":["Step 1: There are 2 carbon atoms, so place 2 before CO₂.","Step 2: There are 6 hydrogen atoms, so place 3 before H₂O.","Step 3: The products now contain 4 + 3 = 7 oxygen atoms.","Step 4: Ethanol already contains 1 oxygen atom, so oxygen gas must supply 6 more oxygen atoms.","Step 5: Six oxygen atoms require 3O₂.","Step 6: The balanced equation is C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 2),
  (2351, 594, 'Why is ethanol described as flammable?', 'text', 1, 'Think about what happens when ethanol reacts with oxygen and is ignited.', '{"why":"A flammable substance can undergo combustion readily.","sol":"Step 1: Ethanol reacts readily with oxygen when ignited.\nStep 2: The reaction releases energy as heat and light.\nStep 3: Therefore, ethanol can burn.","steps":["Step 1: Ethanol reacts readily with oxygen when ignited.","Step 2: The reaction releases energy as heat and light.","Step 3: Therefore, ethanol can burn."],"options":[],"conceptId":"chemistry_organic_chemistry_properties_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Properties of Ethanol"}', 3),
  (2352, 595, 'What is fermentation?', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"Yeast carries out the biochemical conversion of sugar into ethanol and carbon dioxide.","sol":"Step 1: Identify the starting substance: sugar such as glucose.\nStep 2: Yeast acts on the sugar.\nStep 3: The process occurs under conditions where oxygen is absent or very limited.\nStep 4: Ethanol and carbon dioxide are produced.","steps":["Step 1: Identify the starting substance: sugar such as glucose.","Step 2: Yeast acts on the sugar.","Step 3: The process occurs under conditions where oxygen is absent or very limited.","Step 4: Ethanol and carbon dioxide are produced."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 0),
  (2353, 595, 'Write the word equation for fermentation of glucose.', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"These are the reactant and products of alcoholic fermentation.","sol":"Step 1: Identify the reactant: glucose.\nStep 2: Identify the products: ethanol and carbon dioxide.\nStep 3: Write them in reaction order.","steps":["Step 1: Identify the reactant: glucose.","Step 2: Identify the products: ethanol and carbon dioxide.","Step 3: Write them in reaction order."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 1),
  (2354, 595, 'Balance the fermentation equation: C₆H₁₂O₆ → C₂H₅OH + CO₂.', 'text', 1, 'Focus on the core principle of Fermentation.', '{"why":"The same number of carbon, hydrogen and oxygen atoms occurs on both sides.","sol":"Step 1: There are 6 carbon atoms in glucose.\nStep 2: Place 2 before ethanol, giving 4 carbon atoms.\nStep 3: The remaining 2 carbon atoms form 2CO₂.\nStep 4: Check hydrogen: 2 × 6 = 12 hydrogen atoms.\nStep 5: Check oxygen: 2 oxygen atoms in ethanol plus 4 in carbon dioxide gives 6.\nStep 6: The balanced equation is C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.","steps":["Step 1: There are 6 carbon atoms in glucose.","Step 2: Place 2 before ethanol, giving 4 carbon atoms.","Step 3: The remaining 2 carbon atoms form 2CO₂.","Step 4: Check hydrogen: 2 × 6 = 12 hydrogen atoms.","Step 5: Check oxygen: 2 oxygen atoms in ethanol plus 4 in carbon dioxide gives 6.","Step 6: The balanced equation is C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 2),
  (2355, 595, 'Why is oxygen kept out during fermentation?', 'text', 1, 'Consider what happens to glucose when yeast has oxygen available.', '{"why":"The desired conversion of glucose to ethanol occurs under anaerobic conditions.","sol":"Step 1: Fermentation is an anaerobic process.\nStep 2: Anaerobic means occurring without oxygen.\nStep 3: Keeping oxygen low allows yeast to convert glucose into ethanol and carbon dioxide.","steps":["Step 1: Fermentation is an anaerobic process.","Step 2: Anaerobic means occurring without oxygen.","Step 3: Keeping oxygen low allows yeast to convert glucose into ethanol and carbon dioxide."],"options":[],"conceptId":"chemistry_organic_chemistry_fermentation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Fermentation"}', 3),
  (2356, 596, 'What product is formed when ethanol is oxidised completely?', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"Ethanol is oxidised to ethanoic acid.","sol":"Step 1: Identify the starting alcohol: ethanol.\nStep 2: Oxidation changes ethanol into a carboxylic acid.\nStep 3: The carboxylic acid formed is ethanoic acid.","steps":["Step 1: Identify the starting alcohol: ethanol.","Step 2: Oxidation changes ethanol into a carboxylic acid.","Step 3: The carboxylic acid formed is ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 0),
  (2357, 596, 'Write the equation for oxidation of ethanol by oxygen.', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"Ethanol is oxidised to ethanoic acid while oxygen is reduced to form water.","sol":"Step 1: Write ethanol as C₂H₅OH.\nStep 2: Add oxygen as the oxidising reactant.\nStep 3: The acid formed is CH₃COOH.\nStep 4: Water is also formed.\nStep 5: Balance the equation: C₂H₅OH + O₂ → CH₃COOH + H₂O.","steps":["Step 1: Write ethanol as C₂H₅OH.","Step 2: Add oxygen as the oxidising reactant.","Step 3: The acid formed is CH₃COOH.","Step 4: Water is also formed.","Step 5: Balance the equation: C₂H₅OH + O₂ → CH₃COOH + H₂O."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 1),
  (2358, 596, 'Name the type of organic compound formed when ethanol is oxidised to CH₃COOH.', 'text', 1, 'Focus on the core principle of Oxidation of Ethanol.', '{"why":"CH₃COOH contains the carboxyl functional group.","sol":"Step 1: Identify CH₃COOH.\nStep 2: It contains the –COOH functional group.\nStep 3: The –COOH group is characteristic of carboxylic acids.\nStep 4: Therefore, the product is a carboxylic acid.","steps":["Step 1: Identify CH₃COOH.","Step 2: It contains the –COOH functional group.","Step 3: The –COOH group is characteristic of carboxylic acids.","Step 4: Therefore, the product is a carboxylic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 2),
  (2359, 596, 'What organic acid is produced from ethanol by oxidation?', 'text', 1, 'It is the two-carbon carboxylic acid.', '{"why":"Oxidation of ethanol produces ethanoic acid.","sol":"Step 1: Ethanol contains two carbon atoms.\nStep 2: Oxidation forms the corresponding two-carbon carboxylic acid.\nStep 3: The product is ethanoic acid.","steps":["Step 1: Ethanol contains two carbon atoms.","Step 2: Oxidation forms the corresponding two-carbon carboxylic acid.","Step 3: The product is ethanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_oxidation_of_ethanol","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Oxidation of Ethanol"}', 3),
  (2360, 597, 'What functional group is present in carboxylic acids?', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"The carboxyl group is the characteristic functional group of carboxylic acids.","sol":"Step 1: Identify the characteristic functional group.\nStep 2: It is written as –COOH.\nStep 3: This is called the carboxyl group.","steps":["Step 1: Identify the characteristic functional group.","Step 2: It is written as –COOH.","Step 3: This is called the carboxyl group."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 0),
  (2361, 597, 'Identify the carboxylic acid functional group in CH₃COOH.', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"The –COOH group identifies a compound as a carboxylic acid.","sol":"Step 1: Examine the formula CH₃COOH.\nStep 2: The final part is COOH.\nStep 3: COOH represents the carboxyl group.","steps":["Step 1: Examine the formula CH₃COOH.","Step 2: The final part is COOH.","Step 3: COOH represents the carboxyl group."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 1),
  (2362, 597, 'Name HCOOH.', 'text', 1, 'Focus on the core principle of Carboxylic Acids.', '{"why":"Methanoic acid is the one-carbon carboxylic acid.","sol":"Step 1: Count the carbon atoms: 1.\nStep 2: The one-carbon prefix is meth-.\nStep 3: It is a carboxylic acid, so the name ends in -oic acid.\nStep 4: The name is methanoic acid.","steps":["Step 1: Count the carbon atoms: 1.","Step 2: The one-carbon prefix is meth-.","Step 3: It is a carboxylic acid, so the name ends in -oic acid.","Step 4: The name is methanoic acid."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 2),
  (2363, 597, 'Write the general formula for a carboxylic acid.', 'text', 1, 'Use R for the carbon-containing part of the molecule.', '{"why":"All carboxylic acids contain the –COOH functional group.","sol":"Step 1: Identify the characteristic carboxyl group.\nStep 2: Attach it to the carbon-containing group R.\nStep 3: The general structure is R–COOH.","steps":["Step 1: Identify the characteristic carboxyl group.","Step 2: Attach it to the carbon-containing group R.","Step 3: The general structure is R–COOH."],"options":[],"conceptId":"chemistry_organic_chemistry_carboxylic_acids","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Carboxylic Acids"}', 3),
  (2364, 598, 'Write the structural formula of ethanoic acid.', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"Ethanoic acid is the two-carbon carboxylic acid containing the –COOH group.","sol":"Step 1: Ethanoic acid contains two carbon atoms.\nStep 2: The carboxyl group is –COOH.\nStep 3: Attach the carboxyl group to the first carbon.\nStep 4: The remaining carbon is CH₃.\nStep 5: The structural formula is CH₃COOH.","steps":["Step 1: Ethanoic acid contains two carbon atoms.","Step 2: The carboxyl group is –COOH.","Step 3: Attach the carboxyl group to the first carbon.","Step 4: The remaining carbon is CH₃.","Step 5: The structural formula is CH₃COOH."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 0),
  (2365, 598, 'Calculate the relative molecular mass of ethanoic acid, C₂H₄O₂. Use C = 12, H = 1 and O = 16.', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"The relative molecular mass is the sum of the relative atomic masses of all atoms in C₂H₄O₂.","sol":"Step 1: Carbon contribution = 2 × 12 = 24.\nStep 2: Hydrogen contribution = 4 × 1 = 4.\nStep 3: Oxygen contribution = 2 × 16 = 32.\nStep 4: Add: 24 + 4 + 32 = 60.","steps":["Step 1: Carbon contribution = 2 × 12 = 24.","Step 2: Hydrogen contribution = 4 × 1 = 4.","Step 3: Oxygen contribution = 2 × 16 = 32.","Step 4: Add: 24 + 4 + 32 = 60."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 1),
  (2366, 598, 'Where is dilute ethanoic acid commonly found?', 'text', 1, 'Focus on the core principle of Ethanoic Acid.', '{"why":"Vinegar is a dilute solution of ethanoic acid in water.","sol":"Step 1: Identify a common household source of dilute ethanoic acid.\nStep 2: Vinegar contains dilute ethanoic acid.\nStep 3: Therefore, dilute ethanoic acid is commonly found in vinegar.","steps":["Step 1: Identify a common household source of dilute ethanoic acid.","Step 2: Vinegar contains dilute ethanoic acid.","Step 3: Therefore, dilute ethanoic acid is commonly found in vinegar."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 2),
  (2367, 598, 'How many carbon atoms are present in one molecule of ethanoic acid?', 'text', 1, 'Use the molecular formula C₂H₄O₂.', '{"why":"The molecular formula C₂H₄O₂ contains two carbon atoms.","sol":"Step 1: Look at the subscript after C.\nStep 2: The subscript is 2.\nStep 3: Therefore, one molecule contains two carbon atoms.","steps":["Step 1: Look at the subscript after C.","Step 2: The subscript is 2.","Step 3: Therefore, one molecule contains two carbon atoms."],"options":[],"conceptId":"chemistry_organic_chemistry_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ethanoic Acid"}', 3),
  (2368, 599, 'What products are formed when ethanoic acid reacts with magnesium?', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"Acid-metal reactions produce a salt and hydrogen gas.","sol":"Step 1: Ethanoic acid is an acid.\nStep 2: Acids react with reactive metals.\nStep 3: The products are a salt and hydrogen gas.\nStep 4: With magnesium, the salt is magnesium ethanoate.","steps":["Step 1: Ethanoic acid is an acid.","Step 2: Acids react with reactive metals.","Step 3: The products are a salt and hydrogen gas.","Step 4: With magnesium, the salt is magnesium ethanoate."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 0),
  (2369, 599, 'Complete and balance: CH₃COOH + NaOH →', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"An acid reacts with an alkali to form a salt and water.","sol":"Step 1: Ethanoic acid reacts with sodium hydroxide.\nStep 2: This is a neutralisation reaction.\nStep 3: The salt formed is sodium ethanoate, CH₃COONa.\nStep 4: Water is also formed.\nStep 5: The balanced equation is CH₃COOH + NaOH → CH₃COONa + H₂O.","steps":["Step 1: Ethanoic acid reacts with sodium hydroxide.","Step 2: This is a neutralisation reaction.","Step 3: The salt formed is sodium ethanoate, CH₃COONa.","Step 4: Water is also formed.","Step 5: The balanced equation is CH₃COOH + NaOH → CH₃COONa + H₂O."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 1),
  (2370, 599, 'What gas is produced when ethanoic acid reacts with sodium carbonate?', 'text', 1, 'Focus on the core principle of Reactions of Ethanoic Acid.', '{"why":"Carbon dioxide is the characteristic gas produced when an acid reacts with a carbonate.","sol":"Step 1: Ethanoic acid is an acid.\nStep 2: Acids react with carbonates.\nStep 3: Acid-carbonate reactions produce a salt, water and carbon dioxide.\nStep 4: Therefore, the gas produced is carbon dioxide.","steps":["Step 1: Ethanoic acid is an acid.","Step 2: Acids react with carbonates.","Step 3: Acid-carbonate reactions produce a salt, water and carbon dioxide.","Step 4: Therefore, the gas produced is carbon dioxide."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 2),
  (2371, 599, 'Balance the equation: CH₃COOH + Na₂CO₃ → CH₃COONa + H₂O + CO₂.', 'text', 1, 'Balance the sodium atoms first.', '{"why":"The coefficients make the number of every type of atom equal on both sides.","sol":"Step 1: Na₂CO₃ contains two sodium atoms.\nStep 2: Place 2 before CH₃COONa.\nStep 3: This requires 2 molecules of CH₃COOH to supply two ethanoate groups.\nStep 4: Check carbon, hydrogen and oxygen atoms.\nStep 5: The balanced equation is 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂.","steps":["Step 1: Na₂CO₃ contains two sodium atoms.","Step 2: Place 2 before CH₃COONa.","Step 3: This requires 2 molecules of CH₃COOH to supply two ethanoate groups.","Step 4: Check carbon, hydrogen and oxygen atoms.","Step 5: The balanced equation is 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂."],"options":[],"conceptId":"chemistry_organic_chemistry_reactions_of_ethanoic_acid","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Reactions of Ethanoic Acid"}', 3),
  (2372, 600, 'What happens to the carbon-carbon double bond when hydrogen is added to ethene?', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"Hydrogenation is an addition reaction in which hydrogen atoms add across the carbon-carbon double bond.","sol":"Step 1: Ethene contains a C=C double bond.\nStep 2: Hydrogen adds across the double bond.\nStep 3: The C=C double bond becomes a C-C single bond.\nStep 4: Ethene is converted into ethane.","steps":["Step 1: Ethene contains a C=C double bond.","Step 2: Hydrogen adds across the double bond.","Step 3: The C=C double bond becomes a C-C single bond.","Step 4: Ethene is converted into ethane."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 0),
  (2373, 600, 'Write the balanced equation for the reaction between ethene and hydrogen.', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"One molecule of hydrogen adds across the double bond of one molecule of ethene.","sol":"Step 1: Write the formula of ethene: C₂H₄.\nStep 2: Write the formula of hydrogen: H₂.\nStep 3: Addition across the double bond produces ethane, C₂H₆.\nStep 4: Check the atoms: 2 carbon atoms and 6 hydrogen atoms occur on both sides.","steps":["Step 1: Write the formula of ethene: C₂H₄.","Step 2: Write the formula of hydrogen: H₂.","Step 3: Addition across the double bond produces ethane, C₂H₆.","Step 4: Check the atoms: 2 carbon atoms and 6 hydrogen atoms occur on both sides."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 1),
  (2374, 600, 'What product is formed when ethene reacts with bromine?', 'text', 1, 'Focus on the core principle of Addition Reactions.', '{"why":"Bromine undergoes an addition reaction with the carbon-carbon double bond.","sol":"Step 1: Ethene contains a C=C double bond.\nStep 2: Bromine adds across the double bond.\nStep 3: The product formed is 1,2-dibromoethane.","steps":["Step 1: Ethene contains a C=C double bond.","Step 2: Bromine adds across the double bond.","Step 3: The product formed is 1,2-dibromoethane."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 2),
  (2375, 600, 'An alkene reacts with hydrogen in the presence of nickel and heat. What type of reaction has occurred?', 'text', 1, 'Think about what happens when atoms are added across a double bond.', '{"why":"Hydrogen is added across the carbon-carbon double bond of the alkene.","sol":"Step 1: The reactant is an alkene containing a C=C bond.\nStep 2: Hydrogen is added across the double bond.\nStep 3: The double bond becomes a single bond.\nStep 4: Therefore, the reaction is an addition reaction.","steps":["Step 1: The reactant is an alkene containing a C=C bond.","Step 2: Hydrogen is added across the double bond.","Step 3: The double bond becomes a single bond.","Step 4: Therefore, the reaction is an addition reaction."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 3),
  (2376, 600, 'Complete the equation: C₂H₄ + Br₂ → ?', 'text', 1, 'Bromine adds across the double bond of ethene.', '{"why":"Bromine adds across the double bond to form 1,2-dibromoethane.","sol":"Step 1: Start with ethene, C₂H₄.\nStep 2: Add Br₂ across the C=C double bond.\nStep 3: The product contains two bromine atoms.\nStep 4: The product is C₂H₄Br₂.","steps":["Step 1: Start with ethene, C₂H₄.","Step 2: Add Br₂ across the C=C double bond.","Step 3: The product contains two bromine atoms.","Step 4: The product is C₂H₄Br₂."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_reactions","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Reactions"}', 4),
  (2377, 601, 'What type of reaction forms an ester from an alcohol and a carboxylic acid?', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"Esterification is the reaction between an alcohol and a carboxylic acid to form an ester and water.","sol":"Step 1: An alcohol is reacted with a carboxylic acid.\nStep 2: The reaction produces an ester and water.\nStep 3: This reaction is called esterification.","steps":["Step 1: An alcohol is reacted with a carboxylic acid.","Step 2: The reaction produces an ester and water.","Step 3: This reaction is called esterification."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 0),
  (2378, 601, 'Write the equation for the reaction between ethanol and ethanoic acid.', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"Ethanoic acid reacts with ethanol to form ethyl ethanoate and water.","sol":"Step 1: Write ethanol as C₂H₅OH.\nStep 2: Write ethanoic acid as CH₃COOH.\nStep 3: The ester formed is ethyl ethanoate, CH₃COOC₂H₅.\nStep 4: Water is also produced.\nStep 5: Use a reversible arrow because esterification is reversible.","steps":["Step 1: Write ethanol as C₂H₅OH.","Step 2: Write ethanoic acid as CH₃COOH.","Step 3: The ester formed is ethyl ethanoate, CH₃COOC₂H₅.","Step 4: Water is also produced.","Step 5: Use a reversible arrow because esterification is reversible."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 1),
  (2379, 601, 'What catalyst is commonly used during esterification?', 'text', 1, 'Focus on the core principle of Ester Formation.', '{"why":"Concentrated sulfuric acid acts as an acid catalyst in esterification.","sol":"Step 1: Esterification is normally carried out with an acid catalyst.\nStep 2: Concentrated sulfuric acid provides the required acidic conditions.\nStep 3: Therefore, concentrated sulfuric acid is commonly used.","steps":["Step 1: Esterification is normally carried out with an acid catalyst.","Step 2: Concentrated sulfuric acid provides the required acidic conditions.","Step 3: Therefore, concentrated sulfuric acid is commonly used."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 2),
  (2380, 601, 'Ethanol reacts with propanoic acid. What type of compound is produced together with water?', 'text', 1, 'An alcohol reacting with a carboxylic acid forms an ester.', '{"why":"Esterification produces an ester and water.","sol":"Step 1: Ethanol is an alcohol.\nStep 2: Propanoic acid is a carboxylic acid.\nStep 3: Alcohol + carboxylic acid produces an ester and water.","steps":["Step 1: Ethanol is an alcohol.","Step 2: Propanoic acid is a carboxylic acid.","Step 3: Alcohol + carboxylic acid produces an ester and water."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 3),
  (2381, 601, 'Why is a reversible arrow used in the equation for esterification?', 'text', 1, 'Consider whether the products can react to reform the reactants.', '{"why":"The ester and water can react to reform the alcohol and carboxylic acid.","sol":"Step 1: Esterification produces an ester and water.\nStep 2: The products can react under suitable conditions to form the original reactants.\nStep 3: Therefore, the reaction is reversible.","steps":["Step 1: Esterification produces an ester and water.","Step 2: The products can react under suitable conditions to form the original reactants.","Step 3: Therefore, the reaction is reversible."],"options":[],"conceptId":"chemistry_organic_chemistry_ester_formation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Ester Formation"}', 4),
  (2382, 602, 'What is a monomer?', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"Polymers are formed from repeating monomer units.","sol":"Step 1: A polymer is a large molecule made from repeating smaller units.\nStep 2: The small molecules that join together are called monomers.\nStep 3: Therefore, a monomer is a small molecule that can join with other molecules to form a polymer.","steps":["Step 1: A polymer is a large molecule made from repeating smaller units.","Step 2: The small molecules that join together are called monomers.","Step 3: Therefore, a monomer is a small molecule that can join with other molecules to form a polymer."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 0),
  (2383, 602, 'What monomer is used to make poly(ethene)?', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"Ethene molecules undergo addition polymerisation to form poly(ethene).","sol":"Step 1: Identify the repeating unit in poly(ethene): −CH₂−CH₂−.\nStep 2: This repeating unit comes from ethene.\nStep 3: Ethene contains the C=C double bond needed for addition polymerisation.","steps":["Step 1: Identify the repeating unit in poly(ethene): −CH₂−CH₂−.","Step 2: This repeating unit comes from ethene.","Step 3: Ethene contains the C=C double bond needed for addition polymerisation."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 1),
  (2384, 602, 'What happens to the double bond in an alkene during addition polymerisation?', 'text', 1, 'Focus on the core principle of Addition Polymerisation.', '{"why":"Opening the double bond allows the alkene molecules to link into a long chain.","sol":"Step 1: The alkene monomer contains a C=C double bond.\nStep 2: The double bond opens during polymerisation.\nStep 3: The carbon atoms form new single bonds with neighbouring monomers.\nStep 4: A long polymer chain is produced.","steps":["Step 1: The alkene monomer contains a C=C double bond.","Step 2: The double bond opens during polymerisation.","Step 3: The carbon atoms form new single bonds with neighbouring monomers.","Step 4: A long polymer chain is produced."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 2),
  (2385, 602, 'Ethene is polymerised. What polymer is formed?', 'text', 1, 'The polymer name is based on the monomer ethene.', '{"why":"Ethene molecules join together by addition polymerisation to form poly(ethene).","sol":"Step 1: The monomer is ethene.\nStep 2: Ethene undergoes addition polymerisation.\nStep 3: The polymer formed is poly(ethene).","steps":["Step 1: The monomer is ethene.","Step 2: Ethene undergoes addition polymerisation.","Step 3: The polymer formed is poly(ethene)."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 3),
  (2386, 602, 'Does addition polymerisation produce a small molecule such as water as a by-product?', 'text', 1, 'Compare addition polymerisation with condensation polymerisation.', '{"why":"Addition polymerisation joins the monomers without eliminating a small molecule.","sol":"Step 1: In addition polymerisation, alkene monomers join directly.\nStep 2: No small molecule is removed.\nStep 3: Therefore, water is not produced as a by-product.","steps":["Step 1: In addition polymerisation, alkene monomers join directly.","Step 2: No small molecule is removed.","Step 3: Therefore, water is not produced as a by-product."],"options":[],"conceptId":"chemistry_organic_chemistry_addition_polymerisation","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Addition Polymerisation"}', 4),
  (2387, 603, 'What is crude oil?', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"Crude oil contains many different hydrocarbon molecules rather than one pure compound.","sol":"Step 1: Crude oil occurs naturally beneath the Earth''s surface.\nStep 2: It contains many different hydrocarbons.\nStep 3: Therefore, crude oil is a mixture of hydrocarbons.","steps":["Step 1: Crude oil occurs naturally beneath the Earth''s surface.","Step 2: It contains many different hydrocarbons.","Step 3: Therefore, crude oil is a mixture of hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 0),
  (2388, 603, 'Why is crude oil described as a mixture?', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"The different hydrocarbons retain their individual properties and can be separated by fractional distillation.","sol":"Step 1: A mixture contains two or more substances that are not chemically combined.\nStep 2: Crude oil contains many different hydrocarbons.\nStep 3: These hydrocarbons can be separated physically.\nStep 4: Therefore, crude oil is a mixture.","steps":["Step 1: A mixture contains two or more substances that are not chemically combined.","Step 2: Crude oil contains many different hydrocarbons.","Step 3: These hydrocarbons can be separated physically.","Step 4: Therefore, crude oil is a mixture."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 1),
  (2389, 603, 'Why is crude oil separated into fractions?', 'text', 1, 'Focus on the core principle of Crude Oil.', '{"why":"Different fractions have different properties and therefore different applications.","sol":"Step 1: Crude oil contains many hydrocarbons.\nStep 2: Different hydrocarbons have different properties and uses.\nStep 3: Separating them produces groups of hydrocarbons with useful ranges of boiling points.\nStep 4: These groups are called fractions.","steps":["Step 1: Crude oil contains many hydrocarbons.","Step 2: Different hydrocarbons have different properties and uses.","Step 3: Separating them produces groups of hydrocarbons with useful ranges of boiling points.","Step 4: These groups are called fractions."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 2),
  (2390, 603, 'Is crude oil an element, compound or mixture?', 'text', 1, 'Crude oil contains many different hydrocarbons.', '{"why":"Crude oil contains many different hydrocarbons.","sol":"Step 1: An element contains one type of atom.\nStep 2: A compound contains chemically combined elements in fixed proportions.\nStep 3: Crude oil contains many different hydrocarbons.\nStep 4: Therefore, crude oil is a mixture.","steps":["Step 1: An element contains one type of atom.","Step 2: A compound contains chemically combined elements in fixed proportions.","Step 3: Crude oil contains many different hydrocarbons.","Step 4: Therefore, crude oil is a mixture."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 3),
  (2391, 603, 'What type of substances make up crude oil?', 'text', 1, 'Think about the substances discussed in Organic Chemistry.', '{"why":"Crude oil consists mainly of hydrocarbons.","sol":"Step 1: Crude oil contains compounds made only of carbon and hydrogen.\nStep 2: Such compounds are called hydrocarbons.","steps":["Step 1: Crude oil contains compounds made only of carbon and hydrogen.","Step 2: Such compounds are called hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_crude_oil","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Crude Oil"}', 4),
  (2392, 604, 'What is cracking?', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"Cracking converts heavy, long-chain hydrocarbons into smaller molecules such as alkanes and alkenes.","sol":"Step 1: Large hydrocarbons are heated under suitable conditions.\nStep 2: Their long carbon chains are broken into smaller molecules.\nStep 3: The smaller products are more useful hydrocarbons.","steps":["Step 1: Large hydrocarbons are heated under suitable conditions.","Step 2: Their long carbon chains are broken into smaller molecules.","Step 3: The smaller products are more useful hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q1","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 0),
  (2393, 604, 'What two types of hydrocarbons are commonly produced during cracking?', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"Cracking commonly produces smaller alkanes together with alkenes.","sol":"Step 1: Cracking breaks large hydrocarbon molecules into smaller molecules.\nStep 2: The products commonly include saturated and unsaturated hydrocarbons.\nStep 3: Saturated hydrocarbons are alkanes and unsaturated hydrocarbons include alkenes.","steps":["Step 1: Cracking breaks large hydrocarbon molecules into smaller molecules.","Step 2: The products commonly include saturated and unsaturated hydrocarbons.","Step 3: Saturated hydrocarbons are alkanes and unsaturated hydrocarbons include alkenes."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q2","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 1),
  (2394, 604, 'Balance the cracking equation: C₁₀H₂₂ → C₈H₁₈ + C₂H₄.', 'text', 1, 'Focus on the core principle of Cracking.', '{"why":"The equation is already balanced with 10 carbon atoms and 22 hydrogen atoms on each side.","sol":"Step 1: Count carbon atoms on the right: 8 + 2 = 10.\nStep 2: Count hydrogen atoms on the right: 18 + 4 = 22.\nStep 3: The number of carbon and hydrogen atoms is already equal on both sides.","steps":["Step 1: Count carbon atoms on the right: 8 + 2 = 10.","Step 2: Count hydrogen atoms on the right: 18 + 4 = 22.","Step 3: The number of carbon and hydrogen atoms is already equal on both sides."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q3","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 2),
  (2395, 604, 'Why is cracking carried out on some heavy fractions of crude oil?', 'text', 1, 'Think about the demand for smaller hydrocarbons.', '{"why":"Cracking increases the supply of useful smaller hydrocarbons.","sol":"Step 1: Heavy fractions contain large hydrocarbon molecules.\nStep 2: Some smaller hydrocarbons are in greater demand.\nStep 3: Cracking converts large molecules into smaller, more useful hydrocarbons.","steps":["Step 1: Heavy fractions contain large hydrocarbon molecules.","Step 2: Some smaller hydrocarbons are in greater demand.","Step 3: Cracking converts large molecules into smaller, more useful hydrocarbons."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q4","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 3),
  (2396, 604, 'A large alkane is cracked and one of the products is ethene. Is ethene an alkane or an alkene?', 'text', 1, 'Look at ethene''s carbon-carbon bonding.', '{"why":"Ethene contains a carbon-carbon double bond and therefore belongs to the alkene homologous series.","sol":"Step 1: Ethene has the formula C₂H₄.\nStep 2: It contains a carbon-carbon double bond.\nStep 3: Hydrocarbons containing a C=C double bond are alkenes.","steps":["Step 1: Ethene has the formula C₂H₄.","Step 2: It contains a carbon-carbon double bond.","Step 3: Hydrocarbons containing a C=C double bond are alkenes."],"options":[],"conceptId":"chemistry_organic_chemistry_cracking","skillId":"chemistry_organic_chemistry","subskillId":"chemistry_organic_chemistry_q5","subject":"chemistry","chapter":"organic_chemistry","topic":"Cracking"}', 4),
  (2397, 605, 'State two physical properties of sulphur.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"These are observable physical properties of sulphur.","sol":"Step 1: Sulphur is a yellow solid at room temperature.\nStep 2: It is brittle.\nStep 3: It is also a poor conductor of electricity and insoluble in water.\nStep 4: Any two of these are acceptable.","steps":["Step 1: Sulphur is a yellow solid at room temperature.","Step 2: It is brittle.","Step 3: It is also a poor conductor of electricity and insoluble in water.","Step 4: Any two of these are acceptable."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 0),
  (2398, 605, 'What happens when sulphur burns in oxygen?', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"Sulphur combines with oxygen during combustion to form sulphur dioxide.","sol":"Step 1: Sulphur reacts with oxygen.\nStep 2: The product formed is sulphur dioxide.\nStep 3: Write the equation: S + O₂ → SO₂.","steps":["Step 1: Sulphur reacts with oxygen.","Step 2: The product formed is sulphur dioxide.","Step 3: Write the equation: S + O₂ → SO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 1),
  (2399, 605, 'Balance the equation S + O₂ → SO₂.', 'text', 1, 'Focus on the core principle of Properties of Sulphur.', '{"why":"There is one sulphur atom and two oxygen atoms on each side.","sol":"Step 1: Count sulphur atoms on both sides. There is one on each side.\nStep 2: Count oxygen atoms. There are two on each side.\nStep 3: The equation is already balanced.","steps":["Step 1: Count sulphur atoms on both sides. There is one on each side.","Step 2: Count oxygen atoms. There are two on each side.","Step 3: The equation is already balanced."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 2),
  (2400, 605, 'Why is sulphur classified as a non-metal?', 'text', 1, 'Think about its electrical conductivity and physical properties.', '{"why":"Sulphur lacks the typical metallic properties of good conductivity, malleability and ductility.","sol":"Step 1: Sulphur is brittle rather than malleable.\nStep 2: It is a poor conductor of electricity.\nStep 3: These are characteristic properties of non-metals.","steps":["Step 1: Sulphur is brittle rather than malleable.","Step 2: It is a poor conductor of electricity.","Step 3: These are characteristic properties of non-metals."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_sulphur","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Sulphur"}', 3),
  (2401, 606, 'What is the formula of sulphur dioxide?', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"The name sulphur dioxide indicates one sulphur atom and two oxygen atoms.","sol":"Step 1: Sulphur has the symbol S.\nStep 2: Dioxide means two oxygen atoms.\nStep 3: Therefore, the formula is SO₂.","steps":["Step 1: Sulphur has the symbol S.","Step 2: Dioxide means two oxygen atoms.","Step 3: Therefore, the formula is SO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 0),
  (2402, 606, 'How can sulphur dioxide be prepared from sulphur?', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"Sulphur combines directly with oxygen to form sulphur dioxide.","sol":"Step 1: React sulphur with oxygen.\nStep 2: The product is sulphur dioxide.\nStep 3: Write the equation: S + O₂ → SO₂.","steps":["Step 1: React sulphur with oxygen.","Step 2: The product is sulphur dioxide.","Step 3: Write the equation: S + O₂ → SO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 1),
  (2403, 606, 'State two properties of sulphur dioxide.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide.', '{"why":"These are characteristic properties of sulphur dioxide.","sol":"Step 1: Sulphur dioxide is a colourless gas.\nStep 2: It has a pungent smell.\nStep 3: It is also soluble in water and acidic in nature.\nStep 4: Any two are acceptable.","steps":["Step 1: Sulphur dioxide is a colourless gas.","Step 2: It has a pungent smell.","Step 3: It is also soluble in water and acidic in nature.","Step 4: Any two are acceptable."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 2),
  (2404, 606, 'Why is sulphur dioxide considered an air pollutant?', 'text', 1, 'Think about what happens when it enters the atmosphere.', '{"why":"Sulphur dioxide is harmful to the environment and human health.","sol":"Step 1: Sulphur dioxide can be released when sulphur-containing fuels burn.\nStep 2: It can react with substances in the atmosphere.\nStep 3: It contributes to acid rain and respiratory problems.","steps":["Step 1: Sulphur dioxide can be released when sulphur-containing fuels burn.","Step 2: It can react with substances in the atmosphere.","Step 3: It contributes to acid rain and respiratory problems."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Dioxide"}', 3),
  (2405, 607, 'What is formed when sulphur dioxide dissolves in water?', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"Sulphur dioxide reacts with water to form sulphurous acid.","sol":"Step 1: Sulphur dioxide reacts with water.\nStep 2: The acid formed is sulphurous acid.\nStep 3: The equation is SO₂ + H₂O ⇌ H₂SO₃.","steps":["Step 1: Sulphur dioxide reacts with water.","Step 2: The acid formed is sulphurous acid.","Step 3: The equation is SO₂ + H₂O ⇌ H₂SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 0),
  (2406, 607, 'Write the equation for oxidation of sulphur dioxide to sulphur trioxide.', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"Two SO₂ molecules provide two sulphur atoms and four oxygen atoms; O₂ supplies the remaining two oxygen atoms.","sol":"Step 1: Sulphur dioxide is SO₂.\nStep 2: Oxygen is the oxidising reactant.\nStep 3: The product is SO₃.\nStep 4: Balance the equation: 2SO₂ + O₂ → 2SO₃.","steps":["Step 1: Sulphur dioxide is SO₂.","Step 2: Oxygen is the oxidising reactant.","Step 3: The product is SO₃.","Step 4: Balance the equation: 2SO₂ + O₂ → 2SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 1),
  (2407, 607, 'What acid is formed when SO₂ reacts with water?', 'text', 1, 'Focus on the core principle of Reactions of Sulphur Dioxide.', '{"why":"SO₂ dissolved in water forms sulphurous acid.","sol":"Step 1: Write SO₂ + H₂O.\nStep 2: The product is H₂SO₃.\nStep 3: H₂SO₃ is sulphurous acid.","steps":["Step 1: Write SO₂ + H₂O.","Step 2: The product is H₂SO₃.","Step 3: H₂SO₃ is sulphurous acid."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 2),
  (2408, 607, 'Balance SO₂ + O₂ → SO₃.', 'text', 1, 'Start by balancing sulphur atoms.', '{"why":"The coefficients give equal numbers of sulphur and oxygen atoms on both sides.","sol":"Step 1: Put 2 before SO₂ and 2 before SO₃.\nStep 2: Oxygen atoms on the left are now 4 + 2 = 6.\nStep 3: Oxygen atoms on the right are 2 × 3 = 6.\nStep 4: The balanced equation is 2SO₂ + O₂ → 2SO₃.","steps":["Step 1: Put 2 before SO₂ and 2 before SO₃.","Step 2: Oxygen atoms on the left are now 4 + 2 = 6.","Step 3: Oxygen atoms on the right are 2 × 3 = 6.","Step 4: The balanced equation is 2SO₂ + O₂ → 2SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_reactions_of_sulphur_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Reactions of Sulphur Dioxide"}', 3),
  (2409, 608, 'What is the formula of sulphur trioxide?', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"The name indicates one sulphur atom and three oxygen atoms.","sol":"Step 1: Sulphur has the symbol S.\nStep 2: Trioxide means three oxygen atoms.\nStep 3: Therefore, the formula is SO₃.","steps":["Step 1: Sulphur has the symbol S.","Step 2: Trioxide means three oxygen atoms.","Step 3: Therefore, the formula is SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 0),
  (2410, 608, 'How is sulphur trioxide formed from sulphur dioxide?', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"Sulphur dioxide is oxidised by oxygen to sulphur trioxide.","sol":"Step 1: Sulphur dioxide reacts with oxygen.\nStep 2: The product is sulphur trioxide.\nStep 3: Balance the equation.\nStep 4: 2SO₂ + O₂ → 2SO₃.","steps":["Step 1: Sulphur dioxide reacts with oxygen.","Step 2: The product is sulphur trioxide.","Step 3: Balance the equation.","Step 4: 2SO₂ + O₂ → 2SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 1),
  (2411, 608, 'What is formed when sulphur trioxide reacts with water?', 'text', 1, 'Focus on the core principle of Sulphur Trioxide.', '{"why":"Sulphur trioxide reacts with water to produce sulphuric acid.","sol":"Step 1: Write SO₃ + H₂O.\nStep 2: The product is H₂SO₄.\nStep 3: H₂SO₄ is sulphuric acid.","steps":["Step 1: Write SO₃ + H₂O.","Step 2: The product is H₂SO₄.","Step 3: H₂SO₄ is sulphuric acid."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 2),
  (2412, 608, 'Write the balanced equation for the reaction between SO₃ and water.', 'text', 1, 'One SO₃ molecule reacts with one H₂O molecule.', '{"why":"One sulphur, two hydrogen and four oxygen atoms occur on both sides.","sol":"Step 1: Write SO₃ + H₂O.\nStep 2: The product is H₂SO₄.\nStep 3: Check the atoms on both sides.\nStep 4: The equation is already balanced.","steps":["Step 1: Write SO₃ + H₂O.","Step 2: The product is H₂SO₄.","Step 3: Check the atoms on both sides.","Step 4: The equation is already balanced."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphur_trioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphur Trioxide"}', 3),
  (2413, 609, 'What is the formula of sulphuric acid?', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"Sulphuric acid contains H₂SO₄.","sol":"Step 1: Identify the chemical formula of sulphuric acid.\nStep 2: It contains two hydrogen atoms, one sulphur atom and four oxygen atoms.\nStep 3: Therefore, the formula is H₂SO₄.","steps":["Step 1: Identify the chemical formula of sulphuric acid.","Step 2: It contains two hydrogen atoms, one sulphur atom and four oxygen atoms.","Step 3: Therefore, the formula is H₂SO₄."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 0),
  (2414, 609, 'What salt is formed when sulphuric acid reacts with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"The sulphate ion combines with sodium ions to form sodium sulphate.","sol":"Step 1: Sulphuric acid provides the sulphate ion.\nStep 2: Sodium hydroxide provides sodium ions.\nStep 3: The salt formed is sodium sulphate.\nStep 4: The complete equation is H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O.","steps":["Step 1: Sulphuric acid provides the sulphate ion.","Step 2: Sodium hydroxide provides sodium ions.","Step 3: The salt formed is sodium sulphate.","Step 4: The complete equation is H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 1),
  (2415, 609, 'Balance H₂SO₄ + NaOH → Na₂SO₄ + H₂O.', 'text', 1, 'Focus on the core principle of Sulphuric Acid.', '{"why":"The coefficients balance sodium and hydrogen while sulphur and oxygen are already balanced.","sol":"Step 1: Na₂SO₄ contains two sodium atoms.\nStep 2: Place 2 before NaOH.\nStep 3: There are now four hydrogen atoms on the left.\nStep 4: Place 2 before H₂O.\nStep 5: The balanced equation is H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O.","steps":["Step 1: Na₂SO₄ contains two sodium atoms.","Step 2: Place 2 before NaOH.","Step 3: There are now four hydrogen atoms on the left.","Step 4: Place 2 before H₂O.","Step 5: The balanced equation is H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 2),
  (2416, 609, 'Why must concentrated sulphuric acid be handled carefully?', 'text', 1, 'Consider its effect on materials and living tissue.', '{"why":"Its corrosive nature makes concentrated sulphuric acid hazardous.","sol":"Step 1: Concentrated sulphuric acid is highly corrosive.\nStep 2: Corrosive substances can damage skin and other materials.\nStep 3: Therefore, appropriate protective equipment and careful handling are required.","steps":["Step 1: Concentrated sulphuric acid is highly corrosive.","Step 2: Corrosive substances can damage skin and other materials.","Step 3: Therefore, appropriate protective equipment and careful handling are required."],"options":[],"conceptId":"chemistry_nonmetals_compounds_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Sulphuric Acid"}', 3),
  (2417, 610, 'Name the industrial process used to manufacture sulphuric acid.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"The Contact Process is the industrial method used to manufacture sulphuric acid.","sol":"Step 1: Identify the industrial manufacture of sulphuric acid.\nStep 2: The process is called the Contact Process.","steps":["Step 1: Identify the industrial manufacture of sulphuric acid.","Step 2: The process is called the Contact Process."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 0),
  (2418, 610, 'Write the equation for formation of sulphur dioxide from sulphur.', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"Burning sulphur in oxygen produces sulphur dioxide.","sol":"Step 1: Sulphur reacts with oxygen.\nStep 2: The product is sulphur dioxide.\nStep 3: Write the balanced equation: S + O₂ → SO₂.","steps":["Step 1: Sulphur reacts with oxygen.","Step 2: The product is sulphur dioxide.","Step 3: Write the balanced equation: S + O₂ → SO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 1),
  (2419, 610, 'What catalyst is commonly used to oxidise SO₂ to SO₃ in the Contact Process?', 'text', 1, 'Focus on the core principle of Manufacture of Sulphuric Acid.', '{"why":"Vanadium(V) oxide catalyses the oxidation of sulphur dioxide to sulphur trioxide.","sol":"Step 1: Identify the oxidation step: 2SO₂ + O₂ ⇌ 2SO₃.\nStep 2: The industrial catalyst used is vanadium(V) oxide.\nStep 3: Therefore, the catalyst is V₂O₅.","steps":["Step 1: Identify the oxidation step: 2SO₂ + O₂ ⇌ 2SO₃.","Step 2: The industrial catalyst used is vanadium(V) oxide.","Step 3: Therefore, the catalyst is V₂O₅."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 2),
  (2420, 610, 'Why is a catalyst used in the Contact Process?', 'text', 1, 'Think about the effect of a catalyst on reaction rate.', '{"why":"The catalyst makes the industrial reaction proceed faster without being consumed overall.","sol":"Step 1: A catalyst increases the rate of a reaction.\nStep 2: It does this without being permanently consumed.\nStep 3: Therefore, V₂O₅ is used to increase the rate of oxidation of SO₂ to SO₃.","steps":["Step 1: A catalyst increases the rate of a reaction.","Step 2: It does this without being permanently consumed.","Step 3: Therefore, V₂O₅ is used to increase the rate of oxidation of SO₂ to SO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_manufacture_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Manufacture of Sulphuric Acid"}', 3),
  (2421, 611, 'State two uses of sulphuric acid.', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Sulphuric acid has many important industrial applications.","sol":"Step 1: Sulphuric acid is widely used industrially.\nStep 2: It is used in fertiliser manufacture.\nStep 3: It is also used in petroleum processing, chemical manufacture and lead-acid batteries.\nStep 4: Any two are acceptable.","steps":["Step 1: Sulphuric acid is widely used industrially.","Step 2: It is used in fertiliser manufacture.","Step 3: It is also used in petroleum processing, chemical manufacture and lead-acid batteries.","Step 4: Any two are acceptable."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 0),
  (2422, 611, 'Why is sulphuric acid important in fertiliser manufacture?', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Sulphuric acid is an important raw material in the industrial production of fertilisers.","sol":"Step 1: Fertiliser production requires compounds containing nutrients such as phosphorus.\nStep 2: Sulphuric acid is used to process phosphate-containing materials.\nStep 3: This helps produce phosphate fertilisers.","steps":["Step 1: Fertiliser production requires compounds containing nutrients such as phosphorus.","Step 2: Sulphuric acid is used to process phosphate-containing materials.","Step 3: This helps produce phosphate fertilisers."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 1),
  (2423, 611, 'Which type of battery commonly uses sulphuric acid as its electrolyte?', 'text', 1, 'Focus on the core principle of Uses of Sulphuric Acid.', '{"why":"Dilute sulphuric acid acts as the electrolyte in lead-acid batteries.","sol":"Step 1: Identify the common rechargeable battery used in vehicles.\nStep 2: Lead-acid batteries use dilute sulphuric acid as the electrolyte.","steps":["Step 1: Identify the common rechargeable battery used in vehicles.","Step 2: Lead-acid batteries use dilute sulphuric acid as the electrolyte."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 2),
  (2424, 611, 'State one industrial use of sulphuric acid other than fertiliser manufacture.', 'text', 1, 'Think about batteries, petroleum or chemical manufacture.', '{"why":"Sulphuric acid has several industrial uses beyond fertiliser production.","sol":"Step 1: Recall major industrial applications.\nStep 2: One example is its use in lead-acid batteries.\nStep 3: Other acceptable examples include petroleum processing and chemical manufacture.","steps":["Step 1: Recall major industrial applications.","Step 2: One example is its use in lead-acid batteries.","Step 3: Other acceptable examples include petroleum processing and chemical manufacture."],"options":[],"conceptId":"chemistry_nonmetals_compounds_uses_of_sulphuric_acid","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Uses of Sulphuric Acid"}', 3),
  (2425, 612, 'How many valence electrons does carbon have?', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Carbon has four electrons in its outermost shell.","sol":"Step 1: Carbon has atomic number 6.\nStep 2: Its electron arrangement is 2,4.\nStep 3: Therefore, carbon has four electrons in its outer shell.","steps":["Step 1: Carbon has atomic number 6.","Step 2: Its electron arrangement is 2,4.","Step 3: Therefore, carbon has four electrons in its outer shell."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 0),
  (2426, 612, 'Why can carbon form four covalent bonds?', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Carbon''s four outer electrons allow it to form four covalent bonds.","sol":"Step 1: Carbon has four valence electrons.\nStep 2: It needs four more electrons to complete its outer shell.\nStep 3: Carbon can share electrons with other atoms.\nStep 4: It can therefore form four covalent bonds.","steps":["Step 1: Carbon has four valence electrons.","Step 2: It needs four more electrons to complete its outer shell.","Step 3: Carbon can share electrons with other atoms.","Step 4: It can therefore form four covalent bonds."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 1),
  (2427, 612, 'What is catenation?', 'text', 1, 'Focus on the core principle of Properties of Carbon.', '{"why":"Catenation is a major reason why carbon forms such a large variety of compounds.","sol":"Step 1: Identify the ability involved in carbon-carbon bonding.\nStep 2: Carbon atoms can bond to other carbon atoms.\nStep 3: This allows chains, branches and rings to form.\nStep 4: This property is called catenation.","steps":["Step 1: Identify the ability involved in carbon-carbon bonding.","Step 2: Carbon atoms can bond to other carbon atoms.","Step 3: This allows chains, branches and rings to form.","Step 4: This property is called catenation."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 2),
  (2428, 612, 'What is tetravalency of carbon?', 'text', 1, 'Look at the number of covalent bonds carbon can form.', '{"why":"Carbon is tetravalent because it can form four covalent bonds.","sol":"Step 1: Carbon has four valence electrons.\nStep 2: It can share electrons with other atoms.\nStep 3: It can form four covalent bonds.\nStep 4: This property is called tetravalency.","steps":["Step 1: Carbon has four valence electrons.","Step 2: It can share electrons with other atoms.","Step 3: It can form four covalent bonds.","Step 4: This property is called tetravalency."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Carbon"}', 3),
  (2429, 613, 'What is the formula of carbon dioxide?', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"Carbon dioxide contains one carbon atom and two oxygen atoms.","sol":"Step 1: Carbon has the symbol C.\nStep 2: Dioxide means two oxygen atoms.\nStep 3: Therefore, the formula is CO₂.","steps":["Step 1: Carbon has the symbol C.","Step 2: Dioxide means two oxygen atoms.","Step 3: Therefore, the formula is CO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 0),
  (2430, 613, 'Write the equation for complete combustion of carbon.', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"Carbon burns in oxygen to form carbon dioxide.","sol":"Step 1: Carbon reacts with oxygen.\nStep 2: Complete combustion forms carbon dioxide.\nStep 3: The balanced equation is C + O₂ → CO₂.","steps":["Step 1: Carbon reacts with oxygen.","Step 2: Complete combustion forms carbon dioxide.","Step 3: The balanced equation is C + O₂ → CO₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 1),
  (2431, 613, 'State two properties of carbon dioxide.', 'text', 1, 'Focus on the core principle of Carbon Dioxide.', '{"why":"These are characteristic physical and chemical properties of carbon dioxide.","sol":"Step 1: Carbon dioxide is a colourless gas.\nStep 2: It does not support combustion.\nStep 3: It is also denser than air.\nStep 4: Any two are acceptable.","steps":["Step 1: Carbon dioxide is a colourless gas.","Step 2: It does not support combustion.","Step 3: It is also denser than air.","Step 4: Any two are acceptable."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 2),
  (2432, 613, 'Why can carbon dioxide be used to extinguish some fires?', 'text', 1, 'Consider whether it supports combustion.', '{"why":"Reducing the oxygen available to a fire can stop combustion.","sol":"Step 1: Combustion requires oxygen.\nStep 2: Carbon dioxide does not support combustion.\nStep 3: A layer of carbon dioxide can reduce contact between the fuel and oxygen.\nStep 4: Therefore, carbon dioxide can help extinguish some fires.","steps":["Step 1: Combustion requires oxygen.","Step 2: Carbon dioxide does not support combustion.","Step 3: A layer of carbon dioxide can reduce contact between the fuel and oxygen.","Step 4: Therefore, carbon dioxide can help extinguish some fires."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_dioxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Dioxide"}', 3),
  (2433, 614, 'What is the formula of carbon monoxide?', 'text', 1, 'Focus on the core principle of Carbon Monoxide.', '{"why":"Carbon monoxide contains one carbon atom and one oxygen atom.","sol":"Step 1: Carbon has the symbol C.\nStep 2: Monoxide means one oxygen atom.\nStep 3: Therefore, the formula is CO.","steps":["Step 1: Carbon has the symbol C.","Step 2: Monoxide means one oxygen atom.","Step 3: Therefore, the formula is CO."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_monoxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Monoxide"}', 0),
  (2434, 614, 'Under what combustion condition is carbon monoxide formed?', 'text', 1, 'Focus on the core principle of Carbon Monoxide.', '{"why":"Carbon monoxide forms when carbon-containing fuels burn without enough oxygen for complete combustion.","sol":"Step 1: Complete combustion requires sufficient oxygen.\nStep 2: If oxygen is insufficient, combustion is incomplete.\nStep 3: Incomplete combustion can produce carbon monoxide.","steps":["Step 1: Complete combustion requires sufficient oxygen.","Step 2: If oxygen is insufficient, combustion is incomplete.","Step 3: Incomplete combustion can produce carbon monoxide."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_monoxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Monoxide"}', 1),
  (2435, 614, 'Balance 2C + O₂ → 2CO.', 'text', 1, 'Focus on the core principle of Carbon Monoxide.', '{"why":"There are two carbon atoms and two oxygen atoms on each side.","sol":"Step 1: Count carbon atoms: 2 on both sides.\nStep 2: Count oxygen atoms: 2 on both sides.\nStep 3: The equation is balanced.","steps":["Step 1: Count carbon atoms: 2 on both sides.","Step 2: Count oxygen atoms: 2 on both sides.","Step 3: The equation is balanced."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_monoxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Monoxide"}', 2),
  (2436, 614, 'Why is carbon monoxide poisonous?', 'text', 1, 'Think about oxygen transport in the blood.', '{"why":"Carbon monoxide interferes with oxygen transport in the body.","sol":"Step 1: Carbon monoxide enters the bloodstream when inhaled.\nStep 2: It binds strongly to haemoglobin.\nStep 3: This reduces the blood''s ability to transport oxygen.\nStep 4: Body tissues can therefore become oxygen-starved.","steps":["Step 1: Carbon monoxide enters the bloodstream when inhaled.","Step 2: It binds strongly to haemoglobin.","Step 3: This reduces the blood''s ability to transport oxygen.","Step 4: Body tissues can therefore become oxygen-starved."],"options":[],"conceptId":"chemistry_nonmetals_compounds_carbon_monoxide","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Carbon Monoxide"}', 3),
  (2437, 615, 'What is an allotrope?', 'text', 1, 'Focus on the core principle of Allotropes of Carbon.', '{"why":"Different atomic arrangements produce different allotropes.","sol":"Step 1: An allotrope is a form of an element.\nStep 2: Different allotropes have different structures.\nStep 3: Therefore, allotropes are different structural forms of the same element in the same physical state.","steps":["Step 1: An allotrope is a form of an element.","Step 2: Different allotropes have different structures.","Step 3: Therefore, allotropes are different structural forms of the same element in the same physical state."],"options":[],"conceptId":"chemistry_nonmetals_compounds_allotropes_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Allotropes of Carbon"}', 0),
  (2438, 615, 'Why is diamond very hard?', 'text', 1, 'Focus on the core principle of Allotropes of Carbon.', '{"why":"The strong covalent network makes diamond difficult to deform.","sol":"Step 1: Each carbon atom in diamond is strongly bonded to four other carbon atoms.\nStep 2: These bonds form a giant three-dimensional network.\nStep 3: Many strong covalent bonds must be broken to deform the structure.\nStep 4: Therefore, diamond is very hard.","steps":["Step 1: Each carbon atom in diamond is strongly bonded to four other carbon atoms.","Step 2: These bonds form a giant three-dimensional network.","Step 3: Many strong covalent bonds must be broken to deform the structure.","Step 4: Therefore, diamond is very hard."],"options":[],"conceptId":"chemistry_nonmetals_compounds_allotropes_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Allotropes of Carbon"}', 1),
  (2439, 615, 'Why does graphite conduct electricity?', 'text', 1, 'Focus on the core principle of Allotropes of Carbon.', '{"why":"Mobile delocalised electrons allow graphite to conduct electricity.","sol":"Step 1: Each carbon atom in graphite bonds to three other carbon atoms.\nStep 2: One electron per carbon is not involved in a localised covalent bond.\nStep 3: These electrons can move through the structure.\nStep 4: Therefore, graphite conducts electricity.","steps":["Step 1: Each carbon atom in graphite bonds to three other carbon atoms.","Step 2: One electron per carbon is not involved in a localised covalent bond.","Step 3: These electrons can move through the structure.","Step 4: Therefore, graphite conducts electricity."],"options":[],"conceptId":"chemistry_nonmetals_compounds_allotropes_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Allotropes of Carbon"}', 2),
  (2440, 615, 'State one structural difference between diamond and graphite.', 'text', 1, 'Compare the number of carbon atoms bonded directly to each carbon atom.', '{"why":"The different bonding arrangements give diamond and graphite different properties.","sol":"Step 1: In diamond, each carbon bonds to four other carbon atoms.\nStep 2: In graphite, each carbon bonds to three other carbon atoms.\nStep 3: Therefore, their structures are different.","steps":["Step 1: In diamond, each carbon bonds to four other carbon atoms.","Step 2: In graphite, each carbon bonds to three other carbon atoms.","Step 3: Therefore, their structures are different."],"options":[],"conceptId":"chemistry_nonmetals_compounds_allotropes_of_carbon","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Allotropes of Carbon"}', 3),
  (2441, 616, 'What is the formula of nitrogen gas?', 'text', 1, 'Focus on the core principle of Properties of Nitrogen.', '{"why":"Nitrogen gas exists as molecules containing two nitrogen atoms.","sol":"Step 1: Nitrogen exists naturally as diatomic molecules.\nStep 2: A diatomic molecule contains two nitrogen atoms.\nStep 3: Therefore, the formula is N₂.","steps":["Step 1: Nitrogen exists naturally as diatomic molecules.","Step 2: A diatomic molecule contains two nitrogen atoms.","Step 3: Therefore, the formula is N₂."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_nitrogen","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Nitrogen"}', 0),
  (2442, 616, 'State two physical properties of nitrogen gas.', 'text', 1, 'Focus on the core principle of Properties of Nitrogen.', '{"why":"These are physical properties of nitrogen gas.","sol":"Step 1: Nitrogen is a gas at room temperature.\nStep 2: It is colourless.\nStep 3: It is also odourless and only slightly soluble in water.\nStep 4: Any two are acceptable.","steps":["Step 1: Nitrogen is a gas at room temperature.","Step 2: It is colourless.","Step 3: It is also odourless and only slightly soluble in water.","Step 4: Any two are acceptable."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_nitrogen","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Nitrogen"}', 1),
  (2443, 616, 'Why is nitrogen relatively unreactive at room temperature?', 'text', 1, 'Focus on the core principle of Properties of Nitrogen.', '{"why":"The strong nitrogen-nitrogen bond makes nitrogen relatively unreactive.","sol":"Step 1: Nitrogen molecules contain an N≡N triple bond.\nStep 2: This bond is very strong.\nStep 3: A large amount of energy is required to break it.\nStep 4: Therefore, nitrogen reacts slowly under ordinary conditions.","steps":["Step 1: Nitrogen molecules contain an N≡N triple bond.","Step 2: This bond is very strong.","Step 3: A large amount of energy is required to break it.","Step 4: Therefore, nitrogen reacts slowly under ordinary conditions."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_nitrogen","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Nitrogen"}', 2),
  (2444, 616, 'What percentage of the atmosphere is approximately nitrogen?', 'text', 1, 'Nitrogen is the largest component of air.', '{"why":"Nitrogen is the most abundant gas in Earth''s atmosphere.","sol":"Step 1: Nitrogen makes up about four-fifths of dry air.\nStep 2: Four-fifths is approximately 78%.\nStep 3: Therefore, nitrogen makes up about 78% of the atmosphere.","steps":["Step 1: Nitrogen makes up about four-fifths of dry air.","Step 2: Four-fifths is approximately 78%.","Step 3: Therefore, nitrogen makes up about 78% of the atmosphere."],"options":[],"conceptId":"chemistry_nonmetals_compounds_properties_of_nitrogen","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Properties of Nitrogen"}', 3),
  (2445, 617, 'What is the formula of ammonia?', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Ammonia contains one nitrogen atom and three hydrogen atoms.","sol":"Step 1: Ammonia contains nitrogen and hydrogen.\nStep 2: One nitrogen atom combines with three hydrogen atoms.\nStep 3: Therefore, the formula is NH₃.","steps":["Step 1: Ammonia contains nitrogen and hydrogen.","Step 2: One nitrogen atom combines with three hydrogen atoms.","Step 3: Therefore, the formula is NH₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 0),
  (2446, 617, 'Write the balanced equation for manufacture of ammonia from nitrogen and hydrogen.', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Two nitrogen atoms and six hydrogen atoms occur on both sides.","sol":"Step 1: Write N₂ + H₂ → NH₃.\nStep 2: Balance nitrogen by placing 2 before NH₃.\nStep 3: This gives six hydrogen atoms on the right.\nStep 4: Place 3 before H₂.\nStep 5: The balanced equation is N₂ + 3H₂ ⇌ 2NH₃.","steps":["Step 1: Write N₂ + H₂ → NH₃.","Step 2: Balance nitrogen by placing 2 before NH₃.","Step 3: This gives six hydrogen atoms on the right.","Step 4: Place 3 before H₂.","Step 5: The balanced equation is N₂ + 3H₂ ⇌ 2NH₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 1),
  (2447, 617, 'What happens to red litmus paper in ammonia solution?', 'text', 1, 'Focus on the core principle of Ammonia.', '{"why":"Aqueous ammonia is alkaline.","sol":"Step 1: Ammonia solution is alkaline.\nStep 2: Alkalis turn red litmus blue.\nStep 3: Therefore, red litmus turns blue.","steps":["Step 1: Ammonia solution is alkaline.","Step 2: Alkalis turn red litmus blue.","Step 3: Therefore, red litmus turns blue."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 2),
  (2448, 617, 'Why is ammonia important in agriculture?', 'text', 1, 'Think about nitrogen-containing fertilisers.', '{"why":"Ammonia provides nitrogen for producing fertilisers needed by crops.","sol":"Step 1: Plants require nitrogen for healthy growth.\nStep 2: Ammonia contains nitrogen.\nStep 3: Ammonia is used directly or indirectly in fertiliser manufacture.\nStep 4: Therefore, ammonia is important in producing nitrogen fertilisers.","steps":["Step 1: Plants require nitrogen for healthy growth.","Step 2: Ammonia contains nitrogen.","Step 3: Ammonia is used directly or indirectly in fertiliser manufacture.","Step 4: Therefore, ammonia is important in producing nitrogen fertilisers."],"options":[],"conceptId":"chemistry_nonmetals_compounds_ammonia","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Ammonia"}', 3),
  (2449, 618, 'What is the formula of the nitrate ion?', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"The nitrate ion contains one nitrogen atom and three oxygen atoms and has a −1 charge.","sol":"Step 1: Identify the nitrate ion.\nStep 2: It contains one nitrogen atom and three oxygen atoms.\nStep 3: It carries a charge of −1.\nStep 4: Therefore, the formula is NO₃⁻.","steps":["Step 1: Identify the nitrate ion.","Step 2: It contains one nitrogen atom and three oxygen atoms.","Step 3: It carries a charge of −1.","Step 4: Therefore, the formula is NO₃⁻."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 0),
  (2450, 618, 'Write the formula of sodium nitrate.', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"One Na⁺ ion balances one NO₃⁻ ion.","sol":"Step 1: Sodium forms Na⁺.\nStep 2: Nitrate forms NO₃⁻.\nStep 3: The charges are equal and opposite.\nStep 4: Combine them in a 1:1 ratio.\nStep 5: The formula is NaNO₃.","steps":["Step 1: Sodium forms Na⁺.","Step 2: Nitrate forms NO₃⁻.","Step 3: The charges are equal and opposite.","Step 4: Combine them in a 1:1 ratio.","Step 5: The formula is NaNO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 1),
  (2451, 618, 'Write the formula of potassium nitrate.', 'text', 1, 'Focus on the core principle of Nitrogen Compounds.', '{"why":"One K⁺ ion balances one NO₃⁻ ion.","sol":"Step 1: Potassium forms K⁺.\nStep 2: Nitrate forms NO₃⁻.\nStep 3: A 1:1 ratio gives a neutral compound.\nStep 4: The formula is KNO₃.","steps":["Step 1: Potassium forms K⁺.","Step 2: Nitrate forms NO₃⁻.","Step 3: A 1:1 ratio gives a neutral compound.","Step 4: The formula is KNO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 2),
  (2452, 618, 'What is the formula of nitric acid?', 'text', 1, 'Nitric acid contains hydrogen and the nitrate group.', '{"why":"One H⁺ ion combines with one NO₃⁻ ion to form nitric acid.","sol":"Step 1: Hydrogen forms H⁺.\nStep 2: Nitrate is NO₃⁻.\nStep 3: Combine them in a 1:1 ratio.\nStep 4: The formula is HNO₃.","steps":["Step 1: Hydrogen forms H⁺.","Step 2: Nitrate is NO₃⁻.","Step 3: Combine them in a 1:1 ratio.","Step 4: The formula is HNO₃."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_compounds","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Compounds"}', 3),
  (2453, 619, 'What is nitrogen fixation?', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Nitrogen fixation makes atmospheric nitrogen available in forms that can enter biological processes.","sol":"Step 1: Atmospheric nitrogen exists mainly as N₂.\nStep 2: Most plants cannot use atmospheric nitrogen directly.\nStep 3: Nitrogen fixation converts atmospheric nitrogen into nitrogen compounds that can enter the biological nitrogen cycle.","steps":["Step 1: Atmospheric nitrogen exists mainly as N₂.","Step 2: Most plants cannot use atmospheric nitrogen directly.","Step 3: Nitrogen fixation converts atmospheric nitrogen into nitrogen compounds that can enter the biological nitrogen cycle."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q1","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 0),
  (2454, 619, 'What is nitrification?', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Nitrifying bacteria convert reduced nitrogen compounds into nitrates that plants can absorb.","sol":"Step 1: Nitrogen-containing compounds in soil can be converted by microorganisms.\nStep 2: Ammonium compounds are converted into nitrites.\nStep 3: Nitrites are then converted into nitrates.\nStep 4: This process is called nitrification.","steps":["Step 1: Nitrogen-containing compounds in soil can be converted by microorganisms.","Step 2: Ammonium compounds are converted into nitrites.","Step 3: Nitrites are then converted into nitrates.","Step 4: This process is called nitrification."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q2","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 1),
  (2455, 619, 'What is denitrification?', 'text', 1, 'Focus on the core principle of Nitrogen Cycle.', '{"why":"Denitrification returns nitrogen from soil to the atmosphere.","sol":"Step 1: Nitrates are present in soil.\nStep 2: Certain bacteria convert nitrates into nitrogen gas.\nStep 3: Nitrogen gas returns to the atmosphere.\nStep 4: This process is called denitrification.","steps":["Step 1: Nitrates are present in soil.","Step 2: Certain bacteria convert nitrates into nitrogen gas.","Step 3: Nitrogen gas returns to the atmosphere.","Step 4: This process is called denitrification."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q3","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 2),
  (2456, 619, 'Why is the nitrogen cycle important to plants?', 'text', 1, 'Think about what plants use nitrogen to make.', '{"why":"Nitrogen is an essential nutrient for plants.","sol":"Step 1: Plants need nitrogen for growth.\nStep 2: Nitrogen is required to make proteins and other important compounds.\nStep 3: The nitrogen cycle supplies nitrogen to soil in usable forms.\nStep 4: Plants can absorb nitrogen compounds such as nitrates.","steps":["Step 1: Plants need nitrogen for growth.","Step 2: Nitrogen is required to make proteins and other important compounds.","Step 3: The nitrogen cycle supplies nitrogen to soil in usable forms.","Step 4: Plants can absorb nitrogen compounds such as nitrates."],"options":[],"conceptId":"chemistry_nonmetals_compounds_nitrogen_cycle","skillId":"chemistry_nonmetals_compounds","subskillId":"chemistry_nonmetals_compounds_q4","subject":"chemistry","chapter":"nonmetals_compounds","topic":"Nitrogen Cycle"}', 3),
  (2457, 620, 'What is air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Its components retain their individual properties and are not chemically combined.","sol":"Step 1: Air contains several different gases.\nStep 2: These gases are not chemically bonded together.\nStep 3: Therefore, air is a mixture of gases.","steps":["Step 1: Air contains several different gases.","Step 2: These gases are not chemically bonded together.","Step 3: Therefore, air is a mixture of gases."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 0),
  (2458, 620, 'Approximately what volume of oxygen is present in 200 dm³ of dry air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Oxygen occupies approximately 21% of dry air.","sol":"Step 1: Oxygen makes up approximately 21% of dry air.\nStep 2: Calculate 21% of 200 dm³.\nStep 3: 21/100 × 200 = 42 dm³.","steps":["Step 1: Oxygen makes up approximately 21% of dry air.","Step 2: Calculate 21% of 200 dm³.","Step 3: 21/100 × 200 = 42 dm³."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 1),
  (2459, 620, 'Which gas is the largest component of air?', 'text', 1, 'Focus on the core principle of Composition of Air.', '{"why":"Nitrogen makes up about 78% of dry air.","sol":"Step 1: Compare the approximate percentages of the major gases.\nStep 2: Nitrogen is about 78%, while oxygen is about 21%.\nStep 3: Therefore, nitrogen is the largest component.","steps":["Step 1: Compare the approximate percentages of the major gases.","Step 2: Nitrogen is about 78%, while oxygen is about 21%.","Step 3: Therefore, nitrogen is the largest component."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 2),
  (2460, 620, 'A student says that air is a compound because it contains oxygen and nitrogen. Is the student correct?', 'text', 1, 'Think about whether the gases are chemically bonded.', '{"why":"The components of a mixture are not chemically bonded.","sol":"Step 1: Air contains several gases.\nStep 2: The gases are not chemically bonded together.\nStep 3: Therefore, air is a mixture.","steps":["Step 1: Air contains several gases.","Step 2: The gases are not chemically bonded together.","Step 3: Therefore, air is a mixture."],"options":[],"conceptId":"chemistry_air_water_environment_composition_of_air","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Composition of Air"}', 3),
  (2461, 621, 'State two physical properties of oxygen.', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"These are observable physical properties of oxygen.","sol":"Step 1: Consider how oxygen appears and behaves physically.\nStep 2: Oxygen is colourless.\nStep 3: Oxygen is odourless.","steps":["Step 1: Consider how oxygen appears and behaves physically.","Step 2: Oxygen is colourless.","Step 3: Oxygen is odourless."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 0),
  (2462, 621, 'What happens when a glowing splint is introduced into oxygen?', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"Oxygen supports combustion.","sol":"Step 1: Oxygen supports combustion.\nStep 2: A glowing splint needs oxygen to continue burning.\nStep 3: In oxygen, the splint relights.","steps":["Step 1: Oxygen supports combustion.","Step 2: A glowing splint needs oxygen to continue burning.","Step 3: In oxygen, the splint relights."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 1),
  (2463, 621, 'Write the equation for the complete combustion of carbon in oxygen.', 'text', 1, 'Focus on the core principle of Properties of Oxygen.', '{"why":"One carbon atom reacts with one oxygen molecule to form one carbon dioxide molecule.","sol":"Step 1: The reactants are carbon and oxygen.\nStep 2: Carbon combines with oxygen to form carbon dioxide.\nStep 3: Write the balanced equation: C + O₂ → CO₂.","steps":["Step 1: The reactants are carbon and oxygen.","Step 2: Carbon combines with oxygen to form carbon dioxide.","Step 3: Write the balanced equation: C + O₂ → CO₂."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 2),
  (2464, 621, 'A gas relights a glowing splint. Identify the gas.', 'text', 1, 'Think about the gas that supports combustion.', '{"why":"Oxygen supports combustion and relights a glowing splint.","sol":"Step 1: Relighting a glowing splint is the test for oxygen.\nStep 2: Therefore, the gas is oxygen.","steps":["Step 1: Relighting a glowing splint is the test for oxygen.","Step 2: Therefore, the gas is oxygen."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Oxygen"}', 3),
  (2465, 622, 'Why is oxygen used in hospitals?', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"Oxygen is required for aerobic respiration.","sol":"Step 1: Human cells require oxygen for aerobic respiration.\nStep 2: Some patients cannot obtain enough oxygen through normal breathing.\nStep 3: Oxygen can therefore be supplied to them.","steps":["Step 1: Human cells require oxygen for aerobic respiration.","Step 2: Some patients cannot obtain enough oxygen through normal breathing.","Step 3: Oxygen can therefore be supplied to them."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 0),
  (2466, 622, 'Why is oxygen useful in welding?', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"The high-temperature flame is useful for cutting and welding metals.","sol":"Step 1: Oxygen supports combustion.\nStep 2: A fuel burning in oxygen can produce a very hot flame.\nStep 3: The hot flame can melt or cut metals.","steps":["Step 1: Oxygen supports combustion.","Step 2: A fuel burning in oxygen can produce a very hot flame.","Step 3: The hot flame can melt or cut metals."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 1),
  (2467, 622, 'State two uses of oxygen.', 'text', 1, 'Focus on the core principle of Uses of Oxygen.', '{"why":"Both uses depend on oxygen''s ability to support respiration or combustion.","sol":"Step 1: Oxygen is required for respiration.\nStep 2: Oxygen also supports combustion.\nStep 3: Therefore, examples include medical respiration and welding.","steps":["Step 1: Oxygen is required for respiration.","Step 2: Oxygen also supports combustion.","Step 3: Therefore, examples include medical respiration and welding."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 2),
  (2468, 622, 'Why would oxygen be useful for a patient having difficulty obtaining enough oxygen from air?', 'text', 1, 'Think about the role of oxygen in respiration.', '{"why":"Cells need oxygen to release energy efficiently through aerobic respiration.","sol":"Step 1: Cells require oxygen for aerobic respiration.\nStep 2: Supplying oxygen increases the amount available for respiration.\nStep 3: Therefore, oxygen can support the patient''s respiratory needs.","steps":["Step 1: Cells require oxygen for aerobic respiration.","Step 2: Supplying oxygen increases the amount available for respiration.","Step 3: Therefore, oxygen can support the patient''s respiratory needs."],"options":[],"conceptId":"chemistry_air_water_environment_uses_of_oxygen","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Uses of Oxygen"}', 3),
  (2469, 623, 'What is the chemical formula of water?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"Each water molecule contains two hydrogen atoms and one oxygen atom.","sol":"Step 1: Water contains hydrogen and oxygen.\nStep 2: Two hydrogen atoms combine with one oxygen atom.\nStep 3: Therefore, the formula is H₂O.","steps":["Step 1: Water contains hydrogen and oxygen.","Step 2: Two hydrogen atoms combine with one oxygen atom.","Step 3: Therefore, the formula is H₂O."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 0),
  (2470, 623, 'At what temperature does pure water boil at standard atmospheric pressure?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"100°C is the standard boiling point of pure water at normal atmospheric pressure.","sol":"Step 1: Recall the standard boiling point of water.\nStep 2: Pure water boils at 100°C at standard atmospheric pressure.","steps":["Step 1: Recall the standard boiling point of water.","Step 2: Pure water boils at 100°C at standard atmospheric pressure."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 1),
  (2471, 623, 'At what temperature does pure water freeze at standard atmospheric pressure?', 'text', 1, 'Focus on the core principle of Properties of Water.', '{"why":"0°C is the standard freezing point of pure water.","sol":"Step 1: Recall the standard freezing point of water.\nStep 2: Pure water freezes at 0°C.","steps":["Step 1: Recall the standard freezing point of water.","Step 2: Pure water freezes at 0°C."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 2),
  (2472, 623, 'A learner says water is a mixture because it contains hydrogen and oxygen. Correct the statement.', 'text', 1, 'Ask whether hydrogen and oxygen are chemically bonded.', '{"why":"Compounds contain elements chemically combined in definite proportions.","sol":"Step 1: Hydrogen and oxygen are chemically bonded in water.\nStep 2: They occur in a fixed ratio of 2:1.\nStep 3: Therefore, water is a compound.","steps":["Step 1: Hydrogen and oxygen are chemically bonded in water.","Step 2: They occur in a fixed ratio of 2:1.","Step 3: Therefore, water is a compound."],"options":[],"conceptId":"chemistry_air_water_environment_properties_of_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Properties of Water"}', 3),
  (2473, 624, 'What is a solvent?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"The solvent provides the medium in which the solute dissolves.","sol":"Step 1: A solution contains a solvent and one or more solutes.\nStep 2: The solvent is the substance that dissolves the solute.\nStep 3: Therefore, a solvent is the substance that dissolves a solute.","steps":["Step 1: A solution contains a solvent and one or more solutes.","Step 2: The solvent is the substance that dissolves the solute.","Step 3: Therefore, a solvent is the substance that dissolves a solute."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 0),
  (2474, 624, 'What happens when sodium chloride dissolves in water?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"Water can separate ionic particles and keep them dispersed in solution.","sol":"Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.\nStep 2: Water separates and surrounds the ions.\nStep 3: The ions become dispersed in the water.","steps":["Step 1: Sodium chloride contains Na⁺ and Cl⁻ ions.","Step 2: Water separates and surrounds the ions.","Step 3: The ions become dispersed in the water."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 1),
  (2475, 624, 'Why is water important for transporting dissolved substances in living organisms?', 'text', 1, 'Focus on the core principle of Water as a Solvent.', '{"why":"Dissolved particles can move through aqueous fluids.","sol":"Step 1: Water dissolves many substances.\nStep 2: Dissolved substances can move with the water.\nStep 3: Therefore, water can transport substances through organisms.","steps":["Step 1: Water dissolves many substances.","Step 2: Dissolved substances can move with the water.","Step 3: Therefore, water can transport substances through organisms."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 2),
  (2476, 624, 'Salt disappears when added to water. Has the salt necessarily been destroyed?', 'text', 1, 'Think about what dissolving means.', '{"why":"Dissolving is a physical process; the substance remains present in the solution.","sol":"Step 1: Salt particles become separated and dispersed in water.\nStep 2: The particles are still present in the solution.\nStep 3: Therefore, the salt has dissolved rather than been destroyed.","steps":["Step 1: Salt particles become separated and dispersed in water.","Step 2: The particles are still present in the solution.","Step 3: Therefore, the salt has dissolved rather than been destroyed."],"options":[],"conceptId":"chemistry_air_water_environment_water_as_a_solvent","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Water as a Solvent"}', 3),
  (2477, 625, 'What makes water hard?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"These ions cause the characteristic reactions of hard water.","sol":"Step 1: Hard water contains dissolved mineral ions.\nStep 2: The important ions are mainly calcium and magnesium ions.\nStep 3: Therefore, dissolved calcium and magnesium ions cause hardness.","steps":["Step 1: Hard water contains dissolved mineral ions.","Step 2: The important ions are mainly calcium and magnesium ions.","Step 3: Therefore, dissolved calcium and magnesium ions cause hardness."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 0),
  (2478, 625, 'Why does hard water form scum with soap?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"The insoluble calcium or magnesium soap removes soap from solution.","sol":"Step 1: Hard water contains Ca²⁺ and/or Mg²⁺ ions.\nStep 2: These ions react with soap anions.\nStep 3: An insoluble substance called scum is formed.","steps":["Step 1: Hard water contains Ca²⁺ and/or Mg²⁺ ions.","Step 2: These ions react with soap anions.","Step 3: An insoluble substance called scum is formed."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 1),
  (2479, 625, 'Why is more soap needed when washing with hard water?', 'text', 1, 'Focus on the core principle of Hard Water.', '{"why":"The calcium and magnesium ions reduce the amount of soap available to form lather.","sol":"Step 1: Some soap reacts with calcium and magnesium ions.\nStep 2: This produces scum instead of useful lather.\nStep 3: More soap is therefore needed to produce sufficient lather.","steps":["Step 1: Some soap reacts with calcium and magnesium ions.","Step 2: This produces scum instead of useful lather.","Step 3: More soap is therefore needed to produce sufficient lather."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 2),
  (2480, 625, 'A learner adds soap to hard water and obtains little lather. What is the likely reason?', 'text', 1, 'Think about calcium and magnesium ions.', '{"why":"This is the characteristic behaviour of hard water.","sol":"Step 1: Hard water contains calcium and magnesium ions.\nStep 2: These ions react with soap.\nStep 3: The reaction forms scum and reduces lather.","steps":["Step 1: Hard water contains calcium and magnesium ions.","Step 2: These ions react with soap.","Step 3: The reaction forms scum and reduces lather."],"options":[],"conceptId":"chemistry_air_water_environment_hard_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Hard Water"}', 3),
  (2481, 626, 'What is soft water?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"The low concentration of hardness-causing ions means little soap is lost as scum.","sol":"Step 1: Compare its calcium and magnesium ion content with hard water.\nStep 2: Soft water contains little calcium and magnesium ions.\nStep 3: Therefore, it lathers easily with soap.","steps":["Step 1: Compare its calcium and magnesium ion content with hard water.","Step 2: Soft water contains little calcium and magnesium ions.","Step 3: Therefore, it lathers easily with soap."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 0),
  (2482, 626, 'What happens when soap is added to soft water?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"There are few calcium and magnesium ions to react with the soap.","sol":"Step 1: Soft water has little calcium and magnesium.\nStep 2: Little soap is converted into insoluble scum.\nStep 3: Therefore, soap forms lather easily.","steps":["Step 1: Soft water has little calcium and magnesium.","Step 2: Little soap is converted into insoluble scum.","Step 3: Therefore, soap forms lather easily."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 1),
  (2483, 626, 'Which type of water is generally preferred for washing with soap: hard or soft?', 'text', 1, 'Focus on the core principle of Soft Water.', '{"why":"Soft water allows soap to form lather without significant scum formation.","sol":"Step 1: Washing requires soap to produce lather.\nStep 2: Soft water allows soap to lather readily.\nStep 3: Therefore, soft water is preferred.","steps":["Step 1: Washing requires soap to produce lather.","Step 2: Soft water allows soap to lather readily.","Step 3: Therefore, soft water is preferred."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 2),
  (2484, 626, 'Water produces abundant lather with only a small amount of soap. Is it likely to be hard or soft?', 'text', 1, 'Hard water wastes some soap as scum.', '{"why":"Easy lathering with little soap indicates low hardness.","sol":"Step 1: Hard water reacts with soap and forms scum.\nStep 2: Soft water allows soap to lather easily.\nStep 3: Therefore, the water is likely soft.","steps":["Step 1: Hard water reacts with soap and forms scum.","Step 2: Soft water allows soap to lather easily.","Step 3: Therefore, the water is likely soft."],"options":[],"conceptId":"chemistry_air_water_environment_soft_water","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Soft Water"}', 3),
  (2485, 627, 'What is the purpose of filtration during water purification?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"The filter traps solid particles while water passes through.","sol":"Step 1: Identify the type of impurity filtration removes.\nStep 2: Filtration separates insoluble solid particles from a liquid.\nStep 3: Therefore, filtration removes suspended insoluble particles.","steps":["Step 1: Identify the type of impurity filtration removes.","Step 2: Filtration separates insoluble solid particles from a liquid.","Step 3: Therefore, filtration removes suspended insoluble particles."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 0),
  (2486, 627, 'Why is water boiled during purification?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"High temperature damages and kills many microorganisms.","sol":"Step 1: Contaminated water may contain harmful microorganisms.\nStep 2: Heating water to boiling temperature kills many microorganisms.\nStep 3: Therefore, boiling helps make water safer.","steps":["Step 1: Contaminated water may contain harmful microorganisms.","Step 2: Heating water to boiling temperature kills many microorganisms.","Step 3: Therefore, boiling helps make water safer."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 1),
  (2487, 627, 'What is the main purpose of chlorination?', 'text', 1, 'Focus on the core principle of Water Purification.', '{"why":"Chlorine is an effective water disinfectant.","sol":"Step 1: Chlorine is added to water in controlled amounts.\nStep 2: Chlorine acts as a disinfectant.\nStep 3: It destroys or inactivates many microorganisms.","steps":["Step 1: Chlorine is added to water in controlled amounts.","Step 2: Chlorine acts as a disinfectant.","Step 3: It destroys or inactivates many microorganisms."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 2),
  (2488, 627, 'A water sample contains mud particles. Which purification process should be used first?', 'text', 1, 'Think about separating insoluble solids from a liquid.', '{"why":"Filtration removes suspended insoluble particles such as mud.","sol":"Step 1: Mud is an insoluble solid.\nStep 2: Filtration separates insoluble solids from liquids.\nStep 3: Therefore, filtration is appropriate.","steps":["Step 1: Mud is an insoluble solid.","Step 2: Filtration separates insoluble solids from liquids.","Step 3: Therefore, filtration is appropriate."],"options":[],"conceptId":"chemistry_air_water_environment_water_purification","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Water Purification"}', 3),
  (2489, 628, 'How is carbon monoxide formed?', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Insufficient oxygen prevents complete conversion of carbon to carbon dioxide.","sol":"Step 1: Carbon-containing fuels require oxygen for combustion.\nStep 2: If the oxygen supply is insufficient, combustion may be incomplete.\nStep 3: Incomplete combustion can produce carbon monoxide.","steps":["Step 1: Carbon-containing fuels require oxygen for combustion.","Step 2: If the oxygen supply is insufficient, combustion may be incomplete.","Step 3: Incomplete combustion can produce carbon monoxide."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 0),
  (2490, 628, 'Write an equation showing formation of carbon monoxide from carbon.', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Two carbon atoms combine with one oxygen molecule to produce two carbon monoxide molecules.","sol":"Step 1: The reactants are carbon and oxygen.\nStep 2: Limited oxygen produces carbon monoxide.\nStep 3: Balance the equation: 2C + O₂ → 2CO.","steps":["Step 1: The reactants are carbon and oxygen.","Step 2: Limited oxygen produces carbon monoxide.","Step 3: Balance the equation: 2C + O₂ → 2CO."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 1),
  (2491, 628, 'Why is carbon monoxide poisonous?', 'text', 1, 'Focus on the core principle of Carbon Monoxide as an Air Pollutant.', '{"why":"Reduced oxygen transport can deprive body tissues of oxygen.","sol":"Step 1: Carbon monoxide enters the bloodstream through the lungs.\nStep 2: It binds strongly to haemoglobin.\nStep 3: This reduces the blood''s ability to transport oxygen.","steps":["Step 1: Carbon monoxide enters the bloodstream through the lungs.","Step 2: It binds strongly to haemoglobin.","Step 3: This reduces the blood''s ability to transport oxygen."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 2),
  (2492, 628, 'Why is burning charcoal inside a poorly ventilated room dangerous?', 'text', 1, 'Consider incomplete combustion and the gas produced.', '{"why":"Poor ventilation limits oxygen and prevents CO from being safely dispersed.","sol":"Step 1: Charcoal contains carbon.\nStep 2: Limited oxygen can cause incomplete combustion.\nStep 3: Carbon monoxide can therefore accumulate in the room.","steps":["Step 1: Charcoal contains carbon.","Step 2: Limited oxygen can cause incomplete combustion.","Step 3: Carbon monoxide can therefore accumulate in the room."],"options":[],"conceptId":"chemistry_air_water_environment_carbon_monoxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Carbon Monoxide as an Air Pollutant"}', 3),
  (2493, 629, 'How is sulphur dioxide formed during combustion?', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"Sulphur combines with oxygen during combustion.","sol":"Step 1: Sulphur-containing material is burned.\nStep 2: Sulphur reacts with oxygen.\nStep 3: Sulphur dioxide is produced.","steps":["Step 1: Sulphur-containing material is burned.","Step 2: Sulphur reacts with oxygen.","Step 3: Sulphur dioxide is produced."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 0),
  (2494, 629, 'Write the equation for combustion of sulphur in oxygen.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"One sulphur atom combines with one oxygen molecule to form sulphur dioxide.","sol":"Step 1: Sulphur is the reactant.\nStep 2: Oxygen is the other reactant.\nStep 3: The product is sulphur dioxide.","steps":["Step 1: Sulphur is the reactant.","Step 2: Oxygen is the other reactant.","Step 3: The product is sulphur dioxide."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 1),
  (2495, 629, 'State two environmental effects of sulphur dioxide.', 'text', 1, 'Focus on the core principle of Sulphur Dioxide as an Air Pollutant.', '{"why":"Sulphur dioxide is an acidic air pollutant.","sol":"Step 1: SO₂ can react with atmospheric water.\nStep 2: This contributes to acidic precipitation.\nStep 3: SO₂ can also damage vegetation and materials.","steps":["Step 1: SO₂ can react with atmospheric water.","Step 2: This contributes to acidic precipitation.","Step 3: SO₂ can also damage vegetation and materials."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 2),
  (2496, 629, 'A factory burns sulphur-containing fuel and releases SO₂. Name one environmental problem that may result.', 'text', 1, 'Think about acidic precipitation.', '{"why":"Sulphur dioxide is an important contributor to acid rain.","sol":"Step 1: SO₂ enters the atmosphere.\nStep 2: It can participate in reactions that produce acidic substances.\nStep 3: These contribute to acid rain.","steps":["Step 1: SO₂ enters the atmosphere.","Step 2: It can participate in reactions that produce acidic substances.","Step 3: These contribute to acid rain."],"options":[],"conceptId":"chemistry_air_water_environment_sulphur_dioxide_as_an_air_pollutant","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Sulphur Dioxide as an Air Pollutant"}', 3),
  (2497, 630, 'What are nitrogen oxides?', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"NO and NO₂ are common nitrogen oxides produced during high-temperature combustion.","sol":"Step 1: Nitrogen oxides are compounds containing nitrogen and oxygen.\nStep 2: Common examples include NO and NO₂.\nStep 3: These gases are collectively referred to as NOₓ.","steps":["Step 1: Nitrogen oxides are compounds containing nitrogen and oxygen.","Step 2: Common examples include NO and NO₂.","Step 3: These gases are collectively referred to as NOₓ."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 0),
  (2498, 630, 'Where are nitrogen oxides commonly produced?', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"High temperatures promote reactions between nitrogen and oxygen.","sol":"Step 1: Nitrogen and oxygen can react at very high temperatures.\nStep 2: Vehicle engines reach high temperatures during combustion.\nStep 3: Industrial combustion can also produce these gases.","steps":["Step 1: Nitrogen and oxygen can react at very high temperatures.","Step 2: Vehicle engines reach high temperatures during combustion.","Step 3: Industrial combustion can also produce these gases."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 1),
  (2499, 630, 'State one environmental effect of nitrogen oxides.', 'text', 1, 'Focus on the core principle of Nitrogen Oxides as Air Pollutants.', '{"why":"Nitrogen oxides can form acidic substances in the atmosphere.","sol":"Step 1: Nitrogen oxides can undergo atmospheric reactions.\nStep 2: Some of the products contribute to acidic precipitation.\nStep 3: Therefore, nitrogen oxides contribute to acid rain.","steps":["Step 1: Nitrogen oxides can undergo atmospheric reactions.","Step 2: Some of the products contribute to acidic precipitation.","Step 3: Therefore, nitrogen oxides contribute to acid rain."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 2),
  (2500, 630, 'Why are vehicle engines a source of nitrogen oxides?', 'text', 1, 'Think about the temperature inside an engine.', '{"why":"High-temperature combustion promotes NOₓ formation.","sol":"Step 1: Engines burn fuel at high temperatures.\nStep 2: At high temperatures, nitrogen and oxygen from air can react.\nStep 3: Nitrogen oxides can therefore form.","steps":["Step 1: Engines burn fuel at high temperatures.","Step 2: At high temperatures, nitrogen and oxygen from air can react.","Step 3: Nitrogen oxides can therefore form."],"options":[],"conceptId":"chemistry_air_water_environment_nitrogen_oxides_as_air_pollutants","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Nitrogen Oxides as Air Pollutants"}', 3);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2501, 631, 'What is particulate matter?', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Particulate pollution consists of suspended particles rather than gaseous pollutants.","sol":"Step 1: Particulate matter is not a single gas.\nStep 2: It consists of tiny solid particles or liquid droplets.\nStep 3: These particles remain suspended in air.","steps":["Step 1: Particulate matter is not a single gas.","Step 2: It consists of tiny solid particles or liquid droplets.","Step 3: These particles remain suspended in air."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 0),
  (2502, 631, 'Give two sources of particulate matter.', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Combustion processes can release smoke and fine particles.","sol":"Step 1: Consider processes that release tiny particles into air.\nStep 2: Vehicle exhaust can release particles.\nStep 3: Burning biomass or waste can also release particles.","steps":["Step 1: Consider processes that release tiny particles into air.","Step 2: Vehicle exhaust can release particles.","Step 3: Burning biomass or waste can also release particles."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 1),
  (2503, 631, 'Why can fine particulate matter be harmful to humans?', 'text', 1, 'Focus on the core principle of Particulate Matter.', '{"why":"Small particles can penetrate further into the lungs.","sol":"Step 1: Very small particles can be inhaled.\nStep 2: Some can travel deep into the respiratory system.\nStep 3: This can damage or irritate respiratory tissues.","steps":["Step 1: Very small particles can be inhaled.","Step 2: Some can travel deep into the respiratory system.","Step 3: This can damage or irritate respiratory tissues."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 2),
  (2504, 631, 'A town experiences heavy smoke from burning waste. Which type of air pollutant is likely to increase?', 'text', 1, 'Think about the tiny particles found in smoke.', '{"why":"Smoke from combustion can contain many fine suspended particles.","sol":"Step 1: Burning waste produces smoke.\nStep 2: Smoke contains suspended particles.\nStep 3: These particles contribute to particulate matter pollution.","steps":["Step 1: Burning waste produces smoke.","Step 2: Smoke contains suspended particles.","Step 3: These particles contribute to particulate matter pollution."],"options":[],"conceptId":"chemistry_air_water_environment_particulate_matter","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Particulate Matter"}', 3),
  (2505, 632, 'What is acid rain?', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"SO₂ and NOₓ contribute to the formation of acids in atmospheric moisture.","sol":"Step 1: Certain gases enter the atmosphere.\nStep 2: Sulphur dioxide and nitrogen oxides form acidic substances through atmospheric reactions.\nStep 3: These acidic substances dissolve in precipitation.","steps":["Step 1: Certain gases enter the atmosphere.","Step 2: Sulphur dioxide and nitrogen oxides form acidic substances through atmospheric reactions.","Step 3: These acidic substances dissolve in precipitation."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 0),
  (2506, 632, 'Name two gases that contribute to acid rain.', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"Both pollutants can form acidic substances in the atmosphere.","sol":"Step 1: Identify the major acidic air pollutants involved.\nStep 2: Sulphur dioxide contributes to acid formation.\nStep 3: Nitrogen oxides also contribute.","steps":["Step 1: Identify the major acidic air pollutants involved.","Step 2: Sulphur dioxide contributes to acid formation.","Step 3: Nitrogen oxides also contribute."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 1),
  (2507, 632, 'How can acid rain damage limestone buildings?', 'text', 1, 'Focus on the core principle of Acid Rain.', '{"why":"Acids react with carbonates, causing limestone to wear away.","sol":"Step 1: Limestone contains calcium carbonate.\nStep 2: Acids react with carbonates.\nStep 3: The reaction can dissolve or erode the limestone.","steps":["Step 1: Limestone contains calcium carbonate.","Step 2: Acids react with carbonates.","Step 3: The reaction can dissolve or erode the limestone."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 2),
  (2508, 632, 'A power station reduces its SO₂ emissions. How could this help the environment?', 'text', 1, 'Think about one major consequence of SO₂ pollution.', '{"why":"Sulphur dioxide is a major contributor to acid rain.","sol":"Step 1: SO₂ contributes to acid rain.\nStep 2: Reducing SO₂ reduces the amount available for atmospheric acid formation.\nStep 3: Therefore, acid rain can be reduced.","steps":["Step 1: SO₂ contributes to acid rain.","Step 2: Reducing SO₂ reduces the amount available for atmospheric acid formation.","Step 3: Therefore, acid rain can be reduced."],"options":[],"conceptId":"chemistry_air_water_environment_acid_rain","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Acid Rain"}', 3),
  (2509, 633, 'What is the greenhouse effect?', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Greenhouse gases reduce the rate at which some heat escapes to space.","sol":"Step 1: The Earth''s surface absorbs energy from the Sun.\nStep 2: The surface emits infrared radiation.\nStep 3: Greenhouse gases absorb and re-emit some of this radiation.\nStep 4: This contributes to warming of the lower atmosphere and surface.","steps":["Step 1: The Earth''s surface absorbs energy from the Sun.","Step 2: The surface emits infrared radiation.","Step 3: Greenhouse gases absorb and re-emit some of this radiation.","Step 4: This contributes to warming of the lower atmosphere and surface."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 0),
  (2510, 633, 'Name two greenhouse gases.', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Both gases contribute to the greenhouse effect.","sol":"Step 1: Recall gases that absorb infrared radiation.\nStep 2: Carbon dioxide is a greenhouse gas.\nStep 3: Methane is also a greenhouse gas.","steps":["Step 1: Recall gases that absorb infrared radiation.","Step 2: Carbon dioxide is a greenhouse gas.","Step 3: Methane is also a greenhouse gas."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 1),
  (2511, 633, 'Why can burning fossil fuels increase the greenhouse effect?', 'text', 1, 'Focus on the core principle of Greenhouse Effect.', '{"why":"Carbon dioxide absorbs infrared radiation and contributes to the greenhouse effect.","sol":"Step 1: Fossil fuels contain carbon.\nStep 2: Complete combustion produces carbon dioxide.\nStep 3: Increased atmospheric CO₂ strengthens the greenhouse effect.","steps":["Step 1: Fossil fuels contain carbon.","Step 2: Complete combustion produces carbon dioxide.","Step 3: Increased atmospheric CO₂ strengthens the greenhouse effect."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 2),
  (2512, 633, 'A country increases its use of coal for electricity generation. What greenhouse gas is likely to increase significantly?', 'text', 1, 'Think about the product of complete combustion of carbon.', '{"why":"Combustion of carbon-containing fossil fuels releases carbon dioxide.","sol":"Step 1: Coal contains carbon.\nStep 2: Carbon burns in oxygen to produce carbon dioxide.\nStep 3: Therefore, burning more coal can increase CO₂ emissions.","steps":["Step 1: Coal contains carbon.","Step 2: Carbon burns in oxygen to produce carbon dioxide.","Step 3: Therefore, burning more coal can increase CO₂ emissions."],"options":[],"conceptId":"chemistry_air_water_environment_greenhouse_effect","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Greenhouse Effect"}', 3),
  (2513, 634, 'State two methods of reducing air pollution.', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Both measures reduce the amount of pollutants released into the air.","sol":"Step 1: Air pollution is reduced by preventing pollutants from entering the atmosphere.\nStep 2: Cleaner fuels can reduce some emissions.\nStep 3: Reducing open burning can reduce smoke and particulate matter.","steps":["Step 1: Air pollution is reduced by preventing pollutants from entering the atmosphere.","Step 2: Cleaner fuels can reduce some emissions.","Step 3: Reducing open burning can reduce smoke and particulate matter."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q1","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 0),
  (2514, 634, 'Why should sewage be treated before being discharged into rivers?', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Untreated sewage can cause water pollution and harm aquatic ecosystems and human health.","sol":"Step 1: Untreated sewage can contain microorganisms and organic waste.\nStep 2: Discharging it directly can contaminate water.\nStep 3: Treatment removes or reduces harmful contaminants before discharge.","steps":["Step 1: Untreated sewage can contain microorganisms and organic waste.","Step 2: Discharging it directly can contaminate water.","Step 3: Treatment removes or reduces harmful contaminants before discharge."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q2","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 1),
  (2515, 634, 'What does sustainable use of resources mean?', 'text', 1, 'Focus on the core principle of Pollution Control.', '{"why":"Sustainability balances present use with long-term environmental protection.","sol":"Step 1: Natural resources are limited or can be damaged by excessive use.\nStep 2: Resources should therefore be used efficiently.\nStep 3: The aim is to meet present needs while protecting resources for the future.","steps":["Step 1: Natural resources are limited or can be damaged by excessive use.","Step 2: Resources should therefore be used efficiently.","Step 3: The aim is to meet present needs while protecting resources for the future."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q3","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 2),
  (2516, 634, 'A factory releases untreated wastewater directly into a river. Give one action that could reduce the pollution.', 'text', 1, 'Think about what should happen to wastewater before discharge.', '{"why":"Wastewater treatment reduces pollutants entering water bodies.","sol":"Step 1: The wastewater contains pollutants.\nStep 2: It should be treated before entering the river.\nStep 3: Treatment removes or reduces harmful substances.","steps":["Step 1: The wastewater contains pollutants.","Step 2: It should be treated before entering the river.","Step 3: Treatment removes or reduces harmful substances."],"options":[],"conceptId":"chemistry_air_water_environment_pollution_control","skillId":"chemistry_air_water_environment","subskillId":"chemistry_air_water_environment_q4","subject":"chemistry","chapter":"air_water_environment","topic":"Pollution Control"}', 3),
  (2517, 635, 'Which ion is being tested for when ammonia gas is produced after warming a sample with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"Ammonium ions react with hydroxide ions to release ammonia gas.","sol":"Step 1: Ammonia is NH₃.\nStep 2: Ammonia can be produced from ammonium ions when an alkali is added.\nStep 3: Therefore, the ion being tested is NH₄⁺.","steps":["Step 1: Ammonia is NH₃.","Step 2: Ammonia can be produced from ammonium ions when an alkali is added.","Step 3: Therefore, the ion being tested is NH₄⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 0),
  (2518, 635, 'What happens to damp red litmus paper in the presence of ammonia gas?', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"Ammonia produces an alkaline solution in water.","sol":"Step 1: Ammonia dissolves in the moisture on the litmus paper.\nStep 2: The resulting solution is alkaline.\nStep 3: Alkaline substances turn red litmus blue.","steps":["Step 1: Ammonia dissolves in the moisture on the litmus paper.","Step 2: The resulting solution is alkaline.","Step 3: Alkaline substances turn red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 1),
  (2519, 635, 'Write the ionic equation for the reaction between ammonium ions and hydroxide ions.', 'text', 1, 'Focus on the core principle of Test for Ammonium Ions.', '{"why":"The reaction releases ammonia gas from ammonium ions.","sol":"Step 1: The reactants are NH₄⁺ and OH⁻.\nStep 2: Ammonium ions react with hydroxide ions.\nStep 3: The products are ammonia and water.","steps":["Step 1: The reactants are NH₄⁺ and OH⁻.","Step 2: Ammonium ions react with hydroxide ions.","Step 3: The products are ammonia and water."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 2),
  (2520, 635, 'A sample gives off ammonia when warmed with sodium hydroxide. What ion is present?', 'text', 1, 'The gas is produced from ammonium ions.', '{"why":"The sodium hydroxide test is a standard test for ammonium ions.","sol":"Step 1: Identify the gas as ammonia.\nStep 2: Ammonia is released from ammonium ions in this test.\nStep 3: Therefore, the sample contains NH₄⁺.","steps":["Step 1: Identify the gas as ammonia.","Step 2: Ammonia is released from ammonium ions in this test.","Step 3: Therefore, the sample contains NH₄⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonium Ions"}', 3),
  (2521, 636, 'What colour precipitate is produced when sodium hydroxide is added to a solution containing Cu²⁺ ions?', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"Cu²⁺ forms blue copper(II) hydroxide with hydroxide ions.","sol":"Step 1: Cu²⁺ reacts with OH⁻ ions.\nStep 2: Copper(II) hydroxide is formed.\nStep 3: Copper(II) hydroxide is blue.","steps":["Step 1: Cu²⁺ reacts with OH⁻ ions.","Step 2: Copper(II) hydroxide is formed.","Step 3: Copper(II) hydroxide is blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 0),
  (2522, 636, 'Write the ionic equation for the test for Cu²⁺ ions.', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"The charges and atoms are balanced in the precipitation reaction.","sol":"Step 1: Identify the ions reacting: Cu²⁺ and OH⁻.\nStep 2: Two hydroxide ions are required to balance the +2 charge.\nStep 3: The solid product is Cu(OH)₂.","steps":["Step 1: Identify the ions reacting: Cu²⁺ and OH⁻.","Step 2: Two hydroxide ions are required to balance the +2 charge.","Step 3: The solid product is Cu(OH)₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 1),
  (2523, 636, 'What observation indicates the presence of copper(II) ions?', 'text', 1, 'Focus on the core principle of Test for Copper(II) Ions.', '{"why":"Copper(II) hydroxide has a characteristic blue colour.","sol":"Step 1: Add sodium hydroxide solution.\nStep 2: Observe whether a precipitate forms.\nStep 3: A blue precipitate indicates Cu²⁺.","steps":["Step 1: Add sodium hydroxide solution.","Step 2: Observe whether a precipitate forms.","Step 3: A blue precipitate indicates Cu²⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 2),
  (2524, 636, 'A colourless solution produces a blue precipitate when sodium hydroxide is added. Which common ion could be present?', 'text', 1, 'Think of the metal ion that forms blue copper(II) hydroxide.', '{"why":"Copper(II) hydroxide is a blue precipitate.","sol":"Step 1: A blue precipitate is observed.\nStep 2: Cu²⁺ reacts with OH⁻ to form blue Cu(OH)₂.\nStep 3: Therefore, Cu²⁺ may be present.","steps":["Step 1: A blue precipitate is observed.","Step 2: Cu²⁺ reacts with OH⁻ to form blue Cu(OH)₂.","Step 3: Therefore, Cu²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Copper(II) Ions"}', 3),
  (2525, 637, 'What colour precipitate is formed when Fe²⁺ ions react with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"Fe(OH)₂ is characteristically green.","sol":"Step 1: Fe²⁺ reacts with OH⁻.\nStep 2: Iron(II) hydroxide forms.\nStep 3: Iron(II) hydroxide is green.","steps":["Step 1: Fe²⁺ reacts with OH⁻.","Step 2: Iron(II) hydroxide forms.","Step 3: Iron(II) hydroxide is green."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 0),
  (2526, 637, 'Write the ionic equation for the formation of iron(II) hydroxide.', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"The reaction forms an insoluble hydroxide precipitate.","sol":"Step 1: Start with Fe²⁺.\nStep 2: Two OH⁻ ions are needed to balance the charge.\nStep 3: The insoluble product is Fe(OH)₂.","steps":["Step 1: Start with Fe²⁺.","Step 2: Two OH⁻ ions are needed to balance the charge.","Step 3: The insoluble product is Fe(OH)₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 1),
  (2527, 637, 'How can Fe²⁺ ions be distinguished from Cu²⁺ ions using sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(II) Ions.', '{"why":"The hydroxides have different characteristic colours.","sol":"Step 1: Add sodium hydroxide to each sample.\nStep 2: Fe²⁺ produces a green precipitate.\nStep 3: Cu²⁺ produces a blue precipitate.","steps":["Step 1: Add sodium hydroxide to each sample.","Step 2: Fe²⁺ produces a green precipitate.","Step 3: Cu²⁺ produces a blue precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 2),
  (2528, 637, 'A sample produces a green precipitate with sodium hydroxide. Which ion could be responsible?', 'text', 1, 'Compare the characteristic hydroxide colours.', '{"why":"Fe²⁺ produces green Fe(OH)₂ with hydroxide ions.","sol":"Step 1: Identify the precipitate colour as green.\nStep 2: Iron(II) hydroxide is green.\nStep 3: Therefore, Fe²⁺ may be present.","steps":["Step 1: Identify the precipitate colour as green.","Step 2: Iron(II) hydroxide is green.","Step 3: Therefore, Fe²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(II) Ions"}', 3),
  (2529, 638, 'What colour precipitate is formed when Fe³⁺ reacts with sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"Iron(III) hydroxide has a characteristic red-brown colour.","sol":"Step 1: Fe³⁺ reacts with OH⁻ ions.\nStep 2: Iron(III) hydroxide forms.\nStep 3: The precipitate is red-brown.","steps":["Step 1: Fe³⁺ reacts with OH⁻ ions.","Step 2: Iron(III) hydroxide forms.","Step 3: The precipitate is red-brown."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 0),
  (2530, 638, 'Write the ionic equation for the reaction of Fe³⁺ with hydroxide ions.', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"Three hydroxide ions balance the +3 charge on Fe³⁺.","sol":"Step 1: The iron ion has a +3 charge.\nStep 2: Three OH⁻ ions are needed to balance the charge.\nStep 3: Iron(III) hydroxide forms as a precipitate.","steps":["Step 1: The iron ion has a +3 charge.","Step 2: Three OH⁻ ions are needed to balance the charge.","Step 3: Iron(III) hydroxide forms as a precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 1),
  (2531, 638, 'How can Fe³⁺ be distinguished from Fe²⁺ using sodium hydroxide?', 'text', 1, 'Focus on the core principle of Test for Iron(III) Ions.', '{"why":"The two iron hydroxides have different characteristic colours.","sol":"Step 1: Add sodium hydroxide to both samples.\nStep 2: Fe²⁺ gives a green precipitate.\nStep 3: Fe³⁺ gives a red-brown precipitate.","steps":["Step 1: Add sodium hydroxide to both samples.","Step 2: Fe²⁺ gives a green precipitate.","Step 3: Fe³⁺ gives a red-brown precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 2),
  (2532, 638, 'A solution gives a red-brown precipitate when sodium hydroxide is added. Which ion is indicated?', 'text', 1, 'Think about the colour of iron(III) hydroxide.', '{"why":"Fe³⁺ forms red-brown Fe(OH)₃.","sol":"Step 1: Identify the precipitate as red-brown.\nStep 2: Fe(OH)₃ is red-brown.\nStep 3: Therefore, Fe³⁺ is indicated.","steps":["Step 1: Identify the precipitate as red-brown.","Step 2: Fe(OH)₃ is red-brown.","Step 3: Therefore, Fe³⁺ is indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_iron_iii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Iron(III) Ions"}', 3),
  (2533, 639, 'What reagent is used to test for chloride ions after acidification?', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"Silver ions react with chloride ions to form insoluble silver chloride.","sol":"Step 1: Acidify the sample with dilute nitric acid.\nStep 2: Add aqueous silver nitrate.\nStep 3: Observe whether a precipitate forms.","steps":["Step 1: Acidify the sample with dilute nitric acid.","Step 2: Add aqueous silver nitrate.","Step 3: Observe whether a precipitate forms."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 0),
  (2534, 639, 'What colour precipitate indicates chloride ions?', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"AgCl is a white insoluble precipitate.","sol":"Step 1: Silver ions react with chloride ions.\nStep 2: Silver chloride is produced.\nStep 3: Silver chloride is white.","steps":["Step 1: Silver ions react with chloride ions.","Step 2: Silver chloride is produced.","Step 3: Silver chloride is white."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 1),
  (2535, 639, 'Write the ionic equation for the chloride ion test.', 'text', 1, 'Focus on the core principle of Test for Chloride Ions.', '{"why":"Silver chloride precipitates from solution.","sol":"Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.\nStep 2: Combine them in a 1:1 ratio.\nStep 3: Write the insoluble product.","steps":["Step 1: Identify the reacting ions: Ag⁺ and Cl⁻.","Step 2: Combine them in a 1:1 ratio.","Step 3: Write the insoluble product."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 2),
  (2536, 639, 'A sample produces a white precipitate when acidified and treated with silver nitrate. Which ion is indicated?', 'text', 1, 'Silver chloride is white.', '{"why":"Ag⁺ + Cl⁻ → AgCl(s), a white precipitate.","sol":"Step 1: Silver nitrate supplies Ag⁺ ions.\nStep 2: A white precipitate of AgCl forms if Cl⁻ is present.\nStep 3: Therefore, chloride ions are indicated.","steps":["Step 1: Silver nitrate supplies Ag⁺ ions.","Step 2: A white precipitate of AgCl forms if Cl⁻ is present.","Step 3: Therefore, chloride ions are indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chloride_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chloride Ions"}', 3),
  (2537, 640, 'What ion is being tested for when barium ions produce a white precipitate?', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"Barium sulphate is an insoluble white solid.","sol":"Step 1: Barium ions react with sulphate ions.\nStep 2: Insoluble barium sulphate forms.\nStep 3: Therefore, the ion being tested is SO₄²⁻.","steps":["Step 1: Barium ions react with sulphate ions.","Step 2: Insoluble barium sulphate forms.","Step 3: Therefore, the ion being tested is SO₄²⁻."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 0),
  (2538, 640, 'Write the ionic equation for the sulphate ion test.', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"Barium sulphate forms a white precipitate.","sol":"Step 1: Identify Ba²⁺ and SO₄²⁻.\nStep 2: Their charges balance in a 1:1 ratio.\nStep 3: The product is insoluble BaSO₄.","steps":["Step 1: Identify Ba²⁺ and SO₄²⁻.","Step 2: Their charges balance in a 1:1 ratio.","Step 3: The product is insoluble BaSO₄."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 1),
  (2539, 640, 'What observation confirms the presence of sulphate ions?', 'text', 1, 'Focus on the core principle of Test for Sulphate Ions.', '{"why":"BaSO₄ is insoluble and appears as a white precipitate.","sol":"Step 1: Acidify the sample.\nStep 2: Add a soluble barium salt.\nStep 3: Look for a white precipitate.","steps":["Step 1: Acidify the sample.","Step 2: Add a soluble barium salt.","Step 3: Look for a white precipitate."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 2),
  (2540, 640, 'A sample gives a white precipitate after acidification and addition of barium ions. Which ion may be present?', 'text', 1, 'Think of the insoluble barium salt used in qualitative analysis.', '{"why":"Ba²⁺ + SO₄²⁻ → BaSO₄(s).","sol":"Step 1: Barium ions form an insoluble salt with sulphate ions.\nStep 2: Barium sulphate is white.\nStep 3: Therefore, SO₄²⁻ may be present.","steps":["Step 1: Barium ions form an insoluble salt with sulphate ions.","Step 2: Barium sulphate is white.","Step 3: Therefore, SO₄²⁻ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_sulphate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Sulphate Ions"}', 3),
  (2541, 641, 'What gas is produced when a carbonate reacts with a dilute acid?', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"Carbonate ions release CO₂ when treated with an acid.","sol":"Step 1: Carbonates contain CO₃²⁻ ions.\nStep 2: Carbonate ions react with H⁺ ions.\nStep 3: Carbon dioxide gas and water are formed.","steps":["Step 1: Carbonates contain CO₃²⁻ ions.","Step 2: Carbonate ions react with H⁺ ions.","Step 3: Carbon dioxide gas and water are formed."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 0),
  (2542, 641, 'What happens to limewater when carbon dioxide is passed through it?', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"Insoluble calcium carbonate forms.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide in limewater.\nStep 2: Calcium carbonate is formed.\nStep 3: Calcium carbonate is insoluble and makes the solution milky.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide in limewater.","Step 2: Calcium carbonate is formed.","Step 3: Calcium carbonate is insoluble and makes the solution milky."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 1),
  (2543, 641, 'Write the ionic equation for the reaction of carbonate ions with acid.', 'text', 1, 'Focus on the core principle of Test for Carbonate Ions.', '{"why":"This reaction explains the effervescence observed when an acid is added to a carbonate.","sol":"Step 1: Carbonate ion is CO₃²⁻.\nStep 2: Two H⁺ ions are required to balance the charge.\nStep 3: The products are CO₂ and H₂O.","steps":["Step 1: Carbonate ion is CO₃²⁻.","Step 2: Two H⁺ ions are required to balance the charge.","Step 3: The products are CO₂ and H₂O."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 2),
  (2544, 641, 'A solid fizzes when dilute hydrochloric acid is added and the gas turns limewater milky. Which ion is present?', 'text', 1, 'The gas is carbon dioxide.', '{"why":"Carbonates react with acids to release carbon dioxide.","sol":"Step 1: Fizzing indicates gas production.\nStep 2: Limewater turning milky identifies the gas as CO₂.\nStep 3: Carbonates produce CO₂ with acids.","steps":["Step 1: Fizzing indicates gas production.","Step 2: Limewater turning milky identifies the gas as CO₂.","Step 3: Carbonates produce CO₂ with acids."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbonate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbonate Ions"}', 3),
  (2545, 642, 'Which gas is produced in the aluminium and sodium hydroxide test for nitrate ions?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"The nitrate test produces ammonia when nitrate ions are reduced under the test conditions.","sol":"Step 1: Nitrate ions are reduced during the test.\nStep 2: Ammonia is produced.\nStep 3: The ammonia can be identified using damp red litmus paper.","steps":["Step 1: Nitrate ions are reduced during the test.","Step 2: Ammonia is produced.","Step 3: The ammonia can be identified using damp red litmus paper."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 0),
  (2546, 642, 'What observation confirms that the gas produced in the nitrate test is ammonia?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"Ammonia is alkaline in water.","sol":"Step 1: Collect or expose damp red litmus paper to the gas.\nStep 2: Ammonia dissolves in the moisture on the paper.\nStep 3: The resulting alkaline solution turns red litmus blue.","steps":["Step 1: Collect or expose damp red litmus paper to the gas.","Step 2: Ammonia dissolves in the moisture on the paper.","Step 3: The resulting alkaline solution turns red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 1),
  (2547, 642, 'What ion is indicated if the nitrate test produces ammonia?', 'text', 1, 'Focus on the core principle of Test for Nitrate Ions.', '{"why":"The formation of ammonia is the positive result for nitrate in this test.","sol":"Step 1: Identify the gas as ammonia.\nStep 2: In this test, ammonia is produced from nitrate ions.\nStep 3: Therefore, nitrate ions are indicated.","steps":["Step 1: Identify the gas as ammonia.","Step 2: In this test, ammonia is produced from nitrate ions.","Step 3: Therefore, nitrate ions are indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 2),
  (2548, 642, 'A sample produces ammonia when tested with aluminium and sodium hydroxide. Which anion could be present?', 'text', 1, 'Think of the anion identified by this test.', '{"why":"The test detects nitrate through the formation of ammonia.","sol":"Step 1: Ammonia is produced.\nStep 2: The aluminium/sodium hydroxide test is used for nitrate ions.\nStep 3: Therefore, NO₃⁻ may be present.","steps":["Step 1: Ammonia is produced.","Step 2: The aluminium/sodium hydroxide test is used for nitrate ions.","Step 3: Therefore, NO₃⁻ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_nitrate_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Nitrate Ions"}', 3),
  (2549, 643, 'What flame colour indicates sodium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"Excited sodium atoms emit characteristic yellow light.","sol":"Step 1: Place the sample in the flame.\nStep 2: Observe the characteristic emission colour.\nStep 3: Sodium produces a yellow flame.","steps":["Step 1: Place the sample in the flame.","Step 2: Observe the characteristic emission colour.","Step 3: Sodium produces a yellow flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 0),
  (2550, 643, 'Which ion gives a yellow flame in a flame test?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"Sodium has a characteristic yellow flame.","sol":"Step 1: Recall the characteristic sodium flame colour.\nStep 2: Sodium produces yellow.\nStep 3: Therefore, the ion is Na⁺.","steps":["Step 1: Recall the characteristic sodium flame colour.","Step 2: Sodium produces yellow.","Step 3: Therefore, the ion is Na⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 1),
  (2551, 643, 'Why must the wire loop be cleaned before another flame test?', 'text', 1, 'Focus on the core principle of Flame Test for Sodium Ions.', '{"why":"A clean loop improves the reliability of the flame test.","sol":"Step 1: Residue from a previous sample may remain on the wire.\nStep 2: The residue may produce its own flame colour.\nStep 3: This could interfere with the new observation.","steps":["Step 1: Residue from a previous sample may remain on the wire.","Step 2: The residue may produce its own flame colour.","Step 3: This could interfere with the new observation."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 2),
  (2552, 643, 'A sample gives a bright yellow flame. Which common metal ion is indicated?', 'text', 1, 'Recall the characteristic flame colour of sodium.', '{"why":"Sodium gives a characteristic yellow flame.","sol":"Step 1: Identify the flame colour as yellow.\nStep 2: Sodium produces a yellow flame.\nStep 3: Therefore, Na⁺ may be present.","steps":["Step 1: Identify the flame colour as yellow.","Step 2: Sodium produces a yellow flame.","Step 3: Therefore, Na⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_sodium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Sodium Ions"}', 3),
  (2553, 644, 'What flame colour is produced by potassium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"Potassium has a characteristic lilac flame.","sol":"Step 1: Place the potassium compound in the flame.\nStep 2: Observe the characteristic emission colour.\nStep 3: Potassium produces a lilac flame.","steps":["Step 1: Place the potassium compound in the flame.","Step 2: Observe the characteristic emission colour.","Step 3: Potassium produces a lilac flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 0),
  (2554, 644, 'Which ion gives a lilac flame?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"K⁺ produces a lilac flame.","sol":"Step 1: Identify the flame as lilac.\nStep 2: Potassium is associated with this flame colour.\nStep 3: Therefore, the ion is K⁺.","steps":["Step 1: Identify the flame as lilac.","Step 2: Potassium is associated with this flame colour.","Step 3: Therefore, the ion is K⁺."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 1),
  (2555, 644, 'Why can sodium contamination make the potassium flame test difficult to observe?', 'text', 1, 'Focus on the core principle of Flame Test for Potassium Ions.', '{"why":"Sodium emission is intense and can interfere with observation.","sol":"Step 1: Sodium produces a strong yellow flame.\nStep 2: Potassium produces a lilac flame.\nStep 3: The strong sodium yellow can mask the weaker lilac colour.","steps":["Step 1: Sodium produces a strong yellow flame.","Step 2: Potassium produces a lilac flame.","Step 3: The strong sodium yellow can mask the weaker lilac colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 2),
  (2556, 644, 'A sample produces a lilac flame. Which ion is indicated?', 'text', 1, 'Recall the flame colour of potassium.', '{"why":"Potassium has a characteristic lilac flame.","sol":"Step 1: Identify the flame colour as lilac.\nStep 2: Potassium produces a lilac flame.\nStep 3: Therefore, K⁺ is indicated.","steps":["Step 1: Identify the flame colour as lilac.","Step 2: Potassium produces a lilac flame.","Step 3: Therefore, K⁺ is indicated."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_potassium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Potassium Ions"}', 3),
  (2557, 645, 'What flame colour is associated with calcium ions?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"Calcium produces a characteristic red-orange flame.","sol":"Step 1: Place the calcium compound in the flame.\nStep 2: Observe the emission colour.\nStep 3: Calcium gives a brick-red or orange-red flame.","steps":["Step 1: Place the calcium compound in the flame.","Step 2: Observe the emission colour.","Step 3: Calcium gives a brick-red or orange-red flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 0),
  (2558, 645, 'Which ion can produce a brick-red flame?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"Ca²⁺ compounds produce a brick-red flame.","sol":"Step 1: Identify the characteristic colour.\nStep 2: Calcium produces a brick-red flame.\nStep 3: Therefore, Ca²⁺ may be present.","steps":["Step 1: Identify the characteristic colour.","Step 2: Calcium produces a brick-red flame.","Step 3: Therefore, Ca²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 1),
  (2559, 645, 'Why is the flame test useful in qualitative analysis?', 'text', 1, 'Focus on the core principle of Flame Test for Calcium Ions.', '{"why":"The colours arise from characteristic electronic transitions in the atoms.","sol":"Step 1: Different metal ions emit different characteristic wavelengths of light.\nStep 2: These wavelengths appear as characteristic flame colours.\nStep 3: The colour can therefore help identify the metal ion.","steps":["Step 1: Different metal ions emit different characteristic wavelengths of light.","Step 2: These wavelengths appear as characteristic flame colours.","Step 3: The colour can therefore help identify the metal ion."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 2),
  (2560, 645, 'A compound gives an orange-red flame. Which ion could be present?', 'text', 1, 'Recall the flame colour associated with calcium.', '{"why":"Calcium gives a characteristic orange-red/brick-red flame.","sol":"Step 1: Identify the flame as orange-red.\nStep 2: Calcium compounds produce an orange-red or brick-red flame.\nStep 3: Therefore, Ca²⁺ may be present.","steps":["Step 1: Identify the flame as orange-red.","Step 2: Calcium compounds produce an orange-red or brick-red flame.","Step 3: Therefore, Ca²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_calcium_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Calcium Ions"}', 3),
  (2561, 646, 'What flame colour is associated with copper compounds?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Copper compounds produce characteristic green/blue-green flame colours.","sol":"Step 1: Place the copper compound in the flame.\nStep 2: Observe the emitted light.\nStep 3: Copper compounds commonly produce a blue-green or green flame.","steps":["Step 1: Place the copper compound in the flame.","Step 2: Observe the emitted light.","Step 3: Copper compounds commonly produce a blue-green or green flame."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 0),
  (2562, 646, 'Which common metal ion can give a blue-green flame?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Copper compounds have characteristic blue-green/green flame emissions.","sol":"Step 1: Identify the characteristic flame colour.\nStep 2: Copper compounds produce blue-green or green flames.\nStep 3: Therefore, Cu²⁺ may be present.","steps":["Step 1: Identify the characteristic flame colour.","Step 2: Copper compounds produce blue-green or green flames.","Step 3: Therefore, Cu²⁺ may be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 1),
  (2563, 646, 'Why should flame colour be used together with other observations when identifying an unknown?', 'text', 1, 'Focus on the core principle of Flame Test for Copper(II) Ions.', '{"why":"Qualitative identification is more reliable when multiple consistent observations are used.","sol":"Step 1: Some flame colours can be affected by contamination.\nStep 2: Some colours may be difficult to distinguish.\nStep 3: Additional chemical tests provide stronger evidence.","steps":["Step 1: Some flame colours can be affected by contamination.","Step 2: Some colours may be difficult to distinguish.","Step 3: Additional chemical tests provide stronger evidence."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 2),
  (2564, 646, 'An unknown compound produces a blue-green flame. Which metal ion could be present?', 'text', 1, 'Think about copper''s flame colour.', '{"why":"Copper compounds commonly give blue-green/green flame colours.","sol":"Step 1: Identify the flame as blue-green.\nStep 2: Copper compounds can produce a blue-green flame.\nStep 3: Therefore, Cu²⁺ could be present.","steps":["Step 1: Identify the flame as blue-green.","Step 2: Copper compounds can produce a blue-green flame.","Step 3: Therefore, Cu²⁺ could be present."],"options":[],"conceptId":"chemistry_qualitative_analysis_flame_test_for_copper_ii_ions","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Flame Test for Copper(II) Ions"}', 3),
  (2565, 647, 'What is the test for hydrogen gas?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Hydrogen reacts rapidly with oxygen and burns.","sol":"Step 1: Collect the gas safely.\nStep 2: Bring a lighted splint to the gas.\nStep 3: Listen for the characteristic popping sound.","steps":["Step 1: Collect the gas safely.","Step 2: Bring a lighted splint to the gas.","Step 3: Listen for the characteristic popping sound."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 0),
  (2566, 647, 'Write the balanced equation for combustion of hydrogen.', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Two hydrogen molecules react with one oxygen molecule to form two water molecules.","sol":"Step 1: Hydrogen reacts with oxygen.\nStep 2: The product is water.\nStep 3: Balance hydrogen and oxygen atoms.","steps":["Step 1: Hydrogen reacts with oxygen.","Step 2: The product is water.","Step 3: Balance hydrogen and oxygen atoms."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 1),
  (2567, 647, 'Why does hydrogen produce a popping sound during the test?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Rapid combustion of hydrogen causes a sudden expansion of hot gases.","sol":"Step 1: Hydrogen mixes with oxygen.\nStep 2: The mixture can burn rapidly when ignited.\nStep 3: Rapid combustion produces the characteristic sound.","steps":["Step 1: Hydrogen mixes with oxygen.","Step 2: The mixture can burn rapidly when ignited.","Step 3: Rapid combustion produces the characteristic sound."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 2),
  (2568, 647, 'A gas produces a squeaky pop when tested with a lighted splint. Identify the gas.', 'text', 1, 'This is the classic test for a common combustible gas.', '{"why":"Hydrogen burns rapidly with oxygen and gives a characteristic pop.","sol":"Step 1: Observe the squeaky pop.\nStep 2: This is characteristic of hydrogen.\nStep 3: Therefore, the gas is H₂.","steps":["Step 1: Observe the squeaky pop.","Step 2: This is characteristic of hydrogen.","Step 3: Therefore, the gas is H₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_hydrogen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Hydrogen"}', 3),
  (2569, 648, 'What is the test for oxygen?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen supports combustion.","sol":"Step 1: Prepare a glowing splint.\nStep 2: Insert it into the gas sample.\nStep 3: Observe whether the splint relights.","steps":["Step 1: Prepare a glowing splint.","Step 2: Insert it into the gas sample.","Step 3: Observe whether the splint relights."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 0),
  (2570, 648, 'Why does a glowing splint relight in oxygen?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen allows combustion to continue more readily.","sol":"Step 1: The splint contains hot material that is already glowing.\nStep 2: Oxygen supports combustion.\nStep 3: The increased oxygen supply allows the splint to burn again.","steps":["Step 1: The splint contains hot material that is already glowing.","Step 2: Oxygen supports combustion.","Step 3: The increased oxygen supply allows the splint to burn again."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 1),
  (2571, 648, 'Does oxygen itself burn during the glowing splint test?', 'text', 1, 'Focus on the core principle of Test for Oxygen.', '{"why":"Oxygen acts as an oxidising gas in combustion.","sol":"Step 1: Oxygen supports the burning of other substances.\nStep 2: It is not the fuel in the test.\nStep 3: Therefore, oxygen supports combustion rather than burning itself.","steps":["Step 1: Oxygen supports the burning of other substances.","Step 2: It is not the fuel in the test.","Step 3: Therefore, oxygen supports combustion rather than burning itself."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 2),
  (2572, 648, 'A glowing splint relights when placed in a gas. Identify the gas.', 'text', 1, 'Think of the gas that supports combustion.', '{"why":"Oxygen relights a glowing splint.","sol":"Step 1: Relighting a glowing splint is the characteristic test.\nStep 2: Oxygen supports combustion.\nStep 3: Therefore, the gas is oxygen.","steps":["Step 1: Relighting a glowing splint is the characteristic test.","Step 2: Oxygen supports combustion.","Step 3: Therefore, the gas is oxygen."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_oxygen","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Oxygen"}', 3),
  (2573, 649, 'What is the test for carbon dioxide?', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"Carbon dioxide reacts with limewater to form insoluble calcium carbonate.","sol":"Step 1: Pass the gas into limewater.\nStep 2: Observe the appearance of the limewater.\nStep 3: A milky appearance indicates carbon dioxide.","steps":["Step 1: Pass the gas into limewater.","Step 2: Observe the appearance of the limewater.","Step 3: A milky appearance indicates carbon dioxide."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 0),
  (2574, 649, 'Why does limewater turn milky when carbon dioxide is passed through it?', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"The suspended calcium carbonate makes the limewater appear milky.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide.\nStep 2: Calcium carbonate is formed.\nStep 3: Calcium carbonate is insoluble and appears as a suspension.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide.","Step 2: Calcium carbonate is formed.","Step 3: Calcium carbonate is insoluble and appears as a suspension."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 1),
  (2575, 649, 'Write the equation for the reaction of carbon dioxide with limewater.', 'text', 1, 'Focus on the core principle of Test for Carbon Dioxide.', '{"why":"The reaction produces insoluble calcium carbonate.","sol":"Step 1: Carbon dioxide reacts with calcium hydroxide.\nStep 2: Calcium carbonate and water are formed.\nStep 3: Write the balanced equation.","steps":["Step 1: Carbon dioxide reacts with calcium hydroxide.","Step 2: Calcium carbonate and water are formed.","Step 3: Write the balanced equation."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 2),
  (2576, 649, 'An unknown gas turns limewater milky. Identify the gas.', 'text', 1, 'Think of the gas that forms calcium carbonate with limewater.', '{"why":"CO₂ gives the characteristic limewater test.","sol":"Step 1: Limewater contains calcium hydroxide.\nStep 2: Carbon dioxide reacts with it to form calcium carbonate.\nStep 3: Therefore, the gas is CO₂.","steps":["Step 1: Limewater contains calcium hydroxide.","Step 2: Carbon dioxide reacts with it to form calcium carbonate.","Step 3: Therefore, the gas is CO₂."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_carbon_dioxide","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Carbon Dioxide"}', 3),
  (2577, 650, 'What happens when ammonia is brought into contact with damp red litmus paper?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"Ammonia produces an alkaline solution in water.","sol":"Step 1: Ammonia dissolves in the moisture on the paper.\nStep 2: The resulting solution is alkaline.\nStep 3: Alkaline solutions turn red litmus blue.","steps":["Step 1: Ammonia dissolves in the moisture on the paper.","Step 2: The resulting solution is alkaline.","Step 3: Alkaline solutions turn red litmus blue."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 0),
  (2578, 650, 'Why must the litmus paper be damp when testing for ammonia?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"The indicator requires an aqueous environment to show the alkaline property clearly.","sol":"Step 1: Ammonia is highly soluble in water.\nStep 2: The moisture allows ammonia to dissolve.\nStep 3: The resulting alkaline solution changes the indicator colour.","steps":["Step 1: Ammonia is highly soluble in water.","Step 2: The moisture allows ammonia to dissolve.","Step 3: The resulting alkaline solution changes the indicator colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 1),
  (2579, 650, 'What type of substance is ammonia when dissolved in water?', 'text', 1, 'Focus on the core principle of Test for Ammonia.', '{"why":"Ammonia reacts with water to produce hydroxide ions.","sol":"Step 1: Ammonia dissolves in water.\nStep 2: It produces an alkaline solution.\nStep 3: Therefore, ammonia behaves as a weak alkali in water.","steps":["Step 1: Ammonia dissolves in water.","Step 2: It produces an alkaline solution.","Step 3: Therefore, ammonia behaves as a weak alkali in water."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 2),
  (2580, 650, 'A colourless gas turns damp red litmus paper blue. Which gas could it be?', 'text', 1, 'Think of a common alkaline gas.', '{"why":"Ammonia turns damp red litmus paper blue.","sol":"Step 1: The gas produces an alkaline solution with moisture.\nStep 2: Ammonia is a common alkaline gas.\nStep 3: Therefore, the gas could be NH₃.","steps":["Step 1: The gas produces an alkaline solution with moisture.","Step 2: Ammonia is a common alkaline gas.","Step 3: Therefore, the gas could be NH₃."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_ammonia","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Ammonia"}', 3),
  (2581, 651, 'What happens to damp blue litmus paper in chlorine gas?', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Chlorine reacts with water and has a bleaching action in the presence of moisture.","sol":"Step 1: Chlorine reacts with water on the damp paper.\nStep 2: The acidic products can initially turn blue litmus red.\nStep 3: Chlorine''s bleaching action then removes the colour.","steps":["Step 1: Chlorine reacts with water on the damp paper.","Step 2: The acidic products can initially turn blue litmus red.","Step 3: Chlorine''s bleaching action then removes the colour."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q1","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 0),
  (2582, 651, 'Why must the litmus paper be damp when testing for chlorine?', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Dry chlorine does not show the same bleaching behaviour as readily as moist chlorine.","sol":"Step 1: Chlorine reacts with water.\nStep 2: The moisture allows the relevant reactions to occur.\nStep 3: The bleaching effect can then be observed.","steps":["Step 1: Chlorine reacts with water.","Step 2: The moisture allows the relevant reactions to occur.","Step 3: The bleaching effect can then be observed."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q2","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 1),
  (2583, 651, 'State two observable properties that can help identify chlorine gas.', 'text', 1, 'Focus on the core principle of Test for Chlorine.', '{"why":"Both observations are characteristic of chlorine.","sol":"Step 1: Chlorine has a characteristic colour.\nStep 2: It also has a characteristic effect on damp litmus.\nStep 3: These observations can support identification.","steps":["Step 1: Chlorine has a characteristic colour.","Step 2: It also has a characteristic effect on damp litmus.","Step 3: These observations can support identification."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q3","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 2),
  (2584, 651, 'A greenish-yellow gas turns damp blue litmus red and then bleaches it. Identify the gas.', 'text', 1, 'Think of the halogen gas with bleaching properties.', '{"why":"Chlorine is a greenish-yellow gas that bleaches damp litmus.","sol":"Step 1: The gas is greenish-yellow.\nStep 2: It bleaches damp litmus.\nStep 3: These observations identify chlorine.","steps":["Step 1: The gas is greenish-yellow.","Step 2: It bleaches damp litmus.","Step 3: These observations identify chlorine."],"options":[],"conceptId":"chemistry_qualitative_analysis_test_for_chlorine","skillId":"chemistry_qualitative_analysis","subskillId":"chemistry_qualitative_analysis_q4","subject":"chemistry","chapter":"qualitative_analysis","topic":"Test for Chlorine"}', 3),
  (2585, 652, 'What is a reversible reaction?', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"Both reactants can form products and products can react to reform the reactants.","sol":"Step 1: Identify the direction of the reaction.\nStep 2: Check whether the products can react to form the original reactants.\nStep 3: A reaction that can proceed in both directions is reversible.","steps":["Step 1: Identify the direction of the reaction.","Step 2: Check whether the products can react to form the original reactants.","Step 3: A reaction that can proceed in both directions is reversible."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 0),
  (2586, 652, 'What does the symbol ⇌ mean in a chemical equation?', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"The reaction can proceed in both directions.","sol":"Step 1: Look at the two arrows.\nStep 2: One arrow represents the forward reaction.\nStep 3: The other represents the reverse reaction.","steps":["Step 1: Look at the two arrows.","Step 2: One arrow represents the forward reaction.","Step 3: The other represents the reverse reaction."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 1),
  (2587, 652, 'In N₂ + 3H₂ ⇌ 2NH₃, which substances are the reactants in the forward reaction?', 'text', 1, 'Focus on the core principle of Reversible Reactions.', '{"why":"They react together in the forward reaction to form ammonia.","sol":"Step 1: Read the equation from left to right.\nStep 2: The substances on the left are the reactants.\nStep 3: These are nitrogen and hydrogen.","steps":["Step 1: Read the equation from left to right.","Step 2: The substances on the left are the reactants.","Step 3: These are nitrogen and hydrogen."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 2),
  (2588, 652, 'A student writes A + B → C for a reaction that can also produce A and B from C. What should the student change?', 'text', 1, 'Think about the correct symbol for a reaction that proceeds in both directions.', '{"why":"The reversible arrow shows that both the forward and reverse reactions occur.","sol":"Step 1: The reaction proceeds forward and backward.\nStep 2: A single arrow does not show this.\nStep 3: Replace → with ⇌.","steps":["Step 1: The reaction proceeds forward and backward.","Step 2: A single arrow does not show this.","Step 3: Replace → with ⇌."],"options":[],"conceptId":"chemistry_reversible_equilibrium_reversible_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Reversible Reactions"}', 3),
  (2589, 653, 'What is the forward reaction in A + B ⇌ C?', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"The forward reaction proceeds from reactants to products.","sol":"Step 1: Start with the reactants on the left.\nStep 2: Move toward the products on the right.\nStep 3: Write the reaction from A + B to C.","steps":["Step 1: Start with the reactants on the left.","Step 2: Move toward the products on the right.","Step 3: Write the reaction from A + B to C."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 0),
  (2590, 653, 'What is the reverse reaction in A + B ⇌ C?', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"The reverse reaction converts products back into reactants.","sol":"Step 1: Start with C.\nStep 2: Move toward A + B.\nStep 3: Write the reaction from C to A + B.","steps":["Step 1: Start with C.","Step 2: Move toward A + B.","Step 3: Write the reaction from C to A + B."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 1),
  (2591, 653, 'For N₂ + 3H₂ ⇌ 2NH₃, write the reverse reaction.', 'text', 1, 'Focus on the core principle of Forward and Reverse Reactions.', '{"why":"The reverse reaction converts ammonia back into nitrogen and hydrogen.","sol":"Step 1: Start with ammonia.\nStep 2: Move from right to left.\nStep 3: Write ammonia decomposing into nitrogen and hydrogen.","steps":["Step 1: Start with ammonia.","Step 2: Move from right to left.","Step 3: Write ammonia decomposing into nitrogen and hydrogen."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 2),
  (2592, 653, 'For X ⇌ Y, a learner writes X → Y as the reverse reaction. Is this correct?', 'text', 1, 'The reverse reaction travels from right to left.', '{"why":"The reverse reaction proceeds in the opposite direction to the forward reaction.","sol":"Step 1: X is on the left.\nStep 2: Y is on the right.\nStep 3: The reverse reaction must travel from Y to X.","steps":["Step 1: X is on the left.","Step 2: Y is on the right.","Step 3: The reverse reaction must travel from Y to X."],"options":[],"conceptId":"chemistry_reversible_equilibrium_forward_and_reverse_reactions","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Forward and Reverse Reactions"}', 3),
  (2593, 654, 'What is dynamic equilibrium?', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"Equal reaction rates cause the concentrations of reactants and products to remain constant.","sol":"Step 1: Consider a reversible reaction.\nStep 2: The forward and reverse reactions continue.\nStep 3: At equilibrium, their rates become equal.","steps":["Step 1: Consider a reversible reaction.","Step 2: The forward and reverse reactions continue.","Step 3: At equilibrium, their rates become equal."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 0),
  (2594, 654, 'Do the forward and reverse reactions stop at dynamic equilibrium?', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"Equilibrium is a balance of reaction rates, not a stopping of reactions.","sol":"Step 1: Recall that the equilibrium is dynamic.\nStep 2: Dynamic means the reactions continue.\nStep 3: Their rates are equal.","steps":["Step 1: Recall that the equilibrium is dynamic.","Step 2: Dynamic means the reactions continue.","Step 3: Their rates are equal."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 1),
  (2595, 654, 'What happens to the concentrations of reactants and products at equilibrium?', 'text', 1, 'Focus on the core principle of Dynamic Equilibrium.', '{"why":"Equal forward and reverse rates prevent a net change in concentration.","sol":"Step 1: The forward and reverse reactions occur at equal rates.\nStep 2: Reactants are converted to products at the same rate that products form reactants.\nStep 3: The concentrations therefore remain constant.","steps":["Step 1: The forward and reverse reactions occur at equal rates.","Step 2: Reactants are converted to products at the same rate that products form reactants.","Step 3: The concentrations therefore remain constant."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 2),
  (2596, 654, 'A student says equilibrium means that no reaction is taking place. What is wrong with this statement?', 'text', 1, 'Think about the word dynamic.', '{"why":"Dynamic equilibrium is a balance between two continuing reactions.","sol":"Step 1: A reversible reaction continues in both directions.\nStep 2: At equilibrium the two rates are equal.\nStep 3: Therefore reactions are still occurring.","steps":["Step 1: A reversible reaction continues in both directions.","Step 2: At equilibrium the two rates are equal.","Step 3: Therefore reactions are still occurring."],"options":[],"conceptId":"chemistry_reversible_equilibrium_dynamic_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Dynamic Equilibrium"}', 3),
  (2597, 655, 'Why is the forward reaction usually fast at the beginning when only reactants are present?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"A high concentration of reactants generally increases the frequency of successful collisions.","sol":"Step 1: The reactants are present in relatively high concentration.\nStep 2: More reactant particles can collide.\nStep 3: More successful collisions produce products.","steps":["Step 1: The reactants are present in relatively high concentration.","Step 2: More reactant particles can collide.","Step 3: More successful collisions produce products."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 0),
  (2598, 655, 'What happens to the reverse reaction as products build up?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"Increasing product concentration increases the opportunity for the reverse reaction to occur.","sol":"Step 1: Products are formed by the forward reaction.\nStep 2: More product particles become available to react.\nStep 3: The reverse reaction rate increases.","steps":["Step 1: Products are formed by the forward reaction.","Step 2: More product particles become available to react.","Step 3: The reverse reaction rate increases."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 1),
  (2599, 655, 'What condition is reached when the forward and reverse reaction rates become equal?', 'text', 1, 'Focus on the core principle of Establishing Equilibrium.', '{"why":"Dynamic equilibrium occurs when the forward and reverse reaction rates are equal.","sol":"Step 1: Compare the two reaction rates.\nStep 2: Equal rates indicate equilibrium.\nStep 3: This is dynamic equilibrium.","steps":["Step 1: Compare the two reaction rates.","Step 2: Equal rates indicate equilibrium.","Step 3: This is dynamic equilibrium."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 2),
  (2600, 655, 'At the beginning of a reversible reaction, the forward rate is 0.80 mol/s and the reverse rate is 0.10 mol/s. Which reaction is faster?', 'text', 1, 'Compare the two numerical rates.', '{"why":"Its rate is 0.80 mol/s compared with 0.10 mol/s for the reverse reaction.","sol":"Step 1: Forward rate = 0.80 mol/s.\nStep 2: Reverse rate = 0.10 mol/s.\nStep 3: 0.80 is greater than 0.10.","steps":["Step 1: Forward rate = 0.80 mol/s.","Step 2: Reverse rate = 0.10 mol/s.","Step 3: 0.80 is greater than 0.10."],"options":[],"conceptId":"chemistry_reversible_equilibrium_establishing_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Establishing Equilibrium"}', 3),
  (2601, 656, 'For A + B ⇌ C + D, what happens if the concentration of A is increased?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"The forward reaction uses some of the added A and produces more C and D.","sol":"Step 1: A is a reactant.\nStep 2: The system tends to reduce the increased concentration of A.\nStep 3: The equilibrium shifts toward the products.","steps":["Step 1: A is a reactant.","Step 2: The system tends to reduce the increased concentration of A.","Step 3: The equilibrium shifts toward the products."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 0),
  (2602, 656, 'For A + B ⇌ C + D, what happens if the concentration of C is increased?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"The reverse reaction consumes C and forms A and B.","sol":"Step 1: C is a product.\nStep 2: The system tends to use up some of the added C.\nStep 3: The equilibrium shifts toward the reactants.","steps":["Step 1: C is a product.","Step 2: The system tends to use up some of the added C.","Step 3: The equilibrium shifts toward the reactants."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 1),
  (2603, 656, 'What happens when a product is removed from an equilibrium mixture?', 'text', 1, 'Focus on the core principle of Effect of Concentration on Equilibrium.', '{"why":"The forward reaction produces more of the removed product.","sol":"Step 1: The concentration of the product decreases.\nStep 2: The system tends to replace the removed product.\nStep 3: The equilibrium shifts toward the products.","steps":["Step 1: The concentration of the product decreases.","Step 2: The system tends to replace the removed product.","Step 3: The equilibrium shifts toward the products."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 2),
  (2604, 656, 'For X + Y ⇌ Z, extra X is added. In which direction will equilibrium shift?', 'text', 1, 'X is a reactant.', '{"why":"The forward reaction consumes the added reactant.","sol":"Step 1: Identify X as a reactant.\nStep 2: Its concentration has increased.\nStep 3: The system responds by consuming some X.","steps":["Step 1: Identify X as a reactant.","Step 2: Its concentration has increased.","Step 3: The system responds by consuming some X."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_concentration_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Concentration on Equilibrium"}', 3),
  (2605, 657, 'For an exothermic forward reaction, what happens when temperature is increased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"The system responds to added heat by favouring the direction that absorbs heat.","sol":"Step 1: The forward reaction releases heat.\nStep 2: Increasing temperature adds heat.\nStep 3: The system favours the direction that absorbs heat.","steps":["Step 1: The forward reaction releases heat.","Step 2: Increasing temperature adds heat.","Step 3: The system favours the direction that absorbs heat."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 0),
  (2606, 657, 'For an exothermic forward reaction, what happens when temperature is decreased?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"The system responds to the removal of heat by favouring the heat-producing direction.","sol":"Step 1: Decreasing temperature removes heat.\nStep 2: The system favours the direction that produces heat.\nStep 3: The exothermic forward reaction is favoured.","steps":["Step 1: Decreasing temperature removes heat.","Step 2: The system favours the direction that produces heat.","Step 3: The exothermic forward reaction is favoured."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 1),
  (2607, 657, 'Which direction is favoured when temperature is increased: exothermic or endothermic?', 'text', 1, 'Focus on the core principle of Effect of Temperature on Equilibrium.', '{"why":"An endothermic reaction absorbs heat from the surroundings.","sol":"Step 1: Increasing temperature adds heat.\nStep 2: The system tends to absorb the added heat.\nStep 3: Endothermic reactions absorb heat.","steps":["Step 1: Increasing temperature adds heat.","Step 2: The system tends to absorb the added heat.","Step 3: Endothermic reactions absorb heat."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 2),
  (2608, 657, 'A reversible reaction is exothermic in the forward direction. What happens to the equilibrium when temperature is increased?', 'text', 1, 'An exothermic forward reaction has an endothermic reverse reaction.', '{"why":"Increasing temperature favours the endothermic direction.","sol":"Step 1: The forward direction releases heat.\nStep 2: Increasing temperature adds heat.\nStep 3: The reverse endothermic direction is favoured.","steps":["Step 1: The forward direction releases heat.","Step 2: Increasing temperature adds heat.","Step 3: The reverse endothermic direction is favoured."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_temperature_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Temperature on Equilibrium"}', 3),
  (2609, 658, 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), which side is favoured when pressure is increased?', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"The right side contains fewer moles of gas.","sol":"Step 1: Count gaseous molecules on the left: 1 + 3 = 4.\nStep 2: Count gaseous molecules on the right: 2.\nStep 3: Higher pressure favours the side with fewer gas molecules.","steps":["Step 1: Count gaseous molecules on the left: 1 + 3 = 4.","Step 2: Count gaseous molecules on the right: 2.","Step 3: Higher pressure favours the side with fewer gas molecules."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 0),
  (2610, 658, 'What happens to equilibrium when pressure is decreased in N₂(g) + 3H₂(g) ⇌ 2NH₃(g)?', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"The left side contains more moles of gas.","sol":"Step 1: The left side has 4 moles of gas.\nStep 2: The right side has 2 moles of gas.\nStep 3: Lower pressure favours the side with more gaseous molecules.","steps":["Step 1: The left side has 4 moles of gas.","Step 2: The right side has 2 moles of gas.","Step 3: Lower pressure favours the side with more gaseous molecules."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 1),
  (2611, 658, 'When does changing pressure have little or no effect on equilibrium position?', 'text', 1, 'Focus on the core principle of Effect of Pressure on Equilibrium.', '{"why":"There is no side with fewer or more gaseous molecules to favour.","sol":"Step 1: Compare the number of gaseous molecules on both sides.\nStep 2: If the numbers are equal, neither side is favoured by pressure change.\nStep 3: Therefore the equilibrium position does not shift.","steps":["Step 1: Compare the number of gaseous molecules on both sides.","Step 2: If the numbers are equal, neither side is favoured by pressure change.","Step 3: Therefore the equilibrium position does not shift."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 2),
  (2612, 658, 'For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), which direction is favoured by increased pressure?', 'text', 1, 'Count the gaseous molecules on each side.', '{"why":"The products contain fewer gaseous molecules than the reactants.","sol":"Step 1: Left side = 2 + 1 = 3 moles of gas.\nStep 2: Right side = 2 moles of gas.\nStep 3: Increased pressure favours the side with fewer gas molecules.","steps":["Step 1: Left side = 2 + 1 = 3 moles of gas.","Step 2: Right side = 2 moles of gas.","Step 3: Increased pressure favours the side with fewer gas molecules."],"options":[],"conceptId":"chemistry_reversible_equilibrium_effect_of_pressure_on_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Effect of Pressure on Equilibrium"}', 3),
  (2613, 659, 'Write the balanced equation for the Haber process.', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"The equation contains equal numbers of nitrogen and hydrogen atoms on both sides.","sol":"Step 1: Identify nitrogen and hydrogen as the reactants.\nStep 2: The product is ammonia.\nStep 3: Balance nitrogen using 2NH₃.\nStep 4: Balance hydrogen using 3H₂.","steps":["Step 1: Identify nitrogen and hydrogen as the reactants.","Step 2: The product is ammonia.","Step 3: Balance nitrogen using 2NH₃.","Step 4: Balance hydrogen using 3H₂."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q1","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 0),
  (2614, 659, 'Why does high pressure favour ammonia production in the Haber process?', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"The equilibrium shifts toward the side with fewer gas molecules when pressure is increased.","sol":"Step 1: Count gaseous molecules on the reactant side: 4.\nStep 2: Count gaseous molecules on the product side: 2.\nStep 3: Increased pressure favours the side with fewer gas molecules.","steps":["Step 1: Count gaseous molecules on the reactant side: 4.","Step 2: Count gaseous molecules on the product side: 2.","Step 3: Increased pressure favours the side with fewer gas molecules."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q2","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 1),
  (2615, 659, 'What catalyst is used in the Haber process?', 'text', 1, 'Focus on the core principle of Industrial Equilibrium.', '{"why":"Iron increases the rate at which equilibrium is reached.","sol":"Step 1: Recall the industrial conditions for ammonia manufacture.\nStep 2: Identify the catalyst used to increase reaction rate.\nStep 3: The catalyst is iron.","steps":["Step 1: Recall the industrial conditions for ammonia manufacture.","Step 2: Identify the catalyst used to increase reaction rate.","Step 3: The catalyst is iron."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q3","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 2),
  (2616, 659, 'In the Haber process, why is a moderate temperature used instead of simply using a very low temperature?', 'text', 1, 'Think about the difference between equilibrium yield and reaction rate.', '{"why":"Lower temperature favours equilibrium yield but makes the reaction too slow for economical industrial production.","sol":"Step 1: The forward reaction is exothermic, so lower temperature favours ammonia yield.\nStep 2: Very low temperature makes the reaction too slow.\nStep 3: A moderate temperature provides a practical compromise between rate and yield.","steps":["Step 1: The forward reaction is exothermic, so lower temperature favours ammonia yield.","Step 2: Very low temperature makes the reaction too slow.","Step 3: A moderate temperature provides a practical compromise between rate and yield."],"options":[],"conceptId":"chemistry_reversible_equilibrium_industrial_equilibrium","skillId":"chemistry_reversible_equilibrium","subskillId":"chemistry_reversible_equilibrium_q4","subject":"chemistry","chapter":"reversible_equilibrium","topic":"Industrial Equilibrium"}', 3),
  (2617, 660, 'What does collision theory state about chemical reactions?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Collision theory explains that reactions occur when particles make suitable collisions.","sol":"Step 1: Chemical particles must collide for a reaction to occur.\nStep 2: The particles must have sufficient energy.\nStep 3: The particles must collide in a suitable orientation.\nStep 4: Therefore, only suitable collisions can produce a chemical reaction.","steps":["Step 1: Chemical particles must collide for a reaction to occur.","Step 2: The particles must have sufficient energy.","Step 3: The particles must collide in a suitable orientation.","Step 4: Therefore, only suitable collisions can produce a chemical reaction."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 0),
  (2618, 660, 'Why does every collision between reacting particles not produce a reaction?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Only collisions satisfying the required energy and orientation conditions can produce products.","sol":"Step 1: A collision must provide enough energy to overcome the reaction barrier.\nStep 2: The particles must also have a suitable orientation.\nStep 3: A collision lacking either requirement is unsuccessful.","steps":["Step 1: A collision must provide enough energy to overcome the reaction barrier.","Step 2: The particles must also have a suitable orientation.","Step 3: A collision lacking either requirement is unsuccessful."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 1),
  (2619, 660, 'What happens to the rate of reaction when the number of effective collisions per second increases?', 'text', 1, 'Focus on the core principle of Collision Theory.', '{"why":"Reaction rate depends on how frequently effective collisions occur.","sol":"Step 1: Effective collisions produce chemical reactions.\nStep 2: More effective collisions occur in the same amount of time.\nStep 3: More reactant particles are converted into products per second.","steps":["Step 1: Effective collisions produce chemical reactions.","Step 2: More effective collisions occur in the same amount of time.","Step 3: More reactant particles are converted into products per second."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 2),
  (2620, 660, 'A reaction mixture contains particles that collide frequently, but most collisions do not result in products. Give two possible reasons.', 'text', 1, 'Think about the two requirements for an effective collision.', '{"why":"Both sufficient energy and suitable orientation are required for an effective collision.","sol":"Step 1: Check whether the particles have sufficient energy.\nStep 2: Check whether they collide in a suitable orientation.\nStep 3: If either requirement is missing, the collision will not be effective.","steps":["Step 1: Check whether the particles have sufficient energy.","Step 2: Check whether they collide in a suitable orientation.","Step 3: If either requirement is missing, the collision will not be effective."],"options":[],"conceptId":"chemistry_rate_reactions_collision_theory","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Collision Theory"}', 3),
  (2621, 661, 'What is activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"Particles with energy below the activation energy cannot undergo a successful reaction during the collision.","sol":"Step 1: Particles need a minimum amount of energy for a reaction to occur.\nStep 2: This minimum energy is called activation energy.\nStep 3: It is represented by Eₐ.","steps":["Step 1: Particles need a minimum amount of energy for a reaction to occur.","Step 2: This minimum energy is called activation energy.","Step 3: It is represented by Eₐ."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 0),
  (2622, 661, 'A reacting particle has 45 kJ of energy while the activation energy is 60 kJ. Can this particle produce a successful collision based on energy alone?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"The particle must have at least the activation energy for a successful collision.","sol":"Step 1: Particle energy = 45 kJ.\nStep 2: Activation energy = 60 kJ.\nStep 3: Compare the two values: 45 kJ < 60 kJ.\nStep 4: The particle does not have enough energy.","steps":["Step 1: Particle energy = 45 kJ.","Step 2: Activation energy = 60 kJ.","Step 3: Compare the two values: 45 kJ < 60 kJ.","Step 4: The particle does not have enough energy."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 1),
  (2623, 661, 'The activation energy of a reaction is 80 kJ. A particle has 95 kJ of energy. Is the particle energetic enough to overcome the activation energy?', 'text', 1, 'Focus on the core principle of Activation Energy.', '{"why":"95 kJ is greater than the required 80 kJ.","sol":"Step 1: Particle energy = 95 kJ.\nStep 2: Activation energy = 80 kJ.\nStep 3: Compare: 95 kJ > 80 kJ.\nStep 4: The particle has enough energy to overcome the activation energy.","steps":["Step 1: Particle energy = 95 kJ.","Step 2: Activation energy = 80 kJ.","Step 3: Compare: 95 kJ > 80 kJ.","Step 4: The particle has enough energy to overcome the activation energy."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 2),
  (2624, 661, 'A reaction has an activation energy of 75 kJ. A particle has 70 kJ of energy. How much additional energy does it need to reach the activation energy?', 'text', 1, 'Subtract the particle''s energy from the activation energy.', '{"why":"The particle is 5 kJ below the activation energy.","sol":"Step 1: Activation energy = 75 kJ.\nStep 2: Particle energy = 70 kJ.\nStep 3: Additional energy = 75 − 70.\nStep 4: Additional energy = 5 kJ.","steps":["Step 1: Activation energy = 75 kJ.","Step 2: Particle energy = 70 kJ.","Step 3: Additional energy = 75 − 70.","Step 4: Additional energy = 5 kJ."],"options":[],"conceptId":"chemistry_rate_reactions_activation_energy","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Activation Energy"}', 3),
  (2625, 662, 'What is an effective collision?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"Only collisions satisfying the necessary energy and orientation conditions can form products.","sol":"Step 1: Reacting particles collide.\nStep 2: The particles must have sufficient energy.\nStep 3: The particles must have suitable orientation.\nStep 4: If these conditions result in reaction, the collision is effective.","steps":["Step 1: Reacting particles collide.","Step 2: The particles must have sufficient energy.","Step 3: The particles must have suitable orientation.","Step 4: If these conditions result in reaction, the collision is effective."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q1","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 0),
  (2626, 662, 'Why does increasing temperature usually increase the rate of a chemical reaction?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"More particles have sufficient energy to overcome the activation energy.","sol":"Step 1: Increasing temperature gives particles more kinetic energy.\nStep 2: Particles move faster and collide more frequently.\nStep 3: A greater fraction of particles have energy equal to or greater than the activation energy.\nStep 4: The number of effective collisions per second increases.","steps":["Step 1: Increasing temperature gives particles more kinetic energy.","Step 2: Particles move faster and collide more frequently.","Step 3: A greater fraction of particles have energy equal to or greater than the activation energy.","Step 4: The number of effective collisions per second increases."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q2","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 1),
  (2627, 662, 'How does a catalyst increase the rate of a reaction?', 'text', 1, 'Focus on the core principle of Effective Collisions.', '{"why":"Lower activation energy allows more collisions to become effective.","sol":"Step 1: A catalyst provides an alternative reaction pathway.\nStep 2: The alternative pathway has a lower activation energy.\nStep 3: More particles can reach the required energy.\nStep 4: The number of effective collisions increases.","steps":["Step 1: A catalyst provides an alternative reaction pathway.","Step 2: The alternative pathway has a lower activation energy.","Step 3: More particles can reach the required energy.","Step 4: The number of effective collisions increases."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q3","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 2),
  (2628, 662, 'A reaction is slow because only a small fraction of collisions have enough energy to react. What change could increase the number of effective collisions without changing the reactants?', 'text', 1, 'Think about a factor that lowers the energy barrier.', '{"why":"A catalyst lowers the activation energy and increases the proportion of effective collisions.","sol":"Step 1: The problem is that too few particles have enough energy to react.\nStep 2: A catalyst provides an alternative pathway.\nStep 3: The alternative pathway has lower activation energy.\nStep 4: More collisions can therefore become effective.","steps":["Step 1: The problem is that too few particles have enough energy to react.","Step 2: A catalyst provides an alternative pathway.","Step 3: The alternative pathway has lower activation energy.","Step 4: More collisions can therefore become effective."],"options":[],"conceptId":"chemistry_rate_reactions_effective_collisions","skillId":"chemistry_rate_reactions","subskillId":"chemistry_rate_reactions_q4","subject":"chemistry","chapter":"rate_reactions","topic":"Effective Collisions"}', 3),
  (2629, 663, 'What happens to energy when a chemical bond is broken?', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"Energy is required to overcome the forces holding the bonded atoms together.","sol":"Step 1: A chemical bond holds atoms together.\nStep 2: Energy must be supplied to overcome the attraction between the bonded atoms.\nStep 3: Therefore, breaking a bond absorbs energy.","steps":["Step 1: A chemical bond holds atoms together.","Step 2: Energy must be supplied to overcome the attraction between the bonded atoms.","Step 3: Therefore, breaking a bond absorbs energy."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 0),
  (2630, 663, 'A bond has a bond energy of 436 kJ/mol. What does this value mean?', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"Bond energy is the energy required to break one mole of a particular type of bond.","sol":"Step 1: The unit is kJ/mol.\nStep 2: Bond energy tells us the energy required to break one mole of the specified bonds.\nStep 3: Therefore, 436 kJ is required to break one mole of these bonds.","steps":["Step 1: The unit is kJ/mol.","Step 2: Bond energy tells us the energy required to break one mole of the specified bonds.","Step 3: Therefore, 436 kJ is required to break one mole of these bonds."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 1),
  (2631, 663, 'Which requires more energy to break: a bond with an energy of 350 kJ/mol or one with an energy of 600 kJ/mol?', 'text', 1, 'Focus on the core principle of Breaking Bonds.', '{"why":"A larger bond energy means more energy is required to break the bond.","sol":"Step 1: Compare the two bond energies.\nStep 2: 600 kJ/mol is greater than 350 kJ/mol.\nStep 3: Therefore, more energy is required to break the 600 kJ/mol bond.","steps":["Step 1: Compare the two bond energies.","Step 2: 600 kJ/mol is greater than 350 kJ/mol.","Step 3: Therefore, more energy is required to break the 600 kJ/mol bond."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 2),
  (2632, 663, 'A chemical bond has a bond energy of 410 kJ/mol. How much energy is needed to break 2 mol of these bonds?', 'text', 1, 'Multiply the bond energy by the number of moles of bonds.', '{"why":"Breaking 2 mol of bonds requires twice the energy needed to break 1 mol.","sol":"Step 1: Bond energy = 410 kJ/mol.\nStep 2: Number of moles of bonds = 2 mol.\nStep 3: Energy required = 410 × 2.\nStep 4: Energy required = 820 kJ.","steps":["Step 1: Bond energy = 410 kJ/mol.","Step 2: Number of moles of bonds = 2 mol.","Step 3: Energy required = 410 × 2.","Step 4: Energy required = 820 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_breaking_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Breaking Bonds"}', 3),
  (2633, 664, 'What happens to energy when a chemical bond is formed?', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"Bond formation releases energy as the bonded system becomes more stable.","sol":"Step 1: Separate atoms come together.\nStep 2: A chemical bond forms between them.\nStep 3: Energy is released as the new bond forms.","steps":["Step 1: Separate atoms come together.","Step 2: A chemical bond forms between them.","Step 3: Energy is released as the new bond forms."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 0),
  (2634, 664, 'A bond has a bond energy of 500 kJ/mol. What happens to energy when 1 mol of these bonds is formed?', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"The bond energy represents the energy associated with breaking the bond, and the same amount is released when the bond is formed.","sol":"Step 1: Bond energy = 500 kJ/mol.\nStep 2: Bond formation releases energy.\nStep 3: Therefore, forming 1 mol of these bonds releases 500 kJ.","steps":["Step 1: Bond energy = 500 kJ/mol.","Step 2: Bond formation releases energy.","Step 3: Therefore, forming 1 mol of these bonds releases 500 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 1),
  (2635, 664, 'Why does forming a chemical bond release energy?', 'text', 1, 'Focus on the core principle of Making Bonds.', '{"why":"The formation of the bond lowers the energy of the bonded system, releasing energy.","sol":"Step 1: Atoms interact through attractive forces.\nStep 2: Formation of the bond produces a more stable bonded arrangement.\nStep 3: The excess energy is released to the surroundings.","steps":["Step 1: Atoms interact through attractive forces.","Step 2: Formation of the bond produces a more stable bonded arrangement.","Step 3: The excess energy is released to the surroundings."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 2),
  (2636, 664, 'A reaction forms 3 mol of bonds, each with a bond energy of 250 kJ/mol. How much energy is released?', 'text', 1, 'Multiply the energy per mole by the number of moles of bonds formed.', '{"why":"Each mole releases 250 kJ, so 3 mol release 750 kJ.","sol":"Step 1: Bond energy = 250 kJ/mol.\nStep 2: Number of moles formed = 3 mol.\nStep 3: Energy released = 250 × 3.\nStep 4: Energy released = 750 kJ.","steps":["Step 1: Bond energy = 250 kJ/mol.","Step 2: Number of moles formed = 3 mol.","Step 3: Energy released = 250 × 3.","Step 4: Energy released = 750 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_making_bonds","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Making Bonds"}', 3),
  (2637, 665, 'What is the formula used to calculate energy change from bond energies?', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"Breaking bonds absorbs energy while forming bonds releases energy.","sol":"Step 1: Determine the total energy required to break the reactant bonds.\nStep 2: Determine the total energy released when the product bonds form.\nStep 3: Subtract the energy released from the energy absorbed.","steps":["Step 1: Determine the total energy required to break the reactant bonds.","Step 2: Determine the total energy released when the product bonds form.","Step 3: Subtract the energy released from the energy absorbed."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 0),
  (2638, 665, 'A reaction requires 750 kJ to break its bonds and releases 950 kJ when new bonds form. Calculate the energy change.', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"More energy is released forming bonds than is absorbed breaking bonds, so the reaction is exothermic.","sol":"Step 1: Energy absorbed = 750 kJ.\nStep 2: Energy released = 950 kJ.\nStep 3: ΔH = energy absorbed − energy released.\nStep 4: ΔH = 750 − 950.\nStep 5: ΔH = −200 kJ.","steps":["Step 1: Energy absorbed = 750 kJ.","Step 2: Energy released = 950 kJ.","Step 3: ΔH = energy absorbed − energy released.","Step 4: ΔH = 750 − 950.","Step 5: ΔH = −200 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 1),
  (2639, 665, 'A reaction absorbs 1400 kJ when bonds are broken and releases 1000 kJ when bonds are formed. Calculate ΔH and state whether the reaction is exothermic or endothermic.', 'text', 1, 'Focus on the core principle of Bond Energy Calculations.', '{"why":"More energy is absorbed breaking bonds than is released forming new bonds.","sol":"Step 1: Energy absorbed = 1400 kJ.\nStep 2: Energy released = 1000 kJ.\nStep 3: ΔH = 1400 − 1000.\nStep 4: ΔH = +400 kJ.\nStep 5: A positive ΔH indicates an endothermic reaction.","steps":["Step 1: Energy absorbed = 1400 kJ.","Step 2: Energy released = 1000 kJ.","Step 3: ΔH = 1400 − 1000.","Step 4: ΔH = +400 kJ.","Step 5: A positive ΔH indicates an endothermic reaction."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 2),
  (2640, 665, 'The total bond energy of bonds broken in a reaction is 1650 kJ and the total bond energy of bonds formed is 1900 kJ. Calculate ΔH.', 'text', 1, 'Use ΔH = bonds broken − bonds formed.', '{"why":"The negative value means more energy is released during bond formation than absorbed during bond breaking.","sol":"Step 1: Energy absorbed breaking bonds = 1650 kJ.\nStep 2: Energy released forming bonds = 1900 kJ.\nStep 3: ΔH = 1650 − 1900.\nStep 4: ΔH = −250 kJ.","steps":["Step 1: Energy absorbed breaking bonds = 1650 kJ.","Step 2: Energy released forming bonds = 1900 kJ.","Step 3: ΔH = 1650 − 1900.","Step 4: ΔH = −250 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 3),
  (2641, 665, 'A reaction has a bond-breaking energy of 2200 kJ and a bond-forming energy of 1800 kJ. Is the reaction exothermic or endothermic?', 'text', 1, 'First calculate ΔH.', '{"why":"The reaction absorbs more energy breaking bonds than it releases forming bonds.","sol":"Step 1: ΔH = 2200 − 1800.\nStep 2: ΔH = +400 kJ.\nStep 3: A positive ΔH indicates an endothermic reaction.","steps":["Step 1: ΔH = 2200 − 1800.","Step 2: ΔH = +400 kJ.","Step 3: A positive ΔH indicates an endothermic reaction."],"options":[],"conceptId":"chemistry_chemical_energetics_bond_energy_calculations","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q5","subject":"chemistry","chapter":"chemical_energetics","topic":"Bond Energy Calculations"}', 4),
  (2642, 666, 'What is a fuel?', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"The useful energy released during combustion is the main reason fuels are used.","sol":"Step 1: A fuel is a substance that can undergo combustion.\nStep 2: Combustion releases energy.\nStep 3: The released energy can be used for a useful purpose.","steps":["Step 1: A fuel is a substance that can undergo combustion.","Step 2: Combustion releases energy.","Step 3: The released energy can be used for a useful purpose."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 0),
  (2643, 666, 'What are the products of complete combustion of a hydrocarbon?', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"A hydrocarbon contains carbon and hydrogen, which form CO₂ and H₂O during complete combustion.","sol":"Step 1: Complete combustion requires a sufficient supply of oxygen.\nStep 2: The carbon in the hydrocarbon forms carbon dioxide.\nStep 3: The hydrogen forms water.","steps":["Step 1: Complete combustion requires a sufficient supply of oxygen.","Step 2: The carbon in the hydrocarbon forms carbon dioxide.","Step 3: The hydrogen forms water."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 1),
  (2644, 666, 'Write the balanced equation for the complete combustion of methane.', 'text', 1, 'Focus on the core principle of Combustion of Fuels.', '{"why":"The equation has equal numbers of carbon, hydrogen and oxygen atoms on both sides.","sol":"Step 1: Start with CH₄ + O₂ → CO₂ + H₂O.\nStep 2: Carbon is already balanced with one CO₂.\nStep 3: Four hydrogen atoms require 2H₂O.\nStep 4: The products now contain four oxygen atoms.\nStep 5: Therefore, 2O₂ are required on the reactant side.","steps":["Step 1: Start with CH₄ + O₂ → CO₂ + H₂O.","Step 2: Carbon is already balanced with one CO₂.","Step 3: Four hydrogen atoms require 2H₂O.","Step 4: The products now contain four oxygen atoms.","Step 5: Therefore, 2O₂ are required on the reactant side."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 2),
  (2645, 666, 'A hydrocarbon burns with a limited supply of oxygen. Name one poisonous product that may be formed.', 'text', 1, 'Think about incomplete combustion.', '{"why":"Incomplete combustion of hydrocarbons can produce poisonous carbon monoxide.","sol":"Step 1: Limited oxygen can cause incomplete combustion.\nStep 2: Incomplete combustion can produce carbon monoxide.\nStep 3: Carbon monoxide is poisonous.","steps":["Step 1: Limited oxygen can cause incomplete combustion.","Step 2: Incomplete combustion can produce carbon monoxide.","Step 3: Carbon monoxide is poisonous."],"options":[],"conceptId":"chemistry_chemical_energetics_combustion_of_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Combustion of Fuels"}', 3),
  (2646, 667, 'What is calorific value?', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"It allows different fuels to be compared according to the energy released per unit mass.","sol":"Step 1: Consider a unit mass of fuel.\nStep 2: Burn the fuel completely.\nStep 3: Measure the energy released.\nStep 4: This energy per unit mass is the calorific value.","steps":["Step 1: Consider a unit mass of fuel.","Step 2: Burn the fuel completely.","Step 3: Measure the energy released.","Step 4: This energy per unit mass is the calorific value."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 0),
  (2647, 667, 'A fuel has a calorific value of 35 kJ/g. How much energy is released when 20 g burns completely?', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"Each gram releases 35 kJ, so 20 g releases 700 kJ.","sol":"Step 1: Calorific value = 35 kJ/g.\nStep 2: Mass of fuel = 20 g.\nStep 3: Energy released = mass × calorific value.\nStep 4: Energy = 20 × 35.\nStep 5: Energy = 700 kJ.","steps":["Step 1: Calorific value = 35 kJ/g.","Step 2: Mass of fuel = 20 g.","Step 3: Energy released = mass × calorific value.","Step 4: Energy = 20 × 35.","Step 5: Energy = 700 kJ."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 1),
  (2648, 667, 'A fuel releases 2400 kJ when 60 g is completely burned. Calculate its calorific value.', 'text', 1, 'Focus on the core principle of Calorific Value.', '{"why":"Calorific value is the energy released per gram of fuel.","sol":"Step 1: Energy released = 2400 kJ.\nStep 2: Mass of fuel = 60 g.\nStep 3: Calorific value = energy released ÷ mass.\nStep 4: Calorific value = 2400 ÷ 60.\nStep 5: Calorific value = 40 kJ/g.","steps":["Step 1: Energy released = 2400 kJ.","Step 2: Mass of fuel = 60 g.","Step 3: Calorific value = energy released ÷ mass.","Step 4: Calorific value = 2400 ÷ 60.","Step 5: Calorific value = 40 kJ/g."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 2),
  (2649, 667, 'A fuel has a calorific value of 45 kJ/g. How much fuel is required to release 900 kJ?', 'text', 1, 'Rearrange the formula: mass = energy released ÷ calorific value.', '{"why":"20 g of the fuel releases 900 kJ at a calorific value of 45 kJ/g.","sol":"Step 1: Energy required = 900 kJ.\nStep 2: Calorific value = 45 kJ/g.\nStep 3: Mass = 900 ÷ 45.\nStep 4: Mass = 20 g.","steps":["Step 1: Energy required = 900 kJ.","Step 2: Calorific value = 45 kJ/g.","Step 3: Mass = 900 ÷ 45.","Step 4: Mass = 20 g."],"options":[],"conceptId":"chemistry_chemical_energetics_calorific_value","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Calorific Value"}', 3),
  (2650, 668, 'Fuel A has a calorific value of 45 kJ/g while fuel B has a calorific value of 30 kJ/g. Which fuel releases more energy when 10 g of each is completely burned?', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"Fuel A has the higher calorific value.","sol":"Step 1: Energy from A = 10 × 45.\nStep 2: Energy from A = 450 kJ.\nStep 3: Energy from B = 10 × 30.\nStep 4: Energy from B = 300 kJ.\nStep 5: Compare the two values.","steps":["Step 1: Energy from A = 10 × 45.","Step 2: Energy from A = 450 kJ.","Step 3: Energy from B = 10 × 30.","Step 4: Energy from B = 300 kJ.","Step 5: Compare the two values."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q1","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 0),
  (2651, 668, 'Why is calorific value useful when comparing fuels?', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"Calorific value provides a common measure of the energy content of fuels.","sol":"Step 1: Calorific value measures energy released per unit mass.\nStep 2: Fuels can therefore be compared using the same mass basis.\nStep 3: A higher calorific value means more energy is released per unit mass.","steps":["Step 1: Calorific value measures energy released per unit mass.","Step 2: Fuels can therefore be compared using the same mass basis.","Step 3: A higher calorific value means more energy is released per unit mass."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q2","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 1),
  (2652, 668, 'Give two factors other than calorific value that should be considered when selecting a fuel.', 'text', 1, 'Focus on the core principle of Comparing Fuels.', '{"why":"A fuel with a high calorific value may still be unsuitable if it is expensive, unsafe, unavailable or highly polluting.","sol":"Step 1: Consider the environmental effects of combustion.\nStep 2: Consider practical factors such as cost, availability or safety.\nStep 3: Therefore, fuel selection should consider more than energy output.","steps":["Step 1: Consider the environmental effects of combustion.","Step 2: Consider practical factors such as cost, availability or safety.","Step 3: Therefore, fuel selection should consider more than energy output."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q3","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 2),
  (2653, 668, 'Fuel A has a calorific value of 50 kJ/g and fuel B has a calorific value of 40 kJ/g. Which fuel requires less mass to release 2000 kJ?', 'text', 1, 'Calculate the mass required for each fuel using mass = energy ÷ calorific value.', '{"why":"Fuel A has the higher calorific value, so less mass is needed to release the same amount of energy.","sol":"Step 1: Mass of A = 2000 ÷ 50 = 40 g.\nStep 2: Mass of B = 2000 ÷ 40 = 50 g.\nStep 3: Compare the masses.\nStep 4: Fuel A requires less mass.","steps":["Step 1: Mass of A = 2000 ÷ 50 = 40 g.","Step 2: Mass of B = 2000 ÷ 40 = 50 g.","Step 3: Compare the masses.","Step 4: Fuel A requires less mass."],"options":[],"conceptId":"chemistry_chemical_energetics_comparing_fuels","skillId":"chemistry_chemical_energetics","subskillId":"chemistry_chemical_energetics_q4","subject":"chemistry","chapter":"chemical_energetics","topic":"Comparing Fuels"}', 3),
  (2654, 669, 'What is bauxite?', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"Bauxite contains aluminium compounds that can be processed to obtain aluminium oxide.","sol":"Step 1: Aluminium occurs naturally combined with other elements.\nStep 2: The main ore containing aluminium compounds is bauxite.\nStep 3: Therefore, bauxite is the main ore used to obtain aluminium.","steps":["Step 1: Aluminium occurs naturally combined with other elements.","Step 2: The main ore containing aluminium compounds is bauxite.","Step 3: Therefore, bauxite is the main ore used to obtain aluminium."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 0),
  (2655, 669, 'Why is aluminium not extracted from its ore by heating it with carbon?', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"The high reactivity of aluminium makes electrolysis necessary for its extraction.","sol":"Step 1: Aluminium is a very reactive metal.\nStep 2: Aluminium has a stronger attraction to oxygen than carbon can overcome under ordinary extraction conditions.\nStep 3: Therefore, carbon cannot effectively reduce aluminium oxide to aluminium.\nStep 4: Aluminium is instead extracted by electrolysis.","steps":["Step 1: Aluminium is a very reactive metal.","Step 2: Aluminium has a stronger attraction to oxygen than carbon can overcome under ordinary extraction conditions.","Step 3: Therefore, carbon cannot effectively reduce aluminium oxide to aluminium.","Step 4: Aluminium is instead extracted by electrolysis."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 1),
  (2656, 669, 'State the main ore used in the extraction of aluminium.', 'text', 1, 'Focus on the core principle of Bauxite.', '{"why":"Bauxite is the principal ore used as the source of aluminium.","sol":"Step 1: Identify the principal naturally occurring aluminium ore.\nStep 2: The ore is bauxite.","steps":["Step 1: Identify the principal naturally occurring aluminium ore.","Step 2: The ore is bauxite."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 2),
  (2657, 669, 'An ore contains aluminium compounds mixed with several impurities. What is the first major processing step before aluminium can be extracted by electrolysis?', 'text', 1, 'The aluminium compound must first be separated from the impurities.', '{"why":"Impurities must be removed before aluminium oxide is subjected to electrolysis.","sol":"Step 1: The ore is bauxite.\nStep 2: Bauxite contains aluminium compounds and impurities.\nStep 3: The ore must therefore be purified.\nStep 4: Purification produces aluminium oxide suitable for the extraction process.","steps":["Step 1: The ore is bauxite.","Step 2: Bauxite contains aluminium compounds and impurities.","Step 3: The ore must therefore be purified.","Step 4: Purification produces aluminium oxide suitable for the extraction process."],"options":[],"conceptId":"chemistry_metals_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Bauxite"}', 3),
  (2658, 670, 'What is the main product obtained when bauxite is purified for aluminium extraction?', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"Aluminium oxide is the compound used in the electrolytic extraction of aluminium.","sol":"Step 1: Bauxite contains aluminium compounds and impurities.\nStep 2: The unwanted impurities are removed.\nStep 3: The aluminium-containing material is processed to obtain aluminium oxide.","steps":["Step 1: Bauxite contains aluminium compounds and impurities.","Step 2: The unwanted impurities are removed.","Step 3: The aluminium-containing material is processed to obtain aluminium oxide."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 0),
  (2659, 670, 'Why must bauxite be purified before electrolysis?', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"The extraction stage requires aluminium oxide rather than untreated ore containing unwanted materials.","sol":"Step 1: Raw bauxite contains impurities.\nStep 2: The desired aluminium compound is aluminium oxide.\nStep 3: Removing impurities gives a more suitable material for the electrolytic process.","steps":["Step 1: Raw bauxite contains impurities.","Step 2: The desired aluminium compound is aluminium oxide.","Step 3: Removing impurities gives a more suitable material for the electrolytic process."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 1),
  (2660, 670, 'Write the chemical formula of aluminium oxide.', 'text', 1, 'Focus on the core principle of Purification of Bauxite.', '{"why":"Two aluminium ions and three oxide ions give an overall neutral compound.","sol":"Step 1: Aluminium forms Al³⁺ ions.\nStep 2: Oxygen forms O²⁻ ions.\nStep 3: The charges must balance.\nStep 4: Two Al³⁺ ions give +6 and three O²⁻ ions give −6.\nStep 5: Therefore, the formula is Al₂O₃.","steps":["Step 1: Aluminium forms Al³⁺ ions.","Step 2: Oxygen forms O²⁻ ions.","Step 3: The charges must balance.","Step 4: Two Al³⁺ ions give +6 and three O²⁻ ions give −6.","Step 5: Therefore, the formula is Al₂O₃."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 2),
  (2661, 670, 'A sample of bauxite contains aluminium oxide and unwanted impurities. What should happen to the impurities before electrolysis?', 'text', 1, 'Think about what purification means.', '{"why":"Purification separates the aluminium-containing material from unwanted substances.","sol":"Step 1: Identify the desired substance: aluminium oxide.\nStep 2: The remaining substances are impurities.\nStep 3: Purification removes the unwanted substances.\nStep 4: The aluminium oxide is then used in the extraction stage.","steps":["Step 1: Identify the desired substance: aluminium oxide.","Step 2: The remaining substances are impurities.","Step 3: Purification removes the unwanted substances.","Step 4: The aluminium oxide is then used in the extraction stage."],"options":[],"conceptId":"chemistry_metals_purification_of_bauxite","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Purification of Bauxite"}', 3),
  (2662, 671, 'Why is aluminium extracted by electrolysis rather than reduction with carbon?', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Electrolysis provides the energy needed to reduce Al³⁺ ions to aluminium metal.","sol":"Step 1: Aluminium is very reactive.\nStep 2: Aluminium oxide is too stable to be effectively reduced by carbon.\nStep 3: Electrolysis supplies electrical energy to reduce aluminium ions.\nStep 4: Aluminium metal is therefore obtained at the cathode.","steps":["Step 1: Aluminium is very reactive.","Step 2: Aluminium oxide is too stable to be effectively reduced by carbon.","Step 3: Electrolysis supplies electrical energy to reduce aluminium ions.","Step 4: Aluminium metal is therefore obtained at the cathode."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 0),
  (2663, 671, 'Write the half-equation for the formation of aluminium at the cathode.', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Aluminium ions gain three electrons to become neutral aluminium atoms.","sol":"Step 1: Aluminium ions are Al³⁺.\nStep 2: The cathode is where reduction occurs.\nStep 3: Reduction involves gaining electrons.\nStep 4: Each Al³⁺ ion requires three electrons.\nStep 5: Therefore, Al³⁺ + 3e⁻ → Al.","steps":["Step 1: Aluminium ions are Al³⁺.","Step 2: The cathode is where reduction occurs.","Step 3: Reduction involves gaining electrons.","Step 4: Each Al³⁺ ion requires three electrons.","Step 5: Therefore, Al³⁺ + 3e⁻ → Al."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 1),
  (2664, 671, 'What happens to oxide ions at the anode during the electrolysis of aluminium oxide?', 'text', 1, 'Focus on the core principle of Electrolysis of Aluminium Oxide.', '{"why":"Oxide ions lose electrons at the positive anode.","sol":"Step 1: Oxide ions are O²⁻.\nStep 2: The anode is where oxidation occurs.\nStep 3: Oxide ions lose electrons.\nStep 4: The oxide ions form oxygen.","steps":["Step 1: Oxide ions are O²⁻.","Step 2: The anode is where oxidation occurs.","Step 3: Oxide ions lose electrons.","Step 4: The oxide ions form oxygen."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 2),
  (2665, 671, 'During aluminium extraction, a student writes the cathode reaction as Al³⁺ → Al + 3e⁻. What is wrong with this equation?', 'text', 1, 'Reduction at the cathode involves gaining electrons, not losing them.', '{"why":"Aluminium ions are reduced at the cathode by gaining three electrons.","sol":"Step 1: The cathode is the site of reduction.\nStep 2: Reduction means gain of electrons.\nStep 3: Al³⁺ must gain three electrons.\nStep 4: The correct equation is Al³⁺ + 3e⁻ → Al.","steps":["Step 1: The cathode is the site of reduction.","Step 2: Reduction means gain of electrons.","Step 3: Al³⁺ must gain three electrons.","Step 4: The correct equation is Al³⁺ + 3e⁻ → Al."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 3),
  (2666, 671, 'Why do the carbon anodes used in aluminium extraction gradually become smaller?', 'text', 1, 'Consider what happens to oxide ions at the anode.', '{"why":"The carbon anodes are oxidised by the oxygen formed during electrolysis.","sol":"Step 1: Oxide ions are discharged at the anode.\nStep 2: Oxygen is produced.\nStep 3: The oxygen reacts with the carbon anode.\nStep 4: Carbon is converted into carbon oxides and the anode is gradually consumed.","steps":["Step 1: Oxide ions are discharged at the anode.","Step 2: Oxygen is produced.","Step 3: The oxygen reacts with the carbon anode.","Step 4: Carbon is converted into carbon oxides and the anode is gradually consumed."],"options":[],"conceptId":"chemistry_metals_electrolysis_of_aluminium_oxide","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Electrolysis of Aluminium Oxide"}', 4),
  (2667, 672, 'What is formed when magnesium reacts with oxygen?', 'text', 1, 'Focus on the core principle of Chemical Properties of Metals.', '{"why":"Magnesium combines with oxygen to form the metal oxide magnesium oxide.","sol":"Step 1: Magnesium reacts with oxygen.\nStep 2: Metals commonly form oxides when they react with oxygen.\nStep 3: Therefore, magnesium oxide is formed.\nStep 4: The balanced equation is 2Mg + O₂ → 2MgO.","steps":["Step 1: Magnesium reacts with oxygen.","Step 2: Metals commonly form oxides when they react with oxygen.","Step 3: Therefore, magnesium oxide is formed.","Step 4: The balanced equation is 2Mg + O₂ → 2MgO."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 0),
  (2668, 672, 'What products are formed when sodium reacts with water?', 'text', 1, 'Focus on the core principle of Chemical Properties of Metals.', '{"why":"Reactive metals such as sodium react with water to form a metal hydroxide and hydrogen.","sol":"Step 1: Sodium is a very reactive metal.\nStep 2: Sodium reacts with water.\nStep 3: The products are sodium hydroxide and hydrogen gas.\nStep 4: The balanced equation is 2Na + 2H₂O → 2NaOH + H₂.","steps":["Step 1: Sodium is a very reactive metal.","Step 2: Sodium reacts with water.","Step 3: The products are sodium hydroxide and hydrogen gas.","Step 4: The balanced equation is 2Na + 2H₂O → 2NaOH + H₂."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 1),
  (2669, 672, 'What products are formed when zinc reacts with dilute hydrochloric acid?', 'text', 1, 'Focus on the core principle of Chemical Properties of Metals.', '{"why":"Zinc reacts with dilute hydrochloric acid to form zinc chloride and hydrogen.","sol":"Step 1: Zinc is above hydrogen in the reactivity series.\nStep 2: Zinc can therefore displace hydrogen from dilute hydrochloric acid.\nStep 3: Zinc chloride is formed as the salt.\nStep 4: Hydrogen gas is released.\nStep 5: The balanced equation is Zn + 2HCl → ZnCl₂ + H₂.","steps":["Step 1: Zinc is above hydrogen in the reactivity series.","Step 2: Zinc can therefore displace hydrogen from dilute hydrochloric acid.","Step 3: Zinc chloride is formed as the salt.","Step 4: Hydrogen gas is released.","Step 5: The balanced equation is Zn + 2HCl → ZnCl₂ + H₂."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 2),
  (2670, 672, 'A metal reacts vigorously with water and produces hydrogen gas. What does this suggest about its reactivity?', 'text', 1, 'Compare its behaviour with metals that react slowly or not at all with water.', '{"why":"A vigorous reaction with water indicates high chemical reactivity.","sol":"Step 1: The metal reacts readily with water.\nStep 2: Vigorous reaction indicates that the metal readily undergoes chemical change.\nStep 3: Therefore, the metal is relatively reactive.","steps":["Step 1: The metal reacts readily with water.","Step 2: Vigorous reaction indicates that the metal readily undergoes chemical change.","Step 3: Therefore, the metal is relatively reactive."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 3),
  (2671, 672, 'A metal reacts with dilute hydrochloric acid and produces hydrogen gas. What does this tell you about its position relative to hydrogen in the reactivity series?', 'text', 1, 'A metal must be able to displace hydrogen from the acid.', '{"why":"Only metals more reactive than hydrogen can generally displace hydrogen from dilute acids.","sol":"Step 1: The metal reacts with hydrochloric acid and releases hydrogen.\nStep 2: This means the metal displaces hydrogen from the acid.\nStep 3: Metals that displace hydrogen are above hydrogen in the reactivity series.","steps":["Step 1: The metal reacts with hydrochloric acid and releases hydrogen.","Step 2: This means the metal displaces hydrogen from the acid.","Step 3: Metals that displace hydrogen are above hydrogen in the reactivity series."],"options":[],"conceptId":"chemistry_metals_chemical_properties_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Chemical Properties of Metals"}', 4),
  (2672, 673, 'What is an ore?', 'text', 1, 'Focus on the core principle of Concentration of Ores.', '{"why":"Ores contain minerals from which metals can be obtained.","sol":"Step 1: An ore contains a naturally occurring mineral from which a metal can be obtained.\nStep 2: The useful mineral occurs together with unwanted materials.\nStep 3: Therefore, an ore is a naturally occurring material from which a metal can be extracted economically.","steps":["Step 1: An ore contains a naturally occurring mineral from which a metal can be obtained.","Step 2: The useful mineral occurs together with unwanted materials.","Step 3: Therefore, an ore is a naturally occurring material from which a metal can be extracted economically."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 0),
  (2673, 673, 'What is gangue?', 'text', 1, 'Focus on the core principle of Concentration of Ores.', '{"why":"Gangue has no useful value in the extraction of the desired metal and is removed during ore processing.","sol":"Step 1: An ore contains the useful mineral together with unwanted materials.\nStep 2: These unwanted earthy or rocky materials are called gangue.","steps":["Step 1: An ore contains the useful mineral together with unwanted materials.","Step 2: These unwanted earthy or rocky materials are called gangue."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 1),
  (2674, 673, 'Why is an ore concentrated before the metal is extracted?', 'text', 1, 'Focus on the core principle of Concentration of Ores.', '{"why":"Concentration makes the subsequent extraction process more efficient.","sol":"Step 1: An ore contains useful mineral and unwanted gangue.\nStep 2: Concentration removes some of the gangue.\nStep 3: This increases the proportion of useful mineral.\nStep 4: Less unwanted material then has to be processed during extraction.","steps":["Step 1: An ore contains useful mineral and unwanted gangue.","Step 2: Concentration removes some of the gangue.","Step 3: This increases the proportion of useful mineral.","Step 4: Less unwanted material then has to be processed during extraction."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 2),
  (2675, 673, 'An ore contains a magnetic mineral mixed with non-magnetic gangue. Which separation method could be used?', 'text', 1, 'Think about a method that separates substances according to magnetic properties.', '{"why":"Magnetic separation works when the useful mineral and gangue have different magnetic properties.","sol":"Step 1: The useful mineral is magnetic.\nStep 2: The gangue is non-magnetic.\nStep 3: A magnetic field can attract the magnetic material while leaving the non-magnetic material behind.\nStep 4: Therefore, magnetic separation can be used.","steps":["Step 1: The useful mineral is magnetic.","Step 2: The gangue is non-magnetic.","Step 3: A magnetic field can attract the magnetic material while leaving the non-magnetic material behind.","Step 4: Therefore, magnetic separation can be used."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 3),
  (2676, 673, 'What happens to the proportion of useful mineral when gangue is removed from an ore?', 'text', 1, 'Compare the amount of useful mineral with the total mass of the ore.', '{"why":"Removing gangue concentrates the useful mineral in the remaining material.","sol":"Step 1: Gangue is unwanted material.\nStep 2: Removing gangue decreases the amount of unwanted material.\nStep 3: The useful mineral therefore makes up a greater proportion of the remaining material.","steps":["Step 1: Gangue is unwanted material.","Step 2: Removing gangue decreases the amount of unwanted material.","Step 3: The useful mineral therefore makes up a greater proportion of the remaining material."],"options":[],"conceptId":"chemistry_metals_concentration_of_ores","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Concentration of Ores"}', 4),
  (2677, 674, 'What is reduction in the extraction of a metal from its oxide?', 'text', 1, 'Focus on the core principle of Extraction by Reduction.', '{"why":"Removing oxygen from a metal oxide produces the metal.","sol":"Step 1: A metal oxide contains the metal chemically combined with oxygen.\nStep 2: During reduction, oxygen is removed from the oxide.\nStep 3: The metal is therefore obtained from its oxide.","steps":["Step 1: A metal oxide contains the metal chemically combined with oxygen.","Step 2: During reduction, oxygen is removed from the oxide.","Step 3: The metal is therefore obtained from its oxide."],"options":[],"conceptId":"chemistry_metals_extraction_by_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Extraction by Reduction"}', 0),
  (2678, 674, 'How can zinc be extracted from zinc oxide using carbon?', 'text', 1, 'Focus on the core principle of Extraction by Reduction.', '{"why":"Carbon removes oxygen from zinc oxide, reducing ZnO to zinc.","sol":"Step 1: Zinc oxide is ZnO.\nStep 2: Carbon acts as the reducing agent.\nStep 3: Carbon removes oxygen from zinc oxide.\nStep 4: Zinc metal is produced.\nStep 5: The balanced equation is ZnO + C → Zn + CO.","steps":["Step 1: Zinc oxide is ZnO.","Step 2: Carbon acts as the reducing agent.","Step 3: Carbon removes oxygen from zinc oxide.","Step 4: Zinc metal is produced.","Step 5: The balanced equation is ZnO + C → Zn + CO."],"options":[],"conceptId":"chemistry_metals_extraction_by_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Extraction by Reduction"}', 1),
  (2679, 674, 'What happens to carbon monoxide when it reduces iron(III) oxide?', 'text', 1, 'Focus on the core principle of Extraction by Reduction.', '{"why":"CO removes oxygen from iron(III) oxide and therefore becomes CO₂.","sol":"Step 1: Carbon monoxide reacts with iron(III) oxide.\nStep 2: It removes oxygen from the iron oxide.\nStep 3: Carbon monoxide gains oxygen.\nStep 4: It is converted into carbon dioxide.","steps":["Step 1: Carbon monoxide reacts with iron(III) oxide.","Step 2: It removes oxygen from the iron oxide.","Step 3: Carbon monoxide gains oxygen.","Step 4: It is converted into carbon dioxide."],"options":[],"conceptId":"chemistry_metals_extraction_by_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Extraction by Reduction"}', 2),
  (2680, 674, 'A metal oxide reacts with carbon and produces the metal. What role does carbon play?', 'text', 1, 'Carbon removes oxygen from the metal oxide.', '{"why":"The reducing agent removes oxygen from the metal oxide.","sol":"Step 1: Carbon removes oxygen from the metal oxide.\nStep 2: Removing oxygen from an oxide is reduction.\nStep 3: Therefore, carbon acts as the reducing agent.","steps":["Step 1: Carbon removes oxygen from the metal oxide.","Step 2: Removing oxygen from an oxide is reduction.","Step 3: Therefore, carbon acts as the reducing agent."],"options":[],"conceptId":"chemistry_metals_extraction_by_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Extraction by Reduction"}', 3),
  (2681, 674, 'Why is aluminium not normally extracted by heating aluminium oxide with carbon?', 'text', 1, 'Compare aluminium''s position with carbon in the reactivity series.', '{"why":"Highly reactive metals such as aluminium require electrolysis rather than ordinary carbon reduction.","sol":"Step 1: Aluminium is more reactive than carbon.\nStep 2: Carbon cannot readily remove oxygen from aluminium oxide.\nStep 3: Therefore, carbon reduction is not suitable for extracting aluminium.\nStep 4: Aluminium oxide is instead extracted by electrolysis.","steps":["Step 1: Aluminium is more reactive than carbon.","Step 2: Carbon cannot readily remove oxygen from aluminium oxide.","Step 3: Therefore, carbon reduction is not suitable for extracting aluminium.","Step 4: Aluminium oxide is instead extracted by electrolysis."],"options":[],"conceptId":"chemistry_metals_extraction_by_reduction","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Extraction by Reduction"}', 4),
  (2682, 675, 'What is the main ore used to extract iron?', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"Haematite is an important iron ore containing iron(III) oxide.","sol":"Step 1: Iron is extracted from an iron-containing ore.\nStep 2: The main ore used in the blast furnace is haematite.\nStep 3: Haematite contains iron(III) oxide, Fe₂O₃.","steps":["Step 1: Iron is extracted from an iron-containing ore.","Step 2: The main ore used in the blast furnace is haematite.","Step 3: Haematite contains iron(III) oxide, Fe₂O₃."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 0),
  (2683, 675, 'What is the role of carbon monoxide in the extraction of iron?', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"Carbon monoxide reduces iron(III) oxide to iron.","sol":"Step 1: Iron ore contains iron(III) oxide.\nStep 2: Carbon monoxide reacts with iron(III) oxide.\nStep 3: Carbon monoxide removes oxygen from the iron oxide.\nStep 4: Iron is produced.\nStep 5: Fe₂O₃ + 3CO → 2Fe + 3CO₂.","steps":["Step 1: Iron ore contains iron(III) oxide.","Step 2: Carbon monoxide reacts with iron(III) oxide.","Step 3: Carbon monoxide removes oxygen from the iron oxide.","Step 4: Iron is produced.","Step 5: Fe₂O₃ + 3CO → 2Fe + 3CO₂."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 1),
  (2684, 675, 'What is the purpose of limestone in the blast furnace?', 'text', 1, 'Focus on the core principle of Extraction of Iron.', '{"why":"Limestone produces calcium oxide, which reacts with silica to form calcium silicate slag.","sol":"Step 1: Limestone decomposes to form calcium oxide.\nStep 2: Calcium oxide reacts with silica impurity.\nStep 3: Calcium silicate, called slag, is formed.\nStep 4: The slag can then be separated from the molten iron.","steps":["Step 1: Limestone decomposes to form calcium oxide.","Step 2: Calcium oxide reacts with silica impurity.","Step 3: Calcium silicate, called slag, is formed.","Step 4: The slag can then be separated from the molten iron."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 2),
  (2685, 675, 'A blast furnace produces iron and slag. What is the function of the slag?', 'text', 1, 'Think about the impurities removed from the iron ore.', '{"why":"Slag carries unwanted impurities away from the iron during extraction.","sol":"Step 1: Iron ore contains impurities such as silica.\nStep 2: Calcium oxide from limestone reacts with silica.\nStep 3: Calcium silicate is formed.\nStep 4: This calcium silicate is slag and can be separated from the iron.","steps":["Step 1: Iron ore contains impurities such as silica.","Step 2: Calcium oxide from limestone reacts with silica.","Step 3: Calcium silicate is formed.","Step 4: This calcium silicate is slag and can be separated from the iron."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 3),
  (2686, 675, 'Write the equation for the reduction of iron(III) oxide by carbon monoxide.', 'text', 1, 'Iron(III) oxide is Fe₂O₃ and carbon monoxide is CO.', '{"why":"Carbon monoxide removes oxygen from iron(III) oxide to produce iron and carbon dioxide.","sol":"Step 1: Write the reactants: Fe₂O₃ + CO.\nStep 2: Iron(III) oxide is reduced to iron.\nStep 3: Carbon monoxide is oxidised to carbon dioxide.\nStep 4: Balance the equation.\nStep 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂.","steps":["Step 1: Write the reactants: Fe₂O₃ + CO.","Step 2: Iron(III) oxide is reduced to iron.","Step 3: Carbon monoxide is oxidised to carbon dioxide.","Step 4: Balance the equation.","Step 5: The balanced equation is Fe₂O₃ + 3CO → 2Fe + 3CO₂."],"options":[],"conceptId":"chemistry_metals_extraction_of_iron","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Extraction of Iron"}', 4),
  (2687, 676, 'What is rusting?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Rusting is a chemical reaction involving iron, oxygen and water.","sol":"Step 1: Iron reacts slowly with substances in its surroundings.\nStep 2: Oxygen and water are required for the process.\nStep 3: A new substance called rust is formed.","steps":["Step 1: Iron reacts slowly with substances in its surroundings.","Step 2: Oxygen and water are required for the process.","Step 3: A new substance called rust is formed."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 0),
  (2688, 676, 'What two substances are required for iron to rust?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Both oxygen and water are necessary for ordinary rusting of iron.","sol":"Step 1: Rusting requires oxygen.\nStep 2: Rusting also requires water.\nStep 3: Therefore, both oxygen and water must be available for normal rusting to occur.","steps":["Step 1: Rusting requires oxygen.","Step 2: Rusting also requires water.","Step 3: Therefore, both oxygen and water must be available for normal rusting to occur."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 1),
  (2689, 676, 'Why is rusting classified as a chemical change?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Chemical changes involve the formation of new substances.","sol":"Step 1: Iron reacts with oxygen and water.\nStep 2: A new substance, rust, is formed.\nStep 3: Formation of a new substance indicates a chemical change.","steps":["Step 1: Iron reacts with oxygen and water.","Step 2: A new substance, rust, is formed.","Step 3: Formation of a new substance indicates a chemical change."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 2),
  (2690, 676, 'An iron nail is kept in completely dry air. Will it rust normally? Explain.', 'text', 1, 'Rusting requires both oxygen and water.', '{"why":"Oxygen alone is not sufficient for ordinary rusting; water is also required.","sol":"Step 1: Dry air contains oxygen but essentially no liquid water.\nStep 2: Rusting requires water as well as oxygen.\nStep 3: Therefore, the absence of water prevents normal rusting.","steps":["Step 1: Dry air contains oxygen but essentially no liquid water.","Step 2: Rusting requires water as well as oxygen.","Step 3: Therefore, the absence of water prevents normal rusting."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 3),
  (2691, 676, 'Why can rusting cause an iron structure to become weaker?', 'text', 1, 'Think about what happens to the original iron as rust forms.', '{"why":"Corrosion can reduce the amount and structural strength of iron.","sol":"Step 1: Rusting converts iron into corrosion products.\nStep 2: The original metal is gradually lost.\nStep 3: Continued rusting reduces the effective amount and strength of the iron.","steps":["Step 1: Rusting converts iron into corrosion products.","Step 2: The original metal is gradually lost.","Step 3: Continued rusting reduces the effective amount and strength of the iron."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 4),
  (2692, 676, 'What is rusting?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Rusting is a chemical reaction involving iron, oxygen and water.","sol":"Step 1: Iron reacts slowly with substances in its surroundings.\nStep 2: Oxygen and water are required for the process.\nStep 3: A new substance called rust is formed.","steps":["Step 1: Iron reacts slowly with substances in its surroundings.","Step 2: Oxygen and water are required for the process.","Step 3: A new substance called rust is formed."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q6","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 5),
  (2693, 676, 'What two substances are required for iron to rust?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Both oxygen and water are necessary for ordinary rusting of iron.","sol":"Step 1: Rusting requires oxygen.\nStep 2: Rusting also requires water.\nStep 3: Therefore, both oxygen and water must be available for normal rusting to occur.","steps":["Step 1: Rusting requires oxygen.","Step 2: Rusting also requires water.","Step 3: Therefore, both oxygen and water must be available for normal rusting to occur."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q7","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 6),
  (2694, 676, 'Why is rusting classified as a chemical change?', 'text', 1, 'Focus on the core principle of Rusting.', '{"why":"Chemical changes involve the formation of new substances.","sol":"Step 1: Iron reacts with oxygen and water.\nStep 2: A new substance, rust, is formed.\nStep 3: Formation of a new substance indicates a chemical change.","steps":["Step 1: Iron reacts with oxygen and water.","Step 2: A new substance, rust, is formed.","Step 3: Formation of a new substance indicates a chemical change."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q8","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 7),
  (2695, 676, 'An iron nail is kept in completely dry air. Will it rust normally? Explain.', 'text', 1, 'Rusting requires both oxygen and water.', '{"why":"Oxygen alone is not sufficient for ordinary rusting; water is also required.","sol":"Step 1: Dry air contains oxygen but essentially no liquid water.\nStep 2: Rusting requires water as well as oxygen.\nStep 3: Therefore, the absence of water prevents normal rusting.","steps":["Step 1: Dry air contains oxygen but essentially no liquid water.","Step 2: Rusting requires water as well as oxygen.","Step 3: Therefore, the absence of water prevents normal rusting."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q9","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 8),
  (2696, 676, 'Why can rusting cause an iron structure to become weaker?', 'text', 1, 'Think about what happens to the original iron as rust forms.', '{"why":"Corrosion can reduce the amount and structural strength of iron.","sol":"Step 1: Rusting converts iron into corrosion products.\nStep 2: The original metal is gradually lost.\nStep 3: Continued rusting reduces the effective amount and strength of the iron.","steps":["Step 1: Rusting converts iron into corrosion products.","Step 2: The original metal is gradually lost.","Step 3: Continued rusting reduces the effective amount and strength of the iron."],"options":[],"conceptId":"chemistry_metals_rusting","skillId":"chemistry_metals","subskillId":"chemistry_metals_q10","subject":"chemistry","chapter":"metals","topic":"Rusting"}', 9),
  (2697, 677, 'What is an alloy?', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Alloys are produced by combining metals with other elements to obtain useful properties.","sol":"Step 1: An alloy contains a metal mixed with one or more other elements.\nStep 2: The mixture is made to obtain useful properties.\nStep 3: Therefore, an alloy is a mixture containing a metal and other element or elements.","steps":["Step 1: An alloy contains a metal mixed with one or more other elements.","Step 2: The mixture is made to obtain useful properties.","Step 3: Therefore, an alloy is a mixture containing a metal and other element or elements."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 0),
  (2698, 677, 'What elements are mainly present in brass?', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Brass is an alloy mainly composed of copper and zinc.","sol":"Step 1: Brass is a common copper alloy.\nStep 2: Its main components are copper and zinc.","steps":["Step 1: Brass is a common copper alloy.","Step 2: Its main components are copper and zinc."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 1),
  (2699, 677, 'What elements are mainly present in bronze?', 'text', 1, 'Focus on the core principle of Alloys.', '{"why":"Bronze is mainly an alloy of copper and tin.","sol":"Step 1: Bronze is a copper alloy.\nStep 2: Its main added element is tin.","steps":["Step 1: Bronze is a copper alloy.","Step 2: Its main added element is tin."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 2),
  (2700, 677, 'Why can an alloy be harder or stronger than the pure metal from which it is made?', 'text', 1, 'Think about how atoms of different sizes affect the arrangement of metal atoms.', '{"why":"The disrupted structure of an alloy can resist deformation more effectively than a pure metal.","sol":"Step 1: Pure metal atoms form regular layers.\nStep 2: These layers can slide over one another.\nStep 3: Atoms of different sizes in an alloy disturb the regular arrangement.\nStep 4: The layers therefore find it more difficult to slide.\nStep 5: This can make the alloy harder or stronger.","steps":["Step 1: Pure metal atoms form regular layers.","Step 2: These layers can slide over one another.","Step 3: Atoms of different sizes in an alloy disturb the regular arrangement.","Step 4: The layers therefore find it more difficult to slide.","Step 5: This can make the alloy harder or stronger."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 3),
  (2701, 677, 'A material must be strong, relatively light and suitable for aircraft construction. Why could an aluminium alloy such as duralumin be preferred to pure aluminium?', 'text', 1, 'Compare the strength of an alloy with the properties of pure aluminium.', '{"why":"Alloying can improve the strength of aluminium without losing its advantage of relatively low density.","sol":"Step 1: Pure aluminium has the advantage of low density.\nStep 2: An alloy such as duralumin is stronger while remaining relatively light.\nStep 3: Aircraft construction requires materials that combine low mass with sufficient strength.\nStep 4: Therefore, duralumin can be more suitable than pure aluminium.","steps":["Step 1: Pure aluminium has the advantage of low density.","Step 2: An alloy such as duralumin is stronger while remaining relatively light.","Step 3: Aircraft construction requires materials that combine low mass with sufficient strength.","Step 4: Therefore, duralumin can be more suitable than pure aluminium."],"options":[],"conceptId":"chemistry_metals_alloys","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Alloys"}', 4),
  (2702, 678, 'Why is copper commonly used for electrical wiring?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Good electrical conductivity and ductility make copper suitable for electrical wiring.","sol":"Step 1: Electrical wires need a material that allows electric current to pass through easily.\nStep 2: Copper is a good conductor of electricity.\nStep 3: Copper is also ductile, so it can be drawn into wires.\nStep 4: Therefore, copper is suitable for electrical wiring.","steps":["Step 1: Electrical wires need a material that allows electric current to pass through easily.","Step 2: Copper is a good conductor of electricity.","Step 3: Copper is also ductile, so it can be drawn into wires.","Step 4: Therefore, copper is suitable for electrical wiring."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q1","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 0),
  (2703, 678, 'Why is aluminium suitable for aircraft construction?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Low density and suitable strength make aluminium alloys useful in aircraft construction.","sol":"Step 1: Aircraft construction requires materials with relatively low mass.\nStep 2: Aluminium has a low density.\nStep 3: Aluminium can also be made into strong alloys.\nStep 4: Therefore, aluminium alloys can provide useful strength without excessive mass.","steps":["Step 1: Aircraft construction requires materials with relatively low mass.","Step 2: Aluminium has a low density.","Step 3: Aluminium can also be made into strong alloys.","Step 4: Therefore, aluminium alloys can provide useful strength without excessive mass."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q2","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 1),
  (2704, 678, 'Why are iron and steel widely used in construction?', 'text', 1, 'Focus on the core principle of Uses of Metals.', '{"why":"Their strength makes them suitable for structures, machinery and other heavy-duty applications.","sol":"Step 1: Construction materials need to withstand large forces.\nStep 2: Iron and steel have high strength.\nStep 3: They can therefore support heavy loads and form strong structures.","steps":["Step 1: Construction materials need to withstand large forces.","Step 2: Iron and steel have high strength.","Step 3: They can therefore support heavy loads and form strong structures."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q3","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 2),
  (2705, 678, 'A manufacturer needs a metal for making electrical cables. Which property should be especially important?', 'text', 1, 'Electrical cables must allow electric current to flow easily.', '{"why":"A good electrical conductor allows current to flow through the cable efficiently.","sol":"Step 1: Electric current must pass through the cable.\nStep 2: The material should therefore have high electrical conductivity.\nStep 3: Copper has high electrical conductivity and is ductile.","steps":["Step 1: Electric current must pass through the cable.","Step 2: The material should therefore have high electrical conductivity.","Step 3: Copper has high electrical conductivity and is ductile."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q4","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 3),
  (2706, 678, 'A cooking utensil needs a material that transfers heat effectively. Which property of metals is useful?', 'text', 1, 'Think about how heat moves through a metal.', '{"why":"Good thermal conductivity allows heat to be transferred efficiently through the material.","sol":"Step 1: Heat must move from the heat source through the utensil.\nStep 2: A material with good thermal conductivity transfers heat effectively.\nStep 3: Many metals are good conductors of heat.","steps":["Step 1: Heat must move from the heat source through the utensil.","Step 2: A material with good thermal conductivity transfers heat effectively.","Step 3: Many metals are good conductors of heat."],"options":[],"conceptId":"chemistry_metals_uses_of_metals","skillId":"chemistry_metals","subskillId":"chemistry_metals_q5","subject":"chemistry","chapter":"metals","topic":"Uses of Metals"}', 4),
  (2707, 679, 'Name one metal that can be used to prepare hydrogen gas from a dilute acid.', 'text', 1, 'Focus on the core principle of Preparation of Hydrogen.', '{"why":"Zinc reacts with dilute acids to produce hydrogen gas.","sol":"Step 1: A reactive metal can react with a dilute acid to release hydrogen.\nStep 2: Zinc is a suitable metal for this laboratory preparation.\nStep 3: Therefore, zinc can be used.","steps":["Step 1: A reactive metal can react with a dilute acid to release hydrogen.","Step 2: Zinc is a suitable metal for this laboratory preparation.","Step 3: Therefore, zinc can be used."],"options":[],"conceptId":"chemistry_non_metals_preparation_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q1","subject":"chemistry","chapter":"non_metals","topic":"Preparation of Hydrogen"}', 0),
  (2708, 679, 'Write the balanced equation for the reaction between zinc and dilute hydrochloric acid.', 'text', 1, 'Focus on the core principle of Preparation of Hydrogen.', '{"why":"The equation has equal numbers of zinc, hydrogen and chlorine atoms on both sides.","sol":"Step 1: Write the reactants: Zn + HCl.\nStep 2: The products are zinc chloride and hydrogen: ZnCl₂ + H₂.\nStep 3: Zinc is already balanced.\nStep 4: ZnCl₂ requires two chlorine atoms, so use 2HCl.\nStep 5: The two hydrogen atoms then form H₂.","steps":["Step 1: Write the reactants: Zn + HCl.","Step 2: The products are zinc chloride and hydrogen: ZnCl₂ + H₂.","Step 3: Zinc is already balanced.","Step 4: ZnCl₂ requires two chlorine atoms, so use 2HCl.","Step 5: The two hydrogen atoms then form H₂."],"options":[],"conceptId":"chemistry_non_metals_preparation_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q2","subject":"chemistry","chapter":"non_metals","topic":"Preparation of Hydrogen"}', 1),
  (2709, 679, 'What gas is produced when zinc reacts with dilute hydrochloric acid?', 'text', 1, 'Focus on the core principle of Preparation of Hydrogen.', '{"why":"The hydrogen ions from the acid are reduced to hydrogen gas.","sol":"Step 1: Zinc reacts with dilute hydrochloric acid.\nStep 2: The products include zinc chloride and a gas.\nStep 3: The gas is hydrogen.","steps":["Step 1: Zinc reacts with dilute hydrochloric acid.","Step 2: The products include zinc chloride and a gas.","Step 3: The gas is hydrogen."],"options":[],"conceptId":"chemistry_non_metals_preparation_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q3","subject":"chemistry","chapter":"non_metals","topic":"Preparation of Hydrogen"}', 2),
  (2710, 679, 'A student wants to prepare hydrogen using zinc and hydrochloric acid. Why should the acid be dilute rather than concentrated?', 'text', 1, 'Think about controlling the reaction and the safety of handling hydrogen.', '{"why":"Laboratory gas preparation should be controlled, particularly because hydrogen is highly flammable.","sol":"Step 1: The reaction produces flammable hydrogen gas.\nStep 2: A controlled reaction is preferred in laboratory preparation.\nStep 3: Dilute acid provides a suitable reaction rate and safer conditions than using a highly concentrated acid.","steps":["Step 1: The reaction produces flammable hydrogen gas.","Step 2: A controlled reaction is preferred in laboratory preparation.","Step 3: Dilute acid provides a suitable reaction rate and safer conditions than using a highly concentrated acid."],"options":[],"conceptId":"chemistry_non_metals_preparation_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q4","subject":"chemistry","chapter":"non_metals","topic":"Preparation of Hydrogen"}', 3),
  (2711, 680, 'State three physical properties of hydrogen gas.', 'text', 1, 'Focus on the core principle of Properties of Hydrogen.', '{"why":"These are characteristic physical properties of hydrogen gas.","sol":"Step 1: Identify its appearance.\nStep 2: Identify its smell.\nStep 3: Consider its density and solubility.","steps":["Step 1: Identify its appearance.","Step 2: Identify its smell.","Step 3: Consider its density and solubility."],"options":[],"conceptId":"chemistry_non_metals_properties_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q1","subject":"chemistry","chapter":"non_metals","topic":"Properties of Hydrogen"}', 0),
  (2712, 680, 'Write the balanced equation for the combustion of hydrogen in oxygen.', 'text', 1, 'Focus on the core principle of Properties of Hydrogen.', '{"why":"Hydrogen reacts with oxygen to form water, and the equation is balanced with two hydrogen molecules and one oxygen molecule.","sol":"Step 1: Write H₂ + O₂ → H₂O.\nStep 2: Balance hydrogen by placing 2 before H₂O.\nStep 3: There are now two oxygen atoms on the product side.\nStep 4: Place 2 before H₂.\nStep 5: The balanced equation is 2H₂ + O₂ → 2H₂O.","steps":["Step 1: Write H₂ + O₂ → H₂O.","Step 2: Balance hydrogen by placing 2 before H₂O.","Step 3: There are now two oxygen atoms on the product side.","Step 4: Place 2 before H₂.","Step 5: The balanced equation is 2H₂ + O₂ → 2H₂O."],"options":[],"conceptId":"chemistry_non_metals_properties_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q2","subject":"chemistry","chapter":"non_metals","topic":"Properties of Hydrogen"}', 1),
  (2713, 680, 'What happens when hydrogen is passed over heated copper(II) oxide?', 'text', 1, 'Focus on the core principle of Properties of Hydrogen.', '{"why":"Hydrogen acts as a reducing agent and removes oxygen from copper(II) oxide.","sol":"Step 1: Hydrogen reacts with copper(II) oxide.\nStep 2: Hydrogen removes oxygen from the copper(II) oxide.\nStep 3: Copper is produced.\nStep 4: Water is also formed.","steps":["Step 1: Hydrogen reacts with copper(II) oxide.","Step 2: Hydrogen removes oxygen from the copper(II) oxide.","Step 3: Copper is produced.","Step 4: Water is also formed."],"options":[],"conceptId":"chemistry_non_metals_properties_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q3","subject":"chemistry","chapter":"non_metals","topic":"Properties of Hydrogen"}', 2),
  (2714, 680, 'A gas is colourless, odourless and highly flammable. Why can these observations alone not prove that the gas is hydrogen?', 'text', 1, 'Think about identification versus general properties.', '{"why":"Identification of a gas should use a characteristic test rather than relying only on general physical properties.","sol":"Step 1: Several gases can be colourless and odourless.\nStep 2: A property shared by several gases cannot uniquely identify one gas.\nStep 3: Hydrogen therefore requires a specific chemical test.","steps":["Step 1: Several gases can be colourless and odourless.","Step 2: A property shared by several gases cannot uniquely identify one gas.","Step 3: Hydrogen therefore requires a specific chemical test."],"options":[],"conceptId":"chemistry_non_metals_properties_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q4","subject":"chemistry","chapter":"non_metals","topic":"Properties of Hydrogen"}', 3),
  (2715, 681, 'What test is used to identify hydrogen gas?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"The rapid combustion of hydrogen in oxygen produces the characteristic pop.","sol":"Step 1: Collect a small sample of the gas.\nStep 2: Bring a lighted splint to the sample.\nStep 3: Observe the reaction.\nStep 4: Hydrogen produces a characteristic squeaky pop.","steps":["Step 1: Collect a small sample of the gas.","Step 2: Bring a lighted splint to the sample.","Step 3: Observe the reaction.","Step 4: Hydrogen produces a characteristic squeaky pop."],"options":[],"conceptId":"chemistry_non_metals_test_for_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q1","subject":"chemistry","chapter":"non_metals","topic":"Test for Hydrogen"}', 0),
  (2716, 681, 'What causes the squeaky pop when hydrogen is tested?', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"Hydrogen reacts rapidly with oxygen when ignited.","sol":"Step 1: Hydrogen is brought into contact with oxygen.\nStep 2: The hydrogen burns rapidly.\nStep 3: Water is formed.\nStep 4: The rapid combustion produces the characteristic sound.","steps":["Step 1: Hydrogen is brought into contact with oxygen.","Step 2: The hydrogen burns rapidly.","Step 3: Water is formed.","Step 4: The rapid combustion produces the characteristic sound."],"options":[],"conceptId":"chemistry_non_metals_test_for_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q2","subject":"chemistry","chapter":"non_metals","topic":"Test for Hydrogen"}', 1),
  (2717, 681, 'Write the balanced equation for the reaction responsible for the hydrogen test.', 'text', 1, 'Focus on the core principle of Test for Hydrogen.', '{"why":"The equation represents the combustion of hydrogen during the test.","sol":"Step 1: Hydrogen reacts with oxygen to form water.\nStep 2: Write H₂ + O₂ → H₂O.\nStep 3: Balance hydrogen using 2H₂ and 2H₂O.\nStep 4: One O₂ molecule then balances the oxygen atoms.","steps":["Step 1: Hydrogen reacts with oxygen to form water.","Step 2: Write H₂ + O₂ → H₂O.","Step 3: Balance hydrogen using 2H₂ and 2H₂O.","Step 4: One O₂ molecule then balances the oxygen atoms."],"options":[],"conceptId":"chemistry_non_metals_test_for_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q3","subject":"chemistry","chapter":"non_metals","topic":"Test for Hydrogen"}', 2),
  (2718, 681, 'A gas gives no characteristic pop when a lighted splint is applied. Can it be identified as hydrogen?', 'text', 1, 'Recall the positive observation for the hydrogen test.', '{"why":"A positive hydrogen test requires the characteristic pop.","sol":"Step 1: Hydrogen should produce a characteristic squeaky pop.\nStep 2: The gas did not produce this observation.\nStep 3: Therefore, the test does not identify the gas as hydrogen.","steps":["Step 1: Hydrogen should produce a characteristic squeaky pop.","Step 2: The gas did not produce this observation.","Step 3: Therefore, the test does not identify the gas as hydrogen."],"options":[],"conceptId":"chemistry_non_metals_test_for_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q4","subject":"chemistry","chapter":"non_metals","topic":"Test for Hydrogen"}', 3),
  (2719, 682, 'State two uses of hydrogen.', 'text', 1, 'Focus on the core principle of Uses of Hydrogen.', '{"why":"Hydrogen''s chemical properties make it useful in several industrial processes.","sol":"Step 1: Hydrogen is used in industrial chemical reactions.\nStep 2: It is used to manufacture ammonia.\nStep 3: It can also be used as a fuel or reducing agent.","steps":["Step 1: Hydrogen is used in industrial chemical reactions.","Step 2: It is used to manufacture ammonia.","Step 3: It can also be used as a fuel or reducing agent."],"options":[],"conceptId":"chemistry_non_metals_uses_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q1","subject":"chemistry","chapter":"non_metals","topic":"Uses of Hydrogen"}', 0),
  (2720, 682, 'How is hydrogen used in the Haber process?', 'text', 1, 'Focus on the core principle of Uses of Hydrogen.', '{"why":"Hydrogen is one of the reactants required for industrial ammonia manufacture.","sol":"Step 1: Nitrogen reacts with hydrogen.\nStep 2: The reaction is reversible.\nStep 3: Ammonia is formed.\nStep 4: The balanced equation is N₂ + 3H₂ ⇌ 2NH₃.","steps":["Step 1: Nitrogen reacts with hydrogen.","Step 2: The reaction is reversible.","Step 3: Ammonia is formed.","Step 4: The balanced equation is N₂ + 3H₂ ⇌ 2NH₃."],"options":[],"conceptId":"chemistry_non_metals_uses_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q2","subject":"chemistry","chapter":"non_metals","topic":"Uses of Hydrogen"}', 1),
  (2721, 682, 'Why can hydrogen be used as a fuel?', 'text', 1, 'Focus on the core principle of Uses of Hydrogen.', '{"why":"The energy released during hydrogen combustion can be harnessed for useful purposes.","sol":"Step 1: Hydrogen is combustible.\nStep 2: It reacts with oxygen.\nStep 3: The reaction releases energy.\nStep 4: The main product is water.","steps":["Step 1: Hydrogen is combustible.","Step 2: It reacts with oxygen.","Step 3: The reaction releases energy.","Step 4: The main product is water."],"options":[],"conceptId":"chemistry_non_metals_uses_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q3","subject":"chemistry","chapter":"non_metals","topic":"Uses of Hydrogen"}', 2),
  (2722, 682, 'Hydrogen is used to reduce copper(II) oxide. What two products are formed?', 'text', 1, 'Hydrogen removes oxygen from the metal oxide.', '{"why":"Hydrogen reduces copper(II) oxide to copper while forming water.","sol":"Step 1: Hydrogen reacts with copper(II) oxide.\nStep 2: Hydrogen removes oxygen from CuO.\nStep 3: The remaining metal is copper.\nStep 4: The removed oxygen combines with hydrogen to form water.","steps":["Step 1: Hydrogen reacts with copper(II) oxide.","Step 2: Hydrogen removes oxygen from CuO.","Step 3: The remaining metal is copper.","Step 4: The removed oxygen combines with hydrogen to form water."],"options":[],"conceptId":"chemistry_non_metals_uses_of_hydrogen","skillId":"chemistry_non_metals","subskillId":"chemistry_non_metals_q4","subject":"chemistry","chapter":"non_metals","topic":"Uses of Hydrogen"}', 3),
  (2723, 683, 'What is water pollution?', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Pollutants change the quality of water and can cause harm to living organisms.","sol":"Step 1: Water can become contaminated by unwanted substances.\nStep 2: These substances can make the water harmful or unsuitable for organisms.\nStep 3: This contamination is called water pollution.","steps":["Step 1: Water can become contaminated by unwanted substances.","Step 2: These substances can make the water harmful or unsuitable for organisms.","Step 3: This contamination is called water pollution."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 0),
  (2724, 683, 'How can excessive fertiliser use cause water pollution?', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Excess nutrients can cause eutrophication, which may reduce oxygen available to aquatic organisms.","sol":"Step 1: Fertilisers can contain nitrates and phosphates.\nStep 2: Rainwater can carry these substances into rivers and lakes.\nStep 3: The nutrients can cause excessive growth of algae.\nStep 4: When the algae die, microorganisms decompose them and use dissolved oxygen.\nStep 5: The reduced oxygen concentration can harm or kill aquatic organisms.","steps":["Step 1: Fertilisers can contain nitrates and phosphates.","Step 2: Rainwater can carry these substances into rivers and lakes.","Step 3: The nutrients can cause excessive growth of algae.","Step 4: When the algae die, microorganisms decompose them and use dissolved oxygen.","Step 5: The reduced oxygen concentration can harm or kill aquatic organisms."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 1),
  (2725, 683, 'State two ways of controlling water pollution.', 'text', 1, 'Focus on the core principle of Water Pollution.', '{"why":"Treatment removes or reduces harmful substances before wastewater enters natural water sources.","sol":"Step 1: Identify major sources of pollutants.\nStep 2: Prevent sewage and industrial waste from entering water untreated.\nStep 3: Reduce the amount of agricultural chemicals reaching water sources.","steps":["Step 1: Identify major sources of pollutants.","Step 2: Prevent sewage and industrial waste from entering water untreated.","Step 3: Reduce the amount of agricultural chemicals reaching water sources."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 2),
  (2726, 683, 'A lake receives large amounts of fertiliser runoff. After some time, many fish begin dying. Explain how the fertiliser could have caused this.', 'text', 1, 'Think about nutrients, algae and dissolved oxygen.', '{"why":"This is a form of eutrophication in which excess nutrients indirectly cause oxygen depletion.","sol":"Step 1: Fertiliser runoff adds nutrients such as nitrates and phosphates to the lake.\nStep 2: The excess nutrients encourage rapid algal growth.\nStep 3: The algae eventually die and are decomposed by microorganisms.\nStep 4: The microorganisms use dissolved oxygen during decomposition.\nStep 5: The oxygen concentration falls.\nStep 6: Fish and other aquatic organisms may die because there is insufficient dissolved oxygen.","steps":["Step 1: Fertiliser runoff adds nutrients such as nitrates and phosphates to the lake.","Step 2: The excess nutrients encourage rapid algal growth.","Step 3: The algae eventually die and are decomposed by microorganisms.","Step 4: The microorganisms use dissolved oxygen during decomposition.","Step 5: The oxygen concentration falls.","Step 6: Fish and other aquatic organisms may die because there is insufficient dissolved oxygen."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 3),
  (2727, 683, 'Why should sewage be treated before it is released into a river?', 'text', 1, 'Consider disease-causing organisms and substances in untreated sewage.', '{"why":"Sewage treatment reduces contamination and protects water quality and aquatic ecosystems.","sol":"Step 1: Untreated sewage can contain microorganisms that cause disease.\nStep 2: It can also contain organic matter and other pollutants.\nStep 3: Releasing it directly into a river can contaminate the water.\nStep 4: Treatment reduces harmful microorganisms and pollutants before discharge.","steps":["Step 1: Untreated sewage can contain microorganisms that cause disease.","Step 2: It can also contain organic matter and other pollutants.","Step 3: Releasing it directly into a river can contaminate the water.","Step 4: Treatment reduces harmful microorganisms and pollutants before discharge."],"options":[],"conceptId":"chemistry_environment_water_pollution","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Water Pollution"}', 4),
  (2728, 684, 'What is the ozone layer?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Stratospheric ozone forms a region that absorbs much of the Sun''s harmful ultraviolet radiation.","sol":"Step 1: Ozone is O₃.\nStep 2: A relatively high concentration of ozone occurs in part of the stratosphere.\nStep 3: This region is commonly called the ozone layer.","steps":["Step 1: Ozone is O₃.","Step 2: A relatively high concentration of ozone occurs in part of the stratosphere.","Step 3: This region is commonly called the ozone layer."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 0),
  (2729, 684, 'How is ozone formed from oxygen in the stratosphere?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Ultraviolet radiation drives the reactions that form ozone from oxygen.","sol":"Step 1: Ultraviolet radiation splits oxygen molecules into oxygen atoms.\nStep 2: An oxygen atom combines with an oxygen molecule.\nStep 3: Ozone is formed.\nStep 4: The equations are O₂ → 2O and O + O₂ → O₃.","steps":["Step 1: Ultraviolet radiation splits oxygen molecules into oxygen atoms.","Step 2: An oxygen atom combines with an oxygen molecule.","Step 3: Ozone is formed.","Step 4: The equations are O₂ → 2O and O + O₂ → O₃."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 1),
  (2730, 684, 'Why is the ozone layer important to living organisms?', 'text', 1, 'Focus on the core principle of Ozone Layer.', '{"why":"Ozone reduces the amount of harmful ultraviolet radiation reaching Earth''s surface.","sol":"Step 1: The Sun produces ultraviolet radiation.\nStep 2: Excessive ultraviolet radiation can damage living cells.\nStep 3: Stratospheric ozone absorbs much of this radiation.\nStep 4: Therefore, the ozone layer provides important protection for living organisms.","steps":["Step 1: The Sun produces ultraviolet radiation.","Step 2: Excessive ultraviolet radiation can damage living cells.","Step 3: Stratospheric ozone absorbs much of this radiation.","Step 4: Therefore, the ozone layer provides important protection for living organisms."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 2),
  (2731, 684, 'What would happen if much less ultraviolet radiation were absorbed by the ozone layer?', 'text', 1, 'Think about what excessive ultraviolet radiation can do to living cells.', '{"why":"The ozone layer acts as a protective barrier against much of the Sun''s harmful ultraviolet radiation.","sol":"Step 1: Less ozone absorption would allow more ultraviolet radiation to reach Earth''s surface.\nStep 2: Living organisms would therefore receive greater exposure.\nStep 3: Excessive ultraviolet radiation can damage cells and tissues.\nStep 4: Therefore, risks associated with ultraviolet exposure would increase.","steps":["Step 1: Less ozone absorption would allow more ultraviolet radiation to reach Earth''s surface.","Step 2: Living organisms would therefore receive greater exposure.","Step 3: Excessive ultraviolet radiation can damage cells and tissues.","Step 4: Therefore, risks associated with ultraviolet exposure would increase."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 3),
  (2732, 684, 'Why does the ozone layer contain O₃ rather than O₂?', 'text', 1, 'Identify the chemical formula of ozone.', '{"why":"Ozone is an allotrope of oxygen with three oxygen atoms per molecule.","sol":"Step 1: Oxygen gas normally exists as O₂.\nStep 2: Ozone is a different form of oxygen.\nStep 3: An ozone molecule contains three oxygen atoms.\nStep 4: Therefore, its formula is O₃.","steps":["Step 1: Oxygen gas normally exists as O₂.","Step 2: Ozone is a different form of oxygen.","Step 3: An ozone molecule contains three oxygen atoms.","Step 4: Therefore, its formula is O₃."],"options":[],"conceptId":"chemistry_environment_ozone_layer","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Ozone Layer"}', 4),
  (2733, 685, 'What is ozone depletion?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"Ozone depletion occurs when chemical processes destroy stratospheric ozone.","sol":"Step 1: The ozone layer contains ozone, O₃.\nStep 2: Certain chemical substances can cause ozone molecules to be destroyed.\nStep 3: The concentration of ozone in the stratosphere therefore decreases.\nStep 4: This reduction is called ozone depletion.","steps":["Step 1: The ozone layer contains ozone, O₃.","Step 2: Certain chemical substances can cause ozone molecules to be destroyed.","Step 3: The concentration of ozone in the stratosphere therefore decreases.","Step 4: This reduction is called ozone depletion."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 0),
  (2734, 685, 'How can CFCs contribute to ozone depletion?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"Chlorine released from ozone-depleting substances can catalyse the destruction of ozone.","sol":"Step 1: CFCs can reach the stratosphere.\nStep 2: Ultraviolet radiation breaks down CFC molecules.\nStep 3: Chlorine atoms can be released.\nStep 4: The chlorine reacts with ozone and contributes to its destruction.","steps":["Step 1: CFCs can reach the stratosphere.","Step 2: Ultraviolet radiation breaks down CFC molecules.","Step 3: Chlorine atoms can be released.","Step 4: The chlorine reacts with ozone and contributes to its destruction."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 1),
  (2735, 685, 'Why is ozone depletion harmful to humans?', 'text', 1, 'Focus on the core principle of Ozone Depletion.', '{"why":"A thinner ozone layer provides less protection from ultraviolet radiation.","sol":"Step 1: Stratospheric ozone absorbs much of the Sun''s harmful ultraviolet radiation.\nStep 2: Ozone depletion reduces this protection.\nStep 3: More ultraviolet radiation can reach Earth''s surface.\nStep 4: Excessive ultraviolet exposure can damage human cells and tissues.","steps":["Step 1: Stratospheric ozone absorbs much of the Sun''s harmful ultraviolet radiation.","Step 2: Ozone depletion reduces this protection.","Step 3: More ultraviolet radiation can reach Earth''s surface.","Step 4: Excessive ultraviolet exposure can damage human cells and tissues."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 2),
  (2736, 685, 'A chemical released into the atmosphere eventually reaches the stratosphere and releases chlorine atoms when exposed to ultraviolet radiation. How could this affect ozone?', 'text', 1, 'Consider what chlorine atoms can do to ozone molecules.', '{"why":"Reactive chlorine can participate in catalytic reactions that destroy ozone.","sol":"Step 1: Ultraviolet radiation releases chlorine atoms from the chemical.\nStep 2: The chlorine atoms react with ozone molecules.\nStep 3: These reactions destroy ozone.\nStep 4: Therefore, the concentration of stratospheric ozone can decrease.","steps":["Step 1: Ultraviolet radiation releases chlorine atoms from the chemical.","Step 2: The chlorine atoms react with ozone molecules.","Step 3: These reactions destroy ozone.","Step 4: Therefore, the concentration of stratospheric ozone can decrease."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 3),
  (2737, 685, 'Suggest one way of reducing ozone depletion.', 'text', 1, 'Think about the substances responsible for releasing chlorine or bromine in the stratosphere.', '{"why":"Controlling ozone-depleting substances reduces the chemical reactions responsible for ozone destruction.","sol":"Step 1: Identify substances that contribute to ozone depletion.\nStep 2: Reduce their production and use.\nStep 3: Replace them with safer alternatives where possible.","steps":["Step 1: Identify substances that contribute to ozone depletion.","Step 2: Reduce their production and use.","Step 3: Replace them with safer alternatives where possible."],"options":[],"conceptId":"chemistry_environment_ozone_depletion","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Ozone Depletion"}', 4),
  (2738, 686, 'What is sustainable chemistry?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"The aim is to prevent pollution and reduce the environmental impact of chemistry.","sol":"Step 1: Chemical processes can consume resources and produce waste.\nStep 2: Sustainable chemistry aims to reduce these negative effects.\nStep 3: It promotes safer, more efficient and less wasteful chemical processes.","steps":["Step 1: Chemical processes can consume resources and produce waste.","Step 2: Sustainable chemistry aims to reduce these negative effects.","Step 3: It promotes safer, more efficient and less wasteful chemical processes."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 0),
  (2739, 686, 'Why is reducing waste at the source better than producing waste and treating it afterwards?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"Preventing pollution at its source is generally more efficient than dealing with pollution after it has been produced.","sol":"Step 1: Producing waste creates a material that must be collected and treated or disposed of.\nStep 2: Treatment and disposal can require additional energy and resources.\nStep 3: Preventing the waste from being produced avoids these additional requirements.\nStep 4: Therefore, waste prevention can reduce environmental impact.","steps":["Step 1: Producing waste creates a material that must be collected and treated or disposed of.","Step 2: Treatment and disposal can require additional energy and resources.","Step 3: Preventing the waste from being produced avoids these additional requirements.","Step 4: Therefore, waste prevention can reduce environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 1),
  (2740, 686, 'Why can using a chemical process that requires less energy be more sustainable?', 'text', 1, 'Focus on the core principle of Sustainable Chemistry.', '{"why":"Using less energy can conserve resources and reduce environmental impacts associated with energy production.","sol":"Step 1: Energy is required to operate many chemical processes.\nStep 2: Lower energy requirements mean less energy needs to be supplied.\nStep 3: If the energy comes from fossil fuels, lower energy use can also reduce associated emissions.\nStep 4: Therefore, an energy-efficient process can reduce environmental impact.","steps":["Step 1: Energy is required to operate many chemical processes.","Step 2: Lower energy requirements mean less energy needs to be supplied.","Step 3: If the energy comes from fossil fuels, lower energy use can also reduce associated emissions.","Step 4: Therefore, an energy-efficient process can reduce environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 2),
  (2741, 686, 'A factory changes its manufacturing process so that it produces the same amount of product using less raw material and producing less waste. Why is this an example of sustainable chemistry?', 'text', 1, 'Consider resource use and waste production.', '{"why":"Efficient resource use and waste prevention are important principles of sustainable chemistry.","sol":"Step 1: The new process uses less raw material.\nStep 2: It also produces less waste.\nStep 3: This reduces resource consumption and waste generation.\nStep 4: Therefore, the process has a lower environmental impact.","steps":["Step 1: The new process uses less raw material.","Step 2: It also produces less waste.","Step 3: This reduces resource consumption and waste generation.","Step 4: Therefore, the process has a lower environmental impact."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 3),
  (2742, 686, 'A chemical product can be made using either a highly toxic substance or a less harmful alternative. Which option is more consistent with sustainable chemistry?', 'text', 1, 'Sustainable chemistry seeks to reduce hazards where possible.', '{"why":"Using safer substances can reduce risks to human health and the environment.","sol":"Step 1: Compare the hazards of the two substances.\nStep 2: The less harmful alternative presents a lower risk to people and the environment.\nStep 3: Therefore, it is the preferred option when it performs the required function effectively.","steps":["Step 1: Compare the hazards of the two substances.","Step 2: The less harmful alternative presents a lower risk to people and the environment.","Step 3: Therefore, it is the preferred option when it performs the required function effectively."],"options":[],"conceptId":"chemistry_environment_sustainable_chemistry","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Sustainable Chemistry"}', 4),
  (2743, 687, 'What is waste management?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Proper waste management reduces pollution, health risks and unnecessary loss of useful materials.","sol":"Step 1: Waste can harm people and the environment if it is handled improperly.\nStep 2: Waste therefore needs to be controlled, treated, recovered or disposed of safely.\nStep 3: The organised handling of waste is called waste management.","steps":["Step 1: Waste can harm people and the environment if it is handled improperly.","Step 2: Waste therefore needs to be controlled, treated, recovered or disposed of safely.","Step 3: The organised handling of waste is called waste management."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q1","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 0),
  (2744, 687, 'What does reducing waste mean?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Preventing waste at its source reduces the materials and resources that must later be treated or disposed of.","sol":"Step 1: Waste reduction focuses on preventing unnecessary waste from being produced.\nStep 2: This can be achieved by using fewer materials or avoiding unnecessary consumption.\nStep 3: Therefore, reducing waste means producing less waste at the source.","steps":["Step 1: Waste reduction focuses on preventing unnecessary waste from being produced.","Step 2: This can be achieved by using fewer materials or avoiding unnecessary consumption.","Step 3: Therefore, reducing waste means producing less waste at the source."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q2","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 1),
  (2745, 687, 'What is the difference between reusing and recycling?', 'text', 1, 'Focus on the core principle of Waste Management.', '{"why":"Both reduce waste, but recycling involves processing the material whereas reuse does not necessarily require processing.","sol":"Step 1: Reusing means using an item again without necessarily changing it into a new material.\nStep 2: Recycling involves collecting and processing waste materials to make new products.\nStep 3: Therefore, reuse keeps an item in use, while recycling processes the material into another product.","steps":["Step 1: Reusing means using an item again without necessarily changing it into a new material.","Step 2: Recycling involves collecting and processing waste materials to make new products.","Step 3: Therefore, reuse keeps an item in use, while recycling processes the material into another product."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q3","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 2),
  (2746, 687, 'A laboratory produces unused chemical solution after an experiment. Why should it not simply be poured into a drain?', 'text', 1, 'Consider what the chemical could do to water and organisms.', '{"why":"Chemical waste requires appropriate handling and disposal to prevent pollution and exposure.","sol":"Step 1: The solution may contain substances that are harmful or toxic.\nStep 2: Pouring it into a drain can introduce these substances into wastewater and eventually the environment.\nStep 3: The substances could contaminate water or harm organisms.\nStep 4: Therefore, the chemical waste should be handled according to appropriate waste-disposal procedures.","steps":["Step 1: The solution may contain substances that are harmful or toxic.","Step 2: Pouring it into a drain can introduce these substances into wastewater and eventually the environment.","Step 3: The substances could contaminate water or harm organisms.","Step 4: Therefore, the chemical waste should be handled according to appropriate waste-disposal procedures."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q4","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 3),
  (2747, 687, 'A school replaces disposable plastic containers with reusable containers. Which waste-management principle is being applied?', 'text', 1, 'The same container is used repeatedly instead of being discarded after one use.', '{"why":"Using an item repeatedly instead of discarding it after one use reduces waste.","sol":"Step 1: The containers are used more than once.\nStep 2: Fewer disposable containers are therefore thrown away.\nStep 3: This is the principle of reuse.","steps":["Step 1: The containers are used more than once.","Step 2: Fewer disposable containers are therefore thrown away.","Step 3: This is the principle of reuse."],"options":[],"conceptId":"chemistry_environment_waste_management","skillId":"chemistry_environment","subskillId":"chemistry_environment_q5","subject":"chemistry","chapter":"environment","topic":"Waste Management"}', 4),
  (2748, 688, 'What is a cell?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A cell is the smallest unit of a living organism that can carry out the processes needed for life.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A cell is the smallest unit of a living organism that can carry out the processes needed for life."],"options":[{"text":"The smallest living unit of an organism","is_correct":false},{"text":"A group of organs","is_correct":false},{"text":"A chemical found only in plants","is_correct":false},{"text":"A non-living part of an organism","is_correct":false},{"text":"A cell is the smallest unit of a living organism that can carry out the processes needed for life.","is_correct":true}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 0),
  (2749, 688, 'Why is a cell called a unit of life?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because it can carry out the processes necessary for life.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because it can carry out the processes necessary for life."],"options":[{"text":"Because it is always visible to the naked eye","is_correct":false},{"text":"Because it can carry out processes necessary for life","is_correct":false},{"text":"Because every cell is the same size","is_correct":false},{"text":"Because cells are made only of water","is_correct":false},{"text":"Because it can carry out the processes necessary for life.","is_correct":true}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 1),
  (2750, 688, 'What unit is commonly used to measure the size of cells?', 'mcq', 1, 'Focus on the core principle of What Is a Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Micrometre","steps":["Step 1: Identify key concept: Define the required principles for What Is a Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Micrometre"],"options":[{"text":"Kilometre","is_correct":false},{"text":"Metre","is_correct":false},{"text":"Micrometre","is_correct":true},{"text":"Litre","is_correct":false}],"conceptId":"biology_cell_biology_what_is_a_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"What Is a Cell"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (2751, 689, 'Why are cells called the basic units of life?', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because living processes are carried out by cells.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because living processes are carried out by cells."],"options":[{"text":"Because cells are always microscopic","is_correct":false},{"text":"Because living processes are carried out by cells","is_correct":false},{"text":"Because cells are all identical","is_correct":false},{"text":"Because cells only occur in animals","is_correct":false},{"text":"Because living processes are carried out by cells.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 0),
  (2752, 689, 'Which statement best explains why the heart is not the basic unit of life?', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The heart is an organ made from tissues and cells.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The heart is an organ made from tissues and cells."],"options":[{"text":"The heart is not made of cells","is_correct":false},{"text":"The heart is an organ made from tissues and cells","is_correct":false},{"text":"The heart is not part of a living organism","is_correct":false},{"text":"The heart is smaller than a cell","is_correct":false},{"text":"The heart is an organ made from tissues and cells.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 1),
  (2753, 689, 'Give one life process carried out by cells.', 'mcq', 1, 'Focus on the core principle of Why Cells Are the Basic Units of Life.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Any valid example such as respiration, growth, waste removal, response, or reproduction.","steps":["Step 1: Identify key concept: Define the required principles for Why Cells Are the Basic Units of Life.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Any valid example such as respiration, growth, waste removal, response, or reproduction."],"options":[{"text":"Respiration","is_correct":false},{"text":"Rusting","is_correct":false},{"text":"Melting","is_correct":false},{"text":"Evaporation","is_correct":false},{"text":"Any valid example such as respiration, growth, waste removal, response, or reproduction.","is_correct":true}],"conceptId":"biology_cell_biology_why_cells_are_the_basic_units_of_life","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Why Cells Are the Basic Units of Life"}', 2),
  (2754, 690, 'What is the main function of the cell membrane?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To control the movement of substances into and out of the cell.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To control the movement of substances into and out of the cell."],"options":[{"text":"To release energy","is_correct":false},{"text":"To control movement of substances into and out of the cell","is_correct":false},{"text":"To make the cell green","is_correct":false},{"text":"To store urine","is_correct":false},{"text":"To control the movement of substances into and out of the cell.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 0),
  (2755, 690, 'What does selectively permeable mean in relation to the cell membrane?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The membrane controls which substances can cross it and how they cross.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The membrane controls which substances can cross it and how they cross."],"options":[{"text":"Everything crosses the membrane freely","is_correct":false},{"text":"Nothing can cross the membrane","is_correct":false},{"text":"The membrane controls movement of substances across it","is_correct":false},{"text":"Only water can cross","is_correct":false},{"text":"The membrane controls which substances can cross it and how they cross.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 1),
  (2756, 690, 'Why must a cell control what enters and leaves?', 'mcq', 1, 'Focus on the core principle of Cell Membrane.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Membrane.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To maintain suitable internal conditions for the cell to function.","steps":["Step 1: Identify key concept: Define the required principles for Cell Membrane.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To maintain suitable internal conditions for the cell to function."],"options":[{"text":"To make the cell larger","is_correct":false},{"text":"To maintain suitable internal conditions","is_correct":false},{"text":"To stop all substances entering","is_correct":false},{"text":"To prevent respiration","is_correct":false},{"text":"To maintain suitable internal conditions for the cell to function.","is_correct":true}],"conceptId":"biology_cell_biology_cell_membrane","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Cell Membrane"}', 2),
  (2757, 691, 'What is the cytoplasm?', 'mcq', 1, 'Focus on the core principle of Cytoplasm.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cytoplasm.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The living material inside the cell membrane where many chemical reactions occur.","steps":["Step 1: Identify key concept: Define the required principles for Cytoplasm.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The living material inside the cell membrane where many chemical reactions occur."],"options":[{"text":"The outer boundary of the cell","is_correct":false},{"text":"The living material inside the cell membrane","is_correct":false},{"text":"The genetic material only","is_correct":false},{"text":"The rigid wall around a plant cell","is_correct":false},{"text":"The living material inside the cell membrane where many chemical reactions occur.","is_correct":true}],"conceptId":"biology_cell_biology_cytoplasm","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Cytoplasm"}', 0),
  (2758, 691, 'Why is the cytoplasm important?', 'mcq', 1, 'Focus on the core principle of Cytoplasm.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cytoplasm.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Many chemical reactions needed by the cell occur there.","steps":["Step 1: Identify key concept: Define the required principles for Cytoplasm.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Many chemical reactions needed by the cell occur there."],"options":[{"text":"It controls the organism''s behaviour","is_correct":false},{"text":"Many cellular chemical reactions occur there","is_correct":false},{"text":"It surrounds the entire organism","is_correct":false},{"text":"It prevents all substances from entering","is_correct":false},{"text":"Many chemical reactions needed by the cell occur there.","is_correct":true}],"conceptId":"biology_cell_biology_cytoplasm","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Cytoplasm"}', 1),
  (2759, 691, 'Which structure forms the boundary around the cytoplasm?', 'mcq', 1, 'Focus on the core principle of Cytoplasm.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cytoplasm.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell membrane","steps":["Step 1: Identify key concept: Define the required principles for Cytoplasm.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell membrane"],"options":[{"text":"Cell wall","is_correct":false},{"text":"Nucleus","is_correct":false},{"text":"Cell membrane","is_correct":true},{"text":"Ribosome","is_correct":false}],"conceptId":"biology_cell_biology_cytoplasm","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Cytoplasm"}', 2),
  (2760, 692, 'What is the main biological importance of the nucleus?', 'mcq', 1, 'Focus on the core principle of Nucleus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Nucleus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It contains most of the cell''s genetic material.","steps":["Step 1: Identify key concept: Define the required principles for Nucleus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It contains most of the cell''s genetic material."],"options":[{"text":"It produces all ATP","is_correct":false},{"text":"It contains most of the cell''s genetic material","is_correct":false},{"text":"It forms the cell wall","is_correct":false},{"text":"It controls water movement only","is_correct":false},{"text":"It contains most of the cell''s genetic material.","is_correct":true}],"conceptId":"biology_cell_biology_nucleus","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Nucleus"}', 0),
  (2761, 692, 'What are chromosomes made from?', 'mcq', 1, 'Focus on the core principle of Nucleus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Nucleus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Genetic material containing DNA.","steps":["Step 1: Identify key concept: Define the required principles for Nucleus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Genetic material containing DNA."],"options":[{"text":"Only water","is_correct":false},{"text":"Genetic material containing DNA","is_correct":false},{"text":"Cellulose","is_correct":false},{"text":"Starch","is_correct":false},{"text":"Genetic material containing DNA.","is_correct":true}],"conceptId":"biology_cell_biology_nucleus","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Nucleus"}', 1),
  (2762, 692, 'Which process depends on genetic information in the nucleus?', 'mcq', 1, 'Focus on the core principle of Nucleus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Nucleus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell division","steps":["Step 1: Identify key concept: Define the required principles for Nucleus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell division"],"options":[{"text":"Cell division","is_correct":true},{"text":"Evaporation","is_correct":false},{"text":"Melting","is_correct":false},{"text":"Rusting","is_correct":false}],"conceptId":"biology_cell_biology_nucleus","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Nucleus"}', 2),
  (2763, 693, 'What important process occurs in mitochondria?', 'mcq', 1, 'Focus on the core principle of Mitochondria.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitochondria.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Important stages of aerobic respiration.","steps":["Step 1: Identify key concept: Define the required principles for Mitochondria.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Important stages of aerobic respiration."],"options":[{"text":"Photosynthesis only","is_correct":false},{"text":"Important stages of aerobic respiration","is_correct":false},{"text":"Digestion of food in the intestine","is_correct":false},{"text":"Blood clotting","is_correct":false},{"text":"Important stages of aerobic respiration.","is_correct":true}],"conceptId":"biology_cell_biology_mitochondria","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Mitochondria"}', 0),
  (2764, 693, 'Why are mitochondria numerous in muscle cells?', 'mcq', 1, 'Focus on the core principle of Mitochondria.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitochondria.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Muscle cells have a high demand for energy.","steps":["Step 1: Identify key concept: Define the required principles for Mitochondria.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Muscle cells have a high demand for energy."],"options":[{"text":"Muscle cells do not need energy","is_correct":false},{"text":"Muscle cells have a high demand for energy","is_correct":false},{"text":"Mitochondria store genetic information","is_correct":false},{"text":"Muscle cells contain no cytoplasm","is_correct":false},{"text":"Muscle cells have a high demand for energy.","is_correct":true}],"conceptId":"biology_cell_biology_mitochondria","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Mitochondria"}', 1),
  (2765, 693, 'Why is ''powerhouse of the cell'' an incomplete description?', 'mcq', 1, 'Focus on the core principle of Mitochondria.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitochondria.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It does not explain that mitochondria are sites of important stages of aerobic respiration.","steps":["Step 1: Identify key concept: Define the required principles for Mitochondria.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It does not explain that mitochondria are sites of important stages of aerobic respiration."],"options":[{"text":"Mitochondria do not release energy","is_correct":false},{"text":"It does not explain their role in aerobic respiration","is_correct":false},{"text":"Mitochondria are found only in plants","is_correct":false},{"text":"Mitochondria are part of the cell wall","is_correct":false},{"text":"It does not explain that mitochondria are sites of important stages of aerobic respiration.","is_correct":true}],"conceptId":"biology_cell_biology_mitochondria","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Mitochondria"}', 2),
  (2766, 694, 'What is the main function of ribosomes?', 'mcq', 1, 'Focus on the core principle of Ribosomes.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ribosomes.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Protein synthesis.","steps":["Step 1: Identify key concept: Define the required principles for Ribosomes.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Protein synthesis."],"options":[{"text":"Protein synthesis","is_correct":false},{"text":"Storing water","is_correct":false},{"text":"Controlling entry of substances","is_correct":false},{"text":"Producing urine","is_correct":false},{"text":"Protein synthesis.","is_correct":true}],"conceptId":"biology_cell_biology_ribosomes","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Ribosomes"}', 0),
  (2767, 694, 'What are proteins built from?', 'mcq', 1, 'Focus on the core principle of Ribosomes.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ribosomes.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Amino acids.","steps":["Step 1: Identify key concept: Define the required principles for Ribosomes.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Amino acids."],"options":[{"text":"Amino acids","is_correct":false},{"text":"Fatty acids only","is_correct":false},{"text":"Mineral salts","is_correct":false},{"text":"Glucose molecules only","is_correct":false},{"text":"Amino acids.","is_correct":true}],"conceptId":"biology_cell_biology_ribosomes","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Ribosomes"}', 1),
  (2768, 694, 'Which structure contains the genetic information used to specify proteins?', 'mcq', 1, 'Focus on the core principle of Ribosomes.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ribosomes.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The nucleus contains the cell''s genetic material.","steps":["Step 1: Identify key concept: Define the required principles for Ribosomes.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The nucleus contains the cell''s genetic material."],"options":[{"text":"Cell wall","is_correct":false},{"text":"Nucleus","is_correct":false},{"text":"Vacuole","is_correct":false},{"text":"Cell membrane","is_correct":false},{"text":"The nucleus contains the cell''s genetic material.","is_correct":true}],"conceptId":"biology_cell_biology_ribosomes","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Ribosomes"}', 2),
  (2769, 695, 'What is the main function of the plant cell wall?', 'mcq', 1, 'Focus on the core principle of Cell Wall.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Wall.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To provide strength and support.","steps":["Step 1: Identify key concept: Define the required principles for Cell Wall.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To provide strength and support."],"options":[{"text":"To produce proteins","is_correct":false},{"text":"To provide strength and support","is_correct":false},{"text":"To control all cell activities","is_correct":false},{"text":"To release oxygen","is_correct":false},{"text":"To provide strength and support.","is_correct":true}],"conceptId":"biology_cell_biology_cell_wall","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Cell Wall"}', 0),
  (2770, 695, 'What is the plant cell wall mainly made of?', 'mcq', 1, 'Focus on the core principle of Cell Wall.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Wall.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cellulose","steps":["Step 1: Identify key concept: Define the required principles for Cell Wall.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cellulose"],"options":[{"text":"Cellulose","is_correct":true},{"text":"Protein only","is_correct":false},{"text":"Starch","is_correct":false},{"text":"DNA","is_correct":false}],"conceptId":"biology_cell_biology_cell_wall","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Cell Wall"}', 1),
  (2771, 695, 'Why does a plant cell need both a cell wall and a cell membrane?', 'mcq', 1, 'Focus on the core principle of Cell Wall.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Cell Wall.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The cell wall provides strength while the membrane controls movement of substances.","steps":["Step 1: Identify key concept: Define the required principles for Cell Wall.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The cell wall provides strength while the membrane controls movement of substances."],"options":[{"text":"Both perform exactly the same function","is_correct":false},{"text":"The wall provides strength while the membrane controls substance movement","is_correct":false},{"text":"The membrane provides strength while the wall makes proteins","is_correct":false},{"text":"Neither structure has a specific function","is_correct":false},{"text":"The cell wall provides strength while the membrane controls movement of substances.","is_correct":true}],"conceptId":"biology_cell_biology_cell_wall","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Cell Wall"}', 2),
  (2772, 696, 'What does the large permanent vacuole contain?', 'mcq', 1, 'Focus on the core principle of Large Permanent Vacuole.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell sap.","steps":["Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell sap."],"options":[{"text":"Cell sap","is_correct":false},{"text":"Only DNA","is_correct":false},{"text":"Only chlorophyll","is_correct":false},{"text":"Only oxygen","is_correct":false},{"text":"Cell sap.","is_correct":true}],"conceptId":"biology_cell_biology_large_permanent_vacuole","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Large Permanent Vacuole"}', 0),
  (2773, 696, 'How does the vacuole help keep a plant firm?', 'mcq', 1, 'Focus on the core principle of Large Permanent Vacuole.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Water in the vacuole helps maintain turgor pressure.","steps":["Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Water in the vacuole helps maintain turgor pressure."],"options":[{"text":"It produces proteins","is_correct":false},{"text":"Water in it helps maintain turgor pressure","is_correct":false},{"text":"It removes all carbon dioxide","is_correct":false},{"text":"It destroys the cell wall","is_correct":false},{"text":"Water in the vacuole helps maintain turgor pressure.","is_correct":true}],"conceptId":"biology_cell_biology_large_permanent_vacuole","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Large Permanent Vacuole"}', 1),
  (2774, 696, 'What may happen when plant cells lose too much water?', 'mcq', 1, 'Focus on the core principle of Large Permanent Vacuole.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Turgor pressure decreases and the plant may wilt.","steps":["Step 1: Identify key concept: Define the required principles for Large Permanent Vacuole.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Turgor pressure decreases and the plant may wilt."],"options":[{"text":"Turgor pressure increases indefinitely","is_correct":false},{"text":"The plant may wilt","is_correct":false},{"text":"The cell becomes a red blood cell","is_correct":false},{"text":"Photosynthesis always increases","is_correct":false},{"text":"Turgor pressure decreases and the plant may wilt.","is_correct":true}],"conceptId":"biology_cell_biology_large_permanent_vacuole","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Large Permanent Vacuole"}', 2),
  (2775, 697, 'Which structure is found in both typical plant and animal cells?', 'mcq', 1, 'Focus on the core principle of Structures Shared by Plant and Animal Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell membrane","steps":["Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell membrane"],"options":[{"text":"Cell wall","is_correct":false},{"text":"Chloroplast","is_correct":false},{"text":"Cell membrane","is_correct":true},{"text":"Large permanent vacuole","is_correct":false}],"conceptId":"biology_cell_biology_structures_shared_by_plant_and_animal_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Structures Shared by Plant and Animal Cells"}', 0),
  (2776, 697, 'Which structure contains genetic material in both plant and animal cells?', 'mcq', 1, 'Focus on the core principle of Structures Shared by Plant and Animal Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Nucleus","steps":["Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Nucleus"],"options":[{"text":"Nucleus","is_correct":true},{"text":"Cell wall","is_correct":false},{"text":"Vacuole","is_correct":false},{"text":"Chloroplast","is_correct":false}],"conceptId":"biology_cell_biology_structures_shared_by_plant_and_animal_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Structures Shared by Plant and Animal Cells"}', 1),
  (2777, 697, 'Why do both plant and animal cells contain mitochondria?', 'mcq', 1, 'Focus on the core principle of Structures Shared by Plant and Animal Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Both require energy for cellular processes.","steps":["Step 1: Identify key concept: Define the required principles for Structures Shared by Plant and Animal Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Both require energy for cellular processes."],"options":[{"text":"Both need to make cellulose","is_correct":false},{"text":"Both require energy for cellular processes","is_correct":false},{"text":"Both perform photosynthesis","is_correct":false},{"text":"Both have cell walls","is_correct":false},{"text":"Both require energy for cellular processes.","is_correct":true}],"conceptId":"biology_cell_biology_structures_shared_by_plant_and_animal_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Structures Shared by Plant and Animal Cells"}', 2),
  (2778, 698, 'Which structure distinguishes a typical plant cell from an animal cell?', 'mcq', 1, 'Focus on the core principle of Plant Cell vs Animal Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell wall","steps":["Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell wall"],"options":[{"text":"Cell membrane","is_correct":false},{"text":"Cytoplasm","is_correct":false},{"text":"Cell wall","is_correct":true},{"text":"Ribosome","is_correct":false}],"conceptId":"biology_cell_biology_plant_cell_vs_animal_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Plant Cell vs Animal Cell"}', 0),
  (2779, 698, 'A cell contains chloroplasts and a cell wall. Which is the best conclusion?', 'mcq', 1, 'Focus on the core principle of Plant Cell vs Animal Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It is a plant cell.","steps":["Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It is a plant cell."],"options":[{"text":"It is a typical animal cell","is_correct":false},{"text":"It is a plant cell","is_correct":false},{"text":"It is not a living cell","is_correct":false},{"text":"It must be a red blood cell","is_correct":false},{"text":"It is a plant cell.","is_correct":true}],"conceptId":"biology_cell_biology_plant_cell_vs_animal_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Plant Cell vs Animal Cell"}', 1),
  (2780, 698, 'Why do plant cells have chloroplasts?', 'mcq', 1, 'Focus on the core principle of Plant Cell vs Animal Cell.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Chloroplasts allow photosynthetic cells to capture light energy for photosynthesis.","steps":["Step 1: Identify key concept: Define the required principles for Plant Cell vs Animal Cell.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Chloroplasts allow photosynthetic cells to capture light energy for photosynthesis."],"options":[{"text":"To produce urine","is_correct":false},{"text":"To capture light energy for photosynthesis","is_correct":false},{"text":"To control blood flow","is_correct":false},{"text":"To make the cell wall from protein","is_correct":false},{"text":"Chloroplasts allow photosynthetic cells to capture light energy for photosynthesis.","is_correct":true}],"conceptId":"biology_cell_biology_plant_cell_vs_animal_cell","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Plant Cell vs Animal Cell"}', 2),
  (2781, 699, 'Which sequence gives the strongest biological explanation?', 'mcq', 1, 'Focus on the core principle of Explaining Cell Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Structure → Function → Advantage","steps":["Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Structure → Function → Advantage"],"options":[{"text":"Name → Colour → Size","is_correct":false},{"text":"Structure → Function → Advantage","is_correct":true},{"text":"Function → Name → Colour","is_correct":false},{"text":"Size → Shape → Name","is_correct":false}],"conceptId":"biology_cell_biology_explaining_cell_differences","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Explaining Cell Differences"}', 0),
  (2782, 699, 'Why does a chloroplast help a photosynthetic cell?', 'mcq', 1, 'Focus on the core principle of Explaining Cell Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It contains chlorophyll that absorbs light energy needed for photosynthesis.","steps":["Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It contains chlorophyll that absorbs light energy needed for photosynthesis."],"options":[{"text":"It stores urine","is_correct":false},{"text":"It contains chlorophyll that absorbs light energy","is_correct":false},{"text":"It controls the nucleus","is_correct":false},{"text":"It produces cellulose directly from oxygen","is_correct":false},{"text":"It contains chlorophyll that absorbs light energy needed for photosynthesis.","is_correct":true}],"conceptId":"biology_cell_biology_explaining_cell_differences","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Explaining Cell Differences"}', 1),
  (2783, 699, 'Why does a cell wall help a plant cell?', 'mcq', 1, 'Focus on the core principle of Explaining Cell Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It provides mechanical support and helps the cell resist excessive expansion.","steps":["Step 1: Identify key concept: Define the required principles for Explaining Cell Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It provides mechanical support and helps the cell resist excessive expansion."],"options":[{"text":"It makes proteins","is_correct":false},{"text":"It provides mechanical support","is_correct":false},{"text":"It controls all genetic information","is_correct":false},{"text":"It digests glucose","is_correct":false},{"text":"It provides mechanical support and helps the cell resist excessive expansion.","is_correct":true}],"conceptId":"biology_cell_biology_explaining_cell_differences","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Explaining Cell Differences"}', 2),
  (2784, 700, 'What happens to cell number when one cell divides into two?', 'mcq', 1, 'Focus on the core principle of Growth by Increase in Cell Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It increases from one to two","steps":["Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It increases from one to two"],"options":[{"text":"It increases from one to two","is_correct":true},{"text":"It decreases to zero","is_correct":false},{"text":"It remains one","is_correct":false},{"text":"It becomes four immediately","is_correct":false}],"conceptId":"biology_cell_biology_growth_by_increase_in_cell_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Growth by Increase in Cell Number"}', 0),
  (2785, 700, 'If 2 cells each divide once, how many cells result?', 'mcq', 1, 'Focus on the core principle of Growth by Increase in Cell Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 4","steps":["Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 4"],"options":[{"text":"2","is_correct":false},{"text":"3","is_correct":false},{"text":"4","is_correct":true},{"text":"6","is_correct":false}],"conceptId":"biology_cell_biology_growth_by_increase_in_cell_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Growth by Increase in Cell Number"}', 1),
  (2786, 700, 'Starting with one cell, how many cells are produced after three complete rounds of division if every daughter cell divides?', 'mcq', 1, 'Focus on the core principle of Growth by Increase in Cell Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 8","steps":["Step 1: Identify key concept: Define the required principles for Growth by Increase in Cell Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 8"],"options":[{"text":"3","is_correct":false},{"text":"6","is_correct":false},{"text":"8","is_correct":true},{"text":"12","is_correct":false}],"conceptId":"biology_cell_biology_growth_by_increase_in_cell_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Growth by Increase in Cell Number"}', 2),
  (2787, 701, 'What is a unicellular organism?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An organism made of one cell.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An organism made of one cell."],"options":[{"text":"An organism made of one cell","is_correct":false},{"text":"An organism made only of tissues","is_correct":false},{"text":"An organism made of many organs","is_correct":false},{"text":"A non-living cell","is_correct":false},{"text":"An organism made of one cell.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 0),
  (2788, 701, 'What is a multicellular organism?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An organism made of many cells.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An organism made of many cells."],"options":[{"text":"An organism made of one cell","is_correct":false},{"text":"An organism made of many cells","is_correct":false},{"text":"An organism without cells","is_correct":false},{"text":"A group of unrelated cells","is_correct":false},{"text":"An organism made of many cells.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 1),
  (2789, 701, 'Why can multicellular organisms have specialised cells?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because they contain many cells that can become adapted for different functions.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because they contain many cells that can become adapted for different functions."],"options":[{"text":"Because every cell performs exactly the same function","is_correct":false},{"text":"Because different cells can become adapted for different functions","is_correct":false},{"text":"Because multicellular organisms have no organs","is_correct":false},{"text":"Because their cells are non-living","is_correct":false},{"text":"Because they contain many cells that can become adapted for different functions.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 2),
  (2790, 701, 'What is a unicellular organism?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An organism consisting of one cell.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An organism consisting of one cell."],"options":[{"text":"An organism consisting of one cell","is_correct":false},{"text":"An organism consisting only of tissues","is_correct":false},{"text":"An organism without DNA","is_correct":false},{"text":"An organism with no cytoplasm","is_correct":false},{"text":"An organism consisting of one cell.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q4","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 3),
  (2791, 701, 'How does a multicellular organism differ from a unicellular organism?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A multicellular organism contains many cells that can become specialised for different functions.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A multicellular organism contains many cells that can become specialised for different functions."],"options":[{"text":"It contains many cells that can specialise for different functions","is_correct":false},{"text":"It has no specialised cells","is_correct":false},{"text":"It has no genetic material","is_correct":false},{"text":"It contains only one organelle","is_correct":false},{"text":"A multicellular organism contains many cells that can become specialised for different functions.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q5","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 4),
  (2792, 701, 'In a unicellular organism, who performs the essential life processes?', 'mcq', 1, 'Focus on the core principle of Unicellular and Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The single cell.","steps":["Step 1: Identify key concept: Define the required principles for Unicellular and Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The single cell."],"options":[{"text":"The single cell","is_correct":false},{"text":"A group of organs","is_correct":false},{"text":"A nervous system","is_correct":false},{"text":"A collection of tissues","is_correct":false},{"text":"The single cell.","is_correct":true}],"conceptId":"biology_cell_biology_unicellular_and_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q6","subject":"biology","chapter":"cell_biology","topic":"Unicellular and Multicellular Organisms"}', 5),
  (2793, 702, 'Arrange these in the correct order from smallest to largest.', 'mcq', 1, 'Focus on the core principle of How Cells Are Organised in Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Cell → Tissue → Organ → Organ system → Organism","steps":["Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Cell → Tissue → Organ → Organ system → Organism"],"options":[{"text":"Cell → Tissue → Organ → Organ system → Organism","is_correct":true},{"text":"Organ → Cell → Tissue → Organism → Organ system","is_correct":false},{"text":"Tissue → Cell → Organ → Organism → Organ system","is_correct":false},{"text":"Cell → Organ → Tissue → Organism → Organ system","is_correct":false}],"conceptId":"biology_cell_biology_how_cells_are_organised_in_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"How Cells Are Organised in Multicellular Organisms"}', 0),
  (2794, 702, 'What is a tissue?', 'mcq', 1, 'Focus on the core principle of How Cells Are Organised in Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A group of similar cells working together to perform a particular function.","steps":["Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A group of similar cells working together to perform a particular function."],"options":[{"text":"A single organ","is_correct":false},{"text":"A group of similar cells working together","is_correct":false},{"text":"A complete organism","is_correct":false},{"text":"A group of organ systems","is_correct":false},{"text":"A group of similar cells working together to perform a particular function.","is_correct":true}],"conceptId":"biology_cell_biology_how_cells_are_organised_in_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"How Cells Are Organised in Multicellular Organisms"}', 1),
  (2795, 702, 'Why are organs usually made of different tissues?', 'mcq', 1, 'Focus on the core principle of How Cells Are Organised in Multicellular Organisms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Different tissues perform different functions that contribute to the function of the organ.","steps":["Step 1: Identify key concept: Define the required principles for How Cells Are Organised in Multicellular Organisms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Different tissues perform different functions that contribute to the function of the organ."],"options":[{"text":"Because all tissues have exactly the same function","is_correct":false},{"text":"Because different tissues contribute different functions","is_correct":false},{"text":"Because organs contain no cells","is_correct":false},{"text":"Because tissues cannot work together","is_correct":false},{"text":"Different tissues perform different functions that contribute to the function of the organ.","is_correct":true}],"conceptId":"biology_cell_biology_how_cells_are_organised_in_multicellular_organisms","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"How Cells Are Organised in Multicellular Organisms"}', 2),
