  (2989, 766, 'Which stage of Meiosis I separates homologous chromosomes?', 'mcq', 1, 'Focus on the core principle of Meiosis I.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis I.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Anaphase I","steps":["Step 1: Identify key concept: Define the required principles for Meiosis I.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Anaphase I"],"options":[{"text":"Prophase I","is_correct":false},{"text":"Metaphase I","is_correct":false},{"text":"Anaphase I","is_correct":true},{"text":"Telophase I","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_i","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Meiosis I"}', 1),
  (2990, 766, 'What is one major result of Meiosis I?', 'mcq', 1, 'Focus on the core principle of Meiosis I.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis I.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The chromosome sets are separated into different cells","steps":["Step 1: Identify key concept: Define the required principles for Meiosis I.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The chromosome sets are separated into different cells"],"options":[{"text":"The chromosome sets are separated into different cells","is_correct":true},{"text":"Chromosome number doubles","is_correct":false},{"text":"DNA is completely destroyed","is_correct":false},{"text":"Four cells immediately form","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_i","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Meiosis I"}', 2),
  (2991, 767, 'What causes chromosome number to be reduced during Meiosis I?', 'mcq', 1, 'Focus on the core principle of Meiosis I and Chromosome Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Homologous chromosomes separate","steps":["Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Homologous chromosomes separate"],"options":[{"text":"Homologous chromosomes separate","is_correct":true},{"text":"Sister chromatids separate","is_correct":false},{"text":"DNA is destroyed","is_correct":false},{"text":"The cell loses its membrane","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_i_and_chromosome_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Meiosis I and Chromosome Number"}', 0),
  (2992, 767, 'A cell has 12 chromosomes in 6 homologous pairs. How many chromosomes are in each cell after Meiosis I?', 'mcq', 1, 'Focus on the core principle of Meiosis I and Chromosome Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 6","steps":["Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 6"],"options":[{"text":"3","is_correct":false},{"text":"6","is_correct":true},{"text":"12","is_correct":false},{"text":"24","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_i_and_chromosome_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Meiosis I and Chromosome Number"}', 1),
  (2993, 767, 'A human starting cell has 46 chromosomes. What is the chromosome number after Meiosis I?', 'mcq', 1, 'Focus on the core principle of Meiosis I and Chromosome Number.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 23","steps":["Step 1: Identify key concept: Define the required principles for Meiosis I and Chromosome Number.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 23"],"options":[{"text":"12","is_correct":false},{"text":"23","is_correct":true},{"text":"46","is_correct":false},{"text":"92","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_i_and_chromosome_number","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Meiosis I and Chromosome Number"}', 2),
