  (3008, 772, 'How many cells normally result after meiosis is complete?', 'mcq', 1, 'Focus on the core principle of Meiosis as a Complete Sequence.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis as a Complete Sequence.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Four","steps":["Step 1: Identify key concept: Define the required principles for Meiosis as a Complete Sequence.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Four"],"options":[{"text":"One","is_correct":false},{"text":"Two","is_correct":false},{"text":"Four","is_correct":true},{"text":"Eight","is_correct":false}],"conceptId":"biology_cell_biology_meiosis_as_a_complete_sequence","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Meiosis as a Complete Sequence"}', 2),
  (3009, 773, 'Which process normally produces two daughter cells?', 'mcq', 1, 'Focus on the core principle of Mitosis and Meiosis: Final Comparison.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Mitosis","steps":["Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Mitosis"],"options":[{"text":"Mitosis","is_correct":true},{"text":"Meiosis","is_correct":false},{"text":"Fertilisation","is_correct":false},{"text":"Mutation","is_correct":false}],"conceptId":"biology_cell_biology_mitosis_and_meiosis_final_comparison","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Mitosis and Meiosis: Final Comparison"}', 0),
  (3010, 773, 'Which process reduces chromosome number by half?', 'mcq', 1, 'Focus on the core principle of Mitosis and Meiosis: Final Comparison.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Meiosis","steps":["Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Meiosis"],"options":[{"text":"Mitosis","is_correct":false},{"text":"Meiosis","is_correct":true},{"text":"Cytokinesis","is_correct":false},{"text":"DNA replication","is_correct":false}],"conceptId":"biology_cell_biology_mitosis_and_meiosis_final_comparison","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Mitosis and Meiosis: Final Comparison"}', 1),
  (3011, 773, 'Which process normally produces four haploid cells?', 'mcq', 1, 'Focus on the core principle of Mitosis and Meiosis: Final Comparison.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Meiosis","steps":["Step 1: Identify key concept: Define the required principles for Mitosis and Meiosis: Final Comparison.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Meiosis"],"options":[{"text":"Mitosis","is_correct":false},{"text":"Meiosis","is_correct":true},{"text":"Binary fission","is_correct":false},{"text":"Fertilisation","is_correct":false}],"conceptId":"biology_cell_biology_mitosis_and_meiosis_final_comparison","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Mitosis and Meiosis: Final Comparison"}', 2),
  (3012, 774, 'Why is DNA copied before mitosis?', 'mcq', 1, 'Focus on the core principle of Why Mitosis Produces Genetically Similar Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: So each daughter cell can receive a complete set of genetic information","steps":["Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: So each daughter cell can receive a complete set of genetic information"],"options":[{"text":"So each daughter cell can receive a complete set of genetic information","is_correct":true},{"text":"So chromosomes disappear","is_correct":false},{"text":"So the cell loses its nucleus","is_correct":false},{"text":"So meiosis can occur","is_correct":false}],"conceptId":"biology_cell_biology_why_mitosis_produces_genetically_similar_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q1","subject":"biology","chapter":"cell_biology","topic":"Why Mitosis Produces Genetically Similar Cells"}', 0),
  (3013, 774, 'What happens to sister chromatids during anaphase?', 'mcq', 1, 'Focus on the core principle of Why Mitosis Produces Genetically Similar Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They separate and move to opposite poles","steps":["Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They separate and move to opposite poles"],"options":[{"text":"They separate and move to opposite poles","is_correct":true},{"text":"They disappear","is_correct":false},{"text":"They form a cell wall","is_correct":false},{"text":"They leave the cell","is_correct":false}],"conceptId":"biology_cell_biology_why_mitosis_produces_genetically_similar_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q2","subject":"biology","chapter":"cell_biology","topic":"Why Mitosis Produces Genetically Similar Cells"}', 1),
  (3014, 774, 'Why do daughter cells produced by normal mitosis have equivalent genetic information?', 'mcq', 1, 'Focus on the core principle of Why Mitosis Produces Genetically Similar Cells.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Copied chromosomes are accurately distributed between the daughter nuclei","steps":["Step 1: Identify key concept: Define the required principles for Why Mitosis Produces Genetically Similar Cells.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Copied chromosomes are accurately distributed between the daughter nuclei"],"options":[{"text":"Copied chromosomes are accurately distributed between the daughter nuclei","is_correct":true},{"text":"The chromosomes are destroyed","is_correct":false},{"text":"The cells receive no DNA","is_correct":false},{"text":"The nucleus divides without chromosomes","is_correct":false}],"conceptId":"biology_cell_biology_why_mitosis_produces_genetically_similar_cells","skillId":"biology_cell_biology","subskillId":"biology_cell_biology_q3","subject":"biology","chapter":"cell_biology","topic":"Why Mitosis Produces Genetically Similar Cells"}', 2),
