  (3164, 824, 'What percentage of offspring are predicted to be Rh positive?', 'mcq', 1, 'Focus on the core principle of Rhesus Factor Cross: RR × rr.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Rhesus Factor Cross: RR × rr.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 100%.","steps":["Step 1: Identify key concept: Define the required principles for Rhesus Factor Cross: RR × rr.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 100%."],"options":[{"text":"100%.","is_correct":true},{"text":"75%.","is_correct":false},{"text":"50%.","is_correct":false},{"text":"0%.","is_correct":false}],"conceptId":"biology_genetics_rhesus_factor_cross_rr_rr","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Rhesus Factor Cross: RR × rr"}', 2),
  (3165, 825, 'What genotype must an Rh-negative child have?', 'mcq', 1, 'Focus on the core principle of Determining an Unknown Rhesus Genotype.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: rr.","steps":["Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: rr."],"options":[{"text":"rr.","is_correct":true},{"text":"RR.","is_correct":false},{"text":"Rr.","is_correct":false},{"text":"R only.","is_correct":false}],"conceptId":"biology_genetics_determining_an_unknown_rhesus_genotype","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Determining an Unknown Rhesus Genotype"}', 0),
  (3166, 825, 'If an Rh-positive parent has an Rh-negative child, what must the Rh-positive parent''s genotype be?', 'mcq', 1, 'Focus on the core principle of Determining an Unknown Rhesus Genotype.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Rr.","steps":["Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Rr."],"options":[{"text":"Rr.","is_correct":true},{"text":"RR.","is_correct":false},{"text":"rr.","is_correct":false},{"text":"R.","is_correct":false}],"conceptId":"biology_genetics_determining_an_unknown_rhesus_genotype","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Determining an Unknown Rhesus Genotype"}', 1),
  (3167, 825, 'Why must an Rh-positive parent with an Rh-negative child carry r?', 'mcq', 1, 'Focus on the core principle of Determining an Unknown Rhesus Genotype.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The child must receive an r allele from that parent.","steps":["Step 1: Identify key concept: Define the required principles for Determining an Unknown Rhesus Genotype.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The child must receive an r allele from that parent."],"options":[{"text":"The child must receive an r allele from that parent.","is_correct":true},{"text":"Rh-positive parents cannot carry r.","is_correct":false},{"text":"The child receives both alleles from one parent.","is_correct":false},{"text":"The r allele can only come from the environment.","is_correct":false}],"conceptId":"biology_genetics_determining_an_unknown_rhesus_genotype","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Determining an Unknown Rhesus Genotype"}', 2),
  (3168, 826, 'Why are group O red cells useful in basic ABO compatibility reasoning?', 'mcq', 1, 'Focus on the core principle of ABO Red Cell Compatibility.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They have neither A nor B antigen.","steps":["Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They have neither A nor B antigen."],"options":[{"text":"They have neither A nor B antigen.","is_correct":true},{"text":"They have both A and B antigens.","is_correct":false},{"text":"They contain only A antigen.","is_correct":false},{"text":"They contain only B antigen.","is_correct":false}],"conceptId":"biology_genetics_abo_red_cell_compatibility","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"ABO Red Cell Compatibility"}', 0),
  (3169, 826, 'A group B person has which ABO antibody in their plasma?', 'mcq', 1, 'Focus on the core principle of ABO Red Cell Compatibility.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Anti-A.","steps":["Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Anti-A."],"options":[{"text":"Anti-A.","is_correct":true},{"text":"Anti-B.","is_correct":false},{"text":"Both anti-A and anti-B.","is_correct":false},{"text":"No antibodies.","is_correct":false}],"conceptId":"biology_genetics_abo_red_cell_compatibility","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"ABO Red Cell Compatibility"}', 1),
  (3170, 826, 'Why can group A red cells be dangerous for a group B recipient?', 'mcq', 1, 'Focus on the core principle of ABO Red Cell Compatibility.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The recipient has anti-A antibodies that can react with A antigen.","steps":["Step 1: Identify key concept: Define the required principles for ABO Red Cell Compatibility.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The recipient has anti-A antibodies that can react with A antigen."],"options":[{"text":"The recipient has anti-A antibodies that can react with A antigen.","is_correct":true},{"text":"Group B recipients have no antibodies.","is_correct":false},{"text":"Group A cells have no antigens.","is_correct":false},{"text":"The Rhesus factor removes all antibodies.","is_correct":false}],"conceptId":"biology_genetics_abo_red_cell_compatibility","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"ABO Red Cell Compatibility"}', 2),
  (3171, 827, 'What can happen to an advantageous allele over many generations?', 'mcq', 1, 'Focus on the core principle of How Advantageous Alleles Become More Common.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can become more common in the population.","steps":["Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can become more common in the population."],"options":[{"text":"It can become more common in the population.","is_correct":true},{"text":"It must disappear immediately.","is_correct":false},{"text":"It can only exist in one individual.","is_correct":false},{"text":"It automatically changes into a chromosome.","is_correct":false}],"conceptId":"biology_genetics_how_advantageous_alleles_become_more_common","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"How Advantageous Alleles Become More Common"}', 0),
  (3172, 827, 'Why can an advantageous allele become more common?', 'mcq', 1, 'Focus on the core principle of How Advantageous Alleles Become More Common.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Individuals carrying it may leave more surviving offspring.","steps":["Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Individuals carrying it may leave more surviving offspring."],"options":[{"text":"Individuals carrying it may leave more surviving offspring.","is_correct":true},{"text":"Individuals deliberately choose to copy the allele.","is_correct":false},{"text":"The environment directly writes the allele into DNA.","is_correct":false},{"text":"All other alleles disappear immediately.","is_correct":false}],"conceptId":"biology_genetics_how_advantageous_alleles_become_more_common","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"How Advantageous Alleles Become More Common"}', 1),
  (3173, 827, 'What changes over generations as a result of natural selection?', 'mcq', 1, 'Focus on the core principle of How Advantageous Alleles Become More Common.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The frequency of alleles in the population can change.","steps":["Step 1: Identify key concept: Define the required principles for How Advantageous Alleles Become More Common.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The frequency of alleles in the population can change."],"options":[{"text":"The frequency of alleles in the population can change.","is_correct":true},{"text":"Every individual''s DNA changes in the same way.","is_correct":false},{"text":"The number of species always becomes zero.","is_correct":false},{"text":"All mutations are removed.","is_correct":false}],"conceptId":"biology_genetics_how_advantageous_alleles_become_more_common","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"How Advantageous Alleles Become More Common"}', 2),
  (3174, 828, 'What can a sequence of related fossils from different periods show?', 'mcq', 1, 'Focus on the core principle of What Fossils Can Reveal.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can show that characteristics of a group changed over time.","steps":["Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can show that characteristics of a group changed over time."],"options":[{"text":"That characteristics of a group changed over time","is_correct":false},{"text":"That every organism changed during its lifetime","is_correct":false},{"text":"That all organisms appeared simultaneously","is_correct":false},{"text":"That fossils contain complete organisms","is_correct":false},{"text":"It can show that characteristics of a group changed over time.","is_correct":true}],"conceptId":"biology_genetics_what_fossils_can_reveal","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"What Fossils Can Reveal"}', 0),
  (3175, 828, 'Why should fossils be interpreted carefully?', 'mcq', 1, 'Focus on the core principle of What Fossils Can Reveal.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Fossils are often incomplete and may not show every stage of evolutionary change.","steps":["Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Fossils are often incomplete and may not show every stage of evolutionary change."],"options":[{"text":"Fossils are often incomplete and may not show every stage","is_correct":false},{"text":"Fossils are always fake","is_correct":false},{"text":"Fossils cannot be compared","is_correct":false},{"text":"Fossils contain no biological information","is_correct":false},{"text":"Fossils are often incomplete and may not show every stage of evolutionary change.","is_correct":true}],"conceptId":"biology_genetics_what_fossils_can_reveal","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"What Fossils Can Reveal"}', 1),
  (3176, 828, 'A sequence of fossils shows a gradual change in a bone structure. What is the best conclusion?', 'mcq', 1, 'Focus on the core principle of What Fossils Can Reveal.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The sequence provides evidence that the characteristic changed over generations.","steps":["Step 1: Identify key concept: Define the required principles for What Fossils Can Reveal.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The sequence provides evidence that the characteristic changed over generations."],"options":[{"text":"The characteristic changed over generations","is_correct":false},{"text":"One organism deliberately changed its bone","is_correct":false},{"text":"The environment instantly changed every organism","is_correct":false},{"text":"The organisms were definitely unrelated","is_correct":false},{"text":"The sequence provides evidence that the characteristic changed over generations.","is_correct":true}],"conceptId":"biology_genetics_what_fossils_can_reveal","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"What Fossils Can Reveal"}', 2),
  (3177, 829, 'Why is the fossil record incomplete?', 'mcq', 1, 'Focus on the core principle of Limitations of the Fossil Record.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Fossilisation is rare and many organisms or their remains are destroyed before they can become fossils.","steps":["Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Fossilisation is rare and many organisms or their remains are destroyed before they can become fossils."],"options":[{"text":"Fossilisation is rare and many remains are destroyed","is_correct":false},{"text":"All organisms become fossils","is_correct":false},{"text":"Fossils disappear immediately after formation","is_correct":false},{"text":"Scientists refuse to study fossils","is_correct":false},{"text":"Fossilisation is rare and many organisms or their remains are destroyed before they can become fossils.","is_correct":true}],"conceptId":"biology_genetics_limitations_of_the_fossil_record","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Limitations of the Fossil Record"}', 0),
  (3178, 829, 'Why are organisms with hard structures more likely to leave fossils?', 'mcq', 1, 'Focus on the core principle of Limitations of the Fossil Record.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Hard structures such as bones and shells are more resistant to decay and can be preserved.","steps":["Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Hard structures such as bones and shells are more resistant to decay and can be preserved."],"options":[{"text":"They are more resistant to decay and can be preserved","is_correct":false},{"text":"They reproduce faster","is_correct":false},{"text":"They always live underground","is_correct":false},{"text":"They contain more DNA","is_correct":false},{"text":"Hard structures such as bones and shells are more resistant to decay and can be preserved.","is_correct":true}],"conceptId":"biology_genetics_limitations_of_the_fossil_record","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Limitations of the Fossil Record"}', 1),
  (3179, 829, 'Does the absence of a fossil prove that an organism never existed?', 'mcq', 1, 'Focus on the core principle of Limitations of the Fossil Record.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: No. Fossilisation is rare, so an organism may have existed without leaving a fossil.","steps":["Step 1: Identify key concept: Define the required principles for Limitations of the Fossil Record.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: No. Fossilisation is rare, so an organism may have existed without leaving a fossil."],"options":[{"text":"No, because fossilisation is rare","is_correct":false},{"text":"Yes, always","is_correct":false},{"text":"Yes, if the organism was small","is_correct":false},{"text":"No, because fossils are never useful","is_correct":false},{"text":"No. Fossilisation is rare, so an organism may have existed without leaving a fossil.","is_correct":true}],"conceptId":"biology_genetics_limitations_of_the_fossil_record","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Limitations of the Fossil Record"}', 2),
  (3180, 830, 'What is a homologous structure?', 'mcq', 1, 'Focus on the core principle of Homologous Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Homologous Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A structure with a similar underlying structural plan in different organisms, inherited from a common ancestor, even if its function differs.","steps":["Step 1: Identify key concept: Define the required principles for Homologous Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A structure with a similar underlying structural plan in different organisms, inherited from a common ancestor, even if its function differs."],"options":[{"text":"A structure with a similar underlying plan inherited from a common ancestor","is_correct":false},{"text":"A structure found only in one organism","is_correct":false},{"text":"A structure that always performs exactly the same function","is_correct":false},{"text":"A structure that has no inherited component","is_correct":false},{"text":"A structure with a similar underlying structural plan in different organisms, inherited from a common ancestor, even if its function differs.","is_correct":true}],"conceptId":"biology_genetics_homologous_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Homologous Structures"}', 0),
  (3181, 830, 'Why are the forelimbs of humans, bats and whales considered homologous?', 'mcq', 1, 'Focus on the core principle of Homologous Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Homologous Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They have a similar underlying arrangement of bones despite being adapted for different functions.","steps":["Step 1: Identify key concept: Define the required principles for Homologous Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They have a similar underlying arrangement of bones despite being adapted for different functions."],"options":[{"text":"They have similar underlying bone arrangements but different functions","is_correct":false},{"text":"They all fly","is_correct":false},{"text":"They all live in water","is_correct":false},{"text":"They have exactly the same function","is_correct":false},{"text":"They have a similar underlying arrangement of bones despite being adapted for different functions.","is_correct":true}],"conceptId":"biology_genetics_homologous_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Homologous Structures"}', 1),
  (3182, 830, 'What can homologous structures provide evidence for?', 'mcq', 1, 'Focus on the core principle of Homologous Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Homologous Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Common ancestry.","steps":["Step 1: Identify key concept: Define the required principles for Homologous Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Common ancestry."],"options":[{"text":"Common ancestry","is_correct":false},{"text":"Identical habitats","is_correct":false},{"text":"Identical diets","is_correct":false},{"text":"No relationship between organisms","is_correct":false},{"text":"Common ancestry.","is_correct":true}],"conceptId":"biology_genetics_homologous_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Homologous Structures"}', 2),
  (3183, 831, 'What is a vestigial structure?', 'mcq', 1, 'Focus on the core principle of Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A reduced structure that has little or no significant function in its present form compared with the corresponding ancestral structure.","steps":["Step 1: Identify key concept: Define the required principles for Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A reduced structure that has little or no significant function in its present form compared with the corresponding ancestral structure."],"options":[{"text":"A reduced structure with little or no significant function in its present form","is_correct":false},{"text":"A completely new organ","is_correct":false},{"text":"An organ that is always essential for survival","is_correct":false},{"text":"A structure found only in plants","is_correct":false},{"text":"A reduced structure that has little or no significant function in its present form compared with the corresponding ancestral structure.","is_correct":true}],"conceptId":"biology_genetics_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Vestigial Structures"}', 0),
  (3184, 831, 'Why can vestigial structures provide evidence for evolution?', 'mcq', 1, 'Focus on the core principle of Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They may represent reduced remnants of structures that were more important in ancestral organisms.","steps":["Step 1: Identify key concept: Define the required principles for Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They may represent reduced remnants of structures that were more important in ancestral organisms."],"options":[{"text":"They may be reduced remnants of ancestral structures","is_correct":false},{"text":"They prove organisms never change","is_correct":false},{"text":"They show every organ has exactly the same function","is_correct":false},{"text":"They occur only because organisms need them","is_correct":false},{"text":"They may represent reduced remnants of structures that were more important in ancestral organisms.","is_correct":true}],"conceptId":"biology_genetics_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Vestigial Structures"}', 1),
  (3185, 831, 'Why should the human appendix not simply be described as completely useless?', 'mcq', 1, 'Focus on the core principle of Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It has biological functions even though it is greatly reduced compared with the caecum of some herbivorous mammals.","steps":["Step 1: Identify key concept: Define the required principles for Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It has biological functions even though it is greatly reduced compared with the caecum of some herbivorous mammals."],"options":[{"text":"It has biological functions despite being greatly reduced","is_correct":false},{"text":"It has no cells","is_correct":false},{"text":"It is not part of the human body","is_correct":false},{"text":"It performs photosynthesis","is_correct":false},{"text":"It has biological functions even though it is greatly reduced compared with the caecum of some herbivorous mammals.","is_correct":true}],"conceptId":"biology_genetics_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Vestigial Structures"}', 2),
  (3186, 832, 'What is the main feature of a homologous structure?', 'mcq', 1, 'Focus on the core principle of Comparing Homologous and Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A similar underlying structural plan in different organisms.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A similar underlying structural plan in different organisms."],"options":[{"text":"A similar underlying structural plan","is_correct":false},{"text":"Complete absence of function","is_correct":false},{"text":"Small size in every organism","is_correct":false},{"text":"Occurrence only in ancestors","is_correct":false},{"text":"A similar underlying structural plan in different organisms.","is_correct":true}],"conceptId":"biology_genetics_comparing_homologous_and_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Comparing Homologous and Vestigial Structures"}', 0),
  (3187, 832, 'What is the main feature of a vestigial structure?', 'mcq', 1, 'Focus on the core principle of Comparing Homologous and Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It is reduced and has little or no significant function in its present form compared with the ancestral structure.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It is reduced and has little or no significant function in its present form compared with the ancestral structure."],"options":[{"text":"It is reduced compared with the ancestral structure","is_correct":false},{"text":"It always has a completely new function","is_correct":false},{"text":"It is always large","is_correct":false},{"text":"It occurs only in embryos","is_correct":false},{"text":"It is reduced and has little or no significant function in its present form compared with the ancestral structure.","is_correct":true}],"conceptId":"biology_genetics_comparing_homologous_and_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Comparing Homologous and Vestigial Structures"}', 1),
  (3188, 832, 'A group of animals has forelimbs with the same basic bone arrangement but different functions. Which concept applies?', 'mcq', 1, 'Focus on the core principle of Comparing Homologous and Vestigial Structures.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Homologous structures.","steps":["Step 1: Identify key concept: Define the required principles for Comparing Homologous and Vestigial Structures.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Homologous structures."],"options":[{"text":"Homologous structures","is_correct":false},{"text":"Vestigial structures","is_correct":false},{"text":"Acquired characteristics","is_correct":false},{"text":"Environmental variation","is_correct":false},{"text":"Homologous structures.","is_correct":true}],"conceptId":"biology_genetics_comparing_homologous_and_vestigial_structures","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Comparing Homologous and Vestigial Structures"}', 2),
  (3189, 833, 'What is genetic diversity?', 'mcq', 1, 'Focus on the core principle of Genetic Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Variation in inherited characteristics among individuals of the same species","steps":["Step 1: Identify key concept: Define the required principles for Genetic Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Variation in inherited characteristics among individuals of the same species"],"options":[{"text":"Variation in inherited characteristics among individuals of the same species","is_correct":true},{"text":"Variation between different ecosystems only","is_correct":false},{"text":"Variation in weather conditions","is_correct":false},{"text":"Variation in the size of habitats","is_correct":false}],"conceptId":"biology_genetics_genetic_diversity","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Genetic Diversity"}', 0),
  (3190, 833, 'Why can genetic diversity help a population survive environmental change?', 'mcq', 1, 'Focus on the core principle of Genetic Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Some individuals may have inherited characteristics that improve survival","steps":["Step 1: Identify key concept: Define the required principles for Genetic Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Some individuals may have inherited characteristics that improve survival"],"options":[{"text":"Some individuals may have inherited characteristics that improve survival","is_correct":true},{"text":"All individuals become genetically identical","is_correct":false},{"text":"It prevents reproduction","is_correct":false},{"text":"It stops environmental changes","is_correct":false}],"conceptId":"biology_genetics_genetic_diversity","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Genetic Diversity"}', 1),
  (3191, 833, 'Which type of difference is most directly associated with genetic diversity?', 'mcq', 1, 'Focus on the core principle of Genetic Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An inherited difference","steps":["Step 1: Identify key concept: Define the required principles for Genetic Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An inherited difference"],"options":[{"text":"An inherited difference","is_correct":true},{"text":"A difference caused only by temporary weather","is_correct":false},{"text":"A difference caused only by exercise","is_correct":false},{"text":"A difference caused only by learning","is_correct":false}],"conceptId":"biology_genetics_genetic_diversity","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Genetic Diversity"}', 2),
  (3192, 834, 'What does variation mean in biology?', 'mcq', 1, 'Focus on the core principle of Variation in Sexual Reproduction.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Differences in characteristics between individuals of the same species.","steps":["Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Differences in characteristics between individuals of the same species."],"options":[{"text":"Differences between organs in one person","is_correct":false},{"text":"Differences in characteristics between individuals of the same species","is_correct":false},{"text":"The process of cell division","is_correct":false},{"text":"The joining of tissues","is_correct":false},{"text":"Differences in characteristics between individuals of the same species.","is_correct":true}],"conceptId":"biology_genetics_variation_in_sexual_reproduction","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Variation in Sexual Reproduction"}', 0),
  (3193, 834, 'Which process combines genetic information from two parents?', 'mcq', 1, 'Focus on the core principle of Variation in Sexual Reproduction.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Fertilisation.","steps":["Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Fertilisation."],"options":[{"text":"Mitosis","is_correct":false},{"text":"Fertilisation","is_correct":false},{"text":"Diffusion","is_correct":false},{"text":"Respiration","is_correct":false},{"text":"Fertilisation.","is_correct":true}],"conceptId":"biology_genetics_variation_in_sexual_reproduction","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Variation in Sexual Reproduction"}', 1),
  (3194, 834, 'Why can two offspring from the same parents differ genetically?', 'mcq', 1, 'Focus on the core principle of Variation in Sexual Reproduction.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Different sperm and egg cells can combine during fertilisation.","steps":["Step 1: Identify key concept: Define the required principles for Variation in Sexual Reproduction.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Different sperm and egg cells can combine during fertilisation."],"options":[{"text":"They always have different chromosome numbers","is_correct":false},{"text":"Different sperm and egg cells can combine during fertilisation","is_correct":false},{"text":"Their cells contain no DNA","is_correct":false},{"text":"Mitosis changes their chromosome number","is_correct":false},{"text":"Different sperm and egg cells can combine during fertilisation.","is_correct":true}],"conceptId":"biology_genetics_variation_in_sexual_reproduction","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Variation in Sexual Reproduction"}', 2),
  (3195, 835, 'What two cells fuse during fertilisation?', 'mcq', 1, 'Focus on the core principle of Genetic Variation from Fertilisation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A sperm cell and an egg cell.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A sperm cell and an egg cell."],"options":[{"text":"Two body cells","is_correct":false},{"text":"A sperm cell and an egg cell","is_correct":false},{"text":"Two red blood cells","is_correct":false},{"text":"A muscle cell and a nerve cell","is_correct":false},{"text":"A sperm cell and an egg cell.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_from_fertilisation","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Genetic Variation from Fertilisation"}', 0),
  (3196, 835, 'Why can fertilisation produce genetic variation?', 'mcq', 1, 'Focus on the core principle of Genetic Variation from Fertilisation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Different sperm and egg cells can combine to form different genetic combinations.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Different sperm and egg cells can combine to form different genetic combinations."],"options":[{"text":"All sperm are genetically identical","is_correct":false},{"text":"Different sperm and egg cells can combine to form different genetic combinations","is_correct":false},{"text":"Fertilisation removes chromosomes","is_correct":false},{"text":"The zygote has no genetic material","is_correct":false},{"text":"Different sperm and egg cells can combine to form different genetic combinations.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_from_fertilisation","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Genetic Variation from Fertilisation"}', 1),
  (3197, 835, 'What is formed immediately after successful fertilisation?', 'mcq', 1, 'Focus on the core principle of Genetic Variation from Fertilisation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A diploid zygote.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation from Fertilisation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A diploid zygote."],"options":[{"text":"A haploid sperm","is_correct":false},{"text":"A diploid zygote","is_correct":false},{"text":"A gamete","is_correct":false},{"text":"A chromosome","is_correct":false},{"text":"A diploid zygote.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_from_fertilisation","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Genetic Variation from Fertilisation"}', 2),
  (3198, 836, 'How does meiosis contribute to genetic variation?', 'mcq', 1, 'Focus on the core principle of Meiosis and Genetic Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can produce gametes containing different combinations of chromosomes.","steps":["Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can produce gametes containing different combinations of chromosomes."],"options":[{"text":"It produces only identical cells","is_correct":false},{"text":"It can produce gametes containing different combinations of chromosomes","is_correct":false},{"text":"It removes all chromosomes","is_correct":false},{"text":"It produces diploid gametes","is_correct":false},{"text":"It can produce gametes containing different combinations of chromosomes.","is_correct":true}],"conceptId":"biology_genetics_meiosis_and_genetic_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Meiosis and Genetic Variation"}', 0),
  (3199, 836, 'What happens to homologous chromosomes during meiosis I?', 'mcq', 1, 'Focus on the core principle of Meiosis and Genetic Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They separate into different cells.","steps":["Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They separate into different cells."],"options":[{"text":"They become digestive enzymes","is_correct":false},{"text":"They separate into different cells","is_correct":false},{"text":"They disappear","is_correct":false},{"text":"They fuse permanently","is_correct":false},{"text":"They separate into different cells.","is_correct":true}],"conceptId":"biology_genetics_meiosis_and_genetic_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Meiosis and Genetic Variation"}', 1),
  (3200, 836, 'Which statement best summarizes the relationship between meiosis and fertilisation?', 'mcq', 1, 'Focus on the core principle of Meiosis and Genetic Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Meiosis produces genetically varied haploid gametes, while fertilisation combines two gametes.","steps":["Step 1: Identify key concept: Define the required principles for Meiosis and Genetic Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Meiosis produces genetically varied haploid gametes, while fertilisation combines two gametes."],"options":[{"text":"Meiosis produces diploid gametes and fertilisation removes chromosomes","is_correct":false},{"text":"Meiosis produces genetically varied haploid gametes, while fertilisation combines two gametes","is_correct":false},{"text":"Both processes produce identical body cells","is_correct":false},{"text":"Fertilisation occurs before meiosis in every case","is_correct":false},{"text":"Meiosis produces genetically varied haploid gametes, while fertilisation combines two gametes.","is_correct":true}],"conceptId":"biology_genetics_meiosis_and_genetic_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Meiosis and Genetic Variation"}', 2),
  (3201, 837, 'What is genetic variation?', 'mcq', 1, 'Focus on the core principle of Genetic Variation and Environmental Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Differences in genetic information between individuals.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Differences in genetic information between individuals."],"options":[{"text":"Differences caused only by temperature","is_correct":false},{"text":"Differences in genetic information between individuals","is_correct":false},{"text":"Differences caused only by exercise","is_correct":false},{"text":"Differences in body size during one day","is_correct":false},{"text":"Differences in genetic information between individuals.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_and_environmental_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Genetic Variation and Environmental Variation"}', 0),
  (3202, 837, 'Which is mainly genetically determined?', 'mcq', 1, 'Focus on the core principle of Genetic Variation and Environmental Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Blood group.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Blood group."],"options":[{"text":"Blood group","is_correct":false},{"text":"Amount of water a plant receives","is_correct":false},{"text":"Amount of sunlight received yesterday","is_correct":false},{"text":"Soil moisture","is_correct":false},{"text":"Blood group.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_and_environmental_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Genetic Variation and Environmental Variation"}', 1),
  (3203, 837, 'Which statement about human height is most accurate?', 'mcq', 1, 'Focus on the core principle of Genetic Variation and Environmental Variation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can be influenced by both genetic and environmental factors.","steps":["Step 1: Identify key concept: Define the required principles for Genetic Variation and Environmental Variation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can be influenced by both genetic and environmental factors."],"options":[{"text":"It is controlled only by the environment","is_correct":false},{"text":"It is controlled only by one gene","is_correct":false},{"text":"It can be influenced by both genetic and environmental factors","is_correct":false},{"text":"It is unrelated to genes","is_correct":false},{"text":"It can be influenced by both genetic and environmental factors.","is_correct":true}],"conceptId":"biology_genetics_genetic_variation_and_environmental_variation","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Genetic Variation and Environmental Variation"}', 2),
  (3204, 838, 'What is an inherited characteristic?', 'mcq', 1, 'Focus on the core principle of Inherited Variation and Acquired Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A characteristic associated with genetic information passed from parents to offspring.","steps":["Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A characteristic associated with genetic information passed from parents to offspring."],"options":[{"text":"A characteristic caused only by exercise","is_correct":false},{"text":"A characteristic associated with genetic information passed from parents to offspring","is_correct":false},{"text":"A temporary change caused by temperature","is_correct":false},{"text":"A change caused by injury","is_correct":false},{"text":"A characteristic associated with genetic information passed from parents to offspring.","is_correct":true}],"conceptId":"biology_genetics_inherited_variation_and_acquired_differences","skillId":"biology_genetics","subskillId":"biology_genetics_q1","subject":"biology","chapter":"genetics","topic":"Inherited Variation and Acquired Differences"}', 0),
  (3205, 838, 'A person develops larger muscles after regular exercise. How should this be classified?', 'mcq', 1, 'Focus on the core principle of Inherited Variation and Acquired Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: As an acquired change.","steps":["Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: As an acquired change."],"options":[{"text":"As an inherited characteristic","is_correct":false},{"text":"As an acquired change","is_correct":false},{"text":"As a chromosome","is_correct":false},{"text":"As a gamete","is_correct":false},{"text":"As an acquired change.","is_correct":true}],"conceptId":"biology_genetics_inherited_variation_and_acquired_differences","skillId":"biology_genetics","subskillId":"biology_genetics_q2","subject":"biology","chapter":"genetics","topic":"Inherited Variation and Acquired Differences"}', 1),
  (3206, 838, 'Why is increased muscle size from exercise not automatically inherited by a child?', 'mcq', 1, 'Focus on the core principle of Inherited Variation and Acquired Differences.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The acquired increase in muscle size is not itself genetic information passed through gametes.","steps":["Step 1: Identify key concept: Define the required principles for Inherited Variation and Acquired Differences.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The acquired increase in muscle size is not itself genetic information passed through gametes."],"options":[{"text":"Muscles contain no cells","is_correct":false},{"text":"The acquired increase in muscle size is not itself genetic information passed through gametes","is_correct":false},{"text":"Children have no DNA","is_correct":false},{"text":"Exercise removes chromosomes","is_correct":false},{"text":"The acquired increase in muscle size is not itself genetic information passed through gametes.","is_correct":true}],"conceptId":"biology_genetics_inherited_variation_and_acquired_differences","skillId":"biology_genetics","subskillId":"biology_genetics_q3","subject":"biology","chapter":"genetics","topic":"Inherited Variation and Acquired Differences"}', 2),
