  (3334, 881, 'What substance is found in fungal cell walls?', 'mcq', 1, 'Focus on the core principle of Kingdom Fungi.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Fungi.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Chitin.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Fungi.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Chitin."],"options":[{"text":"Chitin","is_correct":false},{"text":"Haemoglobin","is_correct":false},{"text":"Glycogen only","is_correct":false},{"text":"Keratin only","is_correct":false},{"text":"Chitin.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_fungi","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Fungi"}', 1),
  (3335, 881, 'How do many fungi obtain nutrients?', 'mcq', 1, 'Focus on the core principle of Kingdom Fungi.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Fungi.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They secrete digestive enzymes and absorb the resulting soluble substances.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Fungi.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They secrete digestive enzymes and absorb the resulting soluble substances."],"options":[{"text":"They secrete enzymes and absorb soluble products","is_correct":false},{"text":"They swallow food into a stomach","is_correct":false},{"text":"They manufacture all food using chlorophyll","is_correct":false},{"text":"They absorb sunlight as food","is_correct":false},{"text":"They secrete digestive enzymes and absorb the resulting soluble substances.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_fungi","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Fungi"}', 2),
  (3336, 882, 'Which type of organism belongs to Kingdom Plantae?', 'mcq', 1, 'Focus on the core principle of Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A plant.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A plant."],"options":[{"text":"A plant","is_correct":false},{"text":"A mushroom","is_correct":false},{"text":"A bacterium","is_correct":false},{"text":"A human","is_correct":false},{"text":"A plant.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Plantae"}', 0),
  (3337, 882, 'What type of cells do plants have?', 'mcq', 1, 'Focus on the core principle of Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Multicellular eukaryotic cells.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Multicellular eukaryotic cells."],"options":[{"text":"Multicellular eukaryotic cells","is_correct":false},{"text":"Only prokaryotic cells","is_correct":false},{"text":"Cells without nuclei","is_correct":false},{"text":"Cells without cell walls","is_correct":false},{"text":"Multicellular eukaryotic cells.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Plantae"}', 1),
  (3338, 882, 'Why are most green plants considered autotrophic?', 'mcq', 1, 'Focus on the core principle of Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They can manufacture organic food by photosynthesis.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They can manufacture organic food by photosynthesis."],"options":[{"text":"They manufacture organic food by photosynthesis","is_correct":false},{"text":"They obtain all food by eating animals","is_correct":false},{"text":"They absorb ready-made food through roots only","is_correct":false},{"text":"They cannot produce organic substances","is_correct":false},{"text":"They can manufacture organic food by photosynthesis.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Plantae"}', 2),
  (3339, 883, 'Which type of cells do animals have?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Multicellular eukaryotic cells.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Multicellular eukaryotic cells."],"options":[{"text":"Multicellular eukaryotic cells","is_correct":false},{"text":"Only prokaryotic cells","is_correct":false},{"text":"Cells without nuclei","is_correct":false},{"text":"Cells without membranes","is_correct":false},{"text":"Multicellular eukaryotic cells.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia"}', 0),
  (3340, 883, 'How do animals obtain organic nutrients?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They obtain them heterotrophically by consuming organisms or organic material.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They obtain them heterotrophically by consuming organisms or organic material."],"options":[{"text":"By heterotrophic nutrition","is_correct":false},{"text":"By photosynthesis in all cases","is_correct":false},{"text":"By absorbing sunlight","is_correct":false},{"text":"By producing glucose without carbon sources","is_correct":false},{"text":"They obtain them heterotrophically by consuming organisms or organic material.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia"}', 1),
  (3341, 883, 'Which structure is absent from typical animal cells?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A cellulose cell wall.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A cellulose cell wall."],"options":[{"text":"A cellulose cell wall","is_correct":false},{"text":"A cell membrane","is_correct":false},{"text":"A nucleus","is_correct":false},{"text":"Mitochondria","is_correct":false},{"text":"A cellulose cell wall.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia"}', 2),
  (3342, 884, 'Which feature is shared by typical plants and animals?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They are multicellular eukaryotic organisms.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They are multicellular eukaryotic organisms."],"options":[{"text":"They are multicellular eukaryotic organisms","is_correct":false},{"text":"They both have cellulose cell walls","is_correct":false},{"text":"They both have chloroplasts","is_correct":false},{"text":"They both obtain food only by photosynthesis","is_correct":false},{"text":"They are multicellular eukaryotic organisms.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia Compared with Kingdom Plantae"}', 0),
  (3343, 884, 'Which feature distinguishes typical plant cells from animal cells?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Plant cells have cellulose cell walls and may contain chloroplasts.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Plant cells have cellulose cell walls and may contain chloroplasts."],"options":[{"text":"Plant cells have cellulose cell walls and may contain chloroplasts","is_correct":false},{"text":"Plant cells have no nuclei","is_correct":false},{"text":"Animal cells contain chloroplasts","is_correct":false},{"text":"Animal cells have cellulose walls","is_correct":false},{"text":"Plant cells have cellulose cell walls and may contain chloroplasts.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia Compared with Kingdom Plantae"}', 1),
  (3344, 884, 'What is the main nutritional difference?', 'mcq', 1, 'Focus on the core principle of Kingdom Animalia Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Most green plants can manufacture organic food by photosynthesis, while animals obtain organic nutrients heterotrophically.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Animalia Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Most green plants can manufacture organic food by photosynthesis, while animals obtain organic nutrients heterotrophically."],"options":[{"text":"Plants can make organic food by photosynthesis while animals obtain food heterotrophically","is_correct":false},{"text":"Animals photosynthesise while plants eat animals","is_correct":false},{"text":"Both groups obtain food in exactly the same way","is_correct":false},{"text":"Neither group requires organic nutrients","is_correct":false},{"text":"Most green plants can manufacture organic food by photosynthesis, while animals obtain organic nutrients heterotrophically.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_animalia_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Animalia Compared with Kingdom Plantae"}', 2),
  (3345, 885, 'What is the main difference between typical fungal and plant cell walls?', 'mcq', 1, 'Focus on the core principle of Kingdom Fungi Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Fungal cell walls contain chitin, while plant cell walls contain cellulose.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Fungal cell walls contain chitin, while plant cell walls contain cellulose."],"options":[{"text":"Fungal walls contain chitin while plant walls contain cellulose","is_correct":false},{"text":"Both contain only cellulose","is_correct":false},{"text":"Plants have chitin while fungi have cellulose","is_correct":false},{"text":"Neither group has cell walls","is_correct":false},{"text":"Fungal cell walls contain chitin, while plant cell walls contain cellulose.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_fungi_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Fungi Compared with Kingdom Plantae"}', 0),
  (3346, 885, 'Why are fungi not classified as plants?', 'mcq', 1, 'Focus on the core principle of Kingdom Fungi Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They differ from plants in important characteristics including nutrition and cell-wall composition.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They differ from plants in important characteristics including nutrition and cell-wall composition."],"options":[{"text":"They differ in important characteristics such as nutrition and cell-wall composition","is_correct":false},{"text":"They are not living organisms","is_correct":false},{"text":"They contain no cells","is_correct":false},{"text":"They are all animals","is_correct":false},{"text":"They differ from plants in important characteristics including nutrition and cell-wall composition.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_fungi_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Fungi Compared with Kingdom Plantae"}', 1),
  (3347, 885, 'Which statement correctly compares fungal and plant nutrition?', 'mcq', 1, 'Focus on the core principle of Kingdom Fungi Compared with Kingdom Plantae.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Plants can photosynthesise, while fungi obtain organic nutrients heterotrophically.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom Fungi Compared with Kingdom Plantae.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Plants can photosynthesise, while fungi obtain organic nutrients heterotrophically."],"options":[{"text":"Plants can photosynthesise while fungi obtain nutrients heterotrophically","is_correct":false},{"text":"Both groups always photosynthesise","is_correct":false},{"text":"Fungi always eat food using mouths","is_correct":false},{"text":"Plants cannot make organic food","is_correct":false},{"text":"Plants can photosynthesise, while fungi obtain organic nutrients heterotrophically.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_fungi_compared_with_kingdom_plantae","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom Fungi Compared with Kingdom Plantae"}', 2),
  (3348, 886, 'Which kingdom traditionally contains prokaryotic organisms?', 'mcq', 1, 'Focus on the core principle of Comparing the Major Five Kingdoms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Monera.","steps":["Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Monera."],"options":[{"text":"Monera","is_correct":false},{"text":"Animalia","is_correct":false},{"text":"Plantae","is_correct":false},{"text":"Fungi","is_correct":false},{"text":"Monera.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_comparing_the_major_five_kingdoms","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing the Major Five Kingdoms"}', 0),
  (3349, 886, 'An organism is multicellular, eukaryotic and obtains organic nutrients by consuming other organisms. Which kingdom is most likely?', 'mcq', 1, 'Focus on the core principle of Comparing the Major Five Kingdoms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Animalia.","steps":["Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Animalia."],"options":[{"text":"Animalia","is_correct":false},{"text":"Monera","is_correct":false},{"text":"Plantae","is_correct":false},{"text":"Fungi","is_correct":false},{"text":"Animalia.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_comparing_the_major_five_kingdoms","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing the Major Five Kingdoms"}', 1),
  (3350, 886, 'An organism is eukaryotic, has a chitinous cell wall and obtains nutrients by absorption after external digestion. Which kingdom is most likely?', 'mcq', 1, 'Focus on the core principle of Comparing the Major Five Kingdoms.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Fungi.","steps":["Step 1: Identify key concept: Define the required principles for Comparing the Major Five Kingdoms.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Fungi."],"options":[{"text":"Fungi","is_correct":false},{"text":"Animalia","is_correct":false},{"text":"Plantae","is_correct":false},{"text":"Monera","is_correct":false},{"text":"Fungi.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_comparing_the_major_five_kingdoms","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing the Major Five Kingdoms"}', 2),
  (3351, 887, 'What is a species?', 'mcq', 1, 'Focus on the core principle of What Is a Species?.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Species?.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A group of organisms that can interbreed naturally and produce fertile offspring.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Species?.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A group of organisms that can interbreed naturally and produce fertile offspring."],"options":[{"text":"A group that can interbreed naturally and produce fertile offspring","is_correct":false},{"text":"A group of organisms that always look identical","is_correct":false},{"text":"All organisms living in one habitat","is_correct":false},{"text":"All organisms with the same body size","is_correct":false},{"text":"A group of organisms that can interbreed naturally and produce fertile offspring.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_what_is_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Species?"}', 0),
  (3352, 887, 'Why are horses and donkeys classified as different species?', 'mcq', 1, 'Focus on the core principle of What Is a Species?.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Species?.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Although they can produce a hybrid, the resulting mule is generally sterile.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Species?.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Although they can produce a hybrid, the resulting mule is generally sterile."],"options":[{"text":"Their hybrid offspring is generally sterile","is_correct":false},{"text":"They have different habitats only","is_correct":false},{"text":"They have completely different cell types","is_correct":false},{"text":"They cannot produce any offspring at all","is_correct":false},{"text":"Although they can produce a hybrid, the resulting mule is generally sterile.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_what_is_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Species?"}', 1),
  (3353, 887, 'Why is physical appearance alone insufficient for defining a species?', 'mcq', 1, 'Focus on the core principle of What Is a Species?.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Species?.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Members of the same species can show substantial variation in appearance.","steps":["Step 1: Identify key concept: Define the required principles for What Is a Species?.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Members of the same species can show substantial variation in appearance."],"options":[{"text":"Members of the same species can vary in appearance","is_correct":false},{"text":"All organisms of one species must look identical","is_correct":false},{"text":"Appearance has no biological basis","is_correct":false},{"text":"Species cannot reproduce","is_correct":false},{"text":"Members of the same species can show substantial variation in appearance.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_what_is_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Species?"}', 2),
  (3354, 888, 'What is the most specific major rank in the traditional taxonomic hierarchy?', 'mcq', 1, 'Focus on the core principle of Why Species Are the Basic Classification Unit.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Species.","steps":["Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Species."],"options":[{"text":"Species","is_correct":false},{"text":"Kingdom","is_correct":false},{"text":"Phylum","is_correct":false},{"text":"Class","is_correct":false},{"text":"Species.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_why_species_are_the_basic_classification_unit","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Why Species Are the Basic Classification Unit"}', 0),
  (3355, 888, 'What happens when related species are grouped together?', 'mcq', 1, 'Focus on the core principle of Why Species Are the Basic Classification Unit.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: They form a genus.","steps":["Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: They form a genus."],"options":[{"text":"They form a genus","is_correct":false},{"text":"They form a kingdom immediately","is_correct":false},{"text":"They become one organism","is_correct":false},{"text":"They stop reproducing","is_correct":false},{"text":"They form a genus.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_why_species_are_the_basic_classification_unit","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Why Species Are the Basic Classification Unit"}', 1),
  (3356, 888, 'Why is species useful as a classification unit?', 'mcq', 1, 'Focus on the core principle of Why Species Are the Basic Classification Unit.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It identifies a relatively precise group of closely related organisms capable of natural reproduction with fertile offspring.","steps":["Step 1: Identify key concept: Define the required principles for Why Species Are the Basic Classification Unit.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It identifies a relatively precise group of closely related organisms capable of natural reproduction with fertile offspring."],"options":[{"text":"It identifies a relatively precise biological group","is_correct":false},{"text":"It contains every organism in an ecosystem","is_correct":false},{"text":"It is based only on colour","is_correct":false},{"text":"It contains organisms from unrelated kingdoms","is_correct":false},{"text":"It identifies a relatively precise group of closely related organisms capable of natural reproduction with fertile offspring.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_why_species_are_the_basic_classification_unit","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Why Species Are the Basic Classification Unit"}', 2),
  (3357, 889, 'Which sequence is correctly ordered from broadest to most specific?', 'mcq', 1, 'Focus on the core principle of Taxonomic Hierarchy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Kingdom → Phylum → Class → Order → Family → Genus → Species.","steps":["Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Kingdom → Phylum → Class → Order → Family → Genus → Species."],"options":[{"text":"Kingdom → Phylum → Class → Order → Family → Genus → Species","is_correct":false},{"text":"Species → Genus → Family → Kingdom → Class → Order → Phylum","is_correct":false},{"text":"Kingdom → Species → Genus → Family → Class → Order → Phylum","is_correct":false},{"text":"Phylum → Kingdom → Class → Species → Family → Genus → Order","is_correct":false},{"text":"Kingdom → Phylum → Class → Order → Family → Genus → Species.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_taxonomic_hierarchy","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Taxonomic Hierarchy"}', 0),
  (3358, 889, 'What happens to the number of organisms included as you move from kingdom toward species?', 'mcq', 1, 'Focus on the core principle of Taxonomic Hierarchy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The group becomes smaller and more specific.","steps":["Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The group becomes smaller and more specific."],"options":[{"text":"The group becomes smaller and more specific","is_correct":false},{"text":"The group becomes larger and less specific","is_correct":false},{"text":"The group always doubles","is_correct":false},{"text":"Nothing changes","is_correct":false},{"text":"The group becomes smaller and more specific.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_taxonomic_hierarchy","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Taxonomic Hierarchy"}', 1),
  (3359, 889, 'Which rank comes immediately below family?', 'mcq', 1, 'Focus on the core principle of Taxonomic Hierarchy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Genus.","steps":["Step 1: Identify key concept: Define the required principles for Taxonomic Hierarchy.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Genus."],"options":[{"text":"Genus","is_correct":false},{"text":"Species","is_correct":false},{"text":"Order","is_correct":false},{"text":"Class","is_correct":false},{"text":"Genus.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_taxonomic_hierarchy","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Taxonomic Hierarchy"}', 2),
  (3360, 890, 'What is the relationship between kingdom and phylum?', 'mcq', 1, 'Focus on the core principle of Kingdom to Phylum.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A kingdom contains several phyla.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A kingdom contains several phyla."],"options":[{"text":"A kingdom contains several phyla","is_correct":false},{"text":"A phylum contains every kingdom","is_correct":false},{"text":"A kingdom is more specific than a phylum","is_correct":false},{"text":"They are exactly the same rank","is_correct":false},{"text":"A kingdom contains several phyla.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_to_phylum","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom to Phylum"}', 0),
  (3361, 890, 'Which phylum contains humans?', 'mcq', 1, 'Focus on the core principle of Kingdom to Phylum.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Chordata.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Chordata."],"options":[{"text":"Chordata","is_correct":false},{"text":"Arthropoda","is_correct":false},{"text":"Mollusca","is_correct":false},{"text":"Annelida","is_correct":false},{"text":"Chordata.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_to_phylum","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom to Phylum"}', 1),
  (3362, 890, 'Why are kingdoms divided into phyla?', 'mcq', 1, 'Focus on the core principle of Kingdom to Phylum.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To organise the broad kingdom into smaller groups based on important shared characteristics.","steps":["Step 1: Identify key concept: Define the required principles for Kingdom to Phylum.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To organise the broad kingdom into smaller groups based on important shared characteristics."],"options":[{"text":"To organise the kingdom into smaller groups","is_correct":false},{"text":"To make all organisms identical","is_correct":false},{"text":"To eliminate species","is_correct":false},{"text":"To change organisms into different kingdoms","is_correct":false},{"text":"To organise the broad kingdom into smaller groups based on important shared characteristics.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_kingdom_to_phylum","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Kingdom to Phylum"}', 2),
  (3363, 891, 'Which rank comes below phylum?', 'mcq', 1, 'Focus on the core principle of Phylum to Class.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Phylum to Class.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Class.","steps":["Step 1: Identify key concept: Define the required principles for Phylum to Class.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Class."],"options":[{"text":"Class","is_correct":false},{"text":"Kingdom","is_correct":false},{"text":"Family","is_correct":false},{"text":"Genus","is_correct":false},{"text":"Class.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_phylum_to_class","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Phylum to Class"}', 0),
  (3364, 891, 'What class does a human belong to?', 'mcq', 1, 'Focus on the core principle of Phylum to Class.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Phylum to Class.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Mammalia.","steps":["Step 1: Identify key concept: Define the required principles for Phylum to Class.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Mammalia."],"options":[{"text":"Mammalia","is_correct":false},{"text":"Aves","is_correct":false},{"text":"Reptilia","is_correct":false},{"text":"Amphibia","is_correct":false},{"text":"Mammalia.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_phylum_to_class","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Phylum to Class"}', 1),
  (3365, 891, 'Why is a class more specific than a phylum?', 'mcq', 1, 'Focus on the core principle of Phylum to Class.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Phylum to Class.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A class contains a smaller group of organisms with more specific shared characteristics.","steps":["Step 1: Identify key concept: Define the required principles for Phylum to Class.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A class contains a smaller group of organisms with more specific shared characteristics."],"options":[{"text":"It contains a smaller group with more specific shared characteristics","is_correct":false},{"text":"It contains every organism in the kingdom","is_correct":false},{"text":"It is broader than kingdom","is_correct":false},{"text":"It contains no organisms","is_correct":false},{"text":"A class contains a smaller group of organisms with more specific shared characteristics.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_phylum_to_class","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Phylum to Class"}', 2),
  (3366, 892, 'Which rank comes immediately below class?', 'mcq', 1, 'Focus on the core principle of Class to Order.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Class to Order.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Order.","steps":["Step 1: Identify key concept: Define the required principles for Class to Order.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Order."],"options":[{"text":"Order","is_correct":false},{"text":"Family","is_correct":false},{"text":"Genus","is_correct":false},{"text":"Kingdom","is_correct":false},{"text":"Order.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_class_to_order","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Class to Order"}', 0),
  (3367, 892, 'What order does a human belong to?', 'mcq', 1, 'Focus on the core principle of Class to Order.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Class to Order.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Primates.","steps":["Step 1: Identify key concept: Define the required principles for Class to Order.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Primates."],"options":[{"text":"Primates","is_correct":false},{"text":"Carnivora","is_correct":false},{"text":"Rodentia","is_correct":false},{"text":"Artiodactyla","is_correct":false},{"text":"Primates.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_class_to_order","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Class to Order"}', 1),
  (3368, 892, 'What happens when classification moves from class to order?', 'mcq', 1, 'Focus on the core principle of Class to Order.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Class to Order.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The group becomes smaller and more specific.","steps":["Step 1: Identify key concept: Define the required principles for Class to Order.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The group becomes smaller and more specific."],"options":[{"text":"The group becomes smaller and more specific","is_correct":false},{"text":"The group becomes broader","is_correct":false},{"text":"The group becomes a kingdom","is_correct":false},{"text":"The group loses all shared characteristics","is_correct":false},{"text":"The group becomes smaller and more specific.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_class_to_order","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Class to Order"}', 2),
  (3369, 893, 'Which rank comes immediately below order?', 'mcq', 1, 'Focus on the core principle of Order to Family.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Order to Family.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Family.","steps":["Step 1: Identify key concept: Define the required principles for Order to Family.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Family."],"options":[{"text":"Family","is_correct":false},{"text":"Genus","is_correct":false},{"text":"Class","is_correct":false},{"text":"Kingdom","is_correct":false},{"text":"Family.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_order_to_family","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Order to Family"}', 0),
  (3370, 893, 'What family does a human belong to?', 'mcq', 1, 'Focus on the core principle of Order to Family.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Order to Family.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Hominidae.","steps":["Step 1: Identify key concept: Define the required principles for Order to Family.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Hominidae."],"options":[{"text":"Hominidae","is_correct":false},{"text":"Felidae","is_correct":false},{"text":"Canidae","is_correct":false},{"text":"Bovidae","is_correct":false},{"text":"Hominidae.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_order_to_family","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Order to Family"}', 1),
  (3371, 893, 'What does a family contain?', 'mcq', 1, 'Focus on the core principle of Order to Family.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Order to Family.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: One or more related genera.","steps":["Step 1: Identify key concept: Define the required principles for Order to Family.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: One or more related genera."],"options":[{"text":"One or more related genera","is_correct":false},{"text":"All kingdoms","is_correct":false},{"text":"Only one cell","is_correct":false},{"text":"Every species on Earth","is_correct":false},{"text":"One or more related genera.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_order_to_family","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Order to Family"}', 2),
  (3372, 894, 'Which rank comes immediately below family?', 'mcq', 1, 'Focus on the core principle of Family to Genus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Family to Genus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Genus.","steps":["Step 1: Identify key concept: Define the required principles for Family to Genus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Genus."],"options":[{"text":"Genus","is_correct":false},{"text":"Species","is_correct":false},{"text":"Order","is_correct":false},{"text":"Class","is_correct":false},{"text":"Genus.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_family_to_genus","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Family to Genus"}', 0),
  (3373, 894, 'What genus does the human species belong to?', 'mcq', 1, 'Focus on the core principle of Family to Genus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Family to Genus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Homo.","steps":["Step 1: Identify key concept: Define the required principles for Family to Genus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Homo."],"options":[{"text":"Homo","is_correct":false},{"text":"Hominidae","is_correct":false},{"text":"Mammalia","is_correct":false},{"text":"Primates","is_correct":false},{"text":"Homo.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_family_to_genus","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Family to Genus"}', 1),
  (3374, 894, 'What is the relationship between genus and species?', 'mcq', 1, 'Focus on the core principle of Family to Genus.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Family to Genus.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A genus contains one or more closely related species.","steps":["Step 1: Identify key concept: Define the required principles for Family to Genus.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A genus contains one or more closely related species."],"options":[{"text":"A genus contains one or more closely related species","is_correct":false},{"text":"A species contains several kingdoms","is_correct":false},{"text":"A genus is broader than kingdom","is_correct":false},{"text":"Genus and species are exactly the same rank","is_correct":false},{"text":"A genus contains one or more closely related species.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_family_to_genus","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Family to Genus"}', 2),
  (3375, 895, 'How many parts does a binomial scientific name have?', 'mcq', 1, 'Focus on the core principle of Binomial Nomenclature.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Two.","steps":["Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Two."],"options":[{"text":"Two","is_correct":false},{"text":"One","is_correct":false},{"text":"Three","is_correct":false},{"text":"Four","is_correct":false},{"text":"Two.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_binomial_nomenclature","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Binomial Nomenclature"}', 0),
  (3376, 895, 'What is the first part of a binomial name?', 'mcq', 1, 'Focus on the core principle of Binomial Nomenclature.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The genus.","steps":["Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The genus."],"options":[{"text":"The genus","is_correct":false},{"text":"The kingdom","is_correct":false},{"text":"The family","is_correct":false},{"text":"The habitat","is_correct":false},{"text":"The genus.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_binomial_nomenclature","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Binomial Nomenclature"}', 1),
  (3377, 895, 'Which is correctly written?', 'mcq', 1, 'Focus on the core principle of Binomial Nomenclature.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Homo sapiens.","steps":["Step 1: Identify key concept: Define the required principles for Binomial Nomenclature.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Homo sapiens."],"options":[{"text":"Homo sapiens","is_correct":false},{"text":"homo Sapiens","is_correct":false},{"text":"HOMO SAPIENS","is_correct":false},{"text":"Homo Sapiens","is_correct":false},{"text":"Homo sapiens.","is_correct":true}],"conceptId":"biology_biodiversity_and_classification_binomial_nomenclature","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Binomial Nomenclature"}', 2),
  (3378, 896, 'What does species diversity refer to?', 'mcq', 1, 'Focus on the core principle of Species Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Species Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The variety of different species in an area","steps":["Step 1: Identify key concept: Define the required principles for Species Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The variety of different species in an area"],"options":[{"text":"The variety of different species in an area","is_correct":true},{"text":"The number of individuals in one species only","is_correct":false},{"text":"The amount of rainfall in an area","is_correct":false},{"text":"The number of genes in one organism","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_species_diversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Diversity"}', 0),
  (3379, 896, 'Which area has greater species diversity?', 'mcq', 1, 'Focus on the core principle of Species Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Species Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An area containing a wider variety of species","steps":["Step 1: Identify key concept: Define the required principles for Species Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An area containing a wider variety of species"],"options":[{"text":"An area containing a wider variety of species","is_correct":true},{"text":"An area containing only one species","is_correct":false},{"text":"An area with the largest individual organism","is_correct":false},{"text":"An area with the highest temperature","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_species_diversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Diversity"}', 1),
  (3380, 896, 'Does having many individuals of one species automatically mean high species diversity?', 'mcq', 1, 'Focus on the core principle of Species Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Species Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: No","steps":["Step 1: Identify key concept: Define the required principles for Species Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: No"],"options":[{"text":"Yes","is_correct":false},{"text":"No","is_correct":true},{"text":"Only in plants","is_correct":false},{"text":"Only in animals","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_species_diversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Diversity"}', 2),
  (3381, 897, 'Competition between individuals of the same species is called:', 'mcq', 1, 'Focus on the core principle of Competition Within a Species.', '{"why":"Intraspecific means within the same species.","sol":"Step 1: Identify key concept: Define the required principles for Competition Within a Species.\nStep 2: Apply governing rule: Intraspecific means within the same species.\nStep 3: State the final conclusion: Intraspecific competition","steps":["Step 1: Identify key concept: Define the required principles for Competition Within a Species.","Step 2: Apply governing rule: Intraspecific means within the same species.","Step 3: State the final conclusion: Intraspecific competition"],"options":[{"text":"Intraspecific competition","is_correct":true},{"text":"Interspecific competition","is_correct":false},{"text":"Predation","is_correct":false},{"text":"Parasitism","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_competition_within_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Within a Species"}', 0),
  (3382, 897, 'Name two resources organisms may compete for.', 'text', 1, 'Focus on the core principle of Competition Within a Species.', '{"why":"Competition occurs when organisms require the same limited resource.","sol":"Step 1: Identify key concept: Define the required principles for Competition Within a Species.\nStep 2: Apply governing rule: Competition occurs when organisms require the same limited resource.\nStep 3: State the final conclusion: Examples: food, water, space, shelter or mates.","steps":["Step 1: Identify key concept: Define the required principles for Competition Within a Species.","Step 2: Apply governing rule: Competition occurs when organisms require the same limited resource.","Step 3: State the final conclusion: Examples: food, water, space, shelter or mates."],"options":[],"conceptId":"biology_biodiversity_and_classification_competition_within_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Within a Species"}', 1),
  (3383, 897, 'When is competition likely to become stronger?', 'mcq', 1, 'Focus on the core principle of Competition Within a Species.', '{"why":"Limited resources increase competition between individuals requiring them.","sol":"Step 1: Identify key concept: Define the required principles for Competition Within a Species.\nStep 2: Apply governing rule: Limited resources increase competition between individuals requiring them.\nStep 3: State the final conclusion: When resources become limited","steps":["Step 1: Identify key concept: Define the required principles for Competition Within a Species.","Step 2: Apply governing rule: Limited resources increase competition between individuals requiring them.","Step 3: State the final conclusion: When resources become limited"],"options":[{"text":"When resources become limited","is_correct":true},{"text":"When resources are unlimited","is_correct":false},{"text":"When there is only one organism","is_correct":false},{"text":"When no organisms require resources","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_competition_within_a_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Within a Species"}', 2),
  (3384, 898, 'Competition between two different species is called:', 'mcq', 1, 'Focus on the core principle of Competition Between Species.', '{"why":"Interspecific means between different species.","sol":"Step 1: Identify key concept: Define the required principles for Competition Between Species.\nStep 2: Apply governing rule: Interspecific means between different species.\nStep 3: State the final conclusion: Interspecific competition","steps":["Step 1: Identify key concept: Define the required principles for Competition Between Species.","Step 2: Apply governing rule: Interspecific means between different species.","Step 3: State the final conclusion: Interspecific competition"],"options":[{"text":"Intraspecific competition","is_correct":false},{"text":"Interspecific competition","is_correct":true},{"text":"Predation","is_correct":false},{"text":"Decomposition","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_competition_between_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Between Species"}', 0),
  (3385, 898, 'Two bird species use the same limited nesting sites. What type of interaction is occurring?', 'text', 1, 'Focus on the core principle of Competition Between Species.', '{"why":"The birds are different species competing for a limited resource.","sol":"Step 1: Identify key concept: Define the required principles for Competition Between Species.\nStep 2: Apply governing rule: The birds are different species competing for a limited resource.\nStep 3: State the final conclusion: Interspecific competition","steps":["Step 1: Identify key concept: Define the required principles for Competition Between Species.","Step 2: Apply governing rule: The birds are different species competing for a limited resource.","Step 3: State the final conclusion: Interspecific competition"],"options":[],"conceptId":"biology_biodiversity_and_classification_competition_between_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Between Species"}', 1),
  (3386, 898, 'What condition makes competition between species stronger?', 'mcq', 1, 'Focus on the core principle of Competition Between Species.', '{"why":"Competition becomes stronger when organisms need the same scarce resource.","sol":"Step 1: Identify key concept: Define the required principles for Competition Between Species.\nStep 2: Apply governing rule: Competition becomes stronger when organisms need the same scarce resource.\nStep 3: State the final conclusion: A shared resource becomes limited","steps":["Step 1: Identify key concept: Define the required principles for Competition Between Species.","Step 2: Apply governing rule: Competition becomes stronger when organisms need the same scarce resource.","Step 3: State the final conclusion: A shared resource becomes limited"],"options":[{"text":"A shared resource becomes limited","is_correct":true},{"text":"The resource becomes unlimited","is_correct":false},{"text":"The species stop using resources","is_correct":false},{"text":"There are no organisms present","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_competition_between_species","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Competition Between Species"}', 2),
  (3387, 899, 'What is species richness?', 'text', 1, 'Focus on the core principle of Species Richness.', '{"why":"Species richness counts distinct species present.","sol":"Step 1: Identify key concept: Define the required principles for Species Richness.\nStep 2: Apply governing rule: Species richness counts distinct species present.\nStep 3: State the final conclusion: the number of different species in an area","steps":["Step 1: Identify key concept: Define the required principles for Species Richness.","Step 2: Apply governing rule: Species richness counts distinct species present.","Step 3: State the final conclusion: the number of different species in an area"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_richness","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Richness"}', 0),
  (3388, 899, 'An area contains 7 different species. What is its species richness?', 'text', 1, 'Focus on the core principle of Species Richness.', '{"why":"Species richness is the number of different species present.","sol":"Step 1: Identify key concept: Define the required principles for Species Richness.\nStep 2: Apply governing rule: Species richness is the number of different species present.\nStep 3: State the final conclusion: 7","steps":["Step 1: Identify key concept: Define the required principles for Species Richness.","Step 2: Apply governing rule: Species richness is the number of different species present.","Step 3: State the final conclusion: 7"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_richness","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Richness"}', 1),
  (3389, 899, 'Does species richness tell you how many individuals belong to each species?', 'text', 1, 'Focus on the core principle of Species Richness.', '{"why":"Richness counts species, not the abundance of individuals within each species.","sol":"Step 1: Identify key concept: Define the required principles for Species Richness.\nStep 2: Apply governing rule: Richness counts species, not the abundance of individuals within each species.\nStep 3: State the final conclusion: no","steps":["Step 1: Identify key concept: Define the required principles for Species Richness.","Step 2: Apply governing rule: Richness counts species, not the abundance of individuals within each species.","Step 3: State the final conclusion: no"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_richness","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Richness"}', 2),
  (3390, 900, 'What are three common population distribution patterns?', 'text', 1, 'Focus on the core principle of Species Distribution Patterns.', '{"why":"These describe the main ways individuals can be spatially arranged.","sol":"Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.\nStep 2: Apply governing rule: These describe the main ways individuals can be spatially arranged.\nStep 3: State the final conclusion: clumped, uniform and random","steps":["Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.","Step 2: Apply governing rule: These describe the main ways individuals can be spatially arranged.","Step 3: State the final conclusion: clumped, uniform and random"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_distribution_patterns","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Distribution Patterns"}', 0),
  (3391, 900, 'Which pattern occurs when individuals occur in groups or patches?', 'text', 1, 'Focus on the core principle of Species Distribution Patterns.', '{"why":"Clumped distribution means individuals occur in groups or patches.","sol":"Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.\nStep 2: Apply governing rule: Clumped distribution means individuals occur in groups or patches.\nStep 3: State the final conclusion: clumped","steps":["Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.","Step 2: Apply governing rule: Clumped distribution means individuals occur in groups or patches.","Step 3: State the final conclusion: clumped"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_distribution_patterns","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Distribution Patterns"}', 1),
  (3392, 900, 'Which pattern involves relatively even spacing between individuals?', 'text', 1, 'Focus on the core principle of Species Distribution Patterns.', '{"why":"Uniform distribution has relatively regular spacing.","sol":"Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.\nStep 2: Apply governing rule: Uniform distribution has relatively regular spacing.\nStep 3: State the final conclusion: uniform","steps":["Step 1: Identify key concept: Define the required principles for Species Distribution Patterns.","Step 2: Apply governing rule: Uniform distribution has relatively regular spacing.","Step 3: State the final conclusion: uniform"],"options":[],"conceptId":"biology_biodiversity_and_classification_species_distribution_patterns","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Species Distribution Patterns"}', 2),
  (3393, 901, 'What is the main purpose of a taxonomic key?', 'mcq', 1, 'Focus on the core principle of What Is a Taxonomic Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To identify an organism using its observable characteristics","steps":["Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To identify an organism using its observable characteristics"],"options":[{"text":"To identify an organism using its observable characteristics","is_correct":true},{"text":"To measure the age of an organism","is_correct":false},{"text":"To determine how much food an organism needs","is_correct":false},{"text":"To measure the temperature of an organism","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_what_is_a_taxonomic_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Taxonomic Key"}', 0),
  (3394, 901, 'Why can a taxonomic key identify an organism whose name is unknown?', 'mcq', 1, 'Focus on the core principle of What Is a Taxonomic Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It uses observable characteristics to progressively narrow the possible identities","steps":["Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It uses observable characteristics to progressively narrow the possible identities"],"options":[{"text":"It uses observable characteristics to progressively narrow the possible identities","is_correct":true},{"text":"It already contains the organism''s name in every question","is_correct":false},{"text":"It identifies organisms from their size alone","is_correct":false},{"text":"It identifies organisms from where they were found","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_what_is_a_taxonomic_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Taxonomic Key"}', 1),
  (3395, 901, 'What type of information is mainly used when following a taxonomic key?', 'mcq', 1, 'Focus on the core principle of What Is a Taxonomic Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Observable characteristics","steps":["Step 1: Identify key concept: Define the required principles for What Is a Taxonomic Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Observable characteristics"],"options":[{"text":"Observable characteristics","is_correct":true},{"text":"The organism''s age","is_correct":false},{"text":"The organism''s weight only","is_correct":false},{"text":"The time of day","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_what_is_a_taxonomic_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"What Is a Taxonomic Key"}', 2),
  (3396, 902, 'What does dichotomous mean in a dichotomous key?', 'mcq', 1, 'Focus on the core principle of How a Dichotomous Key Works.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Divided into two choices","steps":["Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Divided into two choices"],"options":[{"text":"Divided into two choices","is_correct":true},{"text":"Divided into five choices","is_correct":false},{"text":"Arranged according to size","is_correct":false},{"text":"Arranged according to age","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_how_a_dichotomous_key_works","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"How a Dichotomous Key Works"}', 0),
  (3397, 902, 'How many choices are normally provided at each stage of a dichotomous key?', 'mcq', 1, 'Focus on the core principle of How a Dichotomous Key Works.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Two","steps":["Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Two"],"options":[{"text":"One","is_correct":false},{"text":"Two","is_correct":true},{"text":"Three","is_correct":false},{"text":"Four","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_how_a_dichotomous_key_works","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"How a Dichotomous Key Works"}', 1),
  (3398, 902, 'Why are the two choices normally contrasting?', 'mcq', 1, 'Focus on the core principle of How a Dichotomous Key Works.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: So that the organism can be placed into one of two groups at each step","steps":["Step 1: Identify key concept: Define the required principles for How a Dichotomous Key Works.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: So that the organism can be placed into one of two groups at each step"],"options":[{"text":"So that the organism can be placed into one of two groups at each step","is_correct":true},{"text":"So that both choices describe exactly the same characteristic","is_correct":false},{"text":"So that identification depends on the organism''s age","is_correct":false},{"text":"So that the key can measure the organism","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_how_a_dichotomous_key_works","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"How a Dichotomous Key Works"}', 2),
  (3399, 903, 'What do the two statements in a dichotomous key normally represent?', 'mcq', 1, 'Focus on the core principle of Paired Statements in a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Two contrasting characteristics","steps":["Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Two contrasting characteristics"],"options":[{"text":"Two contrasting characteristics","is_correct":true},{"text":"Two unrelated measurements","is_correct":false},{"text":"Two different organisms","is_correct":false},{"text":"Two stages of reproduction","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_paired_statements_in_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Paired Statements in a Dichotomous Key"}', 0),
  (3400, 903, 'If an organism has six legs and the key says ''6 legs'' at 1a and ''not 6 legs'' at 1b, which choice should be selected?', 'mcq', 1, 'Focus on the core principle of Paired Statements in a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 1a","steps":["Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 1a"],"options":[{"text":"1a","is_correct":true},{"text":"1b","is_correct":false},{"text":"Both","is_correct":false},{"text":"Neither","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_paired_statements_in_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Paired Statements in a Dichotomous Key"}', 1),
  (3401, 903, 'Why should you observe the organism instead of guessing when using a key?', 'mcq', 1, 'Focus on the core principle of Paired Statements in a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Because each choice must match the organism''s actual characteristics","steps":["Step 1: Identify key concept: Define the required principles for Paired Statements in a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Because each choice must match the organism''s actual characteristics"],"options":[{"text":"Because each choice must match the organism''s actual characteristics","is_correct":true},{"text":"Because guessing makes the organism larger","is_correct":false},{"text":"Because the key works only for large organisms","is_correct":false},{"text":"Because observation changes the organism''s classification","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_paired_statements_in_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Paired Statements in a Dichotomous Key"}', 2),
  (3402, 904, 'An organism has wings and feathers. In the key above, which step should be used first?', 'mcq', 1, 'Focus on the core principle of Following a Key Step by Step.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Step 1","steps":["Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Step 1"],"options":[{"text":"Step 1","is_correct":true},{"text":"Step 2","is_correct":false},{"text":"Step 3","is_correct":false},{"text":"No step","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_following_a_key_step_by_step","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Following a Key Step by Step"}', 0),
  (3403, 904, 'If the organism has wings, which option is selected at step 1?', 'mcq', 1, 'Focus on the core principle of Following a Key Step by Step.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 1a","steps":["Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 1a"],"options":[{"text":"1a","is_correct":true},{"text":"1b","is_correct":false},{"text":"2a","is_correct":false},{"text":"2b","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_following_a_key_step_by_step","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Following a Key Step by Step"}', 1),
  (3404, 904, 'If the organism reaches step 2 and has feathers, what is its identification?', 'mcq', 1, 'Focus on the core principle of Following a Key Step by Step.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Bird","steps":["Step 1: Identify key concept: Define the required principles for Following a Key Step by Step.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Bird"],"options":[{"text":"Bird","is_correct":true},{"text":"Insect","is_correct":false},{"text":"Mammal","is_correct":false},{"text":"Reptile","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_following_a_key_step_by_step","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Following a Key Step by Step"}', 2),
  (3405, 905, 'What is the first major task when constructing a dichotomous key?', 'mcq', 1, 'Focus on the core principle of Constructing a Simple Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Choose an observable characteristic that separates organisms","steps":["Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Choose an observable characteristic that separates organisms"],"options":[{"text":"Choose an observable characteristic that separates organisms","is_correct":true},{"text":"Write all organism names in alphabetical order","is_correct":false},{"text":"Measure every organism''s weight","is_correct":false},{"text":"Choose a characteristic that cannot be observed","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_constructing_a_simple_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Constructing a Simple Dichotomous Key"}', 0),
  (3406, 905, 'Which characteristic is most useful in a simple identification key?', 'mcq', 1, 'Focus on the core principle of Constructing a Simple Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A clear observable characteristic","steps":["Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A clear observable characteristic"],"options":[{"text":"A clear observable characteristic","is_correct":true},{"text":"A characteristic that is impossible to observe","is_correct":false},{"text":"A characteristic that changes every minute","is_correct":false},{"text":"A characteristic based only on guessing","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_constructing_a_simple_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Constructing a Simple Dichotomous Key"}', 1),
  (3407, 905, 'Why should a characteristic separate organisms into different groups?', 'mcq', 1, 'Focus on the core principle of Constructing a Simple Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To reduce the number of possible identities at each step","steps":["Step 1: Identify key concept: Define the required principles for Constructing a Simple Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To reduce the number of possible identities at each step"],"options":[{"text":"To reduce the number of possible identities at each step","is_correct":true},{"text":"To make the key longer without purpose","is_correct":false},{"text":"To prevent identification","is_correct":false},{"text":"To make every organism look identical","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_constructing_a_simple_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Constructing a Simple Dichotomous Key"}', 2),
  (3408, 906, 'Why should a dichotomous key be tested?', 'mcq', 1, 'Focus on the core principle of Testing a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: To check that it leads to correct identifications","steps":["Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: To check that it leads to correct identifications"],"options":[{"text":"To check that it leads to correct identifications","is_correct":true},{"text":"To make the organisms change characteristics","is_correct":false},{"text":"To increase the organism''s size","is_correct":false},{"text":"To determine the organism''s age","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_testing_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Testing a Dichotomous Key"}', 0),
  (3409, 906, 'What is wrong if both choices at a step describe exactly the same characteristic?', 'mcq', 1, 'Focus on the core principle of Testing a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The step does not separate the organisms","steps":["Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The step does not separate the organisms"],"options":[{"text":"The step does not separate the organisms","is_correct":true},{"text":"The organisms become extinct","is_correct":false},{"text":"The key becomes automatically correct","is_correct":false},{"text":"The organisms change kingdom","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_testing_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Testing a Dichotomous Key"}', 1),
  (3410, 906, 'What should happen after following a correct identification path?', 'mcq', 1, 'Focus on the core principle of Testing a Dichotomous Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It should lead to the correct organism or group","steps":["Step 1: Identify key concept: Define the required principles for Testing a Dichotomous Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It should lead to the correct organism or group"],"options":[{"text":"It should lead to the correct organism or group","is_correct":true},{"text":"It should return to the first step forever","is_correct":false},{"text":"It should produce two different organisms","is_correct":false},{"text":"It should stop without an identification","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_testing_a_dichotomous_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Testing a Dichotomous Key"}', 2),
  (3411, 907, 'An unknown organism has six legs. Which choice is selected at step 1?', 'mcq', 1, 'Focus on the core principle of Identifying an Unknown Organism Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 1a","steps":["Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 1a"],"options":[{"text":"1a","is_correct":true},{"text":"1b","is_correct":false},{"text":"2a","is_correct":false},{"text":"2b","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_identifying_an_unknown_organism_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Identifying an Unknown Organism Using a Key"}', 0),
  (3412, 907, 'If the organism then has wings with scales on the wings, which choice is selected?', 'mcq', 1, 'Focus on the core principle of Identifying an Unknown Organism Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 2a","steps":["Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 2a"],"options":[{"text":"1a","is_correct":false},{"text":"1b","is_correct":false},{"text":"2a","is_correct":true},{"text":"2b","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_identifying_an_unknown_organism_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Identifying an Unknown Organism Using a Key"}', 1),
  (3413, 907, 'What is the identification in the example?', 'mcq', 1, 'Focus on the core principle of Identifying an Unknown Organism Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Butterfly","steps":["Step 1: Identify key concept: Define the required principles for Identifying an Unknown Organism Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Butterfly"],"options":[{"text":"Butterfly","is_correct":true},{"text":"Bird","is_correct":false},{"text":"Fish","is_correct":false},{"text":"Mammal","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_identifying_an_unknown_organism_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Identifying an Unknown Organism Using a Key"}', 2),
  (3414, 908, 'What should you do instead of guessing when using a key?', 'mcq', 1, 'Focus on the core principle of Common Errors When Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Observe the characteristic being tested","steps":["Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Observe the characteristic being tested"],"options":[{"text":"Observe the characteristic being tested","is_correct":true},{"text":"Choose the first option","is_correct":false},{"text":"Choose the longest statement","is_correct":false},{"text":"Choose randomly","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_common_errors_when_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Common Errors When Using a Key"}', 0),
  (3415, 908, 'What can happen if you skip an identification step?', 'mcq', 1, 'Focus on the core principle of Common Errors When Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: You may identify the organism incorrectly","steps":["Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: You may identify the organism incorrectly"],"options":[{"text":"You may identify the organism incorrectly","is_correct":true},{"text":"The organism will change species","is_correct":false},{"text":"The organism will become larger","is_correct":false},{"text":"The key will automatically correct itself","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_common_errors_when_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Common Errors When Using a Key"}', 1),
  (3416, 908, 'If a key says ''go to 4'', what should you do?', 'mcq', 1, 'Focus on the core principle of Common Errors When Using a Key.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Go to step 4","steps":["Step 1: Identify key concept: Define the required principles for Common Errors When Using a Key.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Go to step 4"],"options":[{"text":"Go to step 4","is_correct":true},{"text":"Go to step 3","is_correct":false},{"text":"Return to step 1","is_correct":false},{"text":"Choose both options","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_common_errors_when_using_a_key","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Common Errors When Using a Key"}', 2),
  (3417, 909, 'The unknown organism does not have six legs. Which choice is made at step 1?', 'mcq', 1, 'Focus on the core principle of Complete Identification Problem.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Complete Identification Problem.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 1b","steps":["Step 1: Identify key concept: Define the required principles for Complete Identification Problem.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 1b"],"options":[{"text":"1a","is_correct":false},{"text":"1b","is_correct":true},{"text":"2a","is_correct":false},{"text":"2b","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_complete_identification_problem","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Complete Identification Problem"}', 0),
  (3418, 909, 'At step 3, the organism has no feathers. Which choice is correct?', 'mcq', 1, 'Focus on the core principle of Complete Identification Problem.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Complete Identification Problem.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: 3b","steps":["Step 1: Identify key concept: Define the required principles for Complete Identification Problem.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: 3b"],"options":[{"text":"3a","is_correct":false},{"text":"3b","is_correct":true},{"text":"4a","is_correct":false},{"text":"4b","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_complete_identification_problem","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Complete Identification Problem"}', 1),
  (3419, 909, 'At step 4, the organism has no fur. What is the final identification?', 'mcq', 1, 'Focus on the core principle of Complete Identification Problem.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Complete Identification Problem.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Reptile","steps":["Step 1: Identify key concept: Define the required principles for Complete Identification Problem.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Reptile"],"options":[{"text":"Bird","is_correct":false},{"text":"Mammal","is_correct":false},{"text":"Reptile","is_correct":true},{"text":"Insect","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_complete_identification_problem","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Complete Identification Problem"}', 2),
  (3420, 910, 'How can habitat destruction reduce biodiversity?', 'mcq', 1, 'Focus on the core principle of Threats to Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can remove places where organisms feed, reproduce and shelter","steps":["Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can remove places where organisms feed, reproduce and shelter"],"options":[{"text":"It can remove places where organisms feed, reproduce and shelter","is_correct":true},{"text":"It always increases the number of species","is_correct":false},{"text":"It makes every organism reproduce faster","is_correct":false},{"text":"It prevents all environmental changes","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_threats_to_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Threats to Biodiversity"}', 0),
  (3421, 910, 'What is overexploitation?', 'mcq', 1, 'Focus on the core principle of Threats to Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Using or harvesting organisms faster than populations can replace themselves","steps":["Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Using or harvesting organisms faster than populations can replace themselves"],"options":[{"text":"Using or harvesting organisms faster than populations can replace themselves","is_correct":true},{"text":"Protecting organisms from exploitation","is_correct":false},{"text":"Classifying organisms into kingdoms","is_correct":false},{"text":"Increasing habitat size","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_threats_to_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Threats to Biodiversity"}', 1),
  (3422, 910, 'How can pollution threaten biodiversity?', 'mcq', 1, 'Focus on the core principle of Threats to Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can harm organisms or make habitats unsuitable","steps":["Step 1: Identify key concept: Define the required principles for Threats to Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can harm organisms or make habitats unsuitable"],"options":[{"text":"It can harm organisms or make habitats unsuitable","is_correct":true},{"text":"It always increases species diversity","is_correct":false},{"text":"It makes all organisms resistant to disease","is_correct":false},{"text":"It prevents all competition","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_threats_to_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Threats to Biodiversity"}', 2),
  (3423, 911, 'What does conservation mean?', 'mcq', 1, 'Focus on the core principle of Conservation of Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Protecting and managing organisms, habitats and natural resources to maintain biodiversity","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Protecting and managing organisms, habitats and natural resources to maintain biodiversity"],"options":[{"text":"Protecting and managing organisms, habitats and natural resources to maintain biodiversity","is_correct":true},{"text":"Removing all organisms from a habitat","is_correct":false},{"text":"Increasing pollution","is_correct":false},{"text":"Using natural resources without limits","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_conservation_of_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Biodiversity"}', 0),
  (3424, 911, 'Which is an example of biodiversity conservation?', 'mcq', 1, 'Focus on the core principle of Conservation of Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Protecting a natural forest from destruction","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Protecting a natural forest from destruction"],"options":[{"text":"Protecting a natural forest from destruction","is_correct":true},{"text":"Clearing an entire forest","is_correct":false},{"text":"Overfishing a lake","is_correct":false},{"text":"Dumping waste into a river","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_conservation_of_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Biodiversity"}', 1),
  (3425, 911, 'Why can controlled harvesting help conserve biodiversity?', 'mcq', 1, 'Focus on the core principle of Conservation of Biodiversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It can prevent populations from being removed faster than they recover","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Biodiversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It can prevent populations from being removed faster than they recover"],"options":[{"text":"It can prevent populations from being removed faster than they recover","is_correct":true},{"text":"It removes every organism from the habitat","is_correct":false},{"text":"It stops reproduction","is_correct":false},{"text":"It increases habitat destruction","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_conservation_of_biodiversity","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Biodiversity"}', 2),
  (3426, 912, 'What is in situ conservation?', 'mcq', 1, 'Focus on the core principle of In Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for In Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Conserving organisms within their natural habitats","steps":["Step 1: Identify key concept: Define the required principles for In Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Conserving organisms within their natural habitats"],"options":[{"text":"Conserving organisms within their natural habitats","is_correct":true},{"text":"Conserving organisms only in laboratories","is_correct":false},{"text":"Removing organisms from all habitats","is_correct":false},{"text":"Destroying the natural habitat","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_in_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"In Situ Conservation"}', 0),
  (3427, 912, 'Which is an example of in situ conservation?', 'mcq', 1, 'Focus on the core principle of In Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for In Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Protecting elephants within their natural habitat","steps":["Step 1: Identify key concept: Define the required principles for In Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Protecting elephants within their natural habitat"],"options":[{"text":"Protecting elephants within their natural habitat","is_correct":true},{"text":"Keeping seeds in a laboratory only","is_correct":false},{"text":"Keeping an animal specimen in a museum","is_correct":false},{"text":"Destroying a wildlife habitat","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_in_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"In Situ Conservation"}', 1),
  (3428, 912, 'Why does protecting a natural habitat help conserve species?', 'mcq', 1, 'Focus on the core principle of In Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for In Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: It protects the environmental conditions and interactions needed by the species","steps":["Step 1: Identify key concept: Define the required principles for In Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: It protects the environmental conditions and interactions needed by the species"],"options":[{"text":"It protects the environmental conditions and interactions needed by the species","is_correct":true},{"text":"It removes all competition","is_correct":false},{"text":"It prevents organisms from reproducing","is_correct":false},{"text":"It makes every species genetically identical","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_in_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"In Situ Conservation"}', 2),
  (3429, 913, 'What is ex situ conservation?', 'mcq', 1, 'Focus on the core principle of Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Conserving organisms or genetic material outside their natural habitats","steps":["Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Conserving organisms or genetic material outside their natural habitats"],"options":[{"text":"Conserving organisms or genetic material outside their natural habitats","is_correct":true},{"text":"Protecting organisms only in natural forests","is_correct":false},{"text":"Destroying habitats","is_correct":false},{"text":"Allowing unlimited exploitation","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Ex Situ Conservation"}', 0),
  (3430, 913, 'Which is an example of ex situ conservation?', 'mcq', 1, 'Focus on the core principle of Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: A seed bank","steps":["Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: A seed bank"],"options":[{"text":"A seed bank","is_correct":true},{"text":"A natural forest","is_correct":false},{"text":"A natural lake","is_correct":false},{"text":"A wild grassland","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Ex Situ Conservation"}', 1),
  (3431, 913, 'What is the main difference between in situ and ex situ conservation?', 'mcq', 1, 'Focus on the core principle of Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Whether conservation occurs inside or outside the organism''s natural habitat","steps":["Step 1: Identify key concept: Define the required principles for Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Whether conservation occurs inside or outside the organism''s natural habitat"],"options":[{"text":"Whether conservation occurs inside or outside the organism''s natural habitat","is_correct":true},{"text":"Whether the organism has DNA","is_correct":false},{"text":"Whether the organism can reproduce","is_correct":false},{"text":"Whether the organism is classified","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Ex Situ Conservation"}', 2),
  (3432, 914, 'A threatened animal is protected in its natural habitat. What type of conservation is this?', 'mcq', 1, 'Focus on the core principle of Comparing In Situ and Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: In situ conservation","steps":["Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: In situ conservation"],"options":[{"text":"In situ conservation","is_correct":true},{"text":"Ex situ conservation","is_correct":false},{"text":"Artificial selection","is_correct":false},{"text":"Classification","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_comparing_in_situ_and_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing In Situ and Ex Situ Conservation"}', 0),
  (3433, 914, 'Seeds of a rare plant are stored in a seed bank. What type of conservation is this?', 'mcq', 1, 'Focus on the core principle of Comparing In Situ and Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Ex situ conservation","steps":["Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Ex situ conservation"],"options":[{"text":"In situ conservation","is_correct":false},{"text":"Ex situ conservation","is_correct":true},{"text":"Natural selection","is_correct":false},{"text":"Habitat destruction","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_comparing_in_situ_and_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing In Situ and Ex Situ Conservation"}', 1),
  (3434, 914, 'What single question best distinguishes in situ from ex situ conservation?', 'mcq', 1, 'Focus on the core principle of Comparing In Situ and Ex Situ Conservation.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Is the organism being conserved in its natural habitat?","steps":["Step 1: Identify key concept: Define the required principles for Comparing In Situ and Ex Situ Conservation.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Is the organism being conserved in its natural habitat?"],"options":[{"text":"Is the organism being conserved in its natural habitat?","is_correct":true},{"text":"Does the organism have DNA?","is_correct":false},{"text":"Does the organism have cells?","is_correct":false},{"text":"Does the organism need energy?","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_comparing_in_situ_and_ex_situ_conservation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Comparing In Situ and Ex Situ Conservation"}', 2),
  (3435, 915, 'What is overexploitation?', 'mcq', 1, 'Focus on the core principle of Overexploitation.', '{"why":"Overexploitation removes resources faster than natural replacement.","sol":"Step 1: Identify key concept: Define the required principles for Overexploitation.\nStep 2: Apply governing rule: Overexploitation removes resources faster than natural replacement.\nStep 3: State the final conclusion: Using organisms or resources faster than they can recover","steps":["Step 1: Identify key concept: Define the required principles for Overexploitation.","Step 2: Apply governing rule: Overexploitation removes resources faster than natural replacement.","Step 3: State the final conclusion: Using organisms or resources faster than they can recover"],"options":[{"text":"Using organisms or resources faster than they can recover","is_correct":true},{"text":"Using resources at a sustainable rate","is_correct":false},{"text":"Increasing biodiversity","is_correct":false},{"text":"Protecting a habitat","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_overexploitation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Overexploitation"}', 0),
  (3436, 915, 'A fish population replaces 500 fish each year, but 800 are caught. What is likely to happen if this continues?', 'text', 1, 'Focus on the core principle of Overexploitation.', '{"why":"Removal exceeds replacement by 300 fish per year.","sol":"Step 1: Identify key concept: Define the required principles for Overexploitation.\nStep 2: Apply governing rule: Removal exceeds replacement by 300 fish per year.\nStep 3: State the final conclusion: The population is likely to decline.","steps":["Step 1: Identify key concept: Define the required principles for Overexploitation.","Step 2: Apply governing rule: Removal exceeds replacement by 300 fish per year.","Step 3: State the final conclusion: The population is likely to decline."],"options":[],"conceptId":"biology_biodiversity_and_classification_overexploitation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Overexploitation"}', 1),
  (3437, 915, 'Which activity is an example of overexploitation?', 'mcq', 1, 'Focus on the core principle of Overexploitation.', '{"why":"The removal rate is greater than the replacement rate.","sol":"Step 1: Identify key concept: Define the required principles for Overexploitation.\nStep 2: Apply governing rule: The removal rate is greater than the replacement rate.\nStep 3: State the final conclusion: Catching fish faster than the population can replace them","steps":["Step 1: Identify key concept: Define the required principles for Overexploitation.","Step 2: Apply governing rule: The removal rate is greater than the replacement rate.","Step 3: State the final conclusion: Catching fish faster than the population can replace them"],"options":[{"text":"Catching fish faster than the population can replace them","is_correct":true},{"text":"Planting trees after harvesting","is_correct":false},{"text":"Protecting endangered species","is_correct":false},{"text":"Creating a wildlife reserve","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_overexploitation","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Overexploitation"}', 2),
  (3438, 916, 'What does sustainable resource use mean?', 'mcq', 1, 'Focus on the core principle of Sustainable Resource Use.', '{"why":"Sustainable use allows resources and ecosystems to continue supporting future needs.","sol":"Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.\nStep 2: Apply governing rule: Sustainable use allows resources and ecosystems to continue supporting future needs.\nStep 3: State the final conclusion: Using a resource at a rate that allows it to remain available for the future","steps":["Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.","Step 2: Apply governing rule: Sustainable use allows resources and ecosystems to continue supporting future needs.","Step 3: State the final conclusion: Using a resource at a rate that allows it to remain available for the future"],"options":[{"text":"Using a resource at a rate that allows it to remain available for the future","is_correct":true},{"text":"Using as much as possible immediately","is_correct":false},{"text":"Never using any natural resource","is_correct":false},{"text":"Removing a resource faster than it can recover","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_sustainable_resource_use","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Sustainable Resource Use"}', 0),
  (3439, 916, 'Why can replanting trees help make timber harvesting more sustainable?', 'text', 1, 'Focus on the core principle of Sustainable Resource Use.', '{"why":"Replacement allows the resource to recover over time.","sol":"Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.\nStep 2: Apply governing rule: Replacement allows the resource to recover over time.\nStep 3: State the final conclusion: It replaces trees that have been removed and helps maintain the forest resource.","steps":["Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.","Step 2: Apply governing rule: Replacement allows the resource to recover over time.","Step 3: State the final conclusion: It replaces trees that have been removed and helps maintain the forest resource."],"options":[],"conceptId":"biology_biodiversity_and_classification_sustainable_resource_use","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Sustainable Resource Use"}', 1),
  (3440, 916, 'Which practice is most likely to support sustainable fishing?', 'mcq', 1, 'Focus on the core principle of Sustainable Resource Use.', '{"why":"Controlled harvesting allows reproduction to replace removed individuals.","sol":"Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.\nStep 2: Apply governing rule: Controlled harvesting allows reproduction to replace removed individuals.\nStep 3: State the final conclusion: Keeping catches below levels that allow the population to recover","steps":["Step 1: Identify key concept: Define the required principles for Sustainable Resource Use.","Step 2: Apply governing rule: Controlled harvesting allows reproduction to replace removed individuals.","Step 3: State the final conclusion: Keeping catches below levels that allow the population to recover"],"options":[{"text":"Keeping catches below levels that allow the population to recover","is_correct":true},{"text":"Catching every available fish","is_correct":false},{"text":"Removing breeding adults continuously","is_correct":false},{"text":"Ignoring population size","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_sustainable_resource_use","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Sustainable Resource Use"}', 2),
  (3441, 917, 'What is conservation?', 'mcq', 1, 'Focus on the core principle of Conservation of Natural Resources.', '{"why":"Conservation aims to maintain biodiversity and natural resources.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.\nStep 2: Apply governing rule: Conservation aims to maintain biodiversity and natural resources.\nStep 3: State the final conclusion: Protection and management of organisms, habitats and resources","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.","Step 2: Apply governing rule: Conservation aims to maintain biodiversity and natural resources.","Step 3: State the final conclusion: Protection and management of organisms, habitats and resources"],"options":[{"text":"Protection and management of organisms, habitats and resources","is_correct":true},{"text":"Destruction of habitats","is_correct":false},{"text":"Removal of all predators","is_correct":false},{"text":"Using resources as quickly as possible","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_conservation_of_natural_resources","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Natural Resources"}', 0),
  (3442, 917, 'Give two conservation methods.', 'text', 1, 'Focus on the core principle of Conservation of Natural Resources.', '{"why":"Conservation can protect organisms, habitats and resources in several ways.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.\nStep 2: Apply governing rule: Conservation can protect organisms, habitats and resources in several ways.\nStep 3: State the final conclusion: Examples: habitat protection, controlled harvesting, habitat restoration, tree planting or pollution reduction.","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.","Step 2: Apply governing rule: Conservation can protect organisms, habitats and resources in several ways.","Step 3: State the final conclusion: Examples: habitat protection, controlled harvesting, habitat restoration, tree planting or pollution reduction."],"options":[],"conceptId":"biology_biodiversity_and_classification_conservation_of_natural_resources","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Natural Resources"}', 1),
  (3443, 917, 'Why is habitat conservation important?', 'mcq', 1, 'Focus on the core principle of Conservation of Natural Resources.', '{"why":"Protecting habitats helps maintain the conditions populations require.","sol":"Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.\nStep 2: Apply governing rule: Protecting habitats helps maintain the conditions populations require.\nStep 3: State the final conclusion: Species depend on habitats for resources and suitable conditions","steps":["Step 1: Identify key concept: Define the required principles for Conservation of Natural Resources.","Step 2: Apply governing rule: Protecting habitats helps maintain the conditions populations require.","Step 3: State the final conclusion: Species depend on habitats for resources and suitable conditions"],"options":[{"text":"Species depend on habitats for resources and suitable conditions","is_correct":true},{"text":"Animals do not need habitats","is_correct":false},{"text":"It eliminates all competition","is_correct":false},{"text":"It stops photosynthesis","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_conservation_of_natural_resources","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Conservation of Natural Resources"}', 2),
  (3444, 918, 'What is the main purpose of a protected area?', 'mcq', 1, 'Focus on the core principle of Protected Areas.', '{"why":"Protected areas are managed to support conservation.","sol":"Step 1: Identify key concept: Define the required principles for Protected Areas.\nStep 2: Apply governing rule: Protected areas are managed to support conservation.\nStep 3: State the final conclusion: To conserve biodiversity, habitats or natural resources","steps":["Step 1: Identify key concept: Define the required principles for Protected Areas.","Step 2: Apply governing rule: Protected areas are managed to support conservation.","Step 3: State the final conclusion: To conserve biodiversity, habitats or natural resources"],"options":[{"text":"To conserve biodiversity, habitats or natural resources","is_correct":true},{"text":"To increase uncontrolled hunting","is_correct":false},{"text":"To remove all organisms","is_correct":false},{"text":"To prevent all ecological processes","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_protected_areas","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q1","subject":"biology","chapter":"biodiversity_and_classification","topic":"Protected Areas"}', 0),
  (3445, 918, 'How can a protected area help an endangered species?', 'text', 1, 'Focus on the core principle of Protected Areas.', '{"why":"Reducing threats improves the species'' chances of survival and reproduction.","sol":"Step 1: Identify key concept: Define the required principles for Protected Areas.\nStep 2: Apply governing rule: Reducing threats improves the species'' chances of survival and reproduction.\nStep 3: State the final conclusion: It can protect its habitat and reduce harmful activities such as uncontrolled hunting.","steps":["Step 1: Identify key concept: Define the required principles for Protected Areas.","Step 2: Apply governing rule: Reducing threats improves the species'' chances of survival and reproduction.","Step 3: State the final conclusion: It can protect its habitat and reduce harmful activities such as uncontrolled hunting."],"options":[],"conceptId":"biology_biodiversity_and_classification_protected_areas","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q2","subject":"biology","chapter":"biodiversity_and_classification","topic":"Protected Areas"}', 1),
  (3446, 918, 'Why can protecting one habitat conserve many species?', 'mcq', 1, 'Focus on the core principle of Protected Areas.', '{"why":"A habitat can support many interacting populations.","sol":"Step 1: Identify key concept: Define the required principles for Protected Areas.\nStep 2: Apply governing rule: A habitat can support many interacting populations.\nStep 3: State the final conclusion: Many species depend on the same habitat","steps":["Step 1: Identify key concept: Define the required principles for Protected Areas.","Step 2: Apply governing rule: A habitat can support many interacting populations.","Step 3: State the final conclusion: Many species depend on the same habitat"],"options":[{"text":"Many species depend on the same habitat","is_correct":true},{"text":"All species have identical requirements","is_correct":false},{"text":"Only one species lives in a habitat","is_correct":false},{"text":"Habitats contain no resources","is_correct":false}],"conceptId":"biology_biodiversity_and_classification_protected_areas","skillId":"biology_biodiversity_and_classification","subskillId":"biology_biodiversity_and_classification_q3","subject":"biology","chapter":"biodiversity_and_classification","topic":"Protected Areas"}', 2),
  (3447, 919, 'Why do antibiotics not cure viral infections?', 'mcq', 1, 'Focus on the core principle of Why Antibiotics Do Not Cure Viral Infections.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Antibiotics target bacterial structures or processes that viruses do not have in the same form.","steps":["Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Antibiotics target bacterial structures or processes that viruses do not have in the same form."],"options":[{"text":"Antibiotics target bacterial structures or processes that viruses do not have in the same form.","is_correct":true},{"text":"Viruses are always larger than bacteria.","is_correct":false},{"text":"Viruses contain no genetic material.","is_correct":false},{"text":"Antibiotics only work in plants.","is_correct":false}],"conceptId":"biology_ecology_why_antibiotics_do_not_cure_viral_infections","skillId":"biology_ecology","subskillId":"biology_ecology_q1","subject":"biology","chapter":"ecology","topic":"Why Antibiotics Do Not Cure Viral Infections"}', 0),
  (3448, 919, 'What can unnecessary antibiotic use contribute to?', 'mcq', 1, 'Focus on the core principle of Why Antibiotics Do Not Cure Viral Infections.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Selection for antibiotic-resistant bacteria.","steps":["Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Selection for antibiotic-resistant bacteria."],"options":[{"text":"Selection for antibiotic-resistant bacteria.","is_correct":true},{"text":"The disappearance of all viruses.","is_correct":false},{"text":"The creation of human antibodies against every disease.","is_correct":false},{"text":"The elimination of all bacterial variation.","is_correct":false}],"conceptId":"biology_ecology_why_antibiotics_do_not_cure_viral_infections","skillId":"biology_ecology","subskillId":"biology_ecology_q2","subject":"biology","chapter":"ecology","topic":"Why Antibiotics Do Not Cure Viral Infections"}', 1),
  (3449, 919, 'Who becomes resistant in antibiotic resistance?', 'mcq', 1, 'Focus on the core principle of Why Antibiotics Do Not Cure Viral Infections.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Bacteria can become resistant to antibiotics.","steps":["Step 1: Identify key concept: Define the required principles for Why Antibiotics Do Not Cure Viral Infections.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Bacteria can become resistant to antibiotics."],"options":[{"text":"Bacteria can become resistant to antibiotics.","is_correct":true},{"text":"The human body becomes resistant to all medicines.","is_correct":false},{"text":"Viruses become bacteria.","is_correct":false},{"text":"Antibiotics become living organisms.","is_correct":false}],"conceptId":"biology_ecology_why_antibiotics_do_not_cure_viral_infections","skillId":"biology_ecology","subskillId":"biology_ecology_q3","subject":"biology","chapter":"ecology","topic":"Why Antibiotics Do Not Cure Viral Infections"}', 2),
  (3450, 920, 'What is ecosystem diversity?', 'mcq', 1, 'Focus on the core principle of Ecosystem Diversity.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ecosystem Diversity.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The variety of different ecosystems in an area","steps":["Step 1: Identify key concept: Define the required principles for Ecosystem Diversity.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The variety of different ecosystems in an area"],"options":[{"text":"The variety of different ecosystems in an area","is_correct":true},{"text":"The number of organisms in one ecosystem","is_correct":false},{"text":"The number of genes in one cell","is_correct":false},{"text":"The size of one organism","is_correct":false}],"conceptId":"biology_ecology_ecosystem_diversity","skillId":"biology_ecology","subskillId":"biology_ecology_q1","subject":"biology","chapter":"ecology","topic":"Ecosystem Diversity"}', 0),
