INSERT INTO public.answers (id, question_id, answer_text, is_correct) VALUES
  (9501, 5593, 'Use continue to skip 5', TRUE),
  (9502, 5594, 'Use a while loop with counter', TRUE),
  (9503, 5595, 'Use a while loop to repeat until correct input', TRUE),
  (9504, 5596, 'A reusable block of code that performs a specific task.', TRUE),
  (9505, 5597, 'A function that belongs to an object.', TRUE),
  (9506, 5598, 'A parameter is a variable in a function definition, while an argument is the actual value passed to it.', TRUE),
  (9507, 5599, 'A variable defined inside a function and used only within it.', TRUE),
  (9508, 5600, 'A variable defined outside functions and accessible throughout the program.', TRUE),
  (9509, 5601, 'def greet():
    print(''Hello World'')

